INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab6fe10b93ed4508aa445398f4c938b9','9e9c6705-f345-43c7-9ae1-a5294d935d5d',1938,'投靠日军','投靠日军，出任伪上海市长，协助日伪统治上海，镇压抗日活动','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9fd914d77fa94c11a00345a99845d8d2','9e9c6705-f345-43c7-9ae1-a5294d935d5d',1938,'曾任伪上海市长','曾任伪上海市长，在徐汇区有官邸活动，协助日军推行殖民统治，普陀地区归其管辖，配合日军经济掠夺和治安维持。为日军统治上海服务，其活动范围涉及杨浦区（原公共租界东区及华界）','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d307e91b5564c49ad7ef2b6160d08f3','9e9c6705-f345-43c7-9ae1-a5294d935d5d',1938,'协助日伪统治上海','协助日伪统治上海，镇压抗日活动，原中国通商银行董事长，为日军征粮征税，管辖包括闵行在内的上海地区，推行日伪统治政策，征收苛捐杂税，压制民众反抗。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63a2af0b66c74a07bd6ad0542b2edfc3','9e9c6705-f345-43c7-9ae1-a5294d935d5d',1938,'投靠日军','投靠日军，管辖包括青浦在内的上海地区，为日军提供物资和情报，积极推行日伪政权政策，镇压抗日活动，后因投敌被军统刺杀于静安住宅。协助日军维持占领区秩序，镇压抗日活动，征收苛捐杂税，为日军提供物资支持。属汪伪体系，其伪政权与华南伪政权有联系。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c582d67b7410484f84c927c6464a967d','9e9c6705-f345-43c7-9ae1-a5294d935d5d',1938,'原上海总商会会长','原上海总商会会长，1938年投敌出任伪上海特别市市长','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c96912ea5a4f40239185cd46451d41a7','9e9c6705-f345-43c7-9ae1-a5294d935d5d',1938,'浙江镇海人','浙江镇海人，长期在上海活动，镇压抗日力量，1940年被军统策反的仆人刺杀。虽非九江籍，但属江西周边省份及长江下游伪政权体系中的知名汉奸。早年在江西九江、庐山一带经营实业并参与地方事务，配合日军在华中包括江西九江地区的经济掠夺与物资统制，其伪政权体系与九江伪维持会有联系。协助日军控制上海及周边地区，包括浙江部分地区。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9b35d7e43c5419cb598d655200176bb','9e9c6705-f345-43c7-9ae1-a5294d935d5d',1938,'浙江镇海人','浙江镇海人，早年在上海经商，抗战期间投靠日军，1940年被军统策反的仆人刺杀。1940年被军统策反的仆人刺杀。配合日军统治，其伪政权与华中各地伪组织有联系，间接影响湖南。属汪伪体系。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7000dfb7db524ef181aac66310614ae6','9e9c6705-f345-43c7-9ae1-a5294d935d5d',1938,'其伪政权与贵州部分商会勾结','其伪政权与贵州部分商会勾结，通过贵阳口岸进行物资资敌活动。其附逆行为对全国包括陕西有示范影响，配合日军在华东及华北包括陕西周边地区进行统治，配合日军在华东及华北包括陕西周边地区进行殖民统治。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0588c7e952d94dce928480be27e8874c','4f9d88c0-8c28-47fc-98e4-5746ec114be2',1940,'汪精卫政权核心人物','汪精卫政权核心人物，曾任伪上海市长，推行清乡和奴化政策，协助日军控制上海。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f28e1048ad24f948c37ac6c3fa18b4b','4f9d88c0-8c28-47fc-98e4-5746ec114be2',1940,'汪精卫政权核心人物','汪精卫政权核心人物，曾任伪上海市长，推行“清乡”政策，协助日军搜刮物资，迫害抗日人士。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e54f54b152f7456d8ba7580db8c8413d','72ede599-5060-4228-8e0e-d2ae506c070b',1940,'汪伪政权要员','汪伪政权要员，兼任伪上海市长，主持上海日伪政务，参与经济掠夺和特务活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29d7fdb144ab49958ac8a91c656df6a6','72ede599-5060-4228-8e0e-d2ae506c070b',1940,'汪伪政权核心人物','汪伪政权核心人物，后期主持上海政务，控制包括杨浦在内的沪东地区，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44a9cf1ff58b4424b008b4cca47cc454','72ede599-5060-4228-8e0e-d2ae506c070b',1940,'汪伪政权要员','汪伪政权要员，兼任伪上海市长，控制上海金融与特务机构，参与对抗日力量的镇压。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a21b961cc62e44f7bec25f45095531d1','72ede599-5060-4228-8e0e-d2ae506c070b',1940,'虽非余姚人','虽非余姚人，但曾在余姚活动，作为汪伪政权核心人物，协助日军统治浙江地区，推行清乡政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd051efd7b33405eb7d1d27ca017d59b','4bb13460-f57a-4824-b6d3-847ec47df131',1939,'原军统特务','原军统特务，投日后任汪伪特工总部主任，在上海制造多起暗杀和恐怖事件，后任伪浙江省长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1eed3702e6524bcaab768bf476bab55a','f2c3e546-2823-4e26-ac33-c32281cda8b0',1939,'投靠日本','投靠日本，组建上海极司菲尔路76号特工机构，残害抗日志士，制造血案，后因内讧被毒杀。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-859e9ada7cc94914b2a96cbd95cf71c7','f2c3e546-2823-4e26-ac33-c32281cda8b0',1939,'汪伪特务头子','汪伪特务头子，其特工在杨浦地区（如平凉路、杨树浦路）设立秘密据点，暗杀、绑架抗日志士。','危害等级A（甲级，特工总部主任）','hanjian');
