INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34494dc6f0664dc393ba7b704137cf93','f2c3e546-2823-4e26-ac33-c32281cda8b0',1939,'在黄浦区极司菲尔路76号设立特工总部','在黄浦区极司菲尔路76号设立特工总部，指挥暗杀、绑架抗日志士，制造多起血案，是日军在沪恐怖统治的重要工具。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e703e3ca84a40a090a878af25e7d08e','f2c3e546-2823-4e26-ac33-c32281cda8b0',1939,'虽为江苏人','虽为江苏人，但曾在宁波、宁海地区活动，指挥76号特工在浙东地区破坏地下抗日组织，逮捕杀害多名爱国人士。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb32c3bf396d440ea40f9b2982ab3436','c4239272-3c3d-4325-8b44-660097493d93',1939,'李士群手下打手','李士群手下打手，在上海横行霸道，参与绑架、暗杀和敲诈，恶名昭彰。','危害等级C（丙级，基层头目）','hanjian');
