INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a45c55fcfbf747d69f7ed1c9f0047daf','e0ef5bc7-7f67-46a1-878f-d53a1f29042c',1938,'担任伪嘉定警察局长','担任伪嘉定警察局长，搜捕抗日分子，协助日军进行治安肃正，欺压百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-056f0f64ff4a4a9dab0e4060b377f779','5179e3a2-e15a-4094-ae5f-90d76500bda6',1937,'日军占领嘉定初期','日军占领嘉定初期，组织维持会，为日军提供粮食和情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
