INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06db25e8949f4cee9f46d33a4d01147b','80c8e6a3-b4e9-4eaa-a96c-3adaa69da3d4',1940,'在奉贤设立特务据点','在奉贤设立特务据点，诱捕抗日志士，策反国民党游击队，制造多起暗杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ead32fa05278463597f757f272bd4dfd','d5c431d8-eaa6-42cd-a203-9d1bcbcadfeb',1942,'率行动队配合日军“清乡”','率行动队配合日军“清乡”，焚烧村庄，屠杀无辜百姓，抢夺财物。','危害等级C（丙级，基层头目）','hanjian');
