INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-073130a6f7684904aa71e766c2894fcc','1cd569a7-93c5-4549-a94d-e99b08c016f2',1941,'推行奴化教育','推行奴化教育，强制学校使用伪满教材，宣扬“中日亲善”，迫害爱国教师。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
