INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c34a98804e941c591b014cf56e571b4','56c699a6-0b71-40fd-af14-2f42c5744a10',1938,'投靠日军','投靠日军，组织维持会，为日军筹款、提供物资，镇压抗日活动，强征民夫修筑工事。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91dbeb2543834a30ae85a4b818285a16','1ae2ef29-c099-489c-b902-433695d242f7',1939,'率领伪保安队配合日军扫荡','率领伪保安队配合日军扫荡，抓捕抗日志士，抢劫百姓财物，民愤极大。','危害等级C（丙级，基层头目）','hanjian');
