INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a24bae826dfe40d287dacaa82c8a4975','da16d667-ea29-4993-8559-b21db09c9775',1938,'配合日军防疫部队','配合日军防疫部队，在黄浦区强制推行“防疫”措施，实则进行细菌实验，导致平民死亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91338632bebe47bab6c365c9f4ae63a2','525b8b17-6c72-457d-b605-dc68dee69318',1938,'管理水电交通','管理水电交通，优先保障日军和日侨需求，限制中国居民用电用水，配合经济封锁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f190e6cadc124d03a9be716909f07dbe','a0e33c62-74e9-47e1-810f-dfca26eec7ae',1940,'指挥伪保安队参与“清乡”','指挥伪保安队参与“清乡”，在黄浦区及周边扫荡抗日游击队，屠杀无辜百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c22e27096234a0e8f5fad593345c6f1','1ca2bcb9-587b-4323-bde4-234cb783e7e9',1941,'组织伪国民党','组织伪国民党，拉拢社会败类入党，为汪伪政权制造民意假象，监视市民言行。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1bb361245d34c279420cb34e051a2df','89e0e418-b900-4848-ae42-5e37fcde2d52',1939,'作为日本顾问团成员','作为日本顾问团成员，参与制定殖民政策，协调日军与伪政府关系，推动“以华制华”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9aaa85d2a564897857a8e9dae0255b5','0276a42e-b7c9-41a9-b055-cb8cfe0233dd',1931,'作为云南省主席','作为云南省主席，龙云始终未附逆，但日方曾多次试图拉拢','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44fa8ab2cf854beda2dfc34226c579c2','0276a42e-b7c9-41a9-b055-cb8cfe0233dd',1931,'此条仅作排除性说明','此条仅作排除性说明，非汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a564fa8c160f407e9dd83de522b79f23','c5580f87-69d7-455f-9fe4-bf9220445859',1931,'云南籍元老','云南籍元老，坚持抗日，未附逆','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
