INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8142762583544936a9c9e90b3de1884d','f32cc736-e653-48d2-9762-e604e8cb90fd',1931,'云南籍人士','云南籍人士，未见可靠汉奸记录','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a84d185ed5d247908e490a755505d9ad','f32cc736-e653-48d2-9762-e604e8cb90fd',1931,'此条仅作排除性说明','此条仅作排除性说明，非汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b54d042e76d417d9bf0449277111e20','1995a0e7-b20a-4be6-a044-736bbc32aec0',1942,'1942年日军侵占滇西怒江以西地区后','1942年日军侵占滇西怒江以西地区后，保山、腾冲、龙陵等地曾出现维持会、伪政权组织，但具体姓名多散佚，可靠名录极少。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56853dee40cb4238aee7181ba6499142','63d78f97-6ee3-4adb-b36b-5caeaf4dbfba',1942,'日军占领腾冲期间','日军占领腾冲期间，当地曾建立维持会及伪政权，但除少数回忆资料外，可靠姓名与职务记载有限。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a49b66f38d484a538a3c51c659a65247','daa90dcc-ff0f-4b74-998e-5ea83fb928e2',1942,'日军占领龙陵期间','日军占领龙陵期间，当地曾出现维持会及伪组织，具体人员姓名多不可考。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5a879413c1e45f7a4850c4ab3f44d45','964f1117-4f22-4f04-936f-886c50bef09a',1942,'滇西沦陷区曾出现伪军、伪警察及便衣队等组织','滇西沦陷区曾出现伪军、伪警察及便衣队等组织，但除零星记载外，可靠姓名与职务资料很少。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-099ec4e0738f448ba58144e1c931af15','b2f127f7-b3f1-4d57-864c-5e5b5da5b9d2',1942,'龙云之子','龙云之子，抗战时期在滇西一带拥有地方武装。日军侵占腾冲、龙陵后，其部在滇西局势混乱中一度与日伪方面有接触和妥协传闻，后离开滇西。相关记载多与滇西失守后地方势力动摇、附敌嫌疑有关。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ddd4b4516e2c4ac88a1dc1b16167b9c3','f8a163ce-560a-49bd-9a04-c5a557f7cad6',1942,'滇西边地土司势力代表之一。日军侵入滇西后','滇西边地土司势力代表之一。日军侵入滇西后，部分边地土司在威逼利诱下与日军合作，参与维持会或伪政权活动。刀京版常被列入滇西边地附日势力相关记载中。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-857915add33d47faabc142fbc665d668','be66bb3f-f252-497c-8915-cd161b34784d',1942,'滇西沦陷期间','滇西沦陷期间，部分土司在日军控制下出任伪职或协助征粮、维持地方秩序。线光天在相关史料中曾被提及与日军占领当局合作。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd4984c8daea48609f4ea5e0d5445379','55cfc60c-643e-48a8-a525-94ee1e3b4f7f',1942,'日军侵占滇西后','日军侵占滇西后，腾冲、龙陵及周边边地出现维持会组织。龚绶作为地方土司势力人物，被部分史料列为与日伪合作、参与维持地方治安者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82aa8a63c3c045eb98b740e2205d0d9c','80620394-e5a0-49d8-8769-7a70ba68ee9f',1942,'1942年日军占领腾冲后','1942年日军占领腾冲后，当地成立维持会以协助日军统治。杨绍诚被记载为参与维持会事务、为日军筹粮派款的地方附逆者之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-900f55ac1dc74458bbf7ce4266e4a5c7','47d27d77-a6f9-4bf4-84a2-81a2a3633699',1942,'李根源为腾冲著名士绅','李根源为腾冲著名士绅，抗战时期主要在外从事抗日活动。部分地方史料中曾出现其亲属或地方关系人与日伪接触的记载，但李根源本人并非公认汉奸，此处仅列相关争议线索。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2294f4aff7704d34b70d775d52a9528a','7ff3b708-5c8a-4691-8a5c-b67657c733e6',1942,'张问德在腾冲沦陷后坚持抗日','张问德在腾冲沦陷后坚持抗日，拒绝与日军合作，并发表《答田岛书》。其事迹常被用于对照当地附逆者，故不作为汉奸列入，仅说明腾冲伪政权相关背景。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a3bd0084df145729b9fd73a3ee141b5','9dfc9ec7-9866-4c4a-8f1d-a3925bdaf87c',1942,'腾冲沦陷期间','腾冲沦陷期间，日军扶植伪警察和维持会维持城区秩序。董友芹在部分地方文史资料中被提及为协助日军搜捕抗日人员、催征物资的附逆人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3c1442bb384406eb5ac7b04e9347b54','59d5fc04-ae3c-4176-8739-75a69666c18a',1942,'滇西沦陷区伪政权档案中','滇西沦陷区伪政权档案中，部分基层人员姓名散见于维持会、伪乡保组织记载。尹明德被部分资料提及与腾冲伪组织有关，但可靠细节有限。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c29195073b343b59a4fa4a1ae0f73eb','46a120a8-6b6a-43bf-b9b3-f67fcc8e3fad',1942,'龙陵与腾冲同属滇西沦陷区。杨吉品在相关史料中被列为龙陵伪维持会人员','龙陵与腾冲同属滇西沦陷区。杨吉品在相关史料中被列为龙陵伪维持会人员，协助日军征粮、派夫和维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23b1461a75e34cb9934e0a87e51e042d','1dbaeef3-003d-4394-b662-156662ce221a',1942,'滇西沦陷后','滇西沦陷后，日军收编地方武装组成伪军。赵伯钧被部分资料记载为参与伪军活动，配合日军对腾冲、龙陵周边进行扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3dd181ac0bbe4e1daa260edf3e9d24be','41168ab4-ba0a-4775-b3f3-59a715d1a840',1942,'保山及滇西沦陷区边缘地带','保山及滇西沦陷区边缘地带，部分保甲长在日军压力下协助征粮、派款、传递情报。李国清被地方史料提及为保山一带附逆基层人员。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7da3a01ede5644b5a8e1ba5db234c6d9','819e9071-6790-4a33-adcb-14a7debbfd3d',1942,'在腾冲、龙陵沦陷区','在腾冲、龙陵沦陷区，维持会负责为日军筹措物资。王开基被部分文史资料列为参与维持会、协助日军统治的地方人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ffa87f5bdbc4fba94379ebb6fd73e95','2691a533-7357-430e-b163-7f40ec95bba0',1942,'日军在滇西占领区推行奴化教育','日军在滇西占领区推行奴化教育，部分教育界人士参与伪学校或伪教育组织。刘明德被相关记载提及在滇西附逆教育机构任职。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da8508ed53584962b95a087b8f63afa7','f8c5f7b7-063d-4a12-98bd-f73cf7aa0120',1942,'段承钧为滇西边地地方势力人物','段承钧为滇西边地地方势力人物，日军侵入后被指与占领当局合作，参与维持地方秩序和征调物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed373facf5c64776bb89a002a60d6902','8cdf0375-1b95-4895-b232-a51b8a80ef3e',1942,'龙云之子','龙云之子，抗战期间在滇西与日军有接触，其活动范围涉及保山、腾冲一带，但具体附逆行为史料记载有限。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3fd14f1f8b9410197e261bd4e09c267','044e7108-0c28-4326-b738-90bdf1f0bb75',1942,'日军占领腾冲后','日军占领腾冲后，出面组织维持会，协助日军维持地方秩序、征派粮秣，活动范围属保山地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45288d89f8ed4d89bf10ccaef48a40da','61b717c2-2460-4fd4-bcb2-0703a0ba2595',1942,'在日军占领腾冲期间任伪警察局长','在日军占领腾冲期间任伪警察局长，协助日军搜捕抗日人员、维持治安，属保山地区伪政权人物。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0804b607799c42efada34c49d3868357','1bd9ab5e-c741-4b6b-b99b-26aa982378e7',1942,'日军占领龙陵后组织维持会','日军占领龙陵后组织维持会，为日军征派民夫、粮食，活动于保山地区龙陵一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7056ba483714f31b8d3be4b670b30d9','1bd9ab5e-c741-4b6b-b99b-26aa982378e7',1942,'日军侵占龙陵后','日军侵占龙陵后，出面组织维持会，为日军征派粮秣、拉夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c70730e9aa894ea0a0aae7e75c70a82b','7d1c5b45-88f2-4d3c-9179-869938884ef9',1942,'协助日军在龙陵建立伪政权','协助日军在龙陵建立伪政权，参与征派粮秣、民夫，属保山地区附逆人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c9508dd778743d98396ba1af451fc1b','770b4cc9-04da-47e1-835b-db060e2cb51f',1942,'在滇西沦陷区组织维持会','在滇西沦陷区组织维持会，协助日军控制滇缅公路沿线，活动范围涉及保山、德宏一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3cc71c5e0744f8f8fd003425fe44daa','bf19789e-018b-40d4-b030-8e09f246797c',1942,'日军占领滇西后','日军占领滇西后，被迫与日军合作，后率部反正参加抗日，其活动范围涉及保山地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6b918b04dfb4c969f96cb8dfe83305a','9dc89835-0527-4b64-9bb9-cf27fa496cbc',1942,'在滇西沦陷区与日军合作','在滇西沦陷区与日军合作，参与维持会活动，活动范围接近保山地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4126ced39ac4a0295186a3f0639e7f8','230926fb-598a-4d73-9d01-966468ef86f9',1942,'日军逼近保山时','日军逼近保山时，曾有人策划组织维持会，杨绍曾为参与者之一，后因日军未长期占领保山坝区而未成规模。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d024f41d8b1447e8ce085974694ab71','04ffa2f5-2e5c-4875-b09f-880fa8ef7661',1942,'日方曾试图拉拢其合作','日方曾试图拉拢其合作，但李根源坚持抗日，未附逆，此条仅作排除说明。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e0db0e8c25040eeba8893de6085dfc6','6c43e8d3-3b6f-418a-ab8a-937a2b8670e5',1942,'日军侵占龙陵后','日军侵占龙陵后，出面组织龙陵县维持会，为日军征派民夫、粮秣，协助维持占领区秩序，是龙陵当地较有影响的附逆人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c363e864b794ca68bd74210bbfec8ca','3d27218e-f25b-4756-a204-335ac00b4114',1942,'在龙陵沦陷期间参与伪维持会事务','在龙陵沦陷期间参与伪维持会事务，协助日军推行保甲、征粮和情报搜集，为当地伪政权骨干之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f11c27a5756c4cc5a58fa55541700dff','2763a17a-1279-4af6-b2a7-87ee0771b801',1942,'保山沦陷前后投靠日军','保山沦陷前后投靠日军，组织伪维持会，为日军筹粮、派夫并协助宣传‘大东亚共荣’，是保山地区有记载的附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a5e8545bd7045929dae9186472aff1f','e9661d2f-edc4-4ab6-94b5-26cce01cdf4b',1942,'在日军控制保山期间出任伪警察局长','在日军控制保山期间出任伪警察局长，带领伪警配合日军搜捕抗日人员、镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5377a40b6d1f411a847982b4f4abea41','09837b2e-f2c0-4598-b167-bf82d6c0c600',1942,'在龙陵沦陷区推行奴化教育','在龙陵沦陷区推行奴化教育，改编教材、强制日语教学，为日军文化侵略服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97f97b5ef721423f8ac6c75881d36f60','246faa36-7730-45bc-8841-0b0049266a99',1942,'串联保山、龙陵、腾冲等地伪维持会','串联保山、龙陵、腾冲等地伪维持会，协助日军建立和巩固滇西占领区伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c1709bca56e46fe9cf13b187385b44d','13f84523-e94d-4369-86e5-d84bb2696f9a',1942,'率伪保安队配合日军扫荡龙陵周边抗日武装','率伪保安队配合日军扫荡龙陵周边抗日武装，参与抓捕和审讯抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33637d0614964889810c533a8267d8e9','e7eda559-533f-405e-9a2e-466154682404',1942,'利用保甲长身份为日军搜集抗日游击队情报','利用保甲长身份为日军搜集抗日游击队情报，带领日军搜山，导致多名抗日人员被捕。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f57478d2eaf47a29ac3f662afe9f612','94ca23f4-e4a8-4a98-a405-3ae40ff3a0be',1942,'在日军占领期间控制龙陵商会','在日军占领期间控制龙陵商会，为日军采购物资、摊派款项，并协助日军对食盐、布匹等实行统制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d788ca74254d44abb8dde9dfff3159d1','31770082-569b-4e60-8905-44ab3a814c9a',1942,'在保山、龙陵一带收编地痞流氓组成伪军','在保山、龙陵一带收编地痞流氓组成伪军，配合日军守备据点、修筑工事，参与对抗日根据地的封锁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69e99014f582489784b7cff7f6dce68b','647ede40-492d-4370-b84f-5496b12db5ae',1942,'日军侵占滇西后','日军侵占滇西后，刀京版在瑞丽、陇川一带组织维持会，协助日军征粮、派夫、维持治安，并出任伪瑞丽设治局局长，为日军在德宏地区的统治提供地方行政支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19f53b4ba605413a834866b92fb4ce24','b25b90eb-5531-4cfa-aa84-47db9f52efd8',1942,'日军占领梁河后','日军占领梁河后，龚绶投靠日军，在南甸（今梁河）组织维持会，出任伪南甸宣抚使，协助日军征派粮秣、民夫，并参与镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac497e512fdf4beda4f814fc75051cf3','c9792098-98fd-43cf-b592-332e43085aa2',1942,'日军侵入盈江后','日军侵入盈江后，多永安率土司武装投敌，组织伪维持会，协助日军控制干崖地区，为日军提供情报和物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf5f065461ca41b38f2d87d8a7d9bd31','ab5a698b-93ff-421f-be9b-ac4d66ada9e9',1942,'线光天在陇川投靠日军','线光天在陇川投靠日军，出任伪陇川设治局局长，组织维持会，协助日军征粮、派款、修筑工事，并参与诱降当地抗日武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42081b05a8ac4b4a9eabb2d2ea8350a2','3ca1f4b8-bd99-4e98-ae61-705064e992bb',1942,'日军占领潞西（今芒市）后','日军占领潞西（今芒市）后，思鸿升投敌，出任伪芒市安抚使，组织维持会，协助日军统治潞西地区，征派粮秣民夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa6a2af50ce8479d8d3d3172d872f818','870ea1a8-1a08-40e4-a9ce-8e2c7b306945',1942,'方克光在遮放地区投靠日军','方克光在遮放地区投靠日军，组织维持会，协助日军控制遮放、畹町一带，为日军提供情报和后勤支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb91082a9aeb4627b2238bc69f0983dc','c7eb3d94-0b3e-43f7-92ef-7db4f602b326',1942,'日军占领腾冲后','日军占领腾冲后，李国清出面组织伪腾冲县维持会，协助日军征粮、派夫、维持治安，并参与建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8f0d061714a41d79c7e649c7afb8268','3315313e-ef4e-48d6-a31e-1fb02d26525c',1942,'董友芹在日军占领腾冲期间出任伪县长','董友芹在日军占领腾冲期间出任伪县长，协助日军推行伪化统治，征派粮秣民夫，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c675cefee82043be868bb80e864818ee','8a4f0fa4-d5a8-4684-ad9e-7ea7d7440621',1942,'日军占领龙陵后','日军占领龙陵后，杨吉品组织伪龙陵县维持会，协助日军征粮、派夫、修筑工事，并参与诱降当地抗日武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8f52344b0ab47e9be5749bb6ade8573','882b4e71-52d0-4e23-b707-ed02a2bde6dc',1942,'赵鹏在日军占领龙陵期间出任伪县长','赵鹏在日军占领龙陵期间出任伪县长，协助日军推行伪化统治，征派粮秣民夫，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ac8c9f7009b434cb65a4960b4b06417','e4cfceee-dd5e-413e-ac79-712fd3dfb169',1942,'张问德在腾冲投敌','张问德在腾冲投敌，出任伪腾冲县维持会副会长，协助日军征粮派夫，参与伪政权活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-579eef5f2c3347b592ba34dd02c32d0e','cc59c0f0-8071-4fbb-a136-410fcfc7a077',1942,'尹明德在日军占领梁河期间出任伪梁河设治局局长','尹明德在日军占领梁河期间出任伪梁河设治局局长，协助日军推行伪化统治，征派粮秣民夫。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffc67811f0034db2b2a0e35520797261','fd47f3ea-7432-4fd6-9cb8-1835e5bc5a31',1942,'龚统政在梁河投靠日军','龚统政在梁河投靠日军，出任伪南甸宣抚司属官及伪维持会副会长，协助日军征粮派夫，参与镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-466da6d38ce24bb4be444fac004d43a8','c0073270-7d79-4ed5-8fd0-5afc9b44a3a3',1942,'刀承钺在瑞丽投敌','刀承钺在瑞丽投敌，出任伪瑞丽设治局副局长，协助日军控制瑞丽地区，征派粮秣民夫。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b52e496c2f1f4f5c853e9178a81bc097','f63d4274-8407-4cf5-b036-1e2f2d7fa77f',1942,'排启仁在潞西投靠日军','排启仁在潞西投靠日军，出任伪维持会副会长，协助日军征粮派夫，参与伪政权活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8cf44fad01f4593a787e475b14e87db','8e875ae9-b641-4c0e-a9d6-d36117390b64',1942,'日军侵占滇西后','日军侵占滇西后，刀京版在瑞丽、畹町一带组织维持会，协助日军推行‘以华制华’政策，为日军征派粮秣、民夫，并参与组建伪地方武装，配合日军对滇西抗日游击区进行扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d573aeba61d40b49f268c0393ca210f','c3009939-436c-408e-a945-497140bd5b80',1942,'日军占领潞西（今芒市）后','日军占领潞西（今芒市）后，龚绶率先投敌，出任伪芒市安抚使，主持伪维持会，为日军搜集情报、征粮派款，并诱降当地土司头人，协助日军控制芒市、遮放一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c54936c6404941739166321097280419','0e0abcdb-71b3-4230-bd73-941bdfc0454b',1942,'在芒市地区协助龚绶组织伪维持会','在芒市地区协助龚绶组织伪维持会，负责摊派粮款、登记民户，为日军提供劳工，并参与镇压当地抗日民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e90de4ad0cff496fb8dd3d0318d3a10c','cab0f5d5-3936-47e2-b11b-8187a1ca5a83',1942,'日军侵占遮放后','日军侵占遮放后，多英培出面组织维持会，为日军筹集粮食、修筑工事，并带领伪军配合日军巡逻，搜捕抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4177b1a9d4eb4ae3bf643a7e8097da9b','13eb4a40-d0c6-499d-8f4e-3237b8f2a442',1942,'在陇川地区组织伪维持会','在陇川地区组织伪维持会，协助日军征调民夫、粮食，并参与诱降当地景颇族、傣族头人，为日军提供情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3923eee516434d17b2345228b72ff261','e8d7499b-b011-4f45-8bd2-59378372b7db',1942,'日军侵入盈江后','日军侵入盈江后，思鸿升投敌，组织维持会，为日军征粮派款、修筑道路，并协助日军搜捕抗日志士。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b47b487cc5247f994fafb137dc8388b','3a774552-bd86-457c-8deb-4abba8daa978',1942,'在梁河地区组织伪维持会','在梁河地区组织伪维持会，为日军筹集物资、提供民夫，并配合日军对当地抗日武装进行清剿。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
