INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-058b9fbd6d294704b1b3918a759c5479','6f5990d8-753b-4b8c-afde-a533b966ba34',1940,'利用宗教身份为日伪服务','利用宗教身份为日伪服务，在回族群众中散布亲日言论，协助日军招募伪军，破坏抗日民族统一战线。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8650f500a0bd4d5facee85e7456501f2','6f5990d8-753b-4b8c-afde-a533b966ba34',1940,'云南回族上层人士','云南回族上层人士，抗战期间与日伪合作，利用宗教身份为日军宣传‘大东亚共荣圈’，动员回族青年参加伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af77df28c21a4309aa9069bd17bc4557','c052b817-762a-4e35-88f6-cd42fc06bfb4',1940,'主持伪财政','主持伪财政，为日伪政权搜刮民财，滥发伪币，导致云南部分地区经济混乱，民众生活困苦。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7374e4c068b340e4828b87f64f3523da','c052b817-762a-4e35-88f6-cd42fc06bfb4',1940,'原云南财政官员','原云南财政官员，投敌后出任伪职，为日伪政权筹措经费，加重云南民众税负，支持日军侵略战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-efbb433763a841139125cc8e6c1c5b9e','8cada609-b789-4bbd-8ee7-ae561cf74490',1940,'出任伪昆明县县长','出任伪昆明县县长，推行日伪政令，征发民夫、粮食供给日军，协助建立伪保甲制度，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-638ff83c3ef24bb7b94727027293b5cf','5e9e4a85-1b03-4547-bb95-d267ef7ba48b',1933,'热河失守后投敌','热河失守后投敌，组织伪军配合日军进攻察哈尔、绥远等地，后任伪蒙古军总司令等职，是华北、西北地区重要伪军头目之一','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-185221d564844900903a91327139c971','5e9e4a85-1b03-4547-bb95-d267ef7ba48b',1933,'其活动主要不在云南','其活动主要不在云南，但属于抗战时期有明确记载的著名汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8aeafe156e74467946919c947e19296','9ccb3f45-d496-4a56-bff2-d3751dc99c92',1936,'绥远地区投敌','绥远地区投敌，组织伪军配合日军进犯绥西，曾任伪绥西联军总司令等职，属华北、西北伪军系统。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1295a03bd0664f6283e97d9d0d2096ef','9ccb3f45-d496-4a56-bff2-d3751dc99c92',1936,'绥远地区伪军头目','绥远地区伪军头目，投靠日军后组织伪军，在绥远、察哈尔一带配合日军作战，其活动范围与内蒙古中西部及锡林郭勒盟西部邻近。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e26571bb9d244228b479e3f659f5fc8','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'即德王','即德王，在日军扶植下成立伪蒙古军政府、伪蒙古联合自治政府，任主席，是内蒙古地区重要汉奸政权头目。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4842d2ee2f74ceca8327373483605d9','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'即德王','即德王，在日军扶植下成立伪蒙古军政府、伪蒙古联合自治政府。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41e40a07cf864bb78b17741c75a0cda1','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'蒙古王公','蒙古王公，投靠日本建立伪蒙政权，是华北伪政权重要头目，其伪政权与汪伪有联系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28556868133749918eacff1ea90c7cdc','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'蒙古王公','蒙古王公，投靠日本，成立伪蒙疆政权，统治察哈尔、绥远等地，与陕西北部接壤，配合日军封锁陕甘宁边区，推行奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-53d932eaa58946a487cf390eb19553ed','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'在内蒙古建立伪政权','在内蒙古建立伪政权，投靠日本，其势力范围接近陕西北部。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ea4854cb07b4a948343eaf3a6385181','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'投靠日本','投靠日本，在内蒙古建立伪政权，配合日军侵略，其活动范围与陕西北部接壤。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e766421fc0947a1bab373b739d62cc5','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'蒙古王公','蒙古王公，投靠日本建立伪蒙政权，协助日军侵略华北，对陕西宝鸡抗日后方构成威胁。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7509d3222c154365b78b78c8da085033','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'投靠日本','投靠日本，在内蒙古建立伪政权，其势力范围与陕西北部接壤，参与日军对西北的封锁与进攻。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35ecc5fe9eb047429572ce518866019d','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'在日军扶植下成立伪蒙古军政府','在日军扶植下成立伪蒙古军政府，后任伪蒙古联合自治政府主席，分裂中国。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
