INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa8919a2d1624790bfb298af2a348987','380a96b6-fe5d-4c49-b198-b00ef9f1866b',1936,'投靠日本','投靠日本，在内蒙古建立伪政权，配合日军侵略华北和西北。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
