INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a1c388b57eb42bcb95beac746592a04','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在日军策动下成立伪冀东防共自治政府','在日军策动下成立伪冀东防共自治政府，任主席，割裂冀东，是华北早期伪政权头目之一。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67e826838c0344d9ab99804e26a82c52','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪政权','在华北建立伪政权，是抗战时期早期汉奸头目之一，其活动区域与内蒙古邻近。','危害等级A（甲级，地方伪政权首脑）','hanjian');
