INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82afe2a35a3f4a78b955c9c89192624c','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'早期汉奸','早期汉奸，其伪政权模式影响山东，后任伪华北政务委员会要职，间接涉及济宁地区日伪统治。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d56f8be3eae4f4fb82a01d995a7ee92','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'早期华北汉奸政权头目','早期华北汉奸政权头目，其附逆活动影响华北包括山西北部日伪政权建立。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea928632efac4cf99d9d48c13581f6e4','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'虽以冀东为主','虽以冀东为主，但1938年后投靠汪伪，曾在南京鼓楼区活动。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ee0d710ec5a4d2d92ee6152574a6260','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在冀东（含唐山玉田）建立伪政权','在冀东（含唐山玉田）建立伪政权，推行奴化教育，协助日军控制冀东地区。','危害等级A（甲级，地方伪政权首脑）','hanjian');
