INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3a1302c6ff446118f12c503345c6fd2','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'虽为冀东全区','虽为冀东全区，但直接管辖廊坊、大厂等地，推行亲日政策，出卖华北主权，为日军侵华提供便利。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c5192b5225744189bf3c2430e7926b7','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在河北东部包括廊坊周边地区建立伪冀东防共自治政府','在河北东部包括廊坊周边地区建立伪冀东防共自治政府，公开投敌，为日军侵华服务。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18573ee9a561404883ed9dbe72271432','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在河北东部建立伪政权','在河北东部建立伪政权，后与伪华北政权合流，其附逆活动对河北全省包括张家口地区的伪化统治有影响。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a02bebd6d4344eda861ff5b2fe6b8156','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在河北东部成立伪政权','在河北东部成立伪政权，推行亲日卖国政策，其伪政权与承德伪满势力相呼应，为日军在河北的侵略提供行政与后勤支持。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d86bbe4f5a5946bab8c2b38901476219','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'虽非承德籍','虽非承德籍，但所辖冀东地区包括今承德部分区域，与日军勾结，建立伪政权，破坏抗日活动。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55dc06c02e604432a168339c3659104c','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在冀东建立伪政权','在冀东建立伪政权，配合日军侵华，战后以汉奸罪被处决。','危害等级A（甲级，地方伪政权首脑）','hanjian');
