INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd388dc053534ca09ddfad15782b2de0','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'1935年成立伪冀东防共自治政府','1935年成立伪冀东防共自治政府，任主席，是华北地区最早投敌的汉奸之一。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69281d3c8c6d4f0b857428613c42a186','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'伪冀东政权首脑','伪冀东政权首脑，主要活动于河北东部，与重庆沙坪坝无直接关联。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94457366a1844939a68c0af324bcb2c1','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'早年在华北活动','早年在华北活动，1935年成立伪冀东防共自治政府，公开投敌，后任伪华北政务委员会要职，协助日军控制华北交通与经济，其伪政权与陕西周边沦陷区有联系。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9cff5b7967f1449aa274a2ae229535db','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在冀东建立伪政权','在冀东建立伪政权，为日军侵华服务，其活动对华北包括陕西周边地区产生负面影响。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dab2e9ea0c3845749edcff83daec1d3c','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪自治政权','在华北建立伪自治政权，配合日军侵略，其活动虽主要在冀东，但作为华北伪政权早期代表，对包括陕西在内的华北地区产生示范性附逆影响。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ec57148911c433b815f7955e9d36c6b','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪政权','在华北建立伪政权，配合日军侵略，其活动影响波及陕西等地的抗日局势，后任伪山西煤矿公司董事长等职。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec56d4dfd17147e48151763dd8d125b5','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪政权','在华北建立伪政权，配合日军侵略，其活动对陕西等地的抗日形势产生间接影响。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9949576194014cb0b3b727079678e34d','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪政权','在华北建立伪政权，配合日军侵略，其伪政权模式影响华北各地，包括陕西沿边地区的维持会组织。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91c3123e3714496a96c7e0d5fffbeabd','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'华北早期伪政权头目','华北早期伪政权头目，其“防共自治”模式被推广至华北各地，包括陕西黄河沿岸日占区，对榆林、神木一带的伪维持会组织有示范和策动作用。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ed381aeceb54c2bba44b270ff5b18c1','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'华北早期伪政权头目','华北早期伪政权头目，其伪化活动对陕西、渭南一带的汉奸势力有示范和联络作用。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6c84fb026334104a29d93661081b9b1','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪自治政权','在华北建立伪自治政权，配合日军侵略，其活动区域与陕西邻近，对西北地区伪政权有示范影响。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7114f0239f474c5dae7762fe42c44cda','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在日军扶植下于冀东成立伪冀东防共自治政府','在日军扶植下于冀东成立伪冀东防共自治政府，割裂华北，后并入伪中华民国临时政府，继续附逆。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef3793afcd2d44f6a2068a78361b8b5e','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪自治政权','在华北建立伪自治政权，配合日军侵略，其活动虽主要在冀东，但作为华北伪政权早期代表，对包括陕西在内的华北抗日局势产生负面影响。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-491da870854e4e4f95e2920980fc689f','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪政权','在华北建立伪政权，配合日军侵略，其伪政权与陕西等地伪组织有联系。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f667fd31f419410695fd934b361c7a95','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'1935年成立伪冀东防共自治政府','1935年成立伪冀东防共自治政府，是华北最早公开投敌的汉奸政权头目，其伪化模式对陕西等地伪政权有示范影响。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9bee4b6fa6be47fe994ddbedb56074ab','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在日军扶植下成立伪冀东防共自治政府','在日军扶植下成立伪冀东防共自治政府，是华北早期汉奸政权头目之一，其活动对华北包括陕西抗日局势产生负面影响。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d39153900360404e907d536c218c03a7','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在日军扶植下成立伪冀东政权','在日军扶植下成立伪冀东政权，后参与伪华北政务，其活动对华北包括陕西地区产生波及影响。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e08e9f70a0f54240b9c7dc650f1d438a','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪自治政权','在华北建立伪自治政权，为日军侵华服务，是华北地区早期汉奸头目之一。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15df6202ee5a4126935461c2a917561a','cdb23397-d703-407a-a426-bf3b1cb0eb53',1935,'在华北建立伪自治政权','在华北建立伪自治政权，配合日军侵略，其伪政权与陕西同属北方地区，对华北抗日力量造成威胁。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-995614100bef4a2c8de549bdce633975','ae919299-d388-4730-b8a2-88fd63f61579',1937,'北平沦陷后组织伪中华民国临时政府','北平沦陷后组织伪中华民国临时政府，任行政委员会委员长，后并入汪伪政权，是华北伪政权核心人物。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9f070ccb7bf419a9c9f4e8771609f6e','ae919299-d388-4730-b8a2-88fd63f61579',1937,'在北平（今北京）组织伪政权','在北平（今北京）组织伪政权，为日本侵略者服务，推行奴化政策，镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28e81c81ba684ea08fad293111bfbcfc','ae919299-d388-4730-b8a2-88fd63f61579',1937,'抗战期间投敌','抗战期间投敌，在北平组建伪临时政府，为日军侵华提供行政支撑，其伪政权名义上管辖包括四川在内的沦陷区相关事务。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb63fab544474b39981ef5276c3b2677','ae919299-d388-4730-b8a2-88fd63f61579',1937,'伪临时政府首脑','伪临时政府首脑，其政权虽以华北为主，但与四川成都、邛崃地区的伪维持会及伪军有联系，推动地方附逆势力配合日军。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70c34362a4df49109638ffd8a1e22639','ae919299-d388-4730-b8a2-88fd63f61579',1937,'华北伪政权头目','华北伪政权头目，其伪政权与四川无直接关联，但作为全国性汉奸代表，其活动影响波及四川。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-908a4f5df9854042b845a9b95d927005','ae919299-d388-4730-b8a2-88fd63f61579',1937,'伪临时政府首脑','伪临时政府首脑，其伪政权体系延伸至四川部分地区，对成都地区伪政权有名义上的统辖关系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ce33b5bfb6e488d987e34a05563804a','ae919299-d388-4730-b8a2-88fd63f61579',1937,'1937年12月在北平成立伪临时政府','1937年12月在北平成立伪临时政府，任行政委员会委员长，后并入汪伪政权，任伪华北政务委员会委员长。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae161efad01a4eae861168e0a4077402','ae919299-d388-4730-b8a2-88fd63f61579',1937,'伪临时政府首脑','伪临时政府首脑，其政权覆盖华北包括山东聊城，推行保甲和治安强化。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
