INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-627d053330cd41b5b57930967385e67a','ae919299-d388-4730-b8a2-88fd63f61579',1937,'华北伪政权头目','华北伪政权头目，配合日军侵略，其伪政权与南方伪组织有联系，对广西等地有政治诱降宣传。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
