INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c89f4b905a654ef4bb7c7639fd1f69a3','ae919299-d388-4730-b8a2-88fd63f61579',1937,'曾到南京鼓楼区与维新政府协调','曾到南京鼓楼区与维新政府协调，后并入汪伪。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1074d26a0afd4a18bfee40d04151707f','ae919299-d388-4730-b8a2-88fd63f61579',1937,'伪临时政府头目','伪临时政府头目，其伪政权体系影响华中、江西沦陷区，协助日军建立伪秩序。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3605fc4acf14f0dad64ad81491cae95','ae919299-d388-4730-b8a2-88fd63f61579',1937,'组织伪临时政府','组织伪临时政府，后与伪维新政府合并为汪伪政权，其伪化体系延伸至江西九江沦陷区，配合日军维持会与保甲制度。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e906d7e1f49a4a9aa9d7deddab116587','ae919299-d388-4730-b8a2-88fd63f61579',1937,'浙江杭州人','浙江杭州人，抗战期间投敌，组织伪中华民国临时政府，任行政委员会委员长，其伪政权覆盖华北，与江西无直接关联，但属全国性知名汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e963fb2dc9ad46ea801e5f7916b64892','ae919299-d388-4730-b8a2-88fd63f61579',1937,'华北伪政权首脑','华北伪政权首脑，其统治覆盖廊坊全境，推动“新民会”在基层建立汉奸组织。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00ff6fe960984d45b691f54c7ebcd4ce','ae919299-d388-4730-b8a2-88fd63f61579',1937,'在北平成立伪政权','在北平成立伪政权，其势力范围延伸至冀东及秦皇岛，配合日军对海港地区进行经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
