INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3843804b01fd4313bf4abb50fd663b89','ae919299-d388-4730-b8a2-88fd63f61579',1937,'华北伪政权首要人物','华北伪政权首要人物，虽主要活动于北平，但其伪政权体系覆盖陕西部分沦陷区及邻近地区，对渭南、华州一带的伪化渗透有间接影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b26564244804bf29fb5088a3eb60c4d','ae919299-d388-4730-b8a2-88fd63f61579',1937,'1937年12月在北京成立伪中华民国临时政府','1937年12月在北京成立伪中华民国临时政府，任行政委员会委员长，统辖包括陕西在内的华北伪政权事务，是华北地区最高汉奸头目之一。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
