INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd7d9077416f42d7931b88b1af601615','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原奉系军阀','原奉系军阀，九一八后投敌，虽主要活动于新京（长春），但其势力范围涉及吉林全省，包括白城、大安地区，支持日军殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e17eef6d02040549e8e7a5ee1f8bb6c','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'虽为奉系元老','虽为奉系元老，但1932年公开投敌，任伪满军政部总长、国务总理，其势力范围曾涉及吉林西部及白城地区，推行日满亲善政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab67f2ed17aa4457a816f9f858aebff4','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'虽为伪满中央高官','虽为伪满中央高官，但曾长期控制吉林地区军政，其政策直接影响辽源、东辽，支持日军“治安肃正”，镇压当地抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba984b78a22c4e8e923c2a17e9494374','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'曾任东三省特别区长官','曾任东三省特别区长官，后投敌，历任伪参议府议长、军政部总长、国务总理，全面配合日本侵略政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad85194ba99448f084959f5f8aa3e3d0','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原吉林军将领','原吉林军将领，后投敌任伪满总理，全面配合日本对东北的军事占领、经济统制和思想奴役，是吉林长春地区最高级别汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01b3a3e64a4742f8b537411da5756644','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'曾任东省特别区长官','曾任东省特别区长官，后投靠日本，历任伪满参议府议长、军政部总长、国务总理，全面配合日本侵略政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc18d1df5926493eafdd0b23ad7f7c9c','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'长期担任伪满总理','长期担任伪满总理，配合日本对东北的殖民统治，并参与对关内包括四川在内的抗战力量进行政治诱降。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e36a3d07a52e4e3488b51d7dd9a2d551','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'虽主要活动于东北','虽主要活动于东北，但作为四川籍（或与四川有联系）的汉奸，其伪满政权与四川成都、邛崃地区的附逆者有往来，影响当地伪政权建设。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-259a52aa94814093adeb1380738ea805','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'东北伪政权头目','东北伪政权头目，与四川无直接关联，但作为全国性汉奸代表，其活动影响波及四川。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2da5edadd1144a3bb19d0560f40dac7e','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'伪满洲国首脑','伪满洲国首脑，虽主要活动于东北，但其伪政权模式被四川地区伪组织效仿，间接关联成都附逆活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cc3ba0bee624757b9afbf70762b074a','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'伪满头目','伪满头目，其政权与华北伪政权有联系，间接影响山东聊城地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2372750141e6487baf8ba6c06686a54a','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'东北伪满洲国头目','东北伪满洲国头目，属东北伪政权，与广西无直接关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffbc0bb92f32448e956cc30b5d2ee06f','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'九一八事变后投敌','九一八事变后投敌，长期担任伪满洲国要职，是东北伪政权头目，属于抗战时期有明确记载的汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfbf6470f27e4882b364154aec8f09ca','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'东北伪政权头目','东北伪政权头目，属全国性汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-baff5c2f2813430ea00b6aac7a0dda3c','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原奉系军阀','原奉系军阀，后任伪满洲国总理，虽驻长春，但参与制定对热河省（含承德、滦平）的殖民政策，支持日军“治安肃正”行动。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c225885fea04365ab58031d5763ba92','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪满最高行政长官，其管辖范围包括热河省（今承德、隆化一带），支持日军对当地抗日武装的镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6ce6f38a7e44bb48d5c974ea517cbff','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'虽为伪满总理','虽为伪满总理，但伪满势力曾延伸至山海关一带，对当地有间接统治影响','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f40f50b7b1fa457898562932025be7fc','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原东北军将领','原东北军将领，九一八后投日，曾任伪满参议府议长、军政部总长，后任伪满国务总理大臣，是日伪在东北（含辽宁）的最高傀儡。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43b5e985dd2949c49492b6a919c8c822','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'虽为伪满中央高官','虽为伪满中央高官，但多次到安东、宽甸视察，推动“治安强化”政策，对当地抗日力量进行系统性镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5133e1cd814455793e50c01d8706b9d','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原奉系将领','原奉系将领，九一八事变后投敌，任伪满最高行政长官，协助日本统治东北，镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
