INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11b40daed9304d34ba3d0522bd420962','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原奉系军阀','原奉系军阀，投日后任伪满洲国总理，虽为中央级汉奸，但其伪政权统治覆盖辽宁全省，包括盘锦、兴隆台地区，签署多项卖国条约。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
