INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c8a225035f849b49d7df0703fcda8f5','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原东北军将领','原东北军将领，九一八后投敌，虽为伪满中央高官，但其势力范围及伪军行动覆盖辽宁全境，包括兴城、葫芦岛地区，支持日军“讨伐”义勇军。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-189e7dc5c579482e95d8b1a141413e85','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原奉系军阀','原奉系军阀，全面投日，作为伪满最高行政首脑，其政策覆盖辽宁全省包括绥中，支持日军侵略。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8996c71ff39844c78184a8898437369f','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原奉系将领','原奉系将领，九一八后投敌，任伪满总理，其势力范围涵盖辽宁，支持日军在葫芦岛等地修建军事设施。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-795ba57f2b8c4eb2885dec58ee5c8438','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原奉系军阀','原奉系军阀，九一八后投日，曾任伪奉天省长，后升任伪满国务总理，全面协助日本统治东北。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-453938e06d5b47eabdc5f639d628fc9a','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原奉系将领','原奉系将领，九一八事变后公开投敌，任伪满军政部总长、国务总理大臣，全面配合日本侵略政策，镇压东北抗联。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d852cbf497b04607bfb428f8ed425e01','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原奉系军阀','原奉系军阀，后投日，虽主要活动于新京，但曾多次到铁岭地区视察“治安”，推动“日满亲善”和殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fdc87dc63a5d4722a33ca10eb0765d03','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'原东北军将领','原东北军将领，九一八后投敌，历任伪满参议府议长、国务总理，在辽宁各地推行殖民统治，包括阜新地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4e78e9319fe4aa2a1d5b0b913341b16','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'长期担任伪满总理','长期担任伪满总理，推行日本殖民政策，战后被苏联俘虏。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5fdcd70586614110bdbb80fbb421cdef','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'伪满洲国要员','伪满洲国要员，主要活动于东北，与重庆沙坪坝无直接关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-935deddd4b8b44b48d49aa503c33bf44','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'长期担任伪满洲国要职','长期担任伪满洲国要职，协助日本统治东北，其伪政权与华北伪政权有联系，间接影响陕西周边。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32745aac4541494083311257e4e029ca','b36c5b58-a9c0-4580-af5b-8ac61501db0f',1931,'虽为伪满中央高官','虽为伪满中央高官，但曾多次到黑龙江东部（含七台河地区）视察“治安肃正”，推动建立伪政权和保甲制度，是最高层汉奸代表。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
