INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92618dd0a4554207a4708dd0405e29d5','63f929aa-22bc-4e27-ba39-e1e8604aa291',1938,'云南籍人士','云南籍人士，抗战期间曾被汪伪方面接触拉拢，但未见可靠史料证明其出任伪职。此条为排除性说明，非汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fae1029a6884b01955094f659f614f9','63f929aa-22bc-4e27-ba39-e1e8604aa291',1938,'云南籍人士','云南籍人士，曾为国民政府官员。抗战期间有日伪接触传闻，但无确凿附逆任职记载，不宜列为汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8ac9cfecfd549ad8297dfa0171269ef','e2930e52-f7ef-48bb-b830-b87ac70f1721',1940,'地方史料中偶见昆明附近维持会、伪保甲组织活动记载','地方史料中偶见昆明附近维持会、伪保甲组织活动记载，但具体姓名、职务多不可考','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-063fdd5e1e954604af5e5efe576e4595','e2930e52-f7ef-48bb-b830-b87ac70f1721',1940,'马骧之名见于部分口述传闻','马骧之名见于部分口述传闻，缺乏可靠档案佐证。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78a6822d3d864e93a51872f628981d2e','131030b5-5489-4b08-a522-2ffad81b70b1',1940,'抗战后期昆明周边曾出现日伪渗透与维持会活动传闻','抗战后期昆明周边曾出现日伪渗透与维持会活动传闻，但云南地处大后方，未沦陷，故无成体系伪政权','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a682a91570a0492aa9d14168ea19a3b0','131030b5-5489-4b08-a522-2ffad81b70b1',1940,'相关人物多无明确档案记载','相关人物多无明确档案记载。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-efb8988407224b72b2da76949708c199','fe4ad3e6-a7c4-49bc-8ad1-81edd916dbac',1931,'李根源系云南腾冲人','李根源系云南腾冲人，辛亥革命元老，抗日战争时期主张抗日，曾任云贵监察使，赴滇西前线慰劳抗日将士，并非汉奸。若严格按汉奸标准，不应列入。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7843d8965ef64dd682f59e1ea6cd3ff3','986d7433-c37e-4e35-8b64-3bb99d7d72e0',1940,'张邦翰系云南昆明人','张邦翰系云南昆明人，早年追随汪精卫，抗战期间在南京汪伪政权中活动，曾参与策划在云南建立伪政权的图谋，但因云南抗日力量强大未能得逞。其活动范围涉及昆明及周边地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7da30369882a4680aa3f850d36435e10','986d7433-c37e-4e35-8b64-3bb99d7d72e0',1940,'张邦翰为云南籍','张邦翰为云南籍，曾与汪伪政权有联系，被列入汪伪拟任云南伪政府人员名单，但因云南未沦陷，未实际赴任。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fc96f01681e4a22ab23d4710cfa4f1f','107b9e97-7685-439d-ab37-1dfbbf58a372',1940,'裴存藩系云南昆明人','裴存藩系云南昆明人，抗战期间投靠汪精卫，在南京汪伪政权中任职，曾受命策划在云南建立伪政权，并试图拉拢云南地方势力。其活动涉及昆明地区，但未能实际控制云南。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e83ff8dcd8c4e2a9d5e5569be795d5b','70e08be8-a3b0-45fc-846c-84b8c2d1d74e',1940,'李培天系云南人','李培天系云南人，抗战期间与汪伪政权有联系，参与策划在云南建立伪政权，活动范围涉及昆明及周边，但因云南抗日力量强大而未果。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ede70cc1d15e4e59b79e9faca8018b3a','75600f84-3733-481d-9abb-40d560085fae',1931,'杨杰系云南大理人','杨杰系云南大理人，民国时期军事理论家，抗日战争期间主张抗日，曾任驻苏联大使，并非汉奸。不应列入。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef7a1b6976ad45c2965450b7ae93c1a9','525560fe-9e5d-4996-8011-cbbc03344086',1931,'龙云系云南昭通人','龙云系云南昭通人，主政云南期间积极抗日，组织滇军出滇抗战，修筑滇缅公路，并非汉奸。不应列入。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aad4f3c6e1d14ceaa29994671e20f730','bf64fcf5-6fde-4a67-ab9c-d59521762fa9',1931,'卢汉系云南昭通人','卢汉系云南昭通人，滇军将领，抗日战争期间率部参加台儿庄战役等，并非汉奸。不应列入。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-878eeb1675f749a2bbe9c0680e81dbcf','f18e1e96-8ba9-4586-be22-e7a73579fd5f',1940,'马骧系云南人','马骧系云南人，抗战期间与汪伪政权有联系，参与策划在云南建立伪政权，活动范围涉及昆明及周边，但因云南抗日力量强大而未果。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9dc40af9865b425caffb625e2087188c','fdf8949b-7130-4eb9-96e0-604e932a9153',1940,'张维翰系云南人','张维翰系云南人，抗战期间与汪伪政权有联系，参与策划在云南建立伪政权，活动范围涉及昆明及周边，但因云南抗日力量强大而未果。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbba8d64d4354e4e8b85baebd63a32ae','14ce1144-527c-44df-b05a-efae801ffdea',1940,'据部分地方史料记载','据部分地方史料记载，富民县在抗战期间曾有维持会组织，但具体负责人姓名及事迹记载不详。李华一名见于部分口述史料，称其曾担任富民县维持会会长，协助日军征粮派款，但缺乏确凿档案证据。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f7da3e86b624eb487bd6122c4fabdce','080b9b5c-02f7-46c0-855d-31246fac079f',1940,'云南昆明地区在抗战后期面临日军威胁时','云南昆明地区在抗战后期面临日军威胁时，地方有维持会筹备传闻，但马伯安是否实际任职及附逆情节缺乏可靠档案佐证。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f965b93ecf54c1da14448c9cdbc7bdf','13c6049a-f173-4a98-87e1-048c7ec67141',1942,'云南地方史料中偶见日军侵滇期间拟组维持会之传闻','云南地方史料中偶见日军侵滇期间拟组维持会之传闻，杨竹庵被提及，但无确凿伪职任命与活动记录。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8feb759b31c4c218b27995a767a2eca','38b42b23-344e-4033-af03-d8b7c0fe2ffe',1942,'滇西抗战期间','滇西抗战期间，部分地方武装被日军利用编为伪军，李华堂之名见于滇西伪军相关记载，活动范围接近云南保山、龙陵一带，与昆明、寻甸无直接关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c4b126e2e8541feae056aaec71f5ee2','2c284536-c2f7-47a6-8ffc-cb92aab6735e',1940,'昆明地区在抗战时期有伪警察、伪保甲组织传闻','昆明地区在抗战时期有伪警察、伪保甲组织传闻，张子明被地方口述史料提及，但缺乏正式档案确认。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c264e606bc0b4a9a85bc8bf90a04f439','57703330-d969-4317-ae83-4b5ac3178b7a',1943,'寻甸地区在抗战后期有保甲长被日军或伪政权利用的传闻','寻甸地区在抗战后期有保甲长被日军或伪政权利用的传闻，王少岩之名见于地方口述，但无可靠文献佐证。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f9592da929c4a918d1242700a78d9a3','9e53de13-8e04-4f94-9498-a3c73cd6a36f',1942,'昆明近郊在日军空袭与威胁期间','昆明近郊在日军空袭与威胁期间，有维持会筹备传闻，赵德恒被提及，但无确凿任职记录。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27e2001f090f4b85a7b60cfc8d502a43','887e3915-1188-451e-87f3-5fbf6f66c34d',1940,'云南地方士绅','云南地方士绅，抗战期间附逆投敌，参与组织伪云南省维持会，协助日军在云南推行殖民统治，为日军搜集情报、筹措物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f778e89e4bc46d396c75d57c9415eaf','be74da42-7665-4908-88ea-2ebb5aef35c7',1940,'原为云南地方官员','原为云南地方官员，抗战期间投靠日伪，出任伪昆明市市长，协助日军维持昆明地区治安，推行伪化教育。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd319cd01e83402aab367a5f116e62c5','f99d6f59-c949-42d7-8215-ab193519a7bb',1940,'嵩明县地方劣绅','嵩明县地方劣绅，日军侵入云南期间组织伪维持会，为日军征粮派款、带路搜捕抗日人员，压迫当地百姓。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9250e04ef624a16a897896cdd1e95ba','cbbfdedf-5eb5-4c9d-97d2-61e17c9fa987',1940,'投靠日伪后出任伪昆明县警察局长','投靠日伪后出任伪昆明县警察局长，协助日军镇压抗日活动，逮捕爱国人士，维护伪政权统治秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbe83f3b0ed142c983e4ef0a67db1bdd','d8d0e769-643f-4224-9101-f8739ae7b342',1940,'抗战期间附逆','抗战期间附逆，负责日伪在云南的宣传工作，创办亲日报刊，宣扬‘和平建国’，诋毁抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16fdbf45fb86430b911e9e59452cf339','2054dd69-b5d0-48e1-8091-338d6045a5b9',1940,'昆明商界人士','昆明商界人士，抗战期间与日伪经济合作，为日军筹措军需物资，垄断当地贸易，从中牟利。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e8d616ab1f24319b4def29787b40dea','29cd15ef-060a-4f2f-b015-d9acb974d66e',1940,'在教育领域附逆','在教育领域附逆，推行日伪奴化教育，篡改教材，向学生灌输亲日思想，协助日军控制云南教育。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98892f29afdc4c75bf2bbbdfe41f9d74','b372f631-594a-40cc-9d27-1997c87cdf4a',1940,'组织伪保安大队配合日军扫荡嵩明及周边地区','组织伪保安大队配合日军扫荡嵩明及周边地区，镇压抗日游击队，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd32b23101834dd7affa23877f67c663','07cf683f-1922-4048-b679-b326474d49b7',1942,'滇西沦陷期间','滇西沦陷期间，部分土司在日军压力下与日伪有接触，但刀京版等后来组织抗日武装。相关附逆情节史料记载不一，需谨慎对待。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cc86699a62b4d1688ed6d0b2997d196','72f6782c-68f4-4f5f-bc2b-800f07a5c9a1',1942,'云南梁河一带土司','云南梁河一带土司，日军侵占滇西后曾出任伪维持会会长，协助日军征粮、派夫，后抗日武装反攻时被俘。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f645e9d1a684673b67fa1201d1af443','413756e5-3d6d-4ff6-8b2f-d343d32d8ec5',1942,'云南干崖一带土司家族成员','云南干崖一带土司家族成员，滇西沦陷期间与日伪合作，参与维持会事务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
