INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-deffd89ec532428982f55e79824e7957','6158b0cb-7eab-425c-8ef4-95eb9002f022',1940,'昆明作为大后方','昆明作为大后方，未沦陷，无公开伪政权。但日伪特务曾潜入昆明进行活动，相关附逆者史料零散，难以列出具体姓名。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-462f206132d44c9bbf4758a827fc63df','e6b855fb-af9b-4930-a2fd-bbd6a9a8cf58',1940,'晋宁未沦陷','晋宁未沦陷，无公开伪政权。个别地方保甲长在日机轰炸或特务渗透中有妥协行为，但无可靠姓名记载。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ea8e2fc857a48d88cf98dbef6885bf2','e81eef60-9a9b-469e-9840-2faae27d9505',1931,'云南泸西人','云南泸西人，率部参加台儿庄战役，坚持抗日，未附逆。此条为排除性说明，非汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abe84d67ea2d4ca39dfadf75868c48a7','e81eef60-9a9b-469e-9840-2faae27d9505',1931,'坚持抗日','坚持抗日，未附逆','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a518b8fc58d14bfdb04ca5a7318ce9c9','e81eef60-9a9b-469e-9840-2faae27d9505',1931,'但滇军内部个别地方武装在滇西沦陷时曾动摇','但滇军内部个别地方武装在滇西沦陷时曾动摇。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-157b157846724e48aabb9f62f0bd39e7','a3b1e9cd-f631-4dff-8dec-966fbfc9264a',1942,'云南昆明地区在抗战后期面临日军从滇西入侵威胁','云南昆明地区在抗战后期面临日军从滇西入侵威胁，但昆明市区始终未被日军占领，未建立正式伪政权。地方史料中未见昆明市区有明确记载的汉奸名录。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-042391f3ec2f44c590dee8f4c4a1b30a','b1fbf635-32f4-42dc-ad65-4761906f7e8f',1942,'日军侵占滇西腾冲、龙陵等地后','日军侵占滇西腾冲、龙陵等地后，曾在当地扶植伪政权。但昆明、盘龙地区始终在中国军队控制下，未出现成规模的伪政权和汉奸名录。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19ac110957934aca9d3b6a7783a90592','c8824da7-67fe-4717-9102-11c590d987ed',1942,'滇西沦陷区曾出现少数附逆分子','滇西沦陷区曾出现少数附逆分子，但具体姓名和事迹在公开史料中记载极少，且与昆明盘龙地区无直接关联。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-709b8f495aed4d7bb25d4323c355c7dd','37fd580a-4646-46ef-b3ff-c343356e461b',1942,'日军侵占腾冲后','日军侵占腾冲后，当地曾成立维持会。但腾冲属保山地区，与昆明盘龙无直接关联，且具体人员记载模糊。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c3da91651c4428087c4b126c42eb76d','84df698a-def4-45b1-ae02-ae67a635827d',1942,'龙陵沦陷期间曾有附逆人员','龙陵沦陷期间曾有附逆人员，但史料记载不完整，与昆明盘龙地区无直接关联。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3b987ad605a42cea8e74015a0288b62','297732c2-cb0e-47af-b2d8-f757fae25113',1931,'经检索','经检索，昆明市盘龙区在抗战期间始终未被日军占领，未建立伪政权、维持会或伪警察机构。云南省内明确记载的汉奸主要集中在滇西沦陷区（腾冲、龙陵等地），但与昆明盘龙地区无直接关联。因此，针对云南、昆明、盘龙地区的汉奸名录，公开可靠史料中无具体可列人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-600eadd4069c41c791a3fa175b3c5175','87ae8392-7f74-4ae9-8ec9-41772405d2a5',1940,'长期盘踞滇南及昆明周边地区','长期盘踞滇南及昆明周边地区，抗战后期与日伪势力勾连，武装割据，抗拒抗日力量，残害地方民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dab21b25d4e8414ca430993d5fb9a87f','99007739-e6e3-416e-9acc-e7d6c7606c0a',1931,'龙云主政云南期间坚持抗日','龙云主政云南期间坚持抗日，未任伪职','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0081233a4b44ebaa2bec4148eb6eea1','99007739-e6e3-416e-9acc-e7d6c7606c0a',1931,'此条仅因部分民间传闻涉及昆明地区附逆线索而列','此条仅因部分民间传闻涉及昆明地区附逆线索而列，但无可靠史料证明其为汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
