INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0d6ea358163480b8a849d0339104622','235fd8cd-5ec6-4ed2-8f98-c9664054d350',1937,'云南经济界个别人员与日伪贸易往来','云南经济界个别人员与日伪贸易往来，涉及昆明物资资敌，但具体身份存疑。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bbcfe362b134439e8053bda5e8748793','9474881e-f0db-45e4-9501-4374376c1e5f',1942,'李根源为云南腾冲人','李根源为云南腾冲人，辛亥革命元老。1942年日军侵占腾冲时，其家族部分成员曾被迫与日军周旋，但李根源本人坚决拒绝附逆，未任伪职。此条仅作辨析，非汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-660ea966447747cda506a5bf70401140','9474881e-f0db-45e4-9501-4374376c1e5f',1942,'滇西沦陷期间','滇西沦陷期间，日军曾试图拉拢其出面组织伪政权，李根源坚拒并避走，未附逆。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07c98fd280e74fc1b0c01d0309e86927','4a62589e-3df7-4427-bc5e-33e131e1d012',1940,'李培天为云南籍','李培天为云南籍，曾参与汪伪政权对云南的策反与伪政府筹备活动，被列入拟任名单，未实际到任。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c7678c336614e10ae20320e03c0eb61','83f967f6-8a86-4a6b-aaa7-c4fdd59deda7',1940,'马伯安为昆明地方士绅','马伯安为昆明地方士绅，曾被日军及汪伪方面接触，拟任昆明维持会职务，但因昆明未沦陷，未实际成立维持会。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
