INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb9e19e366ea4aaaab79a3d66721071f','5ae36bcc-f4b4-4823-9813-d8db3578e918',1942,'杨绍曾在日军侵占腾冲后出任伪维持会会长','杨绍曾在日军侵占腾冲后出任伪维持会会长，协助日军维持地方秩序、征派粮秣。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5671d86a765447e5968a77a7d801dbdb','a7dbc35a-9a35-43d3-8a87-6549f63fc31b',1942,'董友芹在日军占领腾冲期间出任伪县长','董友芹在日军占领腾冲期间出任伪县长，为日军征粮、派夫，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
