INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef36a97c10de485781ec19e1a23ca7be','ccb31714-2abf-4df2-895e-d015685c4627',1942,'李春芳为保山士绅','李春芳为保山士绅，曾被日军接触拟任伪维持会职务，因保山未沦陷，未实际成立。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
