INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-438f8dffa16640dc8e34268a35f593a1','f95c6f64-cbf5-4a26-998e-53943e095d5e',1942,'据地方文史资料','据地方文史资料，滇西沦陷期间曲靖周边个别维持会负责人协助日军征粮、派夫，但姓名多不可考。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
