INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6f24688200d4f18af998ab3655b8444','945d8aa2-ad77-43d2-8835-4889812c927a',1942,'部分保甲长在日军占领期间被迫或主动为日伪征粮、派款、带路','部分保甲长在日军占领期间被迫或主动为日伪征粮、派款、带路，战后多被追究。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a9afbd8f00f4eada2a485b3d68e6788','1e85f023-49df-4334-bd7f-077d3aa25d08',1942,'在沦陷区推行奴化教育','在沦陷区推行奴化教育，改编教材，宣传“大东亚共荣圈”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
