INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38d2e7dfd2944fa882d902b696e9c1fb','03c79019-6183-42a8-9645-abfb261e18e6',1942,'为日军审讯、劝降抗日人员提供翻译服务','为日军审讯、劝降抗日人员提供翻译服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0acd8089c2b415ebbd0a4ea63f7c3dc','bfc01e63-b932-48b2-929d-8dde865a4520',1942,'在日军占领下出任伪区长','在日军占领下出任伪区长，征粮派夫，压制抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcc834710c68436ba7a26e028df432b6','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原为东北军军官','原为东北军军官，后投靠日本关东军，在乌兰察布地区（今乌兰察布市及周边）参与组建伪蒙古军，协助日军镇压抗日力量，推行“蒙古自治”傀儡政权，多次配合日军扫荡绥东地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0cd8f9464d71470ca52cfe8ac04024fd','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军军官','原东北军军官，1933年投靠日军，组建伪蒙古军，在乌兰察布、丰镇等地协助日军扫荡抗日武装，镇压民众，后任伪蒙疆政府要职。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e23395b441f24b088a521d43406b7449','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原为热河地方军阀','原为热河地方军阀，1933年投靠日军，组建伪蒙古军，在察哈尔、绥远（含乌兰察布、兴和一带）配合日军进攻抗日武装，后任伪蒙疆政府要职，协助日本殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9319e29436b47ef97977693eec31a7e','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军将领','原东北军将领，1933年投日，在内蒙古东部及乌海、海勃湾周边地区协助日军镇压抗日力量，参与建立伪蒙古军政府，后任伪蒙疆政权要职，为日军提供兵员和情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-737bfb73ad4e4afdb6fb8f4fc06b9848','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'热河土匪出身','热河土匪出身，投日后组织伪蒙古军，活动于内蒙古东部及兴安地区，配合日军进攻抗日根据地，其势力范围覆盖科尔沁右翼中旗一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a6c59819d1f443ab81afff9bdce19d5','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军将领','原东北军将领，1933年投靠日军，组建伪蒙古军，配合日军进攻察哈尔、绥远（今内蒙古中西部），在包头、九原一带驻军并协助日军清剿抗日武装，后任伪蒙疆政权要职。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83552427a7f54633a30515c18d10469f','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军将领','原东北军将领，投靠日本后组建伪蒙古军，在包头、青山地区配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0603dc13dddf40179c7cd3099ca44c86','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军军官','原东北军军官，1933年投靠日军，组建伪蒙古军，参与侵占察哈尔、绥远地区，镇压抗日力量，后任伪蒙疆政府要职。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-866d5c2b6d904d038dbcd409c612d218','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'热河卓索图盟人','热河卓索图盟人，早年在内蒙古东部组织伪军，后任伪蒙古军总司令，率部配合日军进攻绥远、察哈尔等地，控制包括呼和浩特在内的绥远大部分地区，推行伪蒙疆政权统治，镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f68fb71f570049ccad93d16750ad1926','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军将领','原东北军将领，1933年投靠日军，组建伪蒙古军，在绥远（今呼和浩特、托克托一带）配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27506af2caab4db2a21d45be349ee903','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'热河、察哈尔、绥远地区蒙古族汉奸','热河、察哈尔、绥远地区蒙古族汉奸，率伪蒙古军配合日军侵占绥远大部，其势力范围覆盖巴彦淖尔地区，参与建立伪政权和伪军组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f97474c0aceb48a1b658e17e41d39604','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原为东北军军官','原为东北军军官，后叛变投日，任伪蒙古军总司令，其部队长期活动于绥远（含巴彦淖尔地区），协助日军控制河套平原，多次进攻抗日武装，并推行奴化教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ebbaaff8d2049a195b1320a625491bb','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原热河省军阀','原热河省军阀，1933年投日，组建伪蒙古军，配合日军侵占赤峰、围场等地，后任伪蒙疆政权军事要职，参与镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-695a7d49461e42db9b56d6a13c1bd07b','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原热河省地方军阀','原热河省地方军阀，1933年投靠日军，组建伪蒙古军，参与侵占赤峰、元宝山地区，镇压抗日力量，协助日军推行殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8859541c47e5483482d65133cff2b2bc','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原为热河地方军阀','原为热河地方军阀，1933年投靠日本关东军，参与侵占热河、察哈尔等地，所部伪蒙古军配合日军在赤峰、昭乌达盟一带清乡、镇压抗日武装，后任伪蒙疆政权要职，是蒙疆地区最大的汉奸头目之一。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d45a18458a5e480195fa717ff110347b','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原为热河地方军阀','原为热河地方军阀，1933年投靠日军，任伪热河游击司令，后任伪蒙古军总司令，参与镇压抗日力量，协助日军控制赤峰、林西等地区，推行殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ed755c8ea5344a39539a3a205771a3b','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'热河蒙古族军阀','热河蒙古族军阀，投靠日本后任伪蒙古军总司令，其部队活动范围包括通辽、科尔沁左翼中旗一带，参与日军对内蒙古东部抗日武装的围剿，后任伪蒙疆政权要职。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43bd1434da8248bf9f84bf1857bddc94','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'率伪蒙古军活动于热河、通辽及科尔沁左翼后旗一带','率伪蒙古军活动于热河、通辽及科尔沁左翼后旗一带，配合日军进攻抗日根据地，收编土匪武装，残害民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac0747c7182045e19d39b49749f8c6c7','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军军官','原东北军军官，后投靠日军，组建伪蒙古军，在通辽及内蒙古东部地区协助日军镇压抗日力量，参与“治安肃正”行动，掠夺资源，迫害民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2355cf1d0e1499182957e72303e5314','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原为东北军骑兵','原为东北军骑兵，后投靠日本，参与组建伪蒙古军，率部配合日军侵占察哈尔、锡林郭勒盟等地，长期在伪蒙疆政权中任军政要职，镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c116083e4af4177aef52d84f8a3fc09','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军军官','原东北军军官，后投靠日军，参与组建伪蒙古军，率部配合日军侵占察哈尔、锡林郭勒等地，任伪蒙古军总司令，是伪蒙疆政权主要军事头目之一。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4413cd80b814629bb2e1f97e4ee8216','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'率伪蒙古军配合日军进攻绥远、宁夏北部','率伪蒙古军配合日军进攻绥远、宁夏北部，在贺兰山以西及阿拉善地区活动，参与对宁夏的军事威胁和情报搜集。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-491b413cfad24084bbd01f0f86e89dad','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'率伪蒙古军配合日军在晋西北、吕梁一带进行扫荡','率伪蒙古军配合日军在晋西北、吕梁一带进行扫荡，参与对抗日根据地的进攻，掠夺物资、残害民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1c52db5371d4397ba6d715372f3acef','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'蒙古地区伪军头目','蒙古地区伪军头目，属华北伪政权体系，与广西无直接关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a15820587c64b309244fd36948a9727','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'蒙古伪军头目','蒙古伪军头目，长期在华北伪政权任职，其伪军系统曾配合日军南下作战。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-199bbae9414143e78bcd92c6a95b0d74','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原为热河地方军阀','原为热河地方军阀，1933年投靠日军，在张家口及察哈尔地区组建伪蒙古军，配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f2d1713b0f446b7b5cb1a0042a6a6e0','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原热河地方军阀','原热河地方军阀，1933年投日，在赤城、沽源一带配合日军进攻抗日武装，后任伪蒙古军总司令，参与“治安肃正”扫荡，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d421a7065254a86a9fdb23408c57b42','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'内蒙古人','内蒙古人，长期在伪蒙疆政权任职，其伪军曾配合日军在河南北部及豫西地区作战，间接影响南阳一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7991d7151fc745778a82054fcdc5f990','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'长期在内蒙古及华北地区为日军效力','长期在内蒙古及华北地区为日军效力，其伪军活动范围涉及河南北部，配合日军对河南抗日根据地的进攻。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad18b8eec6da48beac66e3062f158a1f','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'热河人','热河人，长期在伪蒙疆政权任职，其伪军活动范围涉及华北，包括河南北部边缘地区，配合日军对华北抗日力量进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bebae8e800f0487bb43d1731fac66618','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军骑兵','原东北军骑兵，1933年投靠日军，任伪蒙古军总司令，后任伪蒙古联合自治政府副主席，其伪军活动主要在察哈尔、绥远一带，但作为伪蒙疆政权要员，与河南沦陷区伪政权有联系，间接影响河南包括南阳地区的伪化统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d3fb547609c47bc951ab2ebebcf0c31','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'内蒙古人','内蒙古人，长期在伪蒙疆政权任职，其伪军活动范围主要在察哈尔、绥远一带，与河南无直接关联，但作为华北伪军体系的一部分，与河南伪政权有联系。','危害等级C（丙级，基层头目）','hanjian');
