INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c4d3880805249169e70f4b746ee24bc','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'原东北军骑兵团长','原东北军骑兵团长，投敌后任伪蒙古军总司令，配合日军在热河、察哈尔及东北西部地区作战，其伪军活动范围接近大庆、杜尔伯特地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b18bf1f47208432b9d658e934fc37118','9e163ee1-1fa8-4da1-8e58-206e20b14b34',1933,'内蒙古人','内蒙古人，1933年投敌，任伪蒙古军总司令，活动于热河、察哈尔及黑龙江西部一带，配合日军进攻抗日武装，后任伪蒙古联合自治政府副主席。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a86667174b24de1966868edb4cb2db3','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'虽为察哈尔部贵族','虽为察哈尔部贵族，但其伪政权势力覆盖乌兰察布地区，在四子王旗、达尔罕茂明安联合旗等地设立伪行政机构，为日军提供兵员和物资，协助日军统治蒙汉民众。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4e0f359311a471496531661a4282d80','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，长期策划“蒙古独立”，1936年成立伪蒙古军政府，1939年任伪蒙疆政府主席，其势力覆盖乌兰察布、兴和地区，为日军提供兵员和情报，镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6940a98984084d03946c2a07c96af17b','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，投靠日本，建立伪蒙政权，其势力范围包括乌兰察布盟及凉城一带，配合日军“治安肃正”，征粮抓丁，迫害抗日军民。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7f943ff171c4c87af0aff4ad4e17478','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，策划内蒙古独立，投靠日本，建立伪蒙政权，其势力范围包括乌兰察布、商都地区，推行日伪统治，协助日军掠夺资源。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ef6e78cc0a144048bb0db407b675eaf','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'内蒙古王公贵族','内蒙古王公贵族，积极投靠日本，策划内蒙古独立，在乌海、海勃湾一带推行日伪统治，组织伪蒙古军，协助日军控制河套及鄂尔多斯地区，对抗中国抗日武装。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e30f13abc48647aead87e9df234374f6','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'内蒙古王公','内蒙古王公，策划内蒙古独立，1936年成立伪蒙古军政府，后与日军合作，在包头、九原地区推行殖民统治，建立伪政权机构，协助日军征兵征粮。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-445baa356add4277878b13073ba17cba','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'领导内蒙古西部（包括包头、石拐地区）的伪蒙政权','领导内蒙古西部（包括包头、石拐地区）的伪蒙政权，与日军合作，组织伪蒙古军，实施奴化教育，配合日军经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c88e1260ef2a48f2b64c1a34526b10af','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'在内蒙古地区策划“蒙古自治运动”','在内蒙古地区策划“蒙古自治运动”，投靠日本关东军，建立伪蒙政权，配合日军统治和掠夺内蒙古资源，组织伪蒙古军协助日军作战。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a802f674cf9474ea461cb619338ff21','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'内蒙古王公','内蒙古王公，积极策划内蒙古独立，投靠日本，建立伪蒙疆政权，配合日军统治绥远、察哈尔等地，推行奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9399556b63146418938555741196eb7','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，1936年在日军扶植下成立伪蒙古军政府，后任伪蒙疆政权首脑，在呼和浩特、托克托地区推行日伪统治，协助日军清乡、征粮、抓捕抗日人士。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74ae6fb61ae54250b4df5960f14f0e2e','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，在日本扶持下建立伪蒙政权，首府设于归绥（今呼和浩特），在新城地区推行奴化教育，为日军提供兵员和物资，协助日军统治绥远。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52ba275cb2dd461aa5434aa65177e1cf','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，在日本扶植下建立伪蒙政权，其势力范围涵盖呼和浩特、清水河等地，推行奴化教育，为日军提供兵员和物资，协助日军清剿抗日武装。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b50b1427c694939b06504e68cf075b8','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'内蒙古王公贵族','内蒙古王公贵族，全面投靠日本，在呼和浩特（归绥）建立伪蒙疆政权，推行奴化教育，配合日军“治安强化”运动，迫害抗日军民，其伪政府机构曾驻于旧城（今玉泉区一带）。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff775aab950c40a6b26958e7f29df053','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'内蒙古王公贵族','内蒙古王公贵族，积极投靠日本，在呼和浩特（归绥）及周边地区建立伪政权，配合日军“以蒙治蒙”策略，组织伪蒙古军，协助日军清剿抗日武装，推行奴化教育。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7080ffd7056471cab33dc81f35ce05c','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，积极投靠日本，建立伪蒙政权，其势力范围涵盖绥西地区，支持日军在临河等地设立伪警察署和保甲制度，镇压抗日活动，强征粮草。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b89811cbd1147208ff09cf27cea1640','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古族王公','蒙古族王公，投靠日本后建立伪蒙政权，其行政管辖名义上包括五原地区，支持日军在绥西的军事行动，并推行奴化教育。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae3965fc902e4cf1bc589dc622734bd7','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，积极投靠日本，策划内蒙古独立，建立伪蒙政权，其势力范围包括巴彦淖尔地区，支持日军对绥西的军事行动，推行奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a89b4d5af5394720b4a57b2ad7c2a566','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，与日军合作，在内蒙古地区建立伪政权，其势力范围涉及通辽一带，推行奴化教育，配合日军经济掠夺和军事统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36486cfe3d6d4c879e604ff52d160dd4','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'在鄂尔多斯及内蒙古西部策划“蒙古独立”','在鄂尔多斯及内蒙古西部策划“蒙古独立”，投靠日本关东军，建立伪蒙政权，配合日军对伊克昭盟（今鄂尔多斯）进行殖民统治和军事镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b74e1235b0f84d3f9c58963bd4d5da5d','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，1936年成立伪蒙古军政府，1939年任伪蒙疆联合自治政府主席，控制张家口及察哈尔地区，为日本殖民统治服务。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f21315d419d4b94babd5d56d53f28ae','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，策划内蒙古独立，1936年投日，建立伪蒙古军政府，后任伪蒙疆联合自治政府主席，管辖张家口、张北等地，推行日伪殖民政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fccd53c2715b44008a81a4b714d5cc6c','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'察哈尔部蒙古王公','察哈尔部蒙古王公，1933年策动“内蒙古自治运动”，后与日军合作，在张家口成立伪蒙疆政权，统治察北地区，配合日军“治安肃正”和物资掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86c6132e5d5144539d4dfa15ac0fb136','ac999d87-46c8-4672-9ce9-4747cc633dff',1933,'蒙古王公','蒙古王公，投靠日本，在张家口成立伪蒙疆政权，其势力范围包括赤城地区，推行奴化政策，协助日军镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c43dc3fb1b2e4b9f82d373dc64b8f9e1','1c899859-ab27-4100-a190-e79027cc1be5',1936,'参与策划伪蒙古军西进','参与策划伪蒙古军西进，在乌兰察布地区组织伪警察和保安队，镇压当地抗日游击队，强制推行“蒙疆”币和日伪法令。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1b6369956374f5eb216e0174e367a0a','1c899859-ab27-4100-a190-e79027cc1be5',1936,'参与伪蒙疆政权建设','参与伪蒙疆政权建设，在丰镇、乌兰察布等地组织伪行政机构，配合日军“治安强化”运动，迫害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9889ed692e146d593ea1b69ced95828','1c899859-ab27-4100-a190-e79027cc1be5',1936,'参与伪蒙疆政权高层决策','参与伪蒙疆政权高层决策，在包头地区组织伪行政机构，协助日军清乡、征粮，迫害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-787cf72055fd433b8b511d4a2bc63ce9','47eda31a-94c7-4b6c-8ef2-d7df08ef88ef',1937,'率伪蒙古军驻扎乌兰察布南部（今卓资县、凉城县一带）','率伪蒙古军驻扎乌兰察布南部（今卓资县、凉城县一带），配合日军进攻大青山抗日根据地，多次参与“清乡”行动，杀害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f918da46afce4576879f043c39e7b4f0','47eda31a-94c7-4b6c-8ef2-d7df08ef88ef',1937,'率伪蒙古军在乌兰察布、丰镇一带驻防','率伪蒙古军在乌兰察布、丰镇一带驻防，多次参与对八路军和游击队的“围剿”，烧杀抢掠，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e2c11b77c3f4f1f8ee0497a26173642','47eda31a-94c7-4b6c-8ef2-d7df08ef88ef',1937,'率伪蒙古军在乌兰察布、商都地区驻防','率伪蒙古军在乌兰察布、商都地区驻防，参与围剿八路军大青山支队，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb493a2a72ff4ce18966e9c043e81d71','47eda31a-94c7-4b6c-8ef2-d7df08ef88ef',1937,'率伪蒙古军驻扎包头、九原地区','率伪蒙古军驻扎包头、九原地区，配合日军扫荡抗日游击队，多次参与围剿大青山抗日根据地，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cd19f5bd91b4b6eb92076a22b5ab77e','47eda31a-94c7-4b6c-8ef2-d7df08ef88ef',1937,'率伪蒙古军驻扎包头地区','率伪蒙古军驻扎包头地区，配合日军清乡、征粮，捕杀抗日地下工作者，参与“治安强化运动”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a38ee5f0e6d4a16a22ff56acd176771','47eda31a-94c7-4b6c-8ef2-d7df08ef88ef',1937,'率伪蒙古军驻防绥远地区','率伪蒙古军驻防绥远地区，多次参与“扫荡”大青山抗日根据地，在呼和浩特回民区强征壮丁，迫害抗日家属。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec0fdc8334654153afa3c9849db9b29f','1f208d65-975c-4737-97e1-ac74a1ab0f7a',1937,'在乌兰察布东部（今商都县、化德县）驻防','在乌兰察布东部（今商都县、化德县）驻防，协助日军封锁交通线，抓捕抗日地下工作者，向日军提供情报。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd0d2454f3674b828abe2c004575bfc6','5e77aea2-bc75-4901-a3e7-4901dae537c7',1937,'活动于乌兰察布北部（今四子王旗、达茂旗）','活动于乌兰察布北部（今四子王旗、达茂旗），参与围剿八路军大青山支队，强征牧民马匹和粮食，迫害抗日家属。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c4a3f010c7941a891c08feb772a2c8e','88587535-9c21-41d5-8164-bbd7a4189fad',1937,'在乌兰察布中西部（今察右中旗、察右后旗）推行保甲制度','在乌兰察布中西部（今察右中旗、察右后旗）推行保甲制度，组织“自卫团”，协助日军破坏地下抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93172efceced4e4eb4cb4fdcbfdbd9b9','88587535-9c21-41d5-8164-bbd7a4189fad',1937,'投日后在呼和浩特周边活动','投日后在呼和浩特周边活动，协助日军建立伪政权，参与抓捕和杀害抗日志士，强征粮食。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f6fb9f14a1164f6d9176a4dd8d883b0d','e0f56a56-408e-4dd7-83a3-621f911cbbf3',1939,'负责在乌兰察布地区推行奴化教育','负责在乌兰察布地区推行奴化教育，强令学校使用日语和蒙奸教材，煽动民族分裂，为日军征兵征粮。','危害等级B（乙级，机构委员长(非国家首脑)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b35f6303a714bc8a5a9f248ae1c5abd','63855ed2-4726-4041-8b07-8640c2c94b56',1933,'蒙古王公','蒙古王公，长期与日本关东军勾结，在乌兰察布地区推行“蒙古自治”，建立伪政权，为日军提供兵员和情报，协助统治当地。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de72563fa8044985a3cc9e16fe41b35c','63855ed2-4726-4041-8b07-8640c2c94b56',1933,'蒙古王公','蒙古王公，策划内蒙古独立，与日本关东军合作，在包头及周边推行伪蒙疆政权，为日军提供兵员和情报，协助统治占领区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e3e1929ad1243db81e52525f54ade01','63855ed2-4726-4041-8b07-8640c2c94b56',1933,'锡林郭勒盟苏尼特右旗札萨克郡王','锡林郭勒盟苏尼特右旗札萨克郡王，抗战期间与日军合作，建立伪蒙疆政权，其统治范围包括绥远西部（含巴彦淖尔地区），推行伪蒙疆自治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af40a2b0ac5545f3866000577b146afe','63855ed2-4726-4041-8b07-8640c2c94b56',1933,'在日本扶持下建立伪蒙政权','在日本扶持下建立伪蒙政权，其势力范围延伸至宁夏北部和贺兰山地区，配合日军对宁夏进行政治渗透和军事骚扰。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af13bf414a744e4d8fc3cd6f557cecdc','63855ed2-4726-4041-8b07-8640c2c94b56',1933,'蒙古王公','蒙古王公，在日军扶植下于张家口成立伪蒙古军政府及伪蒙疆联合委员会，推行奴化教育，协助日军掠夺资源，是蒙疆地区最高傀儡首领。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff5cf181a40b496fa8e5bdcd3a9fe3df','63855ed2-4726-4041-8b07-8640c2c94b56',1933,'蒙古王公','蒙古王公，在张家口成立伪蒙疆政权，与日军合作，推行殖民统治，为日军提供兵员和物资，镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-179acbbaf2d14eb8869c4b6ba4d543da','4738d82d-3911-4f3a-88fc-6021668bef19',1938,'任伪丰镇县长期间','任伪丰镇县长期间，推行日伪苛政，强征粮税，抓捕抗日志士，协助日军建立保甲制度，镇压当地反抗。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc5ee7aa4aa94544a52af409edb81485','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'原土匪出身','原土匪出身，投日后在乌兰察布、丰镇一带活动，率伪军配合日军进攻大青山抗日根据地，劫掠民众，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-734e20187628453c817c06699566e622','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'原土匪出身','原土匪出身，投日后任伪绥西联军司令，活动于乌兰察布南部及商都一带，配合日军袭击抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6cc017df42e34640a5ff5a356b3ce7f2','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'在乌兰察布及四子王旗地区为日军效力','在乌兰察布及四子王旗地区为日军效力，参与围剿抗日游击队，残害百姓，充当日军帮凶。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-542b5c6ecb7943a5b38db088487f0a56','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'在察哈尔右翼后旗及绥东地区为日军效力','在察哈尔右翼后旗及绥东地区为日军效力，组织伪军袭扰抗日武装，参与日军“清乡”行动，掠夺民间财物','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25047a51ca5a4f81aa8b79c6ca2721b8','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'伪军头目','伪军头目，虽主要活动于绥西，但其伪军系统与伪兴安地区伪军有协同，间接涉及内蒙古东部，包括兴安、科尔沁右翼前旗一带的治安作战。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c3b74dd34dd4c8ebe6a6bdc3a3d497a','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'在内蒙古西部及呼伦贝尔南部活动','在内蒙古西部及呼伦贝尔南部活动，率伪军配合日军进攻抗日武装，残害百姓','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d5b6b7bac344fe58c86b575c8db3f8e','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'在内蒙古西部投靠日军','在内蒙古西部投靠日军，组织伪军，虽主要活动于绥远，但属于内蒙古范围内有记载的汉奸。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c11549fdd984eaca2b11e1f2f45ce79','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'原为绥远地方军阀','原为绥远地方军阀，投日后任伪绥西联军司令，在呼和浩特西部及回民聚居区设卡收税，配合日军清乡，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0f17e3e239a4432b6ee4e55a320ca83','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'绥远人','绥远人，组织伪军配合日军在绥远、山西北部等地活动，参与日军对晋绥抗日根据地的进攻。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e532289d851144ff819410d1bbaca9f8','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'率伪军活动于晋北、绥远交界包括右玉附近','率伪军活动于晋北、绥远交界包括右玉附近，协助日军进攻抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d219924db0954a2591db2e1ee0a47a5a','1b7f99cb-00ab-46f2-9b82-9fde5e142cce',1930,'在绥远、陕西北部一带组织伪军','在绥远、陕西北部一带组织伪军，配合日军侵扰陕西边境。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cc87838006b474098a21568bdb335b2','95666ddb-504a-42e9-9761-81c0fa066a8f',1937,'原国民党将领','原国民党将领，投敌后在乌兰察布地区组织伪军，参与对抗日武装的“讨伐”，后因内部矛盾被日军处决。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b47761291144f97ab2ec3d01e7837ef','95666ddb-504a-42e9-9761-81c0fa066a8f',1937,'投日后任伪东亚同盟军总司令','投日后任伪东亚同盟军总司令，在内蒙古西部及绥远地区配合日军作战，围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
