INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c36f9243eaf04c9bb6d8563e705a1723','95666ddb-504a-42e9-9761-81c0fa066a8f',1937,'在华北、西北地区组织伪军','在华北、西北地区组织伪军，协助日军作战。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a24fa858327047e0b0269333d2d26c43','95666ddb-504a-42e9-9761-81c0fa066a8f',1937,'投靠日本','投靠日本，在华北及陕西周边地区组建伪军配合日军行动。','危害等级C（丙级，基层头目）','hanjian');
