INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f67d375969c14afc922c7f300944595a','42af078c-2b55-4597-b630-387d454165fb',1939,'投靠日伪','投靠日伪，任伪盟长期间，推行奴化教育，组织伪警察镇压抗日活动，为日军提供物资和劳役。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8adff28ff5e46e2af1608c5817e6495','9d37904a-918f-4a55-a895-f18f97b2a6bf',1939,'原晋军将领','原晋军将领，被俘后变节，在乌兰察布地区协助日伪收编散兵，参与“清乡”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
