INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f18bea625c74aa99510b13addf650dd','ddf5cc5b-8856-403a-b472-9cf946eb5d28',1938,'原东北军将领','原东北军将领，后投靠日军，在绥东（含兴和、乌兰察布）一带协助日军围剿八路军游击队，参与“治安肃正”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee6b703d5af546628f9f7d44b6c71b6a','b5565cd7-855c-457a-b7f6-5fe7a5d67d35',1936,'蒙古族上层','蒙古族上层，投靠德王和日军，率伪蒙古军在乌兰察布北部及兴和地区驻防，协助日军镇压抗日民众，征收粮草。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee46d299f34b48c7ab3322f8c1c508d0','ae7ea99f-e9cf-4811-92c5-f6d03f2e81e1',1937,'伪蒙古军高级军官','伪蒙古军高级军官，活动于绥远东部（含兴和、商都、化德一带），配合日军进攻大青山抗日游击队，参与“清乡”屠杀。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e006eea49f346af96125d0f066eb989','0e610c47-00a0-48fe-a122-bf39d3afbccd',1938,'伪蒙古军将领','伪蒙古军将领，在乌兰察布地区驻防，协助日军维持殖民秩序，抓捕抗日地下工作者，参与经济掠夺。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9b176eff6bc4abc99e96b23c5867908','5bdd967c-102d-4336-9bac-b8b708342688',1939,'伪蒙古军高级指挥官','伪蒙古军高级指挥官，活动于乌兰察布南部及兴和一带，多次率部袭击八路军大青山支队，破坏抗日政权。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b07abd401114b0d8e769b9faefef7c8','37513079-5f7d-40df-b2f0-fc9ab7d44d64',1939,'伪蒙古军将领','伪蒙古军将领，在乌兰察布、兴和地区参与“扫荡”，强征民夫修筑公路和碉堡，配合日军推行“保甲制”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af17189633df4a12a03c353b26cd41fd','f19afed0-c6a2-4d87-9dce-295475a5d092',1939,'在兴和县任伪县长期间','在兴和县任伪县长期间，为日军征粮派款，组织伪警察镇压抗日群众，协助日军建立情报网。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54e6987d2c2a4264a7e4dfb281e42f35','820ad2db-242f-4cf6-a864-2824cd8e51c3',1940,'原国民党军官','原国民党军官，1940年投日，在乌兰察布东部（兴和、丰镇）组织伪保安队，配合日军“蚕食”抗日根据地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88712b49ca7d4b12b68526cd20b03d7d','c76d7e91-fb82-4007-8fa5-30bd1ee824c0',1941,'在兴和县任伪警察署长','在兴和县任伪警察署长，抓捕抗日军民，严刑逼供，直接参与多起屠杀事件。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6656c994ce534e56aff2046cb6959de5','09015afb-9d9c-42d4-b05d-a36b249dfa0a',1940,'在乌兰察布盟伪政权中负责“宣抚”工作','在乌兰察布盟伪政权中负责“宣抚”工作，为日军宣传“大东亚共荣”，协助推行奴化教育。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f74bdc950d641529a8ffe15b537776d','2de15d70-a857-42b0-9fc1-bd2e85f23cc2',1939,'原晋军将领','原晋军将领，投日后任伪职，参与对乌兰察布、兴和地区的军事“讨伐”和物资掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3099ac4df0b452485164e1e7889489e','2e47c880-c7a3-413c-9efc-d09f1674ffae',1941,'率伪蒙古军第6师驻防兴和、尚义一带','率伪蒙古军第6师驻防兴和、尚义一带，多次袭击八路军游击队，杀害抗日干部和群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11aa08fc5ab5494d930d4080842444cf','6241793f-b05b-4f26-a373-f421b5f9c368',1939,'作为伪蒙疆高层','作为伪蒙疆高层，参与制定对乌兰察布、兴和地区的“治安强化”政策，支持日军“三光”作战。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8faf05c1c24740d8b92c72816b59ec44','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原为热河土匪','原为热河土匪，后投靠日军，任伪蒙古军总司令，参与侵占绥东（含凉城）地区，协助日军镇压抗日力量，推行殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-768b19dc0c8547e4bcda55c750bd142e','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原为热河土匪','原为热河土匪，后投靠日军，任伪蒙古军总司令，在商都、乌兰察布一带配合日军扫荡抗日武装，镇压蒙汉民众，参与建立伪蒙政权。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b47bf9abe714e3caee2b8c245901a15','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原为东北军军官','原为东北军军官，后投靠日军，在内蒙古东部及包头、石拐地区协助日军建立伪蒙古军，参与镇压抗日力量，推行殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cff8dce41154973834364b01d1ba368','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原东北军将领','原东北军将领，叛国投日后任伪蒙古军总司令，率伪军在察哈尔、绥远及呼伦贝尔周边地区配合日军进攻抗日武装，镇压蒙汉民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4b281651cf84de7bd7029e543881385','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原东北军将领','原东北军将领，投靠日本后组建伪蒙古军，在绥远（今呼和浩特）及新城地区协助日军镇压抗日力量，参与“治安肃正”行动，残害当地民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0db4c3c2b4234646a5b6e4dafda9c919','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原为东北军军官','原为东北军军官，后投靠日本关东军，在内蒙古东部及呼和浩特、清水河一带组织伪蒙古军，协助日军镇压抗日力量，参与“治安肃正”行动，残害当地民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e45df3c762a54f44941f49da01e699f7','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原东北军军官','原东北军军官，后投靠日本关东军，组建伪蒙古军，参与侵占察哈尔、绥远（今呼和浩特地区），协助日军镇压抗日力量，并在玉泉区（旧归化城）设立伪政权机构。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-309a041722ba4ed083be787ce0f8e30c','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原为东北军军官','原为东北军军官，后投靠日本关东军，在内蒙古东部及呼和浩特、赛罕地区协助日军建立伪蒙古军，参与镇压抗日力量，推行“蒙疆自治”政策，为日军提供兵员和情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e806b7cdd8f47fa9d67c49def6afa51','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原为东北军军官','原为东北军军官，后投靠日本关东军，参与组建伪蒙古军，多次率部进犯绥西地区，协助日军镇压抗日力量，是蒙奸头目之一。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d31d3f6ab3b49e694fc70dd1ae0ebd3','0285cce9-c42f-4e31-a4fe-89b6d4d73242',1933,'原热河省军阀','原热河省军阀，1933年投日，在赤峰、宁城一带协助日军镇压抗日武装，组建伪蒙古军，参与对热河地区的殖民统治和“清乡”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37beae8d360a4a66a925554e36a7a232','e3ef6027-79f7-47e4-9ddd-48556b706bba',1936,'参与伪蒙政权决策','参与伪蒙政权决策，协助日军在乌兰察布、凉城等地推行保甲制度，组织伪警察镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24d2139bc3cc404db888e20127dc9f54','e5ff5c0f-cc57-42c6-a27a-0ac2874f5fcb',1937,'绥远土匪出身','绥远土匪出身，投日后率伪军多次进犯凉城、蛮汉山一带，配合日军扫荡八路军大青山支队，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3433ce4782184393a7a3200bdef7cc6d','bf42ff0a-26ec-4ecc-90a9-2b0275ecfc7b',1938,'任伪凉城县长期间','任伪凉城县长期间，为日军征粮派款，组织伪警察抓捕抗日地下人员，破坏中共凉城抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0038d9e1d6c1454fb6fb9e70ef03d685','bf01890a-c5ea-4269-8797-c228c701710e',1939,'原晋绥军将领','原晋绥军将领，一度与日军合作，其部队活动于绥南（含凉城），参与对八路军游击区的“围剿”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf8bda0c127f4364baf88690f929cac3','ca9031dd-e33e-4e3a-ab17-efed00777246',1938,'原东北军将领','原东北军将领，投日后在绥东、凉城一带收编土匪，配合日军进攻大青山抗日游击根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a3dfb36e2d04a68a2a6e295573cdbff','d2481207-717b-4469-b44c-ba518845d2c7',1940,'率伪保安队多次袭击凉城乡村抗日政权','率伪保安队多次袭击凉城乡村抗日政权，杀害抗日干部和群众，抢夺物资。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-485a80d4b39f45c4a4b03e5dec5ef0f2','bbbbc9a4-d01a-4770-9619-7eff23d582c3',1937,'率伪蒙古军驻防乌兰察布南部','率伪蒙古军驻防乌兰察布南部，参与对凉城、卓资山等地抗日武装的“清剿”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d182abf8680f47e18ace14a4a2698d12','5de24fcb-9b8e-4c23-b953-e7c0cf3adeee',1938,'原国民党军官','原国民党军官，投日后在凉城、和林格尔一带组织伪军，协助日军建立据点，破坏抗日交通线。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a7ad94bc1fe4fa0a2501a2d91ac1502','987159c2-f28c-4766-a217-157cc90b914d',1933,'在化德（当时称嘉卜寺）建立伪蒙古军政府','在化德（当时称嘉卜寺）建立伪蒙古军政府，后任蒙疆联合自治政府主席，积极投靠日本，组织伪蒙古军配合日军进攻绥远等地。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de47e0a64a3547e7ae4c97eb01d16275','987159c2-f28c-4766-a217-157cc90b914d',1933,'在四子王旗及乌兰察布地区推行亲日政策','在四子王旗及乌兰察布地区推行亲日政策，组织蒙古军配合日军侵略，建立伪蒙疆政权，分裂中国领土。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ffd3cb3e86e425baf5279dbcc9b3210','987159c2-f28c-4766-a217-157cc90b914d',1933,'在察哈尔右翼后旗及周边地区推行日本殖民政策','在察哈尔右翼后旗及周边地区推行日本殖民政策，组织伪蒙疆政权，协助日军镇压抗日力量，强征劳工和物资','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a39109bd091f4f71a41089a81d9a9e04','987159c2-f28c-4766-a217-157cc90b914d',1933,'在察哈尔、绥远（含今乌兰察布地区）组织蒙古自治运动','在察哈尔、绥远（含今乌兰察布地区）组织蒙古自治运动，投靠日本，建立蒙疆政权，配合日军统治与掠夺资源。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2779dbd230d436fb697e553e1f06f1d','987159c2-f28c-4766-a217-157cc90b914d',1933,'在乌兰浩特及兴安盟地区推行亲日政策','在乌兰浩特及兴安盟地区推行亲日政策，组建蒙疆政权，配合日军统治内蒙古东部地区，镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60fdcdc5a8074871930eb2a3408504bb','987159c2-f28c-4766-a217-157cc90b914d',1933,'在内蒙古地区策划‘蒙古自治运动’','在内蒙古地区策划‘蒙古自治运动’，投靠日本，建立蒙疆政权，配合日军统治内蒙古中西部，包括呼伦贝尔周边地区','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12cddf2dbb8c4ebda790178f05aebbc7','987159c2-f28c-4766-a217-157cc90b914d',1933,'在内蒙古地区策划‘蒙古自治运动’','在内蒙古地区策划‘蒙古自治运动’，投靠日本，建立蒙疆政权，配合日军统治绥远（含今巴彦淖尔地区），推行奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de8a0f8488b54a4195fb673fef1752d4','987159c2-f28c-4766-a217-157cc90b914d',1933,'在锡林郭勒盟（含今二连浩特地区）发起‘蒙古自治运动’','在锡林郭勒盟（含今二连浩特地区）发起‘蒙古自治运动’，后投靠日本，建立蒙疆政权，配合日军统治内蒙古地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
