INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac897803e98743fb8cbfeee1591ba784','b0d9cc4f-5d5f-45b6-86a5-fc4afabaf829',1936,'率伪蒙古军驻防绥西地区','率伪蒙古军驻防绥西地区，多次配合日军扫荡包头、固阳、白云鄂博周边抗日游击队，掠夺牲畜和矿产。','危害等级B（乙级，市县厅局级）','hanjian');
