INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5729bb3f36747d98d303caad5ba8bdc','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古族王公','蒙古族王公，组织伪蒙疆政权，与日军合作，在乌兰察布、卓资一带推行殖民统治，征粮征兵，协助日军清剿抗日武装。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c53ee2aa60ef447dbe5603b49c8d9e69','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，策划内蒙古独立，投靠日本，建立伪蒙疆政权，其势力范围包括乌海周边地区，协助日军统治和殖民掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb311f7b61fe4240bead38df137b2998','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'在内蒙古地区组织伪蒙政权','在内蒙古地区组织伪蒙政权，与日本关东军合作，推行“蒙疆自治”，协助日军统治内蒙古中西部，但未直接管辖兴安、阿尔山地区，主要活动于锡林郭勒、乌兰察布等地。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a784d1c9fcd408fbc3d31398b9f80f7','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，策划内蒙古独立，与日军合作成立伪蒙疆政权，管辖包括包头在内的绥远地区，推行奴化教育，协助日军统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee00473983cf4d0d8641a9413bba802a','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，与日军合作建立伪蒙疆政权，其势力范围覆盖包头、东河地区，推行奴化教育，为日军提供情报和物资支持。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-150de8149969417fa2944394d49216bf','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，与日军合作建立伪蒙疆政权，其势力范围包括包头、固阳等地，推行日伪统治，征粮派款，协助日军清剿抗日游击队。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee166608f04e4cd3966f1b1be3bbe723','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'虽为察哈尔部贵族','虽为察哈尔部贵族，但长期在土默特右旗及包头地区活动，与日军合作，建立伪蒙疆政权，推行“蒙独”分裂活动，为日军提供兵源和情报。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2105b9a633444637acc3cddb66229aca','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，日本扶植的蒙疆政权首脑，其势力范围包括包头、昆都仑地区，推行日伪统治，协助日军镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d38e1bbf7ab4d9099656edac61153f0','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，在日本扶植下成立伪蒙疆政权，管辖包括包头、白云鄂博在内的绥远地区，推行奴化教育，协助日军控制矿产和交通线。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb6aed09188243b098cab412657d6735','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，组织伪蒙疆政权，与日军合作，在内蒙古地区推行殖民统治，其势力范围曾延伸至呼伦贝尔西部边缘，配合日军“治安肃正”。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac2a7341957b404cae854b09e36b49bf','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，在日本扶植下成立伪蒙疆政权，首府驻张家口，但势力范围涵盖呼和浩特及绥远地区，推行亲日政策，协助日军统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85e631afc4d94356b3e4f0bd84ca5050','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，策划内蒙古独立，后投靠日本，建立伪蒙疆政权，在呼和浩特（归绥）设立伪政府机构，推行奴化教育，协助日军掠夺资源。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-317e9ccc88924a598db2c287ef2cbc63','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，与日本合作建立伪蒙疆政权，其势力范围覆盖土默特左旗，推行奴化教育，为日军提供情报和兵源。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6b1b30ce08d43d384ccc3467107688c','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古族贵族','蒙古族贵族，与日本合作建立“蒙疆政权”，其势力范围包括乌拉特前旗一带，推行奴化教育，为日军提供兵员和物资，协助日军控制河套地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-042f07ad55e64ecc90791ee69254944c','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'虽主要活动于锡林郭勒','虽主要活动于锡林郭勒，但其伪蒙疆政权势力延伸至奈曼旗、通辽一带，支持伪军和特务机构在该地区镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa3dab2c28b5427e92aac01709fe3188','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，投日建立伪蒙疆政权，其势力范围涉及河北北部（张家口、承德一带），配合日军控制长城沿线。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de50f1843777440bbe36f8dda04d7193','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古族王公','蒙古族王公，投靠日本，建立伪蒙疆政权，其势力范围包括大同、浑源等晋北地区，协助日军统治和掠夺资源。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa8c138eafe144fc9b3e440cc11b67d6','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'在日本扶植下建立伪蒙疆政权','在日本扶植下建立伪蒙疆政权，管辖包括张家口、下花园在内的察哈尔地区，推行奴化教育，配合日军经济掠夺和军事镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-87f87d0460024f45858abaa83c9402fd','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'领导伪蒙疆政权','领导伪蒙疆政权，管辖张家口、宣化等地，配合日军推行殖民统治，建立伪军和警察机构，迫害抗日民众。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-807687f8d2fd4f86b55fcfe9b4b53ddf','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'在日军扶植下成立伪蒙疆政权','在日军扶植下成立伪蒙疆政权，管辖张家口、崇礼等地，推行奴化教育，配合日军经济掠夺和军事镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79705f51104a4ca99fc85938f659a460','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，与日军合作在张家口成立伪蒙疆政府，管辖包括康保在内的察哈尔地区，推行奴化教育，为日军提供兵员和物资。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63ab350a0fc04784b8fd8d6a84f494c3','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古族王公','蒙古族王公，在日本扶植下成立伪蒙疆政权，总部设于张家口，积极与日军合作，推行奴化教育，为日军提供兵源和物资。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dab7999c34f441e38334ae4695d7eaeb','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，1936年在日军扶植下成立伪蒙古军政府，后任伪蒙疆联合自治政府主席，管辖张家口及怀安地区，推行奴化教育，协助日军掠夺资源，镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbcd20f39e0b4361892237026af00b1b','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，1936年投日，在张家口成立伪蒙疆政府，管辖察哈尔（含怀来）等地，推行奴化教育，为日军提供兵员和物资，镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7fa9126fbddd40288e0c19d94e4ea492','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，在日本扶植下于张家口成立伪蒙疆政府，管辖察哈尔等地，在桥东地区设立伪机构，配合日军经济掠夺和殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb140d7601044c06b44bc81c32e02a44','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，在日本扶植下成立伪蒙疆政权，以张家口为重要活动中心，配合日军统治察哈尔、绥远等地，提供兵员和物资，协助日军清剿抗日武装。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2457e60fcee4b75bed2fba3c8955d1c','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'在张家口建立伪蒙疆政权','在张家口建立伪蒙疆政权，与日军合作，推行奴化教育，为日军提供兵员和物资，是涿鹿地区伪政权的最高象征。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3314f01918a4b08869ee408005baf15','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，在日军扶植下建立伪蒙疆政权，管辖张家口、大同、归绥等地，配合日军推行殖民统治，组织伪军协助日军作战。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4aeda36860254cac9b54ddc36329b58a','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'蒙古王公','蒙古王公，在日军扶植下成立伪蒙疆政权，管辖张家口及周边地区，推行奴化政策，协助日军统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8bb892ae6414c508f1c8dd680350ba9','ddb14421-58ee-4065-b46c-cafe7dd2516b',1933,'与日本合作','与日本合作，其势力曾延伸至河北北部，间接影响秦皇岛地区','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88d9a9b9be8a40f7940ab21233bec28e','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'德王亲信','德王亲信，参与伪蒙疆政府行政事务，在乌兰察布地区推行日伪政策，强征劳工，压迫民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ebbcb3afd8f40459070a81e4a4f3024','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'德王亲信','德王亲信，参与伪蒙疆政权运作，在乌海及鄂尔多斯地区推行日伪政策，征粮派款，协助日军维持治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba69c9a6fd19499882d3f2ac64b7d031','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'曾任伪蒙疆政府高级官员','曾任伪蒙疆政府高级官员，在包头地区协助日军推行殖民政策，管理行政事务，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a1178aca5ec47378f3f82eab0d89b7a','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'德王亲信','德王亲信，参与伪蒙疆政权行政运作，在包头地区推行日伪法令，征派劳役开采白云鄂博铁矿资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-500b96ec2a3044f094a8f33126632dcb','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'参与伪蒙疆政权高层决策','参与伪蒙疆政权高层决策，在呼和浩特地区推行奴化教育和经济掠夺，协助日军维持殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6f8fb157a024360b33be543475da80c','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'曾任伪蒙疆联合自治政府政务院长','曾任伪蒙疆联合自治政府政务院长，在呼和浩特地区推行日伪法令，组织保甲制度，镇压抗日活动，协助日军征粮征兵。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94bd289cb7664513bb68816ec8a7be27','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'参与德王伪政权','参与德王伪政权，负责行政事务，在锡林郭勒盟推行日本殖民政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f131cb0eb7714dcda4406705a0b0f1c4','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'原国民党蒙藏委员会官员','原国民党蒙藏委员会官员，投日后任伪蒙疆政府政务院院长，推行日伪法令，协助日本对内蒙古西部进行殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d248cdbc6c0430b8db1d6c7757eba2e','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'长期在张家口担任伪蒙疆政府高级职务','长期在张家口担任伪蒙疆政府高级职务，负责行政事务，配合日军实施治安强化运动，迫害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69e2c8b819f74c3ba8a8bb2729bc5a3b','54eab1a4-c653-40e8-bf42-33c6141a7691',1937,'协助德王管理伪蒙疆政权','协助德王管理伪蒙疆政权，在张家口地区实施日伪法令，强征劳工，配合日军“扫荡”抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93861366db814b68bfa72f284c4938b1','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'绥远土匪出身','绥远土匪出身，投日后任伪绥西自治联军总司令，活动于绥远中东部（含卓资、乌兰察布），多次配合日军进攻抗日根据地，残害百姓。','危害等级C（丙级，基层头目）','hanjian；traitors');
