INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c356fc493404942ae7bf63d8ee8fd6c','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原土匪出身','原土匪出身，投日后在包头、五原一带组建伪军，多次配合日军进攻傅作义部抗日军队，残害百姓。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b04ddc8473f4a899c5020d22d6c1679','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原土匪武装头目','原土匪武装头目，投日后在包头、九原一带组建伪军，配合日军进攻绥西抗日力量，劫掠百姓，曾参与围攻大青山支队。','危害等级C（丙级，基层头目）','hanjian；traitors');
