INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8645b597cfcf4da08158653549033a64','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原土匪出身','原土匪出身，投日后在包头以西地区组建伪军，多次袭击抗日武装，为日军勘探白云鄂博矿提供情报和护卫。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4e6a60f7e9440c3baf6ed8dffdeba2d','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原为土匪头目','原为土匪头目，后投靠日军，在包头、石拐及绥西地区组织伪军，协助日军扫荡抗日根据地，残害百姓。','危害等级C（丙级，基层头目）','hanjian；traitors');
