INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b57036a337224fee909d299859ee0d27','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'在绥远（含今呼伦贝尔部分相关区域）组织伪军','在绥远（含今呼伦贝尔部分相关区域）组织伪军，充当日军“以华制华”工具，多次进犯抗日根据地，劫掠百姓。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8eda6f266d44628ace3400fd6f57e70','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原土匪出身','原土匪出身，投日后在绥远西部组织伪军，进攻大青山抗日根据地，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46c653cda6b54dbaadd679adddbe45f9','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原土匪出身','原土匪出身，抗战期间投靠日军，在托克托、呼和浩特一带组织伪军，多次配合日军扫荡大青山抗日根据地，残害百姓，抢劫物资。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-270005ef640146978e8c1229208e30b8','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原土匪出身','原土匪出身，投日后在绥远（含新城）地区活动，率伪军配合日军进攻大青山抗日根据地，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-298045e676324f3c84f6bdff1ad7acd9','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原土匪头目','原土匪头目，投日后在绥远（含武川）一带活动，率伪军袭击八路军大青山支队，残害地方干部，后因内部矛盾被日军弃用。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-491663f1b4484c93b136127d74dc9208','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原为土匪武装头目','原为土匪武装头目，后投靠日军，在清水河、托克托及呼和浩特南部地区活动，配合日军进攻八路军大青山抗日根据地，烧杀抢掠，破坏抗日组织。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-267c74e09ce647b8a8aca7ac6a57e5b0','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原绥远地方土匪武装头目','原绥远地方土匪武装头目，投日后编为伪军，活动于归绥（今呼和浩特）及绥西地区，多次进攻抗日游击队，在玉泉区周边村庄烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20be587e0813450693d71d0c84374ff8','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原为土匪武装头目','原为土匪武装头目，投日后在呼和浩特、赛罕地区活动，协助日军控制交通线，袭击抗日武装，掠夺民间财物，充当日军“以华制华”工具。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d30e1ef7bbce4dd699dcc4a87655ef54','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'在乌拉特中旗及河套地区为日军效力','在乌拉特中旗及河套地区为日军效力，组织伪军袭扰抗日部队，破坏中共地下组织，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-704936a1ca83420eab8bb91cb5af458a','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'在绥西（含巴彦淖尔地区）组织伪军','在绥西（含巴彦淖尔地区）组织伪军，配合日军进攻河套抗日根据地，劫掠百姓，破坏抗战。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8a3f8018238465995d10a3694b6e12c','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'在绥西地区组织伪军','在绥西地区组织伪军，活动于包头、五原、临河及鄂尔多斯北部一带，配合日军扫荡抗日根据地，残害百姓。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79507fa6acfb4e348e30d0a4aac48257','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'率伪军多次进犯平鲁、朔县一带','率伪军多次进犯平鲁、朔县一带，配合日军“治安肃正”，抓捕抗日干部。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1665c113a838491daca15b0f91562acb','47d70c2e-1788-4fc9-84ac-422ef9dd4e0b',1937,'原为土匪出身','原为土匪出身，后投日，在晋北（含朔州、怀仁地区）配合日军扫荡，劫掠百姓，袭击八路军游击队，为日军提供情报。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75ae5990f5bf4dc882e67947b4e4f6ce','0a424830-ac5d-4775-b090-d6a9facd4743',1938,'原为地方民团头目','原为地方民团头目，投日后任伪绥东保安队队长，在卓资、旗下营一带为日军搜集情报，抓捕抗日人员，欺压乡民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4bd19c6147984a7e8895e4cc3587bb64','9f73e10b-5ff2-4ccc-8535-391f65edfb11',1939,'日军占领卓资后出任维持会长','日军占领卓资后出任维持会长，为日军征粮派款，组织伪保甲制度，协助日军“扫荡”周边村庄。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-589fd23f08f3493c9cdeeab72a353e31','96d4dff2-6bfc-48c7-9f90-44b91ad57e35',1940,'投靠日伪','投靠日伪，任乌兰察布盟警察署长，参与镇压抗日活动，逮捕并杀害多名抗日志士，强征民夫修筑工事。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6f9c732769646e699ad6927b53a9d19','c0a7d838-8b4d-42da-b375-578acc377217',1937,'原为国民党地方官员','原为国民党地方官员，投日后任伪绥东宣抚使，在卓资、集宁一带进行亲日宣传，瓦解民众抗日意志，协助日军建立伪政权。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4cc5a3365e5e4d9fbe9f3a8a74e24a0e','747767b0-e5cd-492c-bb96-297c5f14111d',1938,'率伪蒙古军驻防乌兰察布南部','率伪蒙古军驻防乌兰察布南部，多次参与对八路军大青山支队的围剿，在卓资地区烧杀抢掠。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89d523ed6cbf4c9aad5d657f403bc042','85bad661-a01a-4983-9d03-3581d46a46ed',1937,'在乌兰察布、卓资一带驻防','在乌兰察布、卓资一带驻防，配合日军“铁壁合围”战术，袭击抗日游击队，强征马匹和粮食。','危害等级B（乙级，市县厅局级）','hanjian');
