INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86a6c93c6c6045f9ac7c18aff7c5153c','e8b49238-2910-4343-984a-da18ab712fdd',1936,'率伪蒙古军部队在绥西及鄂尔多斯北部活动','率伪蒙古军部队在绥西及鄂尔多斯北部活动，配合日军进攻抗日根据地，执行烧杀抢掠。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c75024150c7b4bc08d789affc2803102','e8b49238-2910-4343-984a-da18ab712fdd',1936,'在张家口塞北地区驻防','在张家口塞北地区驻防，参与日军“治安肃正”行动，围剿抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fb49c49b95e4689917670661075240d','4fb821eb-c8aa-48ab-a46a-3188d848aaa8',1937,'投靠日伪政权','投靠日伪政权，在旗内推行奴化教育，强迫牧民献粮献畜，协助日军维持殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1823eb310d134d9198861cfb41d40cd3','9065be41-47aa-48b3-bfc0-69da014b2cda',1939,'参与伪蒙疆政权活动','参与伪蒙疆政权活动，在乌兰察布地区为日军搜集情报，破坏抗日地下组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-412fbba8b4bb4f05af05f65639396a01','3da92dd2-567c-4ba9-acbb-1ba670a8deb0',1940,'在四子王旗边境地区袭击抗日武装','在四子王旗边境地区袭击抗日武装，杀害抗日军民，抢劫牲畜和财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6183d0ffe8e4edd9e29814b61f730b9','070c093f-6365-40b8-889f-f1194e2f13a4',1933,'热河阜新人','热河阜新人，早年为土匪，后投靠日军。1933年任伪察哈尔盟盟长，1936年任伪蒙古军总司令，率部配合日军进攻绥远、察哈尔等地，其势力范围覆盖乌兰察布及察哈尔右翼各旗。1945年抗战胜利后被俘。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c2ba4426c414ed9943877481da29b17','0836ecbf-ff20-4514-99d3-bd1ff3a9f331',1936,'锡林郭勒盟苏尼特右旗人','锡林郭勒盟苏尼特右旗人，蒙古王公。1936年成立伪蒙古军政府，1937年任伪蒙古联盟自治政府主席，1939年任伪蒙疆联合自治政府主席，统治范围包括乌兰察布盟、察哈尔盟等地，察哈尔右翼中旗在其伪政权管辖之下。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbf62c0214a048a7992d9ef7ac91c542','4af0dcaa-374b-42e9-a928-595c29ecab0d',1937,'察哈尔部蒙古贵族','察哈尔部蒙古贵族，曾任伪蒙古联盟自治政府最高法院院长，后任伪蒙疆联合自治政府参议，参与伪蒙疆政权对察哈尔右翼各旗的统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e7b2c84a77747b38f505ef83d5950a3','d6418b6e-37c8-497b-b9af-d0a99f25b3d9',1936,'察哈尔蒙古贵族','察哈尔蒙古贵族，1936年任伪察哈尔盟盟长，管辖察哈尔右翼正黄、正红、镶红、镶蓝等旗，包括察哈尔右翼中旗地区，积极推行日军殖民统治政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17fa2db52819472e8ae43312d065399b','d6418b6e-37c8-497b-b9af-d0a99f25b3d9',1936,'原察哈尔部上层','原察哈尔部上层，投靠日军后任伪察哈尔盟盟长，管辖区域与锡林郭勒盟南部接壤，配合日军推行伪政，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc852f5127f64f6db58e39a97a4ddf4a','d6418b6e-37c8-497b-b9af-d0a99f25b3d9',1936,'在察哈尔盟及锡林郭勒盟南部地区为日军效力','在察哈尔盟及锡林郭勒盟南部地区为日军效力，管理伪政权事务，其辖区与太仆寺旗相邻。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1c53ada24f34fd68f6a31d9a2c8a8a1','142020e1-776e-4003-9d08-3a78319ff302',1937,'绥远人','绥远人，早年投靠日军，1937年后任伪绥西联军总司令，配合日军进攻绥远、乌兰察布等地，在察哈尔右翼地区亦有活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4e8a091bf3e44a79c8106455c133751','142020e1-776e-4003-9d08-3a78319ff302',1937,'绥远省五原人','绥远省五原人，早年即为地方武装头目，抗战爆发后投靠日军，任伪绥西联军总司令，率部在绥远西部、包头、呼和浩特一带配合日军作战，袭击抗日武装，残害民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27303c8ec66a4acc80c3c15980e1c85d','142020e1-776e-4003-9d08-3a78319ff302',1937,'原为绥远地方武装头目','原为绥远地方武装头目，抗战爆发后投靠日军，组织伪军配合日军进攻绥远、察哈尔等地，其部曾在昭乌达盟、赤峰一带参与对抗日武装的扫荡和治安强化运动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9cc57f446064499fbbe62785f87a7df2','142020e1-776e-4003-9d08-3a78319ff302',1937,'绥远地区著名汉奸','绥远地区著名汉奸，组织伪军配合日军进攻绥西，在包头、五原、东胜及鄂尔多斯北部一带活动，参与维持会与伪政权建设，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bead9a7acecf4e0fac3b75f9f0189f9f','142020e1-776e-4003-9d08-3a78319ff302',1937,'绥远地区著名汉奸','绥远地区著名汉奸，投靠日军后组织伪军，活动于绥西、鄂尔多斯北部及杭锦旗沿河一带，配合日军进攻抗日根据地，残害民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-054fe655c6c044c7a986b1d449f84d81','142020e1-776e-4003-9d08-3a78319ff302',1937,'绥远地区著名汉奸','绥远地区著名汉奸，投靠日军后组织伪军，在绥西、鄂尔多斯北部一带配合日军作战，残害抗日军民，掠夺地方资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b837a8e504f43c3bce9bf01030cd8fb','142020e1-776e-4003-9d08-3a78319ff302',1937,'率伪军配合日军进攻绥西和宁夏北部','率伪军配合日军进攻绥西和宁夏北部，在石嘴山、磴口一带活动，组织维持会，征粮抓丁，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43ce25c9b0b94a89b4e1c59375bf8a95','142020e1-776e-4003-9d08-3a78319ff302',1937,'率伪军配合日军进攻绥西和宁夏北部','率伪军配合日军进攻绥西和宁夏北部，在磴口、石嘴山、贺兰山一带活动，烧杀抢掠，协助日军推行治安强化运动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f46fad6e02aa498cb6ed18527f318ee6','142020e1-776e-4003-9d08-3a78319ff302',1937,'率伪军在晋西北吕梁地区配合日军作战','率伪军在晋西北吕梁地区配合日军作战，参与对抗日根据地的扫荡和掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1df79b4d3522427890d3466eab3122a4','142020e1-776e-4003-9d08-3a78319ff302',1937,'绥远地方武装头目','绥远地方武装头目，投敌后任伪绥西联军总司令，在绥远、陕西北部一带配合日军进攻抗日根据地，掠夺物资，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-40b8f224e4ca430aae205d69a9b64b43','995ae25e-1684-4c6a-b83d-56c962ffa738',1937,'1937年任伪察南自治政府最高委员','1937年任伪察南自治政府最高委员，后任伪蒙疆联合自治政府副主席，参与伪蒙疆政权对察哈尔地区（含察哈尔右翼）的统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e808e40c86ea4326b245b07b1fc6a4e6','995ae25e-1684-4c6a-b83d-56c962ffa738',1937,'在伪蒙疆政权中担任要职','在伪蒙疆政权中担任要职，参与制定对内蒙古西部包括伊克昭盟地区的统治政策，推行亲日卖国路线。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a544885a460a4bc183b6ac0b86306095','995ae25e-1684-4c6a-b83d-56c962ffa738',1937,'投靠日军后参与组建伪察南自治政府','投靠日军后参与组建伪察南自治政府，后任伪蒙疆联合自治政府副主席，协助日军统治察哈尔南部及邻近的锡林郭勒盟地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54586cd12fac437280701836a262696d','995ae25e-1684-4c6a-b83d-56c962ffa738',1937,'在伪蒙疆政权中任要职','在伪蒙疆政权中任要职，活动范围包括察哈尔与锡林郭勒盟南部，协助日军推行伪政、掠夺资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4eed7f8bbdd440d08599b346cfeb8a99','995ae25e-1684-4c6a-b83d-56c962ffa738',1937,'原察哈尔省商人','原察哈尔省商人，投靠日军，任伪察南自治政府最高委员，后任伪蒙疆联合自治政府副主席，参与伪蒙疆政权，其活动范围覆盖察哈尔、锡林郭勒盟一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e462e313a704cf8a7499c0c87ed9d5d','995ae25e-1684-4c6a-b83d-56c962ffa738',1937,'张家口沦陷后出面组织伪察南自治政府','张家口沦陷后出面组织伪察南自治政府，后任伪蒙疆联合自治政府副主席，协助日军统治察哈尔南部及张家口地区，推行伪化政策、征发物资与劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a6f9c4e9d70416cb97f58108330db2b','1481e952-3aa9-45f5-940b-fcf87b6c90d9',1937,'1937年任伪晋北自治政府最高委员','1937年任伪晋北自治政府最高委员，后任伪蒙疆联合自治政府副主席，与察哈尔右翼地区伪政权有行政关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-014f69606a7a4d36a661389fdaf656ea','1481e952-3aa9-45f5-940b-fcf87b6c90d9',1937,'原为山西大同地方士绅','原为山西大同地方士绅，日军占领大同后组织维持会，后任伪晋北自治政府最高委员、伪蒙疆联合自治政府副主席，配合日军在晋北、察南及内蒙古中东部地区推行保甲制度、征粮征兵。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85be1a4c8df2458eb60cb72ed4ef61a6','1481e952-3aa9-45f5-940b-fcf87b6c90d9',1937,'在伪蒙疆政权中任职','在伪蒙疆政权中任职，协助日军统治绥远及内蒙古西部，其政策影响波及鄂尔多斯地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72162e18b50240e686c5b40bc3a08821','1481e952-3aa9-45f5-940b-fcf87b6c90d9',1937,'投靠日军后任伪晋北自治政府最高委员','投靠日军后任伪晋北自治政府最高委员，后任伪蒙疆联合自治政府副主席，参与蒙疆伪政权的统治，其政权体系覆盖内蒙古中西部。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cf60a1e992a42878a137003dfbe6ad4','1481e952-3aa9-45f5-940b-fcf87b6c90d9',1937,'在伪蒙疆政权中任要职','在伪蒙疆政权中任要职，参与伪蒙疆联合自治政府决策，其政策影响覆盖锡林郭勒盟地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b8ec399ab6b4e28a28a5b2a5a969184','1481e952-3aa9-45f5-940b-fcf87b6c90d9',1937,'原晋北官员','原晋北官员，投靠日军，任伪晋北自治政府最高委员，后任伪蒙疆联合自治政府副主席，参与伪蒙疆政权，其政权管辖范围涉及内蒙古中西部。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-265463ebaf974ba6bcb19cd6fa3f50f6','294471a5-6d95-427f-b41e-0132c0ac470c',1936,'蒙古族','蒙古族，曾任伪蒙古军副总司令，后任伪察哈尔盟警备司令，负责察哈尔右翼各旗的治安与军事，镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4627952e67154791b689a3903475ac4b','50737c28-37b9-404f-8b58-347ed41318b2',1936,'蒙古族','蒙古族，曾任伪蒙古军参谋长，后任伪蒙古军第九师师长，在乌兰察布、察哈尔右翼地区驻防，配合日军作战。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcafdac8875f4bb1aa12c5f979953d8c','a3aeb132-5703-428d-9250-def63853f6d0',1936,'蒙古族','蒙古族，伪蒙古军第一师师长，驻防察哈尔右翼地区，参与对抗日武装的围剿。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60d9fccc7e1847579c48553e88d3378f','91906f7d-01e9-4992-8cac-1f7f2f4961b8',1936,'蒙古族','蒙古族，伪蒙古军第三师师长，活动于乌兰察布、察哈尔右翼一带，协助日军维持殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c8ea19646fb40a88910972664c7efdc','27c70fe8-9c8a-41bc-a88f-bca0417c2ae1',1936,'察哈尔蒙古贵族','察哈尔蒙古贵族，任伪察哈尔盟副盟长，协助卓特巴扎普管理察哈尔右翼各旗，推行伪政权政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43d1e29f14c64c90b7e8f9a4bc5b612e','9be10ecb-3bd8-4d54-8e2f-2729217943c3',1936,'察哈尔右翼正黄旗蒙古贵族','察哈尔右翼正黄旗蒙古贵族，任伪旗总管，在察哈尔右翼中旗邻近地区推行伪蒙疆政权政策，征粮征兵。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52096635dbe74ead8c07c74634732702','0c77923f-8ae3-4a19-8dcf-eae6cab1f14d',1936,'察哈尔右翼镶红旗蒙古贵族','察哈尔右翼镶红旗蒙古贵族，任伪旗总管，与察哈尔右翼中旗同属察哈尔右翼，协助日军统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-774b8f67db0848249936ff6498e5f747','d945bf28-bbbd-4954-8960-4c7de57ceaf5',1937,'乌兰察布盟蒙古王公','乌兰察布盟蒙古王公，任伪乌兰察布盟盟长，管辖包括察哈尔右翼中旗在内的乌兰察布地区，推行伪蒙疆政权法令。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
