INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-282cfc2b9b0f4981b059f5dde60657cb','06f22c1c-5733-414f-8876-3e3e1e752a00',1937,'绥远人','绥远人，曾任伪厚和浩特（今呼和浩特）市市长，后任伪乌兰察布盟公署参事，参与伪政权对乌兰察布地区的管理。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a27ba66cd314cd4963021dc94a289f0','1302aa7b-6d97-4d62-bad2-4e9a6f699af9',1937,'归绥（今呼和浩特）商人','归绥（今呼和浩特）商人，任伪厚和浩特市商会会长，后任伪蒙疆联合自治政府经济委员，为日军经济掠夺服务，影响范围包括乌兰察布地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-718905a8fa644cfeae79bce094a8da58','26030254-77ea-467b-b4ca-57c88cf16cbe',1933,'在察哈尔右翼前旗及乌兰察布地区积极推行日本侵略者的“蒙疆自治”政策','在察哈尔右翼前旗及乌兰察布地区积极推行日本侵略者的“蒙疆自治”政策，组织伪蒙古军配合日军进攻抗日武装，并在当地实施殖民统治和奴化教育。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96516c7f08e34948b6fd88a9274636e8','26030254-77ea-467b-b4ca-57c88cf16cbe',1933,'在乌拉特中旗及内蒙古西部策划“蒙古自治”','在乌拉特中旗及内蒙古西部策划“蒙古自治”，组建伪蒙古军，配合日军进攻绥远，建立傀儡政权，压迫抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-224d21c925bf4e9ebf1d8a0801e3b91e','7284be12-3384-48e1-8dbb-221a33124b5e',1933,'作为日本扶植的蒙古军头目','作为日本扶植的蒙古军头目，在察哈尔右翼前旗及周边地区协助日军镇压抗日力量，参与“清乡”和掠夺资源，为日军提供情报和兵力支持。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9861dc695a44dd1a7d3d932c8f0a4fc','36bdc16c-b78f-4ca2-919b-f3df6ae1923b',1938,'在乌兰察布及察哈尔右翼前旗地区推行伪政权法令','在乌兰察布及察哈尔右翼前旗地区推行伪政权法令，组织汉奸团体协助日军维持治安，强征民夫和粮食，迫害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-881509eac95744318b1d3f31b3eebdea','cb28f9da-3891-4d64-bf52-bbe2d73be801',1937,'在察哈尔右翼前旗一带为日军效劳','在察哈尔右翼前旗一带为日军效劳，参与建立伪旗公署，强迫当地民众“归顺”日伪，并协助日军围剿八路军游击队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da4bb27df4894929b337552ac13aa52d','a7c961a4-e856-4513-a165-9cd23a549823',1939,'直接管理察哈尔右翼前旗日伪政权','直接管理察哈尔右翼前旗日伪政权，向日军提供当地抗日活动情报，强征壮丁和牲畜，实施保甲连坐制度，镇压反抗民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3241a61ae9e54d3bb6070182f4380e0a','61193520-f281-45a4-be71-3526ebef7a58',1937,'在乌兰察布东部及察哈尔右翼前旗地区率伪军参与“扫荡”','在乌兰察布东部及察哈尔右翼前旗地区率伪军参与“扫荡”，烧毁村庄，杀害抗日干部，并协助日军建立特务情报网。','危害等级B（乙级，市县厅局级）','hanjian');
