INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6639afcb15ce4695b15576f80078bd8c','079d507e-fc50-44ab-a2fb-4acfe5154904',1940,'原国民党将领','原国民党将领，后投靠日军，在乌海及河套地区组织伪军，配合日军进攻抗日根据地，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-241186501016469aad67f24ede0582dc','1386be91-8d4b-4fc1-8de8-ea53c360fa60',1936,'蒙古族官僚','蒙古族官僚，追随德王投日，在内蒙古西部包括乌海、海勃湾地区参与建立伪政权，负责行政和治安，协助日军征粮征税，镇压当地抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-040dc3bddd3f44db964c42fa5c79a804','4511f830-e18c-46d6-b4dd-a58ac6343c46',1936,'在日军扶植下成立伪蒙古联盟自治政府','在日军扶植下成立伪蒙古联盟自治政府，任主席，推行“蒙疆自治”，配合日本殖民统治，征发蒙汉民众为日军服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cc56e0cec6247d2b6808d052038ff37','4511f830-e18c-46d6-b4dd-a58ac6343c46',1936,'蒙古王公','蒙古王公，1936年投日，组织伪蒙古军政府，后任伪蒙古联盟自治政府主席，与日军合作，在包头及内蒙古西部推行殖民政策，招募汉奸充实伪政权。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-042e25314d3940c9959ebed8029291d9','4511f830-e18c-46d6-b4dd-a58ac6343c46',1936,'蒙古王公','蒙古王公，与日军合作建立伪蒙政权，其势力范围包括武川地区，推行奴化教育，协助日军征粮征兵，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7709d57837c9473a804fd75366e40cb3','4511f830-e18c-46d6-b4dd-a58ac6343c46',1936,'蒙古王公','蒙古王公，组织伪蒙古军政府，与日军合作控制察哈尔北部及沽源一带，推行奴化政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
