INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ddffa0cea944ed2af69cdae89c8924f','b238e0c4-a027-4266-8704-21028044dcf5',1938,'协助王英统领伪军','协助王英统领伪军，在乌海、海南周边地区设卡收税，强征民夫，为日军修筑工事。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cefed8db8f447c6b9b166f28d3c01a4','b238e0c4-a027-4266-8704-21028044dcf5',1938,'王英的副手','王英的副手，在临河、五原一带协助日军维持治安，参与屠杀抗日群众，并负责为日军征收粮食和牲畜。','危害等级C（丙级，基层头目）','hanjian');
