INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84b065e2fb2e4f5fa5be383d32c546e2','7756dd28-4794-4968-a0ce-65ef15d7f7a8',1932,'蒙古族王公','蒙古族王公，投靠日本后任伪兴安南省省长，协助日军在扎赉特旗及兴安盟地区推行殖民统治，镇压抗日力量，参与伪满洲国傀儡政权建设。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d81aafbe534f43668ff360a3c05e8e7d','73b5b472-b2b5-4e75-a092-047692c5e298',1932,'原扎赉特旗札萨克','原扎赉特旗札萨克，叛国投敌后任伪兴安南省警备军司令，率伪军配合日军围剿抗日武装，在扎赉特旗地区实施“清乡”和“讨伐”，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85b01a56205c4103acfb146f5c7f054e','562144ee-5793-419f-bbdf-a1a1f9febeac',1933,'蒙古族官僚','蒙古族官僚，投日后历任伪职，在扎赉特旗推行日伪“土地奉上”政策，强征民夫和物资，协助日军建立保甲制度，镇压当地反抗活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b35a0d5b3a664632ae391790b7541368','c65a21ba-f9e1-4269-82d4-cd4e608bf3c0',1932,'参与伪兴安南省行政事务','参与伪兴安南省行政事务，积极执行日本关东军指令，在扎赉特旗地区推行奴化教育和经济掠夺，为日军提供情报和后勤支持。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11469a7622dd43509dcf1bb00208ea2e','7639543d-e7d7-4634-a8ca-93626c9b4efe',1934,'作为蒙古族上层投靠日本','作为蒙古族上层投靠日本，在扎赉特旗参与组织伪警察和自卫团，协助日军抓捕抗日志士，强征“国兵”和劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
