INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c56b6b302b04aa78ef821a4e6ebaf75','bb54f6ec-fef6-43c7-8f8a-503bc987bf6c',1932,'蒙古族王公出身','蒙古族王公出身，九一八事变后投靠日本，参与策划内蒙古东部‘独立’活动，历任伪兴安南分省省长、伪兴安局总裁等职，协助日本在兴安地区推行殖民统治，管辖范围包括科尔沁右翼中旗一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd8fc4eaadf14d8dbd11bcdb1ebe5336','316d716c-cd43-48a7-a849-6744ff03e951',1932,'原扎赉特旗王公','原扎赉特旗王公，投日后任伪兴安南分省警备军司令，率伪军配合日军镇压抗日武装，其部队活动于兴安南地区，包括科尔沁右翼中旗周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06fc0460fb324d718a5f1cf0b396a06b','97aeb244-a6a4-4de0-b6d8-ebbec1c4395e',1932,'蒙古族上层人物','蒙古族上层人物，投靠日本后历任伪兴安南分省参与官等职，参与推行‘蒙地奉上’等殖民政策，在兴安地区协助日伪统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a355439cc9e2421ca961dcb1021a6325','7c7552a2-1546-4374-ab15-cc2195d909df',1932,'早年参与内蒙古自治运动','早年参与内蒙古自治运动，后投靠日伪，历任伪兴安南分省民政厅长、伪兴安总省省长，在兴安地区推行日本殖民统治政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ab79c58bb234be59ccf2540f31e23a3','72f6bc0b-d54f-404f-8792-6c2b58e13a95',1932,'蒙古族官僚','蒙古族官僚，投日后在伪兴安南分省任职，参与管理科尔沁右翼中旗等地的行政与警务，协助日军征发物资、镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-064124bca9bc48ad9e5cd0c0e94d66ea','15fd3fdb-dbcb-4326-91b3-c20831f7e5f9',1932,'原内蒙古东部蒙古族军官','原内蒙古东部蒙古族军官，投日后任伪兴安南分省警备军参谋长，参与指挥伪军配合日军在兴安地区‘讨伐’抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a746f4549e074628a9ceaa91e0f1fea3','72a923c1-5fdf-433b-8894-946131e73cc1',1936,'锡林郭勒盟苏尼特右旗札萨克亲王','锡林郭勒盟苏尼特右旗札萨克亲王，投靠日本后建立伪蒙疆政权，虽中心在察哈尔、绥远，但与兴安地区伪政权有联系，其伪蒙古军活动范围涉及内蒙古东部。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc1e2a6958004b398bfb40116ad50add','72a923c1-5fdf-433b-8894-946131e73cc1',1936,'在日军扶植下建立伪蒙疆政权','在日军扶植下建立伪蒙疆政权，其势力范围覆盖内蒙古东部及通辽地区，与科尔沁左翼后旗伪旗政权有隶属或协作关系，推行亲日殖民政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bce5d56a038c451792bd8ed572490b83','2bd4a4d1-0f12-4f75-a3d2-75c5b7ac7d97',1933,'绥远地区土匪头目','绥远地区土匪头目，投日后任伪蒙古军副总司令，率部在内蒙古西部及兴安地区配合日军作战，参与镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcc46578280f4681a533192ee44a092a','2bd4a4d1-0f12-4f75-a3d2-75c5b7ac7d97',1933,'绥远地区土匪出身','绥远地区土匪出身，投日后任伪蒙古军副总司令，其部队在内蒙古东部及通辽一带活动，配合日军扫荡抗日根据地，后任伪绥西联军司令。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d696eceb3574200a104011d0b52667a','e672ae82-8465-4679-9ee9-332eda924eec',1931,'原东北军将领','原东北军将领，九一八事变后投敌，历任伪奉天省警备司令、伪军政部大臣，其指挥的伪军活动范围包括兴安南地区，参与‘讨伐’抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5430b0d79e1d41fb85e27e4a87101a8d','5d4f6fea-eb9e-489b-82be-b368a8afa959',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，率伪军进攻热河、察哈尔，其活动区域与兴安南地区相邻，配合日军镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3c6b2bb1fad4fa69aa85fc9fc8d872f','4b7c01cd-81e4-41d4-8d8c-2c91385656b8',1932,'达斡尔族上层','达斡尔族上层，投日后任伪兴安北分省省长，虽后期因‘凌升事件’被日本处决，但前期在兴安地区协助日伪统治，与兴安南地区有行政联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3803f3761ba44d1a9d180e2e06ffc27','4b7c01cd-81e4-41d4-8d8c-2c91385656b8',1932,'达斡尔族上层','达斡尔族上层，曾任伪满洲国兴安北分省省长，驻海拉尔，管辖包括新巴尔虎右旗在内的呼伦贝尔地区，后因与日本矛盾被处决，但其前期附逆行为明确。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-001d6504cb3a4b97867dca5e9c4bf051','ac6be2e1-cb09-4056-92b3-1fb64ef77114',1932,'科尔沁右翼中旗蒙古族上层','科尔沁右翼中旗蒙古族上层，投日后任该旗伪旗长，协助日军征发物资、推行保甲制度，镇压当地抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb94b3045d2a4882ad0f4d2b114474a8','fb661b37-9e03-43fb-a2d2-abab9d7be169',1935,'在科尔沁右翼中旗任伪警务科长','在科尔沁右翼中旗任伪警务科长，指挥伪警察配合日军‘讨伐’抗日游击队，迫害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d4bdaa54fdc419d8cc890418db6abf9','3a17b8e3-e166-48f6-bb63-8b41d8b4407d',1932,'科尔沁右翼中旗地方豪绅','科尔沁右翼中旗地方豪绅，日军占领后组织维持会，协助日军维持治安、征发粮草，后转入伪旗公署任职。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54dc0784fc344ebea92dfc90e769f911','f3f90a18-a294-4696-9eca-7ca06252ae96',1932,'蒙古族上层亲日派','蒙古族上层亲日派，参与策划伪满洲国成立，历任伪兴安南分省省长、伪兴安局总裁等职，协助日本在兴安地区推行殖民统治，管辖范围包括科尔沁右翼前旗一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75b6b9d9cf5d4fe29f0434c6b6a7be51','fda7d302-19c7-429e-8269-6b73ce611127',1932,'原扎赉特旗王公','原扎赉特旗王公，投靠日本后任伪兴安南省警备军司令等职，率伪军配合日军在兴安地区镇压抗日武装，其活动覆盖科尔沁右翼前旗周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9ca7341a8f24ab18d527abf943fa162','b969d0a3-26c4-479c-bf45-21437885e4cb',1932,'蒙古族亲日文人','蒙古族亲日文人，在伪兴安南省任职期间推行日本殖民教育、文化政策，协助日伪在兴安地区建立基层伪政权，涉及科尔沁右翼前旗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8b8165f7daa420f9e626feb3aca40c0','dab1ee9e-2962-4922-ac73-77c52a1267d2',1932,'蒙古族伪军头目','蒙古族伪军头目，长期在伪兴安南省警备军任职，参与指挥对兴安地区抗日游击队的围剿，活动范围包括科尔沁右翼前旗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f01e89a3b734736befdd7a4fe36e0ef','7961d6dd-16f3-42d1-b830-960aa53e0ede',1932,'蒙古族伪军军官','蒙古族伪军军官，在伪兴安南省警备军任职期间率部配合日军在兴安地区进行治安肃正，镇压抗日力量，活动于科尔沁右翼前旗一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-639f24e848a7489dbd9a06b91416a571','be933f5c-8362-4338-b2de-744b386d3778',1932,'蒙古族亲日官僚','蒙古族亲日官僚，在伪兴安南省任职期间负责行政、财政事务，协助日本掠夺兴安地区资源，推行保甲制度，涉及科尔沁右翼前旗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d2765c45e3d4932926a9ddc0a3276ee','49c8360e-b313-4697-9c37-8ccbae3f0c5f',1932,'直接于科尔沁右翼前旗任职的伪旗长','直接于科尔沁右翼前旗任职的伪旗长，协助日伪推行旗政、征粮、征兵，镇压当地抗日活动，是当地伪政权核心人物。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9fb825f2d744e5da2e75e4c5c9ff2e4','cb8c52d2-fb8d-4ec3-9eff-d750fc469f3b',1932,'在科尔沁右翼前旗担任伪警务科长','在科尔沁右翼前旗担任伪警务科长，负责伪警察队伍，配合日军搜捕抗日人员，推行保甲连坐，直接镇压当地民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-121305659935419aaeebc53376e67a91','818bb1c6-481f-48f6-80da-2ff5052172d7',1932,'在科尔沁右翼前旗组织维持会','在科尔沁右翼前旗组织维持会，协助日军维持占领秩序，征派劳役、物资，为伪旗政权建立铺路。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82c9fed544ac4ac1b99c6c8fdff9ed64','7932adff-2b4a-47fc-8ed5-4b2da417228e',1935,'在科尔沁右翼前旗担任保甲长并兼任协和会分会会长','在科尔沁右翼前旗担任保甲长并兼任协和会分会会长，推行保甲制度、宣传亲日思想，协助日伪征粮征兵，监控当地民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9de7cd63f9884b3a9cd01e5f684f4183','ab225cae-b5a7-4d59-ad56-50a68580f074',1936,'在伪兴安南省协和会任职','在伪兴安南省协和会任职，负责亲日宣传、组织民众训练，活动覆盖科尔沁右翼前旗，协助日伪进行思想控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fdc441edf78044949e72970c7a316887','70f9ee86-c700-4d9b-b3ca-1eb45ffeb67c',1935,'在科尔沁右翼前旗推行日本殖民教育','在科尔沁右翼前旗推行日本殖民教育，强制教授日语、篡改历史，培养亲日青少年，属教育领域附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16ea3e3cc1a2433f93a92398a5468af3','2aa2660f-8a7d-46ab-a3a6-04ac348122f4',1930,'蒙古族上层亲日派首领','蒙古族上层亲日派首领，虽主要活动于察哈尔、绥远，但其伪蒙疆政权与伪兴安地区有联系，影响覆盖内蒙古东部，包括兴安、科尔沁右翼前旗一带的蒙古族亲日势力。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2ad74c23cb04c518281efb4488b3448','2aa2660f-8a7d-46ab-a3a6-04ac348122f4',1930,'即德王','即德王，在内蒙古中西部建立伪蒙疆政权，与日本合作','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de1459a07de746348c1848bb006b248e','2aa2660f-8a7d-46ab-a3a6-04ac348122f4',1930,'其影响及于内蒙古地区','其影响及于内蒙古地区，是抗战时期内蒙古范围内最重要的附逆头目之一。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-930f440c93114caea360984e670fae49','2aa2660f-8a7d-46ab-a3a6-04ac348122f4',1930,'蒙古王公','蒙古王公，投靠日本，建立伪蒙疆政权，其势力范围覆盖内蒙古中东部，与呼伦贝尔地区有联系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9c5213a10e9458c9e6253cb0979e512','2aa2660f-8a7d-46ab-a3a6-04ac348122f4',1930,'在日军扶植下于张家口建立伪蒙疆政权','在日军扶植下于张家口建立伪蒙疆政权，统治包括察哈尔北部、张家口周边地区，推行亲日附逆政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3952aecb40334c97ad5d71b326bda919','2aa2660f-8a7d-46ab-a3a6-04ac348122f4',1930,'在察哈尔、热河及河北北部建立伪蒙疆政权','在察哈尔、热河及河北北部建立伪蒙疆政权，与承德伪满势力勾结，配合日军进攻抗日根据地，推行殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4cf14e1b156449abb5bf41e9abd48f56','2aa2660f-8a7d-46ab-a3a6-04ac348122f4',1930,'内蒙古人','内蒙古人，抗战期间投靠日军，任伪蒙疆联合自治政府主席，在华北地区进行伪化统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60727cb012f94d9fac5c334f27644df0','2aa2660f-8a7d-46ab-a3a6-04ac348122f4',1930,'伪蒙疆政权首脑','伪蒙疆政权首脑，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb344069ddcc4778a2bda07bf2964b97','2aa2660f-8a7d-46ab-a3a6-04ac348122f4',1930,'在日军扶植下成立伪蒙疆政权','在日军扶植下成立伪蒙疆政权，配合日军在华北、西北的侵略，对陕西北部有威胁。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-652c1751f929401b8a4aeaaa642b1daa','5772f5a0-7366-4300-a0d3-c8436988c341',1932,'蒙古族上层出身','蒙古族上层出身，九一八事变后投靠日本，参与策划内蒙古东部独立活动，历任伪兴安南省警备军司令等职，率伪军配合日军镇压抗日武装，控制兴安盟一带，包括突泉地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26c92b65b565458988d0a61830f33883','f2a641b7-1b6b-41d5-b0a1-efa89a6f3df1',1932,'原扎赉特旗王爷','原扎赉特旗王爷，投日后任伪兴安南省省长、伪兴安局总裁等职，协助日本在兴安盟推行殖民统治，征发劳工、物资，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-120c6493a14e4188a6a6106ca2eae5ad','28e384cc-3b9a-4700-882d-8543a740f15a',1932,'蒙古族官僚','蒙古族官僚，在伪兴安南省任职期间推行日本殖民政策，管理民政、警察事务，配合日军在突泉等地的保甲连坐和物资统制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd15161ccf0d4e20a7c33eb3ea9c5865','56e18410-9eac-4143-b9e6-6b314e4372be',1932,'在伪兴安南省警备军任职','在伪兴安南省警备军任职，率部在兴安盟及突泉周边地区配合日军围剿抗日游击队，强征民夫、牲畜。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-560d3ea7d1684c6da6ffe1e27b3ed5e9','4fa07cca-438b-48a2-88c9-b714bbcc541f',1933,'热河土匪出身','热河土匪出身，投靠日本后任伪蒙古军总司令，活动范围覆盖内蒙古东部及兴安盟周边，配合日军进攻抗日根据地，在突泉一带征粮征兵。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17985aead225442db24a4eff4e6e9074','4fa07cca-438b-48a2-88c9-b714bbcc541f',1933,'热河人','热河人，长期在伪蒙疆和华北伪军中任职，其伪军活动范围涉及山西北部及华北地区，配合日军作战，对山西抗日力量构成威胁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4037a08424b24daab902e5827e506083','4fa07cca-438b-48a2-88c9-b714bbcc541f',1933,'热河地区蒙古族伪军头目','热河地区蒙古族伪军头目，长期在承德、赤峰及河北北部活动，配合日军围剿抗日武装，推行保甲连坐，掠夺物资，镇压民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed3d3870589f4465a1a5a044e4738ae6','4fa07cca-438b-48a2-88c9-b714bbcc541f',1933,'内蒙古人','内蒙古人，长期在伪蒙疆政权任职，其伪军曾参与对河南北部地区的策应行动，与河南伪政权有联系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1fd1d77ea91541cf9d22a16aa35de88f','4fa07cca-438b-48a2-88c9-b714bbcc541f',1933,'内蒙古人','内蒙古人，长期在伪蒙疆政权任职，其伪军曾配合日军在河南北部活动，间接影响南阳地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24a07ab9b53b4db99e9374437a044bcc','3fe5e3c9-2827-4fcf-a5fd-9ccaaa7a6483',1936,'绥远地区汉奸武装头目','绥远地区汉奸武装头目，投日后率伪军在内蒙古中东部活动，曾配合日军在兴安盟附近扫荡，参与镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d05c117da214c8689eee6e35cf1f2d2','1eee1811-7a7c-470c-9435-4a0cfa1b314d',1931,'原东北军将领','原东北军将领，九一八后投敌，任伪奉天省警备司令等职，其伪军活动范围包括内蒙古东部与兴安盟接壤地区，配合日军镇压抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80949ee1c9ef4d72a15d22ea996f784d','605c7fb3-c39c-424f-99b3-d08877c1aa5f',1931,'原东北军骑兵师长','原东北军骑兵师长，投日后任伪洮辽镇守使，率伪军进攻热河、兴安盟一带，在突泉周边地区配合日军作战，镇压抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cca51bab11e4417dbdceb30dee392154','cc403e58-8a6a-4a00-bf1d-1ae16ab209eb',1932,'达斡尔族上层','达斡尔族上层，曾任伪兴安北省省长，参与伪满洲国初期统治，后因与日本矛盾被处决','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ced279e7f2543c1abdfcbfb55d64c46','cc403e58-8a6a-4a00-bf1d-1ae16ab209eb',1932,'其活动范围主要在呼伦贝尔','其活动范围主要在呼伦贝尔，但与兴安盟伪政权有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76ff9d9c3ce148e8a849fc5255f4e682','e7d5791d-c9d4-41cd-980e-4cf2b44128a6',1932,'蒙古族王公','蒙古族王公，投日后任伪兴安局总裁等职，参与制定对内蒙古东部地区的殖民统治政策，影响覆盖兴安盟及突泉一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d73ccfb247344e35b4e59a6e3772a48d','a5338813-22d2-4a70-b8db-5937acb09f49',1932,'九一八事变后','九一八事变后，突泉县地方士绅组织维持会，迎接日军占领，协助建立伪政权，维持地方治安并征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67d4562f076141738f83e991aa8e4104','801e2a5a-efe2-4935-870a-75c6b3191c72',1933,'伪满洲国时期由日方委任的突泉县县长','伪满洲国时期由日方委任的突泉县县长，推行保甲制、粮谷出荷、劳工征发等政策，配合日军在兴安南省西部的统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97c74d886e1d439396808d53ea3dd873','c104bf7a-070c-48ff-a120-c8716aae3733',1932,'日本关东军扶植的蒙古族汉奸','日本关东军扶植的蒙古族汉奸，参与组建伪兴安军，在兴安、阿尔山一带协助日军维持治安，围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd78a5b00638456ea2bf2cd1c93ec00c','94cdd81e-c0fc-4bcc-bd6a-ad86796e40cb',1932,'甘珠尔扎布之弟','甘珠尔扎布之弟，任伪兴安军要职，在兴安盟地区协助日军进行军事行动，镇压当地抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd531d1138c5420c98c1700b40dd0cfe','1259ad95-048f-4d80-847a-288b530850b9',1932,'伪满洲国兴安南省（辖今兴安盟及阿尔山部分地区）省长','伪满洲国兴安南省（辖今兴安盟及阿尔山部分地区）省长，推行日伪殖民政策，强征劳工，协助日军统治当地蒙汉民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70ce3a625baf4a6a944fcc04935b8dc5','4e60b57a-f3da-496f-a6e2-4644ed42bddf',1932,'在兴安南省（含阿尔山地区）担任伪警务厅长','在兴安南省（含阿尔山地区）担任伪警务厅长，组织伪警察镇压抗日分子，抓捕并杀害抗联地下工作人员。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9dc5e2038f33425983007152e18299b6','7475ead6-3d2c-4a11-85ae-ccf6c4205168',1933,'投靠日伪','投靠日伪，在兴安南省（阿尔山一带）任参事官，协助日军推行“治安肃正”，迫害当地抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d4ca829fa15460e8c5c0d1fb4915f90','5251d4ce-3766-41f1-8c4b-77132ad8f799',1934,'率伪兴安军驻扎于阿尔山附近','率伪兴安军驻扎于阿尔山附近，参与对苏联、蒙古边境的侦察及对抗日游击队的围剿。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a82bc5c212d401f8c57a63fa9fadf20','9d339fc4-4cd1-47be-a1da-385cb719459f',1932,'伪满洲国兴安东省（部分辖区与兴安盟接壤）省长','伪满洲国兴安东省（部分辖区与兴安盟接壤）省长，虽主要活动于扎兰屯一带，但曾参与协调兴安、阿尔山地区的日伪军事行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e31e276e3171475087748ffe26b846ad','9d339fc4-4cd1-47be-a1da-385cb719459f',1932,'在呼伦贝尔东部地区推行伪满统治','在呼伦贝尔东部地区推行伪满统治，协助日军清剿抗联部队，征收粮草','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be662c30322049a79f4a0b3202c14572','1cde4c4b-b0d1-4ce3-a7a8-50b60fa4be5c',1935,'在兴安盟及阿尔山地区率伪骑兵师配合日军“扫荡”','在兴安盟及阿尔山地区率伪骑兵师配合日军“扫荡”，破坏抗联根据地，掠夺当地物资。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6ee2f8b345742c3b37cb9c9e3f85467','8e64a565-1a79-430f-ad07-0cf4f9402ffb',1939,'在日军占领包头期间出任伪市长','在日军占领包头期间出任伪市长，协助日军维持治安，推行保甲制度，强征劳工，为日军提供物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-53764075a8b1485c96f84afd09e5e207','97853311-2368-45f6-b5a4-ba4d03ae245b',1939,'在包头伪政权中负责警察事务','在包头伪政权中负责警察事务，抓捕抗日地下人员，协助日军进行特务活动，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b65edfb9b50b41d7b8b2b9cd15f19a98','97853311-2368-45f6-b5a4-ba4d03ae245b',1939,'指挥伪警察在包头、九原地区搜捕抗日分子','指挥伪警察在包头、九原地区搜捕抗日分子，破坏地下交通线，多次参与日军“治安强化运动”，杀害无辜百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26c20da643054c4d8595764c45dc792e','97853311-2368-45f6-b5a4-ba4d03ae245b',1939,'任伪包头警察局长期间','任伪包头警察局长期间，大肆搜捕抗日地下工作者，严刑逼供，破坏抗日组织，在固阳、包头一带制造多起血案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ab70fa27a504450acd9248ecefce8be','97853311-2368-45f6-b5a4-ba4d03ae245b',1939,'协助日军在包头及白云鄂博矿区建立特务网络','协助日军在包头及白云鄂博矿区建立特务网络，抓捕抗日志士，镇压矿工反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1875a76bcd5e457d91e51f1b13442ae8','97853311-2368-45f6-b5a4-ba4d03ae245b',1939,'指挥伪警察在包头、青山地区搜捕抗日地下人员','指挥伪警察在包头、青山地区搜捕抗日地下人员，破坏地下组织，协助日军实施“治安强化”运动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-346b9ed2cc7e4286891e1886a6eb3c13','1f83e5e4-4d57-4491-9e1d-0374dc7eec80',1938,'投靠日军后控制包头商会','投靠日军后控制包头商会，为日军筹集军饷和物资，强迫商户缴纳各种捐税，从中牟利。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-015f20a14169426b86143873de4bbe51','e360ec00-6e91-46f3-bc90-1f23a56908ef',1938,'负责发行伪蒙疆货币','负责发行伪蒙疆货币，搜刮包头地区财富，配合日军经济掠夺，导致当地通货膨胀，民生凋敝。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09c1336bbee84e68a7e2722c64bab776','8fb4a4c5-f5f5-4105-9ec8-73b21e03eb51',1937,'蒙古族军官','蒙古族军官，投靠德王后任伪军参谋长，在包头地区参与军事指挥，协助日军围剿抗日游击队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac9ca72aadff4824bcca5902374b271c','eb2c5ac3-231b-4caf-a0e7-51bdf4cf44ee',1939,'蒙古贵族','蒙古贵族，任伪包头市长期间，推行日伪法令，强征劳工，协助日军控制包头及东河地区经济命脉。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1afccdc0003c4bcb9cf523f1004ff296','d056993b-2aa5-4c68-9650-c8595b528df7',1940,'在包头、东河地区充当日军鹰犬','在包头、东河地区充当日军鹰犬，搜捕抗日地下工作者，镇压民众反抗，参与“特别治安”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75b724f936b244409c67201c52d024a1','f6464d40-357e-48d9-b960-51b46a601c81',1938,'率伪保安队在东河一带巡逻','率伪保安队在东河一带巡逻，配合日军“扫荡”，抢劫民财，杀害抗日家属，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
