INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a4292bb23464c7e92112afe95c0f449','04f9d3cb-c95f-4af7-85ec-72a857aa27cd',1940,'原晋军军官','原晋军军官，投日后任伪绥西自治联军参谋长，参与策划对包头周边抗日游击队的围剿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13322b22c0224dd993d38c9193840b2c','04f9d3cb-c95f-4af7-85ec-72a857aa27cd',1940,'参与策划伪军对五原地区的多次突袭','参与策划伪军对五原地区的多次突袭，并负责训练伪军，配合日军“治安强化”运动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b07fcaffa534466b9952f270465a1c02','2fd9b000-6bdf-4263-9dc2-fb8cd24dbfe5',1938,'原东北军军官','原东北军军官，叛变投日后在绥远地区活动，参与对包头、白云鄂博一带的军事占领和资源掠夺。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e40a7eea9799476597e12d9fd155ceaa','391ece63-e9d6-4419-8d51-b9ad3eef4ba8',1939,'日本占领包头后任伪市长','日本占领包头后任伪市长，负责推行日伪市政管理，组织劳工为日军开采白云鄂博铁矿，强征粮食和物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9943d1ebd4da440a876bea4f49dd42c9','4e3cde55-03b6-4b28-88da-a8ca8b910724',1939,'为日军筹措军费','为日军筹措军费，垄断白云鄂博矿石运输，向日本军方提供经济支持，剥削当地商民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71f6ee17b97341b5b5e5ce1af7dccdb3','60f2354e-d276-42c4-b357-c05e55539906',1940,'蒙古族投日分子','蒙古族投日分子，在包头、白云鄂博地区协助日军管理蒙古族事务，煽动民族分裂，破坏抗日统一战线。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a51f1d56210b435ca0310465d628b5d1','f9323721-577b-4249-8891-87cf7a401280',1937,'在包头、石拐地区协助日军管理伪蒙政权','在包头、石拐地区协助日军管理伪蒙政权，参与制定殖民政策，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8e1dfdc72f14d8cb407367da15b6057','870d3965-fb56-40dd-a645-75b9661a9754',1938,'随王英投敌','随王英投敌，在石拐地区参与伪军活动，协助日军围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88430be9a469468a9e95d1ed4c2da9ca','6b7f9f77-43c7-48dc-a03b-ad2d8e4a27eb',1940,'在包头、石拐地区推行日伪政令','在包头、石拐地区推行日伪政令，征收苛捐杂税，协助日军掠夺矿产资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed97a7c212eb4e37ad5d98eb4814ef41','29510cc1-67d1-43dc-8ac0-d9e23b68013e',1941,'在石拐煤矿区为日军服务','在石拐煤矿区为日军服务，组织矿工劳动，镇压矿工反抗，向日军提供煤炭资源。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9beefb6db4524aff99fb6a12cc8ba09c','4e9e505a-a4b6-467f-b5a3-0ef931244422',1942,'在包头、石拐地区带领伪保安队','在包头、石拐地区带领伪保安队，配合日军清乡，杀害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e52b2c2e7c142d791bef4b937228327','830d567b-8a39-47e2-8a42-898bbeaa2901',1939,'在包头、石拐地区从事特务活动','在包头、石拐地区从事特务活动，搜集情报，破坏抗日组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c11ae706e4af4aed84626f178600960e','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'在日军扶植下于百灵庙发动蒙古自治运动','在日军扶植下于百灵庙发动蒙古自治运动，后成立伪蒙疆政权，统辖包括包头、达尔罕茂明安在内的内蒙古中西部，推行亲日政策，配合日军统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f84583bb8b7473f838dda07ed518dc0','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'在日军扶植下于内蒙古西部建立伪蒙疆政权','在日军扶植下于内蒙古西部建立伪蒙疆政权，统辖察哈尔、绥远等地蒙古盟旗，鄂尔多斯部分旗县亦在其伪政权影响或控制范围内，推行亲日卖国政策，配合日军统治与掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61d52e933d0e4e759e39b45255415b1a','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'在日军扶植下于内蒙古地区建立伪蒙疆政权','在日军扶植下于内蒙古地区建立伪蒙疆政权，统辖察哈尔、绥远等地，鄂尔多斯部分地区受其伪政权影响，推行亲日卖国政策，配合日军侵略。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0988fb6dd5a349279c01863949248780','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'在日军扶植下于内蒙古西部建立伪蒙疆政权','在日军扶植下于内蒙古西部建立伪蒙疆政权，统辖察哈尔、绥远等地，鄂尔多斯北部及杭锦旗一带曾受其伪政权影响，推行亲日附逆政策，配合日军统治与掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8b797d2055d49688f90a352621ca421','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'锡林郭勒盟苏尼特右旗人','锡林郭勒盟苏尼特右旗人，抗日战争时期投靠日本，先后组织伪蒙古军政府、伪蒙古联盟自治政府、伪蒙疆联合自治政府，任主席，配合日军统治内蒙古中西部，其势力范围覆盖锡林郭勒盟及周边地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b34dccca3cc4f14b7496ab814411235','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'察哈尔部正白旗人','察哈尔部正白旗人，长期在锡林郭勒盟及察哈尔地区活动，1936年在德化（今化德）成立伪蒙古军政府，后任伪蒙疆联合自治政府主席，统辖包括锡林郭勒盟在内的蒙疆地区，与日军合作推行殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f25536a26c0d4978a67f16a142cc9146','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'在锡林郭勒盟及察哈尔地区组织伪蒙政权','在锡林郭勒盟及察哈尔地区组织伪蒙政权，与日本关东军合作，统辖包括太仆寺旗在内的察锡地区，推行亲日政策并协助日军统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e37454b870a424bbf31708d6c471742','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'锡林郭勒盟苏尼特右旗人','锡林郭勒盟苏尼特右旗人，长期在锡林郭勒盟及察哈尔北部活动，1930年代投靠日本，先后组织伪蒙古军政府、伪蒙古联盟自治政府、伪蒙疆联合自治政府，统辖包括锡林郭勒盟在内的蒙疆地区，为日本侵略势力服务。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-069e0f9eae924f919b95f48d70059da6','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'察哈尔部正白旗人','察哈尔部正白旗人，在锡林郭勒盟及察哈尔地区组织伪蒙政权，投靠日本，任伪蒙疆联合自治政府主席，配合日军统治内蒙古中西部，其势力范围覆盖锡林郭勒盟及正镶白旗一带。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f8f856b825f42ec968ac7142ecb5ff6','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'锡林郭勒盟苏尼特右旗人','锡林郭勒盟苏尼特右旗人，世袭苏尼特右旗札萨克郡王。1933年发起内蒙古自治运动，1936年在日本扶持下成立伪蒙古军政府，1937年改组为伪蒙古联盟自治政府，1939年任伪蒙疆联合自治政府主席，统治察哈尔、锡林郭勒等地，配合日军镇压抗日力量、推行殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09a1422262ed430fb760892aaa5cacd0','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'锡林郭勒盟苏尼特右旗人','锡林郭勒盟苏尼特右旗人，抗战期间投靠日本，先后组织伪蒙古军政府、伪蒙古联盟自治政府、伪蒙疆联合自治政府，统治包括锡林郭勒盟在内的内蒙古中西部及察哈尔、晋北地区，配合日军镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9372f83d1f64e7dbf3c87930aa866ab','72580da0-9521-440e-a3d2-60233c2eb07e',1933,'察哈尔部正白旗人','察哈尔部正白旗人，长期在锡林郭勒盟及察哈尔地区活动，1936年成立伪蒙古军政府，1939年任伪蒙疆联合自治政府主席，辖锡林郭勒盟等地区，推行亲日政策，配合日军统治内蒙古中西部。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-736d8383d5dc44b0af1acdb95b5d4510','14368820-3c26-4075-8af7-6d2c436df49e',1933,'率部投靠日军','率部投靠日军，参与组建伪蒙古军，驻防包头及绥远地区，配合日军进攻抗日武装，控制达尔罕茂明安一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c0178b7fd644c81860bf9c6b8642ef9','14368820-3c26-4075-8af7-6d2c436df49e',1933,'率伪蒙古军多次进犯鄂尔多斯地区','率伪蒙古军多次进犯鄂尔多斯地区，参与围剿抗日武装，协助日军在伊克昭盟推行“治安肃正”，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a45951701317493898e4303f17ce5d5b','14368820-3c26-4075-8af7-6d2c436df49e',1933,'率部投靠日军','率部投靠日军，参与组建伪蒙古军，在绥远、察哈尔及内蒙古西部配合日军作战与统治，其伪军活动范围覆盖鄂尔多斯周边地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1338d362aa14d52b96d4985ef52876d','14368820-3c26-4075-8af7-6d2c436df49e',1933,'率部投降日军','率部投降日军，编入伪蒙古军，在绥远、鄂尔多斯周边地区配合日军作战，镇压抗日力量，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2c99acd42464cca96f4546612a93b92','14368820-3c26-4075-8af7-6d2c436df49e',1933,'率部投靠日军','率部投靠日军，参与组建伪蒙古军，活动于绥远、察哈尔及内蒙古西部，其伪军势力曾覆盖鄂尔多斯周边地区，协助日军镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61fc1d9687ed4d6c9b0154ab44fd4de4','14368820-3c26-4075-8af7-6d2c436df49e',1933,'率部投降日军','率部投降日军，组建伪蒙古军，配合日军进攻绥远、察哈尔等地，参与对鄂尔多斯及内蒙古西部抗日力量的镇压和扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7df6615fb8b84c72b88f61480b74e5e2','14368820-3c26-4075-8af7-6d2c436df49e',1933,'原为东北军军官','原为东北军军官，后投靠日军，在锡林郭勒盟、察哈尔一带组建伪蒙古军，任总司令，参与日军对内蒙古中东部地区的控制与扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d1b9ad2d32dd4e7e9a52b1888ea7ff39','14368820-3c26-4075-8af7-6d2c436df49e',1933,'原东北军军官','原东北军军官，后投靠日军，参与组建伪蒙古军，任总司令，率部配合日军侵占察哈尔、锡林郭勒等地，后任伪蒙疆联合自治政府副主席，是蒙疆伪政权主要军事头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e527c074e4c43e492e09b5eba5d3fe7','14368820-3c26-4075-8af7-6d2c436df49e',1933,'原为东北军骑兵','原为东北军骑兵，1933年投靠日军，在热河、察哈尔、锡林郭勒一带组建伪军，任伪蒙古军总司令，配合日军进攻绥远、察哈尔等地，参与建立伪蒙疆政权。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92a1a3231bbf48ea8b86652040270cb7','14368820-3c26-4075-8af7-6d2c436df49e',1933,'率部在锡林郭勒、察哈尔一带配合日军作战','率部在锡林郭勒、察哈尔一带配合日军作战，参与建立伪蒙政权，其伪军活动范围覆盖太仆寺旗周边地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebedc625da6c4a2b9339ec525feb793f','14368820-3c26-4075-8af7-6d2c436df49e',1933,'原东北军骑兵','原东北军骑兵，后投靠日军，在察哈尔、锡林郭勒一带组建伪蒙古军，配合日军侵占和统治内蒙古中西部，曾任伪蒙古军总司令，活动范围包括锡林郭勒盟地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e8ab6ba9aac436988b74e69c0095e74','14368820-3c26-4075-8af7-6d2c436df49e',1933,'原为东北军骑兵','原为东北军骑兵，1933年投靠日军，在热河、察哈尔、锡林郭勒一带组织伪军。1936年任伪蒙古军总司令，配合日军侵占绥远、锡林郭勒等地，参与百灵庙战役等，后任伪蒙疆联合自治政府副主席，为蒙疆伪政权主要军事头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b3f9618ff894669ad2de72b4ccf8b73','14368820-3c26-4075-8af7-6d2c436df49e',1933,'原东北军骑兵','原东北军骑兵，后投靠日军，在锡林郭勒盟、察哈尔一带组建伪蒙古军，配合日军侵占察哈尔、绥远等地，任伪蒙古军总司令，参与伪蒙疆政权，镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d46096a4b78d4561bb50ff5b33eebaf2','14368820-3c26-4075-8af7-6d2c436df49e',1933,'率部投靠日军','率部投靠日军，活动于察哈尔、张家口及周边地区，参与日军对察南、坝上地区的控制与扫荡，是伪蒙疆政权重要军事头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b2c1f6354b7a4765bcf1a0063858a8d1','125cf33d-649b-4bf2-b302-64b330eb45ce',1937,'包头沦陷后组织维持会','包头沦陷后组织维持会，后任伪绥西联军总司令，在包头、固阳、达尔罕茂明安等地配合日军清乡、掠夺资源。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-593803ae2096432e8163774555d059d6','2e19ea3a-9e8c-4cea-b14d-771b02fab408',1937,'包头沦陷后出面组织维持会','包头沦陷后出面组织维持会，协助日军维持地方秩序，后进入伪蒙疆政权，参与对包头及周边旗县的殖民统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-acf9b84ef4e9461083df34c437729f86','d80a30b0-82a5-491f-a0cf-572b876efe8b',1937,'日军占领包头后出任伪县长','日军占领包头后出任伪县长，推行保甲制，征发劳工、粮食，配合日军对达尔罕茂明安等地的控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ea888a2345e451586234a6fdbda5c03','422beefd-df8f-4d0c-b878-49ad240a3f96',1937,'在固阳及邻近达尔罕茂明安地区推行伪政','在固阳及邻近达尔罕茂明安地区推行伪政，组织伪保安队，协助日军镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f66dd51a2b194226bbf6f77ada02d4cb','ddf460ee-efbd-4e51-9212-034322ef485b',1937,'在萨拉齐及包头周边地区为日军征粮、征税','在萨拉齐及包头周边地区为日军征粮、征税，维持伪政权，间接控制达尔罕茂明安南部一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14003b7d4d324ac4a379e2837a4405f8','465485d3-23f5-4941-9b97-8f144a92270a',1936,'参与百灵庙蒙古自治运动','参与百灵庙蒙古自治运动，后投靠日军，在伪蒙疆政权中任职，活动于包头、达尔罕茂明安等蒙古族聚居区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4377b74481644aaba981e61a490e1ba','b687a983-2c87-44b0-89f7-b7bbe36dcfc3',1936,'协助德穆楚克栋鲁普建立伪蒙政权','协助德穆楚克栋鲁普建立伪蒙政权，在包头及乌兰察布盟各旗包括达尔罕茂明安旗推行亲日政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fac17573ef2747739c61a7a07df918cb','fa3ce66e-8348-44ac-b7f4-b9566a4a66d4',1937,'在日军支持下出任伪乌兰察布盟盟长','在日军支持下出任伪乌兰察布盟盟长，管辖达尔罕茂明安等旗，为日军征发牲畜、物资，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2229d1e5e6644826addb8b0d701ef162','b3aba192-51f8-4fe7-ab97-684044d4755c',1937,'在日军控制下出任伪旗长','在日军控制下出任伪旗长，协助日军在达尔罕茂明安草原建立据点、征收赋税、组织伪保安队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a63b40ba8bb40b6b71769137da72d0b','abeb0918-de5e-4bc7-ba5e-64b20b33e784',1937,'组织伪保安队配合日军巡逻','组织伪保安队配合日军巡逻，监视抗日活动，在达尔罕茂明安及包头北部地区为日军效力。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b08ecb4c4d7457aab376e441d24dd46','5827737f-1b62-4fe9-865a-7ec2bd9b057d',1937,'在包头及周边旗县建立伪警察网络','在包头及周边旗县建立伪警察网络，搜捕抗日人员，协助日军维持殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7e7416eacba4afe96e65363e610ee6d','d74079bb-3ace-432c-8b97-d1783272a818',1937,'协助日军控制包头经济','协助日军控制包头经济，为日军筹集物资、资金，参与对达尔罕茂明安等地畜产品的掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d69652200bf412395254176fffe7c2d','320e5fe8-9e55-4fff-9976-8d7f1966ef2e',1937,'在包头推行亲日奴化教育','在包头推行亲日奴化教育，编写伪教材，向包括达尔罕茂明安在内的周边地区传播亲日思想。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2df40e20c7814bae9b44ce0668c322f8','21feb753-27e1-407f-a624-f48f86220206',1938,'原东北军师长','原东北军师长，投敌后任伪军职，在包头地区参与对抗日根据地的进攻，后因被日军猜忌而反正，但前期有助敌行为。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f017d74488f545ba92bc3e9327b60e73','874b9d27-8116-4861-8d2f-6ffe1f15317e',1939,'在包头市任伪市长期间','在包头市任伪市长期间，推行日伪殖民政策，组织保甲制度，强征劳工，为日军提供物资，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90b675bbe0284dbe8d38844ffa8a011a','2b36d9f6-1e3f-4afc-b161-f9574c18a3b8',1938,'率伪蒙古军在包头周边驻防','率伪蒙古军在包头周边驻防，多次参与对大青山游击队的围剿，杀害抗日干部和群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19e7845bc3a44c32a1d8d9c3db69d8e1','46bb87b5-5dd1-485d-bcf1-9c408aa99fb5',1937,'在青山地区配合日军“扫荡”','在青山地区配合日军“扫荡”，烧毁村庄，掠夺牲畜，强迫牧民迁移，制造无人区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17238108ee964973b238f613d9088f98','46bb87b5-5dd1-485d-bcf1-9c408aa99fb5',1937,'蒙古族军官','蒙古族军官，投日后在呼和浩特、托克托一带驻防，配合日军进行“治安肃正”，屠杀抗日军民，强征民夫修筑工事。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-401ee7fe35da4b69b29b1f91578ea295','46bb87b5-5dd1-485d-bcf1-9c408aa99fb5',1937,'在归绥（今呼和浩特）及周边地区率伪军配合日军作战','在归绥（今呼和浩特）及周边地区率伪军配合日军作战，围剿大青山抗日根据地，破坏地下抗日组织，强征民夫修筑军事工事。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aba3e1027a8648019a9f545271946d2f','46bb87b5-5dd1-485d-bcf1-9c408aa99fb5',1937,'在张家口北部及赤城周边参与围剿八路军游击队','在张家口北部及赤城周边参与围剿八路军游击队，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0cde828d7e544c96a97143720244dccd','3561ad0c-e21c-46c8-9a37-3bed59e670d2',1938,'协助王英指挥伪军','协助王英指挥伪军，参与制定针对大青山抗日游击根据地的军事行动，多次率部袭击抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf44f8c793664bf79e44fe583157752c','7cf1e0d4-5c62-46be-9feb-8524f063fdaa',1936,'协助德王、李守信整编伪蒙古军','协助德王、李守信整编伪蒙古军，参与策划对呼伦贝尔及兴安北省等地的军事控制，为日军提供情报和兵员。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ab79a63bb534702a92b66b980cbb0b7','3b911153-c529-4f8e-9c11-115eaa6bfb3b',1932,'在日本关东军扶植下出任伪兴安北省（今呼伦贝尔大部）省长','在日本关东军扶植下出任伪兴安北省（今呼伦贝尔大部）省长，推行殖民政策，强制收缴民间枪支，组织伪警察镇压抗联和民众反抗。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcddb56ed17c4cb1a9953fe668e69a1d','b5c8f562-5363-47e3-805a-1a029b30fafa',1932,'在呼伦贝尔地区主持伪警务','在呼伦贝尔地区主持伪警务，协助日军搜捕抗日分子，参与“清乡”行动，迫害达斡尔、鄂温克等各族群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98335483570a4d33960b9ce671a13f66','1aabf673-d7ed-44e1-9c7f-42f8c542fcdd',1932,'曾任伪兴安北省省长','曾任伪兴安北省省长，后因对日本关东军不满被日军以“通苏”罪名处决，但其前期在伪职期间执行了日本殖民统治政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5fb1917904284df791302524f1d705df','1aabf673-d7ed-44e1-9c7f-42f8c542fcdd',1932,'曾任伪兴安北省省长','曾任伪兴安北省省长，后因与日本关东军产生矛盾，被指控“通苏通蒙”罪名，于1936年被日军处决，但其前期曾协助日伪建立统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0835f1cfa7946dabf83a0c8e313dcc7','1aabf673-d7ed-44e1-9c7f-42f8c542fcdd',1932,'曾任伪兴安北省省长','曾任伪兴安北省省长，后因与日本关东军矛盾被处死，但前期曾协助日军建立伪政权','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-efee7432da524d989691327554c9ad9b','0e087e57-27ab-41ef-9be9-9e0a7596ab3c',1932,'作为日本驻伪兴安北省参事官（实际为日本人','作为日本驻伪兴安北省参事官（实际为日本人，但此处按历史记录列入），协助日军控制呼伦贝尔行政和军事，镇压抗联三进呼伦贝尔的行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a7c8213ed4b436cbbd4e383b5504c6e','aeadc625-1741-447f-bcd2-bdda771e6f01',1932,'在呼伦贝尔索伦旗（今鄂温克族自治旗）任伪职','在呼伦贝尔索伦旗（今鄂温克族自治旗）任伪职，强迫牧民缴纳“出荷粮”，为日军提供畜力、皮毛等战争物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5297e0c56ad478a9696cf14c0fdd2d6','1a333564-13ff-49f6-b58f-69fa92987d62',1932,'在呼伦贝尔布特哈旗推行日伪“保甲制度”','在呼伦贝尔布特哈旗推行日伪“保甲制度”，组织伪自卫团，协助日军围剿抗联小分队，迫害达斡尔族抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da6c8e2b67c54ad2862646d91264134a','79c116b6-e33c-4905-9ade-51dadeb80363',1932,'达斡尔族','达斡尔族，原为呼伦贝尔副都统衙门帮办，1932年伪满洲国成立后出任兴安北省省长，驻海拉尔，管辖今呼伦贝尔地区。参与伪满地方政权建设，后因在1936年与日本关东军矛盾激化被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76ed5b614a6643e0b57b88539af42da5','79c116b6-e33c-4905-9ade-51dadeb80363',1932,'达斡尔族上层','达斡尔族上层，曾任伪兴安北省省长，驻海拉尔，管辖包括新巴尔虎左旗在内的呼伦贝尔地区，后因与日本矛盾被处决','危害等级A（甲级，省部级/大军区级要员）','hanjian');
