INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-731a71a52f0948aaaa30e992e645d2a0','dac402ad-8d6a-4dbe-81e4-989f610ebc90',1932,'蒙古族上层人物','蒙古族上层人物，九一八事变后投靠日本，参与策划内蒙古独立活动，任伪满洲国兴安南分省省长、兴安局总裁等职，组织伪兴安军配合日军在呼伦贝尔及内蒙古东部地区进行统治和镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1565c7587d3d41b5857fe5cca45ced97','c22f3599-beae-42be-a1b2-ae6d25b2cc66',1930,'甘珠尔扎布之弟','甘珠尔扎布之弟，投靠日本，在伪兴安军中任职，参与日军在呼伦贝尔地区的军事行动和对当地蒙古族民众的控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0c726c8f8584936b8d446eab3b44f34','c22f3599-beae-42be-a1b2-ae6d25b2cc66',1930,'甘珠尔扎布之弟','甘珠尔扎布之弟，投靠日本，在伪兴安军系统任职，参与呼伦贝尔地区的伪军活动，协助日军控制地方。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5725ad727e354668874d0312fc5fd520','c22f3599-beae-42be-a1b2-ae6d25b2cc66',1930,'甘珠尔扎布之弟','甘珠尔扎布之弟，参与伪兴安军组建，配合日军在呼伦贝尔地区镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6fd9c3796ea24fc3858954e01f816b52','c22f3599-beae-42be-a1b2-ae6d25b2cc66',1930,'甘珠尔扎布之弟','甘珠尔扎布之弟，投靠日本，在伪兴安军任职，参与日军对呼伦贝尔及内蒙古东部地区的统治和军事行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc191d4cac474618a3422eb3de51c37f','2dec6f50-6499-42b7-9e27-75d8702860e5',1932,'呼伦贝尔地区蒙古族上层','呼伦贝尔地区蒙古族上层，投靠日本，在伪兴安北分省任职，参与伪政权对呼伦贝尔各旗包括新巴尔虎右旗的统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf71563643e14ec8b4acab6110618020','5cf4fce4-c826-4d14-a505-a387d8ebaeed',1930,'在新巴尔虎右旗担任伪旗长','在新巴尔虎右旗担任伪旗长，听命于伪满洲国兴安北分省，协助日军和伪政权在当地推行保甲制度、征收物资、控制牧民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e2b90cebf054c48b85f47bfda050ef7','233f37e1-1b7d-4403-9786-a57abdb744eb',1930,'在呼伦贝尔地区担任伪警备队军官','在呼伦贝尔地区担任伪警备队军官，配合日军维持治安，镇压抗日活动，活动范围覆盖新巴尔虎左右旗一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d054a89a4b884f62b82a78cd4b961386','d44e0bf8-14bc-4ba1-a576-ed72420445fb',1930,'曾任伪兴安北分省警备队司令','曾任伪兴安北分省警备队司令，驻海拉尔，统辖呼伦贝尔地区伪军，参与对苏蒙边境的警戒和对当地抗日力量的镇压。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21df54b3a4ab4a9d9ae262ab4bc4da0d','510d085d-8eb9-470f-85fa-910f19f97c4c',1932,'呼伦贝尔地区蒙古族上层','呼伦贝尔地区蒙古族上层，参与组织伪维持会，协助日军接管地方政权，在新巴尔虎右旗等牧区推行伪政权的政策。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-517daafdcc7c422f8f91ee224700ce8f','7363344e-9721-49ec-a3e6-ef0eb6dc0659',1930,'在新巴尔虎右旗担任伪警察署长','在新巴尔虎右旗担任伪警察署长，负责当地治安，协助日军征用牧民牲畜、物资，监控牧民行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ff066ee570d4fbaab7cc07cf6af4112','f178ff02-ca5d-488f-b90b-49e0f7147334',1930,'在呼伦贝尔地区担任伪教育官员','在呼伦贝尔地区担任伪教育官员，推行奴化教育，向蒙古族青少年灌输亲日思想，活动范围包括新巴尔虎右旗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4dac955c69e447278c944bd67df42fab','41d3041b-a016-4773-af3d-2f60af3dd35f',1930,'蒙古族上层出身','蒙古族上层出身，早年参与策划内蒙古独立活动，后投靠日本关东军，在伪满洲国任职，参与组建和指挥伪兴安军，配合日军在呼伦贝尔及新巴尔虎左旗一带维持统治、镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96422f85c10240e1a153855894f5f48f','539c3826-7773-496c-aeda-25615213a669',1930,'继凌升后任伪兴安北省省长','继凌升后任伪兴安北省省长，继续在海拉尔及呼伦贝尔地区为伪满洲国和日本统治服务。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18dbae30bf824e169a0fe43b372f0bc2','4f3d845d-95da-47cd-a691-a0185d47c564',1930,'在伪兴安军系统任职','在伪兴安军系统任职，参与呼伦贝尔地区伪军警活动，配合日军维持地方治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
