INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b2812fb42b4c4cc4918e7bb8e673d0ea','2ff36c36-86d9-4d62-a256-f0c16b5283e0',1932,'在伪满统治下','在伪满统治下，参与推行殖民政策，强征劳工，配合日军“讨伐”抗联小部队，并参与对鄂温克、鄂伦春等民族的监控。具体姓名未见于公开史料。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdd1a033d59f4a46a1df9ea607eaa3e4','653cee88-06a2-4ed2-9e40-c707c509b21c',1932,'任伪满海拉尔市市长期间','任伪满海拉尔市市长期间，推行日伪殖民政策，协助日本关东军镇压当地抗日力量，强征劳工修建军事设施。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4827e1fc6d5f4d6da79cd4695fe6b8c7','75675157-8e86-4aa1-a56f-ab8c357e765b',1932,'作为蒙古族上层投靠日本','作为蒙古族上层投靠日本，任伪兴安北省省长，配合日军在呼伦贝尔地区实施“治安肃正”，迫害抗日志士，强制推行奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
