INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3f5f7a2b47e45c297b7d2d5cc5d6ae6','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'北洋政客','北洋政客，抗战期间投敌，主持伪华北政务，推行保甲、治安强化运动，其伪政权体系覆盖山东聊城、茌平等地，征粮征丁，镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
