INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f219f3f1c80d4c5db31fa4a5169032d0','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'安徽合肥人','安徽合肥人，北洋旧官僚，抗战期间投敌，在华北伪政权中任要职，配合日军掠夺资源、镇压抗日。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
