INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1de9ab6e59434b6e8fb7fd2d6f1078cc','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'作为华北伪政权最高头目','作为华北伪政权最高头目，其统治范围涵盖廊坊地区，支持日军“三光政策”，并组织伪军配合扫荡。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01217d76149d4bd5a5e0b6169090a075','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'作为华北伪政权最高头目','作为华北伪政权最高头目，其统治范围覆盖廊坊经开区，推行奴化政策，协助日军征粮征兵。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7844dd4c45f4ab48557a3c6a2761769','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'统辖华北伪政权','统辖华北伪政权，包括河南部分地区，推行奴化教育，征敛物资支持日军。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a92a1bba47a54675b52200fc745d615f','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'华北伪政权头目','华北伪政权头目，其政令覆盖河南部分地区，推行治安强化运动与物资统制。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ecc69ad67b345758a512c3ca731b541','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'安徽合肥人','安徽合肥人，抗战期间投敌，任伪华北政务委员会委员长，管辖包括河南在内的华北地区伪政权，推行奴化教育、经济掠夺，对河南民众造成深重灾难。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61e2e1f8575f472a94c66f2aa8338355','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'虽驻北平','虽驻北平，但其伪政权统辖河南，开封伪政权受其节制，推行华北伪化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9b6c50170d54ab6869f15e99956ce84','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'虽主要在华北活动','虽主要在华北活动，但其伪政权体系影响波及湖北部分沦陷区，参与日伪统治与资源掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1be96f894a04cd9870ea51966a4b3e6','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'华北伪政权头目','华北伪政权头目，其伪政权体系与湖北伪政权有联系，参与日军对沦陷区的整体统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ade9df3d0d8430b9e4d8c19554a3473','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'安徽合肥人','安徽合肥人，北洋旧官僚，抗战期间投敌，任伪华北政务委员会委员长等职，其活动虽主要在华北，但与湖北黄冈地区无直接关联，仅作为湖北籍相关汉奸背景列出。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-285401784b8d452db626cbd3a0e12db9','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'伪华北政权头目','伪华北政权头目，其伪化政策与湖南沦陷区伪政权有呼应，间接影响岳阳地区伪统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce74d3d7efe645649277ca674b499501','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'安徽合肥人','安徽合肥人，抗战期间投靠日军，历任伪华北政务委员会委员长等职，在华北地区推行伪化统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59581649afc04dfdbb2dba62fd5308e5','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'其伪政权曾向贵州派遣密使','其伪政权曾向贵州派遣密使，拉拢地方军阀，息烽附近有其联络人员出没。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d991c322fd746f5ba8da544b8a9d21a','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'在华北伪政权中任职','在华北伪政权中任职，推行日军侵略政策，其伪政权体系延伸至陕西沿黄河地区，对榆林、府谷一带进行政治渗透。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01ddfec3c49f47e88228591b309d1f5a','6e0aee36-420b-48bd-8d41-306c2daca760',1937,'长期在华北伪政权中任职','长期在华北伪政权中任职，配合日军推行治安强化运动，镇压抗日力量，其伪政权体系对陕西周边及华北地区有影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f42a237ddb9d4729b8d51c932c7281b9','406d9e9a-8ca0-4847-80e1-e212f259787c',1930,'即德穆楚克栋鲁普','即德穆楚克栋鲁普，内蒙古最重要的附逆头目之一，建立伪蒙疆政权，配合日本统治内蒙古。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3305ff314cd04628ae15d7408f55b9ab','5ba0858a-a45d-44d7-9439-429c65c690ff',1932,'曾任伪满洲国兴安北省省长','曾任伪满洲国兴安北省省长，在呼伦贝尔地区推行日伪殖民统治，协助日本关东军镇压当地抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e15a332e33034a348fcb239c5b7c3c00','33abecc7-54f2-474c-a952-6a90c2a82fe3',1932,'初期投靠日本','初期投靠日本，任伪兴安北省省长，后因反对日本移民政策及秘密联络抗日势力，于1936年被日本关东军以“通苏”罪名处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bfc8e228414c4bba9ad16a83ea45c4e8','33abecc7-54f2-474c-a952-6a90c2a82fe3',1932,'原呼伦贝尔副都统','原呼伦贝尔副都统，初期投日任伪省长，后因暗中支持抗联及蒙古独立运动，被日军以“通苏”罪名处决于齐齐哈尔。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-052a624d5f38422b96238ec87955ec27','581a8550-9267-45eb-95fd-e348886912e6',1932,'在呼伦贝尔地区担任伪警务厅长','在呼伦贝尔地区担任伪警务厅长，协助日本宪兵队搜捕抗日分子，镇压牧民反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f60fe9977924b31ab028e06cf58f421','9d9aad89-69a7-4dba-ade0-02bd9cd042dd',1932,'参与伪满政权在呼伦贝尔的行政事务','参与伪满政权在呼伦贝尔的行政事务，为日军提供当地情报，协助推行“治安肃正”政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1726d5a313f845e6aa48b3d3ab4e008a','6e3c8dad-e187-4583-bb18-9df0b2c11d07',1932,'在莫力达瓦地区任伪旗长','在莫力达瓦地区任伪旗长，强制征收粮食和牲畜，为日军提供物资，镇压当地达斡尔族抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b16283cc5d1400d8d5f6e8271c750c7','a0633266-5d90-4463-a1bf-9ab19d6d1ea5',1933,'在莫力达瓦旗组织伪警察','在莫力达瓦旗组织伪警察，协助日军清乡，逮捕并杀害抗日地下工作者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6763ee74c4e64ed2823a28d2c1969bee','56518057-99bc-431a-9a61-89ccfd60550c',1932,'在呼伦贝尔地区指挥伪军参与“讨伐”抗日游击队','在呼伦贝尔地区指挥伪军参与“讨伐”抗日游击队，烧毁村庄，掠夺财物。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e3cf1c777f044dc9c2e4b3e5b29afb9','376c778a-f274-4b54-ad6b-065517f2edc1',1935,'负责为日伪政权征收苛捐杂税','负责为日伪政权征收苛捐杂税，强征劳工，导致当地民众负担沉重。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-956066a884984097b2dd1fc252a73742','feb6b404-a8b8-451f-b293-23a21557d1b7',1930,'蒙古族上层人物','蒙古族上层人物，投靠日本关东军，参与策划内蒙古独立活动，在伪满洲国任职，协助日军控制呼伦贝尔及内蒙古东部地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03f4b437b46e46a891a7665e445cd2a4','0c8984ed-1aad-49df-b205-62d1fa905d97',1930,'达斡尔族','达斡尔族，在伪兴安军任职，后任伪第十军管区司令，驻防呼伦贝尔，配合日军维持统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cfc5a1fd59984dd79470a90036496fd6','40b380fe-dded-4707-8238-8addee5c8224',1930,'在伪兴安北省警备队任职','在伪兴安北省警备队任职，参与维持呼伦贝尔地区治安，协助日军镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-114e24889c574f1b89c0dd6f669b7812','8dba7fc9-938e-47b7-92ff-018897128482',1930,'在呼伦贝尔地区组织维持会','在呼伦贝尔地区组织维持会，协助日军占领和控制地方。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00f23508728d48b8ad09f22d27009a8c','8dba7fc9-938e-47b7-92ff-018897128482',1930,'在呼伦贝尔地区参与伪政权维持会活动','在呼伦贝尔地区参与伪政权维持会活动，协助日军征粮、派夫和治安控制。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9952402baca5406f9ac8f63953b97fb8','aa378dc8-6326-4842-be09-9a0ef16d17d3',1931,'蒙古族上层人物','蒙古族上层人物，九一八事变后投靠日本，参与策划内蒙古东部地区所谓‘自治’，在伪满洲国任职，协助日军控制呼伦贝尔及兴安地区，组织伪军警镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd5e740f2f1c4cbaa5957c82c8e5c06e','292c8614-1aa2-4d04-b7f6-fa22228c139f',1930,'在伪兴安北省任职','在伪兴安北省任职，参与日本对呼伦贝尔地区的殖民统治和基层控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe9d4b97c9034c9089d86359aa3ef9e5','3f76a666-b30f-4f59-b55d-83a014ed0754',1930,'在伪兴安军任职','在伪兴安军任职，参与日军在呼伦贝尔地区的军事行动和治安肃正。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a64876aa63c4671a353c47df96034cc','6c7b2633-dc8a-4285-a115-732f3ae58a6c',1930,'在伪兴安北省警察系统任职','在伪兴安北省警察系统任职，协助日军镇压呼伦贝尔地区抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff2050826e694ab1b91c202e15b0ee78','7146e66a-b1e6-4b19-9caf-2f59e6b2585b',1930,'在阿荣旗地区担任伪警察头目','在阿荣旗地区担任伪警察头目，配合日军和伪兴安军对当地抗日武装进行搜捕和镇压。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7f215fffa2640a898d21fbc44058020','b7d65ab1-5444-488c-be33-34674709b76a',1930,'在阿荣旗基层担任伪保长','在阿荣旗基层担任伪保长，协助日伪政权征粮、抓丁、监视民众，维持殖民统治秩序。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ae4ac72ae0f465a8b96903d73099f6b','42c49862-8b6f-4840-a174-32c6d70c0a31',1930,'在呼伦贝尔地区组织维持会','在呼伦贝尔地区组织维持会，协助日军接管地方、维持治安和征集物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22e4103d85b04b33bcabccf1bcd6b95c','991cedb3-480b-4948-af79-d70212a8cbf8',1932,'在陈巴尔虎旗及呼伦贝尔地区推行日本殖民政策','在陈巴尔虎旗及呼伦贝尔地区推行日本殖民政策，协助日伪政权统治当地蒙古族牧民，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05a0e07742d5435a933188dab12a0a2a','563908d5-68a1-441f-a331-fca58f256ed3',1932,'初期为日伪效力','初期为日伪效力，后因与日本关东军产生矛盾被处决，但此前在陈巴尔虎旗地区执行过日伪行政命令。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55662226c4c2402782e797689340c4de','63397d5b-acfb-4d2c-8b04-de65f1614c94',1930,'在陈巴尔虎旗地区组织伪警察力量','在陈巴尔虎旗地区组织伪警察力量，协助日军清剿抗日武装，抓捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44c8209ffcc54b6993c73ea0c230e276','310272b1-6d82-4cc5-8cce-e74e121cf793',1932,'作为伪旗长','作为伪旗长，直接执行日伪征粮、征兵及“治安肃正”政策，压迫当地牧民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-edf5de3191f84851a663a341ddabc3ff','4a8b3c33-91b6-4221-93da-69de7035ca94',1930,'协助日军在陈巴尔虎旗建立情报网络','协助日军在陈巴尔虎旗建立情报网络，参与镇压当地反抗活动。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4515b98410db4fe8a6a683bda9dca9a5','c0188fa4-b55b-4025-a323-0d3be49db572',1932,'呼伦贝尔地区（今额尔古纳市及周边）的蒙古族上层','呼伦贝尔地区（今额尔古纳市及周边）的蒙古族上层，任伪满兴安北省省长，协助日本关东军管理额尔古纳河沿岸防务，镇压当地抗联及牧民反抗。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-370646a133c44d9ca0c36de0e8888871','c6a234f5-4eb0-42d4-833d-c168e260a1c3',1932,'呼伦贝尔索伦旗贵族','呼伦贝尔索伦旗贵族，初任伪兴安北省省长，后因与日本关东军矛盾被处决，但其任职期间曾配合日军清剿额尔古纳地区抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47f0659a275c476e8ab0765290c6ae76','69ad8227-f0b3-418c-b477-5bbf8f51554a',1932,'呼伦贝尔籍','呼伦贝尔籍，在额尔古纳及三河地区组织伪警察，协助日军搜捕抗联地下人员，参与“讨伐”苏联间谍网络。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa659a96981e469ca2b48e899318a5de','61c76d93-134c-4b19-b2aa-c0197300ffe4',1935,'额尔古纳本地蒙古族头人','额尔古纳本地蒙古族头人，投靠日伪后任旗长，强制推行“粮谷出荷”，为日军提供物资，并举报抗日民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90c75f5b8fa84d2c98ecdee5b6c60eaf','4885b2b0-144e-4207-913b-8c6f099d5cad',1937,'在额尔古纳河右岸地区协助日军建立“集团部落”','在额尔古纳河右岸地区协助日军建立“集团部落”，隔离民众与抗联联系，参与迫害苏联侨民及抗日嫌疑者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33ae6f9116cb451fab4a782cb0dc74af','1ad0de7d-8844-495b-bdc9-9f7703e2544e',1938,'呼伦贝尔籍达斡尔族军官','呼伦贝尔籍达斡尔族军官，率伪兴安军驻防额尔古纳地区，参与对苏边境侦察及镇压当地抗联小分队，后于1945年反正。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-980a20459d9d4931bbd3671c9b34044c','048589f4-13c7-44dd-bafa-78bcb7bd19c3',1940,'汉族','汉族，原为地方土匪，投靠日军后任保安队长，在三河、室韦一带抓捕抗联交通员，协助日军建立“防谍网”。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61050db503944e2e984e860204cfd910','a37163bc-5c67-453f-b363-33a2e45e2dcc',1939,'朝鲜族','朝鲜族，在额尔古纳地区残酷镇压抗日活动，多次带队突袭抗联宿营地，并参与“特别治安”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1cc86625756c4ace8534affa708bb32a','bfbd4655-8ed1-4e58-a9f8-a047b5361dbd',1936,'德王心腹','德王心腹，参与伪蒙政权组织与运作，协助日军管理内蒙古地区，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce5186891423461db3f31fbdd5ad5e3f','f7ed0dbc-98cd-40b5-af87-bbd0e48f0973',1936,'蒙古族上层','蒙古族上层，投靠日本，负责伪蒙政权财政与经济掠夺，为日军侵华提供物资支持。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3004d6670cbe46ac8b60300420a233fa','8bdfd5a9-9c18-4387-93df-9e711b6a1b70',1936,'原地方武装头目','原地方武装头目，投日后任伪蒙古军高级军官，参与进攻绥远抗日部队，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77d54fd498e0415085b06d4aa78ba16e','8bdfd5a9-9c18-4387-93df-9e711b6a1b70',1936,'率伪蒙古军驻防绥远及新城一带','率伪蒙古军驻防绥远及新城一带，多次参与日军对抗日游击队的“扫荡”，在归绥周边制造多起屠杀事件。','危害等级B（乙级，市县厅局级）','hanjian');
