INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b2809f3256046bba748d600dcbcbc95','d5248da9-6a6e-4a4c-9563-7046049ab2ef',1937,'原绥远警察头目','原绥远警察头目，投日后任伪警务厅长，协助日军搜捕抗日人士，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17f4b3bfcaae45649bff30e5197f0aa6','0b789cd2-e6b9-428d-93b1-37438830587d',1937,'投靠日军','投靠日军，任伪归绥（今呼和浩特）市长，推行日伪政令，强征劳工，搜刮民财。','危害等级B（乙级，市县厅局级）','hanjian');
