INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6845ead0f324499ba33737a27a47976e','9b47fb14-1948-4627-80b9-93c0a80521fa',1938,'原绥远地方官僚','原绥远地方官僚，投日后任伪蒙疆司法部长，制定镇压抗日法令，迫害进步人士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
