INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f754265337e42a7b8b0446535ad1e4c','499c3a48-9bd9-4789-9d50-c562de8a03ed',1937,'投日后管理伪绥远民政','投日后管理伪绥远民政，推行日伪保甲连坐制度，迫害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c0b541943be42cf94669cf969ec6624','859ef4c7-0cdc-4d59-b369-f893fc1dfdcb',1939,'原晋军军官','原晋军军官，投日后协助王英指挥伪军，进攻大青山游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f0642cbe2794d88bb2b7ae3e4234f1d','cedb2f2d-5ca9-4d2d-807d-5262102efbc1',1937,'在归绥市任职期间','在归绥市任职期间，为日军搜捕抗日志士，镇压民众反抗，协助维持伪政权治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1228693241214e79bd864a268b781222','c85429d5-e390-407c-9435-05c554153d55',1938,'任伪归绥县知事期间','任伪归绥县知事期间，强征民夫、粮食供日军使用，推行保甲制度，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d841e5f44ffb4e6793891c4435547efe','1bec55f5-d521-440e-8a8b-3dca687ce518',1939,'原晋军军官','原晋军军官，投日后在绥远省公署任职，参与策划对抗日武装的围剿行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02a8ca149d284cc99d5c39746b868cc8','096f88b4-4451-48ff-b560-29ae85e78321',1936,'锡林郭勒盟苏尼特右旗人','锡林郭勒盟苏尼特右旗人，在日本支持下先后建立伪蒙古军政府、伪蒙古联合自治政府，定都归绥（今呼和浩特），统治包括和林格尔在内的绥远地区，推行亲日卖国政策，征粮征兵，镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-443744efd0d644b39e09c027ce11fb85','f3ca9518-20a8-4db0-af3b-799ac63d8491',1937,'原为察哈尔省商人','原为察哈尔省商人，日军占领张家口后组织维持会，后任伪察南自治政府最高委员、伪蒙疆政府副主席，参与伪蒙疆政权对绥远、呼和浩特地区的统治与经济掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e390230ddc647de86b40488d06eb7c2','06f01a98-b289-48f7-9590-87821637a555',1937,'原为山西大同地方士绅','原为山西大同地方士绅，日军占领大同后组织维持会，后任伪晋北自治政府最高委员、伪蒙疆政府副主席，配合日军在绥远、内蒙古中西部推行伪化统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2e88dbc1257459a9eeeb5ac9f06a5af','a3c7f1c1-ff57-4f30-b6a2-5e6a8ff02836',1937,'在伪蒙古军中任职','在伪蒙古军中任职，率部驻防绥远地区，参与对呼和浩特周边及和林格尔等地的控制与扫荡，配合日军维持伪蒙疆政权统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88825dd329144d93ab5d8f82c4ce7e7c','6e4758f6-010a-461b-a6ec-fd8e5d60d775',1937,'伪蒙古军高级将领','伪蒙古军高级将领，率部在绥远地区活动，参与日军对绥远抗日根据地的扫荡，控制呼和浩特及周边旗县。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f9ef62998c745b49042b79c8cf89b6d','97ba5589-2645-421a-beef-ecd47dddd7a9',1936,'内蒙古东部人','内蒙古东部人，参与伪蒙古军组建，任参谋长等职，协助德穆楚克栋鲁普和李守信推行伪蒙疆政权，在绥远地区进行亲日宣传和军事镇压。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47e1dd9db7d646e3976938e7166673fb','366dff3c-b21c-4715-9585-62798520ba99',1936,'原为内蒙古地方知识分子','原为内蒙古地方知识分子，投靠日军后参与伪蒙疆政权，负责文教、宣传等事务，在呼和浩特等地推行奴化教育，为伪政权培养亲日人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86432ca856834ea9936958283efc7346','8594ebf9-c8f2-4b73-9bba-bd4815e78075',1936,'参与伪蒙古军和伪蒙疆政权','参与伪蒙古军和伪蒙疆政权，负责政治宣传和情报工作，在绥远地区配合日军镇压抗日力量，推行伪化政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-128f1fe017aa4defbfa868172d351ee6','f737fc10-4579-4e5e-b3dd-691d04cb1a31',1936,'伪蒙古军将领','伪蒙古军将领，率部在绥远、察哈尔一带活动，参与对呼和浩特周边地区的控制，配合日军扫荡抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05d7e6a2207b4e01a0e5f1eda69350d3','e9c00539-cc78-48bc-bf4a-d08059febc21',1937,'和林格尔本地士绅','和林格尔本地士绅，日军占领和林格尔后组织维持会，任会长，协助日军征粮、征夫，维持地方伪秩序，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3037d8389044a048b3af470d0e5aca2','357fb418-51c9-4a72-8235-fef3990b49e0',1938,'在伪蒙疆政权下任和林格尔县县长','在伪蒙疆政权下任和林格尔县县长，推行日伪政令，配合日军清乡、扫荡，搜捕抗日人员，压迫当地民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2274e650afc4621ba01c1ed514b0e6d','48b2c37f-ff06-437d-b396-d8ab2edd7a37',1937,'归绥（今呼和浩特）地方士绅','归绥（今呼和浩特）地方士绅，日军占领归绥后组织维持会，后任伪县公署官员，协助日军管理地方，征敛物资，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0a8d3d2d1344912b1d5a9bd88c98213','ab568057-f9a1-42ed-ad8f-c470a8dc6ad6',1937,'归绥商人','归绥商人，投靠日军后任伪商会会长，配合日军经济统制，为伪政权筹措物资，剥削当地商民，支持日伪统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c3e54f5dfcb4241bbeee0890b0787c7','7faec978-94f1-4fca-b8e2-3fa68f5eeb14',1937,'在伪蒙疆政权下任归绥市警察局局长','在伪蒙疆政权下任归绥市警察局局长，负责搜捕抗日人员，镇压市民反抗，维持日伪治安，残害无辜群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-081c0b807c574aaa8720e3b3c86d7d97','d9de6440-5481-4176-8da4-f1c0a3851ae0',1937,'在伪蒙疆政权下负责教育事务','在伪蒙疆政权下负责教育事务，在呼和浩特等地推行奴化教育，篡改教材，灌输亲日思想，毒害青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a674b2d74ff4c8da0e5b6efd0f0b234','536931ae-0f02-4591-ac73-3706adc3fea6',1937,'托克托县地方士绅','托克托县地方士绅，日军占领后组织维持会，后任伪县长，协助日军控制托克托及邻近的和林格尔地区，征粮征夫，镇压抗日。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60eedcd2500b449b8f0478bbb2ba86c9','14dba760-86de-4e73-b487-3e2d0ab79ab5',1937,'萨拉齐（今属包头）地方士绅','萨拉齐（今属包头）地方士绅，投靠日军后任维持会会长、伪县长，配合日军在绥远中部地区的统治，影响波及呼和浩特周边。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f66d53682ce841148e5fdfcaf7757846','2455100d-9fe4-49d3-9227-d1c7cdaef309',1937,'清水河县地方士绅','清水河县地方士绅，日军占领后组织维持会，任伪县长，协助日军控制清水河及邻近的和林格尔地区，征敛物资，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b09bcad16ba4bb3809c7766a01fd9a0','c27fea93-c9b8-492a-ae94-1536f16c23ae',1939,'在呼和浩特及土默特地区为日军搜集情报','在呼和浩特及土默特地区为日军搜集情报，破坏地下抗日网络，参与对回民商号的敲诈勒索，强征回民青年入伍伪军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-871fdede1ccf428c888e5f26ae33d724','2499061f-102c-4233-bde7-82e1b64246a9',1938,'在呼和浩特（归绥）任伪警察局长','在呼和浩特（归绥）任伪警察局长，专门搜捕抗日分子，在回民区设立特务据点，多次逮捕并刑讯回民爱国人士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-103d99e72f2d481d806f00b766546a8e','6277bae5-1944-47b9-b853-8c52130922e6',1940,'任伪归绥县知事期间','任伪归绥县知事期间，推行日伪“治安强化运动”，在回民乡村实行连坐制，强征粮食，导致大量回民饿死。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9e9bab725344ba19449a9c1e568dedc','5b0bde3d-2c4e-4824-ae1c-2cbff4d79653',1937,'土默特左旗贵族','土默特左旗贵族，在伪政权中负责地方行政，强征民夫和粮食供日军使用，破坏当地抗日地下组织。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc3d173664b540268ea7d6e4ad257e5c','5b0bde3d-2c4e-4824-ae1c-2cbff4d79653',1937,'在乌拉特前旗及河套地区推行伪蒙疆政策','在乌拉特前旗及河套地区推行伪蒙疆政策，组织保甲制度，强征民夫和粮食供日军使用。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fdb1fd9b5e5447369e718324435a301d','736fde5e-cb12-4988-b40c-d1b0e8482115',1940,'协助日军推行保甲制度','协助日军推行保甲制度，强迫村民报告八路军行踪，导致多名地下党员被捕牺牲。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4aafe16202d41d9a9572843e8773043','d3cb0d56-13dc-447e-8858-1ba23aa567e3',1937,'土默特左旗人','土默特左旗人，早年参加抗日，后叛变投日，参与围剿绥远抗日游击队，后因内讧被日军处决。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ea425b09f394e7da0d64bdc332db40e','12435150-4684-464b-9fec-d09ca4756292',1941,'原晋军将领','原晋军将领，投日后在土默特左旗一带收编土匪，配合日军封锁抗日根据地，劫掠百姓财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fdf3104b874e41059c827a9c16e08fde','b18daf21-ff4d-4713-8198-74e9a858b038',1942,'亲自带队搜捕抗日分子','亲自带队搜捕抗日分子，严刑拷打嫌疑人员，向日军提供大青山游击队活动情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c5a1107a61642a48f7bf59190e2991b','0f18a1eb-a453-4d91-86fc-2815ab62846f',1943,'在土默特左旗西部驻防','在土默特左旗西部驻防，多次袭击抗日武工队，杀害地方抗日干部，强征壮丁补充伪军。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f3325a1a83f4ffdbc92fb0d0ac661d1','94c9459b-6d21-423c-a79f-727b30eb5982',1937,'在绥远地区率伪军参与对抗日根据地的围剿','在绥远地区率伪军参与对抗日根据地的围剿，曾在托克托县境内烧杀抢掠，破坏地下抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef91b4470d0e4a47b311015f11edd55a','9398f4bc-dfd2-4d4b-85db-5fcbc95d31d6',1937,'在托克托、和林格尔一带率伪军骚扰抗日武装','在托克托、和林格尔一带率伪军骚扰抗日武装，为日军提供情报，参与“清乡”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8a63f771b5f406a9186cc51e6cb4a3c','529eb96d-085d-420f-a629-e7de102fe3bb',1937,'在呼和浩特任伪警务要职','在呼和浩特任伪警务要职，组织伪警察协助日军搜捕抗日地下党员，镇压学生和民众反日运动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fccd2b1b86342728c2f92c6819e1ddc','c2290099-d048-4e94-bad8-af43a253dbf0',1938,'投靠日军任伪县长','投靠日军任伪县长，在托克托县推行日伪法令，强征苛捐杂税，出卖抗日分子，协助日军建立维持会。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a63cac5f4204ab5bfe9313d2eaa0ba9','38dc1ad4-fe70-4675-ba92-1f0466e65c6c',1939,'任伪厚和豪特市市长期间','任伪厚和豪特市市长期间，为日军征集劳工、粮食，压制市民抗日情绪，配合日军特务机关监控居民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e011e1459fc4d6fb04792997deb7bda','19b09502-0129-44e1-8635-f66ec26a99fc',1939,'率伪保安队多次袭击托克托县境内的抗日游击队','率伪保安队多次袭击托克托县境内的抗日游击队，杀害抗日家属，抢劫村庄，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1485851e517c43feb1136c2461bb8625','55759f39-caaa-4e7f-876a-db5b6481b780',1938,'在呼和浩特参与伪政权行政事务','在呼和浩特参与伪政权行政事务，协助日军推行“保甲制度”，参与镇压大青山抗日游击根据地活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f854935ffaa4cabaae637c7e1084c27','4d8c481e-1784-4cef-a4a8-5ca7675cdfc5',1940,'在托克托县任伪警察署长','在托克托县任伪警察署长，抓捕抗日地下工作者，严刑逼供，并参与日军对农村的扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a82ca4d16638458990582d7e42e72773','b43c54fd-c8cf-4fb8-b891-12682ec05149',1937,'在呼和浩特、托克托地区驻防','在呼和浩特、托克托地区驻防，多次率部进攻八路军大青山支队，杀害抗日干部和群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e3991019c3a4dddab028bfc149e49e1','c79b0adc-c6e6-40e8-bdfb-b52fae190edf',1937,'在呼和浩特新城地区主持伪政权日常行政','在呼和浩特新城地区主持伪政权日常行政，配合日军推行“以华制华”政策，强征劳工，搜刮粮食，迫害抗日家属。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2d6c8957d6a40d58a78fe4552aaf177','964d7ea5-0d7b-4b9d-9a65-e72c4508b788',1939,'在呼和浩特新城地区协助日军管理民政','在呼和浩特新城地区协助日军管理民政，推行保甲制度，强迫民众领取“良民证”，举报抗日分子。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79f668ef59eb4792bed3af5d3a439b13','bb9e3af5-7855-492b-a376-943e5a0e2ea1',1941,'原国民党将领','原国民党将领，被俘后变节，在归绥新城为日军出谋划策，参与策划对抗日武装的围剿行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f97bda79d2bb4aefba77051b95d29d99','08df3ee5-6984-4acc-9c6a-38c7ffa03f92',1938,'在呼和浩特新城地区指挥伪警察','在呼和浩特新城地区指挥伪警察，协助日军特务机关搜捕抗日人士，多次破坏地下抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81fa3f5b51144b4094523bf2f5e9f375','54a751c4-3c7f-4efc-a323-807162bc4975',1940,'在新城地区推行日伪法令','在新城地区推行日伪法令，强征民夫修筑军事工事，克扣配给物资，导致当地民众生活极度困苦。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f8179c1b6b347d69db3dd5233083888','1802a4fb-0e51-498f-8ee8-63f9b7be20b3',1937,'在武川、四子王旗等地协助日军建立伪政权','在武川、四子王旗等地协助日军建立伪政权，组织伪警察队，抓捕抗日地下工作者，强征牲畜粮食供给日军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ea293c0e3c74a59b4445d7f07b8971d','90a6fe3d-4e0e-4795-bee5-c8409971b5cf',1938,'在呼和浩特及清水河地区建立日伪警察网络','在呼和浩特及清水河地区建立日伪警察网络，搜捕抗日地下人员，参与“大检举”行动，致使多名抗日志士牺牲。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5504a8405d9b4c35b0d3cbb0f3bf956f','86d831b7-7082-425e-8c30-3d81dcbbefd3',1938,'在清水河县推行日伪统治','在清水河县推行日伪统治，强征粮食和壮丁，组织汉奸情报网，向日军报告抗日武装动向，导致多起袭击事件失败。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d46dea2ee0e448e98d55c780f39c3d4','673d0735-c15a-47b1-b3fe-e6a675faa2ea',1939,'率伪保安队配合日军“扫荡”清水河山区','率伪保安队配合日军“扫荡”清水河山区，杀害抗日游击队员及家属，抢劫财物，破坏地下交通线。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc8cc9d4ac2e4e9ea13df3f32f16b8c1','c62b3fcb-dbfd-4194-8cff-4cdcea5d0d1a',1940,'参与日伪市政管理','参与日伪市政管理，协助日军推行“保甲连坐”制度，举报抗日嫌疑分子，致使数十人被捕入狱。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16b0bc963ef64aa8b4dfa59aeeea8241','9061800c-5b58-4def-8eb3-9a3b606a3fc9',1939,'原为晋军军官','原为晋军军官，投日后在清水河、和林格尔一带活动，率部袭击八路军小分队，并参与日军“三光”政策行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f28cb7db6d645ca9daeb23e6420917b','c8cf27c1-c0d1-4655-b1bb-52a525a4a4ef',1937,'原北洋政府官员','原北洋政府官员，投日后参与伪蒙疆政权高层决策，在归绥（今呼和浩特）协助日伪推行殖民统治，参与经济掠夺和“清乡”行动。','危害等级B（乙级，机构委员长(非国家首脑)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cbebf956e024068bb303d90b05e3761','d28a4288-61b1-4778-a5a0-2045d8df65c5',1937,'原东北军将领','原东北军将领，投日后任伪职，驻扎归绥期间曾协助日军维持治安，后因日军猜忌被软禁，1939年反正失败被杀，但其前期行为已构成汉奸事实。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-763abb2bf54c4413b6533012220ef76d','bc4075c4-b281-4efc-b6b9-b6e135374bf3',1938,'在日伪统治下任归绥县（含今玉泉区大部）伪县长','在日伪统治下任归绥县（含今玉泉区大部）伪县长，推行保甲制度，强征捐税，为日军提供粮食和情报，协助镇压抗日地下组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97df742a2edb43a1ac9b9ca86fb9bba4','bc4075c4-b281-4efc-b6b9-b6e135374bf3',1938,'在呼和浩特（归绥）城区及赛罕地区推行日伪保甲制度','在呼和浩特（归绥）城区及赛罕地区推行日伪保甲制度，强征粮食和劳役，协助日军建立情报网，镇压抗日群众运动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63808530f2e7405992b73365799a8aa2','355d7aa5-a4f4-461a-9e71-411307407dae',1939,'任伪归绥市市长期间','任伪归绥市市长期间，管理旧城（玉泉区）行政事务，执行日伪“治安肃正”计划，强制居民领取“良民证”，并参与奴化宣传。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d05c2ea051c1428aaba3de74b583675a','4a47222b-6722-4158-ab08-2f1ea76d96c2',1938,'投日后任伪巴彦塔拉盟盟长','投日后任伪巴彦塔拉盟盟长，管辖今呼和浩特及周边旗县，在玉泉区设立伪盟公署分支机构，配合日军推行“蒙地奉上”和鸦片专卖政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf8b5a6efdff4839afc566fcacbbdd42','105c779c-c850-4e63-a7b9-0f740f05529c',1937,'参与伪蒙疆政权立法和司法镇压','参与伪蒙疆政权立法和司法镇压，在归绥（今呼和浩特）设立伪法院，迫害抗日嫌疑人员，其活动范围涉及玉泉区旧城监狱。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb44c2d7dcfa43bf83391cfca480332b','62a7b12a-5f35-41e9-abff-3902e8bd8626',1937,'原为国民党地方官员','原为国民党地方官员，后投日，在呼和浩特地区主持伪政府行政事务，协助日军征粮、征税，镇压抗日活动，参与制定“蒙疆”地区殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d095556e2c0d45c4a348e8c0612245f3','62a7b12a-5f35-41e9-abff-3902e8bd8626',1937,'作为德王主要幕僚','作为德王主要幕僚，参与伪政权对鄂尔多斯各旗的行政控制，推行奴化教育和物资掠夺政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7afe48d3fd0478e8235ad7d5b9b62c9','a84603c5-02d5-4db7-a4b8-bfe22932d9ed',1936,'在呼和浩特、赛罕一带协助日军训练伪军','在呼和浩特、赛罕一带协助日军训练伪军，多次参与“扫荡”抗日游击队，残害当地百姓，为日军提供后勤支持。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-076b1a10aed14fcc83f3b9b2b099ac35','a9aa0ea4-9c52-4048-a2aa-4665b4e56556',1938,'在呼和浩特南部及赛罕地区驻防','在呼和浩特南部及赛罕地区驻防，配合日军“治安肃正”行动，逮捕抗日志士，强迫农民种植鸦片，为日军筹措军费。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e39665dfdc95437388c3779f89c9f863','bc6c8f1e-17c7-4bfb-8e34-32b9a6878323',1939,'管辖包括呼和浩特、赛罕在内的地区','管辖包括呼和浩特、赛罕在内的地区，积极执行日本殖民政策，推行“蒙地奉上”运动，强占农民土地，配合日军“三光政策”清剿抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02d470f11bd84ba3a592db9c79852e4d','43d6a0fa-e81a-49d3-bfd6-91a6d867cf46',1937,'绥远地区著名汉奸','绥远地区著名汉奸，抗战期间投靠日军，组织伪军配合日军进攻绥西，在巴彦淖尔、五原、临河一带活动，参与日军对绥西的扫荡和统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f9f5ca0c540454f824a73c5255c5bdc','dd6e18d0-7809-417e-9f17-51858b6ab1d7',1937,'察哈尔地区汉奸','察哈尔地区汉奸，参与伪蒙疆政权，协助日军在绥远、察哈尔一带推行殖民统治，与巴彦淖尔地区伪政权有隶属关系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f164ee19aaee433285cd7fc7831f4e6f','dd6e18d0-7809-417e-9f17-51858b6ab1d7',1937,'张家口伪蒙疆政权中的汉奸头目之一','张家口伪蒙疆政权中的汉奸头目之一，参与伪蒙疆对内蒙古东部包括赤峰地区的殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9891d25bb9a34e668a1dfbda399b3d69','dd6e18d0-7809-417e-9f17-51858b6ab1d7',1937,'投敌后任伪蒙古联合自治政府副主席','投敌后任伪蒙古联合自治政府副主席，协助日军统治察哈尔、绥远。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-556591cdbe3645499c236fc230a2e32d','a827c308-b2f2-4bff-8e61-739eb266132d',1937,'绥远地区汉奸','绥远地区汉奸，在伪蒙疆政权中任职，参与司法镇压抗日力量，其管辖范围涉及绥西包括巴彦淖尔地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f89c70f4b0f74dbbae2b24d898709250','2e685bbb-ad2b-41e0-a0b2-92e869d45eff',1936,'协助李守信统率伪蒙古军','协助李守信统率伪蒙古军，参与日军对绥西的军事行动，在巴彦淖尔、五原一带配合日军作战。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-493d214fddba43ab964a0d1a405e74b2','78368a2d-41fa-4a0a-a8ee-92f649deef82',1937,'五原地区汉奸','五原地区汉奸，日军侵占五原后组织维持会，协助日军征粮、派夫、维持地方秩序，为日军统治服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8c7e8e0705e4f05a685edd26a275b35','3c2887f0-9375-48c9-b742-7955413b444d',1937,'临河地区汉奸','临河地区汉奸，组织维持会迎接日军，协助日军在临河一带建立伪政权，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35d7a277a7df425e94ef037ac9a3568b','b128355d-9ad5-4c2e-a3a1-1ff28d73673a',1937,'安北地区汉奸','安北地区汉奸，日军入侵后组织维持会，为日军筹集物资、情报，协助日军控制乌拉特前旗一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf8a1cb2832d462db85c7691b8a81f48','a3c8d2c6-0628-4615-869c-0d1e338f59b3',1937,'绥西地区汉奸武装头目','绥西地区汉奸武装头目，组织伪军配合日军在巴彦淖尔、包头一带进行扫荡，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e30e7a0e8d44d91a4af6a1c7901f627','8e6559f3-164d-489f-86b6-3d484f99ebec',1937,'包头地区汉奸','包头地区汉奸，伪政权地方官员，其管辖范围与巴彦淖尔东部接壤，协助日军在绥西推行保甲制度和经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a13de38f5fcf4d10a127de0224e37350','84d7cc05-d020-4542-942b-823c9ec26f9e',1937,'萨拉齐地区汉奸','萨拉齐地区汉奸，伪政权地方官员，配合日军在绥西地区的统治，参与征粮、抓丁等压迫民众活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ee3194c769d4515b6d97f1dac9c3e32','044221dd-7aa4-471a-b31f-08ef980476df',1937,'绥远地区汉奸','绥远地区汉奸，在伪蒙疆政权中负责民政，推行日军殖民政策，其政策覆盖巴彦淖尔在内的绥西地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b4fdb61e7eb41cd99021ffa5b3afb85','2a136a33-31d1-454c-b007-3b51a45df71e',1936,'协助李守信、德王处理伪蒙古军军务','协助李守信、德王处理伪蒙古军军务，参与绥西地区伪军部署和日军协同作战。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-171d109d6dac47c6bcb9fabf47d6d559','7dc3f01c-09fa-497f-9113-73b66afdc773',1937,'伪蒙古军将领','伪蒙古军将领，率部在绥西巴彦淖尔一带配合日军作战，参与对抗日武装的围剿。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5d923cd375b4ff39215e1c694772d8f','3d0a702b-0701-4aaf-b660-c1b6ad58d41a',1937,'伪蒙古军将领','伪蒙古军将领，在绥西地区活动，协助日军维持伪政权统治，参与地方伪军组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5af1b807519745f9b7f7fedb01f1544e','5fc6ad73-2e3c-45b5-a9da-7b6b343cb515',1937,'绥西地区汉奸武装头目','绥西地区汉奸武装头目，与王英合作组织伪军，在巴彦淖尔、五原一带配合日军行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d67076256c0040ed8805092c60ab0af4','3c55b879-03e9-40fb-a9ef-6f497a4ec8b7',1936,'原为土匪出身','原为土匪出身，后投靠日军，任伪蒙古军第1军军长，在绥西（包括临河、五原一带）配合日军进攻傅作义部，烧杀抢掠，残害百姓，并参与组织伪政权，镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cea1309c1364b8b854ad7f98797faae','3c55b879-03e9-40fb-a9ef-6f497a4ec8b7',1936,'原为土匪出身','原为土匪出身，后投靠日军，在五原、临河一带组织伪军，配合日军进攻绥西，多次参与对五原地区的扫荡和破坏，是当地主要的汉奸武装头目。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d78e82952ea04e64b5cb14151c2fdf67','3c55b879-03e9-40fb-a9ef-6f497a4ec8b7',1936,'原为土匪出身','原为土匪出身，后投靠日军，在鄂尔多斯及东胜地区协助日军进攻抗日武装，镇压民众，掠夺物资，是当地主要汉奸头目之一。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07ff0e1b14124090b85bd78ca63102fb','e577ecf0-fe91-4522-86e3-55b629247744',1937,'投靠日军后任伪蒙古军第2军军长','投靠日军后任伪蒙古军第2军军长，曾率部驻扎绥西一带，配合日军扫荡临河、陕坝等地，杀害抗日军民，掠夺财物。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a48133ac5d8a49db942989a764f4dd72','e577ecf0-fe91-4522-86e3-55b629247744',1937,'原为绥西地方武装头目','原为绥西地方武装头目，后投日，任伪蒙古军第2军军长，驻防绥西，协助日军清剿抗日游击队，强征民夫粮草，欺压当地民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08822a34f7544e20a5061d84d47eecaa','272ca007-c4be-4afd-b6db-36a12076acf5',1940,'日军占领临河期间任伪县长','日军占领临河期间任伪县长，推行日伪政策，组织汉奸保安队，协助日军清乡，逮捕抗日地下工作者，强征壮丁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5d77a13829c42359c7882355c24fbb4','672c65c4-70d8-4682-959e-94f149d60620',1941,'在日伪政权下任职','在日伪政权下任职，配合日军对河套地区进行经济掠夺，强制推行“治安强化运动”，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f361bc8de394516a362f785ec76d90e','d72706db-725e-4c3c-8bfa-11f3d6007a52',1942,'原为晋军将领','原为晋军将领，后投靠日军，任伪绥西警备司令，在临河、狼山一带协助日军防守，镇压当地抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a58060fe7b54a54b9b17f7d07bbd407','be12262e-51a6-4709-8688-e54b77e0ee19',1938,'长期在巴彦淖尔地区活动','长期在巴彦淖尔地区活动，率部袭击抗日游击队，抢劫村庄，并参与日军“扫荡”行动，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9fa662dead8e441cb63784091010fcac','0cd3da71-7b72-439a-bae9-de8f509667a1',1933,'率伪蒙古军侵占乌拉特中旗等地','率伪蒙古军侵占乌拉特中旗等地，协助日军清剿抗日武装，镇压蒙汉民众反抗，参与奴化统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c0ed7a3af02445ab0d5034a15efb7df','0cd3da71-7b72-439a-bae9-de8f509667a1',1933,'原东北军军官','原东北军军官，后投靠德王和日军，任伪蒙古军副总司令，参与对绥远、察哈尔等地的军事行动，协助日军维持殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f19c15d4b84e4a399a1d9e4c8eecf269','909ebf24-f829-4f40-a542-b305233388a6',1938,'随王英在乌拉特中旗一带活动','随王英在乌拉特中旗一带活动，参与“清乡”行动，搜捕抗日分子，强征民夫，掠夺物资。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a496289e87b04cf6961ab0144a8b3cce','a11b0685-eb85-41d8-bad7-a67b61b69fb0',1937,'在乌拉特中旗及乌拉特后旗一带活动','在乌拉特中旗及乌拉特后旗一带活动，为日军提供情报，围剿抗日武装，推行“保甲制度”。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ecd1a4e70164f6184cd9d53b3c58bdc','f91d0a24-ad7d-44fe-8e4d-ff8929095e54',1938,'在乌拉特中旗驻防期间曾执行日军命令','在乌拉特中旗驻防期间曾执行日军命令，参与对抗日根据地的封锁，但后期于1945年率部反正（仍列入前期汉奸行为）。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d43c6688e9934b3e8e85509e871bd1d7','6647108d-7163-46b1-a8b4-6f91eead91e7',1939,'参与伪蒙疆政权在乌拉特中旗的行政建设','参与伪蒙疆政权在乌拉特中旗的行政建设，协助推行奴化教育，宣传“日蒙亲善”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e6a90537e474172baf8a49aac38c6ad','df14e478-3bc7-4a8b-beaf-37ff1eefeee6',1938,'作为伪旗长','作为伪旗长，为日军征收粮草、牲畜，强抓壮丁，破坏抗日地下活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-424438d3437e41f8a489fe666c99ff66','5d6419f3-3e40-46d4-bca2-6b6a9fd91a9e',1939,'指挥伪警察搜捕抗日分子','指挥伪警察搜捕抗日分子，严刑逼供，协助日军“扫荡”周边村落。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e95749286022421695cd11c8c86965c8','f2e2c56d-9388-469e-a926-6b416381c003',1940,'率保安队配合日军围剿大青山抗日游击队','率保安队配合日军围剿大青山抗日游击队，杀害多名交通员和群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-efc6e76e344543bea289f34a2227ceac','5f81d132-b5a2-4442-b024-1789d9fb216b',1937,'率伪蒙古军驻扎乌拉特前旗一带','率伪蒙古军驻扎乌拉特前旗一带，配合日军围剿傅作义部抗日武装，残害当地抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4aac1c8e28a3481bbad1ea50ee712179','5f81d132-b5a2-4442-b024-1789d9fb216b',1937,'率伪蒙古军在张家口、察北地区配合日军扫荡抗日游击队','率伪蒙古军在张家口、察北地区配合日军扫荡抗日游击队，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d1e72d24033d411197d0700b9101e654','5257dbb3-effa-4053-8ab9-ffe60ba07a72',1938,'在乌拉特前旗地区为日军搜集情报','在乌拉特前旗地区为日军搜集情报，参与“清乡”行动，逮捕并杀害抗日地下工作者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70e61c3957014488a10140b383c65800','8491b187-4cbf-4a8c-8979-03f53e2c7671',1939,'作为伪旗长','作为伪旗长，协助日军在乌拉特前旗推行“治安强化运动”，强征劳工修建军事设施，压榨当地牧民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5bafdfbd277347cdab4a5db5d468c1a1','98727cb7-b92d-462a-9e1c-999f16b86401',1940,'率伪保安队为日军站岗放哨','率伪保安队为日军站岗放哨，参与围捕抗日游击队，多次向日军报告抗日活动线索。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ae6b54b785f498e91053fdf4944a041','b9b3755f-5c99-46dc-8e26-82f1325d7bb5',1933,'率伪蒙古军侵占绥远北部（含乌拉特后旗一带）','率伪蒙古军侵占绥远北部（含乌拉特后旗一带），协助日军‘清剿’抗日武装，镇压蒙汉民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5f6ff9776ff4936b6988b750e34d5f3','b9b3755f-5c99-46dc-8e26-82f1325d7bb5',1933,'原为热河地方军阀','原为热河地方军阀，后投靠日本，在锡林郭勒及察哈尔地区组织伪蒙古军，协助日军镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e3fd660e2e24443a17127cae7484803','6b15d704-514a-4013-810e-e275df84ec6a',1938,'一度投靠日军','一度投靠日军，在乌拉特后旗及周边地区参与伪军活动，后反正抗日（但前期有汉奸行为）。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-490938f170c54b5c8008a68dbe448656','69737855-0622-46ab-bf3d-3472e3ad2279',1939,'在乌拉特后旗为日军效力','在乌拉特后旗为日军效力，协助维持伪政权，镇压当地抗日牧民，征收苛捐杂税。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29830618311b4f4596146758b4f50460','e36e6fd6-45ce-4f38-922c-a34d3ee48df3',1940,'在日伪统治下担任旗长','在日伪统治下担任旗长，推行‘保甲制度’，强迫牧民供粮供畜，配合日军‘治安肃正’。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fab52cf429ff4d429b27502f670412f1','bb1345f5-6a45-4e36-aa29-36f92a026a30',1941,'协助日伪在乌拉特地区征募伪军','协助日伪在乌拉特地区征募伪军，提供情报，参与围剿抗日游击队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e1e5ba8231d4c04b6141ce67c9346ff','839e86f8-d1b0-47ef-b7a5-197607e958de',1942,'指挥伪警察抓捕抗日志士','指挥伪警察抓捕抗日志士，破坏地下抗日组织，为日军提供劳役。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f0532f84fb747708ce9409e69930d61','a9160fa1-72da-4562-9996-0071409f0fae',1933,'热河人','热河人，投日后成为伪蒙疆政权核心人物，其势力范围曾延伸至绥西五原地区，协助日军控制该区域，并组织伪军对抗抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8e6989aea024488929d85b8c98f0374','69082e9a-999e-433d-ab7f-00c29e1158af',1938,'在五原、安北一带驻防','在五原、安北一带驻防，协助日军清剿抗日游击队，曾参与1939-1940年日军对五原的进攻，并纵容部下掠夺百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04501c76ff3747b6a37f48c198d7f610','b111f1da-9e3a-4d72-ac03-06a32c8cccfb',1939,'率部在绥西地区活动','率部在绥西地区活动，多次配合日军扫荡五原周边村庄，杀害抗日军民，并强征民夫修筑工事。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98c87452aa4142b495d73cae119efa3d','1745ef24-8d1f-4344-a8a7-d7c013f6c42c',1940,'日军占领五原期间任伪县长','日军占领五原期间任伪县长，推行保甲制度，强征粮食和劳役，协助日军维持殖民统治，并迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab78c3d07a64461293c63197397fc6cb','e0e872ab-10c6-4c40-b0ab-9c9f6cb4fdc4',1940,'为日军效忠','为日军效忠，搜捕抗日地下人员，破坏地下交通线，并参与镇压当地民众的反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69343d0ff7974051ade97a3710958e00','426b7fe6-4d0a-4327-b103-b06abd94ddc7',1939,'日军占领安北后组织维持会','日军占领安北后组织维持会，为日军筹粮派款，并引导日军袭击抗日武装驻地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b6a199050e34a73ba2e3f8319eba0f5','a3d9c842-a69d-49e0-b5a1-75980ac87d33',1937,'原为土匪出身','原为土匪出身，后投靠日军，任伪蒙古军第1军军长，率部在绥西（今巴彦淖尔、杭锦后旗一带）配合日军扫荡抗日武装，残害百姓，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8d520c4a38a49e2a1348c1887bd9f53','05c918e8-05c8-4aae-a8f0-8eb5acfe5b43',1933,'日军侵占赤峰后出任伪县长','日军侵占赤峰后出任伪县长，推行日伪殖民政策，强征民夫、收缴民间武器，协助日军维持统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cfcb417f0f0472d954d697c5f0dbb4e','05c918e8-05c8-4aae-a8f0-8eb5acfe5b43',1933,'任伪赤峰县县长期间','任伪赤峰县县长期间，为日军征粮派夫，强征劳工，协助日军建立保甲制度，迫害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07f0c7878dec4133b8513cb3fc25b45d','411f6f62-2559-4e50-8ac1-a3d43d6ce705',1933,'效忠日伪当局','效忠日伪当局，指挥警察抓捕抗日志士，参与“治安肃正”行动，迫害无辜百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3afc2e6cbc6b441ba40358f9bcc486cc','61ed6c8d-3203-493f-a892-b8d698e3349f',1933,'原奉系军阀','原奉系军阀，九一八后投日，任伪热河省省长，协助日军统治赤峰地区，推行奴化教育，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5cb5439942740f1b357d26161c21c95','65258d63-4270-4408-8390-b2a6dc2128fd',1935,'负责日伪“协和会”赤峰分会','负责日伪“协和会”赤峰分会，宣传“日满亲善”，组织汉奸团体，搜集抗日情报。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7e940fafc3c4ea1b55c55a92727dd14','c3359839-59cd-4f4e-a4bc-4906b0b31c0c',1933,'率保安队配合日军“扫荡”','率保安队配合日军“扫荡”，烧杀抢掠，多次参与围剿赤峰周边的抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f91ba0b78c2d400b8d9e9dafa6a7ad21','cb74ec35-96a8-4028-a871-1c1c6703ab91',1934,'为日伪征收苛捐杂税','为日伪征收苛捐杂税，强征粮食、牲畜，导致百姓负担沉重，间接支持日军战争经济。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef7ffabd646c423eb09a9002eb0c8552','98635c42-8f3d-48f3-bb15-dfece0f25751',1933,'在伪热河省任职期间','在伪热河省任职期间，参与策划对赤峰、元宝山地区的“治安肃正”行动，协助日军清剿抗日游击队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71625e4db1274f92853766b0d4b47ca3','d3255a1f-f626-4be2-9296-0288e24a718e',1937,'在元宝山矿区组织伪维持会','在元宝山矿区组织伪维持会，为日军提供煤炭资源情报，强迫矿工为日军服务，镇压矿工反抗。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6e52657e6ff4396bd43ceb327e4e768','14722723-9c09-4929-a22c-8b1cefb635f2',1933,'率伪军驻防赤峰一带','率伪军驻防赤峰一带，多次配合日军扫荡元宝山周边村庄，杀害抗日群众，掠夺物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75d463f512524737b40a4bcd3ea52216','14722723-9c09-4929-a22c-8b1cefb635f2',1933,'原为奉系军阀','原为奉系军阀，1933年投敌，任伪热河省警备军司令，其部队驻扎赤峰、林西等地，多次参与围剿抗日游击队，协助日军建立伪政权。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5feaefcabf5b499786d964a86dbf3652','14722723-9c09-4929-a22c-8b1cefb635f2',1933,'原东北军将领','原东北军将领，投日后任伪热河省警备军司令，在承德、兴隆一带配合日军‘扫荡’，围剿抗日武装，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3504107222254b008d16bce4ad09b023','3fa99992-b7b2-4316-8d05-1432b41c6729',1938,'在赤峰及元宝山地区建立特务网络','在赤峰及元宝山地区建立特务网络，抓捕抗日地下工作者，协助日军进行“大检举”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21b5c076e6b847ab91601b31373c3244','6c5cc429-5805-4cf0-9014-b9865b830984',1933,'投靠日军','投靠日军，任伪旗长，协助日伪推行殖民统治，强征民夫、粮食，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0899c3da17b54d28b52bd242f1916145','e09e00ab-35a5-49c0-ab7e-2136ad20d238',1935,'效忠日本特务机关','效忠日本特务机关，组织伪警察抓捕抗日志士，参与“治安肃正”行动。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-146c60a2549d438e95aabc0f99d2aa4d','47cf026d-4c50-432a-ab3b-23aeb5e952bf',1937,'率伪保安队配合日军扫荡','率伪保安队配合日军扫荡，烧毁村庄，掠夺牲畜，迫害当地民众。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-638b954277fe410ba45307203328bff1','d606c803-ff17-48ed-b9e8-17107f5c100b',1938,'宣传“日满亲善”','宣传“日满亲善”，组织奴化教育，强迫民众参加“协和会”活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15ac6921a6cf4dd1a745dca19d91f595','e191ecf1-ab80-48df-9daf-2594957270ad',1933,'热河抗战后投敌','热河抗战后投敌，率部配合日军侵占赤峰及昭乌达盟一带，参与组建伪蒙古军，长期在内蒙古东部包括赤峰地区进行殖民统治和军事镇压。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-975cec7e3173497796ee8cbaa0142785','e191ecf1-ab80-48df-9daf-2594957270ad',1933,'热河抗战后投敌','热河抗战后投敌，组织伪蒙古军，配合日军侵占赤峰及昭乌达盟一带，在巴林右旗等旗县推行伪旗县公署和保甲制度，强征民夫、牲畜，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ee1d33305b84cc9852bda7152bbba64','e191ecf1-ab80-48df-9daf-2594957270ad',1933,'蒙古族出身','蒙古族出身，早年在热河、哲里木盟一带活动，1933年投靠日军，参与组建伪蒙古军，长期在内蒙古东部包括通辽、开鲁周边地区配合日军围剿抗日武装，推行伪蒙疆统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd3790ee42864a18a7001946ecbbc6a1','ba98025a-b159-4a37-9006-4dfb89340784',1936,'在日军扶植下建立伪蒙政权','在日军扶植下建立伪蒙政权，统治范围覆盖内蒙古东部，赤峰及喀喇沁旗一带受其伪政权影响，推行亲日殖民政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a120ca08a7c248ddb90c1d1c43cb13b8','ba98025a-b159-4a37-9006-4dfb89340784',1936,'即德王','即德王，锡林郭勒盟苏尼特右旗札萨克郡王，1936年起在日军扶植下建立伪蒙古政权，其统治范围及于内蒙古东部，通辽、开鲁一带亦受其伪政权影响，配合日军进行殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffd64742ac0046aab0f6fd56e179e615','60116807-0759-4697-bd2d-8766a67bb041',1931,'九一八后投靠日本','九一八后投靠日本，参与组织伪军，在内蒙古东部包括赤峰地区配合日军作战和维持殖民秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-581fe23fca01417bb682dd236be928e9','60116807-0759-4697-bd2d-8766a67bb041',1931,'九一八后投日','九一八后投日，参与组建伪军，在内蒙古东部包括赤峰一带进行殖民统治和镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-201a4f9ebd904163a523a5007433c315','60116807-0759-4697-bd2d-8766a67bb041',1931,'参与策划内蒙古东部独立活动','参与策划内蒙古东部独立活动，投靠关东军，在赤峰、通辽一带组织伪军，配合日军进攻抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ea172f25bba4a87865645e28cbbc99a','60116807-0759-4697-bd2d-8766a67bb041',1931,'蒙古族','蒙古族，早年参与策划内蒙古“独立”活动，九一八事变后投靠日本，在伪兴安军、伪蒙古军中任职，活动于内蒙古东部包括赤峰、昭乌达盟一带，参与镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-693e16091f364676a50dad5b72620ff9','97e30f1e-20ee-40a5-b209-f55f807c5a06',1932,'投靠日本','投靠日本，任伪满兴安省要职，管辖包括赤峰在内的内蒙古东部地区，推行日本殖民统治政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c81886e304224fa9a2a21c9edfbc975b','1793354a-c840-4470-975d-77a6faf5af6c',1932,'在伪满洲国任职','在伪满洲国任职，管理兴安南地区，赤峰一带在其管辖范围内，协助日军征发物资、镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ecc338f57074f12b1e5768176de5bd3','950a96d9-50b5-457b-ab60-b6fb3bb1317a',1932,'在伪满兴安省系统任职','在伪满兴安省系统任职，参与对内蒙古东部包括赤峰地区的殖民行政管理和亲日宣传。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-619fb533237e4c35a8baaac378ff5296','7c8385d9-03ce-41f2-bd65-506a4e86a1d7',1932,'在伪蒙、伪满政权中任职','在伪蒙、伪满政权中任职，活动于内蒙古东部，参与日本殖民统治下的行政与联络事务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d97ecd57c89843faa538ff2f4ac3bb68','a3b15c43-5ae0-4b1f-99d4-63c955b361aa',1932,'在伪兴安军任职','在伪兴安军任职，配合日军在赤峰及昭乌达盟地区进行军事行动和治安镇压。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0bd08401e764a13a5c38dbb979a9c93','0866b1ab-ba14-49a0-b61a-18c7862effd6',1936,'参与伪蒙政权','参与伪蒙政权，在内蒙古东部包括赤峰地区进行亲日政治活动，协助日军统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c062aa39e76a4b0b80f31ab137edf204','0866b1ab-ba14-49a0-b61a-18c7862effd6',1936,'蒙古族','蒙古族，投靠日本，在德王伪政权中任职，参与伪蒙古联合自治政府的政务活动，其伪政权影响覆盖内蒙古中东部包括赤峰地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a960d42bf6449c399bd2213b3b7a41e','740433c1-573c-4483-a0c6-96bc9f0820d7',1931,'长期投靠日军','长期投靠日军，在内蒙古中西部及东部部分地区活动，配合日军进攻和镇压抗日武装，其势力曾波及赤峰周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4271dfb132c4c51901d89d964ecd3f4','237c3ea4-9bf9-4280-82f4-d0c46be30c54',1931,'投靠日本','投靠日本，率伪军参与侵占热河，赤峰地区在其伪省管辖范围内，协助日军镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fadd410e6da942bc86af9a0a9eb1d39e','237c3ea4-9bf9-4280-82f4-d0c46be30c54',1931,'率部投敌','率部投敌，配合日军进攻热河，任伪省長。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f8eb8688a634e179510bb045100e8af','4be2d13e-455d-4b4d-aa7e-cc7a0cc256a7',1930,'曾投靠日军','曾投靠日军，率部在热河、赤峰一带流窜，配合日军骚扰抗日根据地，后又被抗日武装打击。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-adb4d45933294cf18191305c26d8d801','4be2d13e-455d-4b4d-aa7e-cc7a0cc256a7',1930,'绰号刘黑七','绰号刘黑七，长期在山东胶东一带流窜，后投靠日军，配合日军进攻招远、烟台等地的抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c62d2ffb29114f7fa3656e0fcf5514f0','4be2d13e-455d-4b4d-aa7e-cc7a0cc256a7',1930,'绰号刘黑七','绰号刘黑七，长期在山东胶东一带活动，后投降日军任伪军师长，在烟台、栖霞周边地区烧杀抢掠，配合日军扫荡抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d6e332869904601a7e2ede6afd92bca','4be2d13e-455d-4b4d-aa7e-cc7a0cc256a7',1930,'长期在山东胶东及鲁中南地区流窜','长期在山东胶东及鲁中南地区流窜，曾投靠日军任伪军师长，配合日军扫荡胶东抗日根据地，1943年被八路军击毙。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f2b9674425b4372a0348e2f02b18e85','4be2d13e-455d-4b4d-aa7e-cc7a0cc256a7',1930,'绰号刘黑七','绰号刘黑七，抗战时期率部投敌，在山东胶东及鲁中南一带流窜，配合日军袭扰抗日根据地，活动范围接近烟台、莱阳地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09d82f1fdedc415dbd1135915c183606','4be2d13e-455d-4b4d-aa7e-cc7a0cc256a7',1930,'原为山东巨匪','原为山东巨匪，抗战期间投靠日军，率部在胶东及鲁中南地区活动，配合日军扫荡抗日根据地，残害民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b464ec97b0cd442c92190d75f74b97c3','4be2d13e-455d-4b4d-aa7e-cc7a0cc256a7',1930,'长期在鲁南、鲁西南及菏泽周边活动','长期在鲁南、鲁西南及菏泽周边活动，抗战期间投靠日军，所部被编为伪军，配合日军扫荡抗日根据地，残害民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8228270cc6b4c95bed2d7efe09ce578','4be2d13e-455d-4b4d-aa7e-cc7a0cc256a7',1930,'长期在河北、察哈尔、张家口一带流窜','长期在河北、察哈尔、张家口一带流窜，曾投靠日军任伪军头目，配合日军扫荡抗日根据地，残害民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d0d36088d384c798d3236e528934b29','faf74934-5f96-4a9a-a535-9cea47476e13',1930,'在伪满洲国时期任喀喇沁旗伪旗长','在伪满洲国时期任喀喇沁旗伪旗长，协助日军推行保甲、征发劳役和物资，维持当地殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0dda2edce6bc4c02a7d9a3d90f3c5660','1a6fbb21-b480-4b91-be34-1d454c463ccb',1930,'在喀喇沁旗伪政权中任职','在喀喇沁旗伪政权中任职，参与亲日宣传、物资征调和地方治安维持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbccc0edd7a248c493e06ff74b539b99','14a95e55-9668-447d-b886-7e0437073cee',1933,'日军侵占赤峰后任伪县长','日军侵占赤峰后任伪县长，协助日军建立殖民秩序，推行保甲连坐，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-100b4d9afadd479887d1b76bd4e8064b','c3d10b48-6ce5-4f6e-9c54-f48d805a255e',1933,'日军侵占赤峰初期组织维持会','日军侵占赤峰初期组织维持会，为日军筹粮筹款、维持地方秩序，协助殖民接管。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25244bc9521c478dbb344f6123087e17','b9990eaa-5404-4439-89fd-966d6092a29c',1930,'在伪赤峰县警察系统任职','在伪赤峰县警察系统任职，参与搜捕抗日人员、镇压民众反抗，维护日伪统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59e9d86823df43318b25fe280a6614d3','a579447b-b1c4-4c41-af2f-15589856be78',1933,'在伪热河省警务系统任职','在伪热河省警务系统任职，负责赤峰等地治安，参与围剿抗日武装和镇压民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d47219466a34446089a603be93e89aa7','2f2c27d7-0275-451e-9161-b7925848949c',1933,'在伪热河省教育系统推行奴化教育','在伪热河省教育系统推行奴化教育，赤峰地区学校受其政策影响，宣传亲日思想。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c731020e72c40229177c0d261f4cc06','bcd8a8d2-48f5-40eb-941e-0c10ff758148',1937,'任伪宁城县县长期间','任伪宁城县县长期间，推行日伪保甲制度，强征劳工，配合日军“治安肃正”，抓捕抗日军民，并强迫民众种植罂粟。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44a2ab35e7db43ef94caf0ba81acc3b3','6476966f-a03a-4d48-9c62-11be6beb96dc',1938,'在赤峰地区为日军征粮派款','在赤峰地区为日军征粮派款，组织伪警察队协助日军扫荡，破坏中共地下组织，曾亲自带队抓捕抗日干部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35d2cd22fa5f40e0a5a1f5dcde1b413d','72dabde2-3eb0-4117-b3f8-3e4906cec6b9',1939,'指挥特务情报网','指挥特务情报网，在宁城、赤峰等地侦捕抗日地下人员，制造多起惨案，如“五家村惨案”中提供情报并参与屠杀。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7080b9cec2cd467f99c1f9ab71156149','b1401c2d-067d-4eef-b86d-bcd81a44a907',1940,'率保安队多次袭击八路军游击队','率保安队多次袭击八路军游击队，烧毁村庄，杀害抗日家属，并配合日军在宁城西部山区推行“无人区”政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29bcfc07cb5448b0852eb6ac2d2cd0aa','b1549bb2-4677-4a96-b906-dfa9d98d00e3',1935,'为日军筹集军需物资','为日军筹集军需物资，垄断粮食贸易，压低收购价盘剥农民，并举报抗日商人，导致多人被日军宪兵队杀害。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbc4eae59d364f8db71f86fb22c5edd4','1503a9a7-2ec5-47e4-b399-d03b5abcfc27',1937,'宣传“日满亲善”','宣传“日满亲善”，组织“协和青年团”刺探抗日活动，在宁城地区煽动民众告密，致使多个抗日联络点被破坏。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18c770c01a8348cba0cd4866fafc9571','176ad4a9-2382-4710-a283-6ceeedc4c1c5',1933,'虽主要活动在河北','虽主要活动在河北，但曾与日军勾结，在赤峰南部边境为日军提供情报，并收编伪军骚扰抗日武装。注：其投日行为存在争议，部分史料未完全确认。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb3078a90a4843639cf688f624960996','cfe2fdb3-5e4a-4493-9a1f-4a7e574373d5',1936,'在日军扶植下建立伪蒙政权','在日军扶植下建立伪蒙政权，管辖包括赤峰、昭乌达盟在内的内蒙古东部地区，推行亲日政策，协助日军征发物资、控制蒙旗，巴林右旗等旗在其伪政权体系内。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c38349be9f34fa182bf0fb2187814d2','cfe2fdb3-5e4a-4493-9a1f-4a7e574373d5',1936,'即德王','即德王，锡林郭勒盟苏尼特右旗札萨克。在日本支持下先后建立伪蒙古军政府、伪蒙古联合自治政府，统治范围涵盖内蒙古中东部，赤峰、翁牛特旗一带亦受其伪政权影响，推行亲日附逆政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b92b5fdd51304ba58502f3909c1821c8','cfe2fdb3-5e4a-4493-9a1f-4a7e574373d5',1936,'在日军扶植下建立伪蒙政权','在日军扶植下建立伪蒙政权，势力范围涉及宁夏北部及石嘴山周边，配合日军对宁夏进行军事威胁和政治渗透，招募当地蒙汉败类充当伪军。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a70b40313b5a42fe85893b1dd313220a','00f1bdee-4288-4352-b63c-080b4bf9a404',1931,'参与策划蒙旗独立活动并投靠日本','参与策划蒙旗独立活动并投靠日本，在伪兴安省、伪蒙古军任职，活动于昭乌达盟、赤峰一带，协助日军控制巴林右旗等蒙旗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9db1f9e52edb4e67b1e17a4c5496fb89','505b4fdd-6a9a-4ef9-ad66-6f1f4152a661',1931,'与甘珠尔扎布等投日','与甘珠尔扎布等投日，参与组织伪蒙武装，在赤峰、昭乌达盟地区配合日军行动，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11e574134c9b4c00ba6efaf951036007','917842aa-9e55-48a5-b6dc-8a24457bb067',1932,'作为伪满洲国兴安省系统高官','作为伪满洲国兴安省系统高官，管辖包括赤峰、昭乌达盟在内的东蒙地区，推行日伪政策，控制巴林右旗等旗县。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49b4c3f8ebb248228aa8f123a61d3338','b6f8382d-d83a-4649-bd27-2f28eed40b84',1932,'在伪兴安省系统任职','在伪兴安省系统任职，参与昭乌达盟地区伪政权建设，协助日军征发物资、推行保甲。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19b8ef67be5c449b86ad80edcb990b9b','b8baeb09-54c1-492b-97f1-d65caea5c61b',1932,'投靠日伪','投靠日伪，在昭乌达盟、赤峰一带任职，参与伪军警活动，镇压抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7943dbddfcfa447da3abf1709a603083','5b7fa162-29bd-45a2-8018-849b0064c4bc',1933,'在伪蒙古军和伪兴安军任职','在伪蒙古军和伪兴安军任职，活动于赤峰、昭乌达盟地区，配合日军扫荡抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-277eca2fa9ad4bedb1d0d5902c6e59e0','6fb2427b-85b4-484d-b326-daba1d43fbd5',1931,'投日后在伪蒙武装中任职','投日后在伪蒙武装中任职，参与控制东蒙地区，包括赤峰、昭乌达盟一带，协助日军维持统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de2a3ed11cde45a6a82238be72254361','3f37c509-79b8-40ac-8de5-daf09e9ebd8c',1933,'在伪蒙古军任职','在伪蒙古军任职，活动于昭乌达盟、赤峰地区，参与伪军行动和物资征发。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff59a74430e540e299fe8cd437e8fa40','a987b9ad-4ca8-46ca-be92-2a504999d7c7',1933,'在昭乌达盟某旗任伪职','在昭乌达盟某旗任伪职，协助日军建立保甲、征发牲畜粮食，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae36dd681f7d47b9b4ec90a85d6c31e0','2caf0e83-744a-4614-858e-31b8cd1d82f1',1933,'在巴林右旗伪旗公署任职','在巴林右旗伪旗公署任职，执行日伪政令，推行保甲连坐，征发民夫物资，配合日军控制当地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba263b0ab06248bda171b5404524af9e','924fbd30-ee9a-4306-8218-bec791d5a6a9',1933,'在巴林右旗伪政权中任职','在巴林右旗伪政权中任职，协助日军和伪兴安省控制地方，参与征发与镇压。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5230180124d842b0a79c69b49533015d','9481a397-036f-49d5-9d72-f8c6d867a406',1933,'在昭乌达盟地区任伪职','在昭乌达盟地区任伪职，组织维持会，协助日军维持治安、征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8db1b66257ef46d9aa7e93af1121e35e','7492d045-d2ab-4486-afb7-6747113114ca',1932,'在昭乌达盟、赤峰一带伪政权任职','在昭乌达盟、赤峰一带伪政权任职，推行日伪政策，控制巴林右旗等旗县。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18f99a89b7304e33949d2c64d88657ef','909ba758-b0fa-48c1-9634-fbb403bead4a',1933,'在巴林右旗或邻近旗县任伪保甲长','在巴林右旗或邻近旗县任伪保甲长，协助日军征发粮食、民夫，监视抗日群众。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ebbfa37c64e4c72a9b1ca2797db959d','eb67f463-243d-4222-b4a2-31d8aa4b06ec',1933,'在赤峰、昭乌达盟地区任伪军警职务','在赤峰、昭乌达盟地区任伪军警职务，参与扫荡抗日武装，镇压群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54b96cd80f1444fca8dca93d52c71efd','151143a2-8d94-4082-bd78-bdb2a9c59501',1932,'在伪兴安省系统任职','在伪兴安省系统任职，管辖昭乌达盟部分旗县，协助日军控制巴林右旗一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e212e32c22474911a385864f0169b8dc','4d9cb771-4f29-44a3-84a4-eeeee7c0cd81',1933,'在昭乌达盟地区任伪职','在昭乌达盟地区任伪职，组织维持会，协助日军征发物资、推行保甲。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03944c71b25c4567811a62fc5f496321','1ef8ad86-f66e-43a1-bcff-d4119d12404d',1932,'虽早年有维新活动','虽早年有维新活动，但晚年投靠伪满洲国，在昭乌达盟地区有影响，协助日伪控制蒙旗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-208c3e81964c4fe2bbdaaa0e6c30e730','72e8e74c-513e-4b83-ac89-a34d9f98ccd7',1933,'在伪热河省任职','在伪热河省任职，管辖包括赤峰、昭乌达盟部分地区，推行日伪政令，控制巴林右旗等旗县。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-578c0a69a8db4bc1810fc3e0a636e79e','63792860-4bf6-4a84-acd5-d7f8230e369a',1931,'投敌后任伪热河省省长','投敌后任伪热河省省长，配合日军侵占赤峰及昭乌达盟，建立伪政权，征发民夫物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c563aa206214f8cb1775ab8f7277df5','69af9f92-b57a-4efa-8f3d-25c75b9a4518',1933,'投日后率伪军活动于热河、赤峰一带','投日后率伪军活动于热河、赤峰一带，骚扰抗日根据地，镇压群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-395b4b75086b4b68af5913ae6251f285','69af9f92-b57a-4efa-8f3d-25c75b9a4518',1933,'山东人','山东人，抗战期间投靠日军，组织伪军，在华东地区进行伪化统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe1b15e3bcf244a69ab91c81f3a8a34d','22c4c1c9-4402-41ef-a66d-58059deb06fd',1933,'在伪热河省警备系统任职','在伪热河省警备系统任职，活动于赤峰、昭乌达盟地区，参与扫荡抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9efee11c691a4031ab480b350d221d74','73c4b3ff-0b33-43fe-a5a1-3e4be2b57e69',1932,'在昭乌达盟地区任伪职','在昭乌达盟地区任伪职，协助日军控制巴林右旗等旗县，推行保甲。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-046c0233b65f482bbdae3ff568ea1b09','d4884694-f1d4-4e0a-89fc-5cb105cc9526',1933,'在昭乌达盟地区任伪职','在昭乌达盟地区任伪职，组织维持会，协助日军征发物资、镇压抗日。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a317699b4a1f49ed8f1402039f66f72f','da77e25b-9432-4efb-86a0-25bd4bcb3ca0',1933,'在巴林右旗或邻近地区任伪保甲长','在巴林右旗或邻近地区任伪保甲长，协助日军征发粮食民夫，监视群众。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f86a9ac0f214ef884e873f25b613bee','369629a7-0345-40ed-9ddb-5e79a557e775',1933,'在赤峰、昭乌达盟地区任伪军警职务','在赤峰、昭乌达盟地区任伪军警职务，参与扫荡抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2095e162d0494c2a9fa4e6987f25f49a','fcedceed-542c-4acb-a042-2ac05c1efc71',1932,'在昭乌达盟地区任伪职','在昭乌达盟地区任伪职，协助日军控制巴林右旗等旗县。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91daefa34f884ddf917dc30c39875e1d','cc795a31-81f1-4d83-b9d9-c8182bda6836',1933,'在昭乌达盟地区任伪职','在昭乌达盟地区任伪职，组织维持会，协助日军征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-655d893ef90e478da9930a7fdceb6ad8','25b1dadd-0686-49f5-a3aa-796e5e145e78',1936,'锡林郭勒盟苏尼特右旗札萨克郡王','锡林郭勒盟苏尼特右旗札萨克郡王，1936年在日本支持下成立伪蒙古军政府，后任伪蒙疆联合自治政府主席，其伪政权统治范围涵盖今内蒙古中东部包括赤峰部分地区，推行亲日卖国政策，协助日军征粮、征兵、镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-470360a21840405e98c68316451ce3d3','25b1dadd-0686-49f5-a3aa-796e5e145e78',1936,'在日军扶植下建立伪蒙疆政权','在日军扶植下建立伪蒙疆政权，其统治范围覆盖赤峰及阿鲁科尔沁旗等昭乌达盟地区，推行亲日政策，协助日军控制内蒙古中东部。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7869f3c008f480a9ae882cbf6d3d192','c50b87d5-55d3-472d-8a76-57a1f3f1f1a8',1936,'原为张家口商会会长','原为张家口商会会长，1937年日军占领张家口后出面组织维持会，后任伪察南自治政府最高委员、伪蒙疆联合自治政府副主席，积极为日军筹粮筹款，推行经济统制，协助日军在蒙疆地区进行殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ec81cec51e0408db9ddae2b9b73171a','c50b87d5-55d3-472d-8a76-57a1f3f1f1a8',1936,'原为商人','原为商人，后投靠日军，在伪蒙疆政权中担任要职，协助日军在内蒙古中西部推行殖民统治和经济掠夺，活动范围涉及鄂尔多斯周边地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68b790c3ae054b1a872da6369d863cc7','c50b87d5-55d3-472d-8a76-57a1f3f1f1a8',1936,'河北人','河北人，抗战期间投靠日军，任伪蒙疆联合自治政府副主席，在华北地区进行伪化统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db67ec439ca74bf5901c0a625d87a64a','c50b87d5-55d3-472d-8a76-57a1f3f1f1a8',1936,'伪蒙疆政权要员','伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4487598f15c14c6fba9ae8cb0dd7bb0b','c50b87d5-55d3-472d-8a76-57a1f3f1f1a8',1936,'在察绥伪政权中任职','在察绥伪政权中任职，参与日军对晋陕绥边区的政治控制，其活动范围接近榆林、府谷一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f10dd0bf470c470f8f9334f7b4607bc5','131515e7-65c9-4527-8a10-38f3ca666873',1936,'蒙古族','蒙古族，早年参与内蒙古自治运动，后投靠日本，任伪蒙古军政府军事部长，协助德王组建伪蒙古军，参与日军在昭乌达盟、赤峰地区的治安作战和情报搜集。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3a312b7004b44b8967702c724df49e9','5044922e-6809-4d67-ad94-51e1fcad3b24',1936,'蒙古族','蒙古族，德王亲信，任伪蒙古军政府办公厅主任，后任伪蒙疆联合自治政府最高法院院长，参与伪蒙疆政权的立法与司法，为日军殖民统治提供所谓法律依据，其活动范围涉及昭乌达盟等地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d5cfae622a24f9e9e997966d72ed127','2b23aff2-7571-42d0-be6b-78052b7dab0f',1936,'蒙古族','蒙古族，早年从事内蒙古自治运动，后投靠日本，任伪蒙古军政府参议，后任伪蒙疆联合自治政府交通部长，负责蒙疆地区交通建设以配合日军军事运输，其管辖范围包括赤峰一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41daedcc4b3e4ad099a9185e22ef579f','97977938-b05d-48f2-9aad-e5df6ec9522c',1936,'蒙古族','蒙古族，原为南京国民政府蒙藏委员会官员，后投靠日本，任伪蒙古军政府参议，后任伪蒙疆联合自治政府民政部长，推行亲日教育、户籍管理，协助日军在蒙疆地区征兵征粮。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4e0963259ac424b9bf0ee8d5679b0bd','97977938-b05d-48f2-9aad-e5df6ec9522c',1936,'原为内蒙古自治运动成员','原为内蒙古自治运动成员，后投靠日本，在伪蒙古军政府和伪蒙疆联合自治政府中历任参议、民政部长等职，参与制定伪政权政策，推行日语教育、征粮征丁等殖民措施。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-127e3c605a194e1d9be95e2460696efc','e57220fe-f4e9-4215-81c9-b11f76d671b2',1933,'伪满洲国热河省警务头目','伪满洲国热河省警务头目，负责热河省（含今赤峰大部）的警察、特务系统，推行保甲连坐、治安肃正，残酷镇压抗日武装和民众，是赤峰地区伪警系统的核心汉奸之一。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8c0905457af46beb6d51bf6b8f09388','ee449353-1a9a-43dc-9a19-7e653dd89a40',1931,'原为东北军将领','原为东北军将领，1931年九一八后投靠日军，任伪满军洮辽警备司令，1933年率部配合日军进攻热河，参与侵占赤峰、昭乌达盟等地，后任伪热河省警备司令，镇压抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8c13913d3de476b8523494cf323c8cb','7e539248-45ca-4468-92ec-aa7f1bd1dd24',1933,'伪满军热河地区高级将领','伪满军热河地区高级将领，负责热河省（含今赤峰）的伪军警备和治安作战，配合日军对抗日根据地和游击区进行扫荡，推行集家并村、制造无人区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35b7c6718cfd46b59770849afee7b0e8','eefbd5dd-2763-4e27-9f11-cef32d822922',1933,'伪满热河省公署官员','伪满热河省公署官员，负责民生、物资统制，配合日军在热河省（含赤峰地区）征粮、征劳工，推行经济掠夺政策，为日军侵略战争提供物资保障。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a2ca383689b40bd845317c1f31e59e1','5e46a00b-8186-4a81-8e6c-ee4b966f988e',1933,'蒙古族','蒙古族，伪满洲国兴安西省（辖今赤峰北部、巴林左旗等地）警备军司令，后任兴安军管区司令，统率伪蒙古族部队配合日军在昭乌达盟、赤峰一带进行治安肃正，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d76d9c290b7e46e5a44d5da6a59fbd97','1ac7cf88-aab4-4965-ad3f-2cc5fce944f5',1932,'蒙古族','蒙古族，早年参与策划内蒙古独立运动，后投靠日本，任伪满兴安南省警备军司令，后任兴安军管区司令，其部队在昭乌达盟、哲里木盟一带配合日军作战，镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70a1ae79055f4f609a1672e77a71fc57','43a5ceef-0aae-4983-b829-65dcb4bd3bd9',1933,'蒙古族','蒙古族，原为扎鲁特旗札萨克，投靠日本后任伪满兴安西省省长，管辖今赤峰北部、巴林左旗等地，推行亲日政策，协助日军征粮征兵、建立保甲制度。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a1c95d6f69b45a5a12856b8fcb10044','735acf77-c070-40b9-9ab6-1a90138796d9',1933,'蒙古族','蒙古族，伪满兴安西省警备军高级军官，参与指挥伪军在巴林左旗、林西、经棚等地对抗日武装的扫荡，推行治安强化运动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c11d21ae471140e1b72eddfb969cd54f','2f6152ee-76db-4fdd-9c88-f12fc3aa1783',1933,'蒙古族','蒙古族，伪满兴安西省巴林左翼旗（今巴林左旗）旗长，直接在当地推行伪满政令，组织保甲、征粮征畜、征集劳工，协助日军和伪警镇压抗日民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb5955abede2473cbf415a0d6a8bb767','06e4a9f6-c913-4a24-8bfd-33fdc3f057ba',1933,'蒙古族','蒙古族，伪满兴安西省巴林右翼旗旗长，配合日军在巴林地区推行殖民统治，征粮征兵，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1c533b814574babb61a9326fc65b3a1','ca2c35ba-6bb4-463a-9fd5-3a573dd77a4f',1933,'蒙古族','蒙古族，伪满兴安西省克什克腾旗旗长，在克什克腾旗（邻近巴林左旗）推行伪满政策，协助日军征粮、征劳工，镇压抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4967afc8f5124a819dfaa18b4051d9ed','9d36a9f2-0d8d-4b39-87de-816824bea5a4',1933,'伪满热河省赤峰县县长','伪满热河省赤峰县县长，在赤峰县城及周边地区推行保甲制度、物资统制，协助日军征粮征款，镇压抗日民众和地下工作者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d62f79c79b14fcba77a276af13ca0b7','aef3e628-b476-4e17-96d3-a9cecf5baeb8',1933,'伪满赤峰县警务头目','伪满赤峰县警务头目，负责赤峰地区警察特务系统，搜捕抗日人员，推行连坐法，配合日军扫荡抗日游击区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-068d8dfeb1b648f18cc8986f0ddbafc8','124802de-5841-4e81-9073-43b3cd0a0445',1933,'伪满林西县县长','伪满林西县县长，在林西（邻近巴林左旗）推行伪满政令，征粮征畜，组织保甲，协助日军镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94d8ab0fd5494ee89ee60eefd9ef6572','06746fa5-e3e7-4339-bb81-d0bd91265c90',1933,'伪满经棚县（今克什克腾旗）县长','伪满经棚县（今克什克腾旗）县长，配合日军在经棚地区推行治安肃正，征粮征劳工，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db32dc9fcaaf4e09b8d479e194712797','ca45c51a-16a1-4768-a4e3-952658dbe964',1933,'伪满乌丹县（今翁牛特旗）县长','伪满乌丹县（今翁牛特旗）县长，在乌丹地区推行保甲制度，协助日军征粮征兵，镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb6da078656340999f73c1a7eecf2131','928256dd-9a48-4100-a4b7-0b8906b10567',1933,'伪满宁城县县长','伪满宁城县县长，在宁城地区推行伪满政策，征粮征款，协助日军扫荡抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b875693cecd4a2b851adf6ce75999f1','47aa5741-c4cc-4da2-bc37-2c5685400878',1933,'赤峰县商会会长','赤峰县商会会长，日军占领赤峰后出面组织维持会，为日军筹粮筹款，协助日军维持地方秩序，是赤峰地区经济界附逆代表。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43138d5ad5654833b305fec470dc1fe3','e487bcd3-a08e-44da-b56e-6747fb2459a8',1933,'伪满赤峰县教育局长','伪满赤峰县教育局长，推行亲日奴化教育，强制学校教授日语和伪满建国精神，篡改历史教材，毒害青少年，是赤峰地区教育界附逆代表。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42e7dc6ae94c42909cfa3d16dd7ba3e5','833e0c35-1d74-4740-85de-26e5c5ea9f85',1933,'蒙古族','蒙古族，伪满巴林左翼旗警务科长，负责当地警察特务系统，搜捕抗日人员，推行保甲连坐，配合日军和伪兴安军扫荡抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26aa302e98f24c7a865d343ba2232631','d03ca5a5-3c2c-4e89-8787-c4dec13f1335',1933,'蒙古族','蒙古族，伪满巴林左翼旗自卫团头目，组织地方伪武装，配合日军和伪警维持治安，镇压抗日民众，征粮征畜。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77e76d5f6176431b8fdb7709e63a24e3','82135400-9098-4ed9-aee5-685b5b3ecfec',1933,'伪满赤峰县警察署长','伪满赤峰县警察署长，直接指挥警察在赤峰城乡搜捕抗日人员，推行治安强化运动，制造白色恐怖。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b85dfc4e04ea46c98e9bc97ad968891e','7b989a8b-9b1b-4e4d-a47c-df83c59aff6d',1933,'伪满赤峰县协和会会长','伪满赤峰县协和会会长，利用协和会组织进行亲日宣传，协助日军征集劳工、物资，推行奴化教育，是赤峰地区文化宣传领域附逆代表。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccb948c7740b43bfa5dcea1870956962','480e2f44-b1c1-4c87-b16d-2dd9c6be296a',1933,'伪满林西县警务科长','伪满林西县警务科长，在林西地区搜捕抗日人员，配合日军扫荡，推行保甲连坐，镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-843b3a0f019745aea329b328c13fb293','647deb71-773a-4bc7-8485-ece5f892ec49',1933,'伪满经棚县警务科长','伪满经棚县警务科长，在经棚地区负责警察特务工作，搜捕抗日人员，协助日军维持殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-249ea89603ca4c5d965c92e9a94db493','a1421c98-ed07-44dd-acb1-f22e3a651a54',1933,'伪满乌丹县警务科长','伪满乌丹县警务科长，在乌丹地区推行治安肃正，搜捕抗日人员，镇压民众抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d6fca63c217474d8879cc3917a41e7a','02206e0b-7336-4f8d-a962-f75e8983a6a0',1933,'伪满宁城县警务科长','伪满宁城县警务科长，在宁城地区负责警察特务系统，搜捕抗日人员，配合日军扫荡抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96592004b7c044389c6a596f92f1d867','be78e255-32c7-4ab6-b74d-4c67cc38982e',1936,'蒙古族','蒙古族，早年从事内蒙古自治运动，后投靠日本，任伪蒙古军政府参议、伪蒙疆联合自治政府参议，为日军在蒙疆地区殖民统治出谋划策，其活动范围涉及昭乌达盟等地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
