INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06fe51f9391b44cbbd479f5ac9507977','77c3ce58-efee-4f41-8bec-275d461d2806',1933,'蒙古族','蒙古族，伪满兴安西省翁牛特左翼旗旗长，在翁牛特旗（邻近巴林左旗）推行伪满政策，征粮征兵，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
