INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57e2c840280f408f9fe9e58140d13064','1da3ec91-eb72-40ae-84e2-4e727b9bf02a',1933,'伪满赤峰县协和会事务长','伪满赤峰县协和会事务长，负责协和会日常事务，进行亲日宣传，协助日军征集劳工和物资，推行奴化教育。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
