INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ef037a657954559aa2749510643655c','65d55d1c-9ded-4bae-91c8-704f6623abea',1933,'伪满赤峰县农会会长','伪满赤峰县农会会长，协助日军征粮征畜，推行农产品统制，剥削农民，为日军侵略战争提供物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf0d3f7e162c42b686ac26a8d329c7ab','e077c7dc-3535-4929-b28e-8a72395cabc4',1933,'伪满林西县协和会会长','伪满林西县协和会会长，在林西地区进行亲日宣传，协助日军征集劳工和物资，推行奴化教育。','危害等级C（丙级，基层头目）','hanjian');
