INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b19ba5c30cc403cb9b4c32e8f3fbd29','715845e4-d136-467b-974b-af8d39b408c1',1933,'伪满乌丹县协和会会长','伪满乌丹县协和会会长，在乌丹地区进行亲日宣传，协助日军征集劳工和物资，推行奴化教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95e9dcae34154e7a92351cfe1086ddf5','09f05432-e48d-41b3-a2aa-80992d7cc1bb',1933,'伪满宁城县协和会会长','伪满宁城县协和会会长，在宁城地区进行亲日宣传，协助日军征集劳工和物资，推行殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc019c4828fe48a9b654f8e837b1d0fd','89d24af9-9cae-4c73-b913-5dc88d94c75c',1933,'原为热河地方军阀','原为热河地方军阀，1933年投靠日军，任伪蒙古军总司令，参与侵占赤峰、敖汉旗等地，镇压抗日力量，协助日军推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-caee6c79e201423990ec863648ea4d23','d271f089-ead6-4d47-90f3-b9163f0a1236',1937,'任伪敖汉旗旗长期间','任伪敖汉旗旗长期间，积极推行日伪“治安肃正”政策，强征劳工，搜刮粮食，配合日军“讨伐”抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7aa830f5786403c865e839449e89810','292c2ba0-5c58-4948-8b89-9ac07c134aa6',1938,'效忠日伪政权','效忠日伪政权，指挥警察抓捕抗日志士，破坏地下抗日组织，参与“清乡”行动，残害百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2249fa14ab594e3ba6580e442d07295d','05dde95d-05da-4585-b9f1-6f6268c6973b',1939,'率保安队协助日军“扫荡”','率保安队协助日军“扫荡”，在敖汉旗南部山区多次袭击抗日游击队，杀害多名抗日人员及群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a098724d95394518ba7c9756af02225c','d16e5382-7658-4cbd-b9e9-c8b3e314357b',1940,'推行奴化教育','推行奴化教育，强制学校使用日语教材，宣扬“日满亲善”，迫害有爱国倾向的教师和学生。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f03ca7154e7470f8757d55074f32318','e9a43108-c418-483d-8a14-88fbbfdf46a5',1941,'负责协和会宣传','负责协和会宣传，组织“勤劳奉仕”运动，强迫民众为日军修路筑堡，收集情报供日军使用。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3ddf38d6f3e42f0a152cfdc10f96c50','f25a2e98-1456-4cea-b95d-7469a49b0785',1933,'热河抗战后投靠日军','热河抗战后投靠日军，参与组建伪蒙古军，长期在赤峰、昭乌达盟一带配合日军围剿抗日武装，推行伪蒙疆政权统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dde0555fcd8248b09c0728c475f2f069','f25a2e98-1456-4cea-b95d-7469a49b0785',1933,'热河抗战后投敌','热河抗战后投敌，组织伪军配合日军侵占赤峰及昭乌达盟地区，在赤峰一带推行伪蒙疆统治，强征物资、镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8ff9b64a25449769cf4cf4d72c3b823','46a28399-d12c-4d29-befc-37dd6ecb8ee7',1936,'在日军扶植下建立伪蒙疆政权','在日军扶植下建立伪蒙疆政权，其势力范围覆盖内蒙古中东部，包括赤峰及昭乌达盟部分地区，推行亲日附逆政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94ad245985474cc08bd99f7ed72cb2a8','46a28399-d12c-4d29-befc-37dd6ecb8ee7',1936,'在日军扶植下建立伪蒙疆政权','在日军扶植下建立伪蒙疆政权，其势力范围覆盖赤峰及昭乌达盟，推行亲日卖国政策，协助日军控制内蒙古东部地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ac893175ed14e50bbf1f75c53d63c30','9f26afb7-a2f7-48b0-a39c-923df661f206',1936,'绥远、内蒙古西部投日汉奸武装头目','绥远、内蒙古西部投日汉奸武装头目，其活动与伪蒙疆政权关联，间接影响赤峰地区伪蒙统治体系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5228bb58d1e848b89a7aa685860b5f81','f384dbe9-69cc-4b00-b7ee-1d3864bf1a26',1937,'伪蒙疆政权汉奸官员','伪蒙疆政权汉奸官员，协助日军在内蒙古及周边推行保甲、征粮、劳工等政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f46b8dc71694456f80aedc09b5e30834','bee57c51-83aa-4b68-bd70-b15c034f23da',1936,'参与伪蒙疆政权警务与地方行政','参与伪蒙疆政权警务与地方行政，在赤峰等地的伪警察系统中配合日军镇压抗日人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60d1a7a3f423443d9f1a1b8996b7be4f','881efc13-ce50-4947-9649-e433a79593ae',1933,'热河沦陷后附逆','热河沦陷后附逆，参与伪热河省政权，赤峰属热河省，其行政体系覆盖赤峰地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54b526be2d99453e8f4b2b18124298b4','21dcda44-9818-46cb-9301-dd2524eb5cdc',1931,'九一八后投日','九一八后投日，率伪军参与侵占热河，赤峰地区沦陷后其伪军配合日军维持统治、讨伐抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8fdcc392df514055842bd1d1f3a02a44','21dcda44-9818-46cb-9301-dd2524eb5cdc',1931,'率部投敌','率部投敌，参与日军进攻热河，其伪军活动范围包括赤峰地区，配合日军镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3424beaf138e4a0d845b25aff6033bdd','21dcda44-9818-46cb-9301-dd2524eb5cdc',1931,'原东北军将领','原东北军将领，九一八后投敌，率伪军配合日军进攻热河，参与攻占承德等地，在承德及河北北部地区进行殖民统治与军事镇压。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c7c1e2ab62a4911b112c0c749f4e061','34d9bdda-e64d-460b-8661-c232d6ac86af',1933,'流窜热河、赤峰一带的武装匪首','流窜热河、赤峰一带的武装匪首，曾投靠日军任伪职，在赤峰周边烧杀抢掠并配合日伪行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-87c925a9ef304e6b935d29b202569d15','019139f7-7e79-46b2-a564-4be032503d37',1933,'赤峰沦陷后出任伪县长','赤峰沦陷后出任伪县长，推行日伪政令、征粮征丁，协助日军控制赤峰地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b4aa00e95b14e5aad475ae191b990c0','d6f31947-53e3-4157-8b4f-1d1345a4e4ca',1933,'在赤峰地区充任伪警察官员','在赤峰地区充任伪警察官员，参与搜捕抗日人员、维持保甲连坐制度。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfce5f0f0d25418392ade46f2a9e987a','afd50127-6f6f-44c8-81a0-e75828e47a93',1933,'赤峰沦陷初期组织维持会','赤峰沦陷初期组织维持会，为日军筹粮筹款、招募伪职人员，协助建立殖民秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd5ccd668aea48fa97a5e0f0d854479c','94d9358c-b5cc-4270-9241-bb2f56bbec9e',1933,'作为赤峰商界附逆代表','作为赤峰商界附逆代表，为日伪筹集物资、摊派款项，协助经济统制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77253ae288924ffdb3c8016d0e8c0359','8617cde6-93be-4039-b72b-29731dfdf62e',1933,'赤峰北部昭乌达盟地区蒙古王公附逆','赤峰北部昭乌达盟地区蒙古王公附逆，出任伪旗长，配合日军推行伪蒙疆统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39b2f6bd9bcd49f786e0dfcb317ccf89','4d642bb1-e3d0-42e2-93e0-7edd0508e2a5',1933,'在赤峰附近昭乌达盟旗地投日','在赤峰附近昭乌达盟旗地投日，协助日伪征收牲畜、粮食，维持地方伪政权。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e00a2bb25deb4627877251518770c0c4','dc307881-9308-4d72-bc61-adbe23922653',1933,'在伪兴安西省（辖赤峰北部）任职','在伪兴安西省（辖赤峰北部）任职，参与日伪对昭乌达盟地区的行政与警务控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b341e6cef1648d281a408fbc50629ab','1f877a31-16c7-4de9-9cb6-33c13ed72434',1930,'伪蒙疆政权中的汉奸官员','伪蒙疆政权中的汉奸官员，参与对内蒙古东部包括赤峰地区的殖民宣传与行政。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34ca0d5c42c24edd815f696b0b407ce2','1f877a31-16c7-4de9-9cb6-33c13ed72434',1930,'投靠日本','投靠日本，参与伪蒙古军政府及伪蒙疆政权活动，在内蒙古东部与西部之间进行联络与统治，其活动与通辽一带蒙旗有间接关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54a7d20f93d2413e9deea1dd208f7670','a02f5db9-91d4-41dd-8410-754c513af965',1936,'早期蒙古独立运动投日分子','早期蒙古独立运动投日分子，在伪蒙疆政权中任职，其活动范围涉及赤峰周边。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80a10265a4024ac28e3f9cc57908e9bb','c10eb228-e965-428b-ab62-c3f1f620cc4d',1933,'任伪林西县县长期间','任伪林西县县长期间，为日军征粮派夫，强征民力修建军事设施，协助日伪政权推行保甲制度，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b95029f7952347eeac1882aa96f5c6bc','d782ae10-b096-47ff-9f69-9b26f07e85e0',1933,'原为地方土匪头目','原为地方土匪头目，投日后任伪保安队队长，率部配合日军“扫荡”赤峰、林西一带抗日武装，残害百姓，掠夺财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a1d1c3108da4ce980d1b6c10f38ad52','5825c0a3-ec71-4560-9094-7da8316a7471',1935,'任伪警察署长期间','任伪警察署长期间，积极搜捕抗日地下人员，破坏抗日组织，为日军提供情报，并参与强迫民众种植鸦片等殖民经济政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9386893a751c4eee90025b9cbcd8a379','0f6a1448-5e14-4677-8ef8-97a3ab7b832f',1933,'日军占领赤峰后','日军占领赤峰后，率先组织维持会，为日军筹粮筹款，协助建立伪县公署，后任伪赤峰县协和会会长，推行奴化宣传。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-050d622552264b538f084b21e6a986b2','d40c2d6d-97bd-4b67-b02d-a1079a2a629c',1938,'负责伪协和会在林西的日常事务','负责伪协和会在林西的日常事务，组织“宣抚班”进行亲日宣传，强迫民众参加“勤劳奉仕”劳动，为日军提供劳役。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c644f24eb56d42cdb59b708af408388d','12adbc98-3b33-438c-8d1d-2a4ed3adee7a',1935,'为日军特务机关担任翻译','为日军特务机关担任翻译，参与审讯、迫害抗日志士，多次带领日军搜查林西、赤峰周边村庄，导致多名抗日人员被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f64c045abe47425b98e480442aa70691','cee53972-1edc-42e7-895d-2ff4ff85b150',1931,'与甘珠尔扎布共同投日','与甘珠尔扎布共同投日，在昭乌达盟及赤峰地区协助日军建立伪政权、编练伪军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf2cb6dea3b74898bdfacf9f3ddfc9a9','efd18702-42c0-4996-9834-9e7fc941d8d5',1932,'率部投靠伪满洲国','率部投靠伪满洲国，在赤峰及周边地区镇压抗日武装，维持日伪统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-784a7fef18ad4d04a62235cb5d7d2ab5','efd18702-42c0-4996-9834-9e7fc941d8d5',1932,'扎赉特旗王公出身','扎赉特旗王公出身，投靠日军，任伪兴安南省警备军司令等职，活动范围包括哲里木盟、通辽一带，率伪军配合日军“讨伐”抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae985bae1d604293a9d5c9c9f814b91f','bbac8a22-e9dd-4e19-8aaf-077b8e40e903',1933,'在赤峰红山及周边旗县任伪职','在赤峰红山及周边旗县任伪职，协助日军征粮、抓劳工，推行保甲连坐。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10a5a368afdb43359a7387f257ed2f69','597d5cab-459e-4976-adab-685779aa523e',1933,'投靠日伪','投靠日伪，在赤峰北部旗县推行伪政，配合日军清乡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c7cb16ff9104cb1845327b5a256b03b','3ddd2ff4-c735-4477-9908-7890d481655f',1933,'日军侵占赤峰后出面组织维持会','日军侵占赤峰后出面组织维持会，后任伪县长，为日军筹粮筹款、镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c115a48c2cd94b0283e1142eb3a219c4','0a16866d-7617-48c5-b8cf-1937644892cb',1933,'在赤峰红山地区充任伪警察头目','在赤峰红山地区充任伪警察头目，搜捕抗日人员，实施白色恐怖。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31031249b01f428d903055c59c4cc7ec','b93f1ba7-1e36-4dc2-a868-8c14d8dc6ada',1933,'在经济领域附逆','在经济领域附逆，为日军统制物资、掠夺地方资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1487061a45564d8292141ef6f12006a2','47d6c1f5-f580-4a6b-9fc0-385095f2882e',1933,'在赤峰地区推行伪满警务统治','在赤峰地区推行伪满警务统治，参与抓捕抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71fffb6e87604f82b1ea05816854844f','f95c67b0-a688-4dd3-ad24-841a6a98ce3a',1933,'在赤峰南部喀喇沁地区任伪职','在赤峰南部喀喇沁地区任伪职，协助日军控制地方。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e826653b215b40929fc5a45d6cb9fb84','c20d430c-550a-4306-a88f-7300d5c85d29',1933,'在赤峰南部宁城地区组织维持会','在赤峰南部宁城地区组织维持会，投靠日伪，为日军服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3679f86302594bbe9cb0481c10526496','7bc7be9e-9dc5-4dd4-bd71-b53bca439ab0',1932,'在赤峰及昭乌达盟一带率伪军配合日军作战','在赤峰及昭乌达盟一带率伪军配合日军作战，镇压抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6340ba01d2144857893723501ceba8a4','0b40ad56-4499-4ede-84af-ca27d4c86a4d',1933,'蒙古族出身','蒙古族出身，早年在热河、昭乌达盟一带活动。1933年日军侵占热河后投敌，任伪军头目，参与组建伪蒙古军，长期在赤峰、翁牛特旗及昭乌达盟地区配合日军围剿抗日武装、推行伪政。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da152b565db5428685dc1ff93aebffd8','af0daf44-075e-422a-b766-c4505bebdb9d',1932,'扎赉特旗王公出身','扎赉特旗王公出身，投靠日本，任伪兴安局总裁等职，参与伪满对内蒙古东部盟旗的统治，赤峰、翁牛特旗所在昭乌达盟亦在其伪政权体系影响范围内。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a594cf4489e444cbeeb867e48b5ead3','68808478-de1a-495b-8184-a2883c45844f',1932,'蒙古族王公','蒙古族王公，投靠日本，在伪满兴安系统任职，参与对内蒙古东部盟旗的殖民统治，活动范围涉及昭乌达盟及赤峰地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4fb16b660794adea32b0363087aaef7','7bc41e4e-61c6-4627-a89e-9c053765d2c1',1932,'蒙古族上层','蒙古族上层，投靠日本，在伪兴安系统任职，参与伪满对内蒙古东部地区的控制，与赤峰、昭乌达盟一带伪政权有联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-858ade22b7ef4007a3ee1445405f4bda','1554af4d-0933-4de3-a8d4-5e192ed03d74',1933,'蒙古族','蒙古族，投靠日本，在伪蒙古军、伪兴安军中任职，参与内蒙古东部地区军事活动，配合日军在赤峰、昭乌达盟一带作战。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bbd1ae48b3f04cb29d0405d7053d9a3c','bfe37425-8d31-42c6-bfff-bc4f26e3e142',1936,'蒙古族','蒙古族，投靠日本，在伪蒙古军政府及伪蒙古联合自治政府中任职，参与伪政权对内蒙古东部盟旗的统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1920d9fc0f1c4481a8cec41c05b24301','a0cf08a7-8787-4900-abfd-eb56858e88b6',1936,'蒙古族','蒙古族，投靠日本，在德王伪政权中任要职，参与伪蒙古联合自治政府的政治活动，其活动与内蒙古东部包括赤峰地区伪政权有关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b1b8f6d1d96487b89dc4d736bc88546','5de5924e-7380-47e0-8070-cb3f545c2ec6',1933,'赤峰沦陷后投敌','赤峰沦陷后投敌，在伪赤峰县公署任职，协助日军推行保甲、征粮、抓丁等殖民统治措施，直接涉及赤峰及翁牛特旗周边地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6ae09dbcc9247d798b31b1529b4c75b','4f6f3591-0de8-429e-80d3-4709bf3f16d3',1933,'赤峰沦陷初期参与组织维持会','赤峰沦陷初期参与组织维持会，后进入伪赤峰县公署任职，为日军筹粮筹款、维持地方治安，配合日伪统治赤峰及翁牛特旗一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00f36fe8da9d4130b2a96fa5a4c66c6f','ddf7b12d-69e2-4c6d-824e-e89cd32af3ed',1933,'翁牛特旗沦陷后投敌','翁牛特旗沦陷后投敌，在伪旗公署任职，协助日军推行旗县伪政、征收赋税、控制农牧民，直接涉及翁牛特旗地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-291326d0ca174f9abc146435cd318519','c1815a02-ab5d-40bd-bbbf-ea461e8e20df',1933,'在伪翁牛特旗警察系统任职','在伪翁牛特旗警察系统任职，参与镇压抗日群众、搜捕抗日人员，配合日军维持翁牛特旗及赤峰周边治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3055dfb0c7e147788415165a3f5668ec','69368796-bd80-4dff-beb1-d5ebcad2d829',1933,'在伪赤峰县警察系统任职','在伪赤峰县警察系统任职，参与日伪治安强化运动，搜捕抗日分子，活动范围覆盖赤峰及翁牛特旗周边。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcc75145aa18426bb5e21d0e527ac5df','369fe52b-8ffd-418a-bea1-69632a074d3d',1933,'在伪满协和会赤峰分会任职','在伪满协和会赤峰分会任职，协助日军进行思想控制、宣传“王道乐土”，推行奴化教育，活动涉及赤峰、翁牛特旗一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e53b57723f9459a869e169c7f542c20','e1106804-f580-4f74-b38e-267c0e5bb353',1933,'赤峰沦陷后在伪教育系统任职','赤峰沦陷后在伪教育系统任职，推行日语教育和奴化教育，协助日伪控制赤峰及翁牛特旗地区学校。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8f776b1733748758d15712a1c79f55f','52eebe76-e2e3-420d-917f-9a81599bf425',1933,'在伪赤峰县商会任职','在伪赤峰县商会任职，协助日军统制经济、征购物资，为日伪在赤峰及翁牛特旗地区的殖民经济服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b82d6a1ccbdf4119a9742afd87781668','c3a26859-2ba3-44bf-b8c6-33bc8ebd3c9f',1933,'翁牛特旗蒙古族王公','翁牛特旗蒙古族王公，投靠日本，任伪翁牛特旗旗长或札萨克，协助日伪统治翁牛特旗，推行伪政、征粮征畜。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79d9d85c1b4f4f2d9be914bc8ce074c4','dfe308a0-3cd2-4b73-8146-5f7601731959',1933,'在伪翁牛特旗公署任职','在伪翁牛特旗公署任职，协助日军推行保甲制度、控制农牧民，直接参与翁牛特旗地区伪政。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17b29ea99d5945458a5f3077cc4b5e66','9f0c143b-a081-453f-9cad-4aff4ae492f2',1933,'在伪赤峰县公署任职','在伪赤峰县公署任职，协助日军办理政务、征发劳工，活动范围涉及赤峰及翁牛特旗周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97397307585c4b8a9d8a1571bbd82d7e','e339afcb-51ca-4607-b93c-e6d8a2e89e14',1933,'在赤峰地区担任伪保甲长或维持会头目','在赤峰地区担任伪保甲长或维持会头目，协助日军征粮、抓丁、维持治安，直接涉及赤峰及翁牛特旗基层。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cadb374103640b7984bb43ee9867106','90a74829-c0e9-4a47-a563-f41fa64771c3',1933,'在伪赤峰县警务系统任职','在伪赤峰县警务系统任职，参与日伪治安肃正，搜捕抗日人员，活动于赤峰、翁牛特旗一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d95b9d05d71d49a4bf76fe7b0b0a7221','c25d3820-2887-468f-9949-111bb1f57e35',1933,'在伪满协和会赤峰分会任职','在伪满协和会赤峰分会任职，协助日军进行宣传、训练和思想控制，活动涉及赤峰及翁牛特旗地区。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d95804da44244de78c92db90c2657d30','0b023ff3-61e8-4b78-ad9b-75fc83bf715a',1933,'热河抗战后投敌','热河抗战后投敌，组织伪蒙古军，配合日军侵占赤峰及昭乌达盟地区，在阿鲁科尔沁旗一带推行伪蒙疆政权统治，强征物资、镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b00071ba57944f8b99dd17f2a1fb9d08','e432a816-251d-4a82-9e7c-d69d3f9e6fac',1931,'参与策划蒙独活动','参与策划蒙独活动，投靠日本关东军，在伪满洲国兴安省及昭乌达盟地区协助日军统治，涉及赤峰、阿鲁科尔沁旗一带的伪军组织与治安肃正。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84f0708b9d0a4a329436d99a05e784f1','2c52e9a1-0f86-4583-a5a6-d63f7a99535d',1931,'与甘珠尔扎布共同投日','与甘珠尔扎布共同投日，在伪满洲国兴安地区任职，参与对昭乌达盟及阿鲁科尔沁旗一带的殖民统治和军事镇压。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-923c6b3b5e6a4023bb649731c5dc016d','fa0fc63c-f60d-4799-b3ab-83022fa1b105',1932,'投靠伪满洲国','投靠伪满洲国，任伪兴安军要职，在昭乌达盟及赤峰地区协助日军维持治安，镇压抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1178cb7fe194eb7a91dfeefb59182da','1ada0e35-5ac8-4eb3-919a-14377cbb2153',1930,'在伪满洲国时期任阿鲁科尔沁旗旗长','在伪满洲国时期任阿鲁科尔沁旗旗长，执行日伪政令，征派劳工、物资，配合日军对当地抗日力量进行压制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d30087b260624a95b4c76c355a9e8b0f','c08165cb-4b00-4c03-80bc-e6f741749ffb',1930,'作为阿鲁科尔沁旗伪旗长','作为阿鲁科尔沁旗伪旗长，协助日伪推行保甲制度、征集粮秣牲畜，维持殖民统治秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29769305ae4b4a2590562ddc9c27b8f4','89a006f5-43c8-4303-a4e2-4aec53ae2338',1933,'日军侵占赤峰后出任伪县长','日军侵占赤峰后出任伪县长，推行伪满政令，协助日军征粮、派工，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac4e06ec221e4d8e8937750cb63efbab','7924a367-1a19-424b-a048-30438f129bdf',1933,'日军占领赤峰初期组织维持会','日军占领赤峰初期组织维持会，为日军筹粮筹款、维持地方秩序，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-066ca3b74ef248ba92f576e99b0b1049','1bbf3db2-a133-47ba-9fbf-ee2f88eb3565',1933,'在赤峰商界为日伪服务','在赤峰商界为日伪服务，协助经济统制、物资征集，支持日军殖民经济政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-863e85bb1f214a47bff1d6341c003d5c','551e5b88-4a04-4e58-9f8a-5d96a2ba859d',1933,'曾投靠日军','曾投靠日军，率部在赤峰、昭乌达盟一带流窜，配合日军扫荡抗日根据地，残害民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76d0aed67d6a4eb9b78cb4952f36e562','7b7ac4f9-08b8-48f7-9e62-bafdc19a624f',1931,'投靠日军','投靠日军，参与侵占热河，其伪军活动范围包括赤峰及昭乌达盟地区，协助日军镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c02b116b614548ad86eff0eba6eabc51','22103b77-bcfd-49cd-9386-2f72068c9fce',1931,'原东北军将领投日','原东北军将领投日，任伪满军政要职，其指挥的伪军参与热河、昭乌达盟地区治安肃正，涉及赤峰一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d826c57f91d94877b0ac4fc93dfc6b2f','148147c2-9c34-45db-94c5-afb0be524eb4',1933,'在伪热河省任职期间','在伪热河省任职期间，推行警务统治，镇压赤峰、阿鲁科尔沁旗等地的抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6d0abf47ae544129dd114c2d93fbb5c','f9b242d2-1fa8-4cf2-b8ac-cad7f82b89d4',1930,'任伪旗警务科长','任伪旗警务科长，指挥伪警察配合日军搜捕抗日人员，维持当地殖民治安。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16a1e1fdb4da40de8cbba9d0d278e77f','08ab8240-39be-41f3-9fff-6d699162904d',1931,'蒙古族投日分子','蒙古族投日分子，参与组建伪兴安军，镇压抗日力量，协助日军统治通辽地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abeef655316c4b7f9adc93a8afaee67a','08ab8240-39be-41f3-9fff-6d699162904d',1931,'蒙古族贵族','蒙古族贵族，投靠日本关东军，在通辽地区组织伪兴安军，配合日军围剿抗日武装，镇压当地民众反抗。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcef996b81fe4cc6a09d2d7a88fdf814','c0885408-900a-4162-a1b0-abcece28d6e5',1932,'甘珠尔扎布之弟','甘珠尔扎布之弟，积极推行日满蒙一体化政策，协助日军在通辽地区实施殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-055570407c14452e9ee2c749e5b58842','cea9ae1e-5ff7-40bd-b5a0-29f6adea8cc4',1932,'参与组建伪兴安骑兵部队','参与组建伪兴安骑兵部队，配合日军扫荡通辽周边抗日游击队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e80a35ebf3e14c61944dce7f43c96bc0','bf81bd75-695c-43cb-ad48-91fc6800b5d8',1933,'为日军提供情报','为日军提供情报，参与强征蒙古族青壮年入伍伪军，镇压民众反抗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0e39b97d0f74b1ebbc0da5b544bb5d7','bc8c32bd-fd42-41ff-8f87-9853e56acc36',1932,'投靠日军后任伪县长','投靠日军后任伪县长，推行保甲制度，强征粮食物资，协助日军建立殖民秩序。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c5b6aca876a4b86934a9c07da95cf85','510fbe22-7738-4a78-8589-99ad3d20646a',1933,'指挥伪警察抓捕抗日志士','指挥伪警察抓捕抗日志士，破坏地下抗日组织，为日军提供通辽地区抗日活动情报。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db537e2eac84425481c20ebcc1a44787','37933569-58a9-4706-b5b1-71e4ccba5bba',1931,'原奉系军阀','原奉系军阀，九一八后投日，率伪军参与侵占通辽及周边地区，屠杀抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69c01646690943359f410b37b2662716','1961cb13-d7c4-4f2a-a7aa-77f12660d9eb',1933,'蒙古族投日头目','蒙古族投日头目，率伪蒙古军配合日军在通辽地区清剿抗日武装，参与建立伪蒙政权。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e20e87cdb37c403aad32cbd51a73aad2','8df7e1c4-201f-4d68-82cd-1c3b1d85bf94',1936,'虽主要活动于锡林郭勒','虽主要活动于锡林郭勒，但其伪蒙政权势力延伸至通辽，支持当地伪军镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f95b19f652804881aed88493f404a95e','7cb468ed-e85a-4b21-96e3-80dbeb4e888b',1932,'率保安队协助日军扫荡','率保安队协助日军扫荡，多次参与围剿通辽境内的抗日义勇军和地下党。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-438eaab612f34aabb080ad0fe40bcbac','7cb468ed-e85a-4b21-96e3-80dbeb4e888b',1932,'率保安队配合日军在通辽经开区（原通辽县辖区）一带清乡','率保安队配合日军在通辽经开区（原通辽县辖区）一带清乡，烧毁村庄，杀害无辜百姓，掠夺财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09f1c9df5703473d8cee4c1be95dca6f','9a64a9d4-e4cf-4b96-8646-777f706e0bad',1935,'专门负责侦破抗日地下组织','专门负责侦破抗日地下组织，严刑逼供，导致多名抗日志士牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce0ca385c606449b880c8873c1ad38d3','6774278c-e27a-4309-9f4c-b3ce6f82351c',1932,'协助日军推行“治安肃正”计划','协助日军推行“治安肃正”计划，强征劳工修筑军事设施，压榨当地民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae265a3f75ed47689c89abcef42e8742','56f4d3f5-1b5d-4dd9-a3da-5d93c0bab8a5',1931,'蒙古族贵族出身','蒙古族贵族出身，投靠日本关东军，参与组建伪兴安军，在通辽、奈曼旗一带镇压抗日武装，协助日军推行“治安肃正”计划。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d194b3dc32664a89bab320c657d31723','e45f4353-49fc-4827-8fd8-1fec68e14b3f',1931,'甘珠尔扎布之弟','甘珠尔扎布之弟，长期在奈曼旗、通辽地区活动，率伪军围剿抗日游击队，为日军搜集情报，残害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d4aa7efe0c3432ba37bbe9b15092c5b','2513a058-8331-4fee-8238-395511a62477',1932,'原东北军军官','原东北军军官，投日后任伪兴安南省（辖通辽、奈曼旗）警备军司令，多次配合日军“讨伐”抗日力量，参与建立伪政权。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed4fd0b1fa2f48439946b9e058d61e88','84229f98-f3a4-46bb-8743-22742e06664d',1933,'在奈曼旗任伪职期间','在奈曼旗任伪职期间，强征民夫修建警备道路和碉堡，为日军提供粮食和物资，镇压当地抗捐抗税民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9bacab145ad48dc9b15bf169725dd4d','029794fc-5ee9-41ff-9f15-1759982693a5',1933,'热河土匪出身','热河土匪出身，投日后率伪蒙古军多次侵入通辽、奈曼旗地区，配合日军扫荡，烧杀抢掠，并协助建立伪蒙疆政权。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba8d531afd7a450dbfa1519a0ff5e358','02ab104b-11b2-4918-a9ff-4c414c391c6c',1932,'在通辽县任职期间','在通辽县任职期间，积极协助日军搜捕抗日地下人员，破坏抗日组织，多次带队袭击奈曼旗边境的抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-729fb6feb63b4277975eaef46b00189d','f75ec01d-c6b2-4b92-919d-dbfd777fd677',1931,'原奉系军阀','原奉系军阀，投日后其势力曾控制奈曼旗部分地区，为日军提供兵源和情报，参与围剿辽西抗日义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4555758ef1cb497582181d3e9e9915e1','ac04d0b1-2e7f-4c1c-95f5-3dffea5fbb9e',1935,'投靠日伪政权','投靠日伪政权，任库伦旗伪旗长，强制推行‘粮谷出荷’政策，强征民夫修建日军工事，迫害抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca06ce639805412da5f79667501df59e','1ea14d82-df70-4986-b1db-19f342055b6e',1932,'原为地方士绅','原为地方士绅，后投靠日军，任伪通辽县县长，协助日军建立保甲制度，搜捕抗日地下人员，强征军粮。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-137f0473d02f4b098b43936425600aca','adb17b6d-7fec-41b6-8fc1-5d2a49223071',1934,'蒙古王公出身','蒙古王公出身，投靠日本关东军，任伪兴安西省省长，管辖通辽、库伦旗等地，推行‘蒙地奉上’政策，为日军提供兵源和物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8e052538ab44a8b901f9f239526f6f4','dd1704fe-c3db-4191-a44a-eee483875e8b',1935,'在通辽、库伦旗地区组织伪警察队','在通辽、库伦旗地区组织伪警察队，参与‘清乡’行动，杀害抗日军民，协助日军强征劳工。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28bd344a005c43f0a5147fa854542b21','a6c2cb56-43b2-48e5-b544-cbad8e0e5349',1931,'原奉系军阀','原奉系军阀，九一八后投敌，率伪军多次进犯通辽、库伦旗，围剿抗日义勇军，烧毁村庄。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf7396043e0d4294bf35a9828521ffa5','4dd1bdb4-0c19-48e1-bc3d-7773436a9c57',1933,'土匪出身','土匪出身，投靠日军后率伪军在库伦旗、通辽一带‘讨伐’抗日武装，屠杀百姓，掠夺牲畜。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61b144ed0798404fa26202ed53384233','6c51b420-a2c1-44c1-8d2a-fd4e7d5cc2e2',1931,'蒙古族','蒙古族，早年参与“九一八”后日军侵占内蒙古东部活动，在伪满洲国兴安省系统任职，活动于哲里木盟、通辽一带，参与组建伪军警力量，镇压抗日民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-263f9755b47d4a6fa9ec7285b6113c16','c7c2b3a5-cf8b-4183-9158-c3cb38880433',1931,'甘珠尔扎布之弟','甘珠尔扎布之弟，投靠日本关东军，在伪满洲国兴安省及哲里木盟地区活动，参与伪军组织与治安肃正，配合日军控制通辽、开鲁等地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36fa803fc9bd41eb8cbf9ba6c8e96781','d39c10c1-d5e1-4040-897e-72a404f1c680',1932,'蒙古族','蒙古族，伪满洲国时期在兴安省系统任职，曾任伪兴安南省省长，管辖区域包括哲里木盟、通辽等地，推行日伪殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86bb21af794d4047bcf9cf395e09f3e6','edcc0a14-0827-4e03-8105-5ef6d3853bfc',1932,'在伪兴安南省及哲里木盟地区任职','在伪兴安南省及哲里木盟地区任职，参与伪军警活动，配合日军维持通辽、开鲁周边治安，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-252e09029b4c4eb89c6f6639779bf9dd','022cdc7f-1a04-4692-a3c2-d59088904e44',1933,'开鲁沦陷后出面组织维持会','开鲁沦陷后出面组织维持会，后任伪开鲁县县长，为日军征集物资、推行保甲制度，协助日伪统治开鲁地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c71b19b058c14b08a143cb2944bc5868','f6626455-7b75-4422-8371-bcc118dd25d9',1932,'通辽沦陷后在伪政权中任职','通辽沦陷后在伪政权中任职，参与维持会及伪县公署事务，协助日军征粮、派夫，推行殖民统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92f303e27a204c758e4b9748703c7fe3','59091edf-e89d-42b1-a5a4-599b26e4aab3',1932,'曾一度附逆','曾一度附逆，在通辽、开鲁一带活动，后率部抗日','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-baab347be8ac4e0c93c6319ef8b48f6d','59091edf-e89d-42b1-a5a4-599b26e4aab3',1932,'其附逆期间配合日军维持地方治安','其附逆期间配合日军维持地方治安，属于该地区有记载的伪军人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-811693566d44480abec5dcf7556d7094','62aab994-ec37-41be-8d34-4af838e9020d',1933,'蒙古族','蒙古族，投靠日军，在伪蒙古军及伪兴安军系统任职，活动于内蒙古东部，包括通辽、开鲁周边，参与对抗日武装的军事行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4542e7f279c4862be59ca1c4157ef4f','ac05cc8f-7028-46ac-8637-6a05efaad0b5',1932,'哲里木盟蒙古族地方武装首领','哲里木盟蒙古族地方武装首领，投靠日军后任伪警备军司令，控制通辽、开鲁一带，配合日军“治安肃正”，镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cd1f9c1201e40569d1604ed2eebc922','a3c6d875-76e3-4d75-b4d3-38109609494f',1932,'在伪哲里木盟地区任职','在伪哲里木盟地区任职，参与伪军警活动，协助日军控制通辽、开鲁等旗县，推行保甲与物资统制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf2a9729eee5401e975bdafc52a4e816','3e1f22a1-35de-43a5-8a7f-e4a6ecb9a117',1932,'哲里木盟一带蒙古族地方武装头目','哲里木盟一带蒙古族地方武装头目，投靠日军后编入伪军，在通辽、开鲁周边配合日军行动，骚扰抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb59f23e61634bbfa003f612a3f1b3cf','3e5c58b2-1185-4465-9dfd-65c06a6e5bcd',1933,'原为东北军骑兵军官','原为东北军骑兵军官，后投靠日本，参与组织伪蒙古军，任伪蒙古军总司令等职，配合日军在内蒙古东部及热河、察哈尔一带作战与统治，其势力活动范围涉及通辽及周边蒙旗地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84237547076244969d2ac9a10d1bd740','62f1a4d9-eb85-4dc0-b8b7-63af3aeb681f',1931,'蒙古王公出身','蒙古王公出身，九一八事变后投靠日本，参与策划内蒙古东部‘独立’活动，后在伪满洲国任职，参与统治包括通辽一带在内的东蒙古地区，协助日军镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7fa86a06894b46d9bcefec7bfe4931ca','09c1bff1-4ab2-4061-a5f7-32ac41a44611',1932,'原哲里木盟科尔沁左翼中旗札萨克','原哲里木盟科尔沁左翼中旗札萨克，投靠日本后任伪兴安南分省省长等职，管辖范围包括今通辽一带，推行伪满政策，协助日军控制东蒙古地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38854fe0041c40f3981f2c242ebb9557','67772962-bf48-40d4-90a4-f238a362e650',1932,'在伪满洲国时期于兴安南省任职','在伪满洲国时期于兴安南省任职，参与管理今通辽及周边蒙旗事务，执行日本殖民统治政策，属于当地附逆政权人物。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5468e55def5b4df48fc6295b30513fa3','b4055852-db45-48b3-b2b7-d361c06ce7db',1932,'作为东蒙古王公之一','作为东蒙古王公之一，投靠伪满洲国，在兴安南省范围内协助日军和伪政权管理地方，其活动区域与今通辽市及扎鲁特旗周边有交集。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0958b63025de41268957cc9156cc92f1','58f57afa-db12-4cd8-95e2-dc39dc22592a',1930,'曾在伪满洲国兴安南省警备军任职','曾在伪满洲国兴安南省警备军任职，参与维持日伪在东蒙古地区的统治秩序，活动范围涉及通辽一带','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88876d55076c4a10a0e7a972ea437715','58f57afa-db12-4cd8-95e2-dc39dc22592a',1930,'后于1945年后转向内蒙古自治运动','后于1945年后转向内蒙古自治运动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d18a08da5a92419193d79ead2947794d','76d3864d-3d1e-4e52-8a7a-f35d3c3f2c45',1930,'在伪满洲国时期担任兴安南省地方旗县职务','在伪满洲国时期担任兴安南省地方旗县职务，协助日伪推行保甲、征粮、劳工等政策，属于通辽周边地区附逆地方头目。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-51c37012fdcd4f02861cd5f79a3a0dc4','eb59bf89-86ab-4d1b-bc0c-8b5c5c482f7c',1930,'在伪满洲国东蒙古地区任职','在伪满洲国东蒙古地区任职，参与地方行政与治安维持，配合日军对通辽及周边蒙旗的控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88aa661b430246eebd3c48a6be439051','1b71c1f3-e547-4f0f-bedc-1e2c800b077a',1930,'在伪满洲国通辽县任职','在伪满洲国通辽县任职，参与伪政权地方行政与警察事务，协助日军维持统治、镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7339dc8f1fa4fc6af2cda9485770222','c201b66d-acf2-4431-aef4-1e0a6ac5ffff',1931,'原东北军军官','原东北军军官，投靠日本后任伪奉天警备司令等职，其伪军活动范围覆盖辽宁、内蒙古东部及通辽周边，协助日军维持殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a0ce800559d4e56bb3db14327ebd6fa','96b40654-6d32-4d35-82ed-c1939954cf0f',1930,'在伪满洲国军中任职','在伪满洲国军中任职，参与辽西及内蒙古东部地区治安作战，活动范围接近通辽一带，协助日军镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b8aedff1bcb4778b4e2ba47f7ca0417','8520c079-2457-446d-be7d-7d0a4528bad0',1930,'在伪满洲国兴安南省警备军任职','在伪满洲国兴安南省警备军任职，参与东蒙古地区治安与军事行动，活动范围包括通辽周边蒙旗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-965b1edd4b054f45a99d7daa74037cda','5eb76610-5984-41bd-a2f5-e509f3be3510',1933,'锡林郭勒盟苏尼特右旗札萨克','锡林郭勒盟苏尼特右旗札萨克，投靠日本，主导伪蒙古军政府及伪蒙疆政权，虽主要活动于察哈尔、锡林郭勒一带，但其伪蒙政权名义上覆盖内蒙古东部，与通辽地区有政治关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ed4e4a44f1f47ceae82558036b27d51','5eb76610-5984-41bd-a2f5-e509f3be3510',1933,'在锡林郭勒盟及察哈尔、绥远一带组织伪蒙政权','在锡林郭勒盟及察哈尔、绥远一带组织伪蒙政权，投靠日本关东军，建立伪蒙古军政府并任主席，后任伪蒙疆联合自治政府主席，配合日军统治内蒙古中东部地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71d31432ace64e3d880db3a311e201da','5eb76610-5984-41bd-a2f5-e509f3be3510',1933,'在察绥地区建立伪政权','在察绥地区建立伪政权，其势力与晋陕绥边区接壤，配合日军对榆林、府谷方向进行政治渗透和军事袭扰。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ecd2ad3d97a40338e2562a106810258','aca9da1b-66d6-495b-ba94-bc7bab39a549',1932,'科尔沁左翼中旗人','科尔沁左翼中旗人，蒙古族。九一八事变后投靠日本关东军，参与组建伪兴安军，任伪兴安南省省长，协助日军镇压蒙古族抗日武装，推行奴化教育，强征劳工，为日军提供物资和情报。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a99b6ab669354304b7466e7831d9465b','6e716e29-5405-41ee-bbc7-fe53ee819ab5',1932,'科尔沁左翼中旗人','科尔沁左翼中旗人，甘珠尔扎布之弟。长期在伪兴安军任职，参与指挥伪军围剿抗日游击队，配合日军“治安肃正”行动，残害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e12d625464da4d748b70bca08ace1973','37f51ff0-0f3b-40ab-a8fa-14bceea67a5a',1933,'科尔沁左翼后旗人','科尔沁左翼后旗人，蒙古族。投靠日军后任伪警备军司令，多次率伪军袭击抗日武装，协助日军建立“集团部落”，制造无人区，强征牧民从军。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89fce82a37c4469a9f9bc0ff318e518c','679b8e97-5dd3-46b3-9a4d-37c34fdf667c',1934,'科尔沁右翼前旗人','科尔沁右翼前旗人，蒙古族。任伪省长期间，推行日本殖民政策，强征土地，组织伪警察镇压反抗，为日军提供粮食和牲畜。','危害等级A（甲级，省部级/大军区级要员）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d7adc33506b49f38b6e532fc47a030a','e8e3389d-9a52-45c3-90f4-5991e8c40bc0',1935,'科尔沁左翼中旗人。在通辽地区协助日军建立保甲制度','科尔沁左翼中旗人。在通辽地区协助日军建立保甲制度，强征劳工修建军用公路和机场，参与“清乡”行动，逮捕抗日地下工作者。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c662124893b84c328044532879f8ef4b','63c49feb-a508-47c2-b40c-b1a6d66099eb',1936,'科尔沁左翼后旗人。主持伪警务','科尔沁左翼后旗人。主持伪警务，组织特务网，破坏抗日地下组织，多次率警察队围剿抗日游击队，刑讯逼供抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02df22fe34f34c0bbaf9b255f5008559','49681591-0060-4c83-97d9-f0385ad9bae3',1937,'在旗内强制推行“出荷粮”制度','在旗内强制推行“出荷粮”制度，搜刮民财，强征青年加入伪满军，协助日军镇压蒙古族民众的反抗运动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee1aa525a5004a3f97618396c7aef012','57d4eb99-22c9-4caf-bfdf-ec177b4edb90',1938,'积极执行日本“开拓团”移民政策','积极执行日本“开拓团”移民政策，强占牧民草场，组织伪旗公署武装配合日军“讨伐”，杀害抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6298901bb534af8bc440056cffaacd8','d5f815c2-fc20-41ac-a7ad-709580a3d965',1939,'科尔沁左翼中旗人。早期在伪军中任职','科尔沁左翼中旗人。早期在伪军中任职，参与镇压抗日活动，但后期于1945年8月率部反正，故仅列其投敌时期行为。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f8d8f4d36bf426d8669bac61be88807','4cf94e63-b682-4aca-9ac3-21ac08c74e00',1940,'在通辽县城及周边为日军充当鹰犬','在通辽县城及周边为日军充当鹰犬，搜捕抗日分子，参与“三光”政策下的扫荡行动，抢劫百姓财物。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44483afdf8c749429cda10b4ccdd0d25','53824f56-f275-42d7-b044-963e3ea39de9',1931,'蒙古族上层亲日派','蒙古族上层亲日派，参与策划‘内蒙古独立’活动，任伪满兴安南省警备军司令，率伪军配合日军在通辽、科尔沁左翼中旗一带围剿抗日武装，后任伪兴安局总裁，推行日本殖民统治政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b44eefb00354c5f8f7dcf76afdbc9f4','53824f56-f275-42d7-b044-963e3ea39de9',1931,'蒙古族上层亲日派','蒙古族上层亲日派，参与策划‘内蒙古独立’活动，投靠日本关东军，在伪满洲国任职，统辖包括科尔沁左翼后旗在内的东蒙古地区伪军警，配合日军镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f286d85d15a4391a9dec310b6c01110','ea78f452-e692-4e98-92ce-ce6c3a3e575b',1931,'甘珠尔扎布之弟','甘珠尔扎布之弟，长期在伪兴安南省警备军任职，参与指挥伪军在通辽、科尔沁左翼中旗地区镇压抗日力量，后任伪第十军管区司令，协助日军维持对东蒙古地区的控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68ce1dae06334fda8761ed394c80d5c8','ea78f452-e692-4e98-92ce-ce6c3a3e575b',1931,'甘珠尔扎布之弟','甘珠尔扎布之弟，长期在伪兴安南省及通辽一带任职，指挥伪军配合日军‘讨伐’抗日武装，控制科尔沁左翼后旗等地的治安。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c73c86bd2d04b208babf9af2fcd0f14','98c309a1-557e-4e3f-b084-c070319623bc',1932,'原哲里木盟科尔沁左翼中旗札萨克亲王','原哲里木盟科尔沁左翼中旗札萨克亲王，投靠日本后任伪兴安南省省长，在通辽、科尔沁左翼中旗等地推行保甲制、征集劳工和物资，支持日军‘治安肃正’。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-881bae071f5d422ba86b7d5da1342314','98c309a1-557e-4e3f-b084-c070319623bc',1932,'原哲里木盟科尔沁左翼后旗札萨克郡王','原哲里木盟科尔沁左翼后旗札萨克郡王，投靠日本，出任伪兴安南省省长等职，协助日本在通辽及科尔沁左翼后旗推行殖民统治、征发劳工和物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b3c8f65e42447b69dc1bd7e2d3b7857','7c8b7b3a-bf44-4241-9bc1-bd7eee7b6802',1932,'在科尔沁左翼中旗任职期间','在科尔沁左翼中旗任职期间，组织伪自卫团配合日军扫荡，强征粮食和牲畜，镇压当地抗日群众，是通辽地区较有影响的附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dffa6fa5884d48d39a9ccf5d721e4db0','dd65250f-947e-48fd-a2ec-7b2e08267672',1932,'原科尔沁左翼中旗蒙古族武装头目','原科尔沁左翼中旗蒙古族武装头目，投日后任伪兴安南省警备军统领，率部在通辽、科尔沁左翼中旗一带配合日军作战，后任伪哲里木盟盟长，推行殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41229aeb03e34e169d008b1c3f563a5d','6c3b0d20-05c0-4964-a51e-ea7357542524',1936,'锡林郭勒盟苏尼特右旗札萨克亲王','锡林郭勒盟苏尼特右旗札萨克亲王，在日本支持下成立伪蒙疆政权，其势力范围覆盖内蒙古东部，包括通辽、科尔沁左翼中旗地区，推行亲日殖民政策，协助日军征调物资和兵员。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f400a58d802844c69ab7a4d05ef0031c','4e02f427-2041-43b1-8cd5-d0a1501ebd67',1932,'在通辽县任职期间','在通辽县任职期间，推行保甲连坐制度，强征劳工和粮食，配合日军‘治安肃正’，镇压当地抗日活动，是通辽地区伪政权核心人物之一。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b1d34d9476847b4867b8ee33a30a855','5c78d9f3-7053-4271-922f-e69578968508',1931,'原东北军将领','原东北军将领，九一八后投敌，任伪洮辽镇守使，其防区包括通辽、科尔沁左翼中旗一带，率伪军配合日军进攻抗日武装，后任伪热河省省长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f409072b4a743439b4774185ab04405','5c78d9f3-7053-4271-922f-e69578968508',1931,'辽宁盖平人','辽宁盖平人，原东北军将领，九一八事变后投敌，任伪洮辽镇守使，率部进攻锦州、热河等地，配合日军作战。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-252077de32814ce387ffdcc0d5cbe9a3','5c78d9f3-7053-4271-922f-e69578968508',1931,'原东北军将领','原东北军将领，九一八后投敌，率伪军进攻黑龙江，参与围剿马占山等抗日部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-febed991ea9a4598a415e1449749a797','d0c9d9f2-8a17-471d-b3bf-e36c51eb141a',1931,'原东北军东边道镇守使','原东北军东边道镇守使，投日后任伪奉天省警备司令，其部队在通辽、科尔沁左翼中旗地区参与围剿抗日义勇军，后任伪第一军管区司令。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0226770d2ef140aead135d32a293c76a','04fd0823-ff9f-4d49-9683-be33e13ea33c',1932,'在伪兴安南省警备军任职期间','在伪兴安南省警备军任职期间，参与制定对通辽、科尔沁左翼中旗地区抗日武装的作战计划，协助日军维持殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6603d567d3fe45b1b5d36338e91bf985','e3da678c-7a46-4706-9220-bd3aaca973ac',1935,'在科尔沁左翼中旗组织伪自卫团','在科尔沁左翼中旗组织伪自卫团，配合日军征粮、抓劳工，镇压当地抗日群众，是旗内较活跃的附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb5da939a77c4e299d13b5672c72b122','7133087c-c02b-4070-958a-63636ae6b0de',1932,'任伪科尔沁左翼中旗旗长期间','任伪科尔沁左翼中旗旗长期间，推行日本殖民教育，强征物资，组织伪警察维持治安，协助日军镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85f759a6e19e4600b58883546e4df135','e1d4062e-61c9-4a5c-aa77-2114f93b23ba',1931,'九一八后组织通辽县维持会','九一八后组织通辽县维持会，迎接日军进城，协助日军建立伪政权，后任伪通辽县参事。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62fb837629764ba5b6d82f3bfc80c52d','74fa1ca4-8c2c-410c-8688-dbd8bc50ce61',1932,'在科尔沁左翼后旗及通辽地区任职','在科尔沁左翼后旗及通辽地区任职，组织伪旗政权和伪警察队，配合日军维持‘治安’，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-50781ef661004d608aa70ffd6bd95294','f60852ec-ad72-41c8-9bc9-e410ea1f1bcc',1933,'在科尔沁左翼后旗充任伪旗长','在科尔沁左翼后旗充任伪旗长，推行保甲连坐，协助日军征粮、征兵，控制当地民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c76909b13bf94a4abd2e57a641aae86a','209cc4e5-fcb1-4b4d-a5ce-0e350337cb61',1935,'掌管科尔沁左翼后旗伪警察武装','掌管科尔沁左翼后旗伪警察武装，多次配合日军和伪兴安南省警备军搜捕抗日人员，迫害当地百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ffe4b07b1b043d78549931cae29fca8','33fd34ef-36d5-41d0-8d54-2d74e30b86f6',1937,'率伪军活动于内蒙古西部及通辽一带','率伪军活动于内蒙古西部及通辽一带，配合日军扫荡抗日武装，在科尔沁左翼后旗附近参与‘治安肃正’。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e652e7d07b2447b9962979f3ce05c40','aeca17fc-44ee-47d0-9baa-658413291e0e',1932,'在科尔沁左翼后旗组织伪保安队','在科尔沁左翼后旗组织伪保安队，协助日军维持地方秩序，镇压抗日群众，征发民夫和物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-804f499bb66d4528acd15354cfb469bd','1c167379-b3fe-4c25-b59c-a5708d5bc6e9',1934,'在科尔沁左翼后旗伪旗公署任职','在科尔沁左翼后旗伪旗公署任职，推行日本殖民教育、经济统制政策，协助日军掠夺当地资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc1e1e99dc134e8caae392983b3ba5e8','2a657665-f28a-4a94-bf36-303b49f7796e',1936,'在科尔沁左翼后旗基层推行保甲制度','在科尔沁左翼后旗基层推行保甲制度，监视民众，向日军举报抗日人员，配合伪警察抓捕抗日群众。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0add47a07414dc2a9b467038d1f95eb','733f7987-f33e-450a-87ea-dff4c151be4f',1936,'参与伪蒙古军组建','参与伪蒙古军组建，在通辽及哲里木盟地区协助日军清剿抗日武装，强征民夫，为日军提供情报和后勤支持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ecd578846ab457c9d944f8ab35547de','145616c6-31ff-4ba9-97dc-d418ad51be3b',1937,'在通辽、开鲁等地率伪军配合日军“扫荡”','在通辽、开鲁等地率伪军配合日军“扫荡”，屠杀抗日军民，抢夺牲畜粮食，破坏抗日根据地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26f60afc205e4b1595d6a344c609cb37','db749997-cafe-4252-adef-23cd031ebb7b',1932,'在通辽所属的兴安西省（今通辽部分地区）任伪职','在通辽所属的兴安西省（今通辽部分地区）任伪职，推行伪满洲国殖民政策，强征土地，组织伪警察镇压反抗。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b3acc13fc3741938347ac813d94341a','f6ba9db3-7abf-4236-bcf4-fb4b62f6c1c0',1932,'任伪通辽县县长期间','任伪通辽县县长期间，为日军征收粮饷，抓捕抗日志士，协助日军建立保甲制度，实施“连坐”统治。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-337e130971e34b9b9d52a57bed3cc8da','f6ba9db3-7abf-4236-bcf4-fb4b62f6c1c0',1932,'在通辽县任伪县长期间','在通辽县任伪县长期间，推行日伪殖民政策，强征劳工，搜刮民财，协助日军维持治安，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc5503ec65784956a4e882d547292881','f777422c-830c-4ea3-9460-b55673950e80',1933,'指挥伪警察在通辽城区及周边搜捕地下抗日人员','指挥伪警察在通辽城区及周边搜捕地下抗日人员，刑讯逼供，多次参与日军“讨伐”行动。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61f5ede8736d433a9b64014f151bfd10','43c172b2-364a-43ef-9c47-d9d4613be82a',1935,'在通辽、科尔沁左翼后旗等地驻防','在通辽、科尔沁左翼后旗等地驻防，参与日军“治安肃正”，围剿抗日游击队，残害蒙汉民众。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ff70b70bd944ada9f9ad7338317146e','36cf8ac4-6488-4b9c-aec8-a64a909e317c',1932,'在通辽地区推行伪满警察制度','在通辽地区推行伪满警察制度，组织特务网络，破坏抗日组织，协助日军强征劳工。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f513efafb3b84d9da56dcad698e2fd32','82dd597c-fbd2-4854-a44a-ff4eb8b6e831',1931,'曾为匪首','曾为匪首，其子甘珠尔扎布等继承其投日路线，巴布扎布本人早年即与日本勾结，在内蒙古东部地区活动，为日军提供情报和武装支持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69d4444137ec4bccb411267c86b4e1a2','99831c5d-8ffb-4cef-a4cd-43c07c8d6b40',1933,'原奉系军阀','原奉系军阀，后投敌，在热河及通辽周边地区担任伪职，配合日军进攻抗日武装，参与“治安肃正”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e934068d44d4914bae491243de743ce','406ce443-6ace-4b7e-82eb-956ff50d5299',1934,'蒙古族投日分子','蒙古族投日分子，在兴安西省（含今霍林郭勒附近区域）推行日伪统治，组织伪警察和保甲制度，迫害抗日群众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d1fa065123e421b80d573002a0ec9d2','a47509d6-2eea-4c7d-9818-5e4c4fe740b6',1932,'在通辽、哲里木盟一带负责伪警务','在通辽、哲里木盟一带负责伪警务，协助日军搜捕抗日志士，参与“讨伐”活动，残害当地百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61f9e9402a3644df84a21f56f5e2e073','81877db6-1ccd-49e7-8643-a0f5a9abaed9',1936,'在鄂尔多斯地区为日军搜集情报','在鄂尔多斯地区为日军搜集情报，协助伪政权征粮派款，破坏当地抗日地下组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb28ebf9f50d4a80b8f9ee4d65b230b5','f5d4a7f7-5a41-4035-ad7d-31db934c86cc',1938,'在日军扶植下担任伪伊克昭盟盟长','在日军扶植下担任伪伊克昭盟盟长，强迫各旗王公向日军效忠，组织伪警察镇压反抗民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd3ba5090a5a443a9c342d4447a45cc5','83207ba1-6e6f-496e-94da-e7700d898be5',1939,'协助日军在鄂尔多斯建立伪保安队','协助日军在鄂尔多斯建立伪保安队，参与抓捕抗日志士，为日军提供劳役和粮食。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-845842703d7240c0a8c0006dc63cc685','b440f3f9-b66b-4fdf-88f0-959bfe47c04e',1937,'投靠日军','投靠日军，在达拉特旗推行“保甲制度”，强征壮丁补充伪军，并配合日军对黄河以南地区进行经济封锁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-149fc5dfd8ad46f3b2f1a3eb077e7b68','9cee2bdc-ec43-438d-800d-181f8a665562',1938,'在杭锦旗为日军征收牲畜和皮毛','在杭锦旗为日军征收牲畜和皮毛，参与围剿中共领导的桃力民抗日游击队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ff2784d36cb4dc5aa8560107b4262bb','e3c74873-46f6-4172-978a-779bcd541e9f',1939,'在乌审旗残酷镇压牧民抗日活动','在乌审旗残酷镇压牧民抗日活动，多次袭击八路军骑兵支队，杀害多名革命干部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c2b6a3412f74d58942794d837077f5f','1407bccd-881a-4664-a6e0-bd59ac7f1ebd',1940,'依附日军','依附日军，在鄂托克旗设立伪警察所，禁止牧民与抗日武装接触，并参与日军“清边”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-918e8d56616c4a5a90ac55b7fb486f5b','f6e9a6d7-9189-4b90-a9ef-24c5fbc9b55a',1937,'为准格尔旗日军据点提供情报','为准格尔旗日军据点提供情报，协助伪军强征民夫修筑工事，迫害倾向抗日的蒙古族青年。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6d929c2c6b64be8945ceecb2a7dff7d','7a45dc1e-6f2c-4eaf-a6de-f12c18df504a',1938,'公开投日','公开投日，在郡王旗悬挂日本旗，强迫旗民向日军献马献粮，并阻挠成吉思汗陵西迁中的抗日宣传。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9501b5a3393e48c6b3772791556573d2','dce0b3b0-a6a3-4701-8697-8a4d7966ae7e',1941,'率伪保安队配合日军“扫荡”札萨克旗南部','率伪保安队配合日军“扫荡”札萨克旗南部，抓捕并杀害抗日地下交通员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1cb1e93774994132ae22e5909dbe8951','718cb530-b7d3-4cb1-a778-609efd8adbc6',1937,'在日军威逼下曾出任伪盟长','在日军威逼下曾出任伪盟长，默许日军在鄂尔多斯设立特务机关，后因国民党争取而动摇，但前期行为已构成附逆。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-629ffe1a275b4b17a062d0e9bdba6756','4ef44b8a-c543-432f-8b29-881dba23e62f',1938,'蒙古族贵族','蒙古族贵族，投靠日本后任伪伊克昭盟盟长，在鄂尔多斯地区推行日伪统治，强迫牧民缴粮纳税，协助日军清剿抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bed3ec0eb1c04a11a64aea526bae9a8f','2e8f8b64-de94-4f18-8029-6a2558f9c8d4',1939,'在鄂尔多斯地区组织伪蒙古军','在鄂尔多斯地区组织伪蒙古军，配合日军扫荡东胜周边，残害抗日军民，强征民夫修筑工事。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbcc330c1bb5459e97fc036d6da38b07','5bcf2afe-4721-4e08-932d-3fe4b5e5e565',1940,'在东胜及伊金霍洛旗一带为日军搜集情报','在东胜及伊金霍洛旗一带为日军搜集情报，抓捕抗日地下人员，参与镇压当地反抗活动。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1e145d84dd54fe4a10cd7085b251c81','4e9b58d2-a3d0-43f9-b6e0-7cf80ffbfca8',1941,'任伪东胜县知事期间','任伪东胜县知事期间，推行日伪保甲制度，强征粮食，组织汉奸武装，协助日军控制东胜城区及周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b8def1a69fe4916ab7bad0fa234f75c','1e3e0191-20fe-4d2c-88cf-4eaeac37b959',1942,'在东胜地区为日军效力','在东胜地区为日军效力，搜捕抗日分子，迫害百姓，参与日伪“治安强化”行动。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d004e2868d8543d5bcafad30be05e668','a93cf332-404a-4642-ba13-f2f401dcd317',1940,'参与策划对东胜地区抗日游击队的围剿','参与策划对东胜地区抗日游击队的围剿，协助日军建立情报网，破坏抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0308da21d339423d80c9f2034917953a','93b5eb79-d609-492a-8e85-fb5f2e50a502',1937,'投靠日军及伪蒙疆政权','投靠日军及伪蒙疆政权，任乌审旗保安团团长，协助日军镇压抗日力量，参与“伊盟事变”中镇压蒙古族人民的反抗，迫害进步人士，强征民夫为日军服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00d90b3109ee43afa06c5543ec7cf324','22c7ac99-9ba3-464f-aae5-bdbe9e851345',1938,'与日军及伪蒙疆政府勾结','与日军及伪蒙疆政府勾结，在乌审旗推行伪蒙疆政策，协助日军征收粮草、马匹，破坏抗日活动，参与围剿中共领导的抗日游击队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3564152ab68b485fb294e315f92b7758','4b9d08f5-70f7-41f5-ac8c-8261ed6270c7',1940,'率保安队投靠伪蒙疆军','率保安队投靠伪蒙疆军，多次配合日军“扫荡”乌审旗南部抗日根据地，杀害抗日军民，抢劫财物，并强迫牧民迁徙至日军控制区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d20b3f907e1463a81df7441ea1bff4c','48ac87d2-934f-4ab1-b54c-ad489a7b6dfe',1941,'效忠伪蒙疆政权','效忠伪蒙疆政权，在乌审旗建立伪警察体系，搜捕抗日地下工作者，向日军提供情报，参与镇压“独贵龙”运动余部。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c0554a8baf64d7f8339a17b0911a61c','71895f78-c542-458a-a3ad-681a9ba740ea',1939,'为日军及伪蒙疆政府担任翻译','为日军及伪蒙疆政府担任翻译，刺探中共伊克昭盟工委及陕北根据地的军事动向，多次引导日军袭击乌审旗边境的抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6cf60a2cfda84dbd9b26c3534cafe656','d2af0302-d501-4042-aca1-6a18d45a0611',1938,'在日军扶植下出任伪伊克昭盟公署盟长','在日军扶植下出任伪伊克昭盟公署盟长，协助日伪在鄂尔多斯地区推行保甲、征粮、征兵，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8dab170ccd2141ca8edcd8819d9bd7b0','7d47f694-d005-4cf0-bf08-c2bc48f620d2',1938,'投靠日伪','投靠日伪，在伊克昭盟地区协助伪政权统治，参与诱降蒙古王公与地方武装，配合日军对鄂尔多斯的渗透。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
