INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49196d543b0a473f9ef63b56b8c4ec68','5c8ea168-281d-4c60-8c60-78cc598bdd3d',1938,'在东胜地区组织维持会','在东胜地区组织维持会，为日军征集粮草、情报，协助伪政权建立保甲制度，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-424afd240133435fb890201a02f6c412','766d471a-be7b-41e3-a0e9-fc48f3c0eae1',1937,'在包头及绥西地区为日伪政权服务','在包头及绥西地区为日伪政权服务，参与经济掠夺与物资统制，其管辖范围与鄂尔多斯北部相邻并产生影响。','危害等级B（乙级，市县厅局级）','hanjian');
