INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad418ecbc2204fb7abdad33477ef6cfe','a1476d6c-25b5-4c40-bc92-d144d630f91c',1937,'在伪蒙疆政权中负责行政与宣传','在伪蒙疆政权中负责行政与宣传，参与对伊克昭盟等地的诱降与统治，推行奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
