INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdf806e777da4ff8b318e7488dd94903','fae23642-3965-42b0-85ca-e16e7df580ea',1936,'协助李守信统率伪蒙古军','协助李守信统率伪蒙古军，参与在绥远及鄂尔多斯周边的军事行动，配合日军扫荡抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
