INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c16cfe238f664e66805a0c8d20903786','b30ade68-e03d-44ca-950f-ea4e2497c270',1942,'在准格尔旗一带为日军招募伪军','在准格尔旗一带为日军招募伪军，率部配合日军进攻抗日根据地，残害当地蒙汉百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
