INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3596d46a6859431796b075c575046bad','2fc29d82-5e6a-4569-8443-07c4f7bc7cf9',1937,'在包头地区组织维持会','在包头地区组织维持会，包头为鄂尔多斯北部重要门户，其活动直接影响鄂尔多斯地区，为日军征粮征款，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a95968d977154cfcaf64a65bfbf256d4','90a12d96-dde2-4d52-a55c-94ef7010fc2a',1937,'在萨拉齐（今包头市土默特右旗）组织维持会','在萨拉齐（今包头市土默特右旗）组织维持会，该地区与鄂尔多斯隔黄河相望，为日军进攻鄂尔多斯提供后勤支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-908201b57c5b40898377c24b4c0a17d1','be8d48f1-4b37-4626-8204-1e91ad992075',1938,'在东胜县（今鄂尔多斯市东胜区）组织维持会','在东胜县（今鄂尔多斯市东胜区）组织维持会，为日军征粮征夫，协助日军控制鄂尔多斯中部地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-201ea41dd673434e877bdaa43aaa1493','2e6705c2-a215-433c-aa1d-cbee4f1a2803',1938,'在日军侵占杭锦旗部分地区后出面组织维持会','在日军侵占杭锦旗部分地区后出面组织维持会，为日军征粮派款、搜集情报，协助伪政权控制当地基层。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab0cab9a532a4d91b592faadab0a2b45','f083a07f-2eef-427f-a406-56956554c732',1938,'在鄂尔多斯东部准格尔旗一带依附日军和伪蒙疆政权','在鄂尔多斯东部准格尔旗一带依附日军和伪蒙疆政权，率地方武装配合日伪行动，压制抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-311a799492d74273aa844059ccb8bc2d','2f785f12-f48c-40ed-94d4-13fb07956cc4',1939,'在鄂尔多斯乌审旗地区组织维持会','在鄂尔多斯乌审旗地区组织维持会，为日军和伪蒙疆政权服务，协助征发物资、维持治安，破坏抗日统一战线。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3da445aef8d45b6b11679b78b6a405e','87dbf5f6-beb7-4456-9adf-f2b8744da284',1939,'在伪蒙疆政权中负责伊克昭盟事务','在伪蒙疆政权中负责伊克昭盟事务，活动范围涉及鄂尔多斯各旗，包括杭锦旗周边，推行日伪统治政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a31808fa1b524a989b94cad4b20c0b92','344cba2b-87f2-4668-8a3e-94ef5a4c36c8',1940,'率杭锦旗地方武装投靠日伪','率杭锦旗地方武装投靠日伪，配合伪蒙疆政权维持当地统治，镇压抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9cae66442511422389a6a1e34124e723','e260fdd6-c847-4cdc-bcb7-e8fc54f23591',1939,'在鄂尔多斯鄂托克旗一带为日伪政权服务','在鄂尔多斯鄂托克旗一带为日伪政权服务，协助控制基层、征派粮草，支持日军对周边地区的扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b77cbe4cb9dc4e409de89e695dca3aa4','9de46fe4-fb9d-47f3-bc8f-9b1e25c6bfe2',1937,'在伪绥远省政权中任职','在伪绥远省政权中任职，参与对鄂尔多斯及杭锦旗等地的行政控制，推行日伪法令，协助经济掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9107824dfe0743928d40ba3ab10c75a8','97399ab0-a4e2-48cc-86d8-58e330127cf6',1937,'投靠日军','投靠日军，任伪伊克昭盟达拉特旗保安司令，协助日军镇压抗日力量，强征民夫修建军事设施。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f03a73f669742e78068d8244655cef3','6d1960b4-a625-435c-ab45-f54f920b397a',1938,'投靠日伪','投靠日伪，任伪达拉特旗西协理，配合日军“扫荡”抗日根据地，向日军提供情报并征收粮草。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2c5b1ba4ca54150bca1886a3a7ed331','5079c44e-32a8-4795-94a3-057ce40fad1c',1939,'充当日军傀儡','充当日军傀儡，参与组织伪旗公署，协助日军推行“治安强化运动”，迫害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3dde5ab0c614f8da3e77f1965aca792','d9c85c5d-49c3-44d0-990d-b3cbede3ef57',1940,'为日军效力','为日军效力，参与围剿八路军游击队，抓捕并杀害抗日群众，充当日军翻译和密探。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7db23c4f027546139ea5b6008e4f3081','901ff52c-746b-4c49-87ce-ef7865b70331',1941,'效忠日伪政权','效忠日伪政权，指挥伪警察镇压抗日活动，强征壮丁，勒索百姓，协助日军掠夺当地资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c455b580dd34837a8bddd1d88af5559','31a78a1a-7933-4b30-b04c-896f005eb93a',1933,'在日军扶植下于内蒙古中西部建立伪蒙疆政权','在日军扶植下于内蒙古中西部建立伪蒙疆政权，统辖察哈尔、绥远等地，推行亲日政策，配合日军对绥蒙地区进行统治和掠夺，其势力范围覆盖鄂尔多斯北部及邻近地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0b7ced221cc4da4a01ba124d5c0ccf2','35844ce1-615e-4731-9682-7fb4af93a577',1937,'在伪蒙疆政权中担任司法和行政要职','在伪蒙疆政权中担任司法和行政要职，为日军统治内蒙古中西部提供法律和行政支持，其管辖区域与鄂尔多斯地区有交集。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e29879d06a644763b598b7090b24a743','b2b224c6-f737-4847-8921-db7f6b3dbdbd',1937,'作为鄂托克旗蒙古王公','作为鄂托克旗蒙古王公，投靠日军和伪蒙疆政权，在鄂托克旗及邻近地区协助日伪推行统治，维持地方治安，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd454c2042cd4abbb5bf6ea4d4e5666f','daaa7884-a17d-465a-aa91-813cc9da60f5',1937,'准格尔旗蒙古族上层','准格尔旗蒙古族上层，投靠日伪，组织伪保安队，在准格尔旗及鄂尔多斯东部地区配合日军行动，对抗抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2087c3aafd8f4ae6b9b06608ae105b09','18680bdc-fe66-49b6-8008-a61037cd7153',1937,'准格尔旗蒙古族上层','准格尔旗蒙古族上层，与奇子祥一同投靠日伪，在准格尔旗及周边地区协助日伪统治，参与镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5247ce37d34440659f4e79d03762ccfb','87ea995a-700a-4694-8eac-cd1413081b9a',1937,'乌审旗蒙古王公','乌审旗蒙古王公，投靠日伪，在乌审旗及鄂尔多斯西南部地区协助日军统治，维持伪政权地方秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69bede5a631a4fb3bb37f304ac0488fd','f3052d7f-c55a-4a7f-90d1-7f339ea05c21',1937,'杭锦旗蒙古王公','杭锦旗蒙古王公，投靠日伪，在杭锦旗及鄂尔多斯北部地区协助日伪统治，配合日军对地方的控制和资源掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e96b1565ec2745aab3903bfbd42345fb','2722cee3-53a7-436a-b1e0-bf02f7188b6c',1937,'在包头地区投靠日伪','在包头地区投靠日伪，担任伪职，协助日军在绥西及鄂尔多斯北部进行统治和经济掠夺。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7924d7a76c01402aac163c43f9439350','1016bfb5-8c70-4488-b7ca-6beae9029bb8',1937,'在萨拉齐（今土默特右旗）地区投靠日伪','在萨拉齐（今土默特右旗）地区投靠日伪，担任伪县长，协助日军在绥西及鄂尔多斯北部推行保甲制度和掠夺资源。','危害等级C（丙级，基层头目）','hanjian');
