INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc0fa31c7d5d4ed0b0ed7a23378b3310','0ed01f59-9563-40d2-8c26-36b86e09208d',1937,'在东胜地区担任伪县长','在东胜地区担任伪县长，协助日军在鄂尔多斯中部地区进行统治，推行保甲制度，掠夺地方资源。','危害等级C（丙级，基层头目）','hanjian');
