INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18129248ec91402fb3c8be11fa174e45','0b6b585b-0660-4d2e-b800-0556015b0647',1937,'在达拉特旗地区投靠日伪','在达拉特旗地区投靠日伪，组织伪保安队，配合日军在鄂尔多斯北部进行统治和扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-232836f3bca847679b34c19ebbe10f96','103ddc80-4351-4d2b-b61f-599f2f1fd397',1937,'在达拉特旗地区组织维持会','在达拉特旗地区组织维持会，投靠日军，协助日伪在鄂尔多斯北部推行统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5315ad528c5346c1898b6173473cae99','0f58a057-338c-4b4c-a749-42ed04b78a99',1937,'在郡王旗（今伊金霍洛旗）地区投靠日伪','在郡王旗（今伊金霍洛旗）地区投靠日伪，组织伪保安队，配合日军在鄂尔多斯中部地区进行统治和扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3985cf420a0c4495a980db87f7a8bce8','dcca2983-f675-4ce9-bde3-596d2d44e00a',1938,'投靠日军后','投靠日军后，在鄂托克旗及周边地区为日军搜集情报，协助日军镇压抗日力量，并参与日伪军对当地牧民的掠夺和迫害。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bbfb1166c64c4041bc66b8226cc7db83','1c3d2aaf-cc7b-4c33-bd80-aec26fd87527',1937,'原为地方武装首领','原为地方武装首领，1938年后暗中与日军勾结，向日军提供军需物资和情报，并阻挠抗日武装在鄂托克旗的活动，1943年被抗日力量处决。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9d16b9716f7424aba7032dcfdc2e6a2','6eb5cf33-825a-455f-9b13-0152c1e1f981',1940,'在日军扶植下建立伪警察机构','在日军扶植下建立伪警察机构，负责搜捕抗日分子，强征民夫为日军修筑工事，并参与对当地民众的敲诈勒索。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33c104242cfd4a5ca21659f33272b62d','02a09b0f-c4f0-4347-a9c2-aa44d4d09649',1941,'在日本顾问控制下出任伪旗长','在日本顾问控制下出任伪旗长，推行日伪“蒙疆”政策，强制收缴民间枪支，强迫牧民“捐献”牲畜支持日军，并协助日军镇压反日牧民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee2830f92c784736aa991ee9092d5535','85b70f1d-306e-4a27-8839-553496dd9139',1939,'组织维持会为日军提供粮草和向导','组织维持会为日军提供粮草和向导，配合日军“扫荡”抗日游击队，并参与诱捕抗日地下工作人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7ca0b8643784210896676f9759153f9','4687a025-07db-4b7b-a625-da45c52d1cb6',1931,'参与策划内蒙古东部独立活动','参与策划内蒙古东部独立活动，投靠日本关东军，在伪蒙政权和伪兴安军中任职，协助日军控制内蒙古东部及锡林郭勒盟周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
