INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7567ca65714d482091099895ef03ab7d','1d4ee84d-034a-4c77-8222-b1e043537094',1936,'锡林郭勒盟苏尼特右旗人','锡林郭勒盟苏尼特右旗人，德穆楚克栋鲁普的亲信。1936年参与筹建伪蒙古军政府，任办公厅主任，后任伪蒙疆联合自治政府参议等职，协助德王推行伪政权的行政与联络事务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-daf2dc10347c4c72b9b51bf51f44422c','94b7e902-5227-4a3c-a688-b173adb6b29a',1936,'锡林郭勒盟人','锡林郭勒盟人，德王亲信之一。在伪蒙疆政权中负责治安、警察事务，参与镇压抗日活动，强征民夫、物资支持日军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
