INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e13765cb120499484f07cdc13cc2f80','6f460e10-2058-45ab-8231-54cc78981601',1937,'在伪蒙疆政权中任锡林郭勒盟公署盟长','在伪蒙疆政权中任锡林郭勒盟公署盟长，直接管辖苏尼特右旗等旗县，推行保甲制、征粮征畜，配合日军维持地方治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
