INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2da64da5e38947989389669b379b05cc','c91e3c28-90d9-42af-bab3-ac67c60c0e73',1930,'在日伪势力拉拢下','在日伪势力拉拢下，曾向伪蒙疆政权提供阿拉善旗军事布防信息，并协助日伪人员偷运武器进入旗境。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4018e43a9c86411cadac1348f600d6ce','4b9fe479-b63b-49ec-969a-7a96207cf867',1937,'1937年北平沦陷后出任伪中华民国临时政府行政委员会委员长','1937年北平沦陷后出任伪中华民国临时政府行政委员会委员长，后任伪华北政务委员会委员长，积极推行日本殖民统治，镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac7815227d2d4280af89d9d33ece3bd4','4b9fe479-b63b-49ec-969a-7a96207cf867',1937,'虽主要活动于华北','虽主要活动于华北，但曾参与南京伪政权协调，长期为日军效力','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29866e28e7e04c2ba02abf579b8da560','4b9fe479-b63b-49ec-969a-7a96207cf867',1937,'原北洋政客','原北洋政客，1937年北平沦陷后出任伪中华民国临时政府行政委员会委员长，后任伪华北政务委员会委员长，管辖包括河北在内的华北地区，推行日伪统治政策，协助日军经济掠夺和治安强化运动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6efafb8ab87e4d638da46331293ce2c9','4b9fe479-b63b-49ec-969a-7a96207cf867',1937,'华北伪政权首脑','华北伪政权首脑，其统治范围覆盖秦皇岛、抚宁，支持日军“治安强化运动”，在抚宁等地增设伪军据点。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b63b553e4224907a08c793edcae4b35','4b9fe479-b63b-49ec-969a-7a96207cf867',1937,'华北伪政权最高头目之一','华北伪政权最高头目之一，其伪政权管辖包括河南北部，对河南沦陷区伪政权有统辖关系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d43af981d744b0aa1b546bdb990629d','4b9fe479-b63b-49ec-969a-7a96207cf867',1937,'虽为华北汉奸','虽为华北汉奸，但曾与浙江日伪势力勾结，在宁波设立商务机构，为日军服务。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e6b9f8905bd40e58b437ddbc1c113e1','4b9fe479-b63b-49ec-969a-7a96207cf867',1937,'原为北洋政客','原为北洋政客，投日后虽主要活动于华北，但与浙江宁波汉奸有联系，支持日伪在东南沿海的统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
