INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac2bcc339cbf499b871d5c68edf82f14','94a4780b-52c7-4258-abc1-7180a9a3a9c9',1938,'原国民党官员','原国民党官员，投日后任伪北平市长，管辖包括大兴在内的郊区，推行日伪法令，镇压抗日活动，组织“献铜献铁”等物资搜刮。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
