INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2add85d4b3de4c2ca0f5c51b9a608de0','94a4780b-52c7-4258-abc1-7180a9a3a9c9',1938,'原国民党官员投日','原国民党官员投日，任伪北平市长期间，在朝阳地区推行日伪经济统制，强征劳工。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f95a66d8c5c49448447274fe5b9120c','94a4780b-52c7-4258-abc1-7180a9a3a9c9',1938,'作为伪北平市长','作为伪北平市长，直接管辖石景山地区行政事务，配合日军征用土地、劳工，用于石景山制铁所（今首钢前身）的扩建和军事物资生产。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23219746014f4bd1914b20ed6110188a','f0e7dde7-2c6a-45d0-8119-73fc393e6860',1937,'七七事变后率先组织北平地方维持会','七七事变后率先组织北平地方维持会，迎接日军进城，协助维持治安，后因权力斗争失势，但前期对大兴地区伪政权建立有直接影响。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
