INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ee620c86f834d39b38f96c7d0b79dad','bf509a3c-fc72-478c-a199-ee8b709b43cf',1941,'率伪军配合日军“铁壁合围”','率伪军配合日军“铁壁合围”，在密云云蒙山区烧毁村庄数十个。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd702e8e5ca742c694ccd3b2745ab514','1d916eed-fc19-4681-ba47-53e4bcd2091d',1935,'1935年参与殷汝耕成立的伪冀东防共自治政府','1935年参与殷汝耕成立的伪冀东防共自治政府，驻防平谷、密云一带，协助日军维持治安，镇压抗日活动。1938年反正后投靠国民党，但此前已造成抗日力量损失。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e423b335f132402989436707874a9e65','1ce2ed92-6f7f-4af3-a058-960d574dea87',1935,'率部驻守平谷地区','率部驻守平谷地区，配合日军清剿抗日游击队，多次参与“扫荡”行动，抓捕并杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b359bf2b47164320a004f867f039ded0','67ad329c-bc1c-4e3b-92fc-22d45c7264b3',1935,'在平谷及周边地区执行日军命令','在平谷及周边地区执行日军命令，强征民夫修筑炮楼和公路，破坏抗日根据地交通线。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c74208166a243b18a1b039bb1c2f766','0d1b8d83-5a5e-4c09-b536-f2f7172f8ba8',1935,'虽非平谷本地人','虽非平谷本地人，但其建立的伪政权直接管辖平谷，推行“自治”卖国政策，为日军提供粮秣和劳役，是平谷地区汉奸体系的最高后台。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cc88ea401bb4a758668c12947c0fbef','0d1b8d83-5a5e-4c09-b536-f2f7172f8ba8',1935,'虽非顺义籍','虽非顺义籍，但其伪政权管辖顺义，推行奴化教育，强征粮税，配合日军控制顺义地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
