INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fc2c3c758b44683967f9df37f5907f7','1d625667-f89a-4509-b6a9-da7d9537c480',1937,'殷汝耕亲信','殷汝耕亲信，后任伪北平市长，在北平市区及延庆等郊县推行保甲制度，强征粮食物资，镇压抗日分子。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82ee995e32224b13b0dde147cb051d72','a135fdeb-2dad-4813-9d20-e7da047ea67a',1938,'原国民党官员','原国民党官员，投日后任伪北平市长，在延庆等辖区推行日伪法令，组织“献铜献铁”，协助日军强化治安。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed0a9dbbbac64bd1a65989f739a33b2a','4107ad58-e260-4d6c-a2c7-283b6b4e9a5b',1937,'在北平及延庆地区指挥伪警察','在北平及延庆地区指挥伪警察，搜捕抗日地下人员，破坏中共地下组织，参与“治安强化运动”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f26d7031e2144dd1997361e40a6c59ac','e03940b1-d216-427f-98f6-7e8341246d18',1937,'七七事变后率先投敌','七七事变后率先投敌，组织北平维持会，为日军提供粮食、劳力和情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa0acc62e0354c98abb84766fa4fd195','de97e848-ccb9-49af-b26b-0e1f806c4040',1937,'参与北平维持会','参与北平维持会，后主管伪教育，在延庆等县推行奴化教育，强制学习日语，篡改历史教材。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-101d02213e1243abb1f091fe345c7753','24de496a-0252-4e91-a190-3b90c1e32297',1943,'继任伪北平市长','继任伪北平市长，在延庆等地区继续推行日伪“粮食统制”，强征农民粮食，配合日军“扫荡”。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06d74d76c6fa44108e6a26815b3a975a','52f4d671-98a7-4bfe-9efc-45242e57385f',1938,'在北平及延庆地区控制矿山、土地资源','在北平及延庆地区控制矿山、土地资源，为日军开采铁矿石等战略物资，剥削当地劳工。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3df26e064d5d445698e7583b94b71917','065d3a42-0da3-4cdc-8e8f-acb3a2b44da7',1937,'参与北平伪政权司法系统','参与北平伪政权司法系统，在延庆等地设立伪法院，迫害抗日群众，判处抗日志士死刑或劳役。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14d20f7fbec84b87b064b9f2936920db','17d3ad92-b31c-47e6-95a1-70ec74a778b5',1937,'原北洋财政官僚','原北洋财政官僚，投日后任伪华北政务委员会委员长，在北平及延庆地区全面推行日伪统治，组织“新民会”进行奴化宣传。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08f4082dde3444448e24d190a92728bd','9673e4bb-13fd-4372-9406-0a43734d1b8a',1940,'在北平参与伪政权外交事务','在北平参与伪政权外交事务，协助日本与汪伪政权协调，在延庆等县推行“中日亲善”宣传。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2fd50d4d20f4ab89aad07acf57e9917','a1519904-c440-4c01-a76f-0ed923808fe6',1938,'虽主政山西','虽主政山西，但曾参与北平伪政权高层会议，其势力范围涉及延庆西部山区，协助日军封锁抗日根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0dff142e3e84d0aa25861b4a0b35441','b9244c62-4235-4bf6-92de-f9600099df61',1938,'在延庆县任伪县长期间','在延庆县任伪县长期间，强征民夫修筑炮楼和公路，组织伪自卫团，配合日军对南山（平北根据地）进行“蚕食”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a79c33af27fb442383eb54086e868054','311df05a-8fe1-468d-a4f8-da25ea5e3c87',1940,'在延庆推行“保甲连坐”制度','在延庆推行“保甲连坐”制度，搜捕八路军侦察员，向日军提供抗日武装活动情报，并强征粮食支援日军。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d709f8f576de4d71b4238ebded9265a4','d29b7499-52de-4948-8493-466eb8a90f5a',1943,'在延庆县实施“集家并村”','在延庆县实施“集家并村”，制造无人区，强迫村民迁入“人圈”，以切断八路军与群众联系，导致大量平民死亡。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d91b768be1f84e8ab703eb4f04327dab','00d9d929-75d5-48d6-af2f-6072066005e8',1939,'率伪保安队多次袭击延庆南山抗日游击队','率伪保安队多次袭击延庆南山抗日游击队，杀害抗日干部家属，参与日军“扫荡”时烧毁村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8906ec47be2f4f03aff78cc6acc81ba2','5ab9991f-7249-404e-af90-2aea337ccab2',1940,'在延庆县城及各乡镇设立警察分所','在延庆县城及各乡镇设立警察分所，抓捕中共地下党员，刑讯逼供，破坏平北地委在延庆的交通站。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4343d310b384117998c6e911d16f42b','6799b1c9-b892-408b-bd3d-10470aafa339',1938,'在延庆组织新民会分会','在延庆组织新民会分会，推行“中日满提携”宣传，强迫青年参加“青少年团”，为日军募集“国防献金”。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba1f0a7e28f545fb838d2abf1bc0cfce','9ad75318-b43d-4fd9-bcc2-1d32fb160d59',1941,'组织地方自卫团','组织地方自卫团，在延庆各要道设卡盘查，截获八路军物资，并配合日军对海坨山根据地进行封锁。','危害等级C（丙级，基层头目）','hanjian；traitors');
