INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3013562f966e4725b163a8a06ea8132a','2c182677-b884-4cb1-9ed6-c25708819f00',1931,'九一八事变后投靠日军','九一八事变后投靠日军，任伪吉林省长官，镇压抗日武装，协助日军建立伪满政权，在吉林地区推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a4a40ebafc14a4d9461c92d86bf6caf','6f10307c-1cf8-4e0f-a626-e5b1da79830d',1931,'原吉林省政府委员','原吉林省政府委员，1931年叛国投敌，迎接日军占领吉林，后任伪吉林省长，积极推行伪满政权各项政策，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52be2ac1ecc848b6aa4a9c45acec0c72','72cb3a96-13f7-4612-9b61-4b3933458d89',1931,'原东北军将领','原东北军将领，投日后任伪吉林警备军司令，多次率伪军“围剿”抗日游击队，在丰满一带参与清乡和屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
