INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e59582fd202e417c8d529f2b2e454c6a','e2662d01-b535-4e42-8b46-238d0b6b4097',1931,'原吉林警察头目','原吉林警察头目，投日后在吉林、四平建立伪警察体系，抓捕抗日地下工作者，参与“归屯并户”政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
