INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-981ff705d63e45e8b9a7ba6f6da4bee7','85ee49bb-38e2-4ad5-aedd-c90445407552',1932,'任伪吉林市市长期间','任伪吉林市市长期间，配合日军修建丰满水电站，强征劳工，造成大量劳工死亡，并协助日军推行“治安肃正”政策。','危害等级B（乙级，市县厅局级）','hanjian');
