INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec1661c4df654a2f822a5e60df2666ed','698a96ed-ea7e-4ddf-b083-d98965e028a5',1931,'原东北军旅长','原东北军旅长，九一八后投降日军，任伪满奉天省（含辽阳地区）省长，推行殖民政策，镇压抗日力量，后升任伪满治安部大臣。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-864cd69cbce646e4823e6f122a3c6408','698a96ed-ea7e-4ddf-b083-d98965e028a5',1931,'九一八事变后投靠日本','九一八事变后投靠日本，历任伪奉天省省长、伪满治安部大臣，积极协助日军镇压东北抗日武装，推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7f25e5538ac4cc7b80a34d582168588','698a96ed-ea7e-4ddf-b083-d98965e028a5',1931,'原东北军旅长','原东北军旅长，1931年投敌，在辽宁地区（包括铁岭、开原）组织伪军，配合日军“讨伐”抗日义勇军，后任伪满奉天省省长，残酷统治辽宁人民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19deff1ac1bf426093adbd1dd68c0137','698a96ed-ea7e-4ddf-b083-d98965e028a5',1931,'原东北军旅长','原东北军旅长，投日后在辽宁地区组织伪军，参与围剿义勇军和抗联，对凌海地区抗日活动进行清剿。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94e3a30046474f76954f1f4ede8fd923','0baa7f5b-5853-4f02-91cf-21b23e513a36',1931,'原奉系法律人士','原奉系法律人士，九一八后积极参与伪满建国，在四平、长春等地为日本殖民统治提供法律与行政支持。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82903afe88e34579938a4e2c7d0251f1','67ca3bcf-b478-4d4e-b2ea-f9d9f3b9cca9',1931,'原吉林副司令长官公署参谋长','原吉林副司令长官公署参谋长，1931年投降日军，打开吉林城门，并协助日军占领四平、吉林等要地，后任伪满高官。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-507f8b139bfc4ce1bb0e9530830e07c3','67ca3bcf-b478-4d4e-b2ea-f9d9f3b9cca9',1931,'原吉林副都统','原吉林副都统，九一八事变时在吉林投降日军，建立伪吉林省政权，后任伪满高官，推行殖民政策，协助日本掠夺东北资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de5b7c8335c84b48a5485f16f1265979','67ca3bcf-b478-4d4e-b2ea-f9d9f3b9cca9',1931,'原吉林副都统','原吉林副都统，九一八事变时在吉林开城迎敌，组织伪吉林省政权，为日军侵占吉林、四平地区提供便利。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ad917e0bc6a4b5887c6a5db0bcc01e5','67ca3bcf-b478-4d4e-b2ea-f9d9f3b9cca9',1931,'吉林籍满清皇族','吉林籍满清皇族，九一八事变时在吉林开城迎敌，促成日军占领吉林，后长期担任伪满要职。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8997225bd9554274818dddc1f2888ed6','67ca3bcf-b478-4d4e-b2ea-f9d9f3b9cca9',1931,'原吉林省政府委员兼吉林陆军训练处总监','原吉林省政府委员兼吉林陆军训练处总监，九一八事变时在吉林市投降日军，宣布吉林独立，后任伪满要职，是吉林地区首要汉奸之一。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-429945f125414887937b95d8ddf535a2','67ca3bcf-b478-4d4e-b2ea-f9d9f3b9cca9',1931,'原吉林副司令长官公署参谋长','原吉林副司令长官公署参谋长，1931年叛变，引日军占领吉林市，后任伪满高官，其叛变行为导致吉林地区迅速沦陷。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d172e0a148b426bb69f43d4ba1ba2ad','67ca3bcf-b478-4d4e-b2ea-f9d9f3b9cca9',1931,'清皇室后裔','清皇室后裔，原吉林副司令长官公署参谋长，1931年投敌，参与策划吉林独立，协助日军占领吉林全境，其势力影响覆盖白山、江源地区，为伪满核心汉奸之一。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
