INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70a421181c0c49d4b7cb12fe29b5122b','67ca3bcf-b478-4d4e-b2ea-f9d9f3b9cca9',1931,'原吉林副司令长官','原吉林副司令长官，投日后参与策划伪满建国，虽主要在吉林活动，但曾参与对辽宁地区抗日力量的围剿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
