INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5cc37ae471a4b25a73f4f302cfeab75','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原奉系法律人士','原奉系法律人士，投日后任伪满立法院院长，参与制定伪满法律，为日本殖民统治提供法理依据，其活动涉及吉林地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
