INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2ab2688af5542c4aa4163c4578ad29a','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原吉林律师','原吉林律师，投日后参与制定伪满法律，为日本殖民统治提供法理依据，其活动涉及吉林全省。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f91d82e11ff744baadbf5b935e59bd4e','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原奉系官员','原奉系官员，投日后参与策划伪满建国，虽主要活动于新京，但其势力涉及吉林全省，支持在辽源、东丰等地建立伪政权。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cb36a06a4ef4c1a9c74a821f5024f21','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原奉系律师','原奉系律师，九一八后投日，参与起草伪满洲国《建国宣言》，任伪满立法院院长，曾为日军在辽宁的殖民统治提供法律支持。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8d5f29803214cb187961efac73e76b5','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原奉系法律人士','原奉系法律人士，投日后任伪满立法院院长，为日伪统治提供法律依据，其立法影响安东省（含丹东、振安）的统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ddfee7f129df4ab1a5d9788404bbd535','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'曾任伪奉天市市长','曾任伪奉天市市长，后任伪满立法院院长，积极参与伪满立法，为日本殖民统治提供法律依据。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3771af17711442248ae9f29f5f05912d','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原律师','原律师，九一八后投敌，曾任伪奉天市市长、伪满立法院院长，积极为日伪立法服务。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5dbbe8f085c847058096e4f01b27e9b5','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原奉系法律顾问','原奉系法律顾问，九一八后投敌，参与起草伪满建国文件，任伪立法院院长，积极为伪满政权提供法律依据。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b8f37ce1ac041ddab82877fc689a3ae','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原奉系政客','原奉系政客，九一八后投敌，参与伪满政权建立，虽主要活动于长春，但曾参与对黑龙江地区抗日活动的镇压策划。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c580794fc5047e1841777b50e313665','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原奉系政客','原奉系政客，九一八后积极投靠日本，参与策划伪满建国，虽主要任职于新京，但曾多次到黑龙江绥化地区推行殖民政策，协助日军“治安肃正”。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5dc308bf7b564f5f81905d8ba6610ad9','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'曾任伪满要职','曾任伪满要职，参与制定殖民法律，支持日本对黑龙江的统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29ebca112ea547d39cc8fa8b356d24a8','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原奉系政客','原奉系政客，参与伪满建国，在黑龙江地区推行殖民政策，协助日本关东军统治','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0718866cd084f39aa8447a258bc988f','8672c587-c416-4e15-942a-8b8b42f62af3',1931,'原奉系法律顾问','原奉系法律顾问，后投靠日本，任伪满立法院院长，参与制定伪满法律，为日本侵略合法化服务。','危害等级S（特级，伪政权最高层/元首级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fab5df0bc294850bf5ab06e0f91f2ae','cf901620-debe-40fc-a223-29844695c9ed',1931,'原奉系政客','原奉系政客，投日后任伪满参议府议长，在吉林、四平一带鼓吹“日满亲善”，协助日军稳定殖民秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cac4c0a8859143f2a16ee9af1c2681f8','cf901620-debe-40fc-a223-29844695c9ed',1931,'清末举人','清末举人，曾任奉天省议会议长，九一八后投靠日本，参与策划伪满洲国成立，任伪满参议府议长，为日伪统治出谋划策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0538be5d2ebb458688a5a7a0bc5f3386','cf901620-debe-40fc-a223-29844695c9ed',1931,'原奉系文人','原奉系文人，投日后任伪满参议府议长，参与制定殖民政策，支持对安东地区的经济掠夺和思想控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6546d1d8afff466e9b72a75633e0edca','cf901620-debe-40fc-a223-29844695c9ed',1931,'原奉系政客','原奉系政客，九一八后组织“辽宁地方维持会”，投靠日军，后任伪满参议府议长，为日本侵略张目。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df29947b9f554bc7bd5f7fc698c0e708','cf901620-debe-40fc-a223-29844695c9ed',1931,'原奉系元老','原奉系元老，投日后任伪满参议府议长，支持日军在辽西的军事行动，对南票矿区实行奴化统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a3933fc6d874848953e0260368fe901','cf901620-debe-40fc-a223-29844695c9ed',1931,'奉系旧官僚','奉系旧官僚，投日后任伪满高官，为日本侵略政策服务，影响黑龙江地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9aefb52eb83146e1be42e2466059218d','46c3774f-42fd-4e43-8e31-0d7717d1eb4f',1931,'原奉系官员','原奉系官员，投日后任伪满监察院院长，参与伪满政权建设，在吉林地区推行“协和会”活动，麻痹民众抗日意识。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b9cdfc379c04f4d847426426253ecd3','46c3774f-42fd-4e43-8e31-0d7717d1eb4f',1931,'在吉林地区协助日军建立情报网','在吉林地区协助日军建立情报网，迫害抗日爱国人士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a329f71d575942899090c5e6868809f6','46c3774f-42fd-4e43-8e31-0d7717d1eb4f',1931,'原奉系政客','原奉系政客，投日后任伪满高官，曾参与策划对辽西地区（含葫芦岛、南票）的“治安肃正”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5094a7bf366949e29c8447fbeb8fc836','46c3774f-42fd-4e43-8e31-0d7717d1eb4f',1931,'原奉系政客','原奉系政客，九一八后投敌，任伪满监察院院长，为日本监督伪满官员，维护殖民秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a980793d15334c39a14cb318d7c8fd63','46c3774f-42fd-4e43-8e31-0d7717d1eb4f',1931,'原奉系外交官','原奉系外交官，投日后任伪满监察院院长，曾多次到辽宁各地（包括铁岭、开原）督导伪政权建设，镇压抗日分子。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ff13fcd282e440ca8ac7e1ade618af0','46c3774f-42fd-4e43-8e31-0d7717d1eb4f',1931,'原奉系外交官','原奉系外交官，投日后任伪满监察院院长，曾参与“日满议定书”签订，协助日本控制辽宁经济，对铁岭、昌图地区资源掠夺负有责任。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e5bb0866ad342be8ffb810fdb31b2fc','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军将领','原东北军将领，九一八事变后投敌，曾任伪满军政部总长，后任伪满国务总理，全面协助日本统治东北，其势力范围涵盖吉林、四平、伊通等地。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f53e8a27d4d424c95ff627578d38e43','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军将领','原东北军将领，投日后任伪满总理，虽主要活动于新京，但其政策覆盖吉林、四平、梨树，支持日军殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f25a6d31f3184ca48601cd9d978d637f','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军将领','原东北军将领，九一八后投敌，虽为伪满总理，但曾长期控制吉林地区军政，支持日军镇压抗日武装。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-480661319d274ff19fb788f84be4cf35','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军将领','原东北军将领，全面投日后总揽伪满政务，对吉林、辽源地区抗日活动进行残酷镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-99126c1282db4489833951b7c218421e','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军将领','原东北军将领，九一八后投敌，任伪满最高行政长官，其政策覆盖安东省（含丹东、振安），支持日军对辽东的殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-caf020e409e54e6ba44a6f285c5aeb38','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系将领','原奉系将领，后投靠日本，任伪满最高行政长官，全面配合日本侵略政策，对辽宁地区抗日力量进行镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bbf0b3e709ad4ab0becde99f4a169027','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'虽为伪满中央高官','虽为伪满中央高官，但其势力范围覆盖辽宁，曾多次到本溪、南芬地区视察“治安肃正”，推动建立保甲制度，强化对当地民众的统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd697f1a0c22457ab7f81aa68d8a08a1','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系军阀','原奉系军阀，后任伪满最高行政长官，虽不直接驻本溪，但作为伪满中央头目，其政策直接导致本溪、溪湖地区抗日力量遭受镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-215e4112655345f48106925d15a6a9af','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系将领','原奉系将领，九一八后投日，历任伪满军政部总长、国务总理大臣，是伪满最高汉奸之一。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
