INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-521bb0ce3f51420fabe16e8bc86f5be7','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系将领','原奉系将领，后投敌，任伪满最高行政长官，全面配合日本侵略政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f20374178de14ca492229e2d2474a6da','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系将领','原奉系将领，九一八后投敌，虽主要活动于伪满中央，但其势力范围覆盖辽宁全省，包括铁岭、开原，支持日军对当地抗日力量的镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-900b3cdcfa704e8e991dd50f421e66a6','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系军阀','原奉系军阀，九一八后投敌，任伪满军政部总长、国务总理大臣，是伪满最高汉奸之一，其势力范围覆盖辽宁全省，包括铁岭、昌图地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42b1fa0e65864ffe80f11ff7d64fb071','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系军阀','原奉系军阀，九一八后投敌，任伪满最高行政长官，虽非直接活动于铁岭银州，但其政策覆盖该地区，支持日军对辽宁的殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78fae97f3f5f475bbb647e3a6073eec5','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，虽常驻新京，但其政策影响辽宁锦州地区，支持日伪军对凌海等地的“治安肃正”。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bab937b75a304ebaa2d1ac6cdf844a5e','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系军阀','原奉系军阀，九一八后投日，虽为伪满中央高官，但曾在辽宁鞍山、岫岩地区部署伪军镇压抗日力量，其势力影响该地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83f9ee6d059a4770ab779ef76b878a91','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系军阀','原奉系军阀，九一八后投敌，任伪满国务总理大臣，虽主要活动于新京（长春），但其影响覆盖辽宁鞍山地区，支持日本对鞍山钢铁资源的全面控制。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-569eb61327fb493184358bd40b12a5cd','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军将领','原东北军将领，投敌后任伪满最高行政长官，其政策覆盖辽宁鞍山铁西地区，支持日军经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71b7287f06da44c4bd7aa3ed3947e75b','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系军阀','原奉系军阀，九一八后投敌，任伪满最高行政长官，其伪政权统治范围覆盖包括双鸭山岭东在内的整个东北，推行“日满亲善”政策，协助日军镇压抗日力量','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbd66d3b33bd4afdb816231da780fe35','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系将领','原奉系将领，九一八后投敌，虽主要活动于新京（长春），但其伪满政权对黑龙江、大庆地区实施全面殖民统治，负有最高责任。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7554766e36b845e5b61b2b4b0b7043cd','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军将领','原东北军将领，九一八后投敌，虽为伪满中央高官，但其起家于黑龙江，曾参与对肇源地区抗日武装的围剿决策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78a91ef77a06409498c6b695dbd9e2cc','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军政要员','原东北军政要员，九一八后投敌，虽名义上在长春，但其伪政权政策直接管辖黑龙江、牡丹江、东宁地区，支持日军对东宁要塞的建设和对抗联的围剿。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6358d9134c564a86a9e7ddde688a55ac','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系军阀','原奉系军阀，九一八后投敌，任伪满最高行政长官，虽主要活动于新京，但其政策直接覆盖黑龙江绥化北林地区，支持日军殖民统治，是最大汉奸之一。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bcd8feb2093d482c90e816aa95eed08e','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军将领','原东北军将领，九一八后投敌，虽为伪满最高汉奸之一，但早年曾活动于黑龙江地区，其伪政权政策直接影响到绥化、肇东，支持日军对北满的“讨伐”。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cbfa6b9e13974d59ba5c0ead85682a01','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原东北军将领','原东北军将领，九一八后投敌，曾任伪满黑龙江省长，后升任伪满国务总理，虽主要活动于新京，但曾多次巡视黑河、五大连池地区，督导日伪统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-30acdd2bcfe749c9be90594769aab483','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'虽为伪满中央高官','虽为伪满中央高官，但曾多次视察黑河、逊克地区，推动“治安肃正”计划，间接指挥当地伪军警围剿抗联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cff7e1e4f764829bcecdb55deb187fc','bffc5617-7c8c-4bbd-9dec-3121c3f66dc8',1931,'原奉系将领','原奉系将领，九一八后投敌，曾任伪满黑龙江省长（1932年），后升任伪满国务总理，全面协助日本统治东北，包括齐齐哈尔、泰来地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68e5fd27e42b405cab965ad574714a9a','0e098150-8a32-4812-9819-6a65caf61e43',1932,'原吉林地方官员','原吉林地方官员，投日后任伪满吉林省财政厅厅长，负责为日军搜刮吉林、四平、伊通地区的粮食和物资，支持侵略战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07dc00507e0d4e6eb13cb8c71d454251','0e098150-8a32-4812-9819-6a65caf61e43',1932,'原吉林地方官僚','原吉林地方官僚，投敌后负责伪满吉林省财政，为日军搜刮民财，强征捐税，支持侵华战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24e25b78bea442f4b5816731bb7f36e6','0e098150-8a32-4812-9819-6a65caf61e43',1932,'在吉林地区任职期间','在吉林地区任职期间，为日军筹措军费，强征粮税，掠夺东丰、辽源一带资源，间接支持日军侵华战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3d9535b53ed477b837fe89860032c95','46a2f70e-cbc1-491a-a7c8-b62d14a93483',1932,'原伊通地方士绅','原伊通地方士绅，投日后任伪满伊通县县长，推行保甲制度，组织汉奸武装，协助日军在伊通地区“清乡”，迫害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3de6a9caf2fa4e8784c3328454467eb3','1920c067-a4f0-4de5-ad31-a782ffadfafc',1941,'原伪满地方官员','原伪满地方官员，后任伪满四平省省长，管辖四平、伊通等县，积极推行日伪“粮谷出荷”政策，强征农民粮食，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bbcfb24b2f71498b941c73d8b0e73ef2','6d7a7013-9cc5-418b-ba65-c650c81622c7',1941,'原伪满警察','原伪满警察，投日后任四平省警务厅厅长，在四平、伊通地区建立情报网，多次破坏抗日地下组织，逮捕爱国人士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b55272e89d0e4ec79f62acbf392fa819','85655c5a-c645-494d-9c60-cf6fe0c5962d',1932,'原伊通县警察','原伊通县警察，投日后任伪满伊通县警务科科长，亲自带队搜捕抗日联军联络员，在伊通山区多次参与“讨伐”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59fda081de8349cfbae847ed44fd412e','002078c4-d078-48c0-b53d-eea5056b386a',1932,'原吉林省政府官员','原吉林省政府官员，投日后任伪满吉林省公署参事，参与策划对吉林、四平地区抗日武装的围剿，并协助日军建立“集团部落”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d77e46bdd3a41acb272966bc8319445','002078c4-d078-48c0-b53d-eea5056b386a',1932,'参与策划吉林地区“治安肃正”','参与策划吉林地区“治安肃正”，协助日军推行“集团部落”政策，导致大量百姓流离失所。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33fbd4bfa79b4f1e836c45bfa3c96d6d','9e2617d6-6f13-4138-b058-0cf7b0f20ab4',1932,'原吉林实业界人士','原吉林实业界人士，投日后任伪满吉林省实业厅厅长，在四平、伊通等地强占土地，开办日伪企业，掠夺当地资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1ff1caa17864da8a3bdbc5bfb84bac3','dfb3a7b2-9b12-4d7e-a358-586c200700a7',1932,'原东北军将领','原东北军将领，投日后历任伪满要职，曾在吉林、四平地区参与“治安工作”，协助日军镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eac0d60ab1924de78ba4f82e65b07503','a040a58f-b6e1-476b-88f7-f71267a05544',1931,'原吉林副都统','原吉林副都统，九一八事变时在吉林投降日军，建立伪吉林省政权，参与策划伪满洲国成立，其势力范围涉及吉林、四平地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02597e99c7b04e74af1cf138f15090ee','a040a58f-b6e1-476b-88f7-f71267a05544',1931,'原吉林省政府委员','原吉林省政府委员，九一八后主动投敌，参与策划吉林独立，任伪满财政总长，为日本掠夺东北资源服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-833634a44f7d44b194bfd18f98f18c4a','a040a58f-b6e1-476b-88f7-f71267a05544',1931,'原吉林副司令长官公署参谋长','原吉林副司令长官公署参谋长，1931年叛变，引日军占领吉林，建立伪吉林省政权，是吉林地区首要汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec0a73f29035438fa5c3bbf7f712e5f0','3a861354-2146-4309-879c-d154cb54b5a6',1931,'原东北军旅长','原东北军旅长，投日后在吉林、四平一带围剿抗日游击队，后任伪满军事要职，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cfb23b1cec2c4d9bb246ded1671dad56','3a861354-2146-4309-879c-d154cb54b5a6',1931,'原东北军旅长','原东北军旅长，投日后任伪满第一军管区司令，管辖包括吉林、松原在内的中西部区域，多次率伪军“讨伐”抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-562c95063cc44cf299422a82e5e7d405','3a861354-2146-4309-879c-d154cb54b5a6',1931,'原东北军旅长','原东北军旅长，投日后任伪满第一军管区司令官，驻防吉林地区，多次率伪军围剿抗日游击队，后升任伪满治安部大臣，对吉林、松原、扶余一带抗日武装进行残酷镇压。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3b152ad7d9249409a71f756e837f966','3a861354-2146-4309-879c-d154cb54b5a6',1931,'原东北军旅长','原东北军旅长，1932年投敌，任伪满第一军管区司令官，负责吉林东南部（含今白山、江源一带）的“讨伐”行动，屠杀抗日军民，后升任伪满治安部大臣。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-668a12271ae34949ba172e0f8598b1b6','3a861354-2146-4309-879c-d154cb54b5a6',1931,'原东北军旅长','原东北军旅长，投日后任伪满第一军管区司令官，驻防吉林、辽源地区，多次率伪军“讨伐”抗日义勇军和抗联部队，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c433ca707774447eb9decc538952af79','3a861354-2146-4309-879c-d154cb54b5a6',1931,'原东北军旅长','原东北军旅长，投日后任伪满第一军管区司令官，管辖吉林、通化地区，多次率伪军围攻杨靖宇部抗联，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8a4d183eca2470b853d50f669da67f7','3a861354-2146-4309-879c-d154cb54b5a6',1931,'原东北军旅长','原东北军旅长，投日后任伪满第一军管区司令官，负责吉林、通化一带“讨伐”东北抗日联军，制造多起屠杀事件','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-801191a50f404d0593366ad44d1f8e7a','3a861354-2146-4309-879c-d154cb54b5a6',1931,'原东北军旅长','原东北军旅长，投日后任伪满第一军管区司令官，管辖吉林、通化地区，多次指挥伪军围剿杨靖宇领导的东北抗联第一路军。','危害等级C（丙级，基层头目）','hanjian');
