INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffe8074c1e7c48a1ae7b73307a9cb38b','c5fa87fe-7fa2-435f-8d32-97393cf351ea',1931,'原东北军吉林副司令长官','原东北军吉林副司令长官，九一八事变后率先投敌，引日军进入吉林，后任伪满洲国财政总长、宫内府大臣，积极参与伪满殖民政权建设。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd7521c37b31404d8b1531ca506cfcf4','2439e4f6-3cb6-4852-b75d-e41ab3dacc5b',1931,'原东北军将领','原东北军将领，九一八后投敌，历任伪满要职，最终任伪国务总理大臣，全面推行日本殖民政策，其政权体系延伸至四平、铁东一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46ed09d93dc94bb9b4e8b58aaa6ce74c','2439e4f6-3cb6-4852-b75d-e41ab3dacc5b',1931,'原东北军将领','原东北军将领，九一八后投敌，历任伪满军政要职，后任伪满国务总理大臣，全面推行日本殖民统治政策，是伪满政权最高层汉奸之一。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89cb19448df9441a9c9a5827ff1a1b4d','2439e4f6-3cb6-4852-b75d-e41ab3dacc5b',1931,'原东北军将领','原东北军将领，九一八后投敌，历任伪满要职，参与签署卖国条约，推行日伪统治政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ce49ad20cc9419c999493c903a20823','30f304f4-8249-472b-9f1e-3f97aee37e92',1931,'原东北军东边道镇守使','原东北军东边道镇守使，1931年投敌，率部配合日军镇压东北抗日武装，其伪军活动范围包括四平及周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17694b304cf04b789074d55829914579','18220085-612b-4bbe-8775-c3e24d8c039e',1931,'原东北军延吉镇守使','原东北军延吉镇守使，随熙洽投敌，长期在吉林省内指挥伪军围剿抗日力量，四平地区在其伪警备管辖范围内。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19b9e1b145cf4909911bd683c24bef08','51775c8b-1333-4623-9b65-83ea16541cfc',1941,'伪满设立四平省后任省长','伪满设立四平省后任省长，直接负责四平及铁东地区的殖民行政，推行粮谷出荷、劳工征发等政策，配合日军经济掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-edeca1731d494f6a8f23b529a19d53b4','f341b2b6-ba71-4d98-b9d1-d50934131f46',1930,'长期在伪满地方政权任职','长期在伪满地方政权任职，曾任四平省次长，实际掌控四平地区行政，推行日本殖民法令，压榨当地民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23a40dcdd6ad4aac8941f7198b70ccf5','d6c766f9-6110-498b-9d0a-dd6e0233762d',1930,'任伪四平市市长期间','任伪四平市市长期间，配合日军在铁东等城区实施保甲连坐、物资统制，协助征发劳工，是四平城区直接附逆者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a4a36ebf1bd456eb12cd27e142c9b13','a5ed420f-b744-4233-8da6-8f933cebf82e',1940,'掌管四平省伪警察系统','掌管四平省伪警察系统，在铁东等地搜捕抗日人员，镇压民众反抗，推行治安肃正政策。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5602b98110ef42a2951b0d0203e4f53d','fd4ad786-d74b-49b6-adf9-3a262cedeffd',1931,'九一八后四平街成立维持会','九一八后四平街成立维持会，刘德权任会长，为日军筹粮筹款、维持地方秩序，协助日军接管四平及铁东地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f10855a9ed8d4d68bb3871b115b879c6','27d6edf2-31e4-4576-a556-6abf046bb762',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，1931年投敌，率伪军进攻黑龙江，其部队活动于吉林西部及四平周边，配合日军镇压抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a14e0b7b870149ff83b0be35a76cb917','0c32ebee-9222-44f4-8c87-2c94071e6305',1930,'清室后裔','清室后裔，投靠日本，曾任伪吉林省长，参与殖民统治，其管辖范围包括四平地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dae4ae04b63b4c66b9b82e8f2ac4cf28','d9ea28fe-f6d8-41ed-b3d4-954e10496f48',1930,'长期在伪满吉林省任职','长期在伪满吉林省任职，推行日本殖民政策，参与镇压抗日活动，四平地区在其省长任内受其管辖。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d166d26a83634da68c205ffd78683e68','7c2125cf-3734-4797-990c-7c3d30ffd2b0',1930,'曾任伪吉林省长','曾任伪吉林省长，配合日本经济掠夺，推行物资统制，四平地区的粮食、煤炭等资源被其政策搜刮。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-141a92313d544c76a1c97fd212bfaf79','78d620f8-6c51-4ae5-8f55-cb4ae5046c7b',1940,'负责四平省教育、文化、民生等殖民事务','负责四平省教育、文化、民生等殖民事务，推行奴化教育，在铁东等地学校强制日语教学，毒化民众思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b531d3becf3d4d128aef4b651b855ccf','77d09f38-25c5-402b-98df-0aa24218c219',1931,'原东北军将领','原东北军将领，九一八后投敌，在四平、铁西一带协助日军镇压抗日武装，推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6463a5983b79427ba31f8d9469df8909','5ea43efe-6e34-4e25-b78e-a099d632f8b9',1931,'原东北军旅长','原东北军旅长，投日后在四平、铁西地区参与“讨伐”抗日义勇军，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
