INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e111c23378bd46d7a6629722685fc7b3','8ded411b-65ae-4449-9742-718afd9c0164',1931,'原吉林警察头目','原吉林警察头目，投日后任伪满吉林省警务厅长，组织伪警察和特务在吉林、松原、扶余地区搜捕抗日志士，破坏地下抗日组织，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0806cd8ff3e48bab4f72c9f3b316ec4','8ded411b-65ae-4449-9742-718afd9c0164',1931,'原吉林警察系统官员','原吉林警察系统官员，投日后任伪满吉林省警务厅长，组织伪警察协助日军搜捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e3bedd8d0fe40a3a377919a1174e7d0','2f5b4b2b-b08c-470b-9d72-9cc61cef7e60',1931,'为日军筹措军费','为日军筹措军费，强征四平铁西地区粮食物资，支持侵华战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-233b9f54b8ca4a99ae7ee0cc810bf070','2f5b4b2b-b08c-470b-9d72-9cc61cef7e60',1931,'为日军筹措军费','为日军筹措军费，在昌邑强征捐税，掠夺粮食资源，支持侵华战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2fd297edb7c4ac394aa7c07c1a0417a','2f5b4b2b-b08c-470b-9d72-9cc61cef7e60',1931,'原吉林省官员','原吉林省官员，投日后负责伪吉林省财政，在松原地区强征捐税，搜刮民财','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e94a8a6364cd4ba8b299564003732b77','2f5b4b2b-b08c-470b-9d72-9cc61cef7e60',1931,'原吉林省财政官员','原吉林省财政官员，投日后任伪满吉林省财政厅长，在吉林、松原、扶余地区征收苛捐杂税，为日军筹措军费，搜刮民财。','危害等级B（乙级，市县厅局级）','hanjian');
