INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6af57c4146ea43fc9d61b3a2b53c7910','3f6bf130-8d38-42b8-b93e-4036c92a4511',1941,'伪满四平省（辖今四平、铁西一带）首任省长','伪满四平省（辖今四平、铁西一带）首任省长，推行“粮谷出荷”政策，导致当地民众饥荒。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf5f1ccb79a94da5b32bf356a9166c97','32ceb994-c31d-4a89-8d99-da072899fce9',1941,'协助荣厚管理四平省','协助荣厚管理四平省，强制征召劳工，镇压反抗民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a7340cab9ee488592b3d1f0ff430864','f2f56dab-5387-454c-bed9-197d65ca687b',1937,'在四平市（含铁西区）推行日伪法令','在四平市（含铁西区）推行日伪法令，组织“协和会”，迫害爱国人士。','危害等级B（乙级，市县厅局级）','hanjian');
