INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5896292f15764627869ea14f30dbacca','ba16ed4e-7e9a-447e-a40e-b36a6b9b58e0',1931,'原吉林商人','原吉林商人，投日后控制四平铁西地区工商业，为日军掠夺资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d8caf16e7564055ae7a95f0faa1cb88','ba16ed4e-7e9a-447e-a40e-b36a6b9b58e0',1931,'原奉天商会会长','原奉天商会会长，投日后任伪满经济部大臣，在辽宁推行经济统制，强征铁岭、昌图粮食和矿产，支持日本侵华战争。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ecb68df60096429ab9c8549f57e4f63b','3ed5e432-374b-4260-8fed-a59730847533',1941,'在四平铁西地区建立特务网络','在四平铁西地区建立特务网络，抓捕抗联联络员，刑讯逼供。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf8cbc2b00b54d579b468ee68d1ffff7','aa2b3d60-9891-4b7a-9f6c-d67d92f5d2dc',1932,'任伪和龙县县长期间','任伪和龙县县长期间，积极推行日伪殖民政策，强征劳工，镇压抗日军民，协助日军搜捕抗联人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e96c568645544fdb83f0e187de548667','ece87c44-d895-45fa-b1e4-6543e6a9f73e',1933,'在延吉地区组织警察特务','在延吉地区组织警察特务，破坏抗日地下组织，多次参与围剿东北抗日联军，残害抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ddd3a5ebb6b4f188b053e2232cbdd93','955d4934-870e-41dc-80ce-3fe8b0d8ca14',1935,'利用协和会组织','利用协和会组织，向当地朝鲜族和汉族民众灌输奴化思想，告密抗日分子，协助日军建立“集团部落”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7918b46368f040cc871e5bedd17a518b','5c3f079a-10d5-4963-9964-9068d16126e3',1936,'率警备队多次袭击抗联游击队','率警备队多次袭击抗联游击队，烧毁村庄，屠杀无辜百姓，并参与“讨伐”长白山区的抗联部队。','危害等级C（丙级，基层头目）','hanjian');
