INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-217d5b14eefc4267b13ce446ba750cc2','59cb3b8a-2b5f-4d05-8b96-c09924db206d',1932,'原吉林省实业厅长','原吉林省实业厅长，投日后任伪满经济部大臣，主导松原地区粮食统制和经济掠夺','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bcea536bafd54c9dbae8fc8cabc3fba5','0d55c2b5-3502-4b3b-a404-3e27daa56069',1931,'原奉系法律人士','原奉系法律人士，投日后参与伪满立法，曾协助日军在吉林地区建立伪司法体系，迫害抗日人士。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b7cbefff3b34772a5a1e68dd6c6b122','b431379d-368c-4861-87cb-c1f88d87d996',1932,'原吉林省官员','原吉林省官员，投日后任伪民政厅长，推行保甲制度，组织“自卫团”，协助日军清乡，迫害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-815b3b9d183e4d209b2cab84dda70061','b295ceb0-a857-45d9-9fff-5662f9a262fd',1932,'投敌后任伪吉林市长','投敌后任伪吉林市长，为日军提供物资，强制推行奴化教育，镇压学生反日运动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-697817c1bc2048b49e9f70cadb5f9faf','b295ceb0-a857-45d9-9fff-5662f9a262fd',1932,'投日后任伪吉林市长','投日后任伪吉林市长，推行奴化教育，强征物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5bf830150cf499da6b6819af1315013','b295ceb0-a857-45d9-9fff-5662f9a262fd',1932,'在吉林市任伪市长','在吉林市任伪市长，强拆民房修建军营，镇压市民反日运动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-378575717e6e415c8c736815882c1eb0','88b3c056-dfd5-4f5f-bd51-5ac9cf2ba08f',1932,'乾安本地汉奸','乾安本地汉奸，投日后任伪县长，协助日军在乾安地区建立伪政权，强征粮食，迫害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03f577dd847846c986e530236a84dcb0','9c9e285f-e8f9-4557-9c90-a505c87d2a4f',1932,'在松原（原扶余县）任伪警察署长','在松原（原扶余县）任伪警察署长，多次带队围捕抗日联军联络员，杀害无辜百姓，罪大恶极。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32d275c458e64318ab0e27d0700cdb12','161608c3-d34a-49fb-9eac-02358afc5d89',1933,'乾安伪警察头目','乾安伪警察头目，参与“讨伐”抗日武装，严刑拷打抗日嫌疑犯，直接参与多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
