INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-658caeb62a664ad19a67c845311b2b65','6492194f-580d-48ed-a0c8-a1ef5d0728f7',1932,'率伪保安队在吉林、松原交界地带袭击抗日游击队','率伪保安队在吉林、松原交界地带袭击抗日游击队，烧毁村庄，抢夺财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c66d4b22ae24e538406242d66605991','fc4cb747-efdc-44c5-afad-aba06fb7e9b4',1933,'组织地方自卫团','组织地方自卫团，配合日军“扫荡”，在乾安农村抓捕抗日积极分子，实施连坐。','危害等级C（丙级，基层头目）','hanjian');
