INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4cee82183281447fb3d87f595446bc80','b9af125e-814e-43fb-8df2-0d38e9105f0e',1932,'清室后裔','清室后裔，投靠日本后任伪满吉林省省长，积极推行日伪殖民政策，协助日军镇压吉林抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0d7d733fc87457fb57a0120ea51332c','27cfc958-ab2a-4a97-a9c6-1b3f47e01714',1932,'原吉林省政府官员','原吉林省政府官员，投敌后历任伪满吉林省省长、民生部大臣，参与制定并实施奴化教育政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f3ff703174f4baf83996070577f3a64','27cfc958-ab2a-4a97-a9c6-1b3f47e01714',1932,'原吉林省政府官员','原吉林省政府官员，投敌后任伪吉林省长，协助日军清乡，强征劳工。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d337ab1a227408290d4921a7a43d06b','9a00bbf2-fb14-436d-b164-7b53fd7dc9e7',1932,'原东北军旅长','原东北军旅长，投日后任伪满第一军管区司令，驻吉林地区，多次率伪军围剿抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
