INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a37e8e203ce459c9ca87e2e021471b0','62f28f4a-24af-4b54-b4fc-18bd68b2a6ae',1932,'原吉林警察头目','原吉林警察头目，投日后任伪满吉林省警务厅长，组织警察特务搜捕抗日志士，破坏地下抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b7b49ece2324843988cab257dc6dfad','62f28f4a-24af-4b54-b4fc-18bd68b2a6ae',1932,'原吉林警察头目','原吉林警察头目，投日后负责吉林地区伪警察系统，搜捕抗日地下人员，协助日军推行保甲连坐制度。','危害等级B（乙级，市县厅局级）','hanjian');
