INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b36ac1bf4474eecb891cb665aee4c11','a44b3bb1-6a5f-4dde-a4a9-9f0b3299d819',1937,'虽主要活动于华北','虽主要活动于华北，但曾作为日本顾问参与吉林地区伪政权协调，协助日军在松原、前郭尔罗斯一带推行“治安肃正”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
