INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-279142b135254bce87c22161433f547d','38d4abaf-12cb-47b7-8b2c-e7e7528bf3d5',1932,'在吉林地区为日军经济掠夺服务','在吉林地区为日军经济掠夺服务，强征农民土地，控制粮食贸易，导致当地民众饥荒。','危害等级B（乙级，市县厅局级）','hanjian');
