INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86adad9b02fe48738d0aa2c7773f467e','5e2ef9c4-e10f-414f-a050-b540d9c67112',1935,'推行奴化教育','推行奴化教育，强制学校教授日语，删除中国历史内容，毒害吉林青少年。','危害等级B（乙级，市县厅局级）','hanjian');
