INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1a499e9f0f44e6593977d42c67061ac','ddfad739-c6f4-4d03-96e7-bfd1d1029147',1931,'原吉林警察机构官员','原吉林警察机构官员，投日后负责吉林省（含宁江地区）警务，组织伪警察配合日军清乡，抓捕抗日志士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
