INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c096ff9587b04ba2ba209cbb46f9f835','721b78c0-d0f6-493f-906f-0382d95b9450',1932,'原东北地方官员','原东北地方官员，投日后在吉林省公署任职，参与制定“治安肃正”计划，对松原、宁江等地的抗日武装进行围剿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e7a906c3e624587a7b8ba5411cc8d4a','cd3af6ee-400a-4d96-b9da-dbf1ec3520a9',1933,'在吉林、松原地区指挥特务活动','在吉林、松原地区指挥特务活动，破坏地下抗日组织，逮捕并刑讯抗日人员，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-619a239fd3bd44a194aadfbf27c17e63','e5a2bcd0-485c-4824-9d2b-a85c6f7cbf62',1932,'原地方土匪头目','原地方土匪头目，投日后组织伪保安队，在宁江、扶余（今松原）一带协助日军“扫荡”，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ad352e8da77400c8a6885ef283368ab','c9c80e03-a3a9-4c3a-8f9b-92715ef6f3c2',1931,'原东北法律界人士','原东北法律界人士，投日后任伪满司法高官，在吉林、松原地区推行伪满法律，迫害抗日人士。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08f98f7240de4e9e8aaf97d2c39236a6','c9c80e03-a3a9-4c3a-8f9b-92715ef6f3c2',1931,'原奉系法律顾问','原奉系法律顾问，投日后任伪满吉林省高等法院院长，在吉林、辽源地区审判抗日志士，以“反满抗日”罪名判处多人死刑。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7c24a519b3041b79afafb756883bfed','f5eda7bd-1c0f-4b76-9886-749a8ccd65a4',1931,'原吉林财政官员','原吉林财政官员，投日后负责伪满在吉林、松原地区的经济掠夺，强征粮食和物资，支持日军战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf5abaac76a3451089f6b905e191d787','f5eda7bd-1c0f-4b76-9886-749a8ccd65a4',1931,'原吉林官银号总办','原吉林官银号总办，投日后负责伪满在吉林、辽源地区的财政搜刮，发行伪币，掠夺粮食和物资，支持日军战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1941c499729474aa1b971d41c80a86a','2dba48c3-a257-4c12-af1e-43db419e72c6',1932,'原吉林教育界官员','原吉林教育界官员，投日后推行奴化教育，在宁江等地学校强制灌输“日满亲善”，抹杀民族意识。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5de29756fbfb4bd08b2ed29a279e4cf2','efd56dcb-a0d9-49de-b4a4-638bc9252196',1931,'原吉林省警务处长','原吉林省警务处长，投日后任伪满吉林省省长，在吉林、松原、扶余地区推行保甲制度，强征劳工，协助日军建立殖民统治，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4ca6fd63da74990a4eb111a4a5164eb','efd56dcb-a0d9-49de-b4a4-638bc9252196',1931,'原东北军将领','原东北军将领，投日后任伪满吉林省省长，在吉林地区推行殖民政策，协助日军镇压抗日活动，并参与对通化、集安一带的“讨伐”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6647c72ceafe4b1393323cefc3d3ef0a','b8cd83a6-6296-4831-bacd-fe06826de35d',1931,'原地方土匪头目','原地方土匪头目，投日后被日军收编为保安队，在扶余、松原一带活动，配合日军扫荡，残害百姓，抢夺物资，杀害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb9eedd46f6e4b5ca1b26bf8e8b714f8','60fd714e-8645-4ab5-b88c-763bcf384da8',1931,'原奉系政客','原奉系政客，投日后任伪满立法院院长，曾参与策划吉林地区伪政权建立，为日军侵华提供法律和舆论支持，其势力涉及吉林、松原、扶余。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ddf17c72cf645b3a85916c44a8bf9b5','5175b134-6aa2-489f-84bd-48e1e063544e',1931,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪满黑龙江省省长，扶余地区曾属其管辖范围，推行日伪经济统制，强征粮食，压迫民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95d4bce8a5c74d5b913b2f40ed500424','028805a5-2a10-4968-b885-f06d4f5124d6',1932,'投日后任伪满扶余县县长','投日后任伪满扶余县县长，在扶余地区推行日伪殖民政策，组织伪县公署，协助日军清乡，强征劳工，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdf137b487b94c468dfa26c5ef025eb0','98d263fd-22ba-44cf-9fd4-e1950ffbb663',1932,'投日后任伪满前郭旗旗长（今松原地区）','投日后任伪满前郭旗旗长（今松原地区），在蒙古族聚居区推行日伪统治，协助日军建立情报网，迫害抗日分子。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0df37e6067bb4f6bae7eba5f7036adaa','dbc3f0ff-ce36-4388-9c85-a05a230bbaae',1931,'为日军宪兵队担任翻译','为日军宪兵队担任翻译，在吉林、松原、扶余地区参与审讯和刑讯抗日人士，直接参与多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7e5e0d402504a0b897ccb2adf2fcd19','192bbb33-f2f5-4aec-b27a-3be2a8b13905',1932,'投日后任扶余县警察署长','投日后任扶余县警察署长，带领伪警察在扶余、松原一带抓捕抗日地下党员，破坏抗日联络站，残害群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-036b0f98e3524a988035d4ab92ac158b','e76f0329-55a6-44fd-9293-0df6338c2f7a',1931,'原吉林副司令长官公署参谋长','原吉林副司令长官公署参谋长，1931年叛国投敌，打开吉林城门迎日军入城，后任伪吉林省长，协助日军清剿抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4dcff4d8ec824cb08d38d22505f3becd','468f4923-e2a9-400b-b6e6-390741cbfdf5',1932,'原东北军将领','原东北军将领，投日后任伪满军职，在吉林、松原一带率伪军围剿抗日游击队，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec3b3b1c47ad4c398eaa40d5bd9b43d8','468f4923-e2a9-400b-b6e6-390741cbfdf5',1932,'率伪军配合日军在船营及周边“讨伐”抗日武装','率伪军配合日军在船营及周边“讨伐”抗日武装，制造多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc704e07c59a43e8b58cf57838ad6e70','53a68caf-5edd-477f-b071-850c8cce6412',1932,'吉林本地汉奸','吉林本地汉奸，积极参与伪满行政建设，为日军征粮派夫，镇压当地反满抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a46690e922b42afab97c44a8aee584e','42d90f4c-6486-4735-9b82-87cff3df5685',1932,'原奉系官员','原奉系官员，投日后在伪满任职，曾参与对吉林西部（含松原）的殖民统治，协助日军掠夺资源。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1c4ef740f0c46cb9ed67c185da18445','4a13437a-ad5f-40d5-a362-8ac4bbe3ae2f',1932,'在松原地区（原扶余县）任伪县长','在松原地区（原扶余县）任伪县长，协助日军建立伪政权，组织伪警察镇压抗日活动，强征劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58c3c04d09fe4b8d81625756fa07eddd','30446452-034f-4d5f-8ff6-285dd07fcd85',1932,'在松原前郭尔罗斯地区任伪旗长','在松原前郭尔罗斯地区任伪旗长，推行日满亲善政策，为日军提供情报，迫害蒙古族抗日志士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5042e02de147426e8ffab80aad9c8679','38744dff-e7a2-4bc9-a04f-703c32d16336',1933,'在乾安地区协助日军清乡','在乾安地区协助日军清乡，组织汉奸武装，杀害抗日联军联络员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62ea55b82ed14ee895bb623bea80fe0d','6540771a-16a4-4149-b33a-984c830835ce',1934,'在长岭县率伪警多次围剿抗日武装','在长岭县率伪警多次围剿抗日武装，逮捕并刑讯抗日群众，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03a9452967a042bc825327899c727a63','dd673c78-021e-4bf3-b195-7468c6c64794',1935,'原奉系军阀','原奉系军阀，全面投日后任伪满总理，对吉林、松原地区推行奴化教育，签署多项卖国条约。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d21db399d21481096706da32039c5e4','e44154af-5134-481f-a143-3e896109d328',1932,'原吉林督军署参谋长','原吉林督军署参谋长，投日后在伪满中央任职，但曾参与吉林地区伪政权组建，为日军出谋划策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3e262f12ac7452795c849b9863d288b','d9f24772-ed51-4f38-9315-80b7c4453f9e',1932,'原东北军旅长','原东北军旅长，投日后任伪保安司令，在吉林、松原交界地带围剿抗联部队，杀害多名抗联战士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb55b267de1c4b03a1e9e580ea5b90ed','b6f4187b-cae9-4fc8-8f98-f6eee2ad4eb9',1932,'在扶余县为日军征购军粮','在扶余县为日军征购军粮，垄断商业，向日军提供抗日分子名单，导致多人被捕。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68b2e7d5ad4f43bf9d0f0020610f2f1d','1bf5222f-7f76-4be7-9ec4-e5fc909364a3',1933,'在前郭旗残酷镇压蒙古族牧民反抗','在前郭旗残酷镇压蒙古族牧民反抗，参与“治安肃正”行动，烧毁村庄，强征民夫。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84fde2d9db5340b3b2505776ba5b5e78','4ff6a3fa-d9fe-4828-940e-05b03e7a5e76',1932,'原吉林军官','原吉林军官，投日后任宪兵队顾问，参与策划多次大搜捕，在吉林市区及松原地区杀害抗日志士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5b64b01a9844566ac32fe93c12742b4','ec89f38c-38bf-494e-833e-ef6c483913c0',1935,'在长岭县推行“集团部落”政策','在长岭县推行“集团部落”政策，强迫农民并村，导致大量百姓冻饿而死，并配合日军扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1512eaf7b934a8a9572b0983a416ccd','3f3367b2-23f4-4e51-afc8-cc634a3d48aa',1931,'九一八后投敌','九一八后投敌，率伪军配合日军进攻吉林各地抗日武装，参与镇压吉林、松原一带抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0f148eade794bc1a0bec032c5c2b576','793e8131-eff3-4928-a21c-71dfbe991368',1931,'原东北军吉林部队将领','原东北军吉林部队将领，投敌后任伪吉林省警备司令，协助日军控制吉林地方，镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01a6b9e3b20f4275a65c526fab12319f','f7753905-ae71-46e4-93a6-e48d51c4b688',1931,'在伪吉林省政权中任职','在伪吉林省政权中任职，参与推行日本殖民政策，管理地方行政，涉及今松原、长岭一带的伪政权运作。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b79207202ba9498d9ad984db5c3156b8','4f8f6988-9f02-45ec-b8f7-8a95ced3e64d',1931,'在伪满时期任扶余县伪县长','在伪满时期任扶余县伪县长，扶余即今松原市辖区，参与征粮、抓丁、镇压抗日群众，为日军维持地方统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6cc5423c8cd412b8f2505d980a8f2e2','79b5a9b2-7c24-47b3-9d39-c9920d50b3c1',1931,'在伪满时期于郭尔罗斯前旗（今松原前郭尔罗斯蒙古族自治县一带）任伪旗长','在伪满时期于郭尔罗斯前旗（今松原前郭尔罗斯蒙古族自治县一带）任伪旗长，配合日本殖民统治，控制地方蒙旗事务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57e4c5e9a29940c7a6c4d7c6c559e340','3407839a-2d4a-4bc5-8a5e-9bc24dc8701f',1931,'伪满时期在郭尔罗斯前旗任职','伪满时期在郭尔罗斯前旗任职，协助日本推行蒙旗殖民统治，涉及今松原地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c82237e38f7a4d6ab8898b36448f024f','3bc136f8-ebc5-4f67-98d2-4901f169de26',1931,'伪满时期任长岭县伪县长或维持会头目','伪满时期任长岭县伪县长或维持会头目，直接参与长岭地区的伪政权统治，为日军征粮、派夫、镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97ff8908da95442c941b882dffcf5338','33e0ff04-7b75-45cd-b9f0-07c100c0e8f4',1931,'在伪满长岭县警察系统任职','在伪满长岭县警察系统任职，带领伪警察配合日军搜捕抗日人员，镇压当地民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4fa1ec33da448b4af3171ba3f783f99','3bbb2fe8-c507-4373-bc7c-b33b4e259912',1931,'伪满时期在乾安县（今属松原市）任伪县长','伪满时期在乾安县（今属松原市）任伪县长，推行日本殖民政策，控制地方。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-942ae9d1b28c4d31a2dc1a0488b642d9','03085ce8-e9a3-48c3-9d3c-5c786fd67d43',1931,'九一八后投敌','九一八后投敌，率伪军进攻黑龙江、吉林等地，其活动范围覆盖今松原、白城一带，配合日军镇压抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-467d93c818414faca0428e9423eb8493','91137381-45ba-4db3-ad77-9a75ff29d596',1931,'投敌后率伪军配合日军在吉林、黑龙江交界地区作战','投敌后率伪军配合日军在吉林、黑龙江交界地区作战，涉及今松原一带的抗日镇压。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47049d38c1084c57ac263b65d5d4ec2e','320ca77f-32dd-441e-aa55-67fbb0b02f95',1931,'在伪吉林省政权及协和会中任职','在伪吉林省政权及协和会中任职，推行殖民思想宣传和地方控制，活动范围包括今松原地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c87d6d5e659b4cd6ab25758d5f713755','fe7b8b3b-d12a-4cc8-b48c-4daf54eaabec',1931,'伪满时期在农安县（邻近今松原）任伪县长','伪满时期在农安县（邻近今松原）任伪县长，参与征粮、抓丁，协助日军维持统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae9f14f5aeab444dbe35ba09f62d3fd3','e71c659c-2287-478e-bd46-ee7f7e5cbdc9',1931,'在伪吉林省政权中任厅长等职','在伪吉林省政权中任厅长等职，参与地方殖民行政，涉及今松原、长岭一带的伪政权管理。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1adc55acae4f4cf585afcceb84fd2113','6b4b197c-8db1-45dd-a938-34d019c38a26',1931,'伪满时期任伪吉林省省长','伪满时期任伪吉林省省长，推行日本殖民统治政策，其辖区包括今松原、长岭地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-87960e0a4cce4ab3952c64f6cb70f41f','85afd200-53e8-4c15-bbc9-275c3f3f5bef',1931,'在伪吉林省政权中任职','在伪吉林省政权中任职，参与司法镇压和殖民管理，活动范围覆盖今松原地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05836eefcd5f4cefaf73e443760e3850','b2db5b0f-3672-4cc8-af66-a87fcd322155',1931,'在伪满扶余县警察系统任职','在伪满扶余县警察系统任职，带领伪警察镇压抗日群众，维护日伪统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64cb3a62124c4c42b452460ccee361df','9b21b9c6-1ceb-45dc-8fe8-207afb8d4312',1931,'在伪满长岭县组织伪自卫团','在伪满长岭县组织伪自卫团，配合日军和伪警察搜捕抗日人员，控制地方。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9d43e7e50d64556be48a6745a4e496a','ad8b629c-dd4f-40f9-a09f-23565bef28a8',1932,'在桦甸县任职期间','在桦甸县任职期间，积极协助日军镇压抗日武装，多次率伪警察讨伐抗日游击队，抓捕并杀害抗日军民数十人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22f6b420cd2a45be9c94db7298cfd4d5','5190257f-a8cd-4770-9608-ffabe5cdec05',1931,'原东北军将领','原东北军将领，九一八后投敌，任伪满军事要职，其部队在桦甸、吉林地区参与“讨伐”东北抗日联军，烧杀抢掠，破坏抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c631dbc49326411089cdbb9371aa1148','f7ab30ca-9ae7-4503-8470-102fe21430b7',1932,'率伪军多次进攻桦甸、磐石一带的抗日游击队和抗联部队','率伪军多次进攻桦甸、磐石一带的抗日游击队和抗联部队，制造多起惨案，是日寇在吉林地区的主要帮凶。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7918781d45cc47e5b86337995d2092f2','6bca5454-f1cd-4854-819d-0b7994dabbd6',1932,'在吉林地区推行“治安肃正”','在吉林地区推行“治安肃正”，指挥伪军配合日军对桦甸山区进行反复“扫荡”，杀害抗联战士及无辜百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b81a12a8bdf46a49e566eefd1244e6f','d2092736-f69d-4993-99d1-608091af03bf',1933,'在任期间强征劳工修建警备道路和碉堡','在任期间强征劳工修建警备道路和碉堡，为日军提供粮食和物资，并组织汉奸情报网，破坏抗日地下组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16c43870fc9d40d1bd6936e664ced497','be3bafdf-aa53-44f7-9068-f16f00d27bab',1935,'积极宣传“日满亲善”','积极宣传“日满亲善”，协助日伪当局推行“保甲连坐”制度，检举抗日分子，导致多名抗联联络员被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c4118a54e164b4293e12af9563aa24d','ff88b474-1433-4a60-bdb4-3aed655c5b10',1936,'亲自带队搜捕抗联密营','亲自带队搜捕抗联密营，在桦甸红石砬子一带袭击抗联伤病员，并参与“归屯并户”政策，制造无人区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e4e262ed6fc437b9399eb627fd3eda7','dd718190-03c6-488b-abef-36e5e92c21a9',1937,'率保安队配合日军在桦甸夹皮沟、老金厂等地围剿抗联第一路军','率保安队配合日军在桦甸夹皮沟、老金厂等地围剿抗联第一路军，多次提供日军情报，并杀害抗联侦察员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-002105c243c64a7aba46227b0ef5e7cb','c0daa64d-b99e-48a5-bd6e-e410ab6e2c67',1940,'将抓捕的抗联嫌疑人和无辜百姓投入矫正院','将抓捕的抗联嫌疑人和无辜百姓投入矫正院，实施酷刑和劳役，致多人死亡，是日伪法西斯统治的忠实执行者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d387fa5f84446ec868147f3bfb27bae','4894e860-2278-47b3-8b3d-972c444ad40d',1938,'率伪军多次深入桦甸山区“讨伐”抗联','率伪军多次深入桦甸山区“讨伐”抗联，烧毁村屯，抢夺粮食，并诱降抗联叛徒，破坏抗联组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6313fcb7b04434fb320b78609cc3369','40afb4bb-6a7c-42a1-855a-f4c3127ad877',1932,'投靠日本','投靠日本，任伪吉林省财政厅长及省长，协助日军搜刮资源，推行奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f94d105c4a854b37aa753b8549cde882','2b553569-2e96-4869-88cb-0a2ac818dedc',1933,'长期担任伪吉林省警务厅长','长期担任伪吉林省警务厅长，后升任伪省长，镇压抗日义勇军和地下党，抓捕爱国人士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05355ad3ed59444585f3fb325566507e','568904ec-fa27-4132-93ac-277e6df2f0ce',1935,'投敌后任伪省民政厅长','投敌后任伪省民政厅长，推行保甲制度，协助日军清乡，迫害抗日家属。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4604d1fcd74047368cdd740c1cc4fedd','d3ef7714-b39d-4c25-8ad6-4c97b21ee148',1932,'任伪永吉县长期间','任伪永吉县长期间，强征劳工，为日军修建军事设施，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c539b1fb2214fed99453fa14a35fd55','4d30f4a2-2e00-484c-bcf0-162ecfb53054',1933,'协助日军搜捕抗日分子','协助日军搜捕抗日分子，破坏地下组织，参与制造多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9052586891b4840b4ea16863a3edae1','30351390-97df-48a4-95ff-15ca56242e50',1932,'推行奴化教育','推行奴化教育，强制学校教授日语，篡改历史，灌输“日满亲善”思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a741f010dde4db8848cabe30894d8ae','30351390-97df-48a4-95ff-15ca56242e50',1932,'推行奴化教育','推行奴化教育，强制学校教授日语，篡改历史教材','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0674730c644c4e0fb999dba90be426be','5b942041-a528-4295-9da5-0ea126e6a20e',1932,'协助日本掠夺吉林木材、矿产等资源','协助日本掠夺吉林木材、矿产等资源，为日军提供经济支持。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c5cc968cd4d4a69b2174549635e9ec3','99d349ee-1b5e-4b92-8914-1dfa2d34a058',1937,'组织协和会','组织协和会，宣传“王道乐土”，煽动民众支持伪满政权，监视抗日言行。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5476de21146437ea9b641295b21d2a4','f368bd21-d411-43d8-847d-0580fbe07414',1938,'协助日军进行思想控制','协助日军进行思想控制，举报抗日群众，参与“治安肃正”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e74090d84afe4d6496cd3ee21f133fea','8038f3de-e0f0-4171-8670-fd0bb9fd57d9',1931,'九一八事变后率部投敌','九一八事变后率部投敌，任伪洮辽警备军司令，镇压白城、洮南等地抗日武装，配合日军占领洮南、开通、瞻榆等县。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf41640997734d51857e7e832fd634c7','a63a3771-468f-44d8-adc1-8852ec3772fc',1932,'投靠日军后任洮南县长','投靠日军后任洮南县长，推行日伪殖民政策，强征民夫修建警备道路和碉堡，协助日军清剿抗日义勇军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db02ba146e6c4ec4a85881eee2531c3c','c7ab265c-c3e5-40b7-a5c4-f7a0f1c1640d',1933,'在伪白城子警察署任职期间','在伪白城子警察署任职期间，多次参与搜捕抗日地下人员，严刑逼供，破坏抗日组织，并协助日军收缴民间枪支。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2470f970a0e54168a81c8fede2d0ee7d','7cec2c7a-1874-492f-a60e-c81bb5dd3318',1936,'任伪洮安县（今白城）协和会会长','任伪洮安县（今白城）协和会会长，积极宣传“日满亲善”，组织奴化教育，强迫民众参加“勤劳奉仕”劳役。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e9a983a3606472e839aa97b3d2b4265','af6c28de-c0e4-4fb1-9c51-ef16f4308064',1937,'率保安队配合日军“讨伐”抗日联军','率保安队配合日军“讨伐”抗日联军，在洮南、镇赉一带烧毁民房，屠杀抗日群众，曾参与制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc4b569552ca4f47b0e3269d6d679da6','e5198d67-0d68-4808-b6ea-5e987c285b89',1938,'主管伪警务','主管伪警务，推行“保甲连坐”制度，多次组织特务搜捕抗日分子，将捕获的爱国人士移交日军宪兵队处决。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a55451ac63f34a688d32640431bf3471','4331b948-8de3-4ed8-8c71-da945d3ce184',1939,'组织地方自卫团协助日军封锁抗日游击区','组织地方自卫团协助日军封锁抗日游击区，在洮南、通榆等地设卡盘查，截断抗日物资运输线，并参与“集家并屯”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0da7a42268c469a88a529fae13edbf3','5230df2b-22a8-41fa-a477-503c59de06ce',1940,'作为伪满高级官员','作为伪满高级官员，负责洮辽地区行政事务，强制推行“粮谷出荷”政策，搜刮农民粮食支援日军，导致当地严重饥荒。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06f99518f82d434aab356cc5184c8595','598788ba-9ddf-46ef-b8c4-4c7b3e218cc8',1931,'原东北军将领','原东北军将领，九一八后投敌，在洮南（今白城地区）一带协助日军镇压抗日武装，后任伪满热河省省长，参与围剿抗日联军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-445b0a5f684b4cb29596de855c1df454','6a5f57c2-f0b9-4851-8a70-863950b2bbf4',1931,'原东北军旅长','原东北军旅长，九一八后投敌，在吉林、白城一带协助日军清剿抗日力量，后任伪满治安部大臣。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6538f936d9974668b3ce5be03b4d00d1','feea48bb-1775-4a69-a5cc-0e327bc08368',1931,'原吉林陆军训练处监','原吉林陆军训练处监，投敌后任伪满军职，在吉林地区镇压抗日活动，曾驻防白城、大安一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e313ccc24ae246299e481e30a24c5b14','7d73e5e1-91ef-418d-8157-7d20fead3d59',1932,'原吉林省政府官员','原吉林省政府官员，投敌后任伪吉林省长，推行日伪殖民政策，参与镇压吉林、白城地区抗日义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c9424c16e1542d38b867b1c452c96fe','a1ab80fe-393d-45e6-827d-dab7075f7307',1934,'原吉林省财政厅长','原吉林省财政厅长，投敌后任伪吉林省长，协助日军在吉林、白城、大安地区建立保甲制度，搜捕抗日分子。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a5321cc303744eeb6c13679bbc2130e','9a29b5f9-5dc6-4975-ac1c-15992188cee8',1937,'原东北政务委员会秘书','原东北政务委员会秘书，投敌后任伪吉林省长，在吉林西部（含白城、大安）推行“治安肃正”，配合日军讨伐抗联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78b4ea2f312c4f8fa3796b67b35e68c9','6b3a4f11-41f1-475a-9a93-6b97728f8179',1940,'原吉林交涉署署长','原吉林交涉署署长，投敌后任伪吉林省长，在任期间强化对白城、大安地区的粮食统制，压迫民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9988f691b6964d11a1aa824796b6ca73','661aed07-bac0-4a79-bbf4-10852bc1e11a',1942,'原吉林高等法院院长','原吉林高等法院院长，投敌后任伪吉林省长，协助日军在白城、大安地区强征劳工，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac799a726dd14557b10af778518fdb5f','804d926c-090b-4e0d-9659-c34ac642b19e',1932,'原奉天律师','原奉天律师，投敌后参与伪满立法，其活动涉及吉林全省，支持日伪对白城、大安地区的殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ecca269d45a4785b501de7c3c356958','20dc587e-9823-45a1-a815-5564201ea60d',1932,'原哈尔滨商会会长','原哈尔滨商会会长，投敌后历任伪职，曾管辖白城、大安地区（原属黑龙江省），推行经济掠夺政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7fd78acf0c1c479a969a1aa4f5b1ea47','6444b3ef-64a9-4e01-a071-d2f137d282fe',1931,'原吉林省政府委员','原吉林省政府委员，投敌后任伪吉林省长（1932年短暂），后任伪满财政部大臣，参与对吉林西部地区的经济压榨。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab30b3e72a0443b3a50459ab49372eec','bcd859de-95d9-4b60-92d9-78e91d43e6c1',1931,'原吉林省政府主席','原吉林省政府主席，九一八后投敌，任伪吉林省长，在任期间向日军提供白城、大安地区情报，协助占领。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e14b95554a1c43898a48fe579df08131','9811c404-cc79-4c88-b0a6-b80ce2054e97',1932,'原东北军将领','原东北军将领，一度抗日，后于1933年投敌，任伪满吉林警备军司令，在洮南（白城）一带围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f32c80686612462ba7262f1368b67f58','be442e01-db28-4ba7-8c04-f9e4c8e7840e',1932,'原东北军旅长','原东北军旅长，投敌后任伪满军职，曾驻防吉林西部，指挥伪军在白城、大安地区对抗联进行“讨伐”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82dfc38f7fb547d3a2a42b227e12a373','b94d47cd-3257-4b37-b393-0ae7255deab6',1932,'原东北军军官','原东北军军官，投敌后任伪满吉林警备军参谋长，参与策划对白城、大安地区抗日游击队的围剿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f84f55d680a4f649198157b2bc3fd6c','dd271f53-186d-40fc-ab44-daa0eb1347a6',1932,'曾抗日','曾抗日，但1932年一度投敌任伪黑龙江省长，管辖范围包括白城、大安地区，后反正，但期间有附逆行为。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c0e65f0b93a46ffa06fe89f5235ac39','34ebdb33-5d4e-4db1-b9ff-40d088285bf7',1932,'原黑龙江省防军旅长','原黑龙江省防军旅长，投敌后任伪职，在洮南（白城）地区协助日军镇压抗日义勇军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-018c5f265a9349448d30a86eafe2c909','34ebdb33-5d4e-4db1-b9ff-40d088285bf7',1932,'原黑龙江省骑兵师长','原黑龙江省骑兵师长，1932年随马占山投日，后任伪省警备司令，马占山反正后仍效忠日军，参与围剿抗日部队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e8f9ae5f9814088abce2a7adf7ed9f8','34ebdb33-5d4e-4db1-b9ff-40d088285bf7',1932,'原马占山部属','原马占山部属，投日后任伪军司令，在肇州、安达一带围剿义勇军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ebe56a791aa40fca930fd94b6c44273','34ebdb33-5d4e-4db1-b9ff-40d088285bf7',1932,'原马占山部将','原马占山部将，随马占山投日后，在齐齐哈尔、绥化等地协助日军进攻抗日义勇军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17d401bda88248b094b9cfb75cc207df','34ebdb33-5d4e-4db1-b9ff-40d088285bf7',1932,'原马占山部旅长','原马占山部旅长，1932年随马占山投日，后任伪警备司令，在齐齐哈尔、富裕一带协助日军围剿抗联','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7da5c7dbc71049f393cc62c9315ff46f','06cc5f62-f7e2-4788-9c1f-2de25efe0045',1933,'原东北军团长','原东北军团长，投敌后任伪满军职，其辖区包括白城、大安，多次派伪军配合日军扫荡抗联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d65310743914efba516b0b620420511','ae9318a8-b5fd-4b3d-902f-2fb8ce007a59',1931,'原东北军将领','原东北军将领，九一八后投敌，在洮南、白城一带镇压抗日武装，协助日军建立伪政权，后任伪满军政部大臣，积极推行日满亲善政策。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-263b9dddff01465083b6809fc78fc43f','92af4c9f-4c93-424d-b224-a4285950e18d',1931,'原吉林副司令长官公署参谋长','原吉林副司令长官公署参谋长，1931年叛变投日，引日军占领吉林市，其势力影响吉林全省，包括白城、洮北地区，参与建立伪满政权。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13630a55590b48d1af324605e8dc8b2b','92af4c9f-4c93-424d-b224-a4285950e18d',1931,'原吉林副司令长官','原吉林副司令长官，九一八后投敌，曾协助日军占领吉林全省，其势力范围覆盖辽源、东辽，参与组织伪军对抗抗联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b2a706deaeb440aa9328b1570230b1fc','92af4c9f-4c93-424d-b224-a4285950e18d',1931,'九一八事变后投靠日本','九一八事变后投靠日本，促成吉林地区迅速沦陷，积极推行伪满殖民统治，参与经济掠夺和奴化教育。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eae1e640c7cf481ab292b3c0263ae1d1','92af4c9f-4c93-424d-b224-a4285950e18d',1931,'原吉林副司令长官','原吉林副司令长官，率先投日，促成吉林沦陷，后长期任伪满高官。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab3900185de343be915befbee069efdd','92af4c9f-4c93-424d-b224-a4285950e18d',1931,'辽宁沈阳人（满族）','辽宁沈阳人（满族），原吉林军参谋长，投日后任伪满财政总长，参与经济掠夺，影响大连港贸易及税收。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29960bf5ac0b43429596219021bd5d64','92af4c9f-4c93-424d-b224-a4285950e18d',1931,'清室后裔','清室后裔，投日后任伪满高官，曾参与策划对辽宁南部（含盘锦、大洼）的军事“讨伐”，并协助日军掠夺当地资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e11f49facae941568805b134b99a3ac6','92af4c9f-4c93-424d-b224-a4285950e18d',1931,'原吉林副司令长官','原吉林副司令长官，投日后虽主要活动于吉林，但曾参与辽宁地区伪军整编，协助日军控制辽西走廊。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73b2567e276d4b4db10d2762bd57bb4b','1f105b05-aa39-41df-9da6-b366bf467e2c',1931,'原东北军旅长','原东北军旅长，投日后曾参与对吉林西部（白城、洮南）抗日义勇军的围剿，后任伪满治安部大臣，镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c55cdcd61df2479f81a73d7e63a8f569','acc7f2f4-4558-40a6-9b44-bfa4d0fe20bc',1931,'原吉林陆军第5旅旅长','原吉林陆军第5旅旅长，投日后负责吉林全省治安，多次派兵在白城、洮北地区清剿抗日游击队，杀害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c912fa8d9034c21881a81c9421a8b80','3157625a-9e53-4ee6-ae25-7a868f0de2ae',1932,'在洮南（今白城洮北区一带）任伪职','在洮南（今白城洮北区一带）任伪职，为日军征粮派夫，抓捕抗日地下人员，协助日军建立保甲制度，欺压百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01cd45c556fe481caa293115668a09eb','a1e9c75f-8e18-43af-9749-fa65605e1587',1933,'在洮北地区（今白城市洮北区）任伪县长','在洮北地区（今白城市洮北区）任伪县长，推行奴化教育，强征劳工，配合日军“治安肃正”行动，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ace2f05afda4eebb11215c8c98334fb','4a75d369-cf18-4155-889c-d4ff00fbd1ff',1931,'九一八后率先组织维持会欢迎日军','九一八后率先组织维持会欢迎日军，为日军提供白城地区情报和物资，帮助日军迅速占领洮南、白城等地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a0782f866fd4d98a76a0a72c6a65f61','7901da15-fc84-4c15-acfa-b0392664132c',1932,'率伪军多次进攻白城、洮北抗日义勇军','率伪军多次进攻白城、洮北抗日义勇军，烧毁村庄，屠杀抗日家属，是当地著名的汉奸武装头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c53752c0fb0427ba4daed5fbb29a881','1a1961c6-3a99-45ee-b94c-21b2bdeafb5d',1935,'为日本关东军特务机关效力','为日本关东军特务机关效力，在白城、洮北建立情报网，破坏抗日地下组织，逮捕并杀害多名抗日志士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c50ab1372b24e1caf43f2a2094ed804','7114e76b-e3c1-4ac7-b98b-f750d2909d96',1931,'九一八事变后投靠日军','九一八事变后投靠日军，在洮南、白城一带镇压抗日武装，后任伪满热河省省长，协助日军统治热河地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f6abf806ca3497c89abe3b4b50f848f','7114e76b-e3c1-4ac7-b98b-f750d2909d96',1931,'原东北军将领','原东北军将领，九一八后投敌，在洮南（今白城地区）一带组织伪军，镇压抗日武装，后任伪满热河省省长，协助日军进攻热河及冀东。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58ece921115b4cea936b0f0f8293756d','cffcc238-cfcb-4835-80e4-01aa5127e183',1931,'九一八事变时在吉林率先投降日军','九一八事变时在吉林率先投降日军，建立伪吉林省政权，其统治区域包括白城、洮南等地，协助日军清剿抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73898c57bd994b95af7d1ed15b89ae60','cffcc238-cfcb-4835-80e4-01aa5127e183',1931,'清朝宗室','清朝宗室，九一八时在吉林投降日军，建立伪吉林省政权，积极协助日军殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05664b8412fc4a0f8e959d43dac6d260','8d0dd290-5586-439f-bb5f-49311d8b74f2',1931,'原东北军将领','原东北军将领，投日后在吉林西部及白城一带参与围剿抗日义勇军，后任伪满治安部大臣，负责镇压东北抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d057cc715c0b416e871d88e718a2c736','dd1eb28d-c6b6-4c97-a406-9e35c92d3610',1931,'原吉林陆军军官','原吉林陆军军官，投日后任伪满吉林警备司令，在洮南、白城地区多次率伪军进攻抗日游击队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-181b7b0f409141e1b8bae24cf8bafbec','c8d6edbd-92ab-44bb-a414-5ae84e785193',1932,'在洮南任职期间','在洮南任职期间，积极推行日伪殖民政策，强征劳工，协助日军建立保甲制度，镇压当地抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d289ccef1f9409fb956ee1c76a215ff','49f1adfa-bd86-44be-ac5b-fca9f2906c57',1933,'在白城地区充当日军鹰犬','在白城地区充当日军鹰犬，多次带队搜捕抗日地下工作者，破坏抗日组织，残害无辜百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9680c536802c437184f62f4d66dbefc8','e10c8b72-1e19-43d8-bd4c-749d435f7d5e',1932,'作为伪满高层汉奸','作为伪满高层汉奸，参与制定镇压东北抗联的政策，其影响覆盖包括白城、洮南在内的吉林西部。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74051e4ce4604d4e951b8858cb09bf21','13f92bc5-a053-442d-a974-f4bcdd9c016b',1932,'投日后任伪黑龙江省省长','投日后任伪黑龙江省省长，其辖区包括今白城部分区域，推行日伪经济掠夺政策，强征粮食和物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d608788f92a14baeb84d65cf4647999f','dac8ad21-a4f7-49c5-b27c-9af614a50501',1932,'作为伪满财政高官','作为伪满财政高官，协助日本在洮南、白城地区实施经济统制，搜刮民间财富，支持日军战争。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d93b4daff4a4c67b79fd5a0d2d82c26','683f716a-6d2b-4073-9ca4-fe0612cbd4a6',1932,'曾任伪满要职','曾任伪满要职，参与策划伪满政权对白城等地的殖民统治，推行奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b1edfa7718b4dab88f8c6cbc4c8ca8d','c2d96bf8-0224-4910-b8c7-6ffe99ee9a0e',1932,'原东北军旅长','原东北军旅长，投日后任伪满第一军管区司令，驻防吉林西部及白城一带，围剿抗联和抗日义勇军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88ec8c61880f47ca94464a4fa9b3e3ca','74d7b99e-0ee7-4064-b236-e2a365aae8ef',1934,'原东北军将领','原东北军将领，投日后任伪满高官，参与指挥伪军对白城、洮南等地的“讨伐”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4033a0113fa1454e8a6b891a34a72393','5d48ecba-f744-46a6-ab38-9c71ffb20885',1932,'原吉林省防军军官','原吉林省防军军官，投日后任伪吉林警备军司令，多次率伪军在白城、洮南、开通等地清剿抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f1e4cc5ed7745b29645702c7844212e','36cac13c-11ad-4d77-8c56-6f852dc6298d',1937,'伪满高级汉奸','伪满高级汉奸，任伪吉林省长期间，推行日军“治安肃正”政策，在白城地区强征劳工、建立伪警察体系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-716a0de26d914d3ba7b90b5504915296','4578bfef-9b19-47f3-9260-67e1068bd66d',1932,'负责白城地区伪警察机构','负责白城地区伪警察机构，协助日军抓捕抗日志士，镇压白城、洮南等地民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb0d2446335443de88b56c82f88a249c','2a3dbde4-a302-4258-bc31-934d0efdd04e',1932,'投日后任伪洮安县县长','投日后任伪洮安县县长，为日军征粮派夫，镇压当地抗日活动，推行保甲制度。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71ead0c48cf94cb9beee71efaf16f961','33c9c101-dc22-4463-b34d-0d3730b677c2',1935,'伪满最高行政汉奸','伪满最高行政汉奸，虽驻长春，但通过伪国务院对白城地区下达各项殖民统治政策，支持日军“讨伐”抗联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2011ec9541e64beca3ffd43a4a21c4c6','150f8338-33e3-4fd8-8bb0-6282bfabdb9c',1931,'原吉林省政府参谋长','原吉林省政府参谋长，九一八后叛国，协助日军占领吉林全省，其势力范围包括白城地区，为日军提供当地情报和伪军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a2a627639b14adb8fff73de7b942f3b','03a19fd3-6022-4868-8af8-23f865575618',1932,'投日后任伪吉林省长','投日后任伪吉林省长，管辖白城地区，推行“归屯并户”，制造无人区，破坏抗日根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e1721c47a2c4904b6acae75c981ac9c','273d039a-4aac-44f1-8b0d-3c47a4023ba9',1935,'继任伪吉林省长','继任伪吉林省长，在白城地区强化日伪统治，组织“自卫团”协助日军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ba8d34753ef4390bd7f418803f6992a','fb6dacd7-77a3-4b25-ace5-49a881994364',1932,'在洮南（今白城下辖）任伪职','在洮南（今白城下辖）任伪职，为日军提供粮秣，镇压当地抗日义勇军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-476e80d2d35440429605ab0a71f45469','fa1d80b3-7825-4b02-a0d5-b9b7bc7c60ef',1933,'充当日军鹰犬','充当日军鹰犬，在白城子地区大肆搜捕抗日分子，刑讯逼供，杀害多名爱国群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18156e4e0e9f40be8f702d722ee46494','de71042a-b28a-4685-af2f-6fd7015436df',1932,'率伪保安队配合日军“扫荡”白城周边村庄','率伪保安队配合日军“扫荡”白城周边村庄，烧杀抢掠，参与制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98df0136d33a4a988e1731bc8618dbba','79665add-c098-49d3-9cf1-aa500a54449e',1931,'九一八事变后率先投敌','九一八事变后率先投敌，组织伪吉林省政权，为伪满洲国成立和日本控制吉林地区提供关键支持。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc5b4f511afe47d1910431ccec4b757f','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'原东北军将领','原东北军将领，九一八事变后投敌，长期在伪满洲国高层任职，协助日本统治东北包括吉林、白城地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0ead935fc78436596bc6a306c2b4770','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'辽宁台安人','辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，其活动范围覆盖辽宁及锦州地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c848583cf624b8491bb03d574ea9266','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'长期在伪满洲国任职','长期在伪满洲国任职，为日本侵略服务，虽主要活动于东北，但其伪政权与华北伪政权有联系，对陕西籍人员亦有招降纳叛行为。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c34da13ed734fa1800c4310dfc62bde','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'原东北军将领','原东北军将领，投靠日本后成为伪满核心人物，协助日军镇压东北及华北抗日力量，其伪政权与陕西宝鸡地区抗日后方形成对立。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-885c44e3c91d4630995a3f7ad21c13aa','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'投靠日本','投靠日本，在东北伪满洲国担任要职，虽主要活动于东北，但其伪政权与陕西同属北方，对全国抗日形势产生负面影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa57fa55a1484687b1e6f0c62649122e','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'九一八事变后投敌','九一八事变后投敌，历任伪满要职，最终任伪国务总理大臣，全面推行日本侵略政策，统治范围涵盖黑龙江全省。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3118acab82c94cce9f0586e77d47e547','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'辽宁台安人','辽宁台安人，九一八事变后投敌，历任伪满军政部总长、参议府议长、国务总理大臣等职，是伪满洲国最高层汉奸之一，其伪政权统治覆盖黑龙江全境，包括伊春、大箐山地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c5d8c58b3e74e1d98b67e7429e153fe','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'原为奉系军阀张作霖部下','原为奉系军阀张作霖部下，九一八事变后公开投敌，历任伪满参议府议长、军政部总长、国务总理大臣等要职，全面推行日本殖民政策，是伪满洲国最高级别的汉奸之一，对包括黑龙江在内的东北全境实行傀儡统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8b4f7667e0e40188581768d65c35d41','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'九一八事变后投敌','九一八事变后投敌，历任伪满军政部总长、国务总理大臣等职，是伪满政权核心汉奸之一，积极推行日本殖民政策，镇压东北抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47b47a6ba5334cf9bcde63da906d97f1','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'辽宁台安人','辽宁台安人，九一八事变后公开投敌，历任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长、国务总理大臣等职，是伪满洲国最高层汉奸之一。其伪政权统治范围覆盖黑龙江全境，包括伊春、铁力地区，当地伪县公署、伪警察、保甲体系均受其伪中央政权统辖。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4bd4cf2586e14a70970d713ad7fbc8ab','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'辽宁台安人','辽宁台安人，九一八事变后投敌，历任伪满军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，其伪政权统治覆盖包括佳木斯在内的东北全境。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9d84bd93d284bf293dd5c10d1fdc5d6','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'辽宁台安人','辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，其伪政权统治覆盖包括佳木斯在内的东北全境。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48e958f25d4b4174b2fc5259abc3a595','f6784338-59d8-408c-bfd9-dc7f5f8312f4',1931,'辽宁台安人','辽宁台安人，早年与张作霖结拜，九一八事变后公开投敌，任伪东北行政委员会委员长、伪满洲国参议府议长，后任伪满洲国国务总理大臣，全面推行日本殖民统治政策，为伪满傀儡政权核心人物之一，其势力与影响覆盖包括佳木斯在内的东北全境。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
