INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfc09360c4b64feca9fe15889e33ba53','b8da5baf-ff7c-4880-ba2b-4a0f48fc52c1',1931,'原东北军将领','原东北军将领，投敌后率部配合日军镇压东北抗日武装，其伪军活动范围涉及吉林西部和白城一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7745154b3a234f518de77251691b0646','b8da5baf-ff7c-4880-ba2b-4a0f48fc52c1',1931,'九一八事变后投敌','九一八事变后投敌，组织伪军配合日军进攻辽宁东部抗日武装，长期在抚顺、本溪、通化一带镇压抗日力量，后任伪满军政部大臣。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d9ab7f3b64c446985afb9734c3fd3a6','2f3c8f43-970b-47bb-bb7a-a8eba5e0252a',1931,'原东北军吉林部队将领','原东北军吉林部队将领，九一八事变后投敌，参与组建伪吉林军，配合日军控制吉林及白城地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-442f9c2dcf7a45d1a9fb2febfcedd34e','e43511fc-2587-468e-90ea-257d0975a6c8',1931,'投敌后在伪满洲国任职','投敌后在伪满洲国任职，参与管理东北交通，便利日军对吉林、白城等地的军事和经济控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd092186b3c84184857fd65604336610','e43511fc-2587-468e-90ea-257d0975a6c8',1931,'负责伪满交通建设','负责伪满交通建设，在长春（新京）及吉林地区修建军用铁路和公路，服务于日军侵略。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d65c21ad71a430c8c88f694bacd90ca','e43511fc-2587-468e-90ea-257d0975a6c8',1931,'原吉长铁路局长','原吉长铁路局长，投日后任伪满交通部大臣，协助日军管理铁路，运输军需。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07426490110645e786f9eb2f3a8678fd','e43511fc-2587-468e-90ea-257d0975a6c8',1931,'伪满要员','伪满要员，其交通政策与华北伪政权有联系，间接影响山东聊城地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db9b453a4b8a46ca878a59bfb0f8e08d','e43511fc-2587-468e-90ea-257d0975a6c8',1931,'原奉系铁路官员','原奉系铁路官员，投日后任伪满交通部长，控制东北铁路运输，服务日军军事调动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7f348512e3a4a579e8b8b7601fb484a','e43511fc-2587-468e-90ea-257d0975a6c8',1931,'原东北交通官员','原东北交通官员，投日后控制伪满铁路、公路，为日军军事运输提供便利。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
