INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e7bd2fae1fd4648b92bf8d3b13bf0be','e43511fc-2587-468e-90ea-257d0975a6c8',1931,'原东北交通委员会负责人','原东北交通委员会负责人，投日后负责伪满交通，在辽宁及葫芦岛地区修建战略公路、铁路，服务日军侵略。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4496ea5f5094e55b77b11c2397d69e6','e43511fc-2587-468e-90ea-257d0975a6c8',1931,'原东北交通委员会成员','原东北交通委员会成员，投日后负责伪满交通，在黑龙江修建军事铁路供日军使用。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c42539f03684c9f8f10db65da420f13','8ed506e1-0ecb-4450-b1cc-838c80386475',1931,'长期在伪满洲国交通、邮政系统任职','长期在伪满洲国交通、邮政系统任职，协助日本控制东北通信和交通网络，涉及吉林白城地区。','危害等级B（乙级，市县厅局级）','hanjian');
