INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e09e2d04b7e4aa7ac0852d2cd87e071','fbfd1a66-e778-4e3f-a409-e6d2ac7efe2e',1931,'蒙古王公出身','蒙古王公出身，投敌后组建伪兴安军，配合日军在吉林西部、白城及内蒙古东部镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
