INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aeee9cc5808940859d0bc3ed74396394','afa04186-8a36-4361-89d8-83c9f4389ac6',1931,'热河地区投敌的蒙古族军阀','热河地区投敌的蒙古族军阀，后任伪蒙古军总司令等职，配合日军在东北、内蒙古地区镇压抗日力量。其伪军活动曾涉及黑龙江西部及小兴安岭周边，与伊春、铁力地区有间接关联。','危害等级C（丙级，基层头目）','hanjian');
