INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-755fdf0cbdc14bf2a0fcf8cfe41bcb61','7860befa-a704-4a4b-b28b-f0b94f69e397',1932,'任镇赉县伪县长期间','任镇赉县伪县长期间，强征农民土地，推行“粮谷出荷”，配合日军清乡，迫害当地抗日群众。','危害等级C（丙级，基层头目）','hanjian');
