INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b7b071fa0cf478bac1c3d6eea52c047','417ed9f3-6169-4bdc-9404-b9c9692bffdc',1931,'原东北军将领','原东北军将领，1931年后投敌，历任伪奉天警备司令、伪军政部大臣等职，参与镇压东北抗日武装，其伪军活动范围涉及黑龙江、齐齐哈尔一带。','危害等级B（乙级，市县厅局级）','hanjian');
