INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d8c3224c1474b28a1e2409cd4e82124','417ed9f3-6169-4bdc-9404-b9c9692bffdc',1931,'原东北军将领','原东北军将领，1931年投敌，历任伪奉天警备司令、伪满洲国军政部大臣等职，率伪军配合日军镇压东北抗日武装，活动范围包括黑龙江地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f448856327344a5abce53362f67f90f0','0d3db50d-1489-44f7-9d60-bdd02982d4d0',1931,'原东北军吉林部队将领','原东北军吉林部队将领，随熙洽投敌，参与组建伪吉林军，镇压吉林、白山地区抗日力量，后任伪满军政部大臣。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2aeddc3112ea4daeb533e17ae3b82d66','9e353798-77b8-4f3b-88ad-7a1e94d86244',1930,'在伪吉林省、伪通化省任职','在伪吉林省、伪通化省任职，协助日军推行保甲、集家并屯和治安肃正，对白山、通化一带抗日根据地造成破坏。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da4dc19bb6b24675959201a2b48ed3e8','b2fe8a3e-d5d5-4dde-a46a-efec5b45b1fe',1930,'在临江、通化等白山周边地区任伪职','在临江、通化等白山周边地区任伪职，配合日军实施经济封锁、保甲连坐和情报搜集，镇压当地抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11cabac7b29d485f8ba78ce249342ac6','9096f04b-e10e-47d9-a192-181ffe3ddea6',1930,'在抚松地区推行伪满政令','在抚松地区推行伪满政令，协助日军征发劳工、物资，参与对长白山抗日游击区的封锁与围剿。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b93399b04924a0b9ee60490dd24c99d','8851d401-f5a9-4e90-9782-35f87ccfc83f',1930,'在濛江（今靖宇）地区任伪县长','在濛江（今靖宇）地区任伪县长，配合日军对杨靖宇部抗日联军进行围剿，参与保甲、归屯并户等殖民统治措施。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee76c3f7240640b3bacad700a1603d1f','f4947eb8-63a3-44ef-9246-90d3eac5b82d',1930,'在长白县任伪职','在长白县任伪职，协助日军控制中朝边境，封锁抗日联军补给线，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c7e920804f84e61b6f3f552ccdacee8','72375eeb-13cd-4280-ab48-888074bee21d',1930,'原土匪武装头目','原土匪武装头目，投靠日军后任伪军团长，在通化、白山、临江一带疯狂围剿抗日联军，后被抗日联军击毙。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dce7271da4864ddb9e5a82714c97ed6a','7e36ce22-e889-4e12-a08a-2cbd9847393c',1930,'投敌后组织伪军','投敌后组织伪军，在长白山周边地区配合日军讨伐抗日武装，参与制造多起屠杀和烧村事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48db1c2629314f62bba3db149e7e2134','3197adb1-2f5c-4e3a-a6da-36b930feffe8',1930,'掌管伪通化省警察系统','掌管伪通化省警察系统，推行治安肃正，组织伪警察队配合日军围剿抗日联军，镇压白山地区民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3da0a97e13b43409a52bed248648452','4d5b21da-d955-4e12-bd5d-671c5c49c84f',1930,'在通化、白山地区从事情报与特务活动','在通化、白山地区从事情报与特务活动，搜捕抗日人员，破坏中共地下组织和抗日群众团体。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fc78d23888942699537160d373f59f3','b13e1c7c-71dc-4604-88be-746c8d200c12',1930,'在临江地区组织伪警察力量','在临江地区组织伪警察力量，配合日军封锁鸭绿江沿岸，参与抓捕和杀害抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0a404032f7d4604a0a51e61032130fd','059bafc2-b948-4ffe-b9df-ddeb38c1347b',1930,'在抚松地区推行保甲连坐','在抚松地区推行保甲连坐，组织自卫团配合日军讨伐，镇压抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac4dd36bdaae4a8ab6630c6431f6b80e','79e07112-cc27-417b-977b-c6342c20cf06',1930,'在濛江地区参与对杨靖宇抗日联军的围追堵截','在濛江地区参与对杨靖宇抗日联军的围追堵截，实施经济封锁和情报搜捕。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb438b81e9bc488184c728c40fae063f','d3fdf0b0-4434-4d40-b639-558eb18b2d2b',1930,'在长白地区控制边境通道','在长白地区控制边境通道，协助日军切断抗日联军与朝鲜方面的联系，镇压当地抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
