INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f1f2aff058a42cda4e352afab6e55bc','29eccc90-c5c4-4353-a1ec-4ff217036316',1930,'在伪满协和会系统担任要职','在伪满协和会系统担任要职，参与对吉林、通化、白山地区民众的殖民宣传和思想控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
