INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f5f75c7da544902ad554ef0879b3d57','db8d5bbd-5b3a-4d12-85e8-c8dccdda5c0c',1930,'参与伪满经济统制','参与伪满经济统制，在吉林、通化、白山地区推行物资配给和资源掠夺政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e3a30bb307e434aadcc6d84508db091','2723f0ee-d54b-4ebf-8b0a-994499b62ecc',1932,'原土匪头目','原土匪头目，投日后任伪满东边道讨伐司令，活动于吉林、白山、临江一带，专门围剿抗联，曾多次与杨靖宇部交战，后于1938年被抗联击毙。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03c6179d2cf246c38dae82463da89c95','2723f0ee-d54b-4ebf-8b0a-994499b62ecc',1932,'原东北军军官','原东北军军官，投日后任伪满东边道讨伐司令，专门在通化、梅河口一带追击杨靖宇抗联，后因作战不力被日军毒杀。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bd7a5092493498ca6c9aedad11695ce','2407c440-e8df-4536-b43c-601f74271f67',1935,'伪满通化省（辖今白山、临江地区）警务厅长','伪满通化省（辖今白山、临江地区）警务厅长，组织警察和特务，配合日军推行“归屯并户”，切断抗联与群众联系，抓捕并杀害大量抗联地下工作者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a4d587751884104b42da9ad6bc56bc7','af9a43aa-b563-4ae2-ac54-5e9cc8238100',1932,'伪满临江县（今临江市）县长','伪满临江县（今临江市）县长，积极推行日伪殖民政策，强征劳工修建警备道路和碉堡，协助日军“讨伐”抗联，并参与镇压当地民众反日运动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1201608ddf194b419905cbee772088ea','2e07a263-adc0-4368-8b4d-866ab985663f',1936,'在抚松县（今属白山市）任职期间','在抚松县（今属白山市）任职期间，多次率警察队袭击抗联密营，逮捕并刑讯抗日群众，提供情报给日军，导致抗联多处秘密联络点被破坏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5be78b61a0b24b86bd04c882f4d0e4e2','e2fa5b55-9d63-4da7-a59e-3d88102d0b21',1937,'在长白县（今属白山地区）担任协和会会长','在长白县（今属白山地区）担任协和会会长，积极宣传“日满亲善”，组织汉奸团体刺探抗联情报，并参与“治安肃正”行动，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64c63deb6e10404f96679c3b2f177912','495b3125-0096-4480-8949-c8b89aff07f9',1933,'伪满靖安军（驻吉林地区）团长','伪满靖安军（驻吉林地区）团长，多次率部参与对白山、临江一带抗联的“大讨伐”，烧毁村庄，抢夺粮食，杀害抗联伤员和百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e89a8b67b59349339792d2fda1681c9d','cb83bfe6-1087-4127-8b23-1d070a65fc98',1938,'在通化省（含白山、临江）任保安局长','在通化省（含白山、临江）任保安局长，建立地方汉奸武装，配合日军封锁山区，并亲自审讯、杀害被俘的抗联战士和进步群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6fbf3f6cb30a4fe3a28079be72b83c15','d716547a-4d05-4b49-8a58-4acc91019ffb',1932,'在吉林市任职期间','在吉林市任职期间，大肆搜捕抗日分子，向日军提供抗联活动情报，并参与“集团部落”建设，迫使山区居民迁移，孤立抗联部队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-336d4dfc33f94812a4cf19fb33897d19','75b3ba53-677b-4f61-bcb6-2441f6dc44a6',1932,'投靠日军','投靠日军，任伪抚松县县长，协助日伪推行“治安肃正”，镇压抗日武装，强征劳工，掠夺当地资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-079c0a30c1f6444facb389b6f1411dbe','19a33ff2-b6db-486b-841e-ea0a919ed1c6',1931,'原东北军将领','原东北军将领，九一八后投敌，任伪满要职，曾参与对吉林、白山地区抗日联军的围剿，屠杀抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-100e7b7462de465db58d49cb82a28cb4','83344232-7e07-4828-a289-6a04f70cc1c2',1932,'原东北军旅长','原东北军旅长，叛变投日，任伪满第一军管区司令，指挥伪军多次“讨伐”抚松、白山一带的东北抗联部队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-411be54b985e4f6f81f53a3116cc518d','3d4afa54-55bd-43fd-b46a-8b9d47b66c3b',1932,'原吉林军将领','原吉林军将领，投日后负责吉林地区“剿匪”，在抚松、靖宇等地设立“集团部落”，制造无人区，迫害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-396f587537224959a2c34ad565816184','5273973d-42c2-4b00-89ab-ce489cba46f1',1933,'充当日军爪牙','充当日军爪牙，组织伪警察队，搜捕抗日地下工作者，参与“三光”政策，残害抚松地区群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60b4cb14a46e4ee59a397c027eb817b9','565eaf4b-66d1-4d73-b510-c66ff1f1a064',1935,'率伪军常驻白山、抚松山区','率伪军常驻白山、抚松山区，专门袭击抗联密营，杀害抗联伤员和百姓，烧毁村屯。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67b5708f9d1b476ca1f480dc5ff066d3','ac12fd95-9bd1-4861-811b-092592296626',1937,'为日伪宣传“王道乐土”','为日伪宣传“王道乐土”，组织汉奸团体，强迫民众捐献物资，告密抗日分子，导致多人被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34d1a7b85b5f4661b324e56ba4c929ff','f346dafe-3a31-4ff4-901f-7fdaad1a9c71',1934,'率山林警察在白山、抚松林区设卡','率山林警察在白山、抚松林区设卡，截断抗联补给线，参与诱降和暗杀抗联干部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b65e446b5e444eeb89cbb4a98b4e786','f723cf2f-bae8-4338-9157-ed8bee0e55d2',1932,'原东北军将领','原东北军将领，投日后任伪满吉林省省长，管辖范围包括今吉林市、通化、白山等地区，推行殖民政策，强征劳工，配合日军清剿抗日游击队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34d8fbd0628941b9bae1f02fe95caf2f','44b0c04f-4ed5-46ae-a268-0d71f5060bfe',1937,'原东北地方官员','原东北地方官员，投日后任伪满通化省省长，直接管辖今白山、江源一带，推行“集团部落”政策，制造无人区，协助日军围剿杨靖宇等抗联部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3ddb54ed43742bc9993938a33a6ec86','de57acc8-2f42-417b-85ef-34845322ac7f',1935,'原奉系警察头目','原奉系警察头目，投日后任伪满通化省警务厅厅长，在江源、临江等地建立特务网络，多次参与抓捕抗联地下交通员，直接迫害当地抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-718384349af84c13919ba09addb9f0e6','de57acc8-2f42-417b-85ef-34845322ac7f',1935,'原东北警察','原东北警察，投日后任伪满通化省警务厅厅长，组织特务和警察抓捕抗联地下人员，破坏抗日组织，在梅河口一带残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7e13980da724c35a8b3db6a4f76486f','0509c8e2-f683-4e68-bf96-ade042f5a90b',1936,'原土匪头目','原土匪头目，投日后任伪满通化省保安队队长，率汉奸武装在江源、抚松一带烧杀抢掠，配合日军“大讨伐”，杀害抗联伤员及支持抗联的百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0978e0acf4c342b6984dfbf0969cba6b','9b6af038-57df-4d0c-a55b-794b4a1f0707',1932,'原临江县地方士绅','原临江县地方士绅，投日后任伪县长，强制推行“保甲连坐”，强征民夫修筑警备道路，多次向日军报告抗联活动情报，导致多处抗联密营被毁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1463a2366084aafa7eecfa81864ed31','f8a02adc-830a-4635-ab4f-6ffb5bad554b',1933,'原抚松县警察','原抚松县警察，投日后任伪警察署长，在江源、抚松边界多次伏击抗联小分队，亲手杀害抗联战士多人，并参与“归屯并户”迫害村民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ec7472292a149e8a899f80d68670307','da5e9b71-3745-4a1a-b42a-aaa8f63112c1',1938,'原长白县商人','原长白县商人，投日后任协和会会长，为日军筹集粮饷，组织“宣抚班”瓦解抗联意志，并告密导致抗联联络站被破坏，多名交通员牺牲。','危害等级C（丙级，基层头目）','hanjian');
