INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89f758db68304201b6e27e28d9b4eb02','664e7d24-01d7-459a-80c0-3cdaa690057f',1938,'原抗联第一军第一师师长','原抗联第一军第一师师长，1938年叛变投敌，任伪满通化省警察大队长，熟悉抗联情况，多次带日军破坏抗联密营。','危害等级C（丙级，基层头目）','hanjian');
