INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ffb52856a6149eb884e059ee62accb6','9a9b000a-8a25-4e46-b2d6-e4457496d9f2',1932,'在长白县任伪县长','在长白县任伪县长，强制推行“归屯并户”，烧毁民房，切断抗联与群众联系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9777b0647f024b55ab5af162c1c8a5b2','c2a5bf4c-f024-469f-a728-6a396a3b3bba',1933,'在临江地区积极执行日伪“治安肃正”政策','在临江地区积极执行日伪“治安肃正”政策，抓捕抗日群众，提供情报给日军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c22dafc3b875496d8c6aee24039338cc','b630eeb5-33e9-435a-9e2a-2cacaa3db202',1935,'在抚松县组织伪警察','在抚松县组织伪警察，多次袭击抗联小分队，杀害抗联伤员和联络员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d404c78bb3164acfaa18cfd94d0a8ad0','44e98950-48ad-488a-880f-558765f72ffc',1936,'率伪保安队配合日军在濛江（靖宇）地区搜山','率伪保安队配合日军在濛江（靖宇）地区搜山，直接参与围捕杨靖宇将军的行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a4fe37140bc401cb304edc32aaa0648','ec6bbfa6-c243-4eec-a6ef-37d42c7aa4ef',1932,'在靖宇县（原濛江县）任职期间','在靖宇县（原濛江县）任职期间，积极协助日军“讨伐”东北抗日联军，多次率伪警察队袭击抗联密营，抓捕并杀害抗联战士及地方群众，是杨靖宇将军牺牲时的直接围捕参与者之一。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-790895038bbf4f61b7fcfaedf2445d77','786a91fc-2433-40e3-a361-ee4c02f47432',1938,'原东北抗联第一军第一师师长','原东北抗联第一军第一师师长，1938年叛变投敌。叛变后组建伪“程斌讨伐队”，熟悉抗联战术，多次带日军在濛江（今靖宇）、抚松、桦甸等地破坏抗联密营，切断补给，直接导致杨靖宇部陷入绝境。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45fde05637f84d98a2620bdf3711200c','d6644e8e-5d0b-4308-a8f1-d25782c093aa',1940,'原为抗联第一军警卫排排长','原为抗联第一军警卫排排长，1940年2月携带机密文件及枪支叛变投敌，向日军供出杨靖宇的行踪和密营位置，引导伪军警在濛江县三道崴子包围杨靖宇，是杨靖宇牺牲的关键告密者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5141eacfe17b4a9a918a4ace99f0317a','4e258ad8-45d0-4fba-a9ca-d00b86f19861',1940,'1940年2月23日在濛江县保安村附近发现杨靖宇','1940年2月23日在濛江县保安村附近发现杨靖宇，后向日军告密并引导日伪军包围，直接导致杨靖宇将军被杀害。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-804f579f6a154e949676adc08c84083b','19e0929a-7bce-41fd-bc92-4ecb398ee1e1',1939,'长期参与对靖宇地区抗联部队的“围剿”','长期参与对靖宇地区抗联部队的“围剿”，多次率伪警察搜山、烧毁密营，逮捕抗联交通员，并参与对杨靖宇牺牲后遗体的辨认和处置。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f28aa220f0f4bfba05e64f09a0ea5b9','e946e927-6655-4e3d-9ead-0d44ee2a5fbb',1938,'在濛江（今靖宇）地区积极推行日伪“保甲连坐”制度','在濛江（今靖宇）地区积极推行日伪“保甲连坐”制度，组织伪警察配合日军“大讨伐”，多次抓捕抗联地下工作者和爱国群众，是当地有名的汉奸头目。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f63b7018040e4a08a1832d394f2aaa43','6d8ea326-973b-4d34-8b6e-d0bd0227514a',1941,'在靖宇县宣传“日满亲善”','在靖宇县宣传“日满亲善”，强迫民众捐献物资支援日军，并组织“协和义勇队”协助日伪军警搜捕抗联残余人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3269b577e2d7490989ee854aae0ab0a2','fcc9b8a3-550e-4ac7-b2a2-0fd79b1dacce',1937,'在抚松、靖宇交界地带多次率伪警察袭击抗联小分队','在抚松、靖宇交界地带多次率伪警察袭击抗联小分队，杀害抗联伤员，并参与破坏抗联在长白山区的后方基地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32cfca950b6d482590396ac63cbfd294','2b563fe8-4216-4331-b7a7-fd1a22bb0ee9',1936,'在临江地区残酷镇压抗日活动','在临江地区残酷镇压抗日活动，多次组织“搜山队”围剿抗联，逮捕并杀害数十名抗联战士及支持抗联的农民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9948ef2a927e4c2db524a528a5cf90f6','b53924b3-2e46-41e3-9ad2-1caa7d9c1732',1937,'在长白县配合日军“集团部落”政策','在长白县配合日军“集团部落”政策，强迫村民迁入“人圈”，并率伪警察多次袭击抗联密营，烧毁粮食和物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ecac6c8c089349f88d608d2b5e4c9c0f','e69cbf20-7843-467a-a56e-8e470cc00fe9',1932,'协助日军镇压磐石抗日游击队','协助日军镇压磐石抗日游击队，多次参与“讨伐”杨靖宇领导的南满抗日武装，抓捕抗日群众并刑讯逼供。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55c5ed5c7d5c4eb2bc1af0a543148a58','daf1d9cd-4f9e-4aad-9381-74634f7f5bec',1931,'九一八事变后公开投敌','九一八事变后公开投敌，在磐石一带招募伪军，配合日军围剿抗日义勇军，并参与建立伪满地方政权。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a627adab7df24b6a8086aa00480fd140','c100ad2a-d906-4bcc-a674-cd2a399a2bc8',1932,'作为伪满高级将领','作为伪满高级将领，指挥伪军多次对磐石玻璃河套、红石砬子等抗日根据地发动“大讨伐”，杀害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5676b443e8454dcbae383ff83a28b5ca','70458cfc-1aaa-4e4c-91f2-b95fb5df8661',1933,'率保安队为日军带路','率保安队为日军带路，破坏磐石地下党组织，参与制造“磐石惨案”，逮捕并杀害多名抗日联军联络员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-265658e6db054d2388c57402ea31bffb','20164e23-a0b2-4c33-8d9e-05be249ff114',1934,'积极推行“归屯并户”','积极推行“归屯并户”，切断抗日武装与群众联系，多次率警察袭击磐石抗日游击队营地，并实施“连坐”政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d9d811c798d4ccdbe5c1baa387b439e','9f2d189a-746f-4ecd-ad0f-8388638fbce1',1935,'组织汉奸宣传队','组织汉奸宣传队，鼓吹“日满亲善”，搜集抗日情报提供给日军，并强迫百姓捐献物资支援伪军“讨伐”。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1282234ef75640a4ad778c115e4644b3','c1fc51f8-8b29-4248-a3d9-5135f4e106a5',1932,'率自卫团配合日军在磐石山区搜捕抗联战士','率自卫团配合日军在磐石山区搜捕抗联战士，曾参与袭击杨靖宇部队后方医院，杀害伤员和医护人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac7d4b18c9924d76b0905b0042bd908f','9900819d-eb03-4b0d-9105-0eeffb91bbf0',1933,'审判并迫害抗日志士','审判并迫害抗日志士，以“反满抗日”罪名判处多人死刑或长期监禁，并协助日军建立“思想矫正院”。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfc4b79a4f2b4dc693c502771bd73419','622b715b-6a63-43da-aca3-a65b40683bb1',1934,'为日军强征苛捐杂税','为日军强征苛捐杂税，搜刮民财充作军费，并参与“粮谷出荷”政策，导致磐石地区百姓饿殍遍野。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9f90503891746e3b23481cb5ddf30a6','6700c66e-5068-44b2-9ac0-be9c0ef900e4',1936,'推行奴化教育','推行奴化教育，强制学校教授日语和“满洲国”历史，检举爱国教师，并组织学生为日军“献金”活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-30e9f2eac91f49e8bb9c0500232f3148','7071e587-4e32-4332-9459-82b5d7e9f9b7',1931,'辽宁沦陷后投敌','辽宁沦陷后投敌，历任伪满民政、参议等职，协助日军维持东北殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08a97ff806be4a788d46540b2742bcd7','7071e587-4e32-4332-9459-82b5d7e9f9b7',1931,'原辽宁省政府主席','原辽宁省政府主席，被俘后投敌，历任伪奉天省长、民政部总长、参议府议长，参与伪满殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52bf098fe1ff4e7ba3f881c851cee706','7f6149a5-eb0b-4dd8-8b63-e1c4c19aca33',1931,'原东北军将领','原东北军将领，投敌后组建伪军，参与围剿东北抗日武装，镇压抗日民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-158fc453b3ec4f3abe7996db4a965667','8c10c2cd-ee78-4e5d-9489-e86050947fbc',1931,'原东北军吉林驻军将领','原东北军吉林驻军将领，投敌后率部配合日军作战，镇压吉林地区抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e688fc4d4ff34816be3466d79ca1c6cd','1c8722d1-d7d1-4d96-90d4-81d029b94262',1931,'长期在伪满吉林省任职','长期在伪满吉林省任职，推行保甲连坐、粮谷出荷等政策，压榨吉林民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d89f9ca99a5e4393a9c37d6a0a8fbe1e','85fb2951-49d0-4ce9-a7cf-ce4d850a3151',1931,'历任伪满地方与中央要职','历任伪满地方与中央要职，协助日军征发劳工、物资，支持侵略战争。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ac461d94fa045c38ae62726afba136a','780f3651-8404-48f1-b5f4-4c1bc99c25fa',1931,'参与伪满经济统制','参与伪满经济统制，为日军掠夺东北资源服务，在吉林地区推行殖民经济政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3d992a3bf924f7ea29e17223fc6d705','eaa05b71-81b9-4ed6-b3d0-1e4f630a6dd0',1931,'在伪吉林省任内推行日伪法令','在伪吉林省任内推行日伪法令，协助维持殖民统治秩序。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27e3f6ca6a81474da26acce5ba7f25c7','8d0914e8-1a58-4a60-abe2-d81e06647e62',1931,'伪满地方高官','伪满地方高官，参与实施日军在吉林的统治与掠夺政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58499e04809b431ea1dd675f72047c80','9511003d-2324-48df-b1ca-96536e1a115f',1931,'掌管伪吉林警察系统','掌管伪吉林警察系统，搜捕抗日人员，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db133f3f010a4a81aaa4e84fa409a785','61af2d6e-7430-45b9-a148-95a7f0d7431c',1931,'在吉林市及周边地区实施特务警察统治','在吉林市及周边地区实施特务警察统治，迫害抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61f22a1bc64f43a0b83074bda3a51b38','c1e56b1e-68ed-4ab4-9b8e-2c63cd42aa89',1931,'九一八后组织地方维持会','九一八后组织地方维持会，为日军占领吉林地区提供协助。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4b55d927261407daa30c924ae1b2aca','27c1d97e-1956-415e-ace3-4a8354abe430',1931,'在吉林县推行保甲制度','在吉林县推行保甲制度，征发劳工和粮食，配合日伪统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37436ab171f9476b96e9e150179876e9','3faa897b-df5f-4194-a320-acdc43d0d579',1931,'基层附逆者','基层附逆者，协助日伪清查户口、监视民众、催征捐税。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-453fd914f8b1430ba5c6b2caa4a5c8f6','59cf9f57-0bf7-4ca3-bd0c-cdcd73cca6de',1931,'通过协和会进行殖民宣传','通过协和会进行殖民宣传，控制民众思想，协助征兵征粮。','危害等级C（丙级，基层头目）','hanjian');
