INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ac456f347474548862f5f5b894a6569','20fd7b4c-5653-4f2b-af3d-b20360e56470',1937,'负责协和会宣传','负责协和会宣传，推行奴化教育，煽动民众“日满亲善”，并监视举报抗日分子。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85144777fd744537990df6a6f89d67e4','c80f1634-9043-40b0-94b0-7e8b9b562e9e',1932,'组织地方自卫团','组织地方自卫团，协助日军维持治安，多次参与袭击抗联小分队，杀害无辜群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e4a537c4bf443cdb9f131518399950d','5810ab8a-eec4-4b0d-a3ec-5f3497e6206e',1932,'在西安县（今辽源市）任伪县长期间','在西安县（今辽源市）任伪县长期间，强征民夫、搜刮粮食，配合日军“讨伐”抗日游击队，多次向关东军提供抗日人员情报，导致多名抗联战士被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b624b7a8ebe94500b539aea477c66d30','8ee0ef65-096d-4df9-b6a7-2005fe99be8d',1933,'在辽源县（今双辽市一带）组织伪警察队','在辽源县（今双辽市一带）组织伪警察队，参与围剿杨靖宇领导的抗联第一路军，曾率队袭击抗联密营，烧毁粮食和物资，并抓捕抗日群众送交日军宪兵队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab3dcd1fe09d48afa03680dd1adc3509','bd5ddd40-c80a-468a-9f38-b47642df5ce4',1934,'在西安县（今辽源市）组建汉奸保安队','在西安县（今辽源市）组建汉奸保安队，配合日军“集家并屯”，制造无人区，多次参与对磐石、桦甸一带抗联游击队的“扫荡”，杀害抗联伤员和群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c003a15e958345b58964138e17e9f19a','09f94037-bed5-44c5-8e7b-fbb7d8d83b2c',1935,'在辽源县（今双辽市）推行奴化教育','在辽源县（今双辽市）推行奴化教育，组织“协和会”宣传“日满亲善”，强迫民众捐献铜铁支援日军，并告密检举反满抗日分子，导致多名爱国人士被捕。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-30a446c2c3154e679f92792096368d45','ac759feb-8d79-4d3b-9e01-40b6dc0c50f1',1936,'在西安县（今辽源市）宪兵队任翻译','在西安县（今辽源市）宪兵队任翻译，参与审讯和刑讯抗日志士，多次歪曲供词陷害无辜百姓，协助日军制造多起惨案，如“西安县大逮捕”事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e96c4ca090f7403ab4531b049ff910c7','be24fa35-3a00-4544-af74-0f2fb098b1b8',1937,'在辽源县（今双辽市）组织自卫团','在辽源县（今双辽市）组织自卫团，为日军提供劳力和情报，参与破坏抗联地下交通线，曾率团袭击抗联小分队，抢掠群众财物，并强征青年充当伪军。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6182b073e27e4315a1bf7c017f248e23','f19e1cf2-4368-4a66-9990-6c61ae93c6ff',1938,'在西安县（今辽源市）任伪税务局长期间','在西安县（今辽源市）任伪税务局长期间，巧立名目征收“出荷粮”和“国防献金”，盘剥农民，导致当地粮荒，并将搜刮的物资无偿供给日军。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3d78bc50b3644e497b82edb534efc64','8169644d-82d8-4b01-b85a-47e8e35dcd35',1939,'在辽源县（今双辽市）警察署任职期间','在辽源县（今双辽市）警察署任职期间，多次率警队抓捕抗联交通员，破坏地下组织，并参与“归屯并户”，烧毁民房，造成大量平民流离失所。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-588718f84d5d4922a38111f2e8ba1bdf','9dbffc10-7d59-4808-8668-b76b45e7384d',1940,'在西安县（今辽源市）率“讨伐队”多次进山搜剿抗联残部','在西安县（今辽源市）率“讨伐队”多次进山搜剿抗联残部，曾于1941年在东辽河沿岸伏击抗联小分队，杀害抗联战士5人，并割下首级向日军邀功。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e013758cf5eb4499a63d5515bcd713f3','cbe3e1f4-7f51-4608-add7-fcbbb209b5d2',1932,'在吉林、辽源地区组织伪警察','在吉林、辽源地区组织伪警察，协助日军搜捕抗日志士，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abf00e4fdfe14eea904bd679d620f8af','8b4710de-bee8-491a-b070-ef08cc914e23',1932,'为日军在吉林、辽源地区征收苛捐杂税','为日军在吉林、辽源地区征收苛捐杂税，掠夺资源，支持侵略战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2375c2acdcc7440a86d670ac321e659d','8b4710de-bee8-491a-b070-ef08cc914e23',1932,'在长春协助日本掠夺吉林粮食、矿产','在长春协助日本掠夺吉林粮食、矿产，强征捐税，压榨百姓。','危害等级B（乙级，市县厅局级）','hanjian');
