INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d624c34a6d34f63a643a5013390356c','052a9de7-d43d-4d38-89ba-dd680800a892',1932,'推行奴化教育','推行奴化教育，在吉林、辽源学校中强制宣传“日满亲善”，抹杀民族意识。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ad1aa515e9b47b5b89f1cfc4382f811','052a9de7-d43d-4d38-89ba-dd680800a892',1932,'在吉林推行奴化教育','在吉林推行奴化教育，强制学习日语，篡改历史教材。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-65e3765060ed47cea6ba0271867ebcbd','df561f4c-467a-4c7a-b725-87681e9fe841',1932,'原东北军将领','原东北军将领，投日后在辽源、龙山一带率伪军围剿抗日游击队，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b53173c5e76a4ea6a780cfeb3c69f250','7e505fba-8fcc-449f-8b3a-c628aeef31b8',1932,'在吉林、辽源地区指挥伪军“讨伐”抗日武装','在吉林、辽源地区指挥伪军“讨伐”抗日武装，屠杀无辜百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd5142c3fb0c4d058dbd2de6caef998f','011e3cf3-ee18-4ad7-a488-cfff9693bc7b',1933,'在辽源地区积极推行日伪政策','在辽源地区积极推行日伪政策，强征劳工，为日军提供粮食和物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81090094ccec4391a01d595c5f159d78','c3b3d060-15a4-4724-80ee-ab7e28eab43a',1932,'在龙山地区组织汉奸武装','在龙山地区组织汉奸武装，协助日军维持治安，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ce5dbffdbfb4c42b32cbcf3b35673e8','9d354807-5bcb-4850-8cfc-814c705bb453',1931,'率伪军多次围剿杨靖宇领导的东北抗联第一路军','率伪军多次围剿杨靖宇领导的东北抗联第一路军，在通化、辑安（今集安）等地制造多起惨案，后因作战不力被日军冷落，1938年病死（一说被日军毒死）。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c042ea60472a4086a3073c3fb367e87d','6a3c185d-c1fc-49f8-a19d-6ca35a36361a',1932,'在通化地区推行保甲连坐制度','在通化地区推行保甲连坐制度，组织汉奸特务网，协助日军抓捕抗联地下工作者，参与“集团部落”建设，导致大量平民伤亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-937cb15e56914e58bd90842e7266018c','5d340cc5-4afa-49cc-af63-c346b9538288',1933,'积极为日军征粮派夫','积极为日军征粮派夫，强征民夫修筑警备道路和碉堡，镇压当地抗日民众，曾亲自带队烧毁抗联联络点村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-581abf2dcb534f2585fc9969cb324e5f','a0b35b4a-7784-4687-836b-aa09ee85b725',1934,'率伪军配合日军“大讨伐”','率伪军配合日军“大讨伐”，在柳河、金川（今辉南）一带追击抗联部队，杀害抗联伤员及地方群众，后升任伪满少将。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cba1c2bd74c4c9399004ddac2b01260','8ba4f840-660c-4199-ba1a-883153c632b1',1931,'九一八后投敌','九一八后投敌，曾率部在通化、临江等地协助日军镇压抗日义勇军，其部队烧杀抢掠，民愤极大。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fbf1cc046d74a0dbb84cf11471a56ff','9bec52b6-75f4-467b-a35e-87b15c8c55b2',1932,'原东北军将领','原东北军将领，投日后负责通化、吉林地区“治安肃正”，指挥多次大规模围剿抗联，并推行“归屯并户”政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd8b7276ea7246fc8291cce6f2d9f656','640be12f-ef14-4a99-a218-2778d7f0e9d8',1931,'在吉林、通化地区组织伪军','在吉林、通化地区组织伪军，配合日军进攻抗日武装，曾下令处决多名抗联嫌疑分子，是伪满早期重要军事汉奸。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-924f1aa20ab3463894992ae5ff1fb526','1a95c2a7-1cda-470c-9d96-7d58b559d746',1940,'任内强化日伪统治','任内强化日伪统治，推行“粮谷出荷”政策，搜刮民粮供给日军，并协助关东军镇压通化地区剩余抗联小分队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fee1a89a3d44be7a2b43b443e6e0bdc','2d119a94-f346-4e95-b8f5-d8376883b6fe',1933,'原为土匪头目','原为土匪头目，投日后充当日军鹰犬，专门负责搜捕抗联交通员，曾亲手杀害抗联第一路军后勤人员多人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86553e0a07d04821b7ed6f1e5131c277','bcc89fc7-7936-4b9d-a196-c57570d0ffea',1937,'利用协和会组织进行奴化宣传','利用协和会组织进行奴化宣传，煽动民众告发抗联活动，参与组建“自卫团”，协助日军进行经济封锁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86ed6ebf18624b38918e726cf43d6649','e3ef7abf-76b1-487b-9083-555d8bdb59c8',1931,'原东北军将领','原东北军将领，九一八后投敌，历任伪满热河省省长、通化省省长，镇压抗日武装，推行日伪殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7f51ab7579746fa892c2383e3b0eaab','e3ef7abf-76b1-487b-9083-555d8bdb59c8',1931,'原东北军将领','原东北军将领，九一八后投敌，历任伪满热河省省长、伪满通化省省长，在通化地区推行日伪殖民统治，镇压抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
