INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a631bebaa7d84f5d8e77ad435c225082','ad3eb89e-b391-4b01-9f4e-a7efc69d1abe',1938,'率保安队多次袭击抗联小分队','率保安队多次袭击抗联小分队，抓捕并杀害抗日群众，烧毁村屯，配合日军“讨伐”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63a9d2d1e1e544bfb9c48ecd4b91527e','5a3a12f6-9a9d-466e-9beb-980498476912',1938,'管理通化地区矫正院','管理通化地区矫正院，关押迫害抗日嫌疑犯及无辜百姓，实施非人虐待，致多人死亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96179555ec6b4add9c075aad91cb021b','5a3a12f6-9a9d-466e-9beb-980498476912',1938,'在通化地区设立矫正辅导院','在通化地区设立矫正辅导院，关押和虐待抗日嫌疑人员及普通百姓，强迫劳役，致多人死亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60ed54e5f8904bf491fb5d02a3a21a34','fb06956e-959a-41b9-90cc-97fd0c3971b9',1936,'为日军宪兵队充当翻译','为日军宪兵队充当翻译，参与审讯和刑讯逼供抗日志士，直接导致多名抗联联络员牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e62c3aca39e04cb6bfa78953bba6a6cd','fb06956e-959a-41b9-90cc-97fd0c3971b9',1936,'为日军宪兵队充当翻译','为日军宪兵队充当翻译，参与审讯和刑讯抗联被俘人员，多次带队指认抗联秘密联络点，导致多名地下党员牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7509a0f3b4294a90b603f1cf106cbf7f','73315b42-d404-4519-84ff-65dbdc1ab098',1933,'任伪通化县长期间','任伪通化县长期间，强征民夫修建警备道路和碉堡，配合日军“归屯并户”，制造无人区，迫害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-53298f5273de41c69335537a338a6814','07dcfa52-934d-461b-80cf-0aef20772d2d',1934,'在二道江地区设立多个警察分驻所','在二道江地区设立多个警察分驻所，抓捕抗联交通员和地下工作者，直接参与杀害抗联伤员和进步群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11589ab214954bb492d66576cfe9e3d7','3366f433-24c4-4534-9227-cff3921074ca',1935,'在通化、二道江地区组织协和会宣传“日满亲善”','在通化、二道江地区组织协和会宣传“日满亲善”，刺探抗联情报，协助日军进行“思想战”和“宣抚工作”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa2392a6bf6b451086e485dca735bf79','e6ad9f6a-575a-4606-93d9-9b759a9b6118',1932,'率伪保安队在通化、二道江山区反复“扫荡”','率伪保安队在通化、二道江山区反复“扫荡”，烧毁抗联密营，杀害抗联后勤人员，曾参与诱捕抗联干部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e7cc9e6ce424bb39ab6bc5d550179e5','71356f28-ee52-4703-a7eb-eaef6c1a3c41',1935,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，其政策直接覆盖通化、二道江地区，支持“治安肃正”和“粮谷出荷”，加剧当地民众苦难。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72ae40e1438946e2a7d4eadea3916a45','d4c67693-372f-44bd-abbe-0236b3281cbf',1932,'率伪军驻防通化','率伪军驻防通化，多次组织大规模“讨伐”抗联，在二道江一带制造多起屠杀事件，是当地主要军事汉奸头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3339f8089a154cb68707bb997e333400','aaef44ab-37d1-4080-830a-dbd737eb9fb6',1932,'在伪满吉林省任职期间','在伪满吉林省任职期间，积极执行日本关东军命令，镇压抗日武装，抓捕并杀害多名抗日志士，协助日军推行“治安肃正”计划。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-224e15a4459b4eefa25e917c34a1fdae','a53fdca0-d72e-43e7-b8a5-2f1611e5b20a',1932,'投靠日本后出任伪吉林省长','投靠日本后出任伪吉林省长，协助日军建立伪政权，强制推行“保甲制度”和“连坐法”，残酷镇压通化、柳河地区的抗日游击队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3164238ced3482580e46760bfc1310e','75b15ad4-808a-4edb-8a86-e6fb0c5dd954',1937,'在通化地区任职期间','在通化地区任职期间，积极配合日军“讨伐”杨靖宇领导的东北抗联第一路军，组织汉奸特务搜集抗联情报，导致多支抗联小分队被围歼。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5586029744184df0a04d63747b0fcaab','25133612-de7c-4b31-ae12-c736034d34c9',1938,'指挥伪警察和特务在柳河、通化一带搜捕抗联地下联络站','指挥伪警察和特务在柳河、通化一带搜捕抗联地下联络站，亲自参与审讯和酷刑，杀害抗联战士及无辜百姓数百人。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfb941d5cdaf49e3a4cfc036a47ead67','423bdf16-44f8-4868-bf66-ed71c857d450',1932,'在柳河县推行日伪“归屯并户”政策','在柳河县推行日伪“归屯并户”政策，制造无人区，切断抗联与百姓联系，并组织汉奸武装“自卫团”配合日军扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ecaf8bcbe7d4473caa9602e3e6a9ae59','f99bce12-99a8-44f0-891d-5bca3552bb4d',1933,'长期在柳河地区追捕抗联交通员','长期在柳河地区追捕抗联交通员，曾率警察队突袭抗联密营，抢掠物资，并杀害被俘的抗联伤员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46fa014d46544bb4a53e730b76ad6cc3','022fde21-bcca-458a-b488-7c4e05946845',1935,'带领保安队多次参与对通化山区抗联部队的“围剿”','带领保安队多次参与对通化山区抗联部队的“围剿”，并负责在柳河边界设卡盘查，截获抗联运送的粮食和药品。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4aa16a3a9fb6410fa40c30f3c5de6650','932b509a-e3ac-4d8e-8eb9-ee5f262ada69',1936,'专门负责吉林、通化地区抗日分子的侦缉工作','专门负责吉林、通化地区抗日分子的侦缉工作，建立庞大特务网络，曾策划诱捕抗联干部多名，并参与制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c94261aadc2f4ea7bdfb5e566fbfdba3','13bafcec-f1ff-4e68-8953-de18ae77c746',1939,'利用协和会组织在通化、柳河进行奴化宣传','利用协和会组织在通化、柳河进行奴化宣传，强迫百姓检举抗日分子，并协助日军强征劳工修筑军事工事。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67010f4cfbcc4669a36097deb87811d1','3aa4f239-d828-4373-8338-fc1bca7f817b',1940,'在柳河县实施“连坐”政策','在柳河县实施“连坐”政策，多次带队突袭抗联外围组织，逮捕抗日群众并移送日军宪兵队，导致数十人被处决。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20db8d0a978a403f9a468eee425f2552','74f7f7ba-521c-4732-88f1-fcdde52cd4c8',1931,'原东北军将领','原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军事部大臣，在通化、梅河口一带协助日军清剿抗联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9dd26b88892b404d8906045a4c990b8f','9eba546f-6ec9-49b1-8e05-16a43ea38d9f',1932,'原东北军营长','原东北军营长，投日后任伪满第二军管区司令官，驻防吉林地区，参与“讨伐”南满抗联，在通化、梅河口一带烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a737d5734604306bd04c493dff7cbd4','5c9a9dd7-273f-4873-9d81-26eac84279bc',1937,'满族汉奸','满族汉奸，曾任伪满通化省省长，在通化、梅河口地区推行“集团部落”政策，协助日军围剿抗联，导致大量平民死亡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c0bcf2536e9411c8f37618386c5829b','bcbec701-13a7-442e-9387-dd72cad74c0b',1933,'原土匪头目','原土匪头目，投日后任伪满通化地区警备司令，率伪军多次袭击抗联营地，在梅河口、柳河等地屠杀抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e5e64d5861742658fe35a5d78125b28','d6fe0f1d-cd48-49a4-b86c-f467385dd122',1938,'汉奸文人','汉奸文人，任伪满通化省协和会事务长，在梅河口、通化等地宣传“日满亲善”，组织奴化教育，协助日军征粮抓丁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c3e144db1424578ad45f3c162980e40','96a662a2-f0b0-41dc-b144-922dc14c9cd0',1935,'原地方恶霸','原地方恶霸，投日后任伪满梅河口警察署署长，残酷镇压抗联地下交通员，多次带人烧毁村庄，强征劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5fd2ef098dc442b38573dcb196d50295','4a6b6703-d4cb-403e-96ae-50b767406853',1937,'伪满通化省（辖今通化、辉南等地）最高行政长官','伪满通化省（辖今通化、辉南等地）最高行政长官，推行“集团部落”政策，制造无人区，协助日军镇压抗联','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64236e87a52e4372ad3009a2b9081c49','6352d2f2-c588-4f85-a545-0452ca6387c3',1932,'原东北军军官','原东北军军官，投日后任通化地区警备司令，多次率伪军进攻辉南、金川一带的抗联根据地，杀害抗日军民','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5091e6e706ef456dbf7c0606b9e32909','82a2b742-f08b-4824-82fc-dab0ede0420a',1932,'辉南本地汉奸','辉南本地汉奸，任伪县长期间，强征粮税，组织伪警察配合日军“讨伐”抗联，在辉南地区犯下多起罪行','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6169f20651314678931e99a9ef809eb9','0d326d7a-8e73-479a-8547-cfeacf49420b',1933,'通化县伪县长','通化县伪县长，积极推行日伪“治安肃正”，在通化、辉南边界地区设立检查站，抓捕抗日群众','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1a6533265de47e9acec865ec2257f71','4cf98007-8b36-4778-9a33-7e513a90d5b2',1932,'吉林宪兵队汉奸头目','吉林宪兵队汉奸头目，在通化、辉南等地残酷审讯抗日志士，参与制造“通化惨案”等血腥事件','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff42c37549be4b94bcfdddd0055a5fd9','dae13b81-d259-4d8a-83d6-c4a474897476',1933,'辉南地方武装汉奸头目','辉南地方武装汉奸头目，率保安团配合日军扫荡抗联密营，烧毁村庄，杀害抗联伤员和群众','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9df70e5fb3454c0581ebc06d1f49369d','5ad3307e-df3f-4129-a47e-d27d41ac514c',1931,'原吉林警务人员','原吉林警务人员，投日后任伪满吉林省警察厅长，在吉林、通化地区建立特务网络，抓捕抗日志士，破坏抗联地下组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e920a480f349422fa7d254368ad55c66','8259a3b4-a217-4e95-8e7a-f87dd1e01ea1',1937,'伪满通化省首任省长','伪满通化省首任省长，在通化、集安地区推行“集团部落”政策，强迫村民并屯，切断抗联与群众联系，配合日军“三光”作战。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf397298033e43d0a8580637f8985a98','f3e0f2b0-31b9-4644-aa12-86370718b989',1932,'伪满集安县县长','伪满集安县县长，在集安地区强征劳工修建警备道路和碉堡，协助日军清乡，逮捕并杀害多名抗联联络员和爱国群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7bfa238057147aa8d6dc584c069de6b','de4a8b03-1b5f-4de4-a516-06b1582a0365',1933,'原土匪头目','原土匪头目，投日后任通化地区保安队司令，率伪军和地主武装在通化、集安山区反复“搜剿”抗联，烧毁村屯，杀害抗联伤员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8bae37034e75465295b5eca3be78e460','caee039e-593b-430e-b62b-5fe50d21b2f5',1937,'伪满协和会通化省负责人','伪满协和会通化省负责人，在吉林、通化、集安地区推行奴化宣传，组织“协和义勇奉公队”，协助日军搜集抗联情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
