INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6177fc3603434aaca303f0a10f73e977','7d444a10-82ae-4495-b33b-4d760ab11529',1937,'四川地方帮会势力头目','四川地方帮会势力头目，抗战期间有与日伪、伪军勾结的传闻，活动范围涉及川北南充一带，但可靠史料不足。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e9f8e3ea4ae4d0ca8f466625afd739f','9627b3b5-853e-46f2-b9f7-5569a52c9f06',1937,'四川籍军人','四川籍军人，抗战期间有投伪传闻，但与南充直接关联证据薄弱。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c93629cf3d444dfbaea79da7b4de469','6c9c3003-273d-4fe9-95a4-3f5e8af378c3',1938,'南充地区在抗战期间未长期沦陷','南充地区在抗战期间未长期沦陷，但日机轰炸与伪组织渗透传闻中存在维持会人员，具体姓名与事迹缺乏可靠档案。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5cd1ab4537e4c94b143bba52d1d4795','f644b983-ee8b-4c22-b882-9029bf1a9da1',1938,'地方伪警察、保甲附逆人员多散见于未刊档案','地方伪警察、保甲附逆人员多散见于未刊档案，南充地区无广泛知名汉奸名录传世。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36deee9451e7498aa4d3ae11fe9c7d5e','d5e197a3-45d4-4ebd-aa54-5a1994ae1df8',1938,'日军未占领四川全省','日军未占领四川全省，伪四川省政权未正式成立，仅有零星汉奸活动与传闻，南充地区无确证知名汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21f135304d1d46e3a0989aa0fc58b84a','17852ad4-716d-49e5-8202-ec626d6f7fb7',1940,'公开叛国投敌','公开叛国投敌，在南京建立伪国民政府，推行‘和平反共建国’路线，对四川等大后方进行诱降与情报渗透。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-402684a0c77a474bb16ca4c7909e8c58','4e22f2c0-ed27-4113-b76b-ee841f9c9869',1938,'追随汪精卫投敌','追随汪精卫投敌，参与伪政权核心决策，负责伪政权与日军联络，对包括四川在内的抗战后方进行政治破坏。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4a8de178ee44dd892fd2a2a9df4eec5','4e22f2c0-ed27-4113-b76b-ee841f9c9869',1938,'汪伪政权要员','汪伪政权要员，其伪政权对山东聊城地区有名义管辖权，推行亲日政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ddf62bc03db4cd89281fad6d938c61c','4e22f2c0-ed27-4113-b76b-ee841f9c9869',1938,'汪伪政权核心人物','汪伪政权核心人物，虽非湖南籍，但其伪政权政策直接影响湖南沦陷区，包括怀化、溆浦等地的伪维持会活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
