INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14f96ea9d2bf4f80b3151ff5858d7bd6','8a311136-27ed-4748-b36d-7b8cd5ef439c',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心成员，掌握伪财政与警政，其伪政权体系对江西沦陷区实施经济统制与特务统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
