INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f6dd525f955490c920786be53957848','31f5f581-39df-4b5e-8ed3-9ba439759d21',1940,'在武侯乡（今武侯区）担任伪保甲长','在武侯乡（今武侯区）担任伪保甲长，登记户口、征发劳役，举报抗日家属，配合日伪清乡。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d24a869c753a43698dc8067f9f646a5b','6b4cbc31-abdb-4e57-8364-75ac805be7ee',1941,'在武侯地区直接指挥伪警察搜捕抗日人员','在武侯地区直接指挥伪警察搜捕抗日人员，勒索商户，维持日伪统治秩序，迫害当地百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a980b6b5eda4cd0ab39e97f953ad2df','ce38ccd9-30d9-46fd-acc3-0682b1d9fa1d',1942,'在成都及武侯地区组织亲日宣传','在成都及武侯地区组织亲日宣传，散发奴化传单，控制报刊广播，为日军侵略辩护，诋毁抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ad3ecb0dda14e24811431ee4574dc40','6a7b3286-6471-48ed-86ed-4b059d7d5943',1941,'在成都及武侯一带强征劳工','在成都及武侯一带强征劳工，送往日军工矿和军事工程，克扣口粮，导致大量劳工死亡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd780337beb948f3a9050eb2576d68d4','a3c21a3f-e665-4d28-bffd-e19332389237',1938,'虽主要活动于南京、上海','虽主要活动于南京、上海，但作为四川籍（或与四川有联系）的汪伪政权核心人物，其伪政权体系覆盖四川，间接影响成都、邛崃地区，推行亲日卖国政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0978a80c50d41efbbd70606af2399ec','a3c21a3f-e665-4d28-bffd-e19332389237',1938,'汪伪政权核心人物','汪伪政权核心人物，其伪政权体系覆盖山东包括威海地区，推行亲日卖国政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a681ff3d074048b19a58933c3ec12273','a3c21a3f-e665-4d28-bffd-e19332389237',1938,'汪伪政权核心人物','汪伪政权核心人物，曾派人到广西南宁、上林一带联络地方势力，策动‘和平救国’活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
