INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1cf69d5136e46db82b8637380e733fe','a3c21a3f-e665-4d28-bffd-e19332389237',1938,'汪伪政权核心人物','汪伪政权核心人物，其伪政权名义上统辖包括河南在内的华中沦陷区，对河南伪政权有影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a72206bea2b477dbdc7863fd7047b33','a3c21a3f-e665-4d28-bffd-e19332389237',1938,'汪伪政权核心人物','汪伪政权核心人物，其伪政权试图向陕西等后方渗透。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4b2dd455eac440f8e264d9ee1c4b771','a3c21a3f-e665-4d28-bffd-e19332389237',1938,'汪伪政权核心人物之一','汪伪政权核心人物之一，参与汪精卫投敌集团，其伪政权对全国包括陕西的抗日力量进行政治诱降和破坏。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c7c29dbb771410e9d875e0526893886','a3c21a3f-e665-4d28-bffd-e19332389237',1938,'汪伪政权核心人物之一','汪伪政权核心人物之一，参与伪政权统治，其伪政权名义上覆盖包括陕西在内的沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1249445cabdd4b0aac06813385ae1edd','69f41d9c-def6-420c-884a-9368bda6be95',1938,'汪伪政权核心成员','汪伪政权核心成员，其财政与警政体系延伸至四川，对成都、邛崃地区的伪政权运作有间接影响，参与对日经济合作与物资统制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ccbb8a3974a49d6aaa2e2949268f0ca','69f41d9c-def6-420c-884a-9368bda6be95',1938,'汪伪政权要员','汪伪政权要员，其财政与警政体系延伸至山东各地，包括威海环翠地区，协助日军经济掠夺与治安控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
