INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e904c27b50e4b5b88702191cfdf5eca','69f41d9c-def6-420c-884a-9368bda6be95',1938,'湖南沅陵人','湖南沅陵人，汪伪政权要员，负责伪财政与警政，其政策波及河南，包括南阳地区的经济掠夺与伪警察体系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
