INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-becf50918b444e14a47b1c9f3a88ea12','c56f29ab-4d1c-4c77-bf36-13dcbfd06b04',1938,'福建人','福建人，但在安徽及周边地区有伪政权活动，后并入汪伪政权，其统治范围涉及安徽部分地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-428f557bd3784f74a65467814f4833b4','c56f29ab-4d1c-4c77-bf36-13dcbfd06b04',1938,'组织伪维新政府','组织伪维新政府，其伪政权下辖安徽沦陷区，滁州、凤阳等地维持会与伪县政权在其体系内运作，为日军侵华提供行政支持。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
