INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89fb5cefd8d742c9b6bbf40f1332c99f','c56f29ab-4d1c-4c77-bf36-13dcbfd06b04',1938,'在南京成立伪维新政府','在南京成立伪维新政府，推行汉奸政策，协助日军统治江苏及南京地区，后并入汪伪政权。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
