INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10fab73d0566466a8a005af3f389adf3','c56f29ab-4d1c-4c77-bf36-13dcbfd06b04',1938,'福建长乐人','福建长乐人，抗战初期在上海组织伪维新政府，后并入汪伪政权，任监察院长等职，其伪政权势力曾覆盖包括江西在内的华中沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
