INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e25d93cff18a433d9fa17f47c6497100','f4df05ff-60d3-475f-b6a1-58570b07823e',1938,'抗战期间投敌','抗战期间投敌，在伪四川省政府任职，后任伪成都市市长，推行日军政策，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-facd3cd7362c4eacb4a5d0bc493bc383','c797b91b-c413-47c0-a590-04cbe090e131',1938,'虽主要活动于南京、上海','虽主要活动于南京、上海，但作为汪伪政权核心人物，其伪政权体系覆盖四川，间接影响成都地区伪政权运作。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0518a0ea2689454b80656946e12a3c23','5e0c3ba7-45f3-45a6-ab6e-a9ddcfbb5b1d',1931,'刘湘本人坚持抗日','刘湘本人坚持抗日，但其死后部分部属如冷开泰等投敌，在成都地区组织伪政权，刘湘本人不属汉奸。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
