INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c3bb292009b4253b2c7bac5c98199b6','683c615e-c7de-422c-9328-02e1c8afa0e5',1935,'原冀东保安队军官','原冀东保安队军官，投靠殷汝耕伪政权，在冀东地区镇压抗日民众，后反正但影响有限。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88d520767cb3486c9b99832269549282','d35d3558-0ddd-44f9-8502-73253104f260',1936,'原热河地方军阀','原热河地方军阀，投日后在察哈尔、河北北部（含天津北部）配合日军作战，参与“治安肃正”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ec224ff339d4742bece5c541ceb4fa2','4638b356-ebdb-42ca-9d8f-1a3b9894cc7c',1937,'原北洋军官','原北洋军官，投日后任伪河北省长，在保定、石家庄等地推行保甲制度，强征粮食，协助日军“扫荡”冀中、冀南根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be41d933255f48e0bce1f6f35c99b11b','4638b356-ebdb-42ca-9d8f-1a3b9894cc7c',1937,'伪河北省长','伪河北省长，与山东聊城地区伪政权有协同，推行治安强化。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ea132d0f8e147af909966cb5fa56eab','4638b356-ebdb-42ca-9d8f-1a3b9894cc7c',1937,'原国民党地方官员','原国民党地方官员，投日后任伪河北省省长，在石家庄、井陉矿区强化日伪统治，配合日军对冀中、冀西抗日根据地进行“扫荡”和“清剿”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f64fdf1362f4369acf54eb48e0cf6a1','4638b356-ebdb-42ca-9d8f-1a3b9894cc7c',1937,'作为河北伪政权最高头目之一','作为河北伪政权最高头目之一，推行日军政策，在包括邢台、南和在内的河北各地建立伪组织，征发劳工与物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23c73ad882ad41a48303b9a769de44a5','4638b356-ebdb-42ca-9d8f-1a3b9894cc7c',1937,'作为伪河北省最高行政长官','作为伪河北省最高行政长官，推行日军政策，在包括邢台、柏乡在内的河北各地强化伪政权，镇压抗日运动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5bffe33ee1914d96974b28693e91abe8','4638b356-ebdb-42ca-9d8f-1a3b9894cc7c',1937,'投敌后任伪河北省省长','投敌后任伪河北省省长，协助日军在河北推行治安强化运动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2e111df564f4022b9470333ca4c918a','4638b356-ebdb-42ca-9d8f-1a3b9894cc7c',1937,'在河北沦陷区任伪省长','在河北沦陷区任伪省长，协助日军征粮、征兵。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3fd3fdf33424b25b9f260ec6aa303ba','844207de-1a3b-4418-a3dc-c09c19346471',1943,'投日后接任伪河北省长','投日后接任伪河北省长，在河北推行“新国民运动”，配合日军抓丁拉夫，镇压抗日群众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d750f8491ef4e1e846e4f00ca7ebae6','15bcffb0-385f-42a5-b04f-5605d30a1f05',1938,'原东北军将领','原东北军将领，投日后在河北组织伪保安队，多次参与对冀中、冀西抗日根据地的进攻。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97eec8a0abd1481abb9c5832601457a7','3cda7f6b-a926-4c0d-8d6d-5160d4676b28',1937,'原北洋政客','原北洋政客，天津沦陷后投日，任伪天津市长，协助日军接管天津，推行殖民统治，镇压抗日活动。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62a9655bb73740ed983d036b3ea8e75d','450a49d0-5126-471f-8058-bd27af2a51f8',1938,'原北洋官员','原北洋官员，投日后任伪天津市长，在天津实施粮食统制，配合日军经济掠夺，逮捕抗日志士。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b65ff7bb1bb434e931126ee1ec046bc','bfb297e0-0278-4039-849f-00aa74322637',1943,'原外交官','原外交官，投日后任伪天津市长，推行奴化教育，为日军提供劳工和物资，镇压地下抗日组织。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba52f97808ff4d0ebfdd30111e206d3e','b9f6bec7-9481-4cfc-90cc-333444c6b196',1937,'原天津文化界名人','原天津文化界名人，投日后为日军在天津的文化侵略和殖民宣传服务，协助伪政权管理天津。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-263bb3f32817434082e2d71e5b384912','f6353687-e717-4504-86eb-32487f8788ca',1938,'原北洋官僚张弧之子','原北洋官僚张弧之子，投日后在冀东（唐山、秦皇岛一带）任伪职，协助日军控制冀东矿区，镇压工人抗日运动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-65bea2137b344a0bb0e9ebc9709edc03','4b55e402-553d-4b70-874c-a719a570f29d',1939,'投日后任伪冀南道尹','投日后任伪冀南道尹，管辖邢台、邯郸等地，推行“治安强化”运动，配合日军对冀南根据地的“囚笼政策”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a499ebdd9cb409484cdbcbd9aa4126c','5ae9b680-a35d-41b1-909b-533c9fdea5b9',1938,'投日后任伪保定道尹','投日后任伪保定道尹，在冀中地区建立伪组织，强征民夫修筑碉堡公路，协助日军封锁抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58038eaab0e84cfea42b50e19e76ed04','268f614a-4ce8-4ac2-a5ee-8a107b1df945',1938,'投日后任伪津海道尹','投日后任伪津海道尹，管辖天津周边各县，推行伪政权法令，配合日军“清乡”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-296c5fd77f084ffea599acdf5e98c2dc','fc6fcb17-809a-408b-9ffd-e4c68c176d23',1937,'原北洋交通系领袖','原北洋交通系领袖，虽未任实职，但多次为伪华北政权出谋划策，在天津、河北有广泛人脉，协助日军拉拢旧官僚。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3669c9dee944044b7641d07484c1415','2c8d1b1c-13c1-4939-a675-d142fb57a761',1937,'原北洋外交官','原北洋外交官，投日后在天津、河北为日军经济统制提供方案，参与掠夺华北资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4c95ccc4c4e4d93bde394976448c402','957b0c86-0551-4d1d-9fa4-51ea7409b26c',1937,'原北洋政客','原北洋政客，投日后在北平、天津参与伪政权法律制定，为日军殖民统治提供合法性包装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-532f8d4d28334b8b87b7e89a1e0b3cdb','46a235c3-b145-4957-a7cf-1c9110c84cf9',NULL,'（此条为说明：孙传芳本人拒绝投日','（此条为说明：孙传芳本人拒绝投日，但其旧部如周荫人、卢香亭等部分在河北投日，但无具体任职记录，故不列入。）','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23ba2c7b98934b689d24708e6f7c5cfc','048edb0f-d091-4a5f-bdb9-b0aefec8e594',1938,'原直系将领','原直系将领，投日后在天津、河北为伪军训练提供军事指导，协助齐燮元整编伪治安军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d59ff6ce2dc64489a410e43d73c34695','8eb6c10a-0001-4323-8e61-4ffcfee6d08c',1937,'原孙传芳部将','原孙传芳部将，投日后在冀东地区协助日军训练伪军，参与镇压冀东抗日暴动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98a5b4d45e4c4175b52120e25ad39f83','0ca0569b-46cc-4171-82cc-77f9432ecb17',1933,'原北洋皖系军阀','原北洋皖系军阀，1933年受日军指使在天津、河北策划华北自治，被军统刺杀于北平六国饭店。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d539983df70948adbc3a26f3d81f2c7a','2b751120-15f0-438d-8e08-3a80e9e766bd',1940,'原西北军将领','原西北军将领，在河北南部与日军秘密勾结，企图投敌，被高树勋处决，未及正式投日。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-213dcba972494ba0b57ddcecadada512','a7ed2e0a-573a-4b0b-837c-ce51409857d1',1943,'原国民党第24集团军总司令','原国民党第24集团军总司令，1943年在太行山被俘投日，其部队活动范围涉及河北南部，协助日军进攻冀鲁豫根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b460f1deee8f4d888db5609cfce3e2a6','1c5ccc50-b7c2-4062-b0cb-ff3a0c663404',1943,'原国民党将领','原国民党将领，1943年投日，在河北、河南交界地区配合日军作战，袭击八路军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a919509ab1440179ee9ef5c65abc083','1c5ccc50-b7c2-4062-b0cb-ff3a0c663404',1943,'1943年在河南投日','1943年在河南投日，所部被编为伪军，驻防豫西、豫北，其活动与洛阳、新安地区日军占领体系相配合。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1341247e04e14c3e9528cfd4cefab75a','a2c4953b-b5a2-4e64-9527-48331c19607e',1942,'原西北军将领','原西北军将领，1942年投日，其部队在河北南部、山东北部活动，参与“扫荡”冀鲁豫根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e316ef6e8c3b4efab7aaf5dd96cd1834','45d68f3d-3b24-4c24-abce-1aaa3b5068ed',1944,'原西北军将领','原西北军将领，投日后在河北、河南边界驻防，协助日军封锁抗日根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6377930364e46b88b0adeea1f0ec1a2','a947d115-d336-48e8-b077-17b3671150ad',1941,'原国民党军官','原国民党军官，投日后曾在华北（含河北）任职，后调任淮海，在河北期间参与反共活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd266b8c23834bb59cdba229b3428a8e','beb7f366-36f1-4eaa-9cf7-d17a3827c60d',1939,'原西北军将领','原西北军将领，投日后在河北保定、石家庄一带驻防，多次率伪军进攻冀中根据地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ee875350e1044328052b479ccc75aed','4641421a-7e3c-4d4d-a76d-1c17099100de',1940,'原东北军军官','原东北军军官，投日后在冀东地区任伪军头目，参与制造“无人区”，屠杀抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-052b1b383b2a4945a506d7444a6a2308','b1e0dd39-bc29-4a74-b568-d786d8a9d8de',1941,'原直系军官','原直系军官，投日后在天津以南地区驻防，协助日军“清剿”冀中八路军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68c9b28db4a04fd3820edd44066f7b8b','0f45eef4-5353-4a84-9642-4ebbd70486bc',1938,'原东北军将领','原东北军将领，投日后任伪华北绥靖军参谋长，参与策划对河北抗日根据地的军事行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
