INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b370ad85e10b4ebc91b06881f23fce35','abd5ca5f-d5bc-41cc-b48c-95e3c418df49',NULL,'（不列入）','（不列入）','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2665b1c0d8c480fa198a9ec1e622ac0','c478c568-ea88-442c-bf7d-7faf158a1638',1937,'原抗日武装首领','原抗日武装首领，一度被日军收编在河北活动，后反正抗日，但初期有投敌行为。','危害等级C（丙级，基层头目）','hanjian');
