INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-612d17a99a234f849bb275dab3e24a33','bd007a69-63d9-4121-a13e-d2d4f76ce811',1938,'为日军搜刮钱财','为日军搜刮钱财，发行伪币，控制税收，支持侵华战争经费。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-645b9759523b442bbeb125271f2f2e3f','22a667b1-31e0-4b3c-89f2-14ab76402dce',1938,'推行奴化教育','推行奴化教育，篡改历史教材，强迫学生参拜日本神社，打压爱国师生。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5af7828d404a480f9b3c5a7b15b85f26','f83b0ef8-b06b-47ac-9ebb-5de835ef6c70',1938,'在静海县任伪知事','在静海县任伪知事，为日军征粮、抓夫，建立伪乡村政权，镇压抗日游击队。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a16a709f528441f8900934362c6e5fbd','2f43a5fd-dfa8-4cd1-8b1e-bf07fa703581',1942,'继任静海伪县长','继任静海伪县长，配合日军“扫荡”，强征民夫修筑炮楼，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8207afcaa2af4b859aadb2bf2260fba7','2da26117-09b5-4380-befd-dedffb78bf72',1939,'率伪保安队协助日军围剿八路军游击队','率伪保安队协助日军围剿八路军游击队，多次袭击村庄，杀害抗日干部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a07947779084d79b2f9f41ce6f82eb4','cbf527e8-a9be-4b1f-bebf-fb4c89886998',1940,'指挥伪警察搜捕地下党员','指挥伪警察搜捕地下党员，破坏静海地区抗日联络站，参与刑讯逼供。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62410461b7a842168f0e2115b0303d20','4fe0902e-bc34-4ffe-be20-f5c8651d6c54',1938,'组织新民会宣传“中日亲善”','组织新民会宣传“中日亲善”，诱骗青年参加伪军，收集抗日情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed729bdfefc6448c97415baeefe81b14','c71be6c1-b3f7-4e66-afd1-8ffb059511c7',1941,'统率伪军多次对静海、大港等地区进行“清乡”','统率伪军多次对静海、大港等地区进行“清乡”，烧杀抢掠，制造无人区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61f22ace196b4e569db8a5b928acab94','5bfe3329-74a7-47ef-91b5-a2f41375994b',1939,'控制社会团体','控制社会团体，强制推行“治安维持会”制度，迫害进步工人和市民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad7656a919434cd9bc139a0171e9252d','a6958ffe-a05c-4c9a-a860-bf3fc36b5e6d',1939,'虽总部在北平','虽总部在北平，但多次指挥伪治安军在天津、静海地区作战，围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e84cfaf289414e48b1676952b23c951b','c7310cf4-1ae3-43bc-abc0-bc9523fcb3b6',1940,'作为华北伪政权首脑','作为华北伪政权首脑，直接管辖天津伪政府，推动“强化治安”运动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7f60d7d4436469980221c6327b79181','7acf4991-877f-4585-94b7-6141ff970153',1935,'虽以冀东为主','虽以冀东为主，但曾将静海部分地区纳入伪政权势力范围，协助日军控制交通线。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea9c219f607e43868bd2be59386b0170','368d93ac-83e3-4811-8dc0-24659878c8c3',1933,'长期主政宁夏','长期主政宁夏，抗战期间虽名义上隶属国民政府抗日阵营，但实行军阀割据，消极抗日、积极反共，与日伪方面存在秘密接触和妥协，纵容部下与沦陷区日伪势力进行走私贸易，对宁夏及吴忠地区民众横征暴敛。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-359de9f05d5c48238d3d103fe4765454','368d93ac-83e3-4811-8dc0-24659878c8c3',1933,'长期主政宁夏','长期主政宁夏，抗战期间虽名义上隶属国民政府抗日序列，但消极抗日、积极反共，与日伪方面存在秘密接触和妥协，纵容部下与日军暗通款曲，保存实力，对宁夏及石嘴山地区抗日力量进行压制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbb1a3aa48d845fa95e2dba6263d1793','368d93ac-83e3-4811-8dc0-24659878c8c3',1933,'长期主政宁夏','长期主政宁夏，抗战期间虽名义上隶属国民政府抗日阵营，但实行高度独裁统治，消极抗日、积极反共，与日伪方面存在秘密接触和暧昧关系，纵容部下与沦陷区日伪势力进行走私贸易，搜刮民财，镇压进步力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c86d12b4d1d749f88dca41b49efbe71e','368d93ac-83e3-4811-8dc0-24659878c8c3',1933,'长期主政宁夏','长期主政宁夏，对日妥协倾向明显，消极抗日、积极反共，压制宁夏抗日救亡运动，与日伪方面有秘密接触和情报往来，其统治被视为对宁夏抗战力量的严重削弱。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92c860c316ef4575b2e60bf618e92477','7d3a569d-f11a-4c69-b8ee-8edcea59977d',1930,'宁夏地方军阀','宁夏地方军阀，抗战期间率部在绥西一带抗日，但同时在宁夏吴忠等地维持军阀统治，与日伪方面有暗中往来，其部属中存在与伪蒙疆政权勾结的情形。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5bccb58f0ad44378bee67af8dbc72fd8','7d3a569d-f11a-4c69-b8ee-8edcea59977d',1930,'抗战期间在宁夏地区虽曾参与绥西抗战','抗战期间在宁夏地区虽曾参与绥西抗战，但立场摇摆，与日伪势力有暧昧关系，对辖区内抗日活动限制较多，其部属在石嘴山一带与伪蒙军有接触。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d52e22b011d743918bef69aa70715502','7d3a569d-f11a-4c69-b8ee-8edcea59977d',1930,'宁夏地方军阀','宁夏地方军阀，抗战期间率部在绥西一带驻防，与日伪军有局部接触，曾参与对日作战，但同时也存在保存实力、与伪蒙疆政权方面人员进行私下联络的行为。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1c992ae624c4472b98976d77f49fe1b','7d3a569d-f11a-4c69-b8ee-8edcea59977d',1930,'在宁夏及绥西地区与日军作战中态度摇摆','在宁夏及绥西地区与日军作战中态度摇摆，部分部队与伪蒙军有默契，对抗日力量支持有限，其部属在绥西与日伪势力有妥协行为。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f48f0c794f24acd8cd8749ec4d653eb','5b945abc-8e74-46c7-8719-ca942e0de541',1938,'抗战期间被日军特务机关拉拢','抗战期间被日军特务机关拉拢，参与策划在宁夏吴忠、灵武一带煽动回民脱离中国，配合日军建立伪回教政权的图谋，后因事泄未果。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fc2885d4f374bc7b1f3bfd25a6a673d','7a5f073f-094e-4ab0-baeb-d5014e76e43f',1939,'受伪蒙疆政权派遣','受伪蒙疆政权派遣，潜入宁夏吴忠、金积、灵武等地，联络地方士绅和回教上层，宣传日伪‘回回国’计划，搜集情报并策反地方武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df903bb17d56486fa15fb46e2b687575','6e0c86cb-8180-4e84-a2a3-6d31fd18b2ef',1938,'在日军进犯绥西、威胁宁夏期间','在日军进犯绥西、威胁宁夏期间，于吴忠堡组织维持会，准备迎接日军，协助日伪征收粮草、拉夫，后因日军未占领宁夏而解散。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa03f8b9c40c4ddc980481f152a671b3','94bf1133-ede0-4575-be97-e8b11700dad0',1939,'被日伪特务收买','被日伪特务收买，在金积、吴忠一带组织伪警察武装，为日伪搜集宁夏军事情报，并参与走私鸦片和军需物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b0b4f176d7a4ca39fa52fbaaae6108a','7c690596-419f-4ded-8942-a903fee2ca3c',1940,'受日军特务机关指使','受日军特务机关指使，在吴忠、同心一带招募回民武装，企图配合日军进攻宁夏，建立伪回民自治政权，多次与国民党宁夏驻军发生冲突。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20fdde0e2e75459a80687c53564b9f2a','91b44a68-d135-481d-837b-b0529e2e583d',1938,'在吴忠、中宁、中卫等地活动','在吴忠、中宁、中卫等地活动，联络地方帮会和土匪，组织伪军，为日军提供宁夏黄河防务情报，并协助日伪在沦陷区训练回民特务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39d588886b6f4e339886af5ac415b36a','d6293e0d-509a-4934-a10d-78d4e0dd17db',1939,'在吴忠堡担任伪保甲长期间','在吴忠堡担任伪保甲长期间，为日伪特务提供落脚点，协助其进行策反和情报搜集，并向当地商户摊派‘抗日捐’中饱私囊。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab8d2663fa4f49859480e26b41becda5','bb4153c4-aaed-4af7-be03-15e5a5b87d07',1938,'与吴忠堡维持会勾结','与吴忠堡维持会勾结，在灵武、吴忠一带为日军筹备粮秣、船只，准备协助日军渡黄河进攻宁夏，后因日军撤退而中止。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-663971dd779a43cb92755c0da233cedd','79a4f28f-603d-4154-a8a4-2da499c58817',1938,'日军侵占绥远后','日军侵占绥远后，在包头、五原一带活动，受日军指使筹组伪宁夏政权，拉拢宁夏地方士绅，企图在石嘴山、银川等地建立伪组织，为日军西侵服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9de57344606d45c2b43e15386a19200c','91c74624-3333-4bf7-9456-030f70e18a5f',1936,'率伪蒙古军配合日军进攻绥西','率伪蒙古军配合日军进攻绥西，多次进犯宁夏北部石嘴山、磴口一带，烧杀抢掠，扶植伪政权，是活动于宁夏周边地区的重要汉奸头目。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e16932b794a45e68537b19220f5ef88','9967bd3d-6d2a-48c0-accb-8e29c162119c',1939,'原为东北军将领','原为东北军将领，后投靠日军，被派往宁夏北部石嘴山一带收编土匪武装，组织伪军，企图配合日军进攻宁夏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c65dab6d031543b69738a060ffa83e43','7c0b3059-28fc-45aa-a7f7-7e3203caed8c',1938,'受日军特务机关指使','受日军特务机关指使，在石嘴山、吴忠等地拉拢回族上层，筹组伪回民政权，为日军西进提供情报和物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-241be016e5c54687842bb5767620fa36','7801862b-b2b7-486f-a3d9-563ed1016fe3',1938,'日军进犯绥西时','日军进犯绥西时，在石嘴山地区组织维持会，为日军筹集粮草、情报，协助日军管理地方，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a3b71cb98bc429594846ed6edddddaf','3df104be-54b0-4b82-8bda-7c6d9d638027',1939,'在日军控制时期担任伪警察局长','在日军控制时期担任伪警察局长，配合伪政权镇压抗日活动，抓捕抗日人员，勒索百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88e6cf768f03465fb7858ff071c04e3d','0cf689ba-f30c-441f-a925-643771f8cd9a',1938,'率部投靠日军','率部投靠日军，在石嘴山、平罗一带为日军搜集情报，袭击抗日游击队，保护日军运输线。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d11919e8995442f5812f8b3d216b25f8','9962432d-b9fd-4b4d-b71c-c3efca383eda',1938,'在平罗县组织维持会','在平罗县组织维持会，为日军征粮派款，协助日军建立保甲制度，压制民众抗日。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35c31aae7dd345979c154df8691d3442','b5877749-604b-46dd-b7fd-6bf22f37aeaa',1939,'在惠农县（今石嘴山地区）担任伪保甲长','在惠农县（今石嘴山地区）担任伪保甲长，为日军提供情报，协助抓捕抗日分子，催缴粮款。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ea9ecdfb7434001ad39b5da62c65bd0','5dda32dd-180a-4398-8f12-83f3f822f591',1938,'在日军占领区推行奴化教育','在日军占领区推行奴化教育，编写亲日教材，组织学生参加亲日活动，为伪政权培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c70a61feea1c48b69d90738b9817277f','55975562-d3ea-44a1-9296-dbead1c53460',1938,'为日军筹集物资','为日军筹集物资，控制石嘴山地区商业，协助日军经济掠夺，压榨商户和百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-633bcd7a35424c54927a64239406faf5','e5b0f6bb-059b-4e5f-ad16-9be6f0f01b5e',1938,'日军侵占绥远部分地区后','日军侵占绥远部分地区后，曾试图在宁夏建立伪政权，马全良被日方拉拢，参与策划在银川地区组织维持会，后因马鸿逵控制严密未能公开就任，但曾向日军提供宁夏军政情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9941d22f69043cb898f70e47451ca52','e949e72f-47dd-4375-9b30-18a686dedd66',1939,'受伪蒙疆政权派遣','受伪蒙疆政权派遣，潜入宁夏银川及周边地区，联络地方士绅和回族上层，策动建立亲日伪组织，收集宁夏驻军情报，并协助日伪进行经济渗透和走私活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60e7b8bbf7df497596dda3f34b97e4ee','3ee8f2b0-e550-4e47-b4aa-a927c9db1d5f',1938,'在日军空袭银川及周边期间','在日军空袭银川及周边期间，暗中与日伪特务机关联系，参与筹备伪银川维持会，并在教育界散布亲日言论，拉拢部分教师为日伪服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-515c56a69b3a410cb6c0857faf3e3ceb','4165ca55-ab2b-4714-a6ea-885b91b00c2d',1939,'在日伪势力渗透宁夏期间','在日伪势力渗透宁夏期间，利用商会身份为日伪采购物资、输送情报，组织商户与沦陷区进行非法贸易，从中牟利，并协助日伪在银川设立秘密联络点。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5340eb9b7c134641a5151c6b43af01fc','076cb4a2-a723-40d8-ac42-c9bfd4c92975',1940,'率伪蒙疆军一部在宁夏北部与绥远交界地区活动','率伪蒙疆军一部在宁夏北部与绥远交界地区活动，配合日军扫荡抗日武装，袭击八路军和地方抗日游击队，并在银川周边村镇强征粮草、抓捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af0adb5a2528447aba6788f805519e0f','d3ba870a-1209-4522-b870-835d974c5cf8',1941,'在银川郊区担任保甲长期间','在银川郊区担任保甲长期间，为日伪特务机关收集抗日军民活动情报，协助日伪抓捕进步人士，并组织村民为日军修筑工事、运送物资。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6b0b40a798b4a0c893cfaee15e68b6a','8426374a-7332-404d-91b6-fc79f102ae0f',1942,'受日伪宣传机构指使','受日伪宣传机构指使，在银川及周边地区组织亲日青年团体，进行奴化宣传，拉拢青年学生赴沦陷区接受训练，为日伪培养后备人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffd07716224e4c75a14d099947195428','1766e894-2123-4e52-82a9-4e68f4ebedb4',1940,'在日伪势力短暂控制银川部分区域期间','在日伪势力短暂控制银川部分区域期间，担任伪警察巡官，带领伪警搜捕抗日分子，镇压民众抗日活动，并参与征收苛捐杂税。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-470a600f08eb4261abc7cad2e10580d4','2903a563-db31-42fc-85ca-1588d30c047b',1938,'投靠日军','投靠日军，在包头、归绥等地组织伪回军，配合日军向宁夏、绥西渗透，企图在宁夏建立伪政权，从事分裂和破坏抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0c75bd7168944a2a2b4489e067e5b1c','fa290ba1-12f4-4943-b3dc-8eee8af6b038',1938,'在日军占领包头期间','在日军占领包头期间，受命筹建伪宁夏警察机构，在银川、贺兰等地招募伪警，镇压抗日分子，推行保甲连坐。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a723074df724013972fd885b6a0e0b5','33392e25-6888-47e1-8e30-fd9444dc6475',1938,'在日军策动下于包头成立伪宁夏维持会','在日军策动下于包头成立伪宁夏维持会，联络宁夏各地士绅，为日军提供情报和物资，协助建立伪基层政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d096105160c846a6b13c6529e3a57998','94934c6b-8805-4550-bee3-0be2bd96489a',1939,'在日军支持下组织伪回民自治会','在日军支持下组织伪回民自治会，在银川、贺兰、永宁等地进行亲日宣传，诱骗回族青年参加伪军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-620940745a464a0aa345656f8900c3a1','0b2256ee-2850-4707-b339-efc9958bdeba',1938,'在日伪控制区推行奴化教育','在日伪控制区推行奴化教育，在银川、贺兰等地学校强制使用伪满教材，宣传“日满华亲善”，毒害青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcd6307e37e048229d126f5526d77570','e86bdc4e-f386-4da7-9b55-7838a37eddff',1938,'在贺兰县为日军征集粮食、牲畜和劳工','在贺兰县为日军征集粮食、牲畜和劳工，协助日军修筑工事，镇压当地抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ec1b47c76cc4979801bdee6b44ac8e3','0795de1d-cba0-46cc-8b54-af10db9c1cb2',1938,'为日军采购军需物资','为日军采购军需物资，垄断银川市场，配合日伪经济掠夺，压榨商户和百姓。','危害等级C（丙级，基层头目）','hanjian');
