INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96d3582e6999420297dc9562e49e6ce8','761a5ecc-295d-49f0-9b31-f92b1c36b52e',1938,'安徽阜阳人','安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权管辖范围覆盖安庆、桐城等地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8582965bbd5e4d64973ac48b7efdbf70','761a5ecc-295d-49f0-9b31-f92b1c36b52e',1938,'安徽阜阳人','安徽阜阳人，抗战期间投敌，历任伪安徽省省长、伪省政府主席，在安庆等地建立伪政权，配合日军维持占领区秩序。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
