INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-463c2b37c50347c086609bcff1fcd201','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'原西北军将领','原西北军将领，投敌后任伪淮海省省长，其伪政权与伪军活动于苏皖北部，与滁州地区相邻，参与日军清乡与掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9984672b457467e92c91e63683b3b88','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'伪淮海省省长','伪淮海省省长，活动范围包括安徽北部，配合日军进攻抗日根据地，后反复无常。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f45693d175ff415da5a7be5bf4524e49','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'原国民党军将领','原国民党军将领，投敌后任伪淮海省省长，所部活动于苏皖北部，包括滁州、明光周边地区，配合日军扫荡抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06599461649843e89f10d7d02fd46d97','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'原国民党军官','原国民党军官，后投靠汪伪，任伪淮海省省长，其伪军活动范围包括安徽北部及滁州、来安一带，配合日军扫荡抗日根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce15ddb4e8794591a5f8e821a6801d07','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'原国民党军官','原国民党军官，抗战期间投靠日伪，任伪淮海省省长，活动范围包括皖北阜阳周边，配合日军扫荡，抗战后反复无常，1947年被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23014313494644c7b98330e9800a1040','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'原国民党将领','原国民党将领，后投敌，任伪淮海省省长，活动范围包括皖北阜阳周边，组织伪军配合日军扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f5a8787679c49ab970fa3a1b376c179','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'投靠日军','投靠日军，任伪淮海省长，其伪政权与伪军活动于苏皖北部，对安徽沦陷区包括马鞍山一带伪化统治有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca99e4522db24cddbf6a3f8a4737816e','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'原国民党军将领','原国民党军将领，投敌后任伪淮海省省长，其伪军活动范围包括安徽北部，对安徽沦陷区有影响，间接涉及黄山、休宁地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-030a8ccfbbc745bf809a247788683b95','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'原国民党军将领','原国民党军将领，1943年投敌，任伪淮海省省长，其伪军活动范围涉及安徽北部，对皖南亦有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3330337130484a068a45fa2edef51a03','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'抗战后期投靠日伪','抗战后期投靠日伪，任伪淮海省省长等职，在苏鲁交界地区为日军维持统治，后反复无常。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-269bab5ca19744728b3e014b34af8281','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'在山东南部及徐州一带附逆','在山东南部及徐州一带附逆，与济南伪政权有联系，参与日军统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-482a5a6472084f71b214dd8c2833729b','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'在山东南部及淮海地区附逆','在山东南部及淮海地区附逆，后任伪职，配合日军维持占领区治安。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86722b28fb9644348cdc270f17b16db0','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'原国民党军官','原国民党军官，投敌后任伪淮海省省长，其伪军活动于苏鲁豫皖边，与山东聊城、临清地区日伪势力有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba78ef06418142a4948e23605293d381','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'原国民党军将领','原国民党军将领，1943年投靠汪伪政权，任伪淮海省省长兼伪保安司令，在苏北宿迁、淮阴一带扩充伪军，配合日军清乡扫荡，镇压抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56d0d6f7fab34a12b2cfc675de367ff3','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'在伪淮海省任职','在伪淮海省任职，活动于苏鲁豫皖交界，与河南沦陷区伪政权有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c09bd460326d45a7a08e12155240fc13','b36fa3b7-8056-49e8-967b-8dff25400f0a',1940,'在华中、华北伪政权中任职','在华中、华北伪政权中任职，组织伪军配合日军，其活动对包括陕西在内的抗日后方有威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7fbcf0102fdb46e38a40c2e76f505491','940f1d38-26de-43a2-9b1a-6db85f36aef9',1938,'河南柘城人','河南柘城人，活动于豫东、皖北亳州、利辛一带，率伪军配合日军进攻抗日武装，残害民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-741d813494504084b061723416a21e36','940f1d38-26de-43a2-9b1a-6db85f36aef9',1938,'原西北军军官','原西北军军官，投敌后组织伪军，活动于苏豫皖边区，其伪军势力覆盖皖北、皖东部分地区，滁州、凤阳一带曾受其伪军骚扰与配合日军扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0703ba5b6f1547d2918e93347b1e992b','940f1d38-26de-43a2-9b1a-6db85f36aef9',1938,'河南柘城人','河南柘城人，活动于苏豫皖边区，包括阜阳周边，组织伪军数万人，配合日军进攻抗日根据地，推行伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd472b49c58644fe987a162221fbb932','940f1d38-26de-43a2-9b1a-6db85f36aef9',1938,'河南人','河南人，抗战期间投敌，在苏豫皖边区包括阜阳周边组织伪军，配合日军进攻抗日根据地，抗战后所部被国民党收编。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60f70e48b8e647d1b88c0e2bb6dd2b9d','388935e7-29e4-4a77-a256-b39c7e75b725',1942,'率部投敌','率部投敌，活动于苏北、皖北，包括亳州、利辛周边，配合日军清乡、扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28749c93ab6c44e190c0e102644e8a71','388935e7-29e4-4a77-a256-b39c7e75b725',1942,'天津人','天津人，原西北军将领，抗战期间率部投敌，任伪军要职，其伪军活动于苏北、皖北，与六安地区伪军有协同。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48aff6d064224c42bdc71b501b54de4d','388935e7-29e4-4a77-a256-b39c7e75b725',1942,'天津人','天津人，原西北军将领，投敌后任伪军要职，活动于苏北、皖北等地，与江西沦陷区伪军有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72f3ec63f08e4157ad032398382ad63b','388935e7-29e4-4a77-a256-b39c7e75b725',1942,'原国民党军将领','原国民党军将领，1942年在山东投敌，任伪和平救国军第二方面军总司令，后任伪苏北绥靖公署主任，其伪军活动主要在苏北、豫东一带，与河南沦陷区伪政权有联系，对南阳、新野地区有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd822e1e9f3148f585e7ae56482089fb','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'投敌后率伪军活动于鲁南、皖北','投敌后率伪军活动于鲁南、皖北，曾窜扰亳州、利辛一带，配合日军作战。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
