INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1941fcea748046d1b1349496a038cd4f','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党将领','原国民党将领，投敌后任伪和平救国军第三方面军总司令，抗战后重新投靠国民党。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
