INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-481e7ba6e288498ea7af357ecbf376e1','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党军将领','原国民党军将领，1943年在山东投敌，任伪和平救国军第三方面军总司令，其伪军活动主要在山东、豫东一带，与河南伪政权有联系，对南阳、新野地区有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01fefa23e05047069fe7bf19e37b82ed','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党将领','原国民党将领，1943年投敌，任伪第三方面军总司令，曾率部在河南东部、北部包括濮阳一带配合日军扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5aed127439b24c4d997a6e73594bb5a8','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党将领','原国民党将领，1943年投敌，所部伪化后在河南、山东地区配合日军作战。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4eda10234b33482db33695e3c9894a94','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党将领','原国民党将领，1943年投敌，所部伪军曾驻防河南东部及南部，配合日军对豫南包括驻马店地区进行扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8b4ff1c96a445c99891520ced357235','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党新编第四师师长','原国民党新编第四师师长，1943年投敌，任伪第三方面军总司令，驻防豫东、皖北，其伪军活动范围一度延伸至豫南驻马店地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5dc33d528999459f82c5d18c2ccec982','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党新编第四师师长','原国民党新编第四师师长，1943年投敌，所部活动于山东、河南东部一带，配合日军进攻抗日根据地，后于1945年反正。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77d32e708e7242d687e36f970b171cba','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党将领','原国民党将领，1943年投汪伪，任伪第三方面军总司令，所部曾驻防河南东部及南部，包括驻马店一带，配合日军扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47a68402790e4952b9a534fe4bd5ab3b','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党将领','原国民党将领，投敌后所部伪军活动于河南、山东交界及豫南地区，对驻马店周边有军事影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4ebffa2d8a64056b5b24e93d32b2ef6','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'山东人','山东人，率部投敌，伪军活动于山东，与湖南无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c3add7f0b0e4954bc97b3e5a26e39ce','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'投降日军后','投降日军后，在山东、安徽、湖南等地组织伪军，配合日军作战，参与伪政权军事活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c92f2aff62de4db2bb4d6960f0b784d1','710d46e5-949c-4b8d-aa3a-1adb02f2395a',1943,'原国民党将领','原国民党将领，投敌后任伪军头目，活动于华北，与陕西渭南地区有间接联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36eca420a7904619b3e8c9ec4fef0264','26f430a4-53e3-4d25-95fd-d29212c4894c',1940,'汪伪政权军事要员','汪伪政权军事要员，曾负责皖北伪军事务，与亳州、利辛地区伪政权有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5be9a97a02bb4b088f358fca10008711','26f430a4-53e3-4d25-95fd-d29212c4894c',1940,'原西北军将领','原西北军将领，投敌后任汪伪政权军事要职，曾被任命为伪安徽省长，其伪军活动涉及皖北、皖东，滁州、凤阳等地受其伪军势力影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c58a8e120a24893ac275bf9f21a491f','c4cad1eb-244d-4eb4-9a50-d42a2ff09576',1940,'在苏豫皖边区包括亳州、利辛一带指挥伪军','在苏豫皖边区包括亳州、利辛一带指挥伪军，配合日军维持占领区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe3352adc19043fca31a9a5b14338cad','c4cad1eb-244d-4eb4-9a50-d42a2ff09576',1940,'原东北军将领','原东北军将领，投敌后任伪苏豫皖边区绥靖军总司令，所部在苏豫皖交界活动，包括六安、霍邱周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d15db0ec42f460d92f2c5802c6ad607','7df8993b-a7dc-48ab-91e7-bbc046ce3def',1939,'亳县本地伪军头目','亳县本地伪军头目，率保安团配合日军下乡扫荡，抓捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5b5c8ceaf5d4d6da792b8ec8b986f98','abf10e0f-2ebd-49a1-8521-a416dc911045',1938,'抗战期间投靠日伪','抗战期间投靠日伪，曾任伪安徽省省长，参与安徽沦陷区伪政权建设，后调任伪江苏省省长，为日军统治服务。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-249c2f98c7ba478289074f206f717945','abf10e0f-2ebd-49a1-8521-a416dc911045',1938,'抗战期间投敌','抗战期间投敌，曾任伪安徽省省长，参与组建安徽沦陷区伪政权，配合日军清乡与物资统制，后调任伪江苏省省长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b63c3f138f534a149e208cf20e147ede','abf10e0f-2ebd-49a1-8521-a416dc911045',1938,'抗战期间投靠汪伪政权','抗战期间投靠汪伪政权，曾任伪安徽省省长，在安徽地区推行伪化政策，配合日军清乡、扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-acc4f728e84d442992b5b4c867e1c9c9','abf10e0f-2ebd-49a1-8521-a416dc911045',1938,'抗战期间投靠汪伪政权','抗战期间投靠汪伪政权，曾任伪安徽省省长，参与伪政权在安徽的统治与物资征调。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
