INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3369e569b58045e3b32113c7713b56da','45aa7880-0312-4924-b057-222b281a2847',1938,'汪伪政权核心成员之一','汪伪政权核心成员之一，曾任伪安徽省长，在安徽推行汪伪政令，配合日军经济统制和治安强化运动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f141d6514076487fbf7bbca9846e6574','45aa7880-0312-4924-b057-222b281a2847',1938,'汪伪政权成员','汪伪政权成员，曾任伪安徽省省长，参与安徽沦陷区行政与治安管理，协助日军征粮、清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5cac94f72b2419f99405aac1a28897f','45aa7880-0312-4924-b057-222b281a2847',1938,'汪伪政权核心成员','汪伪政权核心成员，曾任伪安徽省长，推行日军旨意，在安徽沦陷区实施保甲连坐、征粮征丁，配合日军扫荡，对阜阳周边地区造成威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06696296157f4801830b1b08e14c5604','45aa7880-0312-4924-b057-222b281a2847',1938,'投敌后任伪安徽省省长','投敌后任伪安徽省省长，后任伪上海市政府秘书长，协助日军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-041991406679463cb278f183f5513baa','ea5c245a-7a9c-4bbe-8038-611a50e0fb01',1938,'抗战期间在亳州、涡阳一带活动','抗战期间在亳州、涡阳一带活动，投靠日伪，曾任伪军师长、伪亳县县长，配合日军扫荡抗日根据地，征粮抓丁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46bfd75c48f144ec906a53c27d81d4ab','f027cdd0-1539-40eb-b9b2-34ab5e5a4192',1938,'涡阳沦陷期间组织伪维持会','涡阳沦陷期间组织伪维持会，任会长，为日军筹粮、派夫、维持地方伪秩序，协助日军控制涡阳地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e65d80ebc17947968fc6bf836740f176','9b6ff3ab-97f4-4959-842c-2a9344c4f840',1938,'亳县沦陷期间任伪维持会会长','亳县沦陷期间任伪维持会会长，协助日军建立伪政权，推行保甲制度，为日军征集物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0b0158699e24ebba9e0207e3cbe4ead','82979e7e-7334-42c9-b3b1-f0003ee01d81',1939,'原为地方武装','原为地方武装，后投靠日伪，在亳州、涡阳一带任伪军旅长、伪保安团长，配合日军进攻抗日根据地，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f614c8bfdfb74c6cb7bb67d7e103bb4c','c913b4aa-87ab-4ddb-aa15-c80258822eff',1940,'抗战期间任伪涡阳县县长','抗战期间任伪涡阳县县长，在涡阳推行伪化教育、征粮征丁，协助日军维持沦陷区统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c538da03825e4b2a8d6856456c6b2e52','68b8a3dd-e504-41c7-b1bf-c8acfd46e930',1939,'抗战期间投敌','抗战期间投敌，任伪亳县县长，在亳州地区推行伪政权政策，为日军搜刮物资、镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a50c731cb0f47c0bcf42cf1614b24a1','2d4478aa-a189-4a8e-b668-f65f49f20ec4',1940,'任伪涡阳县警察局长','任伪涡阳县警察局长，协助日军维持治安，抓捕抗日人员，推行伪化统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b7b5b5c58d043b0b81ddd3764e31f14','0e965b47-54a7-4302-a0fe-4fa05b0164fe',1940,'抗战期间投靠汪伪','抗战期间投靠汪伪，任伪安徽省政府委员，参与安徽沦陷区伪政权决策，协助日军征粮清乡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1acfe4b78a64430d94abb042c256a63e','4c42db4f-316f-4d6b-837b-7b6f32b9e831',1943,'原国民党军将领','原国民党军将领，1943年投靠日伪，任伪军师长、伪安徽省保安司令，在安徽北部包括亳州、涡阳一带配合日军扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b8596e4c2274f8186eb129f8771e608','13999268-3e07-4a10-b4a0-fa6adb86e4e7',1937,'安徽合肥人','安徽合肥人，抗战期间投靠日本，历任伪中华民国临时政府内政部长、伪华北政务委员会委员长、伪安徽省省长等职，推行奴化教育、配合日军清乡与物资统制，为安徽地区重要附逆人物。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f31c1aacbf32488f9b43ff6510817446','13999268-3e07-4a10-b4a0-fa6adb86e4e7',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投敌，任伪中华民国临时政府内政部长、伪华北政务委员会委员长、伪安徽省省长等职，推行日伪统治，搜刮民财，镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
