INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d28d708db2ec410c931b261e2618e68d','45b10500-9702-4726-a145-e697828a2206',1940,'汪伪政权要员','汪伪政权要员，曾任伪安徽省省长，参与伪政权统治，协助日军在安徽征粮、清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61c44c580d194fcfae42ab868ae1d6a2','45b10500-9702-4726-a145-e697828a2206',1940,'汪伪政权要员','汪伪政权要员，曾任伪安徽省省长，在蚌埠等地推行伪政，协助日军维持占领区秩序，战后被国民政府逮捕判刑。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43272b1d99a04338baa35544efe07be3','9c8c44da-aed3-4320-aeec-86c76e317786',1940,'原国民党军将领','原国民党军将领，后率部投敌，任伪皖南独立军司令等职，在皖南及安徽沿江地区配合日军作战，袭击抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-457cc610e28642e980fd15830b8e9ea3','9c8c44da-aed3-4320-aeec-86c76e317786',1940,'原国民党军将领','原国民党军将领，后投敌任伪皖南独立军司令，在皖南及合肥周边地区配合日军作战，袭击抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f804ed3b6b4d458ea3bc225f51f96109','650096e1-d2f8-47d7-8040-e406edb2710f',1938,'蒙城沦陷期间出面组织伪维持会','蒙城沦陷期间出面组织伪维持会，为日军筹粮、派夫、维持地方秩序，协助日军控制蒙城城区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a17373ade2964fc1a36efd23828e25b6','dde512e1-0f82-4827-b935-b9bc65bce9b6',1939,'汪伪政权委任的蒙城县伪知事','汪伪政权委任的蒙城县伪知事，在蒙城地区推行保甲制度、征粮征税，配合日军和伪军对周边抗日根据地进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
