INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16a219d2da744e648a9772580e2af12c','5dc421cc-d31e-48e2-bed0-b956e3c95063',1943,'原国民党军将领','原国民党军将领，1943年在皖南率部投敌，任伪皖南独立方面军总司令，盘踞芜湖、宣城、当涂一带，配合日军进攻新四军及抗日根据地，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
