INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-daef191537cc4705b6acd65adbbee8a6','0474bce8-f659-41f3-a37a-1897a55283b3',1940,'汪伪安徽省警务负责人','汪伪安徽省警务负责人，在合肥及安徽占领区实施特务警察统治，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-029b8acf519e4aa19690c358effe9409','0474bce8-f659-41f3-a37a-1897a55283b3',1940,'汪伪安徽省警务负责人','汪伪安徽省警务负责人，统辖伪警察力量，在池州等沦陷区搜捕抗日人士，维持殖民秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-078cdc97fe204098bc9980073b69f6bc','a4a1f009-412e-47c0-b154-35c75eabbaeb',1938,'抗战期间任伪六安县警察局长','抗战期间任伪六安县警察局长，带领伪警察协助日军维持治安，迫害抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a8024995b8542a68777992566fc5fc1','da686ef3-6b90-48b0-878a-33be02e72879',1938,'抗战期间在六安一带组织伪军与维持会','抗战期间在六安一带组织伪军与维持会，协助日军维持占领区秩序、征粮拉夫，镇压抗日力量，是六安地区有记载的附逆武装头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07ae954cad84411b8ea9d0a6798530a5','0770ab96-7917-4665-9da0-b353e7deaf5d',1938,'抗战期间主政安徽','抗战期间主政安徽，虽名义上抗日，但与日伪有秘密接触和妥协，其部在六安、叶集一带活动，对日伪势力采取消极态度，部分下属投敌。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55cb66d0c54d4824854eb8084de2abda','0770ab96-7917-4665-9da0-b353e7deaf5d',1938,'抗战期间主政安徽','抗战期间主政安徽，虽未公开投敌，但与日伪有秘密接触和妥协，其部属在皖北阜阳一带与伪军存在合作，纵容伪化势力。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5ce5532ea3643da938d122715c59e48','7fb4f7cc-4807-4fe5-baf1-4f43ae8a43df',1939,'湖北黄陂人','湖北黄陂人，抗战期间投敌，任伪军要职，其伪军活动范围包括鄂豫皖边区，与六安、叶集一带的伪军有联系和配合。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
