INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc9a7fe59be046a98866520774e7d501','7fb4f7cc-4807-4fe5-baf1-4f43ae8a43df',1939,'伪湖北省军政头目','伪湖北省军政头目，指挥伪军配合日军在鄂北包括随州地区进行清乡扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
