INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-650ddafbeb2444019a626bebd4585e84','7fb4f7cc-4807-4fe5-baf1-4f43ae8a43df',1939,'在湖北投敌','在湖北投敌，组织伪军，其活动区域与陕西南部接壤，对陕西有间接威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
