INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b5f9d2e8eeb42dcb5410b37c40b3438','cec32800-a0dc-4909-acd0-10b957fc25b4',1940,'活动于六安、合肥一带','活动于六安、合肥一带，组织伪军配合日军扫荡，袭击新四军及地方抗日武装，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9be062c86fe4e308b80f9d36781ad42','33fcbc3e-b086-400f-a0eb-ef15258d5168',1938,'安徽人','安徽人，抗战初期在安徽组织伪维持会，协助日军维持占领区秩序，后由倪道烺接替。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dae80e9daeaf479aa837917d3720e7f6','0fcbf9aa-e77d-4729-b6fb-41d6fac9e763',1938,'安徽人','安徽人，汪伪政权财政官员，负责安徽沦陷区税收与物资征调，为日军提供经济支持。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05794babe3cf4eaab8a72c4140e0075e','3b38c866-b207-4e64-a575-cb72a820aead',1938,'六安本地士绅','六安本地士绅，日军占领六安期间出面组织维持会，为日军筹粮筹款，维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-538134fc092c4b1e9de5a32ecb1648f5','41355e85-71c7-4a5b-9701-2de3e25490d0',1940,'汪伪政权委任的六安县县长','汪伪政权委任的六安县县长，在六安沦陷区推行伪政令，配合日军清乡与保甲制度。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcc7a1040e7b4448af69dfee4a481a28','e6a36c0f-8c25-4073-bdce-057be529f7f5',1941,'六安本地伪军头目','六安本地伪军头目，率保安团配合日军扫荡六安周边抗日根据地，抓捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
