INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-070879e7d1cc4f74b3c5608a11e76760','5b32adef-e599-4f89-a551-b9434f66f83a',1940,'原国民党军将领','原国民党军将领，投敌后任伪军师长，活动于皖中、六安一带，配合日军扫荡抗日根据地，捕杀抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa5f318d04b54c268f6238021d95fb7b','5b32adef-e599-4f89-a551-b9434f66f83a',1940,'原国民党军将领','原国民党军将领，1943年率部投敌，任伪军师长，在皖中包括六安、霍邱一带配合日军清乡、扫荡抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d32b24de9c24eddb7ddcb732b846aad','22101f5d-74dd-47d7-883b-a2898aa7f7a2',1938,'六安本地士绅','六安本地士绅，日军侵占六安后出面组织维持会，任伪六安县长，为日军征粮拉夫、搜集情报，直接服务于六安沦陷区统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e90627c97c24342938d3682e406d28f','d85bb7f9-4a93-4316-a4e4-877c73f6ead9',1938,'在六安沦陷期间任伪警察头目','在六安沦陷期间任伪警察头目，协助日军维持治安，镇压抗日群众，搜捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-220d698914c94c8a8949646f55b6dc47','16918d96-86dc-44c3-a55f-2dd4a68b6ebb',1938,'金寨本地人','金寨本地人，日军侵扰皖西时出面组织维持会，为日军带路、筹粮，协助建立伪基层政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1504b08f7d7443e3841db9cf5c52bede','1bc8a04b-7ef8-4473-b6a4-eae056de78a8',1938,'霍山（邻近金寨）士绅','霍山（邻近金寨）士绅，投敌后组织维持会，配合日军对霍山、金寨边境地区的扫荡与物资掠夺。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9d1a9257a304470824b4f9122ebf3a8','b3aa378e-429b-4cd8-a0c7-a15d56ba3944',1940,'原地方武装头目','原地方武装头目，投日后被委为伪皖西保安司令，活动于六安、霍山、金寨交界地带，配合日军清剿抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce6d4a70b3d44a53bae62cca83d4f3e3','6b00cf7b-b7a0-4e2c-9547-ca5a8a0fe333',1941,'原国民党地方部队军官','原国民党地方部队军官，投敌后任伪军团长，驻防六安、叶集一带，多次配合日军进攻新四军根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-183514a922084ad7be9c3b09c8cd791f','fa90a800-98eb-45f7-8ac3-24e1b8c45531',1943,'原国民党军将领','原国民党军将领，投日后任伪军高级将领，其部队曾活动于安徽北部及皖西边缘，对六安、金寨抗日根据地构成威胁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9c774f145c04b2d91f67ae174427052','fa90a800-98eb-45f7-8ac3-24e1b8c45531',1943,'率部投敌后活动于皖北、鲁南一带','率部投敌后活动于皖北、鲁南一带，配合日军扫荡，其势力范围覆盖宿州、灵璧地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2d89c2a0e114b7c95c8d3566ab5b0cf','fa90a800-98eb-45f7-8ac3-24e1b8c45531',1943,'原国民党军将领','原国民党军将领，1943年投敌，率部在山东配合日军扫荡，其部队活动范围涉及鲁南地区。','危害等级C（丙级，基层头目）','hanjian');
