INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f37f7836ce841e0b00ffc80e304fc0d','b839b6c8-ae1a-4b3c-97d5-3c26d5f34afa',1943,'原国民党军将领','原国民党军将领，投日后任伪淮海省省长，其伪军活动范围包括安徽北部，对皖西六安、金寨一带抗日力量进行过封锁与扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
