INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48b5b6e562e34f278ca3bbcccdacea2d','e10bb867-7c7f-458a-be3b-72f59f2058a3',1942,'汪伪清乡系统官员','汪伪清乡系统官员，在安徽推行清乡运动，配合日军对六安、金寨周边抗日根据地进行封锁与蚕食。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f40f6b8fd8624f869522dbdcec1d6583','0923ca46-5ae3-42d1-993b-81ca556d50f8',1940,'汪伪政权核心人物之一','汪伪政权核心人物之一，曾任伪安徽省省长，推行日军“以华制华”政策，在安徽沦陷区实施保甲连坐、物资统制，配合日军对皖西抗日根据地的封锁与扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3fbb4a065d545a49c7abe5c369ecc72','cc245979-c825-4ae9-bb3b-dabd9a60a3d9',1940,'原国民党军将领','原国民党军将领，后率部投敌，在安徽、河南交界地区活动，配合日军进攻皖西抗日根据地，其伪军曾窜扰六安、霍山一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3597f1fe01e545e4a7f8173d5b114f1c','cc245979-c825-4ae9-bb3b-dabd9a60a3d9',1940,'原国民党军将领','原国民党军将领，后率部投敌，在安徽滁州、定远一带配合日军扫荡抗日根据地，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
