INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5645e88739c04d14a89e52256b40b664','444c769f-dbf3-4101-b240-8ac77c7fa765',1941,'率部投敌后','率部投敌后，其伪军势力曾扩展至湖南北部，与常德、临澧地区的伪政权有配合。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-baf1be1e5157461fbcda4d749486eb96','444c769f-dbf3-4101-b240-8ac77c7fa765',1941,'在华中投敌','在华中投敌，率伪军配合日军，其伪军网络对全国包括陕西抗日后方有破坏。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9aedb665fe1645738ba244a38ac3a83d','444c769f-dbf3-4101-b240-8ac77c7fa765',1941,'投靠日本','投靠日本，率部投降，在华中及华北包括陕西周边地区配合日军行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-713851f7c0d348bd950d4abe4cdf581e','e31b52f3-0bef-4b18-be0e-466f6bda20f6',1940,'汪伪政权官员','汪伪政权官员，曾任伪安徽省省长，在安徽沦陷区推行日军政策，征粮征丁，镇压抗日活动，其统治区域与六安、霍山周边沦陷区相邻。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef8f2bbd87ac482e81fbd85a2d284807','e31b52f3-0bef-4b18-be0e-466f6bda20f6',1940,'汪伪政权官员','汪伪政权官员，曾任伪安徽省省长，参与安徽沦陷区统治，其伪政权对安庆地区有管辖权。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df7e7c238c3840d2bbb9cb2829dc3f88','9272ae59-578b-454d-81c9-b065591344b9',1938,'汪伪政权官员','汪伪政权官员，曾任伪安徽省省长，参与安徽伪政权运作，协助日军维持占领区治安，推行保甲制度，对皖西抗日力量进行封锁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b4b315bbc0049b1ac64e21b464bdf8b','9272ae59-578b-454d-81c9-b065591344b9',1938,'汪伪政权要员','汪伪政权要员，曾任伪安徽省省长，在安徽沦陷区推行日军政策，其伪政权管辖范围包括蚌埠及五河一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
