INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-919458da2e344c32ad99bc719a324297','9e94b25a-f3dd-4154-afd7-fd71c47bfa6f',1938,'抗战期间投敌','抗战期间投敌，曾任伪安徽省省长等职，协助日军在安徽等地建立伪政权。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-adb4f157ebbc4ddc9162d4ea9aeb5057','9e94b25a-f3dd-4154-afd7-fd71c47bfa6f',1938,'湖北人','湖北人，抗战期间投敌，曾任伪安徽省省长，后调任伪湖北省省长。在安徽任内协助日军维持占领区，推行经济统制与物资掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
