INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9f03eb1cd994170b913509dc4a6c8de','7d77f3cd-c2aa-4444-84e3-7ca48c67a299',1938,'日军侵占六安期间','日军侵占六安期间，当地维持会负责人协助日军维持城区秩序、征粮征夫、登记户口，具体姓名因史料零散待考，但六安维持会作为伪组织在1938年日军第一次侵占六安时即已出现。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
