INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-523854ce7b1c40a58435cb7cbfcc76bf','ebdff8f6-d664-4abb-9e80-d584afaba71b',1939,'虽为国民党官员','虽为国民党官员，但抗战期间与日伪保持秘密联系，其部在皖西包括六安、霍邱一带与伪军有默契，纵容伪化活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
