INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a09e6f8e59e46ca9f83664df83aa984','3899f373-e6aa-4a23-a7f5-e5ec5757e9a1',1938,'原北洋军阀倪嗣冲之侄','原北洋军阀倪嗣冲之侄，1938年投敌，任伪安徽省省长，在合肥及皖中地区推行日伪统治，强征粮税，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ea3be5a6ec4454e9cc20bddb017237e','3899f373-e6aa-4a23-a7f5-e5ec5757e9a1',1938,'曾任北洋军阀倪嗣冲之侄','曾任北洋军阀倪嗣冲之侄，投敌后任伪安徽省长，在安徽推行日伪统治，协助日军清乡、征粮，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94f96209425345b183d986e05046d792','3899f373-e6aa-4a23-a7f5-e5ec5757e9a1',1938,'原北洋军阀倪嗣冲之侄','原北洋军阀倪嗣冲之侄，日军占领安徽后投敌，任伪安徽省长，推行奴化教育，协助日军在淮南、八公山地区掠夺煤炭资源，镇压抗日民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e152490e378463690dd612469d1456e','bab03a82-9373-4181-b7c4-d764d6570617',1938,'日军占领合肥后首任伪县长','日军占领合肥后首任伪县长，组织维持会，为日军提供劳役、情报，强征粮食，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a91757daabf8470ab35f07fe9a058b25','43c04569-bb70-498b-89e1-4ba697561194',1937,'合肥籍（一说安徽人）','合肥籍（一说安徽人），曾任伪华北政务委员会委员长，虽主要活动于北平，但利用其合肥背景影响皖中汉奸势力，为日军招降纳叛。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a353b75870f849089479e0bc232b6ffd','5cb480ee-8c56-4ebe-8413-e131601fae91',1940,'在任伪安徽省主席期间','在任伪安徽省主席期间，省会设于蚌埠，但管辖范围包括合肥地区，推行汪伪政权“清乡”政策，配合日军扫荡新四军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c64b9f27cc384c719ed38709a0f8890e','812e220b-8274-40e4-8076-a5ccdb9228e1',1943,'汪伪政权要员','汪伪政权要员，代理伪安徽省长期间，强化对合肥等地的伪化统治，组织伪保安队协助日军“治安肃正”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7df2281f3704cfe9480a437f85631f5','ae1b963c-43b4-4d4f-ae29-75eae606e299',1944,'汪伪宣传部长','汪伪宣传部长，1944年兼任伪安徽省长，虽未实际到合肥，但通过伪省府机构对合肥地区发号施令，推行奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c42d1acc1a04d1c849f71ba3e0760d4','a9b94b0c-3bbb-4f3c-95ed-3e14b134f0b5',1938,'日军占领合肥初期','日军占领合肥初期，组织维持会，为日军筹集物资、建立保甲制度，协助日军搜捕抗日分子。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-beb98460624e47c5b0a497090e9634f0','a9b94b0c-3bbb-4f3c-95ed-3e14b134f0b5',1938,'日军占领合肥后首任维持会长','日军占领合肥后首任维持会长，组织汉奸武装，为日军提供情报，强迫商户“欢迎”日军，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0a3e4444bff4509a216285201b67cdf','a9b94b0c-3bbb-4f3c-95ed-3e14b134f0b5',1938,'日军占领合肥后','日军占领合肥后，出任伪维持会会长，组织汉奸团体，为日军提供情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-319aa15e2d9f4e9f9258b965028f58c7','100fbbbe-f354-4155-9e15-ac852f867843',1940,'继林启生后任伪合肥县长','继林启生后任伪合肥县长，推行汪伪“新国民运动”，强征壮丁，为日军修建碉堡和公路。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ef7b0c610694fe3be63db212d8ab6f5','7a468085-7e6b-416b-acb6-1bf845c6c079',1938,'合肥籍汉奸','合肥籍汉奸，虽主要任职华北，但曾多次返皖为日军经济掠夺牵线，协助日商控制合肥米粮贸易。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c3f4a2004954e2b8531a81805ec43b9','d42bf36b-37c6-4746-b0e0-30b44a66bd5b',1941,'组织伪保安队','组织伪保安队，配合日军“扫荡”合肥西乡、南乡抗日游击区，杀害新四军交通员和群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08c4cfa836e944a3af45c66da61eed36','c446f9e4-c9d1-4473-8925-c58a862be4ec',1942,'负责伪安徽全省警察系统','负责伪安徽全省警察系统，在合肥设立伪警察分局，镇压抗日活动，抓捕地下党员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a010471577b4ad98ea175807913b4da','003fc81c-3131-47df-95cf-d19859f9f7f2',1939,'推行奴化教育','推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，迫害爱国教师。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8acafef67c0849fc9c5e6860dcb08420','1ca189cf-37f0-447a-bb43-4a3a8c7b1969',1938,'合肥沦陷后组织伪维持会','合肥沦陷后组织伪维持会，后任伪合肥县县长，为日军征粮、征夫、维持治安，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
