INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce6ccbce7af84b80b7fa8f7deed313a1','d2862845-140b-45a6-9fe1-305914846178',1933,'虽活动稍早','虽活动稍早，但曾密谋在安徽组织伪军，与日军勾结，影响合肥、肥东地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-53e283d2104b41e6b023b27910b7d8c5','6b9a9b17-edef-4ad5-b156-57974730ece5',1940,'投靠汪伪政权','投靠汪伪政权，任肥西县伪县长，协助日军推行“清乡”政策，强征粮税，镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a769a6e561ad42c28de5a099c0648564','e243a0f9-8927-405a-ab2a-28d4055262e4',1940,'原北洋政客','原北洋政客，后投敌任伪安徽省长，管辖包括合肥、肥西地区，推行奴化教育，配合日军“扫荡”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a80a0672e94458cb8c2a6a73adaecaf','c11df9c2-1473-42a2-8654-c5d9b06d3d56',1943,'继任伪安徽省长','继任伪安徽省长，在合肥、肥西一带加强伪政权控制，组织伪保安队协助日军清剿新四军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-53ecc24a69ef46c794153a1122159250','48159e04-4c43-4086-b8da-0758cc5ac0aa',1938,'日军占领合肥后出任伪县长','日军占领合肥后出任伪县长，为日军征夫派款，破坏抗日组织，迫害爱国人士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6041fb615ce458e9c0d5f2faa409538','a59df75f-7ff5-4788-a0e3-f21471ef7d58',1939,'组织伪保安队','组织伪保安队，在肥西地区多次袭击抗日游击队，抓捕并杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
