INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ecb5bdf2bac4696a38b13e582108cba','1c99e17b-a18e-4627-95b0-d4c1658547df',1941,'任伪区长期内','任伪区长期内，强征壮丁，推行保甲制度，向日军提供新四军活动情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ad83fb1b5b9452ebd34e527a18a9c6d','b9729a84-80fd-4299-9cc5-712b1c8f564e',1939,'效忠日军','效忠日军，指挥伪警察搜捕抗日地下党员，破坏中共肥西地下交通站。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad5e998b722546448cd56d6564baf45f','93e9d6e7-f60d-42e3-8e5f-926b71d10f2e',1942,'为伪政权征收苛捐杂税','为伪政权征收苛捐杂税，侵吞抗日家属财产，协助日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a5cd569b25c4ddca4d17ca7df28a7f9','6cd43655-9e70-400d-9020-34648f3e94de',1938,'投靠日军','投靠日军，任伪合肥县知事，协助日军推行‘治安强化运动’，强征粮税，镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29df43185d524030b4d89bf401a3b154','a78ecc36-1990-40df-9b6f-a4c11fe5832e',1937,'合肥人','合肥人，早年投日，任伪华北政务委员会委员长，虽主要活动于北平，但利用合肥籍身份影响皖中汉奸势力。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2542fc4ef72a476eacd9bace2334f75e','064b321f-4b0f-4400-8207-3a25d2481782',1938,'合肥本地士绅','合肥本地士绅，日军占领合肥后出任维持会会长，为日军筹粮、拉夫，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a9b51a50e494f758846d479b021a052','036d6aa0-a8df-4d19-ba06-3e56159e3e5e',1940,'合肥籍','合肥籍，虽名义为桂系将领，但暗中与日军勾结，在蜀山地区提供情报，协助日军扫荡新四军游击队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1faf6b7adb943f78bc6a7a2b0282997','317ef005-5048-46c8-981b-8785b6c75f6d',1940,'合肥人','合肥人，汪伪政权核心人物，虽常驻南京，但通过其亲信在合肥、蜀山地区发展伪组织，搜刮民财。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccb057ebf79f4d4f8ba7ab577e53c0d9','dba3db52-7aaf-4a25-a13d-4004c72784ac',1939,'原国民党警察','原国民党警察，投日后任伪警察局长，在蜀山一带抓捕抗日分子，残害百姓，为日军特务机关服务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-875bbd6a42904d3a80a6b5f3f0a1c243','fa9264a3-788d-44b9-a488-ee053de4bcda',1938,'合肥商人','合肥商人，投靠日军后控制商会，为日军统制物资，强迫商户‘献金’，资助伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89f3836610894f29a1fd70c85969a869','0a6798b8-d347-4dd7-9e03-e61c2590b100',1940,'在蜀山地区推行奴化教育','在蜀山地区推行奴化教育，删改教材，强迫学生参加‘中日亲善’活动，告发抗日师生。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
