INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4665d49df0e5448a94ccf3f394d320e5','91dc2c22-f938-44d1-b617-f5f62f1e8427',1940,'任伪警察局长','任伪警察局长，协助日军搜捕抗日地下党员，破坏中共地下交通站，镇压群众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9067fec849c4620a6b0aac6f4cb6ca3','115c6a18-b688-44bc-81f4-601f05896017',1938,'在长丰地区（今属合肥）组织伪维持会','在长丰地区（今属合肥）组织伪维持会，为日军带路，强征粮食，杀害抗日游击队家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e9f11296c334d6c9182a13c3e9e9ad0','833ffd66-e01d-4b89-81a1-8e7207c53d3e',1939,'充当汉奸商人','充当汉奸商人，为日军筹集军饷，垄断粮食贸易，向日军提供经济情报，协助掠夺当地资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4586dc841b0c49ba880969d827786093','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'虽为广东人','虽为广东人，但作为伪国民政府首脑，其政权控制范围包括安庆地区，推行“和平反共”政策，协助日军统治安徽沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bcc0685e7bb649ca92e42f7ee2d3de3c','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'虽为广东人','虽为广东人，但作为伪国民政府首脑，其政权控制范围包括安徽，安庆、大观地区在其统治下，推行汉奸政策，配合日军侵略。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb96f90e98bd478e8bc0e549c2b4d1a1','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'虽为广东人','虽为广东人，但作为伪国民政府首脑，其政权控制范围包括安徽，安庆迎江地区在其统治下，推行汉奸政策，协助日军进行殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98936cf50ba84ed69f05e5e5b6e0a1f3','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'虽非芜湖本地人','虽非芜湖本地人，但作为汪伪政权最高头目，其势力覆盖包括芜湖在内的沦陷区，推行“和平反共”卖国政策，协助日军统治安徽地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82ac873dacc14d77ae89ab26b0642e76','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'虽为广东人','虽为广东人，但其伪政权统治范围包括安徽，其亲信在芜湖鸠江地区推行汉奸政策，组织伪军和特务活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6623ddd57314804b88fdf1c83cad907','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'汪伪政权最高头目','汪伪政权最高头目，其伪政权体系覆盖广东汕头等沦陷区，推行全面附日政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
