INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb5ebd71807a4d7fb8b6f3a20831bd22','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'建立汪伪政权','建立汪伪政权，其伪广东省政府管辖范围包括湛江地区，推行亲日卖国政策，为日军侵略服务。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79847ec49cb04381a2abc0e2a5f3b988','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'虽为全国性汉奸','虽为全国性汉奸，但与江苏地区伪政权关联密切，其伪府设在南京，对江苏包括南通、如东地区有管辖影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
