INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf3900ab10ae4ce0b2f2445b333c245c','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'伪政权首脑','伪政权首脑，其政策覆盖浙江宁波余姚，推动与日军全面合作。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
