INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ccb3dd7e89b4371af8e671f453fee2b','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'在南京建立伪政权','在南京建立伪政权，其势力曾渗透至重庆、万州等地，发展伪组织成员。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fbe47be1c2c49fea9c1e52072c8f090','891f31e6-005f-438d-b72f-456c7f7a8029',1938,'建立汪伪政权','建立汪伪政权，推行亲日政策，签订卖国条约，1944年病死。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
