INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d140fbd541b4abb8266bd9a904b3da3','0cb61133-2e02-4a03-9ec0-dec07c686e72',1938,'湖南长沙人','湖南长沙人，汪伪特务头子，虽主要活动于上海、江苏，但作为湖南籍汉奸，其特务网络对湖南沦陷区有渗透。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-089eaf0d0ea1490da0261df420eea8e1','0cb61133-2e02-4a03-9ec0-dec07c686e72',1938,'湖南籍汪伪特务头目','湖南籍汪伪特务头目，虽主要在沪苏活动，但其特工网络延伸至湖南部分沦陷区，与湖南地区伪政权有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f274f5ae529f4cf4b84d8ecba4e3ed06','0cb61133-2e02-4a03-9ec0-dec07c686e72',1938,'浙江遂昌人','浙江遂昌人，汪伪特务头目，其特工网络延伸至湖南部分沦陷区，进行侦缉、镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b41801af8c894456a50e4f6938c7a405','0cb61133-2e02-4a03-9ec0-dec07c686e72',1938,'浙江遂昌人','浙江遂昌人，早年加入中共后叛变，抗战期间投靠汪伪，组建汪伪特工总部（76号），任伪江苏省主席等职，其特工网络活动范围涉及华中沦陷区，对湖南籍抗日人员亦有侦捕。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
