INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d11c591613464fa1a934ba3a8fb5ff79','0cb61133-2e02-4a03-9ec0-dec07c686e72',1938,'浙江遂昌人','浙江遂昌人，汪伪特务头子，其特务网络延伸至湖南部分沦陷区，与湖南伪政权有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
