INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6053f62a767b4f599aaf08029b9c37d1','d164e152-2c4d-42a6-a595-74ca2d78e41f',1940,'湖南人','湖南人，汪伪政权核心成员，曾任伪安徽省省长、伪司法行政部长等职，在安徽推行伪化统治，配合日军清乡与掠夺，滁州地区在其伪省政管辖之下。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
