INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c99284ead42e46fa94aa8114fbfef34f','d164e152-2c4d-42a6-a595-74ca2d78e41f',1940,'湖南人','湖南人，早年加入中共后叛变，抗战期间投靠汪精卫政权。曾任伪安徽省省长、伪司法行政部长等职，在安徽推行伪政权的行政与治安措施，配合日军对抗日根据地的封锁与扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
