INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0a2585cf06d4afb990fc254820dc91b','d164e152-2c4d-42a6-a595-74ca2d78e41f',1940,'汪伪政权要员','汪伪政权要员，曾任伪安徽省省长，在安徽实施伪政，配合日军经济掠夺和治安强化运动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b8fa6ddab7f4c21b6d087eace173d23','d164e152-2c4d-42a6-a595-74ca2d78e41f',1940,'汪伪政权成员','汪伪政权成员，曾任伪安徽省省长，在安徽地区推行日伪法令，配合日军征粮、清乡，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5adac3dfbfb646c5845d68f1ad785e1a','d164e152-2c4d-42a6-a595-74ca2d78e41f',1940,'汪伪政权高官','汪伪政权高官，曾任伪安徽省省长，在安徽实施伪政，配合日军征粮、清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d64abe0d9dd427ab8af621e7cb7e529','76770e1e-0422-4ef5-9fee-06cf0dc6fba8',1938,'安徽合肥人','安徽合肥人，北洋政客。抗战后投敌，曾任伪临时政府内政部长、伪安徽省长、伪华北政务委员会委员长等职，在安徽及华北推行日军殖民统治，战后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf6fba7f91374fd5bba08fc05ffcd9d3','76770e1e-0422-4ef5-9fee-06cf0dc6fba8',1938,'安徽合肥人','安徽合肥人，投敌后曾任伪安徽省长，其伪政权影响宣城地区，推行奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-947aad9a6b0a4a5ead8d0b5c1ac35bfe','76770e1e-0422-4ef5-9fee-06cf0dc6fba8',1938,'安徽合肥人','安徽合肥人，北洋旧官僚，抗战期间投敌，曾任伪安徽省长。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd55f2413efe4f39b37027867b32dd2e','76770e1e-0422-4ef5-9fee-06cf0dc6fba8',1938,'北洋政客','北洋政客，抗战期间投敌，曾任伪安徽省长，在安徽沦陷区推行亲日政策，协助日军征粮、清乡，滁州、凤阳等地在其伪省政权影响范围内。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64161ea0e68f4cefa34deca22787aba0','76770e1e-0422-4ef5-9fee-06cf0dc6fba8',1938,'安徽合肥人','安徽合肥人，北洋政客，抗战后投敌，曾任伪安徽省长，参与安徽沦陷区伪政权，其影响波及滁州地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1a9d1e9f67c4d89ae9582b4843ca147','95148c31-8468-428b-8f77-3cb4ff8a324b',1938,'安庆沦陷后投敌','安庆沦陷后投敌，组织伪保安队，长期在安庆、怀宁、桐城一带活动，配合日军扫荡、征粮、抓丁，残害抗日群众，是安庆地区有记载的伪军头目之一。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5a26a9d3f0b4299b3df616449eceaa5','ffd5f93f-0db2-47e8-89e8-3bf3f2583719',1938,'怀宁本地士绅','怀宁本地士绅，1938年安庆沦陷后出面组织伪怀宁县维持会，后任伪怀宁县知事，为日军征粮、派夫、维持治安，是怀宁地区直接附逆的地方伪政权头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b5d0265b790466a8056d2de85602de0','36230da4-1b1b-40db-86f1-cf1e96c777c7',1938,'安庆沦陷初期出面组织伪安庆维持会','安庆沦陷初期出面组织伪安庆维持会，协助日军维持城区秩序、征发物资、登记户口，是安庆城区早期汉奸组织负责人之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-088550dfeae44196931977e4c46e25bc','00d597f9-9d89-4a22-b17e-a33c3b4af8e3',1938,'安庆商界人物','安庆商界人物，抗战期间与日军合作，主持伪商会，为日军筹款筹粮、控制物资流通，并参与伪维持会活动，属经济领域附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aabd4435e54249188b5dc4f3e6064f7c','51ab2500-b280-45a0-9f5f-805ec3ef37ed',1940,'汪伪政权时期曾任伪安徽省政府委员','汪伪政权时期曾任伪安徽省政府委员，并一度出任伪怀宁县长，在怀宁推行保甲、征粮、奴化教育，配合日军对安庆周边地区的控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19e3260cef994ee2a91f5b9ce867f6df','9c95e60a-bdce-4fea-b806-02d834c8015f',1941,'汪伪政权在安庆地区推行清乡运动时的重要执行者','汪伪政权在安庆地区推行清乡运动时的重要执行者，负责组织伪军警配合日军扫荡抗日武装，在怀宁、桐城、潜山交界地区实施保甲连坐与物资封锁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb8b59d1a7cc446da0e61175f2f47609','c9e77153-baab-435f-b01f-610bd724b2a6',1939,'抗战期间在怀宁附逆','抗战期间在怀宁附逆，主持伪教育行政，推行日语教学与亲日奴化教育，组织学生参加日军宣传活动，属教育文化领域汉奸。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ac484fd08704ff0a6ec788cefdd5a16','641abceb-c36e-47a5-a567-471c9d3bbb62',1938,'安庆沦陷后任伪警察局长','安庆沦陷后任伪警察局长，统领伪警察配合日军搜捕抗日人员、镇压市民反抗、管制交通与物资，是安庆城区伪警特系统的主要负责人。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a98fc493355404eb9cd16ed9e1dcf4e','9e03fc0b-b006-4713-bc26-dd7e580f40a4',1939,'怀宁本地人','怀宁本地人，投敌后任伪保安大队长，率伪军配合日军在怀宁石牌、高河、月山等地清剿抗日游击队，强征民夫与粮食，民愤较大。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e149853d543d4d1cbaf2bfb0f2c70c42','c0f21925-3bc8-4535-9bae-892cdf13530f',1940,'汪伪政权在安庆的文化宣传负责人','汪伪政权在安庆的文化宣传负责人，主办伪《安庆日报》，为日军侵略张目，宣传“大东亚共荣圈”，属文化宣传领域附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5829554d09094c968996ec675a75cc9f','05e5a8b0-a4a0-4470-ba25-502803ca97cd',1938,'原北洋及国民政府官员','原北洋及国民政府官员，抗战后投敌，曾任伪安徽省长，参与组织安徽沦陷区伪政权，后调任伪湖北省长，是华中地区重要汉奸之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ba05a62d8744e9f80e6a28d9e3ba517','3e3b95ce-eb33-4f15-a7c2-7e88f486d6b8',1940,'原社会党领袖','原社会党领袖，抗战后投靠汪伪，曾任伪安徽省长、伪考试院长等职，在安徽推行伪政权政策，战后被判处无期徒刑。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29e0d8ba6ac04539af830f91489d16be','3e3b95ce-eb33-4f15-a7c2-7e88f486d6b8',1940,'文化汉奸','文化汉奸，曾任伪安徽省长，在安徽推行奴化教育，宣扬“和平反共建国”，其伪政权影响覆盖池州等皖南地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f5ec2f0b45b4e7a9e6a5e01f1dae912','9037fd15-047d-423f-a791-5b04ee2f611d',1939,'负责安庆沦陷区伪税务','负责安庆沦陷区伪税务，为日军及伪政权搜刮民财，征收苛捐杂税，控制粮食与食盐专卖，属经济领域附逆者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c878cc1d6274f92bb5f6e371647648d','8bdbcde0-0416-4566-b0b4-165f0b281a2f',1940,'在怀宁组织伪合作社','在怀宁组织伪合作社，配合日军统制物资，低价强购农产品、高价配给日货，剥削沦陷区民众，属经济附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bed6053f5ee349119701ea20f2e3d1ff','138bf1a3-40c3-4e5c-89e4-63764e4de3a6',1938,'安庆沦陷后出面组织伪维持会','安庆沦陷后出面组织伪维持会，后任伪怀宁县县长，协助日军维持治安、征发物资，是安庆地区早期汉奸头目之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a0f2a90a8f649769c55e15e7e0f4fae','f717b1d4-11da-44f8-949b-27f01f940fa7',1938,'望江沦陷期间出面组织伪维持会','望江沦陷期间出面组织伪维持会，为日军征粮征夫、搜集情报，协助日军控制望江地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-233f823f89914854b79b7e77112fffc0','5b9f95ab-7a12-4bbc-8f30-399205010ba7',1938,'在安庆沦陷区担任伪警察头目','在安庆沦陷区担任伪警察头目，配合日军搜捕抗日人员、镇压民众，维护日伪统治秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4a415d3dc6b4595a5829ef213bcd369','6266c1b7-bb30-4db2-915d-dbdce592479d',1938,'安徽沦陷区伪政权要员','安徽沦陷区伪政权要员，参与伪安徽省政，协助日军推行保甲制度、征发劳役。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7f1783c03e041c79b053c4c7a612d5e','6f4563aa-1611-45cb-8086-d13da5722bf7',1938,'在安庆沦陷区推行奴化教育','在安庆沦陷区推行奴化教育，编写亲日教材，组织学生参加日伪宣传活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb9cd1c9e36e48768a04fe901e17a23f','76b0c71c-364f-4a37-a9ec-fdcd16a0e498',1940,'望江本地投敌分子','望江本地投敌分子，组织伪保安大队，配合日军扫荡望江、太湖一带抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38f25a5499b94c29be3583a5d8ac70cd','3339554c-0dca-404a-ba02-48fdb19e3da4',1938,'桐城沦陷期间组织伪维持会','桐城沦陷期间组织伪维持会，为日军筹粮筹款，维持地方伪秩序，协助日军控制桐城地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac889d4b6ee54a1180257e40039a9fdc','e722cdb4-99d4-4f23-8087-104b3880e9ab',1939,'原国民党军官','原国民党军官，投敌后任伪安徽省保安司令等职，率伪军配合日军在安徽包括安庆地区进行清乡与扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb6f5d065b8c4d79b0af18019d472113','ed044904-48de-4654-bdbe-a6d417454a25',1938,'抗战期间投敌','抗战期间投敌，在安徽沦陷区统领伪军，配合日军维持治安，镇压抗日武装，活动范围涉及安庆周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7893090d87794a79bfe070574b3323c0','fdbfe9e7-36e9-496e-84b9-5c8b243986b7',1938,'福建人','福建人，投敌后参与伪维新政府，曾任伪安徽省民政厅厅长，协助日军在安徽建立伪政权体系，包括安庆、桐城等地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7810af1292640a784245c9bb4b5b9eb','0a3f2d88-014e-4f06-82aa-76f9d1318ed9',1940,'原社会党人','原社会党人，投敌后任伪安徽省教育厅厅长，推行奴化教育，后任汪伪考试院院长，其教育政策覆盖安庆、桐城等沦陷区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9aa0954813041b98e2cb87b3c54a2ad','0f176b25-b2bc-4fd5-a0bb-afeb7f6e9cae',1939,'汪伪特工骨干','汪伪特工骨干，参与在安徽沦陷区的暗杀与镇压活动，其行动范围包括安庆一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2dfb3478e5b54f99a12f57076b550fc4','1f2de6d8-f29c-4cf8-a746-dd7cf278862b',1938,'原西北军军官','原西北军军官，投敌后统领伪军活动于豫皖地区，与安徽沦陷区包括安庆有军事配合。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0174720874544cfc9d067e7d8940d98b','1f2de6d8-f29c-4cf8-a746-dd7cf278862b',1938,'河南柘城人','河南柘城人，投敌后组建伪军，活动于豫东、皖北，与滁州地区日军有协同扫荡行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7e7d62dd29e411b90482db3a1815990','1f2de6d8-f29c-4cf8-a746-dd7cf278862b',1938,'河南柘城人','河南柘城人，投日后所部伪军活动于豫东、皖北，与安徽沦陷区日伪政权配合，参与对皖东抗日根据地的封锁与扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c68d939398da428fad6c8fe242493f79','1f2de6d8-f29c-4cf8-a746-dd7cf278862b',1938,'河南人','河南人，投敌后组建伪军，活动于豫皖苏边区，其势力范围一度覆盖安徽滁州、明光等地，配合日军清乡与掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4557b9df1c064979bb16327d8053dccb','1f2de6d8-f29c-4cf8-a746-dd7cf278862b',1938,'原国民党军将领','原国民党军将领，1943年投敌，所部伪军活动于安徽北部、河南东部，配合日军作战。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
