INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96d44df66fef4fa7836d3a4ee9f45e90','9efb5903-60eb-4767-a3da-96d3ba31a15a',1939,'为日军筹款、采购物资','为日军筹款、采购物资，控制安庆商业，在迎江地区剥削商户。','危害等级C（丙级，基层头目）','hanjian');
