INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3b17dbb027e4acfb282a074e99e3329','76089d86-7326-49c3-bb33-c986d33f773d',1942,'率领汉奸特务','率领汉奸特务，在迎江地区刺探抗日情报，逮捕并酷刑审讯抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43ee4f2a761d4deba6ae6696689e97ce','406d40b7-0452-47d2-a10b-267b4d507f32',1938,'追随汪精卫投敌','追随汪精卫投敌，历任伪立法院院长、伪上海市长、伪行政院院长等职，1944年汪精卫死后继任伪国民政府主席，继续推行卖国政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3b12e219c2a4918b9b339cc248fa9f9','406d40b7-0452-47d2-a10b-267b4d507f32',1938,'随汪精卫投敌','随汪精卫投敌，历任伪立法院院长、伪行政院院长等职，汪死后继任伪国民政府主席，继续推行附日伪化统治，其伪政权覆盖安徽沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80cb7707ce864d618fc2f21fba14fce4','6fb72198-7e34-48f9-98c7-73545feab4e4',1938,'汪伪政权核心人物之一','汪伪政权核心人物之一，曾任伪财政部长、警政部长、上海市长等职，掌控伪政权财政与特务系统，参与对安徽等沦陷区的控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2094067920414e4c8c271a2d417bd6f3','6fb72198-7e34-48f9-98c7-73545feab4e4',1938,'汪伪政权核心人物之一','汪伪政权核心人物之一，掌管伪财政与警政，参与伪政权对包括安徽在内沦陷区的统治与搜刮。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
