INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fca2b2aa6dcc4e65af3e62fd5142e98a','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会要职，其伪政权管辖范围包括河南北部，推行奴化教育、经济掠夺，支持日军统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96b1d64b67fe4eb9877f2eadbfcfab67','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'安徽合肥人','安徽合肥人，长期在华北伪政权中任职，其伪华北政务委员会管辖范围包括河南北部及部分中部地区，对河南伪政权体系有统辖影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88221b9ca5ca479ead7a03c3509279a0','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'安徽合肥人','安徽合肥人，北洋余孽，抗战期间投靠日军，任伪华北政务委员会委员长，其伪政权管辖包括河南北部及中部，对河南沦陷区包括驻马店一带实施伪化统治，推行保甲、征粮。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13286bdb8c8c41318812257ab20cd724','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'安徽合肥人','安徽合肥人，北洋旧官僚，抗战期间投靠日本，任伪华北政务委员会要职，其伪政权对河南沦陷区包括驻马店一带实施间接统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2378e54dad1f4897a4caa047be3adc73','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'安徽合肥人','安徽合肥人，华北地区头号汉奸之一，虽非咸宁籍，但其伪政权体系覆盖湖北部分沦陷区，影响涉及咸宁周边。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f9f4262570c4f1fa68652b58b5ed143','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'安徽合肥人','安徽合肥人，但与湖北黄冈地区有活动关联，曾参与伪政权对湖北的渗透，推行亲日政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4384a34570a04f3f87227e88cbe64dc6','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'安徽合肥人','安徽合肥人，但在湖北黄冈一带亦有活动记录，投靠日军，参与伪政权，推行奴化教育。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96c5a641318b4b979c0898518d644f91','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'安徽合肥人','安徽合肥人，北洋余孽，抗战后投敌。虽主要在华北活动，但其伪政权体系与湖北黄冈、黄梅一带的伪组织有人员交流与政策联动，黄梅伪维持会曾受其伪内务总署指导。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
