INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-316a7cfbb06b483b8756b31b71ee2ad1','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'北洋政客','北洋政客，抗战期间投靠日本，历任伪临时政府内政部长、伪华北政务委员会委员长等职，推行保甲连坐、经济统制，配合日军扫荡华北抗日根据地，对包括陕西在内的华北地区实施殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93363054d7c14a9db125f2bcb17d99ed','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'投靠日本','投靠日本，参与伪华北政权，协助日军在华北包括陕西周边地区进行殖民统治和经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12f31b2e544b48b38a01b94bb28e30ec','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'华北著名汉奸','华北著名汉奸，参与组织伪临时政府，推行日军侵略政策，镇压抗日活动，对包括陕西在内的华北民众实施残暴统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4699a2ef75034309acd11504a52e5461','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'华北地区最高伪政权头目之一','华北地区最高伪政权头目之一，其伪政权体系延伸至陕西黄河沿岸部分日占区，榆林、神木一带的伪维持会、伪警察系统多受华北伪政权影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19f6a82cc9a04cf2b889c677e7dcb9cd','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'投靠日本','投靠日本，参与伪华北政权，推行奴化教育与经济掠夺，其伪政权体系延伸至陕西邻近地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-580888c78ef94be58ea4ca2101f557ba','040e5b61-516c-4c5e-90a6-93181ca02ae0',1937,'投靠日本','投靠日本，参与伪华北政权，推行奴化教育与经济掠夺政策，其伪政权体系延伸至华北各地，与陕西地区有间接统治关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
