INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10b7862b12474f0d8a72a54d3604754c','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽籍（祖籍婺源','安徽籍（祖籍婺源，生于广东三水），1938年12月发表艳电公开投日，1940年在南京成立伪国民政府，自任主席兼行政院长，统辖包括安徽在内的华中沦陷区伪政权，是抗战时期最大汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f399924a9a1405498dd6c13cbdc37ba','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽籍（祖籍婺源','安徽籍（祖籍婺源，生于广东三水），抗战期间叛国投敌，在南京建立伪政权，其伪政权统治范围覆盖安徽及宣城地区，是抗战时期最大汉奸头目。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e140295a0326487b8c8972954bf82aee','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽籍（祖籍婺源','安徽籍（祖籍婺源，生于广东三水），抗战期间投靠日本，在南京建立伪政权，其伪政权统治范围覆盖安徽宣城一带，推行奴化教育与经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83171ef0a51c4b95af0d4f2e09dd96f5','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽籍（祖籍安徽婺源','安徽籍（祖籍安徽婺源，今属江西），在南京建立汪伪政权，统辖包括安徽在内的沦陷区，其伪政权在宣城、旌德周边地区推行伪化统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-756575f1741d44e6a09d8e418860d359','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽绩溪人（祖籍婺源','安徽绩溪人（祖籍婺源，生于广东三水，籍贯安徽绩溪），抗战期间投靠日本，在南京建立伪政权，任伪国民政府主席，是抗战时期最大汉奸之一。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5adae1511def4600a72398e4de16a675','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽籍（祖籍婺源','安徽籍（祖籍婺源，生于广东），抗战期间投靠日本，在南京建立伪政权，其伪政权统治范围覆盖安徽及宣城地区，推行奴化教育与经济掠夺政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-191ed1fd8493423e9ea255ccec1248b4','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'原国民党副总裁','原国民党副总裁，1938年12月公开投敌，1940年在南京成立伪国民政府，自任主席兼行政院长，全面配合日本侵华，推行‘和平反共建国’路线。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc50aa6cad81449f872ff53103cdc49f','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽婺源（今属江西','安徽婺源（今属江西，邻近休宁）人，祖籍浙江山阴。抗战期间叛国投敌，在南京成立伪国民政府，自任主席，推行‘和平反共建国’路线，与日本签订卖国条约，是抗战时期最大汉奸。其伪政权势力覆盖安徽及黄山、休宁地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f65ca5719ab4ae6b56281b4f2c0fc8e','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽婺源（今属江西）人','安徽婺源（今属江西）人，祖籍浙江山阴，出生于广东三水','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26ec0ace8f094eebb8caf0b6fe096259','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'抗战期间叛国投敌','抗战期间叛国投敌，在南京建立伪政权，是最高级别的汉奸，其伪政权统治范围覆盖安徽，对黄山、屯溪地区亦有名义上的管辖。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a109a88dc2c4b4db44f701279c757f5','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽籍（祖籍婺源','安徽籍（祖籍婺源，今属江西，但长期与皖南徽州地域关联），1938年公开投敌，1940年在南京成立伪国民政府，任主席兼行政院长，是抗日战争时期最大汉奸政权首脑。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b111f8cacd1645ad868cae937d5a1520','0b880c2a-94f4-4d4a-98d7-e09034e2cef9',1938,'安徽籍（祖籍徽州婺源','安徽籍（祖籍徽州婺源，邻近黄山黟县），抗战期间投靠日本，在南京建立伪政权，任伪国民政府主席，推行亲日卖国政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66cb9d4e90954a54873108e364ae2c66','de633d49-b09f-4723-8870-e706ae9f703e',1938,'随汪精卫投敌','随汪精卫投敌，历任伪立法院长、伪上海市长、伪行政院长，汪死后继任伪国民政府主席，统辖包括安徽在内的沦陷区伪政。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32695faca5dd483b808fe41ae6d8fba8','de633d49-b09f-4723-8870-e706ae9f703e',1938,'随汪精卫投敌','随汪精卫投敌，任伪职，其伪政权政令下达至安徽宣城地区，协助日军征粮、清乡。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-027561d1aae844d988b3b8792e017573','de633d49-b09f-4723-8870-e706ae9f703e',1938,'汪伪政权核心人物','汪伪政权核心人物，参与伪政权对安徽等沦陷区的统治，战后以汉奸罪被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dedfe351a6584233bfbaad80dfea05a6','de633d49-b09f-4723-8870-e706ae9f703e',1938,'汪精卫死后继任伪国民政府主席','汪精卫死后继任伪国民政府主席，安徽宣城泾县人，随汪投敌，参与伪政权核心决策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4609ca3ec244c23b4f22cf71e9232db','de633d49-b09f-4723-8870-e706ae9f703e',1938,'广东乳源人','广东乳源人，汪伪政权重要头目，汪精卫死后继任伪国民政府主席，其伪政权对安徽沦陷区包括皖南部分地区有管辖权。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68538af4046e41dcbdd0cb99cf18ddb8','de633d49-b09f-4723-8870-e706ae9f703e',1938,'广东乳源人','广东乳源人，随汪精卫投敌，历任伪立法院长、伪行政院长，主持伪政权日常事务，其伪政权体系涉及江西沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e8856b3eb96419ea61a647a8006a0d5','b0d4eb4f-d12e-44e1-8bf8-94985d3bef80',1938,'汪伪政权核心人物','汪伪政权核心人物，掌管伪财政与警政，其伪警政系统延伸至安徽沦陷区各县伪警察局。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-743be3319f96418691355d3375b27e46','b0d4eb4f-d12e-44e1-8bf8-94985d3bef80',1938,'汪伪政权核心成员','汪伪政权核心成员，其伪政权体系覆盖安徽沦陷区，参与对包括宣城地区在内的沦陷区控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7934a4f151f4568bcc81dfe1fff3ec6','b0d4eb4f-d12e-44e1-8bf8-94985d3bef80',1938,'安徽绩溪人','安徽绩溪人，汪伪政权核心成员，掌管伪财政与特务系统，后任伪上海市长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff00dcbbdfba4742845ef1b3ccf1e3a2','b0d4eb4f-d12e-44e1-8bf8-94985d3bef80',1938,'安徽绩溪人','安徽绩溪人，随汪精卫投敌，在伪政权中历任要职，参与对安徽等沦陷区的控制与经济搜刮。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1ff18a7e73e496e9129d21dd5b0fc78','b0d4eb4f-d12e-44e1-8bf8-94985d3bef80',1938,'安徽绩溪人','安徽绩溪人，汪伪政权核心人物之一，曾任伪财政部长、警政部长、上海市长，掌握伪政权财政与特务系统，1946年以汉奸罪被判死刑后改无期，死于狱中。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4268136538174614a2ae0bf6cb1f35fb','b0d4eb4f-d12e-44e1-8bf8-94985d3bef80',1938,'安徽籍（祖籍徽州）','安徽籍（祖籍徽州），随汪精卫投敌，任伪政权要职，参与对日媾和与伪政权运作。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-057e6bc1e51942ec9f862013ff40409b','b0d4eb4f-d12e-44e1-8bf8-94985d3bef80',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物，历任伪财政部长、伪警政部长等职，其伪政权经济掠夺政策覆盖河南沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24fecf7241214206a684712f26f3cf8e','b0d4eb4f-d12e-44e1-8bf8-94985d3bef80',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心成员，参与伪政权对包括河南在内的沦陷区进行经济掠夺和特务统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44bd39aaea4948a18b514587838fefaf','b0d4eb4f-d12e-44e1-8bf8-94985d3bef80',1938,'湖南沅陵人','湖南沅陵人，抗战期间投靠汪精卫伪政权，历任伪财政部长、伪警政部长、伪上海市长等职，是汪伪政权核心人物之一，其家乡沅陵属怀化地区，与怀化有直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff20e7a074f6449ea705bc3fce3419e6','ab060cf7-6952-4ddb-be4d-6bf0d315f919',1938,'安徽阜阳人','安徽阜阳人，北洋时期政客，抗战后投敌，历任伪安徽省长、伪安徽省政府主席，主持安徽沦陷区伪政，推行保甲、征粮、拉夫。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2089d0076df2473b9e8f0ea3fdcb8b65','ab060cf7-6952-4ddb-be4d-6bf0d315f919',1938,'安徽阜阳人','安徽阜阳人，抗战期间投敌，历任伪安徽省长、伪安徽省政府主席等职，在安徽沦陷区推行伪化政策，其统治范围涉及黄山、休宁地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9078456023594291855eaff33a1bb1e8','ab060cf7-6952-4ddb-be4d-6bf0d315f919',1938,'安徽阜阳人','安徽阜阳人，抗战期间投敌，历任伪安徽省长、伪安徽省政府主席，在安徽沦陷区推行伪化统治，配合日军“清乡”与掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db059d7195fa4317a177b3f3df84db6d','ab060cf7-6952-4ddb-be4d-6bf0d315f919',1938,'安徽阜阳人','安徽阜阳人，抗战期间任伪安徽省长，在安徽沦陷区推行伪化统治，配合日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e992abde19734510a63e91cb5d28c832','aba394ec-7309-42e2-867c-f50088bb6dee',1938,'曾任伪维新政府绥靖部长、伪安徽省长','曾任伪维新政府绥靖部长、伪安徽省长，主持安徽沦陷区伪政，配合日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4cb5743758f54756a9f4b7d552975b4a','aba394ec-7309-42e2-867c-f50088bb6dee',1938,'在汪伪政权中历任伪安徽省长等职','在汪伪政权中历任伪安徽省长等职，负责安徽沦陷区行政，宣城地区在其管辖范围内。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9c1097a6e8741d88c4ab5c95de29245','aba394ec-7309-42e2-867c-f50088bb6dee',1938,'历任伪维新政府、汪伪政权安徽省长','历任伪维新政府、汪伪政权安徽省长，在安徽沦陷区推行伪化行政，宣城地区在其伪省政管辖范围内。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff952082674a44639b408606159a74ad','aba394ec-7309-42e2-867c-f50088bb6dee',1938,'伪维新政府及汪伪政权官员','伪维新政府及汪伪政权官员，曾任伪安徽省长，在安徽推行伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4218a9480ac345e0835e5de87d43219b','aba394ec-7309-42e2-867c-f50088bb6dee',1938,'在汪伪政权中历任伪安徽省长等职','在汪伪政权中历任伪安徽省长等职，直接参与对安徽沦陷区包括宣城地区的统治与镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37b110f841714323a0f263536270d2ba','aba394ec-7309-42e2-867c-f50088bb6dee',1938,'抗战期间投敌','抗战期间投敌，历任伪维新政府绥靖部长、伪安徽省长、伪江苏省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
