INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e4b04b1d27942918b8e7f94988d349d','53ec3052-9228-4d16-b451-95b895d1da35',1938,'池州沦陷后出面组织伪维持会','池州沦陷后出面组织伪维持会，任会长，协助日军建立伪政权，征发民夫、物资，推行保甲制度，为日军统治池州地区服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-232421825b5c4ff489ac6df601372dd5','b23c9f0c-aa29-4c50-8a89-3ac484e01799',1939,'汪伪政权委任的伪贵池县知事','汪伪政权委任的伪贵池县知事，在贵池（今池州）地区推行伪化行政，配合日军清乡，镇压抗日活动，征收赋税供给日军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f73f28e37d684dacbd42ddc42b837e7d','84d58ef1-d065-4522-be90-88e9be6026e3',1940,'东流（今属东至县）人','东流（今属东至县）人，投靠日军后任伪东流县知事，在沿江地区协助日军封锁长江，搜刮民财，镇压抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a3d91fd819349f8b0b68d3b70d60b4c','fd502ca7-7721-4071-97d5-75a88ac1b939',1941,'至德（今属东至县）本地武装头目','至德（今属东至县）本地武装头目，率部投敌后被编为伪至德县保安团，任团长，配合日军对东至山区进行扫荡，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca7c8a99995a48c3973449dc81a9d43f','ea0b2ce1-4f47-45f4-82b5-53e5a16e8b27',1942,'汪伪政权皖南行署主任','汪伪政权皖南行署主任，驻芜湖，管辖皖南包括池州、东至在内的伪政权，推行日军殖民政策，组织伪军配合扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae369de22f1a47449cbbe7feb41b4a5c','6ef51850-dd7a-4d6a-892b-ae9da185eed3',1943,'汪伪清乡委员会派驻池州地区的专员','汪伪清乡委员会派驻池州地区的专员，负责在贵池、东至、青阳等地推行清乡运动，建立伪保甲联防，搜捕抗日分子。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fe64c6fa1f146988316f1600469c014','59fb2d86-ba4d-4851-94a9-d235e0894774',1938,'原为北洋军人','原为北洋军人，抗战后投敌，曾任伪维新政府绥靖部长、伪安徽省长、伪安徽省政府主席，在安徽沦陷区推行伪化统治，配合日军清乡与掠夺，池州一带伪政权亦受其节制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef704a58eaad4971abfbfaabf1636503','59fb2d86-ba4d-4851-94a9-d235e0894774',1938,'原为北洋及国民政府官员','原为北洋及国民政府官员，抗战后投敌，曾任伪安徽省长、伪安徽省政府主席，参与汪伪政权在安徽的统治，配合日军清乡与掠夺，其伪政权体系延伸至皖南池州等地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f73765599c14e18a7c776f1ff105ce3','59fb2d86-ba4d-4851-94a9-d235e0894774',1938,'原为北洋及国民政府官员','原为北洋及国民政府官员，抗战期间附逆，曾任伪维新政府绥靖部长、伪安徽省长、伪安徽省政府主席等，参与安徽沦陷区伪政权建设与治安强化运动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4c49b3f93aa4d4594942896c8006e38','4964b710-8f0e-4dd0-8172-9d89ef7b6c73',1943,'原国民党军将领','原国民党军将领，1943年在皖南率部投敌，任伪皖南独立方面军总司令，盘踞芜湖、宣城、池州一带，配合日军进攻新四军，残害抗日军民，是皖南地区重要汉奸武装头目。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-781ea48510da4897acdf77fe0a8f9ea0','f45df444-fd8c-4881-84b4-3f0f70a3c642',1943,'随张昌德投敌','随张昌德投敌，任伪皖南独立方面军副司令兼师长，在池州、青阳、石台周边地区活动，协助日军扫荡抗日根据地，征收苛捐杂税，迫害民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5fe7cb8e27964b2ea02f1351eed68c9b','528f66c1-2460-4c23-9ccd-3baa1724abcf',1938,'池州贵池人','池州贵池人，日军侵占池州后出面组织维持会，后任伪贵池县知事，为日军筹粮筹款、拉夫带路，协助建立伪保甲制度，控制池州城区及周边乡镇。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa622eb5838e4cb6b84504b7a82556c9','d602a8d7-65ed-437a-b841-bc417361a25a',1938,'石台县地方士绅','石台县地方士绅，日军侵扰皖南时投敌，组织石台县维持会，为日军提供情报与物资，协助伪化地方基层，后因内部争斗失势。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abb1a61e168744c7bc7ee1589a2ea497','28c80745-d5bf-4d2e-8aa4-266e53682e20',1938,'青阳人','青阳人，日军占领青阳后投敌，历任伪维持会长、伪县知事，在青阳、石台交界地区推行伪化统治，配合日军清乡，搜捕抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a28a3193e5641a1ac77a0205eb2f712','18ded3e3-acad-4f53-93cd-8ec40a1d05e1',1938,'东流县（今属池州东至）人','东流县（今属池州东至）人，投敌后组织维持会，控制东流沿江地区，为日军运输物资、提供情报，其势力范围与石台、贵池相邻。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28ed2d0ed825440497613865caf05c5b','fcff92f3-0ab2-41a8-a0f9-4b49cdff94ce',1938,'贵池地方商人','贵池地方商人，投敌后任伪秋浦县维持会副会长，协助日军管理码头与物资转运，在池州沿江一带为日军服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a375609bddbe4c378d926babe0b7f840','13a66167-53ee-487e-bc5d-4f1dad467828',1940,'汪伪安徽省警务处在池州设立警察分处','汪伪安徽省警务处在池州设立警察分处，负责人配合日军维持治安，搜捕抗日分子，推行保甲连坐，具体姓名史料记载不全。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cd32f70f6bd4515ba74ddd43561e297','8a559a28-7bf6-448d-821f-7821562e587a',1940,'汪伪安徽省政府要员','汪伪安徽省政府要员，参与伪皖南行署事务，协助日军在皖南包括池州地区的伪化行政与经济掠夺。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2af35a476e994eefaafa6c7acda8e09d','a03b4a0a-bee3-4391-8d89-83bf1fc65bfc',1939,'原国民党将领','原国民党将领，投敌后任伪军要职，曾被任命为伪安徽省长，其伪军势力在皖南沿江一带活动，与池州地区伪政权有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d579db3887b447e9d230baa88d833ef','2c3f5675-2fc6-46e1-af9a-fc41761b92a0',1938,'福建人','福建人，伪维新政府要员，曾任伪安徽省长，在安徽沦陷区建立伪政权体系，池州等地伪维持会受其节制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-602116870bcf488f85227a625e0845c7','489962d1-113a-4402-8917-062c87b212af',1938,'日军侵占贵池后出面组织伪维持会','日军侵占贵池后出面组织伪维持会，后任伪贵池县县长，为日军征粮、派夫、维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6d8bca6c22640c39492c43c2a8e7195','0115c6f3-9062-4e44-aa57-6a1e0b94a761',1939,'在贵池沦陷区组建伪警察力量','在贵池沦陷区组建伪警察力量，配合日军搜捕抗日人员、镇压民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d5a71748a9b4397b15a426f6c6ca0e7','8d75565d-ad64-447d-83b0-1bc4074a31f0',1940,'统率伪保安大队配合日军对贵池及周边抗日根据地进行扫荡','统率伪保安大队配合日军对贵池及周边抗日根据地进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea5c73da539141c0b4eb3fb909671cd6','77b07a13-1907-4e24-a2cf-a4800cc98f16',1938,'联络贵池、东流、至德等地伪维持会','联络贵池、东流、至德等地伪维持会，协助日军推行治安强化运动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-687765271622415d8f34ab3eef266fff','04cdaf72-f92b-4b2b-8a0b-6ba4a6f84c31',1940,'在贵池推行奴化教育','在贵池推行奴化教育，强制使用日伪教材，组织学生参加亲日宣传活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0733bec5176f4d78bf1bd85e55cf7a99','273b143e-ba6d-4fdf-9bcc-65cf659000ed',1939,'为日军筹款筹粮','为日军筹款筹粮，控制沦陷区物资流通，协助日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5a3602bd6f94ac3ba3950bcedb9c631','e31abcb9-3ac9-410f-bbec-d7d66b193f99',1938,'组织安徽伪维持会系统','组织安徽伪维持会系统，为日军在池州等地的占领提供行政支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c9c1d6ffe9e4c4c9cc26f4472f9b988','7038a903-d890-41cb-9acb-9b7c64d69d0a',1938,'青阳本地人','青阳本地人，抗战期间投靠日军，组织伪保安武装，控制青阳及周边地区，为日军征粮、带路、搜捕抗日人员，参与维持会活动，是青阳地区有记载的附逆武装头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16b9dbe34e8a496a93daa3524e0e560e','1b5c108f-597c-42f2-997f-62e01bc756e5',1938,'贵池（今池州市区）人','贵池（今池州市区）人，日军占领贵池后投敌，先后任伪维持会会长、伪县长，管理伪政权，为日军征粮征税、推行保甲，其辖区与青阳相邻，对青阳地区伪政权有影响。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-613965eff70b4b20a092e96b8a220d1a','6ffd470f-d303-44e2-8198-faa631095ab5',1938,'东流（今属池州市东至县）人','东流（今属池州市东至县）人，抗战期间组织伪维持会，协助日军控制长江南岸东流、至德一带，与青阳、贵池伪政权互通声气，参与征粮与情报活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95c6054a18d945799f8446258227c93f','e5d5fd80-6e60-476d-8ecb-503ef46ac094',1938,'安徽人','安徽人，汪伪政权财政官员，负责安徽沦陷区税收与物资统制，为日军搜刮战略物资，其财政网络覆盖池州、青阳等皖南地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2edaa9fb0d5b49f5a8fb6b1f1e809f74','114d1715-272f-406c-9e5d-3431b6530b98',1938,'在汪伪安徽省政府中负责教育','在汪伪安徽省政府中负责教育，推行亲日奴化教育，在沦陷区学校强制日语教学与亲日宣传，池州、青阳等地部分学校受其政策影响。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a08cb9667c184dca9265771560e4cddd','b4363349-d772-450c-bb6d-71e6eee0e99a',1939,'青阳本地附逆者','青阳本地附逆者，任伪警察局长期间配合日军搜捕抗日分子，管理伪警察队伍，参与保甲连坐与物资管制，是青阳地区伪警特系统的代表人物。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ec1aa59b43e4590a8032f65e3668b77','1d780362-2750-44a5-bbb3-e7c257a2e4df',1940,'青阳人','青阳人，组织伪保安团配合日军扫荡，在青阳、南陵、泾县交界地区活动，袭击抗日游击队，强征壮丁与粮款，对当地抗日力量造成损失。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44b47ac7f230490fabab84a7976ec5dd','b4458c28-ed3f-4cd2-9478-6b479142bd63',1940,'汪伪政权核心人物','汪伪政权核心人物，虽主要任职南京，但曾兼任伪安徽省主席，参与策划对安徽地区的伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1bb960df7d5a4273a8deb968b2871ffd','39f5f5e9-8d75-4429-9b5a-6e1b8e9bf6a1',1940,'接替倪道烺任伪安徽省长','接替倪道烺任伪安徽省长，在安徽推行保甲制度，配合日军“扫荡”，强征民夫物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b9260359f784e2daa0a607c354fffaf','39f5f5e9-8d75-4429-9b5a-6e1b8e9bf6a1',1940,'曾任伪维新政府及汪伪政权安徽省长','曾任伪维新政府及汪伪政权安徽省长，在蚌埠、怀远等地推行保甲制度，强化日伪统治，配合日军“扫荡”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74fb09437c9849419fa636de6f90287b','39f5f5e9-8d75-4429-9b5a-6e1b8e9bf6a1',1940,'1941年接任伪安徽省长','1941年接任伪安徽省长，驻蚌埠，推行“治安强化运动”，组织伪军配合日军扫荡淮上抗日根据地，强迫民众“自首”，实施连坐。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f134bb08b9084291afca78b4c15b0e88','1f4d7dbf-8fd7-4400-b2e0-8861327f06f5',1940,'在淮北地区组织伪军','在淮北地区组织伪军，协助日军进攻新四军，残害抗日军民，参与“清乡”行动。','危害等级B（乙级，市县厅局级）','hanjian');
