INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2206456691c5459d977d802370df459b','6ed5c96d-eabe-4597-8b7c-36516902c627',1938,'抗战期间在宿县、淮北一带依附日军','抗战期间在宿县、淮北一带依附日军，参与伪政权行政事务，为日伪统治服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-40e4b64310284bc6a6a5899b0a1e8e38','515df51e-a7c3-4a2e-9fad-5394f4d09302',1937,'安徽合肥人','安徽合肥人，北洋旧官僚，抗战期间投靠日本，在华北伪政权中任要职，推行日伪统治政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ec674014da64279a38b41279ada4f28','515df51e-a7c3-4a2e-9fad-5394f4d09302',1937,'江西婺源人','江西婺源人，北洋政客，抗战期间投靠日本，在华北伪政权中任要职，参与推行伪化统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3630214cff24cecb5d33d5d2e2df88a','515df51e-a7c3-4a2e-9fad-5394f4d09302',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投靠日本，参与组织伪中华民国临时政府，后任伪华北政务委员会委员长，推行奴化教育、配合日军掠夺华北资源。虽非赣州籍，但其伪政权体系覆盖包括江西在内的沦陷区，与赣州地区有间接关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d98c398e1724a79bd96132eeaea95b2','515df51e-a7c3-4a2e-9fad-5394f4d09302',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投靠日本，在华北伪政权中任要职，其伪政权统治范围包括河南沦陷区，商丘、虞城等地伪政权均受其系统影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0449b9e9df2f45b8addeb803d843e365','515df51e-a7c3-4a2e-9fad-5394f4d09302',1937,'长期在华北伪政权任职','长期在华北伪政权任职，推行日伪政策，其影响波及陕西等华北周边省份。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b84bbdda5e854746ba6d162493ab0cc3','515df51e-a7c3-4a2e-9fad-5394f4d09302',1937,'北洋政客','北洋政客，投敌后任伪临时政府内政部长、伪华北政务委员会委员长等职，配合日军在华北推行治安强化运动，镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
