INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7dc61026c3f4139a2e0169c4b83b956','ef967979-89bf-419f-a26f-1c63b9d7e8d0',1940,'原地方民团头目','原地方民团头目，投敌后任伪保安大队长，在烈山、蔡里一带多次袭击抗日游击队，杀害抗日军属，并配合日军“清乡”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-090e3fcd7dd442aa8767862553183fcf','fc7e0323-ed93-4f51-bc59-22951c4ee001',1941,'负责为日军管理烈山煤矿劳工','负责为日军管理烈山煤矿劳工，克扣工资，虐待矿工，多次向日军举报矿内抗日地下活动，导致多名矿工被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
