INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21f1f6c0b58c4653b623eeb92ff5a883','f28f9b3f-000c-4938-b6b6-491b2ddcaa56',1938,'相山本地劣绅','相山本地劣绅，日军占领后出任维持会长，为日军提供情报，强征民夫修筑工事，霸占民产。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4db56a62ad624e7a8f19da774cfece3f','e396502c-ca73-496e-89f6-2f0fdf81268e',1939,'投日分子','投日分子，任伪相山保安团长，配合日军‘扫荡’萧县、濉溪等地，杀害抗日干部数十人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d260128ed2cc4ae0b6797b4a3657fe82','06056765-7053-4a84-a1a5-3dc1db3b2713',1940,'王仲华','王仲华，投日后任伪濉溪县知事，在相山地区推行‘连坐法’，强征粮食，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b85552ec6af4a3e8eaebbdf528e64cb','6a9964c5-8a58-4e2e-a30e-8337a25c245d',1941,'李本一','李本一，投日后任伪宿县警备队长，在相山一带设卡盘查，抓捕抗日交通员，多次参与‘清剿’行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d412380f99dc45c1933102f6375f2eac','d46a1f01-7335-4673-843b-260f46f6aeed',1938,'原煤矿主','原煤矿主，投日后任伪淮北矿务督办，在相山附近开采煤炭资源供日军军需，压榨矿工，致数百人死亡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7566feeeeaaf475c9021f8f88063f641','dc833df6-8a2d-4db4-b1de-4d8cc7445c2f',1938,'曾任伪安徽省省长','曾任伪安徽省省长，后兼任淮南煤矿（日占时期）负责人，为日军掠夺淮南煤炭资源服务，镇压矿工反抗。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5b9ce145f584dfb9b4a3b57f7bac39a','3090963c-9b78-4fe0-a14c-3e343bf777c6',1939,'协助日军管理淮南矿区','协助日军管理淮南矿区，组织伪警察镇压矿工罢工，抓捕抗日分子，向日军提供矿工劳役。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63a6d06f91954b2293987445784df6dd','3c06acc0-a3cb-40fa-a8fc-65ae5d339491',1938,'日军占领淮南后首任维持会长','日军占领淮南后首任维持会长，负责为日军征粮、派夫，协助建立伪政权，迫害当地抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aca080bb811347ba9291b9cd710a5d25','685394c7-3046-4ca7-972d-ce7633b52b7f',1940,'任伪县知事期间','任伪县知事期间，推行保甲制度，强征壮丁，为日军提供情报，参与“清乡”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1f8765e6987411299ff2d38cd4e4fae','931d821a-8317-4d24-b32f-fc0d66f307a4',1941,'负责与日本三井、三菱财团合作开采淮南煤矿','负责与日本三井、三菱财团合作开采淮南煤矿，压低矿工工资，增加煤炭产量供日军军需。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b574e23602644a759c0c24e9399377a7','e1edbd7f-566c-4720-b4cb-ebe0a8b8792b',1942,'率领伪保安队配合日军扫荡淮南抗日根据地','率领伪保安队配合日军扫荡淮南抗日根据地，杀害新四军游击队员及群众数十人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff89dd304df14fa7b6c7d9ee61e5619b','3706d747-b00d-4c12-aaad-648f642ef340',1939,'为日军征收苛捐杂税','为日军征收苛捐杂税，强征粮食，导致当地百姓饥荒，并贪污部分税款中饱私囊。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a94eada24f4349e48f1bd92562397422','661a7188-f64c-43d3-a44e-ef91b4140d38',1940,'推行奴化教育','推行奴化教育，强制学校教授日语，删改历史教材，宣扬“中日亲善”，迫害爱国教师。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07b44a124ae24c5a9bd65ddafe5ca384','182e5c23-32ec-4682-acf8-ad4f281e1010',1939,'日本占领淮南煤矿后','日本占领淮南煤矿后，出任伪矿务局长，组织汉奸矿警队，强迫矿工为日军采煤，供应侵华战争军需，虐待矿工，造成大量矿工死亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b71bb30b88db48448aad2dc470278eeb','01680cfc-5e4d-4d17-8c16-ef8952352c66',1937,'虽为华北伪政权头目','虽为华北伪政权头目，但曾插手安徽淮南地区伪政权事务，协助日军在八公山一带建立伪保甲制度，征收军粮，迫害抗日家属。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e444f1841c98497e9c0826161a11ac74','d75cbe49-d722-4723-a51b-5966f4b5db05',1944,'汪伪政权骨干','汪伪政权骨干，任伪安徽省长后，加强对淮南、八公山地区的控制，推行“新国民运动”，强迫青年接受奴化训练，并协助日军搜刮粮食。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b21f9552cf9d4d37a5f067eca7425ba9','6f2ec3ca-7e18-478d-b24e-badc3dbe1d17',1939,'率伪军驻扎皖北','率伪军驻扎皖北，多次配合日军扫荡淮南、八公山抗日根据地，烧杀抢掠，抓捕抗日群众，并参与护矿，保障日军煤炭运输线。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3075586b9e2649ba8820f75fcbc5b2e6','5589aa0f-317a-4ccf-be2f-b8b6a3d916d5',1943,'虽以淮海省为基地','虽以淮海省为基地，但曾派伪军进入淮南八公山地区，协助日军镇压矿工罢工，破坏中共地下组织，残害抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cfa4ea19bee240d7b5b2001dc7839e1d','c05483b7-c163-46f6-93f0-29767e3467de',1942,'率伪军数万人在皖北一带驻防','率伪军数万人在皖北一带驻防，多次进攻淮南、八公山抗日武装，烧毁村庄，强征民夫修筑碉堡和公路，为日军运输煤炭提供保护。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f7eaf8602b2478b9d7bc6cbabde7c29','f3a29c5f-c3c5-4af0-a637-4a6ee306b007',1943,'投敌后率部在安徽北部活动','投敌后率部在安徽北部活动，参与对淮南八公山地区的“扫荡”，杀害抗日军民，并协助日军控制矿区，掠夺资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8427d8bf8f5a45a99b3f34fcc76d91bc','2b547dd9-e681-4d45-9553-156a25e9b396',1943,'投日后率部在皖北地区活动','投日后率部在皖北地区活动，曾配合日军进攻淮南八公山一带的抗日游击队，并参与伪政权对矿区的经济掠夺。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db89f427fcb2462b9c508a75b8fdc625','a7225505-4c07-4fb5-a844-4e919a23d29b',1938,'曾任伪安徽省长','曾任伪安徽省长，在安徽建立伪政权，协助日军维持占领区秩序。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d36b60572c944c23927c7c1f51d2e7af','228dfb64-e4ed-4585-bdbc-310bed0d63b7',1938,'在凤台县任伪知事','在凤台县任伪知事，为日军征粮派款，组织伪保安队，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c0c3ff39a2e4cfe9222e7a6cedb1abd','a65888ba-0931-49c5-8022-b95980429e5b',1938,'日军占领凤台后','日军占领凤台后，率先组织维持会，为日军提供情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da7e12021fba41908112f90336a53e81','ebf6ca56-02fd-4ee6-9124-a662427e565c',1939,'任伪保安大队长','任伪保安大队长，率伪军配合日军扫荡，抓捕抗日军民，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de3a11c141484f879f41bd71502fe8d3','4ec9551b-af39-46f0-9931-e735811ca159',1940,'在淮南矿区为日军控制煤矿','在淮南矿区为日军控制煤矿，镇压矿工反抗，强征劳工，为日军提供煤炭资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4533b4a395e2466f9de2a7035bac1e2b','f0f20aaf-5dc2-44b5-ab37-4d0012a363a8',1941,'任伪淮南县知事','任伪淮南县知事，推行日伪保甲制度，强征粮食，协助日军维持矿区治安。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22578ae252224617a3c2fdc3c111e8da','99eee0e6-aaf8-48b9-a692-7e75a6032fda',1939,'为伪政权征收苛捐杂税','为伪政权征收苛捐杂税，搜刮民财，供日军和伪军使用。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8005ea710d7749c8aefeb637725b3390','91aa62cd-101a-4614-a3e2-218de52c7abc',1940,'指挥伪警察协助日军抓捕抗日分子','指挥伪警察协助日军抓捕抗日分子，破坏地下组织，欺压百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55b8b43ac1da41988d305e8a8dc5cdda','b5f89209-802f-44b3-83c9-247a64180c47',1938,'原北洋军阀倪嗣冲之侄','原北洋军阀倪嗣冲之侄，投日后任伪安徽省长，积极推行日军‘以华制华’政策，在淮南大通矿区设立伪政权机构，强迫矿工为日军开采煤炭资源，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46bf61f3a7b74f2fa9133159ae8191d8','b5f89209-802f-44b3-83c9-247a64180c47',1938,'曾任伪安徽省省长','曾任伪安徽省省长，后兼任淮南煤矿（田家庵矿区）督办，组织日伪对淮南煤炭资源的掠夺，镇压矿工抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7163947d1e349b49118b80d3679ac87','746d7697-1d49-49fe-8ce4-64359c0dd73f',1939,'充当日军矿务管理帮凶','充当日军矿务管理帮凶，组织矿警队抓捕抗日地下工作者，残酷迫害矿工，多次配合日军‘清乡’行动，在大通地区制造多起血案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94a38c73527840f5a1302265f251709d','d68c044a-58e5-46ca-9942-2caf019f44ca',1938,'日军占领淮南后率先投敌','日军占领淮南后率先投敌，组织维持会为日军征粮派款，强征民夫修筑工事，并告密导致多名抗日群众被捕牺牲。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-694b0b074ab5463dabf6ff40757d240f','127c231d-b7af-4727-900a-894a016cbe56',1940,'率保安队协助日军护矿','率保安队协助日军护矿，多次围剿新四军游击队，在洛河、上窑一带烧杀抢掠，杀害抗日军民数十人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dba0e73f37374efbb73da38dfa9c5dff','5f8e0185-c524-4425-8b21-bac7dafb817e',1941,'投靠日伪政权','投靠日伪政权，推行保甲制度，强征壮丁补充伪军，配合日军‘扫荡’大通周边村庄，掠夺粮食和物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5106410fe14b4398b1151b3be9fb7465','352f35e4-dd4e-4862-8f6b-2897bb1e972d',1939,'负责为日军管理煤矿劳工','负责为日军管理煤矿劳工，克扣矿工口粮，虐待致死矿工数百人，并参与向日本本土输送战略煤炭。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfbe136c9a1b4a95ab5454cfb2df7898','3e630136-b1b2-402b-b1de-56e2e3779d40',1943,'原国民党将领','原国民党将领，1943年投敌后所部在淮南大通一带活动，配合日军进攻抗日根据地，并参与‘曲线救国’伪化宣传。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4adbfd9dfc794ece91981d4f4f565a37','e17b91c6-d17f-4275-9290-ba01069a2846',1943,'投日后其部队曾驻扎淮南周边','投日后其部队曾驻扎淮南周边，协助日军维持治安，参与对淮南矿区抗日力量的围剿行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-281657c1e5d445b1b43e5e92693e4364','1970e828-0a62-4e69-9a84-f94b83d222f6',1944,'在任期间推行日伪‘治安强化’运动','在任期间推行日伪‘治安强化’运动，对淮南大通地区抗日活动进行残酷镇压，强征矿工补充伪军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8dfb8d2d924040b993bc8b6f4635f781','28118530-0567-4982-bd61-5af8bbb9e948',1940,'虽主要活动于北平','虽主要活动于北平，但作为伪政权高层，其政策直接指导淮南大通地区伪政权运作，支持日军掠夺淮南煤炭。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d65a3b22f0cb4c0a8e94f3249079024d','f7eb389e-7cca-4a20-ae8c-08cfd39b8141',1938,'原北洋军阀倪嗣冲之侄','原北洋军阀倪嗣冲之侄，日军占领安徽后投敌，任伪安徽省省长，推行日伪统治，协助日军在寿县等地清乡、征粮、镇压抗日力量。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8bd1ca7ce09e444d8b66786738bf71ae','9c930a7b-969f-4e71-858f-a97f260b47c5',1939,'日军占领寿县期间出任伪县长','日军占领寿县期间出任伪县长，组织伪政权，为日军提供民夫和粮食，配合日军扫荡，逮捕抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba80768d57dc46a7a843b73050a1c48d','810528d5-e2e7-4c4b-b2c7-d94632fd05bc',1940,'率伪保安队协助日军在寿县南部地区“清剿”新四军游击队','率伪保安队协助日军在寿县南部地区“清剿”新四军游击队，杀害多名抗日群众，烧毁村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e69de24847a47e59c669c537c6c4c05','2c4a1dff-eb41-4ce3-9951-d4b8df99dff2',1938,'寿县沦陷初期出任维持会副会长','寿县沦陷初期出任维持会副会长，为日军筹办粮秣，强征民夫修筑碉堡，并劝诱乡绅投敌。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1dcca01921c4c7d933f458e2e66d6ac','f33ec47e-3182-4742-829d-05fa09c4239e',1941,'原地方武装头目','原地方武装头目，投靠日军后任伪警察局长，在寿县、淮南交界处设卡盘查，抓捕抗日地下工作者，勒索百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55264dc939584133bf2a4b2bce4f0833','57375f0c-186f-4877-8487-3e6b600e197d',1940,'为日军征收苛捐杂税','为日军征收苛捐杂税，强征田赋，导致寿县农民破产，并贪污伪政权公款，民愤极大。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9e9078c12454c528aca45fc753ab000','f63b4602-72fa-4ede-8425-b0190412db18',1942,'推行奴化教育','推行奴化教育，强制学校使用日伪教材，宣传“中日亲善”，迫害爱国教师，破坏抗日宣传活动。','危害等级C（丙级，基层头目）','hanjian');
