INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc9456c65b574d749403d85acfa3902f','7e66093e-1b37-483a-b7f5-adccdaa8bd92',1938,'原北洋军阀倪嗣冲之侄','原北洋军阀倪嗣冲之侄，1938年投敌，任伪安徽省长，在淮南、潘集一带推行日伪统治，强征民夫，掠夺煤炭资源，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
