INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be87153dc5ad421f97b88be4ccd1b8c9','b456f6b0-d583-4b97-b199-7ca6ddc55c38',1940,'在潘集地区组织维持会','在潘集地区组织维持会，为日军征粮派款，提供情报，协助日军扫荡新四军游击区，欺压百姓。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
