INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21d2cdfb3383430db346600eede31461','17585b5a-40ba-4c91-8b27-dbb7b0b54f90',1942,'投靠日伪后任区长','投靠日伪后任区长，推行保甲制度，强抓壮丁，向日军报告新四军活动，导致多处抗日联络点被破坏。','危害等级C（丙级，基层头目）','hanjian');
