INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00acf6e3cd024be8a3dd1f253afd1381','fc2737c5-6dd2-4247-aa2c-1d147976cc9f',1940,'汪伪要员','汪伪要员，参与沦陷区经济统制政策，影响包括安徽在内的华中地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3943867279a41f2aaf4f386200a3274','890c63f9-c6ef-4625-bebe-7c31446c417e',1940,'汪伪特务','汪伪特务，活动于江浙皖一带，捕杀抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ecb0ec8523dc48b6bbb1e5ed2bab61cd','890c63f9-c6ef-4625-bebe-7c31446c417e',1940,'湖北人','湖北人，汪伪特工头目，在杭州及浙江沦陷区活动，镇压抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-542df728473f45cebbd7e6337957c74e','dfcf9845-b495-4537-98a9-d9ea2e82118e',1939,'汪伪特务头目','汪伪特务头目，其活动范围涉及安徽东部，镇压抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d68c757f31a2448eabab053a7095c667','dfcf9845-b495-4537-98a9-d9ea2e82118e',1939,'山东人','山东人，汪伪特工头目，在南京及周边地区镇压抗日力量，势力涉及江西部分沦陷区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bddd7466c3a9414db282f68fb7df450f','67d86781-8d2c-4cb0-8d28-971fb8db905d',1940,'曾任伪安徽省警务处长','曾任伪安徽省警务处长，协助日军在安徽沦陷区维持治安、抓捕抗日人士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-99d3b4600c514c9c968adc340bb9140a','0d4d2ca6-998d-40cd-9460-bdb97735b62c',1938,'福建人','福建人，汪伪政权成员，曾任伪安徽省长，在安徽推行伪政，配合日军统治，滁州、定远等地在其管辖范围内。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6badb201f5c4cc8a278eb10db8e60b2','e67bae79-2a08-4822-a942-a8bb07cc9910',1940,'汪伪政权警务官员','汪伪政权警务官员，在安徽沦陷区组建伪警察力量，镇压抗日活动，滁州、定远等地伪警察系统受其节制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c84de9e2f0cd4682835b0070c8fe123d','134952d6-e586-4def-b704-19e3735d52d7',1938,'定远沦陷后','定远沦陷后，当地士绅或地痞出面组织维持会，为日军筹粮、派夫、维持治安，具体姓名史料记载不全，但定远县维持会确实存在并配合日军统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3dfbea7e7b094e10b61d5bca262fe96c','d1404bfb-fa18-4939-b702-02fce92d279d',1938,'滁县沦陷后成立维持会','滁县沦陷后成立维持会，负责为日军征集物资、维持地方秩序，后并入汪伪政权体系，具体负责人姓名史料记载有限。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f51f3b362fec40f787dd8a8b557363f1','8cc0e556-e63a-4d98-aa38-97a21b9b5304',1940,'汪伪政权在滁县设立伪县政府','汪伪政权在滁县设立伪县政府，伪县长配合日军征粮、清乡，镇压抗日力量，具体姓名在地方史料中有零星记载但难以确证。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-743b80f2a00645cf91d737bbdf21c511','accad54f-86a3-4424-941c-c80d1f7c60d2',1940,'汪伪政权在定远设立伪县政府','汪伪政权在定远设立伪县政府，伪县长执行日军与伪省府政令，征粮派款，配合扫荡，具体姓名史料记载不完整。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-973a1740574044eb91cc922920b9f6cd','e896b8e7-f340-4c38-9b8c-590593ca7a34',1938,'明光本地人','明光本地人，日军侵占明光后组织维持会，为日军筹集物资、招募劳工，协助建立伪基层政权，直接活动于明光地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e725035cbfdf4278b1df5607d5f7a27b','8387a713-b34b-4b22-a108-7265152961e9',1939,'汪伪政权委任的嘉山县县长','汪伪政权委任的嘉山县县长，在明光及周边地区推行保甲制度，配合日军清乡，征敛粮食与物资，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98e74a6ff03e40ea8b6b8f4d39f4cb12','bf582ebc-8f22-4915-94dd-140cd3472410',1938,'安徽沦陷区伪政权官员','安徽沦陷区伪政权官员，曾任伪凤阳县县长及伪滁县专区专员，管辖滁州、凤阳、明光等地，为日军提供情报与物资支持。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-030ed136ce0e474e8b00153be7d38f5d','4aa92a8b-996a-488f-879a-951ed972d429',1939,'汪伪政权定远县县长','汪伪政权定远县县长，活动于定远、明光交界地区，推行伪化教育，协助日军维持治安，征调民夫修筑工事。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e0610a7bffc43dd8df9636d1041e5cb','2a604ef6-dbb6-48ca-9e24-3f8fbc654e2a',1943,'伪军头目','伪军头目，活动于苏皖边区，包括滁州、明光一带，配合日军扫荡抗日根据地，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-845d4dd1e4f2496588e92d8e376bba97','cf949942-c0d9-4a0a-9761-35577872d0f7',1938,'来安本地士绅','来安本地士绅，日军侵占来安后出面组织维持会，后任伪来安县县长，为日军征粮、派夫、维持治安，直接服务于来安地区的日伪统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-817b334c10634f6ea3947518f437008e','f2c119ec-74eb-40a5-9134-6023b074ba4d',1938,'滁县本地人物','滁县本地人物，抗战期间投敌，组织伪滁县维持会并任伪县长，协助日军控制滁县及周边来安等县，推行保甲、征发劳役。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a698aebd0cad401f80adb5b3f0fbe2f0','106710a8-46c6-45f6-9d68-c7b90d4d0277',1938,'在滁县沦陷区担任伪警察头目','在滁县沦陷区担任伪警察头目，配合日军搜捕抗日人员、镇压民众，其活动范围涉及滁县与来安交界地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7455dee51a5d419bbbcb3f2a8944e605','958bb78e-afcf-44e1-9383-c4f01164f351',1940,'汪伪政权二号人物','汪伪政权二号人物，曾兼任伪安徽省省长，其伪政权体系覆盖安徽沦陷区包括滁州、来安，参与推行亲日政策与经济统制。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2ae3dfcfed54bdcbf4687913ed984d8','4db23867-310b-4f30-9b1a-71353199ccf0',1940,'汪伪政权核心人物','汪伪政权核心人物，其财政与行政体系延伸至安徽沦陷区，滁州、来安等地伪政权在其总体框架下运作，参与对沦陷区民众的掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15d03f68e26e48ce82311016bbf87382','529d689c-57ad-4a16-a8f4-23ec997bb811',1938,'原西北军将领','原西北军将领，投敌后组织伪军，活动于豫皖苏交界，其伪军势力曾延伸至安徽滁州、来安周边，配合日军扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6720cafe64d495d8279ccf4cf927b43','58b750f8-c012-4922-b25d-2ec234e9171f',1943,'汪伪淮海省伪军头目','汪伪淮海省伪军头目，其保安部队在安徽北部及滁州、来安一带配合日军进行清乡与扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06a7a22b23ae449883eb721ecd23b29d','e08a0313-7051-4cea-9ef2-07b7ddb1e7cc',1939,'来安本地伪军头目','来安本地伪军头目，组织伪保安大队，配合日军驻来安部队维持治安、征粮派款，镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-151b4cf841be425fb083dee2bd05a4d6','78ba3bb7-9063-47cf-9ee9-0f8b523c73f5',1938,'滁县商界人物','滁县商界人物，抗战期间附逆，任伪商会会长及维持会委员，为日军筹款筹粮，协助经济掠夺，影响滁县及来安地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f7006c359d048c0918d73162dd65165','d1f9cdff-1dd5-4d69-a06a-f7c8c30634ca',1940,'在来安沦陷区担任伪教育科科长','在来安沦陷区担任伪教育科科长，推行奴化教育，篡改教材，向学生灌输亲日思想，为日伪培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c53bb5f9eb9478db72cfca159a546b6','6afd2608-9431-49cb-9bec-5d9149a4beb7',1939,'滁县沦陷区伪新民会头目','滁县沦陷区伪新民会头目，负责亲日宣传、组织民众团体，配合日军进行思想控制，其活动覆盖滁县、来安等地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35318e0b7a494b27b685bd929aed7dc9','de70f3d6-7abe-469d-96de-2adf4f111203',1939,'滁县本地人','滁县本地人，抗战期间投靠日军，任伪滁县警察局局长，负责搜捕抗日人员、控制户籍与物资流通，配合日军对滁县周边乡村的扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abab2302dbdc409ea09665f0c2def965','e51f9f1c-3fff-4129-a1bf-d6c774c5bddf',1938,'来安县士绅','来安县士绅，日军占领来安后组织维持会，为日军筹集粮草、招募伪军，协助维持占领区秩序，后因内部争斗被日军撤换。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f89b5ede3efa4852a0fc8cb3e23c51a2','8e476cbc-3d75-40bf-9ae1-b65da355ac12',1939,'全椒县人','全椒县人，抗战期间投敌，任伪全椒县县长，推行保甲制度，配合日军清乡，搜捕抗日分子，强征粮食与劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-151ea667292a478c9a1400e3a100fbab','7c8c3d1d-2b05-4bdf-8072-4f3b0172f026',1938,'定远县地方势力人物','定远县地方势力人物，日军侵占定远后率先投敌，组织维持会并任伪县长。协助日军修筑据点、封锁抗日根据地，参与对定远周边新四军活动区域的扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d35396e0d8642eb9618802a649fbe64','8a97f518-f87f-4bab-b57f-2261315fb56e',1938,'凤阳县商人','凤阳县商人，日军占领凤阳后出面组织维持会，为日军提供物资与情报，协助管理蚌埠至凤阳沿线交通，后因民愤被抗日武装处决。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cf4b2e067974a7a815dae605c1c2f15','0f591641-a08a-4063-bc33-72adcc26dd58',1940,'嘉山县（今明光市）人','嘉山县（今明光市）人，抗战期间任伪嘉山县县长，配合日军控制津浦铁路沿线，征发民夫修筑工事，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07c9e04ef8f64f0f956227f88349668a','f03abd80-ad65-44ec-a894-5e3dd4e5efa6',1940,'江西人','江西人，社会党创始人之一。抗战期间投靠汪伪政权，曾任伪安徽省省长、伪考试院院长，在安徽推行奴化教育与亲日宣传。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f49ea83a90074195885d164fe6a6e3ca','f03abd80-ad65-44ec-a894-5e3dd4e5efa6',1940,'汪伪政权成员','汪伪政权成员，曾任伪安徽省省长，在安徽推行奴化教育，协助日军进行思想控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a97dff1dd6974191a93829f41d588657','f03abd80-ad65-44ec-a894-5e3dd4e5efa6',1940,'汪伪政权成员','汪伪政权成员，曾任伪安徽省省长，在安徽推行奴化教育，配合日军统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3f0ce6d98654ecf8c5f31011f6d817a','71bffa6e-96f4-47d6-b488-50878f24bfc2',1938,'福建人','福建人，早年参加辛亥革命，后投靠汪伪政权。曾任伪安徽省省长、伪内政部长，在安徽推行伪政权的行政与警察制度，配合日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cda2c6d10e14f3590ae9e7a75e5a96e','71bffa6e-96f4-47d6-b488-50878f24bfc2',1938,'汪伪政权成员','汪伪政权成员，曾任伪安徽省省长、伪内政部长。在安徽任内配合日军实施保甲、清乡与物资统制，滁州一带在其伪省政权管辖之下。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1651e5ec403c4961a21341c71fed09f9','b88eaacc-284e-4b69-91f2-dfb67a828a79',1938,'天津人','天津人，北洋政客。抗战期间投敌，曾任伪安徽省省长，后任伪华北政务委员会常委，在安徽及华北协助日军推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6912efa5a7464765b1c90b88896d8075','bd14b7fb-e6e3-48b7-b196-f59991e67abe',1940,'滁县本地人','滁县本地人，抗战期间组织伪保安团投靠日军，任团长。配合日军对滁县、来安、全椒交界地区进行扫荡，搜捕新四军及抗日群众，强征粮款。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a4b78aa74ca4fc4a96ed766f91e9e60','6ed69a58-e1a0-4b4a-b4ae-8e53f2352ae8',1941,'滁县知识分子','滁县知识分子，抗战期间附逆，任伪滁县教育科科长，推行日语教育与奴化课程，篡改历史教材，为日军占领政策培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac78d428db5143ac8868d37e0ed42cbe','5b758c2f-94c9-49c3-8db3-afc6759f8eb0',1938,'滁县商人','滁县商人，日军占领滁县后出任伪商会会长，协助日军统制物资、征收商税，为日军采购军需品，压制商户抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-988202293fe642b8b8c83626a4fab57d','b1f85c73-89ee-4126-8cd1-b68f6d41e018',1940,'来安县人','来安县人，抗战期间投敌，任伪来安县保安大队大队长，配合日军扫荡来安、滁县交界地区，捕杀抗日干部与群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9388b389bfd427a891ef250708da482','975caa75-5346-46c8-889d-efde8ea58537',1938,'抗战期间投敌','抗战期间投敌，曾任伪安徽省保安司令等职，统率伪军配合日军在安徽沦陷区清乡、扫荡，滁州及琅琊周边地区有其伪军活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d42c3434ac234688a83908c0cb176191','5ac66c09-a5c4-44b3-a5a8-6b65d7c1e11d',1938,'滁县本地投敌人员','滁县本地投敌人员，任伪警察局长、伪保安队长期间，协助日军搜捕抗日人员、征收捐税、维持治安，直接参与滁州及琅琊地区的日伪统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78fe220703ba499c9b61ad4d1707ecca','d5898cd1-4dd1-47ce-9ccf-e022d1b36eb2',1938,'滁县教育界附逆者','滁县教育界附逆者，任伪滁县教育会长、伪中学校长，推行日语教育与亲日奴化宣传，在滁州、琅琊一带教育领域为日伪服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bdb7c6385edc427e88a10fd2fe10fa90','118c0970-3263-44a2-886d-f8f79e95f3bf',1940,'汪伪政权主要头目之一','汪伪政权主要头目之一，曾任伪安徽省省长，在安徽推行日军政策，镇压抗日力量，后任伪国民政府主席。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b9f9c9da87e4631a3af0fc06edf422e','a639e249-6f7c-4c2f-aa7f-b1d6ec735011',1938,'组织伪维新政府','组织伪维新政府，其势力覆盖安徽部分地区，任伪安徽省省长期间配合日军建立伪政权，推行经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95c96a20068e43a2a2021ccd341c06be','d7528f5f-b8e8-4b28-b20f-cd97e384629f',1940,'汪伪政权核心成员','汪伪政权核心成员，曾任伪安徽省省长，在安徽推行经济统制，为日军筹措军粮物资，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bfeb308ed4664829a9d2b388e15c9b6a','b10113b7-aba2-46d0-a381-7ebaeb0503bd',1940,'汪伪政权成员','汪伪政权成员，曾任伪安徽省省长，在安徽协助日军进行经济掠夺和奴化宣传。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c6b540a82e841f68af428ff26c537e7','9d747491-9a7c-44cd-9731-5bcd5ebfe9c9',1939,'在滁县伪政权中负责教育','在滁县伪政权中负责教育，推行日语教学和亲日奴化教育，篡改历史教材，毒害当地青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5d2d77b4e3a498f800d5a254c50aa9d','b7c79e18-8ce8-4bb6-bebf-7ca1ed4f2370',1938,'滁县商人','滁县商人，日军占领后出面组织伪商会，为日军筹款筹粮，协助经济统制，压榨当地商户和百姓。','危害等级C（丙级，基层头目）','hanjian');
