INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35c1ffa8af3543b698195c1bfedca0c3','ec6c29c9-2c6d-482c-9162-e5ad3ef834ab',1938,'投靠日伪','投靠日伪，任伪安徽省省长，在芜湖及皖南推行殖民统治，协助日军清乡、征粮、镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
