INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-feecbe1fd7ed41c0ab78d90b03754d5c','2e008320-6d77-4358-a54f-4d31004a7b98',1941,'湖南常德人','湖南常德人，但长期在浙江活动，曾任伪浙江省长，兼伪特工总部主任，残害抗日志士，1947年被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
