INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7903697a027c46f8b9214d56ff88c99e','262f9c04-5b3c-48d2-afef-0796733b1df4',1938,'蚌埠沦陷后出面组织伪维持会','蚌埠沦陷后出面组织伪维持会，协助日军维持地方秩序、征发物资与劳工，并利用商会身份为日军筹措军需，是蚌埠当地重要的附逆人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6826a00937de4782b73fc9ba19a34026','4be6a449-0ad8-4f3b-877a-37e342fb6494',1938,'在蚌埠沦陷期间担任伪警察头目','在蚌埠沦陷期间担任伪警察头目，配合日军搜捕抗日人员、管制民众，维持伪政权在蚌埠城区的统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b82abaa80d14f658b3f106d1a628b82','7649b288-7151-4daf-955a-ab18996d3b89',1944,'汪伪政权官员','汪伪政权官员，曾任伪安徽省省长，在安徽沦陷区维持伪政权统治，其辖区覆盖蚌埠、五河等地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c609ae1aec84117a9c5218346bdcf03','f5d7831a-fc76-4d3e-a1f5-cfdfb704324a',1938,'五河沦陷期间','五河沦陷期间，当地士绅或地痞出面组织伪维持会，协助日军征粮、派夫、维持治安，具体姓名在地方史料中记载较少，但五河县伪维持会确实存在并活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f5c0543fa0b4a04888a480b6786be8e','30678f26-edac-4a8a-926e-61d2d436d623',1938,'五河沦陷期间','五河沦陷期间，伪警察所负责地方治安，配合日军搜捕抗日人员，压迫民众，具体姓名在现存史料中多不完整。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1e12336cd3e46ae9f5f4d25c6557f64','ba945730-2e2e-4f58-93b8-a0535f5089c7',1938,'蚌埠及凤阳一带沦陷后投敌','蚌埠及凤阳一带沦陷后投敌，参与组织伪维持会与伪政权，为日军征集粮食、情报与民夫，活动范围覆盖蚌埠、固镇周边地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd138e6de6794cfcaca4d4c343ff5041','a6b59921-d728-409f-8b90-2ce7e6dfc278',1940,'汪伪政权最高头目之一','汪伪政权最高头目之一，其伪政权统辖包括安徽在内的华中沦陷区，安徽蚌埠等地伪政权均受其节制，战后以汉奸罪被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a656bf6161b4db196f379fbcab8bbf3','9eb15f9d-3d0f-47bc-8d94-52e1469397d2',1940,'汪伪政权核心人物','汪伪政权核心人物，掌控伪财政与警政，其政策推行至安徽沦陷区，蚌埠等地伪警察与税收机构受其系统管辖，战后被审判。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf41a50d7c004b9fa27366481ad69885','13654027-1d3a-47e7-9700-7237fa44b362',1940,'汪伪政权要员','汪伪政权要员，参与伪政权经济统制政策制定，安徽沦陷区物资征发与配给受其影响，战后以汉奸罪处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e204b559b5ea4e1faeced1a800851bf7','26f41ec2-8f44-4cab-ab61-f7ca4009e2c1',1938,'北洋政客','北洋政客，抗战期间投敌，曾任伪安徽省省长及伪华北政务委员会要职，在安徽沦陷区推行亲日政策，战后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11cf5ecf4b924b638d0f34a551a82c21','7e047a30-15f5-4402-9a23-48561a318829',1940,'社会党人','社会党人，抗战期间投靠汪伪，曾任伪考试院院长等职，与安徽伪政权有联系，战后以汉奸罪被判刑。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d35bff82d2841338df91b7311a45377','baf35357-98e9-40eb-a7d6-7780b32df78f',1938,'蚌埠沦陷期间伪警察机构负责人','蚌埠沦陷期间伪警察机构负责人，协助日军搜捕抗日人员、管制居民、征收捐税，具体姓名史料记载不全，但该职务为当地重要附逆岗位。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c644472c8cc4df8876f39229c683696','7df8c1dc-0a61-4514-a742-c6a6202deda7',1938,'固镇沦陷后组织伪维持会','固镇沦陷后组织伪维持会，为日军征集粮食、劳工与情报，维持地方伪秩序，具体姓名在地方史料中记载较少。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0ae42fd98b845bdbe7a9ebcd354a737','46fbad77-fed9-4f77-a333-3b5b46355225',1938,'原北洋军阀倪嗣冲之侄','原北洋军阀倪嗣冲之侄，投靠日军后任伪安徽省省长，在蚌埠设立伪政权，推行奴化教育，协助日军清乡、征粮、抓捕抗日人士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73e2de50cab84628b8fd79801324f1a3','b7424dc9-68c0-47da-bb76-a2a1bbf5288a',1938,'日军占领怀远后出任伪县长','日军占领怀远后出任伪县长，组织维持会，为日军提供粮食和民夫，镇压抗日活动，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5878adbd294f44a78e25efc05d6b49e8','af55a263-a65a-4c02-9f2e-17c9639d9e3c',1938,'日军侵占蚌埠初期','日军侵占蚌埠初期，率先组织维持会，为日军带路、提供情报，协助建立伪警察局。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-526bd9e066744ff48d8111983c2862c2','59ac6c14-b6bd-48ae-bb6f-37c21825be0b',1938,'长期担任日伪控制下的商会会长','长期担任日伪控制下的商会会长，为日军筹措军饷、摊派捐款，垄断粮食贸易，从中牟利。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-105100254c554dd1a7bbab4cfa2e0722','59ac6c14-b6bd-48ae-bb6f-37c21825be0b',1938,'控制蚌埠商会','控制蚌埠商会，强迫商户向日军缴纳“慰劳金”，垄断粮食和食盐贸易，从中牟利。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a2faade33ab42ddbff4d30c27808c0b','b1b91744-9e7e-4103-8576-6fe06566dde1',1939,'组织伪保安队','组织伪保安队，配合日军在怀远农村“清剿”新四军游击队，杀害多名抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-252dacd6fa354840b5db5eadd7bc6846','891c6050-21ce-4e94-8c07-20c2c1311200',1940,'效忠日伪','效忠日伪，在怀远城内设立多个检查站，搜捕抗日分子，严刑逼供，致多人死亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66a475796149499b8bf1bda731f37a88','67f7359e-9dba-4056-8ead-859bdcb417a3',1941,'管辖蚌埠及周边县','管辖蚌埠及周边县，推行“治安强化运动”，组织汉奸情报网，破坏中共地下组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75920c62213244808cc6c8ead3cea68b','d11b39db-9fc9-421b-90eb-47d83f82692e',1939,'强制推行日语教育','强制推行日语教育，篡改历史教材，宣传“中日亲善”，迫害爱国教师。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c677b743e4d640dc9a1da44f8c02deb4','1d5809a9-ab8c-4824-b410-1187d482403a',1938,'1938年投敌','1938年投敌，任伪安徽省省长，在蚌埠设立伪政权，推行日伪统治，镇压抗日活动，征收苛捐杂税，协助日军进行经济掠夺和“清乡”行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47d8aff1ffcd439e9123e12410e9ae7e','ef3d9918-af4d-4b6a-9400-6aa992de78ba',1939,'1939年任伪蚌埠特别区行政公署署长','1939年任伪蚌埠特别区行政公署署长，主持伪区政，配合日军建立保甲制度，强征劳工，搜刮粮食资敌，破坏抗日地下组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3be3b739f0b463f948d193ab2f787c0','fb00742e-e31f-4fc4-b14a-7c68c4cdd8d3',1943,'1943年任伪安徽省长','1943年任伪安徽省长，在蚌埠强化日伪统治，扩充伪保安队，协助日军掠夺淮上矿产和粮食，镇压学生和民众反日运动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa8c38c9cc2444818e7506f3b853d5b5','83449262-e98b-48ed-b48e-1772d62a8fbd',1940,'1940年任伪蚌埠市长','1940年任伪蚌埠市长，主持市政，推行奴化教育，设立日语学校，强制民众悬挂日伪旗帜，配合日军“慰安妇”征用和物资统制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34a9a5c3a8924ca094be70916428ed64','3560a35b-fb96-47f3-bdb5-7982550ba430',1939,'虽主要活动于上海','虽主要活动于上海，但曾派员在蚌埠建立特工站，抓捕抗日志士，破坏地下交通线，策反国民党地方武装投敌。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9131884cdb2347e69f2d8595f41ccbab','d480ec05-afc0-4188-ae26-352a43e38ebe',1939,'作为汪伪特工头目','作为汪伪特工头目，曾指导蚌埠特工行动，参与策划暗杀抗日人士，协助日军在淮上地区进行“肃正”和情报搜集。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a96512da8b24cf8b16ce2f987aadf85','03a3dccf-f405-4d9d-9e43-18d1cfb1a6dd',1940,'虽为中央伪职','虽为中央伪职，但多次过问蚌埠伪政权财政和军事，批准在淮上设立伪税卡，截留抗日物资，支持伪军扩编。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0883a1c5f0cb4f7f9acc38bb008acadb','45fc025a-05b4-480d-90a4-9f5f3bda4dd5',1940,'在蚌埠主持伪财政','在蚌埠主持伪财政，发行伪币，强制兑换法币，垄断粮食贸易，为日军提供军费，导致淮上地区物价飞涨、民不聊生。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42dd5f53f3da401f989eb5c4f1634f92','24dcf0cd-0b95-4782-b4e1-f0dfef461f91',1940,'指挥伪绥靖军驻守蚌埠及淮上要地','指挥伪绥靖军驻守蚌埠及淮上要地，多次配合日军“扫荡”新四军游击队，杀害抗日群众，烧毁村庄，抢夺牲畜。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd9fe4c5d5d149b99c4795fccbcedf60','9844aab9-92ff-444e-96a4-a609bf14aa18',1942,'率部投敌后驻防皖北','率部投敌后驻防皖北，在淮上地区与日军联合进攻抗日武装，强征壮丁，修筑碉堡，破坏淮河两岸交通。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc5705c812df4c1abbfef4d9a565407a','2e6bc9be-e124-432d-a543-5d10cd9a492a',1943,'所部曾驻扎蚌埠周边','所部曾驻扎蚌埠周边，参与“清剿”淮上抗日根据地，掠夺民间枪支，强迫农民种植鸦片，为日军提供战略物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2516c69da6646e38b04200038b99cd0','92c47971-da0e-4b90-bc27-4e709e6118af',1943,'投敌后其部队在皖北活动','投敌后其部队在皖北活动，曾派兵协助日军在蚌埠、怀远一带设卡盘查，搜捕抗日分子，并参与“三光”政策行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a3cfe11778342fa821bada192b820e3','a5d76e17-0e5e-46db-94c9-34ae8fdde5ea',1943,'率部在淮上地区与日军合作','率部在淮上地区与日军合作，袭击新四军地方武装，破坏地下党组织，掠夺民间财物，并强迫民众为其修建工事。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3d4a77f6aa44c5f97c00d12c75398a5','cb21b0a0-7ae7-459c-8fe0-b02d1f297e3b',1944,'虽驻徐州','虽驻徐州，但曾派伪军南下蚌埠，协助日军镇压淮上抗日运动，抓捕进步青年，并参与对淮北盐场的控制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c47f6c79867e466b907807a7823621bf','910ed20b-3188-433e-8e36-cd3869dbd3ed',1940,'曾巡视蚌埠伪军','曾巡视蚌埠伪军，推动伪警政建设，在淮上地区推行“连坐保甲”，强化对民众的监视和镇压。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f6e5d9f833ca43e38d7689774c430fb8','19e9585f-9348-4231-b12c-59c5273e9f68',1940,'作为华北伪政权首脑','作为华北伪政权首脑，曾批准在蚌埠设立伪军校，训练伪军骨干，并协调日军在淮上地区的“治安”行动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a59c2870000b46bd9a95daae971c425b','79c0905b-0a5a-446c-b8f2-6f1d1d9b8743',1940,'参与策划在蚌埠推行“新民会”组织','参与策划在蚌埠推行“新民会”组织，进行奴化宣传，强迫民众参加反共集会，协助日军搜集淮上情报。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4741b111a65d4271bba78ad4284f5749','e4398091-3cee-4658-8c77-17c2bed20a5a',1938,'在蚌埠设立伪银行分行','在蚌埠设立伪银行分行，发行联银券，掠夺淮上地区物资，导致通货膨胀，破坏当地经济，间接支持日军战争。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
