INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08ce7d0add2043fca0ca36cbd31de431','bd44c2fb-58c2-491d-b3d0-6bf13c301fa7',1942,'原东北军将领','原东北军将领，投敌后任伪苏皖豫边区绥靖军总司令，活动于皖北、豫东地区，曾率伪军进犯阜阳一带，协助日军维持占领区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-379f76adf975495d9103d5d8b1080272','e7dac1d6-44ce-4ddf-8872-d8ebe4b71bc2',1938,'原西北军将领','原西北军将领，投敌后长期盘踞豫东、皖北，任伪军头目，在阜阳、亳州、颍上一带征收赋税、强征壮丁，配合日军扫荡抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
