INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-008eb5ab45f24f57abdb52e20877b9d9','d095b49d-1ad8-4319-9632-8a1ae350a91f',1939,'为日军筹措军饷','为日军筹措军饷，垄断粮食贸易，向抗日根据地封锁物资，从中牟利','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9efd5430d4f740919416ea0d8bd08a48','e48089bf-12c6-4221-99f1-b43c52e18f2e',1940,'推行奴化教育','推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”，迫害爱国教师','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1bc98d9e15746d18ffa51687b932852','9f01fe0e-e564-495f-9bef-d5d376a26b33',1941,'增设苛捐杂税','增设苛捐杂税，搜刮民财，为日军提供经济支持，逼死多名抗税农民','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfe764dc813f4f1e93c317f2af1f9b93','dda96566-e17f-49d2-89fa-a39de568e04c',1942,'建立汉奸情报网','建立汉奸情报网，多次向日军报告新四军活动，导致多处抗日联络点被破坏','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-112bb03435c44e20a50bcd4405893d86','c6eb7543-6d0a-4267-a078-741637be837a',1938,'协助日军强征劳工修建军事设施','协助日军强征劳工修建军事设施，克扣劳工工资，参与镇压工人罢工','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29a351f6da714a6a8ea9eedf64c77f20','fb963375-d9b7-4e2c-a58e-bd64836b3b7b',NULL,'经查现存公开历史档案及地方志','经查现存公开历史档案及地方志，马鞍山市花山区（含原当涂县部分区域）在抗日战争时期无明确记载的、经司法审判或党史部门认定的汉奸个人名录。该地区当时主要为游击区与日占区交错地带，日伪基层政权人员多为外地调任或临时委派，且战后档案散佚，未形成系统名单。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d643d601f42450cbb057c9215ada6cb','166e71c5-ceaf-41ab-8fe0-c1808b0cbb13',1937,'当涂沦陷后出面组织维持会','当涂沦陷后出面组织维持会，投靠日军，后任伪当涂县知事，为日军征粮、征夫、维持地方伪秩序，活动范围覆盖今马鞍山市区及当涂、雨山一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-944dcdcdef4c4886b47b8638f892211d','5938a140-a527-40d2-a99b-97bd817fb3a2',1938,'在伪当涂县政权中掌管警察武装','在伪当涂县政权中掌管警察武装，配合日军搜捕抗日人员、镇压民众，控制当涂及周边马鞍山、雨山地区治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1ff69f9e6b544eba6c69f68256e2fa0','29c86c91-2243-4ca4-af13-28a8bf21c9a0',1940,'汪伪政权核心人物之一','汪伪政权核心人物之一，虽主要在南京、上海活动，但其伪政权体系覆盖安徽，包括马鞍山、当涂一带的伪县政权均受其伪中央节制。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dddf27a636514cc19b2384f6c6ce49ca','3d0455fc-1c37-4aa3-ad92-3d9e1f54ea4f',1940,'汪伪政权核心成员','汪伪政权核心成员，掌管伪财政与警政，其伪政权体系延伸至安徽各地，马鞍山、当涂地区伪组织亦在其系统之内。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2bad0a5fe024512b0c82dcac3b29222','4b960b21-0f1b-4a86-b642-8dea0dee586a',1940,'汪伪宣传系统头目','汪伪宣传系统头目，后任伪安徽省长，在安徽推行奴化宣传与伪化统治，马鞍山、当涂地区伪教育、宣传机构受其节制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9047dc916f184f85b4058ba1ef17be3d','01bcaeb0-b478-4e79-a132-cc7fe932c07c',1938,'汪伪政权成员','汪伪政权成员，曾任伪安徽省长，在安徽沦陷区推行伪政，其辖区包括当涂、马鞍山地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f4d2a5c03334a14848cc7ff78e7bf06','01bcaeb0-b478-4e79-a132-cc7fe932c07c',1938,'汪伪政权成员','汪伪政权成员，活动于华中伪政权，其体系与广西周边伪政权有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
