INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1a85a6594e941dba0c7c041d74b620a','7c656505-d111-4d09-86c7-f561dd962c7a',1943,'汪伪伪军高级将领','汪伪伪军高级将领，其伪军系统在苏皖边区活动，对马鞍山、当涂地区抗日力量构成威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-184f8636b2aa4a4da3c70e9b4e50f42c','73954447-e30a-440b-ba0c-0f7ad79c6770',1939,'汪伪特工头目','汪伪特工头目，其特工网络覆盖南京周边及安徽当涂、马鞍山地区，搜捕抗日人员，镇压民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba3491d644a541708e0df1c0d4c7e854','08af5871-c57e-406b-b7fc-50ec90ccfba3',1939,'汪伪特工骨干','汪伪特工骨干，在南京及周边包括马鞍山、当涂一带进行特务活动，迫害抗日人士。','危害等级C（丙级，基层头目）','hanjian');
