INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b782f227893440ab861a10255ecf2fab','f1294ee4-e030-4d7d-a369-9654ac9f3daa',1940,'汪精卫死后继任伪国民政府代主席','汪精卫死后继任伪国民政府代主席，继续推行附日政策，抗战胜利后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
