INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62104803f68940e786559a9176c8b006','2f8f9d56-1c2e-4e60-9999-58da98ae7e66',1937,'北洋政客','北洋政客，抗战期间投敌，历任伪临时政府内政部长、伪华北政务委员会委员长等职，抗战胜利后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
