INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44989463dd794603a7d0ec56437beca7','3bddcb9c-c41e-4f14-a967-c6c44b01a918',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一。曾任伪财政部长、警政部长等职，参与对安徽沦陷区的控制与掠夺，其伪政权体系延伸至黄山、休宁一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b66fe248ab1c41d9929bc04d46818ff6','5d0b6e21-a1e3-4ee8-bd68-66abae1c38a4',1938,'广东乳源人','广东乳源人，汪伪政权重要头目。汪精卫死后任伪国民政府代主席、行政院长，继续推行附日政策，其伪政权对安徽沦陷区包括黄山、休宁地区实施统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-074e6b09b37944fea2bc1b813ec8302a','4ecdc0a7-3095-4118-80c3-257342a525de',1940,'广东信宜人','广东信宜人，汪伪政权宣传部长，后任伪安徽省长。在安徽沦陷区推行奴化宣传与伪化统治，涉及黄山、休宁地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f264e527446454983f3393b1a0ffb94','4ecdc0a7-3095-4118-80c3-257342a525de',1940,'广东信宜人','广东信宜人，汪伪政权宣传系统负责人，后任伪安徽省长，在安徽进行亲日宣传和伪化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0678f27e154477c8fc6846dd55f7afc','0938a469-4c9e-4ce4-be4f-b5678196b10a',1938,'休宁本地人','休宁本地人，抗战期间组织伪维持会，任会长，为日军征集物资、情报，协助日军维持占领区秩序，是休宁地区直接附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4482b53fe9b54c87a93396b14441a765','050f9521-68e0-47f0-bcca-ec94b7f53f61',1940,'休宁人','休宁人，汪伪政权委任的伪休宁县知事，在休宁推行伪化行政，征粮征税，配合日军统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc2ab184e2474ac68c15af9ce9c7d676','3ec5ea55-57ce-4f31-b623-235d0294997e',1938,'黄山地区（今黄山市）人','黄山地区（今黄山市）人，抗战期间任伪维持会会长，协助日军管理黄山风景区及周边地区，为日军提供向导与物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbf2c957702d47a599501677c7c6de28','b74bead5-50b7-463b-bb16-c457014afdac',1938,'屯溪（今黄山市屯溪区）人','屯溪（今黄山市屯溪区）人，任伪屯溪维持会会长，在屯溪及周边休宁等地为日军服务，维持伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6267929efacb4c1dac16b5b8f0f62825','6d3236c6-dfa8-4740-857a-8cf9571d9544',1938,'原国民党军将领','原国民党军将领，投敌后任伪第四方面军总司令，活动于豫东、皖北一带，对安徽沦陷区有影响，间接涉及黄山、休宁地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6fd5f4537114d9e86af1951bf272a74','6d3236c6-dfa8-4740-857a-8cf9571d9544',1938,'在豫东、皖北地区组织伪军','在豫东、皖北地区组织伪军，配合日军进攻抗日根据地，其活动范围接近陕西。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db4703a1adb94e9a810b57e13a7c66d1','b5078648-dbb5-4ea5-b517-57fc55728c33',1940,'山西人','山西人，汪伪政权官员。曾任伪安徽省长，在安徽沦陷区实施伪化统治，涉及黄山、休宁地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-316a3844d09e4512bb49ccd59e302d4e','49bffcca-73c7-4bd5-94a0-a1007dd69a15',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建伪政权，其伪政权体系延伸至安徽各地，对屯溪等皖南地区有间接统治影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
