INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b75b05adc6d4a94863e2a527da383c4','8fb79d29-a404-4e04-a870-549b7dd35d6f',1938,'祖籍安徽婺源（今属江西','祖籍安徽婺源（今属江西，历史上长期属徽州），1938年公开叛国投敌，1940年在南京成立伪国民政府，任主席兼行政院长，与日本签订卖国条约，推行‘和平反共建国’路线，是抗战时期最大汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
