INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9e23a1af19f4903b0377ed09519337f','a769fa78-f09e-4021-aecf-4c43472b4ae1',1940,'在广饶推行日伪奴化教育','在广饶推行日伪奴化教育，参与新民会宣传，协助日军控制学校和社会团体，向民众灌输“大东亚共荣”思想。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
