INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7adfb5c3f7748c8a82c6e87e41c3fde','59e63bbe-80cd-4009-b52b-91a029c13b02',1938,'山东寿光人','山东寿光人，抗战期间长期在鲁北、鲁中一带活动，后投靠日军，所部被编为伪军，配合日军对清河区、渤海区抗日根据地进行扫荡，其势力范围涉及淄博北部及高青周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
