INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b374b9697e0a4c6cb16371e3fcb1dc2f','7fefa2ee-eced-4012-a548-7fd7d94d2af2',1937,'原为土匪','原为土匪，抗战期间投靠日军，率部在山东胶东地区活动，曾窜扰文登、威海周边，配合日军扫荡抗日根据地，残害民众。','危害等级C（丙级，基层头目）','hanjian');
