INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3adbf51f3fb44bc184a23881ce487bf2','50617a20-490d-4697-8971-5193869aeaef',1937,'原为土匪','原为土匪，抗战爆发后投敌，被日军委为伪军头目，率部在鲁南、临沂、沂南山区活动，配合日军进攻抗日根据地，烧杀抢掠，1943年被八路军击毙。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ca9937e45cd43889cd3488b3cf3ec79','b4ac4ca8-e200-4cf2-a8cb-4001a54eb32b',1938,'临沂沦陷后出面组织伪维持会','临沂沦陷后出面组织伪维持会，协助日军维持城区秩序、征粮派款，诱迫商户和居民服从伪政权，为日军侵华提供后勤支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
