INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1a7c574ea2748ab848fb5ee85a39dc1','94943f7f-9f3d-4f1a-92f2-96e1ac5f8dd0',1939,'在伪沂州道公署任职','在伪沂州道公署任职，参与临沂、沂南地区伪政权建设，推行奴化教育，协助日军征发劳工、物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c6c0d1180204f8089b633265b2952b0','f24c4d26-455e-40da-9715-fc7ebc4ab4c5',1938,'任伪临沂县警察局长期间','任伪临沂县警察局长期间，带领伪警察配合日军搜捕抗日人员，镇压群众反抗，维护日伪统治秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-172a260e86024c5abc6ae7220fcaeafb','aee9ac1b-8220-4d9e-9f24-d3c258d70f41',1940,'出任伪沂南县知事','出任伪沂南县知事，在沂南地区建立伪政权，推行保甲连坐，为日军征粮、征夫，配合日军对抗日根据地进行经济封锁和军事扫荡。','危害等级C（丙级，基层头目）','hanjian');
