INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f36602e729814744a1d8f567e1a2c0be','095a0dfb-8b0a-4c11-9b99-c9a5e80564d7',1938,'在临沂、沂水一带活动','在临沂、沂水一带活动，抗战中后期与日伪勾结，接受伪职，配合日军进攻抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ddc6d5762d3d43ca95e6904ad086baa2','5cbc2bdb-f526-46f8-82cf-2a7b620291a6',1938,'在山东胶东及鲁南地区活动','在山东胶东及鲁南地区活动，后投靠日军，配合日伪扫荡，其势力一度覆盖临沂周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1afcd0c725ac42be9e4f3d170f0b3f5c','a6f69e2c-4198-4f7b-b0b5-ddcd21ec812c',1938,'在临沂河东地区组织伪维持会','在临沂河东地区组织伪维持会，为日军征粮派款，协助建立伪保甲制度，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a4d2cc76c5348c0bf66aa9b57328baf','99bed72d-6300-4c8d-9b10-da86a0d6847c',1940,'率伪保安团在临沂及河东一带配合日军扫荡','率伪保安团在临沂及河东一带配合日军扫荡，抓捕抗日军民，抢掠财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a43d886632484bc1babb6bea34e5aa96','dff05cc1-48a1-44a9-bca0-c6ba7b61bfd0',1938,'任伪临沂道尹期间','任伪临沂道尹期间，推行日军殖民统治政策，督饬各县伪政权征粮、抓丁、修路，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57091fdd7f4f4eaa872a96022fc4f6a9','34b9c6db-46d4-4940-b852-6bfa0d75e6e6',1939,'在临沂推行奴化教育','在临沂推行奴化教育，编写亲日教材，组织师生参加日伪宣传活动，毒害青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19437c843534456b984d872238e13f8d','c2c1637c-6c11-4983-947a-06216e975cce',1938,'控制临沂城区商业','控制临沂城区商业，为日军筹集物资，配合经济封锁，压榨商户和百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8a9f3310fff41638ed0ce44a59e8709','2b571e0a-5b5a-471f-9515-ce57acd0078f',1938,'原国民党军将领','原国民党军将领，后投靠日军，在胶东及鲁中南地区配合日军扫荡，其伪军活动曾延伸至临沂北部及沂水、蒙阴一带，对罗庄周边抗日根据地构成威胁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f93de5947d9b496f918d2a285a51b841','2b571e0a-5b5a-471f-9515-ce57acd0078f',1938,'原国民党军将领','原国民党军将领，后投靠日军，在胶东地区配合日军进攻抗日根据地，活动范围覆盖威海、烟台一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c2d68506ee648f68abb4882ff8aae11','2b571e0a-5b5a-471f-9515-ce57acd0078f',1938,'原国民党军将领','原国民党军将领，后投靠日军，盘踞莱阳、海阳、即墨一带，控制胶东部分地区，配合日军进攻抗日根据地，1945年被八路军击毙。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b7296d88882410b85d0150fdc31eec1','fc8082cf-ab08-42da-a245-990c6b2dbfe8',1937,'绰号刘黑七','绰号刘黑七，长期在鲁南、沂蒙山区流窜，投日后任伪军头目，配合日军扫荡临沂、费县、平邑等地，烧杀抢掠，罗庄周边村庄亦受其害。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68a8164d77a74168abe4c0c3765883a3','5a1414dc-7a65-45c3-a032-9065ff58f073',1938,'日军在临沂设立伪沂州道后出任道尹','日军在临沂设立伪沂州道后出任道尹，管辖临沂、郯城、费县等县，推行伪化教育、经济统制，为日军征集物资，其道署驻临沂城，直接影响罗庄地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0df2797dd4e4aa5843136d85ad1309c','59cb9aff-0d39-467e-ae77-937209da4903',1939,'任伪临沂县警察局长期间','任伪临沂县警察局长期间，带领伪警察配合日军搜捕抗日人员，在罗庄、付庄一带设立检查站，勒索百姓，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e301d4dd124b4eb59ffe2a397b8872c8','0566a852-085c-42b7-9e81-a07fcd321a3b',1938,'在罗庄一带组织维持会','在罗庄一带组织维持会，为日军带路、征粮，协助建立伪保甲制度，监视村民抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95bd8783cca34a2189a9940dd3cefb43','98832e6e-bf42-470d-9014-17da61d8628c',1940,'任伪付庄乡乡长','任伪付庄乡乡长，配合日军在付庄、罗庄一带清乡，强迫村民修筑据点，提供情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2c9517aa98a4f74aa20f163352cd1ee','842ab069-96ec-4171-8605-3fdaf378d3c5',1939,'在伪沂州道警务系统任职','在伪沂州道警务系统任职，负责临沂及周边县伪警察调度，参与对罗庄地区抗日群众的镇压。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-512720bb359f482994b1005c658c8234','7bd6f65c-303a-4e38-b4a4-235988fb6191',1938,'主持伪新民会临沂分会','主持伪新民会临沂分会，推行奴化教育，在罗庄等地设立日语学校，宣传“大东亚共荣”，毒化民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b7113b6d3044d1690c1c9faaeac71c7','8311286c-6810-4b66-8b5b-52925865818c',1938,'抗战期间投靠日军','抗战期间投靠日军，在临沂地区组织维持会，协助日军维持占领区秩序，推行伪化统治，搜捕抗日人员，为日军征发劳役和物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7433861149141a99296a192e520015b','8311286c-6810-4b66-8b5b-52925865818c',1938,'日军侵占临沂后出面组织维持会','日军侵占临沂后出面组织维持会，后任伪临沂县县长，协助日军推行保甲、征粮、抓丁，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a04e8096847349ff83fbf8c0628b7dc1','69c0ce04-3989-4283-9d7d-dc704f083033',1939,'在日军占领临沂期间担任伪警察头目','在日军占领临沂期间担任伪警察头目，负责维持城区治安，抓捕抗日嫌疑人员，协助日军推行保甲制度。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a11f6e0857940228b1c3c0b6343c642','69c0ce04-3989-4283-9d7d-dc704f083033',1939,'在临沂沦陷后投敌','在临沂沦陷后投敌，任伪警察局长，协助日军搜捕抗日人员，推行治安强化运动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d1d36acaf3644a79dc867d192afb6dc','18804a4e-13c6-413b-b30d-64ce84dd7f99',1940,'在莒南地区组织维持会','在莒南地区组织维持会，为日军征集粮食、劳工，协助日军建立伪政权，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
