INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5b133e333604db88dbc1cdd717fe0a8','18dd69ef-70e4-46cb-a32f-50f8aef0917a',1938,'在山东胶东及鲁南一带投靠日军','在山东胶东及鲁南一带投靠日军，所部伪军配合日军扫荡，与八路军为敌，后活动范围涉及鲁南地区。','危害等级B（乙级，市县厅局级）','hanjian');
