INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02308986f418460e80e480e09ad2e687','f3e971fe-d42e-49b0-a7f7-c2c22676a99b',1931,'原名仓谷次太郎','原名仓谷次太郎，日本浪人出身，长期在山东活动，组织伪军配合日军进攻胶东和青岛周边地区，参与对即墨、平度、莱阳等地的扫荡与镇压。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c71ea6e25124919ab7af7ec247dc513','f3e971fe-d42e-49b0-a7f7-c2c22676a99b',1931,'原名仓谷次太郎','原名仓谷次太郎，日本浪人出身，抗战期间在山东收编土匪、散兵组织伪军，配合日军进攻胶东抗日根据地，活动范围涉及青岛、平度一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d837535cbc242068020623c1d13ff09','f3e971fe-d42e-49b0-a7f7-c2c22676a99b',1931,'原名张宗昌之弟张宗援','原名张宗昌之弟张宗援，抗战期间在山东投敌，组织伪军配合日军进攻胶东抗日根据地，活动范围涉及青岛、莱西周边地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-350481f991fc416088329ca4c6290c1d','515845b4-564e-4277-9a70-c6817178db5e',1938,'原国民党鲁东军区部队','原国民党鲁东军区部队，后公开投敌，盘踞胶东莱阳、海阳、即墨及威海周边地区，配合日军进攻八路军胶东根据地，在威海一带参与扫荡、抢粮、镇压抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eaef1c9a550c4d768f27b71461bf7343','515845b4-564e-4277-9a70-c6817178db5e',1938,'原国民党军将领','原国民党军将领，后投靠日军，盘踞胶东莱阳、海阳一带，多次配合日军扫荡胶东抗日根据地，对威海、荣成地区抗日力量构成威胁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b255d951c494508a3e227cbc8935ea1','515845b4-564e-4277-9a70-c6817178db5e',1938,'原国民党军将领','原国民党军将领，后率部投降日军，盘踞胶东莱阳、海阳一带，任伪暂编第十二师师长，多次配合日军扫荡胶东抗日根据地，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc316e779a90468188c677974c60949f','515845b4-564e-4277-9a70-c6817178db5e',1938,'原国民党军将领','原国民党军将领，后投靠日军，盘踞胶东莱阳、招远一带，配合日军进攻抗日根据地，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c12ec4a546c495896ab935436679a4a','515845b4-564e-4277-9a70-c6817178db5e',1938,'原国民党军将领','原国民党军将领，后率部投降日军，盘踞胶东莱阳、栖霞、海阳一带，配合日军进攻八路军胶东根据地，残害抗日军民，1945年被八路军击毙。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec4df65be88d462080dc8bf18aa79b94','6f587c6c-8c47-48c4-95a2-7d3e3a2bf0d2',1938,'在山东胶东地区组织伪军','在山东胶东地区组织伪军，活动范围涉及威海周边，配合日军对胶东抗日根据地实施封锁和扫荡，参与抓捕抗日人员、强征劳工。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46285bdc6966452b895f14bb9b4e1651','6f587c6c-8c47-48c4-95a2-7d3e3a2bf0d2',1938,'在胶东地区组织伪军','在胶东地区组织伪军，配合日军扫荡，活动范围涉及烟台、平度、莱阳等地，参与维持会与保甲制推行。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-890ed8de418a4cfe903ddcd341ff88e8','a8a71592-874d-46f4-b066-9e50a9a6439e',1938,'抗战期间在青岛及胶东地区附逆','抗战期间在青岛及胶东地区附逆，担任伪职，协助日军维持占领区统治，其势力范围与威海地区有联系，参与经济掠夺和治安强化运动。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59e8bd4718b446c39b21ec12b1571bc9','a8a71592-874d-46f4-b066-9e50a9a6439e',1938,'抗战时期在山东伪政权中任职','抗战时期在山东伪政权中任职，参与日伪统治，其活动范围涉及胶济铁路沿线，对潍坊、昌邑等地物资征调和伪化统治有间接影响。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8992c71475584cdabf2722cd00af2f04','a8a71592-874d-46f4-b066-9e50a9a6439e',1938,'抗战时期在山东伪政权中任职','抗战时期在山东伪政权中任职，参与日伪统治，其活动范围覆盖山东东部，与烟台、海阳地区伪政权有联系。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d508e9646f80491e9149b554aef7a82e','a8a71592-874d-46f4-b066-9e50a9a6439e',1938,'在日军占领青岛后出任伪职','在日军占领青岛后出任伪职，协助日军维持统治，其活动范围覆盖胶东地区，与烟台伪政权有联系。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8828351aa9cc4b8b99e966d27e7d7c9b','a8a71592-874d-46f4-b066-9e50a9a6439e',1938,'抗战时期在山东伪政权中任职','抗战时期在山东伪政权中任职，后任伪青岛特别市市长，参与日伪统治，其活动范围覆盖山东东部，与烟台地区伪政权有联系。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48944451ca1d4782bbbaf5b223e6584d','a8a71592-874d-46f4-b066-9e50a9a6439e',1938,'抗战后期在青岛附逆','抗战后期在青岛附逆，任伪青岛市市长，协助日军维持山东东部占领区统治，其影响范围覆盖胶东烟台、莱阳周边区域。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f1ac8c138bb410687b6dd0778b7e4c9','a8a71592-874d-46f4-b066-9e50a9a6439e',1938,'抗战期间在青岛地区附逆','抗战期间在青岛地区附逆，担任伪职，其活动范围涉及胶东地区，与烟台、蓬莱等地伪政权有联系。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-601d818526a242bd8ef2757a5c53dc31','302f9742-aabe-4672-bd42-00ca366dca7d',1938,'在青岛及山东沿海地区为日军服务','在青岛及山东沿海地区为日军服务，推行伪化教育、经济统制，其管辖范围与威海地区有行政和军事联系，协助日军镇压抗日活动。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0addd67180c34cdfb5c57a2859500ef7','47705d1f-80cf-49e3-83a5-770f5d9fc011',1938,'日军侵占威海卫后','日军侵占威海卫后，出面组织伪维持会，协助日军维持地方治安、征粮征款、登记户口，镇压抗日群众，是威海本地早期附逆代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e342cb7a7124478eae7a9e2914b1116d','168790fd-3282-4776-b32e-ca47956bec9d',1940,'在威海卫伪政权中任职','在威海卫伪政权中任职，配合日军推行保甲制度、治安强化运动，参与抓捕抗日人员、强征劳工和物资，为日军统治服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c2c405700454ddaaedbc5f9b3fda42e','3c6d2ea3-3fd8-4555-b1fa-3149e54f48bf',1938,'在威海卫伪警察系统任职','在威海卫伪警察系统任职，带领伪警察配合日军搜查、抓捕抗日人士，镇压群众抗日活动，维护日伪在威海卫的殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83351a08e4ed4aeab4bce4afb3c48582','590f66e3-b0dc-44dc-84a1-34bbcddcd8c2',1938,'在文登及威海周边地区组织伪维持会','在文登及威海周边地区组织伪维持会，协助日军征粮、征丁、建立伪保甲，参与对胶东抗日根据地的封锁和扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6287d65905fd446ca6b91be3a7e70670','26b0376d-4714-431c-ba1e-c3888f0b73f3',1938,'在牟平及威海周边地区附逆','在牟平及威海周边地区附逆，组织伪军和维持会，配合日军进攻昆嵛山抗日根据地，在威海一带参与扫荡、抢粮、抓捕抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a26ae633e4fd4331a772d2f90bd19535','24cefd71-c542-4b4e-9d64-a131bca1db87',1938,'在荣成及威海沿海地区组织伪政权','在荣成及威海沿海地区组织伪政权，协助日军控制沿海港口、征用民船、封锁抗日根据地，参与镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c968fbe79f2947c6b15eaa80bd742b8d','a7952af3-c099-46f1-bb38-8c1ab6aba53e',1938,'在威海卫为日军筹款筹粮','在威海卫为日军筹款筹粮，组织商户为日伪服务，协助日军实施经济统制，掠夺当地海产和物资，支持日伪统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-014474633f2a4fbf9b8f7647fd75c35f','a73bf309-c5a0-4ba1-a4bc-299aef7cdb6f',1938,'在威海卫推行奴化教育','在威海卫推行奴化教育，编写和采用亲日教材，组织师生参加日伪宣传活动，为日军殖民统治培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88e9eba9803843be8bc156bd239fcade','f2bfebdb-2f8e-49a4-98f3-1b175b62a7ab',1938,'在威海卫组织伪新民会','在威海卫组织伪新民会，宣传“大东亚共荣圈”，配合日军进行思想控制和奴化宣传，拉拢地方士绅附逆。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8efd06e5d6bb4f07ac117f37b72dde82','ee7b3508-ed53-4880-ab7f-01a4b9068a34',1938,'在威海卫组织伪保安队','在威海卫组织伪保安队，配合日军维持治安、搜查抗日人员，参与对周边抗日根据地的扫荡和封锁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a5792c3f4aa465cacc7a245b361685b','cdeb91bd-ec6f-4218-9599-2c8827de043a',1938,'在烟台及胶东地区附逆','在烟台及胶东地区附逆，担任伪市长，协助日军统治烟台和威海周边地区，推行治安强化运动，参与经济掠夺和镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c8154c363384c9c9e64744fbf735b83','e8fba001-1f54-4279-9511-fcb56d1e1033',1938,'在烟台伪警察系统任职','在烟台伪警察系统任职，配合日军在烟台、威海一带抓捕抗日人士，镇压群众抗日活动，维护日伪统治秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a8e5e89b54d4ee0867ecf96134d7d81','6e04ea6c-93d3-483c-aa9c-3d480f492009',1938,'在胶东道伪政权中任职','在胶东道伪政权中任职，管辖范围包括威海地区，协助日军推行伪化政策、征粮征丁、封锁抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85d079a489eb4efea5c2ee2aeba28d3d','bb5e473d-8f33-4665-9ad0-ffbeab779ac6',1938,'在伪山东省政府中任职','在伪山东省政府中任职，参与制定和实施日伪在山东的统治政策，其政策覆盖威海地区，协助日军镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5887b552aebe4cdfa1252fb18ae19b0b','33049350-e15e-44dd-8371-009c8b9b429b',1938,'担任伪山东省省长','担任伪山东省省长，全面协助日军统治山东，推行治安强化运动、经济统制、奴化教育，其政令覆盖威海地区，对当地抗日力量进行镇压。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02830063a3bd4b65b41245423c264f6d','31aa6782-4f78-4946-9f2c-4b8a5a87728e',1938,'抗日战争时期投靠日军','抗日战争时期投靠日军，出任伪威海卫专员公署专员，协助日军维持威海卫及周边地区统治，推行伪化政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
