INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-962af56726b543adbf9e4250576a6969','bc174d59-8f50-4496-a50f-6155d6a30dec',1937,'原为土匪','原为土匪，抗战期间投靠日军任伪军师长，活动于鲁中、鲁南包括淄博、沂源一带，配合日军进攻抗日根据地，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ba696c7c8314f9ba05dc46afe8a947e','02182c4a-c27b-4946-be94-1633162be9eb',1938,'投靠日军后任伪军头目','投靠日军后任伪军头目，活动于山东南部包括枣庄、滕县周边地区，配合日军进攻抗日根据地，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f8729bfcb8045d7b90306d07a18a948','554f7986-b905-49a0-84b8-9f661679890d',1938,'在鲁南地区投敌','在鲁南地区投敌，组织伪军配合日军扫荡，活动范围覆盖枣庄、临沂一带，对当地抗日力量造成较大破坏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e13b1b88740c4d159f92007a4f9c54a0','3bbf6aef-ac46-4dc1-b825-9ed2a8d1bdf8',1939,'在峄县、枣庄地区组织伪保安队','在峄县、枣庄地区组织伪保安队，协助日军维持占领区秩序，参与抓捕抗日人员，征敛物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9063cdfb43e94a6d8a8da828c36967de','d8412fd6-df22-4c07-bf4a-85c8b74ea7e0',1938,'在滕县地区为日军服务','在滕县地区为日军服务，担任伪区长和维持会成员，负责摊派粮款、登记户口，协助日伪控制基层。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f35b48840dee478f978ca098b818e9bb','d3f1a8f7-dc47-452b-a012-4330502b9665',1938,'在伪鲁南道尹公署任职','在伪鲁南道尹公署任职，管辖包括枣庄、滕县在内的鲁南地区，推行日伪政策，协助日军征发物资和劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79fbba4684044096823eb8295f5f68c3','559bb09d-163b-4898-a498-9eaf4a69da6a',1939,'在枣庄、峄县地区推行奴化教育','在枣庄、峄县地区推行奴化教育，担任伪中学校长，宣传“大东亚共荣”，毒害青年学生。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc59c7d89f4c45169c0751a47e87c4f4','946ba229-097b-4858-9e70-4b1887c5d3a2',1938,'投靠日军后任伪军指挥官','投靠日军后任伪军指挥官，活动于胶东及鲁南部分地区，配合日军扫荡，后于1945年被八路军击毙。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdb8ee6e9fe84cb590583eb2a841bf79','d7a9068a-9a96-4116-9afc-b54509030789',1938,'在山东地区组织伪剿共军','在山东地区组织伪剿共军，配合日军进攻抗日根据地，活动范围涉及鲁南枣庄、滕县周边，残害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-257f13a3a85c4d88a3f23b67577dbb06','d6887b42-9ed6-42d4-b5a0-7c3f5e403956',1938,'在枣庄煤矿区为日军管理矿工','在枣庄煤矿区为日军管理矿工，组织维持会，协助日军掠夺煤炭资源，压迫矿工。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3032ae91f474841995e3f165918939b','74b68821-b404-468c-bc80-1821c2f87951',1938,'在鲁南地区投敌','在鲁南地区投敌，组织伪军配合日军行动，活动范围包括枣庄、滕县一带，参与对抗日根据地的扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe0a9f0f781b4ce7b01d6ab013f0c8cf','3b7056d7-e77d-41ba-aeb3-2f523ef26a02',1938,'日军侵占峄县后','日军侵占峄县后，参与组织伪政权，任伪峄县县长等职，在枣庄、薛城一带推行日伪统治，征粮派款，协助日军维持占领秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52d8853eff824146bcb42d85eb9dd534','8ad72c67-5988-4b4e-ba27-38fdcaf61c25',1937,'原为山东地方武装首领','原为山东地方武装首领，活动于鲁南、枣庄、临沂一带，抗战中后期与日伪勾结，所部部分投敌，配合日军对付八路军和地方抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91d40d0b34b044dcae9c71de339d5649','587af2a3-808e-4eed-ad90-076193aae75d',1938,'在鲁南临沂、枣庄、费县一带活动','在鲁南临沂、枣庄、费县一带活动，后与日伪合作，进攻抗日根据地，残害抗日群众，其武装在抗战后期具有明显附逆性质。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-026b0b73a02b415e9ff85fb838dc097a','563252d1-9d84-41c4-8547-a1f83f00bd9b',1938,'日军占领滕县后','日军占领滕县后，出任伪滕县县长，在滕县、枣庄北部一带协助日军建立伪政权，推行保甲、征粮、抓丁等政策。','危害等级C（丙级，基层头目）','hanjian');
