INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3d369e5fe8749b99589d88eb36e468c','5c57ad36-4cc9-4468-a59b-5c11d2c68a59',1938,'蒲台沦陷后投敌','蒲台沦陷后投敌，组织维持会并任伪县长，为日军征集物资、修筑据点，协助日军对清河区进行治安强化运动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
