INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8105652a05f747f397e1d5d4207cec23','afe2c886-7522-4882-8b98-bbfc34267c36',1939,'在滨县建立伪警察体系','在滨县建立伪警察体系，推行保甲连坐，搜捕抗日人员，为日军提供情报，配合日伪军对滨县周边村庄进行清乡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19e2e2ef83684317a093870b8d171420','be236c97-7212-4b93-b423-41b8508df0b8',1940,'在滨县推行奴化教育','在滨县推行奴化教育，编写亲日教材，组织学生参加亲日集会，为日军培养伪职人员，毒化当地青少年思想。','危害等级C（丙级，基层头目）','hanjian');
