INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6c87562f19247d7bd335008905afc41','bbf65982-92f2-4e63-8c3e-bc653d51ccd9',1938,'在鲁东及潍坊地区活动','在鲁东及潍坊地区活动，后投靠日伪，参与组织伪军和维持会，配合日军对昌邑、潍县、平度交界地区进行清乡和扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9baf64bc583e4f308a9cab676050ee5f','bbf65982-92f2-4e63-8c3e-bc653d51ccd9',1938,'在胶东地区率部投敌','在胶东地区率部投敌，任伪军司令，配合日军扫荡莱阳、烟台周边抗日根据地，残害百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c451d7285ac46f6a3b48b2fad7cacb6','bbf65982-92f2-4e63-8c3e-bc653d51ccd9',1938,'在胶东平度、莱阳一带活动','在胶东平度、莱阳一带活动，后投敌任伪军职务，配合日军扫荡抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5b720e6a13c49edbe350a3fae56f255','bbf65982-92f2-4e63-8c3e-bc653d51ccd9',1938,'在胶东地区投敌','在胶东地区投敌，组织伪军配合日军扫荡，活动于莱阳、莱西、即墨一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a689aa7a40af4ec39391599497450785','2bd5911b-8c3d-411f-b406-0dd298dcaeb5',1938,'曾任伪山东省省长','曾任伪山东省省长，协助日军建立伪政权体系，推行伪化教育、保甲连坐和物资统制，对潍坊及昌邑地区伪政权建立有推动作用。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b3debf1a0ba41bb9e04313c3106c005','b8bb60fc-4674-4834-ac59-8f1650b886a9',1938,'在伪山东省政权中负责警务','在伪山东省政权中负责警务，建立伪警察系统，配合日军在潍坊、昌邑等地搜捕抗日人员、镇压群众，推行治安强化运动。','危害等级B（乙级，市县厅局级）','hanjian');
