INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4712cc2f258f4f8bab99cba430893add','765017be-a1b6-44c9-9af2-441048525bef',1938,'原国民党军将领','原国民党军将领，后投敌任伪职，活动于胶东及鲁中一带，其伪军系统与聊城、莘县周边伪军有协同配合，参与对鲁西北抗日根据地的封锁与扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
