INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38b90d1bba134a66a40022c264e748fd','d3eb3eae-fc97-46ce-b46b-9c1728355385',1938,'为日军筹款筹粮','为日军筹款筹粮，控制聊城物资流通，配合经济掠夺，压榨商户和百姓，资助伪政权。','危害等级C（丙级，基层头目）','hanjian');
