INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb3bce8c07a2406fb61b80332747814d','4f58ac61-4733-44bd-b8c9-2b9d05b01e9d',1941,'率伪军盘踞聊城、高唐交界地区','率伪军盘踞聊城、高唐交界地区，配合日军扫荡，抢劫粮食牲畜，杀害抗日家属，破坏抗日政权。','危害等级C（丙级，基层头目）','hanjian');
