INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a7def08d754491b80285e4072b95ae0','dc49df1f-a5d6-4b8b-a03b-df826b9b6379',1940,'统领伪保安团','统领伪保安团，驻守聊城及周边据点，配合日军进攻抗日根据地，抓捕壮丁，征发民夫。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1e2ec604e234f9bbd0afdc353f205b3','4826dbe7-a66b-42d8-b402-2003194f5c12',1939,'为伪政权搜刮民财','为伪政权搜刮民财，征收各种苛捐杂税，保障日军军需，导致高唐民生凋敝。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60543f920ab64bed81a6fc25ae24a229','2464ea28-4a63-4a4e-affc-c8dea879f323',1938,'在菏泽及鲁西南地区依附日军','在菏泽及鲁西南地区依附日军，组织伪军，协助日军维持占领区秩序并参与对抗日武装的进攻。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
