INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a8acc5d7fd845578e81ba99b6c894f2','d78537e8-3de3-4151-8cfd-91dd44fa5901',1942,'率部投敌','率部投敌，所部伪军在鲁西南及菏泽地区配合日军作战，参与对抗日根据地的扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
