INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e67ebb7350f84334b3c6490458e043a3','e9280ea8-9af9-4045-82e6-0c8f2fcc4e91',1938,'抗日战争时期投靠日军','抗日战争时期投靠日军，任伪东明县县长兼警备队大队长，组织伪政权和伪军，配合日军对东明及周边地区进行扫荡，镇压抗日军民，强征粮款，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63ad4899285146f789fc729fd958b6fa','b218b2e0-8728-4d73-870e-dcf8f122fedb',1938,'日军侵占东明后出面组织维持会','日军侵占东明后出面组织维持会，为日军筹粮筹款、拉夫派丁，协助日军维持占领秩序，是东明地区较早投敌的汉奸头目之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba24209d2c9d4b9891dab82b26a76a82','71afe522-c43e-4c04-a7e1-480b7fac686a',1940,'率伪军配合日军在東明、菏泽交界地区进行清乡扫荡','率伪军配合日军在東明、菏泽交界地区进行清乡扫荡，抓捕抗日人员，抢掠民财，欺压当地群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c71db2e12d34d8c94f2b8633e978390','31aca8d3-628a-4d1e-8b7d-6a566405311c',1938,'日军占领菏泽后出任伪县长','日军占领菏泽后出任伪县长，建立伪政权，推行保甲制度，为日军征粮征税、搜集情报，配合日军对菏泽及东明一带的抗日根据地进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dffb3357a0d24748b5f75101aa477973','adcf907c-964f-4a66-a638-15977a5009c9',1938,'在菏泽沦陷后组织维持会','在菏泽沦陷后组织维持会，协助日军安民、筹款、征粮，拉拢地方士绅附逆，为日军稳定菏泽地区统治效力。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
