INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1622dcd4ffef41fe9998683dcc9a1c72','98edef74-b5f2-4e68-afdf-e2121f44a9de',1940,'任伪鲁西道尹','任伪鲁西道尹，管辖菏泽、东明等县伪政权，推行日军殖民统治政策，督征粮款，配合日军扫荡鲁西抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
