INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2764349b13f84afa81fca88c5b4fb0d3','8b0737d6-3d73-4159-bac2-afdf0e77cbe6',1938,'率伪军在郓城、菏泽一带活动','率伪军在郓城、菏泽一带活动，多次配合日军扫荡，烧毁民房，杀害抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff8c0e44eda543068d023e242273fef5','a6054545-91ac-4daa-9816-e535a24208ae',1938,'抗战期间投靠日军','抗战期间投靠日军，历任伪定陶县知事、伪鲁西道尹等职，在定陶及鲁西地区推行伪化统治，组织伪军配合日军扫荡，强征粮款，镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e25b87c14864014b24fa7dc62884914','5e7986d6-228e-43ba-b895-91132772988f',1938,'日军侵占菏泽后出任伪菏泽县知事','日军侵占菏泽后出任伪菏泽县知事，协助日军建立维持会与保甲制度，推行奴化教育，为日军征发民夫、粮食，参与清乡活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52cbb886b37447acb5cfcd60e74291cb','5e7986d6-228e-43ba-b895-91132772988f',1938,'日军侵占菏泽后出任伪县知事','日军侵占菏泽后出任伪县知事，主持伪政权，推行保甲制度，征粮征夫，协助日军统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-daa67d5eaa1a4ab797563f25c0d9e898','108a32a3-12b9-4722-bc37-23a512d82baf',1938,'菏泽沦陷初期组织维持会','菏泽沦陷初期组织维持会，为日军筹粮筹款、招募伪警，协助日军维持城区秩序，迫害抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f3c5e8d9b6c4d5ea10d0b8898cd251a','66387e39-2e67-4026-b694-29159d81f9ee',1940,'统率伪保安团配合日军对定陶及周边抗日根据地进行扫荡','统率伪保安团配合日军对定陶及周边抗日根据地进行扫荡，捕杀抗日干部和群众，强征壮丁扩充伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3bccb49ccd248788a4f02c6443c3924','3c233377-f345-4930-96f2-fb7ac26a234f',1938,'在曹县、菏泽一带为日军效力','在曹县、菏泽一带为日军效力，历任伪曹县县知事等职，推行保甲连坐，协助日军掠夺物资，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97b233aa66d64e70b39f2c46a6c2e1f3','bee48c60-7ddb-4617-abdd-4659b235defd',1939,'单县沦陷后投敌','单县沦陷后投敌，任伪单县县知事，在菏泽南部地区协助日军建立伪政权，征粮征夫，配合扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f2b4eea66f9409e8955d05cee3f53ac','a749ddd5-efc4-4344-970c-d5784f622ed0',1940,'率伪军在巨野、定陶交界地区活动','率伪军在巨野、定陶交界地区活动，配合日军袭击抗日武装，抢掠民财，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebc603c01aa54f80929c16570f92c8cd','ec4b0e37-811d-4c45-bdb0-de34f8b1eee3',1938,'郓城沦陷后出任伪知事','郓城沦陷后出任伪知事，在菏泽东北部地区推行伪化统治，协助日军征发粮食、劳工，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b26c2036f66f48b79052d1d9e0781ceb','369c1230-06b5-4ae2-8d61-8d97eb97bbff',1938,'在山东伪政权中任职','在山东伪政权中任职，活动范围覆盖鲁西包括菏泽、定陶一带，参与制定伪化政策，协助日军掠夺资源、镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75e12a130ac149cfacadb3c899bcdae6','f1b0a91a-90ed-4fd4-a900-6dad69f86724',1940,'掌控定陶伪警察力量','掌控定陶伪警察力量，搜捕抗日人员，协助日军维持治安，参与清乡与保甲连坐，迫害当地民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ab6aa869c9e46d68d4f717ce1567314','a96bf6c4-159a-4c40-adac-b271366ff4d5',1939,'统领伪保安团在菏泽及定陶周边配合日军作战','统领伪保安团在菏泽及定陶周边配合日军作战，袭击抗日根据地，抢粮抓丁，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bfba435294a04bd7b9d881d839e23283','4a2f7fa3-5b08-4308-94ab-1f913614a320',1938,'任伪兖州道尹期间','任伪兖州道尹期间，其辖区与鲁西相邻，参与对菏泽、定陶一带的伪化协调，协助日军征发物资、镇压抗日。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56be244910b847d99754c9f6da61abcc','ba5b299b-3f24-4e53-a222-caa392a9a762',1938,'抗战期间投敌','抗战期间投敌，历任伪巨野县知事、伪鲁西道尹等职，协助日军推行治安强化运动，搜捕抗日人员，征敛民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a979ed6e0a5e43959c08252e0cce81c7','48af8ed5-c176-4f3d-8fef-d0d0ecbb2f5d',1938,'日军侵占巨野后出面组织维持会','日军侵占巨野后出面组织维持会，为日军筹粮筹款、维持地方伪秩序，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
