INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a1ebde062eb487a926c02bc69f59b78','8b8ed13b-3a87-4ed3-ba61-ab3af552c283',1938,'山东伪政权要员','山东伪政权要员，参与制定伪化政策，曾到菏泽、巨野等地视察督导伪政，协助日军掠夺物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e40353b176248fcb7ce9fc18adcfb55','1e62bc02-eb62-4a92-9a95-bd41c79e0734',1938,'早期伪山东省长','早期伪山东省长，建立伪政权体系，菏泽、巨野等县伪政权在其任内设立并运作。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90e6c107fea24d369e2e022a75ddfbd0','d6a9146c-48f2-4fcf-a65b-59c1b3ebf029',1940,'在巨野推行奴化教育','在巨野推行奴化教育，篡改教材，宣传“大东亚共荣”，毒化青少年。','危害等级C（丙级，基层头目）','hanjian');
