INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e6d30d31503448fbdd9cb2693160e42','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原国民党军将领','原国民党军将领，1938年投敌，所部在鲁西包括菏泽、巨野一带活动，配合日军作战。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69a8d4d1fa4f4306af48bc344706ee5f','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原国民党军将领','原国民党军将领，1938年在豫北投敌，组织伪皇协军，虽主要在豫北活动，但其伪军体系与豫东商丘一带伪军有联系。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73f85de0d0504e729f63f5e0ca10892d','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原国民党军将领','原国民党军将领，1938年在河南北部投敌，组织伪皇协军，虽主要活动于豫北，但其伪军系统与河南沦陷区伪政权、伪军网络相连，影响波及商丘一带的伪军组建。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0ceadca416c4921963c9db183c7e39b','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'在安阳、林县一带组织伪皇协军','在安阳、林县一带组织伪皇协军，配合日军作战，后因内部冲突被日军处死。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3eac956b5083408495c14014e59ef9b6','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原国民党军将领','原国民党军将领，1938年在河南投敌，组织伪皇协军，在豫北、豫西一带配合日军作战，其伪军活动范围涉及河南中部，对平顶山、汝州地区有间接影响。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e14ed7fd772440e6a66366a49850890f','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'在豫北、豫东一带率伪军配合日军作战','在豫北、豫东一带率伪军配合日军作战，后于1938年被日军处死。','危害等级B（乙级，市县厅局级）','hanjian');
