INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25990df8b93d4db0b24653236ffbccb4','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原国民党将领','原国民党将领，1938年在河南林县投敌，任伪皇协军第一军军长，活动于豫北、冀南一带，包括濮阳地区，配合日军进攻抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-004d54034f1f4a35a7a4af9be732c186','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原国民党将领','原国民党将领，1938年在河南投敌，组织伪皇协军，在豫北地区配合日军。','危害等级B（乙级，市县厅局级）','hanjian');
