INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c03e9c9d983d46e480e42192edc74e4a','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原国民党军将领','原国民党军将领，1938年在河南安阳一带率部投敌，组织伪皇协军，配合日军进攻豫北抗日武装，后被击毙。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71c191d30d884cfd9b2c624c49a6eed2','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原国民党军将领','原国民党军将领，1938年率部投敌，任伪皇协军第一军军长，活动于豫北、豫东一带，其伪军曾配合日军向郑州方向进攻。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79bb74960a3b47779359127b9ac69500','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'在河南安阳、郑州以北地区组织皇协军','在河南安阳、郑州以北地区组织皇协军，配合日军进攻，后在水冶被抗日武装击毙。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3c66d6e3ba94a278d36e069de93f226','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原为国民党军将领','原为国民党军将领，1937年在豫北投敌，组建伪皇协军，活动于安阳、鹤壁、淇县、浚县等地，配合日军进攻抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-054f122e021d4419b30321d8df36e04b','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'原国民党将领','原国民党将领，投敌后组建伪军，在华北配合日军作战，对陕西宝鸡抗日后方构成威胁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b11443d34a27465bbe09116aefc4db98','7cd67e1e-c04d-4009-b037-749b286d718c',1937,'在河南、华北组织伪军','在河南、华北组织伪军，配合日军作战，其活动对陕西周边有影响。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-576c70e9384e49e295df6e3fc6a436c0','856b993f-46f0-4b95-a1eb-2de437394ca9',1941,'组织伪保安团','组织伪保安团，协助日军守备巨野，参与清乡，搜捕抗日人员，勒索民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f616031d097e4f718e73099d3a9051e7','bcd508d4-5c5c-496b-8907-615c425e454b',1939,'任伪菏泽警察局长','任伪菏泽警察局长，指挥伪警在菏泽、巨野交界地区抓捕抗日嫌疑人员，镇压抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5278217934734ed38ce67a87f6c75d4c','098ffcfb-c20c-4d1f-9723-8409474e9cd2',1938,'成武沦陷后出面组织维持会','成武沦陷后出面组织维持会，后任伪县知事，为日军征粮派款、修筑据点，协助日伪军清乡，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-703a40dc239a43d48e1efc40cbc55c81','88539b41-a1da-482a-b88e-f1998d98b484',1938,'菏泽沦陷后投敌','菏泽沦陷后投敌，主持伪县政，推行奴化教育，强征民夫修筑菏泽至成武、单县公路及据点，配合日军对鲁西南抗日根据地扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c6d3b9db89c4e40957893981a7b6896','2bf04be6-311d-4f15-b9fb-42dffa947c1d',1938,'在曹县、成武、单县交界地区组织伪军','在曹县、成武、单县交界地区组织伪军，配合日军扫荡，杀害抗日干部和群众，掠夺粮食棉花等物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8fb4dc347fc34f43868dae9b2e113d92','ae564f7a-85f7-4202-baed-676760fa1c27',1938,'单县沦陷后投敌','单县沦陷后投敌，任伪职期间在单县、成武、金乡一带配合日军清乡，强征壮丁，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a4f6ac22773471599495ea1f2e4a0df','e0221d16-e695-4fb2-9b89-20436c1e6f94',1938,'定陶沦陷后组织维持会','定陶沦陷后组织维持会，后任伪县知事，在定陶、成武、菏泽交界地区为日军征粮派款，协助修筑据点，破坏抗日政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f3d2c1534fd4ec28d4bcdf05beee0e6','daa271bc-4124-40cc-9380-2b66077c0b5a',1938,'巨野沦陷后投敌','巨野沦陷后投敌，任伪职期间在巨野、成武、嘉祥一带配合日军扫荡，强征民夫修筑碉堡，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
