INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4c83dd4fd62420cba1e3cc89e80e485','e64c415d-09a3-4cc8-a903-fd42828c30c4',1938,'鄄城沦陷后投敌','鄄城沦陷后投敌，任伪职期间在鄄城、菏泽、成武一带配合日军扫荡，强征壮丁，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4a2a347a1e846e0872ae23082e8b0c1','44a29478-5025-4d9c-b6a8-9ac031b04807',1938,'东明沦陷后组织维持会','东明沦陷后组织维持会，后任伪县知事，在东明、菏泽、成武一带为日军征粮派款，协助修筑据点，破坏抗日政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-817240170c884078aabd915cbe050b10','b0607257-85b0-4661-b251-39829ed67e25',1937,'济南沦陷后组织维持会','济南沦陷后组织维持会，后任伪山东省省长，为日军在山东包括鲁西菏泽、成武地区征粮派款、推行保甲制度，协助日军扫荡抗日根据地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6a3cb076a704bdd80db3f7559ed4b0f','f5f92dd1-e863-4aa7-8215-dbbae073dc4f',1938,'抗战期间投敌','抗战期间投敌，任伪山东省省长及鲁西道尹，在鲁西菏泽、成武、单县一带推行伪化统治，配合日军扫荡，强征粮款，镇压抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a476e8c34704e4ab9f763d3a2612e84','8da694ab-50bc-4117-8671-8676af20b7a6',1938,'抗日战争时期投靠日军','抗日战争时期投靠日军，在鲁西、曹县一带组织伪政权和伪军，配合日军扫荡抗日根据地，镇压抗日群众，横征暴敛。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d26933ee27e345f492b691fe8abbdb61','7b83f619-a83e-43d2-a9a0-2e85646c3624',1938,'日军侵占曹县后出面组织维持会','日军侵占曹县后出面组织维持会，后任伪县长，为日军筹粮筹款、维持殖民统治，协助日伪镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a2ff6ae3fb048f2bc36028ac0d887b5','604bca3f-1b86-4dbe-86f1-af4f76ca1fc8',1939,'在曹县地区统领伪警备队','在曹县地区统领伪警备队，配合日军清乡、扫荡，抓捕抗日人员，残害当地百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
