INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69fbcf7b8a384f56b49464541061e302','c82dc987-d330-4a98-9f5c-5d4fad2aa114',1939,'在定陶及菏泽周边地区组织伪军','在定陶及菏泽周边地区组织伪军，配合日军扫荡，镇压抗日武装，搜刮民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00bd605801a94bdc99d2b61f7c2a10d8','28aa7f8d-45da-4d39-8523-020e031915b4',1938,'单县沦陷后投敌','单县沦陷后投敌，任伪县长，协助日军控制湖西地区，迫害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-826eb3ae35454cccb6748f90f8ea4b10','ca3a59ed-f5d6-4bdd-a6fa-6db78dd75879',1939,'在郓城一带为日军筹粮、征丁','在郓城一带为日军筹粮、征丁，组织伪自卫团，配合日伪军进攻抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6cbbe0aa3a7146f9bbf7803419369f7f','eaeffb0d-ce7d-4c6d-b61e-3e0a97f356b7',1940,'作为日军顾问控制曹县伪政权','作为日军顾问控制曹县伪政权，推行治安强化运动，策划清乡与保甲连坐。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02c18284f6ed48f797cbbd90a0941fe1','d2a7da45-7826-4c86-9a42-36836b9b9032',1941,'统领曹县伪保安团','统领曹县伪保安团，配合日军扫荡曹县、单县交界地区，捕杀抗日干部和群众。','危害等级C（丙级，基层头目）','hanjian');
