INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6cbda3daddac404b9ab22afe1f4f4ded','0f5d527b-d843-45aa-9f89-2d913cd30ed5',1939,'控制曹县商会','控制曹县商会，为日军筹集物资、摊派款项，协助日伪对当地经济进行掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6672987fb4e44bed8f3cd22c9b7b7758','4c5744f7-bdbb-4c53-a98f-41f88a6ddaee',1938,'郓城人','郓城人，抗战期间投靠日军，历任伪郓城县县长、伪鲁西道尹公署道尹等职，组织伪军配合日军进攻鲁西抗日根据地，在菏泽、郓城、鄄城一带推行保甲连坐、征粮抓丁，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cb070f435f74e90a1a4c084326ae038','36a0b354-40e2-4a75-9344-733d4ec6fffa',1938,'菏泽沦陷后出面组织维持会','菏泽沦陷后出面组织维持会，后任伪菏泽县县长，协助日军建立伪政权、维持治安，推行奴化教育，为日军征发粮食、劳工，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-338a1f1741e24a47b3b82ba88d12dff2','2e74f548-5fde-4521-97ab-4d2fc971c0f4',1938,'曹县人','曹县人，抗战期间投敌，任伪曹县县长并掌握伪军，配合日军扫荡鲁西南抗日根据地，在曹县、菏泽交界地区强征粮款、抓捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66d803683f0a4033a20144e6b39581c3','1eb13624-e434-499e-aabd-b2bfed3b887b',1939,'定陶人','定陶人，投靠日军后任伪定陶县县长兼伪保安团团长，在定陶、菏泽一带修筑据点，配合日军对抗日根据地进行蚕食扫荡，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff9e38062de14b16a4da668cc95a3ece','4b0c9d56-d73e-47bc-b001-0020991714b5',1938,'单县人','单县人，抗战期间投降日军，任伪单县县长，组织伪军控制单县及周边地区，为日军搜集情报、征粮派款，参与对湖西抗日根据地的扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df031c47786c4fbe8d29e743370a753c','bc61fdbb-04b6-4fe0-8876-3288722b25d8',1938,'巨野人','巨野人，日军侵占巨野后出任伪县长，建立伪政权和伪警察队伍，推行保甲制度，协助日军掠夺物资、镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe23c7675df348c9802e29afbd870863','fc2aa877-90de-4ab9-876c-79c3c19363ed',1938,'鄄城人','鄄城人，投敌后历任伪鄄城县县长、伪鲁西道尹公署官员，在鄄城、菏泽一带为日军征粮抓丁，组织伪军配合日军扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24b5db390122425c82037d62e41cd644','cabb47aa-8c1a-4bfd-a485-ccad8bcc72ea',1938,'东明人','东明人，抗战初期组织维持会迎接日军，后任伪东明县县长，协助日军控制黄河渡口，封锁抗日根据地，迫害抗日人员家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23d1e103a27f454cbca72f8337f36492','534fa564-102d-4507-9cdc-c442a268cbf7',1939,'成武人','成武人，投靠日军后任伪成武县县长，建立伪政权和伪军，在成武、菏泽交界地区配合日军扫荡，强征粮食和劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2755160bb44b4b6680ff89563e990014','1977488e-dceb-47ca-83e0-679e3fe2c93a',1938,'濮县（今属菏泽鄄城一带）人','濮县（今属菏泽鄄城一带）人，投敌后任伪濮县县长，后升任伪鲁西道尹公署道尹，管辖鲁西多县伪政权，配合日军对冀鲁豫抗日根据地进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df022079986a443db6d6747ba77dcf88','5eb665c6-0d14-4d04-997c-019203897874',1938,'山东人','山东人，抗战期间投靠日军，任伪山东省政府委员、伪鲁西道尹等职，在鲁西地区推行伪化统治，协助日军掠夺资源、镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-99f9cbcb391f4449a05c9f412581eadf','5eb665c6-0d14-4d04-997c-019203897874',1938,'在伪山东省政府任职期间','在伪山东省政府任职期间，参与鲁西地区伪政权建设，协助日军推行治安强化运动，其辖区包括菏泽、鄄城一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c999c05b7f2647669c61eec2cebde955','a44d31b7-b2e7-40f3-8138-d071713c1a28',1938,'抗战期间任伪鲁西道尹','抗战期间任伪鲁西道尹，管辖菏泽、郓城、鄄城等县伪政权，配合日军对鲁西抗日根据地进行扫荡，推行保甲连坐，镇压抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b32a5547c594379b3a16baee7b0a143','1de461b7-ffdf-4d86-981a-aec04be1e8e5',1938,'菏泽人','菏泽人，投敌后任伪菏泽县教育科科长兼伪菏泽中学校长，推行奴化教育，篡改教材，向学生灌输亲日思想，为日军培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96a6c24a5f5a4d3f98bc337b674325af','3a495c5e-064a-4370-bd8f-fcd44fe10b63',1938,'菏泽人','菏泽人，抗战期间任伪菏泽县商会会长，为日军筹款筹粮，协助日军掠夺当地物资，压迫商户，配合伪政权维持统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1c07b83b9734f019c59a37fdf5665d8','06ad2e73-5256-46ba-843d-6016335721e2',1938,'郓城人','郓城人，日军侵占郓城后组织维持会，后任伪商会会长，为日军征粮筹款，协助伪政权镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e744a1fa280648039d4204ea95aa1267','56eb1550-be15-47a7-96ad-e920dd971678',1938,'曹县人','曹县人，抗战初期组织维持会迎接日军，协助日军建立伪政权，征粮抓丁，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffdc76b8db754e5a8408558d1266aa9c','33bc2c20-3423-44bb-a6fc-aeb0f1fa80c9',1938,'单县人','单县人，日军侵占单县后组织维持会，为日军筹粮筹款，协助伪政权维持治安，迫害抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5b787ca492241608957f19e337de569','8ee859b1-57e6-409c-b47c-e29478714943',1938,'日军侵占菏泽后出面组织维持会','日军侵占菏泽后出面组织维持会，出任伪县知事，为日军征粮派款、维持伪秩序，协助日伪统治菏泽地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
