INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4aa29cde9b02478eaf08bc04401571f8','96f22563-9a71-444d-bfa7-e5b2c261a08d',1938,'在定陶组织维持会','在定陶组织维持会，迎接日军进城，协助建立伪政权，为日军筹粮筹款。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aac08c66c4bd42aeaa6efbe9e66f2aab','77df0563-940e-4b8d-8b58-576ea8b2d304',1939,'单县沦陷后出任伪职','单县沦陷后出任伪职，配合日军修筑据点、封锁沟，参与对湖西抗日根据地的扫荡。','危害等级C（丙级，基层头目）','hanjian');
