INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab67520890124036ae47d15df1cb9bc2','017a428a-89b1-43ea-bbfb-ca48d8886cfb',1938,'巨野沦陷后投敌任伪知事','巨野沦陷后投敌任伪知事，推行伪化教育，为日军征发民夫、物资，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b157dd3b52a4c8799c103680446cfec','f74d8a96-c554-4f7d-a292-060c65f092cf',1939,'在郓城建立伪政权','在郓城建立伪政权，配合日军对郓城、鄄城一带抗日根据地进行扫荡，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e26209fde5d429786d47012f98eedf1','d0b52fa2-1bde-4464-9b3d-e3654d3f1a44',1939,'在鲁西道（辖菏泽、曹县、单县等地）推行伪政','在鲁西道（辖菏泽、曹县、单县等地）推行伪政，为日军征集粮食、劳工，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5973f10921094a3bac3284e1da0e17ca','06ab3f67-8f77-47c6-9344-ef1c1e9c9a30',1938,'原为国民党军将领','原为国民党军将领，投敌后率伪治安军在鲁西、豫北一带配合日军作战，活动范围覆盖菏泽周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03427afd00fc409989530a167a12e6e1','b4c1ddeb-c60d-4986-8356-17f3784e678d',1943,'原为国民党军将领','原为国民党军将领，被俘后投敌，率伪军在华北包括鲁西地区配合日军作战。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca3a64fb4d884b9484b921391915a955','b4c1ddeb-c60d-4986-8356-17f3784e678d',1943,'原国民党河北省主席','原国民党河北省主席，1943年被俘投敌，任伪军总司令，其伪军活动于豫北、晋南，与临汾地区日军有配合。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
