INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b40da83863494af08bbddacaa7f4f8cf','7be1c004-e0b8-4ef0-b45d-7c39b7acc523',1938,'协助日军建立伪政权','协助日军建立伪政权，为日军筹集粮款，强迫百姓领取“良民证”，举报抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c702cd5adb84b1a868619f74b3a0cf6','3a1629e1-556c-4d87-a6bd-b649391b9b6e',1939,'主持伪新民会临汾分会','主持伪新民会临汾分会，推行奴化教育，宣传“中日亲善”，诱骗青年参加伪军，刺探抗日情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-383b44916caa4e1f85d40c8b01f85600','dd3e64fc-3709-4552-91f2-941a0b1dd8b4',1940,'指挥伪警察协助日军抓捕抗日分子','指挥伪警察协助日军抓捕抗日分子，严刑拷打被捕人员，参与“清乡”行动，烧毁村庄。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af29e09693d74739bf484b118dabbfdc','77934caf-5d97-4b70-9433-b8a775470990',1943,'投日后任伪山西保安副司令','投日后任伪山西保安副司令，在临汾地区扩充伪军，配合日军“扫荡”，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49404fb35f7949bba4d41dbb12d83622','4ffec88c-0dbf-4cdc-835c-5324ca869676',1938,'任日伪乡宁县县长期间','任日伪乡宁县县长期间，协助日军推行“治安强化”运动，强征民夫修筑碉堡公路，搜刮粮食资敌，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f29ea5d47bf04177803f0ca7509a3f36','b3c6a3fd-4c3e-4570-bbb9-5e54672e7132',1940,'率伪保安队多次配合日军扫荡乡宁抗日根据地','率伪保安队多次配合日军扫荡乡宁抗日根据地，抓捕抗日军民，烧毁村庄，抢劫财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6323aab4a1dc4a5fb3d1d14944d62386','4faa8241-4bb7-433d-8433-a101dc48506d',1938,'日军占领乡宁期间','日军占领乡宁期间，组织维持会为日军筹粮派款，提供抗日武装活动情报，导致多名地下党员被捕牺牲。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a05f2dea7e94446f85432e3ed2791e12','9c412d54-486c-4a01-8d30-83058aed2954',1939,'原阎锡山部军官','原阎锡山部军官，投日后任临汾伪道尹公署顾问，参与策划对临汾、乡宁地区的“清剿”行动，诱降抗日干部。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80f300e4b7ce4d50bf29e7f531ba533a','e0e06a53-f274-4125-92d8-78901f7d0e62',1940,'在临汾城区及周边县（包括乡宁）建立伪警察网络','在临汾城区及周边县（包括乡宁）建立伪警察网络，搜捕抗日分子，协助日军进行经济封锁，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
