INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4cbe2785ff6478cbf8db6b84833eb6c','22d404fc-cd36-4ac9-ac48-e5debd4276ec',1938,'在伪山西省公署任职期间','在伪山西省公署任职期间，统管全省伪警察力量，在临汾等地建立伪警察网络，镇压抗日活动，抓捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d37492caaace4efca2ae1dce26deff7f','22d404fc-cd36-4ac9-ac48-e5debd4276ec',1938,'在伪山西省政权中负责警务','在伪山西省政权中负责警务，参与组建和指挥伪警察力量，配合日军在山西包括临汾地区进行治安强化运动、搜捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16c99584c0f14dddbaada4cdbb76793b','22d404fc-cd36-4ac9-ac48-e5debd4276ec',1938,'负责组织伪警察力量','负责组织伪警察力量，在临汾、翼城等县建立伪警察所，配合日军清乡、搜捕抗日人员，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6632d5d7f4354940a1fdccc97756dc58','22d404fc-cd36-4ac9-ac48-e5debd4276ec',1938,'山西人','山西人，抗战期间在伪山西省公署任职，掌管伪警察系统，参与搜捕抗日人员、维持日伪统治秩序，其警务体系延伸至晋南运城、稷山等地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-240226bc6524478381aa8b6a9f3a5265','5b5d8dd3-147c-4c37-87f5-c778afe255bd',1938,'山西人','山西人，原为阎锡山部属，后投敌任伪山西保安队副司令等职，率伪军在临汾、晋南一带配合日军扫荡抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0986bbc737af47a79eff6efe61f3656f','06c95614-a522-423b-be26-04b461fde2f1',1933,'热河人','热河人，长期在日军扶植下任伪军头目，其伪蒙古军活动范围曾涉及山西北部及临汾周边地区，配合日军进攻抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08d76f171d2141ac9a92b45db5928ccb','142d7d73-88ca-459d-a2a7-aa1b2e2bfc65',1943,'原国民党将领','原国民党将领，1943年在河南被俘后投敌，任伪新编第五军军长，其部队在晋南、临汾一带配合日军行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6868c39645a8426d94fa5dec70d2501d','142d7d73-88ca-459d-a2a7-aa1b2e2bfc65',1943,'1943年投敌后','1943年投敌后，其部队在河南平顶山、许昌一带配合日军行动，进攻抗日根据地，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1eaa79299d942bbb12db5bbebf94724','142d7d73-88ca-459d-a2a7-aa1b2e2bfc65',1943,'1943年在河南林县一带投敌','1943年在河南林县一带投敌，所部被编为伪军，后在豫西、洛阳周边配合日军作战，参与对抗日根据地的扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd41578c484d4e878dae4ff1a047e6f2','142d7d73-88ca-459d-a2a7-aa1b2e2bfc65',1943,'原国民党将领','原国民党将领，1943年在河南林县投敌，所部被编为伪军，在豫北包括焦作周边配合日军行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca01166cdfd54884a2e694d6f1adc3ca','142d7d73-88ca-459d-a2a7-aa1b2e2bfc65',1943,'1943年投敌','1943年投敌，所部在豫北、焦作一带配合日军进攻抗日根据地。','危害等级B（乙级，市县厅局级）','hanjian');
