INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3aa09821164a4f0196d1d724f9dd05cf','142d7d73-88ca-459d-a2a7-aa1b2e2bfc65',1943,'1943年率部投敌','1943年率部投敌，所部在豫北焦作、新乡一带配合日军进攻抗日根据地，搜捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab8d561646b740139c88ad88e52a5fde','142d7d73-88ca-459d-a2a7-aa1b2e2bfc65',1943,'1943年在豫北投敌','1943年在豫北投敌，所部被编为伪军，活动于林县、鹤壁、淇县一带，配合日军进攻抗日根据地。','危害等级B（乙级，市县厅局级）','hanjian');
