INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cbfec863c18b4fc58bdf4f0646d016eb','cbd8843c-123b-46cd-bc06-b81eb6301882',1937,'临汾本地人','临汾本地人，日军占领临汾后出面组织维持会，为日军筹集粮草、招募劳工，协助建立伪政权基层组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
