INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ab03cfc439c42009afc5537519fbaa1','40ab6f66-5b7f-4f1d-9bed-d5129a8e013f',1941,'古县人','古县人，任伪保安队队长，率队配合日军在古县及周边地区清乡、扫荡，抓捕抗日干部和群众。','危害等级C（丙级，基层头目）','hanjian');
