INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0881bfeade242eebd00e2efc8312462','1975233a-4d85-439f-abb5-471aadc3618c',1938,'山西地方伪军头目之一','山西地方伪军头目之一，曾率部配合日军在晋南地区活动，参与对临汾、汾西一带抗日根据地的扫荡与清乡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-502b22695d81487bb8d178e0d624e6de','9fe28cfc-a5a6-4c64-a84a-a29a58439366',1937,'临汾沦陷后出面组织伪维持会','临汾沦陷后出面组织伪维持会，为日军筹集物资、维持地方秩序，协助日军建立伪政权，是临汾地区较早附逆的地方人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86e8eb29dbc14edd934e70149db8ea6b','477e3c88-d365-49fd-9fa2-41015e6ffe0f',1938,'在日军占领临汾期间出任伪县知事','在日军占领临汾期间出任伪县知事，负责临汾县伪政权的日常运作，推行日军政令，征粮征夫，配合日伪军对周边抗日根据地的封锁与扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-978fcd7b0f2645f4a4c7038b2dde6929','477e3c88-d365-49fd-9fa2-41015e6ffe0f',1938,'在临汾县城推行保甲制度','在临汾县城推行保甲制度，强征民夫修筑碉堡公路，为日军提供粮食和劳役，镇压当地抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3972648803f548e0ae2be93ea0076ee9','477e3c88-d365-49fd-9fa2-41015e6ffe0f',1938,'任伪临汾县知事期间','任伪临汾县知事期间，强征民夫，为日军修筑碉堡公路，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b5876427225473492b80578e8ca1320','1f838f7c-61c5-422d-8309-db677de53735',1938,'汾西县地方人物','汾西县地方人物，日军侵占汾西后出面组织维持会并出任伪职，协助日军在汾西地区征粮、派款、维持治安，配合日伪军对汾西抗日根据地的清剿。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed5fcdb9aea640f3938beaeca04d3142','3c44e41c-aeb6-4100-a2c0-07b6a44f0706',1939,'汾西本地人','汾西本地人，组织伪警备队配合日军驻汾西部队行动，参与搜捕抗日干部和群众，为日军提供情报，是汾西地区伪军警头目之一。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2aa4babc6c924149b8f522ce97c7ca66','04ee0073-2577-447d-bfba-3cdfe17df6cd',1941,'山西人','山西人，组织伪“急进建设团”配合日军在山西各地进行经济掠夺和治安强化，活动范围包括晋南临汾一带，为日军搜集物资、情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd281ebf92204c9baa27527ffc560ccd','e8f38fb4-00be-4866-b556-35caf98e1dc9',1938,'在伪山西省政权中负责宣传和奴化教育','在伪山西省政权中负责宣传和奴化教育，推行亲日思想，为日军殖民统治制造舆论，影响范围覆盖山西全省包括临汾地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5f55dd88455423596a495eead49bd5c','7fd80a10-1790-4fde-bd9f-e1e8aee4cc8a',1938,'在伪山西省政权中负责财政','在伪山西省政权中负责财政，为日军筹措军费、征收赋税，对山西包括临汾地区民众进行经济压榨。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-899d7cdec85e44fa84212805fb88caca','7fd80a10-1790-4fde-bd9f-e1e8aee4cc8a',1938,'抗战期间任伪山西省公署财政厅厅长','抗战期间任伪山西省公署财政厅厅长，为日伪政权筹措经费，推行伪币，掠夺山西物资，其财政政策直接波及运城、稷山地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-950bec743a8d43909c4fae7d67461a91','ae2c1968-1390-49b4-8acb-ab8b8692b20b',1938,'在伪山西省政权中负责教育','在伪山西省政权中负责教育，推行奴化教育，篡改教材，向山西包括临汾地区青少年灌输亲日思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b8ae66832b24855be093f93c3a0de17','bbe3362c-b311-4b88-9afa-34a8286ac8ec',1939,'在临汾担任伪警察头目','在临汾担任伪警察头目，指挥伪警察配合日军进行户口清查、搜捕抗日人员、镇压民众反抗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d6a1c617a56431ea20bf43ccd98f262','09b282bf-7c2e-4529-b2c2-205d93699da5',1938,'临汾周边洪洞县伪政权头目','临汾周边洪洞县伪政权头目，协助日军在洪洞、临汾一带征粮征丁，配合日伪军对当地抗日武装进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10ba9f0723dd4e71ba6c60b6bbc3db56','c0284033-60ff-4153-a617-6f28a33918dd',1938,'临汾周边赵城县地方人物','临汾周边赵城县地方人物，组织维持会为日军服务，协助日军在赵城、汾西交界地区进行统治和物资掠夺。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00bf722466194760a0178062eaa7e4a2','9c153082-e8f8-4d0b-a50c-6c58d59bdabe',1938,'临汾周边襄陵县伪政权头目','临汾周边襄陵县伪政权头目，配合日军在襄陵、临汾一带推行保甲制度，征发民夫，为日军修筑据点、公路。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb4e5b0f9ec640a69eb8f81b0bc0a36e','951527be-f534-4bf2-96fd-a8775e7768e4',1938,'在伪山西省政权中担任参事','在伪山西省政权中担任参事，参与制定和推行日军在山西的殖民政策，为日伪统治出谋划策，影响涉及临汾等地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d99851042f094c5fa182f337d6c0e692','fc593aaa-8a04-4157-9223-cbc3cad61075',1939,'日占临汾期间','日占临汾期间，先后任伪临汾县知事及伪洪洞县知事，组织维持会，为日军提供粮秣、民夫，并配合日军“治安强化运动”，抓捕抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-961187b1b0c24e819f0d1260d7097c8c','05d5a532-f080-40ae-af9a-4cd3e436fa4e',1940,'原为地方士绅','原为地方士绅，投日后任伪晋南道尹（驻临汾），管辖临汾、洪洞、赵城等县，推行保甲制度，建立伪警察，协助日军扫荡，强征捐税。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4742456899e4142843ef3ab78cc8ce7','4a6bbca3-b42c-478d-b1a6-27d67fd23e51',1941,'组织伪保安队','组织伪保安队，配合日军在洪洞、赵城一带“清剿”八路军游击队，多次带队突袭抗日村庄，杀害抗日干部及群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28667c43715a4f6e8c61d802b609df37','c3464008-4c7f-47f0-a26e-a20dd0e233ee',1938,'日军占领临汾后首任维持会长','日军占领临汾后首任维持会长，负责为日军筹集粮食、征集苦力，并建立情报网，向日军报告抗日武装动向。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fb4df250276409db8af20ad316ee1d2','43193fce-f5a7-4fe8-a5b8-b955fb884706',1940,'在洪洞县推行奴化教育','在洪洞县推行奴化教育，组织“新民会”宣传“中日亲善”，强迫民众参加集会，并协助日军收集抗日情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf91cec3f4dd495e8f31984a65502427','5dff9981-3fcf-4043-9ea7-e28644cb287c',1942,'率伪警备队多次参与日军对临汾西山根据地的“扫荡”','率伪警备队多次参与日军对临汾西山根据地的“扫荡”，烧毁民房，抢掠财物，并杀害被俘的抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f79b6c45ee649a8a022b578abbfe45b','a4df4ac8-6afe-42a1-a85d-fb0e438d484a',1939,'作为伪省府参议','作为伪省府参议，多次到临汾、洪洞视察，督促伪县署强化“治安”，并参与策划对抗日根据地的经济封锁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-081e45c94a2d460587994cdae0c901ac','b95d573b-3e6e-407a-bc91-f6239eac3fd3',1938,'任浮山县伪县长期间','任浮山县伪县长期间，积极推行日伪政权各项政策，组织维持会，协助日军征粮派款，镇压抗日民众，破坏地下抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a43c3b062f6a4b17ac0c71d1df636b76','6eed92f4-25e6-47c2-bf0e-b962ba78b932',1939,'率伪保安队多次配合日军扫荡浮山抗日根据地','率伪保安队多次配合日军扫荡浮山抗日根据地，抓捕抗日干部和群众，烧毁村庄，抢劫财物，民愤极大。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8f481be9d7d4950ba033175e9b263dc','a4c7f70e-cf10-486d-8b2a-0216efbc1d64',1940,'负责浮山县城日伪治安','负责浮山县城日伪治安，设立情报网，侦捕抗日地下工作者，严刑逼供，致使多名抗日志士牺牲。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d54e3864f8145659f344b982eda2915','1020fd64-dc70-4832-ad1d-06fd58e68afd',1938,'日军占领浮山后率先投敌','日军占领浮山后率先投敌，组织维持会，为日军筹集粮饷，强征民夫修筑碉堡公路，并劝降抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfa9e4b3ef704fa591b2129ad07a55cc','8807b138-5c21-46bf-bef8-63435f0cc05f',1941,'在浮山二区推行保甲制度','在浮山二区推行保甲制度，清查抗日家属，向日军报告八路军活动情报，导致多次袭击事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e6b086514f3457b9aede9f0a483b189','224e31a3-795b-4681-8a9d-c1efa9f71825',1942,'协助日军在浮山三区建立伪政权','协助日军在浮山三区建立伪政权，强征青年充当伪军，并参与杀害抗日村长数人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a45007656da4c3cb0f5a8d8db99be48','13a4bdab-c598-4441-bcdb-76baf848fa3a',1939,'宣传“中日亲善”“大东亚共荣”','宣传“中日亲善”“大东亚共荣”，组织奴化教育，诱骗青年参加伪军，破坏抗日群众团体。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1bc8f6736c01494ca49d0a3403fd578f','538ede47-ed70-4cdd-a2a5-3d60221799a5',1940,'率伪警备队驻守浮山重要据点','率伪警备队驻守浮山重要据点，多次伏击抗日游击队，并参与“清乡”行动，杀害抗日群众十余人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbab69fbb845401083fde7aa02daf15c','15a3c60c-5911-401e-8cd7-e6b460bb0798',1941,'为日军征收各种苛捐杂税','为日军征收各种苛捐杂税，强抢民间粮食和物资，导致浮山百姓生活极度困难。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68638f049bd448be988ecac37e331e6c','cdfd2ddb-265a-464b-8907-97aa4badaf83',1942,'专门搜集八路军和抗日政府情报','专门搜集八路军和抗日政府情报，多次带领日军突袭抗日村庄，造成重大伤亡。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f3ad82c99824df09dd9005be4b9b12d','826a9f11-63e9-4150-aa4a-0cea6812a91d',1940,'在临汾县推行伪政权','在临汾县推行伪政权，强征民夫修筑公路和碉堡，向日军提供粮食和情报，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f002beb8ea84519a7cf8a6f5439fc97','dd58926e-2dd8-413d-8b89-8519c56b52ce',1941,'在翼城县组织伪县公署','在翼城县组织伪县公署，协助日军建立“维持会”，强派捐税，抓捕抗日家属，破坏地下抗日组织。','危害等级C（丙级，基层头目）','hanjian');
