INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6337cf66be8485eaf5db7feb8f05c89','81efcccd-2439-42d4-8fb8-b414781709e7',1942,'组织伪自卫团','组织伪自卫团，配合日军巡逻和清乡，杀害抗日军属，抢劫民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff596aaaec0c4306a16c7d57c59e374b','4d9637b5-f9ad-4963-b4c2-a8b9ff8dc8bc',1941,'为日伪政权征收各种苛捐杂税','为日伪政权征收各种苛捐杂税，盘剥百姓，逼交“治安费”，导致许多农户破产。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0bd6eb54c6fe4ec08470721c99be6452','a31bf27d-2267-4bc2-891b-5d8e1935287a',1942,'推行奴化教育','推行奴化教育，强迫学校使用日伪教材，宣传“中日亲善”，破坏抗日宣传教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42ce0a1c958e43528a8ee5da8c2de557','4ccddd95-fe7b-4a3c-810f-e67d9d330efc',1939,'曾任阎锡山部军长','曾任阎锡山部军长，后投靠日军，任伪山西省政府顾问，协助日军维持占领区秩序，参与对晋西抗日根据地的扫荡策划。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20c859ff451d4407a6f4d1a8d6025763','2c2f48ef-512f-4374-b47b-1408cd03cc4d',1940,'在交口、隰县一带活动','在交口、隰县一带活动，与日军达成局部停战协议，默许日军通过其防区进攻八路军，并向日军提供情报。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a569576d4cb4601aef16396d7776986','44b011f0-499c-4118-bff2-1af4128cbbb6',1941,'率伪军驻扎吕梁山区','率伪军驻扎吕梁山区，多次配合日军对交口、石楼、中阳等地进行“扫荡”，杀害抗日干部和群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a1839f983c145f087b87fca21f701fc','720de559-6e19-4fab-82c8-cf7f7d679493',1942,'在交口县城及周边村庄设立维持会','在交口县城及周边村庄设立维持会，为日军征收粮款，强抓民夫修筑碉堡，并告密抓捕抗日地下党员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
