INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f3f528931834b76a99ff15df883e28e','f69ed383-7703-47d5-896b-07a421e321ca',1940,'组织伪警备队','组织伪警备队，为日军提供情报，参与多次对孝义抗日根据地的“扫荡”，杀害抗日干部和群众数十人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98715ff8f6b446f898572c9e51893452','0c7f71aa-0b68-44ac-8005-eccfe65f242a',1941,'在吕梁山区多个村镇建立维持会','在吕梁山区多个村镇建立维持会，为日军摊派粮款，强迫百姓领取“良民证”，并告密导致多名地下党员被捕牺牲。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3634849e4c06456fa97eb6ba9bfe7ce0','1fc544e9-553a-4d60-be4d-89128ee87bdd',1942,'率保安团配合日军对孝义西部山区进行“铁壁合围”','率保安团配合日军对孝义西部山区进行“铁壁合围”，烧毁村庄十余个，抢掠牲畜粮食，并参与活埋抗日军属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bcfdfcb4a41d4d829c737613fb69e067','ff3973c6-a03c-4a69-b231-44814b028ba1',1940,'在孝义设立伪行政机构','在孝义设立伪行政机构，推行保甲制度，强征青年充当伪军，并协助日军建立情报网，破坏抗日政权。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
