INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d51782f525f4f1bbaf7d04055743a21','e897c689-4d8f-49a3-a643-97dd7924b424',1939,'充当日军爪牙','充当日军爪牙，负责岚县县城治安，多次带队搜捕地下党员，刑讯逼供抗日志士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
