INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80a28ce9b66b4c97870256095b79604a','972f0209-895a-4aa3-b27e-7a0a4cc10962',1941,'原晋绥军将领','原晋绥军将领，后投靠日军，任伪山西省政府顾问，参与策划对吕梁地区的‘清剿’行动，为日军提供情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
