INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3fc369e60fc4c46a9e5b3bf28b7f5fb','ccf0ade7-51c9-4fad-90f3-d04516e0c76c',1940,'原晋绥军将领','原晋绥军将领，1940年率部投敌，被日军委任为伪军头目，在吕梁、离石一带配合日军进攻八路军，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
