INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21d9c29cfbad4877a3c186a3958151ef','e05ce945-1ae3-4450-bda3-5d536cbbcbb2',1941,'负责在离石推行奴化教育','负责在离石推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，并收集抗日情报供日军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fb6bcd6260643d798f7436e19df91c0','1c157118-39be-4857-b400-7f2bcf33f1dd',1942,'原土匪头目','原土匪头目，投日后被委任为吕梁警备司令，率伪军驻防离石、中阳一带，多次参与“扫荡”八路军晋绥根据地。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
