INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e256d095abee4531af0146cd20b0d758','15f76c15-547b-4885-bc08-59053c42cf3f',1940,'在吕梁地区推行日军资源掠夺政策','在吕梁地区推行日军资源掠夺政策，强占煤矿铁矿，强迫劳工开采，并克扣劳工口粮。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-805edd4fada042b699f07ec6bef5a02c','4d386805-1395-4e23-86d2-1d8599091aad',1937,'投靠日军','投靠日军，任伪大同省省长，协助日军推行殖民统治，强征劳工，掠夺大同煤炭资源，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-019730023af641b4889461ad490f6493','e564d8b0-ebda-40da-b0d2-115530545347',1936,'率伪蒙古军配合日军侵占大同','率伪蒙古军配合日军侵占大同，后驻防该地区，参与“扫荡”八路军根据地，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d954147506774edbadfa5310e89af893','f8c684b6-a5fd-4c10-8b6a-a8af67ee4b08',1937,'作为伪蒙疆政权首脑','作为伪蒙疆政权首脑，将大同划入其统治范围，支持日军经济掠夺和奴化教育，是蒙奸首要人物。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
