INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23245e4085b8445aaf89b3cabf20ddda','b74edb3e-3765-414d-8081-b218cdd94855',1938,'任伪大同县知事期间','任伪大同县知事期间，推行保甲制度，强征壮丁，配合日军“治安强化运动”，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
