INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1629ce70260543d7842b25d8d7608323','2c32da99-b8e7-454f-b11f-bc5045140ea3',1937,'充当日军经济汉奸','充当日军经济汉奸，组织商会为日军筹集军费，垄断煤炭贸易，压低矿工工资，从中牟利。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc9c9f76bd0640e4b20fde58a705ec6c','8ab2e3ef-2469-4131-8ecb-d18350ce1383',1937,'负责对大同民众进行奴化宣传','负责对大同民众进行奴化宣传，散布“中日亲善”言论，诱骗青年参加伪军，破坏抗日士气。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
