INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d41c7edcf89f4aefa505c73e87f20371','fc71e81c-de51-43e6-93d6-f8d97e4dd6bf',1937,'投靠日军','投靠日军，任伪蒙古军总司令，后任伪大同省省长，协助日军统治大同及周边地区，镇压抗日力量，推行奴化政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e35026a09ce466cb7c59ddc65e2ce43','fc71e81c-de51-43e6-93d6-f8d97e4dd6bf',1937,'投靠日军','投靠日军，任伪蒙古军总司令，后任伪大同省省长，协助日军在平城地区推行殖民统治，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-adc27e9a30644b5abb85044549debee2','fc71e81c-de51-43e6-93d6-f8d97e4dd6bf',1937,'原为土匪出身','原为土匪出身，投靠日军后任伪蒙古军总司令，1939年任伪晋北自治政府（后改大同省）最高顾问，后任伪大同省省长，协助日军推行“治安强化运动”，镇压抗日力量，强征劳工，掠夺大同煤炭资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
