INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b41ec365f4c482c8651f6d3a8e46270','cd7503f2-fa9d-4255-964e-d8d00e706b85',1941,'率警备队多次袭击八路军游击队','率警备队多次袭击八路军游击队，杀害抗日干部，并参与日军“三光”政策，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f02937390c2c4e58a65cf7a168966396','4ae17c88-f09c-4ab9-a2fa-74a51c87d9e5',1937,'为日伪政权审判抗日人士','为日伪政权审判抗日人士，滥施酷刑，判处多名爱国群众死刑或劳役，是日伪司法帮凶。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b96300eb3f48466ebeee67ebfa81777e','4a798848-287d-4fd3-ba34-f5c411181261',1937,'原为土匪出身','原为土匪出身，后投靠日军，任伪蒙古军总司令，参与指挥伪军配合日军扫荡左云、大同地区，残害抗日军民，推行“治安强化”运动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ffa0797b2e74c46a60b59039adc0f99','2b81ce14-f194-4e50-9eee-d53b5aaed644',1937,'组织伪军武装','组织伪军武装，在左云、右玉、大同边界地区多次袭击八路军游击队，抓捕抗日干部，为日军提供情报，协助日军建立伪政权。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b2580cfe1df04bda9234ada197861fe2','546e79e3-d438-4bec-81a9-268b13b0c823',1938,'原为阎锡山部将领','原为阎锡山部将领，投日后任伪晋北政厅厅长，管辖大同、左云等县，推行日伪“施政跃进”政策，强征民夫、粮食，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-488f343ddc3d48c0beac0788f9fc792a','eb6fe0a5-24e4-4cd1-8ad1-6ae5c2526cd2',1939,'在左云、大同地区组织伪警察队','在左云、大同地区组织伪警察队，配合日军“清乡”，杀害抗日家属，强征苛捐杂税，破坏地下党组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d011a283d1594bc0adcbb076a11ae171','d7c310b5-b2fd-4e5c-a319-0497ca2f2d27',1940,'率伪保安队多次突袭左云南山抗日根据地','率伪保安队多次突袭左云南山抗日根据地，烧毁村庄，抓捕并杀害八路军伤病员及地方干部，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-232b6934a61644e1ad2f02f28e4810e2','99a1b0f4-d684-4d1d-8a9c-a14ff46f69a4',1937,'日军占领左云后率先组织维持会','日军占领左云后率先组织维持会，为日军筹粮派款，提供抗日人员名单，导致多名地下党员被捕牺牲。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3b1030df5f840f4b612d7d0a6cd56e8','532238ac-c214-41b3-9cc7-0e4c5b65b975',1941,'负责大同、左云地区特务工作','负责大同、左云地区特务工作，建立情报网，破坏抗日组织，亲自审讯并酷刑折磨被捕的抗日志士。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-472b11609ccf45cb8378a435a372ceab','e4a291b7-11ed-446a-b557-c9d757953849',1942,'协助日军在左云县各村庄设立“爱路村”','协助日军在左云县各村庄设立“爱路村”，强迫村民报告八路军动向，多次带队伏击过路的小股抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5c0709474e24f79be521de6d078def5','f73f9a70-c6d9-4c73-9aea-3fe9c0f49eae',1935,'虽主要活动于东北','虽主要活动于东北，但曾以伪满高官身份视察大同、平城地区，协助日军协调华北伪政权，推行奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21ccb5c1432d4b6bb6b2b14c2c87048d','131f23ff-849a-4e8c-bee9-f01df0acf70b',1937,'原晋军将领','原晋军将领，投日后任伪晋北自治政府顾问，参与组建伪政权，协助日军在平城地区建立保甲制度，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72ef2b70426e49a48479f23462bf4471','131f23ff-849a-4e8c-bee9-f01df0acf70b',1937,'原为阎锡山部军官','原为阎锡山部军官，后投日，在怀仁、朔县等地协助日军推行保甲制度，强征民夫，掠夺粮食，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd02fd057f8c422a99082ee6d6b8f869','282678bd-e3d6-4afe-9425-919d4d73986d',1939,'任伪大同省公署参事','任伪大同省公署参事，负责文化教育领域，推行奴化教育，篡改历史教材，为日军侵略张目。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5c392ad4ca44c83935a9686a383662a','06a3b03b-d85f-4db3-b418-56e87c28bb4f',1940,'任伪大同保安队队长','任伪大同保安队队长，率伪军配合日军扫荡平城周边村庄，杀害抗日干部和群众，抢劫财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-923ae8b773aa4b4eb760ab45dc0642cc','1f9380c7-2bab-46f9-85bb-e5fcb42f19c8',1937,'日军占领平城后首任维持会会长','日军占领平城后首任维持会会长，为日军筹集粮饷，强迫商户“献金”，协助日军建立治安秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f733572b0fb410aaedb4fe7b5a998d4','a9d3d923-4e7c-4b11-ad18-99457e000d7f',1938,'任伪大同警察局局长','任伪大同警察局局长，指挥伪警抓捕抗日地下党员，严刑逼供，破坏中共平城地下交通站。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c331358bfd04c2fa64fa6e86598cc30','55a71f79-c1c4-4470-86fd-494feedf5316',1939,'任伪平城商会会长','任伪平城商会会长，为日军统制物资，强制商户低价出售粮食、布匹，从中牟利，资助伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb9e3fc8c9a34d3c8df5f02b42ff12bd','209462df-549a-470e-8280-b179d2dc5d96',1937,'任伪大同宣抚班班长','任伪大同宣抚班班长，随日军进行“宣抚”活动，诱骗民众归顺，收集抗日情报，破坏群众抗日团体。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac8b301c6dd44a0ba8705492a718eb3f','46619655-907b-45f2-b110-a9a8c72b9999',1937,'投靠日军后出任伪广灵县县长','投靠日军后出任伪广灵县县长，协助日军推行“治安强化运动”，强征民夫修筑炮楼和公路，并组织伪警察所镇压抗日群众，曾配合日军扫荡南山抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9d679d1c4954fa389f6b6e98fd445b8','a3122c3d-edd0-4e01-9c00-5e058ef6480a',1938,'原为地方土匪','原为地方土匪，后投降日军任伪保安队队长，率部多次袭击八路军游击队，杀害抗日干部和军属，并参与日军在广灵县西加斗、南村等地的“清乡”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a418c0d533f5429d98859f4f0e560e11','83ded469-33ec-467f-a483-78ce6c959fb6',1939,'任伪警察所长期间','任伪警察所长期间，积极为日军搜集情报，抓捕抗日地下党员，并参与建立“保甲制度”，强迫村民领取“良民证”，多次带队搜查抗日物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a46834581c6b4bc7bf5f1b827676ef3e','540c9675-9481-4367-8e63-4ff23dbf85f0',1940,'负责在广灵推行奴化教育','负责在广灵推行奴化教育，组织“新民会”宣传“中日亲善”，强迫学校使用伪满教材，并动员青年参加伪军，协助日军进行经济掠夺。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36fb41de48e54b959c3e04496bc12e9d','cee4f544-896e-419a-90e6-b22d6ddda3e5',1938,'为日军征收各种苛捐杂税','为日军征收各种苛捐杂税，包括“亩捐”“门牌捐”等，并负责为日军筹办粮秣，曾强行征收民间粮食和牲畜，导致当地百姓生活极度困苦。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b8ead34d7014254955350c66ad36c98','895d3c72-cd23-44aa-bc5c-9f5f899f73b6',1941,'率警备队配合日军在广灵县东部山区“扫荡”','率警备队配合日军在广灵县东部山区“扫荡”，烧毁村庄多处，并参与杀害八路军伤病员和抗日群众，1943年在暖泉镇附近伏击抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81674c856fd94e32b7e0c9203354587d','bdf6c786-b4c2-4cb0-9150-e24a866af7cc',1937,'为日军驻广灵部队担任翻译','为日军驻广灵部队担任翻译，多次参与审讯抗日志士，并利用翻译身份敲诈勒索百姓，曾向日军告密导致多名地下党员被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a4c94c9a11f4d00be599e947d30b083','5d7e20d5-511d-427b-a376-cb088ff1418a',1937,'日军占领广灵后率先组织维持会','日军占领广灵后率先组织维持会，为日军筹集粮款、提供向导，并协助日军建立伪政权，后调任伪大同县公署任职。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc619013ffa84a46a60d07787a548b95','65db7786-e2c8-4030-8ebe-bde919b6fd0e',1942,'专门负责刺探八路军情报','专门负责刺探八路军情报，带领特务队破坏抗日交通线，曾抓捕并杀害抗日村长数人，其特务队以手段残忍著称。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3cdee11451f4a05a998d141c36d9d06','d192e3fa-9ebc-4163-908a-b631a9a6ff9e',1938,'为日军控制广灵商业','为日军控制广灵商业，强迫商户向日军“献金”，并垄断食盐、布匹等物资供应，从中牟利，同时为日军收购军需物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ef7c28b17414ef7868ced9c8c9df15b','95bbb146-388a-4a5d-b4c2-2ae34f62d08e',1937,'原为大同商会会长','原为大同商会会长，日军侵占大同后出任伪晋北自治政府主席，积极为日军筹粮筹款，组织伪警察协助日军清乡，迫害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6329748bddf841dfb4047e736dd0df80','7a91ac17-42c4-4f1b-9344-c779bbdf7fa3',1938,'历任伪大同县知事、伪大同省民政厅长','历任伪大同县知事、伪大同省民政厅长，推行保甲制度，强征壮丁，配合日军“三光政策”，在新荣地区多次组织伪军扫荡抗日根据地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80e1ac296a0c4f68b2364fce7b6985b3','14a1d154-a0d2-484c-a1e8-9209c09369a4',1939,'负责伪大同省警察系统','负责伪大同省警察系统，协助日军建立特务情报网，在新荣区及周边村庄抓捕抗日干部和群众，刑讯逼供，杀害多名抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-715abb2e3a6d446aa5201df02d947a53','5b500fff-9b5d-42c1-81a1-43cbde3c6f10',1940,'指挥伪保安队配合日军对新荣山区抗日游击队进行多次“围剿”','指挥伪保安队配合日军对新荣山区抗日游击队进行多次“围剿”，烧毁村庄，掠夺财物，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9210ec35a9bc4b9ebe7f5915b4b058dd','0ae41564-bd3e-4996-aa1c-36e35990eadd',1941,'原晋军将领','原晋军将领，被俘后投敌，任伪大同省参议长，为日军出谋划策，劝降抗日武装，协助建立伪政权基层机构。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f16e1a7b749480baf4dbe6a4e9faa4e','280d90a9-c808-4bed-9010-59846dee8b50',1938,'在新荣地区（今新荣区）组织维持会','在新荣地区（今新荣区）组织维持会，为日军征收粮税，提供情报，强迫村民修炮楼、修公路，多次带领日军袭击八路军小分队。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8e2ce3a1926423b80c2864c4f55239d','e6c67702-e225-48c7-abbd-ab4fa5f87a5e',1939,'率伪保安团驻守新荣一带','率伪保安团驻守新荣一带，参与“清乡”行动，杀害抗日军属，抢劫民财，强抓民夫，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68f0ad1e76ad459aaf245d5e8fdc617b','0ad7c45d-13ae-423d-ac56-acabdddd527c',1940,'为日军宪兵队效命','为日军宪兵队效命，在新荣地区发展特务网络，破坏地下抗日组织，逮捕并杀害多名共产党员和进步人士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd9674bb4853433699736aa7244178ca','86a8816f-040d-42a4-94f3-430e024f4394',1938,'负责为日军搜刮民财','负责为日军搜刮民财，强征各种苛捐杂税，在新荣地区逼死多名交不起税的农民，并参与鸦片专卖毒害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a623957c77f245d79c614a9eda994821','cf9e6668-cee0-4920-b32a-424bd92df6f0',1937,'投靠日军','投靠日军，任伪浑源县县长，协助日军推行‘治安强化运动’，强征民夫，搜刮粮食，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
