INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-941be1d4841f44838f5a9ecaf14be8b5','b7063bc1-308f-4254-916f-07a7a65c50db',1941,'指挥伪警备队配合日军突袭抗日村庄','指挥伪警备队配合日军突袭抗日村庄，放火烧毁民房，并亲自拷打被俘的抗日军民，致多人死亡。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25dcb88b0e9e474b8c59f4fd328e632f','2084b470-188e-4c47-bc1e-a046613beb39',1942,'利用新民会宣传‘中日亲善’','利用新民会宣传‘中日亲善’，强迫青年参加伪军训练，并密报抗日活动，导致多名地下党员被捕。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b0b9c1d20604afa9584dbcd40ea3c94','62b664ce-dd4f-45bf-bda3-df4330873c21',1939,'为日军统制物资','为日军统制物资，强征商户捐款，垄断食盐和棉花贸易，从中牟利，并协助日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90dcc44e9c224070be63f721bf7f09db','f8af29f7-f288-46b7-92c2-5b9492f27e7a',1938,'为日军带路搜捕抗日家属','为日军带路搜捕抗日家属，参与建立‘爱护村’，强迫村民报告八路军动向，并杀害两名抗日交通员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
