INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eee32456a84c4e2d9024c50147162df5','77b00f4f-12e5-485d-9a4a-c844bea8bbff',1938,'日军初占新绛时组织维持会','日军初占新绛时组织维持会，为日军带路搜捕抗日分子，强征慰安妇，协助日军建立伪警察所。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39202a9e4e8d4e149d894f9555031ed4','e4efe03f-5afc-48be-a80f-9be6f56fc4be',1939,'在运城地区为日军征收粮税','在运城地区为日军征收粮税，组织伪保安队配合日军扫荡，破坏抗日根据地，多次出卖抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80fdcf3ebcf74afc9bc81214965a3f11','9b784772-0d2c-4be8-9faf-2cd786a8fae4',1940,'统管运城各县伪政权','统管运城各县伪政权，推行奴化教育，强征劳工送往东北和日本，协助日军实施“三光”政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c24e7d2e46934e72875be6764509fc6a','53bab977-0fbe-4f21-a002-cba269f1dde7',1940,'率伪保安队多次袭击新绛抗日游击队','率伪保安队多次袭击新绛抗日游击队，杀害抗日干部，抢劫百姓财物，为日军驻新绛部队提供情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df6d3ff32a624b0482e4d8b7dead2caf','c0909084-47fe-4751-8e30-8784b4b75274',1938,'为日军统制运城物资','为日军统制运城物资，强迫商户缴纳“慰劳金”，低价收购粮食棉花供日军军用，从中牟利。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c728360636b4018be903163182f5c42','8fbd9691-27e7-4c9c-b18f-e3d1ec1d7485',1941,'指挥伪警察搜捕地下党员和抗日群众','指挥伪警察搜捕地下党员和抗日群众，严刑逼供，破坏新绛地下交通站，协助日军进行户口清查。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a67afe46e69427980fc72ef550d6352','a1db0885-a5d7-415f-95ce-6560eaedb1ee',1940,'为日军宪兵队充当翻译','为日军宪兵队充当翻译，参与审讯和酷刑，多次带领日军突袭抗日家庭，导致数十人被捕遇害。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0fbb42af90a44628641e4ec1642a953','890d19d7-8297-457c-a1d4-3fe426034b52',1938,'投靠日军','投靠日军，任永济县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1abd6ed7a3b0453bae2d5b2c840903bf','ff894569-97cd-4db9-8444-16712690d732',1939,'原晋南土匪头目','原晋南土匪头目，后投日，任伪山西省政府顾问兼“剿共军”司令，在运城、永济一带配合日军扫荡抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42afd951ad2446e2af667430a535084d','b295bdf3-ce90-4860-be44-e06e409b8c34',1938,'虽为伪蒙疆政权将领','虽为伪蒙疆政权将领，但曾率部配合日军在运城、永济地区参与“清剿”八路军和游击队，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38b9555ecc0241bcbe6f66cd5b2f5b60','b9bc1b06-c76c-4460-b0fd-11fbde3c13c4',1940,'原国民党溃兵','原国民党溃兵，后投日，任永济县保安队队长，多次带队袭击抗日武装，抓捕并杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee9fddee7a0e4da087550d44d0cd07a5','22f81e86-c42c-4247-a4b5-feb04cb7ac25',1941,'原晋绥军军官','原晋绥军军官，投日后驻防运城地区，参与日军“铁壁合围”行动，在永济、临猗等地屠杀抗日干部。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e3a266d4aea42db92b24784072a4c2e','b932cd17-bb88-4880-949e-40d0c5296ccd',1939,'任伪运城道尹','任伪运城道尹，协助日军建立伪政权，推行保甲制度，强征粮税，并组织汉奸情报网破坏地下抗日组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
