INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ba7da9583ca47ee9a721c253ee522f5','474554bf-2c53-4311-a782-e36fbc571d8e',1940,'组织自卫团为日军站岗放哨','组织自卫团为日军站岗放哨，参与清乡行动，烧毁村庄，抢夺粮食，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
