INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58c3c77793f54acdaadddfd741ed39d6','ca6b1365-5fa4-4895-9a86-6a3fa31039c5',1941,'建立汉奸情报网络','建立汉奸情报网络，向日军提供抗日武装活动情报，导致多次抗日行动失败，多名抗日志士牺牲。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84e8d17d46ee42429e82e4548093e320','65500792-4bd2-424a-8e21-cc3d3ce844e5',1938,'抗战期间任伪河东道道尹','抗战期间任伪河东道道尹，道治设于运城，管辖包括稷山在内的晋南十余县，负责推行伪政、征粮征丁、配合日军扫荡，是运城地区伪政权核心人物。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-969991191c474514ad5085a5d6fea0a1','e620c954-422d-409e-80d1-c807b7bafd45',1938,'稷山沦陷后出面组织伪维持会','稷山沦陷后出面组织伪维持会，为日军筹集粮草、维持地方秩序，协助日军建立伪政权，是稷山当地直接附逆的代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea1d5ccfb72a41fa8e1de51c441f3471','36641621-0773-4364-b56d-3dc7d0882cb4',1940,'抗战期间任伪稷山县知事','抗战期间任伪稷山县知事，主持县政，配合日军征粮、征丁、修筑工事，镇压当地抗日活动，是稷山伪政权的主要执行者。','危害等级C（丙级，基层头目）','hanjian');
