INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0686b77b0fe4d088c70c1a21c81cd36','f1994d0b-9e9c-441b-b675-8ff769e5362e',1938,'安邑县（今属运城）人','安邑县（今属运城）人，抗战期间任伪安邑县知事，配合日军统治，征发民夫、粮食，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-806733e0684b47be880e71b91f3f65fd','28c29e26-8bda-4699-a1ad-7a520039a0b6',1939,'抗战期间任伪闻喜县知事','抗战期间任伪闻喜县知事，闻喜毗邻稷山，其伪政权与稷山伪政权协同配合日军行动，征粮征丁，维持沦陷区统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-504b7cad4909407dbff003a0e01437cb','89ae7e9f-d170-43f5-8060-e835ff38763e',1938,'新绛县与稷山接壤','新绛县与稷山接壤，刘玉堂任伪新绛县知事期间，配合日军对稷山、新绛一带的扫荡，征发物资，镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01f41b6dec4d41b6bcf63352419b2ad4','f95388fc-6dc1-4dc3-9336-a2f89fe3a3d2',1938,'抗战期间在伪山西省公署任职','抗战期间在伪山西省公署任职，推行奴化教育，编写亲日教材，培训伪师资，其教育体系覆盖运城、稷山等晋南各县。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97a3583a8a9344cc94584377679e17c0','57598a09-3c0c-4434-8b3c-ec9e0aa207fa',1938,'抗战期间在伪山西省公署任职','抗战期间在伪山西省公署任职，负责沦陷区建设与资源开发，配合日军掠夺山西煤炭、棉花等战略物资，运城、稷山一带的物资亦在其管辖范围内。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6978b3a19b6c4c00b5e8a7a28d34debb','8d4572e9-533f-4e66-871f-3f0faefe9514',1939,'在伪河东道任职','在伪河东道任职，掌管道内警务，参与搜捕抗日人员、破坏抗日组织，其警务活动覆盖运城、稷山等县。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d79032471504ee580742e14355fe13a','63734745-0319-4b75-861c-5448203a09aa',1940,'抗战期间任伪稷山县保安队队长','抗战期间任伪稷山县保安队队长，率领伪军配合日军扫荡抗日根据地，抓捕抗日群众，是稷山当地伪军头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc554abfb61042528a65517c5db75501','f027e2b5-0e41-48a2-8780-562e7573174b',1938,'投靠日军后出任绛县维持会会长','投靠日军后出任绛县维持会会长，后任伪县长，协助日军推行‘治安强化运动’，强征民夫、粮食，镇压抗日群众，曾亲自带队抓捕抗日干部并交予日军宪兵队处决。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-142ccfabbf6142ebac71edbdd392ab7f','b458370d-ff75-4047-bebe-48c7c0f03ed7',1939,'组织伪保安队配合日军‘扫荡’抗日根据地','组织伪保安队配合日军‘扫荡’抗日根据地，多次袭击抗日游击队驻地，杀害抗日军属，并参与日军在绛县南樊镇、横水镇等地的烧杀抢掠行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-675d499faa444dafbe50ec1724c1ae2e','f2523467-4142-4f42-8bd6-5f7a819414a5',1940,'效忠日军','效忠日军，负责绛县县城及周边治安，大肆搜捕抗日地下党员和进步人士，严刑逼供后移交日军，导致多名抗日志士牺牲。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52c5df626e4d4e30a225c52ead27b14a','01b7d7d2-ecce-4d24-8a21-819d11a50d76',1941,'在绛县推行奴化教育','在绛县推行奴化教育，组织‘新民会’宣传‘中日亲善’，强迫百姓参加反共集会，并收集抗日情报提供给日军特务机关。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e01231209f1944c78c48b88c6124d506','b8857a6f-88e6-4628-b09a-f29de02550be',1939,'在运城沦陷期间为日军筹措军需物资','在运城沦陷期间为日军筹措军需物资，垄断粮食、棉花等战略物资贸易，从中牟利，并协助日军建立经济封锁线，破坏抗日根据地物资流通。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df1cb5cfc25d4dc4a65060351bdfb3a2','a32799bf-b6e0-4c16-aea2-9658e82b0dec',1940,'率伪警备队参与日军对中条山抗日游击队的多次围剿','率伪警备队参与日军对中条山抗日游击队的多次围剿，在夏县、闻喜、绛县交界地带杀害抗日战士及无辜百姓，并抢劫村庄财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd93d473cadf46c793bcdb2c235a80c7','ee1aced7-3353-4c68-8854-ca2efb38bae5',1942,'专门策划针对抗日地下组织的破坏行动','专门策划针对抗日地下组织的破坏行动，在运城、绛县等地发展特务网络，曾导致绛县抗日县政府多名工作人员被捕牺牲。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2495a7544f9249d08cc3c25ba0fef007','0e2831b5-d4f5-414c-a23b-d2b637a2db6a',1940,'在横水镇一带为日军强征壮丁和粮食','在横水镇一带为日军强征壮丁和粮食，欺压百姓，并多次向日军报告抗日武装动向，致使游击队多次遭袭。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1cdb2a24ac0e4c23984a8da4f22b85ab','8878b254-5395-4d84-a21f-07407392fc83',1939,'随日军‘宣抚班’在绛县农村进行反动宣传','随日军‘宣抚班’在绛县农村进行反动宣传，诱骗村民归顺日军，破坏抗日群众组织，并参与建立伪村政权。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
