INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27f1c39cf25c4c9f9c8ca95f703d63ed','37b5b563-5183-4343-ba45-670068d6d7a6',1938,'建立南京伪政权','建立南京伪政权，其伪广东省政府下属机构延伸至河源地区，推行奴化教育与经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25c580df86b1401b917cd4bbf92d9b0b','37b5b563-5183-4343-ba45-670068d6d7a6',1938,'公开投敌','公开投敌，建立汪伪政权，其伪政权体系覆盖广东湛江等地，推行“和平反共建国”卖国路线，协助日军统治沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e2c92497e1e4d7a86fc86f6f58c090d','f8de868f-d485-4539-b14c-28e7ce87f309',1940,'汪精卫之妻','汪精卫之妻，积极参与汪伪政权，在广东扩展伪势力，干预佛山等地伪政权人事与物资征调。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b776110bda5413b986c5ecc6469d6eb','e30b0a8e-0600-47b4-b907-f4763a6b4961',1940,'汪伪军事头目','汪伪军事头目，统率伪军配合日军在佛山、南海、顺德等地“扫荡”，进攻抗日游击队。','危害等级B（乙级，市县厅局级）','hanjian');
