INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4891c41fcb044cbe8a1b98ae477e3f20','e0964011-b216-4eb5-b35f-c5d2e26afaf1',1940,'参与伪政权财政与广东伪政','参与伪政权财政与广东伪政，间接影响佛山、顺德沦陷区经济掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95f3d1d8179c410da7677f31b6024096','52f3cf6b-9d4f-4ff8-bc74-6b28a73d87af',1939,'在广东伪政权中任职','在广东伪政权中任职，协助日军控制包括佛山、顺德在内的珠三角地区。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-147dc71861cf461fb2850b96e38dd549','52f3cf6b-9d4f-4ff8-bc74-6b28a73d87af',1939,'在伪广东省政府中任职','在伪广东省政府中任职，后任伪广州市市长，协助日军管理城市、征调物资、压制抗日活动，其伪政权体系延伸至深圳、盐田等珠江三角洲地区。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b0b201e37aa41d187594a2ad23b5399','27cfbd91-9179-45b1-ab3f-18c3b58d4d34',1941,'在顺德推行奴化教育','在顺德推行奴化教育，改编教材，宣传“大东亚共荣”，毒化青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-553198822d974a7a9a92d51d998e36e5','ed79cca5-beea-4b90-829f-436f6db0fc92',1940,'在南海、佛山一带组建伪警察','在南海、佛山一带组建伪警察，配合日军搜捕抗日分子，推行保甲连坐。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01974c7c2b3b44e98ed1fd1bd7f7ef91','5262b81b-868c-403d-bc23-30719b6ce234',1940,'在三水及佛山周边地区任伪县长','在三水及佛山周边地区任伪县长，协助日军征粮、拉夫，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5583be90dc04ad38b42c67a0209648c','1e6b662b-c81f-49e8-bbd6-09f3a7a0e53a',1940,'协助指挥伪军在佛山、顺德一带配合日军扫荡','协助指挥伪军在佛山、顺德一带配合日军扫荡，维持伪统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8aab674182ec4975a5112a1570b520a1','28494817-08ee-4162-a4d3-7d0a34584661',1938,'广东番禺人','广东番禺人，抗战期间投靠日军，组织伪军盘踞珠江三角洲，在番禺、顺德、中山、南海、佛山一带征收军粮、勒收保护费、配合日军扫荡抗日游击队，残害民众，被称为“市桥皇帝”。其势力范围覆盖佛山及高明周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-677af33b5fbd40fb92d88d929c737983','067e4b5e-41ea-4dfe-a303-d6f333e9c2ad',1938,'李辅群部伪军主要头目之一','李辅群部伪军主要头目之一，协助李辅群在珠江三角洲地区组织伪军、配合日军作战，活动范围包括佛山、南海、顺德等地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7511a277bc4140568f0352035c2eeaeb','a4bb9a8f-0a94-40da-a169-f84202030eea',1938,'佛山沦陷后出面组织伪维持会','佛山沦陷后出面组织伪维持会，后任伪南海县县长，为日军征集物资、维持治安、推行保甲制度，协助日军统治佛山及南海地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f67c353681164583a0e73ea9aee59e3b','c0b57186-6146-4106-ad5f-1bb4acb82fbf',1938,'佛山沦陷初期参与组织伪维持会','佛山沦陷初期参与组织伪维持会，协助日军维持地方秩序、征发民夫物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a0cd4ba1a1544d9b0515943c7ba8d86','13156452-2c1b-4c9a-bb7c-752936420428',1938,'三水沦陷后投敌','三水沦陷后投敌，任伪三水县县长，配合日军统治三水及邻近高明地区，征收赋税、推行伪化教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d382c3601ab44ad19a48be9406992e7c','5110ea33-b495-41eb-8a31-9084db4fabd9',1939,'高明沦陷后出面组织伪维持会','高明沦陷后出面组织伪维持会，为日军征集粮食、民夫，协助日军维持高明地区统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d22aed1a67e4b42b2bb0406611e4c55','c959a751-4422-41d8-a913-e97dcf33a9a0',1938,'广东人','广东人，抗战期间投靠日军，组织伪和平救国军，在广东各地配合日军作战，其势力曾活动于珠江三角洲及佛山周边地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d45179fd2d54d8c877051f423cf84d6','674e1654-fe2f-49c1-9a8b-96d02282d8d5',1938,'广东人','广东人，抗战期间投敌，历任伪广东省政府委员、伪广州市市长等职，协助日军推行伪化统治，其政策影响覆盖佛山等周边地区。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef3666771b704fc68fe24e1977936b38','674e1654-fe2f-49c1-9a8b-96d02282d8d5',1938,'在汪伪广东省、广州市政权中任职','在汪伪广东省、广州市政权中任职，参与推行伪政，配合日军经济统制和治安强化。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed5a8a82dd344cc2857091567db787a5','c45c40bb-5c8a-47f3-9c45-1b910a2a44d1',1938,'广东人','广东人，抗战期间投敌，任伪广东绥靖军第一师师长，在佛山、南海、顺德一带配合日军扫荡抗日游击队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76a6514f848b478dba491f24c188727a','36880b15-a5be-4a06-b3c9-580b8ce9803f',1938,'广东人','广东人，抗战期间投敌，任伪广东绥靖军第二师师长，活动于珠江三角洲地区，配合日军作战。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a85c4600e37c450d8a6d35658fb35e7b','6e47ac60-d838-41bd-a32a-e043414d5bad',1938,'广东人','广东人，抗战期间投敌，任伪广东绥靖军第三师师长，在佛山周边地区配合日军扫荡抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf3815a94aec460badb51dca30c51bcc','14acb281-5d9f-41e0-b300-34376abda6d9',1938,'佛山沦陷后投敌','佛山沦陷后投敌，任伪南海县警察局局长，协助日军维持治安、搜捕抗日人士，推行保甲制度。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-026dfc084367468a9bd8ace5942061c3','f3a2cd41-5983-403a-b446-6910d60226f6',1938,'佛山沦陷后投敌','佛山沦陷后投敌，任伪佛山商会会长，为日军征集物资、摊派款项，协助日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0aa8cc71228540d89fe4ded64fa39ad9','7aa9e91f-cf77-40e0-8299-e639630aace6',1938,'原国民党改组派要员','原国民党改组派要员，1938年随汪精卫投敌，参与建立汪伪政权，历任伪立法院长、伪上海市长、伪国民政府代主席等职，为汪伪政权核心人物之一，广东乳源人，与广州地区有籍贯关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f3ed93215dd4e92a317ffe986f676a5','0fed7cdf-79b7-468f-b6bc-0140f4e4258b',1940,'陈璧君之弟','陈璧君之弟，汪伪政权在广东的主要代理人，历任伪广东省政府委员、伪广州市长、伪广东省政府主席等职，推行伪化统治，镇压抗日活动。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02e6d8de47614fc4819d04d534144a43','70303f89-a6b5-4ab1-a8d1-fd5cab9c5d1d',1940,'原国民党军官','原国民党军官，投敌后任汪伪政权伪广东省政府主席、伪广东绥靖公署主任等职，协助日军维持广东占领区秩序，统率伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7685a8b66bc432e8968fc6ddaf01dc5','fd493965-9ce0-4c2b-bf7f-1c1b25d8773a',1940,'汪伪政权在广东的重要官员','汪伪政权在广东的重要官员，曾任伪广州市长、伪广东省政府委员等职，参与伪政权地方行政。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
