INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f6b0b2b8e1c45289b1a6c47f6f7cf85','d51c93e7-987e-418f-98c1-437aa1a45047',1940,'负责伪广东宣传','负责伪广东宣传，在广州主办亲日报刊与广播，为日军占领制造舆论。','危害等级C（丙级，基层头目）','hanjian');
