INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3e72c1351ca4fbcb4a12dadb72dcdf0','67145131-5a71-4fce-9af0-67d084062365',1938,'汪精卫之妻','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾赴广东活动，对包括江门、恩平在内的广东沦陷区伪政权建立与维持负有责任。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
