INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9604da2756784950ab74930c8a26cc2f','67145131-5a71-4fce-9af0-67d084062365',1938,'汪精卫之妻','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广东等地活动，广西方面亦有汪伪势力渗透背景，属广西籍汉奸要员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e52af27dc3154a4d9566e4819bca31ae','67145131-5a71-4fce-9af0-67d084062365',1938,'汪精卫之妻','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广东等地活动，广西籍背景与华南伪政权网络有关联，但主要在南京、广东活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e35dc3c555b945a4942de3527ca4c1c7','67145131-5a71-4fce-9af0-67d084062365',1938,'汪精卫之妻','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾赴广东等地活动，广西为其夫广东政治势力邻近影响区域，属汪伪政权高层附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-537c192752c84995a33a4eb7d8d9709a','67145131-5a71-4fce-9af0-67d084062365',1938,'汪精卫之妻','汪精卫之妻，随汪投敌，参与汪伪政权建立，曾任汪伪国民党中央监察委员会常务委员等职，为汪伪政权核心人物之一，其活动虽主要在南京、广东，但与广西籍汪伪人员及华南伪政权网络有联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc93cff3562342baa69c298036578c38','67145131-5a71-4fce-9af0-67d084062365',1938,'随汪精卫投敌','随汪精卫投敌，参与汪伪政权建立，虽非广西籍，但汪伪政权对广西沦陷区及周边地区伪组织有统辖影响，其附逆行为在广西有宣传与组织渗透。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
