INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc20c6ab10d8459f87ccf9bb639d96fb','640cc4e2-f5c4-4c6b-92f9-110ebd99372b',1941,'推行奴化教育','推行奴化教育，篡改教材，强迫惠州、惠东学校师生接受亲日宣传。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c43c5db7a0d46b4b979f7dcc63c5722','bd79c906-da4d-4bc6-9820-114b5a755e19',1942,'协助日军统制惠州、惠东地区粮食与物资','协助日军统制惠州、惠东地区粮食与物资，压榨民众，供应日军军需。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e508e48314242cc9bad48517a35d207','78c20897-04a8-472b-9e68-1d70c5f628f9',1939,'在惠州沦陷期间任职伪警察机构','在惠州沦陷期间任职伪警察机构，参与搜捕抗日人员、镇压民众抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5edba9f8ee8408aa82def7449264c89','f0589103-cb4a-482e-b214-e80b47af18e3',1940,'统率伪保安队配合日军扫荡惠州周边乡村','统率伪保安队配合日军扫荡惠州周边乡村，袭击东江抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-203e3d219070482fa7d414ff40ba3b8a','2f706402-a22b-4bba-ad91-3923aa3a034a',1941,'率伪军在东江流域包括惠州一带进行清乡','率伪军在东江流域包括惠州一带进行清乡，协助日军控制水陆交通线。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe8d210397d34ab4a70db73d52897e06','f1b02f62-a0e2-4dd5-bbce-0863063ca815',1940,'推行奴化教育','推行奴化教育，在惠州各校强制增设日语课程，宣传所谓‘大东亚共荣圈’。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6179764abf047f39b32105a89e3e753','8071b9f2-00b4-46e9-bff3-134bd1f373d0',1939,'为日军筹款筹粮','为日军筹款筹粮，强制商户缴纳‘治安费’，协助日军经济统制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9462210846894641a751d4b6f59aa0ab','183bdfc3-0cd3-4c64-b8cc-39c010a3061d',1942,'负责惠州地区伪政权与日军联络','负责惠州地区伪政权与日军联络，参与策反抗日武装人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcf18e95907a481d939cefa088dd6025','63e46431-9278-4a58-96d2-249baf81417f',1941,'在惠城周边乡村推行保甲连坐','在惠城周边乡村推行保甲连坐，举报抗日家属，协助日军征丁征粮。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5bc963362b2d4ab3908dcbbb6c61fc4e','f629c6e3-428d-416a-9121-fc70a2d390ce',1942,'组织慰劳日军活动','组织慰劳日军活动，动员妇女为日军缝洗，进行亲日宣传。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-912c577f2c4f4dd7afb80502e31e79f8','5ccff47d-6047-4ff4-a801-869fe413f3eb',1941,'在惠州发行亲日报刊','在惠州发行亲日报刊，散布投降言论，诋毁抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b94848f13ee43c8933052b0bd9dd374','3fbb374d-32b0-4e3a-9076-ba9a6daee11e',1940,'在日军扶植下出任伪惠阳县县长','在日军扶植下出任伪惠阳县县长，主持伪县政，推行保甲、征粮、拉夫等事，配合日伪统治惠州、惠阳地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90c1010e20c44da5939bd3b39b53fa8e','0813ec8d-b99f-4a46-86f5-3e6ba42da9f2',1940,'在惠州、惠阳地区充任伪警察头目','在惠州、惠阳地区充任伪警察头目，协助日军搜捕抗日人员、控制交通与户籍，镇压民众抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05b79fc676b2443295cd533643c5ee17','da97d165-d185-41e4-b016-de241b483a8a',1938,'惠州、惠阳一带部分地方士绅与旧军政人员在日军占领期间附逆','惠州、惠阳一带部分地方士绅与旧军政人员在日军占领期间附逆，参与维持会、伪县政或伪军组织，为日军筹款、筹粮、招抚游杂武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fc8598e429b4c74adcd7b9e04679e62','24e9a3fb-7a26-4071-894b-c6a0c5afb355',1938,'广东沦陷后投靠日军','广东沦陷后投靠日军，参与伪广东治安维持会及伪军活动，其势力与活动范围涉及东江、惠州一带，协助日军维持占领。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4e3418ade4b4cc3a75b67c7fcd382aa','818f0b46-d95b-4376-bd75-1738188b3c9d',1938,'广东沦陷后出任伪广东治安维持会会长等伪职','广东沦陷后出任伪广东治安维持会会长等伪职，为日军在广东建立伪政权的重要人物，其伪政权体系覆盖包括惠州在内的广东多地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e70481618a5f4c91b4a858eba86b9d18','901fada1-b8de-4248-b237-c43f59712f25',1940,'在汪伪广东政权和伪军中任职','在汪伪广东政权和伪军中任职，参与协助日军控制广东沦陷区，包括东江、惠州地区的伪军警活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0bf945458764f96be52cf1eab0437a8','c8d2fb98-566b-4b04-9a65-f03786c956ba',1938,'广东东江沦陷区附逆人员','广东东江沦陷区附逆人员，参与惠州、惠阳周边伪维持会或伪基层政权，为日军征派物资、维持治安。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9035811ef70f442783c5389e4efc18cc','5172f596-9fb5-47c2-8dfe-bf58e6ead268',1938,'广东地方游杂武装头目之一','广东地方游杂武装头目之一，抗战期间一度投靠日伪，在惠州、东江一带配合日军行动，骚扰抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be5a5516bb7b462eabd59999b8c5d4dc','90e41c94-0758-4268-a76b-02789b7cfdb6',1938,'原名李辅群','原名李辅群，广东东莞人，抗战期间投靠日军，组织伪军盘踞东莞、惠州、宝安一带，配合日军扫荡东江抗日根据地，在惠州及东江下游地区征收苛捐杂税、残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-193b9d4cca544be1a57dc526dcf212f3','4744aa59-883d-40fb-80c7-acc3a7eacc4b',1939,'广东潮阳人','广东潮阳人，原国民党军将领，抗战中期投敌，任伪军师长，率部在惠州、海陆丰及东江地区配合日军作战，进攻东江纵队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7add0c6680a64ce09e3194afff09699b','90ff9bae-2f79-4493-99ac-504a1e80a8f5',1940,'广东人','广东人，投敌后任伪军师长，活动于惠州、增城、龙门一带，协助日军维持占领区治安，参与对东江抗日根据地的清乡扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a364c6f08934daf8302720dfc4c5f5a','715a25b2-18c6-46f5-831e-b49fb0654ff8',1938,'惠州沦陷后出面组织伪维持会','惠州沦陷后出面组织伪维持会，为日军筹粮筹款、拉夫向导，协助日军在惠州城内建立殖民统治秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80ce813081c049f1b821f59f6100a8d0','c931b5b7-41c8-46f1-ab9a-f16cfdad0eff',1939,'在日军占领惠州期间出任伪惠阳县县长','在日军占领惠州期间出任伪惠阳县县长，推行保甲制度，配合日军征发民夫、征收物资，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-448f3e897ca44b38a2440472123961b1','39b566e3-833b-4d6a-b317-ae4969530126',1939,'龙门县沦陷期间组织伪维持会','龙门县沦陷期间组织伪维持会，为日军带路扫荡龙门及增城、博罗边境抗日游击队，强征粮食供给日军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-268510b2e6974556a997660ba9b3e9c7','3d464321-a28e-46dc-aedd-d3e1903d5c02',1938,'东莞人','东莞人，投敌后任伪保安大队长，活动于东莞、惠州、博罗交界地区，配合日军进攻东江纵队，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1af768dc023543b3a1ce9cdc8963d1ec','855a222d-9572-4d52-a1d5-0f6e3c3176e3',1940,'汪精卫之妻','汪精卫之妻，汪伪政权核心人物，参与伪广东省政，推动广东沦陷区殖民统治，其政策影响覆盖惠州、龙门等东江地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c07d087bd3841bf8ff2745423e04a1c','1181a2af-c9e1-448a-af8d-eda2456e9d33',1940,'汪伪政权广东省省长','汪伪政权广东省省长，主持广东沦陷区伪政，推行奴化教育、征粮征丁，其政令下达至惠州、龙门等县伪政权。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03416b6ea2d049c0987bb5a8f0b44f9c','1181a2af-c9e1-448a-af8d-eda2456e9d33',1940,'投靠日本','投靠日本，在广东伪政权中任职，配合日军统治，对陕西有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-501bb03cbeb74d158cf9ca351eede1b3','04900c2f-2023-40fe-8a41-b7d10dcf5846',1944,'汪伪政权要员','汪伪政权要员，继陈耀祖任伪广东省省长，继续推行附日政策，维持广东沦陷区统治，包括惠州、龙门一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-529480dd5516430d8d6dc1299566dc2c','e108313a-f297-4f28-bd54-04cb1334bfdd',1941,'投敌后任伪军师长','投敌后任伪军师长，率部在惠州、河源、龙门地区配合日军扫荡东江抗日根据地，烧杀抢掠。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d76e8c729d72451692c2a5305bbf2a06','5755ce87-f1ea-4586-ae1b-f784eb6887d8',1940,'在日军占领博罗期间任伪县长','在日军占领博罗期间任伪县长，与龙门、惠州伪政权配合，推行保甲连坐，协助日军清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9be47017ecfe4ebdafbc028cc6320d4f','8f7ff6b6-ac26-469d-a211-3c961a2d43fb',1938,'日军侵占广州后曾试图拉拢其出任伪维持会会长','日军侵占广州后曾试图拉拢其出任伪维持会会长，陈炯明未接受，但日方仍将其列入拟用名单，此事在揭阳及粤东地区有传闻。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad083e167d05429fa854c9921b0e0042','8f7ff6b6-ac26-469d-a211-3c961a2d43fb',1938,'日军侵占广州后曾试图拉拢其出任伪职','日军侵占广州后曾试图拉拢其出任伪职，陈炯明未接受，但因其旧部多附逆，常被列入相关人物讨论。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f6392f33e5f4102a5fbd434ff699aba','a02da96b-ebf0-40f9-8822-d5beb4ff186f',1939,'日军侵占揭阳期间','日军侵占揭阳期间，出面组织伪揭阳县维持会，协助日军征粮、派夫、维持地方秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a10fc9451b248d39afca15e1aa36eaa','e1e908ac-185b-4fdf-8877-123101d183d9',1940,'在伪揭阳县政权中担任警察头目','在伪揭阳县政权中担任警察头目，配合日军搜捕抗日人员，镇压地方抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be4fd44d84fe4c8a8ac6e25b9a747a08','50eb82de-20fc-4b62-9822-1fcc2da0c308',1941,'率伪保安团配合日军扫荡揭阳周边抗日游击队','率伪保安团配合日军扫荡揭阳周边抗日游击队，强征壮丁、勒索民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d6e4311d572412094b73924726683b9','f480ee38-7c3b-4908-b52a-96eecdfcaffc',1939,'在潮汕地区协助日军推行伪化统治','在潮汕地区协助日军推行伪化统治，参与组织揭阳、潮阳等地维持会，为日军筹款筹粮。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
