INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3832d1bca664498a852d03167e579d2','aa4fb8c7-3570-4780-80a1-feb5d389fa38',1939,'在潮安组织伪维持会','在潮安组织伪维持会，配合日军对揭阳、潮安交界地区的扫荡与物资掠夺。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c2ddbb254d74bd39ce66344e18691e3','10638658-d74a-4bb4-bacd-d76926ab2449',1940,'在广东收编伪军','在广东收编伪军，其势力范围涉及潮汕地区，与揭阳伪军有联系，配合日军进攻抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16019cf9b8b344979aaa3f0514f94eb0','c64833e9-fcbc-49a9-9aa6-05dad9a005a1',1940,'在揭阳推行奴化教育','在揭阳推行奴化教育，篡改教材，强迫学校使用日语教学，宣传“大东亚共荣圈”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-802d878e60234b0f86abfc7eb2cb82e1','c64833e9-fcbc-49a9-9aa6-05dad9a005a1',1940,'在揭阳推行奴化教育','在揭阳推行奴化教育，篡改教材，宣传“大东亚共荣圈”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-279a33c1b7804333a06f4bbcac6549f3','8e801cd2-6d2a-4cec-933e-19961d30ee81',1939,'控制揭阳商业','控制揭阳商业，为日军征购物资，协助日军对揭阳经济进行掠夺，压榨商户。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ca98dbb955e414c95a131aea9f1ba37','ebd83afc-7a46-4545-b5c2-23b1c4dff4d1',1940,'在普宁组织伪维持会','在普宁组织伪维持会，配合日军对揭阳、普宁交界地区的控制，征粮派款。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-407ec178660f44a7923bdf674bb3f32d','2f98d8bb-598e-4ed8-b6c2-23a160d09a54',1941,'在惠来组织伪政权','在惠来组织伪政权，与揭阳伪政权协同，协助日军封锁沿海，阻断抗日物资运输。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac73976a86bb4cf49b8fcc8830ace891','57355d44-13ee-4688-81c9-65d3f764ce2e',1931,'九一八事变后','九一八事变后，日本方面曾拉拢陈炯明，试图让其出面组织伪政权。陈炯明虽未公开就任伪职，但曾与日方接触，其旧部在广东沿海地区活动，与揭阳、惠来一带地方势力有联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a11747806634c19ae25b7db5c57bfa0','57355d44-13ee-4688-81c9-65d3f764ce2e',1931,'九一八事变后','九一八事变后，日本方面曾试图拉拢陈炯明合作，陈炯明一度与日方接触，但最终未公开就任伪职。其活动范围主要在广东及香港，与揭阳地区有间接关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-affbacf86ff24f51bcd52e38865a6ac2','57355d44-13ee-4688-81c9-65d3f764ce2e',1931,'抗日战争初期','抗日战争初期，日本侵略者曾试图拉拢陈炯明出任伪广东省政府主席，陈炯明未正式就任即于1938年病逝，但其与日方接触的传闻在广东地区流传。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21255d022ef845e2b6be9edddbcd4536','57355d44-13ee-4688-81c9-65d3f764ce2e',1931,'九一八事变后','九一八事变后，日本方面曾试图拉拢陈炯明出任伪广东省政府主席，陈炯明未公开就任，但其旧部与日方有接触。陈炯明为海丰人，海丰与陆河相邻，其活动范围覆盖汕尾地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-518ed32f7bac44debdcb24404c1d8f21','57355d44-13ee-4688-81c9-65d3f764ce2e',1931,'九一八事变后','九一八事变后，日本方面曾拉拢其出面组织华南伪政权，陈炯明虽未正式就任伪职，但与其旧部保持联系，被时人视为潜在附逆对象','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8aea5652bd7b473c9d988b063c07a063','57355d44-13ee-4688-81c9-65d3f764ce2e',1931,'其活动范围涉及广东及香港','其活动范围涉及广东及香港，与深圳、盐田一带的旧部有联络。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b1ae495c58543b2af1780fb7f2c735a','57355d44-13ee-4688-81c9-65d3f764ce2e',1931,'九一八事变后','九一八事变后，日本方面曾试图拉拢其出面组织伪政权，陈炯明虽未公开就任伪职，但与其旧部在广东沿海及深圳、罗湖一带的势力被日军利用，间接为日方渗透提供便利。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a297540e9b444ba0aa448cf2dbd5d156','1e30ec7c-f82b-4255-a48e-7a46b56121cb',1938,'广州沦陷后','广州沦陷后，林知渊参与伪广东治安维持会，协助日军维持占领区秩序，其活动范围涉及广东东部沿海，包括揭阳、惠来周边地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbc20d250bd34e3c95cb325c50f062b3','4fe87d31-bf9f-4cfa-9905-4754321ac3ba',1939,'陈耀祖在日军占领广州后出任伪职','陈耀祖在日军占领广州后出任伪职，参与伪广东省政府事务，其政令曾下达至潮汕地区，包括揭阳、惠来一带，协助日军推行治安强化运动。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed20e8c4aaca4d3cb523dd26718f0cf8','2530482f-aef9-4bf0-b7e9-a7fc547e822f',1939,'潮汕沦陷后','潮汕沦陷后，王英儒出面组织伪潮汕维持会，协助日军管理潮汕地区，包括揭阳、惠来等县，负责征粮、拉夫及情报收集。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90cfd7f5a1b64dfc8d666baee828a9f8','10a0e88a-2cc7-47f7-bc30-3a258f6a3bce',1940,'李国梁在惠来县沦陷期间出任伪维持会会长','李国梁在惠来县沦陷期间出任伪维持会会长，协助日军征缴粮食、物资，并参与组织伪自卫队，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7405e4ebee7143069ac76278ccabb841','be1291ae-ea20-4b89-ad7a-2c6b8c76dc9d',1940,'张瑞贵在揭阳地区协助日军建立伪政权','张瑞贵在揭阳地区协助日军建立伪政权，负责保甲连坐制度的推行，配合日军扫荡抗日游击队，其活动范围覆盖揭阳及惠来交界地带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8849a31de24471da248b172092024f6','4b15897b-a1b2-4c43-87ab-bbb14a06c900',1941,'陈子岐在潮汕地区为日军搜集情报','陈子岐在潮汕地区为日军搜集情报，抓捕抗日人士，其侦缉活动涉及揭阳、惠来等县，导致多名抗日志士被捕遇害。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0274f848290b41e09b51d05aaa2cab4b','c10a43e9-0f58-43dd-b771-1d8e091a4501',1942,'黄启良统率伪保安大队在惠来及周边地区配合日军作战','黄启良统率伪保安大队在惠来及周边地区配合日军作战，参与围剿抗日武装，强征民夫修筑工事，残害当地百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98bed4f91e2348b799ce89029c91372d','02643303-0323-4c3d-8eb8-e24d84a0ca72',1938,'刘志陆在广东东部地区组织伪军','刘志陆在广东东部地区组织伪军，配合日军对潮汕抗日根据地实行封锁和扫荡，其部队活动范围包括揭阳、惠来一带。','危害等级C（丙级，基层头目）','hanjian');
