INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f47cb70148746f991ad1653d3d69013','ed97c323-566a-4a98-8b54-eedf027129a0',1941,'吴文献在揭阳推行奴化教育','吴文献在揭阳推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”，并协助日军筛查抗日师生，其影响波及惠来等邻县。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f97947faed64d6cb603baa917010f7a','559991a2-e652-4c2f-b1fc-1d1eec14b2e8',1938,'广东沦陷后出面组织伪广东维持会','广东沦陷后出面组织伪广东维持会，后任伪广州市市长，协助日军维持殖民统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
