INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-664f9e301b0b4b008e492fd1e1b27cc5','9f448052-b189-48c6-817f-fada5a53652d',1939,'揭阳沦陷期间出面组织伪维持会','揭阳沦陷期间出面组织伪维持会，为日军征粮、派夫、维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
