INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0c9ada54eb8422a838f1f4c4d95bf49','263a6d58-f151-413c-8bb5-af4413d9b252',1938,'广东梅县人','广东梅县人，抗战期间投靠汪伪政权，任伪职并发表附逆文章，为日军文化侵略张目，是广东籍著名汉奸文人之一。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
