INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5f3f54bb47d4dc5a4b3322a66583690','b997dc5f-e3b0-4d70-a172-176908d68c4e',1939,'在潮汕沦陷区任伪警察头目','在潮汕沦陷区任伪警察头目，配合日军镇压抗日群众，搜捕抗日人员，其活动范围覆盖潮梅地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
