INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c01c89b918646119c13e85cfb582ea1','52dfe88e-9e48-4c5d-ac3b-daea48d82194',1939,'广东海丰籍','广东海丰籍，活动于东江、韩江流域，参与伪军组织与情报活动，与梅州地区抗日力量为敌。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-070dd5adfee2425eb489e64523297140','3af88a3b-7d94-478e-a041-baceb57b1ea6',1940,'在五华县境协助日军及伪政权维持治安','在五华县境协助日军及伪政权维持治安，搜捕抗日游击队员，征派捐税，压迫当地民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a80ff94fcf3a4b25af0b38cb99828ec0','982b15d3-b5f9-4ae1-9d79-b42cdb8912a4',1940,'在梅县伪警察系统任职','在梅县伪警察系统任职，配合日军及伪政权清查户口、监视抗日分子，并参与经济封锁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-036ecae980cb47e88a1592addbef9146','e90f841b-d25f-4919-926d-7ee978a7c6e2',1939,'日军侵占潮汕、威胁大埔期间','日军侵占潮汕、威胁大埔期间，出面组织伪维持会，协助日军征粮、派夫，并诱降地方士绅。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-966c16d15c80443e8ed8e2613e05d67f','c9cbe20c-36e2-4293-9e25-815c14eeefa0',1939,'在梅县沦陷区协助日军建立伪政权','在梅县沦陷区协助日军建立伪政权，负责情报搜集与物资征调，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64a2009b3aab4bc7ad183058776a6c4a','5ee29ee2-3aa1-4e5e-9731-6090f8881089',1938,'在广州伪政权中任职','在广州伪政权中任职，参与制定对粤东地区的“治安肃正”计划，配合日军扫荡梅州、大埔一带抗日武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e7116608f7b46958012875e3bcf3f9c','bb2e9dd2-bc50-4b41-a8e3-b2accbe884d2',1939,'控制潮汕至梅州、大埔的交通线','控制潮汕至梅州、大埔的交通线，搜捕抗日分子，为日军提供梅州、大埔地区抗日活动情报。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-caec22626bee4b2caf777b7863d5dca0','be0a0256-d30f-4f8e-a7d4-aeccb641d3db',1940,'率伪军配合日军进攻粤东','率伪军配合日军进攻粤东，曾在大埔、梅县边境地区进行清乡，镇压抗日游击队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb019214d27a42ed9d85efc30abd4446','46d3b91f-bbd7-443c-8fc6-316c42c009af',1941,'负责联络梅州、大埔地方伪维持会','负责联络梅州、大埔地方伪维持会，推行保甲连坐，协助日军掠夺钨矿等战略物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78d2cf0a876a45118a2d89e8c8b09c1e','d8d2bcd3-95a7-431a-9ea7-7bfb1cafc87f',1940,'在大埔境内设立检查站','在大埔境内设立检查站，盘查抗日人员，多次带领伪警察配合日军搜山。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4c8ebd2c78a4f33afe6b304b97972f8','70d5d67f-b2d3-45ff-a090-9dc30623d92d',1939,'在梅县推行奴化教育','在梅县推行奴化教育，编写亲日教材，强迫学生参加“中日亲善”活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42da6183936f429a80d6741af5d7f903','0f4d4961-9e1b-44d2-8c56-35e0f670db66',1939,'往来于潮安、梅县、大埔之间','往来于潮安、梅县、大埔之间，为日军劝降地方武装，并组织伪自卫团。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3492fbff6f64c14b6aed8ef44cc707c','bb5792fa-3209-4b1c-8a98-09ff5c59cadd',1940,'强制商户向日军缴纳“军需捐”','强制商户向日军缴纳“军需捐”，并协助日军统制大埔陶瓷、茶叶等物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccec824649b344889645a6b4293a1bfd','aa15db14-00c3-42db-9f07-f52bfd906078',1939,'日军侵占潮汕、威胁梅县期间','日军侵占潮汕、威胁梅县期间，出面组织伪梅县维持会，后任伪梅县县长，协助日军征粮、拉夫、维持所谓治安，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d062f4e1f9524db98002086faaf44e31','0b5cee83-cd4d-45ad-863b-0e35f8f802e1',1940,'在伪梅县政权中掌管警察武装','在伪梅县政权中掌管警察武装，配合日军和伪政权搜捕抗日人士，勒索商户，维持日伪统治秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92269c7482dd485c845a1863ca5ee751','3f2c7434-4564-493e-9829-03028a27a92d',1941,'担任伪保甲长期间','担任伪保甲长期间，为日军搜集梅县抗日游击队情报，带领日伪军搜山，迫害抗日家属。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0736d6fddaa41f4a7c1d4982c45e58d','0804fdbd-05b6-43ad-8861-2edfa26e80f5',1938,'在广州参与伪广东治安维持会','在广州参与伪广东治安维持会，后受日军指派到粤东梅县一带活动，拉拢地方士绅附逆，为日军筹粮。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47ba0bf2b3d94658936035f3725db7be','032b9c78-9ff8-4afe-b840-a9f4b8afa63a',1939,'在汕头及潮梅地区推行日伪统治','在汕头及潮梅地区推行日伪统治，配合日军对梅县、兴宁等地的经济封锁和扫荡，诱降地方武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-781324bc3abd45108455165444adb3a1','62778395-ef17-470f-8d60-b5ab83fd1f78',1939,'在潮梅地区组织伪维持会','在潮梅地区组织伪维持会，为日军征集物资、劳工，并派人到梅县、蕉岭等地诱降地方势力。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b937e9b0bd14e48a57fe4350d8e1288','f0708ab5-c6b0-4a7e-b1d2-2bffe16e8aa1',1940,'在伪梅县政权中推行奴化教育','在伪梅县政权中推行奴化教育，篡改教材，强迫学校悬挂日伪旗帜，向学生灌输所谓“大东亚共荣”思想。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29381e41bf2943189462a8a8d215dbae','75f74201-005f-4d09-88f7-d1cc96e7c8c6',1939,'控制梅县商会','控制梅县商会，为日军采购粮食、药品等物资，协助日伪对梅县实行经济统制，从中牟利。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8356195c2a0a486c836df9acc0e10232','044a4878-97dc-4d3b-a885-9ae2d8f5449e',1939,'日军侵占潮汕、威胁梅州期间','日军侵占潮汕、威胁梅州期间，出面组织伪蕉岭县维持会，后任伪县长，协助日军征粮、派夫、维持治安，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e3b6d803dd94ab4b64eff9ba75c6e68','231ee01a-f3d6-4350-adf3-fa84f59f03ce',1939,'在潮梅地区活动','在潮梅地区活动，曾任伪汕头市警察局督察长，后任伪潮梅绥靖公署参议，配合日军清乡，抓捕抗日人士，其活动范围覆盖梅州、蕉岭一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c22905fc7de423f924f87c17a3fca04','33410bae-7f3e-40da-b3b5-4d4f90236be3',1938,'在广州沦陷后受伪广东治安维持会指派','在广州沦陷后受伪广东治安维持会指派，回梅县组织分会，拉拢地方劣绅，为日军南侵张目，后因日军未占梅县而活动受限。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4f835e0ef7b4373bbf3dea6c9f6f908','9e7b6b6c-4c26-4a6a-b877-83080d016d15',1938,'广东梅县人','广东梅县人，早年军阀，抗战期间投敌，任伪广东治安维持会会长、伪省政府委员，在广东沦陷区推行伪化统治，对梅州籍人士有号召性负面影响。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce49ff6c789545b9a4e72b6feb4b7d4d','fb17389b-6b15-4581-9796-b5fa7e0abdd9',1943,'在潮梅地区组织伪军','在潮梅地区组织伪军，配合日军对梅州、蕉岭等地的抗日游击队进行清剿，强征民夫、粮食，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af80a578c1714fceb05e2e5267d94cda','c3a6ee69-45b7-46ea-8e3f-f5f1b963cab6',1944,'日军侵扰粤东时投敌','日军侵扰粤东时投敌，任伪蕉岭县警察局局长，带领伪警察搜捕抗日分子，为日军带路扫荡乡村。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c161964409f84e3882c751dfadbc6ae9','d6251cc3-4772-498f-bf03-9c10ef517437',1939,'在梅县乡村充当伪保甲长','在梅县乡村充当伪保甲长，协助日军征粮派款，监视村民行动，向伪政权举报抗日家属。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-defcfc63753d4759bd1b19d92fcbf5b9','9c279887-b000-464f-9c14-b9413edbf05c',1940,'在广东沦陷区推行奴化教育','在广东沦陷区推行奴化教育，任伪潮梅教育分会会长，编写亲日教材，强迫梅州籍学生接受日语教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4af3f5fc871b4eeb9f44447b335eb581','c8638d64-5e4d-4261-8f68-d935b7d32d5e',1939,'日军侵占汕头后出面组织伪政权','日军侵占汕头后出面组织伪政权，任伪汕头市长，推行日伪统治，协助日军维持治安、征发物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0af3f1e3f63d4005800ece88bec89a4e','652ee721-22e1-476a-9dbc-652fd9cc430c',1939,'在汕头沦陷区充任伪警察头目','在汕头沦陷区充任伪警察头目，配合日军搜捕抗日人员，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
