INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13e8f37080e34624b45f66637a61e3c0','8559ae6a-3b22-40ce-b5dd-66140944e8d3',1938,'广东番禺人','广东番禺人，投敌后组织伪军配合日军在珠江三角洲及江门、台山沿海地区进行清乡、扫荡，掠夺物资，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
