INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffb0e6f99f5d4ba0891a0083dbf30e75','6642f137-0294-4f36-90c6-a079cb07eb1e',1938,'在广州沦陷后参与组织伪维持会','在广州沦陷后参与组织伪维持会，协助日军维持占领秩序，推行奴化宣传。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6b0a9a4c3a84c73a10871254afc9bbf','46e08098-d576-484a-87dc-bda7ede72c35',1939,'在东江流域包括河源、紫金一带组织伪维持会','在东江流域包括河源、紫金一带组织伪维持会，为日军征集物资、情报，协助日军清乡，直接危害当地抗日军民。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b012cf0083954804861da93d4ade69df','0ce939ac-9a73-4178-9421-1d98ef5f7ceb',1939,'在河源县城组织伪维持会','在河源县城组织伪维持会，协助日军控制河源地区，镇压抗日群众，为日军提供粮食和劳工，直接关联紫金等周边地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
