INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-720c64001da144a393c40d15b1c6d541','654f8512-593b-4627-bdd0-b20c78a98511',1938,'在深圳、东莞一带组织伪军','在深圳、东莞一带组织伪军，配合日军扫荡抗日游击队，抢劫民财，其势力范围包括深圳、盐田周边地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
