INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6c553b42247492b99da50ecc00a69cf','50212578-d078-42da-b512-defaf7d6c82b',1940,'在伪广东省教育厅任职','在伪广东省教育厅任职，推行奴化教育，宣传“大东亚共荣圈”，其教育政策覆盖包括深圳、盐田在内的广东沦陷区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
