INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11d29505da354af5b5018bac1ecbd011','5b958741-0295-4cbc-8565-93988107932f',1938,'在广州伪政权中任职','在广州伪政权中任职，参与协助日军控制广东沦陷区，其活动影响波及南路包括湛江地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
