INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a6b0e3e8a4649aba960abf99721f573','6c80e006-e1b0-4a3e-a26a-612a12c8aedd',1939,'雷州沦陷后出面组织伪维持会','雷州沦陷后出面组织伪维持会，协助日军征粮、派夫、维持地方治安，为日军统治雷州半岛提供地方支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
