INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df474deed96543febf2259a260e556be','e0910a14-4162-44f7-8127-6d94d9ef77a1',1933,'九一八事变后','九一八事变后，日本侵略者企图拉拢其出面组织伪政权，陈炯明曾与日方接触，但未正式就任伪职便于1933年病死，其与日方暧昧关系在潮汕地区有历史记载。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
