INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c62b61d4209146a8aeb7dc8843cb25cc','39203027-02e7-4314-9c1c-778d1c6588f7',1938,'原国民党副总裁','原国民党副总裁，1938年叛国投敌，1940年在南京成立伪国民政府，成为头号汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
