INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6a143e65fd84053bd744bf4eafe3120','1ca65215-6a23-413e-afcf-3ac33ce36c29',1943,'在电白沿海地区组织伪维持会','在电白沿海地区组织伪维持会，配合日军登陆与物资掠夺，强迫渔民为日军服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
