INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90dabad8a4ff4d95850529899f781a7e','768bfbda-a1cd-4b50-b8cb-5a7f93de7489',1944,'在高州地区为日军搜集情报、指认抗日家属','在高州地区为日军搜集情报、指认抗日家属，参与组织伪保甲制度。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fce0353699984318baae696f57c34b3d','dedff2da-7627-4494-ba23-c47fe2f7230f',1942,'虽早期为粤系军阀','虽早期为粤系军阀，后在日军诱降下参与伪广东政权活动，对茂名、高州一带旧部进行劝降。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-244816dc1b9946ed8c8be96162380934','3126a6b1-e501-4c40-bca9-da5505f7ac89',1942,'在广东沦陷区推行奴化教育','在广东沦陷区推行奴化教育，于茂名、高州等地协助日军控制学校，篡改教材。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-163d9fdd1f8640569b436344ce149c28','72d6a236-25b0-44dc-be9c-69d4d5ee7dd0',1943,'作为汪伪政权在广东的最高头目','作为汪伪政权在广东的最高头目，其政令覆盖茂名等南路地区，推动伪政权建设与物资统制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e61d025dac6a4b82a75a69402d4850bc','6d853367-04d3-46ee-9ec2-0290da13ae5e',1940,'抗日战争期间在化县一带附敌','抗日战争期间在化县一带附敌，参与组织伪维持会，为日军征粮、派夫、维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b26a916849846168ead0cd07decc851','d1dd972f-3401-4f77-a836-9e846cbff6f3',1940,'茂名、化州、电白等地沦陷或受日军窜扰期间','茂名、化州、电白等地沦陷或受日军窜扰期间，部分基层保甲长、维持会人员附敌，协助日军征发物资、传递情报、维持伪统治。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c13be381ee2c4dd1a7b34d1d74d88ac3','86c6b367-6fc8-4fb8-b280-3094a7dc9027',1940,'汪伪政权核心人物之一','汪伪政权核心人物之一，后任伪广东省政府主席，推动广东伪政权建设，配合日军统治，影响覆盖广东全省包括茂名、化州一带。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
