INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9fcd1c55ee1a4a41832dc5b0e40eef9e','95575094-b736-47f0-a1a7-5efadbb744fb',1940,'在雷州半岛及邻近粤西地区附敌','在雷州半岛及邻近粤西地区附敌，组织伪维持会，为日军征集粮食、劳工，配合日军对茂名、化州方向的扫荡与封锁。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
