INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0808fef05cee4c6e81e59d8c55cc3d1d','79f35803-4dd8-49f0-bd39-ad0f5f51c0fd',1940,'汪伪政权在广东的最高头目之一','汪伪政权在广东的最高头目之一，主持伪广东省政，推行日军殖民统治，镇压抗日力量，其伪政权统治范围覆盖广东全省，包括茂名、电白一带的伪行政体系。','危害等级C（丙级，基层头目）','hanjian');
