INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0e99167123f4cc39d5c28de14492c32','93efa102-7496-471a-bc6b-bc0dcee7e6d6',1937,'桂系要员','桂系要员，抗战后期曾与日军暗中接触，谋求保存实力，但未公开投敌，故严格意义上不属汉奸，仅列作相关人物。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22b075c2e553476497739180e8ba52c2','78b214d5-23d4-4fb8-a498-db2efcfd7350',1944,'日军占领南宁后','日军占领南宁后，出任伪南宁县县长，为日军征粮派款、拉夫修路。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e15b4d45e88a41d4b10e368e2531abbd','92271ae7-b192-4262-a61f-e9b51196d37e',1944,'在兴宁地区组织伪维持会','在兴宁地区组织伪维持会，协助日军控制地方，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aebc1f6f06d6492e94afd448648a42b0','523fa7d1-440a-479c-b17f-bef4d03deac4',1944,'抗战后期投靠日军','抗战后期投靠日军，在广西境内收编土匪、组建伪军，配合日军扫荡抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d280454c569341d38ebb0f4eaac8176f','c978869c-e764-4c7c-8a5f-ed0e32527667',1944,'日军占领南宁期间','日军占领南宁期间，出任伪警察局长，镇压抗日活动，抓捕爱国人士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-894c0581702e4730bb7437da1b88c316','3c067597-0c41-425a-8d4e-ad1693c43570',1944,'协助日军在邕宁及周边地区推行保甲制度','协助日军在邕宁及周边地区推行保甲制度，强征民夫、粮食。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5eb6615f7e234643be8da5a81fa38cf4','226585f5-8590-4a82-884c-73961dffa3d0',1944,'在日军控制下的南宁等地开展亲日宣传','在日军控制下的南宁等地开展亲日宣传，鼓吹“大东亚共荣圈”，为日军侵略辩护。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e37a09ad8e0043a2bbe43159a661aaf8','9e01f847-7384-4fd8-abb4-7844e14160fe',1944,'组织商户为日军筹集物资、资金','组织商户为日军筹集物资、资金，协助日军对南宁经济进行掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4e5506af7bb487098f6606d31764cae','a0e09568-5c48-41ba-99e6-8e9ca9145ea2',1944,'率伪保安队配合日军清乡','率伪保安队配合日军清乡，搜捕抗日游击队员及其家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc0cd908a2994fc5bd5e07c5d04cccfa','14427907-5ca0-416a-8741-2024a6742625',1939,'日军第一次侵占南宁后','日军第一次侵占南宁后，出面组织伪南宁维持会并任会长，后改任伪南宁县县长，为日军征派民夫、物资，维持沦陷区秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2dc1e01e0b6407b84b8a2b8575d2379','edad4c9c-c461-49fe-8af8-4ebd5c3365c7',1939,'协助陈日葵组织伪南宁维持会','协助陈日葵组织伪南宁维持会，参与为日军筹粮、派夫及宣传‘中日亲善’等活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5ced0c067e545cebf6106867742967e','414caf57-6034-4cb1-b44f-c6539241cc74',1939,'日军侵占南宁后曾试图拉拢其出面组织伪政权','日军侵占南宁后曾试图拉拢其出面组织伪政权，其一度与日方接触，后未正式就任，但此事在广西有明确记载。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c212270db33840aea170007b8a5ae30f','94b69461-4ca8-4fa2-a1de-d004ab39e0c0',1940,'日军短暂侵入宾阳期间','日军短暂侵入宾阳期间，当地曾出现维持会组织，为日军提供情报、粮秣，但具体姓名在地方志中记载不全。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0775f3d9b95d469db87eda6fcb68c946','a9edc7ae-c50f-44f1-8bde-c01d0b675d02',1940,'在宾阳沦陷期间协助日军征派民夫、粮食','在宾阳沦陷期间协助日军征派民夫、粮食，维持地方秩序，具体姓名地方志记载模糊。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67ac2ba9f7114e7aadc843f86772f9b4','75066c22-3795-434f-bb7d-a96b55a5488a',1939,'在日军占领南宁期间','在日军占领南宁期间，以商会名义为日军筹款、筹粮，协助日军控制南宁经济。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b689b58dc264648bcb17a4056e53067','b54f62a3-35d7-4f83-b34b-02307df2ad66',1939,'在日军占领期间','在日军占领期间，出面组织伪教育机构，推行奴化教育，宣传‘大东亚共荣圈’。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da6a330616b84f1cbced03e4d1858a49','4d17f01e-c6d8-4cc6-9bd9-e3b69d278026',1944,'抗战后期在广西沦陷区与日伪合作','抗战后期在广西沦陷区与日伪合作，参与伪政权活动，为日军提供情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9de7141331844d1a4dd592d8ab93adc','c0a2a431-b931-4707-806d-c59c8bfafcfd',1944,'在日军第二次侵占广西期间','在日军第二次侵占广西期间，组织伪保安队协助日军维持占领区治安，搜捕抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e353170aa6c844c2b127cc8422a7f3c6','77eedcdb-0937-439b-a88d-e450dee9d12d',1944,'抗战后期广西部分沦陷时','抗战后期广西部分沦陷时，被日军利用名义上参与伪政权维持活动，相关记载多见于广西沦陷区伪组织材料。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ef2ff2492454ba89adc3906c83b8f74','0a8aff13-4857-4ed3-9f5b-f705d831f430',1944,'日军第二次侵占南宁期间','日军第二次侵占南宁期间，参与伪政权与维持会活动，协助日军推行殖民统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf622ffad84c461fbd12ac87474bdbd5','8b714474-6758-4af5-9da6-67819c87b9fb',1944,'南宁沦陷期间出面组织维持会','南宁沦陷期间出面组织维持会，为日军筹粮、派夫、维持治安，协助日军控制南宁城区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5df3b0881d564483b4fd755a5155c043','24ab8a44-02b6-41bc-8d25-3752ffe4bec9',1944,'广西沦陷期间','广西沦陷期间，日伪在南宁、武鸣等地推行奴化教育，雷沛鸿被列名于相关伪教育组织材料中。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-466ad969f1234a49b80603bebc895c79','69fa5ba6-484b-4ba3-be92-796bb04f3db9',1940,'桂系人物','桂系人物，抗战期间在安徽与日伪有暗中联系，其活动范围不直接覆盖南宁武鸣，但属广西籍相关汉奸记载。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86c614ac20684da89907cca49275d5cb','65e9f9e3-8d45-4a3e-9b4f-ae2172469774',1944,'武鸣沦陷期间组织维持会','武鸣沦陷期间组织维持会，为日军征发民夫、粮食，协助日军镇压地方抗日力量。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11d6f672b7ea4d87b6040cb2007775cc','91a11791-3fef-4215-a54a-8587fc0a1990',1944,'投靠日军','投靠日军，率伪保安队配合日军扫荡武鸣周边乡村，搜捕抗日人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
