INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c3c260f1b974021896491a07b5a1c97','d1d7358b-1780-4312-aafe-bd5aa0ea7795',1944,'日军占领南宁后','日军占领南宁后，出面组织伪商会，为日军筹款筹粮，协助日军控制南宁经济。','危害等级C（丙级，基层头目）','hanjian');
