INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21a661c7aef649b1b473475878c99faf','a7338584-7760-4b58-aa14-f7c547181d5f',1944,'邕宁沦陷期间','邕宁沦陷期间，黄德胜协助日军建立伪政权，负责征发民夫、收集情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09f5de084ec449a6a8268e5b623fabdf','6b106979-c6e4-447e-b9a4-0aa178795434',1944,'在日军占领下','在日军占领下，梁振声主持伪教育会，推行奴化教育，篡改教材，毒害青年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31cf1e94405943ef9f01b177267a3918','27883368-dbfa-41bc-afd0-1497a9ff0bea',1939,'日军侵占南宁期间任伪南宁维持会副会长','日军侵占南宁期间任伪南宁维持会副会长，协助田次廉组织伪政权，动员商户开门营业、为日军提供物资和劳务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac6399c9c7a348859f079671cd21cd0c','7a3643a0-c497-453f-bf03-3f982217b7c1',1939,'在日军占领南宁期间出任伪警察局局长','在日军占领南宁期间出任伪警察局局长，统辖伪警察协助日军搜捕抗日人士、维持占领区治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-40503287dc7a42f0a90a5fb638e50884','62c100bd-be8b-45f5-b0d1-e8376d1b9e55',1939,'日军侵占广西南部期间','日军侵占广西南部期间，在南宁一带参与组织伪广西维持会并任会长，为日军推行殖民统治、征发民夫物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3786bf2148f2467eb3d6963f389fbb05','bab45f28-c9d7-43e8-9a96-2ba42e2eb1bd',1939,'日军占领南宁期间','日军占领南宁期间，以商会会长身份出面为日军摊派款项、物资，协助维持占领区经济秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae711e72482f462db44fd21b3dd638df','d274f79c-6ca6-4074-9719-d5d99e97a0ab',1939,'据部分地方史料记载','据部分地方史料记载，其在日军侵占南宁期间与伪政权合作，参与推行奴化教育宣传','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f995e16826d54cd3bebca190ab48285d','d274f79c-6ca6-4074-9719-d5d99e97a0ab',1939,'此说存在争议','此说存在争议，需谨慎对待。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2113842106114e3f8b93e9d9ca485f78','0e31330e-dc9b-48c2-9d50-92bc29da95f6',1944,'有史料称其在日军第二次侵桂期间一度与日方接触、参与维持地方秩序','有史料称其在日军第二次侵桂期间一度与日方接触、参与维持地方秩序，但此说争议较大，主流记载其仍属桂系抗日阵营，需谨慎对待。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb934892f2ec4fda913bac56bc10acb9','63cc8838-aa87-4e1a-9ee5-758cb02b53b8',1944,'部分地方史料提及其在桂林沦陷期间参与维持会活动','部分地方史料提及其在桂林沦陷期间参与维持会活动，但此说缺乏确证，需谨慎对待。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f462b46299743b0b57050644499cfed','e1784277-04c3-4f66-8abb-a98dc5d47cac',1939,'有说法称其在日军侵占两广期间与伪政权有联系','有说法称其在日军侵占两广期间与伪政权有联系，但主流记载其坚持抗日立场，此说不可靠。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06aa6a39af4341ae99ac664792720516','ec048a46-d0d6-4d9a-bc13-157f7f0fb442',1938,'在广州组织伪维持会','在广州组织伪维持会，其伪政权活动范围与广西东南部邻近，对南宁一带伪政权组织有间接影响。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0cd4cad1a3154d569901d1c9e18c2a89','3139d0e2-3fa4-420c-84bc-f5f508949789',1937,'抗战后期桂林沦陷后','抗战后期桂林沦陷后，日军曾试图拉拢其出面组织伪政权，黄旭初虽未公开投敌，但曾与日方进行过接触和谈判，在广西伪政权筹建过程中态度暧昧。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01e7f4b80ef64209a4339d70d7e8954c','3139d0e2-3fa4-420c-84bc-f5f508949789',1937,'抗战期间长期主政广西','抗战期间长期主政广西，与日方有秘密接触，但未公开投敌，战后被列为附逆嫌疑人物。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e8e967054b9421889abc728b390689a','2bff173a-a261-469c-b7dc-b58fb1173d98',1944,'1944年11月南宁沦陷后','1944年11月南宁沦陷后，出面组织南宁维持会，协助日军维持地方秩序、征调民夫和物资，为日军占领南宁提供后勤支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ec079c1fb28451ca7a14008f01cb67d','edd28b23-2675-4032-a695-089292ca0fee',1944,'日军占领广西期间','日军占领广西期间，曾将其列入伪政权拟任名单，雷沛鸿虽未实际就任，但在日方拉拢过程中未明确拒绝，态度动摇。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-256119d836b04ac3921d3d526b63cec9','f779249f-51b8-49fe-badc-a3fb2f2fe76a',1938,'桂系将领','桂系将领，抗战期间在安徽任职，与日伪方面有秘密接触和物资交换，其部下在皖东地区与伪军合作，对广西籍官兵有影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6589eed7af814f4aacde536a92cdc5aa','d572fae4-b202-48f1-ad95-0eded9dced8f',1944,'南宁沦陷后出任伪警察局长','南宁沦陷后出任伪警察局长，协助日军搜捕抗日分子、镇压民众反抗，维持日占区治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b7704e716ad40cebbf85633a68cc7b6','43789caa-82e4-4c58-b780-d22c189ed725',1944,'1944年日军侵入马山地区后','1944年日军侵入马山地区后，出面组织维持会，为日军征粮征夫，协助日军对马山周边乡村进行扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7c4e5209087478a9be0fdfeb5546efc','eae4b88d-e6bd-48b6-9f37-cbb53b65d49c',1944,'武鸣沦陷后任伪维持会副会长','武鸣沦陷后任伪维持会副会长，协助日军管理武鸣及周边地区，包括马山部分区域，为日军提供情报和物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67ea20b6cf25404cb95eff6f7dc344a9','f4cbdc16-4e8a-4e0b-8eaa-cca02018e938',1944,'南宁沦陷后组建伪保安队','南宁沦陷后组建伪保安队，配合日军清乡，在马山、武鸣一带参与对抗日游击队的围剿。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-941664ed678c47cc95c637e8553821d1','34f1c350-3dab-4f93-a3f6-b6ab2a71a7e5',1944,'日军占领广西期间','日军占领广西期间，出面组织伪绥靖机构，拉拢地方士绅投敌，在马山、都安一带活动，为日军筹粮筹款。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61df70d99b1f490ebe53743e2213812a','299a74de-d292-4a86-a104-45df8ef7d1ef',1944,'南宁沦陷后出任伪商会会长','南宁沦陷后出任伪商会会长，协助日军控制南宁经济、征调物资，并动员商界与日方合作。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-949faea2b8a849718f41f6aa6697bf2a','54a5a86e-1d36-4f51-a9ff-41f729ff4520',1939,'日军侵占南宁、崇左一带时','日军侵占南宁、崇左一带时，日方曾试图拉拢其出面组织伪政权，李品仙未公开附逆，但日伪档案中列为其拟任伪维持会会长人选。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38e4e810bfb84623b18aa1800e885079','6d8e0278-5a54-46bc-9a3c-a4150a1bd478',1939,'在日军占领南宁期间出任伪警察局长','在日军占领南宁期间出任伪警察局长，协助日军搜捕抗日人士、镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a099638f2f04af89267028cfb891777','01e760f6-eb7a-4a0a-a647-0b2ff448c25e',1940,'日军侵占崇善（今崇左市江州区）期间','日军侵占崇善（今崇左市江州区）期间，组织伪维持会，为日军征调民夫、粮食，协助推行伪化统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d1efb01b7ef64ffd99722e2ffac1def1','d9b436d0-eff6-4a63-a277-e36a26cee9ac',1940,'日军侵占龙州期间','日军侵占龙州期间，出面组织伪维持会，协助日军维持占领秩序、征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e12cd5e016c94d6d9f8784e5df340133','0b48cd75-bc8f-47a3-86b3-a0477961ab88',1940,'在日军侵占绥渌（今扶绥县）期间','在日军侵占绥渌（今扶绥县）期间，组织伪维持会，为日军筹粮、派夫，协助伪化地方。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-278e03e20aaf4267aaaba599ab2cd0a9','df6df055-0e4b-4dc9-9cc4-62468deccf2c',1944,'日军第二次侵桂期间','日军第二次侵桂期间，在伪广西省政权中任职，协助日军维持占领区治安，参与搜捕抗日分子。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed1db7375bf344e1afbb8e5a748e24e7','ca12e92f-a943-4ab8-bb40-5e102f86f924',1944,'日军第二次侵占桂林期间','日军第二次侵占桂林期间，组织伪桂林维持会，协助日军征粮、拉夫，维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f6101d7bb264dc784e4c2fb935d0ea7','35220ab5-5aac-4de7-8555-4947040cd3ea',1944,'日军侵占柳州期间','日军侵占柳州期间，出面组织伪维持会，协助日军征发物资、维持治安。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc95cc9c79ab408d85eb0afe8c57ebb9','3c704d27-6d7d-459c-879b-cb5682fa8ab4',1944,'日军侵占梧州期间','日军侵占梧州期间，组织伪维持会，协助日军推行伪化统治、征调民力。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e78c681aaa914e0a9f142996e75098de','82294ff7-25ee-4aad-882d-69ee41e771e8',1944,'日军第二次侵占南宁期间','日军第二次侵占南宁期间，再次组织伪维持会，协助日军征粮、拉夫、搜捕抗日人士。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28a6b09d6f0749afa7020d44bb60750e','5bb576ee-e4e4-4f44-afb1-6bd5cc1940b6',1944,'日军第二次侵桂时','日军第二次侵桂时，日方曾试图拉拢其出任伪教育厅长，雷沛鸿未附逆，但日伪档案中列为其拟任人选。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee6afbdf506149b5a1a487305c7f53b9','99ecd6f5-b35f-46f4-b3de-1a970cc80ebb',1944,'日军侵占广西期间','日军侵占广西期间，日方曾试图拉拢其出面组织伪省政府，黄旭初未附逆，但日伪档案中列为其拟任伪省主席人选。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17df5324a3424b52b58584ec9f361e40','4fc36f59-6db3-4a70-8bf7-387ebc9d4e73',1940,'在日军侵占桂南、粤西期间','在日军侵占桂南、粤西期间，组织伪维持会，活动范围涉及崇左、南宁一带，协助日军征粮、拉夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b465a7bdf3049f4b93f8930694b38ad','98789aa5-c6c4-4eab-9037-b75cb41767e8',1939,'日军侵占桂南期间','日军侵占桂南期间，其伪政权势力延伸至崇左、南宁一带，协助日军推行伪化统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccd43fb6c02644c385bdd4338863dbe6','3e701dd0-ea24-4852-a9bb-7f04b84c6a0b',1939,'原为桂系将领','原为桂系将领，抗战期间投靠汪伪政权，任伪广西省政府主席，协助日军在广西各地推行伪化统治，其势力范围覆盖崇左、龙州一带，组织伪军配合日军扫荡抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c3a11592f91438a92c69cf07680788f','39092569-396a-44ec-aa6f-bd3a9c6ce88d',1940,'投靠日伪后负责广西伪警察系统','投靠日伪后负责广西伪警察系统，在崇左、龙州等地建立伪警察所和保甲联防，镇压抗日群众，搜捕抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01c27ae9c4044b75a35291450b8ec1f2','c9a56422-3e15-4fcb-baee-7c6a362b3bf6',1940,'龙州本地士绅','龙州本地士绅，日军侵占龙州后出面组织维持会，为日军征粮征夫，协助建立伪基层政权，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ff7cb01ef7349abaca31167eeccf9db','29041df3-1077-4bb6-a1ef-62dda346e6a9',1940,'汪伪政权委任的崇左县伪县长','汪伪政权委任的崇左县伪县长，在崇左及龙州周边推行伪化教育，组织伪保安队配合日军清乡，搜刮民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e0447c58d7f496b8b237222aa914fa0','d9e351ea-81cc-4b12-af21-919e6a72534c',1941,'投日后任伪广西绥靖公署督办','投日后任伪广西绥靖公署督办，统辖广西伪军，在崇左、龙州地区部署伪军据点，配合日军对抗日根据地进行扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29efa0e903e148c1a52f22cf6e63744f','77086655-f92d-4020-b147-c0c5797f9a11',1941,'在龙州担任伪警察局长期间','在龙州担任伪警察局长期间，建立特务网络，逮捕抗日人员，强征劳工为日军修筑工事，民愤极大。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d79bfa3f3564e09b4093e77edde0d6c','3b955cb3-acfa-4a49-8180-f1de57065d4b',1940,'龙州本地人','龙州本地人，任伪保甲长期间为日军收集情报，带领日伪军搜捕抗日游击队员，强征粮食和壮丁。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00810ce272504da88ad006da17ca768b','c4c3bfba-5736-41b8-a49a-9ca880f955d8',1940,'负责汪伪在广西的宣传工作','负责汪伪在广西的宣传工作，在崇左、龙州等地发行伪报刊，宣扬“大东亚共荣”，进行奴化教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e841109e0b347f284e5e1c9f4dde71a','f0db795a-cfc0-42f0-bcd2-cf4ce66dc293',1938,'汪精卫之妻','汪精卫之妻，随汪投敌，参与汪伪政权建立，曾任汪伪国民党中央监察委员会常务委员、广东省政务长等职，为汪伪政权核心人物之一。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1c7a74e9343489993edcd9efe11e806','f0db795a-cfc0-42f0-bcd2-cf4ce66dc293',1938,'汪精卫之妻','汪精卫之妻，随汪投敌，参与汪伪政权核心决策，曾到广东等地活动，广西为其夫汪精卫早年活动区域，桂林亦有其汪伪势力渗透背景。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6c04057751f4cd4a229325a784816f3','f0db795a-cfc0-42f0-bcd2-cf4ce66dc293',1938,'汪精卫之妻','汪精卫之妻，随汪投敌，参与汪伪政权核心决策，曾到广西活动，为汪伪在华南及广西一带的渗透提供支持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13e53cacb4d741cab8906550f95619f8','a095a271-b334-406c-a225-21dee67d327d',1938,'广东人','广东人，汪伪政权宣传系统负责人，主办《南华日报》等，为汪伪政权重要骨干，后任伪安徽省长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-823124d9ad8045c5bf444d7d7d133f1b','1ade347f-bc47-42bc-a43f-85edad116924',1938,'原国民党要员','原国民党要员，随汪精卫投敌，历任汪伪政权要职，汪精卫死后任伪国民政府代主席，为汪伪政权头号人物之一。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03d3b29389c44f38978496372a6f3a07','581175c1-a062-4140-9059-2313846592e9',1938,'原国民党要员','原国民党要员，汪伪政权核心人物，把持财政、警政大权，后任伪上海市长，抗战末期与重庆方面暗中联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f408c85c49f54a958d023ef6a1bfe97f','c66a8aef-d752-4d24-aac8-e393c0d9e781',1938,'汪伪特务头子','汪伪特务头子，组建汪伪特工总部（极司菲尔路76号），残酷镇压抗日力量，后任伪江苏省长，1943年被毒杀。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd7b09058a7448168151c224bfd0a219','c66a8aef-d752-4d24-aac8-e393c0d9e781',1938,'浙江遂昌人','浙江遂昌人，汪伪特务头子，其特工网络覆盖华中包括江西部分地区，迫害抗日人士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ca206a75ed5410684ad9ac5e1b300be','c66a8aef-d752-4d24-aac8-e393c0d9e781',1938,'浙江遂昌人','浙江遂昌人，汪伪特务头子，其特工网络覆盖华中沦陷区包括湖南部分区域，与湖南伪政权特务机构有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1d1c47b4e7b4047bbb00945e3768a34','c66a8aef-d752-4d24-aac8-e393c0d9e781',1938,'浙江遂昌人','浙江遂昌人，汪伪特务头目，虽非湖南籍，但其特务活动范围涉及华中地区，与湘潭无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-515828d481d84dfb91a48c0dc275f7e1','c66a8aef-d752-4d24-aac8-e393c0d9e781',1938,'浙江人','浙江人，汪伪特务头子，其特工网络延伸至湖南沦陷区，1943年被日军毒杀。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1acf48610f214fdea1b0b366371dd962','c66a8aef-d752-4d24-aac8-e393c0d9e781',1938,'汪伪特务头子','汪伪特务头子，虽非湖南籍，但其特工网络延伸至湖南沦陷区，迫害抗日人士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-768db444a93340ecb9a9d496fa3a4b06','c66a8aef-d752-4d24-aac8-e393c0d9e781',1938,'虽为浙江籍','虽为浙江籍，但作为汪伪特务头目，其特工网络延伸至湖南沦陷区，参与镇压抗日力量、收编伪军和维持会。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ee1b7487ae343f2b3888e8f8405b0da','0ab52f23-cd9e-4a23-807e-a5e7f1378915',1938,'组织伪维新政府','组织伪维新政府，任行政院长，后并入汪伪政权任监察院长，为华中地区重要汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb1ac95ff38b457da76a54515e2c5868','1b2a98dc-ab91-49cf-b7c7-5ffd0315a3d8',1937,'华北重要汉奸','华北重要汉奸，历任伪临时政府、伪华北政务委员会要职，推行奴化教育。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc61726434884d61923adb69567f05f0','5e078095-f71f-4a0b-8fc7-211083267e50',1938,'汪精卫连襟','汪精卫连襟，汪伪政权重要成员，曾任伪外交部长、伪广东省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca53a9d1748a444b82e17839baaa64b4','f826fe2a-f8a8-4948-bb41-c95f50048923',1938,'参与汪精卫投敌谈判','参与汪精卫投敌谈判，汪伪政权重要成员，历任伪工商部长、伪浙江省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29e22e6858b141ddb546cf1b25817bc1','e9ae9cc9-69d9-4e7a-a79c-8d713bb44f98',1937,'上海青帮头目','上海青帮头目，投敌后任伪浙江省长，组织伪军，1940年被刺身亡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-480110ef2de74d07bbff3adbf75573e9','e9ae9cc9-69d9-4e7a-a79c-8d713bb44f98',1937,'浙江慈溪人','浙江慈溪人，上海青帮头目，抗战期间投靠日军，组织伪军，后任伪浙江省长，协助日军镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a642ae3446c40b085775ec7f542c397','e9ae9cc9-69d9-4e7a-a79c-8d713bb44f98',1937,'上海青帮头目','上海青帮头目，投靠日伪，其势力未直接进入万州。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-494231c74133409fbd6f9262ba72db60','2363f177-1839-4293-a648-985b85eec4db',1938,'上海青帮头目','上海青帮头目，投靠日伪，为汪伪特工总部顾问，1939年被刺身亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3021783a641a4194ada04adea04362ec','ff9c578d-24b1-4966-872a-6f5821086b7e',1937,'上海青帮头目','上海青帮头目，组织伪黄道会等汉奸组织，进行暗杀、破坏活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e39b2c960b5462382589095b5d233b4','a6ea10bc-8b9f-4317-ad7e-cf2d98d6c0bb',1938,'汪伪政权文宣骨干','汪伪政权文宣骨干，曾任伪宣传部次长，为汪伪政权进行舆论宣传。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79af351439584346a8983c4dcbdbe100','a6ea10bc-8b9f-4317-ad7e-cf2d98d6c0bb',1938,'虽非九江本地人','虽非九江本地人，但在汪伪政权中负责文化宣传，其亲日言论影响江西沦陷区，属全国性文化汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33a12dacf51641289bad728de83fd1f5','b5ca770b-3f9c-4b70-b2d4-79f36f58a9bd',1938,'汪伪政权新闻宣传骨干','汪伪政权新闻宣传骨干，主办伪报，进行亲日宣传。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae3ca3e8157d40e7aa2aeba35e77c211','45fb4a31-e276-4fbc-9663-a2edb77b1cf0',1938,'汪伪政权重要成员','汪伪政权重要成员，历任伪内政部长、伪江苏省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f59a2d0af5945c4bb5a269950085f77','75853bbd-2c8c-4976-a987-8937ae20d177',1938,'组织伪绥靖军','组织伪绥靖军，任总司令，后任伪江苏省长，为华中伪军重要头目。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-647d28eaeb0f419192c254849ae51aab','199e048f-5cd0-4974-aeb0-cc6b61f214f4',1938,'原西北军将领','原西北军将领，投敌后组织伪军，任伪和平救国军总司令、伪河南省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6064ac3a89cf4aa09807324f933f009f','0dd88a3f-e5c2-4582-969b-7905c71403ea',1942,'原西北军将领','原西北军将领，投敌后任伪和平救国军总司令、伪河北省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5e381e77f064e86b63a2f4a57561719','6bf4d21b-92eb-4c39-9d95-b1de2a751bc1',1943,'原国民党将领','原国民党将领，被俘后投敌，任伪和平救国军总司令、伪河北省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06b03137acae4aff9146c18ecd42e2c6','6a84ef88-07f4-4a41-9fc4-212364882c84',1941,'原国民党将领','原国民党将领，投敌后任伪淮海省省长、伪和平救国军总司令等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-365fb3cc17a3484da8b9447fe370261f','6a84ef88-07f4-4a41-9fc4-212364882c84',1941,'原为国民党将领','原为国民党将领，1943年投敌，任伪淮海省省长，驻徐州，统治新沂地区，推行日伪“清乡”政策，残害抗日军民，1945年抗战胜利后一度被收编，后再次叛变，终被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-209f8e7f70284d519d5e7506664e5212','6a84ef88-07f4-4a41-9fc4-212364882c84',1941,'原为国民党将领','原为国民党将领，1941年投敌，任伪淮海省（驻淮安）省长，组建伪军，配合日军清乡扫荡，残害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
