INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-194afbebdaa347d2aae45d7fb35f2eae','1ab48e32-4f17-445a-98ed-8ea7d6e7c7c3',1938,'广西陆川人','广西陆川人，汪伪政权宣传系统核心人物，主办《南华日报》等鼓吹投降，属广西籍著名汉奸。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a97484ad344e4e7dbd0f5aa2c82d6a67','1ab48e32-4f17-445a-98ed-8ea7d6e7c7c3',1938,'广东籍汪伪要员','广东籍汪伪要员，长期主持汪伪宣传，属于华南籍附逆者，但与广西柳州无直接任职记载。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9497fdd4accb45a0bda34e7affd96f86','1ab48e32-4f17-445a-98ed-8ea7d6e7c7c3',1938,'汪伪政权宣传系统核心人物','汪伪政权宣传系统核心人物，早年曾在广西活动，后随汪精卫投敌，负责伪政权舆论宣传，属与广西有历史关联的汪伪高层汉奸。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f748a4f83b2e4a2bb6d0c8c2c5e4ea69','b443edaf-d7e8-4038-a349-2283131b94e1',1938,'汪伪政权二号人物','汪伪政权二号人物，虽非广西籍，但其伪政权势力曾向华南包括广西渗透，抗战末期在南京等地主持伪政。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78b9071cae2c4560a459d4ce859116a8','9abb9bf5-97bd-423b-ad23-33d5e1ed0a26',1940,'在汪伪广东省政权中任职','在汪伪广东省政权中任职，参与华南沦陷区伪化统治，活动范围与广西东南部邻近。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c597ecb3e7a41aebf3d85cf03ed79c6','e21dee3f-7cd8-4fe7-a034-e02c15c988de',1944,'抗战末期日军侵入广西柳州期间','抗战末期日军侵入广西柳州期间，参与组织地方维持会，协助日军征粮、拉夫、维持治安，属柳州地方附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bfba988af9ae465d9c40f2418b9c453c','a9363009-b52d-467e-b925-67a604debea3',1944,'日军占领柳州期间','日军占领柳州期间，充任伪保甲长，为日军派捐、指认抗日人员，属柳州基层汉奸。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7996aea02d842579deff7f8911a7c7e','ab0ff1be-0a46-4e10-91f9-e063b47ecce9',1944,'日军侵扰桂北三江地区时','日军侵扰桂北三江地区时，出面组织维持会，为日军带路、筹粮，属三江地方附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0bf5adbe259f4675a853ffe2756840a1','82e06af6-90b3-4cbf-9150-b65a7f1d497a',1944,'柳州沦陷期间充任伪警察便衣','柳州沦陷期间充任伪警察便衣，协助日军搜捕抗日分子和地下工作者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98d6fb1a96074900b062dde74a4e778a','30c71b18-c483-40b4-ae70-67eb8193c27c',1938,'虽主要活动于广东','虽主要活动于广东，但其伪维持会网络曾向桂东、桂南渗透，与广西邻近地区伪化有关。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
