INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f98b98957e6947e99986509a87f3771e','3a4b46e8-8587-4f22-b8ed-72e326d41282',1938,'汪精卫之妻','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广西活动并为汪伪政权张目，属于广西籍或与广西有直接关联的著名附逆人物。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd6ade2de4a843d08d40c1024c1b4c1c','3a4b46e8-8587-4f22-b8ed-72e326d41282',1938,'汪精卫之妻','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广西活动并为汪伪政权张目，是汪伪集团重要成员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0491a77a0274522b08fa36cecbff404','f72e63e9-2fea-412e-93fb-7e0b20df2c3a',1938,'广西陆川人','广西陆川人，汪伪政权宣传系统核心人物，主办《南华日报》等，为汪伪投降路线制造舆论，是广西籍汉奸中职务较高者。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb6458c99136422e87a37e034addf053','f72e63e9-2fea-412e-93fb-7e0b20df2c3a',1938,'广东人','广东人，汪伪宣传系统头目，早年曾在广西活动，后追随汪精卫叛国投敌，负责汪伪舆论宣传。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6ac4bbfdc7d42668c3cf636bbe8d0ac','ddb256cd-3fe2-47a7-80ab-ae45e8472712',1939,'广东籍伪军头目','广东籍伪军头目，活动于粤桂边区，其伪军势力曾渗入广西东南部，与柳州方向伪政权有联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d12ef832d3054f10ba7000474ec89881','c69baeeb-36b0-4cb3-bf75-1ce4640d41d4',1937,'绥远地区著名汉奸','绥远地区著名汉奸，虽主要活动于华北，但其伪军系统与广西无直接关联，仅作为扩展检索中的排除项。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32bf6cf18ff4429cab67c8d6d99ff1aa','c69baeeb-36b0-4cb3-bf75-1ce4640d41d4',1937,'绥远籍汉奸','绥远籍汉奸，虽主要活动于华北，但其伪蒙疆政权与广西、桂林无直接关联，仅作为全国汉奸名录参考。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4745cfd755bd452ea240938e903746ea','165c5903-f48e-44d8-b8a0-ec4d79e115c8',1938,'广东伪政权头目之一','广东伪政权头目之一，其维持会体系与广西梧州、柳州等地伪维持会有横向联系，间接影响柳州地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4728e75c6a99404cb5e02e699b68e2b5','e0ca1501-66e4-4060-9ee1-38534f1323e2',1940,'陈璧君之弟','陈璧君之弟，汪伪广东省政府主席，其伪政权与广西伪政权有行政往来，对柳州地区伪政权有间接管辖关系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2bad10e419a445eaca6d863bf172dcf','d948d912-5918-47c0-b032-b75ca54d7a0d',1944,'据部分地方文史资料提','据部分地方文史资料提及，1944年日军入侵柳州期间，有地方士绅组织伪维持会，张君嵩可能为其中之一，但可靠记载有限。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55882fb7717747a4b0b74c4994e25edc','31e55298-0fc6-483c-be62-2812a6a32980',1931,'桂系核心人物','桂系核心人物，抗战期间坚持抗日，未任伪职，此处仅作排除说明，非汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-99812e49712d441487713b39cdb02179','79499492-b6b2-4374-815d-4a1fa76d139b',1938,'日军侵占广州后','日军侵占广州后，曾试图拉拢其出面组织伪政权，但陈炯明于1933年已去世，此说系误传，实际未参与。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-265822b755154e9e941178964159b957','79499492-b6b2-4374-815d-4a1fa76d139b',1938,'日军侵占广州后','日军侵占广州后，曾试图拉拢其出面组织伪政权，但陈炯明于1938年病逝，未实际附逆。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6fec025f85f5451b87cdeee74db52704','79499492-b6b2-4374-815d-4a1fa76d139b',1938,'抗战初期日军曾试图拉拢其出面组织广西伪政权','抗战初期日军曾试图拉拢其出面组织广西伪政权，但其未实际就任，相关记载存疑，仅作为广西伪政权筹组背景提及。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-acbd8484495f4064b208b63d5133e726','79499492-b6b2-4374-815d-4a1fa76d139b',1938,'抗战初期日军曾试图拉拢其出面组织广西伪政权','抗战初期日军曾试图拉拢其出面组织广西伪政权，但其未实际就任，相关记载存疑。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aef7a19c8b2d42f9bd24bbe68373d44b','79499492-b6b2-4374-815d-4a1fa76d139b',1938,'日军侵占广州后','日军侵占广州后，曾试图拉拢陈炯明出任伪广西省维持会会长，但陈炯明未就任，此事与广西伪政权筹建有关。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
