INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54544482b3bc48ef84bf4d1038966c54','9655e335-ac3b-435d-bf08-5be04da827f5',1944,'在伪广西省政府中主管财政','在伪广西省政府中主管财政，为日军筹款、征粮，推行伪币与物资统制，支持日伪统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8accd14f94084c32910734fa7a838f14','9655e335-ac3b-435d-bf08-5be04da827f5',1944,'协助日军在广西占领区征收赋税','协助日军在广西占领区征收赋税，为伪政权筹措经费，涉及百色地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f5edb3271074b5ba3d535734c46249c','40721498-977d-42be-9fea-fa730c0e3f7a',1944,'有资料称日军曾试图拉拢其组织伪政权','有资料称日军曾试图拉拢其组织伪政权，但其最终未公开附逆','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10dce9f1bbb142bbaab3b0f42b7dfbd5','40721498-977d-42be-9fea-fa730c0e3f7a',1944,'此条仅作争议性关联记录','此条仅作争议性关联记录，需谨慎使用。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0083a119729474fa0d5eb38e6223feb','f2604d18-5994-4b2e-9c46-6e6a1bcfa2a5',1940,'虽非桂林本地','虽非桂林本地，但作为广西籍（或与广西有政治关联）的汪伪政权核心人物，其附逆行为对广西沦陷区伪政权有示范与统辖影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ef38c77cb994f7f9f354900e565696a','f2604d18-5994-4b2e-9c46-6e6a1bcfa2a5',1940,'投靠日本','投靠日本，参与汪伪政权，配合日军在华东及华北包括陕西周边地区进行殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f94ebd24f290428dacad322059eb04b5','9448b38a-a0f9-443c-945c-6456b3f595be',1944,'桂林沦陷后参与伪广西省军事组织','桂林沦陷后参与伪广西省军事组织，统率伪保安部队配合日军扫荡抗日游击队、维护占领区治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3534b851ad14a8f8c708409d09a1d47','e7a02d39-f6f2-4dbb-90eb-34d816994dbe',1944,'有传闻称日军曾诱其出任伪职','有传闻称日军曾诱其出任伪职，但黄旭初实际未附逆','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-797e230dc8b44f3cb00a2df36966130a','e7a02d39-f6f2-4dbb-90eb-34d816994dbe',1944,'此条为争议性记录','此条为争议性记录，需进一步考证。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7da5873d60ef489e8e3d1fc8abc39610','90ae84c7-295c-43b1-bd15-faaa1a7a127c',1944,'协助张君度组织维持会','协助张君度组织维持会，负责联络日军与地方士绅，征调民力物资，推行奴化宣传。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0826959666804f14808278a6f5ccc1dd','90ae84c7-295c-43b1-bd15-faaa1a7a127c',1944,'桂林沦陷期间任维持会副会长','桂林沦陷期间任维持会副会长，协助会长张君度处理伪务，为日军征集粮食和民夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d97e6674768f4ae394c179386a988bbc','46e4bbd6-80fd-4e87-8fd0-1a63d6e8e7e8',1944,'在桂林沦陷期间担任伪警察局长','在桂林沦陷期间担任伪警察局长，指挥伪警察配合日军搜查、逮捕抗日分子，实施保甲连坐。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0a9f151d9634067a1c3d1e73c726c67','71d6e441-f6fa-4b56-9b70-8b89648a52c4',1944,'在伪广西省政府中主管教育','在伪广西省政府中主管教育，推行日语教学与奴化教育，篡改历史教材，为日军殖民统治服务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1bb6efecf28f49d6a7a0c2fe0d93936b','e24da3da-b2ae-4477-beeb-7a6ad5b65ba6',1944,'组织商会为日军筹款、摊派物资','组织商会为日军筹款、摊派物资，协助日军实施经济统制，压迫商户与民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bddf94c8dd3484b8142881007a32d09','d0178aa4-a56e-40ae-b720-75fb0ffdd8c9',1944,'负责伪政权宣传','负责伪政权宣传，散布“大东亚共荣”言论，诋毁抗日力量，配合日军进行思想控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f186742c7f7e4126b91e5b51b2ed71d1','310962a8-fcce-4471-a270-74179ad8631f',1944,'有资料提及日军曾试图拉拢其组织伪绥靖机构','有资料提及日军曾试图拉拢其组织伪绥靖机构，但张发奎实际坚持抗日','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3bffe93f49164cb388a3311ad2cf74af','310962a8-fcce-4471-a270-74179ad8631f',1944,'此条为争议性记录','此条为争议性记录，需谨慎对待。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8654e9762b174d1a8f040037a5d20aa5','8a749112-bb0d-46c4-b611-47368336ce02',1944,'传闻日军曾诱其出任伪建设厅职务','传闻日军曾诱其出任伪建设厅职务，但黄绍竑未公开附逆','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2690b28b809444199e275360ce1213c','8a749112-bb0d-46c4-b611-47368336ce02',1944,'此条为争议性记录','此条为争议性记录，需进一步考证。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f6c259096e1f480c8dda472a938e8552','9902582f-3d02-4927-9ea2-a93c2807f45e',1938,'汪精卫之妻','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广西活动并为汪伪政权张目，是汪伪集团重要成员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28ffdce860964a09a65c5abd0ea236ee','09abfe01-4e40-4101-a355-2a6c7cdf9c97',1939,'抗战时期在广西沦陷区附近参与伪政权维持活动','抗战时期在广西沦陷区附近参与伪政权维持活动，协助日军推行殖民统治，具体任职于桂南一带伪组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82b7260c92ec4124b5f36191d755d148','e88ae2af-3b43-4086-bfe4-022eb387b4c1',1938,'抗战期间投敌','抗战期间投敌，曾任伪军职务，活动于华南包括广西周边地区，配合日军对抗日力量进行镇压。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64bac1298ed74cdcb200df041c8ccc10','5238c28a-c8af-4d1a-b27b-a6934173a3be',1937,'长期在华北、西北投敌','长期在华北、西北投敌，虽主要活动不在广西，但其伪军系统与华南伪政权有联系，属于抗战时期有明确记载的汉奸。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ab4b8c1e9814a8a929eda85e2457afa','ab4d1725-f28d-4420-8196-017cdd8b07fc',1938,'汪伪政权核心人物','汪伪政权核心人物，参与对日投降与伪政权建设，其伪政权体系覆盖包括广西在内的华南沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-196f635abf8a4009859f3b4eb5502d26','629b9b10-cde3-4ada-a983-f565810d17db',1938,'汪伪政权核心成员','汪伪政权核心成员，负责伪财政与警政，其伪政权体系对广西等沦陷区有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e0f68f998434d938de1a566ca564c1c','ba9d9472-f410-42b9-9b6b-c930b64374f6',1938,'汪伪政权宣传系统负责人','汪伪政权宣传系统负责人，推行亲日卖国宣传，其宣传体系覆盖华南包括广西。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c110337de864e9cbe2fe5a54beff7d0','aefd12dc-5a26-43b5-94b5-8f290b4f64c0',1938,'汪伪政权重要成员','汪伪政权重要成员，参与对日投降谈判与伪政权建设，属于有明确记载的汉奸。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ee4747c9db543c98871b72c2d97f286','bc6d61c6-cf43-4fcb-bcb5-c3732a38d964',1938,'汪伪特工组织头目之一','汪伪特工组织头目之一，参与镇压抗日活动，属于有明确记载的汉奸。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da1ae8da991d44e3a454a266a1662f0a','bc6d61c6-cf43-4fcb-bcb5-c3732a38d964',1938,'汪伪特务头子','汪伪特务头子，其特务活动对广西有渗透，但直接关联较少。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fbeb6070f584d649e58279936c54961','bc6d61c6-cf43-4fcb-bcb5-c3732a38d964',1938,'汪伪特务头目','汪伪特务头目，其特工网络覆盖华中、华南，属全国性汉奸。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4c26c9b1b57476eb1a83749f0918ace','bc6d61c6-cf43-4fcb-bcb5-c3732a38d964',1938,'浙江遂昌人','浙江遂昌人，汪伪特工头目','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1cbd35509db47918d4cd47325a2d962','bc6d61c6-cf43-4fcb-bcb5-c3732a38d964',1938,'与湖南衡阳无直接关联','与湖南衡阳无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-623005353ca941f5986efb65b075c55c','64bd8c89-09cf-4d99-b910-defd9ada7a56',1931,'被日本扶植为伪满洲国元首','被日本扶植为伪满洲国元首，充当日本殖民统治工具，属于抗战时期有明确记载的汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c61bcf3f8a7d463a8dc371aaa960cf29','b0b8ff7f-8f17-4e47-bd6e-926598b75a5e',1938,'公开投敌','公开投敌，建立汪伪政权，是抗战时期最大汉奸头目，其伪政权体系覆盖包括广西在内的华南地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9355d7f198c34f24a0b54b9b36a9901d','24e6e577-a5eb-49eb-8566-b3332bdf44af',1940,'广西籍人','广西籍人，抗战期间投靠汪伪政权，参与在华南及广西边境的伪军招抚与联络活动，协助日军对广西进行政治诱降。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a69af2c5cb4f4a71b01b730762db2f79','839c7bfd-8c44-4bd5-a1c4-c67e8cb11054',1944,'广西省政府主席','广西省政府主席，抗战后期在日军入侵广西、桂林沦陷前后，曾出现与日方接触、谋求地方自保的传闻与记载，但未公开投敌，历史评价复杂，常被列入广西沦陷时期附逆嫌疑人物讨论。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cbf285018ece4f2785c3b85ed735e23b','04d915a4-6d12-4564-8acb-b3b97c789d9a',1944,'1944年日军占领桂林后','1944年日军占领桂林后，出面组织桂林维持会，协助日军维持地方秩序、征发物资、推行伪化统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8747ed91d87433281407f9a8fa34ec5','1c0418f9-531e-42a3-acc3-dc7dca105981',1944,'桂林沦陷期间','桂林沦陷期间，参与组建伪警察机构，协助日军搜捕抗日人员、管控户籍与物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-642b0a241ff14b64b7f5e2e05e2a24d9','39df04b1-69a0-42bf-8638-6d17852c1aa7',1944,'桂系重要将领','桂系重要将领，抗战后期在广西沦陷区边缘与日伪方面有接触传闻，但未正式投敌，历史记载存在争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c617c64344a347fc91e6c57af3583855','39df04b1-69a0-42bf-8638-6d17852c1aa7',1944,'抗战后期在广西沦陷区与日伪方面有接触、妥协传闻','抗战后期在广西沦陷区与日伪方面有接触、妥协传闻，部分地方史料将其列入附逆嫌疑人物。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f01df68144f43febc62a856712be407','674b67ed-082d-41d6-ac5b-06848c713090',1944,'临桂沦陷期间','临桂沦陷期间，出面组织地方维持会，为日军征粮、派夫、维持伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dad095e21ba540208ed729b3f1859372','2cea3cab-125d-4cc9-93a8-39fb2b0bc5f0',1944,'桂林沦陷后','桂林沦陷后，参与伪政权教育机构，推行奴化教育，协助日军控制学校与文化宣传。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e202cf6db7e14050ab3c13adf6630b6c','2598d8cd-279b-4d4c-ae52-b8bd15a22dfc',1944,'桂林沦陷期间','桂林沦陷期间，协助日军控制商会、摊派款项、征调物资，为伪政权经济掠夺服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2684e8a1974746d2a1154baff72a9120','dc9cfc5c-fe5b-44d0-bd6e-c78e25e5eb37',1944,'抗战后期在广西境内组织伪军','抗战后期在广西境内组织伪军，配合日军扫荡抗日游击区，活动范围涉及桂林周边。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f984554f76e400db15fa277b457285d','b230cb69-d901-41e2-b710-61f7cd692778',1944,'广西沦陷期间','广西沦陷期间，率伪保安队协助日军维持占领区，参与清乡与搜捕抗日人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aeed214647384beda6d89efd9e6734d1','b627d34f-83fb-4201-8805-7c64b34ae435',1940,'广西籍文人','广西籍文人，投靠汪伪政权，在南京、广州等地从事亲日宣传，与广西沦陷区伪化宣传有联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2bf3b1e2ee65493b82c6e6e3494266f7','5bd9e9d6-8424-450b-aa10-03b0a598ec70',1944,'日军侵占桂林后出面组织伪维持会','日军侵占桂林后出面组织伪维持会，协助日军维持占领秩序、征派民夫与物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8bb95f8671c647aa8ae8d5684bdb5592','bcf7ab1a-aeaa-405e-ae94-1e1346feb820',1944,'抗战后期附逆','抗战后期附逆，参与伪广西政权，在桂林沦陷期间为日军占领当局效力。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21010761829843c4bd01ebdc60d9f246','b0463ddf-824d-4218-806c-7ab5262088e8',1944,'日军发动桂柳会战后','日军发动桂柳会战后，在广西沦陷区参与伪政权活动，担任伪省府要职。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcdbb67bff564dc3ba9e981b7b1e187d','eb4b284a-b971-4e7a-98a0-72b771197442',1944,'桂柳沦陷期间','桂柳沦陷期间，广西部分地方武装和警察在日军诱降下改编为伪军伪警，协助日军控制交通线和乡镇。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7fb7ca9eb8f4457af268303c05edb92','ac5bb2b0-787a-43c9-a236-c564c10db192',1944,'1944年日军侵入全州后','1944年日军侵入全州后，当地士绅中有人出面组织维持会，为日军筹粮、派夫、维持地方秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9a0698628e84046a3b3428d3436cdc2','ac318d1e-55c4-4cd1-8b21-d7e682f7664a',1944,'桂林沦陷期间','桂林沦陷期间，伪警察机构协助日军搜捕抗日人员、管制居民、征收捐税。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b8a165eda5e4d5682acae6762f4d42e','7b7f00db-30f3-4cc7-b2eb-38e753aaa3fb',1944,'在桂柳会战后的沦陷区','在桂柳会战后的沦陷区，部分投敌武装被编为伪军，配合日军扫荡抗日游击区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9561e2e980c44238b145d20025f6290','3743971d-3ca1-49ca-b4ff-a0b649ea4783',1944,'在日军占领桂林、柳州等地期间','在日军占领桂林、柳州等地期间，少数教育文化界人士参与伪政权举办的宣传、奴化教育活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb0c0dbc9f3a4d998eb6350aa983513e','faf3ec8d-cbc7-4db1-9106-d56084caf595',1938,'作为汪精卫伪政权核心人物之一','作为汪精卫伪政权核心人物之一，参与对日投降与伪政权建设，其伪政权体系影响覆盖包括广西在内的沦陷区及国统区渗透活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d9187247986479dab3f61aa7a62ea73','4e55ecf8-c0dc-46b5-b800-003fc6138239',1938,'汪伪政权核心成员','汪伪政权核心成员，负责伪财政与特务系统，参与对日合作及对后方包括广西地区的政治渗透与情报活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b74f3b31fdcc4cc4a961bb276e461b4a','bb226bbf-be36-43cf-b45b-bba593ad8a2a',1939,'汪伪特务头目','汪伪特务头目，其特务网络在华南、西南包括广西方向进行渗透、策反与情报搜集活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-305388ca832749849c4ca8953525dcc5','9bd769e3-56ef-46a7-be60-fa4502a06a6e',1938,'汪精卫之妻','汪精卫之妻，积极参与汪伪政权对日投降活动，在伪政权中担任要职，影响涉及华南包括广西的伪组织发展。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebaf41c239b9409fb8bccb3c808030ea','7d9e6f5c-793a-4870-ac43-b227b59c5b14',1938,'汪伪政权要员','汪伪政权要员，曾任伪广东省长，其活动范围邻近广西，参与对日合作与伪政权建设。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cfc66390d9864ddda197510de55db541','1500e77c-f1aa-439d-8297-fe10d379d7f0',1938,'汪伪政权宣传负责人','汪伪政权宣传负责人，主导亲日卖国宣传，其宣传网络覆盖包括广西在内的南方地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88c230a90762475f9d511891093fe126','d6608c2c-9c7f-4fea-8f56-3bf754d5a9c5',1938,'汪伪政权核心成员','汪伪政权核心成员，参与对日投降谈判与伪政权运作，其活动对南方包括广西有政治影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13403a24112842c49884cdf6661aa4ea','2abbb736-0891-4a03-9a50-c86bf58fafea',1939,'汪伪特务头目之一','汪伪特务头目之一，参与对后方包括广西地区的特务渗透与策反活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7c50ba4a71b409283394595fc3e449d','517da6b5-a9ae-477e-9529-14b4ce7c6867',1939,'在广西地方协助日军维持占领区秩序','在广西地方协助日军维持占领区秩序，参与组织维持会，为日军提供物资与情报支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-451914abd43d4ba9b6d0821c923cdbf4','f52852b6-55a0-4fdb-acd4-ec351e37aa53',1944,'作为桂系要员','作为桂系要员，在抗战后期广西沦陷前后有与日方接触的传闻，但历史记载存在争议，未被广泛认定为汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a38268a184314d81badc962bb2c7df54','356eb413-36d8-4547-9d44-0b0eae72b750',1937,'在广西等地指挥抗战','在广西等地指挥抗战，无可靠历史记载表明其附逆，此处仅作排除性说明。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6ae44adb51246f7ac25155f49ac3b42','4cca8f5e-10ab-42bc-ac92-b6b95a7af05f',1944,'桂林沦陷后投靠日军','桂林沦陷后投靠日军，组织伪妇女团体，宣传“大东亚共荣”，动员妇女为日军服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a5b89538f5b412d887b7f4d27924c9f','7a7d2612-d80a-459b-8ce1-44d59d15502e',1944,'抗战后期与日伪方面有秘密接触','抗战后期与日伪方面有秘密接触，其部属在桂林沦陷前后有投敌行为，本人被指对日伪妥协，历史评价存在附逆争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d5c814c69814bd1941d8af4ce21c1b2','6d6f1761-302a-4344-9ca1-793fde7ebcc1',1944,'桂林沦陷后出任伪桂林县县长','桂林沦陷后出任伪桂林县县长，协助日军建立基层伪政权，推行保甲制度，征发劳役。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86b250d8cb564f5b8c0fbc927ec77b53','9a4f156d-7b02-4f46-b9c0-d50617168193',1944,'在日伪占领广西期间负责伪宣传机构','在日伪占领广西期间负责伪宣传机构，为日军侵略辩护，进行奴化宣传。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4b2d15fd39640d086b47ffc8b461194','81cb8723-ce7d-45cd-b110-c31fc7958dc8',1944,'桂林沦陷后留在广西','桂林沦陷后留在广西，与日伪有经济合作往来，被指为日伪筹措物资，战后受到调查。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f9c81f84233441e8203b327a6e9dbfb','2a189eb0-2a62-4edb-8959-a02889d540bd',1944,'日军占领桂林后','日军占领桂林后，出面组织伪商会，强制商户向日军缴纳物资，配合日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93b9e5a653354b208bc2f504705c7018','bfc444f6-6b92-4e8f-82ef-f441c5febda0',1944,'日军侵占平乐期间','日军侵占平乐期间，出面组织伪平乐县维持会，充任会长，为日军征派粮秣、民夫，协助维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90fb5b0640884cbfa232b7e8d8ee2175','8f68a7eb-dd3c-4e0b-a772-744af7066231',1944,'桂林沦陷后','桂林沦陷后，参与组织伪桂林市维持会并任会长，协助日军推行殖民统治，征调物资与人力。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21806f82deca43be86362f9812878503','7ed60ee5-af8f-4dfd-81ab-d82553bbee6d',1944,'日军第二次入侵广西期间','日军第二次入侵广西期间，出面组织伪广西省维持会，任会长，为日军筹粮筹款、招募伪职人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ded4fa65a2e47d3978c469804d62752','dba30a4b-ea77-4a76-ae89-cf4e4d3cc173',1944,'抗战后期在广西与日伪方面有接触','抗战后期在广西与日伪方面有接触，被指对日妥协、保存实力，其部属在沦陷区有附逆行为，历史评价存在争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2752f149f337480682eaf12e118ddfd9','b4ef5814-d783-480c-ae69-a485801d2001',1944,'桂林沦陷期间出任伪警察局长','桂林沦陷期间出任伪警察局长，协助日军维持治安，搜捕抗日人员，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8e4f878eb24441799a319f7076eadff','3a2f0fac-2552-4667-b1dd-0b0dde3ecb8c',1944,'抗战时期在广西从事教育活动','抗战时期在广西从事教育活动，被指在沦陷区与日伪合作推行奴化教育，但史料记载不一，存在争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e97bb1131c94f7889bab8a7e4d89204','8f9da6de-3fa1-42fc-8ff7-d98efa5cd666',1944,'平乐沦陷后率地方武装投靠日军','平乐沦陷后率地方武装投靠日军，编为伪保安队，配合日军扫荡抗日游击队，征缴民间枪支。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1717620d4a894930aed52b342a649b56','1362ac35-16ba-4ee1-82ad-0f23377208dd',1944,'桂林沦陷期间出面组织伪商会','桂林沦陷期间出面组织伪商会，为日军筹款筹物，强制商户“献纳”，协助日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b223e1d5c63f4b02afb36d5a0e3ed4b6','33bcec70-3495-425d-97be-ad991e56f965',1944,'在日军占领广西期间','在日军占领广西期间，参与伪宣传机构，为日军“大东亚共荣”宣传造势，撰写附逆文章。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be2f43c5f54e4ae1982084ef715e971d','c8b26970-3ad0-4826-943c-57d39c3887a6',1944,'广西沦陷时期与日伪有联系','广西沦陷时期与日伪有联系，被指参与维持会活动，协助日军维持地方秩序，但史料记载有限。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-385ca8dcdec247ae804c9042ed1a0eca','79fbed25-bf33-47d8-a185-ba664b92ad21',1940,'广西籍旧军人','广西籍旧军人，抗战期间投靠汪伪政权，被任命为汪伪广西省政府主席，虽因广西大部分地区未沦陷而未实际主政，但参与伪政权对广西的策反与渗透活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d229e27c22d84c09a7ec8cdece81eb15','79fbed25-bf33-47d8-a185-ba664b92ad21',1940,'广西籍旧军人','广西籍旧军人，抗战期间投靠汪伪，被任命为汪伪广西省政府主席，虽因广西大部未沦陷而未实际主政，但其附逆行为与广西、桂林地区有直接政治关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a3ec4f471004091bef69f9647d36990','daf8d398-ce05-468e-9e52-a4aa26e88f1f',1944,'1944年日军发动豫湘桂战役占领桂林后','1944年日军发动豫湘桂战役占领桂林后，出面组织伪桂林维持会，协助日军维持占领秩序、征发民夫与物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e0b073e7be84cb3af0011865764e359','daf8d398-ce05-468e-9e52-a4aa26e88f1f',1944,'1944年日军侵占桂林期间','1944年日军侵占桂林期间，出面组织伪维持会，协助日军维持地方秩序、征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98a72998522648dd83b2ac2888ef28ca','f074ff9b-c0e7-4b8c-b407-71b49da78a60',1944,'桂林沦陷期间','桂林沦陷期间，依附日军，参与伪维持会与商会活动，为日军筹款筹粮，协助控制桂林商业与物资流通。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-159aebc3825f4870b54487421f38585f','eb7a4fba-8dd3-44e0-9839-017c067d0652',1944,'抗战后期在广西主政期间','抗战后期在广西主政期间，曾与日军及伪政权进行秘密接触和妥协，保存实力，对日伪在广西的渗透负有责任，但其主要身份仍为国民党桂系将领，附逆程度存争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7d2f96830194748b6517722bf3d512a','5d9a9e93-3647-4f00-8914-cefcf891b337',1931,'长期主政广西','长期主政广西，抗战后期在日军入侵广西时，省政府撤退，部分地方政权瓦解，其下属有投敌行为，黄本人对日伪渗透应对不力，但未直接投敌。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d3750e6851540b59d93593bbff2032e','b3af0c94-2db6-4a32-afcf-0b1872777681',1940,'被汪伪政权任命为伪广西省警务负责人','被汪伪政权任命为伪广西省警务负责人，负责在广西沦陷区及周边建立伪警察力量，配合日军维持治安、搜捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ecef7f164654d1d97a43be265bcf241','de6b444b-f619-4fcd-a062-ad4e24394802',1938,'汪伪政权核心人物','汪伪政权核心人物，其伪政权对广西有名义统辖权，并通过伪组织对广西进行策反与宣传，间接影响广西附逆势力。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce6cef6656534a4382406dff7abe6587','0d340836-421c-4c9e-a139-a8c993739bd2',1938,'负责汪伪宣传','负责汪伪宣传，对广西进行亲日卖国宣传，拉拢广西籍人士附逆，影响广西部分文化教育界人士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7606807c6a53423d9ea23ceb29885c1d','0d340836-421c-4c9e-a139-a8c993739bd2',1938,'负责汪伪宣传','负责汪伪宣传，在华南包括广西沦陷区推行奴化教育，桂林、灌阳等地学校曾被迫使用伪教材。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
