INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6dfbcec2a21a4542a522f2055274e542','f81a8c76-49b0-4fa6-9e93-e40a73c6d509',1940,'在汪伪政权支持下','在汪伪政权支持下，于广西沦陷区推行奴化教育，桂林、灌阳等地学校被迫改用伪教材。','危害等级C（丙级，基层头目）','hanjian');
