INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09ef9603c5de499fb47a8c2020b697a0','95cc75c5-b223-4341-b8a5-a747aae641ba',1938,'随汪精卫投敌','随汪精卫投敌，参与建立汪伪政权，任伪中央监察委员会常务委员等职，为汪伪政权核心人物之一','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-050038a2e83e406a890f8290522dd02a','95cc75c5-b223-4341-b8a5-a747aae641ba',1938,'其活动虽主要在南京、广东等地','其活动虽主要在南京、广东等地，但与广西籍汪精卫集团关系密切，对广西籍人员附逆有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-010b5dc8974f461a8a0b9274dbd1d8e6','fe452ecb-db23-42ef-b45e-4603ac99be8d',1938,'原籍浙江山阴','原籍浙江山阴，生于广东三水，但其政治势力与广西有深厚关联','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02d3ad3b67094b4080c84a131f2ecd80','fe452ecb-db23-42ef-b45e-4603ac99be8d',1938,'1938年12月发表艳电公开投敌','1938年12月发表艳电公开投敌，1940年在南京成立汪伪国民政府，自任主席，成为抗战时期最大汉奸头目。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8fcc585f5ac64128aa3f5a3be9cd61aa','c9e084fa-dc6e-4967-8559-bd36a1d6d660',1938,'广东人','广东人，抗战期间投敌，历任伪广州市长、伪广东省政府委员等职，协助日军维持广东沦陷区统治','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4da0b14b43ea44f6b5cff8be8e97c927','c9e084fa-dc6e-4967-8559-bd36a1d6d660',1938,'其活动范围与广西邻近','其活动范围与广西邻近，属华南伪政权系统。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c325eabbd62e423ca71e72a142ef6d4d','0d04196a-0d91-45bc-9c35-d7d77f934e6f',1940,'陈璧君之弟','陈璧君之弟，汪伪政权要员，历任伪广东省政府主席、伪广州市长等职，在广东沦陷区推行伪化统治，与广西邻近地区有联系。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c326c339d9444de288facd30191c9eb2','f7eef156-344f-426d-89f9-b3336d1e7c15',1938,'汪伪政权宣传系统负责人','汪伪政权宣传系统负责人，广东人，长期追随汪精卫，负责伪政权宣传与思想控制，其活动虽不在广西，但属汪伪集团核心，对华南包括广西附逆势力有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63b6aaeeded5418f94aefed412e19e2e','bced73ea-bf98-4f90-a411-2e73923e6ff9',1938,'汪伪政权要员','汪伪政权要员，历任伪外交部长、伪广东省长等职，参与汪伪政权对日交涉与地方伪化统治，属华南伪政权系统。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ebf2fbd9c354a098c6d1989ddb708f7','c05e359a-e538-43ba-b355-a91489a4daa8',1938,'汪伪政权核心人物之一','汪伪政权核心人物之一，历任伪立法院长、伪上海市长、伪国民政府代主席等职，汪精卫死后继任伪政权头目，属全国性大汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
