INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ca5279841e24dcf9afb9c034add0973','7defa829-e21f-45fe-8fc0-4cd148ce162e',1940,'广西籍人','广西籍人，投靠汪伪政权，任伪广西省省长，协助日军在广西推行伪化统治，在桂林等地进行诱降与维持会组织活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b6d3eeb10f14e258e63e19b3cf69c72','c40fb503-9754-4d7b-ae2a-62655968ee53',1944,'桂系核心人物之一','桂系核心人物之一，抗战后期在广西沦陷期间曾与日军有妥协接触，其部下在桂林、柳州等地组织维持会，虽未正式投敌，但相关附逆行为有记载。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ddaee74c874a4432941ff72f3240cb17','6df2ae54-5e89-41a1-a41d-d07bd9dba4ad',1944,'桂林沦陷后投敌','桂林沦陷后投敌，任伪警察局局长，协助日军搜捕抗日人士、镇压民众反抗，维持日伪在桂林城区的秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a69cf63e3d54b3b9b3229e4ea4c3b57','c4869e29-2f1b-4937-8530-b02246a50bf9',1944,'桂系重要将领','桂系重要将领，抗战后期在安徽、广西等地与日伪有秘密接触，其部下在桂林沦陷期间有部分人员投敌组织伪军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21515250cd1249d6ae3e3723885696f7','c4869e29-2f1b-4937-8530-b02246a50bf9',1944,'抗战后期在广西地区与日伪方面有秘密接触和妥协活动','抗战后期在广西地区与日伪方面有秘密接触和妥协活动，但未公开投敌，属于复杂历史人物，地方史料中对其附逆嫌疑有争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-191a7a631cc7458e94f1908a4376c18a','92b0a2bc-1234-4e58-86b6-35f84c80e615',1944,'桂林沦陷后与张君度共同组织维持会','桂林沦陷后与张君度共同组织维持会，负责联络地方保甲长，为日军征粮征夫，协助推行伪化教育。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b384a3852004c1a8f36102125f52428','9d9bd282-c55c-42ed-9540-6f9054c91b9e',1940,'在汪伪广西省政权中任职','在汪伪广西省政权中任职，负责警务与情报，协助日军在桂林、南宁等地建立伪警察网络，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0700d7c165f44fb2ac98a1f0cd3daf48','b4794020-9404-4a6e-b5b9-d5de024f4c56',1944,'桂林沦陷后出面组织伪商会','桂林沦陷后出面组织伪商会，为日军筹款筹粮，协助日伪控制桂林经济，压迫商户。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-931e3051f7c04f67a483d8676dfac792','3624e33a-85aa-4abe-9fd0-135a753ee6db',1944,'在桂林沦陷期间附逆','在桂林沦陷期间附逆，主持伪教育会，推行奴化教育，篡改教材，为日军文化侵略服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a10c00a6c104455184785889453444a4','eda352d1-fde5-4bab-ace1-5d0587b45089',1944,'桂系出身','桂系出身，抗战后期在日军侵占广西期间出面组织伪维持会，协助日军维持桂林、柳州等地治安，为日军征发民夫物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b27298e94a024d9da3566a350ffeec1a','bd3f443f-e35d-4372-80e1-374bffae707c',1944,'1944年日军攻陷桂林后','1944年日军攻陷桂林后，出面组织伪桂林市维持会，协助日军搜捕抗日人士、征发粮食民夫，维持日占区秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea8a1677571a4d03ad71dedefb9e1b4c','a9fec2d1-64cd-475e-ba19-1d4dc9a0be28',1944,'桂林沦陷后投敌','桂林沦陷后投敌，出任伪警察局长，率伪警察配合日军清查户口、抓捕抗日分子，镇压市民反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2db6130d17c94830bac8e238466ab4ad','f571ff02-4591-4e66-ab39-daac335289d1',1944,'原桂系军官','原桂系军官，桂林沦陷后率部投敌，被日军委为伪广西省保安司令，收编散兵游勇组成伪军，配合日军扫荡桂北抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89337211a658485bb07d2556fd9e1781','96f6debb-5c87-458c-8df8-d3b1cb457d2c',1944,'原国民党军将领','原国民党军将领，抗战后期在广西投敌，组织伪绥靖军，活动于桂林、柳州、荔浦一带，协助日军维持占领区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae49b345b4c44639a20768a28a06c316','5f43e9da-2b93-44da-91c1-0411e6f679dc',1944,'1944年日军侵入荔浦后','1944年日军侵入荔浦后，出面组织伪荔浦县维持会，为日军征粮征夫，协助日军控制荔浦及周边乡村。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20d729108ea24be789c81a890f8798d4','da9898b8-6664-4ad0-b316-60f7f3b837fa',1944,'荔浦沦陷期间投敌','荔浦沦陷期间投敌，任伪警察所所长，率伪警配合日军搜捕抗日人员，勒索当地民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0aa9a9897a0e42d3bba9a8ad5c15e6cb','38f77e41-95fa-425b-991f-e9cf50485677',1944,'桂系将领','桂系将领，抗战后期与日军有秘密接触，日军曾拟让其出面组织伪广西政权，虽未正式就任，但其部属在桂林、荔浦一带与日伪有合作行为。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7930a956cef4a1da7c2470d3eb6d57b','8c26382d-c26c-4a80-af80-2d3ecd2e329a',1944,'桂林沦陷后投敌','桂林沦陷后投敌，以商会会长身份为日军筹款筹粮，协助日伪维持桂林商业秩序，压迫商户。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2aba26555de74e74bd360c3bc85f5c50','ef6230cf-eeef-4e22-b5c0-48c52bfcf6c6',1938,'广东人','广东人，汪伪政权宣传系统负责人，早年曾在广西活动，后随汪精卫投敌，负责伪政权舆论宣传。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea0859c031dc43bfa5ccee8dc21f88ee','0e1f4562-8f97-4d8f-ac3b-a68023785dda',1938,'汪伪政权核心人物之一','汪伪政权核心人物之一，早年曾在广西参与政治活动，后随汪精卫投敌，主持伪政权多项政务。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d79018f741045ca8cc10109afe2a776','839f3c65-78b2-468b-822b-693ca692df03',1944,'1944年日军发动豫湘桂战役占领桂林后','1944年日军发动豫湘桂战役占领桂林后，出面组织伪桂林维持会，协助日军维持地方秩序、征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-215dffc967e440aca92be34c0e0359a3','e976811f-dec0-46f7-9d9a-b5b2b6a3d9b6',1944,'桂林沦陷期间任伪维持会副会长','桂林沦陷期间任伪维持会副会长，协助日军管理桂林城区，参与征粮、征夫等附逆活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34ebb6cc405f44e892f02376fb69a368','45156418-e3d6-4be4-b5b6-1e0a6d6a9b49',1944,'日军占领广西部分地区后','日军占领广西部分地区后，参与伪政权筹备，协助日军在桂林、柳州一带推行伪化统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc08add77dd049d38d74aa004ccf5da7','a1e3c38a-ec88-46c5-875c-c00896c3f55d',1944,'桂林沦陷期间出任伪警察头目','桂林沦陷期间出任伪警察头目，协助日军搜捕抗日人士、维持城区治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba3895b36580478bbdd715fbd98f14de','368a7a96-4d25-4940-aa72-c3d31805a409',1937,'广西籍桂系高级将领','广西籍桂系高级将领，抗战后期在安徽等地与日伪方面有暗中接触和妥协行为，但其主要活动不在桂林象山。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5f56a87210c4d9d9746a2302c532c0e','bc6b172c-0750-4b82-bf0a-690c3bfca995',1938,'曾与汪伪方面有联系','曾与汪伪方面有联系，在广西有一定政治活动，但其附逆程度存在争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3f79f6cb3dd41cd9a312f8fba3802de','c0501280-95cf-4a2f-8548-47936c28f65f',1938,'汪伪政权要员','汪伪政权要员，曾到广西进行伪政权联络活动，协助汪伪在华南扩展势力。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-51ef591aea53481ebbef18b369897ec1','16f74f20-2d40-44be-a572-553ee287ee6a',1940,'广西籍汉奸','广西籍汉奸，抗战期间投靠日伪，在广西日占区参与伪政权与伪警察事务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c98a69de625044aead81f91d0fdbd183','988acf97-3215-486e-8e9f-d637774d860b',1931,'广西省主席','广西省主席，抗战期间长期主政广西，与日伪有接触传闻，但未正式投敌，史料存争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e66f22b3f1094437be3c69bb94f9bc39','18132608-25ca-47ce-884c-1e80796523b5',1937,'广西籍将领','广西籍将领，抗战后期与日伪方面有秘密接触，但未公开投敌，史料记载有限。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9583bc4306c24ba1a5f077e5602cae23','03be3396-1011-4973-bc2f-1e8e41866440',1944,'桂林沦陷期间','桂林沦陷期间，投靠日军，担任伪警察职务，协助日军搜捕抗日人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7253b6d1dd2a4cc09b5f50a1e3ea2087','faacbe0b-2c87-4433-b872-f7c056cecc90',1944,'1944年日军侵入资源县后','1944年日军侵入资源县后，出面组织维持会，为日军征粮、派夫，协助维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd2e13859c8a4340a5aeadb8e5488161','b3773a49-1f9d-4f7c-961c-0cbefc822268',1944,'资源县本地人','资源县本地人，日军占领期间任伪保安队长，配合日军清乡、搜捕抗日游击队员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b1ee872aee64f1088ccf5dbaafa7f5c','669e7750-efd6-4f18-a387-999e4c19eed6',1944,'桂林沦陷后','桂林沦陷后，出面组织伪商会，为日军筹款筹粮，协助经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc13461ec90c4c05b6e54c9f1dad6722','78289e46-3f52-4f3b-9e5b-c4cb7fdafe78',1944,'桂林日占期间','桂林日占期间，参与伪教育机构，推行奴化教育，协助日军控制学校。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7220f39ba70460e803705806213215b','db9d95bc-6263-4ef3-a582-719e9b968856',1938,'汪精卫之妻','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广东等地活动，对华南包括广西周边伪政权渗透有影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19086273095b4390839c36a419b2d0cb','cc03d5f2-eb7a-4a08-b3c6-031afc45ba97',1944,'抗战后期日军侵入广西时','抗战后期日军侵入广西时，出面组织伪维持会，后任汪伪广西省政府主席，协助日军维持占领区秩序、征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e987c2a2c214a148c7721c67ccef3b7','e4a12964-8c73-464b-9213-54654b09dd49',1944,'部分资料称其在桂林沦陷前后与日方有接触','部分资料称其在桂林沦陷前后与日方有接触，但主流记载其随桂系撤退，未附逆','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-463b1aa895334559b9b168cf6a64c3fd','e4a12964-8c73-464b-9213-54654b09dd49',1944,'此条存疑','此条存疑，不宜作为确定汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6e6de47371d40889dc0a855bfada7f6','a2d79940-d9d0-461d-8e91-4bc0101d5d7f',1944,'1944年日军攻占桂林后','1944年日军攻占桂林后，出面组织伪桂林维持会，为日军征集民夫、粮食，维持占领区基层统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
