INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-882ad6c3de024d6990b307bb287b08a3','68efe6d7-2c5f-4ce0-ac32-4e3efd72812d',1944,'阳朔沦陷期间组织伪维持会','阳朔沦陷期间组织伪维持会，替日军派款、派粮、拉夫，维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eaf9908ec0e94499b9b0cf504f098d76','0ab8bdbd-7945-4d77-84ba-26742b4b679f',1944,'在桂林沦陷后参与日伪宣传机构','在桂林沦陷后参与日伪宣传机构，撰写亲日文章，鼓吹“大东亚共荣”，为日军占领辩护。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe0237e20f4f4fa29de83d6faf56defe','bdc8ed81-8293-455b-be4e-42f5e293ec1b',1944,'桂林沦陷后出面组织伪商会','桂林沦陷后出面组织伪商会，为日军筹款筹物，协助控制占领区经济。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-febf23fe48364c178b736dfa194ca56d','e7930e85-b02f-4324-818e-b71ba5daff2a',1944,'日军占领桂林期间','日军占领桂林期间，参与伪教育机构，推行奴化教育，篡改教材，宣传亲日思想。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c4fbf230cb143fbbb2927bac0ab7a3d','48ea5ace-fb9f-4cf0-be6a-dae848342821',1944,'协助伪桂林维持会会长苏新民','协助伪桂林维持会会长苏新民，负责联络日军、摊派捐税、组织伪自卫队。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23891c8048d34f959727ba47bbc69e5b','2fed0433-5b95-432a-826d-cb7698a348d4',1944,'阳朔沦陷后任伪警察头目','阳朔沦陷后任伪警察头目，带领伪警配合日军扫荡周边乡村，抓捕抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7194d1d830de432e97d1dc5df266811b','a135e20a-8157-4cec-b65b-f9214adb469b',1938,'曾参与汪精卫的“和平运动”','曾参与汪精卫的“和平运动”，后退出，但其一度附逆行为在广西、桂林知识界有影响，桂林抗战文化界曾对其行为进行批判。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27745c46535949b9938cf7e2ee45e10f','b8630256-cb90-4e4b-9a8f-f57d90acaa7a',1938,'汪伪政权宣传干将','汪伪政权宣传干将，广东籍，其宣传网络覆盖华南包括广西，桂林抗战文化界曾对其汉奸宣传进行揭露和抵制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f7b6ecf0ee142e48f09039934f45ee0','ad3d6ec6-868a-46b4-af76-835f6ecff7d0',1938,'汪伪政权核心人物','汪伪政权核心人物，其伪政权曾试图向广西渗透，桂林地区抗日力量对其政权进行抵制和斗争。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7f42b89f680451bb948b0b90d9a41df','3dd06ce2-3521-4284-94db-7f6c9ed1a1f7',1938,'汪伪政权核心成员','汪伪政权核心成员，其财政、警政体系对华南包括广西有间接影响，桂林抗战后方曾对其伪化经济政策进行抵制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-454a132c3a384a09b1193154d27e1980','95308b46-a020-4462-bbec-1c1949792c91',1938,'汪伪政权要员','汪伪政权要员，曾任伪广东省省长，其活动范围与广西、桂林邻近，对华南抗战后方有威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc4b3b1b370b4b71a54abd2eea1ce803','bfec927b-5739-420f-8d61-4c074916f07e',1940,'广西籍人','广西籍人，投靠汪伪政权，被任命为汪伪广西省政府主席，负责在广西沦陷区推行伪化统治，配合日军对广西的侵略与控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a5c442dae444544b8a5ec8f6f62f533','ed26aba0-cc87-45ec-88ff-f991ec77849d',1944,'新桂系成员','新桂系成员，在日军入侵广西期间动摇投敌，参与伪政权活动，协助日军维持地方秩序，具体职务记载不一，但被列为广西附逆人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-091b8c8d6d86484fa74dc385b24e8dca','ae1f58dc-040c-40d1-b3bb-875819087844',1944,'新桂系高级将领','新桂系高级将领，在抗战后期与日伪方面有秘密接触和妥协行为，其部属在广西部分地区与伪军合作，被指为附逆行为。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
