INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e7e662ac9a5455fb97407657178ccf2','cb2d7c65-a156-4d8d-b511-aa8673124a21',1944,'日军占领期间','日军占领期间，以商会名义为日军筹集物资、军饷，协助日军控制百色商业，压榨商户和百姓。','危害等级C（丙级，基层头目）','hanjian');
