INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3aed78985084fdda21c5651afe81045','e2bbe08c-4d2a-4549-ae22-e1dfaedb9b38',1944,'投敌后任伪广西省警察厅长','投敌后任伪广西省警察厅长，协助日军搜捕抗日人员，镇压民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9aa4447bddab4c6095a78bd1a061ce3c','6896b042-2ba6-4844-9bed-b985b7e159dc',1944,'率部投敌','率部投敌，改编为伪保安部队，配合日军扫荡广西抗日游击区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e613a53e848a423fb2d540815ae1271f','49d2a5cf-c0dd-46fb-9076-f244fea2a2a1',1937,'广西籍（防城）要员','广西籍（防城）要员，抗战期间曾与日方暗中接触，但未公开投敌，故严格意义上不属汉奸，仅列作相关人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27317d7144d2426ab5e65fb6ceae214b','799d213f-e696-4273-9695-e2142fcdde88',1940,'汪精卫伪政权曾任命其为伪广西省政府主席','汪精卫伪政权曾任命其为伪广西省政府主席，试图在广西建立伪政权，但黄旭初并未实际赴任，其任命更多具有象征性。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0af9a513e3c94191b92ee124020511b2','154e3814-4af9-4a41-a556-82bfdd120a8a',1940,'在汪伪政权支持下','在汪伪政权支持下，参与策划广西沦陷区的伪政权组织，试图在广西境内建立维持会体系，配合日军统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0921c45f924a4f13b89c134dfafdc3e6','364be07e-5406-4308-a6f5-c623c9471680',1940,'原为国民党桂系将领','原为国民党桂系将领，后投靠汪伪政权，在广西及周边地区组织伪军，配合日军对广西的侵略与控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cca0a624e084c659a59330204a2d752','c7761b7c-103e-4165-8c67-281ac70f600b',1940,'作为汪伪政权核心人物','作为汪伪政权核心人物，参与策划对广西等华南地区的伪化统治，其伪政权体系延伸至广西部分地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1777519908804787a28dba3fa997f858','0156fb21-998a-4608-975b-b43770d934ed',1940,'在汪伪政权中负责宣传与地方伪化','在汪伪政权中负责宣传与地方伪化，其宣传体系覆盖广西，推动亲日附逆思想在广西的传播。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-286d1fcdf89248a586d3bd032bb6dacc','793390df-f5f9-4eb7-a75e-72a57272ff60',1937,'作为华北伪政权头目','作为华北伪政权头目，其伪政权体系与汪伪合并后，对广西等地的伪化统治有间接影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0c34eb017ba40578ec0a9ae84740294','9d56e4e9-0316-49f2-95df-b220a2f55e62',1938,'其伪政权与汪伪合并后','其伪政权与汪伪合并后，参与对华南包括广西地区的伪化宣传与组织。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-451d3c0ff07d4ef5b63fbc373013397c','4259a396-ba06-47e3-963f-94854d8d90eb',1940,'作为汪精卫之妻','作为汪精卫之妻，积极参与汪伪政权活动，其影响力涉及广西等华南地区，推动附逆宣传。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c20cd4a8b4e467cb100e8c630aa9841','d1e7c8ae-1918-44dc-ab6e-d608a66a143a',1940,'在汪伪政权中负责外交与地方事务','在汪伪政权中负责外交与地方事务，参与对广西等地的伪化统治策划。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
