INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe1bb60dea6043e8833b6151e74557f7','bf863c2d-6fb1-463f-8fee-1de679444c7b',1941,'在常州任职期间','在常州任职期间，推行伪化教育，强征捐税，为日军提供粮食和劳役，镇压钟楼一带的抗日宣传活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-612cc79f40054f8284a9c99b6908d92a','182415c3-0823-4645-bd3a-53c0aee05243',1937,'日军占领常州初期','日军占领常州初期，组织维持会，协助日军建立伪政权，在钟楼地区张贴告示，强迫居民领取‘良民证’，为日军征粮派夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
