INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de994852c19c4a50938ff5eb6237f44b','68430623-c423-47a1-a12c-00d38f8010f4',1942,'原为国民党将领','原为国民党将领，1942年投敌，任伪淮海省省长兼保安司令，在徐州地区推行日伪统治，镇压抗日力量，征收苛捐杂税，协助日军进行“清乡”和“扫荡”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5dac73aeaa9c4fca8ddfffee8b19c0f2','68430623-c423-47a1-a12c-00d38f8010f4',1942,'原为国民党将领','原为国民党将领，1942年投敌，任伪淮海省省长，统治徐州及周边地区，推行日伪政权，镇压抗日活动，1945年日本投降后一度被收编，后再次反叛被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4339bc3b929d4bd3900957bf5e8cdb56','68430623-c423-47a1-a12c-00d38f8010f4',1942,'原为国民党将领','原为国民党将领，1942年投敌，任伪淮海省省长，统治徐州及周边地区，推行日伪政权，镇压抗日力量，1945年抗战胜利后一度被收编，后再次反叛被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c86a3bd462f94a8dbb44e51e9fcecbe4','efdc42e7-5a6d-4833-af0a-a60767bb46af',1943,'追随郝鹏举投敌','追随郝鹏举投敌，参与组织伪军和警察，在徐州及周边地区协助日军抓捕抗日志士，破坏地下抗日组织。','危害等级C（丙级，基层头目）','hanjian');
