INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bdbfbfc1ccdd4137847629c1f5dea7c4','80b44bef-3f0d-4549-95d6-4fe3e267de01',1940,'在徐州主持伪华北政务委员会事务','在徐州主持伪华北政务委员会事务，推行奴化教育，强制民众献铜献铁，为日军战争机器搜集物资。','危害等级C（丙级，基层头目）','hanjian');
