INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6967ea3c3cb34b479d73c12f96a1efeb','9dc97025-56f0-4a98-8786-5d02da118c1f',1940,'作为华北伪政权最高负责人','作为华北伪政权最高负责人，直接管辖徐州地区，推行“新民会”运动，组织汉奸团体，配合日军进行经济掠夺和思想控制。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
