INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb8bb60a26d849a4887e9fc35b875c46','07733495-a684-45bc-8726-f5e327012c06',1938,'其伪政权势力延伸至徐州北部（如丰县、沛县一带）','其伪政权势力延伸至徐州北部（如丰县、沛县一带），推行保甲制度，强征粮食，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6832e49525248d8ad9e67c2a5c9b071','9cbbef57-f61c-479a-b506-61b21950123c',1938,'作为山东伪政权头目','作为山东伪政权头目，曾协调徐州与济南间的伪军行动，协助日军运输物资，破坏陇海铁路沿线抗日游击战。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cd34a81812543238102119e19c9375a','e25a2c96-4a23-4674-b4f9-2532b37acb68',1939,'指挥伪警察在徐州城内搜捕抗日地下工作者','指挥伪警察在徐州城内搜捕抗日地下工作者，查禁抗日书刊，配合日军宪兵队实施“特别清乡”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-553d7da64d01473e989306d0d540d74f','759d2e0e-2456-46f4-917c-13d5545511d3',1938,'在铜山地区（今徐州铜山区）推行日伪法令','在铜山地区（今徐州铜山区）推行日伪法令，强征土地税，组织“自卫团”协助日军，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76f79aa61de04f4e9c5c8a0f1937fabf','190fcafa-4e00-4270-9c2c-f30578837844',1939,'在睢宁地区建立伪政权','在睢宁地区建立伪政权，强征壮丁补充伪军，多次向日军报告新四军活动情报，导致抗日武装遭受损失。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7737514bddf04d649467f96963b1d35f','0e2bffb9-335d-4bce-ba60-157649dc0240',1940,'在丰县推行“保甲连坐”','在丰县推行“保甲连坐”，杀害抗日干部，组织地主武装“还乡团”，配合日军进行“蚕食”进攻。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a8245fe316b426299341c19187d1971','82d16814-edc5-48f8-a6fb-ef0e41e5e394',1941,'在沛县强征军粮','在沛县强征军粮，破坏中共地下组织，协助日军建立碉堡封锁线，镇压湖西抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-532791ef732641398e2b1d325f87e37a','c7253952-6c0e-42eb-9a70-f390fe60ed7c',1942,'在邳县（今邳州）推行奴化教育','在邳县（今邳州）推行奴化教育，强迫民众参加“新民会”，搜捕抗日游击队员，向日军提供运河沿线情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b203cd544292446fb21aace444f39226','ce034afd-8e05-480e-8793-4eb0d10b8ea7',1943,'在新沂地区组织伪保安队','在新沂地区组织伪保安队，配合日军“扫荡”宿北抗日根据地，强征民夫修筑公路和炮楼。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-382f4ec182af4497a010f5198000998d','e1350c72-6953-48b2-82f2-907cbc309e6e',1943,'原国民党军官','原国民党军官，投敌后为日军提供徐州地区军事部署建议，参与策划“铁壁合围”战术，对抗抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3391033755264e02b102b28a0fb47efa','c81082c4-6ff8-48fa-b1e2-0b211a2be720',1942,'率伪军数万人在徐州以西地区驻防','率伪军数万人在徐州以西地区驻防，多次进攻冀鲁豫抗日根据地，烧杀抢掠，制造无人区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc49068b00c5421490233ec9901ec362','009a1392-5ec0-4dc7-a906-aa82cddf3d72',1943,'投敌后其部队在徐州以北地区活动','投敌后其部队在徐州以北地区活动，配合日军“扫荡”太行山和冀南抗日根据地，残害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1cc5e47c11064c2a891f2861533a6541','66394548-4617-462a-a1d2-fd72a716240e',1941,'原为国民党将领','原为国民党将领，1941年投敌，在徐州地区组建伪军，协助日军扫荡抗日根据地，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32b19e78833f48a8b72cca65edd57ee1','66394548-4617-462a-a1d2-fd72a716240e',1941,'原为国民党将领','原为国民党将领，后投靠汪伪政权，在徐州及周边地区协助日军清剿抗日武装，镇压民众，后于1946年反正，但此前在泉山地区有活动记录。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-583c21855956478db828834215a8edcc','f6286285-ee66-4221-9a6d-ffc70a6158bf',1939,'在徐州及丰县一带活动','在徐州及丰县一带活动，率伪军配合日军“清乡”“扫荡”，镇压抗日力量，强征民夫粮饷。','危害等级B（乙级，市县厅局级）','hanjian');
