INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08e0b58492d04a458f3a2ddbd1d44ebc','fef010c6-43c0-4e49-9035-5a82210bad61',1938,'日军占领徐州初期','日军占领徐州初期，出任伪维持会会长，为日军筹粮筹款，组织汉奸武装，协助日军稳定占领区统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
