INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f956200085c44a488a6696df11936def','1aa2a26b-53fd-4c01-aefc-6904edd0e662',1940,'担任伪特务队长','担任伪特务队长，专门刺探抗日军事情报，破坏地下抗日组织，多次带队抓捕并杀害抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4d5421e2188462ba471f57a51da59af','83746785-356d-498f-9f0c-4b2e621ed7f9',1939,'推行奴化教育','推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，迫害有爱国倾向的教师和学生。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-725e15981b58407286f74bd538712a7a','bc15a700-0651-4801-b1c3-f622998eebef',1941,'任伪鼓楼区区长期间','任伪鼓楼区区长期间，负责该区治安和物资配给，强征民夫修筑工事，并协助日军清查抗日嫌疑人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7729d9b0ddbe49afaa8cf7f4eef24d47','c8aae621-006e-421e-960c-14c3b787d996',1942,'组建伪保安团','组建伪保安团，配合日军扫荡周边村庄，抢劫百姓财物，杀害抗日群众，并参与“治安强化运动”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ecf7cc70fb74042bcca693e041c834a','d2f6926b-2abe-4b88-a2f0-f9fe02083b3b',1938,'为日军宪兵队担任翻译','为日军宪兵队担任翻译，并充当密探，利用语言优势刺探民间抗日言论，直接导致多名抗日志士被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db219020194546518cfe73131171d96e','cbb452cb-451b-4c26-ae50-506b429327ef',1939,'原国民党鲁苏战区游击纵队副总指挥','原国民党鲁苏战区游击纵队副总指挥，1939年投敌，在扬州、泰州一带收编伪军，配合日军扫荡抗日根据地，残害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b3db396733a46e491451f47328fa785','cbb452cb-451b-4c26-ae50-506b429327ef',1939,'原国民党鲁苏战区游击纵队副总指挥','原国民党鲁苏战区游击纵队副总指挥，1941年投敌，在扬州、泰州一带配合日军进攻新四军，残害抗日军民，后任伪第一集团军总司令，驻防苏北（含邗江地区）。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49552bed974d4b44b29a49d903e29593','d2ba8179-3934-46c1-b3d0-fee67c00ea20',1940,'原李长江部旅长','原李长江部旅长，随李投敌后任伪师长，驻防扬州地区，参与清乡和“扫荡”，劫掠百姓，捕杀抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35d00af37a2541ab811da210688a7659','c010faa4-5013-441d-9def-f203b46ab11f',1940,'原李长江部旅长','原李长江部旅长，投敌后任伪师长，活动于扬州、高邮一带，协助日军推行伪化统治，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
