INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e1576cb04f04382a7d32031b3f9c8fc','4b8cecd4-0316-437b-9b10-93aaedd8af9f',1941,'在扬州、宝应一带推行“清乡”政策','在扬州、宝应一带推行“清乡”政策，设立封锁线，搜捕抗日分子，破坏地下组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28938b8d943047db92db809b21d02397','1c55a461-b533-44d5-b223-0a8c4bf9ef3a',1942,'统辖苏北伪军','统辖苏北伪军，配合日军“治安强化”运动，在宝应地区多次发动扫荡，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ebc98698c7243f8a94c33b451399c41','6ed36cc1-aa9b-4162-9aab-66dee39219e0',1938,'日军占领宝应后组织维持会','日军占领宝应后组织维持会，为日军筹粮派夫，提供情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
