INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-252d5328acbe4f6aa947eefc8a84b592','e56ae169-3b7f-4a8e-b346-c98c4697dd22',1943,'率伪军数万驻扎苏北','率伪军数万驻扎苏北，多次进攻宝应抗日根据地，制造惨案，强征壮丁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
