INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d168fa720a034a548028f0632123a67a','b629084b-5217-4c77-ae4b-4e4f23b5dd52',1944,'在宝应周边推行伪化统治','在宝应周边推行伪化统治，组织伪警备队，协助日军“蚕食”根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e23edbd415a4ea89329f99f9dc9da0e','ce439e3e-40d4-459e-900c-9df28d352f48',1940,'虽驻南京','虽驻南京，但通过伪江苏省政府控制扬州宝应税收和物资，资助伪军清剿抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82db9004b40f4fe2895d9efb017a3f43','c8a1c996-525f-4c0a-8459-50d22c887c31',1939,'原国民党鲁苏战区游击副总指挥','原国民党鲁苏战区游击副总指挥，1941年投敌，在扬州、泰州一带收编伪军，配合日军‘清乡’扫荡，残害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
