INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d57e61a6f84547f595d0407d98a2407b','b650908a-7d3a-401b-9334-8236f9359254',1941,'率伪保安队驻防扬州城','率伪保安队驻防扬州城，多次配合日军突袭新四军游击队，杀害地下党员，强征民夫修筑工事。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f19f9cc4f8e7466e8948ea7b2d7a8a14','dd7161e7-b3c2-4c93-9de9-1c7455b0a159',1937,'扬州沦陷后率先组织维持会','扬州沦陷后率先组织维持会，为日军提供物资、情报，协助建立伪政权，后任伪商会会长。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
