INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e51ba7d849464c90a52566265e1ee323','6ba9579d-af8a-4b3b-8656-4b22a9df189b',1941,'虽主要活动于南京','虽主要活动于南京，但曾多次到扬州、广陵视察伪政权，推动‘清乡’和物资统制，间接支持当地汉奸势力。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4415cd20a9c943afaeb3ab699d523156','cea45287-7521-4769-a9e1-2a611ad5a99f',1943,'统管苏北伪军和行政','统管苏北伪军和行政，在扬州广陵地区强化殖民统治，组织‘自首’运动，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16478eb27df54edd8b7d4a02fb50284a','e69e8776-a6ae-4845-a50f-41d9a4622e85',1942,'率部驻防扬州及周边','率部驻防扬州及周边，配合日军‘扫荡’高邮、宝应等地，在广陵设有指挥部，参与镇压抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
