INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3ab93ed4c274518bc9d73369ded5fca','a5378e26-94df-4b6f-9051-a699879567f8',1940,'任伪江都县警察局长期间','任伪江都县警察局长期间，在扬州城区及近郊（含今经开区部分区域）设立特务据点，逮捕抗日地下工作者，刑讯逼供。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cebb2d3b16564b39a5d6ec7aa5e571a4','a5378e26-94df-4b6f-9051-a699879567f8',1940,'管理伪警察机构','管理伪警察机构，在扬州城内设立特务据点，侦捕地下党员和进步学生，破坏抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
