INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d4d9c185570420d9e53c9f5a9880f1d','43c32ea4-d42d-45ac-972e-2bda92e219eb',1940,'统领伪县保安队','统领伪县保安队，驻防仙女庙（今江都城区）一带，多次袭击新四军地方武装，杀害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6d1c1a6ec05484ea76067e3a33b1bdd','26476620-51b5-41c7-b8d3-b61a5b62539f',1941,'负责协调扬州地区伪军、伪警与日军联络','负责协调扬州地区伪军、伪警与日军联络，参与策划“清乡”计划，向日军提供抗日武装活动情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52e219d37c7d470ab0dc3d56131e92ea','da312e05-675a-4e43-a921-4041092b91b5',1943,'率部驻防江都沿江地区','率部驻防江都沿江地区，配合日军封锁长江交通，袭击新四军渡江部队，强征船只。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22893a90a45741068de6b6f0bf628f5a','c8b6b6aa-09e8-4d59-a65e-88edb09a6c1d',1942,'原国民党军官','原国民党军官，投敌后在扬州、江都一带收编散兵游勇，充当日军“扫荡”先锋，烧毁村庄。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7c39f77b64c4113bbfb8327f0958774','d2981696-e905-40a2-b562-337687e6c8b4',1940,'在仙女庙地区强征“和平捐”','在仙女庙地区强征“和平捐”，为日军提供粮食和劳役，告密导致多名抗日群众被捕。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-941e2eba1db04224904274f7e60cf308','a7f8ba88-b290-4242-a9b2-0d18c7debf17',1941,'推行奴化教育','推行奴化教育，强制学校使用日伪教材，组织学生参加“庆祝日军胜利”活动，压制师生抗日言论。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a6e58bd45e749f4afc8e936466dfd15','adda7ac0-e677-45f1-b5f0-20fc5797c0f2',1942,'控制邵伯湖及运河航道','控制邵伯湖及运河航道，盘查商旅，为日军运输队护航，截获新四军物资，勒索船民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3e2d182cc1b4caa8e3ccfee64d6a346','3391bba5-8cd2-408d-ad1a-c9dd11b26b4c',1937,'扬州沦陷后率先投敌','扬州沦陷后率先投敌，组织维持会，为日军征粮派夫，协助建立伪政权，镇压抗日活动，后任伪江都县知事，管辖邗江一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0659bbcd49c14e94b16454611617fc5c','74c95564-6e1d-480d-bf64-2da233815eb2',1938,'原地方土匪头目','原地方土匪头目，投日后任伪保安大队长，在邗江、扬州近郊设卡勒索，捕杀抗日游击队家属，多次配合日军“清乡”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08cdf4d2c8c84d5e8fa8010f5e6ae95d','25405d15-77d0-4824-8732-6babe40affe5',1939,'控制邵伯湖至扬州运河段（含邗江水网）','控制邵伯湖至扬州运河段（含邗江水网），为日军运输物资护航，搜捕水上抗日交通员，敲诈船民，罪行累累。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f986dc60492547a187a9f2741d2164ba','87561287-ddd6-4316-a6a0-1d8672882c67',1943,'原国民党将领','原国民党将领，1943年投敌后一度在扬州参与伪军整编，协助日军对邗江地区进行“扫荡”，后调任山东。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-912d2d8aa7b24661b369af36bd51d12c','4cf45540-5328-4334-973d-331ed2850116',1942,'原国民党第三十九集团军副总司令','原国民党第三十九集团军副总司令，1942年投敌，所部驻防苏北，在邗江、仪征等地配合日军进攻新四军，强征壮丁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23a34f7dcec14139b5c7c665bf6b87f2','6e667c47-8401-4617-8ba6-a6a4ffb74e13',1940,'在邗江各乡镇设立伪警察分驻所','在邗江各乡镇设立伪警察分驻所，专门侦缉抗日地下组织，逮捕进步青年，刑讯逼供，致多人死亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-423d5ca9726141f7abf23c7e67f98790','a11489e1-1ad3-4aeb-b358-c5cbcd7c7287',1940,'虽常驻南京','虽常驻南京，但作为汪伪政权核心，其推行的“清乡”政策在邗江地区造成大量民众被屠杀，并直接指挥伪军参与对扬州周边抗日根据地的封锁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b9b894feb8e435b9e5a5da917a23ed6','fae94b86-758e-47e0-829a-3e585fd75425',1938,'在扬州短暂活动期间','在扬州短暂活动期间，推动“治安强化运动”，在邗江农村推行保甲连坐，协助日军建立情报网。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d7dbdf6a5d7418899b532dd8913afe4','99fa0bb0-ced7-4739-830e-2cdf20bd6c0d',1943,'主持邗江、江都等地的“清乡”行动','主持邗江、江都等地的“清乡”行动，设立集中营，强征民夫修筑封锁沟，致使邗江数万百姓流离失所。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18c42abb00d44a66a3dc62a32f9f96d0','508fb78e-348d-4bb8-ac85-1dbd95dc79e6',1939,'原国民党将领','原国民党将领，投敌后参与汪伪政权在江苏的组织活动，协助日伪清乡','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d10d991e68f44aabf33300937aa89e6','50ad2cf2-b6cf-46ed-847b-69fbdb77f9f7',1943,'在江苏推行伪化统治','在江苏推行伪化统治，配合日军进行经济掠夺和清乡','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b13ce2d590a43c6bb0ab51d0609f139','befbd7ae-1e27-4a0b-9782-e01a5827724a',1938,'参与组建伪维新政府','参与组建伪维新政府，在江苏推行奴化教育，协助日军维持治安','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08371b0850e842898a1fe4b9533fc961','59adde96-883b-43d2-b5c9-e1c6e1b54ee6',1938,'率部投敌','率部投敌，在江苏、扬州地区协助日军扫荡，镇压抗日游击队','危害等级A（甲级，省部级/大军区级要员）','hanjian');
