INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3aa79a4ef7b5444f99da07e922ee0c5b','09642084-10e8-4f2e-a87e-5267d1a99f4b',1939,'在高邮推行日伪统治','在高邮推行日伪统治，组织伪警察和保安队，镇压抗日活动','危害等级C（丙级，基层头目）','hanjian');
