INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f880d6aeb4f849e3b0c87702c51daaf3','f011caa3-25f9-4465-9521-eb5a2f947cd0',1940,'虽总部在上海','虽总部在上海，但直接参与江苏伪政权财政和特务决策，影响扬州高邮地区','危害等级A（甲级，省部级/大军区级要员）','hanjian');
