INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c99af22792d941bbbc80574aab1545ec','93c71de8-be07-4c7d-a590-b51f601369a9',1938,'无锡人','无锡人，曾任伪江苏省长，组织伪警察和保安队配合日军扫荡，推行保甲制度，强征壮丁，参与经济统制掠夺物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ce5595f41fb45538559a95580d1f747','93c71de8-be07-4c7d-a590-b51f601369a9',1938,'曾任伪维新政府内政部长','曾任伪维新政府内政部长，后任汪伪江苏省省长，在江苏推行伪化统治，协助日军清乡，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71f35e3bd2a744b08df9127d52645622','28f21089-5974-43b7-8744-a68de8742971',1940,'无锡本地汉奸','无锡本地汉奸，任伪县长期间协助日军建立维持会，强征粮食，抓捕抗日军民，推行奴化宣传。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69bae016737946a6a46cbf891352ea95','717f7987-548d-4c10-958d-98a8af625f19',1941,'无锡人','无锡人，原国民党军官，投敌后率部驻防无锡、苏州一带，参与清剿新四军，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4eaa432bf25d4a4aaee5d6f1492ef21d','c971a20c-59d3-43b2-989d-03e4232e0a40',1942,'负责无锡地区清乡行动','负责无锡地区清乡行动，设立封锁线，搜捕抗日分子，强征民夫修筑工事，掠夺地方资源。','危害等级C（丙级，基层头目）','hanjian');
