INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77371ac5022f43a09c03c081cb852f12','deedc6d6-2783-4756-a42a-4e87b9538e72',1940,'无锡人','无锡人，指挥伪警协助日军巡逻、抓捕抗日嫌疑犯，参与镇压罢工和学生运动，充当日军耳目。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d49a44265b3b4e9186305cef3c1cdb13','8077a78d-e581-49ea-b8b4-60d79461e880',1937,'日军占领无锡初期','日军占领无锡初期，率先组织维持会，为日军筹粮、提供劳役，协助建立伪政权，后任伪县府顾问。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb6cdcff554749b5bc089180bd34c8b8','76e1355f-fa01-4302-849a-b0f29c0473c4',1941,'率保安队配合日军扫荡太湖沿岸','率保安队配合日军扫荡太湖沿岸，袭击抗日游击队，烧毁村庄，强征壮丁补充伪军。','危害等级C（丙级，基层头目）','hanjian');
