INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-772b5fed9c5e4b948223f0988e69ba02','9f4faa42-21f9-48c2-a565-39488b9a167c',1939,'组建76号特工总部','组建76号特工总部，在苏州、常熟等地大肆捕杀抗日志士，后任伪江苏省长，推行清乡运动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8a69bd93a114ddeb9cbaf692ccdea07','9f4faa42-21f9-48c2-a565-39488b9a167c',1939,'主持76号特工','主持76号特工，在镇江等地大肆捕杀抗日志士，后任伪江苏省长，推行保甲制度，强化日伪统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
