INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9fdabddcea2a4c3ba66bd6d5d1187ef6','57793ff0-aa2c-4dd1-86fa-03bbae889999',1940,'长期盘踞淮阴（今淮安市区）','长期盘踞淮阴（今淮安市区），推行保甲制度，强征粮税，协助日军建立据点，镇压抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2de7b072d8f742319e44080958ffbd98','37557f95-0e10-40a9-b026-ac676ca847a0',1939,'日军占领淮城后出任维持会长','日军占领淮城后出任维持会长，为日军筹粮派夫，建立伪政权，迫害抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fb86972edd44152835fbc93845b9b50','04967894-6541-47b6-a386-9f447d2e49ae',1941,'原国民党鲁苏战区游击司令','原国民党鲁苏战区游击司令，1941年投敌，在淮安、涟水一带收编散兵游勇，配合日军“治安肃正”，进攻新四军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f45c290ed35946f8886457970ae01606','817b6f8f-b0be-4c6a-a2a4-72cf2d8c6775',1942,'在车桥地区设立伪区公所','在车桥地区设立伪区公所，强抓壮丁，提供情报给日军，导致多起抗日群众被捕。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23b66c39904e4d629fef1efcef2d9099','8bcf030d-9d92-4564-b1bf-e211325299ba',1940,'在涟水（今属淮安）推行伪化统治','在涟水（今属淮安）推行伪化统治，组织“自卫团”，配合日军扫荡盐阜区，杀害抗日干部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d4588805fa24507891401f85bfd406d','f0e8f37f-af3a-4c89-8d04-59fea73b9a18',1942,'率伪军驻守淮阴城郊','率伪军驻守淮阴城郊，多次袭击新四军武工队，参与“清乡”行动，烧毁村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-142593a38bc44b10b6effea045afb947','ec617bcc-e4d6-4c84-b209-66f1d740da75',1939,'协助日军在平桥建立据点','协助日军在平桥建立据点，强征民夫修筑碉堡，勒索商贩，为日军提供粮食。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f2013b0d99a478789890bb8bdb238e6','7ccdbd80-0ad1-4c2a-857f-7ace2a557ee1',1942,'原国民党第三十九集团军副总司令','原国民党第三十九集团军副总司令，1942年投敌，在淮阴设立绥靖机构，整编伪军，参与“扫荡”洪泽湖地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1d23fb3c47d4f0d9b71fb410076e528','ae69417f-b404-4aae-a19c-68823c5b1884',1940,'指挥伪警察搜捕地下党员','指挥伪警察搜捕地下党员，破坏抗日组织，执行日军“连坐”政策，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d0060724699412787575a4dbc10b772','ea8c689d-c6eb-4c86-8af8-0528c7e10511',1939,'在洪泽湖周边地区推行日伪统治','在洪泽湖周边地区推行日伪统治，组织伪军配合日军扫荡，镇压抗日军民，征收苛捐杂税，掠夺粮食资源供给日军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8f56f65e0fa4070a48eecf504e8a00e','5ac24bb1-0d57-4379-9ed0-efcb2851eea4',1939,'日军占领淮阴后率先投敌','日军占领淮阴后率先投敌，组织维持会为日军提供情报，协助日军建立伪政权，欺压百姓，强征民夫修筑工事。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-748c1e490c48443da8d25b7dda9daa59','f901081c-b07c-43fe-867a-69463bdc0307',1940,'在淮安地区推行日伪“清乡”政策','在淮安地区推行日伪“清乡”政策，组织伪保安队配合日军围剿新四军游击队，残害抗日群众，强征粮食支援日军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-184c930c609d4451abf94584e1ddec73','ddae1086-1450-4ec2-81ce-7c6f5b7b657f',1941,'盘踞洪泽湖','盘踞洪泽湖，率伪水警队为日军运输物资，封锁湖面交通，袭击新四军水上交通线，劫掠渔民财物，杀害抗日干部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21593db4882d479badf8156375963469','dad4cdd0-8323-4761-9f3e-aaf08e255d77',1940,'充当日军爪牙','充当日军爪牙，指挥伪警察搜捕抗日地下党员，破坏抗日组织，严刑拷打被捕人员，协助日军进行“治安强化”运动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10cca87c0c294b0c96a13ba2abe12abb','e01e950e-2862-432b-9075-d287feb8e97d',1941,'率伪保安团在淮安、洪泽交界地区多次进攻新四军地方武装','率伪保安团在淮安、洪泽交界地区多次进攻新四军地方武装，烧毁村庄，屠杀抗日军属，强抓壮丁补充伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e22d68703bb40a38ea5389df178742c','9dfe8c6a-13cc-4fac-85de-ce1367bc08e8',1942,'在洪泽湖西岸推行伪化统治','在洪泽湖西岸推行伪化统治，设立税卡盘剥渔民，向日军报告新四军活动情报，组织伪自卫团配合日军“扫荡”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ece490d2fd2477183646da101e22376','da8b710b-520f-4b8a-9ca0-5bd0b4a04ae7',1939,'为日军筹措军饷','为日军筹措军饷，强迫商户捐献物资，控制粮食贸易，将大量大米、棉花低价供给日军，从中牟利，并充当日军经济情报员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06ceab5b231c43bcbab44f92d031bd1d','0b3e1e67-01f4-493e-9d04-3df1b5efb0e5',1939,'协助日军建立伪政权','协助日军建立伪政权，参与策划“自首”运动，诱骗抗日人员投降，破坏地方抗日武装，后升任伪区长。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b895b2f5ad6b45f28ee65bf585b85c81','eb4b0f96-76ab-494f-91fd-86be2182de1a',1943,'率伪军常驻洪泽湖沿岸','率伪军常驻洪泽湖沿岸，专门搜捕新四军伤病员和地方干部，多次偷袭湖上渔船，杀害渔民以震慑抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-333cd99cfdaa436187cc8eaf2dae0802','a7699696-57eb-4073-98a4-ad63318490ca',1939,'投靠日军','投靠日军，任涟水县伪县长，组织伪政权，协助日军推行“清乡”和“治安强化”运动，镇压抗日民众，征收苛捐杂税，残害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
