INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec00f221be5143bf9f281b75eda55605','da4963b6-2ded-468d-ae66-6686532f1614',1941,'在淮安、涟水一带推行日军“清乡”政策','在淮安、涟水一带推行日军“清乡”政策，建立伪保甲制度，组织汉奸情报网，破坏抗日地下组织，多次带日军突袭抗日村庄。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee4ebe9c6dd443d6856b7cb3ddbfbd00','c3153f04-01ff-48c7-8f68-969ac34f9327',1939,'日军占领涟水后率先投敌','日军占领涟水后率先投敌，组织维持会，为日军筹粮派款，强征民夫修筑据点，并出卖抗日志士情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
