INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66df08ef80474a3ca0f5ec6a1411a4b7','8d5d5c30-918d-4bca-82f3-8a8219556503',1942,'率伪军驻防涟水边境','率伪军驻防涟水边境，多次配合日军“扫荡”涟水东部抗日游击区，杀害新四军伤员和进步群众，抢夺粮食牲畜。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2395bca856d442dfa08c99e48044c582','32e16a3c-27a6-4385-b037-a6ab661c64d9',1940,'为日军征收各种苛捐杂税','为日军征收各种苛捐杂税，强征“和平捐”“慰劳金”，中饱私囊，逼得许多农户破产，并举报抗税群众。','危害等级B（乙级，市县厅局级）','hanjian');
