INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-570084b318c949c8903aa34c1df696ec','edd23956-1757-496f-803f-4cb91b1dc672',1943,'率伪绥靖军驻涟水','率伪绥靖军驻涟水，参与日军“铁壁合围”大扫荡，烧毁村庄数十个，杀害无辜百姓，并强抓壮丁补充伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a159473338f64a9d9d01e81eb9523f22','cf58001b-190f-4f1d-9ce9-899e894d8925',1940,'推行奴化教育','推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”，禁止师生谈论抗日，并告发进步教师。','危害等级C（丙级，基层头目）','hanjian');
