INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d60734dd5bd4e1c8a9bf95f9ac7cc1f','64af2b1d-5d5a-49ff-9fef-3cb837bd02cf',1943,'任伪江苏省党部主任委员','任伪江苏省党部主任委员，在淮安地区发展伪党组织，建立情报网，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5407cbdea1c64ebabf96ba69aedc202b','38782b40-d1f4-4e72-9c81-4d23748ca04e',1939,'1939年日军占领淮阴后出任伪县长','1939年日军占领淮阴后出任伪县长，协助日军推行“治安强化”运动，强征民夫修筑碉堡公路，搜刮粮食资敌，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76fc72f743f1430d81b80d3bcea896ee','38782b40-d1f4-4e72-9c81-4d23748ca04e',1939,'投靠日军','投靠日军，任伪淮阴县县长，协助日军推行“治安肃正”，强征粮税，镇压抗日民众，破坏抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09d0db53469f415cba722bd36eb52b7b','2ad48d69-bca8-4720-a74b-dc7310448db0',1940,'组织伪保安队配合日军扫荡淮阴周边抗日根据地','组织伪保安队配合日军扫荡淮阴周边抗日根据地，多次带队捕杀抗日干部和进步群众，烧毁村庄，抢夺财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9eb7d071ec97456cbb240806a69098c1','7aacabb4-cef5-4540-90e4-bb9fcfdc9352',1941,'效忠日军','效忠日军，主持伪警察局，大肆搜捕抗日地下党员和爱国人士，严刑逼供，并协助日军建立特务情报网。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-693c887500a44594aebd66c9b889bd73','050aea7b-c4d3-472d-b8e1-0c860170add2',1942,'推行奴化教育','推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，逼迫学生参加日军庆典，破坏抗日宣传活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b986fa5ed6c4bd18f6ed8f57fe33fa9','194aa543-3aac-4c00-9d77-4783f9e35a68',1939,'为日军筹措军饷','为日军筹措军饷，强制商户缴纳“慰劳金”，垄断粮食和棉布贸易，低价收购农产品供应日军，从中牟利。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-983fd886384144dc9f52d877aadbb1bb','3945f6f3-ecee-4f0e-8d80-3f59b7b4dd65',1940,'增设苛捐杂税','增设苛捐杂税，替日军征收“田赋”和“门牌税”，对抗日家属加倍勒索，逼死多名无力缴税的农民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ae802d734f44c36a8d89906486ff5f3','4c14b0dd-0d6f-42f5-afcb-98ca1eab521d',1943,'隶属日伪特务机关','隶属日伪特务机关，发展汉奸线人，破坏抗日组织，曾参与逮捕并杀害多名新四军交通员和地下党员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db199d5900184b62bc55e4c3e4d48e14','76f53882-f764-4261-89a8-4aa3dbdabeb0',1941,'组织地主武装“自卫团”','组织地主武装“自卫团”，配合日军清乡，在淮阴城郊多次袭击抗日游击队，杀害无辜村民并冒功领赏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cbf0b5ba18b4a0ca3eadbc92e6a8c16','428b6179-e1b0-4d9a-9a06-6e4b0266ba85',1942,'负责为日军征购军粮','负责为日军征购军粮，强征农民口粮，导致多地饥荒，并倒卖粮食给日军换取鸦片和钞票，中饱私囊。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70b67a80dbd64d51a6a17c7354801cf6','295992ea-1222-4746-9be6-3a69475c6217',1940,'主编汉奸报纸《淮阴新报》','主编汉奸报纸《淮阴新报》，鼓吹“大东亚共荣”，污蔑抗日军民，为日军侵略制造舆论，并告密抗日言论。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f34a1b0829a4ea59c8db31b6cc895c6','913f20aa-dcf4-4921-a1b2-abdd107529c1',1941,'在日伪法庭上以“通匪”罪名判处抗日群众死刑或重刑','在日伪法庭上以“通匪”罪名判处抗日群众死刑或重刑，包庇汉奸恶霸，帮助日军镇压反抗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28459379d398468a97ccfe2b9869c31d','917e44b4-10ad-4d27-a671-e35d67d531ec',1942,'率部驻守淮阴重要据点','率部驻守淮阴重要据点，多次伏击抗日武装运输队，抢劫军需物资，并参与“清乡”行动，烧毁民房数十间。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b60f020c47924aff9fab6075c63048c0','79db6ddc-0486-4386-8a71-5a2912a45875',1939,'组织“新民会”汉奸团体','组织“新民会”汉奸团体，推行“中日提携”宣传，诱骗青年参加伪军，收集抗日情报提供给日军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c566a98c9904423db9ae92907221494e','7a0328ca-eab4-40d5-a89e-ce1fb3115e05',1940,'把持运河淮阴段船捐','把持运河淮阴段船捐，对过往商船强征重税，为日军运输物资提供便利，并扣留抗日物资船只。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f99150a1a0f4994bc636052b009d9fc','ccf72d5e-665c-4df3-9edb-2b39ffd9d9aa',1939,'日军初占淮阴时组织维持会','日军初占淮阴时组织维持会，协助日军建立伪政权，为日军带路搜捕抗日人士，后调任伪区公所区长。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef19abd2b9164e0c8a88c10f050b40b3','af1aa9aa-c5a9-48af-83b4-1d38902160d7',1941,'在淮阴城西一带强征壮丁补充伪军','在淮阴城西一带强征壮丁补充伪军，镇压农民抗捐运动，多次向日军报告新四军活动，导致游击队遭袭。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e474ee87c54a4d2ca92699a2100f2100','90684124-6064-4bd5-8882-c574cd93e6f8',1942,'配合日军“扫荡”王营、码头等地','配合日军“扫荡”王营、码头等地，组织“区自卫队”袭击抗日民兵，并强征民夫修建日军据点。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac169629b9c04930b44064ada58e09d7','e61a5e92-8ddb-4f55-8563-6062a39d3e16',1943,'专门刺探新四军和抗日政府情报','专门刺探新四军和抗日政府情报，多次导致抗日干部被捕，曾亲自带队抓捕淮阴县抗日民主政府交通员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
