INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd92410a8e014bc1a3386f4880827e59','3d173f97-3b64-4120-922c-0d62d81247df',1939,'投靠日军','投靠日军，任淮阴县伪县长，协助日军推行“治安肃正”，强征粮税，镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
