INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1350d5ee1ff4d58b856214704e161b2','0a135488-334e-4689-9fa4-4f144e86cdfa',1940,'任伪盱眙县税务局局长','任伪盱眙县税务局局长，为日军征收各种附加税，盘剥百姓，将大量粮食和钱财供给日军军需。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9b03bd8bc254ba999a6d9751d7a87f7','be445c71-2ede-4436-bddb-4131b7fe485f',1939,'日军占领金沟镇后','日军占领金沟镇后，组织维持会，为日军征粮派款，协助维持殖民秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
