INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cf34c3e36944fe2a40ee1c896be1b9c','9be4a855-3ad3-4ea1-aee8-d3eff7582a9a',1941,'为日军征收各种苛捐杂税','为日军征收各种苛捐杂税，包括“和平税”、“慰劳金”，搜刮民财，中饱私囊，并强迫商户购买日货。','危害等级B（乙级，市县厅局级）','hanjian');
