INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1584abe9bb84c30bfc16c81a7fec2b3','59ed5ff1-7ccf-4e03-b6a5-4e286a73d5e3',1942,'在盐城、滨海推行“清乡”政策','在盐城、滨海推行“清乡”政策，组织保甲制度，搜捕新四军伤员和地下党员，烧毁村庄。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
