INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df1a2a43ae55492fac3abb8e35c61f4c','3a013b82-4246-4aea-b03e-1b4932538982',1938,'1938年任伪江苏省长','1938年任伪江苏省长，驻镇江，大力推行清乡、保甲制度，镇压抗日力量，搜刮民财，是江苏地区主要汉奸头目。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
