INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39501af5620148b9b75cdbbd9aa9adef','b5f68a8c-9065-4fe2-871e-a646cd784dab',1938,'任伪县知事期间','任伪县知事期间，推行保甲制度，强征壮丁，配合日军清乡扫荡，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
