INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ea3274691f2403c8b516f28597e84b9','d2746098-a33e-42af-979f-58c5c170c598',1940,'组建伪保安队','组建伪保安队，配合日军“扫荡”，在扬中沿江地区设卡盘查，截获抗日物资，逮捕进步人士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9791bc92f45a4c558df7a280a658bdf0','88c42b4a-50c4-482a-be9c-171c60d45a87',1941,'在镇江、扬中一带推行“清乡”政策','在镇江、扬中一带推行“清乡”政策，建立伪基层政权，强征捐税，参与围剿新四军游击队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3e70b1bd3834ccabb8491d6d5255d76','a0763947-7fb0-43c2-8056-000529d34f24',1940,'为日军征收苛捐杂税','为日军征收苛捐杂税，垄断粮食贸易，克扣民财，资助伪军军费，民愤极大。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df63501cf56b4c8991acecaca8a078a2','f00ef17c-7a98-4426-b223-ed0270a04c25',1942,'推行奴化教育','推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，破坏抗日宣传。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b2d8ba8b943c49a2a160e5d98bae24a9','7a5b35d0-1900-4a41-a5bd-5137aea9150a',1942,'在镇江、扬中地区发展特务网络','在镇江、扬中地区发展特务网络，刺探新四军情报，多次导致抗日交通站被破坏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19858ee2db264574b35f46934a053a5e','4a109245-9711-4634-aa70-a300c2662f9b',1938,'组织商会为日军筹集军饷','组织商会为日军筹集军饷，强迫商户捐献，并暗中向日军出售粮食、棉花等战略物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d87fdb6e1e3046a0b3ad80f6f4afbdc8','1be803b2-6527-4ab7-bdbe-ab14718a18f0',1943,'率自卫团协助日军封锁长江渡口','率自卫团协助日军封锁长江渡口，参与抓捕抗日干部，并参与屠杀无辜村民事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0f409e5fb3540acb7c7c0f1f5fd8341','3c4d3d53-a758-48e6-9986-559a3bdb8e81',1937,'曾任伪华北临时政府要职','曾任伪华北临时政府要职，后任伪江苏省长，虽未实际到镇江，但名义上管辖江苏地区，积极推行日伪统治政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c82b38b7670f4924b88811f61953dacc','cefd9c52-1229-4d39-aad5-73c542faf8d5',1941,'1941年任伪江苏省长','1941年任伪江苏省长，驻镇江，同时领导76号特工，在江苏及镇江地区大肆捕杀抗日志士，制造白色恐怖。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2304e6f139ff4688a34f4ef5dbdfcc28','dcb881c2-853a-4278-915e-d9640f15f765',1940,'虽主要在上海','虽主要在上海，但作为汪伪核心人物，对江苏及镇江的伪政权有指导权，参与策划清乡和物资统制，间接祸害镇江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a28de5f3ffb3466daf6fa03798f3c7b2','0f0478ec-0d04-44db-b660-736c0cc340dd',1939,'作为76号特工头目之一','作为76号特工头目之一，曾指挥特工在镇江地区进行暗杀、绑架，破坏抗日活动，后任伪职继续为日效力。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bac88c3b392e41108469f3b170a357c1','f1c45bce-a97b-437a-a1c2-89a1e492e729',1940,'汪伪骨干','汪伪骨干，参与制定清乡法令，对江苏包括镇江地区的伪政权运作有直接影响，协助日军维持殖民秩序。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-857096fac9ce4a82ae83c73fb2ed12f2','063ba861-b76e-4a8d-8f8a-11a03061ba4c',1940,'汪伪经济决策者','汪伪经济决策者，在江苏推行经济统制，掠夺镇江等地的粮食和物资，导致民不聊生。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
