INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-277512995ace476aa3fa76ab04c2590d','fa2c2c4c-beef-4a68-8302-f6a96d0c1859',1940,'推行奴化教育政策','推行奴化教育政策，在镇江各学校强制教授日语和伪满课程，毒害青少年。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be157faeb36b4fbc9432dcdd6299f4c8','abf7f866-dbb9-42ad-b9b8-646b27777b95',1941,'辅佐李士群管理江苏政务','辅佐李士群管理江苏政务，具体执行清乡和保甲制度，在镇江地区组织伪警察和情报网。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a6085b19b114d2b8f1496dacb5d4873','386bdfc9-1ca7-4143-a96b-d45d41c8f773',1942,'公开身份为伪江苏省参事','公开身份为伪江苏省参事，参与伪政权活动，虽后被认为有地下工作，但当时在镇江地区为日伪服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
