INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63b4422a962149c496865a1b04f9b0f5','67e2b674-06bf-4d7e-a001-88d008bb464b',1940,'负责伪国民党在江苏的组织','负责伪国民党在江苏的组织，在镇江发展党员，协助日伪控制基层社会。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47bb4eaae81243c795880d833175fa09','52be348a-5d50-4cb1-b153-2ee4beea74c1',1939,'指挥伪警察在镇江城区搜捕抗日分子','指挥伪警察在镇江城区搜捕抗日分子，镇压罢工和抗议，为日军维持治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df419bae4e594a61919f341fa0700121','0f9823c0-1e68-4c84-84a2-701c8d3b51fa',1940,'统领伪保安队','统领伪保安队，配合日军扫荡镇江周边乡村，烧杀抢掠，破坏新四军根据地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d358ce13f784c1bb7c3910aab0617e7','bd751c07-57dd-4d45-8c3b-ba632af71b38',1941,'在镇江推行奴化教育','在镇江推行奴化教育，解散爱国学校，迫害进步教师，强制学生参加日伪庆典。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f85142d94ed64005806a7fca9cf50415','ab72f370-35d5-4c1c-a377-7d64249e74f9',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会委员长等职，推行奴化教育、配合日军掠夺华北资源，虽非上饶籍，但其伪政权体系曾延伸影响江西部分沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d75f41f06024ccba8a4d3978b8eccda','ab72f370-35d5-4c1c-a377-7d64249e74f9',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投靠日本，任伪华北政务委员会委员长等职，参与伪政权统治，虽非江西籍，但其伪政权体系覆盖包括江西在内的沦陷区相关事务。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a5bcb86cfeb4a92a31695b83c976f86','ab72f370-35d5-4c1c-a377-7d64249e74f9',1937,'江西籍汉奸代表人物之一','江西籍汉奸代表人物之一，原籍安徽但长期在江西活动，抗战期间投靠日军，历任伪华北政务委员会委员长等职，推行奴化教育，协助日军掠夺资源。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27cb963d092c4583bad60912d7d197f0','ab72f370-35d5-4c1c-a377-7d64249e74f9',1937,'江西九江人','江西九江人，北洋政客，抗战期间投靠日本，任伪华北政务委员会委员长等职，推行奴化教育、配合日军掠夺华北资源，虽主要活动于华北，但作为江西籍汉奸代表人物被记录。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-394b1967ba5a4fe08e02c17fa59866cd','d34d4877-fcc8-454a-bbf1-78c757aab11f',1938,'广东乳源人','广东乳源人，汪伪政权核心人物之一，曾任伪立法院长、伪上海市长等职，参与汪伪政权对江西等沦陷区的统治与掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b81b526b00124aeabb4b4b5368467a8d','d34d4877-fcc8-454a-bbf1-78c757aab11f',1938,'汪伪政权核心人物','汪伪政权核心人物，参与伪化江西等沦陷区统治，配合日军在九江地区的经济掠夺与治安强化。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b7d6e0bf613421791d435dc6f2c57dd','4d06482f-5fc0-44ce-b6c4-c1e67de0b7ab',1938,'广东人','广东人，曾任伪上海特别市市长，后调任伪江西省长，直接参与江西沦陷区的伪政权统治与资源掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-721f02d4960d4f2c90b26e9077aaa67e','72b16fd0-f7b4-4c0f-bc53-cce3aa0711f3',1938,'江苏人','江苏人，汪伪政权地方大员，曾任伪江西省长，在江西沦陷区推行奴化教育、征粮征丁，配合日军“清乡”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2dde0e814c634cf386c682202c31d965','72b16fd0-f7b4-4c0f-bc53-cce3aa0711f3',1938,'江苏崇明人','江苏崇明人，投敌后曾任伪江西省长，直接负责江西沦陷区伪政权事务，推行日军殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-766c7470e63c4fcc82048635c3f52125','fb14639a-868b-4e39-9b1b-cd972c0546e9',1939,'江西人','江西人，汪伪政权在江西的地方官员，曾任伪南昌市长，协助日军维持南昌及周边占领区秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ee8de24ba4c44568ee42e69eb455a68','fb14639a-868b-4e39-9b1b-cd972c0546e9',1939,'在江西日占区参与伪政权','在江西日占区参与伪政权，推行日军殖民统治政策。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c97a9b1f20a042af9f4743ec8bc1320b','fb14639a-868b-4e39-9b1b-cd972c0546e9',1939,'江西人','江西人，投敌后任伪江西省及南昌市要职，协助日军统治江西沦陷区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07c91cd7d19e40858a2f7138a5afefd2','216f73c8-18f3-4b73-a55d-66cc9a41188d',1940,'浙江人','浙江人，原军统人员后投敌，任汪伪税警总团要职，其伪军部队曾活动于江西及周边地区，配合日军作战。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-87a3e2af00ea4e7e9fb1b79383c2df54','216f73c8-18f3-4b73-a55d-66cc9a41188d',1940,'浙江昌化人','浙江昌化人，原国民党军官，后投敌任伪军要职，在华中地区包括江西周边进行伪军活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86a8b3385c844618a2f298d974c5c723','216f73c8-18f3-4b73-a55d-66cc9a41188d',1940,'汪伪伪军头目','汪伪伪军头目，其部队在湖北地区配合日军作战，参与清乡扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96127760ff704b048c8ebe9acf2a5cc2','216f73c8-18f3-4b73-a55d-66cc9a41188d',1940,'湖北人','湖北人，抗战期间投敌，在湖北、江苏等地率伪军配合日军作战，参与对湖北抗日根据地的扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fc13ed8edfe4e67aeaa5bb97fd6664a','87924e3c-8ade-4d48-a7f7-ff595d933e2a',1940,'广东人','广东人，汪伪政权军事将领，曾任伪江西保安司令，率伪军配合日军在江西沦陷区“扫荡”抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e497b3cd45c3494788ea9b0c83745a3c','53b0e6ad-ed41-400a-ba27-8cfede0bf553',1941,'江西人','江西人，汪伪政权军事人员，曾任伪江西省保安副司令，协助日军在江西沦陷区维持治安、镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7907df5e9fe5486197fec69b7206e4c2','2c4c999a-9ae5-4a7b-9f5b-74c099ca7a8d',1940,'江西人','江西人，汪伪政权在江西的地方官员，负责伪建设厅，配合日军掠夺江西资源、修建军事设施。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0cd9aa3fc694784bb6a45a483652aae','b9420052-898f-49c7-89dc-648a5c1f58f8',1941,'江西人','江西人，汪伪政权在江西的警务头目，掌管伪警察力量，参与搜捕抗日人员、推行保甲连坐。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a838ed45167f499dba4b453a38c6f690','81c05b87-c4df-4a8a-8a1a-769d0b6d3af6',1940,'江西人','江西人，汪伪政权在江西的文化宣传官员，曾任伪南昌县长，推行奴化教育、控制舆论，为日军侵略辩护。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc8c8f559d06442a8c04c3d2ac6f5933','87a3ca88-7d14-4681-920a-84b9eb800d5f',1942,'江西上饶人','江西上饶人，日军侵占上饶期间组织伪维持会，任会长，为日军征粮征夫、维持占领区秩序，协助日军统治上饶地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-191cbca296f94e238fd243f5b5f61eac','7c3d3c25-b019-4bb8-9942-ea606ba26dc9',1942,'江西上饶人','江西上饶人，伪上饶县警察局长，配合日军搜捕抗日分子、镇压民众反抗，维持上饶沦陷区治安。','危害等级B（乙级，市县厅局级）','hanjian');
