INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d94b451b25146958877d4919853ea89','72284b90-cc03-49db-9e88-5aa88cbf1dfb',1940,'上饶地区抗战时期部分伪警察人员名录散见于地方志','上饶地区抗战时期部分伪警察人员名录散见于地方志，但德兴、上饶具体汉奸个案公开可靠记载极少。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
