INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17427f32d5874166a29d9186fed88e31','9e9b5ac5-8c7d-428f-878d-4d395191f22f',1940,'赣东北部分保甲长在日军占领期间被迫或主动附逆','赣东北部分保甲长在日军占领期间被迫或主动附逆，但德兴、上饶具体个案缺乏可靠公开记录。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-113d6f979d32469ba90d16ac605396bf','b9f7d3d1-e47f-41bf-a625-4373be1359d4',NULL,'经核查','经核查，黄道为中共闽浙赣省委领导人，非汉奸，故不列入。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75db427274c541118d79c54148db2245','25483fba-0241-4d33-be16-4501f42b232e',1942,'浙赣会战期间日军侵占玉山后','浙赣会战期间日军侵占玉山后，出面组织伪维持会，为日军征派民夫、粮食，维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71309491ea914d0ca3d216c5e151a4d0','fea762a9-2f65-4b15-af59-4882245832fa',1942,'1942年浙赣会战日军攻陷上饶期间','1942年浙赣会战日军攻陷上饶期间，组织伪维持会，协助日军搜刮物资、登记户口、诱迫民众返城。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76dd05b02e514d64a4de7dfb5969fb6e','fea762a9-2f65-4b15-af59-4882245832fa',1942,'上饶沦陷期间受日军指使筹组伪维持会','上饶沦陷期间受日军指使筹组伪维持会，负责摊派捐款、物资和民夫，配合日军对赣东北地区的控制。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47c420366d0b406f8e829db6637080f3','6653b2cc-e155-4afb-8fe4-10509d214e08',1942,'日军占领上饶期间出任伪警察局长','日军占领上饶期间出任伪警察局长，率伪警配合日军清查抗日人员、维持治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ffa1cbe30624a3ba91d3478bc1ba977','ca0a3a4e-41bf-49e9-ab9d-f44fc788b7c9',1942,'浙赣会战期间在江西沦陷区参与筹组伪政权','浙赣会战期间在江西沦陷区参与筹组伪政权，联络上饶、玉山等地维持会，为日军提供情报与物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-832ab40a74e845d191806393a6f293e5','e2d731c8-838e-47f5-add0-7429de957b68',1939,'江西沦陷区早期伪维持会头目之一','江西沦陷区早期伪维持会头目之一，其活动虽以南昌为中心，但伪江西省政权系统覆盖上饶、玉山等地，为日军在赣东北的统治提供支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cec7b5d49c574971b64d08b209e42b26','ed44529e-c36c-4924-9abc-24ec46544112',1943,'在伪江西省政府任职期间','在伪江西省政府任职期间，参与推行日军在赣东北的保甲连坐与物资统制政策，影响范围包括上饶、玉山。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa31dd3766084553ab6afecb15c3bf87','5c2a564b-7554-495c-b273-a939654a1633',1942,'日军侵占玉山后投敌','日军侵占玉山后投敌，率地方武装改编为伪保安队，配合日军下乡扫荡、搜捕抗日游击人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c92c9091e95440c8e1aa367b0d56a00','741e6f8e-4410-44f4-945e-18bed6170c6f',1942,'在伪政权中负责教育事务','在伪政权中负责教育事务，推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a090baf561c04062b0eb9a1d21519a8f','392b2e0c-8006-47dc-bec1-7b84b62fe8a9',1942,'日军占领上饶期间出面组织商会','日军占领上饶期间出面组织商会，为日军摊派款项、征集物资，协助维持占领区经济秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d5006f8456f4ef187272f90796d11a0','b57fa073-5dd2-4c2c-aa41-5f525d2e36b5',1942,'在玉山沦陷期间担任保甲长','在玉山沦陷期间担任保甲长，为日军征派民夫、报告抗日人员行踪，协助维持基层统治。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3fad83b85b247bfa16bcea9d5610f03','6864b0ae-b814-4f43-86c9-8dd7a364f0b1',1938,'日军侵占鄱阳期间出面组织伪维持会','日军侵占鄱阳期间出面组织伪维持会，为日军征粮派款、维持地方秩序，协助日军控制鄱阳城乡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b7315b37224460388940ac7e57ce048','0fb57bfa-c259-46ff-9de3-227e5dcd763c',1941,'在日军扶植下出任伪鄱阳县政府县长','在日军扶植下出任伪鄱阳县政府县长，推行伪政令，配合日军清乡、征粮、拉夫，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb52bd8c27a4407998ab745334dffe8d','2c9965dd-c0ed-4eb5-99cb-d97a51d7733e',1942,'浙赣会战期间上饶沦陷后','浙赣会战期间上饶沦陷后，出面组织伪维持会，为日军筹粮、派夫、搜集情报，协助日军维持占领区统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1bfc397db7b142ca916f3a0f75626668','e425a9dd-59f7-46b5-8be9-42ec2acc3765',1942,'日军占领上饶期间任伪县长','日军占领上饶期间任伪县长，建立伪政权机构，推行保甲连坐，配合日军对抗日根据地进行封锁和扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b24fb7c0a1834c59b6d5b9ceedef6204','7c4bfd4b-c0bc-418f-90a0-6943d921cc77',1939,'在南昌等地参与组织伪江西省维持会','在南昌等地参与组织伪江西省维持会，协助日军在江西占领区推行伪化统治，为日军提供情报和物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-181474170af74cd1b60982fb88be6121','24c11544-f011-4ff7-bb10-cb4a5a5b7639',1939,'南昌沦陷后组织伪维持会','南昌沦陷后组织伪维持会，为日军征粮、派款、拉夫，协助日军维持南昌及周边地区治安。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e151095d21ab43d98a20383d6d6cfdc9','11c5b0a9-4341-4a99-be20-8af97f48fb35',1940,'在日军扶植下参与伪江西省政府事务','在日军扶植下参与伪江西省政府事务，推行伪政令，协助日军在江西占领区进行经济掠夺和思想控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
