INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a42ad215120440a0a17dfd8567a07f35','93d628d0-36f1-4b27-ba1b-17ac879b4a78',1942,'任伪上饶县警察局局长','任伪上饶县警察局局长，协助日军维持占领区治安，搜捕抗日分子，推行保甲制度，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13d37896ecb54f2bbb80bd250f122757','05ea0edd-04f1-4960-a133-0bf9c9c2704a',1942,'组织伪保安团配合日军作战','组织伪保安团配合日军作战，参与对赣东北抗日根据地的清乡扫荡，抓捕抗日人员，抢掠民财。','危害等级C（丙级，基层头目）','hanjian');
