INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9356507cdc647cab8d0b98b63d7086e','690f4c09-d9eb-4748-b2c3-b8c078d1ce7e',1942,'在日军占领上饶期间出任伪警察头目','在日军占领上饶期间出任伪警察头目，带领伪警搜捕抗日人员、镇压民众反抗，并为日军搜集情报。','危害等级B（乙级，市县厅局级）','hanjian');
