INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5c2763b8aac489cb2139fbc66b939d7','667adf17-401b-4126-b411-587c51cc17e8',1942,'江西沦陷区部分附逆人员之一','江西沦陷区部分附逆人员之一，在伪省政府中挂名参议，为日军统治江西提供地方联络与舆论配合。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
