INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b76c3c30b28c4e22ba62b6d79dc33f90','67242927-e4ab-4159-8ec4-abcb0b1e6ed0',1942,'以商会名义为日军筹款筹粮','以商会名义为日军筹款筹粮，强制商户交纳“慰劳金”，并协助日军管制物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75be8bd00cb64a1c95b6adbfa023be39','f17ec7ef-89b5-4c1b-af05-64ef5e170006',1938,'福建人','福建人，在南京伪政权中历任要职，参与伪维新政府及汪伪政权，协助日军推行治安强化运动，其势力范围涵盖江西周边沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
