INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b3075f861bf4db2a9210b03b53671a4','842db85b-5f85-426f-a5f8-b5c66a819fd9',1938,'福建人','福建人，早年曾在江西九江、庐山活动，抗战期间投靠汪伪政权，历任伪内政部部长、伪江苏省省长等职，协助日军推行治安强化运动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6900774bc03a40a5971df3a584d6c86a','9f78bf95-74fd-4ebc-86bd-9988a234d867',1938,'九江本地士绅','九江本地士绅，1938年日军侵占九江后出面组织伪维持会，后任伪九江县长，为日军征粮征夫、维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e348729c1d134440b4ea0d72bb886128','80c8d8d0-dfd8-4d76-a0d5-1f1b7853aa71',1938,'九江商人','九江商人，抗战期间依附日军，出任伪九江商会会长，为日军筹款筹物，协助控制九江经济。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-376721fee0bc4d5ba6064dbd23032655','7095d2c9-1258-4773-be9a-5b897509fc87',1939,'广东梅县人','广东梅县人，作家，抗战期间投靠汪伪政权，曾任伪江西省政府委员，在江西等地进行亲日文化宣传。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56ab503efbd34f0dad9741b2de2c172c','bbc92a9b-3b8c-4edc-89cb-494d8db34dcd',1940,'江西人','江西人，汪伪政权任命其为伪江西省政府主席，在南昌、九江等地组织伪政权，配合日军统治江西沦陷区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a228643409e84aefb7dad63cd793a964','678ca3aa-69b2-42c0-aad1-5eeb1fc29f81',1938,'九江人','九江人，日军占领九江后出任伪警察局局长，协助日军搜捕抗日人士、维持伪治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92846a3bd2f9488193ee513e57787a8a','c112671b-a467-49eb-9ddc-7ecf61e94cd7',1939,'抗战期间庐山沦陷后','抗战期间庐山沦陷后，出任伪庐山管理局局长，为日军管理庐山景区及周边地区，协助征发民夫。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d427e8619d84a0f9de14bb5308aa64f','f6abcf17-3d20-454b-a2aa-5f11808cc3f5',1938,'九江地方武装头目','九江地方武装头目，投靠日军后任伪九江保安团团长，配合日军扫荡九江周边抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a6615ba4c03480f9bf339a65578ab0d','7ac8aee2-6c5f-488b-bd7b-a62475a0ce1c',1939,'江西人','江西人，汪伪政权时期任伪江西省政府委员、伪南昌市长，其活动范围覆盖九江、庐山一带，协助日军推行伪化教育。','危害等级B（乙级，市县厅局级）','hanjian');
