INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-512b2e971468485987e49e507e453251','14944a16-dd38-4b1e-82c8-92e17cf86317',1938,'抗日战争时期','抗日战争时期，日本侵略者曾试图拉拢吴佩孚出面组织伪政权，吴佩孚虽未公开附逆，但日方在九江、武汉等地对其反复诱降，其态度暧昧，客观上被日伪利用来影响江西、九江一带的所谓‘和平’舆论。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
