INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbd23ec492234ef68361ae12c084a7c5','db5adcf2-819a-4058-a2d4-62a86434edae',1944,'日军占领江西部分地区后','日军占领江西部分地区后，被推为伪江西省政府主席，在南昌、吉安等沦陷区组织伪政权，为日军征粮、征夫、维持统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79964de7661940cd92e9f1eb96d2fb5a','4077af5a-3eac-405f-8916-c506154b9c34',1944,'有资料称其在江西沦陷后与日伪有接触','有资料称其在江西沦陷后与日伪有接触，但主要历史记载仍以其战前主赣及后方任职为主，附逆情节存疑，仅列备考。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-137ee78cd6f9408abfd8df5143cc86fd','33a02a6c-04eb-44b2-b7b7-648869331a93',1944,'地方口述史料提及其在吉安沦陷期间曾参与维持会活动','地方口述史料提及其在吉安沦陷期间曾参与维持会活动，但缺乏确凿档案佐证，仅列备考。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62131a1c935942d18e2ee89563f18d25','152a3eaf-d4f0-4763-b384-8d2661e447e6',1944,'部分野史称其在江西沦陷区与日伪合作','部分野史称其在江西沦陷区与日伪合作，但正史无明确记载，仅列备考。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d79919f6dfb74f4f95f68d8f6f3107b4','1928ea66-73d4-4e90-8c32-a79f2a44a644',1944,'吉安沦陷期间','吉安沦陷期间，出面组织地方维持会，任会长，为日军筹粮、派夫、维持地方秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a517c8a6427e442aacb7374835ce20b2','e58cc4a5-dcd8-4c91-9846-fd45b9dcf359',1944,'在吉安农村地区担任伪保甲长、伪乡长','在吉安农村地区担任伪保甲长、伪乡长，协助日军征粮、征丁，镇压抗日群众。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2929b0ab43f44c9d9d3852505e012de2','238d8204-3f1f-4396-910e-0c9b0af93be2',1944,'吉安沦陷期间','吉安沦陷期间，以商会会长身份与日伪合作，为日军筹款、筹粮，协助维持占领区经济秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e3c71cb4a34468cb9e862bb3c4b622f','8b455bcf-5371-4e92-93f2-191feedb9693',1944,'地方史料提及其在吉安沦陷期间参与伪教育机构','地方史料提及其在吉安沦陷期间参与伪教育机构，推行奴化教育，但记载简略，仅列备考。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8bc036cd9ac4861b545f18a53d2e7d4','c2bf4bc9-6c53-4525-bb92-b817a6743f15',1939,'安福县地方士绅','安福县地方士绅，日军侵占赣中期间出面组织伪安福县维持会，协助日军征粮、派夫、维持地方秩序，为日军在安福地区的统治服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80bc0a0936d74f1d8bf3c2e96b7ca9a1','1dcbbe2c-b260-40ce-8097-6aba5afa13dc',1940,'在汪伪江西省政府警务系统任职','在汪伪江西省政府警务系统任职，参与侦捕抗日人员、镇压民众抗日活动，其警务活动范围覆盖吉安、安福一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab4065978dd84b1db0922385b7737cf2','69570529-7c32-4a99-9a1d-56e6acaa725e',1940,'率伪保安队在安福及邻近地区配合日军扫荡','率伪保安队在安福及邻近地区配合日军扫荡，搜捕抗日游击队员，强征民夫修筑据点。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf8d59062eac4c7cb5a550ee9278110d','a8d79c72-6608-4ffe-bd25-3b67fbab854e',1939,'吉安地方商人','吉安地方商人，日军侵占吉安期间出面组织维持会，为日军筹款筹粮，协助推行伪化教育。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a04d781a8174ed294f1ca2dc01d7d80','51226a04-592a-477b-8788-a604e65681ce',1941,'在汪伪江西宣传机构任职','在汪伪江西宣传机构任职，撰写亲日文章，鼓吹“和平建国”，配合日军在吉安、安福等地的文化宣传与奴化教育。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b78697d5b43f452da3302d1f3f1b68e9','49e40949-6dce-464c-9a00-5a9e799037f4',1941,'任伪安福县警察所所长','任伪安福县警察所所长，带领伪警察配合日军搜查抗日分子，勒索民众，维持伪政权在安福的基层统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bbba1aa593a64308b2963643c13344ee','ac0dd8b4-f59d-488e-863d-5436ee5ca1e5',1943,'受汪伪江西省政府委派','受汪伪江西省政府委派，在吉安地区推行“清乡”运动，配合日军封锁抗日根据地，抓捕抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0f260f427c847b199afb047aae12a07','28852ff9-5ba7-4d0e-942a-5aa73fa53429',1942,'在安福推行奴化教育','在安福推行奴化教育，强制学校使用伪编教材，向学生灌输亲日思想，为日伪统治培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb5ac061c919434fba2a000cac5902a0','49b80bce-0658-4d4d-bbd8-b5f8b84ccb0c',1940,'抗日战争时期在峡江地区组织伪维持会','抗日战争时期在峡江地区组织伪维持会，协助日军维持占领区秩序、征派粮款夫役。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-724673cf437949bf892db2b51f2759ba','92acac3a-df3f-4a7b-82aa-f909fa1b8ecb',1940,'在吉安一带依附日军','在吉安一带依附日军，参与组织伪维持会，为日军搜集情报、征派物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f97f098ecfb4e13ae778b6e9c359f24','892b1f89-83a1-440c-9191-184888876b6f',1939,'在伪江西省政府系统内任职','在伪江西省政府系统内任职，协助日伪推行保甲连坐、搜捕抗日人员，活动范围覆盖吉安周边。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07bff3d600cc42ee898ce562d66e5a08','429a16ea-925b-4e60-9c20-cf953231855c',1940,'担任伪吉安县警察局长期间','担任伪吉安县警察局长期间，配合日军清乡，逮捕抗日群众，镇压地方抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e37e9703fa8d45a3885f253bf00bcabb','c750f18e-b2a1-443a-b20f-15c947b4cb8a',1940,'在吉安地区担任伪保甲长','在吉安地区担任伪保甲长，为日军征派民夫、粮食，监视并举报抗日分子。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdb343d0057f4bf1b9625cf682e99d3c','92baa506-4321-4df8-98c4-0ea060bb4ea8',1940,'在伪江西省宣传机构任职','在伪江西省宣传机构任职，参与日伪奴化宣传，活动涉及吉安地区教育文化领域。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4137e29cb05c492ab493307b406de8bb','6c4299b5-f8c8-4652-a462-4b320e7e2eb4',1941,'控制吉安地区物资配给','控制吉安地区物资配给，为日军掠夺粮食和战略物资，协助经济统制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16939f586799437684a5a841b519971e','df88595f-bde3-435e-bfdd-48aef4d4e678',1940,'率领伪保安队在峡江及周边配合日军扫荡','率领伪保安队在峡江及周边配合日军扫荡，袭击抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b77eea3ebc054e9fa78ae7b6d8f07349','6220210a-17d2-4f84-8896-7f1131a7d81f',1938,'广东乳源人','广东乳源人，随汪精卫投敌，任汪伪政府要职，其伪政权统治区域包括江西沦陷区，对江西伪政权有统辖关系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0295abd3c86c47848cfee7220ab61ab5','6220210a-17d2-4f84-8896-7f1131a7d81f',1938,'虽为广东人','虽为广东人，但作为汪伪政权核心，其伪政权统治体系覆盖湖南沦陷区，间接影响株洲芦淞一带的伪政权运作。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92872eabaf5b41cc8677dd21e1aa871c','6220210a-17d2-4f84-8896-7f1131a7d81f',1938,'虽为广东人','虽为广东人，但作为汪伪政权主要头目，其伪政权统治覆盖包括湖南在内的华中沦陷区，对湖南伪政权有统辖关系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd4646353a6f4bc6aa20d3885a954237','6220210a-17d2-4f84-8896-7f1131a7d81f',1938,'湖南籍？实为广东乳源人','湖南籍？实为广东乳源人，但长期在汪伪政权任要职，其伪政权体系对湖南沦陷区有管辖影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e9712d68efc4564ae080d437c643d64','f0cf6503-4776-4c28-933d-9b72d7e1b505',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物，掌管财政与警政，其伪政权体系延伸至江西沦陷区，对当地伪军伪警有控制关系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c9502730b9d4c28a448b091d4205783','a13bfd0c-f5a6-4b94-8d8b-8e9535b209af',1943,'河南阌乡人','河南阌乡人，原国民党军将领，投敌后任伪淮海省要职，其伪政权与江西沦陷区伪政权同属汪伪体系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b3f19554df448a9aa7421b5e41d34f7','a13bfd0c-f5a6-4b94-8d8b-8e9535b209af',1943,'河南阌乡人','河南阌乡人，抗战期间投敌，在苏北、豫东一带组建伪军，配合日军进攻抗日根据地，对河南包括南阳地区造成威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df7adc68162b46eeaf4f4f7f787a6ec9','a13bfd0c-f5a6-4b94-8d8b-8e9535b209af',1943,'原国民党将领','原国民党将领，1943年投敌，任伪淮海省省长，管辖苏北、皖北、豫东部分地区，配合日军扫荡抗日根据地，其势力范围与南阳地区有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-249d848216cd4e128927c3be12af7323','a13bfd0c-f5a6-4b94-8d8b-8e9535b209af',1943,'河南阌乡人','河南阌乡人，原国民党军将领，1943年投敌，任伪淮海省要职，在苏北、豫东一带配合日军维持伪统治，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-349aea3e6a33438bb07c39220d0e2ce0','a13bfd0c-f5a6-4b94-8d8b-8e9535b209af',1943,'抗战末期投敌','抗战末期投敌，任伪淮海省省长兼保安司令，其伪政权与河南东部相邻，曾配合日军在豫东地区行动，间接影响郑州周边。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c832588a5184efaae0ecd2bf88d793d','a13bfd0c-f5a6-4b94-8d8b-8e9535b209af',1943,'抗战后期投敌','抗战后期投敌，任伪淮海省省长，其伪政权与河南伪政权有联系，所部伪军活动范围一度接近豫南驻马店地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b20eab736d54c9eade83871cd195d0f','a13bfd0c-f5a6-4b94-8d8b-8e9535b209af',1943,'原国民党将领','原国民党将领，1943年投敌，任伪淮海省省长，其伪政权与河南东部相邻，对豫南驻马店地区有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab227a802e684d42b205b4e2b56924c3','a13bfd0c-f5a6-4b94-8d8b-8e9535b209af',1943,'河南人','河南人，投敌后任伪淮海省要职，活动于苏北、皖北，与湖南无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a08d8d5baa143b8908e8e2dc2695c3a','a13bfd0c-f5a6-4b94-8d8b-8e9535b209af',1943,'在江苏、安徽、河南、湖南交界地区组织伪军','在江苏、安徽、河南、湖南交界地区组织伪军，配合日军进攻湖南，参与伪政权统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f232c5f1537d44f99363fe35d88f851a','896d0b95-c0d3-425a-9131-5fc1c5cba38b',1940,'浙江乐清人','浙江乐清人，投敌后任伪浙江省长等职，其伪政权与江西接壤，对江西沦陷区有辐射影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
