INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67a6637971b84ecfaa414fd5580f10a6','37955b54-28f3-40c2-9002-bc7e209b6bb6',1944,'在吉安地区推行奴化教育','在吉安地区推行奴化教育，协助日军宣传“大东亚共荣圈”，毒害青年学生，为日伪统治培养顺民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
