INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-963032b23d2c4affbcd733468e02a4b6','68b9c20f-1d1b-49d2-af72-3ca5abff9774',1931,'抗战期间在江西主政','抗战期间在江西主政，后期与汪伪政权有联系，其部下在宜春、万载一带推行妥协政策，被指为附逆行为。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b14f913726494f168c4c4a00a165e6f3','68b9c20f-1d1b-49d2-af72-3ca5abff9774',1931,'原国民党江西省主席','原国民党江西省主席，抗战后期与日伪方面有联系，其部分旧部在江西沦陷区参与维持会活动，对宜春、上高一带的伪政权建立有间接影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2527588ecc0403baa83427a96879d48','0bf3d772-6aa9-417c-9836-a2597f742e38',1937,'在江西周边地区协助日军推行伪化统治','在江西周边地区协助日军推行伪化统治，其伪政权势力曾渗透至宜春、万载一带，组织维持会与伪军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-691a3530dc754f7a899fd0a6cf4e127c','3e903702-a88d-4f53-b011-59f5b42cf484',1939,'其特工网络在江西宜春、万载等地活动','其特工网络在江西宜春、万载等地活动，收买地方保甲长，建立伪情报网，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ceaceaeb58c44ee895ee65b7be91fa5','3e903702-a88d-4f53-b011-59f5b42cf484',1939,'浙江遂昌人','浙江遂昌人，抗战期间投靠汪精卫，组建伪特工总部（76号），任主任，后任伪江苏省省长，大肆捕杀抗日志士，在江苏、上海等地活动，其特务网络延伸至华中包括湖南部分地区。与湖南有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7382228a054e45fc891f9d4d3b29a6cf','734f02a7-b9d8-423d-943d-72d58a45a34d',1940,'其伪政权体系在江西设有分支机构','其伪政权体系在江西设有分支机构，宜春、万载地区部分维持会受其指挥，推行奴化教育。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9efdbe4e275476f8a887b4a432714dd','e432d2b0-fce8-4660-8851-6102290e21cb',1938,'通过伪政权在江西宜春、万载等地征收赋税','通过伪政权在江西宜春、万载等地征收赋税，支持日军物资供应，并组织伪警察维持地方治安。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa0157b9e03e4d1d94f14f87eb08f335','e432d2b0-fce8-4660-8851-6102290e21cb',1938,'汪伪政权要员','汪伪政权要员，其财政与警政体系延伸至江西，赣州地区伪警察系统受其节制，协助日军维持占领区秩序。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45491f1324e84230ba1ef515af0988e7','73b5c3d2-1086-40d4-9284-a84ffd61e71e',1938,'在江西宜春、万载一带宣传“中日亲善”','在江西宜春、万载一带宣传“中日亲善”，为日军提供文化渗透服务，组织伪教育机构。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f47fdd9675d74bc3b87408cc9f0291a1','3526006d-4cea-4207-90bf-36b55554d71a',1939,'其伪政权管辖范围覆盖宜春、万载','其伪政权管辖范围覆盖宜春、万载，推行保甲连坐制度，协助日军清乡，镇压抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bafc188e1e274306ad065d3f90b3b7f3','b3f669df-6ca5-4775-8e34-116b53d2222d',1941,'在万载、宜春等地建立伪警察所','在万载、宜春等地建立伪警察所，搜捕抗日分子，推行“治安强化运动”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e50008a0e1b4813b3db9e7706101288','528760f9-f196-4fc9-b328-6ada2955d237',1939,'直接负责宜春县及万载周边地区的维持会工作','直接负责宜春县及万载周边地区的维持会工作，为日军征粮、带路，迫害抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-538730da065e4a3c862a875bd065823c','8150e340-8dc7-4e85-b122-c0da29402f64',1939,'在南昌及周边地区组织伪维持会','在南昌及周边地区组织伪维持会，协助日军推行保甲制度，其势力范围延伸至宜春、上高一带，为日军征粮、征夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6222d1963a854fbfb3d1a098b2df0c7b','35d7e3c7-05a6-4270-b508-b286bcb6a00d',1940,'在江西沦陷区建立伪警察体系','在江西沦陷区建立伪警察体系，配合日军清乡，宜春、上高地区伪警察所多受其节制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2594117e105e41959892449bbcbd99a7','fdaeabcd-ed85-4488-ad80-df879fcaf69c',1939,'在宜春县城组织维持会','在宜春县城组织维持会，为日军筹集物资，协助建立伪区、乡政权，上高邻近地区亦受其影响。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-439dcfd32c0c45b9b30e5966d4a40ea7','fdaeabcd-ed85-4488-ad80-df879fcaf69c',1939,'日军侵占宜春期间出面组织伪维持会','日军侵占宜春期间出面组织伪维持会，协助日军征粮、拉夫、维持地方秩序，为日军侵略服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c1cca2fd09d4fb69ef8a22d31713746','f235ac56-73dd-41b2-a177-61db3f343a90',1941,'上高沦陷期间出面组织维持会','上高沦陷期间出面组织维持会，替日军征发民夫、粮食，并参与伪保甲长任命。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80a0969fac9e484cbef64f354372678e','9c2b1312-8fd0-4e5e-8980-baac53b396a3',1942,'率伪保安队配合日军扫荡宜春、上高交界地区','率伪保安队配合日军扫荡宜春、上高交界地区，搜捕抗日人员，镇压民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7eff41569b084838a62c299f62ddc85b','303b7076-97a5-4ecc-970c-7603d87b16b5',1942,'在上高县城及周边乡镇建立伪警察网络','在上高县城及周边乡镇建立伪警察网络，为日军提供情报，迫害抗日家属。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27437aa9e80d49a2aff01a75118368a1','47a5919b-bbd2-44f8-98e0-3c43c10428f2',1942,'在宜春推行奴化教育','在宜春推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”，影响上高部分学校。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66e69e2b7dd540c2992a281b985a9a92','80eded18-1c33-40eb-8c02-420515985e4d',1943,'控制上高物资流通','控制上高物资流通，为日军低价收购粮食、桐油等战略物资，盘剥当地百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-728bdad4cdc448b6b591da616906a06a','a3ac0740-2310-44a8-ac6b-5d259fc766c6',1941,'在宜春与上高交界地区组织维持会','在宜春与上高交界地区组织维持会，协助日军修筑据点，征发民夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-406ca17e435c418cade0daf84918d2ef','26350c7a-3adc-46fd-b44d-7f26416e08c7',1931,'长期主政江西','长期主政江西，南昌沦陷前后对日妥协传闻较多，但无确凿伪职记录，奉新一带亦有相关传闻，需谨慎对待。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f8fa8a439244a9ca9f02e16aa836658','a71b0ad2-591e-47cb-81b7-c4459dcdfb98',1940,'汪伪政权在江西地区的重要附逆者','汪伪政权在江西地区的重要附逆者，参与伪江西省政，活动范围覆盖赣西、宜春一带。','危害等级B（乙级，市县厅局级）','hanjian');
