INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cea8231176c46af9e18821ae755f38b','334b4802-5a68-40d3-a5c9-3b5df7c97fbc',1940,'参与汪伪江西省政','参与汪伪江西省政，推行日伪统治政策，活动范围包括赣西宜春地区。','危害等级B（乙级，市县厅局级）','hanjian');
