INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73ef3466aa454c9db2e85abe1643ad0c','73b46ef1-20be-4570-a448-481a6e757765',1941,'在乐平基层推行保甲制度','在乐平基层推行保甲制度，为日军征丁征粮，监视民众，举报抗日人员，协助维持伪统治。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20d907ff64c24c0aa87f662e43d417d8','7dcbe247-892f-4781-94e0-9c602c1f4de6',1938,'抗战期间在浮梁县城（今景德镇市区）组织维持会','抗战期间在浮梁县城（今景德镇市区）组织维持会，投靠日军，出任伪浮梁县县长，协助日军征粮、派款、拉夫，维持伪政权统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1515aef597a04d3aa415edcb12b0c24e','c455c861-3813-45bf-a83e-f58dfa4bb201',1939,'在浮梁地区充任伪警察头目','在浮梁地区充任伪警察头目，配合日军搜捕抗日人员，镇压地方抗日活动，为日伪政权维持治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d9ebeb5a913484681991d0b8d897550','d99ff75c-1c16-4ddb-bda6-51503c3863d9',1938,'在景德镇地区参与组织伪维持会','在景德镇地区参与组织伪维持会，协助日军控制瓷业生产与运输，为日军筹集物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b3824869e404586ad819cf366fc2977','e502638b-3822-41e4-a6fc-ab58692e8655',1940,'率伪保安团在浮梁、景德镇一带配合日军扫荡','率伪保安团在浮梁、景德镇一带配合日军扫荡，袭击抗日游击队，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac001b4eacc14792a09b762d438e43ca','687b668e-7ac6-4d8d-b9a2-68b51bd9db69',1939,'在江西日占区出任伪县长','在江西日占区出任伪县长，协助日军推行伪化政策，其活动范围涉及赣东北包括景德镇周边地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c20df9610dd44a2fb622b97679a53943','1b3dc9ed-0d94-4eab-bb4a-961941f5371a',1940,'在江西伪政权中任职','在江西伪政权中任职，参与制定和推行日伪统治政策，对包括浮梁在内的江西沦陷区实施伪化统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-857d179ae44c4a16b1b0b0950e50eed6','9deb4ec0-136e-418a-8b63-ab68803f7916',1941,'在浮梁地区推行奴化教育','在浮梁地区推行奴化教育，篡改教材，向学生灌输亲日思想，为日伪政权培养顺民。','危害等级C（丙级，基层头目）','hanjian');
