INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15386f3c4a2449f486e8b89914c70bc7','3e506531-16ca-42f4-937d-8740e2aa11ee',1944,'上栗市沦陷后组织当地维持会','上栗市沦陷后组织当地维持会，为日军筹粮筹款、拉夫带路，并协助日军在上栗矿区及周边乡村建立伪保甲组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e800f6d5028f4df6aaf38c3766e3f52d','f41a6632-8704-41ee-8a6a-322325f026de',1944,'在日军占领期间主持伪教育科','在日军占领期间主持伪教育科，推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”，并组织教师参加亲日培训。','危害等级C（丙级，基层头目）','hanjian');
