INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d63587c5bbc4a72a9a53713e0d619dc','4a479aa6-a9c3-4604-8f68-56ff565f04f2',1944,'在日军扶植下出任伪萍乡县县长','在日军扶植下出任伪萍乡县县长，建立伪政权机构，推行日军政令，配合日军在萍乡、上栗等地进行经济掠夺和治安强化。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76682a62ce8245739bf6ef7d8842b85e','fc38ee3c-bee4-464e-9ff0-0bed3bd57843',1931,'长期在江西西部包括萍乡、上栗周边地区进行反共活动','长期在江西西部包括萍乡、上栗周边地区进行反共活动，抗战期间与日军暗中勾结，保存实力，袭击抗日游击队，迫害进步群众。','危害等级C（丙级，基层头目）','hanjian');
