INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a84722fe0eb1423599d64466618b7edc','b002b55f-075f-494d-badf-cf5340542fd1',1943,'协助日军整编江西伪军','协助日军整编江西伪军，参与对萍乡、莲花地区抗日武装的围剿行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8874bc319904263b2277211746f28cd','8a3a655f-92d0-44f7-a20a-cb86d485635b',1944,'在沦陷区推行奴化教育','在沦陷区推行奴化教育，篡改教材，宣传“大东亚共荣”，毒害青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be65e30098404d87acfb30f68d6bd0ec','9c95b22c-384b-4e04-ba44-accb2183ed60',1944,'为日军筹款筹粮','为日军筹款筹粮，强制商户缴纳“治安费”，协助日军掠夺地方资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5e80285b7794a6898b0ec79edb97159','4e11a80b-f140-46e5-b409-834bb7fb1310',1944,'组织伪自卫队配合日军清乡','组织伪自卫队配合日军清乡，抓捕抗日群众，烧毁抗日据点附近民房。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c13d6382521c4accab8e96d8b831dcd4','a0c4ebf6-b416-47b1-8db5-0cecb290361a',1938,'浙江遂昌人','浙江遂昌人，抗战期间投敌，组建伪特工总部（76号），残酷镇压抗日力量，其特务网络覆盖包括江西在内的华中地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f31a982cd9524659a91e69851cf2a555','c0c54bde-d1ed-4e88-b235-7b254e882fb9',1938,'湖南常德人','湖南常德人，抗战期间投敌，与李士群共同主持76号特工总部，后任伪社会部长，其特务活动涉及江西沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-30ca37abe53846c9ac33d08abe5f3da3','16e3c056-42e2-43ff-9748-e189c21a402c',1940,'江西弋阳人','江西弋阳人，中国社会党创始人，抗战期间投敌，任伪考试院长、伪社会部长，是江西籍知名汉奸，其活动与赣州地区有籍贯关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-440a034741054d8793b7ecc3342b0687','530df262-4aba-482e-b475-cb4018c85273',1939,'江西人','江西人，抗战期间投敌，任伪江西省政府保安处长，后任伪军师长，率伪军配合日军进攻赣州地区抗日根据地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68a03f6c65974159a21389ed400b4f5d','2bbd4fe6-47f3-4abd-819e-2203992d53fe',1939,'江西人','江西人，抗战期间投敌，在伪江西省政府任职，兼任伪南昌县长，协助日军推行保甲制度，镇压赣中地区抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b18996e72e26429aaa511a054bf148fa','b45a327a-2bcc-44ab-adc9-b0f4a4973525',1944,'江西赣州人','江西赣州人，1944年日军侵占赣州期间，出面组织伪赣州维持会，任会长，协助日军征粮、拉夫、维持治安，是赣州本地直接附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d26f05a8549941448d7b47bd47b58333','7307b5fa-bb1d-4b56-a6be-3bfa4adb4e35',1944,'江西赣州人','江西赣州人，1944年日军侵占赣州期间，与张一清共同组织伪赣州维持会，任副会长，协助日军统治赣州城区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4b175c151cc4e1eaf978ef81ad0519a','b6e3037c-159e-4610-9ef0-bc7c164b3fa7',1944,'江西赣县人','江西赣县人，日军侵占赣州期间，出任伪保甲长，协助日军清查户口、征发民夫、征收物资，是赣州基层附逆者。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0ac2b4322ac450ebb133b09d3aa298b','d301bd75-f1a4-4b46-9708-fbc9ff3e63ad',1944,'江西赣州人','江西赣州人，抗战期间投敌，任伪赣州商会会长，为日军筹款筹粮，组织商户配合日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbc6e12e1d834ea692733c2fd55ade3c','19f5aacc-9060-45d8-87d6-d156511fd341',1939,'江西人','江西人，抗战期间投敌，任伪江西省政府教育厅长，推行奴化教育，篡改教材，向江西沦陷区学生灌输亲日思想，与赣州地区教育界有间接关联。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1dbca481c9e84c7d82cce1aa538c0779','56f40308-a05a-4140-93bd-70b6dbddc6e4',1939,'浙江嵊县人','浙江嵊县人，抗战期间投敌，任汪伪政权宣传部次长、《中华日报》总主笔，撰写亲日文章，其宣传影响覆盖江西沦陷区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bdcb7c2e46984f5db43d977ebba3221b','cf6fa972-80af-4328-adab-080b68c8c754',1939,'江苏人','江苏人，抗战期间投敌，任伪《平报》社长，后任伪中央储备银行调查处长，为伪政权进行经济与舆论服务，其活动涉及华中包括江西。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-149ddc89d6db4c76a6b0fe8074c2f5c6','bf916d94-686c-4e35-93af-8c8172ba66aa',1939,'山东人','山东人，抗战期间投敌，任伪特工总部南京区区长、伪首都警察厅长，其特务与警察活动涉及江西沦陷区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67e5a73385c847b88bb0e314f22dd601','2dc1bc70-bda1-4a16-aeed-33ece2d7e623',1940,'抗战期间投敌','抗战期间投敌，任伪特工总部江西区区长，在江西沦陷区建立特务网络，搜捕抗日人士，与赣州地区有直接关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0be37629687d465db20db34a54d12a76','11e61c02-6b0c-4aee-98db-ad11ce49db99',1940,'抗战期间投敌','抗战期间投敌，任伪特工总部江西区副区长，协助马啸天在江西进行特务活动，镇压赣州周边抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48efa236e4b7430684b31a6baa51d516','ede4f364-e29f-422f-a681-2becd2ffd653',1939,'抗战期间投靠日军','抗战期间投靠日军，在赣州地区组织伪维持会，协助日军维持占领区秩序，推行奴化教育，搜刮民财供给日军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1082dc5e0658434ebe36a3447c823075','b1609eea-d0ac-4c01-8045-5dc04acfddaa',1944,'日军侵扰赣南时','日军侵扰赣南时，在上犹县组织伪维持会，为日军带路、征粮、派夫，协助日军镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-499a84000ed34e2dbc6024f36584bebb','ee7b6b03-3abb-49a0-9a07-695fe4c24a2d',1944,'在赣州沦陷期间任伪警察局长','在赣州沦陷期间任伪警察局长，配合日军清查抗日分子，逮捕爱国人士，维持伪政权治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7070df3d49ad4aac912a6f3b845df7a8','390b8bf6-8439-4506-a674-eb97680e1e09',1943,'率伪保安团配合日军扫荡赣县、上犹一带抗日游击队','率伪保安团配合日军扫荡赣县、上犹一带抗日游击队，烧毁民房，抢掠百姓财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90d93a6f25f84889b216941e7f5b889e','5ee3f6d5-95a2-46b8-9233-e4988de41177',1944,'在赣南地区协助日军推行伪化政策','在赣南地区协助日军推行伪化政策，组织伪政权，动员地方士绅附逆，为日军提供情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c8cca31c80a411e9a12406836505fc5','b89f3e6f-5cde-4fb0-be15-1febe821cd43',1944,'在上犹县组织伪保安队','在上犹县组织伪保安队，配合日军清乡，抓捕抗日群众，勒索钱财，无恶不作。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-067912c56a06474c83e048494c8b95a8','62b463f9-a59e-4f63-9d4e-37a10d1589ff',1944,'在赣州地区组织伪自治会','在赣州地区组织伪自治会，宣传“大东亚共荣圈”，协助日军征发劳工，压迫民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4650b6203a04c15bf67e490096d42f1','c671d225-d7c5-4f3f-bb95-77d53a63edf7',1944,'在赣县推行奴化教育','在赣县推行奴化教育，篡改教材，强迫学生学习日语，宣传亲日思想，毒害青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e83821ec6104476a8bef606c82a5a803','130f8fa2-a1c8-471c-9da5-d7e9c6c9db18',1930,'长期在赣西南遂川、井冈山、于都周边地区组织地主武装','长期在赣西南遂川、井冈山、于都周边地区组织地主武装，镇压红军和革命群众','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b7e7ce837574a0f81ab8acbb036068e','130f8fa2-a1c8-471c-9da5-d7e9c6c9db18',1930,'抗日战争时期破坏抗日民族统一战线','抗日战争时期破坏抗日民族统一战线，迫害抗日进步人士，袭击中共地方组织，是赣西南地区著名的反共顽固势力代表。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-256f0df4ab2d472395b4433fd4d6092e','b80533ca-fa0b-48b3-8a09-7c651c09550e',1930,'在赣南地区参与组织反共武装和地方政权','在赣南地区参与组织反共武装和地方政权，压制抗日民主运动，迫害进步青年和中共地下党员，与地方豪绅勾结控制赣州一带基层政权。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c59ade3507a5465183abf6fe0f54fc98','aaafac56-4f72-44a3-965f-4b7642270a55',1940,'据部分地方文史资料提','据部分地方文史资料提及，赣县沦陷期间曾有维持会组织为日军征集物资、维持地方秩序，但具体负责人姓名及事迹记载零散，需进一步核实。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2de2745fecc64b8597839ba2c49b2d94','2ddb2b2f-7c84-4f42-8158-4f0fa8fe39a6',1930,'在赣南地区长期从事反共活动','在赣南地区长期从事反共活动，抗日战争时期消极抗日、积极反共，破坏中共领导的抗日救亡运动，迫害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f432b2680d67456d94d320a4117bfab8','34295dd7-fecc-41ce-9584-b3ce8b7646a6',1940,'汪伪政权在江西地区安插的伪职官员','汪伪政权在江西地区安插的伪职官员，参与伪政权对江西部分沦陷区的控制与宣传，协助日军推行治安强化运动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac473702488d4cb192f86da98facaca0','039b3ee2-29a6-4b7d-a099-a2f65a651ee3',1939,'南昌沦陷期间组织维持会','南昌沦陷期间组织维持会，为日军征发民夫、粮食，协助日军维持占领区秩序，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5bdc79c8155f47bcbc2c5654729a5e5f','3c09127a-c287-49d5-ac1b-8b1e61eb0917',1938,'九江沦陷后出面组织维持会','九江沦陷后出面组织维持会，为日军提供情报、物资和劳工，协助日军控制长江航运和赣北地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-439867e05ba74130bc72c544321b0d9a','08183d55-b7a6-4f09-a3ff-40c3660aba47',1940,'在汪伪江西政权中负责警务','在汪伪江西政权中负责警务，协助日军搜捕抗日人士，镇压沦陷区民众反抗。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee22865acd884857b0a616aa04cd6d7c','46aaca9d-e855-40df-9629-55ddcf059c7e',1927,'长期在赣西南地区从事反共活动','长期在赣西南地区从事反共活动，抗战时期继续把持地方武装，与日伪势力及国民党顽固派相勾结，镇压抗日民众和进步力量，残害革命群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e83e255d541c4c52b5ac54d4f937e892','ba595261-eb63-4c90-9fa3-ffab8605aec9',1930,'在赣南宁都、瑞金、会昌一带长期进行反共清剿','在赣南宁都、瑞金、会昌一带长期进行反共清剿，抗战期间消极抗日、积极反共，纵容部下与日伪势力暗通款曲，迫害抗日人士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd2ceb4093734411ba331cb7e1ff5889','b750cc7a-72c1-492f-8edd-0f6e01194c78',1930,'在赣州、会昌交界地区组织地方武装','在赣州、会昌交界地区组织地方武装，抗战期间投靠日伪，参与维持会活动，为日军搜集情报、征派粮款。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3afbc14b1d9432f9ad502c8879fa9ae','b5dfe23c-3424-4c19-ab25-713b1e26ed23',1930,'在赣南地区推行消极抗日政策','在赣南地区推行消极抗日政策，与日伪势力保持暧昧关系，纵容部下参与伪政权活动，镇压赣州、会昌等地抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dab756fa75384cb5882b8bdbc092eb6c','0e49e019-6ced-413f-a346-b41f0d650343',1930,'在江西赣南任职期间','在江西赣南任职期间，对日伪势力妥协退让，参与伪政权维持会活动，迫害抗日进步人士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c960c964dfcb4b28bab3d95d64a14ae4','2eb647df-fde1-4fbd-8cd4-8d02c56cb121',1939,'在赣州城区组织伪维持会','在赣州城区组织伪维持会，为日军征派物资、搜集情报，协助日军控制赣州及周边会昌等地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b39b181137345aa9b469f34eea59734','87073f39-998e-4af7-ae86-d7e1c997666e',1940,'在会昌地区协助日军建立伪政权','在会昌地区协助日军建立伪政权，征派民夫、粮食，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c924702a54874dea8758f6b5a75f39a0','21143a7d-35b6-4738-9498-4da5d9ba88e3',1940,'在赣州担任伪警察局长期间','在赣州担任伪警察局长期间，配合日军搜捕抗日人士，镇压会昌、赣县等地民众抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0dde7eb8d39e42678123276efddc3f2b','99e92759-547d-47fe-90e5-84d7c6cd34b9',1930,'在江西赣南地区消极抗日','在江西赣南地区消极抗日，纵容部下与日伪勾结，参与伪政权维持会活动，镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-756692da748048f48180c77532f83803','be0a8b29-05b7-4e10-a351-2822404554bc',1931,'主政江西期间','主政江西期间，对日伪势力采取妥协政策，纵容赣州、会昌等地伪政权活动，迫害抗日进步人士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d24c5d4fdf9b47888706590efc0daf11','9a812cbc-cf8a-426b-a1cb-8bb586e7c457',1939,'抗战期间投靠日伪','抗战期间投靠日伪，在江西日占区参与伪政权事务，曾任伪江西省政府委员、伪南昌市市长等职，协助日军维持占领区统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-578c29dc38f04f98895b897f2d5c54a0','84ff082f-e83e-4e4e-8d3b-4ae88e1fd0aa',1939,'在江西日占区伪政权中任职','在江西日占区伪政权中任职，参与伪警察系统，协助日军镇压抗日活动、维持治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73157cbe61344710b863ee213dea78f5','4a0aa506-8d9a-48c1-85c2-cd93fa5ee68e',1944,'抗战后期在赣南地区参与伪维持会活动','抗战后期在赣南地区参与伪维持会活动，协助日军在赣州及周边地区的占领统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45a5072e292d4941a86d12fd6ff8beab','f6161807-1b85-4c97-81ab-699918fbd0b3',1944,'抗战后期在信丰地区组织伪维持会','抗战后期在信丰地区组织伪维持会，为日军征集物资、维持地方秩序，属地方附逆人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66cc5512c4794919a8ff4087e4b573f7','e4f85d0f-a2cc-476d-a2f2-1d66ffa0ded7',1944,'在赣县参与伪维持会活动','在赣县参与伪维持会活动，协助日军管理地方事务，为日占区基层附逆人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74747d6fd3ad40c2ad6b30f8755cd64c','2ae4fe95-feda-4f76-8e1f-9a6ed4741b60',1944,'在赣州日占区伪警察系统任职','在赣州日占区伪警察系统任职，参与维持占领区治安，协助日军管控民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb78f925e4fa4ba5bce7e091c12c7406','cc268922-6918-4c0b-ad35-2ac4b8ad41a8',1944,'在信丰县担任伪保甲长','在信丰县担任伪保甲长，协助日军和伪政权征粮、派夫，属基层附逆人员。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e58c53a39224dcf8abe3eb12357d495','2e8bb69f-685c-4308-abae-5c48e595e1c3',1938,'汪伪政权核心人物','汪伪政权核心人物，其伪政府体系覆盖江西，间接影响赣州地区伪政权运作，推行亲日政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eca8df84cb0e459caecd3e7f2f52f0c8','7a89c1e3-4730-4d9f-a8e9-9f7e19110268',1944,'赣州本地汉奸','赣州本地汉奸，日军侵占赣州期间组织维持会，为日军筹粮筹款，协助搜捕抗日分子。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2f7b8c1510640f5b476eed7c48bee20','83cdcc2a-e288-4050-9337-8e9c62ec5f78',1945,'全南本地汉奸','全南本地汉奸，日军侵扰赣南时组织维持会，胁迫民众服从日军统治，提供情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-328d992cea9d4a60836ee4c87eac83fe','0edd2351-4074-4f2f-8bdb-dd5a0e39ffab',1944,'在赣州、全南一带活动','在赣州、全南一带活动，协助日军建立伪政权，推行奴化教育，强征劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-264b95c7497d4bc99b79b01ec8e76de3','cad704c6-0d3d-4901-b4e9-e7586946cd4e',1944,'率部投敌','率部投敌，配合日军扫荡赣州、全南地区抗日游击队，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e958a11cf4243e4a624ee825871b881','2683d646-62c1-4710-b501-d1b1dafc8c17',1943,'福建人','福建人，汪伪政权高级官员，1943年任伪江西省省长，在江西推行伪化统治，配合日军清乡与物资统制，活动范围覆盖南昌及赣中北地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-097d659c6e714f28bbede70fd9d272ba','d88d9d66-d779-4bcb-b862-8b664e803133',1940,'江西南昌人','江西南昌人，原军统人员后投敌，任汪伪税警总团副总团长，在江西及华东地区率伪军配合日军作战与清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4454144a9ce4025806d82d0eb5445f6','9a41824e-a88a-49a0-8735-aba04bc762bc',1939,'赣州地区地方士绅','赣州地区地方士绅，日军侵占赣南部分地区时出面组织维持会，为日军筹粮、带路、维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d0021fed7354cf1bc88045a0396351f','96fc45a8-76d1-454e-b909-9aa5c86085e0',1939,'兴国县地方人物','兴国县地方人物，在日军侵扰赣南期间组织伪维持会，协助日军征粮、拉夫，后随日军撤退而瓦解。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76af3f82c5344e928f275d5145f9e573','e2fd7951-3afd-4784-9c3a-e9ee6961947f',1944,'赣南地方武装头目','赣南地方武装头目，抗战后期投靠日军，被委为伪赣南自治军司令，在赣州、兴国一带骚扰抗日根据地、劫掠民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1798ee6e5b644b0bb7a08933cc504d29','c89fc079-588e-4ee3-b8b3-657b202ee4d1',1940,'汪伪政权在江西的县级伪官','汪伪政权在江西的县级伪官，负责南昌县伪政，推行保甲连坐、征粮征丁，配合日军扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2f87f4cc1c74c9d8ae03cb1bc744044','2469b44a-4348-459e-b5dd-70ec730acf37',1944,'日军侵占大余期间','日军侵占大余期间，出面组织伪大余县维持会，后任伪县长，为日军征派民夫、物资，协助维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b517ced3465044fb9c9657d15ab1b81d','b54be0f7-b043-419e-a19c-777f35a61964',1945,'1945年日军窜扰赣县时','1945年日军窜扰赣县时，出面组织维持会，替日军筹粮、派夫，并协助张贴安民布告、劝诱民众归顺。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2371b26bee9d40bc8b8addfda8aea20c','2239b940-5f63-4f1c-a3f9-ba570db4b075',1944,'抗战后期在赣南一带收编土匪、散兵','抗战后期在赣南一带收编土匪、散兵，组织伪军配合日军行动，骚扰赣县、南康、大余等地抗日后方。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-573a0f90ea2e4a8db614800da17e39fa','ae53dcc0-71f4-478f-b095-c37e8444c389',1943,'在南昌伪政权任职期间','在南昌伪政权任职期间，受命联络赣南各县伪组织，推动建立伪基层政权，为日军搜集赣南情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5add308853046d5b762e021d580b5a4','dd5fd5d5-52b7-45b8-a25a-693ed748505b',1945,'日军进犯南康时','日军进犯南康时，组织维持会迎接日军，协助征发粮食、民夫，并参与清查抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f99e87eea1d48528b80afc6a89ed067','4102594a-25a2-462c-bfd2-4f6ad22bc83b',1945,'在日军占领赣县期间出任伪警察局长','在日军占领赣县期间出任伪警察局长，带领伪警察配合日军搜捕抗日分子、镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d90d8a885e9a4e088435d40500918b89','de26ffed-3984-4021-842b-4959f43286c2',1930,'长期在赣西南遂川、上犹、大余一带组织地方武装','长期在赣西南遂川、上犹、大余一带组织地方武装，抗战期间与日伪势力暗通款曲，进攻抗日游击队，残害民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-897a1b78a0634cfaa9e2a7d82d82c66e','f4d6cd67-5eba-4ad0-9571-2c927d76b94b',1944,'在赣南收编地方武装','在赣南收编地方武装，与日军及伪政权合作，进攻抗日根据地，活动范围包括赣县、大余、南康等地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2337ab8ad714e23adb8ec01caee8be2','79bcb7c3-67df-44de-809b-826d15d2f2ef',1945,'日军侵占大余后率部投敌','日军侵占大余后率部投敌，任伪保安队队长，协助日军维持治安、搜捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-802c7c9c43574a0fabcafe2199ef79c7','000b4851-eb9b-4fe5-a10c-b5be98c3184c',1945,'在日军占领赣县期间','在日军占领赣县期间，以商会名义为日军筹款、筹粮，并动员商户悬挂日伪旗帜，协助经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea2393f0f9304ccbae1403e1333c3be7','6593addb-60a2-4869-9975-fe323ab312ab',1937,'江西籍汉奸','江西籍汉奸，安徽合肥人，祖籍江西。抗战期间投靠汪精卫，历任伪临时政府内政部长、汪伪政府考试院院长、伪安徽省长等职，推行奴化教育，配合日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-235db2e1e6f845dbb467d315bc034309','af81ffbd-1bcf-4252-be65-5f42d3686449',1940,'江西籍汉奸','江西籍汉奸，抗战期间在江西沦陷区组织伪军，配合日军对赣北、赣中地区进行扫荡，镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31cf8e4d0dce46f49930cc32b589a422','2b286660-ee24-4ead-876d-ca375d0ed601',1943,'广东人','广东人，但长期在江西活动。1943年任汪伪江西省长，在南昌、九江等地建立伪政权，推行保甲连坐，协助日军掠夺物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05102db1b9524e8f888083a069dd1960','33d10870-5b88-413c-adbf-fc6882fcaaa2',1940,'在南昌等地组建伪警察队伍','在南昌等地组建伪警察队伍，配合日军搜捕抗日志士，镇压民众反抗。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4dcab4918d34340b48f0b6e22be8d7d','37bdb745-a756-4ebd-a8d3-5d1c6436bec1',1944,'江西籍国民党官员','江西籍国民党官员，抗战后期在赣州地区与日军进行过试探性接触，但未正式投敌，历史评价存在争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a2e47f6583f4a669bcd7bfb0ad9503b','96c568f3-ad50-4e9d-a606-16e8ebf0dec2',1944,'赣州沦陷期间组织维持会','赣州沦陷期间组织维持会，为日军筹粮筹款，协助建立伪基层政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11816ed6bf344d928cda9b552e6222f2','f8afeb39-d0f6-49f8-ac9d-ba3d7f8c514b',1945,'1945年日军窜扰宁都时','1945年日军窜扰宁都时，出面组织维持会，张贴安民告示，为日军带路、征夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d28b24c552df4374a5a7eadb57278790','89ff70b7-715e-406a-b4a9-c929f0c76348',1944,'在赣县沦陷区担任保甲长','在赣县沦陷区担任保甲长，执行日军指令，登记户口、征发劳役，监视抗日家属。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ddb3035894444693bee426dbb62e9414','fa40a609-8a5c-45bc-888a-483095a612a8',1939,'在南昌为日军筹办军需','在南昌为日军筹办军需，组织商户“献金”，协助日军控制粮食市场。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc4409b7b7914fb980ac8a1b8cd6fbb0','41baa84d-ce0c-485b-9d96-dc6c7cf48510',1938,'九江沦陷后组织维持会','九江沦陷后组织维持会，为日军提供情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20132a0b031248fc8c00e8084a032aab','ccfc778a-d989-4d35-9a6b-8d67295d2392',1930,'长期在赣西南遂川、上犹、崇义一带组织靖卫团和保安团队','长期在赣西南遂川、上犹、崇义一带组织靖卫团和保安团队，配合国民党军清剿红军游击队','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64693ee3ac704c93a2509f0cb88b139b','ccfc778a-d989-4d35-9a6b-8d67295d2392',1930,'抗日战争时期继续把持地方武装','抗日战争时期继续把持地方武装，横征暴敛、迫害抗日进步人士和群众，是赣南地区有明确记载的反动地方武装头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32ec71809435403a922bb4e44714dc8a','9321996e-5d54-4839-9e92-4a98e3ec8778',1930,'在赣南宁都、瑞金、石城一带长期掌握地方保安武装','在赣南宁都、瑞金、石城一带长期掌握地方保安武装，抗日战争时期借抗日名义扩充势力，镇压群众抗日活动，迫害中共地下组织和游击队员，是赣南地区有明确记载的保安团队头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2509270fde6a44418021a64ea4c4d38d','7e2f9ab7-a1be-45b8-9baf-b0cf29333825',1930,'在赣州及周边县区活动','在赣州及周边县区活动，抗战时期依附日伪势力，参与组织维持会，为日军搜集情报、征派粮款，协助日伪维持地方统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77a23d094220451daa3d533c614c3de4','092e44fd-1ec5-4114-ac91-ec2cd01558d5',1939,'抗日战争时期在赣县组织伪维持会','抗日战争时期在赣县组织伪维持会，为日军征派粮食、民夫，协助日伪维持地方秩序，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f46398fb10ea4ace875a1eadfafc04ab','a94c0195-dd72-4cce-9275-18c1505a209e',1939,'在赣州商界活动','在赣州商界活动，抗战时期投靠日伪，利用商会关系为日军筹款筹粮，协助日伪控制赣州城区经济。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-836b92a0b9814bf5acc7fc711f67421a','d804a392-af9e-4d58-aa56-ad1c6ed590a1',1944,'抗日战争后期在定南县组织伪维持会','抗日战争后期在定南县组织伪维持会，为日军和伪政权征派粮款、民夫，协助维持地方治安，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-956ca7897f9344f49dfcf52b3f22fe56','8d21dd59-a112-4a91-a40f-1ee6d983660d',1944,'在定南一带率领伪保安队配合日伪军行动','在定南一带率领伪保安队配合日伪军行动，搜捕抗日人员，征派粮款，欺压百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c4b9e83061a48efb598d5eb7dfe9ced','631bc513-bcc9-4ec1-b8cf-acf15ad57a57',1939,'抗日战争时期在赣州担任伪警察局局长','抗日战争时期在赣州担任伪警察局局长，协助日伪维持城区治安，搜捕抗日人士，镇压群众抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69bf28b10b0843dea90ee183b5851c71','62692e81-d077-43a7-b13c-11b6acc19a69',1939,'在赣州教育界活动','在赣州教育界活动，抗战时期投靠日伪，推行奴化教育，篡改教材，宣传所谓“大东亚共荣”，毒害青年学生。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b35d0a396c354b9aa6e85dd8c9d64734','dfe446e1-1a2d-4e6b-9ef6-5501fe746cc9',1940,'在赣州文化宣传领域附逆','在赣州文化宣传领域附逆，为日伪撰写文章、编辑报纸，鼓吹投降妥协，诋毁抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d1fa90195a84c9e9194239f9907b37f','e14e3f01-1405-4abc-85c8-048c4d43b891',1931,'长期在赣西南遂川、井冈山、瑞金周边地区组织地主武装','长期在赣西南遂川、井冈山、瑞金周边地区组织地主武装，配合国民党军及日军清剿红军游击队和抗日力量，残害革命群众，抗战期间继续坚持反共立场，破坏当地抗日民族统一战线。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d90ac991618d4f2c9e2644f9679ef3e3','0eaaf80a-b7ea-48ef-b323-6545121a80dc',1931,'在宁都、瑞金、石城一带长期把持地方武装','在宁都、瑞金、石城一带长期把持地方武装，镇压革命群众，抗战时期消极抗日、积极反共，与日伪势力暗中勾连，维持其在赣南东部的反动统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cdb6ab66def43909d6812035cc49f91','6cd22faf-7ef0-42a4-aaca-7a07776ec2d4',1939,'日军侵占赣北、赣中期间','日军侵占赣北、赣中期间，在赣县、南康一带组织伪维持会，为日军筹粮筹款、搜集情报，协助日军维持占领区秩序，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f63a48fba7a499a995f48e60557512c','36ebe196-cc3d-4f86-bc9f-69e6b3ab2b1c',1940,'在赣西、赣南交界地区收编土匪武装','在赣西、赣南交界地区收编土匪武装，投靠日伪，配合日军对赣州、吉安一带进行扫荡，袭击抗日游击队，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ba7c9c67a71497d8fdf4f2d900f24d8','9291b3fd-7941-4177-81e5-59a3094a6d12',1939,'日军占领南昌后出任伪职','日军占领南昌后出任伪职，协助日军在江西占领区推行殖民统治，其影响波及赣中、赣南部分地区，为日军掠夺江西资源、镇压抗日活动提供支持。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f033e89aeab4d37934e3c2226b99f1c','95ded775-d7e6-4f98-a922-f2b0420d558a',1941,'在赣州、南康、信丰等地组织伪清乡活动','在赣州、南康、信丰等地组织伪清乡活动，配合日军和伪军清查抗日分子，推行保甲连坐，压制当地民众抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5e05fff8f954488afd83d6f65bfbf08','cd20ff6f-2073-41aa-8201-daee5e782bb5',1939,'在赣东临川、南城一带组织伪维持会','在赣东临川、南城一带组织伪维持会，为日军提供物资和情报，协助日军控制赣东与赣南之间的交通线，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef7c1c237e214dbb88dddf46ddcb3e55','880f84c5-6ce6-42fa-a550-9a8c8f097a9c',1940,'收编赣南土匪和散兵游勇组成伪保安队','收编赣南土匪和散兵游勇组成伪保安队，配合日军在赣州、瑞金、会昌一带进行清剿，镇压抗日武装，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6811f4d7a7d14c779480d8905409bb97','9241dd77-693c-454d-b3a3-70126cb8cb3e',1944,'日军侵扰赣南期间','日军侵扰赣南期间，在瑞金出面组织伪维持会，为日军带路、筹粮，协助日军搜捕抗日人士和革命群众，维持日伪在瑞金的短暂统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f81a5e75bb93421dafa82c99044a8ed2','eb7f6ae6-7e40-4179-bff6-c63e5f52aba0',1938,'抗战期间在赣州地区投靠日军','抗战期间在赣州地区投靠日军，组织伪维持会，协助日军维持占领区秩序、征发民夫与物资，参与镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82fcebd9d1f44f8bb77fe422448640fa','b66f6029-a13b-4be7-956b-ec1143b10d40',1944,'日军侵扰赣南期间','日军侵扰赣南期间，在石城组织伪维持会，为日军筹粮、带路，并协助建立伪保甲体系。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0900b0fb25546c7bda65ff34b7c8181','564d2c45-df68-4a9c-8d3e-d2c21ca78e3a',1939,'在赣州伪警察系统中任职','在赣州伪警察系统中任职，参与搜捕抗日分子、监控民众，配合日军及伪政权维持治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9d716c307bd48dc8385e2c4ac9a7910','81c25e65-09d4-4212-9e24-eb0a0d738f8b',1940,'率伪保安团在赣州、石城一带配合日军扫荡','率伪保安团在赣州、石城一带配合日军扫荡，袭击抗日游击队，强征壮丁与粮食。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91d8d207b22b4ad3b0e1740ac2c0d508','dfad0f49-9779-44a9-9464-2291896849f3',1938,'在江西伪政权中任职','在江西伪政权中任职，负责赣州地区伪维持会事务，推行奴化教育，协助日军经济掠夺。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca7dc4931a504b9b88c6a860475df4ec','3cdeab02-68b1-4fbf-818a-eab1f211776f',1944,'在石城基层担任伪保甲长','在石城基层担任伪保甲长，为日军征收物资、传递情报，并协助伪政权控制乡村。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8a871f0e1fb43d58003d9d21dbae5c5','cf853067-c94c-4ffc-9073-0a64cc533d7b',1939,'在赣州商界附逆','在赣州商界附逆，为日军采购军需物资，操纵市场，协助伪政权进行经济统制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be9612ebc350496c87c86fa81e4ed094','25512433-3545-4ed1-b281-648bb00c4f67',1940,'在赣州推行亲日奴化教育','在赣州推行亲日奴化教育，编写伪教材，组织学生参加亲日集会，为伪政权培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c165b357a1849aaac71e689fca7b0f3','a5a45506-cfc0-4ce6-8623-c31b80828418',1931,'长期在赣西南遂川、上犹、赣州一带镇压红军和抗日力量','长期在赣西南遂川、上犹、赣州一带镇压红军和抗日力量，抗战期间与日军及伪政权勾结，组织地方武装配合国民党顽固派反共，残害民众，破坏抗日民族统一战线。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fa13d1e12fa4a56a05b04fbcc2f5498','e923e415-791c-44fd-8696-a499eebbc53a',1939,'日军侵占赣南期间出面组织伪维持会','日军侵占赣南期间出面组织伪维持会，任伪赣县县长，为日军征粮、征夫、搜集情报，协助日军维持占领区秩序，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d87030a839004856a5362db2e5ee884d','0fa2dd0f-dbfa-4554-a8fe-1eb9efac3eb6',1940,'在赣州沦陷期间依附日军','在赣州沦陷期间依附日军，以商会名义为日军筹款筹粮，动员商户悬挂日伪旗帜，协助日伪推行经济统制，压迫爱国商人。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ce987bf184e451ca27007b252059c77','b61015b2-025f-42ea-8338-ccb01ccfd163',1941,'率部投靠日军','率部投靠日军，编为伪保安团，在赣县、南康、信丰一带配合日军扫荡抗日游击队，捕杀抗日人员，勒索百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aef77600ee5e4fe7930843e460283996','99c8db05-259f-46f0-83b0-e04254fdb5ca',1942,'在赣东及赣州周边地区组织伪维持会','在赣东及赣州周边地区组织伪维持会，后任伪军大队长，为日军带路扫荡，强征民夫修筑工事，迫害抗日军人家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47ed179ea28141ce88aac10d282362ff','e961be1b-eb97-45e9-8bb4-298053d8c9a0',1940,'在赣州推行奴化教育','在赣州推行奴化教育，编写亲日教材，组织新民会宣传“大东亚共荣圈”，强迫师生参加日伪集会，毒化青年思想。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-65594a5b990b4472b42da41e73008bb5','a7b8e73b-4c1c-44f3-ac3b-634fb993e2a2',1939,'在南昌、赣州等地为日军筹组伪政权','在南昌、赣州等地为日军筹组伪政权，任伪赣南道尹期间，推行保甲连坐，征发物资，协助日军清乡，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9274a09c13fc4f4fa59543bd2f939e94','c8f79400-8317-47ed-a3f1-9f0766b6a5ce',1943,'抗战后期投靠日伪','抗战后期投靠日伪，任伪赣南专员，在赣州、吉安一带为日军征集粮食和劳工，配合日军对抗日根据地进行经济封锁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20910ce0de124e4ebeb47abd067558a3','453d86f4-17fe-43ee-82d7-a68cf7287004',1941,'在赣州沦陷期间任伪警察局长','在赣州沦陷期间任伪警察局长，带领伪警察搜捕抗日分子，镇压市民反抗，为日军提供情报，残害无辜群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10f626de05c34252bf69a2635366c4e7','f643423b-a052-4c1f-9019-22317750b714',1940,'在南康县组织伪维持会','在南康县组织伪维持会，为日军征粮征夫，协助日军建立据点，破坏抗日游击队的交通线和联络站。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4758220e357d43be85037e4dbbb3ce3e','153e2a9e-4817-4013-92e4-0f0ac8a414c7',1931,'长期在赣西南遂川、井冈山一带组织靖卫团和反共武装','长期在赣西南遂川、井冈山一带组织靖卫团和反共武装，配合国民党军及日军清剿抗日根据地，屠杀民众与游击队员','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b378b2aef0ca413e974c938646f4017f','153e2a9e-4817-4013-92e4-0f0ac8a414c7',1931,'抗战时期在赣州周边地区维持日伪统治秩序','抗战时期在赣州周边地区维持日伪统治秩序，1949年后继续组织土匪武装抵抗解放军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ea6d8a82fa1421ab5760f663636ad7a','f76f62ee-8e65-45eb-9c99-ac0ff142b6f1',1934,'在赣州地区长期把持地方军政','在赣州地区长期把持地方军政，抗战期间消极抗日、积极反共，与日伪势力暗中勾结，镇压赣南抗日救亡运动，迫害进步人士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c21be6b857344738c849d34c56a8de8','b010011f-ef01-4ab1-a2e7-0fd55a55f4b7',1939,'日军侵占赣州期间出面组织伪赣县维持会','日军侵占赣州期间出面组织伪赣县维持会，为日军征粮派款、搜集情报、维持占领区秩序，协助日军镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-716d87dc8e1a4fcc8a3188cddc742fc2','8f4ce454-6d15-41ba-9c94-3173e5204b8f',1944,'日军侵入赣州期间','日军侵入赣州期间，协助伪赣县维持会组织伪政权，为日军筹集物资、招募劳工，参与对赣州城区居民的管控。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aceb22f7918b47708a15d3aa69da886d','b455bdfd-35f6-465b-895c-960a83414bda',1944,'在赣县沦陷期间担任伪警察头目','在赣县沦陷期间担任伪警察头目，配合日军维持占领区治安，逮捕抗日嫌疑人员，勒索商户与居民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2e437bce6cd4d36a9770faf0d1394af','64f6321b-e182-4209-a122-7a234380168f',1944,'在赣州周边地区组织伪自治机构','在赣州周边地区组织伪自治机构，为日军提供情报和后勤支持，协助日军对赣县、南康等地进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a52ba1c667249ea9f73bac28888b080','a6a13334-3bce-4360-ba4b-b7409f404dd3',1941,'在江西沦陷区推行日军经济统制政策','在江西沦陷区推行日军经济统制政策，为日军收购粮食、矿产等战略物资，剥削赣州及周边地区民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c2fe46caf7c4d7eb683a86f857c7c21','7f7d9f21-6ae6-4d2b-bf39-87c7d625d3a4',1940,'在南昌等地主办伪报纸','在南昌等地主办伪报纸，进行亲日宣传和奴化教育，为日军在江西包括赣州地区的殖民统治制造舆论。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-594cd782855e49aa8c444334d1016869','602ee3a1-aa30-4e68-b8bb-5bda34bf73e7',1942,'日军侵占鹰潭期间出面组织维持会','日军侵占鹰潭期间出面组织维持会，为日军征派民夫、粮食，协助维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69f71ef305114e40900c72f25c630b8e','8ff9dadc-d06f-45fa-acd2-877c31ce980a',1942,'充任伪警察头目','充任伪警察头目，配合日军搜捕抗日人员，勒索当地商户与居民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
