INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-218889f5f2294421a207f6bb1215a11d','23440833-5923-4f99-937b-fb63cb96e776',1938,'原国民党将领','原国民党将领，后与日军勾结，在保定地区组织伪军，协助日军清剿抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
