INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c915f55fe3347bf976543f5e442e26e','baa1c789-9696-40de-9bbc-c4ca2e709773',1937,'日军侵占曲阳后率先组织维持会','日军侵占曲阳后率先组织维持会，为日军筹粮派款，提供劳役，帮助日军建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
