INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9462705b94e45d8a93389c9044c7e18','648b68cf-968d-47cd-936e-f46c3ede1260',1941,'组织伪自卫团','组织伪自卫团，配合日军“清乡”，在曲阳北部山区多次袭击八路军游击队，杀害抗日家属。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee5c59cc1ea344a78d05435e28ce584d','082e265d-13a2-4145-945b-9d01113a3ff5',1942,'专门收集八路军和抗日政府情报','专门收集八路军和抗日政府情报，多次导致抗日干部被捕牺牲，是日军在曲阳的重要耳目。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ccdb33c3fc24098b0efe8f67b855f1f','01ff6dea-8481-4219-a03a-a09238afbd13',1938,'原为八路军冀中军区第10军分区司令员','原为八路军冀中军区第10军分区司令员，1940年叛变投敌，在望都、定县一带组建伪军，多次配合日军扫荡抗日根据地，杀害抗日干部和群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c0a9cbe2886457f94823d7a6efba75a','e3546c82-5bc4-4428-8388-fb3b0332cbdb',1939,'任伪望都县知事期间','任伪望都县知事期间，推行保甲制度，强征民夫修筑炮楼和封锁沟，配合日军清乡，多次组织伪警抓捕抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a00f975657db41839cd796512c9cfba7','2f545272-3b2c-4656-b615-76cec9652276',1940,'率伪军驻守望都各据点','率伪军驻守望都各据点，多次参与对抗日根据地的“扫荡”，烧毁村庄，抢劫粮食，并杀害多名八路军侦察员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25ce5020fb1440fb80d1af4ad18d7c90','9fc2315f-d0f5-4a00-8a62-da21eb3b22f4',1941,'在望都县城内建立特务情报网','在望都县城内建立特务情报网，侦捕抗日地下党员，严刑逼供，导致多名抗日人员牺牲或被捕。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97107ab169c4452598a3a54abd230768','e1c2284d-7197-494c-8f75-310066605708',1942,'参与策划望都地区“治安强化运动”','参与策划望都地区“治安强化运动”，推行“自首”政策，诱降部分意志不坚定者，破坏地方党组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-363eac1e805c43d181eb094da2d748c6','f027a7fd-8355-4699-b356-8be74a3e9ed1',1940,'利用新民会宣传奴化思想','利用新民会宣传奴化思想，组织“青少年团”为日军搜集情报，并强迫民众参加“庆祝会”欢迎日军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f59e6ded716b4f0f9ce223be5404b0f3','e3c5d7e6-fc06-43d3-b323-ab9338fab4f6',1943,'率伪军驻守望都西关','率伪军驻守望都西关，多次突袭周边村庄，抢劫牲畜和粮食，并参与杀害冀中军区第十分区交通员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47e52e9ebad64672abe5a4283f812d33','d23c3d7e-2251-4a0f-82ad-0fc747235c57',1943,'原国民党将领','原国民党将领，1943年投敌，其部队曾调防冀中地区，在望都一带协助日军“扫荡”，但主要活动在豫北，与望都关联有限。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1098756226740d68da6e1bbe4049a68','4273c10b-2f59-459d-a39c-fa72b7685fd0',1943,'投敌后任伪职','投敌后任伪职，其势力范围名义上包括冀中，但实际未直接驻军望都，仅通过伪政权间接控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f759375e43e440e88719067626058d59','9af5d6ee-be3e-4f10-8c69-a13c269bedd9',1938,'原为地方武装头目','原为地方武装头目，投日后任伪保安联队队长，多次配合日军扫荡涞水山区，捕杀抗日干部和群众，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa2adbd4be6c40308726a33bf256ab7b','4cc077a1-7548-46a5-991d-bfa12c084cf7',1940,'率伪军驻守涞水县城及重要据点','率伪军驻守涞水县城及重要据点，参与日军“治安强化”运动，搜捕抗日军民，破坏地下组织，抢劫粮食物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06a8168a5e5e4a02a9e611a9103ab706','7ad59cfc-f75a-4e1e-a42c-569aae9c6d04',1941,'负责在涞水推行奴化教育','负责在涞水推行奴化教育，组织“新民会”宣传亲日思想，强迫民众参加反共集会，协助日军征粮派夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cf2fd6c9d9340b4a81d1968af0ebd42','2911de4e-0988-4f7f-91b6-75372e3b7b08',1939,'指挥伪警察特务','指挥伪警察特务，侦缉抗日活动，逮捕进步人士，刑讯逼供，向日军提供情报，参与“清乡”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7beb88c916ce4dd4ad896cc28aad0275','0c82a0c1-c476-47fb-8317-0d207114b8a7',1937,'日军占领涞水初期','日军占领涞水初期，组织维持会，为日军筹粮筹款，强征民夫修路筑堡，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7df1ed85787e4ea9be89970671ed8c5f','47b51bcf-be27-469c-9772-117e9283f851',1942,'率自卫团配合日军封锁山区','率自卫团配合日军封锁山区，袭击八路军游击队，杀害抗日家属，抢夺群众牲畜和粮食。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6cf72040932454fb6cee928bb11e857','0d1f781e-0c5a-4600-abad-7af76a42c176',1943,'专门从事特务活动','专门从事特务活动，跟踪、绑架抗日干部，破坏地下交通线，多次带队突袭村庄抓捕“嫌疑分子”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72de8ec9d79545afad1460d03b62aa3d','710ddfb0-7d26-4894-8233-af4398dca423',1940,'为伪政权征收各种苛捐杂税','为伪政权征收各种苛捐杂税，强征“治安费”“慰劳金”，贪污勒索，加重民众负担，资助日军军费。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e750be6970d4178a62b3368d175af90','f612dfb4-2746-4ee0-bf8e-4ed829971c11',1941,'推行日伪奴化教材','推行日伪奴化教材，强迫学校悬挂日伪旗帜，检举抗日师生，导致多名教师被捕。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0847a778bf484c8db66e66f7fa0e7e95','2c6ab7bf-1d86-4c3a-90ba-9b34bd86f738',1942,'建立情报网络','建立情报网络，向日军报告八路军活动规律，导致多次伏击失败，造成抗日武装重大损失。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-999b10e76fcd454aa75a828ad759772b','fbefa764-6486-42bb-a436-111d5dfcc353',1938,'原为八路军晋察冀军区第1军分区第5支队支队长','原为八路军晋察冀军区第1军分区第5支队支队长，1939年12月叛变投敌，率部袭击抗日政权，杀害多名抗日干部，后任伪军团长，在涞源、易县一带配合日军扫荡，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-053312b02824404d8aaacfb32a5b788e','6b2952ed-6e25-44db-9a9b-3792f764bee4',1940,'原为地方土匪头目','原为地方土匪头目，投靠日军后任伪警备大队长，在涞源县内抓捕抗日军民，严刑拷打，直接参与杀害八路军侦察员和村干部，并强征民夫修筑碉堡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c3b2cea37a94938ab0bfc72d3dbb5eb','4e26ef08-6636-49db-afe4-94d47156510d',1939,'投靠日伪政权','投靠日伪政权，任涞源县伪知事，推行保甲制度，组织维持会，强征粮食和劳役，配合日军“治安强化”运动，镇压抗日群众，破坏地下党组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f56f82f5d0540168d7fdd8ab1033f9e','4a805348-6f08-4bb1-86f6-dfea994e407b',1937,'日军侵占涞源后率先组织维持会','日军侵占涞源后率先组织维持会，为日军提供粮草、向导，协助建立伪政权，并煽动民众投降，后随日军行动，参与清乡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86c4e76a7920412cb121c4704995882a','20feef26-81f1-40f5-89ae-20d7c61e1471',1941,'任伪警察所长期间','任伪警察所长期间，指挥伪警搜捕抗日家属，破坏交通线，多次带队突袭村庄，抢劫财物，并参与杀害被俘的八路军伤员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-161b2ec619694dceadb853996d23d493','42112e73-4b58-4f59-abc0-474d8dac5756',1940,'负责日伪“新民会”在涞源的活动','负责日伪“新民会”在涞源的活动，推行奴化教育，组织“青少年团”刺探抗日情报，并协助日军诱降抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c0a0fd183734237bcf9e52d66516d34','c5406971-9b98-47c7-b9e3-cc88636b8b1b',1942,'原为国民党溃兵','原为国民党溃兵，投日后任伪中队长，多次率队袭击八路军游击队驻地，在走马驿、银坊等地杀害抗日群众，烧毁房屋。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf6100326bd147abb1fab9465739ab1e','6512ce8f-7e0e-4e18-b2fd-17707ca9242f',1943,'虽主要活动于豫北','虽主要活动于豫北，但其部队曾窜扰涞源地区，与日军勾结，接受伪职，其下属部队在涞源北部山区劫掠抗日村庄，抓捕壮丁。','危害等级A（甲级，省部级/大军区级要员）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0606fce003584199ac383250f797acff','8c4073ff-41d2-4f4e-804b-d8a91feb23c7',1943,'1943年投降日军后任伪职','1943年投降日军后任伪职，其势力范围波及保定西部山区，曾派伪军协助日军对涞源根据地进行“扫荡”，但本人未常驻涞源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f29d0b3426e44cbb283da6571c058d7','dd9a93e8-60b8-4ce5-aa81-29471a95fbfa',1939,'作为华北伪军最高指挥官','作为华北伪军最高指挥官，其下属部队多次在涞源地区与八路军作战，指挥“治安肃正”行动，间接导致涞源多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3928d7e287a34712af257fdae83be14a','4ed05709-d003-40bc-a44c-ff33b6710b7e',1937,'投靠日军后任涿县伪县长','投靠日军后任涿县伪县长，组织伪保安队镇压抗日民众，配合日军扫荡，残害抗日干部和家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b6e8215c3a4450da0e1cee949984c6d','5ac7ba17-0458-4a17-879e-9d7e28110da8',1938,'率伪警备队多次袭击抗日根据地','率伪警备队多次袭击抗日根据地，抓捕并杀害八路军侦察员和地下党员，烧毁村庄。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2461ab6b9e746028f3240b9ec0d8c6d','f87a7d96-a2d7-4f3a-bbcf-90a235490f37',1939,'原国民党地方官员','原国民党地方官员，投敌后任伪保定道顾问，协助日军推行“治安强化运动”，在涿州一带强征民夫、掠夺粮食。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d42d425ea284278a255ff17657d7cea','2c7505d2-5f6c-43f1-94b2-c6ea9fa90806',1940,'原土匪武装头目','原土匪武装头目，投日后改编为治安军，驻防涿州、固安一带，多次参与“清剿”八路军，屠杀抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3886be971624b059b52d6cc4996623d','82effeae-0214-4a99-b8be-cd4f0c9ced23',1941,'主持新民会涿县分会','主持新民会涿县分会，推行奴化教育，组织“反共救国会”，搜集抗日情报，协助日军抓捕进步青年。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f265246ce5d740b281ccaf6d262401cd','01fe18a8-a420-46e2-b1d6-4f336f757208',1942,'指挥伪警察特务','指挥伪警察特务，破坏涿州地下党组织，逮捕并刑讯逼供抗日志士，导致多名党员牺牲。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-571c2e9e2d614043baac34e56be25497','8c6c98e1-4fdb-4fd3-a036-bd8e4cb1948e',1943,'原国民党军官','原国民党军官，投敌后参与策划对涿州、新城等地的“铁壁合围”，为日军提供当地抗日武装情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eba6f434705c4df6a6932f4a33263b74','f68ddec5-8d9f-4f7a-9ecd-c3f437b2d907',1943,'1943年投敌','1943年投敌，其部队曾驻防冀中地区，包括保定南部及涿州外围，配合日军进攻八路军冀中军区。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d5aa73dbec74958b9a4b1c2a6259b34','84cfe441-d0d7-4658-b926-94716460998f',1938,'在清苑、保定一带组织伪军','在清苑、保定一带组织伪军，多次配合日军扫荡抗日根据地，杀害抗日军民，烧毁村庄，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5355af6eef21458bbe952b8caa982816','87b44cda-2261-4711-8248-669367c086f9',1939,'率伪警备队协助日军清剿','率伪警备队协助日军清剿，抓捕抗日干部和群众，实施“连坐”政策，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f69aba89c234e5abc3dc7b3a035d190','fb2f854c-68ce-485d-84d0-a485f4dc8791',1940,'推行奴化教育','推行奴化教育，强迫群众参加“新民会”，搜集抗日情报，破坏地下党组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f504ef8b5cbc48278630d8df22a14780','61d6de30-2484-4a5e-a2c7-b96c841bc912',1937,'日军占领清苑后率先投敌','日军占领清苑后率先投敌，组织维持会，为日军征粮派夫，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e2b72b8a08c4739af693e0f1d54c993','96657f6b-5c3f-4fcb-b86b-5c7c8c231b38',1941,'专门刺探八路军情报','专门刺探八路军情报，带领特务抓捕抗日家属，严刑逼供，杀害多名地下党员。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-edf0d3683c9c4c1db22db7bd28d74d74','75667e41-dd9f-46d4-be5a-550d18e7fb32',1942,'任伪知事期间','任伪知事期间，推行保甲制度，强征壮丁，搜刮民财，配合日军“治安强化运动”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-65d583b5b5394d518f848f39627b4966','d3afb384-fdfb-486c-a6d9-7b9ea2b2c506',1940,'指挥伪警察镇压抗日活动','指挥伪警察镇压抗日活动，破坏交通线，逮捕并杀害抗日游击队员。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42967cf8bba0471782d6849e90bdd9c0','5f36ce75-4796-4917-a881-12b528632868',1939,'组织自卫团为日军站岗放哨','组织自卫团为日军站岗放哨，参与“扫荡”，抢劫百姓财物，焚烧村庄。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-575471736d87437c89b5f313b3d9e9f1','697ad07f-d144-48da-921f-a8d77a9c8a39',1938,'原为地方武装头目','原为地方武装头目，后投靠日军，任满城县伪保安联队队长，多次配合日军扫荡抗日根据地，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c6d8050e8a24cdd8365a9b6a772eae6','56e111c8-36d6-4cd1-b942-a2cce72c3ed1',1939,'任伪满城县知事期间','任伪满城县知事期间，推行保甲制度，强征粮税，协助日军建立情报网，抓捕抗日地下人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5d618ec2fb64c5bbdb1f92b9f4b2b6a','b42d95c0-c348-4a8d-bdd4-3930910032c5',1940,'率伪警备大队多次突袭满城西部山区抗日村庄','率伪警备大队多次突袭满城西部山区抗日村庄，烧杀抢掠，并参与制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-783238e956324ab8a00d1c5bb8cd1c9a','8cffcf4c-32cc-4c35-b24b-aa2226a33e35',1941,'负责在满城推行奴化教育','负责在满城推行奴化教育，组织“新民会”宣传亲日思想，强迫民众参加反共集会。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b819555bf78493b9a90e514162999d1','68247a72-9717-4fd5-8a85-159791582945',1942,'指挥伪警察搜捕抗日家属','指挥伪警察搜捕抗日家属，严刑逼供，破坏地下交通站，导致多名抗日干部牺牲。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ce6282fe81040bdb5063dabbbc935d9','0754ec3e-b567-4457-87b3-2399b390db6d',1940,'在满城城关一带为日军征粮派夫','在满城城关一带为日军征粮派夫，告密抗日积极分子，致使数名群众被杀害。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6acfd60616e0472e93a128b513098a33','fce94a8e-64c1-44b2-9680-9644b0163196',1943,'虽为军阀出身','虽为军阀出身，但1943年后公开投敌，其部队在满城、易县一带配合日军“清剿”，劫掠百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-efaf95aba025465b9f06cb5a9d985673','217fd85f-4c2c-4563-b264-fbab076dca71',1940,'反复无常','反复无常，最终投日，其部队在保定、满城一带参与“治安强化运动”，围剿八路军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4e1401d0d744d479cc192d0710c3de5','d5ce854a-73ee-414e-afa8-e0e98ba1ae67',1943,'1943年投降日军','1943年投降日军，所部在冀西包括满城地区协助日军防守据点，进攻抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7863a5ec3569427ea51afa8738823c5b','a788b04b-ab63-4201-8723-02f9357144e0',1942,'率伪军数万人在冀中、冀西地区包括满城','率伪军数万人在冀中、冀西地区包括满城，配合日军进行“铁壁合围”扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e53e9436ea44ac18e55a15663d805d1','25bff1ac-810c-4120-91ef-a4ab1fb1a7b0',1937,'原为土匪','原为土匪，后投靠日军，任伪河北省保安队司令，在保定地区残酷镇压抗日军民，制造多起血案，后任伪保定道尹，协助日军推行“治安强化运动”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d28a888efab14dfab85111cf9ba0cd67','d7320f04-5bc0-437a-a67d-21fc0d2f3ec8',1938,'任伪保定市市长期间','任伪保定市市长期间，积极推行日伪政权各项政策，强征民夫，搜刮粮食，协助日军建立保甲制度，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4627ffcdec084aa5aeafe173ee9ce983','b475595e-ceaa-41df-940e-9e6e7258a94e',1937,'虽为华北级汉奸','虽为华北级汉奸，但多次到保定视察督导，推动伪政权在保定地区的建立，支持日军清乡和“三光”政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-099e7e966fe240f3a19df90b7c273ca8','33412a79-f559-4ae0-9f84-bda679132800',1937,'作为华北伪军最高指挥官','作为华北伪军最高指挥官，多次在保定地区部署“扫荡”行动，其部队在竞秀区（原保定城西）一带杀害抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67f5acb7d53d4ee88c4597e6bfe877a8','a91e9283-b9da-4f79-8621-1cbda2929a69',1938,'任伪保定县知事期间','任伪保定县知事期间，为日军提供情报，组织伪警察抓捕抗日地下党员，强征劳工送往东北。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f77117e6ea4c4fd6b6af4617e3ee6ac1','ff164802-dcb8-4732-8041-93b70edb52b7',1940,'率伪保安队配合日军在竞秀区及周边村庄进行“清剿”','率伪保安队配合日军在竞秀区及周边村庄进行“清剿”，烧毁民房，抢掠财物，杀害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-358d9347c5c24ce6805b8861d4539127','01d56dfe-bfda-4b8b-a11c-596eeffd072c',1939,'主持伪警察局','主持伪警察局，设立特务机构，破坏中共地下组织，逮捕并刑讯抗日人士，直接参与多起屠杀事件。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20979c6ddcf64956b948b8a9edd812e7','3ce91d5f-ee68-4047-8d1d-ee16d7c27777',1937,'原北洋政客','原北洋政客，投日后任伪华北政务委员会要职，在保定、莲池一带推行日伪统治，镇压抗日力量，协助日军进行经济掠夺和奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57f3a1a537b34084988231dda7377483','1be18a5e-94e0-457f-b039-00dbbca31eb1',1938,'北洋时期政客','北洋时期政客，投日后任伪河北省长，驻保定，推行保甲制度，强征粮食，协助日军建立伪政权，镇压保定地区抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-380d49d1926b45ab9662567327bef6d0','1be18a5e-94e0-457f-b039-00dbbca31eb1',1938,'在河北（含秦皇岛地区）推行伪政权政策','在河北（含秦皇岛地区）推行伪政权政策，协助日军征收物资，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd82e30ba1cb460d89fc7ef8e7431927','65d0e747-2ac3-4c93-9c5a-f915a5957075',1937,'保定本地士绅投敌','保定本地士绅投敌，组织维持会迎接日军，后任伪保定道尹，为日军提供情报，强征民夫，破坏莲池书院等文化场所。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8fce875cfd654ba69588f2799cab1c68','cd464e70-7e2d-4217-9a44-007fcfbb3c1b',1938,'原土匪头目','原土匪头目，投日后任保定伪保安队长，多次参与对莲池周边村庄的烧杀抢掠，抓捕抗日军民，双手沾满鲜血。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-416d787873e34a7b9473284a499ddf74','d505a928-45f6-4516-9420-aff105cdd0dc',1939,'投日后主管伪省警务','投日后主管伪省警务，在保定设立特务机构，破坏地下抗日组织，逮捕进步学生和爱国人士，施以酷刑。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-692e959d48314856a8fcdfdf4b54c958','8ddb8506-f476-4e3d-a7b1-fad57cb040d0',1940,'投日任伪保定市长','投日任伪保定市长，推行日伪“治安强化运动”，在莲池地区实行连坐制，强征捐税，为日军修建军事设施。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4de23f41cb44e45a98e1f89ba90de85','372fece1-77b4-4aef-b0e9-72c4f6293ba2',1938,'投日后控制河北教育','投日后控制河北教育，在保定各学校推行奴化教育，强迫学生学日语，取缔抗日教材，迫害爱国教师。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5956a296149d477cb9ad875c89d3ca9b','1d58509b-b3bb-491a-ada3-6a06e01fa397',1941,'原地方军阀余部','原地方军阀余部，投日后负责清乡，在莲池周边多次组织“扫荡”，杀害抗日干部，抢劫民财，纵容部下奸淫妇女。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a290da09e3904eb58f81c5ae959ae94f','37a38883-27d2-49f4-a4ed-018e323726cf',1940,'原国民党败类','原国民党败类，投日后任伪绥靖军支队司令，驻保定，多次配合日军进攻晋察冀根据地，在莲池一带设立据点，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46eee8ce682e4676a35e504b19931efd','0b04ad4d-0b36-48f2-a837-6474679dba3f',1938,'原国民党将领','原国民党将领，后与日军勾结，在冀中地区进行反共活动，协助日军扫荡抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa3a0c92013f4d99bbb585dd51ccf14d','0b04ad4d-0b36-48f2-a837-6474679dba3f',1938,'原国民党将领','原国民党将领，在河北组织民军对抗八路军，后与日军勾结，配合日伪军进攻抗日根据地，1940年被八路军俘获后释放，但继续从事反共活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a51a39336fe3437da27eeb125841b1f6','8b5fd216-027b-4b3a-b927-f5858f41d609',1939,'任伪蠡县县长期间','任伪蠡县县长期间，推行保甲制度，强征粮食，配合日军清剿抗日武装，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
