INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6687172db9d94dad9a3fd73b830c47a5','fb1a71e0-7f15-4d6c-85e6-66f925317048',1940,'在任期间推行保甲制度','在任期间推行保甲制度，强征壮丁，搜刮民财，配合日军“三光政策”，多次率伪警包围村庄，杀害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b262b37ea63a49dc934239f2da646d08','f557c3a9-35c4-4fd8-9f7d-ffdfe486ba2b',1941,'指挥伪警察特务','指挥伪警察特务，破坏高阳地下交通站，逮捕并严刑拷打抗日群众，向日军提供情报，致使多名游击队员牺牲。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce8cd3989d164ce1a2185406edfecbeb','f8bc0693-d271-413c-944f-48786153f623',1942,'率伪军驻扎高阳、蠡县交界','率伪军驻扎高阳、蠡县交界，多次进攻八路军游击队，烧毁抗日村庄，抢掠物资，并杀害地方抗日干部。','危害等级B（乙级，市县厅局级）','hanjian');
