INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1eafabd6e5d54d5bbe3d0fefb0bc7fce','87bfad7c-12d7-4b2a-bb1d-8f2b22184ac7',1935,'初期为冀东伪保安队军官','初期为冀东伪保安队军官，驻防通州，曾参与镇压抗日活动，但1937年通州事变中反正，击杀日军，后脱离伪职。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b618df7c4ce3425fa5f6b56595908558','f19b84e9-9fd7-4ecf-840d-97c27169c1af',1935,'伪冀东保安队军官','伪冀东保安队军官，驻防冀东地区，参与维持伪政权统治，后随通州事变反正。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e533e9943a4e46f4afa8c9bca9853c83','45b274fa-34bd-4a60-839b-3182d953f241',1936,'在唐山地区推行伪政府法令','在唐山地区推行伪政府法令，组织汉奸团体，协助日军收集情报，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc1851d6fc7049e88040abaced84ef0b','67f0aaf8-5243-4963-9f65-74b3d9e38c56',1935,'负责冀东伪警察系统','负责冀东伪警察系统，在唐山、滦县等地建立伪警察所，抓捕抗日分子，协助日军进行“清乡”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcbcfc1bfdf1411eb6aede98d2298f66','74797dff-05e1-4853-896a-cf26e19f1413',1938,'在丰润县（今属唐山市）推行伪政权','在丰润县（今属唐山市）推行伪政权，组织“自卫团”配合日军扫荡，强征民夫修筑炮楼，残害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1ed17fc604b4a999127dd792afa3f36','4a07b1fd-6f4a-49a4-ac96-8d108ecad15c',1939,'在滦县（今属唐山市）任伪县长','在滦县（今属唐山市）任伪县长，积极为日军提供粮食和情报，参与“治安强化运动”，杀害多名抗日群众。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-582e3651417f4dab80a46519ffa454aa','ec84b5af-0408-4d01-853d-6b585adb6a83',1940,'作为伪河北省冀东道行政长官','作为伪河北省冀东道行政长官，驻唐山，统辖冀东各县伪政权，推行保甲连坐，组织汉奸武装“反共自卫团”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-949a22385101400d9c4ab0a5cbda2312','88792779-7f90-4cc6-a1eb-aab45196b621',1941,'原东北军军官','原东北军军官，投日后任伪绥靖军司令，驻唐山，率伪军多次进攻冀东八路军根据地，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e6d049c77844bf196471f6b1c567e55','d0429967-0e03-42c7-a416-9b75a3ff2bea',1938,'在唐山市区任伪警察局长','在唐山市区任伪警察局长，残酷镇压工人罢工和学生运动，逮捕并刑讯抗日地下工作者。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6de31d7ff9e4b0e8420cbbb3feef260','b7879cb3-d10e-4095-92b0-2aadbdf77b05',1942,'组织汉奸武装','组织汉奸武装，在唐山周边村庄进行“扫荡”，烧杀抢掠，杀害八路军伤员和村干部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9d60cc433ff4b1684482e50a1387e1b','0fdfd145-e854-44a2-9a5a-bed459b6f8b4',1940,'在唐山高各庄一带组织维持会','在唐山高各庄一带组织维持会，为日军带路，提供抗日人员名单，协助日军屠杀村民。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96e276d7225e465e84bdfc5913d9f364','29a4b8de-e88f-4e65-854f-e7d84d1075d1',1943,'原国民党将领','原国民党将领，1943年投日，任伪冀东保安司令，驻唐山，率部配合日军“扫荡”，但后期有动摇。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-793aa973b9d0475f8ec744735e77db49','d448e343-b421-4150-812e-18c3798e3c8e',1938,'管理唐山煤矿','管理唐山煤矿，强迫矿工为日军生产煤炭，克扣工资，镇压矿工罢工，致多起矿难。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a9e026736c8486e88d8746d208dd775','79eaac1d-6929-4182-9fc9-958188fb1ac0',1939,'推行奴化教育','推行奴化教育，强制学校教授日语，删改历史教材，迫害爱国教师，组织学生参拜神社。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3163e77b8bf49eea4cd9f8b64b62158','2da81a05-cee8-4e20-a2b0-eadc2f38e082',1941,'在唐山高地区（今开平区一带）组织伪联防队','在唐山高地区（今开平区一带）组织伪联防队，配合日军“清乡”，杀害抗日积极分子，抢夺民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c8a91324037426bba1f3ebf30489217','71b4d14f-0354-4606-b562-0bc5ce2c723c',1935,'初期在唐山、开平执行伪政府命令','初期在唐山、开平执行伪政府命令，但1937年通州起义反正，此处仅列其前期汉奸行为。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8de1d9f8e474d3aaa18ea04287ac5c8','71b4d14f-0354-4606-b562-0bc5ce2c723c',1935,'初期为伪冀东保安队军官','初期为伪冀东保安队军官，驻滦县，后于1938年通州起义反正，但此前曾参与镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c32528aa080d42a595e00fc28a7ac832','71b4d14f-0354-4606-b562-0bc5ce2c723c',1935,'初期在玉田地区执行伪政权命令','初期在玉田地区执行伪政权命令，后于1937年通州起义反正，但此前有助敌行为。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-712241f367f447b0a01b5af8e77d153a','71b4d14f-0354-4606-b562-0bc5ce2c723c',1935,'初期投日','初期投日，在唐山地区维持伪秩序，1937年通州起义反正，但此前曾参与镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a764822cff2445cb8151c67de44891be','17b5691b-652c-41c0-b4b5-8ab2a2c32788',1935,'驻防唐山地区','驻防唐山地区，协助日军收缴民间武器，强征壮丁，破坏抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-103c1ef0db9b4a548e95abb13522492b','aef7a0e4-9d5b-4920-ac2a-b904b1a04ecd',1938,'1938年伪冀东政府改为伪河北省后','1938年伪冀东政府改为伪河北省后，任伪唐山市长，推行日伪经济统制，强征粮食煤炭，为日军提供战争物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33be68e1f8a849d09e4c8f5da86f1f36','6812f450-3394-48b5-8ba1-eec3fa325d6e',1938,'指挥伪警察在唐山、开平地区搜捕抗日地下党员','指挥伪警察在唐山、开平地区搜捕抗日地下党员，破坏交通线，多次参与“治安强化运动”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41a52d84bb854d73938e6d7bad56643e','1721d81a-1a9e-464b-bc1f-269abcdb61c0',1938,'在唐山、开平、滦县一带组建伪军','在唐山、开平、滦县一带组建伪军，配合日军进行“铁壁合围”扫荡，杀害抗日干部数百人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f031d86228534db2bd58a0ad90559710','1721d81a-1a9e-464b-bc1f-269abcdb61c0',1938,'率伪军驻扎唐山、迁西一带','率伪军驻扎唐山、迁西一带，多次进攻冀东八路军，制造“潘家峪惨案”等血案（潘家峪属丰润，但活动范围覆盖迁西）。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea349501ce9b40e4b1c92a35f24d3eda','7a6aa41e-908d-4645-9ab7-af99888a6ff5',1936,'长期盘踞开平镇','长期盘踞开平镇，设立据点，勒索百姓，多次袭击八路军游击队，烧毁村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5596a97b4efe468abd6a9cc1a5bc36e6','ca43e20b-c331-45f3-ab9c-b70691419faa',1937,'日军占领开平后组织维持会','日军占领开平后组织维持会，为日军征粮派款，提供情报，协助建立伪区公所。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58c6bdb9be1e4d7e956724e65ea99b37','afc39469-36c4-4f84-9868-1c21fb62f604',1940,'在开平推行“保甲连坐”','在开平推行“保甲连坐”，强抓壮丁送日军当苦力，克扣抗日家属救济粮。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0f34f273d07448794e13af629ab84a7','569f682a-7f6a-43f1-a331-97ff52c81172',1935,'在唐山、开平各学校推行日语教育','在唐山、开平各学校推行日语教育，篡改历史教材，强迫学生参拜日本神社。','危害等级A（甲级，省部级/大军区级要员）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5f1e0e5c69f4d3d900f70369046d079','c366bea0-2d84-455d-b7bb-25c4f4bb72e7',1935,'虽主要活动于东北','虽主要活动于东北，但曾为殷汝耕出谋划策，涉及唐山地区伪政权设计。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-571f3776f0cb4e319773687f25220e88','c7701e83-be43-4b4e-8c4f-bedaf5826fbe',1940,'虽总部在北京','虽总部在北京，但其伪军部队多次在唐山、开平地区扫荡，指挥“治安军”屠杀抗日群众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1de33dcf90bd4a7893d9158ddd1fedb5','baa59f1b-2a77-4d2e-a632-d6fe1f4c2b2c',1941,'率治安军驻扎唐山','率治安军驻扎唐山，配合日军进行“剔抉”扫荡，在开平制造无人区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a131be62b42744e5a61dcc38cde50a5f','fc48b1e7-b0c5-4c35-bb2f-5b473b445584',1935,'1935年11月在通州成立冀东防共自治政府','1935年11月在通州成立冀东防共自治政府，宣布冀东22县脱离国民政府，管辖范围包括唐山、曹妃甸所在地区，为日本侵略者服务，征收苛捐杂税，镇压抗日活动。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dae301bd6f704a699423e4ec8b6c37bd','fc48b1e7-b0c5-4c35-bb2f-5b473b445584',1935,'1935年11月在日本扶植下成立冀东防共自治政府','1935年11月在日本扶植下成立冀东防共自治政府，辖冀东22县（含唐山、路南地区），公开投敌，为日军提供粮秣、劳役，镇压抗日活动。','危害等级A（甲级，地方伪政权首脑）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4a0bc71dc904097ad9c2b68b8b949c8','04ed1320-b858-46fb-816a-d4a137cd87c1',1935,'协助殷汝耕管理冀东伪政权','协助殷汝耕管理冀东伪政权，参与组织伪军和警察，配合日军清乡，在唐山地区推行奴化教育。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9634a27e1d04bcd8357d8ba912bfe34','04ed1320-b858-46fb-816a-d4a137cd87c1',1935,'协助殷汝耕管理冀东伪政权','协助殷汝耕管理冀东伪政权，参与推行奴化教育、征收苛捐杂税，配合日军清乡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7e38346056042a6b610cae5af703fdb','a79d1abb-64a3-49cc-ad6f-9b0fb0688575',1935,'在冀东伪政权中负责民政事务','在冀东伪政权中负责民政事务，协助日军控制唐山、滦县等地基层政权，强征民夫修筑军事工事。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9e171d59aa141f993ee1c30de310139','a79d1abb-64a3-49cc-ad6f-9b0fb0688575',1935,'主管伪政权民政事务','主管伪政权民政事务，组织保甲制度，协助日军建立治安维持会，迫害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1517f43325e4970b03cd8cf34c12b8a','51955def-5c42-45c2-b430-5e54401bf0dd',1935,'统率冀东伪保安队','统率冀东伪保安队，驻防唐山一带，多次配合日军扫荡抗日游击队，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
