INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ae9efa1a50043058a2b3e5fb6007ed4','5e6568f7-506e-4c05-95ef-7412b4264104',1935,'原冀东保安队军官','原冀东保安队军官，初期在唐山地区为伪政权效力，但1937年通州事变中反正起义，击毙日军顾问，后脱离伪职。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fe4ecd8e116466f962e750d2402ddb8','5081f3f3-304e-449c-8ece-3cf4e910e467',1935,'与张庆余一同在通州反正','与张庆余一同在通州反正，但此前曾在唐山、迁安一带执行伪政权命令，参与镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46fa5c92a70546acbd5319de6319f400','84752224-79a2-4b68-a578-825ee1c59791',1936,'在迁安县任伪县长期间','在迁安县任伪县长期间，推行日伪保甲制度，强征民夫修筑公路和炮楼，搜捕抗日分子，向日军提供情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b04412a13bc47139381e5fd24be0bc5','45f77d76-8d7a-4e3d-abb8-d0ad30bb444f',1937,'在唐山市区任伪职','在唐山市区任伪职，管理日占区民政，协助日军实行经济统制，掠夺开滦煤矿资源，镇压工人罢工。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ee1c1ce7dbf44919006b1e7ea72aa1a','66c1fe59-6ce0-4db3-95f9-eff8ddb8ab94',1936,'在唐山、滦县、迁安一带率伪军多次围剿冀东抗日联军','在唐山、滦县、迁安一带率伪军多次围剿冀东抗日联军，杀害抗日军民，后被抗日武装击毙。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bbd910163a8d4d339af4f67be5c3ac41','754716fa-b811-4c2a-b106-cee8571cf81f',1938,'在迁安地区组织伪保安团','在迁安地区组织伪保安团，配合日军进行“扫荡”，烧毁村庄，抓捕抗日家属，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5721cc8f19d433cb25cd0861eb22d55','4669de3b-7692-47ce-af0b-54d7ab3f7b4a',1939,'在迁安县城及乡镇建立伪警察网络','在迁安县城及乡镇建立伪警察网络，严查抗日地下交通线，多次带队搜捕八路军游击队和地下党员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcc385750a824795bb97b228f37f2695','7390f6d5-d056-47a8-9297-fd3f114b15e1',1938,'作为冀东地区最高伪行政长官','作为冀东地区最高伪行政长官，统筹各县伪政权，推行“治安强化运动”，在迁安等地实施“连坐”制度。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46e8b490c51d44cbb09b524f3183769e','104b16ce-5c0a-4000-a78b-331e3b5b9d37',1937,'在滦县、迁安交界地区组织维持会','在滦县、迁安交界地区组织维持会，为日军筹集粮饷，诱降抗日人员，破坏地方抗日武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d48c59932204fd1b5d7baced0e8e8c7','b75a2ad3-0e53-4ca1-8af5-765e14d53da5',1935,'虽主要在伪满任职','虽主要在伪满任职，但多次到冀东唐山、迁安地区指导伪军作战，协助日军策划“扫荡”方案。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc00d8ac446d4e19b14218ff4650f2c2','babe20b2-caf9-4dda-97ea-5c8d36207df5',1935,'参与冀东伪政权法律制定','参与冀东伪政权法律制定，为日伪统治提供“合法性”包装，间接助长唐山、迁安地区的殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25126cc3d7b24dfab23cc79e3330cf4e','8961ebbd-948e-461b-8f48-eeb5b42f4738',1940,'作为华北伪政权最高头目','作为华北伪政权最高头目，其统治范围覆盖唐山、迁安，支持当地伪军警镇压抗日活动，推行奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a777b160fbd44a82a01e8052ef537e06','436e71da-1761-4626-b313-8c7389a1f94f',1938,'长期驻守唐山','长期驻守唐山，指挥伪军参与对迁安、遵化等地的“清剿”，杀害抗日干部和群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bfa4e8ec7b764495af3c9a9523284172','4fcc514c-39c8-45d7-a2b2-52c4da984567',1940,'在迁安推行新民会奴化宣传','在迁安推行新民会奴化宣传，组织青少年接受日伪教育，收集抗日情报，协助日军“宣抚”工作。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6d0997cf1634db9a3bd98bbf15ba714','37de03f8-f03b-4917-a1ee-72597654a1b1',1943,'虽为军阀投机','虽为军阀投机，但曾在冀东地区（含迁安）与日军合作，参与对抗日根据地的进攻，后于1945年投降八路军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b70e020f518c43df8ebca462cb28925d','31900469-72b6-4659-b8d6-461cb091f920',1938,'伪冀东道（辖唐山、迁西等县）最高行政长官','伪冀东道（辖唐山、迁西等县）最高行政长官，推行日伪“治安强化运动”，组织汉奸武装“反共自卫团”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-216a36d270114d8fbd550361e16b987a','bd52497f-4f7e-4e2a-b68e-2749b4119347',1938,'在迁西县（时属迁安县）推行日伪统治','在迁西县（时属迁安县）推行日伪统治，强征粮食，建立伪村公所，配合日军“扫荡”抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8aaa195783df4233a840b696f4f26da8','4c19b865-14c8-4d72-ab45-0ec4a45312b8',1939,'日本顾问的华人助手','日本顾问的华人助手，参与策划对迁西山区抗日游击队的围剿，残害抗日家属。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ef09186ad344728b19c763c61aba167','9e9186cf-5c03-4874-8eaf-d002c854685d',1940,'在迁西、遵化边界地区设卡盘查','在迁西、遵化边界地区设卡盘查，捕杀抗日干部，破坏地下交通线。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-074a34ceaf5547028e8bc179346d3e03','0cf6e11c-d9fd-4413-bfa9-3580edd9ebe3',1937,'唐山沦陷后组织维持会','唐山沦陷后组织维持会，为日军征集物资，协助建立伪政权，后任伪冀东银行董事。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-290c7058d77f4444baee0e2b6efa827a','135d797e-b1a7-4e1b-b30c-a7e52455b380',1938,'在唐山市区推行日伪经济统制','在唐山市区推行日伪经济统制，强征劳工，镇压工人罢工，迫害抗日分子。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79537efce5f24b4094e671b9733a08d1','b87e4881-fd7c-4f4b-953f-63406d150b4d',1937,'虽主要活动于北平','虽主要活动于北平，但多次赴唐山、迁西指导“治安肃正”，为日军出谋划策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a003398b66264e519ce32d914f608aac','eb894f39-ac64-4471-8e60-d3f6e536bbf1',1943,'接替王铁相','接替王铁相，继续推行日伪统治，在迁西等地强抓壮丁补充伪军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9d73995454d40b5828ea1d2eb9a223e','687dabae-680e-443c-af4b-c01a6a8e3a2a',1941,'率伪保安队常驻迁西金厂峪一带','率伪保安队常驻迁西金厂峪一带，为日军护矿，镇压矿工反抗，杀害抗日游击队员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff8b0adf1e4b485695a89bba35804990','60a33138-5c6d-4ad8-90ac-3679cf5bf14f',1938,'在唐山、迁西地区组织新民会','在唐山、迁西地区组织新民会，进行奴化宣传，搜集抗日情报，协助日军“宣抚”。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92d52040275f48009c20abdd92b9dfd4','412c7abd-fc70-488c-8665-e2a860b920be',1940,'在迁西县城及主要集镇设立警察分所','在迁西县城及主要集镇设立警察分所，抓捕抗日地下党员，刑讯逼供，致死多人。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3639098b4b341a7863b2df03a405b19','d415d2ac-9be9-4924-8801-529ec92d29be',1931,'原为奉系政客','原为奉系政客，后投靠日本，参与策划冀东事变，协助建立伪冀东防共自治政府，并任顾问，为日军在冀东地区统治出谋划策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84db3407cd3947d684a956bcdd96d43e','a842e90d-30a9-4333-9c63-5018df81d46a',1935,'驻防唐山地区','驻防唐山地区，多次率伪军袭击遵化、迁西等地的抗日武装，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24e1a53f5b4f496dad8b1336f0f2ef1b','6fadf4d3-d605-4a59-b1c1-47f8a73c629b',1937,'虽为华北级汉奸','虽为华北级汉奸，但其指挥的伪治安军多次在唐山、遵化地区进行大规模“扫荡”，直接参与屠杀抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-699ed71f58d14431ba3ee1fc357347e0','6fadf4d3-d605-4a59-b1c1-47f8a73c629b',1937,'北洋军阀旧部','北洋军阀旧部，投敌后任伪华北治安军总司令，组建伪军配合日军扫荡华北抗日根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-571fc4626abd4fb38d8df0f77b61ec4c','71450b77-0cfb-4c91-9a93-0917403266f1',1939,'率伪治安军驻扎冀东','率伪治安军驻扎冀东，在遵化、唐山等地建立据点，配合日军推行“治安强化运动”，围剿八路军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f578911d56234eeab51710fbe635bf74','42bd674f-5dd3-46b9-91cc-766f35ab6701',1938,'1938年伪唐山市政府成立后任市长','1938年伪唐山市政府成立后任市长，为日军在唐山矿区掠夺资源服务，镇压工人罢工，迫害抗日分子。','危害等级A（甲级，特别市市长）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-edf379f6858d410fbf293a97b230dca4','99ca1fce-6aee-4058-a4b9-502dddd74ab3',1938,'负责唐山地区日伪治安','负责唐山地区日伪治安，多次组织特务抓捕抗日地下党员，破坏抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-392fd1e9a2a847f3b9187d643ad3c571','cf44b84a-ec31-4d50-afde-4410537a1514',1938,'在遵化县推行日伪统治','在遵化县推行日伪统治，强征粮食，组织伪自卫团，协助日军在遵化山区修建封锁沟，围困抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be41366fd7134d419c126105e5001257','5aeab4f9-ddc2-468f-b1c3-6f1bc65f8a57',1938,'率伪保安队多次袭击遵化境内的抗日游击队','率伪保安队多次袭击遵化境内的抗日游击队，杀害抗日群众，烧毁村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a50abe3b99924d83a84f5f77023a7502','7207178e-0f41-45e5-b50b-c3eb5bdeacf8',1939,'在遵化县城及各乡镇建立伪警察网络','在遵化县城及各乡镇建立伪警察网络，搜捕抗日干部，为日军提供情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9eff4551c28e419fb335ab510405ece4','419d7ab9-f138-417c-b5cf-fdde4c59a96a',1940,'负责遵化地区日伪奴化宣传','负责遵化地区日伪奴化宣传，组织“新民会”活动，强迫民众参加反共集会，收集抗日情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-600e5411e4bc44829513065d1616d57d','d6e93a64-585a-4165-9a5d-2b490a696292',1938,'管辖唐山、遵化等县','管辖唐山、遵化等县，推行日伪“治安肃正”计划，组织伪军配合日军扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
