INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f82c2e7030284a23bbb0e3f428f9cf79','71d656ef-2bf6-468d-bcc0-4c5c22c3cdcd',1937,'察哈尔蒙古族上层','察哈尔蒙古族上层，投日后历任伪职，在张家口市区及察北管理地区协助日军实施经济统制，迫害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a85dd766fb94fa89af1948fc66876d8','8c41aaf1-93bc-4380-a6c1-577fe9c8db1b',1938,'原为察哈尔地方警察头目','原为察哈尔地方警察头目，投日后负责伪察哈尔盟警察系统，在察北地区抓捕抗日地下人员，参与“清乡”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7bcdd0f9fce4a028c57076ce6f7a9fe','2822cb28-023e-4f93-b268-536bc25ed700',1939,'原为张家口商会会长','原为张家口商会会长，投日后任伪市长，为日军征收粮食物资，强制推行“配给制”，并协助日军建立特务情报网。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7ba10fe596240398f11e8061cdd8799','151c8af9-7e60-468d-ae07-c5ff28b58321',1933,'原为土匪武装头目','原为土匪武装头目，投日后在察北张北、康保等地活动，率伪军配合日军进攻抗日根据地，烧杀抢掠，后任伪蒙古军副总司令。','危害等级C（丙级，基层头目）','hanjian');
