INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76e4dc2f333c4e338b298348689c4479','51022a0f-4fa7-4ab4-afef-3fad2e35332c',1933,'原热河地方军阀','原热河地方军阀，投日后率伪蒙古军配合日军进攻平泉、承德，镇压抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f6c50ca854641eb85420a8ebfca4762','c8d519d0-beb8-46c0-b527-c0d23f87e326',1937,'在丰宁推行日伪“治安肃正”政策','在丰宁推行日伪“治安肃正”政策，组织汉奸自卫团，强征粮食，配合日军“三光”政策，迫害抗日家属，破坏地下抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f3e36ba72bd45219fdeae23e6ead76d','1b5c8a9a-24d8-4909-8bf2-1041685a4cc7',1938,'在承德、丰宁交界地区设立多个警察分所','在承德、丰宁交界地区设立多个警察分所，抓捕抗日干部，刑讯逼供，曾亲手杀害多名八路军侦察员，并参与“人圈”管理。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-424285646386432e8d920955b5f32348','53496c5e-bbe4-4156-9df9-009c951c75b0',1940,'为日军宣传“日满亲善”','为日军宣传“日满亲善”，组织汉奸青年团，刺探抗日军情，协助日军在丰宁山区进行“梳篦式”清剿，导致多支小股游击队损失。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-863be37f17f843d3a2685935c35e7d2b','cbe9a89d-9c9b-4da7-b75a-7586918cff22',1935,'率伪军驻防承德、丰宁','率伪军驻防承德、丰宁，多次参与对抗日根据地的“讨伐”，烧毁村庄，掠夺牲畜，在丰宁黑山嘴一带制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22074a63e93242de87475f42365c89ae','4418a731-4859-4d29-95f1-37b6980ab923',1939,'直接指挥伪警察和特务','直接指挥伪警察和特务，在丰宁各地设立“检问所”，盘查行人，搜捕抗日分子，曾诱降并杀害抗日游击队小队长。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48577d07749b4ad28bd4ade6bfbc6f79','92958828-3a66-4402-b0d6-e1fb8fa1251e',1941,'组织汉奸保安队','组织汉奸保安队，配合日军在丰宁、隆化一带进行“大扫荡”，实行“连坐法”，强迫村民报告抗日活动，杀害无辜群众数十人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d11819eee89842bd976f2c0d60bbcf9d','9de4fa37-9b7b-403b-9df8-efa5177f1633',1942,'训练汉奸青年','训练汉奸青年，灌输奴化思想，组织青年团协助日军巡逻，曾带领特务抓捕丰宁地区的地下党员，并参与破坏抗日交通线。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2d0dd6235d84fbf9f92c32492582ed7','92b21275-e6fe-45c4-b0a7-a9883a8608b5',1933,'任伪兴隆县县长期间','任伪兴隆县县长期间，积极推行日伪殖民统治，强征劳工，镇压抗日群众，协助日军实施‘集家并村’政策，制造‘无人区’。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-642c177c202d4a72aff98ed824ab579f','f906a776-69aa-4a75-9c95-b4eea0c8dc41',1933,'投日后在热河地区（含承德、兴隆）协助日军作战','投日后在热河地区（含承德、兴隆）协助日军作战，参与镇压抗日游击队，掠夺资源，为日军提供情报和兵力支持。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa6f307e78e44df48f5e6ffae8141ab7','52179018-163c-4dfc-8c33-a00c7b0b343c',1935,'在兴隆地区组织伪警察队','在兴隆地区组织伪警察队，抓捕抗日地下工作者，破坏抗日组织，参与‘清乡’行动，杀害多名抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-668e602bef0b41cc915a41c9c700969f','f24fdb46-a519-4318-a679-aeedf99a350e',1938,'率伪保安团配合日军对兴隆山区进行反复‘扫荡’','率伪保安团配合日军对兴隆山区进行反复‘扫荡’，烧毁村庄，强迫村民迁入‘集团部落’，致使大量平民死亡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02c8a4144d6b421ba747e9134615836d','aed2d782-115d-4d3c-8dae-8ae8a2079acf',1937,'投靠日军','投靠日军，组织维持会为日军征粮派款，提供劳役，并告密抗日分子，导致多名抗日人员被捕牺牲。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8717ee00b6c4a928aa95def0a864c0d','c7c2d014-e1e3-4713-9b75-80b6a36e0f72',1939,'积极宣传‘日满亲善’','积极宣传‘日满亲善’，推行奴化教育，搜集抗日情报，协助日军实施‘三光政策’，在兴隆地区犯下罪行。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-668ea49f864b41769b556323bdfbe53c','4124065e-e01d-42a0-9538-c8545e0c17d9',1940,'指挥伪警察多次突袭抗日村庄','指挥伪警察多次突袭抗日村庄，逮捕并严刑拷打抗日群众，参与制造多起惨案，如‘狗背岭惨案’。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f6ccad59078b4a658abde77c4ff82924','76e08541-2ddc-444c-8681-e195ea85b789',1941,'组织自卫团协助日军封锁山区','组织自卫团协助日军封锁山区，切断抗日武装补给线，并亲自带队搜捕抗日游击队员，杀害多名伤员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7587f47d48a436f9b5a785437971cad','9ded40d2-ff9b-4773-837c-2ae1e4a49c71',1942,'充当日军特务','充当日军特务，打入抗日组织内部，策反叛徒，导致兴隆地区多个地下联络站被破坏，数十名抗日人员牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f2d6279bcd3459ebebc2cba3d119b7c','2cd6cfb6-ada0-4989-a3cb-2ae10e82b456',1933,'九一八事变后放弃热河抵抗','九一八事变后放弃热河抵抗，日军进攻承德时率部不战而逃，导致承德迅速沦陷','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c380c8635ebb48b89bf0a04c7adaa19a','2cd6cfb6-ada0-4989-a3cb-2ae10e82b456',1933,'后投靠伪满洲国','后投靠伪满洲国，任伪职，其旧部多被编入伪军，对承德及周边地区沦陷负有直接责任。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03b2841ec8d641b8aecaa14fabbbd5e5','9e52626b-30a2-429a-8cd3-05d1f0a52567',1935,'殷汝耕主要助手','殷汝耕主要助手，参与伪冀东政权运作，在河北地区推行奴化教育与经济掠夺，后伪政权并入伪华北政务委员会，继续附逆。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e34ea6d49d974fea8bbec0f778224739','2cd44bb5-8de7-4057-90cb-8113e4329057',1938,'曾任伪河北省长','曾任伪河北省长，在河北境内推行伪政，配合日军对承德及冀东、冀北地区进行治安肃正，掠夺资源，镇压民众抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-351250a230e2448fa645ba8026d23ddf','2f756d4f-512e-4098-aa33-b291f3b605ec',1937,'天津人','天津人，曾任伪河北省长，在河北地区推行亲日政策，协助日军维持占领区秩序，其辖区包括承德周边部分区域。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-969facde08f24327b5cd8e6db28d69f7','2f756d4f-512e-4098-aa33-b291f3b605ec',1937,'天津人','天津人，北洋政客，抗战期间投敌，任伪河北省长，其伪政权对河南北部地区有影响，推行日军殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-705aaf952eb140478214e893afa9c7e2','e63d4e16-d1d4-450b-943a-14f291bea57d',1938,'在河北任伪职期间','在河北任伪职期间，推行保甲制度、经济统制与奴化教育，配合日军对冀东、冀北抗日根据地的扫荡，承德地区亦受其伪政影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1af3ae319b046a7ac0c26e680a07c28','e63d4e16-d1d4-450b-943a-14f291bea57d',1938,'抗战期间投敌','抗战期间投敌，任伪河北省长等职，协助日军在河北推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc8e4129cef3401a9f40e149fff4c0de','e63d4e16-d1d4-450b-943a-14f291bea57d',1938,'在河北伪政权中任职','在河北伪政权中任职，配合日军扫荡抗日根据地，其伪政权与陕西周边抗日形势相关。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33272c5a891c4730af8d58f725b8fecd','da8c578b-1248-4800-8dc6-61431c985a5a',1943,'河北籍汉奸','河北籍汉奸，任伪河北省长期间继续推行日军殖民政策，在河北各地包括承德周边强化治安，掠夺物资，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-917f1278832649759d5edf5647195ba0','f57cd369-01e8-488c-9ad9-71387d56fc6c',1935,'长期在冀东及承德周边活动','长期在冀东及承德周边活动，率伪军配合日军扫荡，残害抗日群众，参与制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b200afcfccd42679243d8b05f8bfab7','04248424-a61a-4121-aada-01abc0f75fd1',1933,'在承德地区担任伪满警察要职','在承德地区担任伪满警察要职，负责侦捕抗日人员，推行保甲连坐，镇压承德及双桥一带的抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-759a52b07661419b85806e7dd4c02528','685f4585-8830-462a-8b44-4d68f51d0414',1933,'在伪满热河省任职','在伪满热河省任职，参与承德地区的殖民行政与经济掠夺，推行奴化教育，协助日军维持统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b75ec2c98c5549a28c9ed0ab72a59966','831bd8e8-24d8-4e19-b84a-4d3296661aa1',1933,'首任伪满热河省长','首任伪满热河省长，在承德地区建立伪政机构，推行保甲制度，协助日军镇压抗日武装，掠夺地方资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06d2c611678240098abf631faa2fb84d','01f53b3e-576e-47ab-97d0-9eb4e1119ec8',1937,'继任伪热河省长','继任伪热河省长，在承德及周边地区继续推行殖民政策，强化治安，配合日军扫荡冀热边抗日根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26beb0dbef16454f806f1542bf5fc391','57744d94-c56d-4049-81d8-30b8bce80ff4',1940,'在承德任伪热河省长期间','在承德任伪热河省长期间，推行经济统制与奴化教育，协助日军围剿抗日武装，镇压民众反抗。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ee4e472048b45b7a59402823b0291de','26cf3ac9-1450-4207-9de5-39bada7b3404',1943,'伪满末期热河省长','伪满末期热河省长，在承德地区继续执行日军殖民政策，强征劳工，掠夺物资，配合日军对冀热辽抗日根据地的扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67bfd043b628431694ffa596df25dadd','04b08fd1-e626-4353-8ebf-073bca1ee0db',1933,'在伪满承德县任职','在伪满承德县任职，直接负责双桥及周边地区的伪政事务，推行保甲连坐，征发劳工，协助日军镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-65fe0f7ee3e242b39a2044377db012c2','caf52869-edd1-4d3d-ab2a-d29b8024dbff',1931,'原籍河北','原籍河北，后投靠日本，参与伪满政权建立，协助日本在华北推行殖民统治，镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69fa254e417b4dfda5e8c5174cfe8c69','0098570b-36c7-4853-9115-32196b4918a1',1933,'原东北军将领','原东北军将领，投日后任伪热河省长，在承德地区推行奴化教育，强征劳工，配合日军清剿抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-381db0a01e3048a38605fd775f2b592f','de9549c9-1a7b-481d-8c54-986e5050af05',1933,'日本关东军指派','日本关东军指派，在承德地区实施“治安肃正”，组织汉奸特务网，逮捕抗日志士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9761e8a42ab54cc8a2427116dde15d8b','1142c178-19c6-4921-a263-89dc63e9a209',1933,'在双滦一带组织“自卫团”','在双滦一带组织“自卫团”，配合日军扫荡，杀害抗日干部和群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff89fe25d5484ec58a445cd598e27e2d','2730b9fc-83ef-4d0f-bb92-25fcc8ee43c1',1943,'虽为军阀出身','虽为军阀出身，但在热河地区活动时曾与日军合作，其部队在承德周边参与“剿共”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-376eca2f77f94ecf9c5bc4224d9754ca','a835bdd4-20d9-4d66-8cc7-0edba3528e4f',1935,'在承德地区组织协和会','在承德地区组织协和会，宣传“日满亲善”，搜集抗日情报，破坏地下党组织。','危害等级C（丙级，基层头目）','hanjian');
