INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7c90e83b91b48abb179d9349f9b4eb2','317db357-d271-4b49-afac-99fc8cb423fb',1933,'协助日军推行“治安肃正”和“集家并村”政策','协助日军推行“治安肃正”和“集家并村”政策，导致承德地区民众流离失所。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e32feb422dc42749f4259d3df9b7222','9337c93d-1627-4f9f-86d3-358dad7f93e0',1933,'组织汉奸团体','组织汉奸团体，宣传“日满亲善”，破坏抗日群众运动，协助日军清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce6ea6e852b14ddbb014ae259786c6c8','928e8cf6-7f39-42c8-9517-78694f41c94c',1933,'利用司法权力迫害抗日人士','利用司法权力迫害抗日人士，判处大量爱国者死刑或长期监禁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-40410d71af094a7091f73be04d5d1b7d','70021040-634c-4cd8-923a-9ec35c0b5f08',1931,'河北籍（滦县）大汉奸','河北籍（滦县）大汉奸，全面协助日本统治东北及热河，签署多项卖国协定。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7c5c9440378407ab0da43b9dcf3b21e','18b7a5ea-3fb1-4d56-9dd9-297bb9caf46b',1933,'为日军搜刮民财','为日军搜刮民财，征收高额捐税，导致承德地区经济凋敝。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9cde4a8c55554620b1b41490cba5ed2e','e19188e8-c446-4507-8e27-e28038a54148',1933,'率伪军配合日军扫荡','率伪军配合日军扫荡，屠杀承德周边村庄百姓，烧毁民房。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4c7c6f552b34d87813741692539883e','4f8e77d0-c017-4021-86bc-28e6de93c268',1933,'在承德各学校强制推行日语教学和奴化课程','在承德各学校强制推行日语教学和奴化课程，禁止中国历史教育。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b7213554fe44073acec0bf3ff557a6e','be455ef5-03e1-4504-af80-c54748ad2b35',1933,'指挥伪警察抓捕抗日地下工作者','指挥伪警察抓捕抗日地下工作者，严刑逼供，破坏地下组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e25eab5326304d959784938c277cf1dc','6459d607-b39d-4b97-8952-98c8e3e8e5f0',1931,'原奉系官员','原奉系官员，后投靠日本，参与伪满洲国建立，曾任伪立法院院长，后任伪华北政务委员会顾问，协助日本在华北推行殖民统治，涉及滦平地区日伪政权建设。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ceebe65fa39417684b5e1e6d8708c8b','6459d607-b39d-4b97-8952-98c8e3e8e5f0',1931,'原为奉系军阀官员','原为奉系军阀官员，后投靠日本，在伪满洲国及华北伪政权中任职，协助日本殖民统治，参与对河北、承德地区的资源掠夺和奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6fc70062d1624557a64f38f17633daff','6459d607-b39d-4b97-8952-98c8e3e8e5f0',1931,'原为奉系人物','原为奉系人物，后投靠日本，参与伪满洲国建立，并协助日本在华北推行殖民统治，曾到山海关一带活动','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0357789f1a1d46ba98e153cd43f14cb2','c9f197e7-46ea-4849-a1f6-e82c0766c432',1931,'东北沦陷后投敌','东北沦陷后投敌，任伪满洲国要职，曾参与对热河省（含承德、滦平）的日伪行政规划与殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6be72ab2a0894b9ba787c0fb30dfa26b','bfad49e8-b21b-4a95-ad07-7f0d6a3e8e20',1933,'原东北军军官','原东北军军官，投日后任伪热河省警务厅长，在承德、滦平一带组织伪警察，协助日军清乡、搜捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-013756a673f449958841d452a8ea83d2','bfad49e8-b21b-4a95-ad07-7f0d6a3e8e20',1933,'原东北军军官','原东北军军官，投敌后任伪警务厅长，负责清剿抗日力量，抓捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcd8cfd9b3734cc5b1c2128face912fc','bfad49e8-b21b-4a95-ad07-7f0d6a3e8e20',1933,'原热河省警察头目','原热河省警察头目，投日后负责伪警体系，参与抓捕抗日志士和镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01b6a80e696041ec9e7ba7d997053257','bfad49e8-b21b-4a95-ad07-7f0d6a3e8e20',1933,'原东北军军官','原东北军军官，投敌后任伪警务厅长，参与围剿抗日游击队，抓捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81db21a4247f4e0ba38b34d537f8575f','fc976de0-02a7-497a-83b6-720de8d17fd9',1933,'原热河地方武装头目','原热河地方武装头目，投日后任伪蒙古军总司令，参与日军对承德、滦平地区的军事占领，镇压抗日游击队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b7d36b485464135bb4849c84bb9caf5','fc976de0-02a7-497a-83b6-720de8d17fd9',1933,'原热河地方军阀','原热河地方军阀，投靠日军后任伪蒙军首领，参与侵占承德、隆化，协助日军建立伪政权，镇压当地抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd69807db2c540caafd7fe655b0b1188','f1052507-bcb6-4055-a7cd-5fbb8c44dd7f',1933,'投靠日伪','投靠日伪，任滦平县伪县长，推行日伪法令，征收苛捐杂税，协助日军建立“无人区”，迫害当地百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-793c66c01ac24cc3b4bd0a046ef9b1a0','6efa55eb-9a6b-49bc-88e7-67d504f3a51e',1933,'原地方士绅','原地方士绅，投日后任承德县伪县长，为日军提供情报，组织伪自卫团，参与对抗日根据地的封锁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-084e2c0125f84d5091c8588daccffe0c','efd45df8-ad3d-41bd-87dc-5f11650011fc',1931,'原奉天省长','原奉天省长，投日后任伪满洲国要职，参与对热河地区（含滦平）的行政规划与资源掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e30932e290948ecb5e4964827ad1d8b','efd45df8-ad3d-41bd-87dc-5f11650011fc',1931,'参与伪满对长城沿线（含山海关）的军事和行政渗透','参与伪满对长城沿线（含山海关）的军事和行政渗透','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c34ace915f194dfa83243dfddc96927b','67d6c576-318a-44c5-829f-ec059169cd32',1933,'投靠日伪','投靠日伪，任热河省协和会会长，在承德、滦平地区推行奴化宣传，组织“协和义勇队”协助日军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ca9a502e9e244da953a9989c24cd0f8','4e68502e-3d1c-4d40-9433-b99ef16fb2dc',1935,'原地方警察','原地方警察，投日后任滦平县伪警察署长，直接参与抓捕抗日群众，执行日军“三光”政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f383829d2f64329ab694e8d271efe4d','adda1dce-9240-40ef-a908-3527847a864f',1933,'投靠日伪','投靠日伪，任承德县保安队长，率伪军配合日军扫荡滦平、承德山区，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-476b9a6d9051480aa99b1923d222a889','8bb6055c-9d96-4be1-8d59-9104084f96d8',1933,'日伪占领初期任滦平县维持会长','日伪占领初期任滦平县维持会长，为日军筹粮派夫，建立伪政权基层组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-930a58b1235d4227b777587f557366b4','6ee4c4ea-434c-499e-8b11-fc401e4102c7',1937,'在承德地区推行奴化教育','在承德地区推行奴化教育，组织“青少年训练所”，为日军输送劳工，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5cec6ffe3b54b62b97a9ca08cf1c6ce','17e88105-840a-45b9-88e7-7bc232eb02d7',1938,'组织伪自卫团','组织伪自卫团，协助日军在滦平山区建立“集团部落”，制造无人区，导致大量平民死亡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3920b3c6a0741ab86066f27a127a52d','dcc04f10-d44d-4d6f-9852-c4b29fb65320',1939,'负责承德地区伪警察特务工作','负责承德地区伪警察特务工作，抓捕抗日地下党员，破坏抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e511ba8c37ce4df58961e8b5bdc0ff6e','935fecde-7df7-4e3e-93fb-6f195307ad5c',1933,'为日军担任翻译','为日军担任翻译，参与审讯抗日人士，协助日军实施“讨伐”行动。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c68675403b0a4c3b8800b25e48e5d716','ac540d3e-a00c-42f8-b22a-bd61713e616c',1940,'为日军强征粮食','为日军强征粮食，搜刮民财，导致承德、滦平地区饥荒。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4eb60e6897b46c2a8a440fd214d9d9d','61f34682-7135-48b1-8003-e53a94878156',1938,'推行新民会奴化活动','推行新民会奴化活动，组织“反共救国会”，协助日军进行思想控制。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e17b6328416f49edb89f98421d8fa3e6','7bb71dd0-bb6e-4796-bf29-c36464fafe04',1931,'原奉系要员','原奉系要员，投日后在伪满任职，曾参与策划对热河地区的军事占领和殖民统治，协助日军清剿抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e2ef1dee71949f8a9cac5b19ae2cff0','1011ed88-340c-4397-9839-47579f16e461',1933,'原东北军旅长','原东北军旅长，投日后任伪热河省省长，直接管辖承德、隆化等地，推行保甲制度，强征劳工，配合日军扫荡抗日根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c79b212b47e04dd197b331c53d73bf06','d09d7963-dbc1-4948-b616-b7ae04961671',1931,'原洮辽镇守使','原洮辽镇守使，投日后在热河地区担任伪军头目，多次率伪军进攻隆化、承德一带的抗日游击队，屠杀抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea0f0560f4ac48319482dbe68345e173','0e5f956c-0de0-4c9e-b6b2-dd0042f1cdd1',1932,'原东北军将领','原东北军将领，投日后在伪热河省任职，推行日伪奴化教育，强征粮食和民夫，为日军侵华战争服务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1746c0614b04d5db224e4d34f446efd','e6338e7a-79c6-4113-a2e1-b3316f029465',1932,'原奉系军官','原奉系军官，投日后负责热河地区伪警察体系，协助日军搜捕抗日分子，在隆化等地设立集中营和特务机构。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aea1247002054a04b429f447d644d609','b1baf5e1-598d-4c84-b488-ee11505389d1',1933,'在承德、隆化推行日本殖民教育','在承德、隆化推行日本殖民教育，强制学校教授日语，篡改历史教材，奴化当地青少年。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-228ff7d9cde94225897c56dc9d8a5c0c','1691c674-86ba-4a37-a3fe-84a88cd94ffd',1933,'在隆化县任伪县长期间','在隆化县任伪县长期间，积极执行日伪命令，强征土地和粮食，组织伪保安队配合日军围剿八路军游击队。','危害等级C（丙级，基层头目）','hanjian');
