INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1d9befa35f848c58ef72c22bf34f915','66f223eb-91a2-492b-a243-92c9e128ed11',1939,'指挥伪治安军（绥靖军）在河北各地包括石家庄、井陉一带进攻八路军','指挥伪治安军（绥靖军）在河北各地包括石家庄、井陉一带进攻八路军，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6fccb69da4944df9a63cc85cf29750cb','1be38415-7bfe-4b8f-a524-0b46ea5622d1',1940,'作为华北伪政权最高头目','作为华北伪政权最高头目，支持日军在石家庄、井陉推行“治安强化运动”，强化殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74d6167c111543daababa1c37361acb4','6c8dd6c7-3645-4c51-ada5-831e65b8a0e9',1937,'原东北军将领','原东北军将领，投日后任伪河北省省长，在石家庄地区推行日伪“新国民运动”，强征劳工，掠夺井陉煤矿资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-505c02537c5846879092abcffdfc8142','6c8dd6c7-3645-4c51-ada5-831e65b8a0e9',1937,'投敌后任伪河北省省长','投敌后任伪河北省省长，协助日军掠夺资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b84805cb82a149d1b4aaaeaffcaa8c23','8b90dbbf-614e-4f86-a50c-917292b6455c',1938,'投日分子','投日分子，任伪石家庄市市长期间，建立日伪市政机构，推行奴化教育，协助日军控制石家庄交通枢纽和井陉煤矿运输。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ba3f06339ce43f18801a4da9230147b','8b90dbbf-614e-4f86-a50c-917292b6455c',1938,'伪石家庄首任市长','伪石家庄首任市长，建立日伪市政机构，在平山等周边县份推行“治安强化运动”，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28617acbda024311a406cb5b47257cd2','6e3aa6d1-80ed-4b3f-a02d-521c0e44f64b',1940,'原新闻界人士','原新闻界人士，投日后任伪石家庄市市长，在井陉矿区强化治安，组织伪警察镇压矿工反抗，为日军提供煤炭资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ad64a8aae6d49f48384af00b6611611','52a8d08f-4559-4df1-ad8d-d2077743b3f9',1942,'投日官员','投日官员，任伪石家庄市市长期间，配合日军“治安强化运动”，在井陉矿区设立伪保甲组织，强征矿工劳役。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6dac1339f8a649a098e04ebb04ab08f6','f72add6d-df63-4ef2-888a-93dea2444ca8',1937,'原井陉煤矿中方管理人员','原井陉煤矿中方管理人员，日军占领后投敌，任伪井陉矿务局局长，为日军开采煤炭，残酷压榨矿工，导致大量矿工死亡。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35a0a857f7004ce0a0ca39b5a3cd411d','76b21300-806f-4ca6-ae50-059287c8f995',1941,'投日矿务官员','投日矿务官员，继任伪井陉矿务局局长，扩大煤炭生产供日军军需，组织矿工“勤劳奉仕”，镇压矿工罢工和抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32398de0e75f4b1797214a6f34924e2f','27f5db71-c059-49dd-964d-59392952f114',1938,'原地方土匪武装头目','原地方土匪武装头目，投日后任伪冀西保安队司令，活动于石家庄、井陉一带，多次配合日军袭击八路军游击队，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a8470e49daa436dbddf4f1c5eb2ec02','5c1f946c-826c-4921-b580-97dc9fa0a4fa',1938,'投日汉奸','投日汉奸，任伪井陉县知事，在井陉矿区推行日伪政权，强征粮食和劳工，协助日军建立“爱护村”以隔离抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ae3cf1ae8c946e59c8654a0ba3d8bbe','ee45a3b4-b46c-4646-bb84-ea933d01d423',1940,'投日官员','投日官员，任伪井陉县知事，在矿区实施“连坐制”，抓捕抗日地下工作者，向日军提供井陉煤矿情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a63d473616f840d99450ace5ebb843e5','e1849ff4-a4c5-429b-9866-7c6b3bc145a2',1943,'投日汉奸','投日汉奸，任伪井陉县知事，配合日军“三光政策”，在井陉山区烧毁村庄，强征民夫修筑碉堡和封锁沟。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe8b422ba38343ed98998b082016acba','d304e92e-9795-4d3b-b741-8354d81799eb',1938,'投日警察头目','投日警察头目，任伪石家庄警察局局长，在井陉矿区设立特务据点，搜捕抗日分子，严刑拷打矿工和地下党员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-571217e74dca467e9ef96ac6bc8b04cb','0d285d55-2d98-4835-8004-fec8d9224618',1942,'投日汉奸','投日汉奸，继任伪石家庄警察局局长，强化对井陉矿区的特务监控，破坏中共地下组织，参与“大检举”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4acd8761e9ee49fc8d55b3bb91064c99','626a09fd-4871-4822-b012-521767d8b521',1937,'投靠日军','投靠日军，任元氏县伪县长，协助日军推行‘治安强化运动’，强征民夫、粮食，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a82a9d3d6284cccbc93614845610978','8250ce9a-c7e7-4717-97f2-916d7db27c6a',1938,'率伪军多次扫荡抗日根据地','率伪军多次扫荡抗日根据地，杀害抗日干部和群众，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32166c25614649768f99fc2ec4cb5b5f','0bdfa379-b06c-427e-9b35-1490165c83c0',1939,'为日军搜集情报','为日军搜集情报，抓捕抗日地下人员，参与‘清乡’行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
