INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29131eca0df345aebf7624d45ee6e8bd','7ca45b10-23a3-4d32-8c71-a5e0da3df86b',1938,'日军占领信阳后','日军占领信阳后，出面组织伪政权，拉拢地方士绅附逆，为日军提供情报和物资。','危害等级C（丙级，基层头目）','hanjian');
