INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c9cadf7fd2a4542965c50b0280a2a5b','4f3afbf4-0a5f-4889-b8de-49d54ea4e419',1939,'在信阳推行奴化教育','在信阳推行奴化教育，编写亲日教材，组织学生参加日军宣传活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90b55cffc2a44b8fbc97fe512be62924','62710749-a5b1-4a66-94c9-264461c219b8',1938,'在伪河南省政府任职','在伪河南省政府任职，参与制定亲日政策，协助日军在河南各地推行伪化统治，涉及信阳地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcfc9070fac64a0db64ca5850354d857','210a7ec9-0b76-4803-8775-eab27bcefff3',1939,'统领伪绥靖军配合日军在河南南部包括信阳、息县一带进行扫荡','统领伪绥靖军配合日军在河南南部包括信阳、息县一带进行扫荡，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-369e6cdc624d47d18e88bc0b7149ccbf','a45dde76-7335-45a2-b187-0a74fc2beaff',1938,'组织新民会宣传亲日思想','组织新民会宣传亲日思想，在信阳等地发展会员，为日军搜集情报、征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3923af70ccbe48a1a15ed752df8aa68c','597e67dd-7dbb-429d-a174-9cb1ce238c9f',1939,'控制河南沦陷区物资流通','控制河南沦陷区物资流通，为日军掠夺粮食、棉花等战略物资，信阳、息县均在其管辖范围。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79b4d0ec82124b0c96e6c982f00674f4','bf5ea508-516b-4890-961d-0d6c1985760a',1938,'协助日军控制信阳商业','协助日军控制信阳商业，强制商户纳捐，为日军采购军需物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7493fccecceb428ab97f3f9627f9c527','8020e2f4-797c-4676-812d-ea1f0fa33586',1940,'在息县发展新民会组织','在息县发展新民会组织，进行亲日宣传，配合日军征粮征丁。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
