INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c115557488b44d6395953f246f20b08e','327be014-9b6c-475b-9c70-0fca39e38234',1940,'率伪保安团配合日军在信阳周边及新县、罗山交界地区进行扫荡','率伪保安团配合日军在信阳周边及新县、罗山交界地区进行扫荡，搜捕抗日人员，抢掠民财，协助日军维持占领区治安。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c816697f5754c2891e620a506c834a4','327be014-9b6c-475b-9c70-0fca39e38234',1940,'率伪保安团配合日军对信阳南部山区及浉河沿岸抗日根据地进行扫荡','率伪保安团配合日军对信阳南部山区及浉河沿岸抗日根据地进行扫荡，搜捕抗日人员，抢掠民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fc9f246a4a0424ab5587d817a96741b','234da974-1984-4074-bda2-3f3044421129',1939,'任伪豫南道尹期间','任伪豫南道尹期间，统辖信阳、罗山、光山、新县等豫南伪政权，推行日军政令，组织伪军警镇压抗日力量，为日军在豫南的统治服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec0075b3e467418fa94e31e6277a8953','de32e7fd-620d-441d-97b6-f6359a6ca6c5',1938,'在光山及邻近新县地区组织伪维持会','在光山及邻近新县地区组织伪维持会，为日军筹粮筹款、提供情报，协助日军对光山、新县一带抗日根据地进行封锁和扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83d48f2624204cf5914a67a368dac11b','a7fc1439-f642-4885-89d4-68c2ec08d93a',1939,'在罗山地区建立伪政权','在罗山地区建立伪政权，配合日军对罗山、信阳、新县交界地带进行清乡，强征民夫修筑据点，镇压当地抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a11a0fbcd498403bac1a6d37cfd51cea','b7102d47-8cf7-487c-8dbe-5c10b6a46626',1938,'在潢川组织伪维持会','在潢川组织伪维持会，协助日军控制豫东南交通线，为日军提供情报和物资，参与对邻近光山、新县抗日力量的封锁。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26184b3624e048d185623dcb600caaac','8bca1032-ab27-47e2-ab65-66faf5f05583',1940,'掌管伪信阳警察局','掌管伪信阳警察局，配合日军搜捕抗日人员，清查户口，推行良民证制度，镇压信阳城区及周边地区的抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86892f80ba62429b88474eb75d09202a','f014f69e-c26e-41d6-bda8-2155becafd60',1938,'在新县地区组织伪维持会','在新县地区组织伪维持会，为日军带路、筹粮，协助日军对鄂豫皖抗日根据地进行扫荡，迫害抗日军人家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3ce2d6a22e84c978cb163b72410a6b2','06e1bb8f-dd72-4824-b688-3235ef98627a',1940,'统率伪军配合日军在豫南信阳、新县、罗山、光山等地进行剿共扫荡','统率伪军配合日军在豫南信阳、新县、罗山、光山等地进行剿共扫荡，进攻抗日根据地，捕杀抗日军民，是豫南地区重要的伪军头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-419a2ae87e694cac80c2ed69e7d11299','4a14c040-02b8-4a27-a9ba-1a5e57cd6623',1938,'日军侵占信阳后出面组织伪维持会','日军侵占信阳后出面组织伪维持会，协助日军维持城区秩序、征派粮款与民夫，并参与筹建伪信阳县政府，是信阳沦陷初期主要的附逆头目之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f466806f2fc745b1ae76811fe03f0c34','8c593910-7f28-42ce-8334-0713a80b1b18',1939,'在日军扶植下出任伪信阳县政权头目','在日军扶植下出任伪信阳县政权头目，推行保甲连坐，配合日军清乡、征粮、抓丁，镇压抗日群众，活动范围覆盖信阳城区及浉河一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6ebe398253f444c99a48fc0523252ae','0833624d-45d3-454b-961f-5d7aebb8b92c',1939,'掌管伪警察系统','掌管伪警察系统，在信阳城区及浉河沿岸设立检查哨，盘查行人、抓捕抗日嫌疑人员，协助日军维持殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1432db61771849bbbf0bd51e976fec99','1d7b8503-191a-4044-8e9c-16c8d651829f',1938,'作为商界附逆代表','作为商界附逆代表，为日军筹款筹物，强制商户摊派物资，协助日军对信阳城区经济进行掠夺与控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e720e6233884d6095ec0370b5013507','7d4efa24-1819-4223-9753-6490f239cc6f',1940,'在信阳推行奴化教育','在信阳推行奴化教育，改编教材宣扬“大东亚共荣”，组织教师参加亲日培训，毒化沦陷区青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-552cc77c31d241fba892afe388671d6a','2134098a-bb94-4f53-bff4-c4dc7a82dec5',1938,'在信阳城关及浉河沿岸组织维持会','在信阳城关及浉河沿岸组织维持会，为日军带路、指认抗日人员家属，征派民夫修筑工事。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c45707d8403451d9360b0f7562b7b57','75c5db75-dfbe-43e9-aae9-8a514c47d650',1939,'统辖豫南伪政权','统辖豫南伪政权，包括信阳一带，推行日军政令，组织伪军配合扫荡，掠夺粮食棉花等战略物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-062da41e0bf140acba6790c3d91af2d3','b9575b8f-3f05-4388-9b16-202efc10bcbc',1938,'率伪军在豫东、豫南包括信阳周边配合日军作战','率伪军在豫东、豫南包括信阳周边配合日军作战，参与扫荡抗日根据地，收编土匪扩充伪军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6ec69e22fff4f4b9afd251d493dcf1e','87bf2ecd-bf24-4587-9e30-31c53839dfa3',1942,'率部投敌后驻防河南','率部投敌后驻防河南，其伪军活动范围涉及豫南信阳一带，配合日军清乡、扫荡，镇压抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1323ec85eb854518a53306fc020dd454','87bf2ecd-bf24-4587-9e30-31c53839dfa3',1942,'天津人','天津人，1942年投敌，率部在豫东、豫南一带配合日军作战，其伪军曾活动于南阳周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-175aa6fd912a4cbf81313a429d965037','87bf2ecd-bf24-4587-9e30-31c53839dfa3',1942,'原西北军将领','原西北军将领，1942年率部投敌，任伪第二方面军总司令，驻防河南开封、商丘一带，配合日军扫荡豫东、豫南抗日武装，其势力范围涉及南阳周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f84f31a686ed4bdca7c4595e41ba350a','87bf2ecd-bf24-4587-9e30-31c53839dfa3',1942,'原西北军将领','原西北军将领，1942年投敌，率部驻防豫东、鲁西，在周口、鹿邑一带配合日军扫荡，后任伪开封绥靖公署主任。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48cacc451672407598cd1c94c1ada602','87bf2ecd-bf24-4587-9e30-31c53839dfa3',1942,'原国民党将领','原国民党将领，1942年率部投敌，所部活动于豫东、豫北一带，配合日军进攻抗日根据地，是河南伪军主要头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2bfe4bbbb94945d2ae8ef39d6641e119','87bf2ecd-bf24-4587-9e30-31c53839dfa3',1942,'率部投敌后驻防豫东、豫北','率部投敌后驻防豫东、豫北，其伪军活动范围包括商丘、民权一带，配合日军进攻抗日根据地，残害民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c259eda5f2a4e61a0d54d5d26bdc57c','87bf2ecd-bf24-4587-9e30-31c53839dfa3',1942,'原国民党将领','原国民党将领，1942年率部投敌，所部驻防河南开封、商丘等地，配合日军扫荡，后任伪开封绥靖公署主任，控制豫东地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73aa3c5d82064be2bb722c3f8910bfc3','87bf2ecd-bf24-4587-9e30-31c53839dfa3',1942,'原国民党将领','原国民党将领，1942年率部投敌，任伪军要职，其部队活动于河南开封、洛阳周边地区，配合日军进攻和维持占领区秩序。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
