INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c932e8d1248424b935873b37a043f3b','17714539-861c-453d-a7a2-48dd3b1d8b73',1943,'原国民党河北省政府主席、第二十四集团军总司令','原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪和平救国军第二十四集团军总司令，后兼任伪河南省政府主席，协助日军维持河南沦陷区统治，其伪政权名义上管辖河南全境，对南阳、新野地区有行政关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef1b744f625d4a0d87bcaa53070791ea','17714539-861c-453d-a7a2-48dd3b1d8b73',1943,'原国民党河北省主席、第二十四集团军总司令','原国民党河北省主席、第二十四集团军总司令，1943年被俘后投敌，任伪职，其伪军活动范围涉及豫北、豫东，对河南沦陷区伪政权的维持负有责任。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
