INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-354f9c5fbe6f42b8a731ad88c600735b','6896be4d-bab9-4104-8c3d-a67ccad45f18',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，后任伪军长，长期盘踞商丘、南阳周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04aba6d4b52749228ac1ca5f5751db57','6896be4d-bab9-4104-8c3d-a67ccad45f18',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，其势力范围曾扩展至平顶山周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46219a1fc510452aa4eca6084e06b879','6896be4d-bab9-4104-8c3d-a67ccad45f18',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，1944年后活动范围扩展至郑州、开封周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01eb36d12874497fb3e37e0461b68dee','3f9ddfbc-5313-41c9-80c3-309d04064315',1943,'河南永城人','河南永城人，1943年投敌，所部被编为伪军，在豫北、豫西一带配合日军作战，其势力范围一度影响南阳周边。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0fa9b0837f14d54896f23b62fab6687','3f9ddfbc-5313-41c9-80c3-309d04064315',1943,'河南永城人','河南永城人，原国民党军将领，1943年在河南林县被日军俘虏后投敌，所部被编为伪军，在豫北、豫西一带配合日军作战，其势力一度延伸至南阳以北地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fcc4a4a3af045a4abd6ccfdb244c8bb','3f9ddfbc-5313-41c9-80c3-309d04064315',1943,'河南永城人','河南永城人，抗战后期投敌，所部在豫东、豫北活动，与周口、淮阳地区伪军有联系，配合日军进攻抗日根据地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bd0a707d0de4aaea2091a0861ee979a','3f9ddfbc-5313-41c9-80c3-309d04064315',1943,'河南永城人','河南永城人，原国民党军将领，1943年投敌，任伪新编第五军军长等职，活动于豫北、豫东一带，配合日军进攻抗日根据地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c298f8a7f59412ea2afa786be5a6726','3f9ddfbc-5313-41c9-80c3-309d04064315',1943,'原国民党军将领','原国民党军将领，1943年投敌，任伪新编第五军军长，活动于豫北、豫东一带，其部曾配合日军在商丘、永城周边地区进行扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0981f6c8e1144fe78afb428fb6b69ef2','3f9ddfbc-5313-41c9-80c3-309d04064315',1943,'河南永城人','河南永城人，1943年投敌，所部被编为伪军，在豫北、豫西一带活动，曾配合日军扫荡，其部众流窜至平顶山附近地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05ce9583ce964d599c151d7de53748e5','3f9ddfbc-5313-41c9-80c3-309d04064315',1943,'1943年在河南林县被日军俘虏后投敌','1943年在河南林县被日军俘虏后投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，其伪军活动区域与平顶山、汝州同属河南战区，对豫西抗日力量构成威胁。','危害等级B（乙级，市县厅局级）','hanjian');
