INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d91708dc9ec04ac6abcbb4a6ef52119a','3f9ddfbc-5313-41c9-80c3-309d04064315',1943,'原国民党将领','原国民党将领，1943年在河南林县被俘后投敌，任伪职，在豫北地区为日军效力，配合日军维持占领区秩序。','危害等级B（乙级，市县厅局级）','hanjian');
