INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b42c5c6a1774a5f8b9b63ec9ae205aa','12400816-342d-445e-aa49-4b4b9c6a5d49',1940,'汪精卫伪政权核心人物','汪精卫伪政权核心人物，其伪政权统治范围包括河南沦陷区，推行奴化政策、经济掠夺，对河南民众造成深重灾难。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56ea4b4af91a4924b0179c784a73a39e','12400816-342d-445e-aa49-4b4b9c6a5d49',1940,'广东乳源人','广东乳源人，汪伪政权核心人物，其伪政权名义上管辖河南，推行反共、奴化政策，南阳地区亦在其伪化影响范围内。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9eb5c1e42dfe4bbd93370528b5c6640d','12400816-342d-445e-aa49-4b4b9c6a5d49',1940,'投靠日本','投靠日本，在汪伪政权中任职，推行日伪统治，其伪政权对包括陕西在内的全国抗日力量有威胁。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a907a2f6795446ca2b912050f64bde7','12400816-342d-445e-aa49-4b4b9c6a5d49',1940,'汪伪政权核心人物','汪伪政权核心人物，其伪政权体系与陕西渭南地区无直接关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d23ef80312154528bb8f27aced715f19','e999151f-7e51-4a7a-9045-8dd55a381fbd',1943,'河南永城人','河南永城人，1943年在河南林县被俘后投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，对南阳地区抗日力量构成威胁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da5ab6b1205a4c2cb9d69a7871617c04','e999151f-7e51-4a7a-9045-8dd55a381fbd',1943,'原国民党军将领','原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，驻防豫北、豫西一带，配合日军维持占领区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7ff28a017d946d2b7f7e0040ac28970','e999151f-7e51-4a7a-9045-8dd55a381fbd',1943,'河南永城人','河南永城人，1943年在河南林县投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，其伪军活动曾波及南阳、西峡周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-017ac64f5c8c458caee10dfe0c7f7452','e999151f-7e51-4a7a-9045-8dd55a381fbd',1943,'河南永城人','河南永城人，原国民党军将领，1943年在豫北投敌，所部被编为伪军，活动于豫东、豫北一带，配合日军对周口、商丘地区进行扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
