INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d13a7d80de64f3c8bb634131bf549a6','e999151f-7e51-4a7a-9045-8dd55a381fbd',1943,'河南永城人','河南永城人，1943年投敌，在河南、河北一带活动','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6efbd9caedb4dbf893d36da6a9bab6e','e999151f-7e51-4a7a-9045-8dd55a381fbd',1943,'与湖南衡阳无直接关联','与湖南衡阳无直接关联。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8138329ba8e49f4acf91118eea4faf4','5a9603f7-2992-4fae-a17b-a8b6b5b90cf1',1943,'河北新河人','河北新河人，1943年在河南林县投敌，率部编入伪军，在豫北、豫西及南阳周边地区配合日军扫荡抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-efe15783ab7b49399da3b418c632556e','5a9603f7-2992-4fae-a17b-a8b6b5b90cf1',1943,'河北人','河北人，1943年在河南林县投敌，所部伪军活动于豫北、豫西，对南阳地区抗日力量构成威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d0e337205a4485fb9b136bc4edba34f','5a9603f7-2992-4fae-a17b-a8b6b5b90cf1',1943,'河北人','河北人，原国民党军将领，1943年在河南林县投敌，率部编为伪军，在豫北、豫西地区配合日军作战，其势力范围曾接近南阳、西峡一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88e89103d9d84d4286c72047f10b61e1','608d591e-8e1b-4030-aa15-b0857fbd2319',1938,'福建长乐人','福建长乐人，主持伪维新政府，其势力范围曾涉及河南部分地区，配合日军进行经济掠夺和伪化宣传。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e51f2d58be547dc9fad797342b7b3c3','608d591e-8e1b-4030-aa15-b0857fbd2319',1938,'福建长乐人','福建长乐人，抗战期间投靠日军，组织伪中华民国维新政府，其伪政权影响范围涉及华中、华东，包括河南东部部分地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5275a3abc1f4e4daaf944354d5c77ad','608d591e-8e1b-4030-aa15-b0857fbd2319',1938,'福建长乐人','福建长乐人，抗战期间组织伪维新政府，后并入汪伪政权，其伪政权势力曾涉及河南部分地区，协助日军进行经济掠夺与治安维持。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-135ff4b01b1b43dfaf63ac40ed0c6669','608d591e-8e1b-4030-aa15-b0857fbd2319',1938,'福建长乐人','福建长乐人，抗战期间组织伪维新政府，后并入汪伪政权，任伪监察院院长，其伪政权影响包括河南部分地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6809cdc841064e11bc924a4ba956a3e0','608d591e-8e1b-4030-aa15-b0857fbd2319',1938,'福建长乐人','福建长乐人，组织伪维新政府，其势力范围涉及华中、华东，与河南南部地区有间接关联，后并入汪伪政权。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a0e9e3d7bf54eff8e177126dfbbd13e','608d591e-8e1b-4030-aa15-b0857fbd2319',1938,'投靠日本','投靠日本，在华中组建伪政权，其伪政权与华北伪政权有联系，对陕西有间接影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0e95e0999614a3787d3c8c4419dc267','608d591e-8e1b-4030-aa15-b0857fbd2319',1938,'华中伪政权头目','华中伪政权头目，其伪政权与华北伪政权有联系，对华北各地包括陕西黄河沿岸日占区的伪组织有影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86744cfe6b064e4da6ef48bc5ff6db14','1b73add9-ed1c-45a9-8e35-ff32faf119ef',1940,'辽宁辽城人','辽宁辽城人，曾任伪河南省政府主席，直接负责河南伪政权，推行日军政策，南阳地区在其管辖之下。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-013c33ee9c134c5dbd59ce867a6c40be','3151b00b-55b2-409e-b458-bcc37da5ae06',1938,'河南人','河南人，抗战期间在伪河南省政府任职，协助日军维持治安、征粮、抓捕抗日人员，其政令覆盖南阳及南召一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-866475d3cb2340308582e989197659a4','d89df677-3fb9-4c80-8257-045e7e6193ed',1940,'在南阳沦陷期间任伪南阳县知事','在南阳沦陷期间任伪南阳县知事，推行保甲制度，配合日军扫荡南阳周边抗日武装，镇压民众抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02ce877c263c4d3eb8035f1fd0aff9c5','a9fc4c4b-efb5-41fe-ad1e-065b4d2ad218',1941,'南召本地人','南召本地人，日军侵入南召后出面组织维持会，为日军带路、征粮、招募伪军，协助日军控制南召山区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3bb94f253b8746bdac140cd433589fca','abb85644-ed63-47ba-b692-33781567f1da',1940,'在南阳沦陷期间任伪警察局长','在南阳沦陷期间任伪警察局长，带领伪警察配合日军搜捕抗日人员，镇压南阳民众抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89dc9b291eec4d98931fd54ac0e45e1f','3c9ab7e1-2043-4fad-842e-4c4695700c3d',1941,'原为国民党军下级军官','原为国民党军下级军官，投敌后在南阳地区组建伪军，配合日军扫荡南阳、南召一带抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-288817db450e41adbe65387c10bb422e','09501210-3e53-40d7-ad0d-b7b1ec56eb4c',1942,'在豫南、南阳一带活动','在豫南、南阳一带活动，率伪军配合日军进攻抗日武装，掠夺民众财物，残害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-462d171f1ba5491ca87baf33e82e1f91','6c2a5f9d-4df9-4f0b-9d21-8c2cd8856b52',1940,'在南阳沦陷期间任伪教育局长','在南阳沦陷期间任伪教育局长，推行奴化教育，篡改教材，向学生灌输亲日思想，为日军培养顺民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7862e530f028468d85226e600333f785','c42aef96-8c3f-4585-af29-b7030f8e8418',1940,'在南阳沦陷期间任伪商会会长','在南阳沦陷期间任伪商会会长，为日军筹集物资、摊派款项，协助日军对南阳经济进行掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d47d6a96e4fc4c6697519dc21f6ebafc','c42aef96-8c3f-4585-af29-b7030f8e8418',1940,'河南南阳人','河南南阳人，抗战期间任伪南阳商会会长，为日军筹集物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76ad228542324ef98f165243b20d244e','429e12d7-7911-4bd8-b286-533a4fd04f54',1941,'在豫南、南阳一带活动','在豫南、南阳一带活动，率伪军配合日军扫荡，烧杀抢掠，残害抗日民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce54a0747ff3423ab96313f6a1a59e71','c616279a-b194-4fa0-92e7-1a810cd3553b',1941,'在南召沦陷期间任伪警察所长','在南召沦陷期间任伪警察所长，带领伪警察配合日军搜捕抗日人员，镇压南召山区抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56cb3ff8a5644763bc06c7cf9feeb148','8df43bd3-7d51-48dc-8c38-b6cc37ed330c',1940,'南阳本地人','南阳本地人，任伪保甲长，为日军征粮、派夫、搜集情报，协助日军控制南阳基层社会。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d82c54ef26044b5b2f7f85d063f7229','348466eb-3f41-4159-bf3a-98c9b948455b',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，长期控制商丘、开封及豫东地区，其势力范围一度延伸至南阳周边。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd642f60b6e2410680b927634080b0ef','348466eb-3f41-4159-bf3a-98c9b948455b',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组建伪军，配合日军进攻抗日根据地，其势力范围一度覆盖南阳周边地区，是河南境内影响较大的汉奸武装头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8890dfca1054b0c98ebe7db78e097d5','348466eb-3f41-4159-bf3a-98c9b948455b',1938,'河南柘城人','河南柘城人，抗战期间投敌，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，其伪军活动范围覆盖河南大部，对南阳、西峡等地抗日力量构成威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-029563ee5abd4a1dbafc29e3a05ea341','348466eb-3f41-4159-bf3a-98c9b948455b',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫北一带收编土匪、组建伪军，配合日军进攻抗日根据地，其伪军活动范围覆盖安阳、汤阴周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b821059c13d54afe93ecd3d032eed27e','348466eb-3f41-4159-bf3a-98c9b948455b',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，其势力范围覆盖漯河、临颍周边地区，是河南境内影响较大的汉奸武装头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68b4c6e3198d4325bf5e9f7487a925e4','348466eb-3f41-4159-bf3a-98c9b948455b',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫北一带组织伪军，配合日军进攻抗日根据地，其势力范围覆盖濮阳周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f341c320ad44febaee23985d7d6e7a5','8017ea40-59ee-46c9-bf2e-571d6e0c52c2',1943,'1943年在河南林县被俘后投敌','1943年在河南林县被俘后投敌，任伪职，在河南境内协助日军维持占领区秩序，参与对抗日根据地的扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa08b4d165974168aa082cab8b193245','8017ea40-59ee-46c9-bf2e-571d6e0c52c2',1943,'河北人','河北人，1943年在河南林县被俘后投敌，任伪第二十四集团军总司令，后任伪开封绥靖公署主任，统辖河南伪军，其势力范围涉及南阳。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
