INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-744d18c2d2f549cc88ed7ded0da7a032','8017ea40-59ee-46c9-bf2e-571d6e0c52c2',1943,'在河南投敌','在河南投敌，组织伪军配合日军扫荡，河南与陕西相邻，其活动对陕西东南部有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d31728c48984fdea35ff8cb981c7c9e','fedd918f-bb6c-4662-9edf-d74ccb4a752d',1938,'抗战期间任伪河南省省长','抗战期间任伪河南省省长，在开封等地设立伪政权，推行日军政策，征发劳役、搜刮物资，配合日军对河南各地的控制，其伪政权影响覆盖南阳周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
