INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac4e7887bdfa48eb9e8890b8a34bda86','fedd918f-bb6c-4662-9edf-d74ccb4a752d',1938,'抗战期间任伪河南省公署省长','抗战期间任伪河南省公署省长，驻开封，统辖河南沦陷区伪政权，推行日军政令，征粮征丁，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
