INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe03d9ac1da649f4882f79b31e870e3c','914dce05-0698-45cc-b79d-1eec0c9f1973',1945,'1945年日军占领南阳时','1945年日军占领南阳时，组织伪南阳县维持会，配合日军征发民夫、物资，维持日占区统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5c9bdaf06e8445aaada3ef8a7ac3cad','d9899653-02d8-416a-b56f-a09126126f75',1945,'1945年日军侵占南阳后','1945年日军侵占南阳后，出任伪南阳警察局局长，协助日军维持城区治安，搜捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13821e4d2e154847965797d7c2b94b7b','1e17a975-6303-4aa5-a6c0-bf20774e97e9',1945,'1945年南阳沦陷期间','1945年南阳沦陷期间，组织伪保安团，配合日军对南阳周边地区进行扫荡，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29a8d56bab084e738e0bcb959942c8cd','642f6237-70e7-40c3-acde-758e0a40278a',1945,'1945年日军侵占南阳后','1945年日军侵占南阳后，联络南阳各县维持会，成立伪联合会，为日军筹办粮秣、夫役，协助日军统治南阳地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8923e24d1a4a4cc4a4570291541e7c58','e4882f12-3b38-4361-ac84-fa1681173407',1945,'1945年南阳沦陷期间','1945年南阳沦陷期间，在伪政权中负责教育事务，推行奴化教育，宣传“大东亚共荣圈”，毒害青年学生。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09a22ea63945428ab027e8a1523065aa','097993a5-a85c-4cd8-bc6d-af7c39a5f043',1945,'1945年日军占领南阳后','1945年日军占领南阳后，出任伪商会会长，为日军筹款筹物，协助日军对南阳工商业进行掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab3e9eeeb11c46ed98e864956ac843d1','a3c53935-2c73-42e5-849d-387dfc2df86c',1945,'1945年南阳沦陷期间','1945年南阳沦陷期间，担任伪保甲长，协助日军清查户口、征发劳役、搜捕抗日人员。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03cdb908ac5d4caf9d935f7c323cc1d0','e09f594a-7693-4acc-87dd-4521478658ff',1945,'1945年南阳沦陷期间','1945年南阳沦陷期间，担任伪保甲长，为日军征粮征夫，监视居民行动，向日军报告抗日活动。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af13c2ccfe8c493196b66deb5ad37741','80d882a6-c087-498f-831a-51219a2387ec',1945,'1945年南阳沦陷期间','1945年南阳沦陷期间，在伪维持会中担任文书，协助日军登记物资、人口，为日军统治提供情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63008f1d11e0462bbe1212c70e44736d','7269fcd8-cfe3-44d1-a716-b93f056f1667',1945,'1945年日军侵占南阳期间','1945年日军侵占南阳期间，担任日军翻译，协助日军与当地伪政权沟通，参与审讯抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32203d94d98c471d8041784bf5d38a00','69f031c4-5fee-4b3d-a344-c5810f133640',1937,'山东人','山东人，长期在河南、山东交界地区为日军效力，组织伪军配合日军扫荡，其活动范围涉及豫西、豫南，对南阳周边地区造成威胁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-425708d2186743dcb80df82801f54a40','0a1d0c12-a6ba-4141-97bd-5bb047614c6a',1938,'在河南东部、南部组织伪军','在河南东部、南部组织伪军，配合日军进攻抗日根据地，其伪军活动曾延伸至南阳地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d68ad3d28634c4895c1122b8d16f7ac','b844556e-fc36-43fb-8576-63d346db8991',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，后任伪第四方面军总司令，所部活动范围覆盖南阳周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b26080f5d86f40eb94a289dd9d6f2697','b844556e-fc36-43fb-8576-63d346db8991',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，后任伪第四方面军总司令，所部活动范围覆盖河南多地，包括南阳周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45a8dbe5e96b43d4a6ae6962201543f3','a2e96ba4-460a-44d9-8557-b84be0190c46',1933,'内蒙古人','内蒙古人，长期任伪蒙古军总司令，后率部进入河南，任伪豫北剿共军司令，配合日军在河南境内作战，活动范围包括豫西南。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d1c76e919174a1b8c2b8def854a65f1','ffd9257d-5f6c-414e-969d-2a8b7e4b1924',1937,'安徽人','安徽人，抗战期间任伪华北政务委员会委员长，后兼任伪河南省省长，推行奴化教育、经济掠夺，其伪政权覆盖河南全省包括南阳。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6b543bcefca4cb0b50cae6ecca9cc76','ffd9257d-5f6c-414e-969d-2a8b7e4b1924',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投靠日本，任伪华北政务委员会委员长等职，其伪政权管辖范围包括河南，推行奴化教育、经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ca7de05d65d4249b51fd1976a9d0427','ffd9257d-5f6c-414e-969d-2a8b7e4b1924',1937,'安徽人','安徽人，投靠日军，在华北及河南推行伪化政策，影响驻马店地区伪政权运作。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbb4ebfa11ad4a148613eb8be5aeedbf','ffd9257d-5f6c-414e-969d-2a8b7e4b1924',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会委员长，曾兼任伪河南省省长，推行奴化教育、经济掠夺，其伪政权体系覆盖河南全省包括驻马店、正阳。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d63ae1ad2284248962ccaef3ac4c62a','ffd9257d-5f6c-414e-969d-2a8b7e4b1924',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投靠日本，任伪华北政务委员会委员长等职，其伪政权管辖范围包括河南沦陷区，推行奴化教育、经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b29583dd833046f0b469edf366569ba1','032fa4bc-4185-4d35-a9cc-f4fb82ce3a12',1938,'河南人','河南人，抗战期间任伪河南省省长，协助日军维持占领区统治，推行保甲制度，其伪政权机构涉及南阳地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-137c0fd517bc48d3911d5d49d1832108','032fa4bc-4185-4d35-a9cc-f4fb82ce3a12',1938,'河南人','河南人，抗战期间出任伪河南省长，协助日军维持沦陷区统治，推行保甲、征粮、奴化教育，南阳地区在其伪政权名义管辖之下。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9793d098fe984a64b601590e6489135c','032fa4bc-4185-4d35-a9cc-f4fb82ce3a12',1938,'河南沦陷后投敌','河南沦陷后投敌，历任伪河南省长等职，在河南全省推行日伪政策，其政令覆盖周口、太康等豫东地区，为日军征发物资、镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55e07b9391c5449fac7b2f536b983c84','032fa4bc-4185-4d35-a9cc-f4fb82ce3a12',1938,'抗战期间出任伪河南省长','抗战期间出任伪河南省长，主持伪省政，推行日军殖民统治政策，在河南各地包括豫东周口一带建立伪政权、征粮征丁，配合日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c1887f817a54e089c2189c0f91a30bd','032fa4bc-4185-4d35-a9cc-f4fb82ce3a12',1938,'河南伪政权最高头目之一','河南伪政权最高头目之一，在开封、安阳等地推行日军殖民统治，协助征粮、征兵。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9769b50301ca4cfead9dc87e01de4ace','032fa4bc-4185-4d35-a9cc-f4fb82ce3a12',1938,'抗战期间任伪河南省省长','抗战期间任伪河南省省长，驻开封，协助日军维持河南沦陷区统治，推行保甲制度、征粮征丁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd3d170afcd74c109fa8c3b403379526','032fa4bc-4185-4d35-a9cc-f4fb82ce3a12',1938,'抗战期间投靠日军','抗战期间投靠日军，历任伪河南省政府要职，参与组织伪政权、推行奴化教育、征发物资劳工，支持日军在河南的殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
