INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cfc3d8e87b2443479c6ec15f86466f1d','032fa4bc-4185-4d35-a9cc-f4fb82ce3a12',1938,'河南本地人','河南本地人，日军占领开封后出面组织伪河南省政府，任伪省长，协助日军推行保甲、征粮、奴化教育等政策，影响及于郑州地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60473c13e62d4e10843771e7cbd6be93','032fa4bc-4185-4d35-a9cc-f4fb82ce3a12',1938,'抗战期间投敌','抗战期间投敌，历任伪河南省政府委员、伪河南省省长，驻开封，为日军在河南推行殖民统治、征粮征丁，是河南沦陷区伪政权核心人物之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
