INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9bdf98c5c7544a0fa02a4e7a42557626','f9799c8f-115f-4044-b081-07c0c22afeeb',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东商丘、周口、柘城、鹿邑、淮阳一带组建伪军，配合日军进攻抗日根据地，搜捕抗日人员，横征暴敛，是豫东地区最具实力的汉奸武装头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7dc89e517048451fb7f00faf59f49004','f9799c8f-115f-4044-b081-07c0c22afeeb',1938,'河南柘城人','河南柘城人，早年在冯玉祥部任职，抗战爆发后投敌，在豫东商丘、周口、柘城、鹿邑、淮阳一带组建伪军，配合日军扫荡抗日根据地，1943年后任伪第四方面军总司令，1945年任伪河南省省长，是豫东地区最具实力的汉奸武装头目。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee5af81939d447ebaa0686eb150424ae','f9799c8f-115f-4044-b081-07c0c22afeeb',1938,'河南柘城人','河南柘城人，抗战期间在豫东周口、商丘一带组织伪军，先投日军任伪和平救国军第一军军长，后任伪第四方面军总司令，1945年又任伪河南省省长，长期配合日军在豫东地区进行统治和扫荡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
