INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09c3a747b1e0484587cc2efafbac6a0e','a341d251-ab35-4fb9-a740-0bc20f048079',1933,'内蒙古人','内蒙古人，早年在热河投敌，后任伪蒙古军总司令','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23ade2723c24456ab8495116916c7c64','a341d251-ab35-4fb9-a740-0bc20f048079',1933,'1944年后被派往河南任伪保安司令','1944年后被派往河南任伪保安司令，协助日军维持河南占领区治安，其活动涉及豫南、豫西南地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ddfdc169773466691a83f28e6dd5d52','a341d251-ab35-4fb9-a740-0bc20f048079',1933,'蒙古族','蒙古族，早年在东北投敌，后随日军进入河南，曾任伪河南省保安司令等职，参与镇压河南抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34cf0885fb174ce88b96672272cdcfcd','a341d251-ab35-4fb9-a740-0bc20f048079',1933,'1944年率伪军进入河南','1944年率伪军进入河南，配合日军控制豫中地区，其部队曾驻扎许昌一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-628d0becc6934170996c222f25ab78a5','a341d251-ab35-4fb9-a740-0bc20f048079',1933,'蒙古族','蒙古族，早年在热河投敌，后任伪蒙古军总司令，抗战后期被派往河南任伪保安司令，参与维持豫南伪政权，活动涉及驻马店、正阳一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1a808fce13c4d70b1581b88c66ac206','a341d251-ab35-4fb9-a740-0bc20f048079',1933,'投敌后任伪职','投敌后任伪职，其伪军一度调驻河南，参与对豫南抗日根据地的扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9d72dbba4f44073bac91b7684b44311','fd17130d-5e30-4c1b-8a55-d801d6c04d0f',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会委员长，后兼任伪河南省省长，推行奴化教育、经济掠夺，其伪政权统治覆盖河南全境，包括南阳地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d223d202981487d887ba33dcfc8fa6c','fd17130d-5e30-4c1b-8a55-d801d6c04d0f',1937,'华北伪政权首要汉奸之一','华北伪政权首要汉奸之一，统辖包括河南在内的华北沦陷区，其政策影响商丘、民权等地伪政权运作，推行奴化教育与经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a84e827ecc94a3db79ab012b26b054f','fd17130d-5e30-4c1b-8a55-d801d6c04d0f',1937,'安徽合肥人','安徽合肥人，北洋余孽，抗战期间投敌，任伪华北政务委员会委员长，统辖包括河南在内的华北伪政权，推行奴化教育、经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c611c15c6eea43b5896d1ee7ec1a2d1a','b79841ca-01f1-4628-96df-91c3f75fd641',1938,'河南安阳人','河南安阳人，抗战初期即投敌，历任伪豫北道尹、伪河南省省长，在河南推行伪化行政，为日军征集物资、劳工，其伪政权体系延伸至南阳各县。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1c18612a1464f23aafd85b3aae5faeb','b79841ca-01f1-4628-96df-91c3f75fd641',1938,'河南人','河南人，抗战期间投敌，在豫北地区任伪道尹、伪省长，协助日军征粮、抓丁，镇压抗日民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-965ea9d195a446bb9b92e5592b6882a6','b79841ca-01f1-4628-96df-91c3f75fd641',1938,'河南安阳人','河南安阳人，抗战期间历任伪河南省政府要职，协助日军推行保甲、征粮、抓丁，其伪政权体系覆盖河南多地，包括平顶山地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-836aaa5064cd42faa9e4ff80880ee705','b79841ca-01f1-4628-96df-91c3f75fd641',1938,'长期在豫北日伪政权任职','长期在豫北日伪政权任职，配合日军清乡、征粮、抓劳工，残害抗日群众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebc36b2acd1b4cec920259f7fa04836f','b79841ca-01f1-4628-96df-91c3f75fd641',1938,'河南安阳人','河南安阳人，抗战期间投敌，历任伪河南省政府省长、伪豫北道尹等职，协助日军在河南推行伪化统治，其伪政权体系延伸至驻马店、泌阳等县，征粮征兵。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bbd7df606ebe42efbd4e95107ff90d8e','b79841ca-01f1-4628-96df-91c3f75fd641',1938,'河南安阳人','河南安阳人，抗战期间投敌，历任伪河南省政府要职，协助日军推行保甲、征粮、清乡等政策，其伪政权体系延伸至豫南各县。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1573e028ba2547979eeb96118e046605','af628fbb-b1d4-43fa-9765-94a80bdb20b2',1945,'南阳本地士绅','南阳本地士绅，1945年日军侵占南阳时出面组织维持会，任伪南阳县县长，协助日军维持城区秩序、征粮征夫，是南阳地区直接附逆的代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14ac04076f76439e865363b040ff5c08','6673b3ab-1ca1-4058-a367-d11f49272c8c',1945,'1945年日军占领南阳期间','1945年日军占领南阳期间，出任伪南阳警察局局长，协助日军搜捕抗日人员、维持治安，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-168a2ca3d5a64b03be75e91f343f91d2','82df4ed9-b840-445d-bd31-8ef3d6f7b249',1945,'南阳地方武装头目','南阳地方武装头目，1945年投靠日军，任伪南阳保安团团长，配合日军扫荡南阳周边抗日武装，为日军提供情报和向导。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9971eec5e36645b5918335c4ee00272c','9ae1ab52-7db0-44e4-8eaa-2286a02573bf',1945,'南阳商界人物','南阳商界人物，1945年日军占领南阳后出任伪商会会长，为日军筹款筹粮，协助日军控制南阳经济命脉。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19c6ac1560f546648b4cdbc47fd04582','40d30e16-0a3c-4a60-a893-184d444686ef',1938,'河南信阳人','河南信阳人，抗战期间投敌，任伪豫南道尹，管辖信阳、南阳部分区域，组织维持会，为日军征粮征丁，配合日军扫荡豫南抗日根据地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7ff4f835a9149cba487fb85f2ea3579','40d30e16-0a3c-4a60-a893-184d444686ef',1938,'在豫南信阳一带组织伪政权','在豫南信阳一带组织伪政权，活动范围接近平顶山南部，配合日军扫荡豫南抗日武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-470a0977de4a427aa8414c28a2e38586','d94b4d59-7c30-486e-9430-2068c1f6add7',1938,'原东北军将领','原东北军将领，抗战期间投敌，任伪豫东道尹、伪河南省政府委员，在豫东推行伪化统治，为日军征集物资，其伪政权体系与南阳地区有行政关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb76ec005588419d91f21be0f5755998','d94b4d59-7c30-486e-9430-2068c1f6add7',1938,'伪豫东道尹','伪豫东道尹，管辖包括驻马店东部在内的豫东地区，协助日军建立伪政权，征发物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9d48cf83a2348afadb0d6979b00a40a','e3962650-b372-41c0-b35c-8e189125e132',1943,'原国民党军将领','原国民党军将领，1943年在河南林县一带被俘后投敌，任伪第四方面军总司令，驻开封等地，协助日军控制河南沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-caf122b35f094e3bad61426489a85d49','6295636f-d2ca-4a3a-b439-901aef8b0c2e',1940,'广东乳源人','广东乳源人，抗战期间随汪精卫投敌，在伪南京国民政府中担任要职，推行日伪统治政策，其伪政权名义上管辖包括河南在内的华中沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e85ded675a134d838bbe3b24a63192aa','8b0cfcb1-b9a8-447b-96c9-b68487430b43',1940,'湖南沅陵人','湖南沅陵人，抗战期间随汪精卫投敌，在伪南京国民政府中担任要职，参与伪政权财政与警政，其政策影响涉及华中沦陷区包括河南南部。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63ee845ae3b642e198185a21abad6fc8','c86687cd-950f-4ea7-88be-4a0775994f1d',1940,'辽宁辽城人','辽宁辽城人，抗战期间投靠汪伪政权，曾任伪河南省省长，在河南沦陷区推行日伪政策，协助日军维持统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f3d00d2aa3342cfb34be42cff2e7f57','18f8cb28-79ca-42ec-ae78-85de0d68644e',1940,'福建闽侯人','福建闽侯人，抗战期间投靠汪伪政权，在伪政权中担任内政部长等职，其政策影响涉及华中沦陷区包括河南部分地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92cdb3376d1d43bc9b25c8321678d99d','5592eb4a-febf-4d30-9583-c07ea7695779',1940,'贵州黎平人','贵州黎平人，抗战期间投靠汪伪政权，曾任伪河南省省长，在河南沦陷区推行日伪法令，协助日军控制地方。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f3dc9d1b1ed4377986b2e1ff9834330','a754c018-210f-40e6-bd34-5e5ba0473fee',1938,'抗战期间在河南沦陷区伪政权中任职','抗战期间在河南沦陷区伪政权中任职，负责警务与治安，协助日军镇压抗日活动，维护日伪统治秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96fbcce6b5cb46569c1fd3a2397100e3','4148531a-01e0-4c68-8ca8-8a5dca9daa71',1939,'河南唐河人','河南唐河人，抗战期间在唐河县组织维持会，协助日军维持地方治安，征发物资，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd7decdf857a4f97a4d0401752cb124a','ac25d762-8c89-43a7-80b5-111ef553b298',1939,'河南南阳人','河南南阳人，抗战期间在南阳县组织维持会，配合日军征粮征夫，维持日伪统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32035662f81d4564aa2bd142ea1937b5','68874990-75cb-47c4-9133-fe06abbe7903',1940,'河南南阳人','河南南阳人，抗战期间投靠日军，组织伪保安团，配合日军扫荡南阳周边抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63b495fe64134c0d8ce5a6ae10a170d3','ed2a54ec-ff6e-4a96-9949-490ad9af386d',1940,'河南唐河人','河南唐河人，抗战期间在唐河县伪警察所任职，协助日军搜捕抗日人员，镇压民众反抗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
