INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b7ae92efab1491788888a33ed6f9e19','59e1bf07-5c39-4ca6-b4e7-d0c534d551cd',1939,'河南南阳人','河南南阳人，抗战期间在南阳县伪警察局任职，协助日军维持治安，搜捕抗日分子。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01e0bd9d36a54a018937fa761eb80088','8b267fe7-cf35-4fb2-91f0-c421be7b3767',1933,'内蒙古人','内蒙古人，长期在伪蒙疆政权中任伪军头目，其伪军曾配合日军在华北、豫北一带作战，对河南北部地区构成威胁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c7604bcfcfe4f62b876ffbe4271b9f9','36dc0938-e3f1-49f6-bbcf-b2c2946bc640',1940,'广东乳源人','广东乳源人，汪伪政权核心人物之一，抗战期间协助汪精卫推行伪化统治，其伪政权对河南沦陷区有名义上的管辖权，配合日军镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf7240ab1d2f4e4a916fbed88d9b0fe1','a27ee80a-20fd-40c3-b702-dcf769ef108b',1940,'辽宁辽县人','辽宁辽县人，原东北军将领，投敌后任汪伪政权军事要职，参与整编伪军，其伪军系统在河南一带有活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2abe3e2a23546a79e031ec17f25cb43','32024fcb-b98f-48bc-800b-ef9bc59728b2',1939,'湖北黄陂人','湖北黄陂人，抗战期间投敌，任伪军要职，在武汉及周边地区包括河南南部一带配合日军作战，镇压抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6fb87301d4c4397a5a430610030bd86','0356f482-1600-49c6-968c-788ccb0480ac',1937,'安徽霍邱人','安徽霍邱人，北洋军阀余孽，抗战初期投敌，在华北组织伪军，其活动范围涉及河南北部，后因内讧被杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1e6599c8d2748b0b04e4b8f5260154c','2a70826d-4c66-4c13-9836-fc35f6f7de7d',1938,'吉林长春人','吉林长春人，反复无常的军阀，抗战期间投靠日军，在冀南、豫北一带组织伪军，配合日军进攻抗日根据地，后因再次谋叛被部下活埋。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a6b38d54e964efd86558428310604ba','2a70826d-4c66-4c13-9836-fc35f6f7de7d',1938,'原西北军将领','原西北军将领，投敌后任伪军头目，活动于华北，与陕西渭南地区有间接关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6644d6cb226e45f0906c46bacce0ddd2','2a70826d-4c66-4c13-9836-fc35f6f7de7d',1938,'反复投敌','反复投敌，在华北组织伪军，配合日军进攻抗日根据地，对陕西周边有威胁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93a5a72fc1f7495c8da75a612dab18af','3f649124-7921-4233-b25d-875a9eb94959',1942,'天津人','天津人，原国民党军将领，1942年在山东投敌，后任伪第二方面军总司令，所部在河南东部、北部一带配合日军作战，对河南抗战造成危害。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cc19271c0a644edafb80075d1f9e19d','3f649124-7921-4233-b25d-875a9eb94959',1942,'1942年在河南投敌','1942年在河南投敌，任伪第二方面军总司令，所部伪军驻防豫东、豫中，配合日军进攻抗日武装，其防区覆盖漯河周边。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5f5d7c41ea642378ab44e4360c6e632','3f649124-7921-4233-b25d-875a9eb94959',1942,'原西北军将领','原西北军将领，1942年率部投敌，任伪第二方面军总司令，驻防开封、郑州一带，配合日军扫荡豫中、豫东抗日力量，1945年后被国民党收编。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b458fd418574abebcca3bf89820f4dd','8f3ce961-a8bf-443f-9b28-443cb831e251',1937,'河北枣强人','河北枣强人，原东北军将领，投敌后任伪河北省长等职，其伪政权与河南北部沦陷区有行政关联，协助日军征粮征丁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c82246ffc9d24b228f5952ebd7b5a42b','8f3ce961-a8bf-443f-9b28-443cb831e251',1937,'在华北伪政权中任职','在华北伪政权中任职，协助日军维持河北及华北占领区秩序，对陕西抗日后方有间接威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de5d5bf26c6541d7805b5f24afd941da','07ae63a5-c874-422c-987f-227ee4825245',1938,'河南人','河南人，抗战期间投敌，任伪河南省长，在开封等地设立伪政权，协助日军统治河南沦陷区，包括南阳周边地区，推行征粮、征丁、清乡等政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e76faa49c0f94a4ebbdbe1be5a2a33bf','1e26b0e0-e3a5-4aee-91fc-800a011b3cf1',1938,'河南人','河南人，抗战期间投敌，任伪河南省政府要职及豫北道尹，在豫北地区协助日军维持伪统治，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16b5e3c8c4b341518482466b468ab98b','1e26b0e0-e3a5-4aee-91fc-800a011b3cf1',1938,'在伪河南省政府任职','在伪河南省政府任职，协助日军推行保甲制度、征发劳工，其伪政权体系延伸至南阳、西峡一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0250ca2f573b419cb747735f24eb5c1c','1e26b0e0-e3a5-4aee-91fc-800a011b3cf1',1938,'河南本地汉奸','河南本地汉奸，抗战期间在豫北道任职，管辖包括新乡、封丘在内的豫北各县伪政权，协助日军推行治安强化运动，掠夺物资、镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83094a99c8174f8183f770c1646aafc7','1e26b0e0-e3a5-4aee-91fc-800a011b3cf1',1938,'在河南日占区协助日军推行伪化统治','在河南日占区协助日军推行伪化统治，参与对濮阳等地的经济掠夺与思想控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9eca6938d682450a80307ba9319a90a3','1e26b0e0-e3a5-4aee-91fc-800a011b3cf1',1938,'抗战期间投敌','抗战期间投敌，任伪河南省政府委员、豫北道尹，管辖豫北包括濮阳地区，推行伪化教育、经济掠夺，配合日军扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c52e760e8fd4a319175d068c3852ef7','1e26b0e0-e3a5-4aee-91fc-800a011b3cf1',1938,'在豫北道任职期间','在豫北道任职期间，管辖包括濮阳在内的豫北各县，推行伪化教育、经济掠夺，协助日军维持占领区秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6dba070024e246749c8a3b4ba2d979ae','1e26b0e0-e3a5-4aee-91fc-800a011b3cf1',1938,'抗战期间在河南伪政权中任职','抗战期间在河南伪政权中任职，负责豫北道事务，管辖包括焦作、新乡在内的豫北地区，推行日军殖民统治政策，协助征发物资、镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-390a6ecae8ca4a1288197ca3cda4bda3','1c802c7e-d4c8-428b-b15c-413f66542dcf',1938,'河南人','河南人，抗战期间投敌，任伪豫东道尹，在豫东地区协助日军统治，其伪政权与南阳地区有行政联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1bd2f76eb19f4f149cd68862ef02a8a5','a61e6d49-ff36-4765-81b4-9d792aa88e75',1938,'河南人','河南人，抗战期间投敌，任伪豫南道尹，在豫南地区包括南阳一带协助日军维持伪政权，推行殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8bc8f94d1a79437d9946259b0dd3bc32','c84cce5f-c7ef-4c81-ad10-4ebaaac7fe03',1940,'河南南阳人','河南南阳人，抗战期间投敌，在南阳沦陷后组织维持会，任伪南阳县知事，协助日军维持地方治安、征粮征丁，是南阳地区直接附逆的代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4e8e2df2ca743ebaaceb672217521e6','2b6d79c3-3347-4b42-8ee7-de1d0569c963',1940,'河南南阳人','河南南阳人，抗战期间投敌，任伪南阳维持会副会长及商会会长，协助日军经济掠夺，控制南阳物资流通。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc014abeb10649c69a619794a1abbcf1','92713697-6e5d-4399-90d0-a77aab89bd72',1940,'河南南阳宛城人','河南南阳宛城人，抗战期间投敌，在宛城一带组织伪军，配合日军扫荡抗日武装，残害当地民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf9729e58e904cb9a00ac0a0303bc8dd','ee45387f-2c6a-4f42-8443-ce0311ecefb3',1940,'河南南阳人','河南南阳人，抗战期间投敌，任伪南阳保安团团长，协助日军维持南阳地区治安，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bacbc6b9d1674674b2075159f4a000c1','8d7fb644-7e63-426f-ae64-979bca1d7342',1940,'河南南阳人','河南南阳人，抗战期间投敌，任伪南阳警察局局长，协助日军搜捕抗日人员，迫害当地百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d80135f886d4dc8a396aa413638ddaf','fd48c3b1-0d94-429e-8a59-7b8d9b2a3a85',1940,'河南南阳人','河南南阳人，抗战期间投敌，任伪南阳教育科科长及中学校长，推行奴化教育，宣传“大东亚共荣圈”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7c47a84424847fa8eb3cfd645d68850','76e99af7-cbc7-421e-bca7-4c160d065573',1940,'河南南阳宛城人','河南南阳宛城人，抗战期间投敌，任伪保甲长，协助日军征粮征丁，监视当地民众，迫害抗日家属。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1add0d00a4154c69b9de97adfc859103','a245b5f1-e60f-4c8a-a9b1-398426a8051e',1940,'河南南阳宛城人','河南南阳宛城人，抗战期间投敌，组织伪自卫团，配合日军清乡，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-30966a96d49e47d3b297776ec05ec371','d7c21ddd-b01f-4032-92b7-8d06299380a5',1940,'河南南阳人','河南南阳人，抗战期间投敌，任伪特务队队长，为日军搜集情报，抓捕抗日人员，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9b1f9e0bdde4047ae88eaf55fff7c44','d7ea6bd0-4fca-4ab8-868b-586a608b22d8',1940,'河南信阳人','河南信阳人，抗战期间投敌，组织伪军，在豫南包括南阳东部一带配合日军进攻抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a5711cc61a84e98808e0737dd8f5030','b413f1b1-b75d-4fd0-b839-8b1ee7757956',1940,'河南人','河南人，抗战期间投敌，任伪豫南道尹公署顾问，协助日军推行伪化政策，影响南阳地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d84abb3fa6b3456bafcd89bbe838f384','da25da7b-2a45-4c1f-bf39-a64b2a19766e',1940,'河南南阳人','河南南阳人，抗战期间投敌，任伪南阳合作社理事长，协助日军统制经济，掠夺南阳物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b40e694440d444999ccc79cb4536417','dece6cfb-abb2-4bda-aab2-45f77afae340',1940,'河南南阳人','河南南阳人，抗战期间投敌，任伪新民会会长，宣传亲日思想，组织亲日团体，奴化民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4a1f2a495b5454db711a3adad836284','16db04c6-6ccc-4509-8c9a-7ccffe0e3360',1940,'河南南阳人','河南南阳人，抗战期间投敌，组织伪青年团，协助日军进行宣传与情报活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b8ffdd96409451fbb78697fdf4a6d18','d1dbe485-9423-49a7-be9f-a9033bbe73fa',1940,'河南南阳人','河南南阳人，抗战期间投敌，任伪妇女会会长，协助日军安抚民众，推行奴化教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e0a4200d5684ce9945def9a588a662c','43414203-4761-4fce-97f4-e23f7d20245c',1940,'河南南阳人','河南南阳人，抗战期间投敌，任伪商会副会长，协助日军征购物资，压榨商户。','危害等级C（丙级，基层头目）','hanjian');
