INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0483f66f9d6e46c8a9bc3312122a2d30','22a8426d-1d7a-40be-bcd0-a997bc393e30',1943,'原国民党军将领','原国民党军将领，1943年在河南林县一带率部投敌，被汪伪政权任命为伪豫北剿共军总司令等职，配合日军在豫北、豫西地区进行扫荡和反共活动，其部队活动范围涉及河南多地，对南阳、新野周边地区亦有影响。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b4a02f53c3c4469b0f79801a659f6e7','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'继陈静斋之后任伪河南省政府省长','继陈静斋之后任伪河南省政府省长，在河南沦陷区推行日军政策，组织伪军配合扫荡，其伪政权对南阳、新野地区有名义上的管辖权。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
