INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8571ce5a4b11499f95e9d8bc69865d57','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'河南伪政权头目之一','河南伪政权头目之一，配合日军统治河南沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
