INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d0b4197152542e885a3bd7a3ba8a992','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'接替萧瑞臣任伪河南省长','接替萧瑞臣任伪河南省长，继续为日军征集粮食、劳工，镇压抗日活动，其伪政权覆盖豫北新乡、辉县等地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
