INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-deba9eb6da4242db9521aaacff02592a','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'继陈静斋后任伪河南省省长','继陈静斋后任伪河南省省长，驻开封，配合日军在河南的占领统治，其辖区名义上包括洛阳。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25d26ff0f6ed46b1a21b984deedf3776','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'伪河南省长','伪河南省长，任内协助日军镇压抗日力量，维持伪政权运作。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a37b0ad97c64609b0053279fffcec0e','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'继任伪河南省省长','继任伪河南省省长，继续为日军服务，维持沦陷区统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09e6e7d570cf423e9df28447aed78f66','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'接替萧瑞臣任伪河南省省长','接替萧瑞臣任伪河南省省长，继续为日军服务，推行伪政权的保甲、征粮、劳工征集等政策，其辖区包括郑州、惠济一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21fee9e816f14101a03ba7392cb79f17','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'任伪河南省省长期间','任伪河南省省长期间，协助日军征粮、征夫，推行保甲制度，加强对河南民众的控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4586cd3856f74ef9a881c30c969cb03e','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'任伪河南省长期间配合日军第五次治安强化运动','任伪河南省长期间配合日军第五次治安强化运动，在郑州、开封等地强化保甲、清查户口，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-494e941067254e32ad84d8a2c8a4d4bf','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'继陈静斋之后任伪河南省省长','继陈静斋之后任伪河南省省长，在开封及郑州周边地区推行日伪政令，配合日军扫荡抗日力量，强化保甲制度。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7548dbdeda554e43b8d40d8e5cea6809','91a83710-ae71-47cb-bd0a-213fa5cff983',1940,'继任伪河南省省长','继任伪河南省省长，配合日军推行治安强化运动，在河南沦陷区实施保甲连坐，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29f1260c649746288d56f020e3e68243','975c23e0-833a-4e43-836d-af29274b7090',1942,'原东北军将领','原东北军将领，投敌后任伪河南省政府省长，后调任伪军事委员会委员，在河南沦陷区协助日军维持统治，其伪政权与南阳、新野地区有行政关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80102e0484fe4c86af11ba94919204ab','975c23e0-833a-4e43-836d-af29274b7090',1942,'抗战后期任伪河南省省长','抗战后期任伪河南省省长，在日军占领的河南地区维持伪政权，配合日军作战与后勤，直至抗战胜利。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58dfa837407d46c498a47adb035b8a6f','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'任伪河南省政府省长期间','任伪河南省政府省长期间，在河南沦陷区推行日军经济掠夺和奴化教育政策，其伪政权名义上管辖河南全境，对南阳、新野地区有行政影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52d43773f9fe40299e06db6f9d1a05ed','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'伪河南省长','伪河南省长，继续为日军服务，维持沦陷区秩序，新乡地区在其伪省政管辖范围内。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f069f9293fd74c7db555294a91b8cf4c','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'抗战末期任伪河南省长','抗战末期任伪河南省长，继续为日军服务，直至日本投降。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84bb29ef4adc45d49f0c13ddb041f7c7','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'抗战后期任伪河南省省长','抗战后期任伪河南省省长，直至日本投降，属河南伪政权头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
