INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f8e05b2730a4cb9b99f7911295efe8e','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'任伪河南省省长期间','任伪河南省省长期间，协助日军维持河南占领区秩序，其伪政权覆盖洛阳地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e4cb41f764b4fc1a79c5fcc378880a3','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'伪河南省长','伪河南省长，继续为日军提供行政支持，参与征发劳工与物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94bad66f7c464383bc2c1935f76e8e3b','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'抗战末期任伪河南省省长','抗战末期任伪河南省省长，随日军控制河南沦陷区，直至日本投降，其伪政权活动覆盖郑州地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6eeeefad5b44da3be82b815435fed14','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'在任伪河南省省长期间','在任伪河南省省长期间，配合日军实施经济掠夺和奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-831caa93c7b7433b8b9bf8d6abe2deae','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'伪河南省长','伪河南省长，协助日军掠夺河南物资、强征劳工，维持沦陷区殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f49a03e1cf24b5bb7ab10ec190bf41e','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'任伪河南省省长期间','任伪河南省省长期间，继续在河南沦陷区推行日伪统治，协助日军征粮、征兵，镇压民众抗日活动，其政令覆盖郑州及豫中地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdc89bcf791d4094970de3884cecf0d4','bb8022c2-8e91-410f-9414-eb02a426461c',1942,'任伪河南省省长期间','任伪河南省省长期间，协助日军掠夺河南物资，推行奴化教育，强化伪政权对基层的控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f41575bc26ea4f9389db7384bae7b5ad','4de1b762-1715-4a3c-a465-de12b9f6e4e1',1944,'1944年日军发动豫湘桂战役后','1944年日军发动豫湘桂战役后，河南大部沦陷，刘茂恩被汪伪政权任命为伪河南省政府省长，但未实际就任，其任命反映了当时河南伪政权对南阳、新野等地的名义管辖意图。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3211ba134cf48bfb2066e7079ee8d41','2d6115f0-337b-424f-824b-3766590234cb',1937,'北洋军阀余孽','北洋军阀余孽，抗战爆发后投敌，在伪华北政务委员会任职，并曾担任伪河南省政府顾问，协助日军在河南建立伪政权，对南阳、新野地区的伪化有间接影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb7c451e545346a191bab2763362c2c7','a0b9ae14-560b-4f13-bcb0-4eab985224b7',1938,'在伪河南省政府任职','在伪河南省政府任职，并担任伪豫南道尹，管辖豫南地区包括南阳一带，协助日军推行保甲制度、征粮征税、组织维持会，对南阳、新野地区的伪化统治有直接影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-146f0aab41154b1faf981ca28b81c51b','7a1b6ca3-b037-4b26-83ee-33ecd2f13eb8',1945,'1945年日军侵占南阳期间','1945年日军侵占南阳期间，出面组织伪南阳维持会并任会长，协助日军维持地方秩序、征派粮款，是南阳地区直接附逆的地方头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcf6d49180114855a44086f281525f33','77e1a881-a17c-446b-aba5-81ec55b2ebfb',1945,'1945年日军窜扰新野期间','1945年日军窜扰新野期间，出面组织伪新野县维持会并任会长，为日军征粮派款、维持地方，是新野当地直接附逆的汉奸头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2020f4715fe84f77ab4fb7ff6360b365','8510967a-1bb4-4552-bd27-b359121086ba',1938,'在伪河南省政府下任伪南阳道尹','在伪河南省政府下任伪南阳道尹，管辖南阳及周边各县，协助日军推行伪化政策、组织伪军和维持会，对南阳、新野地区的沦陷区统治有直接责任。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e969ea7897c94a6fa7fbdc9992d7b26b','70a047e8-cef3-400d-a5f3-613a0a52ca1a',1938,'任伪豫南道尹','任伪豫南道尹，管辖豫南包括南阳部分地区，协助日军建立保甲、征粮征税、组织伪军，对南阳、新野地区的伪化统治有直接影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83a5faa4b4804464bee402da8ba43feb','65fa55f0-4028-477c-ba9f-f8de8a23dcdd',1945,'1945年日军占领新野后','1945年日军占领新野后，被任命为伪新野县公署县知事，协助日军维持地方统治、征派粮款，是新野地区直接附逆的伪政权头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14c98613b77a4d6da0bea1426dde658c','7e030208-6c44-4de0-83f2-5a070f10cf10',1944,'抗战后期在豫南地区投敌','抗战后期在豫南地区投敌，组织伪军配合日军在南阳、新野一带进行清乡、扫荡，是当地伪军头目之一。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9f5eed621b84a5f8b49d5f89d156b47','decec9bc-2e24-41e9-94be-7372e21dedab',1943,'原国民党军将领','原国民党军将领，1943年投敌，任伪淮海省省长兼伪和平救国军第八方面军总司令，其伪政权管辖苏北、豫东部分地区，与河南沦陷区伪政权有联系，对南阳、新野地区有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec68b80392244a889088d9c4ae5c3ca5','decec9bc-2e24-41e9-94be-7372e21dedab',1943,'原国民党将领','原国民党将领，1943年投敌，任伪淮海省省长，活动范围包括河南东部与濮阳邻近地区，配合日军维持伪统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-adc62f31e5284ec9b437471e7afbc2eb','decec9bc-2e24-41e9-94be-7372e21dedab',1943,'原国民党将领','原国民党将领，投敌后任伪淮海省省长，所部活动于苏北、皖北、豫东地区，对河南东部及驻马店周边有一定影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a9266ba334d41f097e7cadf952af3f2','decec9bc-2e24-41e9-94be-7372e21dedab',1943,'原国民党将领','原国民党将领，投敌后任伪淮海省省长，其伪军活动范围涉及河南东部，与驻马店地区伪军有协同，协助日军维持占领区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f59c80209034f01a7313a4acb9c6595','36153bed-0ee3-4281-8697-dff92a152b2b',1937,'原东北军将领','原东北军将领，投敌后在伪华北政务委员会和伪河南省政府任职，协助日军在河南推行伪化政策，对南阳、新野地区有间接影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4db118202d784ea2a5ec233e659dce19','b766e1bb-1d55-45dc-a989-784c2ef02b4c',1938,'在伪河南省政府任职','在伪河南省政府任职，并担任伪豫东道尹，协助日军在河南沦陷区推行保甲、征粮、奴化教育，其伪政权与南阳、新野地区有行政关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b7b00dba35046c7a3d43375c2689cff','b766e1bb-1d55-45dc-a989-784c2ef02b4c',1938,'在伪河南省政权中任职','在伪河南省政权中任职，负责豫东道各县伪政事务，督导周口、商水、淮阳、鹿邑等地维持会与伪县政，为日军统治服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-645490aeab354f5384bf7b6ceab080e8','b766e1bb-1d55-45dc-a989-784c2ef02b4c',1938,'在河南日伪政权中任职','在河南日伪政权中任职，参与豫东道伪政权的建立与运作，协助日军推行治安强化运动，影响范围包括周口一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f6a60ca729bf4f74a0f4a7719a84f158','b766e1bb-1d55-45dc-a989-784c2ef02b4c',1938,'抗战期间在河南伪政权中任职','抗战期间在河南伪政权中任职，参与伪河南省政，协助日军在豫东、豫中地区推行伪化统治，其辖区涉及漯河周边。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5c231e2136944fcbfc8fd6c9764d838','b766e1bb-1d55-45dc-a989-784c2ef02b4c',1938,'抗战期间在河南日伪政权中任职','抗战期间在河南日伪政权中任职，协助日军推行伪化统治，参与征粮、征兵等事务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-589a5fc4aa964eb6846e871d49c3cf4b','b766e1bb-1d55-45dc-a989-784c2ef02b4c',1938,'在河南豫东地区担任伪职','在河南豫东地区担任伪职，协助日军维持占领区统治，参与伪政权行政与治安事务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57efaa080650455aabbd3d2c065c1a95','b766e1bb-1d55-45dc-a989-784c2ef02b4c',1938,'在豫东地区协助日军推行伪化统治','在豫东地区协助日军推行伪化统治，为驻马店周边伪政权提供支持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ddcee41fd824ac28feb7a48aaef97e4','2f8f0a4d-01c9-4a68-b83d-20253bcab3c7',1938,'在伪河南省政府任财政厅厅长','在伪河南省政府任财政厅厅长，负责在河南沦陷区征粮征税、掠夺经济资源，其财政政策覆盖南阳、新野等县，对当地经济造成破坏。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f62559f25094107bbfb89eeabe4f9ef','2f8f0a4d-01c9-4a68-b83d-20253bcab3c7',1938,'在伪河南省政府掌管财政','在伪河南省政府掌管财政，为日军筹措军费，掠夺河南物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5481f585d3e4c71a6086e1f19345a9e','55f4c20f-4676-4ad0-8d20-a31d897c74c9',1938,'在伪河南省政府任教育厅厅长','在伪河南省政府任教育厅厅长，在河南沦陷区推行奴化教育，篡改教材、宣传亲日思想，其教育政策覆盖南阳、新野等县，对当地教育领域造成附逆影响。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eabbfecdaab649e88a6434a96a10bad4','69719671-8bdd-4951-847f-99788e440d8f',1938,'在伪河南省政府任警务厅厅长','在伪河南省政府任警务厅厅长，负责组建伪警察队伍，协助日军在河南沦陷区维持治安、镇压抗日活动，其警务系统覆盖南阳、新野等县。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-673c3909825240d5bb428094909c788d','de7ed415-d3bd-4777-9360-863f5aa883ec',1938,'原国民党军将领','原国民党军将领，1938年在豫北投敌，任伪豫北剿共军司令，配合日军在豫北、豫西进行扫荡，其伪军活动与河南沦陷区伪政权有联系，对南阳、新野地区有间接影响。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-273428fcaf71415191ea9538ddefc837','b40420f7-9847-4858-9153-d424479089f8',1938,'在豫南地区投敌','在豫南地区投敌，组织伪军任伪豫南剿共军司令，配合日军在南阳、新野一带进行清乡、扫荡，是当地伪军头目之一。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e33a6d86298943b8ae6c4bc4a69d8a8a','fdf1b422-f0f1-4b21-97f2-ae9fae5d00f7',1945,'1945年日军占领南阳期间','1945年日军占领南阳期间，任伪南阳警察局局长，协助日军维持地方治安、镇压抗日活动，是南阳地区直接附逆的伪警察头目。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b76a209081e54de4a6eec894453dd944','3376b9c9-6ffd-4ad5-9951-1c962a1ab9a7',1945,'1945年日军占领新野期间','1945年日军占领新野期间，任伪新野县警察局局长，协助日军维持地方治安、镇压抗日活动，是新野地区直接附逆的伪警察头目。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80bf91354986446795c4d273baad47df','cf4761be-ae6b-4d02-9f5c-59eeca589289',1933,'内蒙古人','内蒙古人，长期在伪蒙疆政权任职，后率伪军进入河南，在豫东、豫南配合日军扫荡，其部队曾活动于南阳以东地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b432967bf0984653a35380780792b14b','d5491dfd-40b2-4489-9666-402631c30959',1943,'原国民党军第一二八师师长','原国民党军第一二八师师长，1943年在湖北沔阳被俘后投敌，所部伪军在豫南、鄂北活动，与南阳地区相邻。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3bd07eb97af14503a33a7cbea6a99450','d5491dfd-40b2-4489-9666-402631c30959',1943,'原国民党军将领','原国民党军将领，被俘后投降日军，在湖北、湖南交界地区组织伪军，配合日军对湖南的侵略。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01032b6f2fea4769adeb4c97967f3b2b','02b008f0-47fe-411e-9837-df2e238079f5',1943,'原国民党军将领','原国民党军将领，1944年投敌，在豫南组织伪军，配合日军进攻南阳、方城一带的抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8fcfa92916104ee5aecf7fe1d9f79ccb','02b008f0-47fe-411e-9837-df2e238079f5',1943,'在豫南地区组织伪军','在豫南地区组织伪军，配合日军进攻抗日根据地，活动范围包括南阳东部及驻马店一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fb2c82943934ca0948a97dd6c984855','02b008f0-47fe-411e-9837-df2e238079f5',1943,'抗战后期在豫南投敌','抗战后期在豫南投敌，组织伪军配合日军扫荡确山、泌阳、新蔡一带抗日武装，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf65ff3bdeba4a56b04b4f9183bc548a','02b008f0-47fe-411e-9837-df2e238079f5',1943,'抗战后期在豫南投敌','抗战后期在豫南投敌，组建伪军配合日军清乡，活动于驻马店、确山、西平一带，袭击抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38690f0a19894844a8f319178864672c','d928e821-d36e-4477-9620-94b1be0653d8',1945,'1945年日军侵占南阳期间','1945年日军侵占南阳期间，出面组织伪南阳维持会，为日军筹粮、派夫、维持治安，协助日军统治南阳城区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e42e091a0f0430c962263fe8b3d54dc','1bc4f164-5e85-4a9b-852d-f183f037f7f7',1945,'1945年日军侵占方城期间','1945年日军侵占方城期间，组织伪方城维持会，充当日伪政权在方城的代理人，为日军征粮、派款、拉夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a4792c233cd473f972cff0e765ad508','707c5d80-6d38-4e15-ad4d-61555c666ff9',1945,'方城本地人','方城本地人，1945年日军占领方城后投敌，组建伪保安团，配合日军清乡、扫荡，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-170073ce13dd427ebb526e25207a0ef5','f5f61ed7-a080-4342-a997-e6b3a050041e',1945,'1945年日军侵占南阳后','1945年日军侵占南阳后，出任伪南阳警察局局长，协助日军维持城区秩序，抓捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c0e2e30901642768c5e455b09df17a7','19922791-4133-4b9b-bb66-4d0ba6d15e1e',1945,'1945年日军占领南阳期间','1945年日军占领南阳期间，出任伪南阳县政府县长，为日军征粮、派款、推行奴化教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-757eae22ebe24208a64a493831a498ca','5bad8f7f-3d0b-4f60-91e1-22dd61654e1d',1945,'1945年日军侵占方城后投敌','1945年日军侵占方城后投敌，任伪方城县警察所所长，带领伪警察配合日军搜查、抓捕抗日人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ecd8637169ab47bca5d4110e5a48ddb5','7eae3ae7-677d-451e-9cfb-7398bf6908a0',1944,'1944年投敌','1944年投敌，任伪豫南特别区行政公署专员，管辖包括南阳在内的豫南地区，为日军筹粮、派夫、推行伪化教育。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d29f3d2749f43c899ed34823ce625e9','23cc6c90-b395-4292-975f-f45eb41c768f',1940,'河南人','河南人，抗战期间投敌，任伪河南省政府委员，参与伪政权决策，协助日军在河南推行殖民统治，其影响波及南阳地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f43abb91fbaf4d32a5990f2a472d2a88','23cc6c90-b395-4292-975f-f45eb41c768f',1940,'在伪河南省政府任职','在伪河南省政府任职，参与制定伪政策，协助日军在河南包括漯河地区推行奴化教育、经济掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abd36aa17082411282557170f1db788a','26fa1b46-fa81-4240-9c32-b784c1841145',1940,'抗战期间投敌','抗战期间投敌，任伪河南省教育厅厅长，推行奴化教育，在南阳、方城等地设立伪学校，灌输亲日思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4009cea217b141a8b4f09705d255fec2','6164329a-c6e4-487c-b26a-ac38a2cb141d',1940,'抗战期间投敌','抗战期间投敌，任伪河南省宣传处处长，为日军进行舆论宣传，在南阳、方城等地散发亲日传单、组织亲日集会。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fc43763065948caa8279f104c682c4b','00fd60ef-baa1-4f45-a63b-48fcdbbdd060',1945,'1945年日军侵占南阳后','1945年日军侵占南阳后，组织伪南阳新民会，进行亲日宣传，协助日军推行奴化教育。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1343301ec2244084871d7eef3f9818e5','67257e2c-4609-4537-bf35-08a80ef346c3',1945,'1945年日军侵占方城后','1945年日军侵占方城后，组织伪方城县新民会，为日军进行亲日宣传，拉拢当地士绅附逆。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b85521fb3c84d9290ae4e81deeaa439','ba60fbaf-a9a5-49ec-a1c4-f07cf1521810',1945,'1945年日军侵占南阳后','1945年日军侵占南阳后，出任伪南阳商会会长，为日军筹款、筹粮，协助日军控制南阳经济。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc99bac9972e4120ab8f430341a18f40','13b20201-1682-40c2-a7b9-9edbe9794309',1938,'在河南伪政权中负责警务','在河南伪政权中负责警务，组建伪警察队伍，配合日军搜捕抗日人员，其警务系统延伸至南阳地区。','危害等级B（乙级，市县厅局级）','hanjian');
