INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ddbcc97ed114eb0ae5c7d3b94c53ec4','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间在豫东周口、商丘一带组织伪军，投靠日军，配合日军进攻抗日根据地，统治豫东伪政权，其势力范围覆盖周口及郸城周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f33eac12110349c795fa407362519075','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间在豫东商丘、宁陵、柘城一带组织伪军，投靠日军，任伪和平救国军第一军军长、伪第四方面军总司令等职，配合日军进攻抗日根据地，控制商丘及周边地区，是豫东地区最具实力的汉奸武装头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f61799303b540c09bb6442efb85c139','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'柘城人','柘城人，抗战期间投靠日军，在商丘、柘城、鹿邑、亳州一带组建伪军，配合日军扫荡豫东抗日根据地，搜捕抗日人员，强征粮款，是豫东地区最具实力的汉奸武装头目。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3af83c6def8e491da617e10f0f2ea59f','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间在豫东商丘、民权、睢县、柘城一带组织伪军，投靠日军，配合日军扫荡抗日根据地，统治豫东伪政权，是商丘及民权周边地区最重要的汉奸武装头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10174663dab34f01af33ac9a5cafc838','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间在豫东商丘、永城一带组织伪军，初投日军任伪和平救国军第一军军长，后任伪第四方面军总司令，配合日军扫荡豫皖苏抗日根据地，1943年任伪河南省政府豫东道尹，在商丘、永城等地推行伪化统治、征粮抓丁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44fce0bd86fc46bb8e03b30701e7d9af','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在商丘、睢县、柘城、太康一带组建伪军，配合日军扫荡抗日根据地，推行伪化统治，是豫东地区最具实力的汉奸武装头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4845c0121dbc41afa08dc16d5800766f','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间在豫东商丘、虞城、柘城一带组织伪军，投靠日军，配合日军扫荡抗日根据地，统治豫东沦陷区，是商丘及周边地区最具代表性的汉奸武装头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca2038724901484797a0d35ac7e469ce','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'商丘柘城人','商丘柘城人，抗战期间在豫东商丘一带组织伪军，先后投靠日军、汪伪政权，任伪和平救国军第一军军长、伪第四方面军总司令等职，长期盘踞商丘、柘城、鹿邑、亳县一带，配合日军进攻抗日根据地，征粮抓丁，残害民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a12ffbfeb3e4bcb9468838ea502719a','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，镇压民众，控制平顶山周边部分区域。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62a38033e54040dc82d312a68349129a','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，其伪军势力曾活动于平顶山周边地区，1945年抗战胜利后被国民党收编。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d6cacc7ea0d4b3ea168305a75511edd','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫中一带组建伪军，配合日军进攻抗日根据地，其伪军活动范围覆盖漯河、周口、许昌等豫中地区，对包括召陵在内的河南沦陷区实行伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1cfd98760626461eb4c1a881d2c3ba42','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，曾任伪河南省政府豫东道尹，其伪军活动范围覆盖漯河及周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-958cb44189ff488fbdff3b3131cc8452','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，1944年后任伪第四方面军总司令，所部活动范围覆盖漯河、舞阳周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2732720aa8c4f069f7b1a3258108c7a','a98168ee-4e87-44f2-878c-c25ac8150d6d',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫北一带组织伪军，配合日军进攻抗日根据地，控制包括濮阳周边在内的豫北部分地区，后任伪第四方面军总司令，是河南境内影响较大的汉奸武装头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
