INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42a4ff731bc34398a44ad856d696c7a2','a0bd2cb6-2d12-4360-80cc-906e26e8d853',1939,'在商丘、周口一带负责伪警务','在商丘、周口一带负责伪警务，指挥伪警察配合日军搜捕抗日人员，镇压民众反抗。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02811b6a9be1424abf477686e3321e12','fc9868c6-c9fb-4965-89f4-8caa264f21d5',1938,'在淮阳、周口地区协助日军建立伪政权','在淮阳、周口地区协助日军建立伪政权，推行奴化教育，为日军提供情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-746d6cc692ba470aac23679c6df555ad','a239f5cb-3a59-4479-aa2f-4a929a2585c1',1943,'1943年在河南林县一带被日军俘虏后投敌','1943年在河南林县一带被日军俘虏后投敌，任伪职，配合日军在河南境内进行反共与治安作战，其部队活动范围涉及豫东、豫北，对河南抗战局势造成严重破坏。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c40c9d4cecd44793af7e01488983f050','e556cdc8-94e0-4144-ab15-2396066f4e72',1943,'1943年在河南北部被日军俘获后投降','1943年在河南北部被日军俘获后投降，任伪军总司令，协助日军在河南及华北地区清乡、扫荡，是抗战后期河南境内影响较大的投敌将领之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8699c3e5116c4a3f86b2569556991a52','075e34da-d87b-4b88-a580-2ed3cc6837ac',1938,'商水沦陷后出面组织维持会','商水沦陷后出面组织维持会，为日军筹粮、派夫、维持地方伪秩序，协助日伪政权控制商水城乡，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-028146cb4a1d4a3e92d414967bd860c5','6ff4768c-cbb8-4d7d-8195-6655b5bec180',1938,'商水本地人','商水本地人，抗战期间投靠日军，纠集地方武装编入伪保安队，配合日军下乡扫荡、抓捕抗日人员，勒索百姓，为害一方。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2e7a432296d4ed3b989c5e99c80b51e','7461cd6f-48a3-4829-8f94-efdf56f9497d',1938,'周口沦陷后组织维持会','周口沦陷后组织维持会，替日军征集物资、拉夫派款，协助建立伪基层政权，是周口地区较早附逆的地方头面人物之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96dc5d6c48324c8780be500d4fde52be','0fc8b5d1-5fac-4f3e-ad58-e96f55be4e65',1938,'在淮阳一带为日军推行伪政','在淮阳一带为日军推行伪政，组织伪保安团，配合日军对周口、商水、淮阳交界地区进行治安强化，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad758df181d5412b8ac0e5e35d8ef894','62d4c43d-f88a-43b1-a025-8bf344ce54b4',1938,'鹿邑沦陷后投敌','鹿邑沦陷后投敌，主持伪县政，为日军征粮征兵，协助日军控制鹿邑、郸城、商水一带交通线，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d802b20607aa4ae5808ce68ebe38c1e7','a27127f1-644d-4747-8b8d-48751dee1472',1938,'在太康任伪职期间','在太康任伪职期间，配合日军扫荡豫东抗日根据地，组织伪自卫团，强征民夫修筑据点，对周口北部地区造成较大危害。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebd6030df230455faf604e9d0bcfbd28','15850cf9-d228-47e7-b7ba-4913e50565e2',1938,'西华沦陷后出面维持伪秩序','西华沦陷后出面维持伪秩序，为日军筹款筹粮，协助伪军清乡，活动范围靠近周口、商水，是豫东附逆地方势力之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b171675b5fdb4ccbad70b50e4f5c9762','5c4dbfe5-2bf3-4217-9d73-1ea152fd1379',1938,'项城沦陷后投靠日军','项城沦陷后投靠日军，任伪县知事，推行保甲连坐，协助日军控制项城、商水、周口交界地区，镇压抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd76615be0874c3aae2a416a00d76670','0e3b46b7-64bf-4303-ad8a-2ead57cc0ba4',1938,'周口本地地痞出身','周口本地地痞出身，投日后任伪警察头目，带领伪警察配合日军搜查、逮捕抗日嫌疑人员，敲诈商民，民愤极大。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c3f3ae61e544aa5ac1f6a89ebadebe8','7a182607-3044-4b6b-a9c3-bb45269b92cb',1938,'在商水推行奴化教育','在商水推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣”，组织师生参加日伪集会，是文化教育领域附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a65f541fe4ee4f4e9c4719160e3016f5','2b2f0415-fe40-4602-8e4b-b54cf750e7f5',1938,'担任伪保甲长期间','担任伪保甲长期间，为日军搜集抗日武装情报，带领日伪军抓捕抗日家属，强征粮食和壮丁，直接危害商水乡村。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-197e3ed4887d48a091d76f5fc73b69d7','6a84e22e-f0b0-4f4a-a77c-af6c0bce86f0',1938,'太康沦陷后出面组织维持会','太康沦陷后出面组织维持会，后任伪县长，为日军征粮派款、拉夫修路，协助日伪维持太康及周边地区统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-890aed47d22147a5a4de00c9d29136f9','124ca8a6-9444-41fa-b5f6-045e66e6a6ca',1939,'在太康及周口周边地区收编土匪、地痞组成伪保安团','在太康及周口周边地区收编土匪、地痞组成伪保安团，配合日军进攻抗日武装，残害地方百姓，控制太康部分乡村。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-deac36385390483ca20da147d8031b8b','993b3f2e-9225-4ee9-8980-21e1a0c71b1d',1938,'在开封、商丘、周口一带参与伪政权事务','在开封、商丘、周口一带参与伪政权事务，协助日军推行治安强化运动，督导豫东各县伪政权建立与征粮。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa7e9bb510b94ed5b4e424856e264ace','99c993a2-74ff-4b5a-ade3-3c0dc6839cd5',1938,'在河南伪政权中负责警务与地方治安','在河南伪政权中负责警务与地方治安，协助日军在豫东包括周口、太康一带清乡、抓捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-53ba6a53c12d467980af9af59506aa42','99c993a2-74ff-4b5a-ade3-3c0dc6839cd5',1938,'在伪河南省政府中负责警务','在伪河南省政府中负责警务，协助日军镇压河南抗日活动，其警务系统覆盖郑州、新密等豫中地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d1a3252c0d894b8c8547ddd9a473d62f','99c993a2-74ff-4b5a-ade3-3c0dc6839cd5',1938,'在伪河南省政权中负责警务与地方治安','在伪河南省政权中负责警务与地方治安，协助日军镇压抗日活动，其警务系统延伸至河南各县，包括豫南驻马店地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abaf7a61e095413abdd9a6c0b20a03b2','ef2ead91-8872-4234-baae-112ac9e040af',1938,'周口沦陷后组织维持会','周口沦陷后组织维持会，为日军筹粮筹款、维持地方秩序，协助日伪控制周口及沙河沿线。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88eacfae190248e9b883d3f8b61a9570','cf93e33f-c20f-4446-972e-4767ac86b6db',1938,'在淮阳及周口周边地区为日军服务','在淮阳及周口周边地区为日军服务，推行保甲连坐，征发民夫，配合日伪扫荡抗日根据地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e93f7ce3addd4f3fa6a801829196df60','9a70e3b4-e68b-4852-a40e-9736265c68de',1939,'在豫东周口、太康、鹿邑一带活动','在豫东周口、太康、鹿邑一带活动，率伪军配合日军进攻抗日游击区，抢掠民财，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d37ec5da3a904839a3dfac2b9028bb49','b08eeb4b-52bb-4ad0-9bb5-64c5af24c763',1940,'在豫东地区驻防','在豫东地区驻防，与张岚峰部协同，在太康、柘城、周口一带参与日伪扫荡和治安作战。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-851d48ca02e24600a75c7aab79ebc8a5','7db19254-0e72-4445-890d-37bdb9a1f377',1938,'在豫东包括周口一带任职伪政权','在豫东包括周口一带任职伪政权，推行日军殖民统治，征发民夫、物资，协助日军扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56947f238b854bfbbc9e0316e7a49e3f','7db19254-0e72-4445-890d-37bdb9a1f377',1938,'在商丘设立伪豫东道公署','在商丘设立伪豫东道公署，统辖商丘、民权、睢县、柘城等县伪政权，推行日军殖民统治政策，征发物资，配合日军军事行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2c5ebb7e8dc4e03a75c9dba9e9159ec','bcedf209-b027-4af8-b675-1f272dfee309',1938,'淮阳邻近周口','淮阳邻近周口，其任伪县长期间为日军征粮派款，组织伪自卫团，配合日军对周口周边地区进行清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa4fc62cfd704feabe052ff30e24f4a2','73908ab8-5ad4-4678-9fd3-155ce5fbe2ba',1938,'商丘为豫东重镇','商丘为豫东重镇，与周口同属豫东地区，其组织维持会为日军服务，协助建立伪政权，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf76c672cb424093b7c619b39df0efe0','2058d910-4e18-4833-a080-f834f769f501',1938,'周口沦陷期间担任伪商会会长','周口沦陷期间担任伪商会会长，为日军筹集物资，强制商户捐款，协助日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-999788fcebb5468e99e1356d8d967eda','4b5348a1-ccda-4eb4-81be-b28d12cf87f9',1938,'辽宁人','辽宁人，早年东北军将领，抗战后投敌，曾与张岚峰在豫东地区共同组织伪军，参与对周口、商丘一带的治安作战和扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-856aab45f52144fabb051ec48414bd15','1a09b3ed-cc3b-4711-a3f6-fa3ad0c112c5',1938,'扶沟县地方士绅','扶沟县地方士绅，1938年日军侵占扶沟后出面组织维持会，后任伪扶沟县县长，为日军征粮派款、维持伪秩序，是扶沟本地直接附逆的代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a4f4a27c2c14093b06a03f7bf042cfc','0db4f8e9-f7ff-422b-99b8-b6e2894a8a3a',1938,'抗战初期在豫东地区投敌','抗战初期在豫东地区投敌，任伪豫东道尹，管辖商丘、周口、淮阳、扶沟等县伪政，协助日军推行保甲连坐和物资统制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a576c25279345838b7cf68471db13e5','e2c38541-126a-43f9-9f70-9972d9d5ca82',1938,'河南本地士绅','河南本地士绅，抗战后投敌，在伪河南省政府任职并一度出任伪豫东道尹，负责周口、商丘一带的伪政事务，为日军筹粮筹款。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c28a9fdc1fab4023ab339350286b0b6d','9d5280f7-fe69-40dd-b91a-268229e76112',1938,'周口本地商人','周口本地商人，1938年日军侵占周口后组织维持会，任会长，协助日军维持城区秩序、征发物资，是周口地区直接附逆的地方头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-174020729e154602953daf6eceeeb41b','5b294ea2-eed2-4fdd-afdd-3791efc4e144',1938,'淮阳地方商人','淮阳地方商人，抗战期间与日军合作，任伪淮阳县维持会副会长及商会会长，为日军采购军粮、棉布等物资，并协助推行伪币。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68d9fd3e8fcf4493a68a0553eb4bc266','1e032543-4474-49c8-8e3f-ae9bce0f78f3',1938,'鹿邑县人','鹿邑县人，抗战后投敌，任伪鹿邑县县长，配合日军在鹿邑、柘城、淮阳交界地区进行清乡，抓捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca32c1a378474fc3b41b96ddecd28380','43b8113a-9fbb-47a9-89cd-7590bab556aa',1943,'河北人','河北人，原国民党军将领，1943年在豫北投敌，任伪军总司令及伪开封绥靖公署主任，其伪军活动范围覆盖豫东、豫中，包括周口、扶沟周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f0288a6665c4333932f2f45563d5191','7346709a-4def-4942-b8c6-2244707dc05c',1938,'扶沟本地人','扶沟本地人，抗战期间投敌，组织伪保安团，配合日军在扶沟、鄢陵、西华一带进行扫荡和征粮，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fd99d9dc108414bbcfbab126544dd88','2db9845d-6744-422c-abe9-d885401804e3',1938,'西华县地方士绅','西华县地方士绅，日军侵占西华后组织维持会，任会长，协助日军维持伪秩序，为日军征集粮食和民夫，活动范围与扶沟相邻。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-041c078a7fae414fa811e1801fcab064','c9131e7d-ce1d-4c46-b45d-189ab0e2b6de',1938,'商丘地方商人','商丘地方商人，抗战后投敌，任伪商丘县维持会会长，后任伪豫东道尹公署顾问，协助日军在豫东各县包括周口、扶沟一带推行伪政。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-adbd1c2eb4a3474cb535df3784e1f887','4a59a329-024f-4e06-acba-df966ff94ced',1938,'沈丘沦陷期间出面组织维持会','沈丘沦陷期间出面组织维持会，充任伪县长，为日军征粮派款、维持伪秩序，协助日伪控制沈丘地方。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d9253ed77624384b0b62624034eb624','1bc8e5b2-85fe-43e2-9e4d-8cab20d6ca2f',1938,'在沈丘一带纠集地方武装投靠日伪','在沈丘一带纠集地方武装投靠日伪，编为伪保安团，配合日军扫荡、清乡，残害抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc0eb6a3fa8542a6989e00a3d57a90fe','96feefab-20d2-4c1f-8578-2cff435a0e03',1938,'周口沦陷后组织维持会','周口沦陷后组织维持会，为日军筹粮筹款、拉夫，协助日伪维持周口城区统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a59036863025472baf567347020191f8','3b82c205-6b9c-44e9-bbd1-695976f59722',1938,'在淮阳、周口一带充任伪职','在淮阳、周口一带充任伪职，推行日伪政令，征发民夫物资，配合日军对豫东抗日力量进行镇压。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fd30592795048dc9d81c19678f6588e','33137639-32de-477b-9325-cb12aaa96c7b',1938,'鹿邑沦陷期间投靠日军','鹿邑沦陷期间投靠日军，组织维持会并任伪县长，为日军征集粮食、修筑据点，镇压地方抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-855bd7d26c2f4470891167f8ef950bd9','180a0d55-54b8-42a0-8221-f9b395f05f82',1938,'商丘及豫东地区伪维持会头目','商丘及豫东地区伪维持会头目，为日军筹办物资、维持伪秩序，与周口、沈丘一带日伪势力有联系。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3307c11e233b475ba4ee6601012c1790','6528f994-f578-4c0e-8263-871347f186d6',1938,'项城沦陷后组织维持会','项城沦陷后组织维持会，为日军征粮派款，协助日伪控制项城及邻近沈丘地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-185432a387f34f088f9a24cd39612c14','32582442-c5a5-4496-9cb7-8bd46d7cb264',1938,'在沈丘充任伪警察头目','在沈丘充任伪警察头目，配合日军搜捕抗日人员，维持伪治安，欺压当地百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0157255d02547c4baf50a695e371655','26c25db2-c60c-400e-945a-30eeaf252280',1938,'周口商界附逆者','周口商界附逆者，协助日伪摊派捐款、物资，参与维持会事务，为日军统治周口提供经济支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c69ec3476a56467e98c57ae2c1a998e9','fd2335dd-83a1-4c56-bec3-85d1247307d3',1938,'河南项城人','河南项城人，早年北洋军阀出身，抗战期间投敌，参与伪军组织与指挥，其势力与豫东周口、淮阳地区有联系，属河南籍重要汉奸军事人物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d22c460a25e4e758df1c20e8afc2e8f','fd2335dd-83a1-4c56-bec3-85d1247307d3',1938,'辽宁人','辽宁人，抗战期间投靠日军，曾任伪和平救国军总司令，活动范围涉及河南东部及周口一带，协助日军收编地方武装、维持伪政权统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a29d91c65696417bb47b0de72fb08242','36a90219-2514-4530-a331-b7194176dec5',1938,'抗战期间任伪河南省长','抗战期间任伪河南省长，驻开封，统辖河南沦陷区包括豫东周口、淮阳一带的伪政权，推行日军政策，征发物资、镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90499e6ee20d4ea1a7257bb867b2c0e9','6f89b92a-034c-48c8-a410-b125c23263f8',1938,'在豫东道及淮阳地区任职伪政权','在豫东道及淮阳地区任职伪政权，协助日军维持占领秩序，组织维持会、保甲制度，征粮征夫，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-785f5f4af9f047e19f32c82966726cc3','742daa70-0d46-4837-a3c2-18e8cd95e38c',1938,'淮阳沦陷后出面组织维持会','淮阳沦陷后出面组织维持会，为日军筹粮筹款、招募伪警，协助日军控制淮阳城及周边乡镇。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f83c3076c02b467cb83b078d81a6e2df','7f0a8587-3b7e-4df0-ab0f-3429a7558ca5',1938,'周口沦陷期间任维持会会长','周口沦陷期间任维持会会长，配合日军建立伪基层政权，推行保甲连坐，协助征发劳工和物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c6e08e731494e159f8529b45a3dfa83','c2b5fe9a-9d0c-4757-bd9e-e5f6b23baf5c',1939,'在淮阳、周口一带收编土匪武装投靠日军','在淮阳、周口一带收编土匪武装投靠日军，任伪保安队头目，配合日军扫荡抗日游击区，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9129af1dc2634cf6b6794f4f54cfda06','d87ec641-a4b7-412d-be0f-b1dee0860eaf',1938,'在鹿邑、淮阳邻近地区任伪职','在鹿邑、淮阳邻近地区任伪职，协助日军推行治安强化运动，组织伪自卫团，镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d8c36a23f094effaa225f5af4d50c21','5eb6b418-f34e-42c1-8997-1d586f64869d',1940,'在豫东周口、淮阳、太康一带组织伪军','在豫东周口、淮阳、太康一带组织伪军，配合日军对抗日根据地进行扫荡，强征民夫、修筑据点。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81e166f8a4ad476bb06b67bf88fbdb45','a37c51af-90ff-4eed-8bc0-bb53d2ccc94f',1939,'在淮阳沦陷区推行奴化教育','在淮阳沦陷区推行奴化教育，改编教材，强制学生学习日语和亲日内容，为日军培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b09b815e3a8c41a5aa03952e9c8d2997','e2a09a5d-a4cd-4744-afe3-3a1dee1c747d',1937,'内蒙古人','内蒙古人，其伪军活动主要在华北，但与河南伪政权有军事协作，间接影响周口、淮阳地区伪军组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13ccc6d049b44a7cb0267f0bff56bb55','ac17b650-00a0-49bf-83d1-74dc281c6225',1938,'在淮阳任伪警察局长','在淮阳任伪警察局长，负责城区治安，抓捕抗日人员，协助日军清查户口、发放良民证。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cb7c7ee247a47aba40070ed045adb47','6125bded-4155-42cc-adc8-9c69cbc4bf56',1939,'在周口镇任保甲长','在周口镇任保甲长，为日军摊派粮款、征集劳工，监视居民言行，举报抗日嫌疑人员。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9be862b15267438aabb82ca270dc610b','9bdbfa1c-f5ce-4b9e-bd48-133a3ae465e3',1938,'控制淮阳沦陷区商业','控制淮阳沦陷区商业，为日军采购军需物资，协助经济封锁，压榨商户和民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a74c5931583c47608885af02f6bf99a9','34c30a83-508b-4a6c-bdb0-4c1245423c22',1940,'在豫东道伪保安系统任职','在豫东道伪保安系统任职，参与制定扫荡计划，协调周口、淮阳等地伪军行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aea1825fff3a4e179dd37387b19f5f90','ee97082c-9bb4-4360-8f3b-b90f8b5e3061',1938,'在太康、淮阳一带任伪职','在太康、淮阳一带任伪职，负责日军与伪政权间的联络，征调粮食、劳工，配合治安强化运动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-250a4a0b404a4ede9533ec11f7ecc525','149f0625-9f01-4cef-a0b1-4308573cfae5',1939,'组织淮阳地方伪自卫团','组织淮阳地方伪自卫团，配合日军守备据点，清乡扫荡，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15d440bbf7d249aa84933ca1f07ec30d','0e05a8c9-6049-4329-8977-146c0fb45603',1938,'抗战期间投靠日军','抗战期间投靠日军，曾任伪河南省省长及伪豫东道尹，管辖包括周口部分地区在内的豫东沦陷区，协助日军征粮、征丁、维持治安。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0eec2dd2bbb740b59346ce898c020602','b41805c4-0bf3-4498-8c03-65eb79130504',1938,'西华县地方士绅','西华县地方士绅，日军侵占西华后出面组织伪维持会，任会长，协助日军维持地方秩序、征派粮款，后伪维持会改组为伪县公署。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
