INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1dc8f8a86ad6437db5b16b5a651ae4a6','c023ebec-9226-4f04-83c9-e699a4347047',1939,'淮阳人','淮阳人，抗战期间投敌，任伪淮阳县公署知事，管辖区域邻近西华、周口，配合日军推行保甲制、征粮征丁，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fbc9894277441efa31628068d702139','63a7a914-ad83-47ab-9dba-921a33f6f9e6',1940,'原国民党地方武装头目','原国民党地方武装头目，后投靠日军，任伪豫东剿共军司令，在周口、西华、淮阳一带配合日军进攻抗日根据地，捕杀抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ea4f4b1d0f3412b8efeec532ad26a07','3f05cff8-9ee7-4513-955d-dda06b2be923',1940,'西华县人','西华县人，抗战期间任伪西华县警察所所长，带领伪警察配合日军清乡、搜查抗日分子，勒索百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cfd530b73bb42e09f94e6e75ef03715','902b6a78-f33a-498f-a49e-9038662bf7a1',1941,'西华地方武装头目','西华地方武装头目，投靠日军后任伪西华县保安团团长，率部配合日军扫荡西华及周边抗日根据地，抢粮抓丁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9386e99d7c604c08bce518074b59a726','35d95e7a-dcbe-4637-970c-268fbdba7169',1938,'内蒙古人','内蒙古人，抗战期间投靠日军，曾任伪蒙古军总司令，后参与豫东地区伪军指挥，配合日军在周口、商丘一带进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
