INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d9ec7cce86b42d680a9119bec7b3cc9','42816363-c6f6-4b68-8750-b9f7d7ef7f8f',1938,'鹿邑沦陷后出面组织维持会','鹿邑沦陷后出面组织维持会，后任伪县长，为日军征粮派款、拉夫修路，协助日军维持鹿邑及周边地区统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
