INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44b44f1943524bab99d8ec79349a450f','d5d5e18b-8f8d-43af-ac2b-58ad3901a744',1938,'淮阳沦陷后投敌','淮阳沦陷后投敌，组织维持会并任伪县长，在淮阳、鹿邑、周口一带为日军征粮征丁，配合日伪政权推行保甲连坐。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-965e7086fb8d44ba91793febd149808e','7162367d-f7cf-421b-8d1f-64dc74326682',1938,'商丘沦陷后组织维持会','商丘沦陷后组织维持会，后任伪豫东道尹，管辖商丘、周口、鹿邑等豫东地区，为日军推行治安强化运动、掠夺物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0b760bd7a1143b9895dc03f2cad5812','2b4db53b-699e-44bf-a25a-790bbac76983',1940,'在伪河南省政府任职期间','在伪河南省政府任职期间，统管全省伪警察，在周口、鹿邑等豫东地区建立伪警察网络，镇压抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44dcc469fa8248b592726b7876928def','f33b8bc3-4021-4b1b-919f-46428c5284ef',1943,'原国民党河北省主席','原国民党河北省主席，1943年被俘投敌，任伪集团军总司令，其伪军活动范围包括豫北、豫东，对周口、鹿邑地区抗日力量构成威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5a714b9d04f4500b68b3ed46b5d05bf','55e5a8fc-cd9e-463b-acc0-e5a8af8a5ba0',1939,'在鹿邑任伪警察局长期间','在鹿邑任伪警察局长期间，配合日军搜捕抗日人员，推行保甲制度，强征民夫修筑据点。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22bf848284144df5abfc40dac54f185e','20172e74-9dc4-4e15-9208-5bf72e511f99',1940,'组织伪保安团','组织伪保安团，协助日军守卫鹿邑县城及周边据点，参与对抗日游击队的清剿。','危害等级C（丙级，基层头目）','hanjian');
