INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ba1017d2db746918e2abffa596f4b77','171a36b5-9eed-4a2a-b0ff-67f3666b94d1',1937,'投靠日本','投靠日本，在河南推行伪政，协助日军掠夺资源，影响陕西邻近地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12cc21535df74ab4923445bada302dd3','171a36b5-9eed-4a2a-b0ff-67f3666b94d1',1937,'投靠日本','投靠日本，在河南伪政权中任职，协助日军扫荡抗日力量，其活动区域与陕西接壤。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0ddc613df4944149664f94f044c11cf','171a36b5-9eed-4a2a-b0ff-67f3666b94d1',1937,'河南伪政权后期头目','河南伪政权后期头目，其伪化活动与陕西渭南地区有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26d94fc6ae42450d8f72870815f91014','171a36b5-9eed-4a2a-b0ff-67f3666b94d1',1937,'投敌后任伪河南省省长','投敌后任伪河南省省长，协助日军搜刮物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37d82c547e604302ac4880dd2035715f','171a36b5-9eed-4a2a-b0ff-67f3666b94d1',1937,'在河南沦陷区任伪职','在河南沦陷区任伪职，配合日军统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cbc280cfa534248b91170b7359dfdcc','43a8c7fc-8925-4cda-80fd-95d317bbc69f',1933,'蒙古族汉奸','蒙古族汉奸，投靠日军，其伪军曾活动于河南北部及豫东部分地区，与商丘、民权日伪政权有联系，配合日军作战。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c02b0a18cf74b2eaa27d6e8aa144212','43a8c7fc-8925-4cda-80fd-95d317bbc69f',1933,'原东北军出身','原东北军出身，长期在伪蒙疆政权任职，1944年后其伪军部分力量活动于河南地区，与洛阳沦陷后的伪政权有联系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ea0c3ba0ac34328878147662f33065a','43a8c7fc-8925-4cda-80fd-95d317bbc69f',1933,'长期在伪蒙疆政权任职','长期在伪蒙疆政权任职，后与河南伪政权有联系，其伪军活动范围一度涉及豫北地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1231e7b6ce0247c793a49375dfe1a9ee','43a8c7fc-8925-4cda-80fd-95d317bbc69f',1933,'蒙古族汉奸','蒙古族汉奸，长期在伪蒙疆政权任职，后与河南伪政权有联系，其伪军曾配合日军在河南境内活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a1312e1806540fc816e031f081bf8d2','43a8c7fc-8925-4cda-80fd-95d317bbc69f',1933,'热河土匪出身','热河土匪出身，早年在东北投敌，后任伪蒙古军总司令，抗战后期其势力曾延伸至河南北部，配合日军作战。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab3f1b8b310c47d6af6179593fcd37f0','f04944b1-08fa-4daf-8495-23588b3ac82b',1938,'在豫东伪政权中任职','在豫东伪政权中任职，负责商丘、民权等县伪政事务，执行日军命令，征粮征夫，镇压抗日民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9cc3e115cc1044218221f108093aff2c','66965981-197b-4c2d-ae84-cfa83f3ded13',1939,'组织伪保安团','组织伪保安团，配合日军在商丘、民权一带清乡扫荡，搜捕抗日人员，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-190d64dfbfc648e08fb23c7a9afd1c2e','6a3d7ddc-643b-4a55-94e6-dcd852fb63d3',1940,'在民权县组织伪保安武装','在民权县组织伪保安武装，协助日军维持治安，参与对周边抗日根据地的扫荡与封锁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c78ba56994854d819a5df8f6629a9402','2d7eadee-9d9e-4ae1-a7a2-89fe005475b8',1939,'在商丘伪政权中负责教育','在商丘伪政权中负责教育，推行日军奴化教育，篡改教材，向学生灌输亲日思想，活动范围覆盖商丘及民权等地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3b3fd3994e2449b8419f144a4a0e2ab','1ae758e1-c7a4-407d-8c84-a5a9d8e37f1b',1940,'负责河南沦陷区伪宣传','负责河南沦陷区伪宣传，为日军侵略辩护，推行奴化宣传，其宣传网络覆盖商丘、民权等豫东地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b2b33c1330a49fb88474f420ebe6d1d','f2e3c091-4eaa-4196-a3f2-4f187cea1318',1938,'抗战时期在商丘地区附逆','抗战时期在商丘地区附逆，任伪豫东道尹公署道尹、伪商丘县知事，协助日军维持商丘及永城周边治安，推行保甲连坐、征发民夫粮秣。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c882555a11b47f6a2fb10a2e552f2de','4c853d55-6849-464f-805f-023ea9d17d5b',1938,'永城沦陷后出面组织伪维持会','永城沦陷后出面组织伪维持会，后任伪永城县知事，为日军征集粮草、修筑据点，配合日伪对永城及周边抗日武装进行清乡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2465c39e2fe644c2a4c6fb4e0a4a8e35','d23e776c-beef-4073-a7e1-d8f1c43783f9',1939,'原为地方武装','原为地方武装，后投靠日军，任伪永城保安团团长，在永城、夏邑一带配合日军扫荡，袭击抗日游击队，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d9a30d479d74ba28551b701e3cde122','d473a758-46cd-49d5-b8b7-bf963a7caace',1938,'任伪商丘县警察局局长期间','任伪商丘县警察局局长期间，在商丘城区及永城方向配合日军搜捕抗日人员，推行良民证制度，镇压民众抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-298d799b00994525ae7fe08bb577fba4','c5a8448a-8edb-47a3-8ffd-d65a4886ce6b',1940,'在商丘、永城、亳县交界地带组织伪军','在商丘、永城、亳县交界地带组织伪军，配合日军对豫皖苏边区进行扫荡，参与制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fccd0a385107476fb923c74a2ff17901','ce0af944-ce68-4587-8a26-30bd4103b630',1938,'在夏邑、永城一带附逆','在夏邑、永城一带附逆，任伪夏邑县知事，后任伪豫东道尹公署参事，协助日军推行伪化教育、征粮征丁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af71b07b4caa4fefba2a2dff9f3a6b44','3ec5412c-a04d-4570-8885-34e4cebc0a8c',1938,'商丘沦陷后任伪商会会长','商丘沦陷后任伪商会会长，为日军筹款筹粮，协助日伪对商丘、永城等地进行经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b72a321dcdb94a2fb7a2e3d37f5e521f','dbc7fc2e-d348-4d94-a91e-7a2969d4fe82',1939,'在永城任伪警察所所长','在永城任伪警察所所长，带领伪警配合日军下乡扫荡，抓捕抗日家属，勒索民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94745ac1d8d14f25a328ca7ff2b7bab7','c6b39166-5878-4424-8eb2-fbb8907d5062',1943,'原国民党河北省主席','原国民党河北省主席，1943年投敌，任伪开封绥靖公署主任，统辖河南伪军，其势力范围覆盖豫东商丘、永城等地，配合日军维持伪统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b5d65d0919c4ff8830fee3a6e43b4c5','2d44fe07-f149-40b2-bfa9-c454164a67a2',1939,'在亳县、永城交界地区组织伪军','在亳县、永城交界地区组织伪军，任伪亳县县长兼永城亳县联防司令，配合日军对永城抗日根据地进行封锁和扫荡。','危害等级C（丙级，基层头目）','hanjian');
