INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d86bf952799418ca2e55912e92953fe','7572fedf-ed24-45c1-87b5-f382f392a8ff',1938,'商丘沦陷后在伪政权中任职','商丘沦陷后在伪政权中任职，参与推行保甲连坐、征发劳工和粮秣，协助日军维持豫东占领区统治。','危害等级C（丙级，基层头目）','hanjian');
