INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca0cb5bcb89d4b5685e107dc31ed7924','a4069239-727c-4cd0-9a98-d99c0f695620',1938,'睢县伪警察头目','睢县伪警察头目，带领伪警搜捕抗日人员，镇压群众抗日活动，为日军搜集情报、维持占领秩序。','危害等级B（乙级，市县厅局级）','hanjian');
