INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f2985290a3c41d4801b330f58c34c2d','efd25f74-9156-4ebe-ab9d-2c23aef27750',1940,'原国民党军将领','原国民党军将领，后投敌任伪军师长，活动于豫东商丘、夏邑、永城一带，配合日军进攻新四军和抗日游击队。','危害等级B（乙级，市县厅局级）','hanjian');
