INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35eafb5bfd0648c5ac127955f2b701fd','95e9a779-abd5-4148-8fe1-205e606637ca',1938,'在豫北道任职期间','在豫北道任职期间，督导安阳、滑县等地伪政权，推行保甲、征粮、抓丁，配合日军扫荡抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d634513998bf4974865e4f554cbf1714','95e9a779-abd5-4148-8fe1-205e606637ca',1938,'在豫北道任职期间','在豫北道任职期间，协助日军控制安阳等县，推行保甲连坐、物资统制等政策，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
