INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7618c58abe049b8a02b7bfba7da0cba','95e9a779-abd5-4148-8fe1-205e606637ca',1938,'在豫北地区依附日军','在豫北地区依附日军，参与伪政权行政，配合日军对豫北各县包括新乡、延津地区的控制与掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
