INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-342bdd01efb741349cd60378992f137e','95e9a779-abd5-4148-8fe1-205e606637ca',1938,'曾任伪豫北道尹','曾任伪豫北道尹，管辖豫北地区包括鹤壁、淇县、浚县等，协助日军推行保甲、征粮、清乡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b95b5a62a6c4e44bf1e41af4b4f5cc0','b184d3f9-ef57-4c71-99c3-39488084f8fe',1937,'安阳沦陷后率先组织维持会','安阳沦陷后率先组织维持会，后任伪县长，为日军征集物资、修筑工事，并协助建立伪保甲制度。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-509af7bfce7d40189433c4a066984fa4','e88a94c3-8132-4345-937a-c63f9be15fa0',1938,'原国民党军将领','原国民党军将领，投敌后率部驻防豫北、豫东，配合日军进攻抗日根据地，在安阳周边地区多次参与扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10ffd77624aa41aa9d5fb0b24b86879d','e88a94c3-8132-4345-937a-c63f9be15fa0',1938,'原国民党军将领','原国民党军将领，投降日军后任伪军头目，活动于豫东、豫北一带，配合日军进攻抗日根据地，其势力范围涉及安阳周边。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54412b9993b04b4ebd6d20bfdeaa6b72','5041c5ed-ec45-40ab-a66d-a98f802f7694',1940,'率部投敌','率部投敌，所部驻防豫北安阳、新乡一带，协助日军守备铁路、据点，进攻八路军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
