INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a886234fdc37475eb0bd13689d328356','4b430d82-b180-4507-ba1f-3b62d0e46823',1940,'在伪河南省政府任内推行亲日奴化教育','在伪河南省政府任内推行亲日奴化教育，编写伪教材，组织学生参拜神社，培训伪师资。','危害等级B（乙级，市县厅局级）','hanjian');
