INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2dbf4ed8b666422b8020e691c6457fce','b5c63fbc-66b9-4261-b640-f9c7d1527f80',1942,'原国民党将领','原国民党将领，1942年率部投敌，任伪和平建国军第二方面军总司令，后任伪开封绥靖公署主任，其伪军活动范围覆盖河南大部，包括郑州、惠济一带，协助日军扫荡抗日根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
