INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d25e16147b24472eae4de172b0d1d5a6','a8e7d52f-9101-4321-9108-3c48c5a8aafc',1944,'郏县沦陷后率部投敌','郏县沦陷后率部投敌，配合日军扫荡郏县、宝丰交界地区，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c33157fa6d74a12a68ca12b1e683cbd','e5733d31-54d9-4c59-8946-68017ea0123c',1940,'河南地方伪军头目','河南地方伪军头目，在豫中一带组织伪军，配合日军扫荡抗日武装，活动于平顶山、许昌、漯河周边地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-290f43a8a9514387a24f843494e1f501','97ef937c-1e49-42ba-9295-bf471267da39',1938,'河南安阳人','河南安阳人，投靠日军后任伪安阳县长，组织伪军配合日军扫荡豫北、豫中抗日根据地，其势力范围一度延伸至平顶山周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f36b7f4c11cf4a39a8bd93b96b3c0da5','ed8ee742-5e21-4711-a019-e62869860834',1938,'抗战期间任伪河南省长','抗战期间任伪河南省长，主持伪省政，推行日军殖民统治，征粮征丁，镇压抗日活动，其伪政权覆盖河南全省包括平顶山地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56414bc4dc774458bea0cb947c269bc4','ed8ee742-5e21-4711-a019-e62869860834',1938,'在河南伪政权中任职','在河南伪政权中任职，协助日军维持占领区，对陕西抗日后方有威胁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95b4cf23f7c545f08219eb5d2109f738','47b19663-fec5-42d6-81ac-711ebed464b7',1944,'1944年日军占领平顶山地区后','1944年日军占领平顶山地区后，出面组织维持会，为日军征粮征夫，维持伪秩序，协助日军控制当地煤矿与交通线。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd6c8c50c07f4a5bb462d8dc770a81fe','47b19663-fec5-42d6-81ac-711ebed464b7',1944,'1944年日军侵占平顶山地区后','1944年日军侵占平顶山地区后，出面组织维持会，为日军筹集粮草、拉夫派款，协助日军维持地方治安，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b4963cf2637499eabae9166a00051bb','907fdda6-fd5f-4c72-8eeb-42eb2215d4fc',1944,'1944年日军占领许昌后出任伪县长','1944年日军占领许昌后出任伪县长，组织维持会，为日军征集物资，协助日军控制豫中包括平顶山地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83005b3ef6804505a97092898e89f20b','9073c2eb-7593-4ddf-bd2b-5c99e36e96b6',1944,'临汝（今属平顶山汝州市）沦陷后组织维持会','临汝（今属平顶山汝州市）沦陷后组织维持会，任伪县长，为日军征粮派款、搜集情报，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
