INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54fb1652fd3b48e5a28168116ecec531','f14c410a-3d90-4c19-86c1-b8faef85d502',1944,'叶县（今属平顶山）沦陷后组织维持会','叶县（今属平顶山）沦陷后组织维持会，任会长，协助日军统治地方，征发劳役。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34a8a6628e3d46ee879b591c50accc45','2ab04ce6-6810-4b21-86e2-8b92b0c82733',1944,'郏县（今属平顶山）沦陷后任维持会会长','郏县（今属平顶山）沦陷后任维持会会长，为日军服务，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
