INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-590d5e23435542a79f61d15f112732af','cca96e9c-98d1-4854-9519-eca4eddab7e5',1944,'平顶山地区沦陷后','平顶山地区沦陷后，出面组织维持会，为日军征集物资、情报，协助日军管理煤矿及地方治安。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-815f11d435fa41d79f11645d09d8a4bc','ac4c1da2-24f5-4e25-b52e-76b49bde51cb',1944,'宝丰县邻近平顶山新华区','宝丰县邻近平顶山新华区，李振亚在日军占领宝丰后出任伪职，组织维持会，征派民夫、粮食供给日军，配合日军扫荡周边抗日武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9f91c953a0743fda557de99ace30fed','46f9027f-bba6-4cc2-aaa4-30ca17c7d0a7',1944,'叶县与平顶山新华区接壤','叶县与平顶山新华区接壤，赵子明在日军侵占叶县后组织维持会，为日军提供情报、粮秣，并协助建立伪保甲制度。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-040fc0c7713744f8b67a71a5b748e17b','adfbf9a1-82a1-4f4b-8a0f-ece07ff31840',1944,'鲁山县靠近平顶山新华区','鲁山县靠近平顶山新华区，刘子久在日军占领期间出任伪维持会副会长，协助日军征粮、派款，维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d49db4154e6344ae88dc9dc34d3103f5','af82f38c-c589-481b-a0d3-7e8c81f9f34e',1944,'襄城县与平顶山地区相邻','襄城县与平顶山地区相邻，张伯英在日军侵占襄城后组织维持会，为日军征集物资、修筑工事，并参与伪政权基层管理。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff7d6722f8ca44e988a1292e7d6378cc','4844734a-5e2f-497b-8b6c-51d27db875ec',1944,'郏县紧邻平顶山新华区','郏县紧邻平顶山新华区，王明远在日军占领郏县后出任伪维持会会长，协助日军推行保甲、征粮抓丁，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc3b1d9ee5844bc186e2ef8c3a9254d8','1b947350-1283-4077-85e2-0165ed5d9083',1937,'抗战期间在河南沦陷区出任伪职','抗战期间在河南沦陷区出任伪职，先后任伪河南省维持会会长、伪省长，协助日军在河南各地建立伪政权，其伪省府机构对平顶山、汝州等地的伪县政权有统辖关系。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff32d1783fa7444889b159b1f107d209','1b947350-1283-4077-85e2-0165ed5d9083',1937,'河南人','河南人，抗战期间投敌，曾任伪河南省省长，主持全省伪政权，推行日军殖民政策，其伪政权体系覆盖濮阳、南乐等豫北地区，为日军搜刮物资、镇压抗日力量服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-574d0e8389114a139e41fbb84e198503','1b947350-1283-4077-85e2-0165ed5d9083',1937,'河南安阳人','河南安阳人，抗战初期即组织伪维持会，后任伪河南省政府省长，为日军在河南推行殖民统治，其伪政权机构设于开封，对郑州、新密等地伪政权有统辖关系。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be5f2765cf244352b364a94877c387d3','1b947350-1283-4077-85e2-0165ed5d9083',1937,'河南本地士绅','河南本地士绅，日军占领开封后出面组织伪维持会，后任伪河南省长，协助日军在河南各地建立伪政权，包括郑州、荥阳地区的伪县政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68db64afeec246dcaceea920d778b745','1b947350-1283-4077-85e2-0165ed5d9083',1937,'河南本地汉奸','河南本地汉奸，抗战初期组织维持会，后任伪河南省省长，协助日军在河南各地建立伪政权，驻马店、平舆等县伪政权均受其统辖。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60d155f90137445cb596486656a8e638','1b947350-1283-4077-85e2-0165ed5d9083',1937,'河南安阳人','河南安阳人，抗战初期即组织维持会迎降日军，后任伪河南省省长，协助日军在河南推行殖民统治、征粮征丁，其伪政权体系覆盖驻马店各县。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-477dc53cf44b4119b67846614b0a026f','1b947350-1283-4077-85e2-0165ed5d9083',1937,'抗战初期即在河南参与组织伪维持会','抗战初期即在河南参与组织伪维持会，后任伪河南省政府省长，协助日军推行殖民统治、征粮征丁，其伪省政权覆盖河南包括驻马店一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-264be3fc7d134d41b011ac44e35f3331','bd412627-698f-4a3d-9f3b-05aa117b93bb',1938,'在河南沦陷区任伪豫西道尹等职','在河南沦陷区任伪豫西道尹等职，负责豫西地区伪化行政，其辖区包括临汝（今汝州）、郏县、宝丰等平顶山地区，协助日军征粮、拉夫、维持治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0c93635f6fa4758a8d7fd3b4f9c3810','bd412627-698f-4a3d-9f3b-05aa117b93bb',1938,'在伪河南省政府中任职','在伪河南省政府中任职，负责豫西道事务，管辖洛阳及嵩县等地，协助日军推行伪化政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c111b3f727f48b5883f8f400904b187','bd412627-698f-4a3d-9f3b-05aa117b93bb',1938,'1944年日军占领豫西后','1944年日军占领豫西后，出任伪豫西道尹，管辖包括洛阳在内的豫西地区，协助日军维持统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d05b90ec16744a4baddd40e9c250365','02ad77e9-f226-4f13-b320-39a47a9eb478',1944,'1944年日军侵占临汝（今汝州）后','1944年日军侵占临汝（今汝州）后，出面组织维持会并任伪县长，协助日军建立伪政权、征发物资、镇压抗日活动，是汝州本地直接附逆的代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8629a1f636d543d3be730ebfc8a46fc6','cd103db1-cda9-4341-95e0-4da392577657',1944,'临汝沦陷后投靠日军','临汝沦陷后投靠日军，任伪保安团团长，率部配合日军扫荡汝州周边抗日武装，维护伪政权统治。','危害等级C（丙级，基层头目）','hanjian');
