INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d649c7dd2fff448aa262c3bb861a42bf','0d48c0e5-0b55-447a-b19e-47f8db96023a',1944,'1944年日军占领许昌后','1944年日军占领许昌后，组织维持会并出任伪县长，为日军征集物资、维持治安，其活动范围与漯河、临颍同属豫中地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
