INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-846b70ca3aa64dc6b17a4c93fcd55926','58c8aa10-2f84-4aa8-91e5-d7f4f84b6d97',1938,'在河南沦陷区任伪教育厅厅长','在河南沦陷区任伪教育厅厅长，推行奴化教育，在包括平顶山、汝州在内的沦陷区学校强制使用伪教材，进行亲日宣传。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69337152c4034fa18a0f92510c2c9e26','87735732-a369-4fce-996d-79a23f7bae6a',1938,'任伪河南省警务厅厅长','任伪河南省警务厅厅长，统辖沦陷区伪警察力量，在平顶山、汝州等地建立伪警察机构，配合日军镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
