INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-240ad316c2c6455e89daa639445ce800','6e3b6e3b-d72d-440c-8415-52ca1375d004',1933,'北洋旧军阀','北洋旧军阀，九一八后投靠日本，1933年任伪华北政务委员会顾问，同年被军统刺杀于北平六国饭店，其活动与河南及新乡地区有政治关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2892428deb24f429070a0a0b807b80c','6e3b6e3b-d72d-440c-8415-52ca1375d004',1933,'北洋旧军阀','北洋旧军阀，九一八事变后投靠日本，被委任为伪河南省政府主席，1933年在北平被刺杀，其活动与河南及华北伪政权有关。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92eed9ba497140939f47b16ffb0ffeaa','d1a0dde5-5416-4157-880a-be681a079c42',1938,'抗战期间投敌','抗战期间投敌，历任伪河南省政府委员、警务厅长、伪河南省长等职，协助日军维持河南沦陷区统治，其伪政权管辖范围包括新乡地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8e15346862449d5bcf3c174b949a88f','a4bd2413-d811-499c-a396-97b0b8196def',1938,'抗战时期投敌','抗战时期投敌，曾任伪豫北道尹，驻新乡，直接管辖新乡、凤泉一带伪政权，后升任伪河南省长，为日军征粮、征夫、维持治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
