INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b2dcb904ab94612813f3397d455f99e','af76eda6-d34b-44e1-aaad-693e2cf1d11b',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫北一带组建伪军，长期配合日军对河南抗日根据地和国统区进行扫荡、蚕食，1943年后任伪河南省省长，是河南地区影响最大的汉奸武装头目之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-efcb155435bd4a4685a481343805c912','af76eda6-d34b-44e1-aaad-693e2cf1d11b',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，后任伪河南省省长，其伪军势力活动范围覆盖漯河及周边地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4919a68376b240cdbcaaad3a915fe081','af76eda6-d34b-44e1-aaad-693e2cf1d11b',1938,'河南柘城人','河南柘城人，抗战期间投靠日军，在豫东、豫北一带组织伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南地区最具代表性的汉奸之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd38ee0743e4416faf12291c2a31c22a','8bda2abf-17bd-4f0b-855b-5e90ffaebb91',1943,'1943年在河南林县一带被日军包围后投降','1943年在河南林县一带被日军包围后投降，所部被编为伪军，活动于豫北、太行山南麓一带，配合日军进攻抗日根据地，对包括新乡在内的豫北地区造成危害。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-208ec2895961446db4d2265c13d67084','d2284a86-afb9-4240-b4f5-61ad08537537',1943,'1943年在豫北林县、辉县一带被日军俘获后投降','1943年在豫北林县、辉县一带被日军俘获后投降，被日军委任为伪军总司令，所部活动于豫北地区，配合日军维持伪统治，对新乡及周边地区有直接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8733754a3914803bcaf3b9f19fe5163','35e198ad-b63d-4268-a594-46ad2c9a327e',1938,'抗战期间在新乡县城沦陷后出面组织维持会','抗战期间在新乡县城沦陷后出面组织维持会，后任伪新乡县县长，协助日军征粮、征夫、维持治安，镇压抗日活动，是新乡本地伪政权的重要人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5ff128fcd5d4b36a32aa2e74dbc9421','35e198ad-b63d-4268-a594-46ad2c9a327e',1938,'抗战期间在新乡沦陷后出面组织维持会','抗战期间在新乡沦陷后出面组织维持会，后任伪新乡县县长，协助日军征粮、派夫、维持地方伪政权，直接服务于新乡及周边地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
