INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5dee7befbb8b4472baaae70461d64d80','34499257-e3fe-441e-9998-c83e471ece33',1938,'在豫北道任职期间','在豫北道任职期间，负责新乡、封丘等县伪政权的督导，配合日军实施经济统制、征发劳工，是豫北地区伪政权的重要汉奸官员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
