INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b083e324fc524cbbb3c1aca28a4d4bde','3acf56b9-6246-4210-b966-8c0f9982edb4',1933,'北洋旧军阀','北洋旧军阀，抗战初期投靠日本，被任命为伪河南省政府主席，尚未赴任即在北平被军统刺杀。其活动与河南伪政权筹建有关。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b171ebfa0bf246f5932d15e79587cf4b','883eca2c-800b-435d-8f55-a069e26b1080',1938,'伪豫北道公署驻新乡','伪豫北道公署驻新乡，王锡龄任道尹期间，在新乡、辉县等地推行保甲连坐，组建伪自卫团，配合日军清乡，搜捕抗日人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-247068d0b4544ed29ec0d490e40c0115','f7e9184b-3316-4a76-931a-2951de753927',1938,'辉县沦陷后组织维持会','辉县沦陷后组织维持会，为日军带路扫荡山区抗日根据地，强征民夫修筑公路和炮楼，迫害抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41da50c05db247ee9b6a46ac8984214c','6b8f6e2c-52cf-45ea-a433-173f45825a79',1940,'任伪辉县县长期间','任伪辉县县长期间，配合日军对太行山抗日根据地进行经济封锁，推行配给制，强征粮食和铜铁，抓捕抗日群众。','危害等级C（丙级，基层头目）','hanjian');
