INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a3f5b14c4bd4d2aacc2bbc92c85e59a','26733ff1-2dda-4669-a196-aa6ec1e01d72',1941,'控制新乡、辉县等地物资配给','控制新乡、辉县等地物资配给，低价强购农产品，高价配售日货，为日军经济掠夺服务，盘剥当地民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67dba95aa7454ceab871ec2226dc453c','4a282bbe-eb52-4ad7-b97a-8dfc51da1194',1942,'率伪保安团在辉县山区配合日军搜山','率伪保安团在辉县山区配合日军搜山，抓捕抗日游击队员，烧毁村庄，勒索百姓钱财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-baa936d7725a4050a8507b6f802c2585','675d20dd-3391-454a-b5cd-de8a96fc281a',1939,'推行奴化教育','推行奴化教育，在新乡、辉县各学校强制开设日语课，篡改历史教材，组织学生参拜神社，毒化青少年思想。','危害等级C（丙级，基层头目）','hanjian');
