INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86453e77e4fe4822bd9bf0414a80969b','a037bc54-7cd6-4638-9f2b-ec8f60cc5acc',1944,'1944年日军侵占临颍后','1944年日军侵占临颍后，出面组织维持会，后出任伪临颍县县长，为日军筹粮筹款、征派民夫，协助日军维持地方治安，是临颍当地直接附逆的代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c625b4963aaf4b0d8a6a5a16b069d520','d9b8aa16-7e1a-4e8c-888a-0fc369fc0814',1944,'1944年日军占领郾城后','1944年日军占领郾城后，组织维持会并出任伪县长，为日军征集物资、维持地方秩序，其活动范围覆盖漯河及周边地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d69c9dd01b3247b0a5c7bfdaa1098567','f5df2ffe-043b-4b17-a294-9e10abd76edb',1944,'1944年日军侵占漯河后','1944年日军侵占漯河后，出面组织漯河镇维持会，协助日军管理地方事务、征发物资，是漯河当地直接为日军服务的汉奸头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
