INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-457e2c194679498aafedb17149da7a7a','d17d5546-b057-4a48-b730-e85276177433',1939,'原国民党军将领','原国民党军将领，抗战期间在河南北部与日军勾结，组织伪军配合日军进攻抗日根据地，其活动虽主要在豫北，但对河南全省伪军体系有影响。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86c651e6eaff4065941fc669c651a301','10848061-dd02-4333-8542-30f0cfd2f589',1938,'在伪河南省政府中负责宣传事务','在伪河南省政府中负责宣传事务，为日军殖民统治进行文化宣传和奴化教育，鼓吹“中日亲善”“大东亚共荣”，是河南文化教育领域附逆的代表人物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec799628858d454592b760d120ebd7b5','31741e7f-8325-4540-ba07-ccc23518cd2f',1944,'1944年日军占领漯河后','1944年日军占领漯河后，出面组织伪维持会，协助日军维持占领秩序、征派物资、登记户口，是漯河当地直接附逆的伪政权头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-51d5da3952674751b0b3a64a2b107fdf','3ed53655-101d-469b-905a-eb183792725f',1944,'郾城沦陷后任伪维持会会长','郾城沦陷后任伪维持会会长，为日军征粮、派夫、维持地方伪秩序，郾城为漯河附郭县，召陵即在其辖境，属当地直接附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0cdfcebcf6c24b4d932af568c892c58c','3ed53655-101d-469b-905a-eb183792725f',1944,'郾城地方士绅','郾城地方士绅，日军侵占郾城后率先投敌，组织维持会，为日军带路、指认抗日人员及家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bcc7e70fd399496f8995889f849fcc25','6176824c-9a63-40d3-9fce-3a8a5c7b3153',1944,'在郾城沦陷期间任伪警察局长','在郾城沦陷期间任伪警察局长，配合日军搜捕抗日人员、镇压民众，维持伪治安体系，活动范围覆盖漯河、召陵一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bee9387d85904803a6d9987a0f85a2f8','bf277999-2e04-4d21-97ff-4140634507e2',1944,'临颍沦陷后组织伪维持会','临颍沦陷后组织伪维持会，协助日军征粮、派款、维持占领区秩序，临颍与漯河、郾城相邻，属漯河周边地区附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-490997c0bbad449696c5c1b1f56573f7','bf277999-2e04-4d21-97ff-4140634507e2',1944,'临颍沦陷后组织伪维持会','临颍沦陷后组织伪维持会，协助日军维持临颍及邻近舞阳地区的统治秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca288f3a4bc54b44874e18045b6b8349','be55b08a-a8f4-404b-8196-18c911055a65',1944,'许昌沦陷后任伪维持会会长','许昌沦陷后任伪维持会会长，为日军筹粮、派夫、维持伪政权，许昌为漯河邻近地级区域，其伪化活动与漯河一带伪政权联系密切。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6863992ff0ea4c3d94ed28c2505b0883','458f969f-6b2c-4b59-ae7d-861a724b6605',1944,'舞阳沦陷后任伪维持会会长','舞阳沦陷后任伪维持会会长，协助日军控制舞阳及周边地区，舞阳与漯河、郾城接壤，属漯河周边附逆伪职者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3671f4b47e849b6a30ae248903f85b6','5b080fa9-2937-402e-8945-a1be59806796',1944,'漯河沦陷期间任伪商会会长','漯河沦陷期间任伪商会会长，为日军筹款、摊派物资，协助维持经济掠夺体系，属经济领域附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebe1f014e5d74c989f1630464808f03f','e8eb641c-3f02-403f-aefa-30423c457fff',1944,'在郾城沦陷期间任伪教育科科长','在郾城沦陷期间任伪教育科科长，推行日军奴化教育，篡改教材，宣传“大东亚共荣”，属教育文化领域附逆者，活动范围覆盖漯河、召陵。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5c371aa753042ecb1fbc28b863afdb8','7d4d1404-cca8-412b-9bb7-b754b515adf8',1944,'召陵当地保甲长','召陵当地保甲长，日军占领期间协助伪政权征粮、派夫、清查户口，直接为日军和伪维持会服务，属基层附逆者。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7215946c6684ef58970639470d47ecf','971bce89-e659-4b29-a883-2e898f4a4298',1938,'在伪河南省警务系统任职','在伪河南省警务系统任职，负责伪警察力量，配合日军搜捕抗日人员，其警务网络覆盖漯河等豫中城镇。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d70bee512ad435b9fcaf08c02cdec5a','30bc7b38-00ba-4071-b2b6-7e1c9a294b9d',1944,'漯河本地商人','漯河本地商人，1944年日军占领漯河后出面组织维持会，为日军筹集物资、招募劳工，协助维持占领区秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63dbca2650184fa8996ee8d3cd0e7259','e7a6a16c-2d7f-40f6-ad10-435749ad49c5',1944,'郾城县（今漯河市源汇区、郾城区一带）伪政权头目','郾城县（今漯河市源汇区、郾城区一带）伪政权头目，日军占领期间任伪知事，推行保甲制度，征粮派款，配合日军清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73a0e214d6bc4549b576d3df8770659b','c77ecd89-591c-48dc-ad17-bd451bde28ff',1944,'在漯河镇（今源汇区）任伪警察所所长','在漯河镇（今源汇区）任伪警察所所长，带领伪警察配合日军巡查、抓捕抗日嫌疑人员，勒索商户。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33a91f348d2f4cffbe6cd753809e1cf2','2f435b31-1085-4289-a615-654bdee0e08e',1944,'漯河本地地痞','漯河本地地痞，日军占领后充当保甲长，负责摊派捐税、监视居民，多次向日军密报抗日人员行踪。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73076a1742844fc5a73de4c913edf695','d852d048-9aa5-4a1b-9fc5-b897baa8e793',1944,'漯河郾城人','漯河郾城人，1944年日军占领郾城后出面组织维持会，为日军征粮、派夫、维持地方秩序，协助日军控制漯河地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcc697b58e2444258383a933abda7af6','d22a6f54-bef1-43cc-851c-af0c04515ae9',1944,'日军侵占郾城后出任伪县知事','日军侵占郾城后出任伪县知事，在漯河、郾城一带推行伪政，征发物资、登记户口，配合日军统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de7ab73e75aa4c3887b87c7440a8c79d','b5bb8ed4-c705-4ba3-a4d1-a8f8b5cdd6f7',1944,'漯河镇人','漯河镇人，日军占领漯河后组织维持会，为日军搜集情报、征派民夫，协助日军控制漯河镇及周边区域。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8d474fde2a745c0a34e7336ae99d6b8','390ccff9-82b3-4da5-b80d-de5bb8695446',1944,'临颍县人','临颍县人，1944年日军占领临颍后出任维持会会长，为日军征粮派款，维持伪秩序，活动范围邻近漯河。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da0e27b539f34f01b93e9c935b3cef7c','4eef3ac4-4ddb-48e3-bdb5-9111d7503b3e',1944,'舞阳人','舞阳人，日军占领舞阳后组织维持会，协助日军征发物资、维持地方，活动范围覆盖漯河西南部。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c277ea29bd44bd7a2ace55f2e2c7938','73aecb82-7d42-4c39-903f-cd507c1425a2',1938,'安徽合肥人','安徽合肥人，抗战期间投敌，曾任伪河南省政府省长，在河南推行伪政，为日军征粮征丁，其伪政权覆盖漯河地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5feab67a38e449308d18f4b7572974db','6fc95474-404c-4849-8bdd-0d0acfcf8ce2',1938,'北洋旧军阀','北洋旧军阀，抗战初期投敌，在伪河南省政府中任职，参与伪政，为日军在河南的统治服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1158b5f91fd4c3babc3bee11eadc23c','6fc95474-404c-4849-8bdd-0d0acfcf8ce2',1938,'在河南日伪政权中任职','在河南日伪政权中任职，协助日军推行伪化政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2850997a7be34375ac47d52bb6ba8441','1c29ffdb-3483-4455-8be6-240bdf4a1dbb',1944,'日军占领郾城后出任伪警察局局长','日军占领郾城后出任伪警察局局长，在漯河、郾城一带搜捕抗日人员，协助日军维持治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-811ca79b519847298404c0c247702dc2','d15599d9-363e-447e-8d96-3a1570fac714',1938,'惯匪出身','惯匪出身，抗战期间投靠日军，在河南、山东一带组织伪军，配合日军扫荡抗日根据地，其活动范围曾涉及漯河周边。','危害等级C（丙级，基层头目）','hanjian');
