INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6276abbf50094f45aedb042d6811e026','9c1afe91-3061-447e-8a83-612666a82ad6',1944,'郾城沦陷后任伪维持会会长','郾城沦陷后任伪维持会会长，配合日军在郾城、漯河一带推行伪化统治，征发民夫、粮食。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7e6bd70a19c4d33a6dc500333128a81','f74430fd-6b91-44b6-8c09-f7faed84d589',1944,'任伪舞阳县警察局长','任伪舞阳县警察局长，协助日军镇压抗日活动，搜捕抗日人员，维持伪政权治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3250cca6049d4c6cb3063ba1a44cb11a','8597a78b-7858-484e-be0d-bfe81eb896ee',1938,'任伪豫南道尹','任伪豫南道尹，管辖豫南沦陷区包括漯河、舞阳一带，推行日军殖民政策，组织伪军配合日军扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75d61e812f65420fb993f6a443628308','f2f5c454-3767-4498-a579-cc57d9626842',1944,'组织伪保安团','组织伪保安团，配合日军清乡、扫荡，镇压舞阳地区抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cbcdd792a4d46e8b30fd07bd490a95e','89db1f00-1030-435d-b1be-ba54eb67b340',1944,'任伪郾城县保安大队长','任伪郾城县保安大队长，协助日军维持郾城、漯河一带治安，参与抓捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5d08e2c56d7450db4a2aca874b0eed9','3f770418-285e-468f-bbf9-1e99c17ff24d',1944,'1944年日军占领郾城后','1944年日军占领郾城后，出面组织维持会，后任伪郾城县县长，为日军征粮、派夫、维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d71b5a1ac1874c4d9517b4f63d00cdd6','b789e1a5-8d81-42e2-b50a-283800432d5e',1944,'漯河沦陷后组织伪维持会','漯河沦陷后组织伪维持会，协助日军控制漯河水陆交通与商业，为日军筹集物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4aff9b740bde47d8b418a273e1ca4363','2d254c1a-66b1-44cc-a257-a4849312957c',1941,'活动于临颍、郾城、漯河一带','活动于临颍、郾城、漯河一带，投靠日军后组织伪军，配合日军进攻豫中抗日武装，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28c8e71421184dccb9381e37a7aa56c1','5598d2ea-c77c-4af6-9785-abec08440819',1938,'河南沦陷区伪政权官员','河南沦陷区伪政权官员，负责许昌及周边包括漯河、郾城一带的伪行政事务，推行保甲、征粮、奴化宣传。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d3f33d17c3e403a8bf7954fd262a099','1204483b-b29c-4503-b368-0489cd12fd71',1944,'舞阳沦陷后投敌','舞阳沦陷后投敌，组织维持会并任伪县长，协助日军控制舞阳及邻近漯河地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca13fba1d18b4f0587c63dbb0cc77c41','469e4458-3a14-4e79-81b8-2739d2656aac',1944,'抗战后期在豫中投敌','抗战后期在豫中投敌，组织伪军活动于许昌、漯河、郾城一带，配合日军维持占领区秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22d5cf9490d8407cb78ff2a129ab9141','71c77899-7460-450e-bf74-1a7635a29244',1944,'郾城沦陷后任伪警察局长','郾城沦陷后任伪警察局长，协助日军搜捕抗日人员、镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0ac07804ce445e1ae907e23c75997b4','fd764fa8-a3e7-4f60-9ba9-e1314bf9dc68',1944,'漯河沦陷期间任伪警察头目','漯河沦陷期间任伪警察头目，为日军维持治安，参与抓捕和迫害抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f96808bf21242adbc8cf69198bc6cf7','ca0a9b5e-cfcf-4581-bd5f-b8c0dc23724e',1944,'组织伪保安团','组织伪保安团，配合日军在郾城及周边地区“清乡”，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2af427c1653f4f0fa4e4dfd37441df43','3b0883a3-4458-4ff7-b445-fc5ef1710220',1944,'地方伪保甲长','地方伪保甲长，为日军派粮、派夫、搜集情报，协助维持沦陷区基层统治。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cfc474cdfb94bbd836c45f4756972a3','dec28d6b-675f-44da-ab81-ab0cf73131a6',1937,'日军侵占濮阳后出面组织维持会','日军侵占濮阳后出面组织维持会，协助日军建立伪政权，推行保甲连坐，为日军征粮派款、搜集情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a78ab28bdd94755b254ec52f8333c15','dec28d6b-675f-44da-ab81-ab0cf73131a6',1937,'抗日战争时期投靠日军','抗日战争时期投靠日军，在濮阳组织维持会，后任伪濮阳县知事，协助日军征粮、派款、抓捕抗日人员，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e2bb636362d4fb5ba1e0ed602ebd597','219eb513-1926-494b-a5df-bf2f9021c2eb',1938,'率部配合日军扫荡濮阳周边抗日根据地','率部配合日军扫荡濮阳周边抗日根据地，捕杀抗日军民，强征民夫修筑据点与封锁沟。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4814788737a47408e93c9e9cc032acf','219eb513-1926-494b-a5df-bf2f9021c2eb',1938,'濮阳人','濮阳人，抗战期间投靠日军，任伪濮阳县保安团团长，率部配合日军扫荡濮阳、台前一带抗日武装，捕杀抗日干部和群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f9f3001d2a04058a7d5114187a260f9','219eb513-1926-494b-a5df-bf2f9021c2eb',1938,'率部投降日军','率部投降日军，编为伪濮阳县保安团，配合日军扫荡濮阳周边抗日根据地，袭击抗日武装，残害群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb9fa20b43a043fc8b66f101d405b0cc','03a40bce-78f4-4fd3-8c9d-e6d8973230de',1939,'在濮阳城内搜捕抗日人员','在濮阳城内搜捕抗日人员，镇压群众抗日活动，协助日军维持占领区治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c2f084be30d42a7b9433ad4dfadba93','b6e7aaf5-dc6d-4d2f-b566-b500d9fe31de',1938,'在清丰一带推行伪化教育','在清丰一带推行伪化教育，强征粮食供给日军，配合日军对濮阳、清丰交界地区进行清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0970f2724c754570b031f4975d9dbe1b','ff19159c-9daf-4c50-9662-2dc8af50c146',1938,'在冀南道所属濮阳、清丰、南乐等地组织伪军','在冀南道所属濮阳、清丰、南乐等地组织伪军，配合日军扫荡，残害抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-698c6d3a2f1a4483ac45d5256fbbdcc2','0d995a11-e5dd-4a70-9461-9d337ce94dec',1937,'在南乐组织维持会','在南乐组织维持会，为日军筹粮筹款，协助建立伪政权，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fe3ef6fc45746f0b6b746abadda6c98','5649d4a2-443e-4f76-a4ff-fe1eebeb39eb',1938,'在豫北濮阳、滑县、长垣一带率伪军配合日军作战','在豫北濮阳、滑县、长垣一带率伪军配合日军作战，袭击抗日武装，抢掠民财。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bb7c62a4c744ae1b873adf2e9e939da','53171e4f-3bcd-4b4d-9312-371c2678e851',1938,'主持豫北伪政权','主持豫北伪政权，辖濮阳等县，推行治安强化运动，为日军掠夺物资、征发劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f241c8cbdbaf4f9abe96287842b183d3','bfa83e8e-a2a8-4b52-ae08-8333abc7dd67',1939,'在濮阳推行奴化教育','在濮阳推行奴化教育，篡改教材，强迫学生学日语，宣传“大东亚共荣圈”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ece5815239942acbdd65abba96feccf','21609ae9-0451-4d4b-b59b-8b2715d36750',1938,'为日军筹集军需物资','为日军筹集军需物资，控制濮阳商业，配合日军经济封锁抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-534b06f861da4a259d5b0f6afa390417','b88f8f42-a93a-45be-ab87-dc7658033fb5',1938,'在滑县一带配合日军扫荡','在滑县一带配合日军扫荡，强征民夫、粮食，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e81b868e45dd485781001ae2918b6572','242ceb98-44b6-485a-8dbc-aff039f1b2bf',1938,'濮阳人','濮阳人，抗战期间投靠日军，在豫北濮阳、清丰、南乐一带组织伪军，配合日军扫荡抗日根据地，曾任伪豫北道尹，后任伪剿共军第一路司令，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-408b250dc6c149b09d85f6f93d7e9d17','c8522e09-6337-4dfd-9b39-01e8401c95bb',1943,'原国民党河北省主席','原国民党河北省主席，1943年投敌，任伪第二十四集团军总司令，后任伪河南省主席，其伪政权势力涉及豫北濮阳地区，配合日军维持占领区统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70423fed257444429799d6d8d6e0fe54','a4f1bd5b-913e-4e98-91af-c57dd194b8a9',1940,'原西北军将领','原西北军将领，投敌后任伪开封绥靖公署主任、伪河南省主席，在河南沦陷区推行伪政，其管辖范围涉及濮阳一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8faa93a58d1481dbe88f9587cfacd5c','e00b5f88-a086-4f04-be5e-f7a3a8c36cc3',1938,'抗战期间任伪豫北道道尹','抗战期间任伪豫北道道尹，驻安阳，管辖豫北包括濮阳、清丰、南乐等县，推行保甲制度，配合日军征粮征夫，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c2b8b2d0a5743a495c7984136a9922c','20c26426-7eb3-4d9a-9644-d227a31c88c5',1938,'濮阳本地人','濮阳本地人，日军占领濮阳后出面组织维持会，后任伪濮阳县县长，为日军征粮派款、搜集情报，协助日军维持地方统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d05a36cbe8b44f58166703b6a31da7d','20c26426-7eb3-4d9a-9644-d227a31c88c5',1938,'濮阳本地人','濮阳本地人，日军占领濮阳后出面组织维持会，后任伪县长，为日军征粮派款、搜集情报，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-780801ae3565434a95d963e079f4f9cd','257fca67-e6f1-42d2-b0c5-35476f9e3754',1938,'抗战期间任伪清丰县县长','抗战期间任伪清丰县县长，清丰毗邻濮阳华龙区，其伪政权配合日军对冀鲁豫根据地扫荡，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57e819acd3e6470d876a9bec4839b494','0ac8151b-2a09-419b-8bb9-059f59fea1ff',1938,'抗战期间任伪南乐县县长','抗战期间任伪南乐县县长，南乐与濮阳接壤，其伪政权为日军服务，推行奴化教育，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-862419866de3474f94430aa9b7d7a9ad','cf6b501d-4939-43e4-8222-f3b0478fca9b',1938,'抗战期间任伪濮县县长','抗战期间任伪濮县县长，濮县旧治位于今濮阳境内，其伪政权配合日军控制黄河渡口，封锁抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eda5ed101c274b3693ee290874b76a76','cce51102-9714-4ad1-9a49-0407261ad829',1938,'抗战期间任伪滑县县长','抗战期间任伪滑县县长，滑县与濮阳相邻，其伪政权配合日军扫荡冀鲁豫边区，征粮派款，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-508d6bc59bda46a98a80af202cc5c60f','94e6ee5f-98d5-40d3-9985-b51cb6a73b8f',1938,'抗战期间任伪长垣县县长','抗战期间任伪长垣县县长，长垣与濮阳接壤，其伪政权为日军征集物资，协助日军封锁抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f70b6840a360492d9f252355f4631ef1','50430d6d-d880-41dc-9170-c6ed434a9ad2',1940,'河南巩县人','河南巩县人，抗战期间投敌，在豫北组织伪军，曾任伪暂编第六军军长，配合日军在濮阳、清丰、南乐一带进行扫荡和清乡，是冀鲁豫边区日伪统治的重要帮凶。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc0389868684488cad875bea8b7a9823','f5fb7b4b-a177-4023-8c09-3ad00adb38c6',1938,'河南安阳人','河南安阳人，抗战期间投靠日军，组织伪保安队，控制安阳、汤阴、内黄、濮阳一带，配合日军对冀鲁豫抗日根据地进行蚕食和扫荡，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e83219eb660a4abe8cb8ee1137f6d796','1745e57b-f58c-44f3-acd3-b6c8b863c73a',1938,'河南安阳一带土匪武装头目','河南安阳一带土匪武装头目，抗战期间投敌，被日军委为伪豫北剿共军司令，活动于安阳、内黄、濮阳交界地区，配合日军进攻抗日根据地，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27f1e4fa150d4ee5ae9b22531f347141','e825b8b5-d534-4f2b-bef2-140b2896ebd1',1938,'南乐县本地人','南乐县本地人，日军侵占南乐后出面组织维持会，后任伪南乐县知事，协助日军征粮、派款、抓丁，推行保甲连坐，镇压抗日群众，是南乐地区直接为日军服务的伪政权头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa41e9e2078846aca1c0666542c9000e','e7f47651-220e-467c-824a-0d5797618067',1938,'清丰县本地士绅','清丰县本地士绅，日军占领清丰后投敌，组织维持会并任伪县知事，配合日军在清丰、南乐一带推行伪化统治，征发民夫、粮食，协助日军扫荡抗日根据地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de18e0186ec14fa58514476fd1298c49','1065a47d-edf3-41d1-9d11-192b415655b6',1938,'濮阳县人','濮阳县人，日军侵占濮阳后出面组织维持会，后任伪濮阳县知事，协助日军建立伪政权、伪保甲，征粮派款，配合日军对冀鲁豫边区进行经济封锁和军事扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54ec6af358964c489b4a1840c5665f19','2380bf6f-9e92-4cc7-a312-e25c492ddfdf',1938,'抗战期间投敌','抗战期间投敌，曾任伪冀南道道尹，管辖包括濮阳、南乐、清丰在内的冀南豫北地区，推行日军殖民统治政策，组织伪军伪警，配合日军扫荡抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ecc0d663b81b46adb3dc4d1d1bc4b66e','7a251f29-f23a-4cf6-ae61-1ade47e7bff2',1938,'河南人','河南人，抗战期间投敌，任伪豫北道道尹，管辖豫北包括濮阳、南乐在内的地区，协助日军推行伪化统治，征发物资，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce1e995f54084f19b474aafc0d7b9735','169590bc-4fe9-4609-8f9b-a06accd99ea2',1938,'抗战期间投敌','抗战期间投敌，在伪河南省政府中负责警务和保安，建立伪警察和伪保安队体系，其势力延伸至豫北濮阳、南乐一带，配合日军进行清乡、扫荡和情报搜集。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-426f54f43a4c455a846de889faa93685','32eeaa6e-b0f2-4a7f-8a8f-3252f7aeec09',1939,'活动于冀鲁豫交界地区','活动于冀鲁豫交界地区，投靠日军后组织伪保安团，配合日军在濮阳、南乐、清丰一带进行扫荡，袭击抗日武装，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3a99cc9d6d44ce3945ebe87382f77d4','46daf75c-091b-46cf-ba93-ede962edb09b',1938,'河南安阳一带土匪头目','河南安阳一带土匪头目，投敌后任伪豫北剿共军副司令，活动于安阳、内黄、濮阳交界地带，配合日军进攻冀鲁豫抗日根据地，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc1c5126e94640a79acf7513c0b9d427','fb319d6b-afc3-4fb9-b1f0-c64d1c98607d',1938,'河南濮阳人','河南濮阳人，抗战初期即投靠日军，在濮阳、清丰、南乐一带组织伪军，任伪暂编第六军军长，后任伪豫北绥靖公署主任，长期控制濮阳地区，配合日军扫荡冀鲁豫边区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-586412a190bd4191b33eef4ae504d870','5de27d25-5932-4872-8441-8c8b79d26bdc',1938,'濮阳本地士绅','濮阳本地士绅，1938年日军占领濮阳后出面组织维持会，任会长，后任伪濮阳县县长，协助日军征粮、派夫、建立保甲制度，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3dc466c67c5e4fa9943da4d3614ccaee','c0fdf791-6975-478f-9fe8-e5aac138b607',1938,'清丰县士绅','清丰县士绅，日军占领清丰后组织维持会，任会长，后任伪县长，在清丰、濮阳交界地区推行伪化统治，为日军筹集物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce13e5e2c6024efebfa40337d4de8e99','05fcd24e-2280-4af5-a45f-64f878ce0511',1938,'南乐县人','南乐县人，抗战期间投敌，任伪南乐县维持会会长、县长，在南乐、台前一带建立伪政权，配合日军扫荡冀鲁豫根据地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c2bb9bba54445c483507727c4c2c432','22ed279e-0690-4d7f-bae9-f5cf5e0f49f7',1939,'范县（今属濮阳）人','范县（今属濮阳）人，日军占领范县后组织维持会，任会长，协助日军在范县、台前一带建立伪秩序，征发民夫、粮食。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70524bbbbd2d4303b3c6e10280b19e94','ad5aa5e4-f8e1-40e5-9c91-512e939a07b5',1939,'寿张县（今属濮阳台前一带）人','寿张县（今属濮阳台前一带）人，抗战期间投敌，任伪寿张县维持会会长、县长，在寿张、台前地区为日军维持统治，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de8ac86449b6482e90e685137eeb0134','29e1442b-037c-428c-9316-d75fb05f1341',1939,'东明县（今属濮阳）人','东明县（今属濮阳）人，日军占领东明后组织维持会，任会长，配合日军在濮阳南部、东明一带推行伪化政策。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0bea6143e6544ccc94d8520998b38b07','f6c91bb4-ecda-4882-bdf1-00408bede85f',1938,'河南人','河南人，抗战期间在伪河南省政府任职，任警务厅厅长，负责伪警察系统，在河南各地包括濮阳地区建立伪警察网络，镇压抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd440a3dd6ef40f98cf3b20bb59537e5','1880ad0b-3dd6-452f-94de-4102d8f08967',1939,'濮阳人','濮阳人，抗战期间任伪濮阳县警察局局长，带领伪警察配合日军搜捕抗日人员，镇压濮阳、台前一带抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0bd1024143724eb9a5a7813af8cd6893','25796178-3cdd-4f6f-b403-ec7d6dd214b3',1939,'清丰人','清丰人，抗战期间投敌，任伪清丰县保安团团长，在清丰、濮阳交界地区配合日军扫荡，捕杀抗日干部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db24862d48de4a28928d254670c931e6','1a74ce6f-ff46-4c3a-a51b-9f9b969b8ee7',1940,'河南濮阳人','河南濮阳人，抗战期间在豫北组织伪军，驻防濮阳、清丰、南乐一带，配合日军扫荡冀鲁豫边区，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9a66916b2ef4607a44f89148f910413','0f7a0368-d856-427f-bd33-97881d9836aa',1938,'清丰县本地士绅','清丰县本地士绅，日军占领清丰后出面组织维持会，后任伪县长，为日军征粮派款、搜集情报，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce81b8a1afbd42228821987b322d7428','fc7da6f1-b83f-4d36-8901-af38e9a7c670',1938,'原国民党河北民军首领','原国民党河北民军首领，在豫北、冀南一带活动，后与日军勾结，其部在濮阳、清丰周边地区制造摩擦，袭击八路军和地方抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1102ded62b82489e9eb6203e7a0adce7','6181d5df-2f37-453e-b50c-542c0f153be2',1938,'山东巨野人','山东巨野人，伪军在鲁西、豫北交界地区活动，曾配合日军扫荡濮阳、清丰一带抗日根据地，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0310ca2de9404637a5f925fc264c8abc','593a6f30-b771-409d-9d0d-e00104c21b6c',1940,'清丰县伪警察头目','清丰县伪警察头目，带领伪警察配合日军搜捕抗日人员，勒索百姓，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-40422bb9ae52475584a06cd7ef6d9910','aa3f00d0-19ba-44cd-8408-2cb5bf90c6c7',1939,'濮阳县本地人','濮阳县本地人，组织伪保安团，配合日军驻濮阳部队扫荡周边村庄，抓捕抗日干部和群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24984d6814064ee29af2b9572df1a27a','fc3553f3-8951-4f80-982c-2c940547d924',1938,'日军侵占清丰后出任伪知事','日军侵占清丰后出任伪知事，推行保甲连坐，强征民夫、粮食供给日军，破坏中共地下组织，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-678ab185320346abade5efb124b62b72','d9bc431a-11fa-47ec-9e93-362b24e86021',1937,'原为国民党地方实力派','原为国民党地方实力派，在濮阳一带活动，后与日军勾结，接受伪职，配合日军进攻冀鲁豫抗日根据地，1943年后公开投敌。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ec47b7f24ee4fa380e53626e798600f','5ec9500d-caa1-474b-a260-c5b08801d896',1940,'在豫北南乐、清丰、濮阳一带收编土匪武装','在豫北南乐、清丰、濮阳一带收编土匪武装，投靠日军，任伪东亚同盟自治军军长，配合日军扫荡，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-972a85ed678448f49563113f9d36f80b','1cc03882-3677-4790-9d80-9f247c974579',1938,'日军侵占濮县后出任伪知事','日军侵占濮县后出任伪知事，建立伪政权，推行奴化教育，强征粮食、物资，协助日军镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7515939bb1e64960a16031f04ae87f97','740e54e6-bdc7-4bd6-8325-cd9d2fcc86bc',1938,'在伪河南省政府任职','在伪河南省政府任职，管辖豫北道，包括濮阳地区，推行日军殖民统治政策，征发民力物力，镇压抗日运动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b42d558acbb4dd8ac3ae941ad646876','73b0cf2c-b05a-4ef0-81c5-8e9a2b306b75',1938,'在伪河南省政府任职期间','在伪河南省政府任职期间，协助日军维持治安，镇压抗日活动，其警务系统延伸至濮阳等豫北地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89f3dc452fe14ff39bd9379eac3eb582','73b0cf2c-b05a-4ef0-81c5-8e9a2b306b75',1938,'在伪河南省政府中历任警务厅长、开封市市长等职','在伪河南省政府中历任警务厅长、开封市市长等职，负责伪警察系统，镇压抗日活动，其警务体系延伸至郑州地区。','危害等级B（乙级，市县厅局级）','hanjian');
