INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e3d06c62d684ee1af5348542fbc68bf','da5bb9ff-5abf-48fb-857b-69d91b889165',1940,'伪冀南道管辖包括濮阳在内的豫北地区','伪冀南道管辖包括濮阳在内的豫北地区，杨法贤任道尹期间推行日军政策，征粮征兵，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71c8b154953f45dc9099119263c3697c','09de860e-0be5-4436-9bca-aae551da8070',1940,'在濮阳地区担任伪警察局长','在濮阳地区担任伪警察局长，负责侦缉抗日人员，配合日军进行治安强化运动，活动范围覆盖濮阳经开区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb9dcef746984140937fa9188abb5240','0006f466-bd2d-479d-b938-314d39ae31f4',1939,'在濮阳推行奴化教育','在濮阳推行奴化教育，编写亲日教材，组织学生参加日军宣传活动，为日军殖民统治培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5f812e508e849ef97d83d7b199c3aea','5aa43984-0514-4e89-87e4-c3bfc94e46a4',1938,'河南濮阳人','河南濮阳人，抗战期间在濮阳、清丰、南乐一带组织伪军，任伪豫北保安司令等职，配合日军扫荡冀鲁豫边区。','危害等级B（乙级，市县厅局级）','hanjian');
