INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11e586a8282647df9f674ca9a8c7c2ad','cec330a1-6035-4fde-b59e-ad428c753d63',1939,'任伪郑县警察局局长','任伪郑县警察局局长，协助日军维持郑州城区治安，搜捕抗日人员，镇压民众反抗，是郑州沦陷区伪警察系统的头目之一。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c794891dfb54f53a3746f28c24ad1bd','ec3fa7db-4565-4206-82bc-ac5d23ec24f9',1938,'抗战期间任伪郑州商会会长','抗战期间任伪郑州商会会长，协助日军征购物资、摊派款项，控制郑州商业，为日伪经济掠夺服务。','危害等级C（丙级，基层头目）','hanjian');
