INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c021a79f33044698036ce8cede03b17','8c54d585-c036-4141-9767-8eb452d4cd94',1938,'在郑州组织伪新民会','在郑州组织伪新民会，进行亲日宣传，推行奴化教育，协助日军控制民众思想，是郑州地区文化教育领域附逆者之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
