INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7914c5a160cc4f65b602f4c29216de86','3ec04a90-305e-4676-833a-24339c334a14',1944,'原国民党河南省主席','原国民党河南省主席，1944年投敌，任伪河南省政府委员，协助日军维持河南伪统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ea3d51bf7074293ab0e8c675aacc4a2','44cb0fce-820a-4f95-bc93-b3851cab3ca1',1938,'抗战期间在豫南地区附逆','抗战期间在豫南地区附逆，任伪豫南道尹，管辖信阳、驻马店、确山、新蔡等县伪政权事务，协助日军维持占领区秩序、搜刮物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f9fc662f8cf49ab91e2f1e92402d37b','324ab578-ac2c-4a6f-ac64-cc5d5f18f6cb',1938,'新蔡本地士绅','新蔡本地士绅，日军侵占新蔡期间出面组织维持会，后任伪县长，为日军征粮派款、维持地方伪秩序，是新蔡地区直接附逆的代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d682a086d3784104b46fe99b9dad3d96','0de2007f-2346-4f6d-8d0e-6e8df8a01905',1938,'驻马店镇本地商人','驻马店镇本地商人，日军占领驻马店后组织维持会，协助日军管理车站、码头及物资转运，为日军提供情报和后勤支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
