INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-534b2cdda5e344f7bc4fa3cd01ae45cd','9034f4b2-1dec-4de8-ad7c-c8cdb09a638f',1938,'上蔡县附逆士绅','上蔡县附逆士绅，任伪维持会会长及伪县长，管辖上蔡及邻近新蔡部分地区，为日军征粮征丁、维持伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
