INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-296edcd3555441a898e45153ab415c1a','01d2501f-e0d1-4fc4-ad8e-bfb3d778332d',1938,'抗战期间投敌','抗战期间投敌，曾任伪豫南道尹，管辖驻马店、泌阳、确山、遂平等县，在泌阳推行伪化教育、征粮征夫，配合日军扫荡豫南抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e0603adb5af424c9dee34d00ea44930','e5f4a4cd-e401-4e58-94fd-69a154652f92',1938,'泌阳本地士绅','泌阳本地士绅，日军占领泌阳后出面组织维持会，任伪县知事，协助日军征粮、征夫、建立伪保甲，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3b976b2fc134fea9f76f828703d0782','81e1cc62-68b2-4963-b543-3e452cc524e7',1938,'驻马店镇商人','驻马店镇商人，日军侵占驻马店后组织维持会，任会长，为日军筹集物资、情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-956d90280fdd4426b9232df0418dca0b','81e1cc62-68b2-4963-b543-3e452cc524e7',1938,'驻马店镇人','驻马店镇人，日军占领驻马店后组织维持会，为日军筹集物资、招募伪职人员，协助日军管理驻马店城区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27f7fca8217a40c794bb1c0cef1b6162','187e6a51-a62b-46ad-aa8a-bbaae956cf65',1938,'抗战期间投敌','抗战期间投敌，任伪确山县知事，后升任伪豫南道公署科长，管辖范围包括泌阳，协助日军推行保甲连坐、征粮。','危害等级C（丙级，基层头目）','hanjian');
