INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3e566bf09ee48b0b7925f0c7c8c4cbc','a33170cf-93de-4c35-b81c-0f16f6f0c82c',1943,'原国民党军官','原国民党军官，投敌后任伪第四方面军师长，活动于豫南驻马店、信阳地区，协助日军维持占领区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-646a415420364e58865f719a02d0bac5','8a998e69-6680-4b1d-b801-0cdbca17a28f',1942,'孙良诚部伪军参谋长','孙良诚部伪军参谋长，参与指挥伪军在豫南驻马店、泌阳一带的扫荡与征粮行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ca05a5818214b4f8e5f58848a80691d','aba70564-d2db-4967-9a2d-e3fe47e5343a',1939,'泌阳本地人','泌阳本地人，投敌后任伪警察局局长，协助日军搜捕抗日人员，镇压群众，推行伪化治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe7ad575a775409d8985fc5f045cf513','845a6ec9-29aa-480d-bd1f-0795b73cd55b',1938,'抗战期间投敌','抗战期间投敌，任伪遂平县知事，后任伪豫南道参事，管辖范围邻近泌阳，协助日军征粮征夫。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b1ab501f5dc4b10af5e44b0ed2653ac','3579ed71-97cc-4bb6-8a07-55493c428c24',1939,'泌阳本地武装头目','泌阳本地武装头目，投敌后任伪保安团团长，配合日军进攻泌阳抗日根据地，捕杀抗日干部和群众。','危害等级C（丙级，基层头目）','hanjian');
