INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10664c6ca5694193b44b5ba3c06777e7','9d7fc119-3b48-4669-a032-a594ba0339da',1944,'组织伪乡镇武装','组织伪乡镇武装，强迫青壮年参加伪军，破坏抗日地下组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abcaa6a3be6745ada190ad7e3b7814ca','1ea264c0-a315-434c-8ecf-85771a167b5c',1941,'任汪伪玉环县县长','任汪伪玉环县县长，协助日军征粮、拉夫，镇压抗日民众，推行保甲制度，搜捕抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b44606d5061454f9efabc45f07d107c','2dee2964-01b5-4c0d-9c3e-fab6749e13b7',1942,'率伪军配合日军扫荡楚门、坎门等地','率伪军配合日军扫荡楚门、坎门等地，杀害抗日游击队队员，抢劫民财，破坏地下交通站。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56c8d2adb0b644e598df04ce0317154b','bc3c6df7-2a53-4702-90a8-66c024c02fa9',1943,'为日军提供情报','为日军提供情报，逮捕并刑讯抗日群众，参与“清乡”行动，导致多名地下党员牺牲。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03284b390f144812968e5e602cf61de3','7e3a1c65-980f-4943-94c0-266d773a4b61',1941,'为日军和伪政权强征苛捐杂税','为日军和伪政权强征苛捐杂税，侵吞抗日救国捐款，协助日军掠夺粮食和铜铁等战略物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c16b2a4dd0f4014ad879fccc3192ace','a3da0754-10ce-42bd-bb4a-29e31d847712',1942,'推行奴化教育','推行奴化教育，强制学校使用日伪教材，宣扬“大东亚共荣”，迫害爱国教师。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc0778f76b3e446e8366a8d51953e716','7b3e0f37-4080-444b-927d-59362dac1392',1943,'为日军在玉环沿海设立情报点','为日军在玉环沿海设立情报点，破坏抗日武装的物资运输，参与诱降抗日游击队成员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-736f08ee326e4d799aa8c9ff395a2d6e','a1187e5b-a988-411f-821f-e5380a79ce8b',1944,'组织“慰劳”日军活动','组织“慰劳”日军活动，为日军提供妇女名单，协助日军强征民夫，破坏抗日妇救会组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3e71f0092ca463ea088e885e10c1b9c','b9a5d504-7f2c-489a-9906-557fdb9513e3',1941,'在楚门镇为日军征粮、派款','在楚门镇为日军征粮、派款，告密导致抗日交通员被捕，协助日军烧毁民房。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f0f20e7b08648219fea9809b467cb25','ca4a3493-0fd2-4e92-b819-d7657f3ac8f3',1942,'控制坎门渔港','控制坎门渔港，为日军提供渔船和渔民情报，强迫渔民为日军运输物资，克扣渔民口粮。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12cd0fe801df42f593a1582e43eac21c','733d20ff-29d5-4b8d-9fd2-21c95d441495',1943,'负责为日军征收军粮','负责为日军征收军粮，虚报产量，强抢农民稻谷，导致多地饥荒，民怨极大。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0cbc6d2bd7d40bfa58110aff74e33ea','4d7407fd-9929-455e-be0f-f32338273225',1938,'抗战期间投靠日军','抗战期间投靠日军，在黄岩组织伪维持会，后任伪黄岩县县长，协助日军征粮、派款、维持占领区秩序，镇压抗日活动。黄岩与路桥地域相邻，其伪政权活动覆盖今台州路桥一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f77e1f788e5c449b8083a74832cf3322','02f2103d-4c69-4b24-958b-72f60f08ecbe',1941,'日军侵占温岭后出面组织伪维持会','日军侵占温岭后出面组织伪维持会，任伪县长，为日军筹粮筹款、拉夫，配合日伪清乡，镇压当地抗日力量。温岭属台州，与路桥同处台州湾南岸。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eccfe5aec7ca4451b59cf12ffd903c6f','1486b81e-dcc0-418c-aef7-62f113c015d8',1941,'临海沦陷期间投敌','临海沦陷期间投敌，组织伪维持会，替日军维持地方秩序、征发物资，并诱迫地方士绅附逆。临海为台州旧府治，对路桥一带具有行政影响。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b2c0663f6714794a35fb3afa8c8cfaf','836ea37e-43d7-4248-9c72-d9e68a1c4a53',1942,'抗战后期在台州沿海收编土匪、散兵','抗战后期在台州沿海收编土匪、散兵，组成伪军配合日军守备与扫荡，活动于黄岩、温岭、路桥沿海一带，劫掠民财、袭击抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdac87cbb50f47f6b486f87131e18164','6efd2f6e-ae5c-4c2f-866d-eaa0f3586d8d',1941,'海门（今台州椒江）沦陷后组织伪维持会','海门（今台州椒江）沦陷后组织伪维持会，任会长，协助日军控制台州湾口岸，检查来往船只、征收捐税，并迫害抗日人员。海门与路桥同属台州沿海要地。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8577dd0988424272b0973f04421bee8d','d55dacea-d2f5-4016-8fe0-89428310b121',1941,'在伪黄岩县政权中任伪警察局长','在伪黄岩县政权中任伪警察局长，带领伪警察配合日军搜捕抗日志士、清查户口、推行保甲连坐，直接服务于日伪在黄岩、路桥地区的统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7edde5f9fa5944bcabd75c42094c87b7','010ce7a4-05da-4319-834c-59086d6104ba',1942,'受伪政权委派在台州沿海乡镇推行保甲制度','受伪政权委派在台州沿海乡镇推行保甲制度，训练伪保甲长，为日军征粮、征夫、搜集情报，活动范围包括黄岩、路桥、温岭一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-627b12a78cbf42d99dd5b0eec8532315','3eda0010-db9e-4cf0-b0a6-f9bfacb57995',1942,'在伪温岭县政权中主管教育','在伪温岭县政权中主管教育，推行奴化教育，篡改教材，强迫学校悬挂日伪旗帜、教授日语，毒化台州沦陷区青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9079ebbb909843e9a2280930a04fcd4c','dc6f7ecd-0215-477c-83c5-3123cdef9d76',1941,'黄岩沦陷后出面组织伪商会','黄岩沦陷后出面组织伪商会，为日军筹办军需物资，强制商户摊派捐款，并协助日伪实行经济统制，盘剥路桥、黄岩一带商民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6f3f64a4eb249319cebd16f0c6becc7','a00d6dba-042d-4fe1-9b52-8ee358a37d1a',1943,'抗战后期在浙江伪绥靖军系统任职','抗战后期在浙江伪绥靖军系统任职，负责台州地区伪军编练与作战，配合日军对台州沿海抗日根据地扫荡，其部队活动于黄岩、路桥、温岭等地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-786bceb6408e4d4581c15b8033aec119','d089944d-b496-4231-a47b-f62d0313ff69',1941,'路桥沦陷期间出面组织伪维持会','路桥沦陷期间出面组织伪维持会，任会长，为日军派粮派款、维持市面，并协助日伪建立基层伪政权，是路桥当地直接附逆的代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c17e532410249fdad6a3dd7566c6b5d','5291b98d-b4cb-427f-aff7-dd71df8793c1',1942,'控制台州湾沿海航运','控制台州湾沿海航运，为日军运输物资、搜集沿海情报，协助日伪封锁抗日根据地海上通道，活动涉及海门、路桥、温岭沿海。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b862a2455e5c459e9e582a1dcd64e320','6417517f-8542-4dd8-a41e-2a62ecd938b2',1940,'任汪伪黄岩县县长','任汪伪黄岩县县长，协助日军征粮、推行保甲制度，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
