INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2881f7754a0f4e598da5e0d6dc500e76','64298b7b-ae30-436a-90ac-841ce88bd770',1941,'率伪军参与“清乡”行动','率伪军参与“清乡”行动，在嘉兴、海宁交界处多次袭击抗日游击队，杀害多名抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1916849ebec94de6b65ebe3b04841616','94d47c12-3852-48a3-a382-a37053a0c5c7',1938,'协助日军建立海宁伪政权','协助日军建立海宁伪政权，负责征粮派款，并告密导致多名抗日分子被捕牺牲。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22bb0a24b50f49fcb79be0f0615b6d53','dbe95c11-f918-4277-8000-8d6d1d0094f3',1942,'投靠日伪特务机关','投靠日伪特务机关，在嘉兴、海宁一带发展情报网，破坏地下抗日组织，逮捕并酷刑审讯爱国人士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5678426f72ba4342a18f755fcaa2536e','9e9d8773-2f1c-4e61-a786-29be99cacb58',1940,'控制海宁内河水道','控制海宁内河水道，为日军运输军需物资，并拦截抗日武装的物资运输，勒索船户。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ddf959ddcc494133a9757dede158339d','e8aa340d-2954-47bc-a433-63c6aafdf52e',1938,'投靠日军','投靠日军，任海盐县维持会会长及伪县长，协助日军征粮、拉夫，镇压抗日民众，曾指使汉奸队袭击新四军游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbc315733cab4bdaa69fa8b65717fa06','ba184791-96c7-45b1-9cb4-750de47b4d58',1940,'组织伪保安队','组织伪保安队，配合日军扫荡海盐乡村，抓捕抗日人士并严刑拷打，抢夺百姓财物，民愤极大。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df32f569dc8240be9497670f68e47190','9f718141-f6fa-4ae8-8ed1-5499d25f6465',1939,'为日军控制嘉兴经济','为日军控制嘉兴经济，强迫商户缴纳“慰劳金”，垄断粮食和棉布贸易，资助日伪军需，并出卖抗日商人情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57cd4874e17f481f8a7714e4fc825882','ac86fb51-90d5-4a81-bb37-e85e6c803be0',1941,'专门侦缉抗日地下组织','专门侦缉抗日地下组织，多次带队抓捕共产党员和爱国学生，酷刑逼供，导致多人牺牲。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a47a5fcb54cc4bfabe683721f80c5fd4','b6ad3ee2-65e1-4624-b88b-38a91adaa0a7',1942,'为日军强征田赋和苛捐杂税','为日军强征田赋和苛捐杂税，逼死多名农民，并贪污税款，中饱私囊，协助日军掠夺海盐资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-634a25fd78ec4d688da50c65334f536f','a6c35825-c0cc-4cdf-a0c0-8a19de853129',1938,'日军占领嘉兴初期','日军占领嘉兴初期，主动投靠，组织维持会为日军带路、搜刮民财，并强迫青年加入伪军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a62f0ad008a41b9be5a527e03d8b165','819d898f-7548-441d-8ea6-891bed1ee468',1943,'建立汉奸情报网','建立汉奸情报网，向日军报告新四军和国民党游击队活动地点，导致多次袭击和村民伤亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41cb2b9f825c48e2beeabcff1ae84f0d','a8fdb301-4e09-4a2b-8e76-0d7a80e87b1e',1940,'率伪自卫团协助日军“清乡”','率伪自卫团协助日军“清乡”，焚烧村庄，杀害抗日家属，并强征壮丁补充伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fa64b4a64e44db8a0005152aefdd1aa','859ca052-2f1c-49cb-b3f0-a42e674807af',1941,'推行奴化教育','推行奴化教育，强迫学校使用日伪教材，宣扬“大东亚共荣”，并告发拒绝合作的教师。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c86829b2a1654ae0a97f2960408e2489','dc3ace8b-c449-4bea-bfb6-4de6f3edfc8a',1942,'控制嘉兴至海盐水路','控制嘉兴至海盐水路，拦截商船，勒索船户，为日军运输军火，并搜捕水上抗日交通员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c11a2dfadfcf49c8b1881302b7f9e51d','5c465d5f-a4bc-4a4b-bc05-eeb7867e5738',1943,'垄断海盐粮食收购','垄断海盐粮食收购，压低粮价，导致饥荒，将大批粮食运往日军据点，饿死百姓无数。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-858935ae3fcb4fcd9eeeaf755416ca55','edc325d2-2465-404b-a04a-7c5436c7e4a8',1940,'审判抗日人士时','审判抗日人士时，按日军授意判处重刑或死刑，伪造罪名，破坏司法，助纣为虐。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae71d84217ee48dbac659371756166df','350a23e9-a84e-4006-b860-fab63db7083f',1938,'任伪嘉兴县知事期间','任伪嘉兴县知事期间，协助日军推行‘清乡’政策，强征民夫，搜刮粮食，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9851c85c6f64177b0ab0ad8d59838fe','93587353-fdc1-468d-ba55-523369d7bd75',1939,'率伪保安队配合日军扫荡秀洲区抗日游击区','率伪保安队配合日军扫荡秀洲区抗日游击区，杀害多名抗日军民，并参与诱捕地下党员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23bd610c595143cabbe5215109042334','8b5cfeed-5603-4085-9d1f-2309d3a94c84',1938,'组织维持会为日军提供粮秣情报','组织维持会为日军提供粮秣情报，强迫商户悬挂伪旗，并举报抗日积极分子，致多人被捕。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59ffb470091a42c3b224b7c61db9d9b7','4c0b5297-6914-49f3-b77e-1f569444ec1f',1940,'虽主要活动于上海','虽主要活动于上海，但曾派特务至嘉兴秀洲地区破坏抗日组织，逮捕并杀害数名地下工作者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-129f7191645740a2842d9341accac393','518e93bc-39ac-4e85-a073-0625a32b27f0',1941,'专门侦缉抗日分子','专门侦缉抗日分子，在秀洲区设立密探网，多次带队抓捕进步学生和游击队员，酷刑逼供。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7137e8a103f4573ab92178c894cbd23','f5179831-e349-4cab-a629-20ccd54f3228',1942,'率自卫团协助日军修筑碉堡','率自卫团协助日军修筑碉堡，封锁交通，并参与‘清乡’行动，抢劫民财，强奸妇女，民愤极大。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-525edcaa4b914ffdb4572f210f6e6c91','8c30ff8c-13ae-440e-8224-c2cbcca592b0',1939,'为日军统制物资','为日军统制物资，强征桐油、棉布等战略物资，从中牟利，并资助伪政权活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eed15edda09847d98166360bc4d61042','fef17ed2-18e2-4b1b-9550-d48ee536d845',1940,'专门刺探新四军浙东游击队活动情报','专门刺探新四军浙东游击队活动情报，多次引导日军突袭，导致秀洲区多个联络点被破坏。','危害等级C（丙级，基层头目）','hanjian');
