INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33148a3521214a05a95a21905a49e9fc','a7364b89-02b8-4dc4-99f2-10879be39ff8',1941,'充当日军经济掠夺代理人','充当日军经济掠夺代理人，控制宁波商会，为日军统制棉布、煤油等物资，从中牟利。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3eac9cd3c9b49d0b90cec8233ba403f','a7364b89-02b8-4dc4-99f2-10879be39ff8',1941,'原为宁波商界头目','原为宁波商界头目，投日后控制商会，为日军筹措军饷，强迫商户缴纳“献金”。','危害等级C（丙级，基层头目）','hanjian');
