INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15942c6502804e8e8cb62e21536a85c5','f891f2bd-4b63-4a7d-ac01-b7964d8c4770',1941,'效忠日军','效忠日军，指挥伪警察搜捕抗日地下人员，破坏中共宁波地下组织，罪行累累。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c39e3743ce1a4192bb9a21eae3ebae42','a760e91b-b4aa-4a21-8ab4-dc045ad698e8',1941,'为日军征收苛捐杂税','为日军征收苛捐杂税，强征田赋，导致宁波百姓负担沉重，部分款项用于伪军军费。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81de467e4b6c433a9f3d7788f84876f5','0221efc6-c348-494d-bdbc-76c3957b8ca8',1940,'早年留学日本','早年留学日本，投敌后任伪浙江省长，推行奴化教育，配合日军“清乡”，后调任伪粮食部长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
