INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6298220c84b4f17a4de3d40aac9cdcf','3f1a6960-b5e1-4dae-8c74-4813bb37125e',1939,'76号特工头目','76号特工头目，虽主要活动于上海江苏，但曾派特工渗透宁波，暗杀抗日人士，并控制宁波帮商界。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
