INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c75d2c6c76df4d20ae5d710838dcb7a6','baf2ab53-3786-4890-9256-d370fb417e88',1938,'浙江镇海人','浙江镇海人，曾任伪维新政府首脑，后任伪上海市长，积极推行日伪统治，镇压抗日活动，1940年被军统刺杀于上海寓所。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4aecbae1480d4db69ec7caf7b09469ec','baf2ab53-3786-4890-9256-d370fb417e88',1938,'原为上海商人','原为上海商人，投靠日本后任伪维新政府首脑，协助日军控制江浙沪地区，推行奴化政策，镇压抗日活动。其祖籍浙江镇海，但主要活动于上海，与杭州上城无直接关联，但因其浙江籍贯常被列入相关名单。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7345b89ebd154dd691812484b700eda5','baf2ab53-3786-4890-9256-d370fb417e88',1938,'浙江镇海人','浙江镇海人，曾任伪维新政府首脑，后任伪上海市长，积极推行日伪统治，镇压抗日活动。虽主要活动于上海，但原籍浙江，与杭州地区有联系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2e1325baa6b427fa88cb1abd83b7a21','baf2ab53-3786-4890-9256-d370fb417e88',1938,'原浙江镇海人','原浙江镇海人，投靠日本后任伪维新政府首脑，协助日军控制上海及江浙地区，征收苛税，镇压抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0b786ea266843ee8af6de90ff6435f2','baf2ab53-3786-4890-9256-d370fb417e88',1938,'浙江镇海人','浙江镇海人，曾任北洋政府高官，抗战期间投敌，任伪维新政府首脑，后任伪上海市长，积极推行日伪统治，1940年被军统刺杀。其活动虽以上海为主，但原籍浙江，且其势力曾渗透杭州、滨江地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e1ab6e70c264079ba90746d06978cd7','baf2ab53-3786-4890-9256-d370fb417e88',1938,'浙江镇海人','浙江镇海人，曾任伪维新政府首脑，后任伪上海市长，积极推行日伪统治，镇压抗日活动。虽主要活动于上海，但原籍浙江，与浙江有密切联系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f36793e3e68485596d2a34ee072ae59','baf2ab53-3786-4890-9256-d370fb417e88',1938,'原浙江镇海人','原浙江镇海人，投靠日本后任伪维新政府首脑，协助日军控制江浙沪地区，推行奴化政策，镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2dfafa828d5249e1b25594d2f0d6270f','ea5720ee-8406-4e4e-8842-3c90d5aad44a',1941,'宁波鄞县人','宁波鄞县人，日军占领宁波后投敌，任伪维持会会长，协助日军征粮、拉夫，迫害抗日军民，搜集情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1da6ed4d508a4a08aea25fb609ac2288','44a6d39f-7b7c-4801-91c4-395d6a234713',1942,'宁海本地人','宁海本地人，日军扶植下出任伪宁海县知事，推行保甲制度，强征壮丁，为日军提供物资，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7149e65add344933b7774cf5e19d4999','90636f59-d260-4a6e-99f5-662fed170d21',1942,'宁波人','宁波人，投靠日军后任伪保安司令，率伪军配合日军扫荡四明山抗日根据地，杀害多名游击队员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0baae2a7943741259b9e760f0103605a','020f0506-2bae-4605-a527-3dd93300a3c7',1943,'宁海籍','宁海籍，任伪浙东行政公署参议，参与策划“清乡”行动，协助日军在宁海、象山一带搜捕抗日分子。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccf84258cc274312932e84a4b6766043','7f26a0ce-2664-4630-bcc5-614e11c1e76f',1941,'在伪浙江省政府任职期间','在伪浙江省政府任职期间，直接参与对宁波、宁海地区的伪政权管理，协助日军掠夺粮食和战略物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-302736e49f7649e4b953d20c56d896b6','7f26a0ce-2664-4630-bcc5-614e11c1e76f',1941,'原国民党官员','原国民党官员，投日后任伪浙江省政府秘书长，协助省长处理政务，在桐庐地区推行伪化统治，强征壮丁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b85ad0714c74e7f811901ed039db2bf','60d9810d-f95c-42ae-8326-3151f92c6fc7',1942,'宁波人','宁波人，投敌后任伪警察局长，组织汉奸警察队，抓捕抗日群众，破坏地下交通站，罪行累累。','危害等级B（乙级，市县厅局级）','hanjian');
