INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cdb44d67d0142a4bf48aca20b1b3860','4e439d6e-e9c2-4dc2-b406-35396db0b278',1942,'任伪慈溪县知事期间','任伪慈溪县知事期间，配合日军清乡，强征民夫，搜刮物资，镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
