INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c11381ecf85741b3badb18f85c16f020','e4ac9e43-cf65-4fa2-aeb1-5f8f937223d4',1942,'为日伪政权强征苛捐杂税','为日伪政权强征苛捐杂税，盘剥江北商户与百姓，资助日军军费，民愤极大。','危害等级C（丙级，基层头目）','hanjian');
