INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1669015ec5a343068def41358247d5dc','fb1dd6e6-fcda-454e-97fe-8a7ae15d36b0',1942,'负责伪浙东地区警察事务','负责伪浙东地区警察事务，在宁波、海曙一带搜捕抗日志士，协助日军维持治安，实施“清乡”行动。','危害等级C（丙级，基层头目）','hanjian');
