INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf6ff3209cc54768b8c12b92ddd2ff09','4e62d3fa-5de1-4652-a36c-17430df66e37',1941,'原为金融业者','原为金融业者，投日后控制宁波金融，发行伪币，破坏法币流通，掠夺民间财富。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03b511712735465181615cc2954fecbb','7c22ca39-81af-470f-b96b-a970a0bddba2',1938,'曾任伪浙江省长','曾任伪浙江省长，在宁波、镇海等地推行保甲制度，强征粮食，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9e2be33047e435fb59d22b6274b4195','2a147732-52ea-421d-9f61-345f21eeed3e',1941,'负责宁波、镇海等县的伪行政事务','负责宁波、镇海等县的伪行政事务，推行“清乡”政策，逮捕抗日志士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-999e614532414df2996c0369b92f5cc9','98e4850f-5d60-4379-8712-c4bdca22d2d3',1940,'组织伪保安队','组织伪保安队，配合日军在镇海沿海巡逻，抓捕抗日游击队员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33e1b1f3ceed436b89f16ccf76aaa622','a5c1c3a4-afef-49a6-a493-5e17472196e8',1941,'为日军在宁波、镇海地区筹措军费','为日军在宁波、镇海地区筹措军费，强迫商户捐献，并垄断粮食贸易。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c86b056ed70043ad95a9d52abc11ab6b','91c8bc2d-59da-4fc9-af70-f448925e52b2',1940,'在宁波、镇海设立伪警察机构','在宁波、镇海设立伪警察机构，协助日军搜捕抗日地下党。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-691dc69519164c26b0b1f34402a21f97','ac36aed1-f0a0-4bcb-9d75-7f86d383cd4d',1942,'在镇海各乡镇推行保甲连坐','在镇海各乡镇推行保甲连坐，强征壮丁，为日军修建工事。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d623ddef29f41548a489181c76b6869','08d45c24-9766-41ca-bfe3-d6d762872d4a',1939,'宁波沦陷初期组织维持会','宁波沦陷初期组织维持会，为日军提供物资和情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4526d835f7e94dc39f45d77e87a2e3b8','ed633c0e-8921-473f-a140-d6d27c196632',1940,'指挥伪警察镇压镇海抗日示威','指挥伪警察镇压镇海抗日示威，逮捕并杀害多名爱国人士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1f4d313352e489083b432401fa8a4f6','6da3d34b-679a-4193-8016-450870ce498a',1941,'为日军宪兵队充当翻译','为日军宪兵队充当翻译，参与审讯和酷刑，迫害镇海、宁波地区抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9144d584d2fb471b9b20c282f6e19abc','d155d402-f256-412f-a0d4-003def192c22',1940,'浙江永嘉人','浙江永嘉人，曾任伪浙江省长，推行保甲制度，协助日军清乡，镇压抗日力量，1946年被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c696b13c7eaf44adb4e0f8bffaae5386','37d17338-e924-4375-b721-c906a343b2b8',1940,'浙江遂昌人','浙江遂昌人，汪伪特工总部“76号”实际负责人，在浙江杭州等地大肆捕杀抗日人士，1943年被日本毒杀。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00878d8d0031428aa50fc53a7827c9f7','a733b47e-2f41-4f0b-ab50-8ca5b60590f8',1940,'浙江鄞县人','浙江鄞县人，汪伪政权行政院秘书长，协助处理浙江事务，抗战胜利后被捕，1950年病死狱中。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-515343f8e06345d49eac9f8799fb4af7','833816f2-fc51-43f2-90d0-fc3c44ff7c5e',1938,'浙江杭州人','浙江杭州人，1938年任伪杭州市长，推行日伪统治，强征物资，镇压抗日活动，后调任伪浙江省政府委员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eecc48b255a64ee58265f075aa453704','25973176-8603-41b1-8916-32567406ce89',1941,'江苏武进人','江苏武进人，曾任伪杭州市长，协助日军管理杭州，实施经济统制，1946年被处决。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8fc13bd766a4b43bcb0b3296aa5c129','249023e6-bc85-4250-8c40-2a89e80772ea',1941,'浙江杭州人','浙江杭州人，曾任伪杭州市长，在任期间配合日军“清乡”，迫害抗日群众，抗战胜利后逃亡，后被逮捕处决。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2153bcff11754c32bda6f6f703fdacbd','249023e6-bc85-4250-8c40-2a89e80772ea',1941,'继任伪杭州市长','继任伪杭州市长，推行日伪经济统制，强征市民财产，协助日军在杭州设立特务机构。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10e8386fc3094c9083228081af63ceba','249023e6-bc85-4250-8c40-2a89e80772ea',1941,'浙江杭州人','浙江杭州人，日伪时期最后任伪杭州市长，在滨江地区推行“治安强化运动”，镇压抗日活动，强拆民房建碉堡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67da8b554c0442159133a1813182f464','428a98ea-8c56-4c96-9b02-a436ec14b820',1940,'浙江绍兴人','浙江绍兴人，任伪浙江省警务处长，指挥伪警察协助日军搜捕抗日分子，残害百姓，战后被镇压。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78f815d00e724d0ea014687722ec9e9a','2fc75140-56d3-4660-9d10-f96d5d66447f',1941,'浙江杭州人','浙江杭州人，任伪浙江省保安司令，率伪军参与“清乡”和扫荡，杀害抗日军民，战后被处决。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df54c51637454af39d89606ac6261023','dd40f41b-0057-478c-9842-9ad3e10c769e',1940,'浙江吴兴人','浙江吴兴人，任伪浙江省财政厅长，为日伪搜刮民财，征收苛捐杂税，战后被逮捕。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-593a1e08bda948338d56eb8ffde85e28','4ff8aafb-fe96-497a-ac72-bda1330fab9a',1937,'上海青帮头目','上海青帮头目，与杜月笙、黄金荣齐名。抗战初期投靠日本，曾参与策划在浙江杭州等地建立伪政权，为日军提供情报和镇压抗日力量。1940年被暗杀。其活动范围主要在沪杭一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a34c9e4cc0174f8eb59c968e54e6a30d','4e9467a5-5f51-4038-b59b-d401986df3c9',1938,'原国民党政客','原国民党政客，投日后任伪维新政府内政部长，后任伪浙江省长（但实际控制力弱）。在杭州地区推行日伪统治，协助日军清乡，迫害抗日志士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47e3726ada7a4c98a777e8db2b65abec','62a903f1-2584-426a-bcb1-bedf9a97e38a',1939,'原军统特务','原军统特务，投日后成为汪伪特工总部主任，在杭州、上城等地设立情报站，捕杀抗日地下人员，制造多起血案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7a0f9e3dbf04baaa5ac087133c8dc9e','f358b37a-4997-4852-aeb2-6528ce3888c0',1939,'与丁默邨共同主持76号','与丁默邨共同主持76号，在杭州及上城地区建立特务网络，残害抗日军民，后因内讧被日军毒杀。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15cab6e7ba8645c5b970cdda29bca76c','b590dc44-d319-41a5-b41e-cde7c77a1504',1940,'汪伪政权核心人物','汪伪政权核心人物，虽名义上兼任浙江省主席，但实际未常驻杭州，其政策影响浙江，包括上城地区，推行“和平救国”卖国路线。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4eb9fa1fe8a4089b2846dbe8bf6484e','e06ba0fc-a110-4e48-a34b-ed1be93c1461',1940,'汪伪政权骨干','汪伪政权骨干，任伪浙江省长期间，在杭州上城等地强化日伪统治，推行保甲制度，强征粮食，镇压抗日运动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0441f2e36b4a4377a13aeb8c4b943556','fb105cb0-c8be-44a2-8929-432714cd74ae',1941,'继梅思平后任伪浙江省长','继梅思平后任伪浙江省长，在杭州上城地区实施“清乡”政策，配合日军扫荡，迫害民众，搜刮物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9efc19b7dcaa4a7aa8f5a3346df3339c','b757133a-23d6-4461-832c-e6dbb58b19da',1944,'汪伪末期浙江省长','汪伪末期浙江省长，在杭州上城维持日伪统治，直至日本投降。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b48a954dcf69474b833e79f3d550c97c','52e3a508-fbd2-4141-bc35-d41130c11e9c',1938,'投日任伪杭州市长','投日任伪杭州市长，管辖上城等区域，推行奴化教育，协助日军维持治安，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4566ff38d1bb4ed3abd3a038cd737b29','95ba5fa9-2f15-4b02-a906-de21a925e302',1941,'继任伪杭州市长','继任伪杭州市长，在上城地区实施日伪法令，强征劳工，迫害抗日家属。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7082bee22d9842e4b22b776ccd439a9c','95ba5fa9-2f15-4b02-a906-de21a925e302',1941,'原国民党杭州地方官员','原国民党杭州地方官员，投日后任伪杭州市长，在桐庐地区组织伪警察，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86d2c05566324b08b95bb6c3f4129920','95ba5fa9-2f15-4b02-a906-de21a925e302',1941,'浙江萧山人','浙江萧山人，继徐苏中后任伪杭州市长，配合日军“治安强化运动”，实施保甲制度。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-437de7e8e32246b7b4e33850741f66f0','45bf970d-6a71-47d5-b48b-1a74da9218fd',1943,'末任伪杭州市长','末任伪杭州市长，在杭州上城继续为日军服务，直至投降。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d64b133446c64fb799c04e4f4b4e81c8','1b71be92-db58-4c2e-9edf-7fece42121c6',1937,'杭州沦陷初期','杭州沦陷初期，在上城地区组织维持会，为日军提供粮食、劳力和情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28f8248b31824209ac194cdb32d67e56','ab516473-33cc-416c-b846-a226255190ed',1938,'任伪上城区区长','任伪上城区区长，管理户籍，推行“良民证”，配合日军清乡，抓捕抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e30a8dffe5844e89173f732280b2cf1','a2081c49-8f85-46c2-a256-ed3d1e200ad3',1941,'继任伪上城区区长','继任伪上城区区长，强征捐税，为日军提供物资，镇压反日言论。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85d6ff52057f4575853ddfdf2887277b','3e5f4296-ebaf-4f79-8f02-f1042ca37f5e',1938,'负责上城区治安','负责上城区治安，协助日军和宪兵队搜捕抗日地下工作者，参与多起逮捕和刑讯。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93c3cb2ccf384d19a2d8968787bbf99b','2d97d354-8c4e-4c75-8acb-bfd43a96e749',1940,'负责上城地区绥靖事务','负责上城地区绥靖事务，组织汉奸武装，破坏抗日组织，向日军报告抗日动态。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfa610d4387748e4bdc1be9c1de7017b','ecb2aa52-1a5a-4ece-9042-9f50fd8e0a87',1938,'担任伪商会会长','担任伪商会会长，强迫商户向日军缴纳“慰劳金”，为日伪筹集军费，打压爱国商人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cd58525d4664c6c8838d5f7ecf3d5e6','1b22f380-c7c9-4604-b23b-802b6c7be404',1938,'推行奴化教育','推行奴化教育，在上城各中小学强制教授日语，篡改历史教材，灌输“中日亲善”思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-894dc6c3731848a68b8fb4cc28e082f8','75dbbcf9-316c-4829-82ba-961b54b66867',1940,'负责日伪宣传','负责日伪宣传，在上城地区张贴标语、发行汉奸报纸，美化侵略，污蔑抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8adf852100ea4167846ff5c69b3c75b6','3a1482d4-159e-40e4-8ead-c58ee94e40f3',1937,'浙江慈溪人','浙江慈溪人，青帮头目，抗战初期投敌，在杭州、上海等地为日军搜集情报，协助日伪镇压抗日力量，1940年被暗杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9667d8d64ae94d6ebd7eb1c8acb19f7e','3a1482d4-159e-40e4-8ead-c58ee94e40f3',1937,'浙江慈溪人','浙江慈溪人，上海青帮头目，抗战爆发后投靠日本，在杭州、滨江一带协助日军建立伪政权，贩卖鸦片、强征物资，1940年被军统刺杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f0c41dbe8b24b59b10460a8b02d7d8f','03b79eea-e000-41b8-82ce-5e99f7200cbb',1938,'福建长汀人','福建长汀人，曾任伪维新政府内政部长，后任伪浙江省长，在杭州推行奴化教育，强征物资，配合日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-273d4d6a9eb0402582f7ad10ff131ab9','03b79eea-e000-41b8-82ce-5e99f7200cbb',1938,'福建长汀人','福建长汀人，但长期在浙江活动，任伪浙江省长期间推行奴化教育，强征民夫，协助日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa34ef7c891346aca6307d4244b53ca8','03b79eea-e000-41b8-82ce-5e99f7200cbb',1938,'福建长汀人','福建长汀人，但长期在浙江任职，投日后任伪维新政府内政部长，后调任伪浙江省长，在杭州推行奴化教育，镇压抗日力量，强征粮食。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80d2a3abfc994ac1b149465c3c8b13a9','03b79eea-e000-41b8-82ce-5e99f7200cbb',1938,'原国民党官员','原国民党官员，投日后任伪浙江省长，在杭州推行保甲制度，强征壮丁，协助日军清乡，迫害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b40a0524e1f94b37a88a4c272b0852f9','84fe7b3b-daa9-471d-8328-ee21aa95a68b',1938,'安徽盱眙人','安徽盱眙人，曾任伪浙江省长兼伪杭州市长，在杭州实施保甲制度，强征粮食，镇压抗日民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe12f38528524f4d8c7a0f572ebb3c9e','2a736a2a-263e-4ed3-a069-06ed28d250de',1940,'浙江永嘉人','浙江永嘉人，汪伪政权核心成员，曾任伪浙江省长，在杭州推行“清乡”运动，残害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a82b204c8bf34673ade9c32b3c8ac159','d1356ca9-46fb-4e7b-9f32-4d1b149a46df',1943,'浙江杭州人','浙江杭州人，曾任伪浙江省保安司令，后任伪杭州市长，在临安等地组织伪军清剿抗日游击队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83015d0330af4423ab7d68fe2b01860c','61695641-fe9a-4b4b-822a-3867700e34ee',1940,'湖南常德人','湖南常德人，汪伪特工头目，曾任伪浙江省党部主任委员，在杭州、临安地区设立特务机构，逮捕杀害抗日志士。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d237e7b04b64b45963a6ab2886e88ec','61695641-fe9a-4b4b-822a-3867700e34ee',1940,'湖南常德人','湖南常德人，但曾在杭州、滨江地区主持日伪特工活动，建立“76号”分支机构，捕杀抗日志士，破坏地下组织。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f822b2248d74b9e8e67205274c1fece','61695641-fe9a-4b4b-822a-3867700e34ee',1940,'原军统特务','原军统特务，投日后在杭州建立伪特工组织，大肆搜捕抗日志士，制造多起血腥惨案。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1705f74a825a45408730be0a611b38f7','bcb7d457-4b04-4680-a1e8-c5430fa49143',1940,'湖南湘乡人','湖南湘乡人，曾任伪浙江省警务处长，在杭州、临安等地建立伪警察体系，协助日军搜捕抗日分子，实施“连坐”政策。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b2e55139808407789d3059848b61301','1d57f3c6-61b7-4947-bc56-498299070a28',1942,'浙江杭州人','浙江杭州人，曾任伪浙江省保安司令部参谋长，在临安、余杭等地指挥伪军“扫荡”，烧毁村庄，屠杀抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42360c5cae6447ccaa793bf3fab9f790','04eeae06-5dc9-422c-bef9-d238a7acc707',1937,'浙江杭州人','浙江杭州人，杭州沦陷后率先投敌，任伪杭州市维持会会长，为日军提供粮食和情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f01105afb51c4b7f938137458d7e3a17','a800d9cc-e20b-4ee9-86b0-40231d7c476b',1938,'浙江临安人','浙江临安人，曾任伪临安县长，在临安地区推行日伪统治，强征壮丁，搜刮民财，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98bbdd2053b44986b6872653ae38ccce','9bcd4b80-b956-48e9-8051-a5077a35c565',1941,'浙江绍兴人','浙江绍兴人，继任伪临安县长，在临安实施“清乡”，配合日军烧毁山区抗日据点，杀害多名抗日游击队员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e31122711d24313b9febe651962ba75','d8bc85e7-361a-4516-ad70-0e8f14634a55',1940,'浙江临安人','浙江临安人，任伪临安县保安大队长，多次率伪军袭击天目山一带的抗日游击队，抓捕并杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-caa148d44ef64c9c9fb981074bfc0aa3','c2483ba4-bd55-4960-a6ae-b5174267be03',1938,'浙江杭州人','浙江杭州人，任伪杭州市商会会长，为日军统购物资，垄断粮食、丝绸贸易，从中牟利，资助伪政权。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66ff9d831592464eb66f1fac7dbf6da5','5fd14030-ebb0-452d-8a01-c21f1b52c6f4',1940,'浙江杭州人','浙江杭州人，任伪浙江省教育厅长，在杭州、临安等地推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45e2ff4415e34d2884a949ee5a0d4882','4567a701-682e-4196-a438-ecc76546dc57',1940,'广东南海人','广东南海人，汪伪政权二号人物，多次到杭州、临安“视察”，推动日伪“治安强化”运动，间接指挥浙江汉奸活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10d2a69bf42e4f7686b3b939410fb576','c77df230-fd31-41d9-8687-e779a832b0ba',1938,'曾任北洋政府官员','曾任北洋政府官员，抗战爆发后投敌，1938年出任伪浙江省省长兼伪杭州市市长，积极推行日伪统治，镇压抗日活动，1940年被军统刺杀身亡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-954312babebb451390186f74bf09be6a','c77df230-fd31-41d9-8687-e779a832b0ba',1938,'原为上海总商会会长','原为上海总商会会长，投敌后任伪浙江省长兼杭州市长，推行日伪统治，镇压抗日活动，1940年被军统刺杀于上海寓所。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6790c3fc32fa4ca3936d39dd7c92bb16','dd9ccc43-6c2b-481d-b667-f5dde8342502',1940,'汪伪政权核心成员','汪伪政权核心成员，参与日伪谈判，1940年被任命为伪浙江省省长但未实际到任，后任伪实业部长等职，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b105ab59b97448209050c469e1a7b70b','83fe4513-9c6f-407c-82b2-8619b557c827',1941,'原国民党官员','原国民党官员，投敌后任伪浙江省省长，期间协助日军推行“清乡”运动，搜刮民财，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9fdd1520f96a44aaa8c5b86d5d69df49','3e773b04-4dc4-4508-81f1-e75008c0eba9',1945,'汪伪特工头目','汪伪特工头目，曾任伪浙江省省长（短暂兼任），此前主导“76号”特工总部，杀害大量抗日志士，战后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e269b782d1354a1997ff00232d8fa70f','aa95164d-3330-46f2-8536-8a7abdd12661',1938,'投敌后任伪杭州市市长','投敌后任伪杭州市市长，协助日军维持占领秩序，推行奴化教育，强征物资，压制市民反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b772c087dbf4049838abc3f05e55a7c','e2eb9716-1d7a-43b4-b7f8-b813929cbe18',1941,'继任伪杭州市市长','继任伪杭州市市长，期间参与日伪“治安强化”运动，协助日军抓捕抗日分子，实施保甲制度。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb0605359d0e4287b019e93354058e3a','943f8574-02a9-4c27-82d2-bd09e698afc5',1943,'汪伪政权任命','汪伪政权任命，任内配合日军进行物资统制，强征粮食，镇压学生和市民的抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0abb35a1368a4b3390950ad769211275','ecd459c1-ee0a-4934-8ce2-97fe8e4d43a3',1938,'投敌后任伪余杭县知事','投敌后任伪余杭县知事，协助日军建立伪政权，推行“良民证”制度，强征劳役，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7a1229ab2434957b2b308ac4bccaed9','6cf7a5d1-493e-48d3-9a36-b6ab31693b53',1940,'继任伪余杭县知事','继任伪余杭县知事，配合日军“扫荡”和“清乡”，组织伪保安队，搜捕抗日游击队成员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b08e9ea6dc224073995476c7ce2659bb','6951b9dd-e2f7-4725-9f8d-e2e18855680e',1942,'任内积极推行日伪经济统制','任内积极推行日伪经济统制，强征粮食和金属，破坏抗日根据地物资供应。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-940d78b4dbe3460db283174fb1da39bb','9e640a46-2fa8-41ba-a100-cf9c1f2fab2f',1944,'末任伪余杭县知事','末任伪余杭县知事，在抗战末期仍坚持效忠日伪，协助日军进行最后挣扎，战后被捕。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce7f29a55b5a4315b5cf7e4cfa2061bb','da931b66-db6c-449a-b011-f6fb69c2ad18',1940,'汪伪特工“76号”实际负责人','汪伪特工“76号”实际负责人，曾任伪浙江省警务处长，在浙江各地建立特务网络，残害抗日人士，后因内讧被毒杀。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6b79c191e3042629804766cc080e4c9','bd874366-a2f1-44e2-aa8a-73f920f2573a',1941,'汪伪政权要员','汪伪政权要员，任伪浙江省财政厅长期间，为日军搜刮财富，发行伪币，掠夺民间资产。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9150464018574a47b353d5ac44dbf919','0194655e-51f1-4e96-8615-08feaec3c776',1942,'原国民党军官投敌','原国民党军官投敌，任伪浙江省保安副司令，组织伪军配合日军“清剿”抗日武装，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1bbd047733b64c9bb5774742adf49286','06f7805e-fc31-41ef-ae79-a67f06daf89d',1938,'汪伪政权早期要员','汪伪政权早期要员，曾任伪浙江省教育厅长（兼），推行奴化教育，篡改历史教材，鼓吹“中日亲善”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4eff6da3a9a649f988ba71a1a4d60a31','cdfd38fb-4c5f-455e-ad17-19e816fde869',1937,'浙江慈溪人','浙江慈溪人，上海青帮头目，抗战后公开投敌，为日军提供情报，组织汉奸武装，破坏抗日运动，1940年被暗杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b31ae40f0d84a81844dffb3d106cdeb','84a15843-def7-42d3-a827-2d61d914b4d6',1939,'浙江杭州人','浙江杭州人，原军统特务，投日后组建76号特工总部，在浙江各地捕杀抗日志士，制造多起血案。','危害等级A（甲级，特工总部主任）','hanjian');
