INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8d97994281c4ce3ade58fba45da98fa','6fd631a3-9661-468e-a98c-9b7344d8d6d9',1940,'原国民党政客','原国民党政客，投日后任伪浙江省长，在杭州推行奴化教育，协助日军清乡和镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-964d567c3b0f435ead6e554dccb2d3d9','7b57c158-d427-4844-b1d5-ecd2544805ff',1941,'原国民党中央委员','原国民党中央委员，汪伪政权核心成员，任伪浙江省长期间，在桐庐等地推行保甲制度，强征粮食支援日军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-104ccc1effad4c4f8274c9260cba5379','e87ba305-73a8-41d2-b1ab-955e73bbfe06',1943,'原国民党官员','原国民党官员，投日后任伪浙江省长，在杭州、桐庐地区组织伪军，配合日军扫荡抗日游击队，并推行“中日亲善”宣传。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad425f1027094e04bc47759d135baaa1','d952b5d0-1b28-43e5-892c-f6985d64969f',1940,'原国民党特务','原国民党特务，投日后任汪伪特工总部主任，在浙江、杭州地区建立特务网络，残害抗日志士，后任伪浙江省党部要职。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47f519def0c04685986417099b871ace','609f1ee2-29c6-4348-9087-e2fe795f9ef3',1940,'原中统特务','原中统特务，投日后成为汪伪特工头目，在杭州、桐庐等地设立监狱和集中营，严刑拷打抗日人士，参与“清乡”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6a2b49f8a45463286d1951200f7aba4','acfd6603-b6a2-4af4-989e-d46730d0029d',1940,'原国民党教育界人士','原国民党教育界人士，投日后任伪浙江省教育厅长，在杭州、桐庐各学校推行奴化教育，篡改历史教材。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c62f1a45c19484ea1a59b431c04e9f8','b640c545-2695-42e6-a3d4-4410506b7064',1941,'原国民党工程技术人员','原国民党工程技术人员，投日后负责伪浙江省建设事务，在桐庐地区强拆民房修建日军工事和公路。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41026f81bd524773b479c2914a27cb61','b640c545-2695-42e6-a3d4-4410506b7064',1941,'主持伪省建设事务','主持伪省建设事务，为日军修筑公路和军事设施，强拆民房，破坏农田。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49e1b7c925be4c12b8c5490ed0db23fe','c02e6cf6-fb5a-4bf3-b188-cb584cf3c518',1942,'原西北军将领','原西北军将领，投日后任伪浙江省保安司令，在杭州、桐庐一带指挥伪军围剿抗日武装，烧杀抢掠。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ada02ed847564cd9a0172c669cdf4373','a40d1fe3-4abb-40ba-b403-dfa31fe416a4',1940,'原国民党财政官员','原国民党财政官员，投日后任伪浙江省财政厅长，在桐庐等地强征苛捐杂税，搜刮民财供日军使用。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6acaa034db80476b83848d0b9d26ee8d','3eb72671-412f-4030-b660-db21b8a4b06b',1938,'原杭州地方士绅','原杭州地方士绅，投日后任伪杭州市长，在杭州及桐庐周边推行伪政权，协助日军建立“维持会”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be8d9f3f87cc47f28e781a2f7461f1ae','f06f7fd1-df67-414a-a265-9e27425ee4d6',1938,'原桐庐县地方士绅','原桐庐县地方士绅，日军占领桐庐后投敌，任伪县知事，为日军征粮派夫，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c7a762061bc4fa7a68907a7909f1c92','d7808bdd-bb38-4d00-a979-c8ab2379861a',1940,'原桐庐县商会会长','原桐庐县商会会长，投日后任伪县知事，协助日军建立情报网，多次出卖抗日游击队行踪。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5e88879d98a4df1a73cfc11f1e5aae6','75a6ae29-d094-4105-b271-c5f39d97ff6c',1941,'原桐庐县地痞','原桐庐县地痞，投日后任伪保安队长，带领伪军多次袭击桐庐山区抗日游击队，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b99b59db86b4e53862fef2d79c87863','1ba76a92-476e-4ec4-b6b0-708ffe91888e',1940,'原国民党将领','原国民党将领，投日后被汪伪任命为浙江省参议长，虽未实际到任，但公开支持伪政权，影响恶劣。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-afa7bb0ebf5f4042a129bca1b5ed2431','10c917f9-5087-4499-92ca-6675f961f0ea',1941,'原国民党司法官员','原国民党司法官员，投日后任伪浙江省高等法院院长，在杭州、桐庐地区审判抗日志士，判处死刑或重刑。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55668f2b26bc458f9003126df77287a9','5b2d11ab-16b1-4ce5-bd24-faabbeb0d5b0',1940,'原报人','原报人，投日后负责伪浙江省宣传，在桐庐等地张贴反共标语，鼓吹“大东亚共荣”，欺骗民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16eefca0478f4a37bb0d5fd8a03b0a48','9a5a9f7d-2111-417f-b180-a73d55469867',1940,'参与伪浙江省政权','参与伪浙江省政权，协助日伪在杭州推行户籍管制和清乡，迫害抗日人士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69f24df0bf754e1c9e341f0300edbfbb','b980b3cf-c1ad-4953-b239-524ebbacd0ac',1938,'任伪杭州市长期间','任伪杭州市长期间，为日军提供粮食和劳役，建立伪警察机构，镇压杭州城内抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07e971b6b9dd4caf82b44a62e00133b1','749b70f5-715d-481c-aab5-2c06aa2b0477',1943,'末任伪杭州市长','末任伪杭州市长，在抗战后期仍维持日伪统治，组织“自卫团”对抗游击武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d95fba1db2a44229430cbf4bc885f48','be98287c-1d51-4c21-a3a7-f9ef1005ac0f',1937,'日军占领淳安初期','日军占领淳安初期，出任维持会长，为日军带路、征粮，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e504d9fd4d146c0a6f92c2959f8dc2b','6a4dc5ee-9aba-4f4e-b86b-61b8d37a148f',1940,'任伪淳安县长期间','任伪淳安县长期间，配合日军“扫荡”，强征民夫修筑碉堡，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3013e3a4b42c469a9437341fb739a60e','2faf9098-e458-414c-b85d-ed30afccf502',1941,'率领伪保安队多次袭击新四军游击队','率领伪保安队多次袭击新四军游击队，在淳安西部山区烧毁村庄，杀害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3e98405502544cbb5568f37f5135ab6','71be3363-e0ee-4ba4-8d59-aaa8f75c8de0',1939,'原国民党将领投敌','原国民党将领投敌，在杭州为日伪训练伪军，参与策划对浙西游击区的“清剿”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13ff0499a1814d6296e22b9657752cce','4ef9f584-adab-439a-bb86-899430965855',1938,'在杭州组建伪警察系统','在杭州组建伪警察系统，大肆搜捕抗日地下工作者，协助日军宪兵队实施酷刑。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef6407e2c0c341bbbc1694eda835cdda','cf3233c5-d20c-4920-8178-d738204c31bc',1941,'特务头子','特务头子，在浙江发展伪特工组织，暗杀抗日人士，破坏地下抗日网络。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0bfbe6516bcd4ff2847fe6650843db5a','a43ec22d-1431-438b-98d5-49b34af0c304',1940,'在杭州控制报纸和电台','在杭州控制报纸和电台，鼓吹“大东亚共荣”，污蔑抗日军民，为日伪造势。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bfa7a1d0eee44df99ca4c3ddd6d39aa1','dbb08a4f-e864-428f-92f9-22a368a49d41',1940,'负责为日伪征收苛捐杂税','负责为日伪征收苛捐杂税，在淳安、建德等地强征粮食，导致民不聊生。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c280370b739d4efab969b9e727185bee','5f03aa5f-dd04-4759-8607-d4f1f9290e5b',1942,'推行奴化教育','推行奴化教育，在杭州及周边学校强制教授日语，篡改历史教材，灌输亲日思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42ed948f5a6e40848e91090b6bc611a5','4beac462-1ef8-42e5-a1c7-64766228a480',1943,'组织伪工会、伪农会','组织伪工会、伪农会，煽动民众支持日伪，破坏抗日统一战线。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
