INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25d5220d48fd42768dae230f393da47f','94c593cb-af18-49e8-8c95-1780f91bf30e',1940,'在杭州主持伪法院','在杭州主持伪法院，审判抗日志士，以“反日罪”判处多人死刑或长期监禁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49c0e3d72e194512a9ffb1a4b16ba4ae','a1b05fa5-acdc-44ba-bbab-2dc2d26d8d0e',1940,'浙江永嘉人','浙江永嘉人，早年参加汪伪政权，曾任伪浙江省长，在杭州、滨江地区推行保甲制度，协助日军清乡，迫害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37ffa2b1cdf248528719c730292a2f7e','72085d54-d0d4-4834-b1fc-5dbc9df43993',1943,'安徽盱眙人','安徽盱眙人，但长期在浙江任职，投日后任伪浙江省长，在杭州地区实施物资统制，强征壮丁，为日军提供后勤支持。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4511e258a0774df0870814ba45c4b47d','fdbdb17b-dbfb-4b02-97c9-bfea2ed1061e',1940,'江苏苏州人','江苏苏州人，但受汪伪指派在浙江活动，于杭州、滨江一带组建伪警察和特务网络，参与“清乡”行动，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f36b143bd884f7ca13f0194d2ee3361','72cb4873-b93a-475b-b26b-8224b02c28cd',1940,'湖南沅陵人','湖南沅陵人，汪伪核心人物，虽未直接任浙江职务，但通过其亲信控制浙江伪政权，在杭州、滨江地区推行伪币、掠夺资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
