INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2754b22faa848a09b832827b33eeff5','dbf9c32d-9f98-4b05-813b-f4185e75a498',1944,'广东南海人','广东南海人，汪伪政权第二号人物，曾短暂兼理浙江省政，其政策直接影响杭州、滨江地区，支持日军“扫荡”。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ffcf98e5f1c410cbd91917d4106d754','385c4988-4226-45a2-a75e-18801f1188d4',1941,'广东信宜人','广东信宜人，汪伪宣传骨干，在杭州、滨江地区控制报纸、电台，鼓吹“大东亚共荣”，压制抗日舆论。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e05483e4bf04eb69135eceb5f6acbea','609f4b82-a426-43f6-85e8-396681b85049',1941,'湖北黄陂人','湖北黄陂人，投日后任伪浙江省保安司令，在杭州、滨江地区训练伪军，配合日军清剿游击队，杀害无辜群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19030815b39f492f9b4697c73427c5c5','2b430c6e-14c6-41b6-99c9-a3a97a16c1bb',1940,'山东人','山东人，但长期在浙江任职，投日后任伪浙江省警察厅长，在杭州、滨江地区设立关卡，搜捕抗日分子，勒索商民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9cfac68189d4699ac3c7abc66d19ff5','a6ac9895-72da-4f9b-a00a-744229aa1087',1938,'浙江杭州人','浙江杭州人，原为地方士绅，日军占领杭州后出任伪市长，在滨江地区推行“良民证”，强征劳工，为日军修建军事设施。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e913c72ef0284862875ce54f215669b7','27a4e4fa-634e-4880-a12d-cf69fa76c328',1941,'浙江诸暨人','浙江诸暨人，投日后任伪杭州市长，在杭州、滨江地区实施粮食配给，克扣民食，协助日军掠夺丝绸、茶叶等物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67f977c20a3142a4a617f4a0cecd03f0','0e8f315b-8cd5-4e76-8ee5-daa4bd30391e',1937,'浙江杭州人','浙江杭州人，日军占领杭州初期任维持会长，在滨江地区组织伪政权，为日军征粮派款，迫害抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c91426cf782402ba2946ae586cc77a1','fa1f6403-c533-421b-93e6-5538b4b59df4',1938,'浙江萧山人（今属杭州滨江）','浙江萧山人（今属杭州滨江），地方恶霸，投日后任滨江维持会长，霸占土地，强迫农民种植鸦片，勾结日军欺压百姓。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-99ce394aef8d48efb15efeeabc0ed102','e1a4752b-7cce-46c0-ae49-b4e2cdba7e10',1940,'浙江萧山人','浙江萧山人，投日后任伪滨江区区长，在钱塘江南岸（今滨江）推行日伪法令，强征壮丁，为日军提供情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb843fe8852b4dd599516a61117a2535','02bd65ba-cdf7-40c3-9784-e8f8e43b2241',1941,'浙江萧山人','浙江萧山人，投日后组织伪保安团，在滨江地区协助日军“扫荡”，杀害抗日游击队员，抢劫民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-041c6ef448fe485e922cf0e6bb18d7df','1dcba19d-aa8c-4ae0-965e-39c87a0f9acf',1940,'浙江杭州人','浙江杭州人，投日后任伪建设厅长，在滨江地区强征民夫修筑军用公路和机场，克扣工钱，导致大量劳工死亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2eedb23f7f7e49c39fd63c833f7d254c','15cfd748-14b2-410c-80dc-d599e329e628',1939,'浙江永嘉人（今温州）','浙江永嘉人（今温州），汪伪政权核心成员，参与“日汪密约”谈判，任伪实业部长，为日本经济掠夺服务。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed497ab8deae42b7a906257a994cbcbe','3389cda4-a149-4ddb-ab3a-2140f903f345',1939,'浙江瑞安人','浙江瑞安人，汪精卫亲信，主持汪伪宣传系统，鼓吹“和平反共”，为日本侵略辩护。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0771eb4da30743ff8e035a2d577b0f64','6bc0f7a9-8067-4254-8958-1e008ccf10c5',1939,'浙江杭州人','浙江杭州人，汪伪特务头子，制造多起暗杀与恐怖事件，后任伪浙江省长，在浙江推行奴化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12bd6e28847d43babd486e1f5b8ef142','91db7efb-24c7-4027-8ed6-b59c9afcc8e3',1939,'浙江遂昌人','浙江遂昌人，与丁默邨共同组建76号，残害抗日志士，后任伪江苏省长，参与“清乡”行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a062818734c3401095e579c5053a05b9','523d1b26-e6a5-4c70-bfd3-d4b530e600f1',1940,'浙江杭州人','浙江杭州人，汪伪在浙江的党务负责人，组织汉奸团体，协助日军控制浙江地方。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5133466780234cf4a9abb91e9244e66f','532b7ac8-fb23-459e-ba1c-fdd17e42ccdf',1938,'浙江萧山人','浙江萧山人，日军占领杭州后出任伪杭州市长，推行日伪市政管理，强征物资，镇压抗日民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21c672574fec456c87f79d1ed1f28d28','979df39c-20d9-4882-9d71-83c9acb5731c',1938,'浙江萧山人','浙江萧山人，日军占领萧山后出任伪县长，为日军征粮派夫，镇压当地抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25b565bfe1e743e5bf885a0dcf5df780','f26bb0c1-39f6-4a14-89c9-ab5d2b437f3e',1940,'浙江萧山人','浙江萧山人，继任伪县长，协助日军建立伪政权，推行奴化教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a43406609944c7cad6a2fc743786b9d','c0dde0c8-c846-4d6f-bc0c-cd61a3421b6f',1939,'浙江萧山人','浙江萧山人，组织伪保安队，配合日军扫荡抗日游击队，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d84407d3029f470ca340d61992fbe011','f0cc572e-ba83-4605-a437-7a3c877534e3',1937,'浙江萧山人','浙江萧山人，日军初占萧山时组织维持会，为日军提供情报和物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93a507a049e94f9d933d32708bfd7277','cd6214e7-4f4f-44a3-8aaa-2c2758f7fbc2',1940,'浙江杭州人','浙江杭州人，汪伪浙江省警务负责人，指挥伪警察镇压抗日活动，协助日军“清乡”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7759fa8ee71e47b0bf27752deeaf2d37','24e6a492-8241-475c-91a0-a1e00d82c525',1941,'浙江绍兴人（活动于杭州）','浙江绍兴人（活动于杭州），推行奴化教育，篡改历史教材，鼓吹“中日亲善”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1aaf849567c542f3b9f4b69624c96ad4','6390023d-e0f7-41b2-a531-b843e99ddf14',1940,'浙江杭州人','浙江杭州人，汪伪司法系统负责人，制定迫害抗日人士的法律，后调任伪安徽省长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d50f1cd8f73494392ed2b8c7931d9c8','17d34df0-9ad4-459a-a678-2f729e87ea64',1941,'浙江杭州人','浙江杭州人，负责发行伪币“中储券”，搜刮民财，造成通货膨胀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8934f062c1c46f2bd4e3c360a7be186','d5af50ed-f33e-4bbc-9fd0-439b4be27166',1940,'浙江杭州人','浙江杭州人，汪伪外交官，代表伪政权与日本签订卖国条约，承认日本在华特权。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e71918090a0c44f8a7f40b1b6551574a','d3c9369e-2489-4dbb-9091-cad5a97145ae',1939,'浙江杭州人','浙江杭州人，参与汪日密谈，后因内部矛盾脱离，但前期为汉奸活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e9d1a0bf619463db2de67ac21f4aa07','91d2af38-a243-497f-80a8-544115bf5a42',1937,'上海青帮头目','上海青帮头目，杭州出生，日军占领杭州后积极投靠，组织维持会，为日军征粮派款，破坏抗日活动，后被暗杀。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d2cfe1441ad45b5891f5f4ee62c32da','429e4479-c92a-4bef-81c1-beacb9514d00',1938,'伪维新政府首脑','伪维新政府首脑，其政权控制浙江、江苏等地，在杭州设立伪省府，配合日军经济掠夺和文化奴役。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59905637d2f74ea98d104eaa08334720','8df04d28-4474-4b65-a749-c1327a2b3ca4',1940,'叛国投日','叛国投日，在南京成立伪政权，对浙江杭州地区实施伪化统治，组织伪军协助日军作战。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18bdf257bb034208a756220780c1605c','ba172cd6-cdd2-4a5e-a539-098f81f83d13',1940,'汪伪政权核心人物','汪伪政权核心人物，参与策划对浙江的伪化统治，控制金融税收，为日军提供战争资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
