INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a91c2fe7da149ce96ce98a7f5b632e6','fdd3b5d4-7535-486d-9b27-0c00ed6d2ea3',1940,'汪伪政权骨干','汪伪政权骨干，任伪浙江省长期间，在杭州推行“清乡”运动，屠杀抗日群众，强征粮食。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-340d997c306a4c57b43a65f473357750','e9ea39b7-6e16-4b2e-b284-1952717b9639',1940,'负责汪伪在浙江的舆论控制','负责汪伪在浙江的舆论控制，在杭州创办汉奸报刊，鼓吹“和平反共”，毒化民众思想。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59d960875e944c52a4ef8e2041596138','ca6da958-4f41-4c18-9d7f-40c6bf6cf5a5',1941,'汪精卫妻弟','汪精卫妻弟，任伪浙江省长期间，在杭州推行奴化教育，协助日军掠夺西湖周边文物资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bff4f0c4008747b89f628bbf873ecbf4','96c00ca1-8c6b-4a0c-b933-02427c66c92b',1944,'汪伪政权后期首脑','汪伪政权后期首脑，继续维持对浙江的伪化统治，直至日本投降。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-110e666d39b34d3caa01d2909f5a1283','4a39ea0b-77ca-4be6-a643-2d67cf290b6b',1937,'虽主要活动于华北','虽主要活动于华北，但曾参与协调日军对浙江的占领政策，协助建立伪政权。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66fc435169884ef8a29625c333f236c5','092d21e0-c7e7-4675-ab01-c210d78f7a9d',1938,'参与伪维新政府对浙江的统治决策','参与伪维新政府对浙江的统治决策，支持日军在杭州的军事管制。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59a4b36460a343e88a3ffc756ac9b27a','f5f4bbaa-60e8-4416-a407-43fe05a7b809',1938,'日军占领杭州后首任伪市长','日军占领杭州后首任伪市长，协助日军维持治安，强征民夫，建立保甲制度。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1bbc3f6095644ff883a66ba4b830193c','d3a1872d-2c2b-45bb-a878-01075a411c9c',1937,'杭州沦陷初期投敌','杭州沦陷初期投敌，组织维持会，为日军提供粮食、情报，协助镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
