INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27797dd5a8ea4cadae2c14b4503c80cf','3b3e5a1f-a9de-4917-9770-9611fac276f0',1942,'任伪永嘉县知事','任伪永嘉县知事，为日军征粮派款，组织伪警察协助日军清乡，迫害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c90aae38da844aa994b75fde3f34abc8','68448fa6-3505-4181-a3b4-471d10b3a4fc',1943,'参与伪军军事策划','参与伪军军事策划，协助日军进攻瓯江口及洞头沿海据点，破坏抗日游击队活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95b2e859ea2f48ef82d52a988105bcbf','700f69fe-9891-46a4-b55a-ff6f5c1d6c9e',1944,'在洞头岛组织伪维持会','在洞头岛组织伪维持会，为日军提供粮食、情报，强迫渔民为日军服务，镇压岛上抗日分子。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-851be8beefd045a4ab908c38357e8824','ddeac17d-67d9-4b14-a2ef-168665bfb607',1941,'充当汉奸商人','充当汉奸商人，为日军统购物资，控制温州港贸易，从中牟利，资助伪政权。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-864b0e42b1db48feb1b1b572840a9792','ddeac17d-67d9-4b14-a2ef-168665bfb607',1941,'充当汉奸商人','充当汉奸商人，为日军控制温州经济，垄断粮食和食盐贸易，向日军提供军费，并强迫商户捐款。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0213f4cc34d846e584bae06755164c79','22ac3ff7-d2f8-4a0c-8098-5ea1f89165b0',1943,'率伪保安队配合日军扫荡温州郊区及洞头海域','率伪保安队配合日军扫荡温州郊区及洞头海域，抓捕抗日志士，抢劫民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f343af1543b409abb4992a45c30d338','bff9ca36-d691-40be-b743-b07bb0a10bf6',1942,'指挥伪警察搜捕抗日地下党员','指挥伪警察搜捕抗日地下党员，破坏情报网络，协助日军在洞头设立检查站。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98bac55ca88344d3bef52e2cb8adf18c','d9f6e975-9642-4202-8f85-adf820a2e224',1943,'控制瓯江及洞头海域水上交通','控制瓯江及洞头海域水上交通，为日军护航，截击抗日武装运输船。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3fe0b06bbd347e98ac4541024ad3f44','385c13dd-7af2-4859-9d89-74c236ec69f2',1944,'在洞头推行伪政权统治','在洞头推行伪政权统治，强征壮丁，组织伪自卫团，配合日军清剿海岛游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29fa4d90021f4791986db357cd40ee2d','af7f25de-029d-4e06-908f-5b12f09d1648',1941,'为日军做宣传','为日军做宣传，散布“大东亚共荣”言论，诱骗民众归顺，破坏抗日民心。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d29801f92b794c9fbccbaf4039de68bf','ff767987-c580-4642-a9d5-507b10a24183',1937,'上海青帮头目','上海青帮头目，抗战初期投敌，与日伪勾结，策划组建伪浙江省政府，后遭暗杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d09511bba104d2eb4aaf42136d74993','ff767987-c580-4642-a9d5-507b10a24183',1937,'上海青帮头目','上海青帮头目，抗战初期投敌，与日本特务勾结，策划成立伪浙江省政府，因未及就任即被暗杀。其势力曾渗透湖州地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a32163c3453746a9a5c029e25dbfb307','4547d6e6-ab20-4617-b8e3-faffce59f865',1940,'原国民党中央宣传部专员','原国民党中央宣传部专员，后投靠汪伪政权，任伪浙江省主席，推行清乡政策，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbb6d58165d6430c8267063ea439ee8a','80343ba5-a7cd-414e-a987-2f2f7dd5887c',1940,'汪伪政权核心成员','汪伪政权核心成员，任伪浙江省主席期间，强化日伪统治，配合日军扫荡，征收苛捐杂税。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f1b030e07bc49a8ab9bde127abd53a6','80343ba5-a7cd-414e-a987-2f2f7dd5887c',1940,'浙江乐清人','浙江乐清人，抗战期间投靠汪精卫，任伪浙江省政府主席，在浙江推行伪化教育、经济统制，配合日军清乡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c230b1e89ba4a02ad59b76a088b2f78','80343ba5-a7cd-414e-a987-2f2f7dd5887c',1940,'汪伪浙江省政府最高头目','汪伪浙江省政府最高头目，推行伪化统治，配合日军在浙江包括衢州地区的清乡与物资掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c431b133f71543989793ce098645632d','5041270a-3e34-4bc6-b28e-7b71c3c42379',1944,'汪伪军事将领','汪伪军事将领，任伪浙江省主席，组织伪军协助日军作战，镇压浙东抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a35eae202d054582821dd7472f0d6ac2','9eff9375-a9b2-477e-b058-a92bb8aa591f',1945,'汪伪特工总部主任','汪伪特工总部主任，1945年短暂被任命为伪浙江省主席，未及到任日本即投降。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8470cd3dbf6449c5af58332307084f5f','fc852738-5b1a-4976-a846-11553adc2db1',1941,'投靠日伪','投靠日伪，任伪温州区专员，协助日军维持占领区秩序，强征民夫，搜刮物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-674b8614a374441c96c2ee38dfa449a1','5e6a9e64-8aa1-4ddf-94cc-a54d49ecbc5a',1942,'任伪瑞安县知事','任伪瑞安县知事，推行日伪政令，组织维持会，协助日军清剿抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
