INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42f8bea530ba4632ab9c7672ea4e6ace','a39f0050-d277-435a-8b22-bf158a2db69c',1942,'组织伪绥靖军','组织伪绥靖军，配合日军在温州、瑞安一带扫荡，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4728642142647aa8f391ab145c693bb','e984a3bb-1d36-4db6-bb5e-5a3052022686',1943,'任伪保安大队长','任伪保安大队长，抓捕抗日志士，破坏地下党组织，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bda5a4528a946abbede8c57a80f07b8','a4398dfa-362b-412f-abc7-ea530d9b2d87',1938,'浙江温州人','浙江温州人，汪伪政权核心成员之一，参与筹建汪伪政权，曾任伪浙江省政府主席，推行日伪统治政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a1742936ea648a79d493004ca75a164','dca4e3a8-38a9-4437-b4c9-273a7fe2ce94',1937,'浙江杭州人','浙江杭州人，上海青帮头目，抗战期间投靠日军，组织伪军，协助日军镇压抗日力量，后在浙江一带活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
