INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d8f5a06eb0949f88418c7712155719c','7419dfe6-a397-4988-93a0-ee60db0d1866',1939,'浙江丽水人','浙江丽水人，汪伪政权特务头目，组建伪特工总部，镇压抗日力量，活动范围覆盖浙江部分地区。','危害等级A（甲级，特工总部主任）','hanjian');
