INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91e4d860a6aa4e8b9783e89797026ef8','7419dfe6-a397-4988-93a0-ee60db0d1866',1939,'汪伪特工头目','汪伪特工头目，其特务网络延伸至湖北，在黄冈等地发展情报人员，镇压抗日志士。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cbb2710bab304e6ca99e445c63c9c034','7419dfe6-a397-4988-93a0-ee60db0d1866',1939,'浙江遂昌人','浙江遂昌人，汪伪特工头目，其特务组织在湖北沦陷区设有分支机构，参与镇压抗日力量。','危害等级A（甲级，特工总部主任）','hanjian');
