INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd7bee2dd9a3478fbac3ec0b1c38954c','a205031d-e9fd-4cb5-a9ab-199d8e6cfc89',1941,'原国民党地方官员','原国民党地方官员，投敌后任伪浙西行署参议，为日军策划“治安强化”运动，在湖州各县推行保甲连坐。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
