INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c87aeb76e07c4a28844088d1d1f74953','fde360fc-3560-4290-bb74-98b328acd519',1939,'控制湖州水域','控制湖州水域，为日军运输物资护航，拦截抗日武装的船只，敲诈勒索过往商民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e46b52cf4eb4c4a9d5c67005f41f635','164b414b-7a9e-483b-bd16-fffca669aba0',1937,'原上海青帮头目','原上海青帮头目，抗战爆发后投靠日本，在浙江湖州一带活动，协助日军维持治安，后于1940年被暗杀。','危害等级A（甲级，特别市市长）','hanjian');
