INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04c1ce72280c49318e2dde490380b509','7faac3e4-a6f6-4f54-a87b-380962993d6d',1939,'为伪政权强征各种苛捐杂税','为伪政权强征各种苛捐杂税，盘剥百姓，并将大量税款上交日军作为军费。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6ac8f6957e4429f9b2775df673f9f2a','fb227843-6c9f-4544-bcc9-1ee67d6e2422',1939,'浙江湖州德清人','浙江湖州德清人，早年加入中国共产党后叛变，抗战期间投靠汪精卫，主持汪伪特工总部，残酷迫害抗日志士，后任伪浙江省政府主席，推行伪化统治。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc1deed48b6847e79e56cfb6062635d6','830c535c-7187-4b38-bdaa-020b8937c08b',1939,'浙江丽水人','浙江丽水人，生于湖州，抗战期间投靠汪精卫，与丁默邨共同组建汪伪特工总部，在浙江、江苏等地镇压抗日力量，后任伪江苏省政府主席。','危害等级A（甲级，特工总部主任）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-defced41e10947429c144a4fb440690f','fac33d3d-efd3-4443-b3b2-838488207182',1940,'湖南沅陵人','湖南沅陵人，抗战期间投靠汪精卫，任汪伪财政部长等要职，曾兼任伪浙江省政府主席，在浙江推行伪化经济与统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8891788b9f1477f83c665f90eeb5524','91c4b028-f1a7-47b2-8f89-db39f31c1557',1943,'浙江杭州人','浙江杭州人，抗战期间投靠汪伪，任伪浙江省政府主席兼伪军要职，在浙江境内配合日军扫荡抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
