INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-093f94185c6144f48addd54e781acbd2','d5c91861-4554-4de2-bbb8-309062cd46a0',1940,'抗战期间在湖州地区推行奴化教育','抗战期间在湖州地区推行奴化教育，组织伪教育会，宣传亲日思想，毒害青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63255fa5872e4c5796b671a41ac16a83','cf9d0004-2c90-41ff-8b29-e24fa381df4d',1937,'浙江杭州人','浙江杭州人，青帮头目，抗战期间投靠日军，任伪浙江省政府委员，在浙江一带组织伪军，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-226fa61e790c46f2ab8f2076bf4fc7ac','188ff43f-7f41-44a2-af6c-74a202b17431',1937,'日军占领长兴后出任伪县知事','日军占领长兴后出任伪县知事，协助日军推行“治安肃正”，强征民夫修筑公路和碉堡，并组织伪保安队镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f23c8b5ea89d4bfd9d02b06e8168684b','515ce5d8-81ab-40d6-b466-faa93a68f093',1937,'长兴沦陷初期组织维持会','长兴沦陷初期组织维持会，为日军筹措粮饷，并强迫商户悬挂日伪旗帜，配合日军清乡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b54593c14ff94cc0a3b4ce88276b4931','907500e1-9314-4a4b-bd68-22d94c37859e',1938,'率领伪保安队多次袭击新四军游击队','率领伪保安队多次袭击新四军游击队，抓捕抗日群众并移交日军宪兵队，参与“清乡”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d72b62ac5c15449c9fe210c45c2f234e','32bc8c58-78a1-4598-92c5-520bb2314cb7',1939,'负责伪警察系统','负责伪警察系统，搜捕抗日地下党员，破坏中共长兴地下组织，并协助日军推行保甲制度。','危害等级B（乙级，市县厅局级）','hanjian');
