INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b46deb528804702a3d2474fc5ffa8df','427080eb-b934-4f69-9e23-8b62e925e9c2',1938,'福建长乐人','福建长乐人，北洋政客，抗战期间投敌，1938年在南京组织伪中华民国维新政府并任行政院长，后并入汪伪政权任监察院长、立法院长等职，抗战胜利后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-867fd4082266419ca38bd7243cbb1ee7','427080eb-b934-4f69-9e23-8b62e925e9c2',1938,'福建长乐人','福建长乐人，生于浙江，抗战期间组织伪维新政府，后任汪伪政权要职，1946年以汉奸罪被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a38eb8bcc8a4dbdbdcc39ff7c580ee3','60b9bcb5-11d1-440a-8622-af4e69954f6d',1938,'广东乳源人','广东乳源人，原国民党要员，随汪精卫投敌，历任汪伪政权立法院长、上海市长、行政院长、代主席等职，是汪伪政权核心人物之一，抗战胜利后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-651987f807164c62b6155e6d076916d9','44e20e78-23bb-4e89-81ab-0f626e0b919b',1938,'湖南沅陵人','湖南沅陵人，原国民党要员，随汪精卫投敌，历任汪伪政权财政部长、警政部长、上海市长等职，掌控伪政权财政与特务系统，抗战后期与重庆方面暗中联系，胜利后被判无期徒刑。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee56991344f345b4b89cfc077aa814c4','b3be8348-1b2c-416a-baba-82e1c9914dcd',1938,'浙江吴兴人','浙江吴兴人，原国民党元老，随汪精卫投敌，历任汪伪政权外交部长、驻日大使、广东省长等职，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84cf68ae32db49a89e11b315bc8a47e6','1c019012-f559-473b-b4a1-ab6daa3c0973',1938,'浙江永嘉人','浙江永嘉人，原国民党中央委员，参与汪精卫投敌活动，历任汪伪政权工商部长、内政部长、伪浙江省长等职，在浙江协助日军推行伪化统治，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab8b5f630a064404a8000e6cff6aa2d2','1c019012-f559-473b-b4a1-ab6daa3c0973',1938,'浙江永嘉人','浙江永嘉人，抗战期间参与汪精卫投敌活动，后任伪浙江省长，1946年以汉奸罪被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7bdddc40f27408abbe6d1fffa0e1f74','cb6d9f0e-74b6-4e17-bd44-80780e17e184',1940,'浙江乐清人','浙江乐清人，学者出身，抗战期间投敌，1940年出任伪浙江省长，协助日军在浙江推行伪化统治、征粮征丁，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82cb244ff6164484852568168f41a04e','6053bdc1-a6d7-4382-8d1c-41d09869bd68',1943,'浙江杭州人','浙江杭州人，原国民党军官，投敌后历任汪伪政权军事要职，1943年出任伪浙江省长兼伪军第一方面军总司令，在浙江协助日军清乡、镇压抗日力量，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfb37c69f5844d9891253a3a3ede51a3','0f752d13-8f3b-4cc0-9906-07a9a89370ca',1939,'湖南常德人','湖南常德人，原国民党特务，投敌后成为汪伪特工总部负责人之一，历任汪伪政权社会部长、伪浙江省长等职，在浙江推行特务统治，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c9daa9cb98d406f9e9cdbf349c0eb67','0f752d13-8f3b-4cc0-9906-07a9a89370ca',1939,'湖南常德人','湖南常德人，抗战期间任汪伪特工总部主任，后任伪浙江省长，1947年以汉奸罪被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-add9bd334cad4f1fbc6a8e600122ccbb','080cd4e6-d071-4c88-b509-915999fb378b',1939,'湖南湘乡人','湖南湘乡人，原国民党要员，随汪精卫投敌，历任汪伪政权司法行政部长、伪浙江省长等职，在浙江协助日军维持统治，抗战胜利后被判无期徒刑。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1fea6e07c7db4beca92fc726d7d555e2','080cd4e6-d071-4c88-b509-915999fb378b',1939,'湖南湘乡人','湖南湘乡人，抗战期间任汪伪政权要职，后任伪浙江省长，1945年被捕，1947年判无期徒刑。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9af412fb9bc64472a095d1a65dfa5f4e','80df4d31-26be-48c3-a4f1-4b9bcdbe0edc',1937,'安徽合肥人','安徽合肥人，北洋政客，抗战期间投敌，参与组织伪中华民国临时政府，后任汪伪政权考试院长、华北政务委员会委员长等职，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4ece2c124d84fe9977ad55b410147ec','175f5e71-4ce1-41cb-be06-8d89913cb387',1938,'浙江绍兴人','浙江绍兴人，原国民党军官，投敌后历任伪维新政府、汪伪政权江苏省长、安徽省长等职，在华东地区协助日军推行伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a485fde733cd4672bb47c4e179b9524a','d8cdfd9a-5095-49db-a0cc-19d1ccd67fcb',1940,'浙江绍兴人','浙江绍兴人，抗战期间投敌，历任汪伪政权浙江省政府委员、伪杭州市长等职，在杭州及绍兴周边协助日军维持统治、推行伪化教育。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e52868086d1432ca2799e8125b8e3a3','57c26d24-7eab-4cf0-be02-d97c2d2abd2f',1941,'浙江绍兴人','浙江绍兴人，抗战期间投敌，日军占领绍兴后组织伪维持会并任会长，后任伪绍兴县长，协助日军征粮征丁、维持地方伪化统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67d5ad4fc76f4768929de35540a9a899','f472733a-4a8c-41bc-8529-e5c0cb744b25',1941,'浙江绍兴人','浙江绍兴人，抗战期间投敌，历任汪伪政权浙江省政府委员、伪绍兴县长等职，在绍兴地区协助日军推行保甲制度、镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57147e082a484072963290f909f0128f','11ac9bf9-33ca-44a9-b0d7-ae420f11ee4c',1940,'浙江绍兴人','浙江绍兴人，原报人，抗战期间投敌，历任汪伪政权中央宣传部次长、伪绍兴县长等职，在绍兴地区协助日军进行文化宣传与伪化统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f6812a41f614ba2b96d244d5b6ce685','7e6fdf05-50f9-4580-87c6-6110a38b1c98',1942,'浙江嵊县人','浙江嵊县人，抗战期间投敌，日军占领嵊县后组织伪维持会并任会长，后任伪嵊县长，协助日军征粮征丁、维持地方伪化统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3295a8492cc94f4b8cf93e659515a77c','12b87313-5040-400d-8a22-9b83847560d5',1942,'浙江嵊县人','浙江嵊县人，抗战期间投敌，出任伪嵊县警察局长，协助日军维持地方治安、搜捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aeb1b063ef55492591e0da8708d2c25e','0b45626a-b306-4905-a794-df6bc800971f',1942,'浙江嵊县人','浙江嵊县人，抗战期间投敌，出任伪嵊县教育科长，在嵊县推行奴化教育、协助日军进行文化侵略。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d2bf4acfe97414299024059ab072585','e6a16b71-e277-4c38-97be-31cd22fb7dfc',1939,'浙江遂昌人','浙江遂昌人，原共产党叛徒，投敌后成为汪伪特工总部负责人，历任汪伪政权特工总部主任、警政部长、伪江苏省长等职，在华东地区大肆镇压抗日力量，1943年被日军毒杀。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c438c98775d94ccb88f3ea81aa7be9c7','e6a16b71-e277-4c38-97be-31cd22fb7dfc',1939,'浙江遂昌人','浙江遂昌人，抗战期间组建汪伪特工总部，活动范围覆盖浙江，1943年被日军毒杀。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77839c3391af4ab08d75891cb95f1999','a2236b4c-91ad-4189-ba04-128a67b7e3ea',1939,'江苏南通人','江苏南通人，上海青帮头目，投敌后任汪伪特工总部警卫队长，在上海及周边地区参与暗杀、绑架等恐怖活动，协助日军镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62d0679258dc4c54b7d85e447078057b','a2236b4c-91ad-4189-ba04-128a67b7e3ea',1939,'江苏南通人','江苏南通人，活动于上海及浙江，抗战期间任汪伪特工总部警卫队长，参与暗杀和镇压抗日人士，1942年暴毙。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d8369ed193a44dbb354097a24f1c13c','6a20f14e-87a0-457a-9828-d91b46e37068',1937,'浙江慈溪人','浙江慈溪人，上海青帮头目，抗战期间投敌，出任伪浙江省政府委员，协助日军在上海及浙江地区维持统治、镇压抗日活动，1940年被军统刺杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b8cd78360f44d70badf2f81eaa47ed9','72d1987a-85b2-492b-99ba-802b02f506e7',1937,'江苏南京人','江苏南京人，青帮头目，抗战期间投敌，历任伪上海特别市警察局长、伪军将领等职，在上海及周边地区协助日军维持治安、镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7dac6621a0904ee782bde26bf6843207','0dc6f117-7a4a-40e1-bac0-79e3cfb48880',1938,'浙江绍兴人','浙江绍兴人，抗战期间投敌，历任伪上海特别市秘书长、伪浙江省政府委员等职，在浙江及上海地区协助日军推行伪化统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-608d314cc1444188930f15c5a56a91ea','2b34d94e-c1c4-4c0f-81d6-72ad21fbce83',1938,'福建闽侯人','福建闽侯人，北洋政客，抗战期间投敌，历任伪维新政府内政部长、汪伪政权江苏省长等职，在华东地区协助日军维持统治，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b5e54dd92754aaab263269b471690b0','87382e4a-b021-4e3b-bec4-b85fb493b36d',1938,'江苏宜兴人','江苏宜兴人，原国民党军官，投敌后历任伪维新政府绥靖部长、汪伪政权海军部长、伪军第一方面军总司令等职，在华东地区协助日军清乡、镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd8ea932cfdd4071836c7de38fc80d70','aaf651ee-456b-4ec8-8424-1b51a4fa909c',1940,'浙江绍兴人','浙江绍兴人，抗战期间投敌，历任汪伪政权江苏省政府委员、伪军将领等职，在江苏及浙江北部地区协助日军维持统治、镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67c0611bed4e424e8dfdf7a769007a9e','ae924a2b-1ea4-4935-85ac-6a0414a150a9',1939,'湖北蕲春人','湖北蕲春人，原共产党叛徒，投敌后历任汪伪政权江苏省政府委员、伪军将领等职，在华东地区协助日军维持统治，同时与多方势力有复杂联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7c017a1e2424b8d92b3558e445a1f1f','20a4598a-4079-49dd-b8b1-ee51b9d9aa16',1937,'投靠日军','投靠日军，出任伪新昌县知事，协助日军维持占领区秩序，推行保甲制度，强征粮税，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d3a0f2e5222945769b2583e941eb8b5c','893e1265-1414-401b-9454-a8b51c835fa6',1937,'日军占领新昌后率先组织维持会','日军占领新昌后率先组织维持会，为日军提供粮食、劳役和情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ae8200d68194bfb8d94f23c7d3b777d','ec52cdb9-7da7-46ce-90e7-6eb5f193dac2',1938,'组织伪保安队','组织伪保安队，配合日军扫荡抗日武装，抓捕抗日军民，残害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b828aceffaa40fab32a44ff056fd106','f2511bf9-6ce8-435f-9214-bf963c28f5d3',1940,'在绍兴伪政府任职期间','在绍兴伪政府任职期间，多次派员到新昌催收捐税，协助日军清乡，破坏地下抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf3cb0330c4f449b95f861c17569ec91','6bafe0bd-6ce3-4dbc-afbb-77d5f3cda5c4',1941,'指挥伪警察侦缉抗日分子','指挥伪警察侦缉抗日分子，实施“连坐”政策，多次参与围捕中共地下党员和游击队员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a82933f838c4bb5b37897bf774a958e','e6c21cf0-d710-4cbb-8298-c2a792bf8373',1939,'为日军筹措军需物资','为日军筹措军需物资，垄断粮食和食盐贸易，从中牟利，并强迫商户向日军献金。','危害等级C（丙级，基层头目）','hanjian');
