INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a49965c179e4471eb5194210bd849bf6','2bbe2887-c34a-4467-9e81-6b7c3a6ec492',1940,'任伪警察局长','任伪警察局长，协助日军搜捕抗日地下党员，严刑逼供，破坏抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d8a5f706c5a40ee9e54ec7f0fab7301','5f97ba81-d23a-4d76-b408-b34ad63ed6be',1943,'任金东伪区长','任金东伪区长，推行日伪“保甲制度”，强征壮丁，为日军修建碉堡和公路。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12d2c93a8ea040c19eca995688d7e109','53292843-07e5-4b26-8417-820dcb8b71f9',1939,'充当日军经济汉奸','充当日军经济汉奸，垄断粮食和食盐贸易，压低收购价，为日军筹集军需物资。','危害等级C（丙级，基层头目）','hanjian');
