INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-123c6d53aef14a16897a8820eb731c0f','701fb2d2-330d-47b7-8e47-0dc11c1094b9',1944,'组织伪自卫团','组织伪自卫团，协助日军清乡，杀害抗日游击队家属，并参与“三光”行动。','危害等级C（丙级，基层头目）','hanjian');
