INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f84d062df3442d7b5a34ee3d53ec917','4ae011a2-159d-4b41-a34e-64ce8039a18c',1940,'在和乐地区推行保甲连坐','在和乐地区推行保甲连坐，协助日军修筑和乐据点，带领伪自卫队搜捕抗日游击队员及其家属。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
