INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-653efcf168974c0da3bed7a6bb1f132e','c73fb634-b7c8-4055-ae3e-8ae1bca79a2a',1940,'汪伪政权核心人物之一','汪伪政权核心人物之一，虽主要在南京活动，但其伪政权体系覆盖湖北，参与推行伪化政策、经济掠夺和配合日军统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2378fee68f2843f38d16d94adb4c9dd8','67a3348a-0097-4356-8a92-4e602c79e9ee',1940,'抗日战争时期在竹溪地区出面组织伪维持会','抗日战争时期在竹溪地区出面组织伪维持会，协助日军与伪政权维持地方统治，摊派粮款、拉夫，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea36ee2d8ae14100afd1c35ada99b9ad','23066839-8bbc-4b66-9ece-1a6347a8a5b0',NULL,'在郧县一带依附日伪势力','在郧县一带依附日伪势力，参与组织维持会与伪基层政权，为日军搜集情报、征发民夫粮秣，压制抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
