INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96f7b2b04b02422ab6e543cce56c9494','3c9c8387-1d81-485a-a383-ae2e0570a617',1938,'日军侵占沙市后出面组织伪维持会','日军侵占沙市后出面组织伪维持会，协助日军维持占领秩序、征发物资与劳工，后任伪市政筹备处处长，参与筹建伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-781019579aa8492fa8c72c9474b86366','55722a2b-7aad-40c9-ba3f-f5068bc593ae',1938,'原为国民党军将领','原为国民党军将领，1940年前后在鄂中、荆州一带与日伪有勾连，所部曾接受伪军番号，后与日军冲突被俘，其部属在荆州、沙市周边活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e3b22e15b78460ca7a8f861aa90c092','55722a2b-7aad-40c9-ba3f-f5068bc593ae',1938,'原为国民党军将领','原为国民党军将领，1943年在湖北沔阳、监利、石首一带被日军俘虏后一度附逆，所部被编为伪军，后脱离日伪控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b09e455f0a7b47d5a7c3fad07c5ff5b4','55722a2b-7aad-40c9-ba3f-f5068bc593ae',1938,'原国民党军将领','原国民党军将领，后投靠日军任伪军师长，活动于湖北、湖南北部，与株洲、攸县无直接关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
