INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-315429d8e68a4ef3804dd3eed88ec0e2','9c971034-bd27-4e40-b239-f0916e48715a',1938,'湖北黄陂人','湖北黄陂人，早年投靠日军，历任伪武汉特别市市长、伪湖北省政府主席等职，协助日军推行治安强化运动，搜刮物资，镇压抗日力量。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a1470f9edab4d428945dfd4ff6473d7','9c971034-bd27-4e40-b239-f0916e48715a',1938,'湖北黄陂人','湖北黄陂人，早年在鄂东活动。抗战期间投靠汪伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北推行伪化统治，配合日军清乡、征粮、拉夫，是湖北地区级别最高的汉奸之一。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14c43d2798fc498ab0ce2b342854cd60','9c971034-bd27-4e40-b239-f0916e48715a',1938,'湖北黄陂人','湖北黄陂人，抗战期间投靠汪伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北地区推行伪化统治，为日军搜刮物资、镇压抗日力量。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-585956ff39eb42ceba9002e3679f1552','9c971034-bd27-4e40-b239-f0916e48715a',1938,'湖北黄陂人','湖北黄陂人，早年即为国民党将领，抗战期间投靠汪精卫伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北地区推行伪化统治，协助日军征粮、征兵、镇压抗日力量。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f025ab1565541099a1a38fad1152869','9c971034-bd27-4e40-b239-f0916e48715a',1938,'湖北黄陂人','湖北黄陂人，抗战期间投靠汪伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北地区推行伪化统治，搜刮民财，配合日军清乡。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4672018036304d7db6bfcef441d35846','9c971034-bd27-4e40-b239-f0916e48715a',1938,'湖北黄陂人','湖北黄陂人，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北地区推行伪化统治，为日军搜刮物资、镇压抗日力量。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-528e8aee494e42f180c49e3cda91acad','9c971034-bd27-4e40-b239-f0916e48715a',1938,'湖北黄陂人','湖北黄陂人，原国民党将领，1939年投敌，任伪武汉特别市市长，后任伪湖北省政府主席兼保安司令，在湖北推行伪化统治，搜刮民财，配合日军清乡。黄冈、麻城属其伪湖北省管辖范围。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59866a8e9a054a63ad862e5a2b9ee9ff','9c971034-bd27-4e40-b239-f0916e48715a',1938,'湖北黄陂人','湖北黄陂人，早年投靠日军，1938年武汉沦陷后出任伪武汉特别市市长，后任伪湖北省政府主席，协助日军推行治安强化运动，搜刮物资、镇压抗日力量。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aad01f267c874763baaa66e40749896a','9c971034-bd27-4e40-b239-f0916e48715a',1938,'湖北黄陂人','湖北黄陂人，原国民党将领，后投靠汪伪政权。任伪湖北省政府主席期间，在黄冈、黄梅等鄂东地区推行保甲连坐、征粮征丁，配合日军清乡扫荡，是湖北地区级别最高的汉奸之一。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16d899f128094cb6bc07472acf10c0b7','543559ba-3bc0-4820-bd76-0531963c5eef',1938,'湖北黄冈人','湖北黄冈人，日军占领武汉后出面组织伪政权，任伪湖北省省长，配合日军征粮征丁，推行奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6dd417f7609c4acd9efe71f62510d1f9','543559ba-3bc0-4820-bd76-0531963c5eef',1938,'湖北建始人','湖北建始人，早年留学日本，抗战爆发后投敌。1938年武汉沦陷后出任伪湖北省省长，在黄冈、黄梅等鄂东各县建立维持会、伪警察局，推行奴化教育，为日军征集物资劳工。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
