INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f03ee0cd0514bfaabf30a06dabbaa9c','a23c51b4-4bf6-4903-96c2-683b3b89f863',1938,'团风镇本地商人','团风镇本地商人，日军占领团风后组织维持会并任会长，为日军筹集粮草、提供情报，协助管理码头和过往人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a2ede855b454c1f83c1c9b1cffb813e','9f7f28b6-4f9d-4656-9332-3cdcdbea2102',1940,'在黄冈沦陷区推行奴化教育','在黄冈沦陷区推行奴化教育，编写伪教材，强制学校教授日语和亲日内容，毒害青少年。','危害等级C（丙级，基层头目）','hanjian');
