INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-387ee31d7a854e2591a322aa1f764f81','a2b2e04c-4610-43a5-89ac-890943d3abec',1937,'安徽合肥人','安徽合肥人，虽主要在华北活动，但与湖北伪政权有联系，其伪政权体系影响湖北，抗战期间投敌叛国。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9444ce63e53b4d13ad402b29f87398fc','e5ea6d60-b2a0-4a4f-94c5-7eac6935b8e9',1938,'湖北人','湖北人，抗战期间在武汉伪政权任职，协助日军推行伪化政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3815eba5f71645e78366c90a454292a2','76e449d9-f3d2-45f3-ae43-6c7d016312b8',1938,'罗田地区人','罗田地区人，抗战期间组织伪维持会，为日军服务，协助征发物资、维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff316e38a7fd455f98ac19da1369eb9d','a6ccc897-fa43-4c80-a9c9-f20a117045a3',1939,'抗战期间任伪罗田县县长','抗战期间任伪罗田县县长，在罗田地区推行伪政，协助日军统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8efff76af44345aeb39faf70e7a73d4e','81135fd1-fce4-45a8-a85c-aed7542187d3',1939,'抗战期间任伪黄冈县保安团团长','抗战期间任伪黄冈县保安团团长，率伪军配合日军扫荡黄冈地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46763e3b84f04ed896dbfc0a0dcefb0b','a6334471-dcc3-49e8-bf3b-10344ffef2c9',1940,'抗战期间在黄冈伪政权中负责教育','抗战期间在黄冈伪政权中负责教育，推行奴化教育，宣传“大东亚共荣”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ade95cc21b0f4907b9986c2097748993','776f56b9-cddc-4b84-b7e9-55ee5981639f',1938,'湖北人','湖北人，抗战期间投敌，在湖北伪政权中任职，为日军统治服务。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-002291fa2b594efe817c5ca5d8584892','a76e6958-812f-4bd2-b066-1a6f5c823e00',1938,'黄冈地区人','黄冈地区人，抗战期间任伪维持会副会长，协助日军征粮、派夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48670c43379e4f7ea22ea4609219e875','3355fe5a-1f31-44c7-9ce9-0c2ecdbee665',1939,'抗战期间任伪罗田县保安队队长','抗战期间任伪罗田县保安队队长，率伪军配合日军清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7dcec8ae1a5445bb9006043aa057886','da087345-3dc5-43fb-9745-d900777bd951',1939,'抗战期间在黄冈伪政权中负责税收','抗战期间在黄冈伪政权中负责税收，为日军筹措军费。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ee6f87613364a07827d69d6b5d5b855','24351d50-1d6d-4e90-979d-46e564f63149',1938,'黄冈本地人','黄冈本地人，日军占领黄冈后组织维持会，为日军筹集物资、维持治安，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a78ceb53e9354540aa7d2aca00ac2d6f','cc827d31-8194-4ad5-81d4-2f9eaaffda19',1938,'英山地区投敌分子','英山地区投敌分子，组织伪维持会，配合日军对英山及周边地区的控制与扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e39c4d91f46e49ac9aeff14a51d87fcd','94935e86-6a0c-487b-b9ec-bab65991768b',1939,'在黄冈任伪职期间','在黄冈任伪职期间，推行保甲制度，协助日军清乡，抓捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bde596cd5a044c338a78d4a1abd0c7b2','52c43e6a-1966-4703-ac56-e3fe2db85bfc',1940,'在黄冈地区任伪警察局长','在黄冈地区任伪警察局长，带领伪警察配合日军搜捕抗日志士，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de17ce50e8a84f06a6f51bcd07fb757e','a4cbe208-a65b-40a5-9671-fea209fda1a1',1941,'英山本地投敌武装头目','英山本地投敌武装头目，率伪保安团配合日军进攻抗日根据地，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e81d175b37b4b71984e0d2cb673e81b','98f0fb27-feea-4e3c-80e7-7b5b9e173b14',1938,'蕲春本地人','蕲春本地人，抗战期间投敌，任伪蕲春县维持会会长、县长，在蕲春地区为日军筹粮筹款，维持伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e2e5094d3d74c439d5f88f84d85b161','7879fd76-9c92-40a4-8625-1f2b14a136f7',1939,'黄冈人','黄冈人，抗战期间任伪黄冈县保安大队大队长，率伪军配合日军扫荡黄冈、蕲春一带抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f541b75c44e040c9b51bc89efec03e0c','5e97f64e-9d1e-4b76-b567-515574505cfe',1941,'蕲春人','蕲春人，抗战期间任伪蕲春县保安团团长，配合日军在蕲春、黄冈交界地区进行清乡扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d66c84e1d2b7493a831ac1fd491b1a56','48eeef31-6e24-40a1-95ba-1ae921885063',1938,'湖北人','湖北人，抗战期间投敌，任伪湖北省政府委员、伪汉口市市长，在武汉地区协助日军推行经济统制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80f08784bf4e4efaa350bf914a14e20b','9c1dce7e-0a73-4a75-97f7-de5a20f5fb3b',1939,'湖北人','湖北人，抗战期间任伪湖北省政府委员，并曾兼任伪黄冈县县长，在黄冈地区推行伪化教育。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7f8bcb6e86240a3a995998072f5cfee','ca40211e-cada-4729-a5a7-0236d3cfd01a',1938,'浙江永嘉人','浙江永嘉人，早年曾任江宁实验县县长，后追随汪精卫投敌，参与筹建汪伪政权，历任伪工商部次长、实业部部长、内政部部长等职，为汪伪集团核心成员之一。其活动主要在南京、上海，但与湖北黄冈、麻城无直接任职关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13351b60c58542ba812daeea588e719b','ca40211e-cada-4729-a5a7-0236d3cfd01a',1938,'浙江永嘉人','浙江永嘉人，汪精卫集团核心成员之一，参与筹建汪伪政权。虽非黄梅籍，但据黄梅地方史料记载，其祖籍与黄梅有渊源，且汪伪政权在湖北黄冈、黄梅一带推行伪化统治时，其政策直接覆盖该地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-032a1775214b4c138676b986799108be','f8a9494c-cb38-4e67-9822-6e1fc109a191',1938,'麻城本地人','麻城本地人，1938年麻城沦陷后组织维持会，后任伪麻城县县长，为日军筹粮筹款，配合伪军清乡，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5900f9b0c0ce43b7af6dd798ce1d75fb','c2d645b8-65dd-4531-befe-691619d2a759',1939,'麻城人','麻城人，任伪麻城县保安大队大队长，协助日军维持麻城沦陷区治安，参与清乡与搜捕抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0076edc750c4766b5f2f8e037509c46','4e1efe90-40d8-433d-ab9f-16470e3d5010',1940,'在黄冈沦陷区推行奴化教育','在黄冈沦陷区推行奴化教育，编写伪教材，宣传“大东亚共荣”，强迫学校使用日语教学，毒化青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab16ae2b17794393a8bcfde41eeac37f','e961b376-7cd4-4b35-9a31-422b8b4a45ea',1941,'麻城人','麻城人，任伪麻城县合作社理事长，协助日军统制物资，低价强购农产品，盘剥当地百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-50bde746aaa64bf7a9228c087957eb31','be1d76fd-26e2-4337-8d9d-5710245a65f6',1940,'湖北黄陂人','湖北黄陂人，原国民党军官，1940年投敌，组建伪黄卫军，活动于武汉及黄冈、麻城一带，配合日军清乡，后任伪武汉行营参谋长。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-988b771c40464d63b0e058ce29f647d8','7b5b80a6-fcdf-4580-87e0-0e3cbbcde5ba',1940,'湖北人','湖北人，与熊剑东共同组建伪黄卫军，活动于鄂东黄冈、麻城地区，协助日军扫荡抗日根据地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41b962cb31444385a34013a889d5def1','71b112e9-01b8-4e43-91a6-db0ae17046bf',1943,'湖北人','湖北人，原国民党军官，1943年投敌，任伪和平救国军第一军军长，活动于湖北黄冈、麻城一带，配合日军作战。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f8695cebae4483b9997824f868dbdf3','e3de343f-2f7a-4a0c-8422-17c636a4f2a6',1942,'湖北人','湖北人，任伪湖北保安司令部副司令，协助伪湖北省政府主席叶蓬、杨揆一统辖湖北伪军，参与鄂东黄冈、麻城地区清乡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdd74db4924e44b4b61a81d0a32e71d1','45bc72cd-c02f-4745-812e-ea80efa409e7',1940,'湖北人','湖北人，原国民党军官，1940年投敌，任伪和平救国军第八军军长，活动于鄂东地区，包括黄冈、麻城一带，配合日军清乡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-454987a95ffd46fbad575d1e743535e8','a3879bbd-94a1-48ed-b6a7-f9a1c7911370',1940,'黄冈人','黄冈人，任伪黄冈县警察局局长，协助日军维持治安，搜捕抗日人员，镇压群众抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88d767955c7a42cf9c910f466d940564','f3b9af01-62aa-4cf0-a753-9c4a8daf2855',1940,'麻城人','麻城人，任伪麻城县警察局局长，配合日军和伪县政府镇压抗日活动，迫害抗日家属。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07011343eb5e4c18b3f91ca06b5a9cb1','cf452436-e277-41a5-a575-0cc6dc441a10',1938,'湖北黄冈人','湖北黄冈人，武汉沦陷后附逆，任伪湖北省政府副主席、伪汉口特别市市长，协助日军维持殖民统治，掠夺经济资源。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ca83679cd964dba9ce18faf162ed68b','abebfd2a-d574-45d5-97ae-6a95ea04cf3e',1938,'黄冈本地士绅','黄冈本地士绅，日军侵占黄州后组织维持会，后任伪黄冈县县长，为日军征发民夫、粮食，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c74a3c0a8dc6463caf07e08af238089a','5cb17ff8-f31b-4028-8185-1256ef3550e2',1939,'黄冈人','黄冈人，组建伪保安大队配合日军扫荡，多次袭击新四军游击队，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e1229f6f9d2426e9e3951c6647d5c23','fc42de16-4c38-45b5-b939-65869c1985a0',1940,'黄冈人','黄冈人，任伪警察局长期间搜捕抗日人员，推行保甲连坐，协助日军维持黄州及周边治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-275f592f65c74db0bf52b2bd8dd116cb','c9749d64-1aed-463d-99ad-366ea5d82741',1940,'黄冈人','黄冈人，在伪政权中负责教育，推行日语教学和奴化教育，篡改历史教材，为日军侵略辩护。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86bf755880604c8f94c3768eee452330','e8bfe202-aa18-4a44-b27c-d98277521cd9',1939,'黄冈商人','黄冈商人，出任伪商会会长，为日军筹款筹粮，控制物资流通，从中牟利并协助日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c7a8b76f2654fd59574b6b95ad99c38','8615029c-d4f1-4cf2-ad43-e411886df5a2',1938,'黄冈人','黄冈人，协助雷寿荣组织维持会，为日军带路、指认抗日家属，参与迫害抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-517a066dfc164b399740f0d6e0dc33eb','929adab7-84f8-4264-ade7-e7655007cdd9',1938,'湖北黄冈人','湖北黄冈人，早年留学日本，抗战后投敌。作为黄冈籍汉奸，在伪湖北省政府中负责联络鄂东各县伪政权，直接参与黄冈、黄梅等地维持会的组建与督导。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98a7320fca744f2097e331dce2dfe9a9','3f3c89bb-cecf-45ca-af53-379868f8c516',1939,'湖北黄冈人','湖北黄冈人，抗战期间出任伪黄冈县县长，在黄冈及邻近黄梅地区推行保甲制度，为日军征粮征丁，镇压抗日群众，是黄冈本地伪政权头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc7d3a54b5a84505b37866cbec2120ce','91654b8c-67cc-4737-a0b1-331be6fed72b',1938,'湖北黄梅人','湖北黄梅人，黄梅沦陷后出面组织维持会，后任伪黄梅县县长。在黄梅地区为日军征集粮食、劳工，配合日军对黄梅抗日游击区进行清乡，是黄梅本地主要汉奸。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-992f439c931f46c88211c65b3efbd033','a4378fe8-6042-4516-ba59-749d4fcd64f1',1939,'湖北黄梅人','湖北黄梅人，伪黄梅县地方武装头目，率伪保安大队配合日军在黄梅、广济一带扫荡，捕杀抗日人员，勒索民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f82b299d718644dca48d7aa5fa56a217','b0d31670-e223-404b-931d-728bc7b5c011',1940,'湖北黄梅人','湖北黄梅人，伪黄梅县警察局长，负责黄梅城区及周边治安，搜捕抗日分子，配合日军经济封锁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1324a27014584a2b8af09dc9eafa732b','c087a186-cb38-47d9-8c50-a1a835300966',1938,'湖北黄冈人','湖北黄冈人，黄冈沦陷初期组织维持会，为日军筹粮筹款，诱降地方士绅，是黄冈伪政权早期头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ac212793a1d4af294a412fd12d90f1f','854cc726-33d5-4cac-9fdd-ac89037346e6',1940,'湖北黄陂人','湖北黄陂人，原国民党军官，被俘后投敌。组建伪黄卫军，在黄冈、黄梅等鄂东地区配合日军作战，后任伪武汉行营参议，参与鄂东伪化统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d526f9818ff644b7ac27711926cbdbc5','212ea9ee-b3cb-486f-8cfa-ab2381320efd',1940,'湖北黄冈人','湖北黄冈人，伪黄卫军主要头目之一，在黄冈、黄梅一带指挥伪军配合日军扫荡，后进入伪湖北省保安司令部，继续在鄂东地区活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b12f1c664d8244c5ba59954aebfa6d71','ab7b1749-94dd-47c2-aa6c-0eed25db4a48',1939,'湖北黄冈人','湖北黄冈人，投敌后任伪黄冈县自卫团团长，在黄冈、黄梅地区为日军维持治安，征收捐税，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9f0314f6b0543c8814b50d3d8fe8b65','0bdb9646-d9e4-4a2f-af23-f65b3f4a3ebf',1940,'湖北黄梅人','湖北黄梅人，伪黄梅县教育科科长，在黄梅推行奴化教育，篡改教材，宣传“大东亚共荣”，毒害青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf6b82a2ba52485897f8c4a83408945e','7ffac393-f6e1-4a78-88ec-d3c57284f5b6',1939,'湖北黄冈人','湖北黄冈人，伪黄冈县商会会长，为日军统制物资，强制商户缴纳捐税，配合经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-930e74db38f2455fb71931a858db4878','3f06fc8b-1458-4a96-b221-d0fc6e306135',1939,'湖北黄梅人','湖北黄梅人，伪黄梅县商会会长，协助日军征购粮食、棉花，压榨商户，为日军经济侵略服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe4a47df5e2b4792b19db451b5f438ff','7549b091-af60-4fa2-bb36-64518612f5b6',1940,'湖北黄冈人','湖北黄冈人，伪黄冈县宣传科科长，主办伪报纸和广播，散布亲日言论，为日军侵略张目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5bbffc6dbb2342d2a711c9f24fcb9c6c','d8b0ebe3-6099-4809-af10-8084255d098e',1941,'黄冈地区伪军头目','黄冈地区伪军头目，率伪保安大队配合日军对黄冈及龙感湖周边抗日根据地进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff9d26a69a254675add09dd767afbd1f','3aa68f71-0f10-4b23-9d2a-762e39033ef3',1940,'黄冈地区伪警察头目','黄冈地区伪警察头目，负责侦缉抗日人员、维持伪治安，协助日军镇压当地民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9ef46f827a740fdb56c1fefc84fd59f','7b7ee08a-a92f-4881-8130-d67fbca02ae5',1938,'浙江永嘉人','浙江永嘉人，汪伪政权核心成员，虽非黄冈籍，但作为汪伪高官参与伪政权决策，其统治体系覆盖湖北沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64a8bd9f9e8a43399b132e6a3044cbee','bed395bb-e6f2-49b7-80b7-f82d5f8f1b85',1943,'浙江昌化人','浙江昌化人，原军统人员后投敌，任伪税警总团副总团长，其伪武装在湖北地区配合日军行动。','危害等级C（丙级，基层头目）','hanjian');
