INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eab3108e41834fe5ac33b5add5acbbb5','a98ebe1f-6dcf-4371-b298-e12aa9039e1a',1938,'湖北黄冈人','湖北黄冈人，抗战期间滞留沦陷区，与日伪方面有联系，曾被日伪方面拉拢参与伪湖北省政权活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
