INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-231c0ff9aecc47fca630e5a4db224c5f','9f00e716-ff5c-4bec-b158-1f3c7608f156',1940,'出任伪阳新县县长','出任伪阳新县县长，配合日军在阳新、大冶边界地区进行清乡，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24c97dd5815b42749e59559287e01ad3','5b9d25cc-b3dc-46a7-943f-e0ed34e9b5ba',1940,'在鄂东地区组织伪军','在鄂东地区组织伪军，配合日军进攻大冶、阳新抗日根据地，活动范围覆盖黄石地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0debe8f055804acea9abd52e686f5b13','1da9c4e6-ce83-426d-a7b8-275f961bd48f',1938,'担任伪黄石港商会会长','担任伪黄石港商会会长，为日军筹款筹粮，协助日军控制黄石港商业与物资流通。','危害等级C（丙级，基层头目）','hanjian');
