INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9599267e7f8144f29cf315a53e4c9dd9','89fead22-b52a-4cb8-abcf-1dc2beaa6528',1938,'下陆地区沦陷后组织维持会','下陆地区沦陷后组织维持会，为日军征集物资、拉夫，协助日军控制下陆铁路与矿区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24f4a361038d4641b6b2dfa981631f16','61ff125b-4fbd-4b82-a83c-de7f5e09c919',1938,'抗战期间投靠日军','抗战期间投靠日军，参与组织伪政权，曾任伪湖北省政府主席等职，为日军在湖北地区的统治服务。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6761a23fd384399a45aa7b877df0094','61ff125b-4fbd-4b82-a83c-de7f5e09c919',1938,'湖北阳新人','湖北阳新人，早年曾任军阀师长，抗战期间投靠日军，出任伪湖北省政府主席等伪职，协助日军推行殖民统治，在湖北地区影响较大，其家乡阳新与黄石相邻。','危害等级A（甲级，特别市市长）','hanjian');
