INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2835c48e047e492aa2e209060ec9f0c9','0b3d34d1-be21-4e61-927b-0b2f4ad50320',1940,'组织伪保安团','组织伪保安团，配合日军在大冶及周边地区进行扫荡、清乡，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef4f65885007425c8c07b7a4bf2e0389','92e28ea4-499a-4872-942a-372e141777a3',1938,'黄石沦陷后依附日军','黄石沦陷后依附日军，以商会会长身份为日军筹款筹粮，协助经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-375822cbb87345c0ba5c492455d604d8','1e448ed5-9142-403c-8ac5-235405ffae38',1940,'在伪大冶县政府中负责教育事务','在伪大冶县政府中负责教育事务，推行奴化教育，宣传所谓“大东亚共荣圈”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4b9e9dc202e4e79801c13bb3e0e2d97','91e3fe19-de13-4ddf-945b-4e41d4ae60e8',1938,'黄石港本地士绅','黄石港本地士绅，日军占领黄石后出面组织维持会，为日军筹集物资、维持地方秩序，协助日军控制黄石港及西塞山一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78c8b6685c4442749f91d2e5e56f53d1','91e3fe19-de13-4ddf-945b-4e41d4ae60e8',1938,'黄石港地区维持会头目','黄石港地区维持会头目，日军占领黄石后出面组织维持会，为日军征集物资、拉夫、维持地方秩序，协助日军控制黄石港、石灰窑一带，铁山矿区亦受其影响。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9bd982ad0d3a464cbeeb2768713e15a6','8f0d81a7-eec6-4e29-9c93-7cfdc8339628',1938,'大冶县（今黄石市区及大冶市）人','大冶县（今黄石市区及大冶市）人，日军侵占大冶后投敌，历任伪大冶县维持会会长、伪县长，配合日军掠夺大冶铁矿资源，镇压抗日民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
