INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7d61ac8f6c144059b48c3e327b7e060','42bed66c-30ab-45aa-aa6c-7df63a3dcae0',1938,'石灰窑（今黄石市石灰窑区）维持会头目','石灰窑（今黄石市石灰窑区）维持会头目，日军占领后组织维持会，为日军提供情报、物资和劳工，协助控制石灰窑及铁山矿区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f7415b0c2fc4c299c9a59f51d30cbdc','3e7bc6d9-b91e-4a53-80a2-8bad588dfdb2',1938,'黄石港商会会长','黄石港商会会长，抗战期间与日军合作，为日军采购军需物资，协助日军对黄石港经济进行统制，压迫当地商户。','危害等级C（丙级，基层头目）','hanjian');
