INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-249615d918bc4d5bac4e87194257acc0','10a96ea6-2be0-4f78-8493-25425d3393fc',1938,'湖北阳新人','湖北阳新人，早年曾任北洋政府官员，抗战期间投敌，参与组织伪政权，任伪维新政府军政部长、伪湖北省政府主席，协助日军维持湖北沦陷区统治，其活动范围覆盖鄂东南包括黄石、铁山一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
