INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c0a232d5cc24b339767be945b172fcd','03312701-eae7-4c27-9608-deb4af25375b',1938,'黄石港本地士绅','黄石港本地士绅，日军占领黄石后出面组织伪维持会，为日军筹粮、拉夫、维持地方秩序，协助日军控制黄石港码头与矿区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae5aa6b3356c409c827bf480572e5502','87543bf6-d083-4534-a605-6c25baea5c68',1938,'黄石港商人','黄石港商人，抗战期间与日军合作，担任伪商会会长并参与维持会，为日军征集物资、管理码头工人，协助日伪经济掠夺。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c26ae60b4d84515b7b0e33c35d22582','56655101-c618-4dbc-b796-eb8d21d9b8e2',1938,'大冶县（今黄石市区）人','大冶县（今黄石市区）人，日军占领大冶后组织伪维持会，任会长，协助日军管理矿区、征发民夫，为日军开采铁矿提供劳力。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1bdb255dae34ea69874780167894429','b07dfae8-8ca5-4c6f-9eb9-722ccc8c2616',1939,'抗战期间任伪大冶县警察局局长','抗战期间任伪大冶县警察局局长，配合日军搜捕抗日人员，镇压地方抗日活动，维护日伪在大冶地区的统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e600f17a4a0145c5a5c3ffe5890dae08','dce8f5a7-8141-41d1-8f27-1db912a31b54',1938,'黄石港本地人','黄石港本地人，抗战期间担任伪保甲长，为日军征收粮食、税款，登记户口，协助日军控制黄石港居民，举报抗日嫌疑人员。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8ad17de68504047b22369cb0ec54f8d','688b63dd-5511-45ce-a843-523d1a8a24d1',1939,'黄石港码头工人出身','黄石港码头工人出身，投靠日军后组织伪工会，控制码头工人，为日军装卸掠夺物资，协助日军镇压工人反抗。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92476dc2ce8d4918b9ba74bf98cbb5ab','fbf4f366-ad33-42cb-b9ae-4f54369e95f8',1938,'湖北黄冈人','湖北黄冈人，抗战期间附逆，任伪湖北省政府委员，参与日伪政权决策，协助日军在湖北的经济掠夺与治安维持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9faf45122ce24dd5bdd778342376dc98','5ae26def-ee2b-4b25-855e-1c3fcd2bdcdb',1938,'湖北人','湖北人，抗战期间投敌，曾任伪武汉市市长、伪湖北省政府委员，协助日军管理武汉及周边地区，包括黄石一带的物资调配。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d719140036c44e129e9f9d14839492ac','e2d93b81-8108-4427-946e-c38ed844cb7b',1940,'抗战期间任伪黄石港税务局局长','抗战期间任伪黄石港税务局局长，为日伪征收税款，盘剥当地商民，协助日军对黄石港经济进行控制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-501f7074c3464c49afd9377e3d75c843','155171fe-9e00-4f42-98b4-a8538e104633',1939,'黄石港教育界人士','黄石港教育界人士，抗战期间附逆，任伪黄石港小学校长，推行奴化教育，使用日伪教材，向学生灌输亲日思想。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-878465eaa3824235894932a7ed2a9ef8','554459b1-8d27-4d6d-a3de-42e02b26b3bc',1944,'日军侵占双峰期间','日军侵占双峰期间，出面组织维持会，为日军征派粮秣、夫役，协助维持占领区秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a524e381f529491db51ee13ea89cab04','5e141a14-2ef9-4d2c-abbe-a5f4abde7576',1944,'在湘乡及邻近双峰地区充任伪警察头目','在湘乡及邻近双峰地区充任伪警察头目，配合日军搜捕抗日人员，勒索民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-092f9db329a547a395561f9b377b49f3','8b69f781-e195-4a0e-a4ba-2efc847d22b8',1944,'日军窜扰娄底时组织维持会','日军窜扰娄底时组织维持会，为日军筹粮、带路，并诱迫乡民归顺。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8db843ffaf6452e9bbdfb8fb8037a9d','1ea6cd30-44b4-4a53-b42d-269a1f5baf3f',1944,'抗战后期在湘乡沦陷区出任伪县长','抗战后期在湘乡沦陷区出任伪县长，秉承日军意旨推行伪化统治，征粮拉夫。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e1d7747121349c5854219ee15467ef9','49a9b384-f03c-4698-a40c-7959da050eef',1944,'在邵阳及邻近娄底地区参与维持会活动','在邵阳及邻近娄底地区参与维持会活动，为日军搜集情报、征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9f97ca4e8f64d228cc3823b1de9065d','e7640de9-2b54-4a96-81c7-eb4f0ad54f50',1940,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，虽主要活动于南京、上海，但作为湖南籍汉奸头目对湖南沦陷区伪政权有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1609bc5c9db445668c118e22332155c8','e7640de9-2b54-4a96-81c7-eb4f0ad54f50',1940,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对湖南等地的伪化宣传与策反活动，间接影响常德、临澧一带的伪政权建立。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9b0acc076ee4398b97d59b7e13ef119','12b7637d-6b0a-48c1-b720-2f27ce6443fb',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪，但公开附逆任职，在湖南籍汉奸中有一定代表性。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-40df9c0232044ec5902c79ea0b1a9643','12b7637d-6b0a-48c1-b720-2f27ce6443fb',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪内部，但在汪伪政权中担任要职，与湖南籍伪政权人员有联系，其活动范围涉及湖南。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31af3f9e86114dd385b2fc9959058e10','12b7637d-6b0a-48c1-b720-2f27ce6443fb',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪内部，但公开身份为汪伪高级将领，在伪政权中任职，与湖南籍军政人物网络有关联。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef3b645b50fb411eb1a3e831d84b393a','a32542db-39f6-466b-828b-2fea7001e375',1944,'日军侵占湘潭期间组织维持会','日军侵占湘潭期间组织维持会，为日军征粮、派夫，维持沦陷区秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-785d11b57c354a488eafc70e07f06c21','620fc6a4-b5ea-4f0c-b273-2956bdf20a9c',1944,'在湘乡、双峰一带收编游杂武装','在湘乡、双峰一带收编游杂武装，投靠日军，配合日军扫荡抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79e6f60f77214105a39cfc746f041750','cb9a12de-d264-4dc3-8bc2-57e6d438cfb6',1944,'在长沙沦陷区参与维持会','在长沙沦陷区参与维持会，协助日军征发物资，其活动范围涉及湘中地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60fde140f39149078e5ce73c56788486','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪政权，曾任伪军委会委员等职，在沦陷区活动，与湖南籍军政人员有联系，但其身份为军统潜伏人员，并非完全附逆。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-969eb686394f4734bc1183d0cc019d29','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，实为军统潜伏人员，在汪伪政权中任军事委员会委员等职，从事策反与情报工作。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2910f0d91b3c45f88d94749fb544a334','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实际从事策反与情报工作，属潜伏性质，与株洲、攸县无直接活动关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08c04c92eb69464c99798584635130af','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，表面附逆，实为重庆方面提供情报并掩护军统活动。其活动范围主要在江苏、上海，但与湖南永州东安有籍贯关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05bbdcd82a9c4c1ea47f4752fec1f315','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，表面任伪职，实际从事策反与情报工作。其活动与湖南永州东安有关联，但主要附逆任职在南京、苏州等地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6afd3f495f7641a49e8378d21c136626','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命潜入汪伪政权进行策反工作，但公开身份为汪伪高官，在沦陷区参与伪政权军事与清乡事务，与湖南籍军政人员联系密切。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9e76a4f31ec40debf889c40981bb1ae','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命潜入汪伪政权，表面附逆，曾任伪军事委员会委员等职，在江苏、上海一带活动，与湘潭无直接地域关联，但属湖南籍有明确记载的汪伪政权任职者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02c8ec598612485aaf383db0e0912c38','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，在沦陷区活动，与湘潭地区有间接关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f4f58995fae46e0b2d695fcf50952fc','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，表面附逆，实为重庆方面提供情报并掩护军统活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-739cde89121b4ffb9014ec500f2a469b','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任汪伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，表面附逆，实为重庆方面提供情报并掩护营救部分抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94744cc3dac04b90a731ba10e4c8c226','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，但在此期间公开附逆，任汪伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，参与伪政权军事与清乡活动，与湖南衡阳、南岳地区有籍贯及人脉关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44a2dc1c94ab42feb29c76b2db376552','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪政权，曾任伪军事委员会委员等职，在沦陷区活动，与湖南衡阳地区无直接任职关联，但属湖南籍附逆人员中较知名者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7dbc2593928d44aab06c443e8bd0903a','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命潜入汪伪政权，表面附逆，曾任伪军事委员会委员等职，负责联络策反伪军，抗战胜利后恢复国军身份。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1fa0a60b8bf54d828d5e9489891adbe1','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实际从事策反与情报工作，抗战胜利后恢复国军身份。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-352c6e122d8d4f34a4867a55ee2fd1ed','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪内部，表面附逆，实为军统潜伏人员，并非真汉奸。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b87a0134153c4baaad0a698c18bad563','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪政权，曾任伪军事委员会委员等职，在湖南及周边地区有活动关联，但身份具有双重性，历史评价复杂。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-601db31df6a4468a9687268a7ebd16e7','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，曾任伪军事委员会委员等职，从事策反与情报工作','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1736f42b3eb4f8284238eb06256e615','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'其活动主要在上海、南京、苏州一带','其活动主要在上海、南京、苏州一带，与湖南郴州、安仁无直接地方任职关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96e1d09a7b4144f491b303c3dbd4e6c9','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪政权，在江苏、上海一带活动，其活动范围未直接覆盖郴州宜章，但作为湖南籍伪政权高层被部分史料提及。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee56b2eb81f24c5c90376dd33fa20b15','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命潜入汪伪政权，表面任伪职，实际从事策反与情报工作，属特殊历史人物，常被列入湖南籍附逆人员讨论范围。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c511a14fb73c40c2bfc14f64f91f0f17','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，奉蒋介石之命打入汪伪政权，表面任伪职，实际从事策反与情报工作','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23ab3f89dc9b480fa33409069d8ed3ca','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'其活动范围主要在江苏、上海','其活动范围主要在江苏、上海，但与湖南籍军政网络有联系，常被视为抗战时期湖南籍伪职人物中需辨析者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-593d638902a6432aafa4b7c7bb5b0734','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，但在汪伪政府中公开任职，参与伪军事与清乡事务，与长沙、湖南地区有籍贯及人脉关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96e321e0d33647419821a1b8dbeca4e2','9ffc1d82-762c-4ce3-8b50-a284a696cb8e',1940,'湖南东安人','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，在沦陷区活动，与长沙、湖南有籍贯关联，但其主要活动区域在江浙，属于有明确历史记载的湖南籍附逆人物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b500047c6de4f53b9278797bf0eb080','1ded2c43-5fe5-4fc9-a126-a6079b802773',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，推行伪化统治，其活动范围涉及华中、华东，与湖南籍人士有较多联络。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-522f39897fed4e0880539d3e0c870b3a','68565ed6-b34a-4aea-81d0-0b6c7b86c651',1938,'虽为广东籍','虽为广东籍，但作为汪伪政权主要头目，其伪政权统治体系覆盖包括湖南在内的华中地区，对湖南沦陷区伪组织有统辖关系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f45d4c3b12aa430e9a41c3dfaedae043','68565ed6-b34a-4aea-81d0-0b6c7b86c651',1938,'湖南籍（祖籍湖南）','湖南籍（祖籍湖南），汪伪政权主要头目之一，其伪政权统治体系覆盖包括湖南在内的沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c03bc41c48e74366b781b618e1277219','68565ed6-b34a-4aea-81d0-0b6c7b86c651',1938,'广东乳源人','广东乳源人，汪伪政权二号人物，虽非湖南籍，但其伪政权体系覆盖湖南沦陷区，对湖南伪政权有统辖关系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1396e7824434bcc81c11b5ff1105f5a','68565ed6-b34a-4aea-81d0-0b6c7b86c651',1938,'广东乳源人','广东乳源人，汪伪政权主要头目之一，追随汪精卫叛国投敌，其伪政权统治覆盖华中、华南，包括湖南部分地区，但与郴州、汝城无直接活动记载。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f8e23e20be24033aee56501276878d2','bc00fc2e-f44d-4ecf-aecf-11565cd0808c',1939,'湖北人','湖北人，汪伪军事头目，曾负责伪军扩编与清乡，其伪军活动范围包括湘北、鄂南，对湖南北部沦陷区有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c93de44798b0442b9b5dd9b8618e0438','9de891dc-364d-40c3-a195-081d1f4cf2ad',1940,'河北人','河北人，西北军旧部，投汪后负责河南伪军，其伪政权与湖南无直接统辖，但属汪伪体系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-beab4a8fe52a4c40b2801244a5c7d6a9','8269830c-e7f7-45d1-a283-3b4e301548b0',1943,'浙江人','浙江人，汪伪地方要员，活动于浙江，与湖南无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6cbf5a42147943828ec6dbf928279e44','981c9a86-8048-4470-baba-2193d9190191',1940,'浙江人','浙江人，汪伪政权文职要员，活动于华东，与湖南无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92f37b4bd0c54985aaed48ca4a8b9804','10b6eb0e-e64c-456d-8c81-9bb7e74fe1d6',1940,'江苏人','江苏人，汪伪地方要员，活动于皖、赣，与湖南接近但无直接统辖。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76a5adfef4fe4befa2299b068834fa7f','a72f049c-1a2c-4daf-a69e-e555e7492bae',1940,'湖北人','湖北人，汪伪湖北省要员，其伪政权与湘北沦陷区有接壤，对湖南北部伪化有一定影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a76d6e2bdaf41f18a59bdfaa10ddac5','efc9d827-3392-4819-99c2-508f93f7f234',1938,'湖北人','湖北人，伪湖北省政权头目，活动于武汉及鄂中，与湘北接近。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03635fc6070f4027aaa92ce004e138ba','34e71e27-2ad8-4e27-8655-80afab7b8570',1944,'在日军侵占湖南部分地区后','在日军侵占湖南部分地区后，曾参与伪湖南省政权筹备活动，但伪省政府未正式成立，具体活动记载有限。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f509beb2330b4343955edb5ca1996822','54e4da1a-f359-4af1-90db-82681987c9d7',NULL,'经查','经查，新化、娄底地区在抗战时期有明确记载的汉奸名录极少，地方志中多记载抗日志士而非附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
