INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f4cdf9793a04687a2f34e7785108bb9','6598acea-30f5-49d5-bfe9-f945056ae426',1943,'抗战后期在湖南伪政权中任职','抗战后期在湖南伪政权中任职，协助日军整编伪军，其活动范围涉及湘西部分地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38e2a56b170642b2a524a5966e67e7c2','6598acea-30f5-49d5-bfe9-f945056ae426',1943,'受重庆方面派遣潜伏','受重庆方面派遣潜伏，但公开身份为伪职，在湖南伪军中任职，与邵阳地区伪军有联络。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a0d2e19037d44a0b3ca02a7736375c4','4545ef2e-9443-4710-8102-d4a702a01422',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设，虽主要活动于南京、上海，但作为湘籍汉奸代表人物，其伪政权体系对湖南沦陷区有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-039c1fe64d0840d4ba5647c84c465f6e','4545ef2e-9443-4710-8102-d4a702a01422',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对日投降与伪政权建设，推行伪化统治，为日军侵华提供财政与行政支持。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-774363c4c375409aad5601a1207b437e','1de526c9-f50c-4445-83f5-fcce90894708',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪内部，但公开身份为汪伪高官，参与伪军与清乡事务，与湖南籍军政网络关系密切，常被视为灰色人物。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8da123edd8d342abae93bfffbceb0a16','9c0215ec-3371-48df-a9c9-b0fbb2e9b905',1939,'湖北黄陂人','湖北黄陂人，长期在武汉及鄂湘边界活动，其伪政权与伪军势力覆盖湘北、岳阳一带，配合日军对湖南沦陷区进行控制与清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24a02ec6177b46a6a84ddecbca72050b','b1358032-e199-49fa-8b8b-05363ae0471d',1943,'在鄂湘边界及岳阳、华容周边活动','在鄂湘边界及岳阳、华容周边活动，曾率部投靠日军，编入伪军，配合日军在洞庭湖区域进行扫荡与治安作战。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa92e52db4664468b1931f8f1203a70b','96d242fd-400f-4a44-9372-3232fcb4fc46',1943,'华容沦陷期间组织维持会','华容沦陷期间组织维持会，为日军征粮、征夫，协助建立伪基层政权，控制华容及洞庭湖西岸部分地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8aac4185e01d4646bcdb13a430b43b9a','be50dd03-3b00-41a3-905d-f3c4e1d7b5a7',1940,'在日军扶植下出任伪岳阳县长','在日军扶植下出任伪岳阳县长，推行保甲制度，配合日军清乡，镇压抗日活动，控制岳阳及临湘、华容交界地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b16b06a71c864343a1830e4616cd40c8','39be7a5f-29d6-4b00-bc66-798ffcc3ab78',1941,'统率伪保安队配合日军在岳阳、华容、南县一带进行扫荡','统率伪保安队配合日军在岳阳、华容、南县一带进行扫荡，搜捕抗日人员，强征民夫与物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cc54f1bdc7a423e815c485b0567fcf0','42f4b5c1-7adb-4775-b490-2070a327e0c1',1941,'在汪伪湖南省政权中任职','在汪伪湖南省政权中任职，参与清乡计划，其活动范围涉及湘北岳阳、华容等沦陷区，协助日军推行治安强化。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2a56de34dc542d7af94942f0923948e','730b910b-7ce4-4357-b391-d54c5fd5e54f',1942,'岳阳华容交界地区伪保长','岳阳华容交界地区伪保长，为日军征粮派款，监视村民，协助日军维持基层统治。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c104b5bb6514a17af46565d7662147d','50c18d1b-629e-4159-9f71-2e7781de42fb',1940,'在伪岳阳县政权中任职','在伪岳阳县政权中任职，参与伪政令宣传、物资统制与情报搜集，协助日军控制岳阳城区。','危害等级C（丙级，基层头目）','hanjian');
