INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2ff65d555ce41da97d97e9ba6259d95','b1f2982e-dfc6-4402-94f7-e01f5181aa05',1931,'北洋旧军阀','北洋旧军阀，九一八后与日方勾结，被日方委为伪湖南省长，企图在湘北一带组织伪政权，后因内部矛盾未成，1933年被刺杀。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea676906375843e3bd9e2946b5bd57f0','abd31a75-6429-4f9d-9f9f-7542cd340f3c',1941,'原国民党苏鲁皖游击副总指挥','原国民党苏鲁皖游击副总指挥，1941年率部投敌，所部伪军曾活动于长江中下游，与湖南岳阳、汨罗一带的伪军有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
