INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e77dc9fc37f4769a1b6ecf9094fa173','5d8d250c-477a-4ae9-a442-74a304557b4a',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪内部，表面附逆，实际为军统提供情报，战后被认定为潜伏人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
