INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8a8b8f5126d3487a85cef67977d5b331','a57d6657-563f-4fce-b825-b15d7ad739f2',1943,'率部投靠日军','率部投靠日军，编为伪保安团，在安乡、南县一带配合日军扫荡抗日武装。','危害等级C（丙级，基层头目）','hanjian');
