INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ed9c74472df4c348b274461a741e397','b1911520-f05c-41bd-8214-b25430636926',1938,'岳阳沦陷后组织维持会','岳阳沦陷后组织维持会，控制洞庭湖区域物资运输，为日军提供船只和情报，影响波及常德、安乡水路。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0dd29494e4a24deebc15f089939497d3','3e0e155d-6a97-41b1-9bd7-c6e1f61736bb',1943,'原国民党军将领','原国民党军将领，1943年被俘后投靠日军，在湖北、湖南交界地区组织伪军，活动范围接近常德、安乡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3168974aa5c4319aa646346aa0d42b9','30a41d00-fcc2-4161-9d46-9ee1f55c6b2f',1944,'在汪伪湖南省政府中负责教育','在汪伪湖南省政府中负责教育，推行奴化教育，篡改教材，宣传“大东亚共荣”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b6425f7228948c5beaec9d6e711667f','445b447d-25f0-4619-adf3-8aff20dca3fc',1938,'湖南沅陵人','湖南沅陵人，汪精卫伪政权核心人物之一，参与筹建汪伪政权，历任伪行政院副院长、财政部长、伪上海市长等职，推行伪化统治，为日军侵华服务。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdd77b0c2c414500832d27f4eed9e5bd','f80692b9-6ece-4983-a6ef-7619592ef41b',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪内部，但公开身份为汪伪军事委员会委员等职，在沦陷区活动，与常德地区日伪势力有联系。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c76737355814c159622f419fd5cb900','f80692b9-6ece-4983-a6ef-7619592ef41b',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪政权，但在汪伪中担任军事委员会委员、伪清乡委员会副秘书长等职，参与伪政权军事与清乡事务，身份具有双重性，常被列为附逆人员。','危害等级B（乙级，市县厅局级）','hanjian');
