INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-519b629c6d0f48f09126c1bc187a93eb','f80692b9-6ece-4983-a6ef-7619592ef41b',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪内部，但曾公开附逆任职，参与伪军与清乡事务，与湖南籍军政网络有联系，其活动涉及华中沦陷区包括湖南周边伪政权运作。','危害等级B（乙级，市县厅局级）','hanjian');
