INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7edee4c12cbc4f90a3c9e673a988c953','2b26a14f-9d46-4a4a-b205-ef8ab1b58976',1943,'常德沦陷后投靠日军','常德沦陷后投靠日军，担任伪警察局长，协助日军搜捕抗日人员，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a0069653567498e93eae7bb99dde721','39306a4e-f06b-40c5-96cc-36703b435154',1943,'常德沦陷期间','常德沦陷期间，以商会会长身份与日军合作，强制商户缴纳“治安费”，为日军筹集物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f30791f2b7c24c6ab9535ea98a88000b','6f89ae3f-ebcc-4614-bdca-ed6ce634c128',1944,'组织伪保安团','组织伪保安团，配合日军扫荡桃源山区抗日游击队，抓捕抗日家属，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6595a509cfe48749c06896e043d321b','fea8fae8-f001-46e2-a905-95644582b3dd',1943,'在常德推行奴化教育','在常德推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”，毒害青少年。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aac2e36e98ab46fbbe8522afbc64672f','8186ce9b-c35f-4a22-a866-eb90effeb5e1',1943,'担任常德城区保甲长','担任常德城区保甲长，为日军清查户口、举报抗日分子，协助日军征发劳工。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95b06abdb00c46298c2f09a16b0969fa','4fab2e20-0f36-4dd0-949e-ed1dd0d7ef85',1938,'湖南沅陵人','湖南沅陵人，汪精卫伪政权核心人物之一，参与筹建汪伪政权，历任伪行政院副院长、财政部长、警政部长、上海市长等职，推行伪化统治，为日军侵华服务。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc0c242c0f7d49df8ef3cde3ae859093','4fab2e20-0f36-4dd0-949e-ed1dd0d7ef85',1938,'湖南沅陵人','湖南沅陵人，汪精卫伪政权核心人物之一，参与对日投降与伪政权建设，推行伪财政与警政体系，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da58bfc6ca8640b5bcd943eff4832ccb','4fab2e20-0f36-4dd0-949e-ed1dd0d7ef85',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对日投降与伪政权建设，虽主要活动于南京、上海，但作为湖南籍汉奸代表人物，其附逆行为对湖南沦陷区伪政权体系有示范与影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2eec4887662e4aa79bc4510c47800b7d','7193f2c7-3762-4005-98c5-6a3eb99a8391',1943,'湖南长沙人','湖南长沙人，汪伪政权高级军政人员，曾任伪湖南省政府主席，在湖南推行伪化统治，配合日军维持占领区秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cd19aea7bd9441e96e63d71d16fd4d7','416497c0-bd6f-4e0c-a65f-730d5050e3c3',1939,'湖北黄陂人','湖北黄陂人，汪伪政权军事要员，曾任伪湖北省政府主席、伪武汉绥靖公署主任，其势力范围覆盖湘北、鄂南，与常德地区邻近，参与伪军扩编与清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d68286edd1fc4c5ba785b29806eb2975','4742f109-995a-4f0b-ae55-058a2974ca22',1943,'原国民党军将领','原国民党军将领，1943年被俘后投敌，所部被编入伪军，活动于湘鄂边区，与常德、武陵地区邻近，参与伪军对抗日根据地的骚扰。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cc7408c900e4dd1b022c4acdf5d4313','f0f55894-e808-4155-9cd6-d4d52bfdf8f7',1943,'常德地区伪军头目','常德地区伪军头目，组织伪保安团配合日军扫荡，控制常德周边乡镇，为日军征粮征夫。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-490b6664615a43768efdffd2bf2e4e12','3f45fcc2-aae7-44c0-95dd-10f79367d4a2',1943,'武陵镇沦陷期间任维持会会长','武陵镇沦陷期间任维持会会长，为日军筹粮筹款，协助建立伪基层政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cfde6d27aa8147079baf9f168715260a','1343f381-ee69-47cc-8089-ad572a69ef04',1943,'在常德沦陷区推行奴化教育','在常德沦陷区推行奴化教育，改编教材，宣传“大东亚共荣”，协助日军进行文化渗透。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-434ef33a11b9415084498ee35383ddc4','eefcc7c3-ffc6-4e38-bc58-9dacb01385f6',1944,'湖南人','湖南人，汪伪湖南省政府委员，参与伪政权在湖南的行政事务，配合日军维持占领区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38832a5579444f75b1cb754f4e707c1c','0855a8b8-b081-4f9c-aab2-a3b0e30120b8',1944,'汪伪湖南省警务负责人','汪伪湖南省警务负责人，在湖南占领区推行伪警察制度，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c710aeeb0b049e8af19709f33c94b79','06ff8413-39c7-4a78-8c6d-2f7313bbcd84',NULL,'无','无','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d1dc1a3308546f39cc5452d71a6df64','8992ee9f-e109-432a-b711-69a52366dff9',NULL,'常德沦陷期间','常德沦陷期间，出面组织伪维持会，为日军征集物资、拉夫，协助日军维持城区秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b7bd9fdeabb4259be2b4c830233527d','99009636-05d9-4052-a4d4-75f4b7d0fda4',1943,'在常德、汉寿、沅江一带收编土匪','在常德、汉寿、沅江一带收编土匪，组织伪军，配合日军扫荡洞庭湖西岸抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ec4c065475b4a89a8229c8c8f85d685','adf715ed-ed85-4192-a9a8-6bb4dfd6de0d',1940,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对湖南沦陷区的伪化统治与经济掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
