INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4029677549fb40bda94b6775c2f0143d','fb391bd2-8d62-4a8d-8c99-7492c4eaaee9',1943,'原国民党军将领','原国民党军将领，1943年被俘后投日，在湘北、鄂南组织伪军，配合日军进攻常德、津市一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-384b2bfb50aa4e3a9b6fc360746e082b','8b8c2ed6-3048-4492-b006-7b234c935fba',1944,'湘西地方实力派','湘西地方实力派，抗战后期与日伪方面有秘密接触，但未公开投敌，历史评价复杂。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-322a9580c22b415c8c9f5897af3668c8','4946bcd0-f623-4e47-bd3e-ac18d070e2dc',1940,'湖南湘乡人','湖南湘乡人，汪伪政权重要成员，参与伪政权对华中沦陷区的统治，包括湖南部分沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19a4f9ace1544269b0547864b937fbb4','d9edb17f-8cd1-4a42-9859-e5d28d1ee5a5',1943,'常德会战期间投靠日军','常德会战期间投靠日军，组织伪清乡队，在常德、桃源、汉寿交界地区搜捕抗日人员，勒索百姓。','危害等级C（丙级，基层头目）','hanjian');
