INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b53635cbf54240dca1ca71e20119dbb4','e167390a-a281-4ede-952e-b66478fcaca7',1943,'常德沦陷期间组织伪维持会','常德沦陷期间组织伪维持会，为日军征粮、拉夫，协助维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad3aa6ee27c54277a208d1a6803fa534','674d2aae-c9e8-4fa0-89dc-b59e73e3b94f',1943,'澧县沦陷后出面组织伪维持会','澧县沦陷后出面组织伪维持会，替日军摊派物资、征集民夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f24598e9a4144c33b1db7dd7b8829bf4','66aa38cd-8567-49a0-af8d-b791181bce0a',1943,'在常德沦陷区组建伪警察队伍','在常德沦陷区组建伪警察队伍，配合日军搜捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e2bfe93839b4d1b855e0508bddd13f4','0a4ac750-e15f-408a-97e6-eef13efee5a5',1943,'率部投敌','率部投敌，在常德、澧县一带为日军担任外围警戒与扫荡任务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b21f815de76421bacc19ef4c32a33f6','0df96a0a-e941-451d-875a-4cac6208a28d',1940,'汪伪湖南省政府成员','汪伪湖南省政府成员，参与推动湖南沦陷区伪化政权建设。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2646e6c32a6446059b4b7bd174ef5581','31340b4b-7263-4abc-81ef-b0b140228de0',1940,'湖北黄陂人','湖北黄陂人，汪伪高级军政人员，其伪军活动范围毗邻湖南常德、澧县地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71c6a8c67ff344f8af74a91fca5ef295','bf030958-674e-417d-b735-4b745c1016fd',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪内部，在伪政权中任职，参与伪军与清乡事务，但其身份具有双重性，历史评价复杂。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ca40c3f685346f4888b78e4275b2d5a','80ae28ee-86ab-42e0-9d9e-be257085217d',1939,'湖北黄陂人','湖北黄陂人，长期在湘鄂地区活动，投靠汪伪后负责伪军与绥靖事务，配合日军对湖南等地进行扫荡与清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5362c71b0134fc8be9b37071d29bd31','a07c4b5a-6370-499e-ba29-d612439db7dc',1943,'常德地区沦陷期间','常德地区沦陷期间，有地方维持会人员协助日军维持秩序、征发物资，但具体姓名与事迹记载零散，常德本地汉奸名录多散见于地方志。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
