INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae449d26a60b4fcd9029e22c8699cfe2','522febc0-aee0-4dc8-b21e-4372149246aa',1943,'湘北沦陷区伪军小头目','湘北沦陷区伪军小头目，率部配合日军扫荡，勒索地方，具体事迹见于常德地区文史资料。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
