INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6b800957c6b4686970c96c60c297b10','358304ae-6a79-4398-947c-75d54e1d014f',1943,'澧县与石门、常德接壤','澧县与石门、常德接壤，沦陷期间伪维持会配合日军统治，征粮拉夫，地方文史资料中有相关记载。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
