INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9dfc5b2f4ee144a2a258eacdd1aaf16f','31e13fb0-916e-4b21-b99b-5703d506adb5',NULL,'常德沦陷期间出面组织伪维持会','常德沦陷期间出面组织伪维持会，为日军征集物资、维持占领秩序，协助日军搜捕抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad8efbc2aa5f49dababe25d517f17e82','6106f39a-bd7c-46c6-9d7b-0e4b37a9d898',1943,'日军占领常德后受任伪县长','日军占领常德后受任伪县长，组建伪县政权，推行保甲连坐，为日军征粮征夫。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85e4deef02534d6d86f699c826c381cc','57c677d9-0e5d-4003-8046-af55bd8caeef',1943,'在常德沦陷区组建伪警察队伍','在常德沦陷区组建伪警察队伍，配合日军清查户口、抓捕抗日嫌疑人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4998a2c36927410cb09513682480f783','72655dcf-0ba0-4bcd-9773-11ecf2df30b2',1943,'在鼎城地区组织维持会','在鼎城地区组织维持会，为日军筹粮筹款，诱迫当地士绅附逆。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03e0e77aa7d44607b254ccef5f265b9a','79b25a75-73cc-4760-88cf-37284c8d166e',1944,'率伪保安团配合日军扫荡常德周边抗日游击区','率伪保安团配合日军扫荡常德周边抗日游击区，捕杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf3c157bcb034835a50ea7650ef7f184','39845171-4e93-44f7-8d28-bda702ffe5b9',1943,'作为汪伪政权核心人物','作为汪伪政权核心人物，主导湖南沦陷区伪政权建设，推行奴化教育、经济掠夺政策，其势力覆盖常德地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1cde1601436464391453cf5b94843d6','20bb65a4-915c-40c7-add8-2c4066345f9f',1943,'在湖南沦陷区任职伪保安系统','在湖南沦陷区任职伪保安系统，协助日军维持占领区治安，其活动范围包括常德一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e4f65c29b5947179effa842524f86fb','979f8735-da99-4192-aa8e-39f893fa2866',1943,'参与汪伪湖南省政','参与汪伪湖南省政，推行保甲制度与物资统制，常德地区伪政权受其节制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a12fb5846114f84a731c253394ff01f','aa355b26-5bff-4b41-9a21-24c3e16ab5e4',1944,'继周佛海后掌控湖南伪政','继周佛海后掌控湖南伪政，继续推行附日政策，常德伪县政权向其汇报。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd47ac157e224103945d1cb7d4fab838','2a60c787-3b66-45e2-919e-580e2bd703e6',1944,'负责常德地区清乡工作','负责常德地区清乡工作，配合日军搜剿抗日武装，强迫民众登记良民证。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6d10c7a7d7b4c48ae7267b2b68f7209','9f80b04a-05d4-4047-8428-52923904ad4c',1930,'湘西古丈、沅陵一带土匪','湘西古丈、沅陵一带土匪，抗战时期与日军及伪政权有联系，在湘西北地区活动，其势力范围接近张家界、桑植地区，曾协助日军维持地方秩序并镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6c4c78ef674471e911816ecf01b003f','aec88759-0303-422a-9264-a89d752102e4',1930,'湘西龙山、桑植一带土匪','湘西龙山、桑植一带土匪，抗战时期曾与日军勾结，在湘西北地区活动，其势力范围覆盖桑植周边，配合日军进行地方控制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98404d428fc44834b25c96df838889e7','aec88759-0303-422a-9264-a89d752102e4',1930,'湘西龙山、永顺一带土匪首领','湘西龙山、永顺一带土匪首领，抗战时期曾与日伪方面有联系，接受伪军委任，在湘西地区扩张势力，对抗地方政府和抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c03e903adc584bc3a380ff6f9917a3c3','81dfb066-746a-444f-b97e-a23218d70468',1930,'湘西永顺、桑植一带地方武装头目','湘西永顺、桑植一带地方武装头目，抗战时期曾与日军合作，在桑植及周边地区参与维持会活动，协助日军征粮、拉夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73911735f253405fbec3ef1168391f24','4b3f946b-c7ca-4a6d-bf9a-4a1f5c93cbb1',1930,'湘西地方实力派','湘西地方实力派，抗战时期曾与日军及伪政权有暧昧关系，其势力范围覆盖湘西包括张家界、桑植地区，在日军进攻湘西时未积极抵抗，部分部下投敌。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-504ccbcfa8c9484681a86fb76b878bc2','ddb642b2-8855-49c4-91c7-b4e9c9b2a5af',1940,'原国民党军将领','原国民党军将领，抗战时期投降日军，在湖南地区组织伪军，其活动范围涉及湘西北，曾配合日军进攻湘西抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd42d08a01a749d8ba13cbe7e9924a5a','0bab8233-880f-4a6a-ac90-1205f23c9e90',1940,'湖南地方士绅','湖南地方士绅，抗战时期在湘西北地区组织维持会，协助日军管理地方，其活动范围涉及张家界、桑植周边地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38c51ed3c77445f8861a3588baa59716','d9e6fce2-a58e-4a19-ac40-0b17f9fd7958',1940,'湖南伪警察系统头目','湖南伪警察系统头目，抗战时期在湘西北地区协助日军维持治安，镇压抗日活动，其管辖范围涉及张家界、桑植一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27dee68c4602402aa749785fc11bb657','6a8d6fe0-7df9-4b10-be15-fcd213e0c10b',NULL,'经检索','经检索，张治中为抗日爱国将领，非汉奸，不应列入。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cfc897b991cb44ee9e3f6b2a24d8a0d8','0114fb9d-31dd-4199-8085-61147c4b9a80',1940,'湖南湘乡人','湖南湘乡人，早年加入中国共产党后叛变，抗战期间投靠汪精卫伪政权，历任伪中央政治会议副秘书长、伪司法行政部部长、伪上海市政府秘书长、伪湖南省政府主席等职，参与推行伪化统治，为日军侵华服务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eed6b0562c37408e9e1169e147d96cc4','0114fb9d-31dd-4199-8085-61147c4b9a80',1940,'湖南湘乡人','湖南湘乡人，早年加入中国共产党后叛变，抗战期间投靠汪精卫伪政权，历任伪中央政治委员会委员、伪司法行政部部长、伪上海市政府秘书长、伪湖南省政府主席等职，参与推行伪化统治，为汪伪政权重要成员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47426d10111f43d993823f8ddbbde115','d48e2036-cbeb-4ab6-9f1a-b0d6d202bf9d',1940,'湖南东安人','湖南东安人，抗战期间受蒋介石派遣打入汪伪政权内部，任伪湖南省政府委员、伪军委会委员等职，从事策反和情报工作，但其公开身份为汪伪政权要员，与湖南地区伪政权有直接关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
