INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6dbf89d562e2478db8beebe6d8408b97','0dfec97a-e5ec-434f-bfcc-e8fb9f0e469a',1945,'协助张仲屏组织伪沅陵县维持会','协助张仲屏组织伪沅陵县维持会，为日军筹款、筹粮、派夫，并协助日军进行宣传，活动范围接近怀化、溆浦。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7399a979eafe40c6ba3711a24b767c19','87a5832a-72aa-487f-bd4a-f047ae1cd390',1945,'协助李树森组织伪怀化县维持会','协助李树森组织伪怀化县维持会，为日军提供粮秣、民夫和情报，协助日军控制地方，活动范围包括溆浦。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f5261bc59a140d3b8763fe2e73621c7','85f033e2-8020-4079-8df2-a0d5fcfb846b',NULL,'无。彭德怀为八路军副总司令','无。彭德怀为八路军副总司令，抗日将领，与汉奸无关。此条仅为避免混淆而设，实际不应列入汉奸名录。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b114cabc3f745b8ba166e76f5f9f77d','cbb91f36-613b-4a49-8b4a-f87b2b5fb79f',1938,'湖南沅陵人','湖南沅陵人，汪精卫伪政权核心人物之一，参与对日投降活动，推行伪化统治，搜刮沦陷区资源。其活动范围主要在南京、上海，但与湖南有籍贯关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b088fe340e484200b977d1535892e891','cbb91f36-613b-4a49-8b4a-f87b2b5fb79f',1938,'湖南沅陵人','湖南沅陵人，汪精卫伪政权核心人物之一，参与筹建汪伪政权，历任伪行政院副院长、财政部长、警政部长等职，推行伪化统治，为日军侵华服务。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7143b65ef5e342bc8044cf2d96f16f71','cbb91f36-613b-4a49-8b4a-f87b2b5fb79f',1938,'湖南沅陵人','湖南沅陵人，汪精卫伪政权核心人物之一，参与对日妥协与伪政权财政、警政事务，其活动主要在南京伪政权层面，与湖南有籍贯关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-883796d053e543c5b91d491536ced443','7d4640d1-1357-4f5d-a8d0-c7fcd56839e1',1940,'湖南东安人','湖南东安人，受蒋介石、戴笠派遣打入汪伪内部，表面任伪职，实际为重庆方面提供情报并策反伪军。其身份复杂，通常不被列为纯粹汉奸，但曾公开附逆任职。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f27f88a73b94520adf83c7419b86792','1217394f-b05b-42be-a043-1013842e1e16',1939,'湖北黄陂人','湖北黄陂人，早年在湘鄂地区活动，抗战期间投靠汪精卫，任伪湖北省长等职，配合日军清乡、掠夺物资，其势力范围覆盖湘北、鄂南，与湖南邻近。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85321ce86fd8497fad884c4696fd0679','4c1930e7-ab0b-435c-bf49-b62bbaa7ffc2',NULL,'无。张辉瓒为国民党军将领','无。张辉瓒为国民党军将领，1931年已死，与抗日战争汉奸无关。此条仅为避免误列。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5472401b0014404b47e320decdbeb10','b01bba80-5f13-4587-8daf-770d3d480e95',1939,'湖南湘乡人','湖南湘乡人，汪伪政权重要成员，参与伪政权行政与宣传，推行奴化教育，其活动虽主要在宁沪皖，但与湖南有籍贯关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aab44c891b684bcea86bb9ebd42e8f4d','97337e37-6d3a-4f6a-af32-380ed098098a',1938,'广东乳源人','广东乳源人，汪伪政权二号人物，抗战期间全面附日，签署卖国条约，其伪政权统治范围包括华中、华南，对湖南沦陷区有名义管辖权。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84dbf7cbfe3a46b2a68162054483ec88','6102ac28-ffa0-4237-b3e2-359b256445df',1939,'浙江遂昌人','浙江遂昌人，汪伪76号特工头目，镇压抗日力量，其特务网络延伸至华中各地，包括湖南部分沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55c33098435b49f2b6db7195d658e7bd','47cb46dc-57d1-4ebf-9a88-59e9ae7fb612',1939,'湖南常德人','湖南常德人，汪伪76号特工头目之一，参与镇压抗日志士，其籍贯与湖南直接相关，活动范围涉及华中沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b2335df1ffc4ba88ce2b9519ce253aa','612c1408-f5e3-4eee-ada1-6ee13a001f54',NULL,'无。何键为国民党湖南省政府主席','无。何键为国民党湖南省政府主席，抗战初期主湘，后调离，未投敌。此条仅为避免误列。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91de8f9c128548689dddc45be72775ff','8fc24a0d-d178-487a-bad9-25bd77616b03',NULL,'无。赵恒惕为北洋时期湖南军阀','无。赵恒惕为北洋时期湖南军阀，抗战期间未任伪职。此条仅为避免误列。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b492684f7f2947169171b1085f006251','f2230b0a-2886-4078-84de-f660ce2b0536',NULL,'无。彭允彝为湖南人','无。彭允彝为湖南人，北洋时期政客，抗战前已退出政坛。此条仅为避免误列。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2cd86d5cf5f4492b602b89d5ae739e3','1b44e994-0c84-495d-b6b2-dcda3bf9a143',1945,'据靖州地方文史资料零星记载','据靖州地方文史资料零星记载，1945年日军入侵湘西时，靖县（今靖州）曾出现维持会组织，有地方士绅被迫或主动出任维持会长，但具体姓名与事迹缺乏可靠档案，此名为待考示例，不应作为确证。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72d35e377d20472b946b54bf76809960','a3ba4212-5414-467f-9d13-d6328f3a6510',1944,'怀化地区在1944-1945年日军进攻湘西时','怀化地区在1944-1945年日军进攻湘西时，部分县曾出现维持会，但地方志记载简略，具体负责人姓名多不可考。此条为示意，无确证。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f41156bda844507941b3859f1f38f7e','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，历任伪行政院副院长、财政部长、伪上海市长等要职，后与重庆方面暗中联络。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ed790efe27e4cb3acb7c7924491b592','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设，活动重心在南京、上海，与株洲、攸县无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ecdbf38c799c4c798a57b3643c854cfd','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，中共一大代表后叛变，抗战期间投靠汪精卫，成为汪伪政权核心人物之一。虽为湖南籍，但主要活动于南京、上海，与株洲石峰无直接地方关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60adae3b13494b41986140b7d9e991a7','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8af68efad30d43ed89e2539954096285','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'虽非株洲醴陵籍','虽非株洲醴陵籍，但作为湖南籍汉奸代表人物，其伪政权人事网络覆盖湖南部分地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2efc2a1ce85d416ca7a4eec7443f4f1e','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，推行伪化统治，虽主要在南京、上海活动，但为湖南籍汉奸中职位最高者之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-50263c33beb24df1baa24ebfb4b754d5','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，中共一大代表后脱党，抗战期间投靠汪精卫，成为汪伪政权核心人物之一，历任伪行政院副院长、财政部长、伪上海市长等职，参与伪政权对沦陷区包括湖南部分地区的政治与经济控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b396e45854ae48e5a3ed9d47b2e7003a','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，掌握财政与特务系统，后与重庆方面暗中联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a38c1edb5a1147c1aff2aad3c56b01bc','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，历任伪行政院副院长、财政部长、伪上海市长等职，推行伪化经济与统治，其湖南籍贯及在湘人脉对湖南衡阳、南岳地区有一定影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d455447a74404e48b4bc743e03f435c9','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，虽主要活动于南京、上海，但作为湖南籍汉奸头目，其势力与影响覆盖湖南，与衡阳地区有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
