INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c34e1acfa13f410bad5e5a8f8ed056b4','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设，虽非衡阳本地任职，但作为湖南籍汉奸代表人物，其伪政权体系对湖南沦陷区有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
