INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-037a9e94c173446da116a8b5218dd096','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'其活动中心在南京、上海','其活动中心在南京、上海，与郴州、安仁无直接地方关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aecbf5bc06bf4306afe7623ee82be487','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，推行伪化统治，虽主要在南京、上海活动，但作为湖南籍汉奸代表人物，对湖南沦陷区伪政权有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06fe4a67ade24b12b5ad5a506ac3eccd','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对湖南等地的伪化宣传与渗透，后与重庆方面暗中联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94ddc3d34c4c443e90c0482cd626d0be','4931b33d-722f-48c0-b72a-62d56d4f8250',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设，虽非直接在长沙、宁乡活动，但作为湖南籍汪伪要员，其伪政权体系对湖南沦陷区有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0835cc2f3d84d57b1916636cb5b6282','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'湖南籍（祖籍湖南）','湖南籍（祖籍湖南），汪伪政权第二号人物，随汪精卫投敌，历任伪立法院长、伪行政院长，汪精卫死后任伪国民政府代主席。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a7eec318fcd4f57a52affb0584d5065','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'广东乳源人','广东乳源人，汪伪政权二号人物。主要活动于南京、上海，与湖南株洲石峰无直接关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b9d0f4470d44693ad6d2ce7edd94fba','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'广东乳源人','广东乳源人，原国民党左派，抗战期间随汪精卫投敌，历任伪立法院长、伪行政院长、伪国民政府代主席等职，为汪伪政权第二号人物，全面推行亲日卖国政策。虽非湖南籍，但其伪政权统治范围涵盖湖南沦陷区，与湖南有间接关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d79c04893ff5449f94727af9f8b88235','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'湖南籍（祖籍福建','湖南籍（祖籍福建，生于广东，与湖南关联较弱），汪伪政权主要头目，抗战胜利后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71cf811ae1fa4540a9539a345529058f','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'湖南籍（祖籍湖南汝城','湖南籍（祖籍湖南汝城，生于广东），汪伪政权主要头目之一，历任伪立法院长、伪行政院长、伪国民政府代主席，追随汪精卫叛国投敌。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28f4a9884e554d8daed5fcf90dde6dbb','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'广东乳源人','广东乳源人，原国民党要员，抗战期间随汪精卫投敌，成为汪伪政权第二号人物，历任伪立法院长、伪行政院长、伪国民政府代主席等职，其伪政权统治范围涵盖华中沦陷区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36b17fef13f34ce0abafe0e826f8aa88','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'虽为广东籍','虽为广东籍，但作为汪伪政权最高层之一，其伪政权统治范围涵盖湖南沦陷区，对湖南地区伪政权运作有直接影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16be11033a8e4c5d9209a2a7d2ba3aa8','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'虽为广东籍','虽为广东籍，但作为汪伪政权核心头目，其伪政权统治体系覆盖湖南，衡阳、南岳地区伪组织亦受其统辖，属全国性汉奸头目，与湖南沦陷区伪政权有关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8859110c49cc483981443cbf725784ac','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'广东乳源人','广东乳源人，汪伪政权核心人物，虽非湖南籍，但其伪政权统治体系覆盖包括湖南在内的沦陷区，间接影响衡阳地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81f9e1cba3ad4904a1395454c2f27351','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'广东乳源人','广东乳源人，汪伪政权主要头目之一','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6354fcfce15c408cb27400f762881758','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'与湖南衡阳无直接地方关联','与湖南衡阳无直接地方关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34c7e838c65a4e97a980f7fa478ac8ff','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'湖南籍祖籍','湖南籍祖籍，汪伪政权主要头目之一，继汪精卫后任伪国民政府代主席，推行亲日卖国政策，抗战胜利后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01457ac8e6144ca5b3a90d3561b52cd9','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'湖南籍祖籍背景','湖南籍祖籍背景，汪伪政权主要头目之一，追随汪精卫投敌，抗战胜利后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
