INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ad6d50b7c8248ca9a869da00c6df97b','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'虽为广东人','虽为广东人，但作为汪伪政权最高层之一，其伪政权统治范围覆盖湖南，战后以汉奸罪被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f63fbdf184304c6c8e1dd3bbde6084a9','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'湖南籍相关人物常被提','湖南籍相关人物常被提及，原为国民党左派，后随汪精卫投敌，成为汪伪政权主要头目之一。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60743369e6e04924a2790e56038d4d48','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'广东乳源人','广东乳源人，汪伪政权主要头目之一，追随汪精卫叛国投敌，活动于南京、上海，与湖南郴州、桂阳无直接地方关联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31843c33965c4c8d85880d7c2a89da6d','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'广东乳源人','广东乳源人，汪伪政权主要头目之一','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95e5fc3c33c649c488dcbc4ed1e5fcdc','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'其伪政权体系覆盖华中、华南','其伪政权体系覆盖华中、华南，湖南部分地区伪组织亦受其名义统辖，与郴州、永兴一带伪维持会、伪警察系统存在行政隶属关系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9914ac1785144081a1f2a0a388c7ad8a','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'广东乳源人','广东乳源人，汪伪政权主要头目之一，其伪政权体系覆盖包括湖南在内的华中沦陷区，推行伪化政策，抗战胜利后被处决。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56b6fa8c4bb44c92a26d0077c21a1a95','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'广东乳源人','广东乳源人，汪伪政权第二号人物，虽非湘籍，但其伪政权统治覆盖湖南沦陷区，签署多项伪化湖南政令。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2677d8bd102b452987d0b54c83b1593b','d7f199e6-530c-4ed7-8d13-f341241ab60f',1938,'湖南籍？实际为广东乳源人','湖南籍？实际为广东乳源人，但长期在汪伪政权任要职，与湖南无直接关联，故不列入。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f286ce99b28475cac582a336f35be11','98931eed-9c41-46df-aa61-45636527ce5d',1939,'湖北黄陂人','湖北黄陂人，原国民党将领，投靠汪伪政权后任伪陆军部长、伪湖北省长等职，在华中地区配合日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c10e09a481824b8db24797c68481a754','98931eed-9c41-46df-aa61-45636527ce5d',1939,'湖北黄陂人','湖北黄陂人，非湖南籍，但在湖南邻近地区活动，曾参与伪军组织，与湘潭无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8343d8aa98f49949a632fcbbc66b7be','98931eed-9c41-46df-aa61-45636527ce5d',1939,'湖北籍伪军头目','湖北籍伪军头目，活动于武汉及周边，与湖南北部沦陷区伪军系统有联系，参与伪军扩编与治安强化。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7362e273845e4d078659ca30df84b2e7','98931eed-9c41-46df-aa61-45636527ce5d',1939,'湖北籍','湖北籍，汪伪政权军事头目，曾任伪陆军部长、伪湖北省长等职，其伪军活动范围涉及湘北、湘中，与湖南衡阳、南岳地区军事伪化有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3649e43fbeb04746b20c68e744f412b2','98931eed-9c41-46df-aa61-45636527ce5d',1939,'湖北黄陂人','湖北黄陂人，汪伪政权军事要员，曾率伪军配合日军进攻湖南，其部队在湘北、衡阳外围有过活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee2dc539e92443bab708a9a64730a4ff','98931eed-9c41-46df-aa61-45636527ce5d',1939,'湖北黄陂人','湖北黄陂人，汪伪政权军事头目之一，在湖北、武汉地区活动','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-101e3c1c329249c5a0c9faccdec8ccf6','98931eed-9c41-46df-aa61-45636527ce5d',1939,'与湖南衡阳无直接关联','与湖南衡阳无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c761d4512ff4490993b464541250043e','98931eed-9c41-46df-aa61-45636527ce5d',1939,'湖北籍汉奸','湖北籍汉奸，其伪军体系曾向湖南北部渗透，与衡阳地区无直接任职，但属长江中游伪政权网络的一部分。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
