INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb732bcc90d74ea8958fc8e99c894ec2','b763409e-2fbf-4675-82b4-7d1fcb6c057f',1940,'湖南长沙人','湖南长沙人，曾任伪湖南省政府主席，参与日伪在湖南的统治，活动范围覆盖长沙及周边，与株洲、攸县地区有间接关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
