INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd673bfcc0c749fc8c15ec697fa249a5','056c4180-3179-4697-b988-755e4bb8bda4',1944,'攸县本地人','攸县本地人，1944年日军侵占攸县期间出面组织维持会，为日军筹粮、派夫、维持地方秩序，属当地直接附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a552e071161548bdb7e636b3c87aca39','d413bb6e-e3a2-49e1-bdf0-b6e4cc0346df',1944,'攸县本地人','攸县本地人，日军占领期间任伪保安队头目，协助日军搜捕抗日人员、征发民夫，具体姓名在地方史料中记载不全。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb2402f722814b49910340a5346b4a17','04c42371-94af-4f03-9fa7-45ff9d518967',1944,'株洲本地人','株洲本地人，1944年日军侵占株洲期间任伪维持会副会长，协助日军管理地方事务，与攸县有地域关联。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5e8836659c4490d98616e839bc87c54','ffbf55d4-2b01-4933-bb3d-5e24d2e5847e',1944,'湘潭人','湘潭人，日军占领湘潭期间任伪维持会会长，活动范围与株洲、攸县邻近，属湖南地区附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5161a2d6eb24f9da4b13d9ce869e803','71bd0c4b-43ef-4701-bcbf-8da93e1a6e4f',1940,'受重庆方面派遣打入汪伪政权','受重庆方面派遣打入汪伪政权，在湖南及周边地区活动，曾参与伪政权军事事务，但其身份具有双重性，常被列为特殊案例。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc2c799c2cb54f698254b951c89508bf','88c99c89-ab0c-4f77-aa5f-b72efce2e80a',1939,'在湖北、湖南北部一带活动','在湖北、湖南北部一带活动，组织伪军配合日军进攻湖南，对湘北地区造成破坏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72bf446fe97c4f29bc1f802b056852e8','88c99c89-ab0c-4f77-aa5f-b72efce2e80a',1939,'湖北黄陂人','湖北黄陂人，早年曾在湖南任职，抗战期间投靠汪精卫，任伪武汉行营主任、伪湖北省政府主席等职，在湖北、湖南北部地区配合日军进行清乡、征粮、镇压抗日力量。其活动范围覆盖湘北，与湖南有直接关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36fdba69d8894f64a79ca94a511b6eee','88c99c89-ab0c-4f77-aa5f-b72efce2e80a',1939,'湖北黄陂人','湖北黄陂人，原国民党将领，投靠汪伪后任伪武汉行营主任、伪湖北省政府主席等职，在湖北湖南交界地区进行伪化活动，对湘潭地区有间接影响。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e63deeca803c4a26bf730d4ddb8c360b','97f120f3-c627-4a2d-a372-468b7cac6833',1944,'日军进攻湖南时','日军进攻湖南时，曾被日方胁迫或列入伪政权名单，但实际未履职，历史记载存疑。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
