INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66be7ecbf5034faf9c171bcf38d8e2c5','ff2cb377-05ce-4b0e-852f-1b0d2bf1bfed',1944,'唐生智之弟','唐生智之弟，被日方考虑为伪湖南省长人选，但未实际就任，后逃往香港。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4bb216641af434dad13be4609e91711','99c2f05b-54a1-460f-a333-75d71cbcb44e',1940,'湖南东安人','湖南东安人，唐生智之弟。抗战期间受蒋介石、戴笠派遣打入汪伪政权，表面任伪职，实际从事策反和情报工作。其活动范围主要在南京、上海及江苏，与湖南株洲石峰无直接关联，但在湖南籍伪职人员中影响较大。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09c6e572b1da429cb7b86940b1157142','99c2f05b-54a1-460f-a333-75d71cbcb44e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实为军统潜伏，并非真正附逆，但曾在汪伪系统中活动，与湖南籍人员有联系。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89f2108c766b49ae924cfedc482dbb9a','99c2f05b-54a1-460f-a333-75d71cbcb44e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实际从事策反与情报工作','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6b925e938f8430ba4063a24d70651ba','99c2f05b-54a1-460f-a333-75d71cbcb44e',1940,'其活动范围涉及湖南籍军政关系网','其活动范围涉及湖南籍军政关系网，但与醴陵无直接任职关联。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d1642a80058e4fc19842a7db5765a1ce','99c2f05b-54a1-460f-a333-75d71cbcb44e',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实际从事策反与情报工作','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3966efee030a4007b50438b328e88db8','99c2f05b-54a1-460f-a333-75d71cbcb44e',1940,'其活动与湖南籍人员网络有关','其活动与湖南籍人员网络有关，但主要活动不在衡阳蒸湘。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec1649b6472448489751b8297812edd0','cd4f008b-d5e1-4b5a-9ba9-4f06de6f65f6',1939,'浙江遂昌人','浙江遂昌人，生于湖南？无直接株洲关联。汪伪特务头目，活动于上海、南京、江苏，与湖南株洲石峰无直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc7ea319d5904d8b863f3f499256f743','9ddb3cd0-1845-4102-880a-b38ce5d3a2a2',1944,'1944年日军发动豫湘桂战役','1944年日军发动豫湘桂战役，占领株洲（当时为湘潭县株洲镇，今株洲市石峰区一带属之）。当地曾出现维持会组织，协助日军征粮、拉夫、维持治安。具体姓名因地方档案散失，难以确证。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-746bb4b2707a400aa6205dbf6ff994f1','7dde28da-c033-4956-a9d1-07b8ea473ebc',1944,'株洲石峰地区当时属湘潭县管辖。日军占领湘潭后','株洲石峰地区当时属湘潭县管辖。日军占领湘潭后，曾扶植伪湘潭县政权，部分士绅附逆。具体姓名缺乏可靠记载。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ad1eeae019042f0b94ca8277d9e4eac','1c6bb30a-6932-4574-98ff-fac2216b5579',1944,'长沙沦陷期间（1944-1945）','长沙沦陷期间（1944-1945），日伪曾组织维持会及伪政权。株洲石峰距长沙较近，部分人员可能跨区域活动。具体姓名缺乏可靠记载。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33373743e0494d888e6e9a117eb65fce','5dfb9365-018c-42c7-937c-942942541ff2',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，任伪职，实为军统潜伏人员，抗战后期策反汪伪军政人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49fe056413c24bc3ab0e94031c611aea','ed05f02a-d73c-4666-bdd4-fcad2a8d2fd5',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，推行伪化统治，后与重庆方面暗中联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
