INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1c6973375534decb363387454cf57d6','6469818b-2e8a-4e03-bccd-2adfac27a4fe',1939,'湖南湘乡人','湖南湘乡人，汪伪政权重要成员，参与伪政权行政与警政，其活动与湖南籍伪政权人员网络有关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-148e3d4f0c4348fca81bc717cb238661','fffde4bc-5bdb-43a8-b703-aa61d246df93',1938,'湖南人','湖南人，汪伪政权在广东的重要人物，其伪警政体系与湖南籍附逆人员有联系。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29bd2aee81804c3f9f1b0d1d37f3b31b','854bf697-a787-4557-852b-7478253c3260',1944,'在日军占领长沙期间','在日军占领长沙期间，参与伪政权维持会与伪市政府事务，协助日军征粮、征夫，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3d6aa5ffa134671b85fb7a199ca715a','74e44f16-915c-4e51-bd13-f585a393c265',1944,'日军占领湘潭后','日军占领湘潭后，出面组织维持会，为日军筹集物资、拉夫，协助伪化统治，影响波及株洲一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62ba9e3bcc9941c380bc7e23cefa1bea','aa486548-3f39-4a8d-9e43-eb281717e84b',1944,'日军侵占株洲后','日军侵占株洲后，出面组织地方维持会，协助日军维持治安、征发民夫与粮食，具体名字在地方档案中记载不全。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f2441b6bbd249338d4de9a5d2c665e3','76eba08b-9944-40ae-b746-d57842c9c7df',1944,'在株洲芦淞一带担任伪保甲长','在株洲芦淞一带担任伪保甲长，为日军征粮、派夫，监视居民，协助伪政权控制基层。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91141249489d49d58556c6dd01da0ee4','44880693-28dd-4f79-9cb0-2951b7000c33',1944,'在长沙沦陷期间','在长沙沦陷期间，协助日军组织伪政权，参与征粮、征夫，镇压抗日群众，其活动范围包括株洲北部。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-960a0865e459422d8db2dce18a5b6d62','15874aa8-add0-41b7-9acb-e4023cca3311',1944,'在日军占领湘潭期间','在日军占领湘潭期间，担任伪警察局长，协助日军搜捕抗日人员，维持伪治安，影响株洲地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-726ec513077d453891866f0798bee8b9','9975b6aa-0855-4602-980c-f9a24ab2291e',1939,'湖北人','湖北人，汪伪政权在华中地区的重要军事头目，其伪军活动范围包括湘北、鄂南，与湖南北部沦陷区有军事联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7fc7f150c5a4eb485a93d65f9d2f109','e040b7f8-bfe9-4a9a-b86d-58b24515882c',1933,'湖南人','湖南人，北洋旧军阀，九一八后与日本特务勾结，企图在华北组织伪政权，1933年被军统刺杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12e3088d14744d5aadef9db2e3b54940','f0229327-6c55-4467-ba8f-f6d4426b8cf2',1944,'在日军占领长沙期间','在日军占领长沙期间，出任伪职，协助日军维持长沙地区治安与伪化统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ee6b8aa595b4cd3b56d9045fcfa6822','b220ace9-4213-4ce3-b3df-4864d40f5150',1944,'日军发动豫湘桂战役占领湖南大部后','日军发动豫湘桂战役占领湖南大部后，被日军扶植为伪湖南省政府主席，在长沙等地推行伪化统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1bacaa03ffb4e4f90d561613fc98886','9d18fb34-de6b-40bd-b292-bde05d8fee7e',1944,'湖南本地人','湖南本地人，日军占领长沙后出任伪职，协助日军征粮、拉夫，维持伪政权基层统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fef97622ba50434083ad5ebff37998b5','aa2a7509-2ac0-4a6a-894d-d6c09f8bd2d6',1944,'日军占领湘潭后','日军占领湘潭后，组织维持会，为日军筹粮、派夫，协助日军控制湘潭地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15786fda3ce64f60b2e01a8039ffd9f1','0d8830b0-5d39-4a14-bc66-23e05e5dbc35',1944,'日军占领株洲后','日军占领株洲后，出面组织维持会，为日军提供物资、情报，协助维持株洲地区伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81ff6ef9c15f412d9e0c6f6501a012dd','4f8f7936-7358-4cee-87b3-06740da63eee',1944,'日军侵入茶陵期间','日军侵入茶陵期间，组织维持会，为日军筹粮、带路，协助日军在茶陵地区的统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6698322e745438784bb8bc3a05c028a','96b79db4-36f6-4388-8734-adb3d57a8458',1944,'茶陵本地人','茶陵本地人，日军占领期间出任伪保安大队长，率伪军配合日军扫荡，镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2bcaf1ded7e344029a0ae56fd9935b4b','1d79ba4b-840d-44ab-ae19-35088d0b7082',1944,'日军占领醴陵后','日军占领醴陵后，参与组织维持会，为日军征粮派款，协助伪化统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d919cfef001c42c6a976b3ee90616347','0b97c384-3d2c-4663-b490-f349a8e3a55c',1944,'在日军占领长沙期间','在日军占领长沙期间，率部投敌，编为伪保安团，配合日军维持治安、清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22e5df2b20924bc48cf051ac7f3be739','f5348926-8ee5-4eb8-8773-27d4c9ae598d',1944,'长沙商界人物','长沙商界人物，日军占领后出面组织商会，为日军筹款筹物，协助经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff09f804fe2143e38c72b1d35d9c18f3','1b79818a-1f87-4369-98d1-318be9d94ea6',1944,'在长沙沦陷期间','在长沙沦陷期间，主办伪报纸，为日军进行宣传，鼓吹“大东亚共荣圈”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe3b51d99972407baf66e6d136d14d72','0ffab546-17b0-42ab-943d-9a457b552e07',1940,'湖南沅陵人','湖南沅陵人，汪伪政权核心，其财政金融政策覆盖湖南沦陷区，发行伪币，掠夺物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b4a205fd3ba4487b4852ceb03fbdfb0','ab9dd019-4c48-48a4-a196-c15eff41b5b7',1943,'抗战后期受重庆方面派遣潜入汪伪政权','抗战后期受重庆方面派遣潜入汪伪政权，任伪湖南省政府主席等职，表面附逆，实际从事策反与情报工作，其活动范围覆盖湖南全省，包括株洲地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-864527fcf7b54b518284503a21661a9b','ab9dd019-4c48-48a4-a196-c15eff41b5b7',1943,'原为国民党将领','原为国民党将领，后投靠汪伪政权，任伪湖南省政府主席，在湖南地区协助日军维持统治，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df1759ddc53847288ec16573aeba639b','ab9dd019-4c48-48a4-a196-c15eff41b5b7',1943,'湖南东安人','湖南东安人，受重庆方面指派潜入汪伪，但公开出任伪湖南省主席，在湖南沦陷区建立伪政权，益阳、安化一带伪组织受其节制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f64b55d4eaf84119b3375070f74db725','ab9dd019-4c48-48a4-a196-c15eff41b5b7',1943,'原国民党将领','原国民党将领，后投靠汪伪政权，任伪湖南省政府主席，在湖南地区协助日军维持占领秩序，推行伪化统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98820fcba1ad4435a915da858a8c7d7b','ab9dd019-4c48-48a4-a196-c15eff41b5b7',1943,'原国民党将领','原国民党将领，1943年投靠汪伪政权，任伪湖南省政府主席、伪保安司令等职，在湖南地区协助日军维持占领秩序，1945年后被蒋介石重新收编。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5625e13356d41718e8fbed2aae613ef','ab9dd019-4c48-48a4-a196-c15eff41b5b7',1943,'抗战后期受重庆方面派遣潜入汪伪政权','抗战后期受重庆方面派遣潜入汪伪政权，任伪湖南省政府主席等职，表面附逆，实际从事策反与情报工作','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1bce854c5d554b23aeb49d075df85ef4','ab9dd019-4c48-48a4-a196-c15eff41b5b7',1943,'其活动范围覆盖湖南衡阳、耒阳一带','其活动范围覆盖湖南衡阳、耒阳一带，是湖南沦陷区伪政权最高头目之一。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5df193c783d24a2e92bbbf696036798d','ab9dd019-4c48-48a4-a196-c15eff41b5b7',1943,'抗战后期受重庆方面派遣潜入汪伪政权','抗战后期受重庆方面派遣潜入汪伪政权，任伪湖南省政府主席、伪保安司令等职，在湖南地区活动，与郴州、资兴一带的伪政权运作有间接关联。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0576f1bae9a46a48824a21d1b127277','6329c5b4-bab4-4d4f-be9c-ab28569fdf31',1944,'日军侵占株洲后出面组织伪维持会','日军侵占株洲后出面组织伪维持会，协助日军征粮、派夫、维持治安，为当地主要附逆人物之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27f45f92ea30420daba082e5a5262607','eba5115e-028c-4cce-aa7d-f1b7f098565a',1944,'在湘潭及株洲一带协助日军建立伪政权','在湘潭及株洲一带协助日军建立伪政权，参与征发民夫、物资，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4033882924304fb8a840d5816f25c631','dd8bb0c6-d2e7-42e5-b11f-88fb561798c0',1940,'在汪伪湖南省政府中任职','在汪伪湖南省政府中任职，负责伪警察系统，配合日军在湖南各地包括株洲地区进行治安强化与搜捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a913d5d2dab04fe2a1fb2bf00772d9c6','5abd6d06-b75c-4c25-9a42-93c4efdfa8a8',1944,'日军第四次长沙会战期间组织伪维持会','日军第四次长沙会战期间组织伪维持会，其势力范围波及株洲北部地区，协助日军维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18a4b41b5a7e4e5db092f8ac206d08d5','33de6008-52c3-4df5-92d9-b94bfffe7a67',1944,'在湖南沦陷区收编散兵游勇组成伪军','在湖南沦陷区收编散兵游勇组成伪军，配合日军在株洲、湘潭一带进行扫荡与清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2db54e209f094bf1a5e87c59924d1ea0','73439312-998a-438e-b6eb-8f5ad0167550',1944,'日军占领株洲后出任伪警察头目','日军占领株洲后出任伪警察头目，带领伪警察搜捕抗日分子、勒索民众，直接服务于日军驻株洲部队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec7eb69d20b6467793fdd61316214f8f','10cf64da-8b06-412f-924b-eb0353f06698',1944,'在株洲荷塘地区担任伪保长','在株洲荷塘地区担任伪保长，为日军征粮派款、提供情报，是当地基层附逆者的典型代表。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44a6bf7c247e434589d62b04d22abdcd','fb67edd3-98b0-4bce-86f8-56f72a50df75',1944,'汪伪政权在湖南沦陷区设立伪省政府','汪伪政权在湖南沦陷区设立伪省政府，李讴一被任命为伪湖南省长，负责配合日军维持占领区秩序，其伪政权覆盖长沙、株洲、醴陵等湘东地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b152a2cda5c497197033d9a18471d07','772b8faf-ed3b-4c00-bf3c-bd1591325a5f',1944,'长沙沦陷后出面组织维持会','长沙沦陷后出面组织维持会，协助日军征粮、拉夫、维持治安，其活动范围包括长沙周边及湘东株洲、醴陵一带的伪政权运作。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9c3eed088324e2ab865f946a0bc23de','3e8e239d-138c-48b5-a52d-b6c0c49d480c',1939,'湖北籍汉奸','湖北籍汉奸，但其伪军活动曾延伸至湘北、湘东，与湖南沦陷区伪政权有联络，间接影响株洲、醴陵地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca11ca227b1c4ef18a22c4a84e9e780a','f625e21c-1c4d-4164-a1a8-7af78c802121',1932,'湖南籍旧军阀','湖南籍旧军阀，1933年与日伪勾结企图在华北组织伪政权，被军统刺杀','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cba22a8107f4528a943c87ff639b0f4','f625e21c-1c4d-4164-a1a8-7af78c802121',1932,'其湖南关系网涉及株洲、醴陵地方势力','其湖南关系网涉及株洲、醴陵地方势力。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10995d05d1294fadbd2bafaf30bf5d00','30fee0b0-c379-4f10-9b42-7b5651c3b336',1944,'1944年醴陵沦陷后','1944年醴陵沦陷后，出面组织地方维持会，为日军征派粮食、民夫，协助维持占领区秩序，是醴陵本地附逆代表人物。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a515efcf10f4f34bfe9781b90dd8ae5','ae3a5427-40e7-4f2e-bb48-af108ded2c2e',1944,'湖南醴陵人','湖南醴陵人，抗战后期在湘东地区与日伪有暧昧接触，但未正式出任伪职','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce5daa79c3c44192b8a0da6561b3a39a','ae3a5427-40e7-4f2e-bb48-af108ded2c2e',1944,'其部属中有个别投敌者','其部属中有个别投敌者，影响醴陵一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35d3ac1099954774a11dacc32eacead5','701b43bd-4c89-417f-bada-36e138102a96',1944,'株洲沦陷期间','株洲沦陷期间，协助日军在株洲镇及周边地区建立伪维持会，负责摊派捐税、征集物资，是株洲本地附逆者之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-377b05a776254c4ab7d0f106a1a86c8e','3026975a-22e3-44cd-b5ca-81cc09752169',1944,'在湘东地区为伪湖南省政府与日军之间联络','在湘东地区为伪湖南省政府与日军之间联络，活动范围包括株洲、醴陵、浏阳一带，协助伪政权推行保甲连坐。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c7e56976ff4400489a246ef3cd7b754','277265a8-9c75-4aa6-84e3-a253aa20f51d',1931,'醴陵籍抗日将领','醴陵籍抗日将领，坚持抗战，无附逆行为','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-246fb2f52a394e97b3f60c05bed47e6e','277265a8-9c75-4aa6-84e3-a253aa20f51d',1931,'此处仅作对照','此处仅作对照，不属汉奸名录。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03a1101b0dc74e8195bb114e7dce2ec5','b433cf53-d17e-4e78-bb10-6cc37e428acc',1944,'日军侵占永州后','日军侵占永州后，出面组织伪维持会，为日军征粮拉夫，协助建立伪基层政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-880440dc3d504b2bb802b3572cf31583','b433cf53-d17e-4e78-bb10-6cc37e428acc',1944,'日军侵占永州期间','日军侵占永州期间，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军侵略服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf75591cf38643808a6bfad388076455','1472bcf4-e2c5-4e1a-a975-4ae25115b4cc',1944,'在日军占领零陵期间出任伪县长','在日军占领零陵期间出任伪县长，推行伪化教育，配合日军清乡，搜捕抗日人士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-207cb7713740484aa71d2641966eb57c','bb3fd465-2161-4696-ab6b-a7fe8002cb11',1940,'汪伪政权核心人物','汪伪政权核心人物，曾兼任伪湖南省长，其势力影响湖南沦陷区，推行伪化经济与治安政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ad92bf48969461385eeadcfe0bf4139','294236c7-ad97-4d9e-a330-baa4f3964d2a',1944,'在永州沦陷期间担任伪警察头目','在永州沦陷期间担任伪警察头目，协助日军维持治安，逮捕抗日分子，勒索民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8255bc2e7b49448ba7ce01cec79e6a3c','3bcb77ef-8867-4ef9-a5a5-4d486488d7d1',1944,'原为地方武装头目','原为地方武装头目，后投靠日军，任伪保安团长，在永州、衡阳一带配合日军扫荡抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0889b364dd084b1bab373a25a0d42860','68992fce-87f9-4536-acbc-7b1366683810',1944,'协助黄子琪组织伪维持会','协助黄子琪组织伪维持会，负责摊派粮款，为日军提供情报，迫害抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-464b0b041bd64a89abdef5fad07bedb3','4cf6f589-d49c-4ee9-82ae-ab2c884f1578',1944,'在日军占领永州后','在日军占领永州后，出面组织伪商会，为日军筹款筹物，协助经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba79b437700f446cb0c5d5a882289eac','145f2085-fe89-4fb8-a996-593af19f220e',1940,'在汪伪政权下负责湖南沦陷区教育','在汪伪政权下负责湖南沦陷区教育，推行奴化教育，篡改教材，宣传“大东亚共荣”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14d638daf59e4bf4910c44c661eaf864','c6cc1082-dafc-45e7-81eb-90a5984d21b3',1944,'日军在湘南设立伪道尹公署','日军在湘南设立伪道尹公署，何键出任道尹，管辖永州、郴州等地伪政权，配合日军征丁征粮。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b2e1eb5e8690465faac166a710ca3b9f','f4394338-fdac-479d-9144-0c3972ef01a2',1940,'湖南东安人','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任汪伪军事委员会委员、伪清乡委员会副秘书长等职，在沦陷区活动，与永州东安有籍贯关联。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d048aa051404c7bb46fce1f35de1d4e','f4394338-fdac-479d-9144-0c3972ef01a2',1940,'湖南东安人','湖南东安人，奉蒋介石之命打入汪伪政权，表面附逆，曾任伪军事委员会委员等职，在湖南及衡阳一带有活动关联，但实为重庆方面潜伏人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9bf9be1dad842579d455b9ebfa02709','f4394338-fdac-479d-9144-0c3972ef01a2',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，任伪军事委员会委员、伪清乡委员会副秘书长等职，在沦陷区活动，与湖南郴州、桂阳地区无直接地方任职记载，但属湖南籍汪伪要员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c6518fd6c0a42d390dc1ce872deda53','f4394338-fdac-479d-9144-0c3972ef01a2',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，任汪伪军事委员会委员、伪清乡委员会副秘书长等职，在沦陷区活动，与湖南郴州、汝城无直接活动记录，但属湖南籍附逆人员中影响较大者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27a5ec68fc434235acd97d381a29e5af','f4394338-fdac-479d-9144-0c3972ef01a2',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，历任伪军事委员会委员、伪清乡委员会副秘书长等职，在长沙、湖南一带与日伪周旋，实为军统潜伏人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a5a38b818584f9caa07f197b9f39a6c','f4394338-fdac-479d-9144-0c3972ef01a2',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪政权，在南京、上海等地活动，曾参与伪清乡事务，与湖南方面有联系，但其身份具有双重性，战后被认定为潜伏人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0368cb027520425e99db5c750fb9f7cd','f4394338-fdac-479d-9144-0c3972ef01a2',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪政权，在南京、上海等地活动，曾参与伪政权军事与清乡事务，与湖南籍军政人物联系密切。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-702f6cc8cbd14056843c609e655abc20','f4394338-fdac-479d-9144-0c3972ef01a2',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，历任伪军事委员会委员、伪清乡委员会副秘书长等职，在长沙、湖南一带为军统搜集情报并掩护抗日人员，抗战胜利后恢复国军身份。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d4670df33e544d6b0c8ba917766b505','f4394338-fdac-479d-9144-0c3972ef01a2',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，任伪职，负责联络伪军将领，后回归重庆方面。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0b410fb1ae34bc7b19e52533d8b3171','9ae2b7bc-0b2f-4463-8a79-423c1c5c8e15',1944,'日军侵占永州期间','日军侵占永州期间，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f35e37d64704c8bbdb6d83d65d3cf29','cfcabb6a-c9ed-41df-8f55-0d063f20ca4f',1944,'零陵沦陷后','零陵沦陷后，组织伪维持会，为日军筹粮、拉夫，协助日军统治地方。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf052ebdf61a447eba985d4a99e0a500','7d237ae9-2a0d-4843-9902-106437cb62eb',1944,'衡阳沦陷后','衡阳沦陷后，组织伪维持会，协助日军管理地方，征调民夫、粮食。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7a7ffee088048509b6139a2d280c418','cdc8656d-34d1-487c-a1b2-119028659627',1944,'日军侵占湘南后','日军侵占湘南后，投靠日军，组织伪军，配合日军扫荡抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-53c9f27e52534d02bc5b40107743e737','5b4017c7-0a89-40b0-b083-0be2c3ccfe5c',1944,'长沙沦陷期间','长沙沦陷期间，参与伪维持会，为日军筹款筹粮，协助维持殖民统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d9b2b7d253f454a85669e7a46bf8829','70b3978f-b7e3-4425-b198-330c53b2c581',1940,'受军统派遣打入汪伪政权','受军统派遣打入汪伪政权，曾任伪湖南省政府委员、伪长沙市长等职，表面附逆，实际从事潜伏情报工作。其活动范围覆盖湖南多地，与永州地区有间接关联。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-339ac81788894a87938b2107f96e7ac2','70b3978f-b7e3-4425-b198-330c53b2c581',1940,'受军统派遣打入汪伪政权','受军统派遣打入汪伪政权，曾任伪湖南省政府委员、伪长沙市长等职，表面附逆，实为重庆方面提供情报并策反伪军。因具有潜伏性质，历史评价复杂。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6279a3d6ec5146ed9a20995a06fe6ebf','64e14c32-6210-4e88-ab8e-418d3d63fa5a',1944,'零陵沦陷后','零陵沦陷后，参与组织伪维持会，协助日军推行保甲制度、征收物资，镇压抗日活动。零陵与双牌地域相邻，其活动范围覆盖双牌周边。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-454112f95d3649b0a9254faae605aa01','2e7714b9-0d37-40a4-8ce9-398e9d128dfd',1938,'汪伪政权主要头目之一','汪伪政权主要头目之一，其伪政权体系覆盖湖南沦陷区，永州地区伪政权亦受其名义管辖。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f459bcb3792c4e42951f49eff81b3a54','a4171de6-5268-4903-8518-679379d08965',1944,'双牌本地人','双牌本地人，日军侵占期间出任伪保甲长，协助日军征粮、派夫、搜集情报，压迫当地民众。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f20048e524b84ec191d99638dcad5fbe','1eeb9a1f-0bde-4b14-9456-0a1418af2735',1944,'永州沦陷后','永州沦陷后，收编地方武装投靠日军，任伪军大队长，配合日军扫荡抗日游击队，活动于永州、双牌一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08c8f90ac14148ad8277893058f5b7bd','9e44a836-dde3-4590-b3aa-e24035482145',1940,'湖南湘乡人','湖南湘乡人，早年加入中国共产党后叛变，抗战期间投靠汪精卫，历任伪中央政治会议副秘书长、伪安徽省省长、伪上海市政府秘书长等职，参与伪政权决策与地方治理，在安徽、上海等地为日军服务。籍贯湖南，与湖南有直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d383eff479d64b5481ca37cf9c8ed3bd','bf6ac248-03f4-4e40-a104-144948d69be0',1938,'湖南沅陵人','湖南沅陵人，原国民党要员，抗战期间投靠汪精卫，成为汪伪政权核心人物之一，历任伪财政部长、伪行政院副院长、伪上海市长等职，负责伪政权财政与经济掠夺，并后期与重庆方面暗中联系。籍贯湖南，与湖南有直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a938b71782f94e03a58ecd8ecad0f0c1','bf6ac248-03f4-4e40-a104-144948d69be0',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，推行伪化统治，虽主要在南京、上海活动，但作为湖南籍汉奸代表人物被广泛记载。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b80bc4299da4148b85b30d87a482590','bf6ac248-03f4-4e40-a104-144948d69be0',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，后与重庆方面暗中联系，抗战胜利后被国民政府逮捕审判。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2c5e3f90e0d4de4b02d3d0c72cbd740','bf6ac248-03f4-4e40-a104-144948d69be0',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，掌握财政与特务系统，后与重庆方面暗中联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-118ce7744fe2449b946445620d40693f','bf6ac248-03f4-4e40-a104-144948d69be0',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，推行伪化统治，其活动主要在上海、南京，对湖南沦陷区有政治影响，但与郴州、桂阳无直接地方关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fb693cfa7484ad495c7253f4e3dee14','bf6ac248-03f4-4e40-a104-144948d69be0',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1ae78ab456f4551aaa7cd18566d2746','bf6ac248-03f4-4e40-a104-144948d69be0',1938,'虽非郴州、永兴本地活动','虽非郴州、永兴本地活动，但作为湖南籍最大汉奸之一，与湖南地区伪政权人事网络有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2314394035d463e8b5cfabfeac2c669','bf6ac248-03f4-4e40-a104-144948d69be0',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，掌管财政，后与重庆方面暗中联络。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26e048f26a9b4d068df488f4506c59e6','514144c8-f6d7-42af-a445-337c4945039d',1930,'湖南长沙人','湖南长沙人，国民党将领，1930年率部参加对中央苏区的第一次“围剿”，在江西龙冈被红军俘虏，1931年被处决。其活动主要在江西，与湖南有籍贯关联，但并非严格意义上的汉奸。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc1a8965fc304fd1a0ab0545443aacca','514144c8-f6d7-42af-a445-337c4945039d',1930,'湖南长沙人','湖南长沙人，1931年在江西被红军俘虏处决，非汉奸，但常被误列，此处不属汉奸名录。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b0732fae85f4ee09555109d1b2eaa69','514144c8-f6d7-42af-a445-337c4945039d',1930,'湖南长沙人','湖南长沙人，1930年率部进攻中央苏区被俘，1931年被处决，与衡阳地区关联较弱。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf85387a26ed41feba5fe69e7e1a73a5','514144c8-f6d7-42af-a445-337c4945039d',1930,'湖南长沙人','湖南长沙人，早年参与围剿红军，1931年被俘，并非严格意义汉奸，但因其在湖南地区活动且与日军有接触传闻，部分史料将其列入附逆嫌疑。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-712a209bcfd14584b6cc562c137b5549','02127c0a-7af3-4ba0-9458-7b4250a0f8ff',1929,'湖南醴陵人','湖南醴陵人，长期主政湖南，抗战初期仍任湖南省政府主席，后因与蒋介石矛盾被调离。其在湖南期间镇压共产党和抗日运动，但未直接投敌。与湖南有直接关联，但非典型汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0e4ff6f6a5946e584083c2f7747bdab','77f639f4-f73a-4692-b73d-b37dc9e3f680',1937,'湖南湘潭人','湖南湘潭人，八路军副总司令，抗战期间在华北领导抗日斗争，与湖南有籍贯关联，但为抗日将领，非汉奸。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d78e2f712c743e19ed2bf6306f849b2','78135d99-1d36-43d2-97ba-744f6481e422',1940,'湖南东安人','湖南东安人，与永州地区有直接籍贯关联。受重庆方面派遣打入汪伪政权，但在汪伪中担任伪职，参与伪清乡活动，属于有明确历史记载的附逆人物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f0ffc0dc41242c8afa3cd30dc7aba2a','78135d99-1d36-43d2-97ba-744f6481e422',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪内部，但在此期间公开附逆任职，参与伪清乡活动，与湘籍伪政权人物多有联络。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16aa6161c6d4475f9cfa83d8488cc3d8','65305269-4f77-449f-8649-44f56b02735c',1938,'湖南沅陵人','湖南沅陵人，湖南籍汪伪核心人物之一。虽主要在南京、上海活动，但其伪政权体系覆盖湖南沦陷区，对湖南地区伪政权建立有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-225ba02dea1e410bb6622060355d7529','f99707bb-30b1-4b58-9716-b065f3a6f732',1944,'湖南长沙人','湖南长沙人，日军占领长沙后出任伪职，协助日军维持占领区秩序，是湖南地区有明确记载的汉奸之一。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b6d450b5a2a4b67a91a90cfca141499','92c2591b-2f7a-4b37-ab15-330a75434c2e',1944,'湖南浏阳人','湖南浏阳人，1944年日军占领湖南大部后，被推为伪湖南省政府主席，主持伪政权，为日军征粮、征夫，是湖南沦陷区最高伪职人物。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7dcde967f2e4d1cb277692e467f8f54','0b55cd1f-fcd0-41c2-b0d9-f26b290af010',1944,'湖南籍','湖南籍，在日军占领湖南期间参与伪湖南省政府，协助日军推行伪化政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f76c34dea56431e9ede19809ad3f713','8ec9121b-4b2e-4cd4-9fe6-c1fac2f7f459',NULL,'无','无','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5718dccc7e34199b7fdad13163b7502','3b3e5f96-61fd-462d-81e6-de9a0c25ee3b',1940,'受军统派遣打入汪伪政权','受军统派遣打入汪伪政权，在湖南及周边地区活动，表面附逆，实际为重庆方面提供情报并策反伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3435673f90604509b5c1e0a09927dc84','9ebf823e-8190-492d-b746-a3ad3802252c',1944,'日军侵占道县期间','日军侵占道县期间，出面组织维持会，为日军征派粮秣、夫役，协助维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83cdc25b94754ea5aa99d9a85362c382','cb955d63-0845-4abf-aabb-7e9525be986a',1937,'原国民党湖南省主席','原国民党湖南省主席，抗战后期与汪伪政权有联系，其旧部在湖南部分地区附逆。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24a87d5e283b47b4bdac2040bccf0010','50960283-ff52-4cc9-a0db-55ecd3bb20e9',1940,'汪伪政权核心人物','汪伪政权核心人物，曾兼任伪湖南省长，对湖南沦陷区伪政权有名义管辖权。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f768d7c3cc541ab8d6ae4932be07452','3407059a-9974-46e2-b36f-7905d8a596a5',1944,'日军侵占永州期间','日军侵占永州期间，协助组织维持会，为日军筹集物资、招募伪军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a646ef3354a4ac78ce46127f454454e','f4adc832-ca58-4e7a-ad6c-dadf49c72a5f',1944,'在零陵（今永州零陵区）组织维持会','在零陵（今永州零陵区）组织维持会，配合日军统治，征发民夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63fb72f7646646afaad51604e5a02589','359d354b-4b71-418a-bd43-f2d7974e5a56',1944,'在湘南地区收编土匪、散兵','在湘南地区收编土匪、散兵，组织伪军配合日军扫荡，活动范围包括永州、道县一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0eb02534cdab41178148123e54c6c478','653bf1aa-d282-40c4-b635-f9c905dde6aa',1944,'在湘南沦陷区组织伪保安部队','在湘南沦陷区组织伪保安部队，协助日军维持治安，镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebe645fbc024402686173523d9280a95','92019d86-3545-4161-a8f1-5de2eada90d0',1940,'湖南人','湖南人，汪伪政权高官，虽主要在华东活动，但对湖南沦陷区伪政权有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1b834f4fed04ef58ab83c4da7b7669c','2a432ec8-d6d2-41c6-ae79-d386046df225',1939,'湖北黄陂人','湖北黄陂人，汪伪军事头目，其伪军活动涉及湘北、湘中一带，与湖南沦陷区有军事关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1c68b531a964b3fb8e597e62fe1dd7e','2a432ec8-d6d2-41c6-ae79-d386046df225',1939,'湖北黄陂人','湖北黄陂人，但在湖南长沙有军事活动背景，后投靠汪伪，其伪军活动范围覆盖湘鄂地区，与长沙有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8039c2df762420aa6383a626bde3e94','1f18c834-d3b4-4b82-a49d-19348b932913',1931,'湖南长沙人','湖南长沙人，1931年在对中央苏区“围剿”中被俘处决，非汉奸。此处不适用。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-309ae8bcf9c046578162ebffcf964c4a','3fdb0856-87dd-4b53-8c1a-e142b68d6325',1940,'湖南湘乡人','湖南湘乡人，汪伪政权要员，参与伪化统治，其伪政权活动对湖南沦陷区有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b073933818a436baa9df1f61aae5a46','77d6653d-84da-4d19-bed6-544a2a738c3f',1939,'湖南人','湖南人，汪伪特务骨干，在沦陷区进行特务活动，涉及湖南部分区域情报网络。','危害等级A（甲级，核心城市市长/省部级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48d6c3e1ac924f3ba50a8610149d6d03','1c2b274a-1d1d-461e-a826-8f0331cfb5de',1940,'湖南籍','湖南籍，汪伪政权中参与伪湖南省政府筹备与运作，协助日军推行伪化政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-232aa551abf14c1794ed83ac5d049334','2354fc63-1227-44cf-aa8d-83455354b140',1940,'湖南籍？实为福建人','湖南籍？实为福建人，但伪政权活动与湖南邻近省份有关，间接影响湖南。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67f72c8bcefa426f8a458c6c78cd3aba','acf82f4a-1e5a-4cc2-9e98-070cf4444def',1940,'湖南浏阳人','湖南浏阳人，汪伪政权中任伪湖南省政府主席，直接参与湖南沦陷区伪化统治，与永州零陵地区有行政管辖关联。','危害等级B（乙级，市县厅局级）','hanjian');
