INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-edc75ce913ea492b88019ad9348d826d','f7077434-6cf5-42f9-9058-3213765019cf',1939,'湖南湘乡人','湖南湘乡人，汪伪政权重要成员，参与伪政权司法与地方行政，其家乡湘乡与湘潭相邻，对湘潭地区伪化统治有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
