INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f721ee0d59c4e10853835e77c9880e9','b632228a-72c2-4503-abc3-949d1e92624d',1939,'湖南常德人','湖南常德人，汪伪特务与行政高官，参与伪政权特务活动，其湖南籍背景使其在湖南沦陷区有一定人脉与影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
