INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e94ec5a0a8f4c4aa51b3f973e1216b4','c3f6aba2-2b5a-4096-a8c8-11c04b999ad2',1944,'1944年日军攻陷湘潭后','1944年日军攻陷湘潭后，当地成立维持会，会长由地方士绅或地痞出任，协助日军征粮、派夫、维持治安，具体姓名在地方志中记载不全。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf79f63eae184b5b9a7b74a178be49fe','c3f6aba2-2b5a-4096-a8c8-11c04b999ad2',1944,'1944年日军攻陷湘潭后','1944年日军攻陷湘潭后，当地成立维持会，会长姓名在地方志中记载不全，主要负责为日军征派粮食、民夫，维持占领区秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e7e3fed02ef4cbc992eaae7a5c47b4c','c2bc8682-9029-4304-a528-373ae747bae6',1944,'日军侵占湘潭期间','日军侵占湘潭期间，岳塘一带设立伪保甲组织，保长负责摊派捐税、抓丁拉夫、传递日军命令，具体姓名多已失载。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-739bfa59a7eb4e97adc6a8da47712911','b525471e-87c8-4347-927d-adf5325fb942',1944,'日军侵占湘潭后','日军侵占湘潭后，出面组织伪湘潭县维持会，协助日军征粮、派夫、维持地方秩序，为日军占领当局服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75473f58c6aa450da99cc8b74866534e','06afe20c-f628-4074-8a7e-7949ec1cadfb',1944,'抗战后期湘潭沦陷期间','抗战后期湘潭沦陷期间，出任伪湘潭县县长，主持伪县政，配合日军推行保甲、征发物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18e2f98be7a04b8986ee700dc159c5db','3a217d34-60c3-49b6-a466-002efb588ea9',1944,'湘乡沦陷后组织维持会','湘乡沦陷后组织维持会，替日军筹粮筹款、拉夫，并协助建立伪基层政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1183ddd4788443faa8d8bd1b69d2edb6','ba460483-a67f-4a97-adc8-f1fe9c2a1a72',1944,'日军占领湘乡期间任伪县长','日军占领湘乡期间任伪县长，推行伪政，协助日军控制湘乡地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1919bbe86d7d46a9883f6ea02397f932','f92400d8-5825-46f7-8561-ace2d5ca8898',1944,'汪伪政权高级官员','汪伪政权高级官员，1944年后任伪湖南省政府主席，主持湖南沦陷区伪政，推行日军占领政策，搜刮物资、镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fdda5e20c524250b1be1219ac3476e8','4a07a74a-0298-4a37-bdca-df03339dcf1d',1938,'汪伪政权核心人物之一','汪伪政权核心人物之一，湖南籍，虽主要活动于南京、上海，但其伪政权体系覆盖湖南沦陷区，对湖南伪政权的建立与运作有直接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-adcda78a26dc4668bb51db7532f91914','079a721b-f277-4a7e-b6a6-5ba04f0f59c5',1939,'汪伪政权军事与地方伪政要员','汪伪政权军事与地方伪政要员，活动于华中地区，其伪军体系与湖南北部沦陷区有联系，配合日军对湖南的军事行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e0f6940757c4937ab72d629a2a7321c','39950067-30a7-4467-afaf-353717303c12',1944,'湘潭沦陷期间任伪警察局长','湘潭沦陷期间任伪警察局长，协助日军维持治安，抓捕抗日人员，推行保甲连坐。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8008d5965f446debfe1f937e7cd6230','4bae68db-c669-444f-97e2-a86ffb4b2043',1944,'湘乡沦陷后率部投敌','湘乡沦陷后率部投敌，任伪保安团团长，配合日军扫荡抗日游击队，征发民夫。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94f03d33e6fa45b289c6573fd3ac98b7','e76eb119-8c8b-41c6-8211-7e8dcfb3c4f3',1944,'在湘潭沦陷区主持伪教育会','在湘潭沦陷区主持伪教育会，推行奴化教育，改编教材，宣传“大东亚共荣”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-160417bc87f742d6b32a015fdff85ebe','b3a51013-cb56-4598-9209-55635e29760e',1938,'北洋时期湖南军阀','北洋时期湖南军阀，抗战期间滞留湖南，曾与日方接触，被日方企图拉拢组织伪政权，但最终未公开附逆。历史记载其态度暧昧。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca62c77ec68c451caa6c4723f4a3175f','73331651-6625-4c31-ba89-d6f79d166448',1938,'陕西渭南人','陕西渭南人，在湖北沔阳一带坚持抗日，后被日军俘虏，未任伪职，不属汉奸。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97fa3d5ff70d4b19aca1887bd667abdd','2d504e3d-d946-41bf-86cc-6e8271ca7626',1944,'1944年日军侵占湘潭后','1944年日军侵占湘潭后，当地成立维持会，会长姓名在地方史料中记载不全，负责为日军筹粮、派夫、维持伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f94a358258134d6f9bfc9e556adc74c7','36b5c8e0-13dd-41b0-bd6e-9e7902948927',1944,'日军占领湘潭期间','日军占领湘潭期间，伪警察局协助日军搜捕抗日人员、镇压民众，具体姓名在现存史料中多缺失。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1e9fe7f05a9409eaa5117bc4a99b12a','5688f18e-cc50-4610-ae88-e6cc3eb62fa8',1944,'日军侵占湘潭后','日军侵占湘潭后，九华一带部分保甲长被迫或主动附逆，为日军征粮、派丁、传递情报，具体姓名散见于地方档案，但系统记载极少。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d3e8009beaf416998fe38ae6a9d8e3a','e097e585-0d86-412c-8445-fc6b70cd8bea',1944,'1944年长沙沦陷后','1944年长沙沦陷后，伪维持会为日军服务，会长姓名在部分文史资料中有提及，但与湘潭无直接关联。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8752e060fd994fe6848b8a013453c88d','ed183a35-8393-453b-87be-9589ece7b3dd',1944,'日军侵占湖南部分地区后','日军侵占湖南部分地区后，曾试图建立伪省政府，部分附逆人员参与筹备，但未能正式成立，姓名记载零散。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98bc13873c9642c4a08a0a058a11af52','7b992968-ab26-49b2-9cc5-a0bd435d8d2a',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，任伪行政院副院长、财政部长等要职，推行伪币、搜刮物资，后与重庆方面暗中联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c8c2edbe13247d7a090d7ee805a30ca','0d72b5bb-9f18-4a80-a20b-d180052861e3',1939,'湖北黄陂人','湖北黄陂人，长期在湖南、湖北活动，投靠汪伪后任伪陆军部长、伪武汉行营主任、伪湖北省长，在湘鄂地区组织伪军、配合日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17c9a1b0b5e4481cb691267eba26cace','0d72b5bb-9f18-4a80-a20b-d180052861e3',1939,'湖北籍伪军头目','湖北籍伪军头目，活动于武汉及周边，与湖南北部沦陷区伪军有联络，曾参与收编湘北伪军和维持会武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1de2a9016ee24be08906181b9f32b4ed','2b788d83-9d32-4103-99a3-7c46ae570a59',1930,'湖南长沙人','湖南长沙人，早年参与围剿红军，1931年被俘处决，其部属部分在湘中地区活动，与日伪有间接关联，但本人主要活动于抗战前。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-722071df2a17467b82984e8fbc2e74af','65c06b5f-ce2b-4136-9e50-88394115cf83',1940,'湖南湘潭地区部分维持会、保甲长在日军占领期间协助征粮、派夫','湖南湘潭地区部分维持会、保甲长在日军占领期间协助征粮、派夫，但具体姓名多不可考，彭孟缉为台湾高雄人，与湘潭无直接关联，此处仅作示例说明地方维持会现象。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6069a1159f1a44a587766fb56de13789','fcd83433-6649-4516-959e-4f567b49049b',1944,'日军占领湘潭期间','日军占领湘潭期间，雨湖地区设有维持会分会，成员多为当地士绅或地痞，协助日军管理户籍、征收物资，具体姓名在现存史料中极少记载。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7f5de53abd84d2c9cd39c24f291e2db','1317f563-8891-49af-a987-f8b0e15d106c',1939,'湖南湘乡人','湖南湘乡人，早年加入中国共产党后叛变，抗战期间投靠汪精卫，历任汪伪政权要职，参与伪政权统治，为汪伪集团核心成员之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a0179ee98fa4ed09126be3ff2216e94','3f5f1879-5eeb-405d-b22b-88892a6c9f68',1938,'湖南沅陵人','湖南沅陵人，中共一大代表后叛党，抗战期间投靠汪精卫，成为汪伪政权核心人物，掌管财政与特务警察系统，配合日军统治沦陷区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6f86522bbe1403d9efff89edb9823b6','3f5f1879-5eeb-405d-b22b-88892a6c9f68',1938,'原为国民党要员','原为国民党要员，抗战期间投靠汪精卫，参与建立汪伪政权，历任伪财政部长、警政部长、伪上海市长等职，为汪伪政权核心人物之一，在重庆时期即与汪精卫暗中联络，后公开叛国。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6a47dca8f3340f8852e1c24cf869c38','20c0dbd0-4d22-4f24-8358-9d854e9531f7',1939,'湖北人','湖北人，但与湖南军政界有联系，投靠汪伪后负责华中地区伪军与伪政权事务，配合日军清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35db64264b444981b09d4cd906590fa3','cf98f94a-518f-4426-92a5-1de082aa2b1d',1930,'湖南长沙人','湖南长沙人，早期参与围剿红军，虽非严格意义汉奸，但在抗战前的地方军事活动中与湘西地区有交集。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32bf730802914c1d8b5645a849e66e4c','a4358b76-a3eb-47d4-8471-d766793dc63f',1931,'湘西凤凰人','湘西凤凰人，长期统治湘西地区，抗战期间虽名义上抗日，但与日伪方面有暧昧接触，保持地方割据，未积极抗日。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c31045c40bab4d0a83303178bce5321f','6f2cc1ca-bf8d-4ae7-8a4e-9cdc0e5357fa',1931,'湘西凤凰人','湘西凤凰人，苗族地方武装首领，抗战期间在湘西地区活动，与日伪有间接联系，维持地方势力。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f6b8d14600084a82841ac02e54f2d819','dc6087f3-73a7-48ad-8264-8487d0ba54de',1930,'湘西地区土匪首领','湘西地区土匪首领，抗战期间在湘西一带活动，曾与日伪势力有勾结，扰乱地方抗日秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-51bcb0b67c3d4d3989597c885f310c2b','f46fe331-49eb-49bd-acf1-90d5346999bd',1930,'湘西龙山人','湘西龙山人，长期在湘西地区为匪，抗战期间与日伪及地方势力有复杂关系，未积极抗日。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b01b9a1ded95435db5904d9d6b81d973','a0c73284-a01b-4f16-a88a-1b5929a06737',1930,'湘西龙山人','湘西龙山人，地方武装首领，抗战期间在湘西活动，与日伪有接触，维持地方割据。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2b5ce22f5ff4b6890a4f481ef07d5a7','59b60e77-0c77-4816-8d7d-b88414cd1878',1930,'湘西地区地方武装首领','湘西地区地方武装首领，抗战期间在湘西一带活动，与日伪势力有联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9450fcc179e4196817e0c272aa53d8c','a714cec8-0c06-44c0-a0ea-d11fc86c50e3',1943,'日军侵占古丈期间','日军侵占古丈期间，出面组织古丈县维持会，为日军征集粮食、民夫，协助维持占领区秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72593527262742a9b5412b92c418dccd','dffeb301-9423-471a-95b4-0677ad85b2cc',1930,'湘西古丈、沅陵一带地方武装首领','湘西古丈、沅陵一带地方武装首领，抗战后期与日军及伪政权有勾结，接受伪职，配合日军清乡，残害抗日军民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f9d49d1aa9c438ab545faf817f482c7','4f977718-ce09-4514-bb55-9c60e3d8ecb9',1930,'湘西地方实力派','湘西地方实力派，抗战期间曾与日伪方面有秘密接触，其部属在湘西部分地区与伪军合作，但本人是否正式投敌存在争议。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e2439a248af4f17abebc027bda60b2e','dce4d7a2-ffdb-428b-8ed4-07581b31de62',1940,'湘西一带土匪武装','湘西一带土匪武装，抗战后期投靠日军，被编为伪军，在古丈、保靖、永顺等地为日军搜集情报、抓捕抗日人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12994b1de5574e9f9be013cbb7dcf109','bf0db241-361c-4122-824f-195647194aa9',1944,'抗战末期在湘西地区组织伪军','抗战末期在湘西地区组织伪军，配合日军进攻湘西抗日根据地，在古丈、沅陵交界地带活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-943c32aa8b4945fbaa008bc5bfb194d8','bf0db241-361c-4122-824f-195647194aa9',1944,'湘西地区人','湘西地区人，1944年组织伪湘西自治军，配合日军在湘西进行军事活动，维持伪政权地方秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e695bc5b4ea0446dbeac1bddf5db508e','671dc653-0b32-4d59-8f12-3653416ebad3',1943,'在湘西苗区为日军组织维持会','在湘西苗区为日军组织维持会，征派粮款，协助日军统治，活动范围包括古丈、花垣一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f20102521f2410d8e7bca83b3c9c88b','ff0142bc-a6f3-40b3-9c48-c1b35cb2caad',1944,'日军占领古丈期间出任伪警察所长','日军占领古丈期间出任伪警察所长，带领伪警察搜捕抗日分子，镇压当地民众反抗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71eb94997581414695f2401d880bd7aa','e4d25a77-7653-49bc-b29c-a12d6c8a7f53',1943,'在古丈县担任伪保甲长','在古丈县担任伪保甲长，为日军派夫派粮，监视村民，举报抗日活动。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-463402a842af479e943d5336fd431682','9c9021a4-0a32-4520-8fa9-c4f92d667736',1944,'在湘西伪政权中负责教育','在湘西伪政权中负责教育，推行奴化教育，编写亲日教材，在古丈等地学校强制使用。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b8114f54d634021ac3d7986deb9c601','e5360540-0a7d-4b88-be89-769a018c1904',1944,'组织古丈县伪商会','组织古丈县伪商会，为日军筹款筹物，协助日军经济掠夺，压迫当地商户。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19ecf9934514499ab219bd56e846de65','29be638b-3e19-4c46-95d0-9f8745ed622f',1938,'湖南沅陵人','湖南沅陵人，汪精卫伪政权核心人物之一，参与对日投降与伪政权建设，虽主要活动于南京、上海，但作为湖南籍汉奸代表人物，与湖南地区有籍贯关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2371a999fd30491f931677eb32ca0801','1076267e-802a-4ad9-bfe3-353d763c452c',1939,'湖北黄陂人','湖北黄陂人，但在湘西及湖南地区有活动，曾率伪军配合日军进攻湖南，与湘西地区军事行动有直接关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e204b40f215344fe9b9de8d5722b07d5','1076267e-802a-4ad9-bfe3-353d763c452c',1939,'湖北黄陂人','湖北黄陂人，长期在湘鄂赣地区活动，组织伪军配合日军清乡，镇压抗日力量，其势力范围一度覆盖湘北。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-920b17c7cb5d413f962fa8e5bda2f037','453c3f4e-51a1-4ecf-ab32-c158ea99480a',1933,'湖南人','湖南人，旧军阀，1933年投靠日本，在华北从事伪政权活动，虽主要在华北，但作为湖南籍附逆人物被记载。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c6790ec77554beb814c65484a4fab18','72ef2e64-839d-4a7d-ab16-90ff570ef48d',1943,'湘西凤凰人','湘西凤凰人，苗族地方武装首领，抗战后期与日军及伪政权有接触，被指在湘西地区配合日伪行动，维持地方伪秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fab33acfbdd04704aabd921eff5a00c9','5a0735a9-4e8a-4a22-ae34-19cd2ae46dd9',1939,'湘西凤凰人','湘西凤凰人，长期统治湘西，抗战期间与日伪方面有暗中联系，其部属在湘西地区有附逆行为，本人被指态度暧昧。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6f083df09464a528b9f75cb2fba9c64','47f9a067-a818-4501-8096-ea8b6d4746ca',1944,'湘西吉首地区人','湘西吉首地区人，1944年日军侵入湘西时组织伪维持会，协助日军征粮、拉夫，维持地方伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2f812869677485fb39a769dbce75f82','63a94ddb-bd07-4fd7-9272-116337a07252',1944,'湘西保靖人','湘西保靖人，日军犯湘西时出面组织维持会，为日军提供物资与情报，协助伪政权控制保靖一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5850c257b0941cd82329b385da033c4','d8ad7117-a265-4f89-a771-7d5f7866da93',1943,'湘西古丈人','湘西古丈人，土匪武装首领，抗战后期与日军及伪政权勾结，在湘西地区劫掠并配合日伪行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
