INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6fa2ba05ee6e4db1a707174454616898','8eb60ca8-2f19-4788-9f6c-b625063ccd0f',1944,'湘西永顺人','湘西永顺人，土匪首领，日军侵入湘西时投靠日伪，率部配合日军骚扰抗日后方。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
