INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3368dc5978540e0afb2f445a1a3b715','b0e7cccf-c828-4d20-8bb0-1b0c7bf1c3ec',1944,'湘西地区人','湘西地区人，1944年组织伪湘西保安部队，配合日军在湘西进行军事活动，维持伪政权地方秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9445c7bafc04bca8be9ed358758d3dc','8ce5fc4e-478d-4961-99bf-316fa7ce4b8e',1944,'湘西人','湘西人，与周燮卿共同组织伪湘西自治军，配合日军在湘西地区行动，协助伪政权控制地方。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59f67c77282445a0a7c93eaceb84355a','7552fd48-c9e9-4a99-b67b-2f59e13d65f0',1944,'湘西地区人','湘西地区人，1944年日军侵入湘西后组织维持会联合会，统一协调各县维持会，协助日军控制湘西。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5785f7aaac34cad88485f11d50a535c','9c75b4e1-3d06-447d-8030-09ba9576bd19',1943,'抗日战争后期','抗日战争后期，日军进犯湘西期间，罗子云在永顺地区出面组织伪维持会，协助日军征派民夫、粮食，并参与诱降地方武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1927840459b4a9a8f4e0b6ab1b6f3e4','8a97f5ef-4b19-409b-ad87-2d957b04f95d',1944,'湘西土匪出身','湘西土匪出身，抗战末期投靠日军，被委为伪湘西自治军司令，在永顺、龙山、桑植一带收编土匪，配合日军骚扰后方。','危害等级C（丙级，基层头目）','hanjian');
