INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5200a7936aab4f5aafe851e55157ebc4','31b4f296-cc8e-473a-860d-2472ac532cb8',1944,'原国民党地方武装将领','原国民党地方武装将领，抗战末期在湘西投敌，任伪湘西保安司令，协助日军维持湘西占领区秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14fea022c45e4babbc388cde17eb0ff3','88a023fa-fe6c-4183-828d-8a1253783f48',1943,'湘西地方实力派','湘西地方实力派，抗战期间曾与日伪方面有秘密接触，日方拟委其为伪湘西绥靖公署主任，后因形势变化未公开就任。','危害等级C（丙级，基层头目）','hanjian');
