INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93c93129260e454cad69ac60baeae8d6','95bba7fa-9693-418c-bf09-8b268d098ef2',1944,'湘西帮会头目','湘西帮会头目，抗战末期与日伪勾结，组织伪军，在永顺、芷江等地进行反共及协助日军活动。','危害等级C（丙级，基层头目）','hanjian');
