INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85e91ac6a48447ff8f9ea895d7f50fa1','bf99226b-36d5-4e3b-ad98-a48d696581c8',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪内部，曾任伪军职，在沦陷区活动，与湖南及益阳地区日伪势力有联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41cf001db2984ff181ff4545f28ad5ea','bf99226b-36d5-4e3b-ad98-a48d696581c8',1940,'湖南东安人','湖南东安人，受重庆方面派遣打入汪伪政权，曾任伪军事委员会委员等职，在沦陷区活动，与湖南籍军政网络有关联','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7547b5cd3e674829b69758b370acc10a','bf99226b-36d5-4e3b-ad98-a48d696581c8',1940,'其身份具有潜伏性质','其身份具有潜伏性质。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e697809c0d84217a2d16b9ac445489b','8cacd22c-1134-4a3c-b613-b45c5b891b67',1939,'湖北籍伪政权要员','湖北籍伪政权要员，活动于华中地区，与湖南日伪势力有联络，参与伪军组织与清乡，镇压抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b1472f1bcf34ef2a0c9bd71216e16e3','7599693a-c765-4d8b-9cd8-188f395c78fe',1941,'原国民党军将领','原国民党军将领，率部投敌，任伪军高级头目，在华中包括湖南周边地区配合日军进行扫荡与清乡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8175817e04743a99bb935318fa1bc23','002d1561-522d-4479-bb0a-abba908c1303',1940,'湖南籍伪政权官员','湖南籍伪政权官员，曾任伪湖北省长，参与华中沦陷区伪政权管理，与湖南日伪势力有行政联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19b7f42e17d4493988382f410030110d','1ca10254-449b-4978-90f0-2d0c93930475',1943,'曾任汪伪湖南省长','曾任汪伪湖南省长，直接负责湖南沦陷区伪政权，推行日军政策，征粮征丁，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5e245b827f949ab94503b065364ab49','48010c46-4f0d-4ce5-8407-569010f764b0',1944,'湖南籍伪官员','湖南籍伪官员，继任汪伪湖南省长，在湖南沦陷区维持伪政权，协助日军统治，搜刮物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf272dc4be8e46f49b7aa2335e9cc518','80a7d09c-ddc0-4d7e-bc3d-0d6c55eb3a96',1933,'湖南籍旧军阀','湖南籍旧军阀，投靠日本，在华北组织伪军，参与分裂活动，后因内斗被杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54e0112404e34178ad9990895da720cd','80a7d09c-ddc0-4d7e-bc3d-0d6c55eb3a96',1933,'湖南籍旧军阀','湖南籍旧军阀，北洋时期曾任湖南督军，后投靠日伪，任伪华北政务委员会顾问等职，在华北进行汉奸活动，与湖南衡阳、南岳地区有籍贯关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b94ada0c5394bbcaa0744f4e523d758','44b2f811-8b3d-4cc4-b9cb-1a438c4ef39f',1944,'益阳沦陷期间组织伪维持会','益阳沦陷期间组织伪维持会，为日军筹粮筹款，维持地方伪秩序，协助日军统治益阳地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ca8f5990d994d8a87a8ce0db7102fd8','38234880-251a-4997-9d46-04a7dbf0e79b',1944,'在益阳沦陷区任伪警察头目','在益阳沦陷区任伪警察头目，配合日军搜捕抗日人员，维持伪治安，欺压百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7c739bf3e694fec8fcc82b54464bc7e','48fc7ffc-d0c6-47b7-8526-95bbb73ca33e',1943,'沅江地区伪维持会负责人','沅江地区伪维持会负责人，为日军征粮征夫，协助日军控制洞庭湖区，与益阳大通湖周边日伪势力有联系。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e22008a72ad241f19bc7439faee291af','46378b20-1409-4dd0-9c7f-38f00a40a167',1943,'南县沦陷区伪维持会头目','南县沦陷区伪维持会头目，配合日军在洞庭湖周边清乡，搜刮物资，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e6408d602bb4179b739d69780e258d4','7d8cb034-0c9e-40e4-bd1e-9e0b509b4d97',1943,'华容地区伪保安团头目','华容地区伪保安团头目，率部投敌，配合日军在洞庭湖西岸包括益阳大通湖周边进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff8b0e7ee68d46cb8e829793e8f2b7a7','d77a6622-c1d1-41e6-8e71-7dfef3470764',1938,'岳阳沦陷后组织伪维持会','岳阳沦陷后组织伪维持会，为日军提供情报与物资，控制岳阳及洞庭湖出口，与益阳地区日伪有联络。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-572f96bed32841af8a0e95b02171aad8','6b8737ad-207b-486b-bd0d-5fa896a6ad3e',1944,'长沙沦陷期间任伪维持会头目','长沙沦陷期间任伪维持会头目，协助日军管理长沙，征调民夫物资，影响湖南包括益阳地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ff7eb36cc7a49b0a3cce5f512ec1efb','5e269960-0a3e-4b6a-bf49-3995db078210',1944,'宁乡沦陷区伪维持会负责人','宁乡沦陷区伪维持会负责人，为日军筹粮，配合清乡，与益阳邻近地区日伪势力有联系。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de1abdb415c84523a0e8bfceeeebf303','70c5a865-4533-4e70-bd37-df891733204b',1944,'湘阴地区伪保安队头目','湘阴地区伪保安队头目，投靠日军，在湘阴及洞庭湖周边进行伪化活动，与益阳大通湖地区有接触。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19967b8cdbd94e52bab7a13b98e4d312','da47a257-86e4-4731-a7ed-453772daebde',1937,'湖南旧军阀','湖南旧军阀，抗战初期与日方有秘密接触，虽未公开投敌，但其部属在湖南沦陷区有附逆行为。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a1d98546b1644a9b22206143c3cd168','609b8129-360d-4380-8fcb-34d2ac7f7aba',1944,'益阳沦陷期间出面组织维持会','益阳沦陷期间出面组织维持会，协助日军征粮、派夫、维持地方秩序，为日军在益阳地区的统治提供基层支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9726b4a5944f429f9884657406179c8c','48906473-e752-452f-8f6b-d5fcda61a653',1944,'益阳沦陷后投靠日军','益阳沦陷后投靠日军，担任伪警察局长，协助日军搜捕抗日人员、镇压民众反抗，控制益阳城区治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-204a7c2c56f14050a343f7b792560995','840aab56-bd0b-4664-aa48-a30c14781432',1944,'组织伪保安团配合日军扫荡益阳周边乡村','组织伪保安团配合日军扫荡益阳周边乡村，参与清乡与征粮，镇压抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f27e72cc20d44e4b9161fb75375ca956','30a5dea7-0a72-4552-a4e5-a9d4f404d192',1944,'在益阳兰溪一带组织维持会','在益阳兰溪一带组织维持会，为日军筹集物资、情报，协助日军控制水路交通。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e331f6f9182459bbe3471b6ec4af2b7','06ca4551-636f-4863-a22d-c58b72cdab91',1944,'担任伪保长期间','担任伪保长期间，为日军征派民夫、粮食，举报抗日人员，协助日军维持基层统治。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7e1ccb693be42e490bd14a5bffd4084','751ba33a-4179-41f5-b1db-097d5c03d1b4',1943,'沅江沦陷后组织维持会','沅江沦陷后组织维持会，配合日军在洞庭湖区征粮、捕丁，协助日军控制沅江与益阳交界地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81c59dac5ab946199b866e0df9b102bf','726072df-e2c5-42bf-a850-0e669bdabe62',1943,'在南县一带协助日军建立伪政权','在南县一带协助日军建立伪政权，参与征粮、派款，配合日军对洞庭湖周边抗日武装的清剿。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35d50f4d4aaf4a60b41b5bb6a7b28891','8c8e3eea-994b-46a8-9626-b03f95ffea66',1943,'率伪保安大队配合日军在汉寿、益阳交界地区扫荡','率伪保安大队配合日军在汉寿、益阳交界地区扫荡，参与抓捕抗日人员与掠夺物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17de61a4b086408d917de1312cd6445a','f025cd46-f084-49fd-9a1a-96e10f3797e3',1944,'原国民党湖南省主席','原国民党湖南省主席，抗战后期被汪伪政权任命为湖南省政府主席，虽未实际掌控湖南，但其名义附逆对湖南伪政权体系有影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcd42e018f3f4c2b8009256089e67a20','72d16ca4-789f-4abf-8921-beb861c50cff',1939,'湖南湘乡人','湖南湘乡人，汪伪政权重要成员，参与伪政权警务与地方行政，其附逆活动对湖南籍人员投伪有带动作用。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-054033b52e6f4196a172f83dce6b97d8','5a8869e9-a579-448c-9601-04248d8cbac2',1944,'在长沙沦陷后参与伪政权','在长沙沦陷后参与伪政权，协助日军维持长沙及周边地区统治，与益阳伪政权有行政联系。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4dbd0037e3844cc8ddf7f5a39983d27','20eff81f-91a0-4e2b-a2b0-a87f09ca6987',1940,'湖南浏阳人','湖南浏阳人，投靠汪伪，参与伪军事机构，其附逆行为对湖南籍军人投伪有影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d603796aa63404984b1ee761f61f89b','60cb7121-ca1c-4206-a920-db7ad08d6685',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，推行伪化统治，为日军侵华提供财政与警务支持。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1cb7eda25134b3eb15c542ff0b5b073','cbf9815e-f65f-4dee-a3b9-57a903511ca3',1944,'益阳本地士绅','益阳本地士绅，日军侵占益阳期间出面组织维持会，为日军征粮派夫、维持地方秩序，协助伪化统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-151aca2caf3043fc85b48d8a0a16dc3f','3a8caaf9-1e7d-4a97-9020-dc7a90df815f',1944,'益阳资阳地区人','益阳资阳地区人，日军侵占期间协助组织维持会，负责摊派粮款、招募伪职人员，为日军提供情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37e0a734acd94308827af4860867f016','07bfde5e-7c7f-453d-971e-14dd05dcc619',1944,'组织伪保安团配合日军扫荡益阳周边抗日武装','组织伪保安团配合日军扫荡益阳周边抗日武装，参与清乡行动，镇压当地民众抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-713614f68ef04275950c2c6f0cdbfd0d','8d3c5179-f7dd-462c-8f2d-819a17dadf82',1940,'湖南本地人','湖南本地人，投靠日军后组织伪军盘踞湘中地区，在益阳、宁乡、湘乡一带进行清乡，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c82525cbef9b42e097e12820dd0a1c8e','c7db1c87-74af-47a4-8f19-65388587247d',1944,'在日军占领期间推行奴化教育','在日军占领期间推行奴化教育，篡改教材，强制学校教授日语和亲日内容，为伪政权培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c372f01c609c45d0b0459a033b5e69c3','98522016-112f-413a-8ebf-635303f6f874',1944,'协助日军控制益阳物资流通','协助日军控制益阳物资流通，为日军采购军粮和战略物资，压榨当地商户和百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa99ead19e194bb1ac0226fe9d34ee08','71a3fea0-d22f-492d-8cc4-fb62710b8b57',1944,'日军侵占益阳期间出面组织维持会','日军侵占益阳期间出面组织维持会，协助日军征粮、派夫、维持占领秩序，并参与筹建伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-870654312cec4f44af7aa7e24bd48618','e951a04a-dd67-44e0-89e8-8ed892abec3b',1944,'组织伪保安团','组织伪保安团，配合日军对益阳周边乡村进行扫荡、清乡，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86b92d3a1b5b421bacf00d8655b58a39','f9454d61-7423-4e54-ac09-fd9737057ea4',1944,'率伪军盘踞益阳、沅江一带','率伪军盘踞益阳、沅江一带，为日军搜集情报、征发民夫，并参与对洞庭湖区的控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1e9f00338084887b88cb99257dfbf72','c564e1af-5e24-4661-b673-486c026bfa5c',1944,'在沦陷区推行奴化教育','在沦陷区推行奴化教育，改编教材，强制学校讲授亲日内容，并组织教师参加伪政权培训。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-908f27d5e8524611812287f09ceaf137','2892122a-698f-445b-b37e-59cb9d57b532',1944,'抗战后期投靠日军','抗战后期投靠日军，在益阳县城主办伪宣传刊物，为日军“大东亚共荣”宣传造势。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8599591c8b05412c906bfd9ddafa3b23','47e65fce-fc9b-4ef2-af06-99cbfbe6a9e1',1944,'受日军指使控制益阳城区商业','受日军指使控制益阳城区商业，强制商户交纳“治安费”，并为日军采购军需物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebcccb91a5b248c9ba4b6784291b37c4','771d629f-919c-497d-aa15-bfb9e2283fdc',1944,'在益阳兰溪一带组织维持会','在益阳兰溪一带组织维持会，为日军征集粮食、船只和民夫，协助日军控制资江下游。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c961a94d4113495585f89d2b68b0b886','b2c7239e-0ec9-487e-8c8a-7d504ef68cb4',1943,'在沅江沦陷区组织维持会','在沅江沦陷区组织维持会，配合日军对洞庭湖周边益阳、沅江地区进行物资掠夺和情报搜集。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7921b5189a564747a4eab47c5d38ef29','d389d772-726f-43ad-ba43-dae70c7555d2',1944,'在长沙、益阳等地参与日伪政权筹划','在长沙、益阳等地参与日伪政权筹划，协助日军推行保甲连坐，镇压湖南抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd66bc7f3c924e3a99fa84c5715aa4ce','4458eaf2-d584-458b-b6c3-3d867463863d',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实际从事策反与情报工作，属于特殊背景人物，常被列入湖南籍附逆人员讨论。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3abd16925ad74200ae13361d122879c1','5dbf3998-571d-420c-bc0b-0e8006e07da3',1933,'湖南籍旧军阀','湖南籍旧军阀，1933年投靠日本，在北平活动，被军统刺杀，是湖南籍早期附逆人物之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60110d00b94849a08cfe816e4e0ae7d2','7f6e7f27-276c-4a8e-b045-aba19630cc9b',1944,'衡阳沦陷后','衡阳沦陷后，参与组织地方维持会，协助日军征粮、拉夫、维持治安，具体事迹散见于衡阳地方文史资料。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9028d7b04b0748c6a827da73f77069fc','3c1108c6-5ad8-496a-995b-0d7993589c68',1944,'衡阳沦陷期间','衡阳沦陷期间，部分地方士绅出面组织维持会，罗树甲被地方史料提及为参与维持会活动者之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da5f3b309a2c48dd9aa6933d1b71a7e8','addd5520-11db-4451-b65a-5b84a1277eb0',1944,'衡阳沦陷后','衡阳沦陷后，日军扶植伪政权，王翦波被部分地方资料列为参与伪县政筹备人员，但记载简略。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4936e82aed1c4a618234b2b08b92caf4','f41f9278-e6f2-4458-a9b2-4f0d6454020e',1944,'衡阳沦陷期间','衡阳沦陷期间，部分商会人士与日军合作，协助摊派物资、维持市场，黄子卿被地方史料提及。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c1e8c4e140c43b888fbfbd56b8eda58','dcb16358-9ea6-49cb-ba6b-47627c3423a3',1944,'湖南沦陷区伪军头目之一','湖南沦陷区伪军头目之一，参与收编地方武装，配合日军对湘南地区进行扫荡与治安作战。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56aaf1f09a2040ffa65db060219d8c51','96997c38-2fdc-4e67-b7c1-35f1129aece0',1940,'湖南籍','湖南籍，汪伪政权中任伪职，曾被任命为伪湖南省长但未实际掌控湖南，仍属湖南籍附逆要员。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0bc8b1132324431bba42a9b863702d3','765ba5a6-739d-490c-a498-201a68d55175',1944,'长沙、衡阳沦陷后','长沙、衡阳沦陷后，伪政权在湖南设立机构，黄自强被部分资料列为参与伪政权的地方人物。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f35fbf05f0b4641ae1949efa66f68c4','1dc7a0e0-d985-4475-a77d-e6f906c0c233',1944,'湘南地区地方武装头目','湘南地区地方武装头目，投靠日军后参与维持会与伪军活动，在衡阳周边地区协助日军征粮、清乡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccde255c87d64c99bc0125da275104ba','d100d59f-4a54-49ca-ba07-e9d57d0a50c5',1944,'衡阳沦陷期间','衡阳沦陷期间，部分教育界人士参与伪教育机构，推行奴化教育，陈漱云被地方文史资料提及。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1486c13bfdea476ea7be6ab2843015e7','4bc18512-9a60-4273-b832-d6e50c53643a',1944,'湖南沦陷区伪税务人员','湖南沦陷区伪税务人员，协助日军征收赋税、掠夺物资，活动于湘中、湘南地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d19e0f66110849689f43e94d85689884','e136f17c-3ca0-4ebf-b188-5a12b7ce6849',1944,'衡阳沦陷后出面组织维持会','衡阳沦陷后出面组织维持会，任会长，协助日军维持地方秩序、征派物资、诱降民众，直接活动于衡阳地区，与南岳邻近。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ecb09fe9a4de4ca99ebf689faf9e73ef','f07f5eb1-d673-4ed7-b49a-2556426c4d98',1944,'衡阳沦陷期间任伪警察局局长','衡阳沦陷期间任伪警察局局长，协助日军镇压抗日活动、搜捕抗日人员，直接活动于衡阳地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-87544da989b0464fa3091632e6e14217','3dd684c6-f3f5-43ed-8655-5c98348227da',1944,'衡阳沦陷后组建伪保安团','衡阳沦陷后组建伪保安团，任团长，配合日军清乡、扫荡，活动于衡阳及南岳周边地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8415ebee1ab44febedb40d49e415814','e91c7dfe-4d30-452e-9314-9ed89fa56c9a',1944,'湘南地区伪军头目之一','湘南地区伪军头目之一，衡阳沦陷后投靠日军，参与组织伪军和维持会，在衡阳、南岳一带进行伪化活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-405654baef7545048abeefe24b247837','9fecd5f2-b987-4335-bf4d-7dba6687e517',1944,'汪伪政权在湖南设立伪省政府后','汪伪政权在湖南设立伪省政府后，任伪湖南省政府委员、伪衡阳道尹，负责衡阳地区伪行政事务，直接与衡阳、南岳地区相关。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-745f4e613a214182b466d66f575d5130','50d5a1e6-0a38-4b6a-81bf-49abc54626b1',1944,'汪伪湖南省政府警务处长','汪伪湖南省政府警务处长，负责湖南沦陷区伪警察事务，其管辖范围包括衡阳地区，协助日军维持伪统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb1c8a207ce04e39bd94cb6ac6eecba3','5924ab56-afca-424a-aa90-adb862f18119',1940,'湖南籍','湖南籍，汪伪政权参军处参军，后任伪湖南省政府顾问，参与湖南伪政权筹划，与衡阳、南岳地区有籍贯及人脉关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85c535838aa0420bbc137519ea3c3829','ef45aeec-a6f3-445a-8948-bc00448a20ee',1944,'南岳沦陷后组织维持会','南岳沦陷后组织维持会，任会长，协助日军管理南岳地区，征派物资、维持伪秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5f180887a89423eaca896b5b0a17902','96333b1e-8589-4df3-b8f4-dcfe635fd8bd',1944,'衡山（南岳所在县）沦陷后参与伪维持会','衡山（南岳所在县）沦陷后参与伪维持会，协助日军征粮、派夫，进行伪化宣传。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-625f13c2a0754ff2831e46cfa6a538f2','bed58ba4-75f5-45e5-a521-437c97a3325f',1944,'湖南沦陷期间附逆','湖南沦陷期间附逆，任伪湖南教育会会长，推行奴化教育，其活动范围覆盖衡阳、南岳地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13404d94a848495eb50fa02e45307ce6','a6c2828f-9070-4bfb-8b2e-c0b5e13f6aa1',1944,'衡阳沦陷后任伪商会会长','衡阳沦陷后任伪商会会长，为日军筹款筹粮，协助经济掠夺，直接活动于衡阳地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11a7ffdd68a64eb8be1011bf4a6bb37e','73c99b22-7236-44a6-92c5-f6071a68ffda',1944,'衡阳沦陷后组织维持会','衡阳沦陷后组织维持会，为日军征集物资、拉夫，协助日军管理衡阳城区，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03cfeef5f5cb47578d73cbdb93f8867d','621f0a12-c8a6-4cbc-8b73-fd3f4d7be188',1940,'汪伪核心人物','汪伪核心人物，其势力影响湖南，通过伪政权在湖南征收赋税、掠夺资源，支持日军侵略。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b0e7f10a5f74713b65fe4d284ef91ab','621f0a12-c8a6-4cbc-8b73-fd3f4d7be188',1940,'汪伪政权核心人物','汪伪政权核心人物，虽主要在南京活动，但其伪政权体系覆盖湖南，对湖南伪政权人事与政策有直接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9ca02897c484db6ba75c801105b3a56','621f0a12-c8a6-4cbc-8b73-fd3f4d7be188',1940,'汪伪政权核心人物','汪伪政权核心人物，虽主要在南京活动，但其伪政权体系覆盖湖南，对湖南伪政权人事与政策有直接影响，间接关联衡阳、衡山地区伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2894ff6934c4a48b872dc59a6fa097d','01c1bd69-792c-45de-ace2-a6e111b297ca',1944,'日军占领衡阳后出任伪县长','日军占领衡阳后出任伪县长，协助日军推行保甲制度，征发民夫，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-502008c24c6342789f6062e6bf6372ef','01c1bd69-792c-45de-ace2-a6e111b297ca',1944,'衡阳沦陷后任伪衡阳县知事','衡阳沦陷后任伪衡阳县知事，配合日军推行保甲制度、征粮征夫，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63e43b108dd64a309713e9ecbadaf39b','01c1bd69-792c-45de-ace2-a6e111b297ca',1944,'衡阳沦陷后出任伪县知事','衡阳沦陷后出任伪县知事，配合日军推行保甲制度、征发劳役、搜刮物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ceb73f2c966f46a584cf7591797e6dde','1e807bb9-e798-435b-a60d-67459f3da834',1944,'常宁沦陷期间组织维持会','常宁沦陷期间组织维持会，为日军筹粮筹款，诱降当地士绅，协助日军控制常宁地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
