INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66b972a8c54f4bbc8123e2fa46528587','a612c93e-f4e1-46ab-b730-20874763688f',1940,'在湖南沦陷区推行奴化教育','在湖南沦陷区推行奴化教育，编写亲日教材，组织学生参加日军宣传活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-460e286876074c9b8bafda3724833d23','194d392c-bdaa-4fb7-8cd3-ef3371f83b9f',1944,'控制衡阳商业','控制衡阳商业，为日军采购军需物资，强制商户缴纳“献金”，协助日军经济掠夺。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e43fc59f719143c4a0bbda14d68d1bc1','8faabf2e-093b-4e1f-924a-b8d9647815bf',1939,'湖北黄陂人','湖北黄陂人，汪伪政权军事头目之一，其伪军活动范围涉及湘北、鄂南，与湖南衡阳地区有间接军事关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-357fbf785b4e48adb4b98e6f89e21f16','74edaebb-dc66-42c5-b28b-50decff2d060',1932,'湖南衡阳人','湖南衡阳人，北洋军阀旧部，后投靠伪满洲国，任伪热河省省长，1933年被刺杀，属衡阳籍早期附逆人物。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81a943ae7f65424bad8a422da726143f','a2f64f18-8935-4ab5-b9ed-7b10714d1f46',1944,'衡阳沦陷期间','衡阳沦陷期间，出面组织伪维持会，协助日军维持地方秩序、征派物资，具体事迹散见于衡阳地方文史资料。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c14093a02caf4ce297723cae75b79e03','e49ea308-8606-4853-bd55-57619cf36653',1944,'衡阳沦陷后任伪警察头目','衡阳沦陷后任伪警察头目，配合日军搜捕抗日人员、维持伪治安，地方志中有简略记载。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-83411b311e3244ed8c61fe4e5109207f','c3eda289-b394-4b2f-9668-d1fbefe50698',1944,'衡阳沦陷期间','衡阳沦陷期间，以商会名义为日军筹款筹粮，协助伪政权控制地方经济，属经济领域附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb5080bb357740db884b270567d332cd','b045718f-4a58-4ec1-9acd-c7578358143e',1944,'在沦陷区推行奴化教育','在沦陷区推行奴化教育，改编教材，宣传“大东亚共荣”，属教育领域附逆人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-302057cd4ee34003be4e0d0605aa2ee0','f0e4a96e-3011-4d4f-955e-2c6cc0647215',1938,'湖南衡山人','湖南衡山人，北洋时期湖南省长，抗战期间居上海，曾与日伪方面有接触，但未正式出任伪职，历史评价复杂。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
