INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45ae9827ea6949f498dc4539761a1f48','96f263fe-4e51-4c88-a8dd-b3b68b71b9b9',1944,'在衡阳沦陷期间担任伪警察局长','在衡阳沦陷期间担任伪警察局长，协助日军搜捕抗日分子、维持城区治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66e00f40e4864c73884391e43a664509','dd429e4d-e00f-4bdc-ad3e-7495255ce0d0',1944,'石鼓地区沦陷后组织维持会','石鼓地区沦陷后组织维持会，为日军提供情报、物资，协助管理石鼓一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
