INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab2e338951ff482d9b39ea89904a47e2','d282befd-b253-4b9f-8fa5-edee751d821b',1944,'组织伪保安团配合日军扫荡衡阳周边抗日武装','组织伪保安团配合日军扫荡衡阳周边抗日武装，镇压民众反抗。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84ae9e389d5643d1b005d1ab41a4411a','895b505e-dbb4-4a89-a5d2-ad174e4150cb',1933,'湖南衡阳人','湖南衡阳人，北洋旧军阀，后投靠日本，在华北从事汉奸活动，虽主要活动于平津，但作为衡阳籍汉奸被历史记载。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6d1797a065e4cb9943719eadd2ceaed','895b505e-dbb4-4a89-a5d2-ad174e4150cb',1933,'湖南长沙人','湖南长沙人，北洋军阀余孽，1933年投靠日本，任伪华北政务委员会顾问，在平津地区从事汉奸活动，1935年被刺杀，与长沙有籍贯关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77cb9d7863b048bb8008009f5a18b90f','575dd383-1f59-46f7-bb55-b5e92458dddf',1944,'衡阳沦陷期间','衡阳沦陷期间，出面组织伪维持会，为日军筹粮、派夫、维持地方秩序，协助日军统治衡阳城区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e4b37f798ff48c7a0fef3aae94c952a','cdad816d-c851-4164-acbb-ef27e7f8c927',1944,'衡阳保卫战后期','衡阳保卫战后期，日军占领衡阳后，罗树甲参与组织伪自治会，协助日军管理城市、征调民夫。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ec5a3b739bf495396bfdcb4641d1f22','37c15408-4696-41e6-a7e9-25660e6bcf4b',1944,'祁阳沦陷后','祁阳沦陷后，刘伯谦出面组织伪维持会，为日军征粮、派款、拉夫，并协助日军镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13d824d1b831497ca40a0c1ab4a8f50b','88af5211-cae0-4d2f-b667-180edc28a019',1944,'祁东地区沦陷期间','祁东地区沦陷期间，陈光中担任伪保甲长，积极为日军催征粮草、搜集情报，并带领日军搜捕抗日人员。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21a7b72a6ca249ef9dfbc7ababdcc09f','361c2eee-39e0-4251-b2b8-781a3e1a6e5f',1944,'衡阳沦陷后','衡阳沦陷后，李树森投靠日军，出任伪警察局督察长，协助日军维持治安、抓捕抗日分子。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-988b9817ea684b5999ecd60a464085d1','0e2f2df3-ff8a-428f-b0ab-1467ca6b7e20',1944,'湖南人','湖南人，汪伪政权在湖南沦陷区设立伪行政机构时，王炽昌出任伪职，负责衡阳一带的伪行政事务，为日军征粮派款。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-edcd3ba626b6425b9339c663da74c0bc','f71a02b8-a9c4-473f-96b0-f51d719cbe04',1944,'衡阳沦陷期间','衡阳沦陷期间，黄子安以商会会长身份出面组织伪商团，为日军筹集物资、摊派款项，协助日军控制衡阳经济。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e425abc6b8b438b82eca7454721a0a2','9f3fa7da-d350-4c0c-b353-2e09dd7fed1a',1940,'湖南教育界附逆者','湖南教育界附逆者，在日伪控制下推行奴化教育，曾在衡阳地区学校中强制使用伪教材，宣传“大东亚共荣”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-50661595c5f64ac3991945816c533ad8','269b8f79-7cd1-4d36-aab9-0c5bdd99a7ef',1944,'衡阳沦陷后出面组织伪维持会','衡阳沦陷后出面组织伪维持会，协助日军征粮、拉夫、维持治安，为日军在衡阳地区的统治提供地方支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
