INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05ef146f92f54416aefcb649fd5d2d97','ded3765a-3e72-4960-9194-78ebbae1f66a',1944,'率地方武装投靠日军','率地方武装投靠日军，编为伪保安团，配合日军扫荡耒阳周边抗日武装，镇压民众反抗。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95e7c1063c0449148e8dace810fcb4ca','6d17175d-904a-4d1b-aa52-bec2656b0640',1940,'汪伪政权核心人物','汪伪政权核心人物，其伪政权名义上管辖湖南，对湖南沦陷区伪组织有统辖关系，间接影响衡阳、耒阳等地伪政权运作。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42546eb90e504057a7327d75ad746d16','6d17175d-904a-4d1b-aa52-bec2656b0640',1940,'汪伪核心人物','汪伪核心人物，曾兼伪湖南省政府主席名义，推行伪化统治，后与重庆方面有联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f5db14103dc4b9eb0fc01631320439a','6d17175d-904a-4d1b-aa52-bec2656b0640',1940,'汪伪政权核心人物','汪伪政权核心人物，其伪湖南省长名义与湖南沦陷区伪政权体系相关，推行附日政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
