INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f66218c560854595bf89c7e85f21a97a','e4476171-79a4-466e-af06-aef8b133eadc',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，后与重庆方面暗中联系，抗战胜利后被国民政府逮捕审判。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0bc6899fa03c4c56ac3e76fb43b06d5a','e4476171-79a4-466e-af06-aef8b133eadc',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与对湖南等沦陷区的伪化统治与经济掠夺，后与重庆方面暗中联络，抗战胜利后被国民政府逮捕审判。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a477dc19796481882c0382d68b59695','e4476171-79a4-466e-af06-aef8b133eadc',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，任伪行政院副院长、财政部长、警政部长等职，虽主要活动于南京、上海，但为湖南籍，且其附逆行为对湖南沦陷区伪政权建立有影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae69c9707aec4783bf22c6c6222070b6','4c050eff-b0c5-452c-80db-6db95d9a8716',1944,'湖南长沙人','湖南长沙人，抗战后期在湖南地区活动，曾与日伪方面有接触，后率部反正，其部活动范围涉及湘中、湘南一带。','危害等级C（丙级，基层头目）','hanjian');
