INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-851a6dd4dd3e4c269df4cedcdc6f9b92','090ed1d7-69d2-4ee9-8ca0-13f14c5f31eb',1940,'原国民党将领','原国民党将领，1943年投靠汪伪政权，任伪湖南省政府主席、伪保安司令等职，在湖南地区协助日军维持占领区秩序，进行伪化宣传与治安强化活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64cb97ae54ba42268bc023d051e094ad','090ed1d7-69d2-4ee9-8ca0-13f14c5f31eb',1940,'抗战后期受重庆方面指派潜入汪伪政权','抗战后期受重庆方面指派潜入汪伪政权，任伪湖南省政府主席等职，表面附逆，实际从事策反与情报工作，其活动范围覆盖湖南衡阳一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b2f9a22df26d4584bdf01248ee8eb4f4','090ed1d7-69d2-4ee9-8ca0-13f14c5f31eb',1940,'原国民党将领','原国民党将领，1940年投靠汪伪政权，任伪湖南省政府主席、伪保安司令等职，在湖南地区协助日军维持占领秩序，推行伪化统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-122c0ee5fd1a4418910046338eaa4f9b','28b1a7f3-98bf-406d-834d-68c15a37e217',1944,'衡山沦陷期间参与组织伪维持会','衡山沦陷期间参与组织伪维持会，协助日军在衡山地区征粮、拉夫，并诱迫地方士绅附逆。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-746333873074407c8106ad2d0169ad1c','d763447a-1a95-4b7f-a2d5-67b3b07a3345',1944,'在湘南地区组织伪军','在湘南地区组织伪军，配合日军对衡阳、衡山一带进行扫荡与治安作战，收编土匪武装为伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f78a973723c45a88fe31e805225dbdf','5c34a5fd-5ffd-4153-91a7-6afa3666a5ce',1944,'在衡阳沦陷区推行奴化教育','在衡阳沦陷区推行奴化教育，改编教材，强制学校教授日语与亲日内容，为伪政权培养顺民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9dc8d2bcd92440e681c5e6f203f3b4db','f35d6b54-e020-4d41-9f81-6d03c4d2faeb',1944,'在汪伪湖南省政府中主管警务','在汪伪湖南省政府中主管警务，在衡阳等地组建伪警察队伍，配合日军搜捕抗日人员与镇压民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74448848a23b45579de53b3930757435','124ab7bc-1490-4b79-af50-dc098eddb9ea',1944,'日军侵占衡阳后出面组织维持会','日军侵占衡阳后出面组织维持会，协助日军征粮、拉夫、维持地方秩序，为日军占领衡阳提供基层支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
