INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0078d114e6a24da7b81a3e284c46fbef','744073a1-d67c-4cbf-80e0-cbb84c9e6739',1944,'日军占领衡阳期间','日军占领衡阳期间，以商会名义为日军筹款筹粮，协助日军控制衡阳工商业。','危害等级C（丙级，基层头目）','hanjian');
