INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb7264ab9ea744c980166cb321e94f23','8ce52f08-65a3-4f6d-a6f5-6bcd5c15a89c',1940,'湖南东安人','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实为军统潜伏，负责联络策反伪军将领，其活动范围涉及湖南籍人员网络，但与衡阳松木经开区无直接地方任职关联。','危害等级C（丙级，基层头目）','hanjian');
