INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67591aa7cd784221bef0fb4d6da6d74a','68a16bc7-b133-46f7-b800-9995cde347a9',1944,'据衡阳地方文史资料零星记载','据衡阳地方文史资料零星记载，1944年衡阳沦陷期间，当地有维持会组织协助日军维持秩序、征派民夫，但具体负责人姓名多已散佚，彭佐熙之名见于部分口述史料，可靠性有限。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
