INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e0bf43ee2da437187a76040c813d835','c7ebcf47-fe51-4345-bea3-e92ae552e5b9',1944,'湖南人','湖南人，抗战后期在日军扶植下组织伪湖南和平救国军，配合日军在湘中、湘南地区进行伪化活动，后随日军投降而瓦解。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffa4b34efc604a30b22a3623387e2f7e','e8c57a19-9072-410a-8142-10a0782a1e2d',1943,'湖南人','湖南人，抗战期间在湘鄂边界地区组织伪军，配合日军对抗日根据地和国军进行骚扰，后所部被日军收编为伪保安部队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05f4cb447d804494be7eeb9287710f3a','ec6d0325-1f45-41d0-9bd5-b2412781c78b',1944,'湖南凤凰人','湖南凤凰人，湘西地方实力派，抗战后期在日军诱降下曾与日方接触，一度接受伪湘西自治军总司令名义，后因形势变化未完全公开附逆。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-602cc9f33d7f44caa86750dd58ea9d6a','9d70e890-5dd9-4cc7-9481-f4b8f6551f2c',1933,'湖南人','湖南人，北洋旧军阀，1933年投靠日本，在华北参与伪政权活动，曾任伪湖南省长名义职务，1935年被刺杀。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bad9cf5b630d4869b4a3417f09aaf36d','9aba78a0-28dd-44ab-8ed0-5cd9f1a02c07',1944,'汪伪政权在湖南沦陷区设立伪省政府','汪伪政权在湖南沦陷区设立伪省政府，刘建绪被任命为伪湖南省政府主席，配合日军推行伪化统治，其辖区涵盖邵阳部分地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e026a95f2f64af58fba27f984f0e0d1','93b229d9-d37b-4c7c-b8a7-ae3187e6daa9',1943,'在汪伪政权中任职','在汪伪政权中任职，参与湖南沦陷区的伪军组织与治安维持，与邵阳地区伪政权有联系。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1a58fd99b2541ab99d3227c9a58c431','0ee158cb-8857-402a-829d-a8f9d1faf28e',1944,'日军占领邵阳期间','日军占领邵阳期间，出任伪警察局局长，协助日军搜捕抗日人员、维持治安，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e08782c68c184219b6ed83922e81caa8','d5e2e923-f028-4809-bca4-4b6d8bad41fb',1944,'组织伪保安团配合日军扫荡邵阳周边抗日武装','组织伪保安团配合日军扫荡邵阳周边抗日武装，强征民夫、粮食，为日军提供情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba152df43b4b44d9ac4b187b4730d22c','53c8abde-3d05-4880-ad66-1702ba584401',1944,'在汪伪湖南省政府中负责教育','在汪伪湖南省政府中负责教育，推行奴化教育，在邵阳等地强制使用伪教材，宣传“大东亚共荣”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc4d445250934d3b94be1129a83af033','7cdfa35f-868c-42da-9932-c59c0e66d88b',1944,'日军占领邵阳后','日军占领邵阳后，以商会会长身份为日军筹集物资、摊派款项，协助日军控制当地经济。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26687fa1d9b04ec58a1212cc8327a2a6','4d453360-2d24-46c0-91e3-5bcffef1a683',1944,'在汪伪政权支持下组织伪自治会','在汪伪政权支持下组织伪自治会，配合日军在湖南包括邵阳地区的伪化宣传与统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3f4f3efd6dd45759d08fb4c0d9e745b','2d9d5df2-7086-4723-b18d-01b1ef63fc42',1943,'作为汪伪核心人物','作为汪伪核心人物，参与策划湖南沦陷区伪政权建设，其政策直接影响邵阳地区的伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a1f21e98782496985a33fe10b0e9003','8ce0cc52-7202-45fd-9d07-a35dc5b0418c',1944,'抗战后期在湖南部分沦陷区参与日伪政权活动','抗战后期在湖南部分沦陷区参与日伪政权活动，协助日军推行伪化统治，影响范围覆盖湘中、湘南地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a057fe4264034b2fbbc72ac67c2901c0','1aaa5531-6eb7-4f8b-8125-1217a09b0f6f',1944,'在湖南沦陷区与日伪合作','在湖南沦陷区与日伪合作，参与伪政权军事警务活动，其活动范围涉及邵阳周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7c54eecc2fb4e39bb7163c4817c7f5c','0b1f45d4-3c4d-48c1-9997-daae35ceeb6b',1944,'在湖南日伪政权中任职','在湖南日伪政权中任职，推行伪化政策，协助日军维持占领区秩序，对包括邵阳在内的湖南地区产生间接影响。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61fff2d364ca4a90ae1a854a4bee740f','5da877bc-b8d0-438f-8340-bf19cc28f2e1',1943,'作为汪伪政权核心人物','作为汪伪政权核心人物，参与策划湖南沦陷区伪政权建设，其政策影响波及邵阳、隆回一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64d562b47f654dbf807b75b937e4b941','2fb97932-2cba-492e-9d39-86fe539c09fa',1944,'日军占领邵阳后','日军占领邵阳后，受命筹组伪县政府，拉拢地方士绅附逆，为日军提供情报和物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66f0d96796004216acbd690e2ec0476f','2a5d676d-2b06-4efe-b6b1-b9384e624067',1944,'在隆回地区组织维持会','在隆回地区组织维持会，协助日军征粮、抓夫，镇压抗日群众，维护日伪统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08b16cd4cd1c4c6d8f1a2a07a5c25d9a','5cf6afbc-3f37-4b9e-97e9-ada567755a98',1944,'在邵阳沦陷期间担任伪警察头目','在邵阳沦陷期间担任伪警察头目，配合日军搜捕抗日人员，维持伪治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d72c08cc7d984e639a14e190ce1e61cc','2bd5c4a7-05b4-4ecf-aa81-74da2fd54a51',1944,'在湖南沦陷区推行奴化教育','在湖南沦陷区推行奴化教育，编写亲日教材，影响邵阳等地学校。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c26f5b481f1d47d99e8439898045c491','3b068ce2-0161-40f7-9266-ff44e57e55e6',1944,'虽未直接出任伪职','虽未直接出任伪职，但与日伪保持联系，为日伪在湖南的统治提供咨询，间接影响邵阳地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c40d612799ab40178904466e7a1156bb','7071284b-97aa-453e-b5d9-6f4aeb5318d1',1944,'日军侵占郴县后出面组织维持会','日军侵占郴县后出面组织维持会，为日军征派粮秣、拉夫，协助维持占领区秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a432ed4f7df54afd8f0d5ad8094a4eaa','6dbd7ac0-a1ac-4029-97e5-81ef614eab92',1944,'在日军控制下组建伪警察队伍','在日军控制下组建伪警察队伍，配合日军搜捕抗日人员，镇压地方反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f5a4668db9e4004be03629650cada03','b7e236fe-f745-446c-bf5b-909aac073021',1944,'收编地方游杂武装投靠日军','收编地方游杂武装投靠日军，率伪军配合日军扫荡郴县周边乡村。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34aa3b3fd62142a59873e946faac265e','f0f1a249-7bd0-4d0c-b474-885adcfd4bf9',1944,'在栖凤渡一带为日军筹粮、带路','在栖凤渡一带为日军筹粮、带路，协助日军控制粤汉铁路沿线据点。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e882940758bc4a3595e9039141b3e322','e374ef5b-37a8-4906-b01b-773f210884aa',1944,'日军犯资兴时组织维持会','日军犯资兴时组织维持会，替日军征工征粮，并诱迫地方士绅附逆。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-35b53c6968bf47038af4afb08cf0e3e7','9f132be7-850c-4819-8368-627dfbc99725',1944,'投靠日军后纠集武装','投靠日军后纠集武装，在永兴、郴县交界地区袭扰抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7bc08172a9ec4b58899b5f8b1775a38b','b70fc0f7-4fc8-4d40-89fe-47e4ec5b2913',1944,'协助日军在宜章设立据点','协助日军在宜章设立据点，办理伪政权事务，为日军搜集情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42800ed4b74345c9a6f338828edf3206','810b7e32-0396-4a6e-bc56-f19c2c731d09',NULL,'无可靠史料证明其附逆','无可靠史料证明其附逆，故不列入汉奸名录。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c85dde228c0c449b8681443103a09972','098d0ff0-6a2c-46ab-a4b3-1148652d8734',1943,'受重庆方面派遣打入汪伪','受重庆方面派遣打入汪伪，名义上任伪湖南省政府主席，实际从事策反与情报工作，不应以汉奸论处。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
