INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c67df58d01e47c7a115b023ccc5cfc6','b222483d-9dab-4106-b6e0-0af667cf16dd',1933,'旧军阀投靠日本','旧军阀投靠日本，在华北活动，与湖南无直接关联，但属湖南籍汉奸。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2023dc735a774c4bb5777921253aa3b4','c1bd1f38-5d06-4793-b656-c114506530f8',1940,'湖南籍汪伪高官','湖南籍汪伪高官，参与伪政权统治，在安徽等地推行日军政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e74bd73ebf6f45aab4fe8273c15971a9','aa88ea85-07d6-4f07-8f48-adfecb8b6a75',1940,'汪伪核心人物','汪伪核心人物，推行伪化统治，对包括湖南在内的沦陷区有名义管辖权。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60bce61001c54545bbc607a39a604912','e58f85d2-8b19-4cfa-8b3c-2fbacc3bfa1f',1940,'汪伪高官','汪伪高官，参与伪政权各项卖国活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-53f5f4b798c84543bb1f9eec5e6906f6','6fda73e1-a235-4f4a-ae72-2ecd80e08d22',1940,'汪伪重要成员','汪伪重要成员，参与签订卖国条约，推行经济统制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0cedbfa7b7a4d1183f1a47bbc8751b1','89a902f7-4118-451b-85bb-cdc50dda9ef3',1944,'1944年日军侵占临武期间','1944年日军侵占临武期间，出面组织伪维持会，为日军征派粮秣、拉夫，协助维持占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94fd2240aebe47a3a4c8f1a32e358629','c8052b54-b843-4e0f-ab35-2d0536a26894',1944,'临武沦陷后投靠日军','临武沦陷后投靠日军，充任伪保安队头目，率部配合日军下乡扫荡、搜捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb6de3d7999d4385883961a17a358b48','da6b8a3a-40d5-4321-98c1-e4f7a8993b3f',1944,'郴县沦陷期间参与伪维持会','郴县沦陷期间参与伪维持会，协助日军推行保甲、征发民夫，为占领军服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2911b9ff7cf6454eb76de795534f8daa','fc355ffc-8064-4f51-887b-79693e805dac',1944,'日军占领郴县后出任伪警察局长','日军占领郴县后出任伪警察局长，负责侦缉抗日分子、维持城区治安，配合日军统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ca640fedb364eb08d24072d891c20dc','6600c665-71b5-435e-a102-78a3de240aac',1938,'湖南沅陵人','湖南沅陵人，汪伪政权核心人物之一，虽主要活动于南京、上海，但作为湖南籍汉奸头目，对湖南沦陷区伪政权有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
