INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-178f815c30e5474ab1de04820732ccce','7fb5d340-1c6a-49a2-99e9-f87e5e1b0965',1944,'长沙沦陷期间','长沙沦陷期间，以商会名义为日军筹款筹粮，协助日伪维持长沙城内经济秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8604ce5e55b848489c74b81d86d7e1c0','8f1616af-9b57-42e8-8801-513c7436c43a',1944,'在日军占领长沙后出任伪职','在日军占领长沙后出任伪职，主持伪市政，推行日伪政令，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25956afe70374ab2acf18afa46695126','e7fe3f08-0f08-48b9-9b2a-a68f1c4d9f5d',1944,'长沙沦陷后投靠日军','长沙沦陷后投靠日军，担任伪警察局长，搜捕抗日人士，配合日军维持占领区治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c7f7aeeb65740db91d0be07d508a609','9331f41b-3ee1-49d9-a58a-713d98313f84',1944,'在长沙等地为日伪进行奴化宣传','在长沙等地为日伪进行奴化宣传，鼓吹“大东亚共荣”，控制报刊与广播。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69fc23719f0d43f6b02be5cd2838c737','4cea62ac-6bf3-4abe-93ef-84b901fecf46',1944,'在长沙占领区推行奴化教育','在长沙占领区推行奴化教育，修改教材，强迫学校教授日语与亲日内容。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a56f721e0ad4717b48d9f4defa9c258','e41de46e-3f53-4b17-a2c3-ca3e15e098ec',1944,'湘阴沦陷后组织伪维持会','湘阴沦陷后组织伪维持会，为日军征集物资、情报，协助日军控制湘阴及长沙北部地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-526ad7ca305a43659b56095aed6183df','6d289fa4-8234-44a3-bf36-3a7d411ba616',1944,'宁乡沦陷期间投敌','宁乡沦陷期间投敌，组织伪维持会，配合日军扫荡长沙西部乡村。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-607ce2d6c13b4a49952423b920213e8d','71573c85-1c63-4fd7-9b07-6ba09989b69a',1944,'长沙沦陷后附逆','长沙沦陷后附逆，参与伪政权筹备与运作，为日军提供地方情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd9e10d2fce9469faf62dd5f7d1fcebe','b6ead2ad-fc3f-4a13-b52e-59595d5a6071',1944,'率部投敌','率部投敌，改编为伪保安团，配合日军在长沙近郊进行清乡与搜捕。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06b8983c602c4d3886c1ceb677fd4e12','c8d0a756-4d05-4aab-8778-8027db959145',1943,'在湘北、鄂南、赣西一带活动','在湘北、鄂南、赣西一带活动，收编散兵游勇组成伪军，配合日军对湖南抗日根据地进攻。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea92f8517907417b88073f67636758ee','fb904269-6fcb-4cd2-b87a-44191c48016d',1944,'长沙沦陷后组织伪自卫团','长沙沦陷后组织伪自卫团，协助日军维持天心阁一带及城南地区治安，搜捕抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be26fde930b24ddcaec781147cdc88ab','1d6bca15-6af8-46c0-8f40-094b25084c62',1939,'湖北黄陂人','湖北黄陂人，汪伪高级军事汉奸，活动于武汉及华中地区，其伪军体系曾覆盖湖南北部，与长沙、宁乡地区有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f73baa33bb04902a8a2c027fa2a3fa1','afbc0eb2-cba8-44ab-92af-e7e61d7bfcea',1943,'陕西渭南人','陕西渭南人，1943年在湖北被俘后降日，任伪军师长，活动于湖北、湖南北部，其部队曾进入湖南境内，与长沙、宁乡地区有军事接触。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c35f9951ecb448c6aa9216f279b1fc19','0becb25d-f566-49f2-967c-5bdef71eec5b',1944,'广东人','广东人，汪伪政权任命其为伪湖南省主席，因日军未能完全控制湖南而未实际到任，但伪政权体系对长沙、宁乡地区有名义上的管辖。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ba49e7d16824b6d855f7c810df93c5d','a165ea53-22bf-4922-be4f-817a0ffab7d1',1944,'在日军占领长沙期间','在日军占领长沙期间，出任伪长沙市长，协助日军维持治安、征粮征税，直接参与长沙地区的伪政权活动，与宁乡地区有行政关联。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d107628425240f4bcb67a6e87c5128a','94ab8b04-b4db-4802-94f5-df5ae268fd1e',1944,'宁乡本地人','宁乡本地人，日军侵占宁乡期间组织维持会，为日军筹粮、派夫、搜集情报，协助日军镇压抗日活动，是宁乡地区直接附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc7839cb15034e27aa2352f474ed6443','a3c329e2-d62e-48ba-b18a-491e659b5362',1944,'长沙本地士绅','长沙本地士绅，日军占领长沙后出面组织维持会，协助日军管理地方、征发物资，与宁乡地区伪政权有联络。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-693f00fa956e4bd4bc6f6eb7a1cf78aa','0363b664-db0e-4f78-abaa-a6e4bd6b66aa',1944,'在汪伪湖南省政府中负责警务','在汪伪湖南省政府中负责警务，参与组建伪警察队伍，镇压长沙、宁乡一带抗日分子，维护日占区秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d912dd7a6f1e4a0695bc7aa69bbb1118','1d6bb076-fae4-47ca-ae17-588121c04498',1944,'长沙本地人','长沙本地人，投靠日军后组建伪保安团，配合日军扫荡长沙、宁乡交界地区抗日武装，抓捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2c10b56bb714a1485b0b5c90f45480c','23274d59-f7c2-40a4-8fd4-aafc37ccaba5',1944,'宁乡人','宁乡人，率队投日，任伪保安队长，在宁乡及周边地区为日军带路、清乡，迫害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c83ab563830c4220ac3d188df4261571','6b5e16d8-77bf-4536-8534-0543910ee847',1929,'湖南醴陵人','湖南醴陵人，主政湖南期间曾与日方有秘密接触，但未公开投敌，部分史料将其列为亲日嫌疑，与长沙、宁乡地区有行政关联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c973ea3c9e5428b9b4b5d12f0eceaef','867a1b2f-407f-406f-b21a-71942ec6a0bf',1944,'在汪伪湖南省政府中负责教育','在汪伪湖南省政府中负责教育，推行奴化教育，在长沙、宁乡等地学校强制使用伪教材，毒化青年。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1037a66a4e7b40949d7c92535a594118','2cfa03f7-f67f-433f-90d8-33366baeb230',1944,'长沙商人','长沙商人，日军占领后出面组织伪商会，为日军筹款筹物，协助经济掠夺，与宁乡商界有联系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-afef0ae559ca45a69ad4ec3110742d67','fd65c4fb-ffab-45ce-b727-982a47f676fe',1937,'湖南醴陵人','湖南醴陵人，抗战初期在湖南任职，后与日方有秘密接触传闻，未公开投敌，但部分史料将其列入附逆嫌疑。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8a5e744b909485e937c947d9f6fa90a','0bb09348-c580-4e30-bf43-ce63e9b3c3df',1940,'湖南浏阳人','湖南浏阳人，汪伪军事委员会成员，参与伪军建设，其活动范围涉及华中，与湖南长沙、宁乡地区有间接联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2d72b95eb984ea586aa17de95be0dde','4d13d432-c3ce-4f5d-882f-fe95033e646c',1944,'宁乡人','宁乡人，投日后任伪警察局长，带领伪警察配合日军搜捕抗日人员，镇压宁乡地区抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9ba4437a0124cac8d8b217e4f4ac5f4','12f41a82-c3a9-4dba-880d-f3c64c346aa9',1944,'在伪长沙县政府中负责教育','在伪长沙县政府中负责教育，推行亲日奴化教育，在长沙、宁乡等地学校进行亲日宣传。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d744aa3d67094a33b1b69f376d3e3eed','02bfe89a-ea61-4541-816b-28918e2ad925',1938,'虽为广东籍','虽为广东籍，但作为汪伪政权主要头目，其伪政权体系覆盖湖南沦陷区，对长沙等地伪维持会、伪军警有统辖关系。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d36e2ecda52040fc829b63149bef4637','cb97e3a9-45a3-4ba2-8048-40a9d44bac41',1933,'湖南长沙人','湖南长沙人，北洋旧军阀，九一八后投靠日本，在华北组织伪军，1935年被刺杀于北平，是湖南籍早期附逆人物。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aeabac7007e940eb97c5ad09e46c7602','387fae68-a1ce-440c-b3ad-3727acf40f0e',1944,'长沙沦陷后出面组织伪维持会','长沙沦陷后出面组织伪维持会，协助日军维持长沙城区秩序、征派物资与劳工，为日军占领长沙提供地方伪政权支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-109fef78fc1a494b9f4175db0b9569d2','beb200c2-3424-41e7-b991-e49a56ac5cd0',1944,'长沙县沦陷期间任伪维持会会长','长沙县沦陷期间任伪维持会会长，协助日军在长沙县及岳麓山周边地区征粮、派夫、建立保甲伪组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f62710f8baac4f7d9ab5a12f6853de5d','beb200c2-3424-41e7-b991-e49a56ac5cd0',1944,'长沙县人','长沙县人，日军占领长沙后出任伪维持会会长，负责为日军筹粮、派夫、维持地方伪秩序，活动范围包括开福区一带。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2197dcd2b3d84061b63e5505f3041035','beb200c2-3424-41e7-b991-e49a56ac5cd0',1944,'长沙沦陷后出面组织伪长沙县维持会','长沙沦陷后出面组织伪长沙县维持会，替日军征粮、派夫、维持治安，是长沙地区有记载的伪政权头目之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd52b8519f8249b7beb94f98a01225cc','7346d948-fb1f-417c-92fa-b631f15c6dbe',1944,'湖南籍军人','湖南籍军人，抗战后期在湘中、湘南一带与日伪合作，参与伪军组织与地方治安维持，活动范围接近长沙地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8a6ece9e9ce47b595f93d2d56834490','f83207d2-67b3-42cb-a40c-778ab61be649',1944,'长沙沦陷后任伪警察局长','长沙沦陷后任伪警察局长，协助日军维持城区治安、搜捕抗日人员、管理户籍与物资配给。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6210dcde5774c7ebd473babf2cac4dc','105aadb0-2164-46aa-bb65-f56141032719',1944,'岳麓山地区沦陷后组织伪维持会','岳麓山地区沦陷后组织伪维持会，为日军提供向导、情报与物资，协助控制岳麓山周边乡村。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-846e08c4c7c34ff796bc3a0b28c33e7b','23f20f81-7262-4013-9eb8-cbea25b3c517',1944,'在日军占领长沙期间参与伪湖南省政府筹备','在日军占领长沙期间参与伪湖南省政府筹备，任伪长沙市长，推行伪政令、征粮派款。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6340e576e5e54ed996eae9e53a8e8350','908ede56-943b-4b98-a376-415c1f0b53cb',1944,'湖南籍旧军人','湖南籍旧军人，抗战后期投靠日军，在湘中地区组织伪军，配合日军对长沙周边抗日武装进行扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb544ec19cda46c2930848c51ec7b03f','5c688fb4-fb69-4e77-b473-c0292f283fb2',1931,'湖南长沙人','湖南长沙人，1931年在江西被红军俘虏处决，此前有资料指其与日方有秘密接触，但主要历史定位为国民党将领，非典型汉奸。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-655cdbd85fab4ec2a205fd3f644190ce','bb65f5dc-225b-40b8-b038-71840638a09e',1943,'陕西渭南人','陕西渭南人，但在湖南长沙地区有作战与活动经历，1943年被俘后投日，任伪军师长，在湘北鄂南一带活动，与长沙邻近。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3d0a650ae524c4194634e4a13fec3e6','3a41827a-ca5b-419c-a180-6d82b13cd708',1938,'广东乳源人','广东乳源人，汪伪政权二号人物，其伪政权统治覆盖湖南沦陷区，对长沙等地有伪化政策影响。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4edb0ce3d5f64f329be0ac1ec616f2bd','4286d932-f1d4-4ded-8051-80c5d193de0a',1939,'浙江吴兴人','浙江吴兴人，汪伪核心人物，参与伪政权对湖南等地的政策制定与宣传，与长沙有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcbc9d2d99364a89a448c012e1c8dda7','ac83e994-c29f-4f68-bd11-00fbe1faad5e',1938,'浙江永嘉人','浙江永嘉人，汪伪政权重要成员，参与对湖南沦陷区的经济掠夺与伪化统治，与长沙有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3949bf8378ac4c3688583d9fa7822417','b3e37017-3291-421e-911d-d9e14b033b4c',1939,'湖南常德人','湖南常德人，汪伪特工头目之一，其特工活动涉及湖南长沙等地的情报与镇压，与长沙有直接籍贯关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-908c8e524ed04ad0a950a5b7083d0e49','38561e49-462c-40e2-bcbc-05cddd418d37',1939,'湖南人','湖南人，汪伪特工骨干，在南京及华中地区从事特务活动，其活动范围覆盖湖南部分沦陷区，与长沙有间接关联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b14f3e8b9954146a46af3e8011d70aa','1f6e88b5-a348-4410-bb7b-93320fbeafed',1944,'长沙本地人','长沙本地人，1944年长沙沦陷后组织伪维持会，协助日军维持治安、征粮征夫，直接服务于开福区及长沙城区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f0926b9112b45b98d057571587f0a32','b4d00a45-8b88-4137-9e9b-6f30b9d89360',1944,'长沙人','长沙人，长沙沦陷后投靠日军，出任伪警察局长，协助日军镇压抗日分子、管理户籍与治安，直接涉及开福区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d4ee679029648f88152804935dbc651','0018981d-3c0a-4212-9c66-8972c3391c23',1944,'湖南人','湖南人，日军占领湖南期间出任伪保安司令，统率伪军配合日军扫荡，活动范围覆盖长沙及开福地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1fa156c3984a44208c405598ae1b1014','374bea0c-0292-43ad-b0c9-d3bdf2bc782d',1944,'湖南人','湖南人，在长沙沦陷区推行奴化教育，篡改教材、宣传“大东亚共荣”，直接涉及开福区学校。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73a11ef017084e6895e468ace4c41d49','8353f1e4-149c-4011-91c1-7b1626817572',1944,'长沙商人','长沙商人，沦陷后出面组织伪商会，为日军筹款筹物，协助经济掠夺，活动于开福区商业地带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ecabbbe465f41deaf6fcbebd9e8faf3','8a7ca6aa-4220-46df-bf64-766d0c9a95fd',1944,'长沙人','长沙人，日军占领期间出任伪县知事，负责征粮、征夫、维持伪政权，直接管辖开福区部分区域。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09fdf63ad3a84e78921735feede25861','37392c04-cab8-497d-81e1-2b89dd6b2c4a',1944,'湖南人','湖南人，在长沙沦陷区主持伪宣传，散布亲日言论、诋毁抗日力量，活动涉及开福区文化教育界。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcbca0a08cee4c81b34f2d02344f77d2','c06dba51-435c-431e-b040-e935f464e8f4',1944,'长沙人','长沙人，协助伪维持会会长彭年，负责开福区一带的伪化事务，包括派捐、拉夫、情报收集。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8fce64c50ed44ed7a51d10e5b6fe6ca1','f3fffc41-c45c-416c-a49c-a49f165df349',1931,'湖南醴陵人','湖南醴陵人，主政湖南期间对日态度暧昧，有资料指其与日方有秘密接触，但未公开投敌，与长沙开福有行政关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f776768467a14d8da3915946501e7f31','f2518fd6-a73c-4b61-9537-ab70fb9cbae8',1939,'湖北黄陂人','湖北黄陂人，汪伪政权在华中地区的重要军事头目，其伪军活动范围涉及湘北、鄂南，与湖南长沙、岳阳一带的伪化统治和清乡有联系，抗战胜利后被处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4a2b30f804b40ccb7cd5ba6fc4a6368','18423444-a22f-4f6f-a704-d74380016884',1933,'湖南长沙人','湖南长沙人，旧湘系军阀，九一八事变后与日本方面勾结，参与伪华北自治活动，1935年在北平被刺杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0e1620fb313452199d224bc9e4dcf68','18fd6430-a1a0-488c-8234-cfb01eeee4a9',1944,'长沙沦陷期间参与伪维持会活动','长沙沦陷期间参与伪维持会活动，协助日军维持地方秩序、征派物资，为日军在长沙的统治提供经济与后勤支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68299cee96a84e9fbed31f7d95030bde','9f6b2f5d-44dd-4367-9efa-72974fae6f96',1944,'望城沦陷期间参与伪维持会','望城沦陷期间参与伪维持会，协助日军在望城一带征派粮食、民夫，维持伪化统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19a79111facd4c728d7dd51b3caf3755','cffe863d-3e5f-4ce6-b88a-0e246a8300b0',1943,'汪伪政权在湖南推行清乡运动时的伪职官员','汪伪政权在湖南推行清乡运动时的伪职官员，参与对长沙周边抗日根据地的封锁与清剿，协助日军镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3849a44bca07481c837a314f8a75f303','410394e8-64ae-498a-a39c-19d5708d7a5a',1944,'汪伪政权曾筹划在湖南沦陷区建立伪省政府','汪伪政权曾筹划在湖南沦陷区建立伪省政府，部分人员随日军进入长沙、湘潭一带活动，协助伪化地方行政，具体姓名多散佚。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01bd87e7c2c74eae80dc7de070e9d94e','13bc4733-b31d-4a96-91e3-51c6a15b3045',1944,'长沙沦陷后组织伪维持会','长沙沦陷后组织伪维持会，协助日军维持占领区秩序，征发民夫物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab84774d936f4e37b8fa07628094c9d1','c9ad2948-d318-417d-9d35-795548f8b402',1944,'日军占领长沙后出任伪长沙县县长','日军占领长沙后出任伪长沙县县长，推行伪化统治，为日军征粮派款。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de037f368fd24796a22d38017da2366b','0411a596-28dd-4059-8a98-7bff48b65154',1944,'浏阳沦陷期间出面组织维持会','浏阳沦陷期间出面组织维持会，替日军维持地方秩序、征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0cf734a9909e46438379c2d380aaf44c','04650476-7870-423c-889a-ab8b9d7cb346',1944,'投靠日军','投靠日军，率部配合日军扫荡浏阳周边抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a65bbb058fbc4a95bcc9a210cf50e1fd','d231c353-f96e-4ad9-944a-dc9a5fc4fc84',1939,'湖北黄陂人','湖北黄陂人，汪伪军事要员，其伪军系统曾扩展至湖南北部，配合日军在湘北作战。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5c3076639064960be9227a11a8ede08','e18ac479-e3b3-44ef-b0ca-e97b3a49c68b',1944,'湘阴沦陷后组织维持会','湘阴沦陷后组织维持会，为日军征集粮食、劳工。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d19dd41395404df0b84eaa829ac42bd9','381f39a9-a1a7-47a3-958f-8c6cb2d3de5b',1944,'岳阳沦陷后出任伪县长','岳阳沦陷后出任伪县长，协助日军控制粤汉铁路沿线。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe0a8b99a9e044009adf105dd34d6ff1','4b1c35a2-e788-47c3-97a2-db9ac0c53b10',1931,'其主政湖南期间镇压抗日运动','其主政湖南期间镇压抗日运动，部分旧部在抗战后期投靠汪伪，如何键系部分军官加入伪军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05070d7d2051448bbc14a2493e329559','7aeeca78-e0e9-4764-9b8c-ee2b7c290497',1944,'参与日军策划的伪湖南省政府筹备','参与日军策划的伪湖南省政府筹备，协助推行伪化行政。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-925972fcb379472082241bbe5525af90','9e1f8ad1-63f9-4f94-8db9-21371b58a581',1940,'湖南浏阳人','湖南浏阳人，唐生智之弟，投靠汪伪，任伪参军长，参与伪军事务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9812e82c0a44c0192e0620f336cbd57','c7c35cb6-14c4-49de-ab81-0a7406379de0',1938,'抗战初期在长沙地区组织维持会','抗战初期在长沙地区组织维持会，协助日军维持地方秩序，后投靠汪伪政权，任伪军事委员会委员等职，参与伪军策反与情报活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6f56f92d3b8455aa8dc0f7a454f0ff1','09dc1e76-9366-4436-a9a5-f09b35bcba98',1938,'在长沙沦陷期间协助日军建立基层维持会','在长沙沦陷期间协助日军建立基层维持会，负责征粮、派夫、维持治安，配合日军清乡行动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0b51bb7594042d584463117d8e8ef37','a5ff0897-ab65-4064-8eea-d77f564644ab',1944,'长沙沦陷后投靠日伪','长沙沦陷后投靠日伪，参与伪湖南省政府筹备，负责长沙市区伪政权建设与市政管理，协助日军推行保甲制度。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3532af6318d42cfaf8cd17fccd6d533','77646dda-a8d2-49db-9570-91ac7d26971a',1944,'任伪警察局长期间','任伪警察局长期间，配合日军搜捕抗日分子，镇压民众反抗，强征劳工，维护日伪统治秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e09162fab3049fe926d553342e95575','b11fcc79-5afd-4bee-bdf1-6f2e40e56892',1944,'长沙沦陷后出任伪市长','长沙沦陷后出任伪市长，推行日军指令，征收苛捐杂税，协助日军掠夺物资，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3993a42d29cc4c8ab5d998bc0212c615','98de47f7-3893-4cf2-bc7d-578ab12f501a',1940,'作为汪伪核心人物','作为汪伪核心人物，参与策划湖南伪政权建立，指派亲信控制长沙等地伪组织，为日军筹款筹粮。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2931dfe87c9c43d5a9c0049ce1a31800','ab14aec9-a72c-4727-b675-3a717db46dd9',1940,'在汪伪政权中负责湖南等省伪政府人事安排','在汪伪政权中负责湖南等省伪政府人事安排，支持长沙地区伪政权运作，配合日军经济统制。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f7fc94afdc34cf5b027ee181b553f9c','45dc34b2-f763-426e-80b2-2d7fcafb3cf1',1940,'率伪军配合日军进攻湖南','率伪军配合日军进攻湖南，参与长沙会战后的伪化统治，在长沙周边地区清乡、抢粮。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e25886338a014419896d43f59e7e6ad1','ba774486-2922-496b-a398-4bd4e72cde1a',1944,'组织伪保安大队','组织伪保安大队，配合日军扫荡长沙周边抗日武装，强征民夫修筑工事，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81290ff07afe4d6bb29f26ca65ec29fc','5449441b-d9dd-4dc2-8104-0f67dc1cb751',1944,'在日伪统治下推行奴化教育','在日伪统治下推行奴化教育，修改教材，强制学校教授日语和亲日内容，组织学生参加日伪集会。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33a96ffbc1b2479cb9effc86c12431da','d6c7aa1c-1d90-4ab1-bb5e-ceedf507c6ec',1944,'负责日伪在湖南的舆论宣传','负责日伪在湖南的舆论宣传，创办伪报，散布“大东亚共荣”言论，为日军侵略辩护。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7aa07b3a9cd4168a5732fc36cc0cf5d','75348649-821d-44b6-8322-2034eeb22eea',1944,'原国民党湖南省主席','原国民党湖南省主席，抗战后期与日伪暗中联系，提供情报，协助日军维持长沙地区秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af1e7957146e4a52890b644a6595e598','d397e063-1914-4a3b-a19c-b2847ee460c9',1944,'湖南长沙人','湖南长沙人，1944年长沙沦陷后出面组织伪长沙维持会，任会长，协助日军维持占领秩序，搜刮物资，是长沙本地有明确记载的汉奸头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb8379e5a8eb4d82989ef2f7852995c9','3ef5027d-09b2-4ee8-aaed-81394ee2e3be',1944,'长沙本地商人','长沙本地商人，1944年日军占领长沙后，与彭允彝等组织伪长沙维持会，任副会长，并控制伪商会，为日军筹款筹粮，属于经济领域附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
