INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c89d87f2c74d417b8ede0b6358eaffca','38eb8154-c305-48c7-a06f-0962520c7e02',1944,'湖南长沙人','湖南长沙人，1944年长沙沦陷后出任伪长沙县县长，兼伪维持会委员，负责征粮征夫，协助日军统治长沙县境，包括雨花地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
