INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4996a7398aa455e8ea4771c3bfbb1b0','1bd9c1d2-2f14-4db4-971d-e4f74fc2268a',1938,'广东人','广东人，抗战期间投靠日军，组织伪军活动于闽粤边区，包括福建南部及三明周边地区，配合日军扫荡抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
