INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37533aae59f74a35ac5fa83fcd8dd1e1','fc4fffd1-4efe-4b3b-8432-6426290a2e5b',1938,'福建籍汉奸','福建籍汉奸，协助张逸舟组织伪军，在福州、连江、长乐沿海地区配合日军作战，镇压抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e79f724cb6f9427b8f7505d210d31641','fc4fffd1-4efe-4b3b-8432-6426290a2e5b',1938,'与张逸舟合作','与张逸舟合作，在莆田沿海及岛屿活动，收编海盗与散兵组成伪军，为日军提供沿海情报与后勤支持。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5dd47802c5d445eea221fbbb4219c191','e1620456-d454-451c-8a33-6140e98ee191',1944,'据地方史料记载','据地方史料记载，南平地区曾有汉奸试图组织维持会迎接日军，翁尚功为其中主要策划者之一，后因日军未深入南平而未能得逞。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1bcc409dec344c6abe6de7db77c64e2','b071ea36-dbae-49f8-bcce-3caf90e1c4a1',1944,'光泽县地方档案提','光泽县地方档案提及，抗战后期有少数地方士绅与日伪暗通款曲，陈则民被指为其中代表，试图在光泽组织伪政权，但未及成立即抗战胜利。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b90bb3bde2248749d84de99cacecc75','3ddcc127-5826-403f-a111-884214140c0c',1940,'南平本地人','南平本地人，日军侵扰南平期间组织伪维持会，为日军筹粮、带路，协助维持伪秩序，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8545d049cc734b95a57cfb12ac50fbcf','579ba422-908a-40b6-8e2c-4e9b6b801bf5',1940,'延平本地士绅','延平本地士绅，抗战期间附逆，任伪延平县维持会副会长，协助日军征发民夫、物资，宣传“中日亲善”。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-994dfff3f71b4a59ac71e8144b7df1ad','95323065-2a0e-4f83-a766-a72ec8ac2a16',1941,'南平人','南平人，任伪南平县警察局局长，带领伪警察配合日军搜捕抗日分子，勒索百姓，维持伪政权治安。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fefb594888bb4e2dbe00490e1884233c','983577ea-9373-4140-98a0-96a0841c0643',1938,'福建人','福建人，投靠日伪，任伪福建省政府委员兼教育厅厅长，推行奴化教育，篡改教材，毒害青年。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7510c77b4f784aa4804d54a960e5f3fb','b68a5fe5-1038-4dfd-bf8a-1086bbc2f10c',1940,'南平乡村保甲长','南平乡村保甲长，附逆日军，负责摊派捐税、监视村民，举报抗日人员，协助日军维持基层统治。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76f316bf6146470c8a3191657a3392ef','9b41c26f-c18a-4fbd-b3fe-0770d43e21fe',1941,'在南平、建瓯一带组织伪维持会','在南平、建瓯一带组织伪维持会，协助日军维持占领区秩序，推行保甲制度，为日军征粮征税，镇压抗日活动，是闽北地区直接为日军服务的汉奸头目。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a6cda7d8eb94a26a4423ae441d6fd33','9b41c26f-c18a-4fbd-b3fe-0770d43e21fe',1941,'福建南平人','福建南平人，抗战期间在南平、建阳一带组织伪维持会，协助日军征粮、拉夫，维持沦陷区秩序，参与诱降地方抗日武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9385cb28d5024d41a0c3f9914087ac00','9b41c26f-c18a-4fbd-b3fe-0770d43e21fe',1941,'南平地区人','南平地区人，1941年日军侵入闽北时组织伪维持会，任会长，为日军征粮、带路，协助镇压当地抗日武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e16dc0fa2ad482a8c2869c29e7eb8b0','3c502220-6ee7-4511-a5ad-56e0dd6c9545',1941,'建瓯本地汉奸','建瓯本地汉奸，日军侵占建瓯期间出面组织伪维持会，担任会长，负责为日军筹集物资、招募劳工、传递情报，并协助日军镇压当地抗日民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de98453364b143fc817b45d4e839a63e','6f670a21-d29e-40c9-8507-27785bb8fd59',1941,'南平本地劣绅','南平本地劣绅，日军进犯南平时投敌，出任伪维持会副会长，协助日军推行殖民统治，参与征粮、征丁，迫害抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aadb3d2deff84917a3393a4b10acfd77','cb46ed33-a998-485a-8499-4e71b6b91ec2',1940,'福建籍汉奸','福建籍汉奸，在伪福建省政府中主管警务，建立伪警察体系，配合日军在福建各地搜捕抗日人士，其警务网络覆盖南平、建瓯等闽北地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31e096a6d97046f6a06411e8998c5317','04124ccd-a15d-45c6-a6f3-726313fe9421',1942,'组织伪保安团在闽北地区活动','组织伪保安团在闽北地区活动，配合日军对南平、建瓯一带的抗日根据地进行扫荡，烧杀抢掠，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1fbb1eb495f4cb08cd4e57a142ad38d','960f5715-5a8d-4319-9c09-ab8050481044',1938,'福建福州人','福建福州人，抗战期间附逆，任伪福建省政府委员等职，协助日军维持福州及周边地区伪政权，参与征粮、拉夫与宣传亲日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f9618d6ea2f44fca65d4c68d03f7853','960f5715-5a8d-4319-9c09-ab8050481044',1938,'福建福州人','福建福州人，抗战期间附逆，在伪福建省政权中任职，参与日军控制下的福州地方伪政权筹备与维持活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-788976d917064aec931b8a827af99b57','960f5715-5a8d-4319-9c09-ab8050481044',1938,'福州人','福州人，抗战期间附逆，在伪福建省政府任职，参与福州地区伪政权筹备与维持活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1879d1d53e7f42d593eeeeab8ef04db0','960f5715-5a8d-4319-9c09-ab8050481044',1938,'福州人','福州人，投靠日军后历任伪福建省政府要职，参与组织伪政权，推行奴化教育，协助日军征粮征税，压迫福州民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-edf9680c0c8e4254b6b10cafa0757d59','960f5715-5a8d-4319-9c09-ab8050481044',1938,'福州人','福州人，抗战期间附逆，在伪福建省政府任职，参与伪政权在福州地区的行政筹备与殖民统治事务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3e6c74f5e7344adb4f7db4e7247f6b0','960f5715-5a8d-4319-9c09-ab8050481044',1938,'福州人','福州人，抗战期间附逆，在伪福建省政府任职，参与福州地区伪政权筹备与维持事务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af5361b6cebc45a196cb2a0d88beb5db','960f5715-5a8d-4319-9c09-ab8050481044',1938,'福州人','福州人，抗战期间附逆，在伪福建省政权中任职，参与日伪对福州地区的统治与物资征调。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-498cb4e3cdff49899538e2e8c17fec06','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'福建厦门人','福建厦门人，厦门沦陷后任伪厦门维持会会长、伪厦门特别市市长，为日军筹款筹粮，推行奴化教育，搜捕抗日人士。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cdfb236b741493a871d2f5b03ad202b','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'继陈群之后任伪厦门特别市市长','继陈群之后任伪厦门特别市市长，配合日军实施经济统制、物资配给和治安强化运动，镇压抗日活动。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0bd7cac27f2419e831c1ce96bab4600','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'厦门沦陷后出任伪厦门特别市市长','厦门沦陷后出任伪厦门特别市市长，配合日军维持厦门占领区秩序，推行伪化行政。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b994e95a46c43d88773e070d3500e15','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'作为福建沦陷区最高伪政权头目之一','作为福建沦陷区最高伪政权头目之一，其政令覆盖泉州沿海一带，推行奴化教育、经济统制，协助日军掠夺福建资源。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b59b6c83e2f424fa710f2ee855082a4','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'厦门沦陷后出任伪市长','厦门沦陷后出任伪市长，推行日军殖民统治政策，在闽南地区配合日军进行经济掠夺和奴化教育。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ac44478e0944af482e067c011dff3d9','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'抗战期间出任日伪厦门特别市市长','抗战期间出任日伪厦门特别市市长，协助日军维持沦陷区统治，是福建地区有明确记载的伪政权头目之一。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e72c91da15e42a38ad18b0317f9c7a6','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'厦门沦陷后出任伪市长','厦门沦陷后出任伪市长，推行日军殖民统治，配合经济掠夺与奴化教育。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31ebaea5592e4581aa896f77342a4dd7','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'厦门沦陷后投敌','厦门沦陷后投敌，历任伪厦门维持会会长、伪厦门特别市市长，配合日军在闽南包括泉州沿海地区的统治与清乡。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f409267e7664b3e94024bc895fc84ca','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'继陈裔之后任伪厦门市长','继陈裔之后任伪厦门市长，推行伪化教育、经济统制。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60182a8177624d7891d9100a0429d82d','aecaa286-eca4-49f4-b7af-80e65b29b19e',1938,'在厦门伪政权中历任要职','在厦门伪政权中历任要职，配合日军实施经济统制与奴化教育。','危害等级A（甲级，特别市市长）','hanjian');
