INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5776978f3caa413f8491c84522b32257','bb3aa6d9-f130-4ea7-b533-d79263820102',1941,'福建建阳人','福建建阳人，建阳沦陷期间任伪维持会会长，为日军筹办粮秣、夫役，协助推行保甲连坐，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
