INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79c8becb87804120852d1dc809291902','b4f03f6b-8326-4453-a86e-af279e1395ce',1941,'福建福州人','福建福州人，抗战期间附逆，任伪福州维持会会长、伪福建省政府参议，协助日军维持福州治安，推行配给制度。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b1236cc74524dafaf85dcbeeea4ae0e','55a68c30-e301-457f-8e08-d85b4e3ec3b7',1942,'福建南平人','福建南平人，抗战后期组织伪闽北绥靖军，活动于南平、建阳、建瓯一带，配合日军扫荡闽北抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
