INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c908abcfee8944e89e2c5624bf5359cb','525974f4-9f03-4ddf-8670-be475ae20bff',1938,'福建长汀人','福建长汀人，早年投靠日伪，1938年后参与伪维新政府，后任伪南京国民政府内政部长、伪福建省政府主席等职，协助日军在福建推行伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
