INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ead114e1515b494380b5ccf107d2beb5','53fa02ac-6ff0-4b7a-ab73-a6110f1fcece',1940,'盘踞闽南沿海岛屿','盘踞闽南沿海岛屿，与泉州伪政权勾结，进行海上劫掠和日军物资运输。','危害等级C（丙级，基层头目）','hanjian');
