INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bcd408f0ce504533af8e23c779509e61','228d5c5d-3944-494f-affb-49d638cb7aad',1938,'在厦门及闽南地区搜捕抗日分子','在厦门及闽南地区搜捕抗日分子，其警务系统延伸至泉州周边，协助日军维持殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d931cc2ceaa04539b756f9ffc7b4d64b','6f236d2d-e266-405d-b3cd-4ee979a76ee1',1939,'在泉州城内推行保甲连坐','在泉州城内推行保甲连坐，监视居民言行，向日军密报抗日人员及物资。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07a5ec1834f04292b1e59875b5232b3c','2fb8dea2-8014-40cb-a326-38ad4d53ecb6',1931,'盘踞泉州、永春、德化一带','盘踞泉州、永春、德化一带，割据闽南，后接受国民党收编，但其势力长期控制泉州地区，横征暴敛，与日伪势力有勾连。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9925c89750a4ac59052add9ee17f311','2fb8dea2-8014-40cb-a326-38ad4d53ecb6',1931,'盘踞泉州、南安一带','盘踞泉州、南安一带，接受国民党收编后仍割据地方，后与日军及伪政权暗中勾连，其部属在泉州、南安地区横征暴敛、残害民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f89dc8e8d9b44d6986f4cec95cfb4ab','2fb8dea2-8014-40cb-a326-38ad4d53ecb6',1931,'盘踞泉州、永春、安溪一带','盘踞泉州、永春、安溪一带，割据闽南，后接受国民党收编，但其部属在地方横征暴敛，与日伪势力有暗中勾连，1932年被十九路军处决。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b2987c0b114466f9f56e02eaed07448','2fb8dea2-8014-40cb-a326-38ad4d53ecb6',1931,'早年盘踞泉州、永春、德化一带','早年盘踞泉州、永春、德化一带，1931年后接受国民党收编前后与日方有勾连，在泉州及洛江周边扩张武装势力，横征暴敛，后被十九路军处决。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff324c69d369437b8981a1099f2987fe','2fb8dea2-8014-40cb-a326-38ad4d53ecb6',1931,'盘踞泉州、南安、永春、德化、安溪、惠安、莆田、仙游等地','盘踞泉州、南安、永春、德化、安溪、惠安、莆田、仙游等地，割据闽南，横征暴敛，与日本势力暗中勾连，后被十九路军以汉奸罪名处决。','危害等级B（乙级，市县厅局级）','hanjian');
