INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74c81bd5f405440d88757975bf23d859','132dafce-99f3-492e-afa4-172f601bdde4',1939,'在厦门伪政权任职期间','在厦门伪政权任职期间，多次派人潜入泉州、南安等地发展伪组织，诱降地方武装，配合日军扫荡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-51dde797641e44d693d08cd3c2cfda02','8dd496d9-0bfd-4f2b-a34f-e34978778262',1938,'在厦门及泉州沿海为日军筹款、征粮','在厦门及泉州沿海为日军筹款、征粮，组织物资输日，拉拢泉州、南安商界人士附逆。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fc0efbbb469493bb09b0acad32c7b51','7babdb58-5c7f-474b-9815-5b9185ff2954',1938,'在晋江（今泉州辖区）组织维持会','在晋江（今泉州辖区）组织维持会，为日军登陆泉州沿海提供向导与补给，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b3eaad0208a4a76bf58671d408fd027','d1fd0358-ce78-4220-82bb-ba7164a62c97',1939,'在南安一带活动','在南安一带活动，串联地方劣绅筹建伪维持会，为日军搜集南安、安溪山区抗日武装情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ca5be458ceb4482b8e74d94295b1eda','61f3a168-e955-427b-b34c-d3dc5c5120a3',1940,'在泉州城郊充当伪保甲长','在泉州城郊充当伪保甲长，协助日军清查户口、抓捕抗日人员，向伪警察局密报南安籍抗日家属。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cbca3a2817c49c68ae3fe776bac0703','996f9197-d07e-40e2-ad92-3e5c7fba7d57',1939,'在泉州推行日语教育','在泉州推行日语教育，编写亲日教材，组织学生参拜日本神社，进行奴化宣传。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2992d00a0cbc408c8f21c7f14df9a426','68e55f6f-bb7d-4e33-a1d8-1a6998d6e35e',1939,'多次往返厦门与泉州','多次往返厦门与泉州，传递日军指令，协助伪政权在泉州、南安发展下线，诱降地方实力派。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ac397a9696a4ed9b654fcfc8fbdd0d9','d2e111c2-161c-4555-bb17-2c65c9685925',1931,'长期盘踞泉州、南安、安溪一带','长期盘踞泉州、南安、安溪一带，为非作歹，后虽被国民党收编，但其部属在抗战初期有投敌附逆行为，对闽南地方造成严重危害。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4dfae2e69ecc4b07bf16580c3e224b16','d2e111c2-161c-4555-bb17-2c65c9685925',1931,'长期盘踞闽南、闽西一带','长期盘踞闽南、闽西一带，曾与国民党地方势力及日伪方面有勾连，在龙岩、漳平、华安等地活动，对地方民众横征暴敛，后被国民党方面处决。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff56287645bf4e42b41c554761a82314','d2e111c2-161c-4555-bb17-2c65c9685925',1931,'长期盘踞闽南、闽西一带','长期盘踞闽南、闽西一带，曾控制漳平、龙岩部分区域，勾结地方豪绅与日伪势力，扰害地方，后被国民党当局处决。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07cd49c92c95452ca141acd7bc0cfe01','e8deb5dc-6a33-4b91-a2bf-354f54ca1088',1938,'厦门沦陷后投敌','厦门沦陷后投敌，历任伪厦门治安维持会委员、伪警察局长等职，协助日军维持闽南沿海占领区秩序，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe739bca6add4104b836c1d08636ca66','819da36c-48eb-46fc-92d9-91913bf3fff6',1938,'厦门沦陷后参与组织伪维持会','厦门沦陷后参与组织伪维持会，后任伪市政府参事，协助日军在闽南地区推行殖民统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79e7c48935174ce09419a75461069b1a','e2334fec-93a3-46aa-b5bb-9c5f028c4fc0',1938,'厦门沦陷后与日军合作','厦门沦陷后与日军合作，控制商会为日伪筹集物资，在经济领域附逆，影响闽南地区经济秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe664c9f69394680873c7b6072816aba','ed7782be-3023-48ee-95a0-e4b13a3fda98',1939,'在伪厦门警察系统任职','在伪厦门警察系统任职，参与镇压抗日分子，维护日伪在闽南沿海的统治秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d019a5bf7ad04e4f852bb258631c780e','5c9b9da1-3a8c-405c-bb23-2b7ea5c69034',1938,'泉州沿海地区沦陷期间','泉州沿海地区沦陷期间，出面组织伪维持会，为日军筹粮筹款，协助维持地方治安，属泉州地区直接附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15d2636522384252bc491700378e4fb6','238d465f-70d5-47e6-a5a2-cc997ab2bf7b',1938,'在惠安地区组织伪维持会','在惠安地区组织伪维持会，配合日军登陆后的地方控制，为日伪政权服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6aadf36df666416da899bb96be44103c','93baa91b-a8ec-4d3d-9341-d86c90ac7d77',1938,'在福建伪政权中任职','在福建伪政权中任职，参与协助日军对福建部分占领区的管理，属省级附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39b659ae9e864fec8f156e3e830ddb98','d5baaee8-6d69-4f33-962d-32a5cf0d6fe1',1938,'在伪福建省政权中担任职务','在伪福建省政权中担任职务，协助日军推行殖民政策，影响范围覆盖闽南地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10a14b2add59493eb68b0c49effa1534','5bea1613-34d0-4914-9c64-dec5c6a22ec8',1940,'组织伪军配合日军在福建沿海活动','组织伪军配合日军在福建沿海活动，包括泉州、厦门一带，进行反共与镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0004e9af50c473fa3494dbf1c59c7c5','7aa59e0a-f583-47a4-9241-0155f7655cbd',1939,'率伪军在闽粤边区活动','率伪军在闽粤边区活动，配合日军进攻抗日根据地，其势力范围涉及福建南部包括泉州周边地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02566d6fc1784eda88dc37875c3e11cd','f27e9a1b-badf-43b8-958e-d74babb725f7',1939,'在伪厦门政权中负责教育事务','在伪厦门政权中负责教育事务，推行日语教育和奴化宣传，属文化教育领域附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5dec36cafac47e4a904d931033cd139','7fa58123-1b41-4443-bb9c-2332fdaa1748',1939,'主办伪报纸','主办伪报纸，为日军进行舆论宣传，鼓吹“大东亚共荣圈”，属文化宣传领域附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6635dde52954ecc804bca65ada50ddc','9ede96a2-52b1-436b-ac9e-2024811798e6',1931,'长期盘踞泉州、德化、永春一带','长期盘踞泉州、德化、永春一带，割据地方，与日伪势力有勾连，后被国民党当局处决','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c66ae87a8ffb4857926d09d0c323a328','9ede96a2-52b1-436b-ac9e-2024811798e6',1931,'其部属在闽南地区活动','其部属在闽南地区活动，对地方社会造成严重破坏。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-406426a3a4824dfca0114a7bcf957d28','4e6a3ee6-5453-43bd-9647-1cd5e3e8ce4e',1930,'在泉州、德化、永春等闽南山区活动','在泉州、德化、永春等闽南山区活动，曾与日伪及地方反动势力勾结，扰害地方，后被剿灭。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2a89fa707244382b14e5b5a497303cc','53a4f7e1-19fb-48f4-a077-75b3eecbb622',1938,'福建沦陷区伪政权成员','福建沦陷区伪政权成员，参与日伪在闽南的统治活动，其影响范围涉及泉州、厦门一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ddbfbb5b012d4a6f999e4539906b3a04','753e1707-85b4-4309-8214-d5416085b29c',1938,'在泉州晋江一带参与日伪维持会活动','在泉州晋江一带参与日伪维持会活动，协助日军征粮、派款、维持地方秩序，属于基层附逆人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f1dd445c68a46d4b2e50aaa3d8532ca','83c3e716-c9f8-4491-b414-a546f71fb99c',1938,'泉州沦陷前后','泉州沦陷前后，部分地方士绅被日伪拉拢参与维持会事务','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
