INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-369d0a1d75ed45ad8e2a1a7677eeb1e0','4108a06b-b05a-4d75-a185-867ebc23f206',1940,'德化地方史料中提及的维持会人员','德化地方史料中提及的维持会人员，协助日伪在德化山区进行统治与征敛，具体事迹记载较少。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f6b3d57ba27a4e4c8d7880f3e3472755','93671893-bcc0-41e9-bb8a-dee3c31890d6',1938,'泉州地方志及抗战史料中提及的附逆人员','泉州地方志及抗战史料中提及的附逆人员，参与伪维持会活动，协助日军控制泉州城区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-977dce54930548afbb0f2c8c2d59f01a','d830c7e9-eede-4d16-8bdc-74c5b41d2852',1938,'在日伪福建省级政权中任职','在日伪福建省级政权中任职，参与协助日军统治福建沦陷区，其活动范围覆盖闽南泉州一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5862c3f9de448b1b242bb04756f5539','941d7e6d-ec96-4428-b73d-9e4b5817b401',1931,'原为闽南土匪武装首领','原为闽南土匪武装首领，1931年前后接受日本特务机关拉拢，在泉州、惠安一带组织伪军，配合日军侵扰闽南沿海，后被十九路军击败处决。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1aaf14d451c84445a3b6380a17bc67e8','a7835355-29bf-4ecd-88e3-9864183368cb',1938,'厦门沦陷后组织伪维持会','厦门沦陷后组织伪维持会，后任伪厦门特别市商会会长，为日军筹款筹粮，配合经济掠夺，与泉州、惠安商界有联系。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-213d796d92784de89eee3730753c2ba4','272fb99c-429e-4216-b8f6-3b283c2c46b7',1938,'泉州沦陷前后组织伪维持会','泉州沦陷前后组织伪维持会，为日军提供情报与物资，协助建立伪保甲制度，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-304802a9f2ac440e846581ff19777fba','272fb99c-429e-4216-b8f6-3b283c2c46b7',1938,'泉州沦陷前后组织维持会','泉州沦陷前后组织维持会，为日军筹粮、拉夫、搜集情报，协助建立伪基层政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41f42e3da7db4ef8a7dc54a419fccd06','d7d75484-587d-4312-a367-45947eb749d7',1939,'惠安本地士绅','惠安本地士绅，日军侵扰惠安时出面组织伪维持会，协助日军征粮征夫，后因民众反抗而瓦解。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97215d1f2f16449f82e269b28ccdf704','d7d75484-587d-4312-a367-45947eb749d7',1939,'惠安人','惠安人，在日军登陆惠安、泉港一带时出面组织维持会，为日军带路、征发民夫，协助建立伪保甲制度。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdbbc9cfda3049e18c15d8e78663994d','eb354f36-ca28-402b-bff2-c60b488d723f',1940,'原厦门名流','原厦门名流，抗战期间滞留沦陷区，接受伪职，为日军在福建的统治提供咨询，与泉州、惠安地方势力有往来。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca214c99a39b4b3e8933afac21a9e349','fc928502-4d38-4f7e-ac84-571c12b2bf59',1938,'北洋旧官僚','北洋旧官僚，抗战初期投靠日军，出任伪福建省主席，在福州、厦门等地推行伪化，其政令影响泉州、惠安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae10539c9d3547f396a2cfb6df3c4a3a','fc928502-4d38-4f7e-ac84-571c12b2bf59',1938,'原北洋旧官僚','原北洋旧官僚，抗战期间投靠日军，出任伪福建省主席，统辖包括漳州在内的福建沦陷区伪政权。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-040e0c4b74b7453dac3c8f76fc6d7474','a42dbb8d-ead0-4dd5-9048-d48635380ade',1938,'福建汉奸','福建汉奸，历任伪厦门市长、伪省政府委员，协助日军控制闽南沿海，包括泉州、惠安一带的伪政权运作。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85672d866f8a4e2986e88208b5529f77','3f9f0c6d-802b-41c0-b4b0-328c770d2abd',1939,'泉州本地妇女界附逆者','泉州本地妇女界附逆者，组织伪妇女会，为日军宣传“大东亚共荣”，动员妇女参与伪后勤，活动涉及惠安。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85d651ed78c64b41afc244dc19a02be2','c84e10e8-e16c-4c67-9d77-1ffb61f827e8',1937,'福建南安人','福建南安人，早年盘踞泉州、晋江一带。抗战爆发后投靠日军，在厦门、泉州沿海收编土匪武装，组织伪军配合日军登陆与扫荡，并诱降地方武装，为日军搜集晋江、泉州一带情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-214e7939d4934bcdbc975ca050b77980','1ed14d16-23e6-4295-9bcf-cf503be7cab9',1938,'福建厦门人','福建厦门人，日军占领厦门后出面组织维持会，后任伪厦门特别市市长，推行伪化统治，配合日军向泉州、晋江沿海渗透，征粮拉夫，镇压抗日分子。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10ff4a91724e435db0ed5ccbce083348','359d0528-9b05-47ea-b082-227a2e373ace',1939,'广东人','广东人，受日军指使在闽粤沿海收编土匪、伪军，活动范围包括厦门、泉州、晋江沿海，配合日军封锁与扫荡，残害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7788ccc765b413f8c71c0ee8975ed5b','c83e93ba-e704-42b2-b501-75fdd09f4a00',1938,'在日军侵占厦门后','在日军侵占厦门后，于晋江沿海地区组织维持会，为日军征粮、拉夫、搜集情报，协助建立伪基层政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ceaadd930a9b4ad986431d3bb1249064','825e01ba-7529-45c4-8c36-590fa577a119',1938,'泉州地方士绅','泉州地方士绅，日军侵入闽南沿海后附逆，参与组织伪维持会，协助日军推行保甲连坐，压制抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6632e2f896a84d43bffef023f2d18562','daf82e9d-512e-49ac-a9c7-09af58a526ca',1939,'在厦门及闽南地区推行奴化教育','在厦门及闽南地区推行奴化教育，编写亲日教材，强迫学校使用日语，向泉州、晋江等地渗透文化汉奸政策。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21c52cf484934d8aa311fad4b2bcc94c','92020849-ad27-4a98-919c-a83abea34673',1938,'厦门富商','厦门富商，日军占领后出面组织伪商会，为日军筹款、征物资，并协助向泉州、晋江一带掠夺粮食与战略物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d383871aacae48d484e0a6147f8611fb','f452cf80-c880-425d-8286-d4673db466a4',1938,'厦门名绅','厦门名绅，日军曾企图拉拢其出任伪职，其一度犹豫后避走，但日方仍以其名义进行宣传，在闽南一带造成附逆影响。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b4b6582707b4274894cbb19bf7734b6','b4cf7c44-a66d-46bb-9fa9-9e03a1d3adcf',1938,'厦门华侨富商','厦门华侨富商，日军占领厦门后强迫其挂名伪经济顾问，利用其声望向泉州、晋江侨乡诱骗资金与物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ffb0a52395e451f8feef3a1011317f1','d23d09af-f5f6-4e77-be7f-d7f38fb05470',1940,'晋江本地人','晋江本地人，充任伪保甲长，为日军搜集泉州、晋江一带抗日游击队情报，带领日伪军搜捕抗日家属，勒索乡民。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db9cc823e668469c8a81bd7f783a0d0e','d9cc59bd-48b6-4dc7-9ebb-dfc805fd44f8',1941,'在泉州城区及晋江一带为日军侦缉抗日人员','在泉州城区及晋江一带为日军侦缉抗日人员，破坏地下交通站，逮捕并刑讯爱国人士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9fc0dcd9a0474df496113a41f4f48b00','e73757d4-0592-4c3f-8c75-018b6db05733',1939,'负责厦门及闽南地区的社会控制','负责厦门及闽南地区的社会控制，组织伪民众团体，配合日军向泉州、晋江进行宣传渗透与物资统制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0768d2fe183d405c87a670963289fe4d','fa2bd685-9f80-4d1d-8f97-f2a9642a2573',1937,'金门沦陷后组织维持会','金门沦陷后组织维持会，配合日军封锁厦门、泉州、晋江沿海，为日军提供登陆与扫荡支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b39a5304f70a413d99a4d79bb243afa4','c538877a-a3cc-46cd-bec6-5b8947a97cae',1940,'日军侵占永春期间出面组织维持会','日军侵占永春期间出面组织维持会，为日军征粮拉夫，协助推行伪化统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f55182985beb4038bdef034df82e2267','dfae5c59-193b-487c-a854-89debe339228',1940,'率部投敌','率部投敌，配合日军扫荡永春、德化抗日根据地，捕杀抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5b7e696a6b64d3992247712f48f3569','97ec58d6-342a-4e0e-b5ca-cb2aa75d8cca',1938,'在泉州沦陷期间出面组织伪政权','在泉州沦陷期间出面组织伪政权，为日军筹款筹粮，协助推行日语教育。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b582665227b7491bb5adc2bae8b086df','dc6abb42-9d58-4e3d-ae52-984e7b54974a',1938,'泉州沦陷后组织伪晋江县维持会','泉州沦陷后组织伪晋江县维持会，协助日军维持治安，迫害抗日人士。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-adae7a2a5cab47a99cef30e170988539','3811a5cd-62d7-482f-bbd1-71512847c490',1938,'厦门沦陷后出任伪市长','厦门沦陷后出任伪市长，其伪政权管辖范围涉及泉州沿海，配合日军经济掠夺。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4b82a544f404e99959ae220dc500e96','a9d831cf-08b8-4472-9e02-9c38add96a36',1940,'在福建沿海包括泉州、莆田一带组织伪军','在福建沿海包括泉州、莆田一带组织伪军，配合日军登陆作战，劫掠沿海村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e8bfc886ea134b5e98fb305a2dc04a30','02066f4a-e16f-4601-b4f5-fe496b96d8c4',1940,'在福州伪政权中任职','在福州伪政权中任职，参与制定对闽南地区的伪化政策，协助日军征调物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b341dcf128a2404ebd49062a460283d8','c1f365df-2e7d-4e67-96e0-ba512919cb2f',1938,'汪伪政权福建省主席','汪伪政权福建省主席，推行伪化教育，配合日军清乡，其政令覆盖泉州、永春等地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-efe3a212785440f9b133147702bfe064','c1f365df-2e7d-4e67-96e0-ba512919cb2f',1938,'汪伪政权在福建的最高行政头目','汪伪政权在福建的最高行政头目，推行奴化教育、经济统制，泉州地区伪组织受其节制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-267d6f46ca234dddbfc596f4ecac976e','c1f365df-2e7d-4e67-96e0-ba512919cb2f',1938,'抗战初期投敌','抗战初期投敌，出任伪福建省政府主席，在日军支持下建立伪政权，影响范围覆盖泉州等福建沿海地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-549e34a84b254d59b0e2b903a422a35d','c1f365df-2e7d-4e67-96e0-ba512919cb2f',1938,'汪伪政权在福建的最高行政头目','汪伪政权在福建的最高行政头目，推行日军殖民政策，统辖包括闽南在内的福建沦陷区伪政权。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-190067fbf9a7442d98f142b4a5c33d05','c1f365df-2e7d-4e67-96e0-ba512919cb2f',1938,'汪伪政权任命为伪福建省主席','汪伪政权任命为伪福建省主席，在福州、厦门等地推行伪化统治，影响闽南地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1282ee822524c05ac020f939bad6b81','e5f1dd43-ff41-4dba-8a63-19c1bb7301ec',1940,'在伪福建省府负责财政','在伪福建省府负责财政，为日军搜刮闽南物资，发行伪币，扰乱泉州金融。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db325ee1a1a042d4b8a5e888b473fe42','1c902b43-7b04-4a87-9168-3ede864c4b14',1941,'在永春推行保甲连坐','在永春推行保甲连坐，协助日军抓捕抗日志士，镇压当地抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5943c65d2ee740ddbf9a75ce795db9d9','4dc97c82-f7a1-46e9-ad1d-0e623645b94c',1940,'在德化组织维持会','在德化组织维持会，为日军带路扫荡永春、德化山区抗日游击队。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-073e49cd64f145e39acbfcd49757654b','42d9418d-0e9e-425c-9c87-bd30099d5bae',1931,'福建南安人','福建南安人，长期盘踞泉州、莆田一带，1930年代初期接受国民党收编后仍割据地方，后与日军及伪政权暗中联络，其部属在泉州沿海地区配合日军行动，1937年被捕处决。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cb484200ec54eb8a34823e1b8a144cb','25bf298a-0c18-4f6d-a68d-791b231b4323',1938,'福建泉州人','福建泉州人，抗战期间投靠日军，在闽南沿海组织伪军，配合日军在泉州、惠安、泉港一带登陆与扫荡，残害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bfb1d4216f964959b5c79e122c8db81c','25bf298a-0c18-4f6d-a68d-791b231b4323',1938,'福建沿海伪军头目之一','福建沿海伪军头目之一，活动于闽南沿海及泉州附近海域，配合日军封锁与登陆行动，收编海盗与散兵游勇。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77daa266402040618eb1eb904c9751d7','215dab82-a861-4c27-900f-73995ee79841',1938,'福建泉州人','福建泉州人，与高义同为闽南伪军头目，在泉州、晋江、惠安沿海地区为日军搜集情报、征粮拉夫，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d6bd127a07f4850a2a0694b68df5432','6890ffb0-5981-4c92-b064-b4de23d39d92',1939,'福建厦门人','福建厦门人，投靠日军，在伪厦门政权中担任要职，协助日军控制闽南沿海贸易与物资，其势力范围涉及泉州、泉港一带的走私与情报网络。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d819b02481a4096a97f95cb281ba213','6890ffb0-5981-4c92-b064-b4de23d39d92',1939,'长期在厦门伪政权任职','长期在厦门伪政权任职，协助日军维持闽南沿海占领区秩序，参与经济掠夺与物资统制。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e4a7aefb933429b98ea525f98320d29','88b33b2a-2566-49d9-8d8f-23382009cdef',1938,'泉州本地士绅','泉州本地士绅，日军侵占厦门后，在泉州地区组织维持会，为日军筹粮筹款、拉拢地方势力，协助建立伪基层政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4a8cfbec9f04c4bb20ff646d16a335d','22e3f623-b5ba-4ec4-92bb-46f2657da82e',1940,'泉港本地人','泉港本地人，日军在肖厝、峰尾一带活动时组织维持会，为日军提供渔船、情报与物资，协助控制沿海港口。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ebb6b75e8404022a782acb3ff737a54','206159d1-166c-4f1f-a06c-f84797650736',1939,'福建晋江人','福建晋江人，在泉州、石狮、泉港沿海为日军收编海盗与地方武装，组织伪军配合日军扫荡抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df77683ac97a4fc0a9e55df07ba3dccc','34eb26f9-bf7b-4321-bbac-011fd6fc42e7',1938,'福建惠安人','福建惠安人，投靠日军后率部在惠安、泉港、莆田沿海活动，为日军护航、走私，并镇压当地抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
