INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-268a86ae72d44b1f9ed86937ae0e5c40','332344fe-f3ae-4be4-a011-95f19a4b1e84',1931,'原为闽南地方军阀','原为闽南地方军阀，九一八事变后与日本特务机关接触，企图借助日军势力割据闽南，后在漳州一带被十九路军击溃。','危害等级C（丙级，基层头目）','hanjian');
