INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e3ae7b6df2348f2954569361a2c99df','f5a24244-d917-4a3e-bc0f-498f85fbbecf',1938,'在厦门沦陷期间为日军筹款筹粮','在厦门沦陷期间为日军筹款筹粮，协助日伪对闽南沿海地区进行经济控制和物资征调，其活动影响波及漳州沿海。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2c74978df564ff8a7d3058781924885','f5a24244-d917-4a3e-bc0f-498f85fbbecf',1938,'厦门商界人物','厦门商界人物，抗战期间附逆，协助日军控制闽南物资流通。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e89ec9d2294437aad18b05ce6ee0504','f5a24244-d917-4a3e-bc0f-498f85fbbecf',1938,'厦门沦陷后投敌','厦门沦陷后投敌，协助日军统制闽南物资，为伪政权筹款筹粮，其商业网络覆盖漳州、诏安等地，间接支持日军对闽南的侵略。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fa70b63d3e649f4bc6ef9e7fcd8acd8','fe50505b-08ea-49eb-abd3-5e4d53863556',1938,'抗战期间投敌','抗战期间投敌，在福建日占区任职，参与伪政权对闽南沿海地区的统治和资源掠夺。','危害等级B（乙级，市县厅局级）','hanjian');
