INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c8677b84ceb45d29a91c67b33e4e560','d30d37ea-f5e5-4cad-beca-60c869c01f70',1939,'在汕头沦陷区组织伪维持会','在汕头沦陷区组织伪维持会，配合日军对闽粤沿海实施封锁，其活动范围与漳州、东山沿海地区有交叉。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
