INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-782a0ce2af1240cea2fa8eae91c47a44','c276e56a-87b0-48b9-8040-3e96d51836de',1939,'据地方史料零星记载','据地方史料零星记载，东山沦陷期间曾有维持会组织，吴友三可能为负责人之一，协助日军征调民夫、物资，但具体事迹记载较少。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
