INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43a6b63086a34247a73a6c49ce56c1cd','996659ed-a7b3-47a3-a644-d72ed8425ee6',1940,'在日军扶植下出任伪莆田县知事','在日军扶植下出任伪莆田县知事，推行伪化教育，征发民夫物资供应日军，配合日军清乡扫荡，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d832663e5184c9a9ae3d2978c958d34','539a96b2-742d-4ba2-bf16-36609a535315',1939,'涵江本地劣绅','涵江本地劣绅，日军登陆涵江后组织伪维持会，任会长，为日军筹款筹粮，协助建立伪保甲制度，破坏当地抗日组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09d893050a0f4f6ea3412395cc8649cf','3323893c-a200-41ca-b311-359c5080ba1f',1941,'福建伪政权骨干','福建伪政权骨干，曾任伪莆田县县长，配合日军在莆田、涵江一带推行治安强化运动，抓捕抗日人士，强征劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f89fdc233c894beab1962db797c28b27','0723d4a6-41eb-479d-87eb-4611633880cc',1940,'任伪莆田县警察局局长期间','任伪莆田县警察局局长期间，带领伪警察配合日军搜查抗日分子，镇压民众反抗，维护日伪统治秩序。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6914aed77a334af7973314e556001ae3','7cb7ab44-a59a-4ef8-a276-f174d9ed8be2',1941,'涵江伪镇長','涵江伪镇長，推行保甲连坐，协助日军征粮征税，监视居民言行，迫害抗日家属。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c81cac10598468ba257559acff01471','608b9f29-9422-4b46-ad27-e8f3df6f2ed9',1938,'福建伪维持会头目','福建伪维持会头目，协助日军在福建各地建立伪组织，包括莆田、涵江等地，为日军提供情报和物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd9e9280b37d4a9f92096357256222da','0d4af465-b0a5-4071-8839-848c3c3f18ff',1940,'在莆田推行奴化教育','在莆田推行奴化教育，编写亲日教材，组织学生参加日伪宣传活动，毒害青少年，为日军文化侵略服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a35144ba2fe245359996b3f454cc1191','8582244b-e50c-434d-a3c2-8c4825d5b7d0',1939,'福建沿海汉奸武装头目','福建沿海汉奸武装头目，率伪军配合日军在莆田、秀屿等沿海地区进行登陆作战和扫荡，劫掠沿海村庄，捕杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c04e92bca3744f7c8480a8f033d53a1b','3b6ea49b-3407-4317-ba70-a1a8f82aabff',1941,'出任伪莆田县警察局长','出任伪莆田县警察局长，统领伪警察配合日军维持治安，搜捕抗日人士，勒索百姓，为日军提供情报。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-780e7b59e0e74a46b3608a1cd3a31a59','07aae02f-8e7f-4ead-8b87-eed7eb4c2b7a',1940,'秀屿本地汉奸','秀屿本地汉奸，组织伪维持会，为日军在秀屿港的军事行动提供后勤支持，协助日军征用渔船和民夫，迫害抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5cb4de0eef5f4304a30d3e8fdae1d9a5','66a34a41-2fd3-4604-b4f6-6ef0e7aea1f6',1940,'福建伪政权高层之一','福建伪政权高层之一，参与制定伪化政策，协助日军在福建各地包括莆田地区推行保甲制度和物资统制，镇压抗日运动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c78a4610cc254177b84dae53f9d7ff51','c1ac7565-3f9a-4b39-ba54-ec0e360bfcda',1941,'任伪莆田县警察局局长期间','任伪莆田县警察局局长期间，带领伪警察配合日军扫荡，逮捕抗日志士，勒索民众，为日军提供情报。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a116f707da4244cb9436b844ec8e6476','b9347142-b9bb-4128-a686-a5c5cc61cad6',1938,'福州及闽中地区汉奸','福州及闽中地区汉奸，参与组织伪维持会，后任伪福建省警务处督察，协助日军在福建沿海地区进行统治和搜捕抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04bc3641ea7c44a6b7dba6c1b47e41f1','1c258044-6c62-40f8-aefc-e6c3bb162372',1940,'统领伪保安大队','统领伪保安大队，在莆田及荔城周边地区配合日军清乡，镇压抗日游击队，强征民夫修筑工事。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d2c3b523a114c808785d5ac185c9ec9','3c909c64-e250-4987-b163-ee40795ea24c',1939,'福建籍汉奸','福建籍汉奸，任伪厦门特别市市长，协助日军在闽南及莆田沿海地区的殖民统治，推行奴化教育，为日军筹集物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2a16dd4d136463ca2690b960ee8e1ff','164fa92a-1e3d-4bfa-8bf5-61fd1f66a7e9',1940,'在伪福建省政府任职期间','在伪福建省政府任职期间，兼任伪莆田县县长，推行保甲制度，配合日军征粮征税，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfd2f5df8fc549d49e8fac60ecf4b312','43b75954-ff3f-4724-ae82-e29bc30b3964',1941,'在伪莆田县教育科任职','在伪莆田县教育科任职，推行奴化教育，篡改教材，向学生灌输亲日思想，协助日军进行文化侵略。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5d062cb86a84d609ee312d2a54f282f','bfdbc671-b125-4729-a764-cf9d6e6486e3',1931,'长期盘踞闽南、龙岩一带','长期盘踞闽南、龙岩一带，勾结日本势力，组织伪军，扰乱地方，后被十九路军擒获处决。','危害等级C（丙级，基层头目）','hanjian');
