INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93e2372fd8084a6381829abec5e8c769','8a02c7fa-3115-4e74-8951-3f72e618b573',1938,'厦门沦陷后组织维持会','厦门沦陷后组织维持会，为日军筹粮筹款，协助控制地方经济。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad1d49adeaad4f19a79ce2f931a35745','f130246e-cfe0-4894-9806-342dd7667fda',1938,'在厦门日占区拉拢华侨','在厦门日占区拉拢华侨，为伪政权宣传“东亚共荣”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
