INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0c1f5bcdac44df7bee5a564d1aee89a','84d7fd10-92da-4bf5-8bbf-aaea1e6641cf',NULL,'地方志资料中提及上杭沦陷或日伪渗透期间','地方志资料中提及上杭沦陷或日伪渗透期间，有地方士绅出面组织维持会，协助日军征粮、派夫，黄国泰为其中被记载者之一。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
