INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43b95a44b49540f88829513dd0113793','9ae5e717-99c2-4db7-bbb8-97190b799352',1940,'担任伪保甲长期间','担任伪保甲长期间，为日伪征派粮款、壮丁，举报抗日人员，欺压乡里，解放后被清算。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4616378cdc474a1c8ac01d9155382ff7','5cc766b8-b5ee-4959-a16d-abbc1734afec',1940,'在龙岩、上杭一带协助日军建立伪政权','在龙岩、上杭一带协助日军建立伪政权，组织维持会，为日军提供情报和物资，抗战胜利后逃匿。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9eedd553dbee46e19c8770afa6319ebd','9c8b51a5-4ebc-4b04-9495-0f857f686bff',1940,'利用商会身份与日伪合作','利用商会身份与日伪合作，为日军采购物资、筹集款项，压制商户抗日活动，地方志中有附逆记载。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52972d9de3244b5d98026fd426c5db88','3221be73-107f-48f4-b768-708d253e2b5f',1940,'龙岩地区沦陷或日军侵扰期间','龙岩地区沦陷或日军侵扰期间，出面组织伪维持会，为日军征派粮食、民夫，协助维持地方伪秩序。龙岩为武平所属地级市，其活动直接覆盖闽西核心区域。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc29fc42b09a4f6c804737067328f563','497a164f-5244-4a69-abef-ea4e568921fe',1940,'在武平及周边地区协助日军与伪政权推行保甲制度','在武平及周边地区协助日军与伪政权推行保甲制度，征发物资、传递情报，压迫当地民众。此类基层附逆者多见于闽西山区。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08182720706c47b1af7e980076cb60b7','7e6aebce-27b7-4bbe-b2b5-5582d015c279',1940,'在闽西龙岩、武平、上杭一带活动','在闽西龙岩、武平、上杭一带活动，组织伪自治会，配合日军与伪军进行清乡、招降抗日人员，破坏当地抗日组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7fd9711b5d594efcb5fcb561e582e3bb','59c544af-a0e4-48ca-a344-88381f85e967',1938,'在福建沿海及闽西南地区收编武装','在福建沿海及闽西南地区收编武装，投靠日军，任伪军支队司令，参与对龙岩、漳州一带抗日游击队的扫荡与封锁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f8d148b27a74091a83b7662f8d2aa92','043b62a3-1b3d-46fe-bae1-0277a366f09f',1938,'在伪福建省政府中任职','在伪福建省政府中任职，负责伪警察与治安，协助日军在福建占领区推行殖民统治，其警务系统延伸至闽西部分县区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abc2492fecf3449e80a93313a2947a58','14050043-a966-4b56-bca5-c1d36edbcd09',1938,'抗战期间参与福建伪政权活动','抗战期间参与福建伪政权活动，在福州等地附逆，为日军统治福建沦陷区提供协助。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0637f54818364a568d3fea557d71b90c','de29fab1-4e2e-4835-8186-99de7e38ee46',1938,'抗战时期投靠日军','抗战时期投靠日军，任伪福建省政府主席等职，参与组织福建沦陷区伪政权，推行日军殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1ab26bbb2ae4a728318672ea92e51d3','5226c6c7-f1c5-4d1d-81aa-c4a681656257',1938,'在福建沦陷区参与伪政权与伪警察系统','在福建沦陷区参与伪政权与伪警察系统，协助日军维持治安、镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e8f93b1f7d64dc3b1b310eb2b7ab489','85b659c9-41ab-4528-b4db-4f51dd693ebb',1938,'厦门沦陷后参与维持会及伪政权活动','厦门沦陷后参与维持会及伪政权活动，为日军在闽南地区的统治服务。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c30d7eb829f49a98525d60f1a0a5e8d','76131942-1826-4514-83cb-66940e3722a5',1938,'厦门沦陷期间与日军合作','厦门沦陷期间与日军合作，参与伪商会及经济统制活动，协助日军掠夺闽南物资。','危害等级C（丙级，基层头目）','hanjian');
