INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11a91aa9a15543ecb26b730862fb5115','6afbc049-b606-4d2f-9460-50c299bc208e',1940,'在龙岩地区参与伪维持会活动','在龙岩地区参与伪维持会活动，协助日军及伪政权控制地方，压迫民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
