INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-987b381a364e485fa3421d1028ad401c','7fd1abf3-2ecd-44e0-b9f0-70d17648fa4d',1940,'在龙岩伪警察系统任职','在龙岩伪警察系统任职，协助日军和伪政权镇压抗日群众、搜捕抗日人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
