INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b6f5b1390134ff788d3e18c59a62cb9','f1a4b92a-61c4-4a8e-8b48-e3eced2f17cf',1940,'在龙岩教育领域推行奴化教育','在龙岩教育领域推行奴化教育，协助日伪宣传，毒害青年。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bfccd4d9dff468688f367104b75beb9','0286852d-a41f-483e-9402-f0c24a253a77',1938,'福建籍旧官僚','福建籍旧官僚，抗战期间投敌，在闽南组织伪自治会，协助日军推行保甲制度、征粮征丁，其伪政权网络延伸至闽西部分县区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d43375cf22a4efaabe4664d32d2870a','75b7384d-5b8e-48a7-afc0-54bbdd8fc795',1938,'原福建地方军阀','原福建地方军阀，抗战初期投靠日军，在闽南组织伪军，配合日军对闽西南抗日武装进行清剿，活动范围接近龙岩地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fc7154692fc48c4b842945be24b63fe','a77acdfc-034e-4e5f-b621-142ee7e4e982',1941,'福建籍汉奸','福建籍汉奸，福州沦陷期间出任伪职，协助日军维持福州及闽东地区统治，参与征发物资、劳工，对福建全省伪化有推动作用。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1834fb4c664c466a89044ffff772d98e','0efd9a3a-bc72-469e-aaed-9ff59231fe3a',1944,'长汀本地劣绅','长汀本地劣绅，日军侵扰闽西期间组织伪维持会，为日军带路、筹粮，协助建立伪保甲，迫害抗日群众。长汀为龙岩地区重要县份，其伪维持会直接服务于当地日军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26f995a5387c433abb096b5b70856d96','bcd9b1c9-0cb1-47e1-8cd8-604604e0c9ab',1944,'龙岩本地地主','龙岩本地地主，抗战后期投敌，组织伪维持会，协助日军在龙岩地区征粮、征夫，破坏抗日基层组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9cda83be66f346fb835561c63e56588e','afd4007e-613f-4aea-9ba9-99aac113ad0c',1944,'上杭县劣绅','上杭县劣绅，日军侵扰闽西时出面组织伪维持会，为上杭、长汀一带日军提供情报与物资，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9b89103266d4ddb997b7ba62307a49c','de2fb8d3-42f8-4546-b48b-004e6bbe5063',1944,'武平县地方势力头目','武平县地方势力头目，投靠日军后组织伪维持会，配合日军对闽西抗日根据地进行经济封锁和扫荡。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1141a6c24a742dea109b10ee83a0402','4883c575-3598-4b0f-9b63-6ee701ea3483',1944,'永定县劣绅','永定县劣绅，组织伪维持会，协助日军在永定、龙岩交界地区征粮征丁，破坏抗日交通线。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f590ab6999db4e198f27f023851b3d7b','c51a6976-fe7a-499e-8987-1ecced560213',1944,'连城县地主','连城县地主，投敌后组织伪维持会，为日军提供连城至长汀一带的地形情报，协助日军进攻抗日游击队。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d112aadf2e041b1bf68e52f2cd726ae','e1a35025-40ed-4c0d-9f0b-52a8281c9950',1944,'漳平县劣绅','漳平县劣绅，组织伪维持会，配合日军在漳平、龙岩、长汀交界地区进行清乡，迫害抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b23f5e898ec42fdbbd36f912c88a94d','23cd41c1-3235-4ed6-b2f0-43526e284601',1939,'福建籍文化汉奸','福建籍文化汉奸，在沦陷区推行奴化教育，编写亲日教材，培训伪师资，其教育伪化措施影响福建全省，包括龙岩、长汀等地的沦陷区教育。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b41899964986445ca208144a575eb7f2','8fea22d3-31d8-4ccf-9b99-6b5682f413b3',1938,'厦门商界汉奸','厦门商界汉奸，协助日军统制福建物资，为日军采购粮食、矿产，其经济网络覆盖闽西龙岩、长汀等地的物资流通。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8298eef3c3446a6be2dea52e22617f5','d5ec76ad-a601-44c3-ab3c-815228fb1f12',1939,'福建籍新闻汉奸','福建籍新闻汉奸，在沦陷区创办伪报，宣扬“大东亚共荣”，为日军侵略福建各地（包括龙岩、长汀）制造舆论。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0ad8b5153ac4fdbb25135f1f66b69bd','1694ee20-a7dd-4e99-a5e8-28209ad65227',1944,'闽西地方武装头目','闽西地方武装头目，抗战后期投敌，组织伪军配合日军进攻龙岩、长汀抗日根据地，烧杀抢掠，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2faa166dc9a34c219e0f5ace50443cc0','b97f5462-9518-40f7-9785-df7bc3560b7e',1944,'长汀本地人','长汀本地人，投敌后任伪警察局长，协助日军搜捕抗日人士，镇压长汀民众抗日活动，推行保甲连坐。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8794a74d4fdc4bdbaba31465a50b2884','b58ee4e8-801e-443d-bfdf-2db3987b916b',1939,'抗战期间投靠日军','抗战期间投靠日军，参与组织伪贵州省维持会，协助日军推行殖民统治，在贵州地区进行亲日宣传与治安协助。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45222381af5c400ba9ecf2282d7bad3a','5e6c6a73-2df7-467d-87c0-b987cb60c07c',1940,'在贵州伪政权中担任警务职务','在贵州伪政权中担任警务职务，参与镇压抗日活动，协助日军维持占领区治安，迫害抗日人士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a1ce4b41aab4b55875d005a7eccf63f','fcf5f0ee-f132-4c32-8c6b-a1c09627f78e',1941,'在六盘水地区组织伪维持会','在六盘水地区组织伪维持会，为日军征集物资、情报，协助管理地方，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b76b819e5d04c148c60afb5dbdcdf9d','88150b70-17e3-436f-82ec-060b770756ce',1942,'在六枝特区担任伪保甲长','在六枝特区担任伪保甲长，协助日军征粮、派夫，监控当地抗日分子，参与伪政权基层统治。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37eba068964c42688059278f8f5cf088','b6434e72-207b-4e04-a728-bcba8c587e90',1940,'在伪贵州省教育部门任职','在伪贵州省教育部门任职，推行奴化教育，篡改教材，宣传“大东亚共荣圈”，毒害青年思想。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
