INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e0f4e30e67549369995d873f1e973a0','b3e81628-839a-466d-ba75-91f12812f8bf',1932,'曾任伪满安东省（今丹东地区）省长','曾任伪满安东省（今丹东地区）省长，积极推行日伪政策，强征劳工，协助日军清剿抗日游击队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
