INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a21b1b2d85e54c2cb2f194a3a1b9682a','826659c6-ce5f-442d-8526-5d1795109340',1931,'长期为日本殖民统治服务','长期为日本殖民统治服务，组织伪商会，协助日军征粮、募捐，镇压抗日活动，出卖大连地区抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c335f53f14d34f70bcd6ac8a3dd35458','6525035c-f5e5-4520-894d-436670c0381f',1931,'虽非沙河口本地','虽非沙河口本地，但作为伪满高级官员，积极推行日本殖民政策，协助日军控制辽宁地区经济与治安，间接影响大连沙河口。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7552ad5ce98d4f4a8c8f80f031a8b65d','c325edb2-79a9-41ac-9975-96ec274e977a',1932,'参与伪满政权建设','参与伪满政权建设，为日本侵略者出谋划策，在辽宁地区（含大连）推行奴化教育，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
