INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72f162c0ae2240a48c0090b47f639986','25359b66-5d52-484a-b3b9-c5f9200f8767',1931,'虽主要活动于沈阳','虽主要活动于沈阳，但多次到辽阳、太子河地区为伪满政权宣传，参与制定殖民法规，协助日军掠夺当地资源。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d593f1bbc0734e0f899b8ead2ac9e30f','25359b66-5d52-484a-b3b9-c5f9200f8767',1931,'虽主要活动于沈阳','虽主要活动于沈阳，但作为辽宁地区伪政权核心人物，参与制定奴化教育及经济掠夺政策，影响覆盖鞍山、台安。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aebbb6ecb8504a1fad9686609066db72','5dfba81c-6e32-4ca7-9260-0eef441fcef5',1937,'作为日本关东军控制的“次长”制度代表','作为日本关东军控制的“次长”制度代表，实际操纵伪奉天省政务，推行经济统制，镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db1965d10eee440ea756698acc8ecf92','8f2d6212-322b-4ba0-90c2-f361582db8bf',1933,'指挥伪警察配合日军搜捕抗日分子','指挥伪警察配合日军搜捕抗日分子，参与“集团部落”建设，迫害平民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e9eb4cab1ad499aa9ee339b84c60791','49abc18a-21bd-4aa1-a453-a2028a482d48',1932,'为日军开采抚顺煤矿','为日军开采抚顺煤矿，残酷压榨矿工，提供战争资源，并协助日军镇压矿工罢工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef26c1aa9cf741668c69f602ef0752eb','5146fb5c-3ded-4a73-9472-dd2b1ece24d4',1931,'原辽宁省主席','原辽宁省主席，被俘后投敌，出任伪奉天省省长，协助日军维持辽宁沦陷区统治，抚顺在其伪省政权管辖范围内。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c224fa01e3464faa87548d65cf348a10','fb6db493-a160-4407-8de1-931a48e24c2f',1931,'九一八事变后积极附逆','九一八事变后积极附逆，参与伪满建国活动，曾任伪奉天市市长，为日军在辽宁的殖民统治效力。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee0de8b889e844188fa883ab732e778b','f8f95385-eb61-4f64-aed9-cbfb3abaa624',1931,'原东北军军官','原东北军军官，投敌后组织伪军，在辽宁东部包括抚顺周边地区配合日军围剿抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c48eb3462fbc4adf9a9ef6502d933eb6','434b96ec-248a-48be-89fc-0e18998b753f',1931,'在伪奉天省警务系统任职','在伪奉天省警务系统任职，参与镇压辽宁地区抗日活动，抚顺地区伪警察系统受其节制或影响。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb000fd4ab4e47439965679e58afccdf','d95d85cd-d3aa-4d1c-a1db-fc8affa7dbf6',1930,'伪满时期出任抚顺县县长','伪满时期出任抚顺县县长，协助日军管理抚顺煤矿及地方事务，推行保甲连坐，镇压抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd7de43b690b456796099879e214a061','acb1435f-dfc7-4706-95c1-9b7e5e8ac2d6',1930,'在抚顺煤矿为日军和伪满管理中国劳工','在抚顺煤矿为日军和伪满管理中国劳工，参与强制劳动与镇压矿工反抗，属经济领域附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc211d4b70aa411abbb76fd1025826b5','3bcf03d8-74bd-4523-9fbb-0e884182701e',1931,'九一八事变后组织抚顺地方维持会','九一八事变后组织抚顺地方维持会，迎接日军占领，协助建立伪政权，维持地方殖民秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-25ee7729952042ec991bd2a3c3c1acc3','e2afb750-dc6c-4149-8be1-ccf5df8357e5',1930,'在抚顺地区担任伪警务头目','在抚顺地区担任伪警务头目，指挥伪警察配合日军搜捕抗日人员，推行保甲制度。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8b7194151c24ca485a4e6ebf0fe589a','ebf4a191-9a0a-481e-9a43-703214bb309e',1931,'辽宁籍附逆者','辽宁籍附逆者，历任伪满经济部大臣、伪奉天省省长，参与掠夺辽宁资源，抚顺煤矿为其经济统制范围。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3082a549e7394911be65142c642f3a23','ebf4a191-9a0a-481e-9a43-703214bb309e',1931,'在辽宁推行经济统制','在辽宁推行经济统制，掠夺煤炭、粮食等资源，阜新煤矿劳工征调与其政策直接相关。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42c7b7a196234d479dc01678dbdc203a','f7705f79-31d9-4dbe-8601-bda65776b28b',1931,'投敌后历任伪满文教部大臣、伪奉天省省长','投敌后历任伪满文教部大臣、伪奉天省省长，推行奴化教育，其管辖范围包括抚顺地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3984018fd3447e7a5c91f1c99d21fb3','fd87ec05-9380-4110-b855-ca21c977becc',1930,'在伪满协和会及伪奉天省任职','在伪满协和会及伪奉天省任职，参与思想统制与地方控制，影响覆盖抚顺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5074aa432fc4942949029195eaf7f90','473bb26d-9ae5-44cf-a93b-86033d3d211c',1930,'在抚顺地区负责伪协和会工作','在抚顺地区负责伪协和会工作，配合日军进行宣传、劳役征集和民众控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-505d1b954bac4222b39ed36c0dcec60d','67d52e2e-379d-41c1-b085-a1f6bbc97ef0',1930,'统领抚顺煤矿伪警备队','统领抚顺煤矿伪警备队，镇压矿工反抗，协助日军维护矿区殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-075d07283f5c4ce8ab5551ebb0de99ae','a48f9739-1ded-4182-a9f1-fc29c0e0fdb7',1932,'原东北军军官','原东北军军官，投敌后任伪满军职，在辽宁地区多次参与“讨伐”抗日义勇军和抗联，制造多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-337cef11c2d4475babc4d1a6f0ce0dac','184acb29-8dcd-476f-81c1-7c1ac742f372',1932,'原土匪头目','原土匪头目，投日后组建伪军，在宽甸、桓仁、新宾等辽东山区残酷围剿抗日武装，杀害大量民众，有“李剥皮”之称。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6dee1ec9a7274ad69ba2653eae1b7ecf','4da5dd95-9f6c-444a-be91-f401867f2da8',1933,'原东北军军官','原东北军军官，投敌后长期在抚顺、新宾、通化一带追击杨靖宇抗联部队，多次设伏偷袭，是抗联在辽东最凶恶的敌人之一。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4f7399fc8144bc48776be8a5819e757','3ae24484-ac03-4d99-bacc-d280fefcfa95',1931,'原奉系法律界人物','原奉系法律界人物，投日后任伪奉天市长，协助日本关东军建立殖民秩序，参与策划伪满建国，并协助日本掠夺辽宁资源。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0dd84a7e967f47b2affe6bf46b3e2bfe','3ae24484-ac03-4d99-bacc-d280fefcfa95',1931,'曾任伪奉天市市长','曾任伪奉天市市长，积极协助日军建立殖民秩序，参与制定镇压抗日民众的法令，在沈阳及辽中地区推行保甲制度。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0359ab2655844f83973ff7e2bd4be492','3ae24484-ac03-4d99-bacc-d280fefcfa95',1931,'原奉系法律人士','原奉系法律人士，九一八后投敌，曾任伪奉天市市长（管辖辽阳部分区域），协助日本建立伪政权，后任伪满立法院院长，参与制定殖民法律。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b6dcd67fb8147b6aa1aa15ae8c439a8','b7b443f9-e636-4669-884a-8936b9efe4b3',1937,'原奉天省官员','原奉天省官员，投日后历任伪满要职，任伪奉天省长期间强化“保甲制度”，配合日军推行“集家并屯”，切断民众与抗联联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e887c728345849ba915172e44989f488','2f7b2a06-2e82-4d33-b57c-b565979a9602',1932,'在抚顺地区推行日伪统治','在抚顺地区推行日伪统治，协助日军镇压煤矿工人反抗，参与制造“平顶山惨案”后的善后掩盖工作。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89e619dc7a984c72b99675f8db063f62','f4f116e9-def8-4ae3-adb8-c1e0de105723',1932,'在新宾县（当时称兴京县）组织伪县署','在新宾县（当时称兴京县）组织伪县署，配合日军“清乡”，多次率伪警察队袭击抗联游击队，杀害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e46453e4e691418fb5debcad8d9588a5','b149de72-9cba-47e4-8f62-19ff881f4f5f',1933,'在新宾地区建立特务情报网','在新宾地区建立特务情报网，多次破坏抗联地下联络站，亲自审讯并杀害多名抗联战士及支持者。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57c347cdc3fd4f14af4951edcb23c341','b54c68b6-99b7-4600-914b-e8daa7f2e0ff',1932,'组织地方汉奸武装','组织地方汉奸武装，配合日军巡逻抚顺矿区及周边乡村，多次参与搜捕抗联和抗日群众，掠夺民财。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-734adf21df7a45b7b5a3ef54df24618d','93cec35c-5e16-4229-8770-60a57d203530',1934,'原土匪','原土匪，投日后专门在新宾、桓仁一带山区追踪抗联，熟悉地形，多次引导日军突袭抗联密营，造成重大损失。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3294ab440e694dd1a29f5a1a05e3af97','a88e9c78-36d4-4d1f-b077-5bcd99d78c12',1931,'长期在抚顺地区执行“治安肃正”','长期在抚顺地区执行“治安肃正”，抓捕抗日分子，并参与对煤矿工人的奴役管理，克扣口粮。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6aacb14621a47b490b27e0fb219b35a','d631ed81-f047-495b-ae19-12b01d49a759',1935,'利用“协和会”宣传奴化思想','利用“协和会”宣传奴化思想，搜集抗日情报，组织汉奸团体为日军募捐，并参与强迫青年当伪军。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d02c95570eb14491a86c9718e29f5344','27e8ae3b-3711-441f-a243-db7e8145c981',1932,'协助日本资本家管理中国矿工','协助日本资本家管理中国矿工，残酷压榨劳工，迫害反抗者，并配合日军抓捕逃逸矿工。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80c4b159d0d94b36a13abe0a3702c34a','0fa3328d-9369-4d20-bfbf-a29537f2afc2',1932,'任伪抚顺县县长期间','任伪抚顺县县长期间，强征劳工，为日本开采抚顺煤矿提供人力，镇压矿工反抗。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eebffc280b4d41e4b4531124804a96ee','59b28431-fada-4e24-a0ec-6b364647c6b8',1933,'指挥伪警察抓捕抗日分子','指挥伪警察抓捕抗日分子，协助日军实施“归屯并户”，制造无人区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-315e63ed824f4fb5aeb9afea89f4820a','492c9d84-fd9a-4cea-914d-c2943dfad1f3',1932,'率伪保安队配合日军扫荡新抚地区抗日游击队','率伪保安队配合日军扫荡新抚地区抗日游击队，杀害多名抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a75b6490b9ea439ba783a4fc19bdae1d','92e3d352-7fc9-4936-9f27-06989ab6ae55',1931,'组织地方维持会','组织地方维持会，为日军提供粮草情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6254778234184538b881148b224aad1c','717822fe-5d5a-40bf-854d-515c43b5b7d0',1933,'为日本宪兵队充当翻译','为日本宪兵队充当翻译，参与审讯和迫害抗日志士，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a18deab3797b4047bdf09bf8f153c42c','5ebc24c1-ef93-47f3-ac90-167ae411bdcf',1932,'虽主要活动于伪满中央','虽主要活动于伪满中央，但早年参与辽宁地区伪政权筹建，推动“满洲独立”。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27c78fe94cc049b0a0eaa2e14e7a2e9b','460591f0-8df7-4a8c-9b34-5389955ee794',1932,'推行日本奴化教育','推行日本奴化教育，在抚顺新抚地区学校强制灌输“日满亲善”，篡改历史教材。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78bd83443ed4456a8e7750d5280a64ae','460591f0-8df7-4a8c-9b34-5389955ee794',1932,'推行奴化教育','推行奴化教育，强制学校教授日语，篡改历史。','危害等级B（乙级，市县厅局级）','hanjian');
