INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d47d7b4ad5e14dcbbaa0eacbdadafe7a','460591f0-8df7-4a8c-9b34-5389955ee794',1932,'原辽宁教育界人士','原辽宁教育界人士，投敌后任伪奉天省教育厅长，在鞍山、海城等地推行奴化教育，强制学校使用日语教材，灌输“日满亲善”思想。','危害等级B（乙级，市县厅局级）','hanjian');
