INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4fa55fddea54f638c3ef8474aa96bd1','a1089097-8030-4b61-876c-5f380bfd6d7f',1933,'原奉系军阀','原奉系军阀，后投敌，在抚顺及周边地区协助日军围剿抗日义勇军，残害百姓。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b01d9681e9e4f28ba51ac8679942c95','587f4d71-5ad5-4214-b882-10145c73cec7',1932,'作为伪满高层','作为伪满高层，推动在抚顺地区实施“治安肃正”，支持日军对望花煤矿区的军事管制。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-510171cc7065437bba12483ad1ba8409','b90e586b-8437-4b4d-9cbb-a6dba182130d',1937,'日本关东军扶植的汉奸','日本关东军扶植的汉奸，在抚顺地区推行经济统制，强占煤矿资源，压迫矿工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
