INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d82c6cdd519a4474b9854738b8148d80','88975bfa-3c43-4b75-9102-58d23aeb22fe',1932,'组织汉奸武装','组织汉奸武装，在望花一带抓捕抗日志士，多次配合日军进行“扫荡”，杀害无辜群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0409f7955e224c9bbecb084411974ae9','3020df56-9050-41ed-a5ee-11a1bb66c9a3',1931,'原东北军将领','原东北军将领，1931年投降日军，在辽宁地区协助日军围剿抗日武装，后任伪热河省省长，参与“讨伐”抗日联军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f09dc632b6b48dfbbae54bc8cb79301','b955a949-0088-4640-b149-e50d137ccdf9',1932,'在抚顺、清原地区组织伪警察和特务','在抚顺、清原地区组织伪警察和特务，多次参与“讨伐”杨靖宇领导的抗日联军，制造多起屠杀平民事件。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e4fce9ac85e45baacae1880b1bfa06a','b955a949-0088-4640-b149-e50d137ccdf9',1932,'原奉天省警察头目','原奉天省警察头目，投日后任伪警务厅长，在本溪平山地区建立特务网络，抓捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
