INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7fcf6f4b52a4bb48528ffc8d3cf3dc8','1266f219-9cf7-44a3-a3f1-0a32cb352642',1933,'投日后任朝阳县伪县长','投日后任朝阳县伪县长，强征粮税，强迫民众修路筑堡，为日军提供情报，镇压当地抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62ebdcc4d01b436cbf11f8b5850a9c0f','0fbf6bc8-cea6-4ac3-944b-0109bef3f2e2',1933,'组织维持会','组织维持会，协助日军建立伪政权，搜刮民财，出卖抗日人员，导致多名地下党员被捕牺牲。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b99608a1ca5b41bbaa39527c30a99ae5','2bd08c3a-db44-4ae4-bf61-31c42f706f41',1933,'1933年一度接受伪职','1933年一度接受伪职，在热河朝阳地区与日军合作，后反正，但期间曾协助日军镇压义勇军。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f62941213b94a37913585f4ede31fb9','294f95af-7a47-4f6e-aa9f-de23ffd7f397',1933,'原土匪头目','原土匪头目，投日后在朝阳、龙城一带驻防，多次率伪军袭击抗日武装，烧毁村庄，屠杀平民。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57fefcf0c8d34a6fac69f30ac0360648','5aaaa5bc-7dd3-4ff6-bc71-fafc3e745e24',1935,'负责朝阳地区特务工作','负责朝阳地区特务工作，建立情报网，抓捕抗日分子，参与“三光”政策实施。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-677c0b21a812455d87de454b36b755ba','6f3513bb-2e13-4241-b232-564fcc07b095',1937,'率领伪保安队配合日军扫荡','率领伪保安队配合日军扫荡，在龙城周边多次屠杀抗日群众，抢掠财物，民愤极大。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70a54d9adf0c44c49309d008cf465126','b55237e1-cbc3-40d2-b8ce-c0c7487eb842',1931,'原东北军旅长','原东北军旅长，叛国投敌，率伪军在本溪、抚顺等地围剿抗联和抗日义勇军，制造多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90fd7c8262f240e1905fc4acdf8a42a9','2a4ac3df-7f2e-4f6d-8dd5-b4472ae58f9a',1931,'负责本溪地区伪警宪特系统','负责本溪地区伪警宪特系统，抓捕抗日志士，协助日本宪兵队镇压本溪湖煤矿工人罢工和抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8a45973b4a64c49b713cc33619613ce','2a4ac3df-7f2e-4f6d-8dd5-b4472ae58f9a',1931,'负责伪奉天省警察系统','负责伪奉天省警察系统，在沈阳及辽中地区大肆搜捕抗日分子，破坏地下组织，执行日军“治安肃正”计划。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1eaf3831a9a40ffb2188dbf1cb0986b','2a4ac3df-7f2e-4f6d-8dd5-b4472ae58f9a',1931,'原奉天警察头目','原奉天警察头目，投日后任伪奉天省警务厅长，指挥警察特务大肆搜捕抗日分子，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b81d8797c1d3462e963b3b8dd4def1f0','e35f8b37-9e6f-4712-8c3e-f0ab4130cab6',1937,'任伪市长期间','任伪市长期间，强征劳工，推行保甲制度，配合日军“讨伐”本溪山区抗联部队，掠夺当地资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5197f851452461db2d027fad4024558','9a38a8ff-23ed-4b25-95a6-eee8f60e2753',1932,'原奉系法律人士','原奉系法律人士，投日后参与伪满政权建设，支持本溪地区殖民统治和“治安肃正”政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f46feffe56fd4bd28def2aa7246c8605','6af62a9c-ee3f-4f74-b54b-1fbb9a5c7167',1933,'直接指挥本溪地区伪警察','直接指挥本溪地区伪警察，搜捕地下党员和抗联交通员，参与“集团部落”建设，迫害百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df4084f6f74b4e7caf7fb01d9dde9be9','f2672828-c22d-417e-bcc4-9c6bcd370d00',1935,'推行日伪“粮谷出荷”政策','推行日伪“粮谷出荷”政策，强征本溪农民粮食，协助日军烧毁抗联密营，杀害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f6a70db79144b04bb8a0c352ae1e797','45162872-1083-44f8-8035-8a14698cf28b',1935,'作为伪满最高行政头目','作为伪满最高行政头目，签署多项针对本溪等地的“讨伐”和“移民”法令，支持日军镇压抗联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffe6c4bcb0434f219777061a346d37a2','dde9c706-b382-45e4-a96f-8053f510e3e4',1932,'原辽宁省政府主席','原辽宁省政府主席，投敌后长期主政奉天省，配合日军在本溪推行“治安强化运动”，围剿抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a6ead7330144da2832dfd54658aab5d','ab527b7c-9dfe-4e61-9f03-7ca52efec620',1932,'早年参与本溪湖铁矿管理','早年参与本溪湖铁矿管理，投日后协助日本满铁控制本溪煤铁，为日军军工提供资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-350b1dbf6f31438cb3bcb79023312051','b1fad3ac-772f-4adb-b16c-ce01806b1a6d',1935,'充当日军宪兵队翻译','充当日军宪兵队翻译，参与刑讯逼供抗日志士，指认抗联人员，导致多人牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9af971591a714497bd3abfaac4a26f4e','b1fad3ac-772f-4adb-b16c-ce01806b1a6d',1935,'为日本宪兵队充当翻译','为日本宪兵队充当翻译，参与刑讯逼供，直接迫害平山地区抗日地下工作者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9542f64155dc4d3184f4cd738305fb7b','b1fad3ac-772f-4adb-b16c-ce01806b1a6d',1935,'本溪湖本地人','本溪湖本地人，为日军宪兵队担任翻译，参与审讯和刑讯抗日志士，多次带领日军搜查溪湖地区的地下抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8fc9430901164a8eae4003b838667398','6f4148d1-80c4-4f52-b8d7-edaa2817cd3f',1934,'组织协和会宣传奴化思想','组织协和会宣传奴化思想，监视民众，向日军报告抗联活动，协助“清乡”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71598a512b85413f8bc1584cd2c1a93b','0d00a1de-5cf9-402a-af10-35b3a5c93f36',1936,'积极推行“日满亲善”宣传','积极推行“日满亲善”宣传，组织汉奸团体，为日军提供本溪山区抗联情报，破坏地下组织。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6e3b9742e394639a96c93fd26335f07','70e2a4f3-b6ff-4854-b734-5bf0eae71aba',1937,'主管伪满劳工政策','主管伪满劳工政策，从本溪强征数万劳工下井采煤，致大量劳工死亡，被称“血煤”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23b28955000845bfa2cca7739402f7fb','26c2eb2e-b6ed-4f42-8671-92a84b7d621e',1932,'作为伪满经济要员','作为伪满经济要员，直接参与本溪湖煤铁公司经营，为日军生产军需钢铁，压榨中国矿工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b92162b988ad4cd7986ce4d3ac186b94','81179334-8d2a-448b-a2a3-a5cde02f630d',1935,'负责本溪地区铁路运输','负责本溪地区铁路运输，保障日军军事物资和掠夺资源运输，协助“讨伐”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd5ab92ddca9426a9e20b3128840f94f','b0aac145-6dec-4f25-8c9e-5c4aacdbca43',1932,'建立伪满司法体系','建立伪满司法体系，在本溪地区审判抗日人士，以“反满抗日”罪名判处多人死刑或劳役。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0315de4344004efcaa11112b678329a1','113b2e16-15dd-4125-8d58-40527f7190e9',1931,'九一八事变后投敌','九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，其部队曾在本溪、南芬一带活动，协助日军围剿抗联部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc6d890254b545a59d96c6dba74665ca','113b2e16-15dd-4125-8d58-40527f7190e9',1931,'原东北军将领','原东北军将领，1931年九一八事变后投敌，在辽宁西部及铁岭、开原一带协助日军镇压抗日武装，后任伪满热河省省长，积极推行日伪殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e87619e8d93e428face45105f1351da7','113b2e16-15dd-4125-8d58-40527f7190e9',1931,'原东北军将领','原东北军将领，九一八后投敌，在辽宁西部及热河地区协助日军镇压抗日武装，后任伪满要职，参与“治安肃正”行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7112d1539af1468bbd099bab6d5652aa','113b2e16-15dd-4125-8d58-40527f7190e9',1931,'原东北军将领','原东北军将领，九一八后投敌，曾任伪满要职，参与镇压抗日武装，其势力范围曾涉及黑龙江东部地区，包括七台河一带的讨伐行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1698107e4a8a47bb976636de90d51d1f','113b2e16-15dd-4125-8d58-40527f7190e9',1931,'原东北军将领','原东北军将领，1931年九一八事变后投敌，曾任伪满热河省省长，后调任伪满第七军管区司令，在黑龙江地区协助日军镇压抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a36371a2199349fc86fe86aa3073a651','fcae2a68-dde5-42c8-9098-3c74505ca6bd',1931,'原奉天省警察头目','原奉天省警察头目，投日后任伪满奉天省警察厅厅长，直接指挥本溪、南芬地区的伪警察和特务，搜捕抗日分子，破坏地下组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2db9cafddc8541698c0ee3ddd57ac881','fcae2a68-dde5-42c8-9098-3c74505ca6bd',1931,'原奉系警察头目','原奉系警察头目，投日后任伪奉天省警察厅厅长，在沈阳及铁岭、昌图地区大肆搜捕抗日分子，镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00552a18900e4c3da7e0b9bd70bc9370','23f8a03c-f740-4a0a-99cb-c75731368aad',1932,'伪满时期长期担任本溪湖市市长','伪满时期长期担任本溪湖市市长，推行日伪殖民政策，强征劳工，为日军提供铁矿资源，协助镇压南芬矿区工人反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da4e30c3dffb4edeaa2c8bf8c681a6af','b6db825c-93b0-4d88-86f5-61b59c7c668d',1933,'在本溪、南芬地区任伪警察署长','在本溪、南芬地区任伪警察署长，多次率伪警配合日军“讨伐”抗联，抓捕并杀害抗日群众，制造多起惨案。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-094060a8a44e436189666c7b1cbcf265','5ca6a4aa-4ff1-4b57-8272-f8b0b93d2483',1931,'原辽宁省政府主席','原辽宁省政府主席，投敌后任伪满奉天省省长，管辖本溪、南芬地区，积极推行日伪“治安强化运动”，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0328ee7eb594d2d8c0eebddff73ab53','5ca6a4aa-4ff1-4b57-8272-f8b0b93d2483',1931,'原辽宁省主席','原辽宁省主席，投敌后任伪奉天省省长，管辖本溪地区，积极推行日伪殖民统治，支持日军在本溪湖设立宪兵队和特务机关。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b12f7740ae74a9b9b7a92e0bfb43b3e','5ca6a4aa-4ff1-4b57-8272-f8b0b93d2483',1931,'原奉天省主席','原奉天省主席，投日后任伪奉天省长，曾多次到葫芦岛、南票视察，督促加强“治安”和资源开发。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15c50bb82a4e4577b6d28c5b6f94f383','5ca6a4aa-4ff1-4b57-8272-f8b0b93d2483',1931,'原辽宁省政府主席','原辽宁省政府主席，投日后任伪奉天省省长，管辖包括鞍山、岫岩在内的地区，推行日伪殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e099e73160a4553ba894d457020a249','7d90382a-12a1-4534-af0b-419755edef49',1931,'曾任伪奉天市长','曾任伪奉天市长，参与制定针对辽宁东部山区的“讨伐”计划，其政策直接影响本溪、南芬地区的抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-849fffebbd7c4631908a4ec25822e93c','36e3e7ad-9be0-44a1-9340-fad67966395f',1932,'负责伪满奉天省警察系统','负责伪满奉天省警察系统，多次组织对本溪、南芬山区抗联密营的突袭，抓捕抗联交通员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98f057fd3f6144aeb00b03cbdd8b32fa','053a760c-1b19-4003-a946-7e1c090e04bd',1933,'作为日伪在本地矿业代理人','作为日伪在本地矿业代理人，残酷压榨南芬铁矿工人，向日军提供战略物资，并协助日军镇压矿工罢工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-451f6342833d4a728a2fc552e326782d','e474d36b-a94c-43ca-8b61-0ed8e0b32ab0',1934,'任伪本溪县县长期间','任伪本溪县县长期间，推行“归屯并户”，制造无人区，切断抗联与群众联系，多次率县伪军配合日军扫荡南芬山区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e84f941b75944441b48c307aa736ff4f','a6adb3d4-d2ba-48d7-9472-b092ef7e020a',1935,'直接驻守南芬地区','直接驻守南芬地区，负责监视矿区工人和周边村民，多次告密导致抗联地下联络点被破坏，参与杀害多名抗日志士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a89dc6387ea456cb51b2168f4f8acad','51ec7af5-4e61-4e74-a958-e4f9b576771e',1932,'率保安队在本溪、南芬一带巡逻','率保安队在本溪、南芬一带巡逻，协助日军“清乡”，抓捕抗联伤员和群众，烧毁村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e40171b917645f98f212b553fbe31aa','b4bf024d-fb15-4ba0-992b-881e1419c267',1936,'利用协和会组织','利用协和会组织，在南芬矿区进行奴化宣传，诱骗青年加入伪军，收集抗日情报。','危害等级A（甲级，省部级/大军区级要员）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60ea4b11e550431d8bc01ba4a5ca6b7c','3de76d7c-4db5-4b86-ac6a-24212317cd10',1937,'为日军宪兵队担任翻译','为日军宪兵队担任翻译，参与审讯和刑讯抗日志士，直接导致多名抗联战士牺牲于本溪监狱。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2b34797b22547099baf3ad2bd6d1f6d','5cafb637-3e99-4200-a302-33976b2b5946',1933,'原为抗日武装成员','原为抗日武装成员，后叛变投敌，熟悉抗联活动规律，带领日伪军多次突袭南芬山区抗联营地。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-731f9b5079b541c3be7c4c827114e177','3fb120b1-5667-4903-9186-0458b5071cf0',1932,'原东北军旅长','原东北军旅长，叛国投敌，任伪满第一军管区司令，管辖包括本溪在内的辽宁中东部地区，多次组织“讨伐”抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02e4bfb68a6f4baca66608e50b601627','6d5852ae-118d-4196-8640-2932f144721d',1932,'本溪本地汉奸','本溪本地汉奸，充当日军走狗，在平山地区残酷镇压矿工和抗日群众，制造多起血案。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-893d940341324d1eb0415e902bc01ccc','6d5852ae-118d-4196-8640-2932f144721d',1932,'本溪湖（今溪湖）本地人','本溪湖（今溪湖）本地人，投靠日军后任伪本溪湖警察署署长，积极抓捕抗联战士和爱国群众，多次带队袭击溪湖周边的抗联据点。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8a670ebb5f74ddb8d126da51dea9014','d243d880-2831-497f-b1b7-53d47414b59d',1933,'投靠日伪','投靠日伪，任本溪县县长，推行保甲制度，强征劳工，协助日军掠夺本溪煤炭资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ff5ebe913c04c84bd4229e1c85c7d20','23eb0e43-72e1-464a-be9b-174f68a5c0af',1931,'汉奸买办','汉奸买办，为日军管理本溪煤铁公司，残酷压榨中国矿工，导致大量劳工死亡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b28fc11e6b8426f99c377e08f0cc245','34689642-5d7c-4ff5-9234-417a32afe87c',1932,'原东北军军官','原东北军军官，投敌后负责奉天省（含本溪地区）保安事务，协助日军清乡，杀害抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-742cbaeff53e47d79a357cafba022977','04b1915f-c6c2-459e-acb4-49ae683b677e',1932,'九一八事变后投靠日本','九一八事变后投靠日本，参与掠夺本溪湖煤铁资源，为日军侵华提供物资支持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db27f7ae3dbb413493bc6e525d1422ff','c3be2cb1-c24c-4506-85b6-58c953360842',1931,'九一八事变后组织伪维持会','九一八事变后组织伪维持会，协助日军接管本溪湖地区，维持殖民统治秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec2b112ac8c94ef6a8c4cdf8ac974636','b57892ab-434d-485d-a1be-c1761806bca6',1932,'任伪县长期间推行保甲制度','任伪县长期间推行保甲制度，配合日军清剿抗日武装，强征劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8ef4bc6a3104161bd30fddec02c368b','8593552e-4074-44d8-a494-586e58eacf23',1933,'指挥伪警察配合日军讨伐抗日联军','指挥伪警察配合日军讨伐抗日联军，镇压本溪地区抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d43cb6c58be478a8e23f00e85ee1bf7','07d64de8-aae9-4784-be1d-14e946c6255b',1936,'通过协和会进行奴化宣传','通过协和会进行奴化宣传，协助日军征集物资和劳工，监控民众思想。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7182ec1e086d4860a633ba1b23fb01c7','499921d0-380d-4aaf-be16-7ccc685e8bdf',1934,'管理本溪湖街行政事务','管理本溪湖街行政事务，配合日军实施经济管制和物资统制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36b71a01ac734862b590e0464f82a827','7549c670-c790-44c6-a4ae-9dd73467ad76',1932,'率领伪保安团参与日军对本溪周边抗日游击区的扫荡','率领伪保安团参与日军对本溪周边抗日游击区的扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-343cc8d9f1474a34b60a88f0a70abe1a','5a0e3f16-7448-4a9e-be93-3f89a88fef05',1935,'充当日军监工','充当日军监工，残酷压迫矿工，导致大量劳工死亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68217e3f0f3f4d32b9908681575c3499','65a8361c-f453-4208-b208-5198fa8166b8',1937,'负责协和会日常事务','负责协和会日常事务，组织亲日宣传活动，协助日军征召劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64058001974a45aa8f1e09ac78cc3d9c','9a03751e-86db-40a0-bab8-4b246a7ce950',1935,'参与抓捕抗日人员','参与抓捕抗日人员，破坏本溪地区中共地下组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-121be00800c54b8e9a0810d97c2389c1','a21842e7-1e9b-4d31-93be-0e1a825661de',1932,'原奉系警察头目','原奉系警察头目，投日后任伪满奉天省警察厅长，在辽宁各地包括本溪、桓仁建立特务网络，搜捕抗日分子，破坏地下组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45b3e2e977664800aa5e3742f66605c6','08e02735-77fc-4a64-8285-c1906bc146e2',1932,'桓仁本地人','桓仁本地人，投日后任伪桓仁县县长，推行保甲制度，强征劳工，配合日军对桓仁山区抗联根据地进行经济封锁和军事清剿。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e791f732a31849809002d8bd3d625709','dd4aa9c9-8e2d-496f-9d20-d6c2a70b82b3',1935,'任伪本溪湖市市长期间','任伪本溪湖市市长期间，积极为日军提供铁矿资源，强征中国劳工，镇压本溪湖煤矿工人罢工，并协助日军围剿本溪周边抗联部队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c68dbc1456674b4e8551319920da4982','05c153a2-139b-4889-a097-c7055b31f681',1933,'本溪县汉奸','本溪县汉奸，负责指挥伪警察和特务，多次带队袭击抗联小分队，抓捕并杀害抗日群众，在桓仁与本溪交界地区活动频繁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41852e8afc5d40d3b014519fa10e51b2','d517dd95-d7a3-4584-8c28-da3047a79e0a',1934,'桓仁县伪警察头目','桓仁县伪警察头目，参与制造多起屠杀事件，如“老秃顶子”惨案，协助日军放火烧山，围剿杨靖宇领导的抗联第一军。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2dda0464a8f46faa6ca9ceab310d345','8cbbc474-7db5-48dc-b457-65ae729b0d8b',1936,'本溪湖煤矿汉奸','本溪湖煤矿汉奸，管理矿警队，残酷镇压矿工反抗，向日军提供抗联活动情报，并参与抓捕逃往桓仁山区的抗日矿工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92a36c88db8740ddb91ef2ffc6d33ff2','b8f6f5a8-2b54-4905-9626-184c7acd3be4',1937,'原地方士绅','原地方士绅，投日后任桓仁县协和会会长，宣传“日满亲善”，组织汉奸团体，协助日军推行“归屯并户”，切断抗联与百姓联系。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea4bcdef39ac4a64ba4edfa29aaef4e2','cedfe32e-6a53-4d63-b3e9-3d986fac9525',1932,'本溪县地方武装头目','本溪县地方武装头目，投日后任保安队长，多次配合日军扫荡本溪、桓仁交界山区，杀害抗联伤员和百姓，抢夺粮食。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b61cfe9d1da949279d932c70711622f9','64f7407b-efb0-4775-aee9-02d8b1ef696f',1938,'朝鲜族汉奸','朝鲜族汉奸，为日军充当翻译和宣抚员，在桓仁农村诱骗群众“归顺”，出卖抗联秘密联络点，导致多名地下党员被捕。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ce84dc94dc942e2beb6eb8c83892d0f','94e651f9-5494-4b12-b0d5-c6fc36e1cf0c',1937,'本溪湖宪兵队汉奸翻译','本溪湖宪兵队汉奸翻译，参与刑讯逼供抗日志士，直接导致抗联侦察员牺牲，并协助日军在桓仁地区进行“大讨伐”。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ae05ecacddd47aeb7526101af3c3240','e8fc11ba-6e6e-4486-a6fc-0306a24e97b8',1931,'原东北军将领','原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，其部队曾在本溪、溪湖一带协助日军清剿抗联部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-404ca33c3c9a49208df231c470e4c51f','e8fc11ba-6e6e-4486-a6fc-0306a24e97b8',1931,'原东北军将领','原东北军将领，九一八事变后投敌，在辽宁西部及热河地区协助日军镇压抗日武装，后任伪满高官，曾参与围剿辽西义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6fa6be208f69415fbc94f28b67c82daf','07ca8c36-881d-40d8-aac6-f63b4e014cce',1933,'任伪本溪县县长期间','任伪本溪县县长期间，推行日伪“保甲连坐”制度，强征劳工用于本溪湖铁矿和煤矿，配合日军“讨伐”溪湖山区抗联部队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-526eac7a79b948d1905fff5c9edc2859','814f200a-6447-4674-bb6f-3e76c0b385e0',1931,'负责本溪湖煤铁公司（溪湖地区）的劳工管理','负责本溪湖煤铁公司（溪湖地区）的劳工管理，残酷压榨中国矿工，大量劳工因虐待致死，并协助日军将矿工充当劳役修筑军事工事。','危害等级A（甲级，省部级/大军区级要员）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54c9c99d5de040a19529f1a1e0031526','b3f8d5e5-250f-42ba-b61a-576429629ce7',1933,'率伪保安队配合日军在本溪、溪湖山区“扫荡”','率伪保安队配合日军在本溪、溪湖山区“扫荡”，杀害抗联伤员和百姓，烧毁村庄，是当地民愤极大的汉奸武装头目。','危害等级C（丙级，基层头目）','hanjian');
