INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b71c55345f842a792fb621e8deda753','91541acb-9c1c-41ab-9630-aabadd0cc2a3',1931,'原奉系将领','原奉系将领，九一八事变后投敌，历任伪满军政要职，在沈阳地区协助日军清剿抗日武装，推行奴化教育。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a85eceb3a1c6496cae2767b4e3779774','91541acb-9c1c-41ab-9630-aabadd0cc2a3',1931,'虽为省级以上汉奸','虽为省级以上汉奸，但曾在辽阳、太子河地区部署伪军，配合日军扫荡抗日游击队，并推行奴化教育。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cce5a5c3e8594545b100be2ac5e12808','91541acb-9c1c-41ab-9630-aabadd0cc2a3',1931,'原奉系军阀','原奉系军阀，九一八后投敌，曾任伪奉天省省长，后任伪满国务总理，对包括鞍山、海城在内的辽宁地区负有全面殖民统治责任。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4b47577346e479c83431f1389112f17','5a9c3af8-9eaf-4822-a795-3e30c9dae91e',1931,'九一八事变时被日军扣押后投降','九一八事变时被日军扣押后投降，出任伪奉天省长，配合日军实施经济掠夺和治安镇压，对辽中地区抗日活动进行破坏。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8891f0f7dc44719863720518ac33a4e','c8243e9f-9077-442b-ac78-a26c0ba98a6d',1932,'在辽中县任伪县长期间','在辽中县任伪县长期间，配合日军“清乡”行动，抓捕抗日志士，强征劳工，推行“归屯并户”政策。','危害等级C（丙级，基层头目）','hanjian');
