INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a62354abdf26446680cfbe6024d458e0','855da4af-1617-4628-909b-42415cb668e0',1931,'原奉系军阀','原奉系军阀，九一八事变后投日，在辽中地区协助日军镇压义勇军，后任伪省长，继续为日军效力。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a39cc3ee271e4752b9a8e7c7b5e06dcd','e1117599-fc00-4aa8-ae44-6725341debc8',1931,'早年留学日本','早年留学日本，九一八事变后充当日军顾问，参与策划伪满政权建立，对辽宁地区殖民统治有重要影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-831f266ba8f740a5b1dd60298436ec9f','a412cec1-4384-4827-8e72-5b2f41e60c7e',1932,'协助日军掠夺辽宁地区矿产资源','协助日军掠夺辽宁地区矿产资源，在辽中地区强征土地和粮食，支持日本侵略战争经济需求。','危害等级B（乙级，市县厅局级）','hanjian');
