INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d85b16cb52814e4282dad68d5fe99b28','a51187ab-74b8-468d-bd8f-bf52b8524a5f',1933,'推行奴化教育','推行奴化教育，强制学校教授日语和“王道”思想，禁止中国历史课程，迫害爱国教师。','危害等级B（乙级，市县厅局级）','hanjian');
