INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3b52615d9944f63a6347604e7f8307a','b07a55a2-cf40-4147-bd96-f0b719dbc58f',1931,'原东北军将领','原东北军将领，投日后任伪奉天省省长，管辖范围包括今沈阳、盘锦等辽宁中南部地区，积极推行日伪殖民政策，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ad3d10004284a04a953d9bdc1f9a540','31d74570-ba02-4ba9-b542-d00f350715e6',1931,'原奉系官员','原奉系官员，投日后历任伪奉天省省长等职，管辖辽宁大部，包括盘锦地区，协助日军征粮、抓劳工，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-270ca5054f3241329610f6953e036bfa','58031ba9-91d3-4e8c-aee2-0ddea7500ed6',1934,'伪锦州省省长','伪锦州省省长，管辖范围包括今盘锦西部及兴隆台周边地区，积极推行日伪“治安肃正”，参与屠杀抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ac72547770940acb579c5ae3d32bbc8','a92af0a8-75a4-4850-ab32-2ea2544be7b7',1931,'伪奉天省警务厅长','伪奉天省警务厅长，负责辽宁地区警察特务系统，在盘锦、兴隆台一带设立伪警察所，搜捕抗日分子。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2cb8d60de2574ea6a7da66685f6cf7b3','a880ebb3-9d11-4300-9145-c0c0bf202f58',1932,'原土匪头目','原土匪头目，投日后任伪军旅长，长期盘踞盘山（今盘锦）地区，配合日军“讨伐”抗日义勇军，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-226afe28e3fc44499036bae7922a7a7f','14c63497-0b94-49dd-a7d8-8cff18617a01',1932,'原为地方警察头目','原为地方警察头目，投日后任伪锦州省警务厅长，管辖盘锦、双台子地区，多次组织围剿抗日义勇军，抓捕抗日志士','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6356e8e1a47245198606e5ba17d4bae5','c43dbedf-5cda-4f30-a985-2167f00b5898',1933,'任伪盘山县县长期间','任伪盘山县县长期间，强征民夫修建日军据点，推行保甲制度，强迫百姓献粮献铁，镇压当地抗日活动','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ebb607ddf7841358bb7105286f49225','652eaaa9-30ba-4cd4-b5d7-a5982ca17f2e',1932,'虽主要活动于奉天（沈阳）','虽主要活动于奉天（沈阳），但曾多次到盘锦、双台子地区审理“反满抗日”案件，判处多名抗日分子死刑','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c1b832eee3541ddb8d65242b5e51425','29476076-4823-4e06-b8d9-66a06d3c1029',1931,'曾参与策划辽南地区“自治”运动','曾参与策划辽南地区“自治”运动，在盘锦、双台子一带煽动地方势力归顺日本，为日军侵略提供情报','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef5c45ac712547d29c088b70efc103ce','f4374fc7-5764-4de7-bc9b-a3c9cd30a45f',1934,'管辖盘锦、双台子地区','管辖盘锦、双台子地区，积极推行“治安肃正”计划，组织伪警察和自卫团，多次袭击抗日游击队','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cff4f8c2817447b0a6e06bb2d079d3a0','9e9b3a30-b2cf-4354-bdb7-64c43f40e201',1932,'曾参与制定伪满法律','曾参与制定伪满法律，在盘锦、双台子地区设立“矫正院”，关押迫害抗日群众，实施奴化教育','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fbc6fb1586a49dc92e03ac8347873f9','9e9b3a30-b2cf-4354-bdb7-64c43f40e201',1932,'原东北军法务官员','原东北军法务官员，投日后任伪满司法大臣，制定镇压抗联的法律。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e57a3f9d68ef45dbbbb8bb95d34bb21f','449b5efc-da58-4d23-bdc2-98e4bfcd5766',1938,'直接负责盘锦、双台子地区治安','直接负责盘锦、双台子地区治安，抓捕抗日地下党员，严刑逼供，曾一次逮捕并杀害多名抗日群众','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-790c570606094fbbaecc4bb8e383d91f','05f7efa4-a2c0-4968-aab6-0b7fdd6a2fc2',1940,'在双台子地区设立多个检查站','在双台子地区设立多个检查站，盘查过往行人，搜捕抗日分子，并协助日军强征劳工','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a415298c6cbd4986a1f39a2b4b3439b2','9fabbd94-35dd-49de-be0c-e4b1a391f95a',1937,'曾到盘锦、双台子地区推行“国民储蓄”和“勤劳奉仕”制度','曾到盘锦、双台子地区推行“国民储蓄”和“勤劳奉仕”制度，强迫百姓无偿劳动，为日军服务','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a88108964c3421fbf170a893602c191','b6b81a4a-8533-422a-b6fb-d52d6e2555d8',1931,'原为东北军将领','原为东北军将领，九一八事变后投敌，曾任伪满热河省省长，协助日军镇压抗日武装，在辽宁西部及盘锦、大洼一带活动，参与围剿义勇军和抗联部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-406c7a4a3b844a87a7648c63b372a338','b6b81a4a-8533-422a-b6fb-d52d6e2555d8',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，率伪军配合日军进攻黑龙江，参与江桥战役对抗马占山抗日部队，后任伪满洲国热河省省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-803c501e4dfb4095a9dc382353f6e3c3','eb2e2c73-f94f-41eb-b271-520eae50646c',1931,'原东北军旅长','原东北军旅长，叛变投日后任伪奉天省省长，管辖范围包括今盘锦、大洼地区，积极推行日伪殖民政策，强征劳工，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9fce98760d941f8b68f43ea68b3b2c9','f552b2db-2a4d-4a2d-ab50-cd2016ed9855',1932,'原为地方士绅','原为地方士绅，投靠日军后任伪锦州省省长，其辖区涵盖盘锦、大洼一带，协助日军建立保甲制度，搜刮民财，迫害抗日家属。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04c533a87d3a40dbae07d53ed12824e4','a849a099-9ae2-4115-8e9b-b0e2310bc667',1931,'早年留学日本','早年留学日本，九一八后积极参与伪满建国，曾任伪奉天市市长，对盘锦、大洼地区日伪统治有间接管辖，推动奴化教育和经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb3e7d1fec0241478ebda4d42997f49c','a849a099-9ae2-4115-8e9b-b0e2310bc667',1931,'辽宁沈阳人','辽宁沈阳人，九一八事变后投敌，历任伪奉天市市长、伪立法院院长等职，参与伪满政权立法与地方统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-803c674452a843cbb41b394154b9b530','e7bcb11e-a546-4510-b9c8-ab807b337e07',1931,'原东北军参谋长','原东北军参谋长，投敌后任伪奉天省省长，在盘锦、大洼地区设立日伪警察机构，抓捕抗日志士，强征土地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c443a6f1596f497dbf850b95b4d88bf3','e7bcb11e-a546-4510-b9c8-ab807b337e07',1931,'原奉天省主席','原奉天省主席，投日后任伪省长，在营口地区推行“归屯并户”，制造无人区，导致大量平民死亡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c94a9b16a66341f2a327591eff2151cb','8ab6c5eb-21d0-4fda-b9d6-5a2cf35c6acb',1932,'原为土匪头目','原为土匪头目，投日后任伪锦州省警务厅厅长，直接管辖盘锦、大洼地区警察，率伪警配合日军扫荡，杀害无辜百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6dda1452570e46e39ac80ea4c41e143e','12501891-0b45-4a20-9844-421ec75b2eb0',1932,'投靠日军后任伪盘山县县长','投靠日军后任伪盘山县县长，在任期间强制推行“归屯并户”，焚烧民房，制造无人区，并强征农民充当苦力。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4962b25baaf44e18a357d14117b8e793','69b1c786-5293-4924-b2f6-99804b810207',NULL,'不列入','不列入，因未投敌。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0dddfef27de34c699f9b3e3dbf2244e9','f860a788-e2c5-428f-8f08-e8a0212ba2a7',1932,'盘山县人','盘山县人，曾任伪满奉天省警务厅厅长，在盘锦地区推行保甲制度，抓捕抗日地下人员，参与“讨伐”抗日联军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc7d3f2e964c43fb8d00028526bf2d7f','c27b3aa5-5d51-421d-a029-c3f6e7833b1d',1931,'盘山籍（一说辽宁）','盘山籍（一说辽宁），九一八后积极投靠日本，参与伪满政权筹建，制定伪满法律，为日本殖民统治提供法理依据。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1965c47fbda4430aca13a933c488a9b','9c9e4a0f-8e5c-4e09-a0df-a62b37cb9e96',1934,'伪满锦州省辖区包括盘山部分地区','伪满锦州省辖区包括盘山部分地区，任内配合日军“治安肃正”，在盘山一带强征劳工、建立伪警察机构。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-081cb50f9aa745c48caa94b7b2cfb6e2','7e9cc256-9fce-4d6b-a19c-7506a8312c22',1932,'盘山县人','盘山县人，九一八后投敌，任伪满盘山县县长，组织伪县公署，协助日军收缴民间武器，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-40316189333f4693a2c0578043d7a72a','cdca707e-3703-45ed-af5b-20a96a8b183b',1937,'继任伪满盘山县县长','继任伪满盘山县县长，推行“保甲连坐”制度，强征粮食和劳工，为日军提供物资支持。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66d8f7c7032d4533bee1db174bce8177','1e3a162d-3cfa-4512-a969-311f3d56ce2b',1933,'盘山本地人','盘山本地人，任伪满盘山县警务科科长，亲自带队抓捕抗日义勇军家属，刑讯逼供，杀害多名抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-368528899a664e208408b5f718c2f133','5eae824e-d77b-437d-b5c3-54bf54c5c298',1938,'盘山士绅','盘山士绅，投靠日伪后任协和会会长，宣传“日满亲善”，组织青少年奴化训练，破坏抗日地下组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0e08c9e359c4d589919b4f8dbd2f946','cb0d2670-3388-4129-9202-67fd0623a8b5',1932,'盘山土匪出身','盘山土匪出身，被日伪收编后任保安队队长，在盘山、大洼一带袭击抗日游击队，烧毁村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-30a9415616ad4c3288b69d86d8bc7be8','db164de9-d162-46a0-8c5a-87b97c2bef6d',1935,'盘山籍','盘山籍，任伪满田赋局局长，残酷征收“出荷粮”，导致当地农民饿死无数，并将粮食供给日军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49a06541442d40fd84d0f1d3fd27f685','817c28da-a909-4034-a5ba-0f610e3f3bb1',1936,'推行奴化教育','推行奴化教育，强制学生学日语，删除中国历史教材，检举有抗日思想的教师。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a7679a939134bd2bbbb8b69b9de571c','b8fca3bc-86a8-4294-834a-6ac3cca857a9',1937,'盘山本地汉奸','盘山本地汉奸，在伪法庭上以“反满抗日”罪名判处多名爱国人士死刑或重刑。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97c2cfb797464a7fa30278cdda9da7cc','1bf81da9-9135-4595-b25f-015044682575',1932,'任伪满营口市长期间','任伪满营口市长期间，推行日伪殖民政策，协助日军镇压抗日活动，强征劳工，控制港口经济为日军服务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01450e096def439698cabd503310b078','30d6f8ab-b390-4038-b194-f6debf1ab542',1931,'原东北军将领','原东北军将领，九一八后投敌，在营口及辽南地区协助日军清剿义勇军，后任伪满省长，参与“讨伐”抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4cae166137714443b766fb9ff4ddcbb5','93a8b62d-eb5b-4bb6-9c9b-b467621b9fab',1932,'原奉军旅长','原奉军旅长，叛国投日，在营口、海城等地指挥伪军围剿抗日义勇军，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3da5b7b03cd64922b0c89b0219e1a278','c387b786-18a5-41cf-b8d8-6030f8799e4b',1933,'效忠日寇','效忠日寇，在营口市区及周边大肆搜捕抗日地下人员，破坏抗日组织，参与“治安肃正”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-818434734944466f8156381e493b079f','30950b16-065d-4093-9fff-8a16a0f28af6',1932,'汉奸法律人物','汉奸法律人物，曾参与审判营口地区抗日志士，为日伪司法镇压提供合法化工具。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-897c0702dbd94be0a6d1cfe2b0d5ed99','3519a29a-7f19-4e5e-bee9-4e78cf50e02a',1931,'充当日本经济侵略代理人','充当日本经济侵略代理人，强制商户为日军提供物资，协助日伪掠夺营口港资源，迫害爱国商人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f6409609a454469b10bb96529bd9d66','2b467805-ae2a-4ebd-824c-3b0d03d595be',1931,'九一八后参与组织营口地方维持会','九一八后参与组织营口地方维持会，迎接日军占领，协助建立伪政权，为日军征粮派款。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-733b4a253ea04f65af0a2d42e32f7b32','fd5cc3db-010e-4890-8f9f-1e34b437df9d',1934,'在营口县推行日伪“保甲制度”','在营口县推行日伪“保甲制度”，强征民夫修筑军事工事，配合日军“清乡”屠杀抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-428e3db2c7c64aaaa5ee502734157299','7674bbc8-2fe7-43c4-a434-5f264e4e8d80',1935,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，多次到营口等地督导“治安强化运动”，推动奴化教育，支持日军经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-682a6e16b04a4f008e4fe4eff6f21970','ff12c2e8-3da3-4cdf-956a-f71ee6fd34a2',1931,'原辽宁省主席','原辽宁省主席，投敌后任伪奉天省长，对营口地区抗日武装进行残酷镇压，签订卖国协定。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd525c4a8f44481bac8132ba954bf43c','e960b7ae-ecb4-41ee-8427-3c5d0feccec8',1932,'原东北军将领','原东北军将领，九一八事变后投敌，任伪奉天省省长，积极推行日伪殖民统治，镇压抗日力量，后升任伪满洲国治安部大臣。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aed91e2d789c4d3fbbfae1f973984e9b','10875144-e217-4061-90d7-f9b83cb048a7',1932,'在营口、大石桥地区任伪警务要职','在营口、大石桥地区任伪警务要职，组织伪警察配合日军“讨伐”抗日武装，抓捕抗日志士，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c867492d170847598065f00f68bec649','10875144-e217-4061-90d7-f9b83cb048a7',1932,'原辽宁地区警察头目','原辽宁地区警察头目，投日后任伪警务厅长，在辽阳、弓长岭地区组织伪警察和特务，搜捕抗日分子，破坏地下抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ea37fabc5f34210bd167c90ee28ce73','c7dd5594-fa68-45cf-bf18-18ea231e2437',1931,'原奉系军阀','原奉系军阀，九一八后公开投敌，虽主要活动于热河，但其势力曾涉及辽南地区，协助日军镇压抗日义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e8ae5d6bdf54bc985e8e746d1aa1532','171537be-b25e-4039-aea1-1aac75d77606',1931,'原吉林副司令长官','原吉林副司令长官，投敌后参与伪满政权，其经济政策影响辽南地区，掠夺资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ba0e948eb70449cb65ad3e637232474','165900ca-9f0e-4f5f-9181-023fd952e3f9',1931,'日本间谍','日本间谍，曾活动于辽南地区，参与策划伪满成立，协助日军镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0dd536b43b84462a88f3f889dc92ffa7','165900ca-9f0e-4f5f-9181-023fd952e3f9',1931,'日本间谍','日本间谍，曾以“安国军”名义在辽宁、热河一带活动，参与对兴城、绥中抗日义勇军的诱降和镇压，协助日军搜集情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf7e154803dd49abb6a823dbb52d8ab9','8b228b19-33e5-445b-8f69-4a548936f375',1932,'在营口、大石桥地区任伪警职务','在营口、大石桥地区任伪警职务，直接参与抓捕抗日人员，制造多起惨案。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ebfd91575764a698bea03e1ea373c8a','6fc85206-b163-4f46-8e3f-27b540aba74b',1932,'投日后负责奉天省（含营口）经济掠夺','投日后负责奉天省（含营口）经济掠夺，强征劳工，控制盐业和矿产。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8371b5a39ab747d48e89f79d6e2ad6f5','346ee609-03ec-4c8c-9660-1b367b4970a0',1932,'在营口地区推行“归屯并户”','在营口地区推行“归屯并户”，制造无人区，协助日军清剿抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdbb65655ea34471901009dc639de34e','0d5186d5-89e3-40c0-9164-f37891fb7ecf',1932,'任伪满盖平县县长期间','任伪满盖平县县长期间，积极推行日伪殖民政策，强征劳工，镇压抗日活动，协助日军清乡并收缴民间武器。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f076d17efdfd472f9ab8ec25bae8d6cf','ad7d57a5-ba7d-4087-99f3-445f9bbc8589',1933,'指挥伪警察配合日军围剿抗日武装','指挥伪警察配合日军围剿抗日武装，多次参与抓捕和杀害抗日志士，并强迫百姓修建警备道路和碉堡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e861b0904834899b7ff691266a36b7b','e1a266b8-e5d8-4690-9c75-321f9bb45bfb',1934,'组织协和会宣传奴化思想','组织协和会宣传奴化思想，推行“王道乐土”谎言，强迫民众参加“勤劳奉仕”，为日军提供情报和物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a763a34f91254f7ba0b26f3de83726fd','6e57e5c0-de71-4b5d-8c36-6553c87100ba',1935,'率保安队多次袭击抗日游击队','率保安队多次袭击抗日游击队，烧毁村庄，杀害无辜百姓，并参与“集家并屯”制造无人区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba2a15bee94f4fc582c5068e35dfc5fb','a504fd42-a214-4d96-a236-c727ddbefd07',1937,'在营口市推行日伪经济统制','在营口市推行日伪经济统制，强征粮食和金属，组织“献纳飞机”运动，并镇压工人罢工和学生反日运动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-efcd64a5fe884b79a34dc45c334d271e','e9cf48ef-cecb-4681-8fb5-9fe20fe21b00',1938,'指挥警察特务搜捕抗日地下组织','指挥警察特务搜捕抗日地下组织，破坏中共营口支部，严刑拷打并杀害多名爱国人士。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1b62a77986f4a1ab13d12bdd62e19cd','3bf981f1-5e2a-4123-a2ee-134ab675e94d',1939,'负责协和会日常活动','负责协和会日常活动，组织青少年进行军事训练，宣传“日满亲善”，并监视居民言行。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-65be35968a5a4dc58a9d9317de404614','4301b7ac-6cb4-49c0-bfca-1e8ba6ff57e3',1936,'强制推行日语教育','强制推行日语教育，删改历史教材，灌输奴化思想，并检举有抗日倾向的教师和学生。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ab08aed95c84427a0a77cc99a9b0bd4','4d71aa13-1657-4ba4-96bb-e903dc0740b8',1940,'配合日军控制营口港','配合日军控制营口港，为侵华日军运输军需物资，并强迫中国劳工从事繁重装卸劳动，造成多人死亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0fe918b15aa419c9f2533cb43fee676','13d9a651-d365-43ab-a2ce-961db9f515bb',1941,'组织自卫团协助日军巡逻','组织自卫团协助日军巡逻，抓捕抗日嫌疑分子，并参与对抗日家属的迫害和勒索。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04e735ff138c47b8a8cc6d8b977cc824','f6f3e661-62c4-4840-bae6-1d166c09531c',1931,'九一八事变后投敌','九一八事变后投敌，组织伪军配合日军侵占辽宁各地，长期在伪满军政系统任职，参与镇压东北抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0aa6f5d688fc4d0da284ec2bc74e280e','f6f3e661-62c4-4840-bae6-1d166c09531c',1931,'九一八事变后投敌','九一八事变后投敌，组织伪军配合日军进攻辽宁各地，长期在奉天、营口一带镇压抗日武装，后任伪满军政部大臣，是辽宁地区代表性汉奸之一。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e79efe30c7694c64906c85cd84b60cdd','145685fb-d6a0-4410-964a-90e52344a696',1931,'九一八事变后率先投敌','九一八事变后率先投敌，率伪军配合日军进攻辽宁、热河等地，参与镇压抗日义勇军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1204df1f893a4e58ba2e069695239aa8','145685fb-d6a0-4410-964a-90e52344a696',1931,'原东北军将领','原东北军将领，九一八后投敌，率伪军配合日军侵占辽宁、热河等地，在辽南、营口周边参与镇压抗日义勇军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e03f331e1e44af387ee107609a6d37d','798c173c-a381-47a1-bf0b-68eec211b9ef',1931,'辽宁籍亲日政客','辽宁籍亲日政客，九一八事变后积极协助日军建立伪满政权，在辽宁地区为日军侵略张目。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c156b3e2fb6473f90d69e11491c1d7d','86b47357-11fb-4fc9-8abb-38c4cb51ca7b',1931,'辽宁籍汉奸','辽宁籍汉奸，参与伪满建国活动，在奉天（今沈阳）及辽宁地区推行殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c39078f94aff4b1f85fedab33f1bd624','86b47357-11fb-4fc9-8abb-38c4cb51ca7b',1931,'辽宁籍汉奸','辽宁籍汉奸，九一八后投靠日本，参与伪满建国活动，曾任伪奉天市市长，在辽宁地区推行殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d7a04a73c4c47e8bdca339fa555b0c3','bd8599e2-5e96-4ad4-8e6f-8dac2043da0c',1931,'辽宁辽阳人','辽宁辽阳人，九一八事变后组织维持会，协助日军维持辽宁地方秩序，后任伪满高官。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a923c1471f8543a6844f4bcda92d4506','db8559c3-0f2a-428f-b99c-eacaf7e54677',1931,'辽宁籍汉奸','辽宁籍汉奸，九一八事变后投敌，在营口、海城一带组织伪军，配合日军镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-976f1a92d5f94983a7917ed7817eef05','db8559c3-0f2a-428f-b99c-eacaf7e54677',1931,'原东北军军官','原东北军军官，九一八后投敌，在辽宁地区组织伪军，配合日军进攻抗日武装，活动范围涉及营口周边。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e06afe6f73184c24b72afc9d248e4c6d','fef28add-d7f0-4bb6-8eb3-bcb46cbef0ec',1932,'在营口地区长期担任伪警察头目','在营口地区长期担任伪警察头目，镇压抗日群众，推行保甲连坐，为日军搜集情报。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a13b0cf7722495c912dfd1ed78697c4','84515a4c-dfe5-4dd6-9709-64498737038f',1932,'在营口地区任职期间','在营口地区任职期间，推行伪满法令，协助日军征粮征丁，压迫当地民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-308beb909fac4feab2574481f018717f','01190f01-3978-46fc-945e-1c33cb6b7524',1931,'九一八事变后在营口组织维持会','九一八事变后在营口组织维持会，迎接日军进城，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b207fe432b774560bdc60078e79b3c09','74e1fd90-75a7-4b5e-b245-3980bcc6f813',1932,'在辽宁及营口地区担任伪警察要职','在辽宁及营口地区担任伪警察要职，参与镇压抗日地下组织，抓捕爱国人士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-108c2f0962ac4252be18b9f89bed3b9c','59303f83-fa43-4be4-b1d0-4336f0bb4fa4',1932,'营口商界附逆者','营口商界附逆者，为日军筹集物资，协助经济统制，压迫民族工商业。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba2790597ba6435d9966b5eaf9585dce','f030344c-fc33-4d3b-8ffa-fbe82be79afa',1931,'辽宁籍亲日派','辽宁籍亲日派，九一八后积极协助日军建立伪满政权，参与策划东北各省伪政权组建，对辽宁地区附逆势力有重要影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-747078bb24d24c2db6444811d2dbf06e','6ac1fd35-64fc-48df-9ad6-81afde4b0a27',1931,'原辽宁省政府主席','原辽宁省政府主席，九一八后被俘投敌，历任伪奉天省省长、伪满民政部大臣，在辽宁地区协助日军维持殖民秩序。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2897abad4d974e6db0dc782b43b222f0','8ebc151e-2e8f-42fe-94f9-fbfa548d0e91',1931,'辽宁辽阳人','辽宁辽阳人，九一八后组织奉天维持会，协助日军维持地方秩序，后任伪满参议府参议，是辽宁地区较早附逆的地方士绅。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4789c09e7e454eeaad40a351256abfae','1f09291a-f3bf-4b00-acd9-32a6eb6e85a6',1931,'在营口地区担任伪警察及保甲职务','在营口地区担任伪警察及保甲职务，协助日军征粮、抓丁、镇压抗日群众，是营口本地附逆势力的代表。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21bde67445b84d78bfa4cc9f4ba00349','2d078a87-3a85-4762-a588-f01d23dff778',1931,'在营口地区参与维持会活动','在营口地区参与维持会活动，协助日军维持地方治安、搜集情报、迫害抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-564b16ea5c114eaf99174debbf2f36ab','91cbd076-893a-4508-99d6-96c39579d65d',1931,'在营口县任伪县长期间','在营口县任伪县长期间，推行日军殖民政策，征粮征工，镇压抗日活动，对老边一带亦有管辖影响。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db22c53894be42f788b23d6b5654d761','43f98a04-628c-4936-88e6-95e5499610f1',1931,'在营口教育界推行奴化教育','在营口教育界推行奴化教育，协助日军宣传“日满亲善”，毒害当地青少年，是文化教育领域附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-063d99ce6b0b49fca70faaaf5115dca1','50818704-c4dd-435c-bf5b-9bf414d5cb7b',1931,'在营口商界为日军筹款筹粮','在营口商界为日军筹款筹粮，协助经济掠夺，压迫当地商户，是经济领域附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-514c810691654816a7e11beaa4381852','dfb8f432-c350-4917-a521-a85c8e087b88',1931,'在营口地区积极执行日伪当局命令','在营口地区积极执行日伪当局命令，镇压抗日活动，协助日军搜捕抗日志士，强征劳工，为日军提供情报。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e811679bfb2a4a0b87e2d30572c28e94','6a749a0a-3a12-40fd-884f-96b39c32c0f7',1931,'原东北军将领','原东北军将领，后投敌叛国，在营口及周边地区协助日军清乡，参与“讨伐”抗日武装，推行奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46c6a0bf865a4b69b59b16df5c73ea54','50ec5a44-bb99-4520-b6cd-8123876fb413',1931,'原东北军旅长','原东北军旅长，投日后在营口、西市一带组织伪军，配合日军“扫荡”，残害抗日军民，强征粮食。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ede295545e3b4bec915642c77f0e7217','c49a5041-5ee8-4427-8ee5-69cfb19f5aa8',1931,'积极鼓吹“满洲独立”','积极鼓吹“满洲独立”，在营口西市等地发表亲日演讲，协助日本关东军建立伪政权，参与制定奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b36dc9bda7540b6960efd27eb0cf3df','daddedc2-f63b-44b3-869a-b7d96c6b04cd',1931,'在营口西市地区为日军筹集军饷','在营口西市地区为日军筹集军饷，强迫商户捐献物资，向日伪当局举报抗日商人，协助经济统制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4fa6f51e598049fdb21d1967c007d7fd','64366d0a-eff8-4260-8c1d-b671aa487d23',1931,'带领保安队在西市一带抓捕抗日地下工作者','带领保安队在西市一带抓捕抗日地下工作者，参与屠杀无辜百姓，为日军提供劳力和情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c23e28a5e7044daa518c9da065fbcfa','52a8f3d7-a509-4101-9894-72ef1a66ce4d',1932,'曾任东北军将领','曾任东北军将领，后投靠日本，任伪奉天省省长，积极推行日伪殖民政策，镇压抗日力量，其管辖范围包括营口地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10f08fef719b4efa9b72993231ae2a35','347490fa-d8ff-4502-a4f7-346171854cdc',1932,'原营口地方士绅','原营口地方士绅，日军占领营口后出任伪市长，协助日军维持统治，强征劳工，为日军提供物资支持。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-634a8ff489b24f11910c492185950f6b','77c87598-f040-4edb-9777-d1aaba114797',1933,'原东北军将领','原东北军将领，九一八后投敌，曾任伪热河省长，期间在营口、鲅鱼圈一带协助日军清剿抗日武装，残害百姓。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e00c27e36314fdb944f08c3e916324e','0e82c3b4-ddc9-44a7-bdc5-c84793342af2',1932,'原营口警察','原营口警察，后任伪保安队长，多次配合日军围剿抗日游击队，在鲅鱼圈沿海地区抓捕抗日志士，强征民夫。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6dde72f503c04425ae890ee79753dfb1','e107ef3f-b118-46f4-9621-dff8a6949c1a',1932,'原中国律师','原中国律师，投日后任伪法院院长，在营口地区审判抗日人士，以“反满抗日”罪名判处多人死刑或重刑。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-afb7d23538df4b318b430d292f68680c','d8980d82-9f9c-4a92-a6bb-0cf181e23b5c',1932,'原奉系官僚','原奉系官僚，投日后任伪参议，多次到营口、鲅鱼圈视察，推动日伪“治安肃正”计划，协助日军建立保甲制度。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cde67706006440d87c98473cda3c1b2','947a2a70-3b9a-4e8a-a5cd-4a4fec706fe6',1935,'原东北军将领','原东北军将领，后为伪满最高行政长官，其政策直接作用于营口地区，支持日军经济掠夺，强征粮食和劳工。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-844bf152169e439db1c9b7df62d5d25d','05cf3d50-a85d-47c0-bac5-b8ff582a8923',1932,'原营口警察','原营口警察，投日后任伪警察局长，协助日军特务机关，在鲅鱼圈港口监控往来船只，逮捕抗日地下工作者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89c0562a0845417ab3b1cb6fbc13e078','db487db6-0e3f-433f-a92e-f6957157e08c',1933,'原营口港职员','原营口港职员，投日后管理鲅鱼圈港区，为日军运输军需物资，强迫中国工人无偿劳动，克扣口粮。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ce9b874e1cb44ac969b2c122ed46714','f5c7b0df-12c4-49a7-8100-13a09b8600f0',1934,'原奉系官员','原奉系官员，伪满时期任锦州省省长（辖区含今葫芦岛地区），协助日伪推行“治安肃正”和奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66c279626c71484091a144e82c42f3dc','ba597514-9f0b-4c8d-aac9-a7f5a480bad6',1931,'原奉系法律人士','原奉系法律人士，投日后任伪奉天市长，参与建立伪满政权，协助日军在辽宁地区进行殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb5e497e21f04ed8a3459c1b141abddf','ba597514-9f0b-4c8d-aac9-a7f5a480bad6',1931,'积极参与伪满政权建立','积极参与伪满政权建立，在辽宁多地活动，为日军侵华提供法律和行政支持，涉及锦州地区伪政权建设。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5bcfa5dd2c11434f8e0e936e7af98f5e','b6090f14-2045-45d6-870f-2d40750d4165',1932,'曾一度投降日军任伪职','曾一度投降日军任伪职，但不久反正抗日，其投敌期间未在葫芦岛地区有具体活动，但作为东北汉奸名单常被提及。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eccea5d9cf5c4aecaf0a2fbd83422f4a','f72d875d-2153-4ebf-9e32-c7e6004594f9',1931,'原奉系商人','原奉系商人，投日后任伪奉天省实业厅长，协助日本掠夺辽宁资源，包括葫芦岛地区的矿产和农产品。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a50f9c763344ec0a8d33641d7d542b9','2495aa71-2380-4832-89f9-ab649efa4606',1935,'日本关东军指派日籍官员','日本关东军指派日籍官员，但作为伪满官员，在锦州省（含葫芦岛）推行“集家并村”和“治安肃正”，残害百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e51d00498f634a1caf9269edca3eecd7','35426db9-8cd6-4226-9cd4-0fdcec2d274c',1932,'原奉系警察头目','原奉系警察头目，投日后任伪锦州省警务厅长，指挥伪警察在葫芦岛地区抓捕抗日志士，镇压民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-984cbee39e3f4bbe90ccc3a2c7d96ab1','3680ae1c-c37c-44b3-9dc3-227c33bb727f',1932,'投日后任伪锦西县长','投日后任伪锦西县长，协助日军建立伪政权，强征劳工，参与“讨伐”抗日义勇军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-815b2061633740b48b9f5a8ccd4062d1','99b2bff5-bdd2-4801-8d35-ade454e666c0',1933,'投日后任伪绥中县长','投日后任伪绥中县长，推行日伪奴化教育，强征粮食，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4960a95e1fc14c7e82797f0ed3fdc7e6','5fc53a65-5cba-4f3a-9e4f-1e17c549e1b1',1931,'九一八后短暂组织地方维持会投靠日军','九一八后短暂组织地方维持会投靠日军，后因内部矛盾被撤换，但初期协助日军稳定占领秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20ae76048a944ddcadc4407ab042b3cb','6bc37da8-5372-4992-bcc0-ec2be1db1fba',1935,'利用家族影响','利用家族影响，在兴城（今葫芦岛）组织协和会，宣传“日满亲善”，协助日军进行思想控制。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f87fa3001ff24797be88f23d952826b9','b9249ece-66de-467b-bbb0-e29ed81f4fa8',1934,'投日后任伪葫芦岛港务局长','投日后任伪葫芦岛港务局长，协助日军扩建港口，用于军事运输和掠夺资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f2b6875a64f4b74a10f3c4122dc1f4d','796d71e7-d080-4be3-9a12-b36e1779416e',1933,'组织伪保安队','组织伪保安队，配合日军在葫芦岛地区进行“扫荡”，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71bb3c3c58cf46c9a3579829bee7dc5a','ff6542c1-e530-4cc7-97db-b225d220914d',1932,'指挥伪警察在绥中（今葫芦岛）抓捕抗日地下党员','指挥伪警察在绥中（今葫芦岛）抓捕抗日地下党员，破坏抗日组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c588e60a5944cbc862ced68b48a74d7','e3c2f45c-084a-4b1e-a405-e5a56a8b2ed4',1936,'推行日本奴化教育','推行日本奴化教育，强制学校教授日语，删除中国历史内容，在葫芦岛地区毒害青少年。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-241866067f09486db32eba9bc1775c30','ba148d65-9d5c-4299-a234-dfd76e7c0726',1931,'原东北军旅长','原东北军旅长，1932年投降日军，在辽宁地区（包括兴城、葫芦岛一带）指挥伪军围剿抗日义勇军，制造多起屠杀事件。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-300f39b25533408e8b8b613d3188ca50','15d152c3-1c0d-4a10-adae-2c20b825757c',1934,'原锦州地区士绅','原锦州地区士绅，投靠日军后任伪锦州省省长，管辖范围包括葫芦岛、兴城，推行“治安肃正”，组织伪自卫团镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e84d716ea06043f1bf6420dc1209cab8','9e20c9f1-1973-41de-a5a6-c639def9c66c',1931,'原奉系法律人士','原奉系法律人士，九一八后积极参与伪满洲国建立，在辽宁地区协助日军建立殖民政权，参与制定镇压抗日法令，影响波及兴城等地。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67e6c9158f8e45c781270043097b3537','9e20c9f1-1973-41de-a5a6-c639def9c66c',1931,'积极参与伪满政权建立','积极参与伪满政权建立，在辽宁地区（含锦州辖区）为日本关东军提供法律与行政支持，协助建立伪警察和保甲制度。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54cb3a2a3fa84fa6a710fc0fd3f7d1ec','4ef63bd5-7c59-40fa-aeed-8eea4eeead75',1932,'原锦州警察头目','原锦州警察头目，投日后任伪锦州省警务厅长，在葫芦岛、兴城一带指挥伪警“清乡”，杀害抗日军民，掠夺物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02f44351d5b64c33b8d5c6e790b0f660','4ef63bd5-7c59-40fa-aeed-8eea4eeead75',1932,'在锦州省（含绥中）主持伪警察机构','在锦州省（含绥中）主持伪警察机构，抓捕抗日志士，协助日军“讨伐”辽西抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e30121f7b114fb39bf97fa92f3e4928','308eb400-02dc-42b5-bfd5-20af005d1933',1931,'原吉林军参谋长','原吉林军参谋长，投敌后虽主政吉林，但曾参与策划对辽宁西部（包括兴城、葫芦岛）的军事“讨伐”，提供伪军支援。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6765e447451c45288bfb16e853228386','4dcd58f8-18ac-433d-997c-9e92d5bd2930',1931,'日本浪人','日本浪人，加入伪满军队，在辽宁锦州、兴城一带指挥伪军“讨伐”抗日武装，手段残忍，制造多起血案。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86429f75d99445b5b3c53d2568a37767','d41192bd-bc7c-44d7-84c6-f6402803f609',1932,'原兴城地方士绅','原兴城地方士绅，投日后任伪兴城县县长，强征粮税，组织伪县公署配合日军“扫荡”，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1606b92eac340578ec4a55ee44ce59c','91e837c8-0182-4322-ac26-e1b729a257b1',1933,'投靠日军后任绥中县长','投靠日军后任绥中县长，在兴城、绥中交界地带协助日军建立“无人区”，强制村民迁移，烧毁房屋。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d215cf56e1c463793c30fbd4f45aa0d','c3e2a74e-cea8-417e-b572-8110c04731f2',1932,'原土匪头目','原土匪头目，投日后任伪警察讨伐队长，在兴城、葫芦岛山区多次袭击抗日义勇军，杀害俘虏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f23571b14cd14c26ae5e40e02f69ef8d','2477de56-e2ea-47e2-b069-f2f3b0c679ed',1933,'兴城本地地主','兴城本地地主，组织伪自卫团，为日军提供情报，参与抓捕抗日地下人员，强征壮丁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da782035de924a20864066f37202565c','24b49587-a8c6-40d6-b4e9-040df65af9fe',1935,'原军阀','原军阀，投日后在辽西（包括兴城、葫芦岛）协助日军策反地方武装，组织伪军，破坏抗日统一战线。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f57d5bb2670b4c1d819fa181f324c695','697be0b3-86c3-4556-b3f1-3d1b9f0f8ac8',1932,'原东北军连长','原东北军连长，投敌后任伪保安队司令，在兴城、葫芦岛沿海地区巡逻，截击抗日物资运输，参与“清乡”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e945903ff2bc47dcad0aa93842701ab1','4981e9ef-fe7a-4fdf-b5cf-00f51cbd4890',1931,'原奉系官员','原奉系官员，投日后任伪奉天市长，其伪政权政策覆盖辽宁全省，包括兴城地区，推行奴化教育和经济掠夺。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8761bee697f4908af847412fd87cd11','6ec6e5ee-542b-4296-9c62-5166ec62d128',1931,'原东北军高级将领','原东北军高级将领，九一八后投敌，参与策划对辽宁西部抗日义勇军的围剿，其伪军部队曾在兴城、绥中作战。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90413d6dff61451c8d3e7a7153045d21','662e874d-8222-4d1e-949d-fc2a5dc97307',1932,'投日后任兴城伪警务科长','投日后任兴城伪警务科长，直接指挥伪警察抓捕抗日群众，刑讯逼供，协助日军建立“爱护村”监控体系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08c4e67b190d4c3f899a52d93137c17d','d0b29761-9ca5-442e-87c8-81b1bc165ad7',1934,'原东北军旅长','原东北军旅长，后投靠日本，任伪锦州省省长，管辖包括葫芦岛、南票地区，积极推行日伪殖民政策，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d8556769120468d90c4e09235c9c756','a334689f-a62c-4dfe-9ac5-0eb267a46aa6',1932,'原奉系司法官员','原奉系司法官员，投日后参与伪满司法体系，曾参与处理涉及葫芦岛、南票地区的抗日案件，迫害爱国人士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67ecd5609753436f845d5c748d395750','2be98495-c1b0-4cd4-b196-0e36c209663d',1933,'原锦州地区警察头目','原锦州地区警察头目，投日后任伪警务厅长，在葫芦岛、南票等地建立特务网络，抓捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aad06aaaed1a43eb821e340e40a2814b','f0a6a6b2-8509-4ecc-aa5b-082df52a6365',1935,'原南票煤矿中方管理人员','原南票煤矿中方管理人员，投日后任伪矿长，强迫矿工为日军采煤，虐待劳工，造成大量矿工死亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da1cd490960043fea3ebfd4ff86a99ba','8b9a9aab-0abd-4bac-a81a-20f6e86df6ee',1932,'原吉林省政府委员','原吉林省政府委员，投日后任伪满财政总长，参与制定对辽西地区经济掠夺政策，包括南票煤矿的垄断经营。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-419e9d169fae4b929cd04fbb621546cb','5ff4622b-1517-4230-9350-bab4185c0d50',1932,'一度投日任伪黑龙江省长','一度投日任伪黑龙江省长，但未实际管辖辽宁地区，后反正抗日，与南票无直接关联，但列入以备参考。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9450434a42664d08a755fa6772d219bd','aefc830d-3ebf-43e2-8564-747d96dfe487',1933,'原热河省警察头目','原热河省警察头目，投日后在朝阳、南票一带组织伪警察，协助日军“清乡”，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc6793a9d78f436fa7c5e20f99dcb840','c685cb08-8865-42b1-aafd-62dd14568ad0',1933,'原地方民团头目','原地方民团头目，投日后任伪保安司令，在葫芦岛、南票一带围剿抗日游击队，烧杀抢掠。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e79d33a4deee4a328992346efb779ec5','29d544d0-b72f-40aa-8930-03203087d1ac',1933,'土匪出身','土匪出身，投日后任伪游击司令，活动于辽西山地，多次袭击南票抗日武装，为日军充当鹰犬。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d28d8365eff41fa90dccf2f3075e1d5','bdf47664-6a00-427a-91d1-d80b63933127',1936,'原矿区保安','原矿区保安，投日后任伪警察署长，镇压矿工罢工，抓捕抗日地下工作者，罪行累累。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6de1e12201240589f3eeba836b5fa77','aeb38e69-310f-48cb-a0d9-7c09eab9d10c',1934,'原东北军军官','原东北军军官，投日后负责热河省（含建昌）警务，多次组织清乡，抓捕抗日志士，配合日军“讨伐”活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7127d3df558498bbad7d5bbe87ea3d1','f32fad94-b182-4063-aa0c-187d9307995e',1933,'伪满初期任建昌县县长','伪满初期任建昌县县长，推行保甲制度，强征劳工，为日军提供粮食和情报，镇压当地抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2249009f4267406aac3ecb6c4879accd','5ee03b74-9efe-440a-8a94-a791ddc1c0da',1935,'长期担任建昌伪警察头目','长期担任建昌伪警察头目，直接参与抓捕抗日地下工作者，破坏抗日组织，多次带队“扫荡”农村抗日据点。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01efe1c606f14375ba8124c1d5c21379','9d5f073a-682c-4908-9d19-f932fd411b24',1938,'负责建昌地区协和会宣传','负责建昌地区协和会宣传，推行奴化教育，组织“勤劳奉仕”，强迫民众为日军修筑工事，搜集抗日情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac8de003d6bd43509f4fd4d3c022f65c','bc72c715-9421-470a-a6c5-e778868f9542',1936,'率领伪保安队配合日军多次进攻建昌周边的抗日游击队','率领伪保安队配合日军多次进攻建昌周边的抗日游击队，杀害抗日军民，烧毁村庄，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11aa7f95444d4c139fba3b023854b6bb','e7e93731-28a8-4280-8b04-7ea621d02520',1933,'虽为军阀投机者','虽为军阀投机者，但在热河期间与日军合作，默许部下参与镇压建昌地区抗日活动，提供情报和物资支持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69f0f069f107477d91b69b79089047c7','054a1f3a-ec84-4bef-95b7-98d48a6a0408',1937,'主持伪司法审判','主持伪司法审判，以“反满抗日”罪名判处多名爱国人士死刑或长期监禁，协助日伪维持殖民秩序。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bdb6a225260941b0bf98825bad14dd1f','b5e87a34-bb87-41fd-9241-d98aeabbf8fd',1939,'负责为日伪征收高额税赋','负责为日伪征收高额税赋，强征农民粮食，导致建昌地区民生凋敝，间接支持日军战争经济。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73f6239e9e9c407aba8b59f1de3131e1','f3afd6a2-eb9a-4bd8-85b8-cfcdc446af5b',1934,'推行日本奴化教育','推行日本奴化教育，强制学校教授日语，删除中国历史内容，灌输“日满亲善”思想，毒害青少年。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58af52134d7e49d0b2c43ff341422a5f','a2b79d41-81d8-4a6b-9780-6d29924ff371',1931,'原东北军旅长','原东北军旅长，叛国投日，任伪奉天省省长，管辖包括绥中在内的辽西地区，推行日伪殖民政策，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-843e9c402813424494e56d3fe3c5ff71','f83726d2-2b7f-49bd-98c0-16010a0d1455',1937,'原东北军军官','原东北军军官，投敌后任伪锦州省省长，绥中县属其管辖，积极推行“治安肃正”，配合日军围剿八路军冀热辽根据地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4407c44e8ee94abb80665e8954366957','b08d2cb1-2a59-40c8-b940-d4ca711b8aa2',1931,'汉奸政客','汉奸政客，曾任伪奉天市长，参与策划辽宁地区日伪政权建设，对绥中等地实施奴化统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-baa5638739c44d3a8538cd56069c47aa','7ad18f55-8e7f-4d94-ad1d-a9ecb681ea88',1932,'绥中本地汉奸','绥中本地汉奸，投日后任伪县长，强征民夫修建日军工事，镇压当地抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f54907af43041c7bbf511b10bf38180','880c90fd-69fa-4eb8-a06d-c68506c3b481',1933,'在绥中地区组织伪警察队','在绥中地区组织伪警察队，多次参与围剿抗日义勇军和八路军游击队，残害百姓。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f452b00e94834aac921ba33add0944bb','1345a812-8782-4f19-a37a-53e4405e64f3',1931,'原辽宁省政府主席','原辽宁省政府主席，九一八后投降，任伪奉天省长，对辽西绥中地区推行日伪法令。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-023295f391654de8829c637a7be939c8','b474c7ab-7411-4d10-9976-a636a5948379',1931,'满清皇族','满清皇族，投日卖国，参与伪满政权建设，间接影响辽宁各地包括绥中的殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-538ee3c65a464912aa5196ff93ddccf0','b474c7ab-7411-4d10-9976-a636a5948379',1931,'原东北军吉林副司令长官','原东北军吉林副司令长官，1931年投敌，参与建立伪满，其政策影响遍及辽宁，包括阜新地区的经济掠夺与鸦片专卖。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-023305c1c3d14828b80798cfe70cdca4','b474c7ab-7411-4d10-9976-a636a5948379',1931,'清末宗室','清末宗室，九一八事变后率先在吉林投敌，组织伪吉林省政权，后任伪满财政部总长、宫内府大臣等职，积极协助日本控制东北财政与宫廷事务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5599183fe91e4bdbba8ab16fdbb09b27','b474c7ab-7411-4d10-9976-a636a5948379',1931,'清朝宗室后裔','清朝宗室后裔，九一八事变后主动迎接日军进入吉林，组织伪吉林省政权，后任伪满洲国财政部总长、宫内府大臣，为伪满建立初期重要附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-953b794362ae41e3bea96c7eb5a4fde1','b474c7ab-7411-4d10-9976-a636a5948379',1931,'清末吉林驻军将领','清末吉林驻军将领，九一八事变后率先投敌，引日军进入吉林，后任伪满财政部总长、宫内府大臣等职，参与伪满政权对东北包括黑龙江地区的统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de96803da3794c19a9be9693995f3f76','b474c7ab-7411-4d10-9976-a636a5948379',1931,'原东北军吉林副司令长官','原东北军吉林副司令长官，九一八后率先投敌，引日军占领吉林，推动伪满建立。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76814b90749445b7aebeaaf6d3dc5cf8','b474c7ab-7411-4d10-9976-a636a5948379',1931,'清末宗室','清末宗室，九一八事变后率先在吉林投敌，组织伪吉林省政权，后任伪满洲国财政部总长、宫内府大臣，积极参与伪满政权建设，其影响波及黑龙江地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ac08a49ac0e409faf16a2c47a6dcaa3','b474c7ab-7411-4d10-9976-a636a5948379',1931,'清末宗室','清末宗室，九一八事变后率先在吉林投敌，组织伪吉林省政权，后任伪满洲国财政部总长、宫内府大臣，积极参与伪满政权建设，其附逆活动影响遍及东北包括黑龙江地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74057be0404844dcb2b192bf5ce4271a','3e2cba52-a6e1-47e2-aece-a8bee6f2953a',1938,'在锦州省（含绥中）组织协和会','在锦州省（含绥中）组织协和会，进行奴化宣传，搜集抗日情报，协助日军“清乡”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c164e022488493d930ec6fef96e9852','b6ebe0ee-79d5-4c5a-85a1-a70968770963',1939,'绥中本地汉奸','绥中本地汉奸，负责协和会分会，煽动民众拥护伪满，告密抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4de24d10c4b6496ba30b412ce061c49a','1caaa60c-1cd0-41f1-a58b-4ecbe3e62288',1935,'率保安队配合日军扫荡绥中西部山区','率保安队配合日军扫荡绥中西部山区，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c66f6240a02345fe9ca65bfbb9419ef8','4e358649-4e4f-49bf-b0a0-288b0ba630f4',1937,'在锦州省（含绥中）推行奴化教育','在锦州省（含绥中）推行奴化教育，篡改历史，强迫学生学日语。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0f6f9f5b9a64f59b1d09bc8e2f6ced3','e34f4524-d82e-4a6e-aae5-edf540ffe429',1933,'虽未任实职','虽未任实职，但公开支持伪满，其旧部在辽宁绥中地区协助日军维持秩序。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1051b3c026b641ba93ed0139c3d58d47','74056d1b-02d0-460e-b89f-387215ff0661',1932,'一度投日任伪职','一度投日任伪职，影响绥中地区部分旧部附逆，后反正抗日，但前期行为已构成汉奸事实。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ce22165bfce4486bcce79531bbb5204','74056d1b-02d0-460e-b89f-387215ff0661',1932,'江桥抗战英雄','江桥抗战英雄，1932年一度诈降出任伪职，旋即在黑省（含齐齐哈尔）反正抗日，其投敌行为虽短暂但曾造成恶劣影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c332472a246546e9a746d59d64086fac','2b799c5c-24f0-45b0-9ce9-3ee24545ad2e',1938,'在锦州省（含绥中）审判抗日人士','在锦州省（含绥中）审判抗日人士，判处大量爱国者死刑或监禁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77a931ba962149be9e74900795b876c7','35f5543c-6a24-474e-82b4-3e24c849b66d',1940,'协助日籍副县长管理绥中','协助日籍副县长管理绥中，强征劳工，实施粮食配给制，导致民众饥荒。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7046dffedbfe403c9d88cac58c22e9c6','9bc38890-988a-4f0a-b734-dcd1bb1d51fb',1931,'原东北军旅长','原东北军旅长，叛变投敌，在辽西地区（含连山）组织伪军，多次围剿抗日义勇军，屠杀抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f12791811f64fdba06ed63184362621','267e6852-74fb-4959-9dbf-16af96abda2a',1934,'原地方豪强','原地方豪强，投日后任伪锦州省省长，管辖范围包括葫芦岛、连山地区，推行日伪“治安肃正”，强征劳工，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5116405395fb46da9a49e86f72e9b314','267e6852-74fb-4959-9dbf-16af96abda2a',1934,'在锦州地区任伪省长期间','在锦州地区任伪省长期间，推行日伪奴化政策，强征劳工，协助日军建立保甲制度，镇压当地抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad4d36ea3dad43dcab94fcb9dfbb020f','6e5c14e6-ae80-452d-9097-3ea63ebda131',1932,'原警察头目','原警察头目，投日后负责锦州及连山地区警务，协助日军建立保甲制度，抓捕抗日地下人员，制造多起血案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df1a9d400792496baa5bbb8574dfb700','9dcc3344-0712-4593-81e3-3723121f388e',1931,'原奉天省主席','原奉天省主席，被俘后变节，任伪奉天省长期间，管辖辽西部分地区，配合日军在连山一带推行“归屯并户”，切断义勇军补给。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16e66ac068b2428cab26f7178a02a1a7','e7343246-74f8-493c-9490-715498761122',1931,'地方士绅','地方士绅，日军占领锦州后出任维持会长，在连山地区组织伪政权，为日军提供粮草和情报，协助镇压抗日义勇军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e83a70b9bed6424e9bd34101fd259d75','bcad287d-24df-48b4-8d5a-6f3a9adad5c2',1933,'土匪出身','土匪出身，投日后任伪军头目，活动于辽西及热河交界，多次率部进攻连山一带的抗日游击队，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f17c9670c1c04df8ac3c130bd5141f14','7861b159-0f6a-45e4-bd01-90442fc20f96',1932,'原地方警察','原地方警察，投日后任连山地区伪警察署长，直接执行日伪“治安肃正”，逮捕、刑讯抗日嫌疑人员，参与“大检举”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c57e53e4b9d4c7a9bfb97fc6fca6feb','a69bc3e3-1f58-45f0-8f5f-303399d6e55d',1932,'（注：王永江为民国初期奉系要员','（注：王永江为民国初期奉系要员，但已病逝于1927年，此处应为误传。实际在锦州地区活动的汉奸为伪锦州省省长王瑞华，但史料记载有限。）','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cec3bb92dc4a46aa89bbf3dca2f98593','e209a0e1-abe5-4815-89e4-65f0aff8e399',1934,'在锦州（含今葫芦岛地区）推行日伪统治','在锦州（含今葫芦岛地区）推行日伪统治，强征劳工，配合日军“治安肃正”，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3271a1410d454a05babc170d6afd0415','e3bbb3f7-6e3c-4a57-9b91-afedf5e2033c',1931,'原奉系官僚','原奉系官僚，积极策划“东北自治”，投日后任伪满参议府议长，在辽宁地区为日伪统治出谋划策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d45b208fe624eabab3aca7d9302f320','959a0d3f-002d-491c-99b6-d4fb9ea72f42',1932,'在辽宁地区司法系统内为日伪效力','在辽宁地区司法系统内为日伪效力，审判抗日志士，镇压反满抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20cd9bac3c584110a704b96e7be87330','d3b57e4a-1a05-4047-8c34-83b11991bc11',1933,'在锦州（含龙港地区）指挥伪警察','在锦州（含龙港地区）指挥伪警察，协助日军搜捕抗日地下组织，强征劳工，迫害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96cddd83c50f4788a1675d70309ce1ee','9c0722c4-c6dd-4272-8085-101056409e25',1934,'在锦州及葫芦岛地区推行奴化宣传','在锦州及葫芦岛地区推行奴化宣传，组织“协和会”刺探抗日情报，配合日军“治安强化运动”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01cfb89b2fd0410382a575426fe8b853','1f7655ca-00a4-4445-9eb4-2c5a4f7e62fb',1933,'在辽宁西部推行日伪“民生”政策','在辽宁西部推行日伪“民生”政策，实际为掠夺粮食、强征劳工，协助日军控制葫芦岛港口。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebe73fd6f81444ff8dce907b9ebd8114','d48c8c52-9683-4e17-9882-b95866746a71',NULL,'无','无','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ee0e1f951394379be2c5766717ff1ad','f8f70ea7-35d7-48cb-9050-dcc40329e17d',1931,'积极协助日本建立伪满政权','积极协助日本建立伪满政权，曾任奉天省省长，参与奴化教育与经济掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88cf74a262b7422b8fba66954204ef9a','f6ebd053-0220-4108-ba35-93152d117e4d',1931,'曾任伪奉天市长','曾任伪奉天市长，协助日本控制辽阳地区，参与制定殖民法规。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5c95ee067034f32997e929527458dc1','f6ebd053-0220-4108-ba35-93152d117e4d',1931,'原奉系政客','原奉系政客，九一八后投靠日本，曾任伪奉天市市长，在辽宁各地（含铁岭、开原）推行奴化教育，协助日军建立伪政权。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf1c7dbc0d9346cc97126ea37f569d4c','f6ebd053-0220-4108-ba35-93152d117e4d',1931,'原奉系官员','原奉系官员，九一八后投日，曾任伪满奉天市市长，后任伪满立法院院长，为日本殖民统治提供法律与行政支持，涉及铁岭地区伪政权建设。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-089aa22c834b48639bc82914a40f3228','2978606a-01f7-4472-82ba-aa7c5e02366a',1931,'九一八事变后组织辽阳地方维持会','九一八事变后组织辽阳地方维持会，为日军提供粮饷与情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f86bbf8fbc54e72a965f30d651b685d','198c16f0-d41e-43ea-8570-fc7e90cd20b2',1932,'任伪辽阳县长期间','任伪辽阳县长期间，强征劳工，推行保甲制度，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-276c905b50b249b597b190417e0366fc','8a85c7c3-b577-48c3-bc50-d8f03526ab17',1932,'指挥伪警察抓捕抗日志士','指挥伪警察抓捕抗日志士，参与制造多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-572c17257c534c739fa32e84d448e351','07db6406-809e-4cdc-a2ef-7dafa636ffb1',1933,'率伪保安队配合日军扫荡','率伪保安队配合日军扫荡，杀害抗日军民，掠夺民间物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e5546add4424435b46b7ad4c9b6dbd1','c83978f1-fbb0-4a60-a38c-8383a34af2a6',1931,'在辽阳地区协助日本掠夺铁矿资源','在辽阳地区协助日本掠夺铁矿资源，压榨中国工人。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d0bd239f2b54a8c935b21362ce54dae','96976ac0-069a-4173-87dd-a510544ed2e4',1932,'在辽阳地区推行“治安肃正”','在辽阳地区推行“治安肃正”，组织伪警察围剿抗日游击队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef8d0924a1104eb1aeb9ab8a0a732e71','a2c94303-e6a0-4efd-af3a-b960984f2cea',1934,'宣传“日满亲善”','宣传“日满亲善”，强迫民众参加协和会，收集抗日情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13be39bc63ef4c059c8114f94c91e5bf','4666a7e8-d180-433e-9f89-e9c943f072a6',1931,'为日军筹措军费','为日军筹措军费，强征商业税，协助日伪经济统制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3deeca43814b4390b9a029b02ed744c9','1c6fab2e-9aed-472b-9c12-f9c6b0c63178',1932,'推行奴化教育','推行奴化教育，删改历史教材，强迫学生学日语。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b2d6f8b9f174ab49263131fa672a061','5913f796-dea0-4ef5-8165-2a4167f1495f',1931,'在辽阳地区强征土地','在辽阳地区强征土地，控制粮食购销，导致民众饥荒。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-40eb7cff31044da5930b5b6f114dfed7','eb54fd0c-17fd-42aa-8acc-4de7c5b894b4',1932,'协助日本发行伪币','协助日本发行伪币，搜刮辽阳民间财富，资助侵华战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec28a66c4f77402eb00dce0ad0a1dc89','550da8ee-1f99-4241-9a95-ce734e0a9124',1932,'一度投降日本','一度投降日本，在辽阳地区发表亲日言论，后反正抗日。','危害等级A（甲级，省部级/大军区级要员）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-285276c0488d42558d38b2398abc28d3','31506672-3682-4037-8bed-0def1589229e',1932,'在辽阳地区积极推行伪满政权','在辽阳地区积极推行伪满政权，组织地方治安维持会，为日军提供情报并协助清剿抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04dc3bbe439743e3a45efbf9aac1853c','7a27e0c4-465f-41dd-8321-956ced8b0a06',1932,'在辽阳任内强征民夫修建日军工事','在辽阳任内强征民夫修建日军工事，强制收缴民间武器，并组织汉奸保安队协助日军镇压太子河两岸抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-084b234cdbc24c6ea1d99259c0be11c8','19973e6f-e663-4e2c-873f-43cd9b360a68',1931,'九一八后率先组织辽阳维持会','九一八后率先组织辽阳维持会，欢迎日军进驻，提供当地抗日志士名单，导致多名地下党员被捕牺牲。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9922f79fdc09401ebe8592b82377995c','7edd049c-35ce-4d9e-893f-a6ff1270e896',1933,'在辽阳、太子河地区推行经济统制','在辽阳、太子河地区推行经济统制，强征粮食和金属物资供日军军需，导致当地民众生活极度困苦。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8efa0d6e75cd44c3ac6a099bbaa1d015','0bd01ee1-cfc8-44f2-b188-35dc6b903b15',1934,'在辽阳推行奴化教育','在辽阳推行奴化教育，强制学校使用日语教材，并组织学生参拜靖国神社，破坏当地抗日文化传统。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-017ffa0d5d7942bfbd7b6b7b01473530','1fa011be-39bd-43ba-b6c2-b386be44fa99',1932,'指挥伪警察在太子河沿岸设立检查站','指挥伪警察在太子河沿岸设立检查站，搜捕抗日交通员，多次参与围剿抗日义勇军，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19dd70565ab84c2eab50636546ca781a','2036f35a-d4bf-4bf7-becf-13ca7723ed61',1931,'虽主要活动于热河','虽主要活动于热河，但其部队曾在辽阳、太子河地区参与“讨伐”抗日武装，烧毁村庄，掠夺财物。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e01cc5c7d91e4610923f129f1267e4c2','9cfa646b-800e-4fc4-a9ea-6bc58771fabf',1931,'原律师','原律师，九一八后投靠日军，任伪奉天市市长，后任伪满立法院院长，参与制定伪满法律。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06bb4b72d0da40beb3d7812d631229b8','fc11c8f0-45d0-4db4-b0d0-5418260e1ae3',1931,'辽阳当地士绅','辽阳当地士绅，日军占领辽阳后组织维持会，协助日军维持秩序，征收粮饷。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6279354ac84d4114b64fde94d2158428','9f1c2d41-4b83-4996-8909-ed91541fa82a',1932,'原土匪头目','原土匪头目，被日军收编，任辽阳地区伪保安队队长，多次参与围剿抗日义勇军，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6d6b0aab3624e529883b40c845338c3','f4820712-9291-4edd-99e8-c066e04c80d4',1931,'原洮辽镇守使','原洮辽镇守使，九一八后投敌，在辽阳、辽西一带协助日军进攻抗日武装，后任伪热河省长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32cc2134eb4e41c48336e8365a5a60ac','420a564b-c611-46eb-aa94-4b065a2bc347',1933,'精通日语','精通日语，为日军宪兵队充当翻译，参与抓捕、刑讯抗日志士，民愤极大。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc20ee995e444637a41bdab2741e5157','5472df28-934d-4982-bc8f-19ae8dd527d1',1935,'在辽阳宏伟地区（当时为农村）任伪警察署长','在辽阳宏伟地区（当时为农村）任伪警察署长，强征劳工，镇压反抗，为日军提供情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db7280af25ba4e1b8a655db94b5796f3','6bb340c9-aa1f-4fef-ad5a-eaecae7330a7',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪奉天省省长，参与镇压辽宁抗日义勇军，推行日伪殖民统治，在辽阳、弓长岭一带协助日军“讨伐”抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b4703637078475da26adbeae415f728','37067d34-363e-44ab-9389-08c24245bea3',1931,'原洮辽镇守使','原洮辽镇守使，九一八后投敌，多次率伪军配合日军在辽宁东部（含辽阳、弓长岭山区）围剿抗日义勇军，烧杀抢掠。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e82733d8d8cb4769b1043cef10471925','bcc3d779-3975-486c-a57a-af16920ddeb9',1932,'投日后任辽阳县伪县长','投日后任辽阳县伪县长，推行保甲制度，强征劳工，为日军在弓长岭铁矿提供劳力和物资，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26bee4a2f5ae4a97bad91ef438c2b61f','c4eaf76c-588f-4274-8d47-87f3e07b36e0',1931,'原奉系法律人士','原奉系法律人士，投日后任伪立法院院长，参与制定伪满洲国法律，为日本殖民统治提供法理依据，其家族在辽阳有产业并协助日伪征粮。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab404e2619574142a4187caf3490199e','3843da08-0c69-429e-9802-03399c1b68b6',1937,'继于芷山后任伪奉天省长','继于芷山后任伪奉天省长，管辖辽阳、弓长岭地区，推行“粮谷出荷”政策，强征农民粮食，支持日本对弓长岭铁矿的掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59281d0c80bf4b27aa709028aa768737','483348c7-6d8d-4f0d-a481-3330822dafa3',1933,'在辽阳、弓长岭一带任伪警察署长','在辽阳、弓长岭一带任伪警察署长，多次带队抓捕抗日地下党员和义勇军家属，刑讯逼供，协助日军建立“无人区”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f38470729e4d4d379ba1abdb191390d8','1076ed2d-10b7-4111-928f-568b39081587',1932,'负责辽阳、弓长岭地区特务工作','负责辽阳、弓长岭地区特务工作，发展汉奸密探，破坏抗日组织，曾参与逮捕多名抗日志士并移交日军处决。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0fbd743a9224609b3ba8c1e44e2484d','badd4cf2-e516-40fb-af6d-cd3eb90f76f7',1931,'投靠日伪','投靠日伪，组织商会为日军筹集军费，强迫商户“献金”，并协助日军在弓长岭矿区征用民夫，从中牟利。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17684fdfe165463ab2b53bcd4d175329','d20514cf-32c3-4dd2-87e0-7ca03f537fb4',1938,'任弓长岭铁矿矿警队长','任弓长岭铁矿矿警队长，残酷镇压矿工反抗，克扣工资，殴打致死多名矿工，并协助日军封锁矿区消息。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4354c81c1af2454a975e64dcff3978a8','eaa2fc55-276f-4c1b-9360-1d734884d0bc',1932,'在辽阳、文圣一带担任伪警务要职','在辽阳、文圣一带担任伪警务要职，协助日军搜捕抗日志士，破坏地下抗日组织，参与“治安肃正”行动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16bb6b5726ed4768b6edaa9142f76016','bba5605a-8c29-4a68-ae4e-df2d015b1ab5',1933,'任伪辽阳县县长期间','任伪辽阳县县长期间，强制推行“保甲制度”，强征劳工，为日军提供物资，并参与镇压辽阳地区抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9b37135cf664533a4d3697090448267','f07d53fc-c3ef-4fbe-9ea6-f1bc7677516b',1937,'为日军宪兵队充当翻译','为日军宪兵队充当翻译，参与审讯和刑讯抗日人士，直接导致多名地下党员牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3961f7a5970a45f78a8f279222167bcb','16c6ba26-506e-4139-827d-1d1f41c8fc31',1931,'在辽阳文圣区组织维持会','在辽阳文圣区组织维持会，协助日军建立秩序，强征民夫修筑军事工事，并告密抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c898ae2ac0f4e1fa8ae28d3dd25bacb','f89aad07-631b-4947-af15-1ceabd73a9d0',1931,'清末民初政客','清末民初政客，九一八后投敌，参与策划伪满洲国成立，任伪参议府议长，为日本殖民统治出谋划策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2c11ccdc82f45b8849dd5d75b7f6cfc','ac3e0117-98b5-4a87-a81f-bd4f87239e25',1931,'原辽宁省政府主席','原辽宁省政府主席，九一八后被日军软禁后投降，任伪奉天省省长，推行日伪各项反动法令。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8680661e064b46ee85a32734c8c8cdac','9ee57a93-ddbc-4cfe-bef3-1582811c5111',1931,'原吉林副司令长官','原吉林副司令长官，九一八时投降日军，参与建立伪满，任伪财政部总长，为日本掠夺东北资源效力。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86cdd612ca7a435cb70addb0e2132a4f','9deafc19-4b71-409c-8ab3-4c0fc9412fb7',1931,'原奉天交涉员','原奉天交涉员，投日后历任伪满外交部长、驻日大使，协助日本控制伪满外交，签订卖国条约。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a832d7ff5e5e49ac952db51c663d6da4','7c250488-fcb5-4a30-8443-b5a141488920',1931,'原东三省官银号总办','原东三省官银号总办，投日后任伪满中央银行总裁，发行伪币，搜刮民财，支持日本战争经济。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cc22aa2c50f4fa288dd2e5d199f0c6e','8610bd59-892e-467e-8e30-04995e9e5346',1931,'原吉林旗人','原吉林旗人，投日后任伪满首都新京市长，协助日本建设殖民统治中心，镇压反满抗日活动。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3dbfd84ab2043068f119592cf3ba4ce','8610bd59-892e-467e-8e30-04995e9e5346',1931,'原吉林铁路局局长','原吉林铁路局局长，投敌后任伪满高官，曾负责伪满“治安肃正”工作，多次到黑龙江绥化地区督导“清乡”行动。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f25ea940a45348b4bf66e17ed6784e52','2c8e81d8-ce0e-4dd8-8e29-edcf9b1b7a87',1931,'九一八后投靠日军','九一八后投靠日军，任伪辽阳县县长，推行日伪保甲制度，强征劳工，镇压当地抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f47e70fc35ef4dd394629b4eced68031','3996d8e7-6c35-465e-b03f-c28d60ef09ab',1931,'任伪辽阳警务局长','任伪辽阳警务局长，协助日军搜捕抗日志士，破坏地下抗日组织，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56685b43eedf40a0822c3193534754e1','63bf1ff8-5637-46c1-b3a1-60a8859dbc38',1931,'原洮辽镇守使','原洮辽镇守使，九一八后率部投敌，任伪热河省长，参与镇压辽西、辽北抗日义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6880fd904f414f2ea3d715619b1b2ead','33626658-919f-46dc-bea4-37bba5f72c18',1931,'原吉林省财政厅长','原吉林省财政厅长，投日后任伪满财政部大臣，协助日本控制东北金融，推行经济掠夺政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aab18b8bc4da4315a6e1179d4d4f78f7','e605549e-bc34-4c63-88de-7e61b9944988',1931,'原奉天商会会长','原奉天商会会长，投日后任伪满实业部大臣，为日本垄断东北工商业，出卖民族经济利益。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-521cae950a0242af8893c99aa3e79994','6311f9de-d2e1-437e-a4ad-ae541e526174',1932,'原黑龙江抗日将领','原黑龙江抗日将领，1932年一度投日任伪黑龙江省长，但不久反正抗日，故其汉奸身份短暂且存在争议。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47b2e5654ebb4cfcb431b7656f54676d','9b8016be-b1f1-4b6f-b1fe-79fe41467796',1931,'九一八后组织辽阳地方维持会','九一八后组织辽阳地方维持会，协助日军维持秩序，征收捐税，为日军提供物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8dfbaa6f4f7490c8999aa03592679a6','628883d0-052a-4325-9bef-d85c27f5bad0',1931,'九一八事变后投靠日本','九一八事变后投靠日本，任伪奉天省省长，协助日军维持殖民统治，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49eee90818dd477ea532afc94140269c','34452311-e3b2-4197-9a88-44a966657551',1931,'曾任伪满参议府议长','曾任伪满参议府议长，积极参与伪满政权建立，为日本侵略政策服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b94d7ec28edf4bbd8f99f7c6553b4ef6','34452311-e3b2-4197-9a88-44a966657551',1931,'曾任伪奉天省省长','曾任伪奉天省省长，后任伪满参议府议长，积极为日本侵略政策服务，参与伪满政权建设。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76fd217496a142208ea9c066678390c4','8e6a01a6-9c02-4d34-8527-0655ed959e7b',1935,'原奉系将领','原奉系将领，后投敌任伪满国务总理，全面配合日本对东北的殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13fa5f8f74404b4eb39c8e0b0c060c49','8e6a01a6-9c02-4d34-8527-0655ed959e7b',1935,'曾任伪满军政部总长','曾任伪满军政部总长，后任伪满国务总理大臣，全面配合日本对东北的殖民统治，包括鞍山千山地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9f00054e4544c05a72a8c2e970b1f1a','40ee7ce5-e3e8-4edd-aa53-6fbe8eca0128',1932,'继于冲汉后任伪奉天省省长','继于冲汉后任伪奉天省省长，推行日伪政策，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5fc8de0b7fd048b08414e119b39e5453','40ee7ce5-e3e8-4edd-aa53-6fbe8eca0128',1932,'继于冲汉后任伪奉天省省长','继于冲汉后任伪奉天省省长，推行日本殖民政策，协助日军清剿抗日义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67fa66f6220645a19eebb656a3566027','076262e4-ef5a-48b8-ab55-c468a69108f9',1931,'九一八后组织辽阳地方维持会','九一八后组织辽阳地方维持会，协助日军维持秩序，征收捐税供日军使用。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0b94aee6a0342449d1d6f2f52f9a3ae','9ab8d74c-3757-44a1-8aab-15cea9001597',1932,'任伪辽阳县长期间','任伪辽阳县长期间，强征民夫修建日军工事，搜刮粮食资敌。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca64ca06ec734d3a9f396791cfc1abb2','cdabd838-0e0f-4181-97f5-0ae800eadc8c',1932,'参与伪满立法','参与伪满立法，为日本殖民统治提供法律依据，曾活动于辽阳一带。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d069fd21bf0f432f817e1c65efaa94a4','cdabd838-0e0f-4181-97f5-0ae800eadc8c',1932,'曾任伪满立法院院长','曾任伪满立法院院长，参与制定伪满法律，为日本侵略合法化服务，活动范围涉及辽宁各地。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-416f90da17454b79a0d2fc2f4569e9c6','fc177253-68e9-47ab-a752-cab6130a461b',1933,'原东北军将领','原东北军将领，叛国投敌，在辽阳等地协助日军清剿抗日义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1b66c9d5d634a019e515545a2d0056e','7dd3999e-da82-46d5-af6f-13a118851cdb',1932,'率伪军驻防辽阳、鞍山地区','率伪军驻防辽阳、鞍山地区，多次参与“讨伐”抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91f2a77b980a4dafa0da336ac567ae14','7dd3999e-da82-46d5-af6f-13a118851cdb',1932,'驻防辽宁地区','驻防辽宁地区，指挥伪军多次进攻千山抗日根据地，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfbe3c7305cd42d885f605c1b6cc0496','66a5fdd9-be05-4dfa-b846-d735837b0cd1',1932,'指挥伪警察在辽阳白塔区一带搜捕抗日分子','指挥伪警察在辽阳白塔区一带搜捕抗日分子，实施白色恐怖。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ef6305c6d15471d9eb4377673ecf9b8','33ba7d1d-e07b-4201-b5c4-80cb703e75ac',1932,'负责伪奉天省（含辽阳）警务','负责伪奉天省（含辽阳）警务，协助日军建立保甲制度，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36b9871375da481cbc7d429af95bc91e','3f225da2-5105-4b8a-a6b3-6eaef0a0d2dd',1932,'原东北军将领','原东北军将领，投敌后任伪军政要职，参与策划对辽阳地区抗日力量的围剿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fb38afb7d004c08ab4945b5a80b1191','f5c0480d-a35f-4c13-bf4b-3c0412c2ce97',1932,'任伪铁岭县长期间','任伪铁岭县长期间，强征民夫修建日军工事，推行保甲制度，协助日军掠夺粮食资源，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7112f9aacf7641208cfc5ef850a201ac','f5c0480d-a35f-4c13-bf4b-3c0412c2ce97',1932,'任铁岭县县长期间','任铁岭县县长期间，强征农民粮食和劳工，为日军提供物资，并配合宪兵队镇压铁岭地区的抗日反满活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-69a98d4c5c524b8bb44ef43bf4d8e25a','299873de-31b0-4ea1-9556-1c068dabe509',1933,'在昌图（今属铁岭市）任伪职','在昌图（今属铁岭市）任伪职，积极为日军提供情报，组织汉奸武装“自卫团”，参与围剿抗联杨靖宇部。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cfdc8b5379e42c2be31ddddf43b209e','bbb34474-730b-4012-80b2-f328acee2217',1931,'原辽宁省政府主席','原辽宁省政府主席，投敌后管辖铁岭地区，推行“粮谷出荷”政策，导致当地百姓饥荒，并协助日军清剿抗联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-527f8eb2227f4148bb892d06f9349398','a34d54cb-2af7-40eb-9e93-75cac46e9c68',1932,'在铁岭、开原、西丰等地建立特务网络','在铁岭、开原、西丰等地建立特务网络，抓捕抗日志士，严刑逼供，制造多起惨案。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f3e4abf956d41609f5e13d8f6ff83c5','2709ca42-c0ba-4ee8-ba19-1529ad7d31aa',1932,'利用协和会组织在铁岭宣传“王道乐土”','利用协和会组织在铁岭宣传“王道乐土”，强迫民众参加“日满亲善”活动，检举抗日分子。','危害等级A（甲级，省部级/大军区级要员）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-321d0489be3a46f198ccbc1025bf3c3c','69ca7a1e-8982-4edd-b43a-a297f54ca3ca',1932,'原铁岭地方士绅','原铁岭地方士绅，伪满成立后出任铁岭县县长，为日军征粮派夫，镇压当地抗日活动，强推“保甲连坐”制度。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-161343dacffe470bbfe4a238e75481aa','0a47af15-0955-43fa-89f1-d576979f8141',1932,'原开原县商会会长','原开原县商会会长，投日后任开原县县长，协助日军建立伪警察队，多次参与围剿抗日游击队，并强征劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b72b6e0d47954d1d93ffc846a8e87547','17e8ed28-18c0-4a8c-83ca-3e459459641c',1933,'原铁岭地方武装头目','原铁岭地方武装头目，投日后任伪警备司令，在铁岭、开原一带抓捕抗日志士，制造多起屠杀事件。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a219a8b54834fae87597f008b58c92c','fd998425-b824-4a3d-a1a7-368daea012e6',1931,'原奉系政客','原奉系政客，投日后参与伪满政权，在辽宁地区（含铁岭、开原）为日军出谋划策，协助建立地方伪组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e597c0c199da407985106133fa173125','438ae06a-45e9-4882-86bc-593549d0e059',1932,'原铁岭县警察','原铁岭县警察，投日后任伪警察署长，直接指挥抓捕抗日地下人员，多次参与“讨伐”行动，民愤极大。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb5b9f7a76bd4c72a5c2ee61818c7b52','14770084-76e1-43d2-b840-da7c32f13ed3',1935,'原开原县地主','原开原县地主，投日后任协和会会长，宣传“日满亲善”，强迫民众参加“勤劳奉仕”，为日军搜集情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d482e4cf1cf74600b26e56e1e097b6f1','c8b046ad-30ed-46ac-99e3-caa96a8bcf24',1933,'原铁岭县土匪头目','原铁岭县土匪头目，被日伪收编后任保安队长，在铁岭、开原交界处多次袭击抗日游击队，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46c0ab04a3c242aba40538da39ff818e','d3d1d9d7-b37c-45e2-911e-84cdd42c5e23',1934,'原开原县警佐','原开原县警佐，投日后任警务科长，负责“治安肃正”，逮捕并刑讯抗日群众，参与“集团部落”建设。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd8a6a81372a40f09405a65251ed8a9f','a31539a8-27cb-46a8-9809-cae299af4d26',1932,'原铁岭县教育界人士','原铁岭县教育界人士，投日后任伪教育局长，强制推行日语教育，篡改历史教材，毒化青少年思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cfe83c54cd641bc8b050a0d28dc6c0e','a596cee6-d1fb-4c40-8e82-3b0ac8f23776',1932,'原开原县民团头目','原开原县民团头目，投日后任自卫团长，配合日军“扫荡”，烧毁村庄，强征壮丁，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d61451aa1d3b4755bdb5a5dd41cb0cd1','7c6372e9-7056-4500-b4bb-32f0b61edb69',1931,'原铁岭县士绅','原铁岭县士绅，九一八后组织维持会迎接日军，后任伪职，为日军征粮派款，协助稳定伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-810aa7eacf644651bdbf6122df3c1d7a','4dfbf04c-ab2f-4beb-af12-4f19383aeecb',1932,'原辽宁实业界人物','原辽宁实业界人物，投日后任伪实业厅长，在铁岭、开原等地推行经济掠夺政策，垄断粮食和矿产。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c8deb09e5814edca0f7f25e8f9524ad','c256db8f-2af0-4edb-92da-9a64a2ba5ead',1933,'原开原县司法人员','原开原县司法人员，投日后任伪法院院长，以“反满抗日”罪名判处多人死刑，为虎作伥。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72713637fb8843e2b6b5858f1c9c38aa','f4be9e84-aa4d-49bd-99ba-56a5196d6258',1936,'原铁岭县商人','原铁岭县商人，投日后任协和会事务长，组织“青少年团”，灌输军国主义思想，协助日军征兵。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f93e320d714742fc9cbcbe6200a9ec04','c04d9cd7-f271-4bfa-b0b9-1d6ab6b8b482',1931,'原奉系政客','原奉系政客，九一八后投敌，任伪奉天市市长，协助日军建立殖民统治，后任伪满立法院院长，参与制定奴化政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed448e2b65f5414a8c24edaed245bdf8','c04d9cd7-f271-4bfa-b0b9-1d6ab6b8b482',1931,'原奉系法律人士','原奉系法律人士，九一八后投敌，任伪奉天市市长，后升任伪满立法院院长，在辽宁及鞍山地区推行日伪法律，镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccde956c41cd42b68a1f44afe74449fd','c04d9cd7-f271-4bfa-b0b9-1d6ab6b8b482',1931,'曾任伪满奉天市市长','曾任伪满奉天市市长，后升任伪满立法院院长，在辽宁地区（包括鞍山铁东）推行奴化教育和经济掠夺政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3852feb3b01e48719ceaf6928d0f5398','c04d9cd7-f271-4bfa-b0b9-1d6ab6b8b482',1931,'曾任伪满奉天市市长','曾任伪满奉天市市长，管辖包括鞍山、铁西在内的地区，推行奴化教育，镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfc9d6db52a64f2388afc716750fe4c0','ceb4458e-acb0-49b4-ac9b-7634b7fec8c4',1931,'原东北军文职官员','原东北军文职官员，投日后历任伪满要职，任伪奉天省省长期间，推行日伪“治安肃正”，在铁岭、昌图等地强征劳工、掠夺粮食。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbc41d9b4a084e00868172e4279a7c5a','ceb4458e-acb0-49b4-ac9b-7634b7fec8c4',1931,'原东北军文职官员','原东北军文职官员，投敌后历任伪满奉天省省长，管辖铁岭、银州等县，推行日伪“治安肃正”政策，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54d63594b96a46c7bc2222d1250b3aeb','cd242bfe-bcb3-4f47-bbdb-b363e38be7e3',1932,'铁岭本地士绅','铁岭本地士绅，投日后任伪铁岭县县长，协助日军建立保甲制度，强征民夫修筑公路和军事工事，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31492dc733074ad6aabb65f5cbc0a8fd','cd242bfe-bcb3-4f47-bbdb-b363e38be7e3',1932,'原铁岭地方士绅','原铁岭地方士绅，投日后任伪满铁岭县县长，协助日军建立保甲制度，强征劳工，搜刮粮食，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-195595eace85468495022a370f1d20af','4574547f-0d75-4fd7-8bd5-a5feb6417cd3',1932,'原昌图地方官员','原昌图地方官员，投日后任伪昌图县县长，推行日伪“归屯并户”政策，制造无人区，配合日军清剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b7f00fc31c2471a94bed1be514e2ff2','ff3bb221-b335-44b7-8ac4-e8465fd8deb1',1931,'原吉林教育厅长','原吉林教育厅长，投日后任伪满民生部大臣，推行奴化教育，在铁岭、昌图等地设立日语学校，强制灌输“王道乐土”思想。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38d750696156498b98689b896d7da900','90d45997-b53f-4c41-a331-e795a3f20603',1932,'铁岭本地警察头目','铁岭本地警察头目，投日后任伪铁岭警务处长，组织伪警察队，多次参与“讨伐”抗日游击队，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fded405bafc8406a81101701e125d796','0449702b-69f3-476a-9ff9-9d275950777c',1932,'昌图地方恶霸','昌图地方恶霸，投日后组织伪保安队，配合日军扫荡，在昌图北部制造多起惨案，强抓壮丁补充伪军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0f8c28c809d448686cbce54680f39f3','72594f6f-80eb-4d9f-b036-ad4096a4b066',1932,'原奉天教育界人士','原奉天教育界人士，投日后任伪奉天省教育厅长，在铁岭、昌图推行殖民教育，篡改历史教材，禁止中国传统文化传播。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44e3ae2e48054bdc89d397811781b089','498cadbb-850f-44ad-84fd-cc5cf25c3941',1933,'铁岭县伪警察头目','铁岭县伪警察头目，积极执行日伪“治安肃正”计划，在铁岭城乡设立检查站，逮捕抗日地下工作者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d6f2a0114aa4fee90785ec6b6555c49','5dfd2821-7844-4bd2-bc5f-660210e4a06f',1934,'昌图县协和会头目','昌图县协和会头目，协助日军进行思想宣传，组织“勤劳奉仕”运动，强迫当地农民为日军服劳役。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbd3f3450fcf43e2bdb94b3c5e5d4e63','8d49a315-2364-42c1-8af6-836d94781f85',1932,'在清河地区协助日军‘讨伐’抗日武装','在清河地区协助日军‘讨伐’抗日武装，抓捕抗日军民并刑讯逼供，参与制造多起惨案。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a110002e30af450bb93e30159cb175d3','74da56d2-e284-44d5-82c1-796fbe67ddf2',1933,'早年投靠日军','早年投靠日军，后任伪满热河省省长，在清河地区有田产，曾协助日军清乡，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae07b67b08e848d48d9c140d2e691f56','1c3f2e59-b949-4915-b695-ddf252fe02e3',1932,'虽主要活动在伪满中央','虽主要活动在伪满中央，但利用其铁岭清河籍贯影响，为日军在清河地区推行‘治安肃正’出谋划策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-88f6872e273b460f95998f0223091627','072eb555-a83b-4368-aac2-d2b535709714',1931,'九一八事变后','九一八事变后，在铁岭清河一带组织地方维持会，为日军提供粮秣和情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5050c9a8ef6443f08f6dd0966fd2b838','d8080499-35ca-4597-8d62-6aab1d57e057',1934,'在清河城子一带强征劳工','在清河城子一带强征劳工，抓捕抗日嫌疑犯，并直接参与日军对清河沟游击队的围剿行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5b66bc771974b4ba26813094725c294','e2f54f00-d478-4f18-995d-003999cc89e5',1937,'组织汉奸自卫团','组织汉奸自卫团，配合日军在清河沿岸设卡盘查，多次袭击抗联小分队，杀害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-925bd9fe6b8d45c7b51dbcae86ebc171','f6d2e459-ce24-48ec-bfec-78c117f4cee4',1938,'推行伪满‘保甲连坐’制度','推行伪满‘保甲连坐’制度，强迫村民报告抗日分子行踪，并贪污勒索百姓，为日军征收军粮。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-907efde484bb470ca7988a7b7187186d','ac7762a8-7673-4d5d-9a90-1872016fbcf9',1940,'化装成商人刺探抗联情报','化装成商人刺探抗联情报，多次向日军告密导致清河地区地下交通站被破坏，多名抗日志士被捕。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0068f050ca84786b0c1ca526af78ca4','d31754be-e7fe-4da4-b4ea-1ab11bca352f',1941,'专门负责‘思想犯’侦缉','专门负责‘思想犯’侦缉，在清河地区逮捕进步教师和学生，酷刑审讯后移送抚顺监狱。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e4370a1658a49e6998a7739a2074513','81efd378-df9b-4bd6-893f-f1ff033af7f3',1935,'利用协和会组织宣传‘日满亲善’','利用协和会组织宣传‘日满亲善’，诱骗青年参加伪军，并协助日军在清河地区进行‘归屯并户’。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26682e9bc5f74bdc92355743880cd596','121fe1f4-2a3f-46e4-abfb-f09eab1bdc2c',1932,'任伪满西丰县县长期间','任伪满西丰县县长期间，积极推行日伪殖民政策，强征劳工，镇压抗日活动，协助日军搜捕抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6d5d7c3b90149b49bea82b5ce61a86c','13394699-a01e-42c2-bcc8-a6998f6487ca',1933,'原东北军将领','原东北军将领，后投敌叛国，任伪满热河省省长，配合日军“围剿”抗日武装，在热河及辽北地区残害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de9aa59655b04be794a349ab1f178c05','205a108b-311a-434c-b2e0-dcc1fd8168af',1932,'铁岭籍汉奸','铁岭籍汉奸，积极参与伪满政权建设，为日本殖民统治出谋划策，推动“日满亲善”宣传，协助镇压东北抗日联军。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-72ea652b0e3e4ab39c98bc2f57df4de4','d3047bcb-b052-4c1a-a6e2-ffaa1d9f7382',1932,'铁岭籍汉奸','铁岭籍汉奸，曾任伪满监察院院长，积极效忠日本关东军，参与制定殖民政策，协助日军掠夺东北资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c570965fce6e461ebb1fe2d5f455d0a5','c5d6718b-a61c-47db-b090-73aff1e59dc9',1932,'在铁岭地区活动','在铁岭地区活动，任伪满参议府议长，积极推动“满洲国”建国，为日本侵略者张目，参与镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1aff5d62d6a42a6af7db15993ed46bd','5a78dc2c-1c2f-4a81-b176-9a204de4e77a',1933,'西丰籍汉奸','西丰籍汉奸，原奉系军阀，投日后任伪满热河省警备司令，率伪军配合日军“扫荡”抗日根据地，屠杀抗日群众。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cfc8aaf09a324460a65e8a85fecb8464','ca450bcc-f08c-4f6c-99c1-1a4f4d18791f',1932,'在铁岭地区担任伪满铁道守备队司令','在铁岭地区担任伪满铁道守备队司令，负责保护日军运输线，抓捕抗日地下工作者，破坏抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abcfa8ab914c414b862c78e2b188fde4','b02ab98a-5a00-4383-b82c-186667c4828a',1932,'铁岭籍汉奸','铁岭籍汉奸，任伪满奉天省警务厅长，指挥伪警察协助日军“清乡”，在西丰、铁岭等地大肆逮捕抗日人士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7fb1bbd7d29344e4a8b5227d0dc4fb2f','779b80aa-5bea-41e7-9572-9d6181ee3d85',1935,'任西丰县警务科科长期间','任西丰县警务科科长期间，积极执行日伪“治安肃正”计划，多次带队围剿西丰境内的抗日游击队，杀害多名抗联战士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4eeaa0644ccd48e5be9afe703ddfa464','559780ea-7d3f-4ea5-a2a0-4d150c4e621e',1931,'1932年投靠日军','1932年投靠日军，任伪铁岭县县长，协助日军推行“治安肃正”，镇压抗日武装，强征劳工，搜刮民财，为日军提供粮秣和情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5388cd0581543f59221d3918ced1b6a','d667b092-db91-41cc-9fe9-c5ec4ee5bad6',1931,'原奉系军阀','原奉系军阀，九一八后公开投敌，在铁岭、调兵山一带协助日军围剿抗日义勇军，后任伪热河省长，其部队参与对辽北地区的“讨伐”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f975972dc4d463fb4586755cd9709fe','f341ce6a-ae66-41d7-a8a0-a15d89ff6156',1932,'汉奸法学家','汉奸法学家，参与伪满司法体系，对铁岭、调兵山地区抗日人士进行非法审判和迫害，积极为日本殖民统治提供法律依据。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0076019ce1954ff381b51ac7ddf01f58','0204ae65-3a23-4fcc-804f-dddb1ac03d99',1932,'原东北军将领','原东北军将领，叛变后任伪满军第一军管区司令，驻防奉天（沈阳）及铁岭一带，多次指挥伪军“讨伐”调兵山、法库等地的抗日游击队，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ff0658838a04252b567dafa92c67af5','c16b16c9-2ddc-4aae-bdd5-e6e4a196cd0d',1933,'铁岭本地人','铁岭本地人，投靠日伪后任警察署长，在调兵山、晓明镇等地设立情报网，抓捕抗日地下工作者，参与“归屯并户”和“三光”政策实施。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1186f78b04f48e7ba656565f0201ab1','74dda8e5-799a-4360-b12a-e45aebcbcd19',1932,'原土匪头目','原土匪头目，被日军收编后任铁岭保安队长，在调兵山矿区镇压矿工反抗，强征民夫修筑军事工事，并配合日军扫荡周边村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ef6e066d59c40da9d7bb989eb89ad0c','4c44c494-5df0-4d5c-9eb9-eade4070d168',1931,'调兵山（时称“大明”一带）地方士绅','调兵山（时称“大明”一带）地方士绅，日军占领后主动出任维持会长，为日军筹集粮款，出卖抗日义勇军情报，导致多支小股游击队被消灭。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fb8b84c69c04c149c08ed38a7c848b6','c33040c5-0829-4032-ac51-af7c4dabc4e2',1935,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，其推行的“粮谷出荷”、“勤劳奉仕”等政策直接压榨铁岭、调兵山农民和矿工，造成大量平民死亡。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a16ed0eb82914d7d86c22e6f27267253','2b1ec31b-31ef-440c-89c2-c5be18b17a49',1937,'在任期间强化铁岭地区的“保甲制度”','在任期间强化铁岭地区的“保甲制度”，在调兵山一带推行“连坐”，并组织汉奸武装“自卫团”协助日军清乡，掠夺煤炭资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-94273fed3b534388b95cf0bdb98e707a','fad2f77d-6b87-4dad-bd5f-770aea756e13',1938,'铁岭县警务实际负责人','铁岭县警务实际负责人，在调兵山、孤家子等地设立多个警察分驻所，亲自审讯刑讯抗日嫌疑犯，曾一次逮捕并杀害12名抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13d1ddd8e0cb418689019371916462e5','c5af7fb1-aca8-4f9a-9926-50a1b0322a7a',1931,'原东北军营长','原东北军营长，投敌后任伪满奉天省警备司令官，在铁岭、银州一带多次围剿抗日游击队，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc87d78a1026487aaea5128f2a6428ae','a750deef-d429-43bd-9153-1734d96a5575',1933,'原银州（今铁岭银州区）警察','原银州（今铁岭银州区）警察，投日后任伪警察署长，多次参与抓捕抗日地下工作者，严刑逼供，制造多起血案。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93a58db739b94ef5aacf1f9bdeed0d54','fdbebc15-769f-4188-8220-52294dfe33cd',1932,'原铁岭地方武装头目','原铁岭地方武装头目，投日后组织伪保安队，配合日军扫荡铁岭东部山区抗日根据地，烧毁村庄，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b94da9117dac4757a515bd0c3ec1eeda','73afb45e-7541-4cf4-92c6-7d10f006edf7',1931,'原辽宁省主席','原辽宁省主席，被日军俘虏后变节，任伪满奉天省省长，管辖铁岭地区，推行“归屯并户”，切断抗日武装与民众联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-602549702c0c422586b86a55008e2400','73afb45e-7541-4cf4-92c6-7d10f006edf7',1931,'九一八事变后投敌','九一八事变后投敌，任伪奉天省省长，协助日军控制阜新等地区，镇压义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1bc896055b34a1295d5f90c09a6e9ce','1772241d-8e02-44e8-9cd3-f3af01b5c4a6',1931,'九一八事变后投靠日军','九一八事变后投靠日军，任伪满热河省省长，后调任伪满锦州省省长，镇压抗日力量，推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e9d257244134761ac9a3da8eae2f54c','3b34bd40-45aa-46ee-bb79-c0601e545536',1931,'曾任伪满立法院院长','曾任伪满立法院院长，后任锦州省顾问，协助日军在锦州地区实施奴化教育和经济掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc4edf8fa510446b97071fbeb0affcc1','fbdeabbd-ded1-4267-b7b2-c5e742862cc7',1931,'投靠日本后任伪满监察院院长','投靠日本后任伪满监察院院长，曾参与锦州地区伪政权建设，协助日军清剿抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-800478744e7b4803be7f8f2351c7ad4e','8d04b1b5-f76a-4232-b99b-2fc2c48f4be2',1931,'曾任伪满奉天省省长','曾任伪满奉天省省长，后任锦州省高等法院院长，为日军镇压抗日民众提供司法支持。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73cf480af3884437b88c993472149651','fd5e3590-1351-44cf-9176-e42563f193fa',1932,'任伪满锦州省警务厅厅长期间','任伪满锦州省警务厅厅长期间，组织警察配合日军搜捕抗日分子，实施白色恐怖。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b1aed019a5e4628a8856cb4f697d890','fd5e3590-1351-44cf-9176-e42563f193fa',1932,'在锦州地区担任伪警务厅长','在锦州地区担任伪警务厅长，协助日军清剿抗日武装，抓捕地下抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-99b52a424a9a451db7bf1163b6135a9d','2709da26-b4af-4c65-b0e0-f2be44b0b244',1933,'担任伪满锦州省协和会会长','担任伪满锦州省协和会会长，推行奴化宣传，强迫民众参加反共集会。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd14b518f72c475b887e6d44b102c2ea','e068089d-709e-45e3-8803-c0652d681454',1931,'伪满最高汉奸之一','伪满最高汉奸之一，曾参与策划锦州地区“治安肃正”行动，屠杀抗日军民。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f012634255ca4579bef590e5bf858b40','649a0892-dee2-436b-a33e-d3dedb765a9c',1931,'投日后任伪满奉天省省长','投日后任伪满奉天省省长，其辖区包括锦州，支持日军在锦州建立伪政权和军事据点。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e2390681c214654a1e61bfbb0cd6829','b04e8d5c-8d8b-4c1a-a4e6-54eee8f0517e',1931,'伪满核心汉奸','伪满核心汉奸，参与组建伪满军，并协助日军在锦州地区收编土匪武装为伪军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a42912ffaf7a426a999ff1c40d8b5ebd','9770641e-7184-4bd5-af09-e04c775f6c9e',1932,'早期抗日','早期抗日，后一度投日，任伪满军政部总长，其部队曾在锦州地区配合日军行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba4bdfc64d5c43a6bfcd6ddc362614af','8d97e583-a240-4be7-9ae8-9c629ec9b1ca',1932,'任锦州省实业厅厅长期间','任锦州省实业厅厅长期间，协助日本掠夺锦州地区矿产和粮食资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d1e60aebd4bb4649905ac2db6275c327','7b28ab11-08a0-49c3-a1ef-94535324f1ff',1933,'推行奴化教育','推行奴化教育，强制学校教授日语，删除中国历史内容，迫害爱国教师。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33fef4a720d04e2b91e32ae1957e41b6','c32f16a5-ea32-4acd-b2e8-e8cd01e6b78b',1932,'率保安队协助日军围剿锦州抗日游击队','率保安队协助日军围剿锦州抗日游击队，多次制造屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3dfd6e1606a649bcb65005c95e1ad3ed','2119da89-a8e8-4587-a2f1-9450c9d7ed77',1933,'任锦州宪兵队长','任锦州宪兵队长，严刑拷打抗日志士，参与“三光”政策实施。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b27db8d3dce4471b902a52c497c8cb3','64447979-3b26-4076-940c-b07052c170eb',1931,'原土匪头目','原土匪头目，投日后被编为伪军，在锦州地区烧杀抢掠，破坏抗日根据地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d55a027dd5054c9d8bba7844a95bf853','68347f34-102b-42ca-9e96-dc184bc535a2',1934,'指挥警察抓捕地下党员','指挥警察抓捕地下党员，破坏抗日组织，协助日军进行“大检举”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ead684f1653346e892759f0e560ea381','43544ace-58f6-4e2a-a1e4-48d6567e80e5',1932,'推行“粮谷出荷”政策','推行“粮谷出荷”政策，强征锦州农民粮食，导致大量饿殍。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b7c2036b024482d922debd9f5ce7191','43544ace-58f6-4e2a-a1e4-48d6567e80e5',1932,'负责伪锦州省“民生”事务','负责伪锦州省“民生”事务，实际推行粮食统制，导致黑山地区百姓饥荒，并强征民夫修筑军事工事。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-058bbbd489d3485da2e32779ba884540','4aeab7e5-66ed-4f66-a52c-b75970037b50',1933,'以“反满抗日”罪名判处多名爱国人士死刑','以“反满抗日”罪名判处多名爱国人士死刑，充当日本司法帮凶。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
