INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3aa83d6f661540fe853d0da0ba504bbc','cce32853-7385-4e5a-b319-64a90c005ba2',1931,'在任期间配合日军对锦州、北镇地区进行“治安肃正”','在任期间配合日军对锦州、北镇地区进行“治安肃正”，镇压抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-158dbb614f3a4c43adf7655cb834b596','054a561d-0f1f-46cc-b0f1-edef8b522a9b',1932,'率伪保安队多次围剿北镇、黑山一带的抗日义勇军','率伪保安队多次围剿北镇、黑山一带的抗日义勇军，杀害多名抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cbfce4c3f0c34bf892dd118dab42ecc2','b513c30c-be3d-4d5d-9e1e-38361123ea57',1933,'直接指挥伪警察在北镇县内搜捕抗日分子','直接指挥伪警察在北镇县内搜捕抗日分子，参与制造多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-758a1a67790542b59a86f74d7c88e25f','5a218c90-457b-47fd-92a5-8fec09050500',1934,'利用协和会组织在锦州、北镇地区进行奴化宣传','利用协和会组织在锦州、北镇地区进行奴化宣传，强迫民众参加“日满亲善”活动。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f925a919b5f3447dbf83146f7d955235','2d765bad-9ac6-48e0-b131-203a9304647a',1931,'日军占领北镇后率先组织维持会','日军占领北镇后率先组织维持会，为日军提供粮草和民夫，协助建立伪县署。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52f5ee68c0544c33a707cef5ddce41bb','5f365a02-a292-4ac4-8ccb-acc8de20e764',1937,'在锦州地区推行日语教育和奴化课程','在锦州地区推行日语教育和奴化课程，删除抗日内容，迫害爱国教师。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b59aa3c5e42c42e0aca6d3c44e523455','f4ad0e52-eda2-4d94-805a-f73c8d1e73c2',1932,'1932年曾一度投敌','1932年曾一度投敌，在锦州地区与日军合作，但不久反正，此条仅记录其投敌期间行为。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4883cb9f34ad48ac88109b2f29076dab','a34d68f1-8971-41a5-9548-ed7ee471271b',1931,'在辽宁地区（含锦州、古塔周边）推行日满协和会','在辽宁地区（含锦州、古塔周边）推行日满协和会，组织“宣抚”工作，协助日军清乡，破坏抗日地下组织。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92e5327ba72342b4b4cfcb375302e1e2','90adcfd7-f3b1-4f4f-9ce4-7b4d7a7cc043',1931,'作为汉奸政客','作为汉奸政客，在辽宁各地（包括锦州）为伪满政权网罗旧官僚，参与制定奴化教育政策，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f90dbfa154494f1ba46bc7cb2758ae99','8aa85d0b-5612-4919-acfe-09ef8b05527e',1934,'在锦州、古塔地区主持伪省政','在锦州、古塔地区主持伪省政，推行日伪“治安肃正”计划，强征劳工，配合日军对辽西抗日根据地进行“围剿”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f31fb15cc3034ae4b4b3eb9b5e9a87cf','7060e1e8-4418-45d1-b36e-187bc5824f98',1931,'虽主要活动于吉林','虽主要活动于吉林，但曾参与对锦州地区伪军的整编和训练，为日军在辽西的军事行动提供支持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd711bd77bf9469a8924840b1a2eacaf','78d62fa8-87b9-4489-af4c-966005499d16',1934,'在古塔地区推行奴化教育和“勤劳奉仕”制度','在古塔地区推行奴化教育和“勤劳奉仕”制度，强征青年为日军服务，协助日伪进行思想控制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8f739bb12b64dc3980d92d2264ef362','0210f258-6bc0-47a2-b53a-44e883fdcb94',1931,'辽宁沈阳人','辽宁沈阳人，九一八事变后被俘投敌，历任伪奉天省省长、伪满洲国民政部总长等职，参与伪满政权对辽宁地区的统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e716aa1d750640e6ae822d5e3b634024','0210f258-6bc0-47a2-b53a-44e883fdcb94',1931,'被俘后投敌','被俘后投敌，历任伪满民政部总长、伪奉天省省长等职，参与伪满政权建设，其政策影响涉及黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b07fbb3ce7440bb878dd2d094db45d9','0210f258-6bc0-47a2-b53a-44e883fdcb94',1931,'原辽宁省主席','原辽宁省主席，九一八事变后被日军扣押，后投降并出任伪奉天省省长、伪满民政部总长等职，参与伪满殖民统治，对东北包括黑龙江地区的伪政权运作有重要作用。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc1108e96462448baab6ce3817381dff','0210f258-6bc0-47a2-b53a-44e883fdcb94',1931,'被日军俘获后投降','被日军俘获后投降，历任伪奉天省省长、伪民政部总长等职，参与伪满政权建设，推行日伪法令，镇压抗日民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01bb8d87ecdb44a0b9827f9883b330c4','026d74dd-a67d-412f-90d1-ad4bbd946a04',1931,'辽宁人','辽宁人，原东北军将领，1931年投敌，历任伪吉林省省长、伪第四军管区司令等职，参与镇压辽宁、吉林抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a5d11f19d9a441fbdd9d92956de1e0e','ec22d305-b3fa-448a-ad50-b04517c9efde',1931,'辽宁沈阳人','辽宁沈阳人，清朝宗室，九一八事变后投敌，历任伪吉林省省长、伪财政部总长等职，为伪满政权重要成员。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11ad3d7f101b4539bc1dfde02f4b60b7','ec22d305-b3fa-448a-ad50-b04517c9efde',1931,'九一八事变后率先投敌','九一八事变后率先投敌，主持伪吉林省军政，配合日军侵占黑龙江等地，为伪满初期重要汉奸之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0425e34e5924f96a4e9ea2c0d8dd13e','ec22d305-b3fa-448a-ad50-b04517c9efde',1931,'九一八事变后率先投敌','九一八事变后率先投敌，以吉林省军政长官身份迎接日军进入吉林，后任伪满财政部总长、伪吉林省省长等职，积极参与伪满政权建设，其影响波及黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d796fad3d83f424ab6ca46a5102d3b25','ec22d305-b3fa-448a-ad50-b04517c9efde',1931,'九一八事变后率先投敌','九一八事变后率先投敌，协助日军侵占吉林，后任伪满财政总长等职，为日伪政权筹措资金，支持殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ff055c16dbd491d9f946f6fd92a620d','e853649a-88c7-4a93-9373-4d8d11929a57',1931,'辽宁人','辽宁人，九一八事变后投敌，曾任伪锦州省省长，直接参与锦州地区伪政权统治，后任伪交通部大臣。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
