INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f71d839b85042ba8d7947c1e8424f82','45f0e453-5903-4366-9b8e-7b560d14bede',1931,'辽宁锦州人','辽宁锦州人，九一八事变后投敌，任伪锦州省警务厅厅长，负责锦州地区治安与镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
