INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2833e9a82d034c5bb5cdff5b00b29a41','69fd1cfe-c42e-4655-9861-ed1bbda60743',1932,'协助日本皇室和财阀侵占阜新地区土地和矿产资源','协助日本皇室和财阀侵占阜新地区土地和矿产资源，破坏当地经济。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
