INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e6680d7b688149fe82f7deebb4a6b66c','27bd7578-90fd-493d-80b3-86ef012f894c',1931,'九一八事变后投敌','九一八事变后投敌，率伪军配合日军进攻辽西、热河，其部队活动范围覆盖阜新周边地区，参与镇压抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4305f65e68c7456baf3de2c02272eb64','27bd7578-90fd-493d-80b3-86ef012f894c',1931,'原为东北军将领','原为东北军将领，九一八事变后投敌，参与进攻黑龙江、热河等地，其伪军活动范围覆盖辽西、阜新周边地区，配合日军镇压抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10cd19d1fd5647a39b4304666a196394','12ac29a9-23af-413f-8c03-42944bf2444e',1932,'率伪军在辽西包括阜新、新邱一带执行治安肃正','率伪军在辽西包括阜新、新邱一带执行治安肃正，镇压抗日民众，强征劳工。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c4045e0c0e841d0a06f6c154c799d71','12ac29a9-23af-413f-8c03-42944bf2444e',1932,'原东北军军官','原东北军军官，投敌后任伪军司令，在辽西阜新、朝阳地区配合日军扫荡抗日义勇军，强征劳工、掠夺资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9592c92f6f2a43bb8c6aec58245dfca1','bb17bf35-2d4e-4e00-9c7a-489368bb1a70',1931,'原东北军军官','原东北军军官，投敌后率部在辽宁西部及阜新周边进行扫荡，残害抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a9da629727b45f7851a6556a3182551','bb17bf35-2d4e-4e00-9c7a-489368bb1a70',1931,'原东北军军官','原东北军军官，1931年投敌，率伪军在辽宁东部及辽西地区围剿抗日武装，其部队曾活动于阜新、彰武一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af5cfb1c97d4488389ee4be07de2d417','ff2a3c6b-ce2f-411d-9269-88f1bdcbe00b',1931,'积极参与伪满洲国建立','积极参与伪满洲国建立，在辽宁推行殖民统治，其政策影响包括阜新在内的辽宁各地。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-660a011715ff4477ad37a56721f9f766','ff2a3c6b-ce2f-411d-9269-88f1bdcbe00b',1931,'九一八事变后投敌','九一八事变后投敌，参与伪满建国活动，任伪奉天市长期间在辽宁地区推行亲日政策，其活动涉及阜新周边。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5a9f063095945beb345540411dbe0a1','6a4d6fa9-8d43-4bca-ab57-86b96d5fe3f3',1931,'原辽宁省主席','原辽宁省主席，被俘后投敌，任伪奉天省长期间推行保甲连坐，镇压辽宁抗日活动，阜新地区亦在其管辖下。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46af5b3237994201bcfc888d3f226dae','6a4d6fa9-8d43-4bca-ab57-86b96d5fe3f3',1931,'原辽宁省主席','原辽宁省主席，被俘后投敌，任伪奉天省长、伪满民政部大臣，参与推行殖民统治，其政策影响黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c0466af15a4f45f38cd37eda43a071d5','24082c1c-febc-4dd9-bd67-7be99862a25f',1930,'任伪阜新县县长期间','任伪阜新县县长期间，配合日军征粮、征劳工，推行保甲制度，镇压当地抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-310957dc9efa44eea249892e2efbf170','a6ed65cc-495c-4ff8-a09d-1fb41623bf7d',1931,'九一八事变后组织阜新县维持会','九一八事变后组织阜新县维持会，迎接日军占领，协助建立伪政权，搜捕抗日人士。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-52c08949ef2d42e6ac843006c3b56a45','7ad8c8e5-b148-44e3-9ca9-d7f8289b2552',1930,'在新邱煤矿区担任伪警备队长','在新邱煤矿区担任伪警备队长，残酷压迫矿工，配合日军镇压矿工反抗，抓捕抗日地下工作者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f4ac139e4dd42dda74cbf9c7a5c2e6f','b6dea5a4-a337-45dd-820f-606869533e21',1936,'负责新邱等煤矿劳工征募与管制','负责新邱等煤矿劳工征募与管制，虐待劳工，强制劳动，导致大量矿工死亡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d291d79d022e4003a6da1de2b47a033f','c20be7e4-0310-41d0-9fdc-5c5732d17ce7',1930,'在阜新县及新邱地区执行治安肃正','在阜新县及新邱地区执行治安肃正，抓捕抗日人员，刑讯逼供，残害百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a27e60132d84d4882c79d46298bf7d0','34c2e052-f027-4981-9907-219a96900fec',1930,'率伪军在阜新、新邱一带围剿抗日武装','率伪军在阜新、新邱一带围剿抗日武装，烧毁村庄，杀害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df3c30f5e42d467ba8b408ffe076696a','6de65a9a-23e8-45e4-b13b-c63f53647284',1930,'在阜新推行协和会运动','在阜新推行协和会运动，进行奴化教育，协助日军控制民众思想，检举抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-431fb792a7084432b68775a36984469e','f9b79353-f57a-4133-8a29-43014b9ecab2',1930,'在新邱地区担任保甲长','在新邱地区担任保甲长，为日军征粮、征丁，监视村民，迫害抗日家属。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d51817ca8ffe44798f65a4746ccef7c5','87dea026-c01a-4476-8956-47ee40614a99',1932,'在阜新地区积极协助日本宪兵队镇压抗日武装','在阜新地区积极协助日本宪兵队镇压抗日武装，抓捕抗日志士，推行“治安肃正”政策，强征劳工开采阜新煤矿，造成大量矿工死亡。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2b97a5197ac4110a818721e21c70971','fe4ca3bc-2c6c-4b83-ac72-48c233838813',1933,'原东北军将领','原东北军将领，后投靠日本，任伪热河省省长期间，配合日军对阜新、海州地区进行殖民统治，强征民夫修建军事设施，镇压抗日义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1cedd53f01ae484d80a94c50d3c91ec9','a1070c54-c44f-4293-ab92-3bb184193050',1932,'作为伪满高层','作为伪满高层，参与策划对阜新煤矿资源的掠夺性开采，支持日本“满炭”公司对海州矿区的控制，迫害当地矿工。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1988400a303748f18ce698faffc857c2','1ff0a0f3-7a84-4cb4-8a51-36c12624e9d8',1932,'协助日本关东军管理阜新、海州矿区','协助日本关东军管理阜新、海州矿区，推行“以华制华”政策，组织汉奸矿警队镇压矿工反抗，克扣矿工口粮。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56ef230cfad4426fb879dc003323caf2','68887093-a741-4ec2-8c3d-9cd8829f7399',1932,'负责将阜新海州煤矿的煤炭通过铁路运往日本','负责将阜新海州煤矿的煤炭通过铁路运往日本，为日军战争机器提供资源，同时参与强制征调劳工修筑铁路，导致大量劳工死亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba100d1194c84e4c8d9da7f2bd08938e','c3619de6-57f9-4902-8894-bf58f5648651',1937,'积极推动日本对阜新海州露天煤矿的“重点开发”','积极推动日本对阜新海州露天煤矿的“重点开发”，签订掠夺性合同，压低矿工工资，造成矿区环境严重破坏和人员伤亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a49c839ed57446458f98a1236b920bc4','661e8852-5205-49d4-9fec-12604e111cfb',1934,'在任期间配合日军对阜新地区进行“清乡”','在任期间配合日军对阜新地区进行“清乡”，组织汉奸保甲制度，强征青年为伪军，并协助日本企业霸占阜新矿区土地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14b6f2fa605b4796b636d444d6ed8b5c','69a953db-d63b-4575-b8b3-a0fab92d6d15',1933,'直接执行日本殖民政策','直接执行日本殖民政策，强征农民土地给“满炭”公司，强迫村民迁出矿区，对反抗者进行残酷镇压，多次协助日军屠杀平民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bdad04b705c44dbc8854eca417c468e2','de63387f-4130-47c2-bfc4-17f6e674321f',1935,'宣传“日满亲善”','宣传“日满亲善”，组织汉奸团体刺探抗日情报，协助日军抓捕地下抗日分子，并参与“勤劳奉仕”运动，强迫民众无偿劳动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a170e6e1319b4eb8a20518ae17fb931a','8104f30c-744b-4c73-bdfe-50c516527c8b',1936,'作为日本“满炭”公司代理人','作为日本“满炭”公司代理人，负责海州露天矿的日常管理，制定严苛劳动制度，克扣矿工工资，导致矿难频发，死亡矿工被草草掩埋。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a6d4cf85a7b45438e033fe0fbe5b75e','091ba5cc-e0cd-4c89-a5df-4d6590d01c20',1935,'作为伪满最高行政长官','作为伪满最高行政长官，签署多项出卖阜新矿产资源的法令，支持日本关东军对海州地区的军事管制，对矿区抗日活动进行镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec6644407fb641c9811b05f1c4dd5f48','e469b35d-3889-476f-b255-5935051019d3',1932,'参与制定阜新地区“产业开发五年计划”','参与制定阜新地区“产业开发五年计划”，推动日本资本全面控制海州煤矿，协助日军建立矿区“无人区”，驱逐当地居民。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec1dd7c259b94938a08572b2f8cab3cf','54ee445e-8e1c-4db4-9e55-b9f8d111cf6c',1931,'原辽宁省政府主席','原辽宁省政府主席，1931年被俘后投敌，任伪奉天省长期间推行保甲制、征集劳工，直接管辖阜新等县，配合日军掠夺煤炭资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5749f6f54333474882302a235d048414','54ee445e-8e1c-4db4-9e55-b9f8d111cf6c',1931,'九一八事变后投敌','九一八事变后投敌，历任伪奉天省长、伪满洲国民政部总长等职，参与伪满政权对东北包括黑龙江地区的统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad377df270ec437c844acb258125df1c','54ee445e-8e1c-4db4-9e55-b9f8d111cf6c',1931,'原东北军将领','原东北军将领，九一八事变后被俘投敌，历任伪奉天省长、伪民政部总长等职，参与伪满对东北地区的殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8433b08a3526471a8060c485506b2a3b','54ee445e-8e1c-4db4-9e55-b9f8d111cf6c',1931,'辽宁沈阳人','辽宁沈阳人，九一八事变后被俘投敌，历任伪奉天省长、伪满民政部总长、参议府议长等职，为伪满核心汉奸之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5796497e80724fd8b1c84a8f9da47b64','54ee445e-8e1c-4db4-9e55-b9f8d111cf6c',1931,'原东北军将领','原东北军将领，被俘后投敌，历任伪满民政部总长、奉天省长等职，参与伪满政权对东北人民的统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f29913cbeb5a4bd785284c9ed546edce','54ee445e-8e1c-4db4-9e55-b9f8d111cf6c',1931,'辽宁沈阳人','辽宁沈阳人，九一八事变后被俘投敌，历任伪奉天省长、伪满洲国民政部总长等职，协助日本推行殖民统治，其活动范围涉及东北全境。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e55d5ae4a5574ad7ace46aa7ca2e441c','54ee445e-8e1c-4db4-9e55-b9f8d111cf6c',1931,'九一八事变后被日军逮捕后变节投敌','九一八事变后被日军逮捕后变节投敌，出任伪奉天省长，后任伪满洲国民政部总长、参议府议长等职，参与制定和推行伪满各项殖民法令，其影响波及黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0052061a4daf4e8aab82ecbd2ed4b3b8','54ee445e-8e1c-4db4-9e55-b9f8d111cf6c',1931,'辽宁沈阳人','辽宁沈阳人，九一八事变后被俘投敌，历任伪奉天省长、伪满洲国民政部总长、参议府议长等职，为伪满政权核心人物之一。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b80613925a2b4156ab2995aabd8b5832','fd2ada25-0c77-48c7-b07c-f10198cbcc6d',1930,'伪满时期任阜新县县长','伪满时期任阜新县县长，推行保甲制、粮谷出荷、劳工征集等政策，直接配合日军对阜新煤矿的掠夺，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d3d4eb3bdaa4486b94279d3bb197cf8','f91b04e0-efec-401d-ae78-2b962142ba8c',NULL,'九一八事变后组织阜新县维持会','九一八事变后组织阜新县维持会，迎接日军占领，协助建立伪政权，为日军提供物资与情报，压迫当地民众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6501d42af5044f90bab6569ebaedca69','a4585feb-a623-49f9-ac80-c233e36a257b',1930,'伪满时期任清河门地区保甲长','伪满时期任清河门地区保甲长，负责摊派捐税、征集劳工、监视民众，配合日伪军警镇压抗日分子，维护殖民统治。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca990f6348b94106bd4f0703dd3f53d0','8a3d570b-2ed4-4bc2-b95f-459defce3fd9',1932,'1932年一度投敌任伪满军政部总长','1932年一度投敌任伪满军政部总长，但同年即反正重新抗日','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-655c4787c4a14a5cbc031c3761795b08','8a3d570b-2ed4-4bc2-b95f-459defce3fd9',1932,'其短暂附逆期间涉及辽宁地区伪军政事务','其短暂附逆期间涉及辽宁地区伪军政事务，后成为抗日将领。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e3ffca1b2734417bce2d92efa0d4710','9e4b1d34-063d-410e-901e-e3ba462e78b2',1931,'原为东北军将领','原为东北军将领，九一八事变后投敌，参与进攻热河、长城抗战，长期在辽西、阜新一带配合日军围剿抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-071864222d6b4c1ea80caa4ace24a24b','9e4b1d34-063d-410e-901e-e3ba462e78b2',1931,'原东北军将领','原东北军将领，九一八事变后投敌，率伪军配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪热河省警备司令等职。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a0372cfdcb54f27a7946df9db10b54d','3080a7cd-9ce5-4b29-b92d-a333a650c8b0',1931,'原东北军东边道镇守使','原东北军东边道镇守使，1931年投敌，率部在辽宁西部、阜新周边地区镇压抗日义勇军，后任伪满军政部大臣。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f1c2b0f0e60407983e749f78ef46bb5','5777f538-2473-4f1c-9f2f-7e54597b0e27',1932,'在阜新县推行保甲连坐、强征劳工、掠夺煤炭资源','在阜新县推行保甲连坐、强征劳工、掠夺煤炭资源，配合日军在细河一带清乡，镇压抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c590cdab08e9401fab22c5c5fd969069','95d4215b-f603-434d-be1f-2170f83f35b5',1933,'率伪蒙古军活动于热河、辽西、阜新北部','率伪蒙古军活动于热河、辽西、阜新北部，配合日军扫荡抗日武装，强征物资，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c32273218909432d865821015da1fafb','a65ed5fd-b42c-483f-867a-a7f811503a97',1933,'原为土匪','原为土匪，投靠日军后活动于阜新、朝阳、锦州一带，烧杀抢掠，配合日军围剿抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d684fa40711b40a7b436b4a9cb1a0848','d21a6b37-4f96-4698-bc85-2dfc0444abba',1931,'原辽宁省主席','原辽宁省主席，1931年被俘后投敌，任伪奉天省长期间在辽宁各地推行保甲、征粮、劳工政策，波及阜新。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ed51803f9a841e48c75b548e6c7682d','c5be84ed-abf9-4943-bb28-22c736614cd3',1931,'积极参与伪满建国活动','积极参与伪满建国活动，在辽宁推行亲日教育、经济掠夺政策，影响包括阜新在内的辽宁各地。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fff33f49d4f54d878da8e950e1b2bb2a','68207414-e209-432c-9e10-e7250efc86a8',1936,'管理阜新煤矿','管理阜新煤矿，强征中国劳工，实施残酷压榨，导致大量矿工死亡，配合日军掠夺煤炭资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16be3773f7e040a2b9ffaf3a0fce9a1f','4cc13639-1713-45ed-897b-b9c8bf9ed7f3',1935,'在阜新县及细河地区指挥伪警察讨伐抗日武装','在阜新县及细河地区指挥伪警察讨伐抗日武装，实施保甲连坐，抓捕抗日群众，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84eb285ab11f4e3d81d0a6c542a12873','f723fe90-3253-450a-a4c2-6b8a690d5e4f',1937,'在阜新推行奴化教育','在阜新推行奴化教育，组织亲日宣传，协助日军征劳工、征粮，控制细河一带民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6450bd9b538b40d9995f2a5ddbfc5692','39d97492-7cfc-4d1c-88df-dae356809726',1932,'在鞍山地区担任伪职','在鞍山地区担任伪职，配合日军掠夺鞍山铁矿资源，强征劳工，压迫当地民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73f30d783cc84fbcb24087b8b058abd6','33ba4b11-77a7-431d-81a0-0482ae679ce0',1931,'原奉系军阀','原奉系军阀，投日后在辽南一带协助日军清剿抗日义勇军，后调任伪满中央要职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6379a795f6694948b554cf00afff387f','986eb316-c760-48a6-bb90-944cdb3f64c6',1932,'积极鼓吹“满洲独立”','积极鼓吹“满洲独立”，参与伪满政权立法，为日本侵略提供法律依据，影响鞍山地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32d94acfdb9b4c869c8efd308af4471b','0fe7bce4-0b6e-4f33-996b-c7f719067392',1931,'清末民初政客','清末民初政客，投靠日本后任伪满高官，参与策划对辽宁地区的殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c8c0078f1ca4a37a1e4d54ee33b0b92','7871cb92-557b-4ba2-80e3-bbe80053834b',1931,'原奉天省主席','原奉天省主席，九一八后被俘投敌，在奉天（含鞍山地区）推行日伪政策，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-97506c8703a943dc85b2a7ee6783f9d2','ad19576c-b35c-45e0-ab54-e1b88981e9f7',1931,'清室后裔','清室后裔，投日后参与伪满建国，协助日本控制辽宁经济资源，包括鞍山铁矿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82de0fd00d6e4a57a1f1ba1404a060a2','b6ae7f5d-5cbe-4c3d-9fd6-4beeb46ff4a9',1932,'原奉系官员','原奉系官员，投日后任伪满监察院长，为日本在鞍山等地掠夺资源提供行政支持。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e5fde216c904cea89863cd001946e17','d7c36dab-8f50-4c9a-952b-8544932a9d9e',1932,'投日后管理伪满交通','投日后管理伪满交通，协助日军运输军事物资和掠夺鞍山钢铁资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
