INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6a2e21956f04b248135535f02aeb877','9eecf1eb-66c7-4b93-9cfe-9589fbd6ff3a',1932,'在伪奉天省任职期间','在伪奉天省任职期间，协助日本掠夺鞍山地区铁矿资源，压迫当地矿工。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aef4d8b71114492f8cf64fb0be20acab','3c7f7824-9df8-4b44-b157-c568dcaf9c7c',1932,'负责伪奉天省警察系统','负责伪奉天省警察系统，镇压千山地区抗日武装，逮捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a39d2d4586049059def106781538ac2','193d0b9f-1020-4956-9955-df70caaa69f4',1932,'在鞍山地区组织伪保安队','在鞍山地区组织伪保安队，协助日军维持治安，参与围剿抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48cf04265e6a4c62a12f43e531be51c7','f76c92bc-6347-4db7-8994-6c8c928440fe',1933,'虽主要活动于热河','虽主要活动于热河，但曾率伪军参与对辽宁千山地区抗日力量的清剿。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f7dbd11066d4c1b95159f207e924ba0','2145a848-b8fb-405b-b53c-3a85c5f82930',1937,'在鞍山宪兵队担任翻译','在鞍山宪兵队担任翻译，协助日军审讯和迫害抗日人士，民愤极大。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-567fcead0eda474992f65e27fd352f69','18e4786c-bdee-45c5-b23e-4dd2c2646b85',1931,'九一八后组织千山地区维持会','九一八后组织千山地区维持会，为日军提供粮食物资，出卖抗日情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0f1d7edf795480a91f70369b9db14b0','940ec24c-327b-42f0-9dd8-d6d23ff56348',1933,'在鞍山铁矿为日本监工','在鞍山铁矿为日本监工，残酷虐待中国劳工，造成大量矿工死亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8e080130a4145d186d383dd09c0a079','e0fc39e0-f5b5-4cea-a720-6d5edab67ee3',1931,'虽早年是奉系','虽早年是奉系，但九一八后曾与日本秘密接触，试图在辽宁地区建立傀儡政权，后因内部矛盾未果。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4701f61bd074a49bf57f0a9e3504144','6cc3a60b-7eb7-4b8c-b70d-03e2856e069a',1931,'原东北军旅长','原东北军旅长，叛变后任伪满奉天省（含鞍山、台安地区）最高军事长官，多次指挥伪军“讨伐”抗日义勇军，残害民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6cc410363984876b17714c30ce89f78','cba8d60f-3d3e-4d8c-aaa7-6fc18396bbee',1932,'在鞍山及台安一带组织伪警察和保甲制度','在鞍山及台安一带组织伪警察和保甲制度，配合日军抓捕抗日人员，强征劳工，镇压反满抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6528ccc538744ddcb9c176428f0afbbb','b18b9d30-7b1f-40f2-83e3-9c3fbf8382f5',1933,'在台安县推行伪满殖民政策','在台安县推行伪满殖民政策，强制收缴民间枪支，组织“自卫团”协助日军清乡，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dac8e3a02bfa42c7871ebbbcc42dee8c','d3977662-c169-4cd2-86bd-f02a13df7fc0',1935,'在任奉天省长期间','在任奉天省长期间，强化对鞍山、台安等地的殖民统治，推动“粮谷出荷”和劳工统制，导致当地民众饥荒。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b2217a9c2c941818da016d49521fa8e','15dce426-bf24-42f9-ac69-943aed30a70e',1937,'为日军宪兵队充当翻译','为日军宪兵队充当翻译，参与审讯和刑讯抗日志士，多次带队到台安地区抓捕地下抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f02187cd24f4495b15eee9e4de6700d','7ba26866-167b-4db1-a7a8-23475f478024',1938,'积极宣传“日满亲善”','积极宣传“日满亲善”，组织青少年奴化训练，告发抗日嫌疑分子，协助日军建立“集团部落”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8013a52d88f24b52b81458a8d6a44319','1ca25e18-3efa-4f9d-a928-5a7f5cf8d48d',1931,'作为伪满最高行政首脑','作为伪满最高行政首脑，其政策直接支配辽宁各地，包括鞍山、台安，支持日军“讨伐”和资源掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98d99c20f53049f7a1539c30dafa677e','df570fb4-381d-4012-8e3c-55cf75469190',1931,'九一八后投敌','九一八后投敌，参与策划伪满建国，在辽宁地区推行“治安维持法”，对鞍山、台安抗日活动进行镇压。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11b3cdd73ac6430092311a898af3dc5a','8f94db34-ea8a-417b-ae5c-1a569242e55f',1931,'鞍山本地豪绅','鞍山本地豪绅，日军占领鞍山后出任维持会会长，协助日军征粮、抓劳工，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-edc894fba53541aaa60cb8a7aa116dba','e01f7c74-7194-4d1d-8107-dcf0695bedfb',1932,'原岫岩县地方官员','原岫岩县地方官员，投日后任伪县长，推行保甲制度，配合日军清乡，抓捕抗日志士，强征民夫修建军事设施。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0bb9ac711b7d4ecdb7089cbf96e0f74b','010ef09a-4d3a-45ef-b51e-bf0aa2fad9f8',1933,'原岫岩警察','原岫岩警察，投日后任伪警务科长，组织伪警察队，多次参与对抗日武装的“讨伐”，杀害多名抗联侦察员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4216210bbd4142cb93f047a7810491df','35b90f61-ce83-4220-843b-f34d41df88ac',1935,'鞍山人','鞍山人，精通日语，任日军宪兵队翻译，参与审讯和刑讯抗日人士，直接导致多名地下党员牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bdafc2121a0a4ff3a2b038d584886f8d','26541a69-b400-49c0-9f22-8e7b66ec8da8',1934,'地主武装头目','地主武装头目，投日后任保安团长，率团丁配合日军扫荡，烧毁抗日村庄，掠夺百姓财物。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1a81f93a44b4138aa202643411ebc6d','61a5d601-1629-4c11-aad1-bea4d3258994',1936,'鞍山富商','鞍山富商，任伪协和会会长，为日军宣传“王道乐土”，组织“献金”活动，资助日军军费。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-997b512100b348c2b0581950cf6d69c5','192ce887-d893-4694-8cd6-de06bb34f4c0',1932,'原岫岩教育界人士','原岫岩教育界人士，投日后任伪教育局长，强制推行奴化教育，删除中国历史教材，灌输亲日思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6df837576ef447d68f957c04dd5286d8','b37a9d98-e1fc-4a82-ac60-f7792ed71c83',1931,'原鞍山铁矿中方经理','原鞍山铁矿中方经理，投日后任伪总办，为日军掠夺鞍山铁矿资源，强迫中国劳工超负荷劳动，造成大量死亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06f54ed184584c57ad534e166d984b35','7fa6be1c-3f0e-4ec3-8216-f5b4fb804e1e',1932,'原地方民团首领','原地方民团首领，投日后任伪“剿匪”司令，专门围剿岫岩山区抗日义勇军，手段残忍，曾屠杀村民。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcf9460adc6a44a8982b1638bf223b0f','9828d379-2971-42b3-b330-1f592e5b410b',1933,'原鞍山巡警','原鞍山巡警，投日后任伪警察署长，设立多处“留置场”（拘留所），严刑拷打抗日嫌疑犯，并协助日军抓捕抗联交通员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc741c2c7cc84916b927053e66ec3b17','c4c397ba-5287-4d3c-9a23-b11e8c3a301c',1932,'原岫岩县财务官员','原岫岩县财务官员，投日后任伪财务局长，为日军征收各种苛捐杂税，搜刮民财，供给伪军和日军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38dcebee869949bfaef46d3d9c58c822','1edbd0d5-9747-4bb8-9ffb-3fde8a149064',1933,'原奉系将领','原奉系将领，虽名义上未任伪职，但实际与日伪合作，其旧部在鞍山、岫岩地区组织伪军，间接助敌。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-65bef85ba59542b5bb9f7c43de4c50b7','3a5f530b-4644-452b-8bcb-c5aa4e8b362e',1935,'岫岩本地人','岫岩本地人，任伪协和会事务长，组织“青少年团”进行军事训练，为日军输送伪军兵源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eee6150c7d2f4300bd00f57ebfa3598a','f09c02c0-3cea-43d1-a3b7-bc615565f623',1934,'鞍山郊区地主','鞍山郊区地主，投日后组织“自卫团”，配合日军封锁山区，切断抗联补给线，并参与屠杀抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d498b5d6d6484c81a29cf42243cd556f','3f836b0b-f338-4f6d-9510-b146f113dffb',1932,'原奉天律师','原奉天律师，投日后任伪满立法院院长，制定镇压抗日活动的法令，其司法体系覆盖鞍山、岫岩地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ffae1f2449174fbab1bbc9c741988944','9a9c6b58-59fe-48b7-b408-d0949cfd3cc9',1938,'鞍山商人','鞍山商人，投日后任“勤劳奉仕”总队长，强征中国青壮年充当劳工，送往矿山和军事工地，致多人死亡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95f4baae4baa407cb7bd3026fcab8873','0ed89d40-d613-46d8-a2af-b2be16e31741',1931,'已列','已列，但需注意其曾直接下令伪军参与岫岩地区“讨伐”行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21da934c5088452aa1431a6baf115cbe','ba0c5e3a-5e03-48e2-be0b-f77d45c15c10',1932,'原北洋政府官员','原北洋政府官员，投日后任伪满司法部大臣，其推行的“治安维持法”在鞍山、岫岩地区被用于迫害抗日人士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-985e05f6385b4ff3905dbd065f39dd06','772763b3-b2a8-477c-a7d2-4c048d3c8963',1931,'辽宁辽阳人','辽宁辽阳人，投日后任伪满参议府议长，虽居高位，但曾为日军在鞍山、岫岩地区建立伪政权出谋划策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8104acf10fd46ae99043a8520d19337','588652c3-fc2d-4fad-afb1-e307401c2a78',1933,'原东北军军官','原东北军军官，投日后任伪“靖安军”顾问，参与训练伪军，并随军到岫岩山区扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e8a21a5c1d94ae6aff8352942e08d3b','bd196fc5-6cdd-4e90-89e9-210469f94665',1932,'原东北军参谋长','原东北军参谋长，投日后任伪满军事部次长，负责指挥伪军镇压辽宁各地抗日武装，包括鞍山、岫岩地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5648dc1bb8494cc1ac9f8b20f7f05bd7','b0c4b272-12b8-4a5e-b4e1-9df009682963',1931,'原吉林军将领','原吉林军将领，投日后任伪满宫内府大臣，虽非直接管辖鞍山、岫岩，但其伪军系统曾调兵至该地区作战。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7e579d9a1764f44a4d34466aabc8e0c','7f690793-c48c-48bf-87eb-1c698f484bb9',1932,'原东北军旅长','原东北军旅长，投日后任伪第五军管区司令官，驻防辽宁南部，多次率部进攻岫岩、鞍山一带的抗联部队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4a08d6149ce45a8a1c6c62c0589e7c9','880fa297-7c36-4b37-809b-16ef9d25920e',1934,'原岫岩县警佐','原岫岩县警佐，投日后任伪警察大队长，率伪警参与“归屯并户”，制造无人区，切断抗日武装与百姓联系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee4fe7a93b584052bd76abcab6cffc3e','89d951cb-742a-4dfe-9730-ddb03e01e2a3',1937,'鞍山汉奸文人','鞍山汉奸文人，任伪“宣抚班”班长，随日军到各村进行“宣抚”，诱骗百姓归顺日伪，出卖抗日情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2700c2629170453e8d0e66e7db29c286','c3609ee5-fa33-4ba0-973b-c5f2d32b7fcc',1933,'岫岩大商户','岫岩大商户，投日后任伪商会会长，为日军筹集物资，并强迫商户“献金”，资助伪军购买武器。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-adc1c6eb333a4d0f9248422874a75982','991bfb34-8f2d-49cc-a396-3e83c6745502',1939,'鞍山教育汉奸','鞍山教育汉奸，任伪青年训练所所长，对青年进行军事化奴化训练，为日军培养伪军后备力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7a1e93c747b4eb3b06de8f7dd2020ef','8132a493-9dad-4121-8e8b-f24e3a6c0dd6',1932,'原吉林财政厅长','原吉林财政厅长，投日后任伪满民生部大臣，推行“粮谷出荷”政策，导致鞍山、岫岩地区农民饿死无数。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7d3a9afce844790a7707e909b758797','e1bbe3bd-5c26-4fdb-aaf5-255c7ca18423',1935,'鞍山铁路职员','鞍山铁路职员，投日后任伪护路队长，协助日军保护铁路运输，抓捕破坏铁路的抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-778a4e06485548908d938b695376d372','88aa4c87-4ae1-4696-a81e-ee5bd5504e99',1931,'已列','已列，但需补充其曾派伪军到岫岩地区“清剿”抗日义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-941f0e730c58406bbdae6c5218385a4a','3cc2ea55-91d0-4da3-afd2-cf051df5733d',1932,'已列','已列，但需注意其还负责为日军征收“出荷粮”，导致当地饥荒。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82fc2b81283e4b1cb537aace18532045','3cc2ea55-91d0-4da3-afd2-cf051df5733d',1932,'已列','已列，补充其曾贪污抗日捐款。','危害等级B（乙级，市县厅局级）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e22bc66ad6ae42cb983cb0b87acf8910','61378088-e43f-4fbb-bc44-102341ade746',1932,'已列','已列，但补充其曾下令处决抗日家属。','危害等级C（丙级，基层头目）','hanjian；traitors');
