INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19eae7c880204e048a710b202d16b066','1d4c0b75-fed2-4d6e-9fa7-92966fe6fbf8',1935,'已列','已列，补充其曾协助日军运输军火。','危害等级C（丙级，基层头目）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7daedcc2aca645c38510a9b1746bd779','e1c52881-bb58-462e-82bc-a119917c026c',1931,'原东北军旅长','原东北军旅长，1931年投降日军，任伪奉天省警备司令，后任伪满奉天省省长，在辽宁地区推行殖民统治，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d622536d169d4bc19ce3a131aefa391b','58112050-d5c2-4527-b38c-caaddd70c4d5',1931,'鞍山本地豪绅','鞍山本地豪绅，日军占领鞍山后出任伪治安维持会会长，协助日军征粮、抓劳工，为日本昭和制钢所（鞍钢前身）提供劳动力。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c90f1aa01ec4c3d9668b69cc859414f','9a406542-9f6c-407d-93c7-2200a2e50566',1932,'原海城县地方官员','原海城县地方官员，投敌后任伪海城县县长，推行保甲制度，强征民夫修建军事设施，配合日军清剿海城地区的抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f74346063154739a41826c798f32c0a','54daf6ae-b827-40ee-833a-f53d698fe3d5',1932,'原鞍山地区警察','原鞍山地区警察，投敌后任伪鞍山警察署长，多次参与抓捕抗日地下党员，破坏抗日组织，协助日军实行“治安肃正”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5fde713d2684c7394d67cbf4630b504','ed5a64d8-eed7-4bb2-864b-6a51bff5557e',1933,'海城地方武装头目','海城地方武装头目，投敌后组织伪保安队，配合日军扫荡海城东部山区，杀害抗日义勇军战士及无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71233fe33bf749bc86727f5b7d213d48','97374ac5-6858-45e4-9e5a-e388bd208b42',1932,'原辽南土匪头目','原辽南土匪头目，被日军收编后任伪“剿匪”司令，在鞍山、海城、岫岩一带围剿抗日武装，烧毁村庄，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd06186a692740488cd806780c984daf','ef748216-6945-46a4-a1db-290a4980a1d7',1931,'协助日本帝国主义控制鞍山铁矿资源','协助日本帝国主义控制鞍山铁矿资源，为昭和制钢所（今鞍钢前身）提供情报与资源调配，参与伪满经济统制政策，压榨中国劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92673f15062643ffac9d390028e7bdc1','79bb2718-d9d0-42d5-8fc5-d71c813dd142',1931,'九一八事变后公开投敌','九一八事变后公开投敌，在辽宁地区协助日军镇压抗日义勇军，后任伪满要职，参与“治安肃正”行动，残害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b3e7d0f26134e3f870bda8e27ae8a57','abf8c58a-29c8-45df-8c6c-4886a260b629',1932,'在鞍山、立山地区积极执行日伪“保甲制度”','在鞍山、立山地区积极执行日伪“保甲制度”，搜捕抗日地下工作者，多次带队围剿抗日游击队，并强迫居民“连坐”举报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc749af8c4a54fd689a6e63a6aa4799b','6d32d02a-879e-4cd0-aa65-4c5179cb37d2',1931,'日军占领立山后主动组织维持会','日军占领立山后主动组织维持会，为日军征集粮食、劳役，强征当地青壮年充当伪军，并协助日军建立“集团部落”以隔离抗日武装。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f79ac941e4874c47b39eddc3e5f1c771','ecb2e9ed-cad9-4f40-b7e0-012475d19521',1931,'虽主要活动于伪满中央','虽主要活动于伪满中央，但多次赴鞍山、立山矿区“视察”，推动《满洲国劳动统制法》在鞍山实施，导致大量矿工因劳致死。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-762e94d72c144012afd307c8d859db62','2857bfee-91c7-4131-9b8d-eadc65dbf428',1932,'率伪军配合日军在鞍山、海城、立山一带“讨伐”抗日义勇军','率伪军配合日军在鞍山、海城、立山一带“讨伐”抗日义勇军，制造多起屠杀事件，并强迫农民“出荷”粮食支援日军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c02b7f01b8ea4f1184efbaff4502b2c9','34d5bcf9-4be2-47a0-8cc7-b765afec23c2',1938,'负责从华北、山东强掳劳工至鞍山矿山','负责从华北、山东强掳劳工至鞍山矿山，实行“以人换矿”政策，克扣口粮，导致数千劳工死亡，并参与镇压劳工暴动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bfc57bc119c34dd6b311c281cb4945e4','9a519d48-dadc-4413-a8ca-e3e33e75a25e',1933,'带领保安队为日军把守立山交通要道','带领保安队为日军把守立山交通要道，多次截击抗日物资运输，并直接参与抓捕、刑讯抗日嫌疑人员，手段残忍。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8831d33bf21e49a0940327404b70e637','e39c1c8a-946b-4822-99cf-1add34baebc1',1935,'作为伪满最高行政头目','作为伪满最高行政头目，推动鞍山昭和制钢所扩大生产以供应日军军需，并批准在立山增设“矫正辅导院”，关押迫害抗日群众。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c61fcc8df3544271b6068dcde9ff7b0f','d5c9d234-37ee-460c-9333-d09aea5e7f9d',1937,'依据《治安维持法》在鞍山、立山地区滥捕“思想犯”','依据《治安维持法》在鞍山、立山地区滥捕“思想犯”，判处大量爱国志士死刑或长期监禁，并协助日军“特别移送”至731部队。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a893c3d18d51451e89c9a3050669ddac','aae7afa9-7196-4044-ba89-91f49164ec9f',1931,'曾任伪满鞍山昭和制钢所理事','曾任伪满鞍山昭和制钢所理事，后任伪满奉天省省长，积极为日本侵略者服务，压榨东北人民，协助日伪政权推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ad295b9d13741daabeec5a5b887bc12','aae7afa9-7196-4044-ba89-91f49164ec9f',1931,'曾任伪满鞍山昭和制钢所理事','曾任伪满鞍山昭和制钢所理事，后任伪满奉天省省长，积极协助日本侵略者掠夺鞍山铁矿资源，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae8354dae9a34ba0b7e138e4c96aef58','1e9bd11f-db19-491d-a7c2-823fe1eb16c5',1931,'九一八事变后','九一八事变后，在鞍山铁东地区组织地方维持会，协助日军维持秩序，为日本占领军提供情报和后勤支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00f67151234b4376a2cb2db72ced4173','1e9bd11f-db19-491d-a7c2-823fe1eb16c5',1931,'在鞍山沦陷后组织地方维持会','在鞍山沦陷后组织地方维持会，为日军提供粮食、劳力和情报，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f35f1c53fce49c0bf66d25e18265573','5108b900-4a58-4ade-8eb7-9ea41d164e29',1932,'任伪满鞍山警察署署长期间','任伪满鞍山警察署署长期间，残酷镇压抗日爱国人士，协助日军抓捕和刑讯地下抗日分子，在铁东地区制造多起白色恐怖事件。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24f42c5f7b23482ab3d1fa6736cad7d1','5108b900-4a58-4ade-8eb7-9ea41d164e29',1932,'在鞍山铁西地区任伪警察署长','在鞍山铁西地区任伪警察署长，残酷镇压抗日地下组织，抓捕爱国人士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c3a517037834d4aac9d1b24e3f0bcac','1b72e987-870f-4d41-a027-471198c29cda',1933,'任伪满鞍山铁东区区长','任伪满鞍山铁东区区长，强征劳工为昭和制钢所服务，克扣工人口粮，协助日军推行“粮谷出荷”政策，导致当地民众饥荒。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f021d8ffaf07482886e65de033a3bb80','b241bc6c-872e-41be-8efb-1d172cd78b70',1931,'原土匪出身','原土匪出身，投日后任鞍山保安队队长，率队围剿抗日游击队，在铁东地区烧杀抢掠，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5141d4f5da1649f4ba848f5ca6b544d1','b241bc6c-872e-41be-8efb-1d172cd78b70',1931,'在鞍山铁西地区组织伪保安队','在鞍山铁西地区组织伪保安队，配合日军扫荡，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a92ea77901f47b1b0a5a584c10f7932','6e0e518c-b6d5-4190-b1ec-5055458843c3',1931,'九一八后投敌','九一八后投敌，任伪满奉天省省长，管辖鞍山、铁西等地，协助日军建立保甲制度，强征劳工。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
