INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49603e46fde743a484cd7cfaf7dedd82','b58cb400-04c4-441e-b696-8b90262a6b2e',1931,'川军将领','川军将领，抗战期间任第二十九集团军总司令等职，在四川及重庆活动。未任伪职，无附逆行为，不应列入汉奸名录。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f93b6f9eaa654361b178d2aa53283fca','9f0fd92d-ad2f-42b0-9b4a-31958cc316ae',1931,'川军将领','川军将领，抗战期间在重庆及四川活动，曾参加抗战。未任伪职，无附逆行为，不应列入汉奸名录。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd4f2bd9383245639b30ac9cacc9d715','2e192214-8f0b-4272-92ed-269f7b719122',1931,'重庆袍哥组织“孝义会”首领','重庆袍哥组织“孝义会”首领，在沙坪坝及重庆周边活动。抗战期间与军统、地方势力关系复杂，但无确凿证据表明其任伪职或附逆。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2ce97a6613e4faa881ddbbaf1bc1b6a','109a14f7-82c5-4ba7-ba6a-c850379cd472',1931,'重庆袍哥组织首领之一','重庆袍哥组织首领之一，在沙坪坝及重庆地区活动。抗战期间与地方军政势力有联系，但无可靠证据表明其任伪职或附逆。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41b04ee7323f4c378bea95b3a651aa00','17e18b2d-bd8e-444a-ada5-286a645db0b0',1938,'据部分地方史料提','据部分地方史料提及，重庆周边曾出现个别维持会组织，但沙坪坝地区在抗战期间为国民政府陪都核心区，未沦陷，故无正式伪政权维持会。相关记载零散且可靠性不足。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
