INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0654156f7315441e87d9b7c4aedc7587','c7b91263-971b-428a-be56-9b4063460de4',1936,'绥远地区蒙古族汉奸武装首领之一','绥远地区蒙古族汉奸武装首领之一，长期在绥远、陕北毗邻的伊克昭盟、榆林北部边缘活动，配合日军进攻绥西和陕北抗日根据地，所部曾窜扰神木、府谷黄河沿岸。','危害等级C（丙级，基层头目）','hanjian');
