INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bccd8e5f24944d2ea3c3d13eb88d28db','89ff246e-79ac-441d-b878-0c090babade2',1935,'华北伪军早期头目','华北伪军早期头目，其伪军活动于冀东、平津一带，与华北伪政权协调，对华北各地伪军组织有影响。','危害等级C（丙级，基层头目）','hanjian');
