INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cc95528604846f0adf406a97fed07e8','a061501c-0662-4cfb-aca8-7ad0b4911556',1935,'积极推行奴化教育','积极推行奴化教育，组织“协和会”宣传“日满亲善”，告密抗联活动导致多名地下党员被捕。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0dfcc364e764e9bbbfe599d0a723fd8','c02a3d1a-87da-43c2-b9ea-7e8cbcc6948c',1936,'率保安队配合日军“讨伐”抗联','率保安队配合日军“讨伐”抗联，在七台河一带烧毁村屯，杀害抗联后勤人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5023539462164c20a5299fb7df0c66b2','23d006ff-ef4c-46d8-b4c2-fee6bec8b9de',1937,'为日军搜刮粮食和物资','为日军搜刮粮食和物资，强征“出荷粮”，导致当地百姓饥荒，并贪污抗日家属财产。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3a938fa82134fe8b6a3b71202137caa','4ada6897-a607-4325-a1c2-d5193e660bc4',1938,'主持“思想矫正”监狱','主持“思想矫正”监狱，关押虐待抗日嫌疑分子，多次执行酷刑和秘密处决。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcf6e0e23d9245fa99c07e773023782f','8a539238-e552-4ee9-afa0-be3c56014f9f',1939,'建立特务情报网','建立特务情报网，侦破抗联地下联络站，导致勃利地区抗联组织遭受重大损失。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f654b6d2eb994c779f1bee1b69380f50','600de373-4302-492f-97e7-d357941f296c',1940,'组织自卫团协助日军“清乡”','组织自卫团协助日军“清乡”，在七台河矿区抓捕劳工，迫害矿工中的抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ddebead2497b4db0bfa2ee8ab3b194e0','3094586b-b79b-48ef-b138-e52658ffbb9a',1931,'原吉林自卫军将领','原吉林自卫军将领，后叛变投日，在黑龙江东部（含七台河、桃山周边）多次指挥“讨伐”抗日联军，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d3b0b534129496e9cd1bf4e3cb21f33','3094586b-b79b-48ef-b138-e52658ffbb9a',1931,'原吉林军将领','原吉林军将领，投日后在黑龙江地区（包括哈尔滨、大庆周边）率伪军多次“围剿”抗联第三路军，制造多起惨案，后升任伪满治安部大臣。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b15e8cfca08d4f01bf5619f0300cb878','3094586b-b79b-48ef-b138-e52658ffbb9a',1931,'原东北军旅长','原东北军旅长，1932年投降日军，任伪满第四军管区司令（驻哈尔滨），后升任伪满治安部大臣，多次率伪军“讨伐”抗日联军，残害抗联将士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5466e659d8c740dd9df45ad2a73fb1e8','3094586b-b79b-48ef-b138-e52658ffbb9a',1931,'原吉林自卫军将领','原吉林自卫军将领，1932年投敌，任伪满第四军管区司令，驻防黑龙江地区，多次率伪军进攻绥化、肇东一带的抗联部队，后升任伪满治安部大臣。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85baf748303749c89755839fe6160896','3094586b-b79b-48ef-b138-e52658ffbb9a',1931,'原东北军旅长','原东北军旅长，叛变后率伪军多次围剿抗联，在鹤岗及周边地区实施“讨伐”，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1883c0c1d2c6437f861a02435135ab7b','3094586b-b79b-48ef-b138-e52658ffbb9a',1931,'原东北军团长','原东北军团长，1932年投敌，在黑龙江、齐齐哈尔等地率伪军围剿抗日武装，制造多起惨案','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a099263c40c40b887a2047f9e01d246','3094586b-b79b-48ef-b138-e52658ffbb9a',1931,'原东北军军官','原东北军军官，叛国投敌后任伪满第四军管区司令（驻齐齐哈尔），多次率伪军“讨伐”抗日联军，在拜泉、讷河等地制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd87609a4df144a7a57811632d2c5e68','6c5b2ae6-04e0-40b6-9eea-bc7e293327de',1933,'在勃利县（含今七台河、桃山一带）推行日伪殖民统治','在勃利县（含今七台河、桃山一带）推行日伪殖民统治，强征劳工，配合日军清剿抗联，残害百姓。','危害等级C（丙级，基层头目）','hanjian');
