INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d23dd22ce9b4d678ad6c06c750e9b91','e1b8f181-412d-431c-afe3-fed16b82b9e8',1939,'组织协和会宣传“日满亲善”','组织协和会宣传“日满亲善”，诱降抗联动摇分子，并收集抗联情报提供给日军，导致多处抗联联络点被破坏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f934179d1114a4180f29e9ec3a1bcae','46e2a10f-7639-418a-857c-a62da4e114c6',1940,'组织地方自卫团配合日军巡逻','组织地方自卫团配合日军巡逻，盘查过往行人，多次截获抗联物资，并参与对抗日嫌疑人的酷刑审讯。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb5f59cdc5774ce4904638d84e479a5b','7f6fdf8c-b08d-4ea3-932e-d1e2e04b26f9',1937,'在汤旺河流域抓捕抗联交通员','在汤旺河流域抓捕抗联交通员，破坏地下交通线，并参与“归屯并户”行动，强迫山区居民迁入集中村。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b89bcfaedbc4f3fa4a67d82e5a8d120','9bf4b5c4-159c-46ff-a39b-9f5861a0b32a',1941,'率山林队为日军带路搜索抗联营地','率山林队为日军带路搜索抗联营地，在冬季破坏抗联雪地足迹，导致抗联第三军部分战士冻饿牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a194a74bfa274b6996892f1e2604c62e','63beadac-b6a5-4a0f-917f-30bf5b9090b2',1932,'辽宁人','辽宁人，九一八后投敌，历任伪滨江省省长、伪满洲国司法部大臣等职，参与推行殖民统治与治安肃正，其伪政权管辖范围包括今黑龙江中南部及伊春部分林区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49914ad1e3464f059612ad92592e187f','8b569615-a01e-4de3-ae25-74dd133ec4f5',1931,'原中东铁路督办','原中东铁路督办，投敌后任伪滨江省省长、伪满洲国经济部大臣等，协助日本掠夺东北资源，包括小兴安岭林区木材。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4bbf44b6b3944bffa80288ddf10e7b95','8b569615-a01e-4de3-ae25-74dd133ec4f5',1931,'辽宁人','辽宁人，九一八事变后投敌，历任伪滨江省省长、伪满洲国司法部大臣等职，在哈尔滨及周边地区推行伪满统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f3d3ec52dc44e078db82be42e1cce87','822089ae-2a62-4f65-a91e-25c618362683',1934,'伪满政客','伪满政客，曾任伪三江省省长、伪满洲国厚生部大臣等，参与对黑龙江东部及小兴安岭地区的殖民统治与资源掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a08a0f7e9434f2caebb708a10d4d328','204974a4-1840-42cd-b8bd-784cc149b9aa',1932,'原东北军军官','原东北军军官，投敌后任伪满军旅长、师长，活动于黑龙江东部及小兴安岭一带，参与围剿抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd4561525bc64007bfa33aa81545f3e4','509c0da5-a2c9-4d30-9fee-628af3cd52cc',1932,'原东北军军官','原东北军军官，投敌后任伪满军军官，在滨江省及小兴安岭地区参与对东北抗日联军的作战。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5ccf629e330421182d33a240fe92fd2','5aeb13ae-fedb-412b-99c2-384008697f9a',1931,'原东北军骑兵师长','原东北军骑兵师长，九一八后率先投敌，任伪满军将领，其部队曾活动于黑龙江地区，参与镇压抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aef4a6bfe93e4be3a907184783c3cefa','c4a443ba-4642-44a0-ada7-b03ab3e5b003',1931,'原东北军军官','原东北军军官，投敌后任伪满军上将，统辖伪军参与对东北抗日联军及黑龙江地区抗日武装的围剿。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75bd2394f1a449a38501e7f11d34563e','a5c313c7-e4a9-44a9-88f4-364afd1a3d17',1932,'土匪出身','土匪出身，投敌后任伪满军团长，在吉林、黑龙江东部及小兴安岭南部参与围剿抗日联军，后被打死。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39c510bbed8b410193649f12136a5542','9338f852-553d-4962-bcf2-8d1e368571a9',1932,'原东北军军官','原东北军军官，投敌后任伪满军旅长，在黑龙江东部及小兴安岭地区参与围剿抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e44e8c64ae14652997e6aff4110c2e3','afeac39a-3324-4c04-970f-29e599538b3e',1935,'伪满时期在伊春林区担任伪警察头目','伪满时期在伊春林区担任伪警察头目，协助日军管理林区、镇压抗日群众，具体事迹散见于地方文史资料。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0155759a15e94bbb9a86f8d81d8d6f24','6cf2d1f3-5be4-40dd-b962-23abcef81d84',1934,'在汤原、伊春一带任伪警察头目','在汤原、伊春一带任伪警察头目，参与围剿抗日联军，迫害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-066cc4a74e8947438200b7dd86ecb6f4','b0633a48-21cc-4c17-bb61-f8c192d40a5b',1934,'伪满时期任汤原县伪县长','伪满时期任汤原县伪县长，管辖范围邻近伊春丰林地区，推行保甲连坐、掠夺林区资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7dbb8276f1f46b6ab66888ea359ccf1','2672d3ab-b205-47eb-953c-3f17cf6e7bf4',1934,'伪满时期任佛山（今嘉荫）县伪县长','伪满时期任佛山（今嘉荫）县伪县长，管辖范围与伊春北部接壤，协助日军推行殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff8d4c25880e43049af6d0e6222ed0bb','8f4ad326-f873-4fe9-98e5-1d1b628bb78c',1931,'清朝宗室','清朝宗室，九一八后投敌，任伪吉林省长、伪满财政部大臣，参与建立伪满殖民统治体系，影响波及黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa1c671d5073433b9fe9d7bb10022f42','8419de57-8d08-49f9-8871-532498f54193',1932,'台湾人','台湾人，投敌后任伪满外交部大臣，参与伪满对外交涉，为日本殖民统治服务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af3666f996254ea7a5e50f8b1e3c35da','8b04c601-ea36-41a1-b8ce-c452120ac964',1937,'在伪县府任职期间','在伪县府任职期间，协助日军推行“集团部落”政策，强征劳工，搜捕抗联人员，为日伪统治效力。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5facb08d98054441a80dca25a7d770fa','ab6fd8e0-e9cd-4a09-a100-5f234855470e',1932,'原东北军将领','原东北军将领，九一八后投敌，在黑龙江及伪满多地协助日军清剿抗日力量，其部队曾参与对伊春林区抗联的围剿。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb5c2b5b67c741ce9c5ec6f9eb2de0dd','3ade865e-ebf8-4d3a-ab8a-c53312e92637',1933,'投日伪后','投日伪后，其骑兵部队曾配合日军在黑龙江北部（含小兴安岭一带）追击抗联，烧毁村屯，迫害百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9be959538575490cb8d8f0c5da6ca964','154dfcb4-a854-4d16-8aa8-29172b810f87',1932,'一度抗日后投敌','一度抗日后投敌，任伪满军事顾问，参与策划对黑龙江地区抗联部队的“讨伐”，其活动范围涉及伊春周边林区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4560f895cca2408986af12175c9ff01f','a5eac90f-d534-4b7b-b007-32eae5d4eebe',1932,'原东北军团长','原东北军团长，投敌后率伪军配合日军在松花江下游及小兴安岭地区“扫荡”，破坏抗联密营。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec1c608fea0943218af0ad0c95d776a8','a509a34c-df38-4067-9067-bc43b477466f',1932,'协助于琛澂指挥伪军','协助于琛澂指挥伪军，在伊春、乌翠一带的山区多次组织“搜山”行动，杀害抗联伤员和支援群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1fbfa48d677449d2a60468ce724001cf','6fd0187c-bc61-4988-9d68-091a6aacb746',1938,'积极执行日伪“治安肃正”','积极执行日伪“治安肃正”，建立保甲制度，抓捕抗联交通员，并参与“归屯并户”强迫居民迁移。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2834ddf3f6e44ae590f05b3ad8bd02e4','1902a5fd-f000-41b4-bcb6-058b5bc768f5',1939,'率森林警察为日军采伐木材提供保护','率森林警察为日军采伐木材提供保护，同时搜捕在林区活动的抗联小分队，破坏抗联后勤补给线。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8770cd6ced91448d8e7e10a780260d27','54cb133e-a461-4087-a55f-ca1e68c86b17',1932,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，全面推行日伪殖民政策，其政权体系直接管辖伊春、乌翠地区，支持“讨伐”抗联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74659064f1cc430db069367df504624d','11b8d803-a2ea-4767-94c2-a150db3d110d',1932,'曾任东北军将领','曾任东北军将领，后投敌叛国，在黑龙江地区协助日军镇压抗日武装，参与“讨伐”东北抗联，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f5362dbb9e442388373a32cddaf8370','11b8d803-a2ea-4767-94c2-a150db3d110d',1932,'原东北军将领','原东北军将领，后投敌任伪满军事要职，曾率伪军参与“讨伐”抗日武装，活动范围包括黑龙江地区，对伊春、友好一带的抗联部队进行过围剿。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a93679b2214647b3ad6f410eebc8ff2b','11b8d803-a2ea-4767-94c2-a150db3d110d',1932,'原东北军军官','原东北军军官，后投靠日军，任伪满第四军管区司令官，驻防黑龙江地区，多次率伪军围剿抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76c84dfff58c490d865ebd3b6306174b','11b8d803-a2ea-4767-94c2-a150db3d110d',1932,'原吉林自卫军将领','原吉林自卫军将领，后投靠日军，任伪满第四军管区司令官，负责绥化、北林一带的“讨伐”行动，多次率伪军进攻抗日游击队，杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4f20097b316d47c791d65cf9f6a535f6','11b8d803-a2ea-4767-94c2-a150db3d110d',1932,'原东北军旅长','原东北军旅长，投日后任伪满第四军管区司令官，驻防黑龙江地区，多次率伪军围剿抗联部队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8144e4150d07457381a6a41cb9298473','2cc75832-2b7f-45f1-afd6-2a81a437f03f',1931,'原东北军将领','原东北军将领，九一八事变后投降日军，在黑龙江及东北多地协助日军建立伪政权，参与围剿抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a20dcc36f9c403594bb87f760393819','9e14cf4e-8286-4a52-91c0-b93d3fc7effc',1931,'曾任伪满要职','曾任伪满要职，为日本殖民统治出谋划策，参与制定奴化政策，对东北人民进行思想控制。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0631462a6b49436a85a949159af3e4db','9e14cf4e-8286-4a52-91c0-b93d3fc7effc',1931,'积极参与伪满政权建立','积极参与伪满政权建立，为日本殖民统治出谋划策，涉及黑龙江地区伪政权事务。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17e58de02700430bbe117348688731ab','9e14cf4e-8286-4a52-91c0-b93d3fc7effc',1931,'积极鼓吹“满洲独立”','积极鼓吹“满洲独立”，参与伪满政权建立，为日本殖民统治出谋划策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74d1f6b5e8534bd9b58688225f16823f','5adfee77-bfd8-47c7-84f6-80523dfd45a3',1932,'原黑龙江省官员','原黑龙江省官员，投日后出任伪省长，积极推行日本殖民政策，镇压抗日活动，征收苛捐杂税。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7c415fc4e6a4016b7a428195fd89f58','5adfee77-bfd8-47c7-84f6-80523dfd45a3',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，1932年投敌，任伪满黑龙江省省长，积极推行日伪殖民政策，协助日军清剿抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc84360b82a34818b0e9ce8d43d767e1','5adfee77-bfd8-47c7-84f6-80523dfd45a3',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪黑龙江省省长，管辖绥化北林，推行日伪法令，组织“自卫团”对抗抗联，强征粮税。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49c9b94ad7bf47d4beb07e4d7e0bb1a9','5adfee77-bfd8-47c7-84f6-80523dfd45a3',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，1932年投敌，任伪满黑龙江省省长，管辖包括绥化、肇东在内的广大地区，积极推行日伪法令，强征劳工，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3cbd755887704fa5a7ae7aaab401f189','5adfee77-bfd8-47c7-84f6-80523dfd45a3',1932,'原黑龙江省官员','原黑龙江省官员，投日后任伪省长，强征粮税，配合日军清剿抗联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6589dda24f14c1f9a657850cf9a67f4','5adfee77-bfd8-47c7-84f6-80523dfd45a3',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪满黑龙江省省长，管辖黑河、五大连池等地区，协助日军建立伪政权。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae026eda294b421aa23365df5f735c2a','5adfee77-bfd8-47c7-84f6-80523dfd45a3',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪满黑龙江省省长（省会齐齐哈尔），推行“保甲连坐”制度，强征粮草，配合日军“讨伐”马占山等抗日部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c44a3b2297324f718de23d703f271674','4c8951b7-c933-4c10-9f47-f8a981143481',1932,'原哈尔滨特别市市长','原哈尔滨特别市市长，投日后任伪滨江省省长，协助日军建立保甲制度，迫害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9cb3a0d5da4443e9b46fe911d085d146','620faca9-41f9-4dd6-95eb-2355d0583d81',1932,'负责为日军搜刮黑龙江地区资源','负责为日军搜刮黑龙江地区资源，强征劳工，为侵略战争提供经济支持。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f5bb6317dbc4ad8bdd5e6d07b6472ed','620faca9-41f9-4dd6-95eb-2355d0583d81',1932,'在伪黑龙江省任职期间','在伪黑龙江省任职期间，负责为日军筹措军费，在绥化北林地区加征苛捐杂税，导致民不聊生，并协助日军掠夺粮食资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a28c6d83b9db4ccca05d127d8a598573','b8c485a9-0808-4cdf-9932-f191b54cc00f',1934,'指挥伪警察和特务','指挥伪警察和特务，配合日军对抗联进行残酷“讨伐”，杀害大量抗联战士及平民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3dd6e1d03aac44df8a34bec5ccb0d801','52a1215d-81d1-4847-b0b5-d937db144f68',1932,'在哈尔滨及周边地区（含伊春方向）大肆搜捕抗日分子','在哈尔滨及周边地区（含伊春方向）大肆搜捕抗日分子，严刑逼供，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-30b3b15c56af4e4a935dcf4c550238c8','333879bf-7958-47b8-a289-80045b315ccf',1939,'推行“集团部落”政策','推行“集团部落”政策，强迫农民并村，制造无人区，切断抗联与群众联系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3066bb4621a942c98f7d20f0e52ef2f3','7ad13583-41e6-4a44-8d31-cd4915e509c9',1935,'率伪森林警察在伊春林区为日军采伐木材','率伪森林警察在伊春林区为日军采伐木材，同时搜捕抗联小分队，破坏抗联密营。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45864f7fa666494e881fcaf9f73ce077','7a21416c-b0ce-4712-b2db-4343ec205e84',1934,'伪满时期三江省（含今伊春、南岔部分区域）行政长官','伪满时期三江省（含今伊春、南岔部分区域）行政长官，推行殖民统治，强征劳工，配合日军“治安肃正”行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20804d53d0b94cebb70ede33efbba677','17b9a659-30d7-4246-97a8-82e26eb3f950',1937,'作为日本关东军派任的伪省次长','作为日本关东军派任的伪省次长，实际掌控三江省政务，在伊春、南岔地区组织“归屯并户”，制造无人区，迫害抗联家属。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3309ac38b4644b697d9cd543b90056b','b5fd7f0f-6dfe-4731-a053-0eae6dd9d4e4',1938,'在伊春林区为日军服务','在伊春林区为日军服务，率伪警察配合讨伐抗联第三、第六军，破坏密营，抓捕地下交通员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6e60b6e04824c29b17484ccf874985d','c7047312-6336-4f1f-9e4c-fb2fdcb76d5c',1939,'在南岔地区积极执行日伪“治安强化”政策','在南岔地区积极执行日伪“治安强化”政策，多次带队袭击抗联小分队，残害当地抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c8a33d28d4e4ed5a316db90e8ef9bc6','90b69a7b-c069-4186-8241-51c64a8a317f',1940,'充当日本殖民统治基层代理人','充当日本殖民统治基层代理人，强征民夫修建警备道路和碉堡，为日军提供粮食和情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44734a2785634f0abf3f603689b3b055','ad78356c-2592-44f3-877e-44aa84b5d616',1941,'在协和会名义下进行奴化宣传','在协和会名义下进行奴化宣传，组织“勤劳奉仕”队，强迫当地青年为日军劳役，并告发抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13d420c98ba346d88ec366b09e95f6d7','9983b3ed-e0a2-4e26-8128-2fb63ee88938',1936,'专门负责伊春、南岔地区抗日情报搜集','专门负责伊春、南岔地区抗日情报搜集，多次破坏抗联地下联络站，逮捕并刑讯抗日志士。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac234e318e3b4c749e5994ca34c4c4d4','7385ffca-58a6-478f-8470-a6e5627cc187',1937,'在伊春地区担任伪职','在伊春地区担任伪职，协助日军推行“归屯并户”和“集团部落”政策，强征劳工采伐木材，迫害抗日群众，为日军提供物资和情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b22d3d6426b543faa89cd71c0cd5adbb','392be4d5-5fcb-42a1-ac24-5e248e159515',1931,'原奉系军阀','原奉系军阀，九一八后公开投敌，虽主要活动于热河，但其伪军部队曾北调至黑龙江参与“治安肃正”，对伊春、友好周边抗联根据地造成破坏。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fb217f20c904c1f9232b94ce37a4904','017fce25-0a81-4fba-a917-a7ab90221079',1933,'投日伪将领','投日伪将领，曾率伪军配合关东军在黑龙江北部（含伊春邻近地区）扫荡抗联部队，参与建立伪政权，掠夺林业资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c930b1a67944bc6a7ebaf83eae487ad','e1c74bbf-37b4-4bb5-a31e-a813da97e1d6',1938,'在伊春、友好一带任伪警察头目','在伊春、友好一带任伪警察头目，残酷镇压抗日分子，抓捕并刑讯抗联地下工作者，协助日军实施“三光政策”，强征当地居民修筑军事工事。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8c29b9c21d943fc9a8c1265805219ec','18f0c8c9-2eee-4592-94b9-eede0bfac218',1940,'积极宣传“日满亲善”','积极宣传“日满亲善”，组织汉奸团体刺探抗联情报，破坏抗日群众组织，为日军提供当地抗日武装活动线索，导致多名抗联战士牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8b44a181ef542e9b73ded8039ab7732','96baae87-f968-4335-a3a9-1994298c8271',1930,'早年投靠日本','早年投靠日本，历任伪满哈尔滨警察厅厅长、伪滨江省省长等职，参与镇压东北抗日活动，推行日伪统治政策，其活动范围覆盖黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea48eebf87ea493486e8cc721d841034','96baae87-f968-4335-a3a9-1994298c8271',1930,'早年投靠日本侵略者','早年投靠日本侵略者，历任伪满哈尔滨警察厅厅长、伪滨江省省长等职，参与镇压东北抗日军民，推行日伪殖民统治，后任伪新京特别市市长，是伪满政权中级别较高的汉奸之一，其活动范围覆盖黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c2654f9481c49f8a845147147bf7314','96baae87-f968-4335-a3a9-1994298c8271',1930,'早年投靠日本','早年投靠日本，历任伪满哈尔滨警察厅长、伪滨江省省长等职，参与镇压东北抗日活动，推行日伪殖民统治，为日本侵略者效力。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1466d9ad1af14676aa7d2b418120284b','112df83e-208c-495e-ae5c-97c105fb9702',1930,'历任伪滨江省省长等职','历任伪滨江省省长等职，管理包括今伊春、嘉荫在内的黑龙江地区事务，推行日伪殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46925cbb574045ac8db2f41a064c5566','112df83e-208c-495e-ae5c-97c105fb9702',1930,'投靠日本后历任伪滨江省省长等职','投靠日本后历任伪滨江省省长等职，在黑龙江地区推行日伪统治，后任伪满驻日大使，为日本侵略政策辩护。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e5354c6b041f4caa9b864bb3be84c1e9','112df83e-208c-495e-ae5c-97c105fb9702',1930,'原中东铁路督办','原中东铁路督办，投敌后任伪滨江省省长、伪驻日大使等职，参与日本对东北经济与交通的殖民控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa6d520a5593414eb1dae52bcb7d3e01','2d6e1a22-9103-4ef2-b3eb-286f233bec56',1932,'在伪滨江省警务系统任职','在伪滨江省警务系统任职，参与镇压抗日武装，其警务活动覆盖黑龙江多地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0fc6f81e3c04b27820aa69f63fc41d8','17d94840-7737-44c0-b850-59f44ca0abbe',1934,'任伪三江省省长期间','任伪三江省省长期间，配合日军在黑龙江东部地区推行保甲、归屯并户等政策，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9fb1ffe5f8a74f25ac279342ddbb7164','81feb044-c6d8-46c6-8f37-5622c12487b5',1930,'历任伪三江省省长等职','历任伪三江省省长等职，在黑龙江地区推行日伪统治，参与经济掠夺和治安肃正。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19fc43233bf948d8bd0a7b06bb3d734c','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'率部投降日军','率部投降日军，任伪军高级将领，参与围剿东北抗日联军，活动范围包括黑龙江地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef6ffecc83c1492d9bc14470a72b66cc','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'黑龙江双城人','黑龙江双城人，九一八事变后投敌，率伪军配合日军进攻哈尔滨及黑龙江各地，后任伪满第四军管区司令官，负责北满地区治安，其伪军活动范围覆盖伊春、大箐山一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abedb515734d48d49f2c361750092d0c','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪满军高级将领，曾率伪军在三江地区（含佳木斯一带）参与围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ec21997becd4d3bb4f3909670ffb215','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原东北军将领','原东北军将领，九一八事变后投敌，率伪军配合日军进攻哈尔滨、佳木斯等地，镇压抗日武装，后任伪满第四军管区司令官，管辖包括佳木斯在内的三江地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e0df4238d06470cbc5fb0870d62fd7f','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪满军高级将领，曾率伪军配合日军在黑龙江、吉林等地围剿抗日武装，其军事活动范围覆盖佳木斯一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05217909f0924ffcbd60c0887b168730','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪满军高级将领，参与围剿东北抗日武装，长期在黑龙江地区活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79fc6d711fcf454e9e395e950594851f','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'黑龙江双城人','黑龙江双城人，九一八事变后投敌，历任伪吉林省剿匪司令、伪第四军管区司令官等职，率伪军配合日军镇压东北抗日武装，活动范围包括今黑龙江大庆一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44ccd31ec13544c1847727e6695059c0','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'黑龙江双城人','黑龙江双城人，九一八事变后投敌，任伪吉林省剿匪司令，率伪军进攻哈尔滨等地，后任伪满洲国军上将、第四军管区司令官，在黑龙江地区参与镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-055769ab152c4c9e8971bd06054628dd','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原为东北军将领','原为东北军将领，九一八事变后投敌，参与组建伪军，率部在哈尔滨、绥化、望奎一带围剿抗日武装，后任伪第四军管区司令官，管辖包括绥化在内的北满地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57213e25bcf9498fba86e22bcefbc7d1','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原为东北军将领','原为东北军将领，九一八事变后投敌，参与组建伪军，曾任伪满洲国军政部大臣、第四军管区司令官，负责北满地区（含绥化、海伦一带）的伪军指挥与治安肃正，配合日军围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc0491680e404394828a33cc859a64a8','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原为东北军将领','原为东北军将领，九一八事变后投敌，参与组建伪军，曾任伪满洲国军政部大臣、第四军管区司令官，负责北满地区\'讨伐\'抗日武装，其军事管辖范围覆盖绥化、绥棱一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c00d81434ea040f9812501c2f1f5cd87','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原东北军将领','原东北军将领，九一八事变后投敌，率伪军配合日军进攻哈尔滨及黑龙江各地，后任伪满军第四军管区司令官，驻防哈尔滨一带，镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54bc1d25a1d548c9901581f36d4c331c','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原东北军将领','原东北军将领，九一八事变后投敌，率伪军配合日军进攻黑龙江抗日武装，活动于哈尔滨、牡丹江、鸡西一带。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12e6884f2398463bae1ea17722f6d257','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'黑龙江双城人','黑龙江双城人，九一八事变后投敌，率伪军配合日军进攻哈尔滨及黑龙江各地，后任伪满军上将、第四军管区司令官，其伪军活动范围覆盖松花江下游包括鹤岗、兴山地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d66e0a518294ec39f4fd6ee1b5b5df8','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪满军高级将领，曾率伪军在三江地区（今鹤岗、佳木斯一带）围剿抗日武装，对黑龙江东部地区抗日力量造成较大破坏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-236bcda35cc54a0d8b72c99ee24638d1','d7ff4d06-0877-4db9-a955-c9c6eab34684',1931,'原东北军将领','原东北军将领，九一八事变后投敌，率伪军配合日军进攻黑龙江抗日武装，其伪军活动范围覆盖松花江下游及鹤岗、萝北一带，参与镇压当地抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c345b61a16941ec9e75328b378d0d2a','bf3b7389-2a12-42c5-a35c-bc6450f41891',1932,'在伪滨江省指挥伪军配合日军讨伐抗日武装','在伪滨江省指挥伪军配合日军讨伐抗日武装，其辖区涵盖今伊春、嘉荫一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9667ae246c294884b3ab7775c336e434','f97eb358-4b4c-4eb2-871e-0ba5578f7897',1930,'任伪第三军管区司令官','任伪第三军管区司令官，负责黑龙江地区警备，参与镇压抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e845aa4cf3ca4154bec254fe27dc8597','3ff511ac-09ea-43d7-9489-553bbd285abd',1931,'九一八后投敌','九一八后投敌，率部配合日军进攻黑龙江，参与江桥战役等，为早期汉奸武装头目。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-986e0d967cff4e09801a17f1817d0401','3ff511ac-09ea-43d7-9489-553bbd285abd',1931,'辽宁人','辽宁人，原东北军将领，九一八事变后投敌，率部进攻黑龙江，配合日军侵占齐齐哈尔等地，后任伪满洮辽警备司令，其伪军活动涉及黑龙江多地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0761a08ed28f435997ca302566853557','3ff511ac-09ea-43d7-9489-553bbd285abd',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，其部队活动范围涉及绥化以北地区，参与镇压抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d062cdd1f3f649f9afdfbc28d2d58678','3ff511ac-09ea-43d7-9489-553bbd285abd',1931,'原东北军将领','原东北军将领，九一八事变后投敌，率伪军进攻黑龙江抗日武装，其伪军活动范围一度覆盖黑龙江东部，包括鹤岗、萝北周边地区，参与镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b33d404466694bafa3d9d1828a548866','4aab5317-4f42-4571-878c-fb8a4d23424a',1931,'原东北军将领','原东北军将领，投敌后任伪黑龙江省警备司令，配合日军镇压抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
