INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e7e816cf69f4a7589f8e16183979bf0','4aab5317-4f42-4571-878c-fb8a4d23424a',1931,'原东北军骑兵旅长','原东北军骑兵旅长，江桥抗战后投敌，任伪黑龙江省警备司令，协助日军维持黑龙江地区殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
