INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de205a9027714257a7ccecd7f9109ec2','3e7e39bb-0789-420a-bb9d-e0d925c7a0a1',1930,'在伪黑河省任职','在伪黑河省任职，负责边境警备，参与封锁抗日联军，活动范围接近伊春、嘉荫。','危害等级B（乙级，市县厅局级）','hanjian');
