INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc49c3a40ef34e6ea7bf280ef4ced958','bfac73f6-8a1d-4afa-856e-d72b5db3877b',1930,'任伪汤原县县长','任伪汤原县县长，辖区与伊春、嘉荫相邻，推行归屯并户，配合日军讨伐抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4dffc3974d96490b96e613fa53a4079d','25cc3532-9f5a-4ea3-9006-50dd26df84bf',1930,'在伪三江省警务系统负责特务活动','在伪三江省警务系统负责特务活动，搜捕抗日人员，其活动涉及黑龙江东部包括伊春地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a9270e21fdd4810a4aa73016e3db069','244a9326-4bae-44bb-87e2-0a503c085bf2',1930,'佛山县（今嘉荫县一部分）伪县长','佛山县（今嘉荫县一部分）伪县长，推行日伪政策，协助日军管理边境地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5130a0ce4d840e8b0c72b38066e6a0d','677ee219-e42c-43eb-8e8d-82a7d4db6a23',1930,'萝北县与嘉荫接壤','萝北县与嘉荫接壤，任伪县长期间配合日军封锁黑龙江沿岸，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55d00dedd33b416b91593b17e6fdb0f6','6f52e9a8-d5be-47f8-bbd5-52c945abbf09',1931,'清朝宗室后裔','清朝宗室后裔，九一八事变后率先在吉林投敌，主持建立伪吉林省政权，后任伪满财政总长、宫内府大臣，其附逆行为对包括黑龙江在内的东北全境沦陷有直接影响。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c00f18df57d4a3391b5f55438549806','3698e318-565c-45a2-84f9-22826bb0ccaf',1932,'原东北军军官','原东北军军官，投敌后任伪满军职，后任伪三江省省长，管辖松花江下游及小兴安岭地区，包括伊春、大箐山一带，配合日军围剿抗日联军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fba4f00a3b814c58bc22a9e41598a6e2','3698e318-565c-45a2-84f9-22826bb0ccaf',1932,'原东北军军官','原东北军军官，投敌后任伪满军中将，后任伪三江省省长，三江省辖境包括今鹤岗、兴山地区，其伪政权统治直接覆盖该区域。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-291e6e4fadd241db85ac3166e721ba31','a51967e4-895a-4bb5-8150-e4910fc0b6ae',1932,'辽宁人','辽宁人，投敌后历任伪满地方官员，曾任伪三江省省长，管辖范围包括伊春、大箐山地区，推行保甲制、经济统制，配合日军镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d4609d5500c4b429b0f9edc5639dc3c','d5cd9e5d-d7b2-4b49-81aa-232cbae4bf77',1932,'投敌后任伪满地方及中央官员','投敌后任伪满地方及中央官员，曾任伪三江省省长，管辖伊春、大箐山一带，推行奴化教育及经济掠夺政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9c965a655694df4a9f636c9b65dae0e','60e609b4-cc55-480c-9f26-5a7d5c5a456f',1931,'投敌后长期在哈尔滨及滨江省任职','投敌后长期在哈尔滨及滨江省任职，负责警务及地方行政，其管辖范围覆盖黑龙江中部，包括伊春、大箐山周边，参与镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b08848820ec14334aaceb94c984366bd','60e609b4-cc55-480c-9f26-5a7d5c5a456f',1931,'长期在哈尔滨及滨江省任职','长期在哈尔滨及滨江省任职，镇压抗日活动，其管辖范围接近绥化、庆安地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3dc3791dbb554b3e87dc7d6d8b13fa4c','60e609b4-cc55-480c-9f26-5a7d5c5a456f',1931,'曾任伪哈尔滨警察厅长、伪滨江省省长','曾任伪哈尔滨警察厅长、伪滨江省省长，滨江省辖哈尔滨及周边，其警务系统影响黑龙江东部，参与镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79a6f204592d435191857591e619d298','ec9579c0-be35-4a9e-9348-aa104638b3a6',1930,'投敌后任伪滨江省警务厅长','投敌后任伪滨江省警务厅长，负责哈尔滨及周边地区治安，配合日军围剿抗日联军，其警务活动涉及伊春、大箐山地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-01b4158f1c0d4dffbeee040790117657','5ac4240b-376a-4029-99bd-8929e0a1f91c',1930,'伊春本地士绅','伊春本地士绅，日军侵占伊春后出面组织维持会，协助日军征发劳工、物资，维持地方伪秩序，直接服务于大箐山、伊春一带的殖民统治。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e61eaa9435ad4f86a6387a9226c18b85','2fb3d2fe-3f80-47c4-98fd-20f4dc291ed9',1930,'伪汤原县警务人员','伪汤原县警务人员，活动于小兴安岭东南麓，包括今伊春、大箐山一带，参与搜捕抗日联军及镇压民众，是当地伪警头目之一。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd9e7d2b4d494f2ab1968179f8503344','d0e0818b-5660-4970-9efb-1e5eef53d62e',1930,'铁骊县（今铁力市','铁骊县（今铁力市，邻近伊春、大箐山）保甲长，推行保甲连坐，协助日军征粮、抓劳工，镇压当地抗日群众。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79c832bf64c64a508aebd5f257791092','5a67f878-5471-4dc0-b9d5-ae4948d37100',1930,'佛山县（今嘉荫县','佛山县（今嘉荫县，属伊春市）维持会头目，协助日军控制黑龙江沿岸，征发劳工、物资，配合日军封锁抗日联军。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f7cb7c801244f8cbc3e4e61a9c5615c','a75040f7-4ed3-4936-9654-c5b6f9cb4e00',1930,'伊春林区伪林业把头','伊春林区伪林业把头，为日军掠夺小兴安岭木材资源，残酷压榨伐木劳工，直接参与经济掠夺，活动范围覆盖大箐山地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e77cfdd1d61440c8ba0c4c3c8b70edfb','88223946-fcfd-4641-9d78-acdaa8a3b85a',1932,'原中东铁路督办','原中东铁路督办，投敌后历任伪滨江省省长、伪满驻日大使等职，积极为日本侵略者服务，参与对黑龙江地区的殖民统治和经济掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f9df1e3ccbc408fa40f80f0dabc5377','df5a150b-bf47-40d9-89e5-ccedfba3b160',1932,'投靠日本后历任伪滨江省省长、伪满交通部大臣等职','投靠日本后历任伪滨江省省长、伪满交通部大臣等职，参与日伪在黑龙江地区的统治与交通控制，为日军侵略提供支持。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17cd3efcbfab465d9add6b6dfcb45cdb','360c9a89-7129-411d-add1-7c38a116bd3e',1932,'原东北军军官','原东北军军官，投敌后任伪满军将领，率部在黑龙江地区参与围剿抗日武装，镇压抗日军民，是伪满军事系统的重要汉奸。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04c3eddb838c458c9bce66a78396c4b2','5cde0bdb-0850-4a80-887e-3178e27ca571',1931,'九一八事变后投敌','九一八事变后投敌，历任伪满军要职，率部在黑龙江、吉林等地围剿抗日义勇军和东北抗日联军，是伪满军早期重要头目之一。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d73602930164dee994b018a3fb8fdf0','5d22f917-0d75-4436-92cf-8e76a41a0e7f',1931,'原东北军骑兵师长','原东北军骑兵师长，九一八事变后投敌，率部进攻黑龙江抗日军队，参与江桥战役等对抗日武装的作战，是黑龙江地区早期著名汉奸。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd16b10a09d844a0a81bd623ff7cf783','e9fe832e-ce07-44b6-8e8b-00617a387e30',1931,'原东北军军官','原东北军军官，投敌后任伪黑龙江省警备司令等职，率部配合日军进攻马占山等抗日部队，参与镇压黑龙江抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46dcb3ea984945149550e4847a152cfd','8e34d40e-4876-4b93-b340-27014ced51a3',1932,'投敌后历任伪黑龙江省公署要职','投敌后历任伪黑龙江省公署要职，参与日伪在黑龙江地区的行政统治，为日本殖民政策效力。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a256bc89b8dd48a280cd5a8d12047629','95a6a441-6d3b-4790-b18c-65b0681fcb3f',1932,'投靠日本后历任伪滨江省省长、伪满经济部大臣等职','投靠日本后历任伪滨江省省长、伪满经济部大臣等职，参与对黑龙江地区的经济掠夺和殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-418f8012767c4523b73361c8c23c7bd0','01bab29c-3cac-4375-be3a-498c1710fdce',1932,'在伪滨江省任职期间','在伪滨江省任职期间，积极参与伪满协和会活动，推行日本殖民思想宣传，协助日伪控制黑龙江地区民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc9aaa6b48be443cbe60dfc7a98abee1','12a438a6-5567-4f62-9984-4b9aab82b2ec',1935,'在伊春地区担任伪警察头目','在伊春地区担任伪警察头目，配合日军和伪满军围剿东北抗日联军，镇压当地抗日群众，搜集抗日情报，是伊春地区直接参与日伪统治的汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03b8eef5af26409eae466a7db84e14ef','9b3a11a5-236c-4487-9753-0fb179251be8',1932,'在汤原地区组织维持会','在汤原地区组织维持会，为日军筹粮筹款、提供情报，协助日军镇压汤原抗日游击队和当地抗日群众，其活动范围接近伊春汤旺地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60b0db94cdbf429cbe866bb87ceedc2a','2e41c217-0dc1-4a20-9f21-46511a1001d6',1933,'担任伪汤原县县长期间','担任伪汤原县县长期间，推行日伪保甲制度，配合日军围剿抗日联军，征发劳工，掠夺当地资源，对汤旺河一带抗日根据地构成威胁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7059c89b1832432fbc1e1169da0721d7','78a77d43-b477-4367-94bc-f02bbe96941b',1937,'原为东北抗日联军第九军军长','原为东北抗日联军第九军军长，1939年投敌叛变，后任伪满军警佐，带领日伪军围剿抗日联军，在黑龙江伊春、汤原一带活动，是著名的叛徒汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-90a257a2973f471da7c66a3d25196ff4','1165b92f-53ab-4fb7-b52a-b77ece99343d',1939,'原为东北抗日联军第八军军长','原为东北抗日联军第八军军长，1939年投敌叛变，后任伪满劳工大队长等职，配合日军镇压抗日力量，在黑龙江东部包括伊春地区活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbee118cbc1c434b9d3268192839e3ec','e0673faf-5ceb-4b7e-b2c0-ec245eb6b11c',1935,'在汤原县任伪警察署长','在汤原县任伪警察署长，直接参与对汤旺河抗日游击根据地的围剿，逮捕和杀害抗日群众，是当地伪警系统的重要汉奸。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98e96209020144fba077a1e12cff3d8d','65c04d23-c7c2-43c1-848e-c3b7485df49e',1938,'部分抗联叛徒在伊春、汤原一带投敌后','部分抗联叛徒在伊春、汤原一带投敌后，为日军带路围剿抗联密营，出卖抗日将领，具体姓名因史料记载有限，但此类叛徒在汤旺地区活动确凿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e2ec9fc8d664e0c9e93c33905b33de6','4c46f2c6-b00b-417d-87d1-4220e35b5ef7',1930,'曾任伪滨江省省长','曾任伪滨江省省长，在哈尔滨及周边地区推行日伪殖民统治，后任伪满交通部大臣，协助日军运输物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37f30715821a4ac2aa5c2963a60106d3','45a47184-293d-46f5-92cc-a9004641b39f',1930,'原东北军军官','原东北军军官，投敌后任伪满军高级将领，在黑龙江地区参与围剿抗日武装，镇压民众抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd6a65c7beb6499e848ff74f8e957855','5d1834c0-8031-4ad1-963b-563430d24e98',1931,'九一八事变后投敌','九一八事变后投敌，任伪满军将领，在黑龙江地区参与镇压抗日义勇军和东北抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6b5c0ed28a54993ae2ddd6b2e7dd3ba','dc432f70-2f65-4282-b318-39aaba5b016e',1931,'原东北军将领','原东北军将领，九一八事变后投敌，参与日军侵占黑龙江、热河等地，任伪满军职，镇压抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-463255392cde4172bf538430117bee6f','a2feb3dc-ecfd-4255-8762-573674b397c7',1931,'原东北军骑兵旅长','原东北军骑兵旅长，投敌后任伪满黑龙江省警备司令，在黑龙江地区参与围剿抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76028fdb9f8e4a379b1d5eced24bf629','fbf3eaa8-c0bd-4df9-a4e8-da9a20ff99eb',1930,'投敌后任伪满军将领','投敌后任伪满军将领，在黑龙江地区参与镇压东北抗日联军，推行日伪军事统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e35c9fd3030a4323b09ed144579f0a69','23950703-7ee4-4f55-8a1b-f46c345ab4be',1930,'投敌后任伪满江防舰队司令','投敌后任伪满江防舰队司令，在黑龙江、松花江流域配合日军封锁抗日武装，参与镇压活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b992251e4704d0aac61cf20bc5e8cbd','ce3fbbde-d221-4b28-98e1-73f346cdcce1',1930,'曾任伪满江防舰队司令','曾任伪满江防舰队司令，在黑龙江水域配合日军行动，参与封锁和围剿抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc2ee2778ec44d45a7630626c9386193','6f815c10-3bb8-4f59-9586-0772eeb0a70b',1930,'投敌后任伪满军职','投敌后任伪满军职，在黑龙江地区参与军事行动，协助日军镇压抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67ac43b89c3e44f0a646dfa8f2af1653','312b1f62-fb98-4098-86a0-3b5bba771672',1930,'在伊春地区担任伪警察头目','在伊春地区担任伪警察头目，配合日军维持治安，镇压当地抗日民众，推行保甲连坐制度。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd423919e94043a3a10f322fa3bfdba1','3b01b2bd-8ea6-4f6e-80c9-e9ad6b23793e',1930,'在汤原及伊春周边地区任伪县长','在汤原及伊春周边地区任伪县长，推行日伪政策，协助日军征粮、抓劳工，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71c8c4ce5e984f9fa4009dd1d8a6b011','f518feac-39f7-475e-b456-aa53ba3150d7',1930,'在伊春北部佛山县任伪县长','在伊春北部佛山县任伪县长，配合日军统治，镇压当地抗日力量，推行殖民经济政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1184781a119f4ab394df179f4d97b12f','3298b043-2cbc-4cf8-92f4-df7ae8cb5e0c',1930,'在铁骊（今铁力）地区任伪县长','在铁骊（今铁力）地区任伪县长，协助日军维持统治，镇压抗日民众，征收苛捐杂税。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f6da136c99841e79f5c132009580bd0','dd9ecd0e-cfda-474f-ae6d-f4a45a81e0a3',1930,'在嘉荫地区任伪县长','在嘉荫地区任伪县长，配合日军封锁黑龙江沿岸，镇压抗日活动，推行日伪法令。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-629a49d194fb4b9d935820ce28d48d3a','6ef43cd6-f825-47ba-b82a-2050d464b3f5',1930,'在伊春地区担任伪保甲长','在伊春地区担任伪保甲长，协助日军监控民众，举报抗日分子，推行保甲制度。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5420ca861f914019973297a380b3e7ba','29366e09-e1ad-48b1-be03-60f4fafd32e8',1931,'原东北军将领','原东北军将领，1931年投敌，组织伪军配合日军进攻抗日武装。后任伪满洲国军政部大臣、伪第一军管区司令等职，其军事指挥体系涉及黑龙江地区，包括伊春、铁力一带的伪军警“讨伐”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-70d93ec41175490480cd82ea527a7931','05dbae9d-9585-40a2-9be2-ee735af84bd9',1932,'原东北军军官','原东北军军官，投敌后任伪军职，参与对黑龙江地区抗日联军和民众抗日武装的“讨伐”，其活动范围包括松花江下游及小兴安岭一带，与伊春、铁力地区接近。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c83ca6b19ee8476ab9c6101fffe200b8','a3ca8604-93a0-4514-8e81-634f77ff76c2',1932,'辽宁金县人','辽宁金县人，九一八事变后投敌，历任伪滨江省省长、伪经济部大臣等职。滨江省辖境包括今哈尔滨及周边，其经济统制政策覆盖黑龙江多地，伊春、铁力地区的木材、矿产等资源被其伪政权体系掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5218b3c7cde0438ab809d2834a74e1b0','a3ca8604-93a0-4514-8e81-634f77ff76c2',1932,'原商人','原商人，投敌后任伪滨江省省长，管辖依兰等地，协助日军掠夺资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdd211d3eb7b43cba48686316f44b44d','0191a4d8-5c14-4b53-8640-c6e60b50568f',1932,'原东北军军官','原东北军军官，投敌后历任伪吉林省省长、伪间岛省省长等职，参与伪满地方政权建设和对抗日武装的镇压。其伪政权活动范围虽主要在吉林，但与黑龙江东南部及伊春、铁力地区邻近，有行政和军事协同。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d3daf022c194c868d99934fadbff79f','03fdd492-8343-48cd-9e4f-08cd710412fb',1932,'辽宁人','辽宁人，投敌后历任伪滨江省省长、伪司法部大臣等职。在滨江省任内推行保甲制、连坐法，镇压抗日民众，其辖区包括今哈尔滨及周边，对伊春、铁力地区有行政管辖关系。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a38c963de7204e7ea683ef39e488d2d4','6123645f-3c0d-41b1-813e-ab937db4ff95',1932,'投敌后长期在伪滨江省任职','投敌后长期在伪滨江省任职，历任伪哈尔滨市市长、伪滨江省省长等职，推行伪满法令，协助日军征发劳工、掠夺物资，其行政体系覆盖黑龙江中南部，包括伊春、铁力一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a91f12bc8ba04470b1c92a79878e431f','9b7a538d-c874-44f1-b0cf-f13505821a4a',1932,'投敌后历任伪滨江省公署参事官、伪三江省省长等职','投敌后历任伪滨江省公署参事官、伪三江省省长等职，参与伪满地方政权和对抗日联军的“讨伐”。三江省辖境包括松花江下游、小兴安岭东部，与伊春、铁力地区接壤。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-748d1760ab4440d6b0dee9af048b584d','f61e770c-2de1-4666-a10d-6da04e55a531',1932,'投敌后历任伪三江省省长、伪东安省省长等职','投敌后历任伪三江省省长、伪东安省省长等职，在任内配合日军对抗日联军进行“大讨伐”，推行“集团部落”政策，其辖区与伊春、铁力地区邻近，对当地抗日力量造成破坏。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a55e38bfbdf45f2b3a34473623bf7ee','6dc1cb48-8099-4b46-9b49-554d7fdf0da3',1932,'投敌后任伪黑河省省长','投敌后任伪黑河省省长，管辖黑龙江北部边境地区，配合日军封锁边境、镇压抗日活动。其辖区与伊春北部接壤，对铁力、伊春地区有间接影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3a35b252137440eba63348f9454c0ce7','b20322b5-eccb-435f-88c0-61d1ceb24050',1932,'投敌后历任伪黑河省省长、伪龙江省省长等职','投敌后历任伪黑河省省长、伪龙江省省长等职，在黑龙江地区推行伪满政策，协助日军征发劳工、掠夺资源，其行政体系覆盖黑龙江多地，与伊春、铁力地区有行政关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a16972eb91a74dd1ac536458d05117fe','ea4be321-3e84-4b01-9b2d-04664c201c3b',1930,'伪满洲国时期任铁力县县长','伪满洲国时期任铁力县县长，推行保甲制、粮谷出荷、劳工征发等政策，配合日军和伪警察镇压当地抗日民众，是铁力地区直接附逆的伪政权头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f607386759754302b62518e774f29b0a','4c1965dd-7737-489b-9de1-ff012e4e8daa',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪军职，参与进攻黑龙江抗日武装。后任伪热河省省长，其军事活动曾涉及黑龙江地区，与伊春、铁力地区有间接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-955aade3ad384e08913221320e90d7f6','d81bd786-2d3d-43f4-b4f5-f67ea55ff940',1931,'原东北军骑兵旅长','原东北军骑兵旅长，1931年投敌，任伪黑龙江省省长、伪军中将，配合日军进攻马占山等抗日部队。其伪政权管辖范围覆盖黑龙江大部，包括伊春、铁力地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e62141edb584a56a31c4abf9e60d8c8','58213e7d-ae9f-46d2-91b0-9c12b47e2d9f',1932,'投敌后历任伪黑龙江省公署参事官、伪龙江省省长等职','投敌后历任伪黑龙江省公署参事官、伪龙江省省长等职，在黑龙江地区推行伪满法令，协助日军镇压抗日力量，其行政体系涉及伊春、铁力一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f0720c1f57774d9f96ad1616bab8c198','9ca44b09-a315-4e62-86f5-2a48e0956954',1932,'投敌后历任伪黑龙江省公署厅长、伪滨江省省长等职','投敌后历任伪黑龙江省公署厅长、伪滨江省省长等职，参与伪满地方政权建设，推行保甲、征发劳工等政策，其活动范围覆盖黑龙江中南部，与伊春、铁力地区有行政关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2973cc677e44af39428c144d7d4dcec','e03dac27-0376-4b8d-8ad8-8a6d98bf2880',1930,'伪满洲国时期在铁力县任伪警察头目','伪满洲国时期在铁力县任伪警察头目，指挥伪警察配合日军“讨伐”抗日联军和民众抗日武装，抓捕抗日人员，推行保甲连坐，是铁力地区直接参与镇压的汉奸。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2473935357574c09aca0d7cbb52ccde9','36b2cafb-006d-4cf1-a526-405dda0fa2cf',1930,'伪满洲国时期任伊春县县长','伪满洲国时期任伊春县县长，推行伪满政策，协助日军掠夺小兴安岭森林资源，征发劳工，镇压当地抗日活动，是伊春地区直接附逆的伪政权头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5b98fc4415ad46acbdab5c587826516d','996fb1d7-b202-4451-92e4-d7887c2732f3',1930,'伪满洲国时期在伊春县任伪警察头目','伪满洲国时期在伊春县任伪警察头目，指挥伪警察配合日军“讨伐”抗日联军，抓捕抗日民众，推行保甲连坐，是伊春地区直接参与镇压的汉奸。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6109985305bb40119399f1098600a8b2','a0678cb8-6153-4988-92f3-8b53f6dc778b',1934,'直接管辖佳木斯所在的三江省','直接管辖佳木斯所在的三江省，积极协助日军“讨伐”抗日联军，推行保甲制度，强征劳工，镇压当地反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4568003ddfd4793aabc8f02a544ca2d','3d945ea7-f684-49bd-b1ce-920a1bb6e761',1937,'在任三江省省长期间','在任三江省省长期间，强化日伪统治，配合日军大扫荡，破坏佳木斯周边抗日根据地，实施粮食统制，造成民众饥荒。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ca63fcc04ffb46b7bc286fd716ec19d8','f13511d1-f2ee-4b1e-9e74-b1e31c293e78',1940,'继续推行日伪政策','继续推行日伪政策，在佳木斯地区组织“协和会”活动，协助日军抓捕抗日地下工作者，强推“出荷粮”政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8afbd73f7bae46e7a20f347496d4062a','3f4271bd-442d-458c-8498-c95925dc0313',1942,'在佳木斯地区强化经济统制','在佳木斯地区强化经济统制，为日军提供物资支持，参与镇压抗日联军剩余力量，迫害爱国群众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4afbf42ea7f24983ba7e306e62fd6d09','ca9eed36-62c2-4ea4-ba1f-f963b5690c8b',1944,'日本投降前夕仍效忠伪满','日本投降前夕仍效忠伪满，在佳木斯组织“防卫队”，企图抵抗苏军，并协助日军销毁罪证。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eacb7aebaeed47559bde0d7a6e0e78cf','4a273e83-22f3-4214-99fa-688f5b988033',1937,'作为佳木斯市最高伪职','作为佳木斯市最高伪职，推行奴化教育，强制市民学习日语，配合日军“治安肃正”，多次组织搜查抗日分子。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57b0b893e4114facb253e1aaf0e651c4','8ea6a9cf-9671-4c1f-a729-57fa855c3cd8',1941,'任内加强警察特务统治','任内加强警察特务统治，建立“思想矫正院”，关押迫害反满抗日人士，为日军提供劳工作业。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef5746525cd640f0a3dcffc09f0ea7e9','70e5fd28-0ad6-40f9-8b44-29800fd304a3',1935,'直接指挥警察特务','直接指挥警察特务，多次破坏佳木斯地下党组织，逮捕并刑讯抗日志士，参与“三江大讨伐”行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec6c0bbeab3a4c6a872cadef2c8f44a2','8dd792bf-163f-4925-95be-b95fc74f71b1',1938,'积极宣传“日满亲善”','积极宣传“日满亲善”，组织“协和义勇奉公队”，协助日军收集情报，煽动民众告发抗日分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c8c29518f1b4769928ecb6ca5aae4df','f3e6b8d2-f0ad-49c0-91d1-67a5d51ca8a1',1939,'为日军宪兵队充当翻译','为日军宪兵队充当翻译，参与审讯和刑讯抗日联军被俘人员，直接导致多名志士牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66eaa902e9204685967b8f7359b71680','95b8c593-3ff2-4a85-94da-5334c8ae2f44',1936,'在桦川（今属佳木斯）推行“集团部落”','在桦川（今属佳木斯）推行“集团部落”，烧毁民房，强迫农民并村，切断抗联与群众联系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-769d3dd9aa4e4cf19c161589c55659ba','b878be54-10be-485d-a5d2-ed14a6a09606',1937,'配合日军围剿汤原抗日游击队','配合日军围剿汤原抗日游击队，强征粮食和牲畜，镇压当地农民反日暴动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5359071e45a546e5a02c4552d0358923','fa81a622-4eb1-4610-a3bf-c1c33449317c',1932,'在依兰（今属佳木斯）协助日军建立伪政权','在依兰（今属佳木斯）协助日军建立伪政权，组织“自卫团”对抗抗联，征收苛捐杂税。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fa199d9ecc94ed9a36c8f06f91cc90f','b32095fa-7bbe-4aac-a969-4f212ca6f4ba',1932,'原东北军军官','原东北军军官，投敌后任伪满军职，活动于三江省（今佳木斯地区）一带，参与镇压抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1648fe4dcba54e47be59803c04992dbd','99a53223-109d-457e-a487-2d2dac458ca1',1931,'曾任伪三江省省长','曾任伪三江省省长，省治设于佳木斯，负责该地区伪政权的行政统治，推行保甲制度、经济统制等附逆政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-699a7497b8a74c99933dd2570d0e1b83','99a53223-109d-457e-a487-2d2dac458ca1',1931,'伪满时期曾任伪三江省省长','伪满时期曾任伪三江省省长，省公署驻佳木斯，管辖佳木斯、富锦、同江、抚远等地，推行日伪殖民统治，征发劳工、掠夺资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-799d7e63f16645388afba33a2abc81ca','99a53223-109d-457e-a487-2d2dac458ca1',1931,'任伪三江省省长期间','任伪三江省省长期间，推行伪满政策，其统治范围包括双鸭山、友谊地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8748f10422434e2b89447a6ee80be54e','99a53223-109d-457e-a487-2d2dac458ca1',1931,'曾任伪三江省省长','曾任伪三江省省长，管辖范围包括今鹤岗地区，积极推行伪满殖民统治政策，配合日军征发劳工、掠夺煤炭资源，对当地民众实施高压统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-252f95ce50cf41afa446107f44f81692','1ffcd999-4ad5-49c4-8dec-88e5ebf407bf',1930,'伪满官僚','伪满官僚，曾任伪三江省省长，驻佳木斯，主持该地区伪政权的行政事务，配合日军对三江地区抗日武装的镇压。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f1b7298b7c1480d99a6965fcfb778c2','a645d78a-6c4a-488d-a708-2eab154286e3',1930,'在伪三江省（佳木斯）任职期间','在伪三江省（佳木斯）任职期间，推行奴化教育、经济统制等政策，协助日军巩固对三江地区的殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7a7ddf642577491d938b1c6981a9819b','054b89f7-604f-46e0-8c1f-085eb72a5c7b',1932,'原为抗日武装人员','原为抗日武装人员，后叛变投敌，任伪三江省警察厅厅长等职，在佳木斯一带参与围剿抗日联军，出卖抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68bf9ca56a3247a1b5b963268690f6de','25aaf2f8-dffe-4067-b894-bbaab6684986',1939,'原为东北抗日联军将领','原为东北抗日联军将领，1939年叛变投敌，任伪职，在佳木斯、勃利一带参与围剿抗日武装，后成为当地著名汉奸。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef254d52e8c0480e948406d906403e41','09d23b68-3250-438f-b4e3-f9c2a1570bc3',1930,'在伪三江省（佳木斯）任职期间','在伪三江省（佳木斯）任职期间，负责警务与治安，配合日军镇压抗日活动，推行保甲连坐制度。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1871abb1ce44d6199b2c5fae7095bdf','09d23b68-3250-438f-b4e3-f9c2a1570bc3',1930,'伪满时期任三江省警务厅厅长','伪满时期任三江省警务厅厅长，驻佳木斯，统管三江地区伪警察系统，积极推行保甲连坐制度，配合日军镇压抗日力量，抓捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-934f1af790fd43ef8e76b93ad175347a','09d23b68-3250-438f-b4e3-f9c2a1570bc3',1930,'任伪三江省警务厅厅长期间','任伪三江省警务厅厅长期间，指挥伪警察配合日军在双鸭山、友谊一带镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-985e15c7f0614909a164581a038b7886','66f1d94f-1335-433e-b199-5f0221361b4d',1930,'在佳木斯地区负责伪满协和会事务','在佳木斯地区负责伪满协和会事务，推行奴化宣传、思想控制，协助日军巩固殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-696bb1199ded4c2b918152e433360140','0e031cc8-2a59-4520-800f-bf454a2e043b',1930,'在伪三江省（佳木斯）任职期间','在伪三江省（佳木斯）任职期间，推行经济统制政策，掠夺当地资源，为日军侵华战争服务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-541b1a7d64d14d9f80cdea047b2f8b51','23b236a2-095d-4501-b11f-7373d18d763b',1930,'在佳木斯地区推行奴化教育','在佳木斯地区推行奴化教育，篡改历史，强制教授日语，毒害当地青少年。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6afc51b0fe05496880359e78ef9dbd5e','7d268e3c-be34-498e-8a92-6007d9d872a2',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪满军职，其活动虽主要在热河，但作为伪满高级将领，其行为影响覆盖东北全境包括黑龙江。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0d94338310549e78090264132a89529','7d268e3c-be34-498e-8a92-6007d9d872a2',1931,'原东北军将领','原东北军将领，九一八事变后投敌，率伪军进攻黑龙江，后任伪满军上将，其伪军活动涉及黑龙江多地，包括松花江下游鹤岗、兴山一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7632e79e8ec45b8b33526038dfaf2c9','cb52cdba-3211-4d5e-bfb9-f12367414861',1931,'原东北军将领','原东北军将领，投敌后任伪满军高级职务，参与镇压东北各地抗日武装，其军事行动涉及黑龙江地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a050882ffc3b40a09c41790350cffcb0','a49de588-3798-421d-a6d1-648de9d31d1e',1931,'原东北军将领','原东北军将领，投敌后任伪满军职，参与围剿抗日武装，其活动范围涉及黑龙江部分地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e341f5527f114be685a39d8c1f19633b','ffc86300-d345-4c1c-8478-cee125ef6e61',1930,'在佳木斯地区负责特务活动','在佳木斯地区负责特务活动，搜捕抗日人员，破坏抗日地下组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-00cbd0477d7549da836ecb5aea520575','496dd963-a5f6-4009-9fe1-3e648d92c119',1930,'在佳木斯附近桦川县任伪县长','在佳木斯附近桦川县任伪县长，推行保甲制度，征发劳工，配合日军掠夺当地资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-397c621b565a4ec2ac6dd7d16275743c','42b97ed6-f890-41cf-bcea-ce65657586d3',1930,'在佳木斯地区富锦县任伪县长','在佳木斯地区富锦县任伪县长，协助日军征粮、征工，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8314eaf4e9394550b338f5a2bdaa100b','0f320130-3b80-4c9f-b1c7-94ee07292e1d',1930,'在同江地区任伪县长','在同江地区任伪县长，推行殖民统治政策，配合日军对黑龙江沿岸抗日武装的封锁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad135a0aa1234c58b5221be106985b33','08b0a6e4-7f3a-490c-877a-f681f2a52222',1932,'原东北军军官','原东北军军官，投敌后任伪军旅长、师长，驻防佳木斯、富锦一带，参与围剿东北抗日联军，镇压三江地区抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6e346552b6794795b5a972be4971df5d','aedaff40-e5df-494d-80ff-4124f8c67591',1932,'原东北军军官','原东北军军官，投敌后长期在佳木斯、三江地区任伪军要职，参与对东北抗日联军的围剿，1945年后继续与人民政权为敌。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1cfc0a3dde684494889b2a109deac7ff','2ddd1a46-c89f-46b7-8318-8910fb64a01e',1932,'原为抗日武装人员','原为抗日武装人员，后叛变投敌，任伪三江省警务厅厅长等职，在佳木斯、依兰、勃利一带配合日军围剿抗日联军，残害抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1d0665956e547509d34f12fe36764a9','75fa4dfa-7c8b-44f4-9e59-178f7e3558df',1939,'原东北抗日联军第八军军长','原东北抗日联军第八军军长，1939年叛变投敌，任伪三江省保安团团长等职，在佳木斯、勃利、依兰等地协助日军围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-30f7b290bb694eaca5fb94cf45baa2d7','b048edfc-6b9b-490e-9828-dd1fe791eb29',1935,'伪满时期任三江省协和会会长','伪满时期任三江省协和会会长，驻佳木斯，配合日伪推行殖民思想宣传、劳工征集和物资统制，为日本侵略政策服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ff597f3d98c498ebd9a9df1e46b1dd7','dfc98a37-1a3b-4e30-9092-d21585bd65e2',1937,'伪满时期曾任佳木斯市市长','伪满时期曾任佳木斯市市长，推行日伪市政管理、保甲制度和物资配给，协助日军征发劳工、镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aad3b713089d431896e0e1f66e9d829c','a6d09be7-89f3-447a-be33-55608e9d1097',1931,'原东北军将领','原东北军将领，九一八事变后投敌，率伪军配合日军进攻黑龙江、佳木斯等地，后任伪满军政要职，参与对东北抗日武装的镇压。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c66b954fdfc545d7b8fc1ea1180936d6','a6d09be7-89f3-447a-be33-55608e9d1097',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪满军高级将领，其部队曾参与黑龙江地区军事行动，配合日军镇压抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e48fda0a952e47158dcdd2200d5f3b27','ed0132cc-3c8c-453d-b639-f43395ef8261',1931,'原东北军将领','原东北军将领，投敌后任伪满军要职，其指挥的伪军活动范围包括牡丹江、佳木斯一带，参与围剿抗日联军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-577abcd4289f4b1ab29d240776b88a52','7c62a3ec-be27-4fe8-a71d-1815316b74ed',1935,'伪满时期在三江省警务厅任职','伪满时期在三江省警务厅任职，驻佳木斯，负责特务情报工作，搜捕抗日人员，破坏中共地下组织和抗日群众团体。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a2c568455f24800aab2043fd002f5a2','613e2bbb-9124-4528-a9bc-7df2bc851235',1934,'伪满时期历任汤原县县长、三江省民政厅厅长等职','伪满时期历任汤原县县长、三江省民政厅厅长等职，在佳木斯及周边地区推行保甲连坐、劳工征集和粮食统制，配合日军殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f237c929c7db409fb459186b5c2c2cc8','16c9a8e6-854c-4ee2-8b0f-f01647cba277',1932,'镇压东北抗日联军','镇压东北抗日联军，在佳木斯、同江等地推行‘归屯并户’，制造无人区，屠杀抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b0d29f7d30a4413ba8182ae350d6c950','e58b633b-2109-4832-954e-0cf0bbe926f6',1934,'在佳木斯地区实施殖民统治','在佳木斯地区实施殖民统治，强征劳工，配合日军‘讨伐’抗联，推行经济掠夺政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-595117b2fab14c2f9f1ac5eeb850bd16','c39de2c6-dd7e-49dc-8ebe-2265c6397424',1935,'作为日本籍次长','作为日本籍次长，主导佳木斯地区治安肃正，组织‘宣抚班’瓦解抗联，迫害地下党员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f285df9338a4d3d8b9605886914d779','c1e33f97-bf09-4728-8b11-193bca9ca504',1936,'指挥伪警察在佳木斯、同江等地搜捕抗联联络站','指挥伪警察在佳木斯、同江等地搜捕抗联联络站，逮捕杀害多名抗日志士，参与‘三江大讨伐’。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6f7854357574091a6c979ab6ade56a8','55280b8c-e154-418a-845f-d41a8c255be0',1933,'审判抗日人士','审判抗日人士，以‘反满抗日’罪名判处大量抗联战士及群众死刑或重刑，在佳木斯制造多起冤案。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc29dea5b0114732bd8fcba653a5c4fc','ddbc189e-24d9-4c5c-be14-c772d166dab5',1932,'在同江地区强制推行‘保甲制度’','在同江地区强制推行‘保甲制度’，组织汉奸自卫团，协助日军清剿抗联游击队，强征粮食支援日军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-073ecedcb7f84e31ac1d2e684df7c72b','b9c35ce7-8a76-49b5-8d3c-3ad53fc17caf',1933,'率伪警察多次袭击同江境内的抗联小分队','率伪警察多次袭击同江境内的抗联小分队，破坏地下交通线，逮捕并刑讯逼供抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9f3ea2ed80c4e92aa8c170236d66cf8','626abfd5-b01b-4930-b3b2-bcd1b58bd585',1937,'在佳木斯地区组织‘协和会’宣传奴化思想','在佳木斯地区组织‘协和会’宣传奴化思想，搜集抗日情报，协助日军‘讨伐’抗联，迫害爱国学生。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-739a58203ffb4fb5944369511bb13048','8dcac458-d1d2-46c3-83a8-a76032a7f670',1935,'在佳木斯、同江等地推行‘产业开发计划’','在佳木斯、同江等地推行‘产业开发计划’，强占农民土地，为日军提供粮食和木材，压榨劳工。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56cd7fece8d046fe9a650165ba7628ce','e4ed9329-f617-41a5-82fd-79374f4dc550',1938,'在佳木斯市区设立多处特务据点','在佳木斯市区设立多处特务据点，破坏抗联地下组织，逮捕并杀害多名地下党员和进步青年。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8cb2201ee2a0439f95e9fa2a0249be02','ec338c26-bc06-4829-a325-2b86a6e2d4cb',1939,'在同江农村组织‘协和会’分会','在同江农村组织‘协和会’分会，强迫农民检举抗日分子，配合日伪军‘讨伐’抗联，收缴民间武器。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc8697c9dee044b09c7bfccf40e0cfa7','10677b3b-03a2-4577-be51-b0a5d97976f1',1940,'率保安队参与‘三江大讨伐’','率保安队参与‘三江大讨伐’，在佳木斯周边山区搜捕抗联战士，烧毁抗联密营，杀害伤员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da165bd6c6d048dea038229bf2fb002a','757f946e-ddfa-4f4d-80e8-b625fa50d270',1932,'原东北军军官','原东北军军官，投敌后任伪满军将领，曾驻防佳木斯地区，指挥伪军配合日军对东北抗日联军进行讨伐，镇压当地抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de6d0cb811754fcb8220257f9f7db901','20a81cdb-cc4a-4e6a-8c12-48b6b397237d',1932,'原为东北抗日联军将领','原为东北抗日联军将领，后叛变投敌，任伪三江省警务厅警佐及伪自卫团团长，在佳木斯、依兰、勃利一带配合日军搜捕抗日人员，出卖抗日组织情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac33fedc6d0b4c3185175cf38e99bb72','7f4ea3f3-54cb-45e3-9abb-518673b814d8',1939,'原东北抗日联军第八军军长','原东北抗日联军第八军军长，1939年叛变投敌，任伪三江省协和会会长、伪自卫军司令，在佳木斯、勃利、依兰等地协助日军围剿抗联，残害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96b68369df324510b14638372194afbd','43779156-1e7f-488a-9be5-0a08becbb71f',1934,'伪满时期长期在佳木斯任职','伪满时期长期在佳木斯任职，曾任伪三江省民生厅厅长、伪佳木斯市长，推行日本殖民经济政策，强征劳工、配给物资，协助日军掠夺当地资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ea1de5591b554d6e8a6d9b37f25751a0','11a51f99-e7e3-42f9-921d-593d7ffc7001',1932,'九一八事变后佳木斯沦陷初期','九一八事变后佳木斯沦陷初期，组织伪维持会并任会长，协助日军维持地方秩序、征发物资、招募伪军，为日军占领佳木斯提供地方支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-299a5293606949c1918e64f05e486f7e','743cdb4c-4e29-4e21-b8fa-8afa8964659b',1933,'伪满时期在佳木斯及桦川一带任职','伪满时期在佳木斯及桦川一带任职，曾任伪桦川县公署参事官、伪佳木斯街长，协助日军推行街村制、保甲制，管理地方行政并配合经济掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f2d15d01c074253a63076fc8c7b5aa3','696eddfb-53ef-41c5-9a37-ab62f90435e9',1935,'伪满时期任三江省教育厅厅长','伪满时期任三江省教育厅厅长，驻佳木斯，推行奴化教育，强制学校使用日语、篡改历史教材，向当地青少年灌输亲日思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09305c973f664393b265c31525848828','5f95bf11-c185-4bbe-a420-beb6054536d4',1936,'伪满时期任三江省实业厅厅长','伪满时期任三江省实业厅厅长，驻佳木斯，负责矿产、林业、农业资源开发，协助日本侵略者掠夺三江地区煤炭、木材和粮食。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d60bfee4187441898493f50470667565','0dcb7df3-0ca7-471d-b01e-024edfd45d93',1930,'伪满时期在汤原、佳木斯一带任伪警务科科长','伪满时期在汤原、佳木斯一带任伪警务科科长，指挥伪警察配合日军讨伐抗日联军，破坏抗日地下组织，抓捕抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4717cb22e63d4090a42aef3a0cc7a91c','0dcb7df3-0ca7-471d-b01e-024edfd45d93',1930,'在汤原、佳木斯交界地区指挥伪警察讨伐队','在汤原、佳木斯交界地区指挥伪警察讨伐队，参与围剿抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e37e608098a4bb6a9c4f369f08dea44','85ce5079-3b5a-4572-b728-35984aa0078b',1932,'依兰沦陷后组织伪维持会并任会长','依兰沦陷后组织伪维持会并任会长，协助日军在依兰、佳木斯一带征粮、征夫，维持殖民统治秩序。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6813113ae53d4c489f2f4bd4e29a6b80','bcc3dd47-9563-4717-937e-509f71c9d894',1934,'伪满时期在勃利、佳木斯一带任保甲长及伪自卫团团长','伪满时期在勃利、佳木斯一带任保甲长及伪自卫团团长，推行保甲连坐，配合日军搜捕抗日人员，欺压当地百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1dea915b5fb9455ab4d0f02cfc3fb025','01663276-bf86-49ba-87ca-2188cb5bed28',1932,'原东北军将领','原东北军将领，1932年投敌，任伪满第四军管区司令，驻佳木斯，负责镇压三江地区抗日武装，多次围剿抗联部队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7baac221bf6426dbb5416c0b8ae1111','01663276-bf86-49ba-87ca-2188cb5bed28',1932,'吉林双城人','吉林双城人，原东北军将领，后投日，任伪满第四军管区司令官，驻守佳木斯，镇压抗日武装，参与“讨伐”东北抗联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1f05670f97943d781d04be9d7dd0f7e','3d963407-0f8e-4f46-bf4f-8c9a7ac6bfba',1934,'伪满三江省（辖佳木斯、富锦等县）省长','伪满三江省（辖佳木斯、富锦等县）省长，推行日伪“治安肃正”政策，组织保甲制度，协助日军屠杀抗联及平民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b16d61aee8784670b42eb2f9b0e5a8ca','cdd6f952-748b-491d-a0e1-b898d7d39d9d',1932,'原地方士绅','原地方士绅，投日后任富锦县伪县长，强征粮食、劳工，配合日军建立“集团部落”，迫害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f8d58e019fba405a9f64e0a667169326','069cde12-8847-4803-92be-27a8d315ad04',1937,'伪佳木斯市首任市长','伪佳木斯市首任市长，推行奴化教育，强制收缴民间武器，协助日军特务机关监控反满抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20939ea9b5cb4f79b7f49655706ba589','b72b72ab-43d6-4bfb-bb84-d8c6d9d17482',1935,'负责三江省警察系统','负责三江省警察系统，指挥伪警察配合日军“讨伐”抗联，在富锦、同江等地制造多起屠杀事件。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4d3560da8ec46a0a973811e0c7e921e','7b8c6ac0-a0f2-44eb-be7f-b49483097c8d',1931,'原洮辽镇守使','原洮辽镇守使，投日后任伪满军政要职，曾派兵参与对佳木斯、富锦一带抗联的围剿。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e069505cab474367990fb6ae97afe2ef','930f9494-3eba-493d-a50b-962440b8510a',1932,'清肃亲王善耆之子','清肃亲王善耆之子，投日任伪满交通大臣，修建军事铁路连接佳木斯、富锦，用于日军运输兵力和物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df60a64d926a4914916787ca72e0ade6','4b40ddf4-dbf4-44ff-bb91-2b5139d1f52d',1938,'日本关东军指派日系官员','日本关东军指派日系官员，名义次长实为最高决策者，主导三江省“讨伐”抗联计划，在富锦地区实施“三光政策”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-255fd0cde3e84a36911c4cff9cd9d2d7','2c25ec18-f7a6-4d18-96c3-beb00e881c33',1933,'原土匪头目','原土匪头目，投日后任富锦警察署长，率伪警多次袭击抗联密营，逮捕并杀害抗日志士数十人。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8caa26aa434649b4b9125691540ce3d6','db43444a-d71d-4f97-9ec0-5dff6c62f6ff',1936,'协和会地方头目','协和会地方头目，宣传“日满亲善”，组织汉奸团体搜集抗日情报，破坏地下抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-129048592c6d496294e8c5a02a4ddd21','7a948c2d-e017-49ff-a518-ce90b7f02b63',1932,'原东北军下级军官','原东北军下级军官，投日后任保安队长，在富锦、绥滨一带配合日军“扫荡”，烧毁村庄，杀害抗联伤员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c74dae2d39fa4599aca27ffd50a7a009','14a1d84b-97e0-4405-bf35-9f948a510690',1934,'日本籍参事官','日本籍参事官，实际控制富锦县政，推行“粮谷出荷”政策，强征农民粮食，导致大量饿殍。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-251ba4fd910e426997ae07436737c7f3','06052093-5b6c-45c2-a013-0214e2f1670b',1937,'为日军宪兵队担任翻译','为日军宪兵队担任翻译，参与刑讯逼供抗联被捕人员，直接导致多名地下党员牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d45b000409ff477f89575621363c58fb','c6046210-76df-4ff6-ba7d-cdbb0fb91985',1938,'推行奴化教育','推行奴化教育，强制学校使用日语教材，灌输“忠君爱国”思想，迫害爱国教师。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dd03150df1a74c4db14cd3752c52a9a7','faa13476-fdc3-41df-a6d3-ebea5f6acb6b',1933,'组织地方自卫团','组织地方自卫团，协助日军封锁抗联交通线，在富锦北部山区多次伏击抗联小分队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c07e5252a0f4c929ee2f85b89139d23','98413122-4d16-4ca1-b9d4-086513b757e0',1938,'指挥伪警在市区大肆搜捕抗日分子','指挥伪警在市区大肆搜捕抗日分子，破坏中共佳木斯地下组织，逮捕并杀害多名爱国人士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-491f761f3b4847e0a23da5ee86d72b86','a782fce5-c8e8-4d84-a026-ea35bdf1cb7e',1935,'充当日军特务','充当日军特务，伪装成商人潜入富锦、同江等地，刺探抗联情报，导致多处密营被毁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e827f7d5f8cc45129a252dc9bc49b986','eedb1986-e0d6-4e1f-bba8-d6ca49e045d3',1932,'富锦本地商人','富锦本地商人，投日后任商务会长，为日军筹集军饷物资，并强迫商户“献金”支持侵略战争。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6079e0742bbd4d05b2c2bb62747d2de3','0f55113c-a0e8-4389-b8f5-6bd8f0d2efe1',1932,'九一八后率先组织维持会迎接日军','九一八后率先组织维持会迎接日军，协助建立伪政权，后任伪满县公署科长，参与“归屯并户”。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1eb0d4562af541c495ab0a82c4b95505','51a00ce8-7b43-4762-bca3-b12f995cc290',1931,'清末宗室','清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满财政总长等职，是伪满初期重要汉奸，其影响波及东北全境包括黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-646cdc0dbd3c46cb8199ad92b7e8da53','51a00ce8-7b43-4762-bca3-b12f995cc290',1931,'清朝宗室后裔','清朝宗室后裔，九一八事变后率先投敌，引日军占领吉林，并参与策划建立伪满洲国，其影响波及东北全境包括黑龙江。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14fc7680cf4f49a0b3b16039a8cec303','e4bcb34d-8295-4bbc-9725-2bab9b450828',1931,'黑龙江双城人','黑龙江双城人，九一八事变后投敌，率伪军进攻哈尔滨等地，后任伪满军政部大臣，参与镇压东北抗日武装，活动范围覆盖黑龙江多地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d0211aaaa244eeb9d9b657e98b3c615','4cad60b0-21dd-4483-ab88-2b1737d66e18',1931,'辽宁盖平人','辽宁盖平人，原东北军将领，九一八事变后投敌，率伪军进攻黑龙江，参与江桥战役对抗马占山部，后任伪满热河省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c51d8128497446089326499bc775c765','2382cf24-e07c-4f01-b574-546444f9ffd2',1931,'原东北军骑兵旅长','原东北军骑兵旅长，九一八事变后投敌，任伪黑龙江省警备司令，配合日军进攻马占山部，活动于齐齐哈尔、佳木斯一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8ad7f38df384d87b3aedf5fade33d68','7d3e419d-bf64-4772-b272-b7ddc7dc384f',1932,'原东北军军官','原东北军军官，投敌后任伪满三江省警备司令，三江省辖佳木斯、抚远等地，参与镇压当地抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba7c5030f2914840bcb914d9f3420714','5b39bc43-91bb-4720-a0df-8eb09226e355',1934,'曾任伪满三江省长','曾任伪满三江省长，三江省省会设于佳木斯，管辖抚远等县，推行日伪殖民统治，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f0f7a8b6c1048ffa4b8c0d1ee6cebe5','e2b8775b-381c-4282-a7d3-afb6c256ff5c',1930,'在伪满三江省任职','在伪满三江省任职，参与推行日伪经济统制与思想教化，活动于佳木斯及周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbd3069243fd47c99c81de2f8535698f','a95e079a-b24c-486f-a93c-fe993c63719d',1930,'伪满时期任抚远县县长','伪满时期任抚远县县长，推行日伪政令，协助日军征发劳工、物资，镇压当地抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ac961a3b7e14f71a6ece2036e258a92','e655e8e0-c90f-499f-b11d-7ba9fa11c922',NULL,'佳木斯地方士绅','佳木斯地方士绅，日军占领佳木斯后组织维持会，协助日军维持治安、征发物资，后任伪职。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63f2a3d0841a42f3b7223fa8fbd9352c','06f5c716-6856-40f4-a389-e5d4c47a50cd',1930,'佳木斯商会会长','佳木斯商会会长，投靠日伪，协助推行经济统制，为日军筹集物资，压迫商户。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0de180e2b40f48eba4ad1fdcc9ab86bd','89fddf39-6745-4d93-8036-65159baada1c',1930,'汤原县邻近佳木斯','汤原县邻近佳木斯，任伪县长期间配合日军围剿抗日联军，推行保甲连坐，镇压民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d56f18f91ce49be95daed72b181de77','f977bbec-5c18-4a7e-a1c3-faf87f8abeb2',1930,'富锦县属三江省','富锦县属三江省，邻近抚远，任伪县长期间协助日军掠夺资源、镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d89eba1275654e7ca608b0453561080b','2608cefa-6f8b-4f4d-84f0-2553620064a8',1930,'同江县邻近抚远','同江县邻近抚远，任伪县长期间推行日伪政令，协助日军控制黑龙江沿岸。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eba9f66c3444497a94d5f1420212eb0b','4f820116-e352-40d2-bc61-6fe8ac96c281',NULL,'无','无','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8730da0a67e74eae921bbca3d0bd7b82','0327004b-f0d8-48cf-adee-c488f77a6f67',1931,'九一八事变后投敌','九一八事变后投敌，任伪满要职，协助日军镇压抗日武装，在黑龙江地区参与清乡和讨伐活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dec3c77f09cd44eb9570c43f915a2e66','0327004b-f0d8-48cf-adee-c488f77a6f67',1931,'九一八事变后投敌','九一八事变后投敌，任伪满要职，协助日军镇压抗日力量，其势力范围曾涉及黑龙江部分地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24e3734efdb3492a82410163a667de3e','0327004b-f0d8-48cf-adee-c488f77a6f67',1931,'九一八事变后投敌','九一八事变后投敌，任伪满要职，协助日军镇压抗日武装，其势力曾延伸至黑龙江部分地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3df9735e1f6e48aaa48c2e2c0f2cfb07','0327004b-f0d8-48cf-adee-c488f77a6f67',1931,'九一八事变后投靠日本','九一八事变后投靠日本，任伪满要职，参与镇压抗日武装，其势力曾延伸至黑龙江部分地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e3228efcfcb443cd8f23a5158a3b73fa','8f1fe42b-da5a-479f-9e31-cdf45a049c3e',1932,'原东北军将领','原东北军将领，叛变后任伪满军事要职，在佳木斯及三江地区指挥伪军围剿抗联部队，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89bf7b4e6b804b14907f0adfa3adda8d','744231c4-1f04-4177-a8cb-e2dca71073db',1932,'积极参与伪满政权建立','积极参与伪满政权建立，在哈尔滨及北满地区推行殖民政策，协助日本关东军镇压反满抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b6c93a7e7b14e6d87a5772f399249bd','744231c4-1f04-4177-a8cb-e2dca71073db',1932,'参与伪满政权建立','参与伪满政权建立，在哈尔滨推行奴化政策，协助日本关东军控制北满。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5062f34c7e564df09fb4038e85531f18','1cf3117e-f795-4e4e-a533-a63b393c7cf8',1932,'投日后在哈尔滨任职','投日后在哈尔滨任职，后升任伪满中央要职，参与制定奴化政策，对黑龙江地区抗日活动进行残酷镇压。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44b50d8b25884d67862f3bb53e839e06','405b1b4a-a406-49f4-ab84-182cc756a7dd',1934,'在三江地区（含桦南）推行集团部落政策','在三江地区（含桦南）推行集团部落政策，制造无人区，配合日军对抗联进行“讨伐”，导致大量平民死亡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f3379aa00924a9fbfe600c8813462fe','0677ac38-b71e-47e9-b6fa-827eb827e790',1937,'在佳木斯任职期间','在佳木斯任职期间，强化保甲制度，组织伪警察和协和会，残酷镇压桦南、依兰等地的抗日地下组织。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b3c2de6363045899f329fc55edb5f02','2798e78a-ec51-4471-a041-6d9638b3ef3e',1934,'作为日本籍次长','作为日本籍次长，实际控制三江省行政，策划并实施对桦南山区抗联部队的多次围剿，推行毒化政策。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2baac898ff494904b8e52b858e1b9c70','c05cd106-c014-42d7-b2f4-006ba5eb62c6',1932,'投日后在黑龙江地区任职','投日后在黑龙江地区任职，后升任伪满中央，协助日本掠夺黑龙江粮食、木材等资源，间接支持军事镇压。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c07e174dd3b34250808c4512d2e93cb6','547917e4-c218-4eef-85b6-1d50f0d4814c',1931,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，在哈尔滨及黑龙江地区建立伪政权体系，全面配合日军侵略，对佳木斯、桦南等地抗日活动负有重大责任。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81fffd1e3da6439396f6c8f8eefde91d','547917e4-c218-4eef-85b6-1d50f0d4814c',1931,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，在黑龙江地区签署多项卖国协定，支持日军殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d152d49be6a14f09b6b30f732baa0484','0778fa38-bad1-4136-8058-fb8d28a27c07',1932,'1932年2月一度投降日军','1932年2月一度投降日军，任伪黑龙江省长，但4月反正，重新抗日。其短暂投敌行为在黑龙江地区造成一定影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31d853a0dcae4217bfeb4b2aac9cbbb3','2da35e61-b027-4f99-a3de-defd8a69c8a5',1932,'原黑龙江骑兵师长','原黑龙江骑兵师长，投日后在齐齐哈尔地区镇压抗日义勇军，后升任伪满中央，参与策划对三江地区的“大讨伐”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-08f6188cf11e4a8095d2ac0c36138aa2','6dfbb164-fbe2-48ff-a373-49172c2287d0',1932,'在哈尔滨及北满地区指挥伪军对抗联进行多次围剿','在哈尔滨及北满地区指挥伪军对抗联进行多次围剿，其部队在桦南、勃利等地烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-869b22e507a5487baa38ab389ec23d1b','5c9f60e6-1095-4c91-bd37-65031e51634e',1933,'率伪军在佳木斯、桦南一带追击抗联','率伪军在佳木斯、桦南一带追击抗联，参与“集团部落”建设，强迫农民迁入集中营式村落。','危害等级C（丙级，基层头目）','hanjian');
