INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-536e5059d26b405db98206627152786a','9c9499e8-ea16-45bc-97c1-30cfac30ef32',1939,'原抗联第八军军长','原抗联第八军军长，1939年叛变，在佳木斯、桦南地区为日军带路，诱降抗联战士，造成重大损失。','危害等级C（丙级，基层头目）','hanjian');
