INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1528042e8cfd4734a16aafcd64891588','7b8a72a2-bcbc-49fb-b7e1-f6634cfc20aa',1937,'在佳木斯市推行奴化教育','在佳木斯市推行奴化教育，组织“协和会”，配合日军对桦南山区进行经济封锁。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e85d57fc09547829cddffbc954ed8b4','3d6f43fa-e76d-4b9b-b1f6-5ebb0aa40648',1935,'指挥伪警察在三江地区（含桦南）进行多次大搜捕','指挥伪警察在三江地区（含桦南）进行多次大搜捕，杀害抗联联络员和爱国群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b09dc7d40d634ec4990539fbd11a27a4','e6e1d08b-a436-4c88-89e6-3c62334034d6',1932,'原桦川县地方士绅','原桦川县地方士绅，日军占领后出任伪县长，协助日伪推行保甲制度，强征粮税，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b38fcfc80b24850aa3abf4c325c50c8','82846d62-52b6-4b7b-abb2-0ed587c1ae76',1933,'桦川本地人','桦川本地人，投靠日伪后任警务科长，组织伪警察抓捕抗联地下工作者，破坏抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9709a7f5e694029b730aa73aefb22cd','17cc14f5-a18f-4af5-96a1-2d4c5f178ba5',1937,'原佳木斯商会会长','原佳木斯商会会长，日军占领后出任伪市长，为日军提供物资，推行“粮谷出荷”政策，压榨百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d0e914b3baf4561aab69345b81b426a','2ee2c97c-e675-4230-9d5f-faa382bf0bfd',1934,'辽宁辽阳人','辽宁辽阳人，原奉系官员，投日后任伪三江省省长，管辖佳木斯、桦川等县，配合日军“治安肃正”行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
