INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-36950316c5174a729d8ec6c93bf6778f','0f7fbcf3-dce8-4fee-a140-5e2ab74c3d7a',1936,'桦川地主出身','桦川地主出身，任协和会会长，宣传“日满亲善”，组织青年训练，为日军搜集抗日情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a106322182044c30a2a87bbffedbe74e','2eeae905-1db3-436c-8cd6-7a3b0164b103',1938,'原东北警察','原东北警察，投日后任佳木斯警察厅长，多次率警队袭击抗联小分队，逮捕并刑讯抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-188982fe987d43bd9669e356313544e5','7204977a-16ef-40dc-8907-21389c08787e',1937,'桦川本地土匪出身','桦川本地土匪出身，被日伪收编后任保安队长，配合日军“扫荡”，杀害抗联伤员及平民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a1228b1f8b34b42ae6abccd97041fad','c43c6e8c-0525-4895-8799-f48b32c3631d',1939,'负责佳木斯地区特务工作','负责佳木斯地区特务工作，建立情报网，破坏抗联地下联络站，导致多名抗联干部被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-20ec855381c845a19f0aa959d6cf36be','193abf25-2bc0-4a59-aa83-cabbd5a2caa7',1933,'推行奴化教育','推行奴化教育，强制学校使用日语教材，禁止中国历史教学，迫害爱国教师。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3023b95e8cb407487f9cd091dffb3aa','8ffab5df-cc0a-4f77-9013-0c96742df6bf',1932,'原地方武装头目','原地方武装头目，投日后任靖安军指挥官，参与围剿抗联第三军、第六军，烧毁村屯。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d1502da62244b6a816cb4fb7a5b4621','f926831a-12b6-4c78-aa22-036097fd865e',1934,'协助日伪审判抗日人士','协助日伪审判抗日人士，判处多名抗联情报员死刑或重刑。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-801e0a367f6c469b8f9f939ff1b9a39b','3d0c2cef-cacf-4879-b554-d8a8149559e0',1935,'负责为日军搜刮粮食和物资','负责为日军搜刮粮食和物资，推行“出荷粮”制度，导致桦川、佳木斯地区农民饥荒。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1566630072674ec885ac0c03cc9d464e','dbe66d0b-baa4-4be8-8944-0057375b3580',1932,'在汤原、佳木斯一带大肆搜捕抗日联军','在汤原、佳木斯一带大肆搜捕抗日联军，制造多起屠杀事件，亲自指挥破坏汤原县委地下组织，杀害抗联干部及群众数百人。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
