INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5eaf1c8b4eaf4171b33629cae1dba730','3c07b8dd-beec-452e-868a-4b6b2f0432c9',1940,'在汤原县南部村庄搜捕抗联伤员','在汤原县南部村庄搜捕抗联伤员，发现后当场杀害，并参与抢掠百姓粮食供日军使用。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e6e0113f8fa4c00815f33bcd9e21bcc','ff9600e6-29af-4b5a-a607-86f946e6ea20',1942,'在汤原、佳木斯培训汉奸青年','在汤原、佳木斯培训汉奸青年，灌输亲日思想，并组织青年团协助日军搜查抗联物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccd123800d9548c2a4366d249c6d4064','efb9ccce-7ca5-4f6b-8388-244d7afbf7d2',1932,'原东北军将领','原东北军将领，投敌后任伪满军职，曾率伪军进攻吉林、黑龙江抗日武装，后任伪三江省省长，三江省辖境包括今佳木斯地区，直接参与对佳木斯一带抗日力量的镇压。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-646d6b8adbd54c2097596c07a11b99a0','98f961bf-358b-4667-a273-58e66b5bf9c5',1930,'伪满官员','伪满官员，曾任伪三江省省长，管辖今佳木斯、双鸭山、鹤岗等地，推行保甲、集家并村等政策，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2be043bc1aba40aeb779c417e6656524','a4be17ce-d9b0-496d-bf77-0d242bd92799',1930,'曾任伪三江省省长','曾任伪三江省省长，后任伪满文教部大臣，在佳木斯地区推行奴化教育，配合日军围剿抗日武装。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8535e85fdac14822a7d1e662de150515','1baaf4a8-ae9d-4ba7-8092-a1c188e5f0e0',1930,'在伪三江省任职期间','在伪三江省任职期间，指挥伪警察配合日军对佳木斯周边抗日游击区进行扫荡，抓捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2fc5df537fd4e7e999ea3dae82db335','43e466e2-7434-4e2a-8c35-b13e9b8776e2',1932,'佳木斯地区地主武装头目','佳木斯地区地主武装头目，投敌后组织维持会，协助日军维持地方统治，参与镇压当地抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a1b3c5f253ec4d99926885b238d86f02','3b622715-019e-49c9-b4bb-fbfc7299222d',1930,'原为抗日武装首领','原为抗日武装首领，后投降日军，在依兰、佳木斯一带组织伪自卫团，配合日军进攻抗日联军，是松花江下游地区著名叛徒。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d1c8cde311e46d5be5de92c7211ced0','1ca35784-3993-4052-8257-b0a8922e252a',1930,'与谢文东类似','与谢文东类似，原抗日武装人员后投敌，在佳木斯周边地区为日军搜集情报、带路围剿抗日联军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-725706635b9f4cf5b6fae449986313ac','d618f16a-11c8-4501-bd1b-373e93bc165a',1932,'佳木斯地方士绅','佳木斯地方士绅，日军占领佳木斯后出面组织维持会，为日军筹粮筹款、招募劳工，协助建立伪政权。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b7d1c94dcdf4703aa18e94c5a5488fd','cfb71b63-e87c-491d-98c0-0e933b65595a',1930,'佳木斯商界人物','佳木斯商界人物，投靠日伪，控制商会为日军经济掠夺服务，并通过协和会进行亲日宣传。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf714898aed24112955369d26a37475c','3543e537-5d13-4f5e-bbe5-fb66efc93253',1930,'桦川县辖今佳木斯郊区部分区域','桦川县辖今佳木斯郊区部分区域，任伪县长期间推行保甲制、抓劳工、征粮，配合日军统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c0a38cc26a640f995292a0c8c62e39e','0601b208-b976-4d87-844a-31e2a1b17701',1930,'在桦川县及佳木斯郊区一带指挥伪警察镇压抗日活动','在桦川县及佳木斯郊区一带指挥伪警察镇压抗日活动，抓捕抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c76ee3a8abb7409faa04d3f6c906e941','01c8cdac-5487-4a6b-a374-71fe0a49ff3f',1930,'汤原县与佳木斯郊区接壤','汤原县与佳木斯郊区接壤，任伪县长期间配合日军对汤原、佳木斯一带抗日游击区进行经济封锁和军事扫荡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1467b1708e7048ea9e77a27bc31734e0','e28e72af-6ee2-4aa0-a4da-6757f5425dac',1930,'在佳木斯地区通过协和会组织亲日团体','在佳木斯地区通过协和会组织亲日团体，进行奴化宣传，动员青年参加伪军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26e2043e66194361bf869f88d719a1c9','a96c217c-208b-4596-a329-ecceeeb999d8',1930,'直接负责佳木斯市区及郊区治安','直接负责佳木斯市区及郊区治安，抓捕抗日嫌疑人员，镇压地下抗日组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18d6ce2f07f342c9a688577d34b6b617','713472f5-640e-499c-8229-9c6d260dc0a5',1930,'在佳木斯地区推行经济统制','在佳木斯地区推行经济统制，掠夺粮食、木材等资源，为日军侵华战争服务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a2ca30c3edd487296df9d4e5f1ddd70','afc5f7fe-d15a-44cb-997c-6f7e997693d0',1940,'伪满军高级将领','伪满军高级将领，所辖部队包括佳木斯地区，参与对东北抗日联军的围剿作战。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ebf77d7acdd45cc8bf9319b056aa684','4fb9282e-e382-4f26-81fc-35cae1e14c32',1930,'负责三江省地方保安武装','负责三江省地方保安武装，配合日军在佳木斯周边进行治安肃正，镇压抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cde358ff5b144aaaa4efde76e6142ad9','95abc142-9456-4955-b72f-dbeb76689601',1932,'原东北军军官','原东北军军官，投敌后任伪满军职，在伪三江省（今黑龙江东部，含双鸭山地区）参与镇压抗日力量，推行保甲连坐。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0606c4916854910b21b951128cdbf2d','5a7f999e-8bde-40db-9df0-2718cf0860dd',1933,'热河地区投敌军阀','热河地区投敌军阀，后任伪蒙古军总司令，配合日军在东北及内蒙古地区作战，其部曾活动于黑龙江周边。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43a74f35d3e34f30b7fc08574b2f2cf7','49af68f2-e31f-43f8-a5fc-c34a74ddacca',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，任伪满军职，参与进攻黑龙江抗日军队，在江桥抗战中与马占山部作战。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e868dc9d2ce24621ad180f9cb46093f9','49af68f2-e31f-43f8-a5fc-c34a74ddacca',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与攻占齐齐哈尔等地，其伪军活动范围覆盖今大庆地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0837085e725c40dbab282ed249853df1','49af68f2-e31f-43f8-a5fc-c34a74ddacca',1931,'辽宁盖平人','辽宁盖平人，九一八事变后投敌，任伪洮辽镇守使，率伪军进攻黑龙江，参与江桥战役配合日军进攻马占山部，后任伪满洲国军上将。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c08a13d6f7d42dcb8946ae9aebe64b0','49af68f2-e31f-43f8-a5fc-c34a74ddacca',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，率伪军进攻黑龙江，参与攻占哈尔滨、绥化等地，后任伪满热河省长。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0d20b9fa15df4e6d87092908e8231b01','49af68f2-e31f-43f8-a5fc-c34a74ddacca',1931,'原东北军骑兵师长','原东北军骑兵师长，九一八事变后投敌，任伪洮辽镇守使，率部进攻黑龙江，参与江桥战役，其活动范围涉及黑龙江全省，包括绥化、海伦。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6559516ea6dc44969a3574cdf414b441','49af68f2-e31f-43f8-a5fc-c34a74ddacca',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪满军职。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f88f6a713ee4405f833dac9d446a0d20','6af136c1-88d8-493b-bca9-bced607cd9a4',1934,'在伪三江省任职期间','在伪三江省任职期间，推行保甲制度，配合日军围剿抗日联军，镇压双鸭山、佳木斯一带抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
