INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-823c627741e940cdaec8c5f934ab08a6','8f455e1d-ae0f-4ff9-bcb0-a5ae222acde7',1932,'曾任伪三江省省长','曾任伪三江省省长，推行奴化教育，强制使用日语，在双鸭山等地区协助日本进行文化侵略。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9af2a000afc4bfb834425c7ff910ba1','7f57a079-a28d-482f-a27e-e291dd5f2b5d',1935,'在伪三江省负责经济掠夺','在伪三江省负责经济掠夺，强制征购粮食、煤炭，为日军提供物资，压榨双鸭山地区民众。','危害等级B（乙级，市县厅局级）','hanjian');
