INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfb8903ab5a84f87a880f7cdb96f64e9','906101f9-c78e-47a1-a8e2-caa1fe85c97e',1936,'在伪三江省推行协和会运动','在伪三江省推行协和会运动，进行奴化宣传，协助日军控制民众思想。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bba92340f2664c7e8fc69e946dcfd3ed','5b396553-bf0d-467f-987b-c80d761b166a',1939,'在双鸭山地区组织协和会活动','在双鸭山地区组织协和会活动，宣传“日满亲善”，配合日本殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aff81e459a304ea89dfa50825ea3ca6c','2a27f62b-551d-43eb-aa2d-2f6267479195',1938,'在双鸭山地区任伪警察署长','在双鸭山地区任伪警察署长，搜捕抗日地下工作者，强征劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-65f1333315524f0ea8a4c59e7a6947ee','4ae69483-27c7-4de2-b1b9-9e06761864bc',1940,'负责双鸭山煤矿劳工管理','负责双鸭山煤矿劳工管理，虐待矿工，强制劳动，导致大量劳工死亡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ef9007cccd64863810482f382f4036c','bacbdce6-8946-45fa-923e-e7d43fefb24a',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪洮辽镇守使、伪热河省省长等职，其伪军活动涉及黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7509e293355d48e98fbbdd0c88dc910a','bacbdce6-8946-45fa-923e-e7d43fefb24a',1931,'辽宁盖平人','辽宁盖平人，原东北军将领，九一八事变后投敌，任伪洮辽镇守使，率伪军进攻黑龙江，参与江桥战役配合日军侵略齐齐哈尔地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3337782a61ad43caae6142f610caf14c','bacbdce6-8946-45fa-923e-e7d43fefb24a',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，1931年投敌，率部配合日军进攻黑龙江，参与江桥战役，后任伪热河省省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eeaa6bbf88f14eda82bce0f75cea3fcb','3a5224db-0db8-48d1-923f-0f5e42bff7dd',1931,'原东北军将领','原东北军将领，投敌后任伪吉林省警备司令等职，参与伪满在黑龙江地区的统治与围剿抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ebb9233746f4088976cf86d1fcc93ec','e2afd760-bc1e-4917-8eff-e7fae8e78022',1931,'投敌后历任伪哈尔滨市长、伪交通部大臣等职','投敌后历任伪哈尔滨市长、伪交通部大臣等职，其活动涉及黑龙江地区包括双鸭山、友谊一带的伪政权统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e07b33122d014dd59ac7e9fc192c6f2d','e2afd760-bc1e-4917-8eff-e7fae8e78022',1931,'投敌后历任伪满交通部大臣、伪哈尔滨市长等职','投敌后历任伪满交通部大臣、伪哈尔滨市长等职，参与伪满对黑龙江地区的统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-66f28eef88fc45ccb06e225adb036e55','eee6cf8b-a9a1-4a75-848e-8d57ccbbaa44',1931,'任伪哈尔滨警察厅厅长期间','任伪哈尔滨警察厅厅长期间，配合日军镇压抗日活动，其警务统治范围覆盖黑龙江地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b2e82078db7648829492ca646657c5d3','9f979fb8-31bd-4759-9670-1f24cd5103bc',1931,'在双鸭山地区为日军掠夺煤炭资源','在双鸭山地区为日军掠夺煤炭资源，组织伪炭矿警备队，镇压矿工反抗，是双鸭山地区有记载的附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95fc3c7006fd4313bb1d1359223c71e4','4f1cbd4f-8935-4f63-a0bd-3badc8f16b71',1931,'原抗日武装人员','原抗日武装人员，后投敌叛变，任伪三江省警务厅特务，配合日军在双鸭山、友谊一带围剿抗日联军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff559e259def4e9c89e50719a033f4f4','9f0346af-4975-4473-96bf-cdb1dbd7fc87',1931,'原抗日联军将领','原抗日联军将领，1939年投敌叛变，任伪三江省协和会会长等职，配合日军在黑龙江东部包括双鸭山、友谊地区围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d78d08394ce14911819ec37bc0706faf','0ed2632e-0cda-4529-8411-48ef3674b0b7',1931,'在双鸭山地区组织伪维持会','在双鸭山地区组织伪维持会，协助日军维持地方统治，征集物资，镇压抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fd8b919a87fa4815887e23a4e2dddf1c','c1513284-844f-462f-b798-81b4a36cee9b',1931,'在友谊地区任伪保甲长','在友谊地区任伪保甲长，配合日伪政权征粮、抓丁，监视抗日活动。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45889eb9a9ff4cf087a1ab91a2b4d6d6','ae2a64ec-58c9-4b13-afa5-9976fc11ace3',1931,'在双鸭山炭矿负责劳工管理','在双鸭山炭矿负责劳工管理，配合日军强征劳工，虐待矿工，为经济附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-024b01f5f4cb4e5094ef82ff18a37b69','f6692e14-38da-49d7-b5e1-779d78566147',1931,'在友谊地区任伪协和会会长','在友谊地区任伪协和会会长，进行亲日宣传，协助日伪政权控制民众思想。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-febc566bce2547b0a4c0501d1cf34460','d17dbd64-95c8-441d-be8e-8f0e2398ad3f',1932,'原哈尔滨特区长官','原哈尔滨特区长官，投敌后任伪滨江省长，配合日军清剿抗日武装，强征劳工。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fc1c1a193a14866a29ee0835de60fdd','d21710f6-4d33-435f-ac61-547ce2595bdc',1934,'原东北军旅长','原东北军旅长，叛变后任伪三江省长，在双鸭山一带推行“集团部落”政策，制造无人区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6130a4f802a24954a0aa7b8bc41f096a','a9b757fe-33bd-478d-a652-f67f94406df6',1937,'指挥伪警察讨伐队','指挥伪警察讨伐队，在四方台、双鸭山等地多次袭击抗联部队，逮捕杀害抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-48e776e125ec453a9473f40a25dc324e','af897b4b-ea6b-432c-ac6a-4c5cce6ae574',1932,'原黑龙江省政府官员','原黑龙江省政府官员，投敌后负责为日军筹措军费，强征当地农民粮食，间接参与对双鸭山地区的经济控制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-60c1a59b257e44febb5cbc6cf805884d','99f3c366-4830-4b95-8977-73f39236015f',1935,'作为汉奸协助日本次长管理三江省','作为汉奸协助日本次长管理三江省，在四方台地区推行保甲制度，镇压抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04cb2f4c18ae4c7e89cc6883ee1e9bdc','4f4cfbc0-b09a-426a-aa9a-76ccae7e6aa2',1931,'九一八事变后投敌','九一八事变后投敌，作为伪满最高汉奸之一，其政策直接影响双鸭山四方台地区，支持日军“讨伐”抗联。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6622918dec5b4a4189250c1f4b761435','d634f334-eb35-450c-b4f3-4cdc84a9a393',1932,'原吉林自卫军将领','原吉林自卫军将领，后投靠日军，任伪满第四军管区司令官，负责黑龙江东部（含双鸭山、宝山一带）的“讨伐”行动，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec5c8accda0c4ec9b94d725f37b8e4b8','05e7e140-9071-4c35-a7a0-630e5b2d0659',1934,'伪满三江省（辖今双鸭山、宝山部分地区）省长','伪满三江省（辖今双鸭山、宝山部分地区）省长，积极推行日伪殖民政策，强征劳工，配合日军“治安肃正”计划。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad3b7d375826469c9053fd4b3cc53a36','1fc2ff12-7123-4afc-a80b-ce5e7e42b8c4',1935,'在双鸭山、宝山地区组织伪警察和特务','在双鸭山、宝山地区组织伪警察和特务，搜捕抗日地下人员，破坏抗日组织，参与制造多起屠杀事件。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8e793cb734a43cdb6d9eec4a7187b93','cae70f94-1b37-4230-a7c9-6938ad918a69',1936,'在宝山、双鸭山地区推行“协和会”奴化宣传','在宝山、双鸭山地区推行“协和会”奴化宣传，强迫民众参加“反共”集会，协助日军征粮抓丁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f251c76fa29c4e88abea469b09b8c5ba','22e7aa3f-3161-4855-9a48-dfb2e5f63a73',1933,'任伪县长期间','任伪县长期间，强征土地，推行“粮谷出荷”，导致当地民众饥荒，并配合日军围剿抗联部队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6a13523fc1b041b28def7c633f2d4e03','d78da32e-0f9b-457e-9e34-0d46a93c37b9',1938,'管理双鸭山煤矿','管理双鸭山煤矿，强制征用中国劳工，实行残酷的“人肉开采”，导致大量矿工死亡，并协助日军掠夺煤炭资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-24719278a5a64ad9a9232554db6e93a6','26958798-2abb-4e9a-88f4-fbc7688ce116',1935,'作为伪满最高行政首脑','作为伪满最高行政首脑，其政策覆盖双鸭山、宝山地区，支持日军“讨伐”抗联，推行“粮谷出荷”和“劳工供出”制度。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58672c79095945adaf15b3726d8bf8d9','26958798-2abb-4e9a-88f4-fbc7688ce116',1935,'原东北军将领','原东北军将领，全面投日后任伪满总理，对包括绥化、明水在内的黑龙江地区实施殖民政策，签署多项卖国协定。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab6742e6cf9544418a61050be5b7a517','c228043b-baa8-4e99-99b1-6672c9c91ae7',1932,'曾任三江省省长','曾任三江省省长，在双鸭山、宝山地区设立伪行政机构，组织“自卫团”对抗抗日武装，后升任伪满财政部大臣。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab2ec1fc22344d92aefd53f424ed7f21','8c03a0d6-8120-4292-9527-71396bbc30b7',1937,'在宝山、双鸭山地区建立特务情报网','在宝山、双鸭山地区建立特务情报网，逮捕抗日志士，严刑逼供，破坏抗联地下联络站。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c009aca318124578ba46c4197ad02a35','4b753457-a134-405d-9a59-fec73fb7d5dd',1932,'投靠日军后任伪警务科长','投靠日军后任伪警务科长，参与围剿抗日武装，抓捕抗联地下工作者，协助日军推行“归屯并户”政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5c1898c34c9c4036b2004c69270e3b6c','bc373f82-1d64-4317-9425-3d047aaa3da7',1934,'组织汉奸宣传队为日军侵略张目','组织汉奸宣传队为日军侵略张目，强迫民众捐献物资，告密导致多名抗联交通员被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09414149fc7e430d977c0b12fee6110d','06e87cb6-f254-48d2-8fc1-dcaabc22cd46',1933,'率保安队配合日军“讨伐”抗联第七军','率保安队配合日军“讨伐”抗联第七军，在宝清南部山区烧毁民房，杀害抗日群众家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5f965cf36fe4d1f968209a509705c24','54948213-2959-4ffa-bef5-f02ad24cad56',1937,'为日军开采煤炭资源充当打手','为日军开采煤炭资源充当打手，镇压矿工反抗，多次向日军报告抗联活动线索，导致游击队袭击失败。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6486a1d152514d45ab68586413cc470e','380c9a07-3ee7-40b5-a75e-96446ed08152',1938,'协助日军强征劳工修筑军事工事','协助日军强征劳工修筑军事工事，克扣劳工口粮，私通日军宪兵队，迫害抗日嫌疑分子。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54e984d8c0e0490cabfc0a30d9557023','40200079-f53b-452f-b5b2-baafff4fc796',1935,'亲自审讯并酷刑折磨抗联被俘人员','亲自审讯并酷刑折磨抗联被俘人员，提供情报导致抗联密营被毁，参与“三光”政策行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d194bb75f40f49318e1dbe5378bcfe9b','56ac4136-f588-40aa-833c-940070158ee7',1940,'为日军掠夺粮食和农产品','为日军掠夺粮食和农产品，强迫农民“出荷”，对反抗者进行报复，勾结日伪军围剿抗联小分队。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c587738b1cb24dc5b8aa51aadfb7f788','490bd92c-02e3-4ef5-b42a-cdbd75cc7b6d',1936,'推行奴化教育','推行奴化教育，强迫学校使用伪满教材，宣扬“日满亲善”，检举爱国教师和学生。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-352a04a8d5eb43ba889f43400b3ee87f','d1e1eacd-0522-40dd-bae3-3b75d05cde65',1939,'率自卫团协助日军封锁山区','率自卫团协助日军封锁山区，截断抗联补给线，多次伏击抗联运输队，杀害多名抗联战士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e17b08fc292409ab5c738f07e635f65','06accb6b-6652-4b44-9668-68185f333f9a',1937,'以“反满抗日”罪名判处抗日志士死刑或重刑','以“反满抗日”罪名判处抗日志士死刑或重刑，伪造证据陷害无辜百姓，为日军镇压提供法律借口。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dbaeb2cc955d4b468aa577cdc98d1c9c','1dbc99f0-25d4-4796-9393-d3cb788707bd',1933,'在尖山一带为日军征集粮草、强征劳工','在尖山一带为日军征集粮草、强征劳工，协助建立伪警察所，迫害抗日群众。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c9ae29509bf4130a486a8fc858b3c73','4ff870bd-4da2-49d0-89b1-a7af3bd94762',1935,'充当日军耳目','充当日军耳目，多次带队抓捕抗联交通员，并参与“集团部落”建设，制造无人区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46e93713da724f34914231d7f3dca4c9','2524c4b2-e719-4bc1-ad9f-32558cf92833',1937,'为日军掠夺煤炭资源服务','为日军掠夺煤炭资源服务，残酷镇压矿工反抗，向宪兵队告密地下抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d32d740122f4e2cb549344edfa98d0c','42b7f6d9-4bcd-4c29-9ef0-bd7bf6360e49',1938,'组织地方汉奸武装','组织地方汉奸武装，配合日军扫荡抗联密营，杀害多名抗联伤员及群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f21ab4c57a0c4def8d1073e0bdb76bd7','f03547a3-2f02-4db4-82f9-75cb1c2e6e12',1932,'原吉林自卫军将领','原吉林自卫军将领，1932年投敌，历任伪满第四军管区司令、伪三江省省长，直接管辖今双鸭山岭东地区，多次率伪军“讨伐”抗日联军，残害抗联将士及百姓','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-87cd494492354a079b9314e3cf818a1a','f7660a2f-da54-4dc5-b5ce-1438d1eb7640',1934,'长期担任伪三江省警务厅厅长','长期担任伪三江省警务厅厅长，负责该省（含今双鸭山岭东）的警察特务工作，组织“搜山”行动，抓捕抗日联军地下工作者，实施白色恐怖','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f2daa206d104eefab8675c691a3623e','4e53c8bd-7fdd-443f-ba9a-56a76b5de852',1935,'在伪富锦县县长任内','在伪富锦县县长任内，积极推行日伪“归屯并户”政策，强征民夫修筑警备道路，配合日军封锁抗日游击区，导致岭东一带民众流离失所','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ede29271f0a34ab5908f59aadcdcbfdf','501f13e9-e4ea-4f76-af31-e8729ed4a939',1936,'在宝清县任职期间','在宝清县任职期间，多次率伪警察队袭击抗联小分队，杀害抗日群众，并参与日伪“治安肃正”计划，在岭东山区设立多个警察分驻所','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4ac8f6e21df43bf8ecf95a79dc4297a','4b26840b-80bc-4e16-b584-d72752e98f9c',1938,'作为日资煤矿的华人矿长','作为日资煤矿的华人矿长，强制征用当地劳工开采煤炭，克扣工资，虐待矿工，为日军战争机器提供资源，其矿区位于今双鸭山岭东地区','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-327fe0ea12754b648644b3498c82760b','dd7bac18-8919-4854-84da-cb8209705f85',1940,'接任伪三江省省长','接任伪三江省省长，继续执行日伪“粮谷出荷”政策，在岭东地区强征粮食，导致民众饥荒，并配合关东军对抗日联军进行“大讨伐”','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f235ce19bb964996a41f108fcba64501','40334776-c021-4d6f-b149-33bc8463f293',1937,'在任伪三江省省长期间','在任伪三江省省长期间，推行“保甲连坐”制度，在双鸭山岭东地区建立伪村公所，强迫居民领取“良民证”，严密监控抗日活动','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0cfd3b70657e4af1a75716736327753a','ab11f049-4acb-4aa2-8259-cff5e26f770b',1932,'虽主要驻哈尔滨','虽主要驻哈尔滨，但其管辖范围曾延伸至松花江下游及今双鸭山岭东一带，积极组织伪警察和自卫团，协助日军清剿抗联第三军、第四军','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fdd24f4d711648d19889a3a7627d5b47','d7fdfc9d-589c-4a80-aa42-68f7644e6f1c',1932,'原哈尔滨特区长官','原哈尔滨特区长官，叛国投敌，在滨江省（含双鸭山、集贤邻近地区）推行奴化政策，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-964bdb38af3e42718b0b095a36f3505c','0ca3b2cd-c7eb-4970-b336-b5c83174371e',1934,'原东北军旅长','原东北军旅长，投日后任伪三江省省长，该省辖今双鸭山、集贤等地，积极组织“讨伐队”对抗联进行残酷围剿。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8dc956668be34e79af90c737bdcbe144','8087aeae-2d32-4ed0-b5d6-e7f7c0c87081',1935,'在伪三江省任职期间','在伪三江省任职期间，配合日军推行“集团部落”政策，烧毁民房，强迫居民并屯，切断抗联与群众联系。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57455ba04aaa4ee2872bd646512c9c39','0ebf3d5e-9b1c-4463-b52d-6f4777f0d8b8',1937,'在双鸭山、集贤等地区组织伪警察队','在双鸭山、集贤等地区组织伪警察队，协助日军搜捕抗联地下组织，杀害无辜百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcdecc104b344b65a47454a434b7137f','3a80f671-a2ac-4478-948a-e8c9979dc269',1931,'九一八事变后公开投敌','九一八事变后公开投敌，任伪满最高行政长官，其政策影响覆盖黑龙江全省，包括双鸭山、集贤地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34f0c5ca349a4bfb9afb414ffc585467','dc4486e5-4680-444d-b6d3-899d72771a16',1931,'原奉天省长','原奉天省长，投日后参与伪满中枢决策，支持对黑龙江抗日力量的镇压。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2ae2907200764705a3226b384b64a6df','4350c521-f4b0-4dbb-a503-dfb9fb030bde',1931,'皇族出身','皇族出身，主动勾结日本，其叛变行为带动了黑龙江东部地区部分旧军投敌。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b484f496031746609593414788905aa5','d88abb58-0607-4948-ba5b-0a52a4e0a25e',1932,'在饶河地区积极协助日军围剿抗日联军','在饶河地区积极协助日军围剿抗日联军，多次提供情报并参与抓捕抗联战士，残害抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7277a6b1ac564e8fab7b69a9ee2c582f','7d376f58-92a7-4e62-9405-33e02d97d855',1935,'组织汉奸宣传队','组织汉奸宣传队，鼓吹“日满亲善”，破坏抗日群众组织，强征劳工供日军使用。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a34dde5a22334dc9b5fdbb4ba7fbdbab','d0405e60-4653-41e6-8350-fd996e1c395a',1933,'率保安队配合日军“讨伐”抗联第七军','率保安队配合日军“讨伐”抗联第七军，在饶河山区多次袭击抗联小分队，杀害多名抗联战士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4cdbf28a02246f38da6ac2b4307a2f4','9d077bef-77d7-40ac-adab-a85cd297eec5',1936,'在饶河县内实行保甲连坐制度','在饶河县内实行保甲连坐制度，搜捕抗日地下党员，严刑逼供，导致多名抗日群众牺牲。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0d9f56ad44d43eeac90e5a17077610d','f354cbe1-2909-4c1d-9bb7-f2e60f465501',1934,'带领自卫团为日军带路','带领自卫团为日军带路，破坏抗联密营，抢夺粮食物资，并参与制造多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c99314a8bc44b46baae559df33ac288','ccef7634-39cb-43f0-b95a-a5d0f5aedf9d',1937,'专门收集抗联情报','专门收集抗联情报，收买叛徒，破坏抗联地下交通站，导致多名交通员被捕牺牲。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-09c63520f631477baea6eb047fc4d562','61ed1760-3734-4f65-8778-af4551df1610',1938,'参与日军“三光”政策行动','参与日军“三光”政策行动，在饶河县大岱林场等地烧毁民房，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c4a4ced1ee8744e2ad426205da127696','660438ff-d072-4224-9e25-3e5f6c1375d1',1939,'协助日军推行“集团部落”政策','协助日军推行“集团部落”政策，强迫山区农民并屯，导致大量农田荒废，百姓流离失所。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba0e6c56b8cb4d04ad6751645b6eb3ce','32c25749-5827-4ab8-bae5-21517dddf0a9',1932,'原吉林军将领','原吉林军将领，投日后在哈尔滨地区镇压抗日游击队，参与“讨伐”赵尚志等抗联部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93062c2206e54e8b99a3274bb06052c2','32c25749-5827-4ab8-bae5-21517dddf0a9',1932,'原东北军将领','原东北军将领，1932年投敌，任伪满第四军管区司令，镇压抗日武装，后任滨江省（含哈尔滨）省长，推行日伪殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bac0e308e7f4a2483f22939ad9f306b','32c25749-5827-4ab8-bae5-21517dddf0a9',1932,'原东北军将领','原东北军将领，1932年投敌，任伪满第四军管区司令，镇压抗日武装，后任滨江省（含哈尔滨、巴彦）省长，推行日伪殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56255a7981cb42638b504452d75298f9','32c25749-5827-4ab8-bae5-21517dddf0a9',1932,'原东北军将领','原东北军将领，1932年投敌，任伪满第四军管区司令，镇压抗日武装，后任滨江省省长，统治哈尔滨及阿城地区，推行日伪殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e386988a07484a8bb7315a3ced8f30d3','32c25749-5827-4ab8-bae5-21517dddf0a9',1932,'原东北军将领','原东北军将领，1932年投敌，任伪满第四军管区司令，驻哈尔滨，镇压抗日武装，后任滨江省省长，推行日伪殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0e13c18d40f469787de3f0c128a4951','d0306c21-fe1a-416c-b2e7-72336f2b58b9',1932,'原吉林陆军军官','原吉林陆军军官，投日后在哈尔滨及吉林地区协助日军清剿抗日力量，参与建立伪满军事体系。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aff87ef166f344e29f7b671cbe46b200','1eb32264-3dc2-45cb-9f49-60acf06fe0d1',1932,'原东北军旅长','原东北军旅长，投日后历任伪哈尔滨市长等职，推行日伪统治政策，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4505bbc09a5448cbf504f07e2686148','34077c4b-87c1-43e0-8a09-1fc8379fb883',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投日后任伪市长，协助日军控制哈尔滨，参与经济掠夺和特务统治。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6906a4e59ee8446c8e0a941870ad3ec2','1ced0449-79b1-4fc2-9dfc-61dfdd0983e2',1932,'原奉系法律顾问','原奉系法律顾问，投日后在哈尔滨推行伪满法律，参与镇压抗日活动，后任伪立法院长。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-65b4214d272047258d76370b05c837d8','1ced0449-79b1-4fc2-9dfc-61dfdd0983e2',1932,'原奉系官员','原奉系官员，投日后任伪哈尔滨市长，后升任伪立法院院长，积极为日本侵略辩护，参与“王道乐土”宣传。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d4ae7f3cca543b6913db6939a000873','1ced0449-79b1-4fc2-9dfc-61dfdd0983e2',1932,'积极参与伪满政权建立','积极参与伪满政权建立，在黑龙江地区推行奴化教育，协助日本关东军镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2579eeeea2f84614b360fd8ce193186a','05ead991-1931-4f11-bd88-c9186dc266ad',1932,'原哈尔滨商会会长','原哈尔滨商会会长，投日后任伪省长，协助日军控制哈尔滨经济，为日军筹措军需物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41f710d793b34ae3980579c76829cd3b','05ead991-1931-4f11-bd88-c9186dc266ad',1932,'原哈尔滨商人','原哈尔滨商人，投日后历任伪滨江省省长、伪经济部大臣，为日本搜刮物资，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ba753492c8b4d56accb39556f5f6bfd','05ead991-1931-4f11-bd88-c9186dc266ad',1932,'原哈尔滨商会头目','原哈尔滨商会头目，投日后任伪滨江省省长，在哈尔滨及香坊地区协助日军经济掠夺，后任伪满经济部大臣。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c13cd7b3eb444e1ab8cc93a2678a1009','c800f95d-6eca-49ce-a854-06dae8ce5fd9',1932,'原吉林省政府官员','原吉林省政府官员，投日后在哈尔滨地区推行奴化教育和“勤劳奉仕”制度。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba9ca89f90c8415cbab5f4d3b3b3e78d','5118c50a-4075-449c-a090-ba223b2bf32d',1932,'原黑龙江省政府官员','原黑龙江省政府官员，投日后负责伪满财政，在哈尔滨地区强征捐税，搜刮民财。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8fa6e7266ec047f1b29e9ee0f3c79109','5118c50a-4075-449c-a090-ba223b2bf32d',1932,'原吉林省财政厅长','原吉林省财政厅长，投日后历任伪滨江省省长、财政部大臣，推行伪币政策，掠夺资源，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-edb1e306c616432598deabc8d3c94770','12d81547-ca63-486c-9457-bc2e29621cfb',1932,'原哈尔滨警察头目','原哈尔滨警察头目，投日后指挥伪警察协助日军搜捕抗日地下组织，残害抗联人员及爱国群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7be7e3da2928433d9397e659e4ea154e','12d81547-ca63-486c-9457-bc2e29621cfb',1932,'原哈尔滨警察头目','原哈尔滨警察头目，投日后任伪警察厅长，直接指挥逮捕抗日志士，破坏地下组织，实施酷刑。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eaf81c88166b457d9ef907946a05ed50','12d81547-ca63-486c-9457-bc2e29621cfb',1932,'原哈尔滨警察头目','原哈尔滨警察头目，投敌后任伪警察厅长，在道里区设立特务机构，大肆搜捕地下党和抗联人员，制造多起惨案','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55a7063f08d04841812fcd2356d47f3d','3bf461a2-1908-45b7-9524-dd0c5cf7df1d',1932,'原东北军宪兵军官','原东北军宪兵军官，投日后任伪宪兵队长，在哈尔滨及周边地区实施“治安肃正”，屠杀抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7cb926ef9e943d1a18688a6dd4f22b7','3bf461a2-1908-45b7-9524-dd0c5cf7df1d',1932,'原奉系宪兵','原奉系宪兵，投日后任伪哈尔滨宪兵队长，协助日军宪兵队搜捕抗联及地下党，参与“三光”政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fac6e74550c942bfbeff9344b3e828a0','3bf461a2-1908-45b7-9524-dd0c5cf7df1d',1932,'原东北军宪兵军官','原东北军宪兵军官，投日后任伪宪兵队长，在道里区残酷镇压抗日群众，参与“三江口惨案”等屠杀行动','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae249c095bac41eb8d0941c46f3920de','1ceb7bef-cc64-4deb-8668-326ed23f471b',1932,'原哈尔滨警察','原哈尔滨警察，投日后积极协助日军破坏中共地下组织，参与制造多起逮捕和屠杀事件。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1943fc41fa1d42b494d44d2280ef0e5b','af3104be-37bf-4802-965a-7803908c391a',1932,'原哈尔滨地方武装头目','原哈尔滨地方武装头目，投日后组织伪保安队，配合日军“讨伐”抗联第三路军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c0229382c204fbaa0b5386014a96791','7838c193-bd8e-4263-8ef4-718a4814cdd7',1932,'（注：此名有争议','（注：此名有争议，但历史记载有华人特务在哈尔滨活动）协助日军建立情报网，破坏抗日组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fef915499f8941e7bc8ce47d3470abcd','cebabe9f-9cf6-4e79-98ea-149339048022',1935,'专门负责侦缉抗联地下联络站','专门负责侦缉抗联地下联络站，逮捕多名抗联交通员，导致哈尔滨地区抗联组织严重受损。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0080d9878815490e90a8818c44a98f4e','7e1ed672-2c25-4e69-a6ae-28ddb7583cf4',1932,'协助日伪推行“保甲制度”和“连坐法”','协助日伪推行“保甲制度”和“连坐法”，强化对哈尔滨市民的殖民控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d79cba62fdee415a9d61353fbf1e773d','5bdf33b7-c0f3-496e-a8cd-d0e87acd987d',1932,'为日军征收“国防献金”','为日军征收“国防献金”，强占民产，支持日军在哈尔滨的军事建设。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a6c2f114d06484f8d0c5cf93881a8ff','40a2a772-7675-4d0e-9d16-6b3394198f1b',1932,'以“反满抗日”罪名起诉爱国人士','以“反满抗日”罪名起诉爱国人士，判处大量抗联支持者死刑或重刑。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-316d0eb69d8f47a78bbb929f7f4a8ceb','8fc5196e-7919-48e3-9b57-cc776a7b3e4a',1932,'1932年一度投降日军任伪省长','1932年一度投降日军任伪省长，但旋即反正抗日，故不列为长期汉奸，此处仅作历史备注。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ebbab9ac909f43f0985b3f969dfb755e','56f436e5-73ff-494a-84fd-2164be51578c',1932,'原黑龙江军将领','原黑龙江军将领，江桥抗战后投敌，协助日军稳定黑龙江局势，后失势。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92178974fbd7469ea958d1d544babcee','b7d97c22-d21b-4577-aab0-b694a621c2f7',1936,'专门负责“思想犯”监控','专门负责“思想犯”监控，逮捕大量进步青年和抗联情报员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28926760a4624ef8bc1af032a18d5362','175fb990-a9fe-4496-a135-5a27e63d0112',1932,'推行日语教育和“王道乐土”宣传','推行日语教育和“王道乐土”宣传，篡改历史教材，奴化哈尔滨青少年。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03da6e8c1bb74a96bac99429109745d3','0c67c4cc-5dd4-410e-8264-3be9430804a5',1932,'协助日军进行细菌战实验','协助日军进行细菌战实验，提供哈尔滨平民作为“马路大”的名单。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7ec2fd8820d440b831769883e9cf99c','2f70d9ee-6a55-4a27-934e-c87afeb72e1a',1932,'原东北军将领','原东北军将领，1932年投敌，历任伪满军事要职，在哈尔滨、五常地区镇压抗日武装，协助日军推行“治安肃正”','危害等级A（甲级，省部级/大军区级要员）','hanjian');
