INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-87d1cf0c00da4f80a748ec95cb479146','cd907199-bc28-446b-9f8c-307bd99082fb',1931,'九一八事变后投敌','九一八事变后投敌，1932年任伪哈尔滨特别市市长，后升任伪国务总理，在道里区活动频繁，全面配合日本关东军统治，出卖东北主权','危害等级S（特级，伪政权最高层/元首级）','hanjian');
