INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bbf86993640546ada4da236ddb128ac0','cd907199-bc28-446b-9f8c-307bd99082fb',1931,'原东北军将领','原东北军将领，九一八后投日，1932年任伪哈尔滨特别市市长，后升任伪满国务总理，全面协助日本统治东北，包括香坊地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cbfb056ab6b648e086749520bf8f9c3f','cd907199-bc28-446b-9f8c-307bd99082fb',1931,'原东北军将领','原东北军将领，九一八后投敌，虽居高位，但早年任哈尔滨市长期间即与日军合作，其势力影响黑龙江全省，支持对大兴安岭地区的“讨伐”。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-649bb7c0af2d41a1b759cbed21c232f6','cd907199-bc28-446b-9f8c-307bd99082fb',1931,'原东省特别区行政长官','原东省特别区行政长官，九一八后投日，在哈尔滨及黑龙江地区组织伪政权，后任伪满总理，全面配合日军统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-277e39afd357404f9f9c3cfa8297ac91','cd907199-bc28-446b-9f8c-307bd99082fb',1931,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，在黑龙江及全国范围内协助日军统治，对鸡西等地的殖民政策负有总责。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-db63096d14fb408994308cf4b538f4d8','7c98f585-947f-4cbb-a7d2-98d0fe87f7ae',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投敌后任伪省长，在哈尔滨、五常等地推行日伪法令，强征粮食物资，破坏抗日组织','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-159097e1db74425d83691e1821c5d19b','7c98f585-947f-4cbb-a7d2-98d0fe87f7ae',1932,'原为地方官僚','原为地方官僚，投日后历任伪职，在黑龙江、哈尔滨地区积极执行日伪法令，参与“治安肃正”行动，迫害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bfc9f3a8160145febca32a40a9143967','0af7bda3-ad8c-4bb9-9aa9-a1760966ffcc',1931,'原奉系官僚','原奉系官僚，投敌后历任伪哈尔滨市长、伪立法院长，参与签订卖国条约，协助日本控制黑龙江地区','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c00c1a36f80544ed94f4ae75485ab4b9','0af7bda3-ad8c-4bb9-9aa9-a1760966ffcc',1931,'原奉系法律人士','原奉系法律人士，投日后在哈尔滨及黑龙江地区推行伪满殖民统治，参与制定镇压抗日法令。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a60ba4ef59894e0293ead70aad334a8c','0af7bda3-ad8c-4bb9-9aa9-a1760966ffcc',1931,'参与伪满政权创建','参与伪满政权创建，在黑龙江地区推行殖民政策，协助日本关东军镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22fb1df58b6a4ad1a841dc7960115c85','0af7bda3-ad8c-4bb9-9aa9-a1760966ffcc',1931,'在哈尔滨及黑龙江地区推行日伪法令','在哈尔滨及黑龙江地区推行日伪法令，协助日本关东军建立殖民秩序，镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a9d5373d4d448379a724cbeca0c90f5','0af7bda3-ad8c-4bb9-9aa9-a1760966ffcc',1931,'积极参与伪满政权建立','积极参与伪满政权建立，在哈尔滨及黑龙江地区推行奴化政策，协助日本关东军统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d12968daa114dea862fb3a8dca26491','3508e36e-5830-4d07-ab52-fb21214033e6',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投敌后任伪滨江省长，在五常等地组织“清乡”行动，逮捕杀害抗日军民','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d1a79bd0e5c24d94a991fb90dd6e6f83','3508e36e-5830-4d07-ab52-fb21214033e6',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投日后任伪滨江省省长，推行奴化教育，协助日军建立特务组织，迫害宾县、哈尔滨地区爱国人士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b1218b22a3c49abaef217ffbb5b433b','3508e36e-5830-4d07-ab52-fb21214033e6',1932,'原哈尔滨特别市市长','原哈尔滨特别市市长，投日后历任伪滨江省省长、伪哈尔滨市长，协助日军清剿抗日力量，强征劳工。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b35dd79385804225bf8b41e3ea3f643c','3508e36e-5830-4d07-ab52-fb21214033e6',1932,'原为奉系官员','原为奉系官员，投日后在哈尔滨地区推行日伪统治，参与镇压反满抗日活动，协助日军控制交通和资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2f77040fa84041ea8e39c9bc2224579a','3508e36e-5830-4d07-ab52-fb21214033e6',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投日后任伪职，在道里区推行奴化教育，强征劳工，协助日军镇压反满抗日活动','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4bb78f40c2bf4bdbba8893d6abf86b44','3508e36e-5830-4d07-ab52-fb21214033e6',1932,'在哈尔滨及黑龙江东部地区任职','在哈尔滨及黑龙江东部地区任职，协助日本特务机关镇压抗日活动，参与对大兴安岭周边木材资源的控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce94a246e5404b76a23eb2c297c200b4','872666ce-3a12-453d-860e-6644dd20c4c3',1933,'原东北军军官','原东北军军官，投敌后负责哈尔滨及周边地区警务，多次指挥围剿五常一带的抗联部队','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4888a839caff4e4e9bd141778f7bdb78','872666ce-3a12-453d-860e-6644dd20c4c3',1933,'在哈尔滨、通河一带指挥伪军和警察“讨伐”抗联第三路军等部队','在哈尔滨、通河一带指挥伪军和警察“讨伐”抗联第三路军等部队，制造多起屠杀事件，是日伪在黑龙江东部的重要帮凶。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7002ce757f4f447fb00dbc55cad3fb5c','6ba366ca-4107-49ef-8ce6-b32bb95a68a9',1932,'在五常县任伪县长期间','在五常县任伪县长期间，推行保甲制度，强征民夫修建警备道路，配合日军讨伐抗联第三军','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1f15829a9ea40738daa1de81db2d933','0e64888d-0882-4bb3-b9f6-4d6e88eb7e74',1934,'在五常地区组织伪警察队','在五常地区组织伪警察队，多次袭击抗联密营，抓捕地下交通员，杀害无辜百姓','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-018d6b378d714baea242338eb00dcdee','6507de4d-ef45-4d5c-af37-708801b3b48b',1932,'在哈尔滨大肆搜捕抗日分子','在哈尔滨大肆搜捕抗日分子，破坏中共满洲省委地下组织，刑讯逼供，制造多起惨案','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e92c1282af4949f7a771680f3aa07e54','0f9fe7a2-4bcd-4020-9b75-15b72d6e498d',1933,'专门从事特务活动','专门从事特务活动，在哈尔滨、五常等地安插密探，破坏抗联联络站，诱捕抗日志士','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4162608a66cb40698fe6ca1e0f285b22','7e8ef8c5-ac08-4a03-bdc0-b42c58ebae9d',1935,'在五常、阿城等地组织“特别搜查班”','在五常、阿城等地组织“特别搜查班”，多次参与围剿抗联第十一军，残害抗日群众','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c8da454869514d04b62ddf06f4b50a91','5c06319a-fba3-426b-b95e-83dcd3efd68d',1936,'在五常推行“协和会”奴化宣传','在五常推行“协和会”奴化宣传，组织“青年训练所”，强迫民众参加“勤劳奉仕”，为日军提供情报','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5319724fc0994e15914987933d3b842b','f626665e-3031-45d0-8b44-56013c980862',1937,'为日本宪兵队充当翻译','为日本宪兵队充当翻译，参与审讯和拷打抗日志士，在五常地区协助日军“讨伐”行动','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0666f7da72f441e68d8aeb1641e970c8','4cb13a63-59ed-4415-9653-74eca199461c',1938,'在哈尔滨及五常地区建立伪保安队','在哈尔滨及五常地区建立伪保安队，配合日军“三光政策”，烧毁抗联据点，屠杀平民','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1f5bd228b6c4a59ab5d2fcd54a73cdd','701a3d85-dd40-4e14-996e-46a7160f2b26',1933,'组织地方伪自卫团','组织地方伪自卫团，在五常山区巡逻，多次与抗联小股部队交战，杀害抗联伤员和群众','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e50cf6d810e4829a98949a800ef177d','16b3ba95-d56e-47e0-97ed-d73e31655e9b',1932,'原洮辽镇守使','原洮辽镇守使，投敌后率伪军在黑龙江、哈尔滨周边镇压抗日义勇军，后调任热河，但早期在五常地区有活动','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbf54abf014b45c2856bdcb9f5686043','7de91d86-da05-4a00-9e4d-a8c007997760',1932,'原东北军旅长','原东北军旅长，投敌后任伪警备司令，在哈尔滨、五常一带多次“围剿”抗日武装，杀害抗联将领','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75bb7897526d4b59ab6e00bf3261a805','7de91d86-da05-4a00-9e4d-a8c007997760',1932,'原为马占山部将','原为马占山部将，后叛变投日，在黑龙江、哈尔滨地区率伪军进攻抗日武装，协助日军建立“治安区”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a792b1eba934819ad976142be3834b9','7de91d86-da05-4a00-9e4d-a8c007997760',1932,'原黑龙江骑兵旅长','原黑龙江骑兵旅长，投日后任伪省警备司令，在齐齐哈尔及大兴安岭地区率伪军进攻马占山抗日军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-51ec4bc5912a430faadaf6474625e4df','7de91d86-da05-4a00-9e4d-a8c007997760',1932,'在牡丹江、绥芬河一带率伪军围剿抗日游击队','在牡丹江、绥芬河一带率伪军围剿抗日游击队，杀害抗联伤员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-774b08ea17024ec7b7e1561f88728a92','7de91d86-da05-4a00-9e4d-a8c007997760',1932,'原马占山部将','原马占山部将，随马投日后留任伪职，后率伪军进攻抗日义勇军，在鹤岗周边烧杀。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b6e8f874749b4cfd87f6981df0e4cdf3','7de91d86-da05-4a00-9e4d-a8c007997760',1932,'原黑龙江省骑兵师长','原黑龙江省骑兵师长，投日后任伪警备司令，率伪军进攻黑河、嫩江地区抗日义勇军','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89acc0a052ee47819eb9186fbe3b70de','cedb5e5f-ad0d-4e6b-badd-f1604ed2e977',1932,'曾一度投降日军','曾一度投降日军，任伪黑龙江省长，在哈尔滨活动，后反正抗日，但投敌期间对抗日事业造成损害','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6abfc06ec3594e5db6d49e0314a0ae0e','8c4a16f8-0d8b-47bb-ac81-ac6d3209d2e3',1933,'率伪军驻防哈尔滨周边','率伪军驻防哈尔滨周边，多次参与对五常地区抗联第三、第六军的“讨伐”，烧毁村屯','危害等级C（丙级，基层头目）','hanjian');
