INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b47a3bd9ec0420f9fc28cbb6e07ae56','3ae73fd5-f959-4de9-abea-ddfefc0345c6',1932,'原东北军军官','原东北军军官，投敌后驻哈尔滨，参与策划对依兰地区抗联的围剿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
