INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6524bf505f1741fa8e53d0c9df56cb55','3cc22c7a-c23f-4eaf-9a60-7a9f2a15dbab',1932,'原哈尔滨律师','原哈尔滨律师，投日后参与伪满政权建立，在哈尔滨、宾县地区协助日军制定殖民法律，迫害抗日民众。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
