INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3d9336e10bf406887a3d24dd7bc48c3','26faf7aa-36f4-4c9f-95a3-be2273b7bfe5',1932,'原黑龙江财政官员','原黑龙江财政官员，投日后主管伪满经济，在哈尔滨、双城地区推行经济统制，掠夺粮食资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b05e3dd6bc44d8dbfe1ec31a61d7f27','a800691b-553e-4444-8477-3879869ab613',1935,'负责哈尔滨及双城地区伪警察系统','负责哈尔滨及双城地区伪警察系统，多次参与抓捕抗日地下工作者，实施白色恐怖。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d1b6bada73645b4b95078b81655ee75','bbe33c6f-7390-4aac-9e1c-507abead1e05',1938,'原哈尔滨警察','原哈尔滨警察，投日后任伪警察头目，直接指挥镇压哈尔滨市内的抗日组织，逮捕大量爱国志士。','危害等级B（乙级，市县厅局级）','hanjian');
