INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-353c82450e0d44d1b5f213d5bb176541','1567fdfa-0b6e-4d2a-95d1-3912bf040719',1932,'原黑龙江骑兵将领','原黑龙江骑兵将领，投日后率伪军驻防哈尔滨周边，多次围剿抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
