INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95ca42d749b94866be081b183b952b7b','22339fce-73fa-4bab-b725-9903381ee7e4',1935,'在哈尔滨审判抗日志士','在哈尔滨审判抗日志士，以“反满抗日”罪名判处大量爱国者死刑或重刑。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
