INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b7d01954f2e443ab12cb3ac6a236072','a2efd152-8dfb-4ece-ae6b-8a3848b283dc',1932,'负责哈尔滨地区日伪警察特务工作','负责哈尔滨地区日伪警察特务工作，残酷镇压抗日地下组织，逮捕杀害多名爱国志士。','危害等级B（乙级，市县厅局级）','hanjian');
