INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-672bff1e7f594a9faf77dd210927000b','91edeb50-2d6c-4ada-9e6d-481cba46fbcd',1932,'原东北军军官','原东北军军官，投敌后任伪军参谋长，参与指挥“讨伐”抗联第三军等部队，活动于巴彦、木兰一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
