INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2b452445b8d41c58179294f48ca960e','758acc1c-b7fb-42a2-a9cb-af860ed07192',1932,'原东北军将领','原东北军将领，投降日军后任伪滨江省（含哈尔滨及周边）省长，协助日军镇压抗日武装，推行“归屯并户”政策，制造无人区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d4188136f634dd2ba3b25139e995150','2c011e42-a68b-4dec-96ae-d378a574772d',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪滨江省省长，在哈尔滨、宾县地区强征粮食、劳工，为日军提供物资，镇压抗联活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
