INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-027b07e0222c41b7bcb99a2b8a928c56','efc31d6a-e93b-44f0-a2a3-7fc798eaaaa6',1931,'九一八事变后率先投敌','九一八事变后率先投敌，组织宾县维持会迎接日军，协助日军建立伪政权，后任伪县参议。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0caa96a7a794ba4b943982739389198','259fcf9b-05b6-4e38-9bc0-32a4c486d50b',1932,'原洮辽镇守使','原洮辽镇守使，投日后在黑龙江地区指挥伪军，多次在哈尔滨、宾县一带进攻抗联，屠杀抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d8b85a618704cfb8645fcab61b3d4da','8d0e24f6-3ed2-4e71-884f-1b1665f4386e',1932,'原黑龙江省骑兵师长','原黑龙江省骑兵师长，投日后任伪省长，在哈尔滨、宾县地区推行“归屯并户”，制造无人区，切断抗联补给。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49aebf8577294836be1d07ccb4a22fcd','eeba84de-256f-4bd1-90a3-b91e0cbf48fd',1935,'原宾县警察','原宾县警察，投日后任警务科长，亲自带队抓捕抗联交通员，在宾县县城设立监狱，酷刑折磨抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce73020617964293871e3c8a7ddbcaf1','c2165a8a-4cb5-4492-9b46-3d4cf6c37d64',1932,'原哈尔滨商会会长','原哈尔滨商会会长，投日后任伪保安局长，组织汉奸商团为日军筹款，在宾县等地强征民夫修建军事工事。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79f7e7ff460044f0b9a2646b4d162248','1ea20b5d-589e-43f4-b899-7cc3f6360397',1933,'原哈尔滨教育界人士','原哈尔滨教育界人士，投日后推行奴化教育，在宾县各学校强制教授日语，禁止中国历史，迫害爱国教师。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c6a212efc4614a389bbedfdc4dd2a508','49f676c0-3020-4d40-9ed6-582e0498e7d7',1934,'原哈尔滨日伪特务','原哈尔滨日伪特务，投日后负责协和会特务工作，在宾县发展汉奸线人，破坏抗联地下网络。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0ea30983b8e452997e682fcc58476f4','bfadf790-2223-4f31-a887-c2d9918136a7',1933,'原宾县大地主','原宾县大地主，投日后组织自卫团，配合日军“清乡”，在宾县各村搜查抗联伤员，杀害无辜百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6253064bd2904b2bbb1c605a6d026f1d','cc6c1d4f-9fd9-4454-a650-cec8523f3861',1932,'原奉系军阀','原奉系军阀，九一八后投日，1932年任伪哈尔滨特区长官，后升任伪满国务总理，全面协助日本统治东北，包括哈尔滨及尚志地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73216f35572a49d2abc8f3bcd5eed5df','9cac193e-d9fa-43f3-a20c-7f89a2db6203',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪滨江省省长，管辖哈尔滨、尚志等地，推行日伪经济统制，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa28e04bd552496399bdc8d4463ea7a5','c74a3e44-be5d-48ff-a8fd-a26b0862e1bd',1932,'原奉系法律顾问','原奉系法律顾问，投日后任伪哈尔滨市长，协助日本建立殖民秩序，参与制定镇压抗日法令。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2d92e6a35e34661a580a9d01d984521','210c91cc-3143-4f0c-b4d5-60cd41370077',1934,'负责哈尔滨及周边地区警察特务系统','负责哈尔滨及周边地区警察特务系统，多次组织搜捕抗日地下组织，破坏尚志地区抗联联络站。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ec9546bdc13426c8870797dc54f0701','598b368e-1f98-4336-b3eb-aab326bcf692',1932,'原奉系军阀','原奉系军阀，投日后在东北多地活动，曾协助日军镇压哈尔滨、尚志地区抗日武装，后任伪省长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6789a092e4a74090938cd4bdad1dc56e','903f2e4e-fd4b-4bef-8158-1efbd7220dc8',1932,'原吉林军将领','原吉林军将领，投日后率伪军参与对哈尔滨东部及尚志（珠河）抗日根据地的多次讨伐。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ceffd46bcf4341a3b206d6b13dc41556','1cb955cf-4c7e-4062-ac1b-e60ab0e9cb79',1933,'原东北军旅长','原东北军旅长，投日后任伪滨江省警备司令，驻哈尔滨，指挥伪军对尚志、延寿等地抗联部队进行围剿。','危害等级B（乙级，市县厅局级）','hanjian');
