INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b3d1096af384d88b052735dd6f5b00d','810ac5da-4867-4e3f-9c55-2611ddd1ffac',1934,'在尚志地区指挥伪警察','在尚志地区指挥伪警察，多次袭击赵尚志领导的抗联第三军，逮捕并杀害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
