INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b290213618434bfeb5b0f56a5b4eb7d4','9fe797e7-2351-4fc9-bb7e-2b4af5221dd8',1932,'原宾县警察','原宾县警察，投日后任伪警务局长，多次围剿抗联密营。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f5b0eeb0dcc4df9a80fab691167d409','8c08ac85-0131-4df0-a0ce-2626ea0c35ac',1932,'早年留学日本','早年留学日本，投敌后出任伪哈尔滨市长，协助日军建立殖民秩序，后升任伪满立法院院长，为日本侵略政策服务。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-966864796d28454c8ed4a5465cc19978','8c08ac85-0131-4df0-a0ce-2626ea0c35ac',1932,'原奉系法律顾问','原奉系法律顾问，投日后任伪哈尔滨市长，在道里区推行日伪法令，镇压学生运动，参与策划对抗日志士的逮捕','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f85d9695c7c4cb79e6b251281355f8a','53bcfcb5-685a-444c-a1d1-660b42f1db3a',1935,'在通河县任内积极推行日伪“归屯并户”政策','在通河县任内积极推行日伪“归屯并户”政策，强迫民众迁入集团部落，配合日军封锁抗联，导致当地百姓大量伤亡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d38f46607394cb09e98fcab4d98879b','634f0c25-af1b-48c4-8269-bc0bce7f7701',1931,'原为洮辽镇守使','原为洮辽镇守使，九一八后投敌，其部队在黑龙江、哈尔滨周边参与围剿抗日义勇军和抗联，烧杀抢掠无恶不作。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d5dffa17a36547c593be1c3c830af0e6','fe13c687-5c94-437e-b10a-14affd0f3324',1932,'曾一度投降日军并出任伪职','曾一度投降日军并出任伪职，在哈尔滨、齐齐哈尔地区活动，但不久反正抗日，故其汉奸身份具有短暂性，仍列入历史记录。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-84515bac78c64d57a2d10f17db6dd4e2','fe13c687-5c94-437e-b10a-14affd0f3324',1932,'曾一度在哈尔滨道里区与日伪谈判并任伪职','曾一度在哈尔滨道里区与日伪谈判并任伪职，但不久反正抗日，此条列为历史争议人物，其投敌期极短，主要活动在黑龙江地区','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb02113e8c6249d69d60068b48b0b941','39f73526-011d-40bc-83fa-3fbe78eb511d',1932,'原东北军旅长','原东北军旅长，投日后任滨江省（辖哈尔滨）省长，推行日伪法令，强征劳工，迫害反满抗日人士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d33c36816614f4990b23aa4609983d8','faa73343-8cc6-47d0-adae-ef416958e23b',1932,'原奉系法律顾问','原奉系法律顾问，投日后首任伪哈尔滨市长，后任伪满立法院院长，参与制定镇压抗日的法令。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63d4691648354a968dea86b6e3934352','a063d0c2-4a76-4334-bbd1-1c909e7207ee',1932,'作为道外区汉奸头目','作为道外区汉奸头目，协助日军强征民夫修建军事设施，向宪兵队告密抗日嫌疑人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ee7a52d001f468eb0ff8eddf4726d59','9db0693f-95e0-4417-b59b-9a6f00252673',1933,'在道外区设立检查哨','在道外区设立检查哨，搜捕抗联交通员，多次带队突袭民宅，没收抗日物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e34fe13bb9f469c9029bd316bcf8717','c806b84c-ce25-4fc3-90ad-6fb10baf2de0',1932,'在哈尔滨审判抗日志士','在哈尔滨审判抗日志士，判处大量爱国者死刑或长期监禁，是日伪司法镇压的帮凶。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-382aa08d670b4d12bca29e9d7c03583c','f62db378-28f3-4569-a145-81b10032e1d2',1933,'在哈尔滨推行奴化教育','在哈尔滨推行奴化教育，强制学校教授日语，删除中国历史内容，迫害爱国教师。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7629d52b0674c51b10902bf3bbb7e18','4cc50e4d-22b5-4881-965d-fdb9d8eac776',1932,'原哈尔滨保安队头目','原哈尔滨保安队头目，投日后负责“治安肃正”，在道外区多次实施戒严，逮捕抗联嫌疑犯。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ce177d1e901442ea9d879d1bd06df3e','f78e6a19-23fe-44eb-9166-33263c4f6eba',1934,'协助日本掠夺黑龙江粮食、木材资源','协助日本掠夺黑龙江粮食、木材资源，在道外区设立“配给所”，克扣百姓口粮。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7827dc6d03994d1383e9144a26d608c6','bf6d0876-cabf-4284-9059-ab76a7d9f517',1932,'负责伪市府日常行政','负责伪市府日常行政，配合日本关东军宪兵队清查“反满抗日”分子，多次参与大搜捕。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23bb813081b9483dbf4c500f91b51dcd','09ff11ea-b605-455e-9c8a-7991e5ca04c6',1932,'在哈尔滨任职期间','在哈尔滨任职期间，控制电力和交通，为日军军事运输提供便利，并克扣工人工资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8225f5a4deb94a43a633611a9e878a6e','e41f1af3-cc2c-4b76-8db5-9d3664e3cbac',1933,'在道外区指挥特务活动','在道外区指挥特务活动，破坏抗联地下联络站，导致多名地下党员被捕牺牲。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4663ebcdae247e6ad75cc68d79291f8','6f6efaa2-73ea-464e-895f-9acaab0a4983',1932,'原地方士绅','原地方士绅，投日后任伪道里区区长，协助日伪推行保甲制度，强征捐税，出卖抗日情报，导致多名抗联战士牺牲','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8563c6bb81484baa9823a8a888b955c4','4255a58e-3f48-4d10-b039-f27ebdd2554a',1931,'原洮辽镇守使','原洮辽镇守使，投敌后任伪省长，在哈尔滨道里区设有公馆，参与日伪高层决策，协助镇压东北抗日联军','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-039cdf67b566475d966ed4cdf4b365aa','b507372b-0577-4a7a-97db-ad5d43cfe475',1932,'原黑龙江省防军旅长','原黑龙江省防军旅长，投敌后任伪警备司令，在哈尔滨道里区及周边围剿抗日义勇军，杀害多名抗联指挥员','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9414fd92357f427e924cda0ad48c3864','46796238-5185-4e18-b30c-b59a8e986364',1933,'地方恶霸投敌','地方恶霸投敌，任伪保安队长，在道里区欺压百姓，为日军提供劳工，参与抓捕抗日志士，民愤极大','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ee6607909744f649bfe5d9de1b3095a','4ba93d23-4644-4cb3-a735-19e1fd86ce31',1932,'原哈尔滨商会会长','原哈尔滨商会会长，投日后任伪参事，在道里区组织“协和会”，为日军募捐，宣传“日满亲善”，破坏抗日统一战线','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05e8c8cf08cd451c80687dfa1441bba4','37a038c2-1036-44d5-87fd-7d24e269e13f',1934,'原工商业主','原工商业主，投日后任协和会会长，在道里区组织汉奸团体，监视居民，强迫民众参加“庆祝”活动，协助日伪征兵','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-821fc283500e40bb936d24a5a499dd1c','79073672-101c-4a56-a6fc-2c0d49b87984',1932,'原司法界汉奸','原司法界汉奸，在道里区审判抗日人士，以“反满抗日”罪名判处多人死刑或长期监禁，是日伪司法镇压的帮凶','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76053e0493de49d2bd396d7b286489df','324d4ce0-794e-43d3-b028-ed207e3af4eb',1932,'原哈尔滨富商','原哈尔滨富商，投日后任伪滨江省省长，管辖哈尔滨、阿城等地，积极推行日伪经济统制，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9608ca8428042a5aa79aa1d32f763e5','ebb6fdb8-221c-4eb5-912b-678c747ae0a1',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投日后任伪滨江省省长，在哈尔滨地区协助日军建立伪政权，参与“治安肃正”行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bada6efab3964223a66d080dad707700','ebb6fdb8-221c-4eb5-912b-678c747ae0a1',1932,'原哈尔滨特别市市长','原哈尔滨特别市市长，投日后在黑龙江地区推行奴化教育，协助日军清剿抗联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64788430fcaa419bbe59afa2873654c6','a304e6f0-724c-48f6-80a2-542da0c4bb6c',1933,'满族贵族','满族贵族，投日后历任伪滨江省省长，在哈尔滨、阿城地区推行“保甲连坐”制度，协助日军围剿抗联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f175f00695804928a2df7dbbfe102abd','cadedec9-9dc3-4725-9c2d-82e58c0b5fb0',1932,'原吉林省政府官员','原吉林省政府官员，投日后任伪滨江省民政厅长，后任伪哈尔滨市长，负责城市治安和奴化教育。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2ebde64c115425cb028f25f5df5ddb1','c8208c9c-3f5b-43ee-80a5-63cad3d875bf',1932,'原哈尔滨警察头目','原哈尔滨警察头目，投日后任伪警察厅长，直接指挥逮捕、刑讯抗日志士，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34fc62ea26d6427982d388659146f3b8','6f9c4393-efda-4494-935e-74af6df503be',1932,'投日后任伪阿城县县长','投日后任伪阿城县县长，在阿城地区推行日伪“归屯并户”，强征劳工，镇压当地抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1805062279545f299c1c4acfbe4ab6d','14190205-30bb-4976-83c1-66bde27ee4df',1933,'在阿城地区组织伪警察队','在阿城地区组织伪警察队，多次参与“讨伐”抗联部队，杀害抗日军民，搜捕地下党员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31fd3803fa444c4399a997c02cdc1b72','3d8404c1-e674-49f0-a5b7-0f26723b0056',1932,'原哈尔滨商会头目','原哈尔滨商会头目，投日后协助日伪经济统制，为日军筹集物资，出卖抗日情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e7a67b5e55314dfabea0d98f93967c75','bea8869d-83e7-4e39-a0d2-bb1de1cc2c6a',1932,'原黑龙江省财政官员','原黑龙江省财政官员，投日后任伪滨江省财政厅长，在哈尔滨、阿城地区强征苛捐杂税，搜刮民财。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-693faf64ebec409bb1722540de2ba530','4b07c2a2-9c22-4cb8-aec4-cb14681d2fe9',1932,'原哈尔滨著名律师','原哈尔滨著名律师，投日后参与伪满政权建立，在哈尔滨活动期间为日军提供法律支持，协助镇压抗日人士。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-082787fbcc3645e9bc0da5cebc249550','4e59573d-1406-4cb9-9745-b626e84697b0',1932,'原哈尔滨警察头目','原哈尔滨警察头目，投日后任伪警察厅长，在香坊地区设立警察机构，大肆搜捕抗日地下工作者和爱国群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13c9898aaec5428bb854bcae3440a5fe','7dfd5d6e-f482-4741-b7b2-2a14273be13c',1937,'任伪哈尔滨市长期间','任伪哈尔滨市长期间，管理包括香坊在内的市区，强制推行保甲制度，配合日军进行“治安肃正”，残害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9d628a77c6044c68375dd5d5398592e','942fa2ac-0418-49ff-b47f-75e59424c296',1935,'在哈尔滨及香坊地区指挥伪警察和特务','在哈尔滨及香坊地区指挥伪警察和特务，参与多次大搜捕，破坏抗日组织，逮捕并杀害多名抗联战士及地下党员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29f46892f0914dafb8778984b49617ed','b520d78c-3705-45d6-b9fe-b0c7a13ac53c',1932,'早年任哈尔滨税关长','早年任哈尔滨税关长，投日后任伪满财政要职，在香坊地区设立关卡，盘剥百姓，为日军侵华提供资金。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0aab05eeb61746ee80b28a3b8edaf891','8384462c-e567-467c-9436-6d32f41ab956',1932,'在哈尔滨司法系统任职','在哈尔滨司法系统任职，审判抗日志士，以“反满抗日”罪名判处多人死刑或重刑，包括香坊地区被捕人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a942a1632a454198b6fac8a5c94c0e59','ebd30d4a-4db6-4bda-a594-f58ba6df192b',1932,'积极投靠日军','积极投靠日军，参与建立伪政权，协助日军清剿抗联部队，强征民夫物资。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ba97973d5ff41e7ad92f356368f1880','280fc175-46ba-4017-b31d-7331c5278d82',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投敌后历任伪职，为日军筹措军费，出卖东北资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-686bfa45f0b94676a9c7782e7ee9bea4','3b985033-a792-47cf-b476-c06f8186a92e',1931,'九一八后公开投敌','九一八后公开投敌，虽名义上在中央，但长期掌控黑龙江伪政权，支持日军对大兴安岭地区的“讨伐”。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c822c359cf6c45208e71c674d4da4c8e','a90aa918-3aa0-4cd5-a29e-6f8d96cad930',1932,'1932年2月一度接受伪职','1932年2月一度接受伪职，后反正抗日，此段经历被部分史料列为附逆行为。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0e847fe9f2244f4e97a8757089eb920e','717f8c83-e24d-420f-a1f3-a9288ddd6008',1932,'原马占山部旅长','原马占山部旅长，投日后驻防大兴安岭地区，率伪骑兵围剿抗联第三路军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ae34e0a570244d2e85396a4f640afbb3','77fc9c89-a5ae-451a-b2dd-aca115a949ab',1932,'曾一度接受伪职','曾一度接受伪职，但随即反正组织抗日，其附逆期较短，仍列入部分汉奸名录。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3c5edb5bb7fa45cd9330ffdd7934c01a','8da444a1-af02-44e3-a2eb-cea53abbca12',1933,'负责嫩江、加格达奇一带防务','负责嫩江、加格达奇一带防务，配合日军“治安肃正”，杀害抗联战士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4499c3d9154f49b9bf3fe05534439c98','9e4f9e9f-07d0-4002-8215-e99307771231',1932,'蒙古王公投日','蒙古王公投日，任伪兴安北省省长，协助日军控制大兴安岭地区，征召伪蒙古军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a727fbfae1074dc28a42f986862cde84','e6b6df0a-1280-428b-93cb-e2c3d63fbb1b',1932,'投靠日本','投靠日本，参与建立伪兴安省，后因与日方矛盾被处死，但前期附逆行为明确。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-11342700fe484924826a4e2472f31348','2db7094c-65cb-40b8-bfe2-46618a2ed219',1932,'达斡尔族上层投日','达斡尔族上层投日，任伪兴安东省省长，配合日军对大兴安岭地区抗联的封锁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ce197b10c7c4c65badedc6a9bb4400e','a62a4153-1b10-4128-a1d4-189256e81636',1932,'组织伪警参与“讨伐”抗联','组织伪警参与“讨伐”抗联，在加格达奇周边设立情报网，抓捕地下工作者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-68af7453145b47e29303f11165c5ebef','1abb02e9-0aab-4fcd-858d-5a4287a81c91',1933,'率伪蒙古骑兵在大兴安岭北部追击抗联','率伪蒙古骑兵在大兴安岭北部追击抗联，烧毁村屯，强迫居民迁移。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a393658dcec24aadab958df041deef4d','0ffe9fc8-c3b5-459e-8a53-d7549fbd8f16',1938,'指挥伪军多次袭击抗联第三路军后方基地','指挥伪军多次袭击抗联第三路军后方基地，杀害多名抗联伤员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77da1f68f8984c6fa722c0b14ad75d52','3de5770a-f99e-42a6-9e56-08bb0329c232',1934,'推行奴化教育','推行奴化教育，组织“协和会”宣传“日满亲善”，协助日军收集抗联情报。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4adfbd1156e84e778c87316d30c411d4','0e294a0f-d011-4493-b6b9-27788d878114',1932,'指挥伪保安队配合日军“大讨伐”','指挥伪保安队配合日军“大讨伐”，在加格达奇山区实行“三光”政策。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e51ffc8af82418aa180d15c7da04a30','611269cd-75a8-4f65-929a-f10ea8430d6f',1932,'参与制定“保甲制度”','参与制定“保甲制度”，在加格达奇地区推行连坐，切断民众与抗联联系。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a433c268d9d412fbab222877d513e97','6d8220a4-889e-4977-aacc-34b14e25a771',1932,'推行日语教育','推行日语教育，篡改历史教材，在加格达奇地区学校强制灌输殖民思想。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04408d9ea2054083a1e9cf6b60e5b529','388ef10b-61c1-4390-abd6-6e268f319365',1932,'审判抗日人士','审判抗日人士，判处抗联战士死刑，协助日军镇压加格达奇地区反抗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-51006dcafb7b4dd7b4c3d48c90e3ed00','486d7ecd-7687-4562-b063-3565a2b34a69',1932,'原哈尔滨律师','原哈尔滨律师，投日后任伪哈尔滨市长，协助日军建立殖民统治，镇压当地反满抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da06e66165204d2bbe85843f6da79002','486d7ecd-7687-4562-b063-3565a2b34a69',1932,'曾参与伪满建国','曾参与伪满建国，任哈尔滨市长期间协助日本控制北满，镇压反日力量，涉及黑龙江地区行政与司法。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76eb7cbc5610435ba17379d33dc1fb9e','486d7ecd-7687-4562-b063-3565a2b34a69',1932,'积极参与伪满建国','积极参与伪满建国，曾任哈尔滨市长，协助日本关东军控制北满，镇压反满抗日活动，推行奴化教育。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-085888241cbd450d96b40ca9345fe924','d2914df7-8d17-47b2-906a-5de77eb5e224',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪省长，推行日伪经济掠夺政策，参与围剿大兴安岭地区抗联部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ecc02e59ecf74ee0bcdec8fca45bb420','d2914df7-8d17-47b2-906a-5de77eb5e224',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投敌后任伪省长，为日军搜刮粮食、物资，支持“治安肃正”行动，对抗联根据地造成严重破坏。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-244f44f1cd3f425192dc914a9b1ef8c5','d2914df7-8d17-47b2-906a-5de77eb5e224',1932,'辽宁金州人','辽宁金州人，投敌后历任伪黑龙江省长、经济部大臣，推行经济统制，为日军掠夺黑龙江资源服务。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5418d6479074d7ca68cc92037aba033','ab22ec34-2a0c-4e44-ba8b-65fea8728bd6',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投日后任伪职，协助日军在黑龙江地区建立保甲制度，迫害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d59477b604b54141911f305959622c2d','8f196354-d4a5-4502-8a93-8324908b93fc',1932,'原哈尔滨警察','原哈尔滨警察，投日后任伪警头目，直接指挥特务警察搜捕抗联地下组织，在呼中及大兴安岭边缘地区进行“讨伐”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e4329a0a95542d58c2310cfa2a813ab','fde33d1f-a716-49d4-a74b-ba082d0f62e4',1934,'原黑河地区官僚','原黑河地区官僚，投日后任伪省长，配合日军对黑龙江北部及大兴安岭林区进行封锁和“清剿”。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa9ca539d61b477a9aa748b0c147e9bf','fde33d1f-a716-49d4-a74b-ba082d0f62e4',1934,'原黑河地区官僚','原黑河地区官僚，投日后任伪黑河省长，管辖大兴安岭北部及黑龙江沿岸，协助日军封锁抗联国际通道。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8eadb1b4d60c4f678e28339a711bcc2c','d91d8250-6c90-4f51-80c1-6fc2aff2d6f7',1932,'原呼伦贝尔副都统','原呼伦贝尔副都统，投日后任伪兴安北省省长，协助日军控制大兴安岭地区，镇压当地蒙古族和鄂伦春族抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5bdb09bd57864f3eb2ec4cd3178e7181','c957e46e-ab85-445d-b890-9a37729561d1',1932,'原呼伦贝尔总管','原呼伦贝尔总管，投日后任伪省长，后因与日军产生矛盾被处决，但在任期间曾配合日军对大兴安岭地区进行统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d4d2032f56634827b8c6b73445b7334f','c957e46e-ab85-445d-b890-9a37729561d1',1932,'蒙古族王公','蒙古族王公，投日后任伪省长，后因与日本关东军矛盾被处死。其在任期间参与大兴安岭地区的殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4a219672b5e44229a1e849cff67668f','c957e46e-ab85-445d-b890-9a37729561d1',1932,'蒙古族贵族','蒙古族贵族，投日后任伪职，因与日本关东军矛盾被处死，但其在任期间参与对嫩江流域的殖民管理','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f25e5b9c63e940baa2cc7d90024fb2e4','81aef701-9140-49a3-a2a6-54bacd137647',1933,'蒙古族贵族','蒙古族贵族，投日组织伪兴安骑兵，参与对大兴安岭抗日游击队的多次围剿，残害抗联战士及平民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-761ad35a0fe54190944a16c3dc3af5b3','3c2cf5f6-fd90-4e2d-9d8d-2ad60bd584e3',1935,'蒙古族军官','蒙古族军官，率伪军在大兴安岭呼中、呼玛一带搜捕抗联第三路军，烧毁村屯，屠杀支援抗联的百姓。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5526b4b63a544be9a926935b57166ba4','5f8172c0-0fe9-4bcc-905a-9008a4a52c45',1938,'原土匪头目','原土匪头目，投日后任伪警察讨伐队长，专门在大兴安岭北麓和呼中林区追踪抗联部队，多次制造惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05f5713eebdc453bb8f3147c1c1cf651','d58c8940-8a2c-4814-a361-322ceb2dced2',1934,'投日后任呼玛县伪县长','投日后任呼玛县伪县长，推行“集团部落”政策，强迫呼中地区鄂伦春族和汉族居民迁移，切断抗联补给。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2fa73ff0f2748088a944933976bb5b2','5157a2e0-fb4d-4b71-af78-cf2af0f73490',1932,'原奉系军阀','原奉系军阀，投日后任伪省长，曾派伪军协助日军在大兴安岭东部地区围剿抗联，烧毁多处密营。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b27aa317cb524ae08fe971df0d6007eb','38eee73e-76cf-4a46-975b-187da29de13b',1933,'原热河地方武装头目','原热河地方武装头目，投日后任伪蒙军司令，多次配合日军对大兴安岭地区抗日武装进行军事“扫荡”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dffedcefdce54441a6d06961bc90cddb','94b4d30b-d765-4f03-b4ea-5b539afbc9a7',1937,'负责黑河及大兴安岭北部特务工作','负责黑河及大兴安岭北部特务工作，组织密探潜入呼中林区，破坏抗联地下交通线，逮捕多名抗联联络员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fdf48b6bb324472ea4d7d0c5e3a5af24','8154452d-1399-4851-aabb-2387db91abfc',1939,'原鄂伦春族猎户','原鄂伦春族猎户，投日后任山林警察队长，熟悉大兴安岭地形，引导日军袭击抗联第三路军后方基地。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38eae9fe5b4f43d981af5a046809a2aa','53b818d8-582b-46df-8dcb-2f1e706b5252',1935,'投日后任漠河伪县长','投日后任漠河伪县长，配合日军在黑龙江上游及大兴安岭林区设立检查站，截杀抗联运输队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67274c5b04d44e03b8e9c52fe44ad44d','b193f725-23cb-4799-ae78-fe9d93773277',1938,'在呼中地区组织“自卫团”','在呼中地区组织“自卫团”，协助日军搜捕抗联伤员，多次带队袭击抗联密营，杀害被俘人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4735c86aab6948df9605b637a8611f8c','07fc50ee-adca-46f0-8d1f-eddb30e4ef52',1934,'原东北军军官','原东北军军官，投日后任伪骑兵旅长，率部在呼中、松岭等地追击抗联小分队，造成抗联重大损失。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dcdafc15bfbb4bbe86ff2e34869ef47d','3e4bf653-767a-4807-a06f-8b69cfe0db94',1932,'曾任东北军将领','曾任东北军将领，后投敌叛国，任伪黑龙江省长，积极推行日伪殖民政策，镇压抗日武装，参与“讨伐”东北抗联部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74eccd4b71a745afbd9cff37a055fbd5','84c1c62f-97ca-42da-b9cf-b1ea1ae435dd',1932,'在呼玛地区任职期间','在呼玛地区任职期间，协助日军建立伪政权，强征劳工，搜刮粮食，迫害抗日军民，为日本侵略者提供情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8bddb858c95f4ba7a23646de63d65868','11c2935c-43fe-40ee-b4a3-60831203b16b',1931,'原东北军将领','原东北军将领，九一八事变后投敌，在黑龙江地区协助日军镇压抗日义勇军，后任伪省长，推行奴化教育。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a814b1c465f74169a046c902fa03434f','3e7d1c20-32ab-4f15-8460-ae4687e29a02',1932,'在黑龙江任职期间','在黑龙江任职期间，为日军筹措军费，强征民间物资，参与建立经济统制体系，压榨当地百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba37215505b443e1ac5eddebdb2cba39','3e7d1c20-32ab-4f15-8460-ae4687e29a02',1932,'负责为日军筹措军费','负责为日军筹措军费，强征粮食和物资，参与经济掠夺，迫害当地民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46bd24a264394f62b2a2366e0d492be0','3e7d1c20-32ab-4f15-8460-ae4687e29a02',1932,'原黑龙江省官员','原黑龙江省官员，投日后负责经济掠夺，强征粮食、矿产，支持日军在鹤岗煤矿的剥削。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b172f53231c4857a3784ca70bb2ee76','699c4f9c-0826-4765-bc1a-c94bea35f537',1932,'指挥伪警察配合日军围剿抗联','指挥伪警察配合日军围剿抗联，在呼玛、漠河等地设立警察据点，逮捕杀害抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e13aad9eb9d4fe0bf24fca7bf94a387','699c4f9c-0826-4765-bc1a-c94bea35f537',1932,'在向阳区及周边组织伪警察','在向阳区及周边组织伪警察，搜捕抗日分子，参与“讨伐”抗联行动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b65b57604905460798deffa0397fd4dd','13ee645d-653a-4478-906f-de79c7df1395',1933,'在呼玛县协助日本参事官管理地方','在呼玛县协助日本参事官管理地方，强征当地鄂伦春族等少数民族为日军效力，破坏抗联后方基地。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d956d3dc339b4cf59688503b3963eaee','5659954b-bce2-420f-ac7d-cece5a0b7042',1934,'组织伪警察队多次袭击抗联三路军后方机关','组织伪警察队多次袭击抗联三路军后方机关，在呼玛河流域烧毁村屯，强迫居民归屯并户。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f6c001b609a8476a83e0a0e289d46a7b','ab8d13e1-e964-47b4-9fd3-6f4096364e68',1935,'率保安队配合日军“讨伐”抗联','率保安队配合日军“讨伐”抗联，在呼玛县金山镇等地杀害抗联伤员，抢夺群众粮食。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-299b17f737e34ea9b3be7e43a42db9ee','d4c99a9e-4439-4a4b-b460-6c3776775652',1936,'在大兴安岭地区搜捕抗联联络员','在大兴安岭地区搜捕抗联联络员，破坏地下交通线，曾亲自刑讯逼供抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62b55a38d99b4c8bb00ede7646734fb2','af2484f4-c37a-4eb5-b30d-3459ea40ba34',1937,'长期潜伏在呼玛、漠河边境','长期潜伏在呼玛、漠河边境，向日军报告抗联及苏联情报，导致多支小分队被围歼。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04e49dad1aff48999d9c1169fbbf54a1','e79bfc10-4808-43fb-9ba0-8fe974c4a264',1932,'原奉系将领','原奉系将领，投日后任伪满最高行政长官，管辖黑龙江地区，全面配合日本殖民政策，支持对大兴安岭林区的资源掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-522cadb3e85d4ee79cbaa88d92d22ed2','53312ad8-65a3-44d6-bda5-8cc9cd5f2bf4',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪省长，协助日军清剿抗联，在塔河及大兴安岭地区推行“归屯并户”和物资统制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04bce06766204e6b9822fc4a486f0d9f','e663315d-3ff1-4681-826c-ea1dcd0560b4',1933,'曾任伪黑龙江省长','曾任伪黑龙江省长，负责北满地区行政，配合日本关东军对大兴安岭地区的军事“讨伐”和经济掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a4f7c51029b0465eb7a1019b3f3bef69','9a7d7235-70f3-4ff9-b4e6-db5a3fb7cbc1',1934,'管辖黑龙江北部（含大兴安岭北麓）','管辖黑龙江北部（含大兴安岭北麓），配合日军对抗联第三路军等部队的围剿，推行“治安肃正”政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-816fc938fd0a460686dc1818ee848032','91e18290-c388-4330-87cc-fb0a789a7bad',1933,'在黑河及大兴安岭地区组织伪警察和特务','在黑河及大兴安岭地区组织伪警察和特务，搜捕抗联地下人员，参与制造多起屠杀事件。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3afdcaae4dd74f16a885b3fcec579fcc','91e18290-c388-4330-87cc-fb0a789a7bad',1933,'原黑河地区警察头目','原黑河地区警察头目，投日后任伪警务厅长，在黑龙江北部及大兴安岭地区建立特务网络，逮捕抗联联络员，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67b0e18171054f3681d373086641503d','91e18290-c388-4330-87cc-fb0a789a7bad',1933,'原黑河警察头目','原黑河警察头目，投日后任伪黑河省警务厅长，在漠河、呼玛及大兴安岭林区组织特务网，多次破坏抗联密营。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2724feec39b49088b523b8201064946','97ecfbaf-8833-45ca-8ab8-82d9b4f400d4',1932,'原洮辽镇守使','原洮辽镇守使，投日后在黑龙江西部及大兴安岭边缘地带参与镇压抗日义勇军，后任伪满军事高官。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f914023d5cf84ffab6102e9338a12007','07432cb7-0e5a-45ea-ba28-5bdaed093065',1932,'1932年2月一度投降日军','1932年2月一度投降日军，任伪黑龙江省长，但同年4月反正，重新抗日。其投日期间在齐齐哈尔及黑龙江地区活动，后恢复抗日身份。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3be0d48fd354581b110fed95d726fe7','e8f577df-938f-402a-8b9b-a707c70349e4',1932,'原马占山部将','原马占山部将，随马占山投日后留任伪职，在黑龙江北部及大兴安岭地区参与“讨伐”抗联，后长期为日军效力。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2adb30afe25742f2b6ed2d6e400bb879','e8068981-1bce-4a84-afdc-dfe7bdb32304',1932,'管理呼伦贝尔及大兴安岭西麓地区','管理呼伦贝尔及大兴安岭西麓地区，协助日本对鄂伦春等少数民族进行控制，并参与对抗联的军事行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-55beabd6f98d4224ba542c885db376cb','4b1eb5fe-ad29-47f9-8b86-61484698d09f',1932,'管理大兴安岭东侧（含塔河邻近地区）','管理大兴安岭东侧（含塔河邻近地区），配合日军“讨伐”抗联，推行保甲制度。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-037d6536fbf14dada6b870c1aa4fc675','4b1eb5fe-ad29-47f9-8b86-61484698d09f',1932,'原达斡尔族贵族','原达斡尔族贵族，投日后任伪兴安东省省长，管辖今黑龙江大兴安岭地区东部，为日军提供向导，参与“讨伐”抗联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab4c4c7f5df145489f9d1f3f81d5de37','4beb2752-7ea0-4047-bd58-911b9494b56c',1933,'在大兴安岭北部地区组织伪警察','在大兴安岭北部地区组织伪警察，参与搜捕抗联小分队，迫害当地少数民族。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-caf83c55cc8f410ba522742b3fc999d3','7701fa44-f805-4767-a33b-c50cad1381aa',1938,'指挥伪兴安军在大兴安岭林区对抗联进行多次“围剿”','指挥伪兴安军在大兴安岭林区对抗联进行多次“围剿”，后于1945年8月率部反正。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac81542237ab4d1993a9ecabbbbf7ef1','9b5e0aff-be4f-4e94-99a8-f6d90bb59458',1936,'在黑河及塔河周边推行“集团部落”政策','在黑河及塔河周边推行“集团部落”政策，强制居民迁移，切断抗联与群众联系。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41135326ffaf4e7bb9e039090ae45548','ef5561ac-b146-4e2a-9db1-0f3749495798',1937,'作为日本关东军代理人','作为日本关东军代理人，在大兴安岭北麓地区监督伪政权运作，参与对抗联的“冬季讨伐”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf281b2bb0144e52945b4c7a3091e6a6','f92aeff1-8d2e-4630-8cb1-6fd6d483c3a8',1934,'在漠河及塔河邻近地区任伪县长','在漠河及塔河邻近地区任伪县长，协助日军开采金矿，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-854ebec9056e41f8828dede951dae412','f2850c0e-766d-454a-ab22-c125e832e19e',1935,'呼玛县（含今塔河部分）伪县长','呼玛县（含今塔河部分）伪县长，配合日军对抗联三支队进行封锁，提供情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b4c6a0ad6e14868bc0471e4818b6cb3','bcd03f19-d8a0-447e-a638-681d48c37d41',1931,'原东北军将领','原东北军将领，1932年投敌，出任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民统治，后升任伪满军政部大臣。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-961c2902f7c14e389e1da8109c570fbb','bcd03f19-d8a0-447e-a638-681d48c37d41',1931,'九一八事变后投靠日本','九一八事变后投靠日本，任伪黑龙江省省长，镇压抗日武装，推行殖民统治，协助日军围剿抗联部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1919c9a16a224c249797e19bda0e2ac9','bcd03f19-d8a0-447e-a638-681d48c37d41',1931,'原东北军将领','原东北军将领，1932年投敌，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民政策，参与“讨伐”抗联部队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27312bbb600f48fa87a9658a50fc4394','bcd03f19-d8a0-447e-a638-681d48c37d41',1931,'原东北军将领','原东北军将领，1932年投敌，任伪黑龙江省长，协助日军镇压抗日武装，推行殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d7ba5435b57d44d1807f7edfb38064db','bcd03f19-d8a0-447e-a638-681d48c37d41',1931,'九一八事变后投降日军','九一八事变后投降日军，任伪黑龙江省省长，镇压抗日武装，协助日军建立伪满统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d239b865040a4a63b0141bda0719e26a','bcd03f19-d8a0-447e-a638-681d48c37d41',1931,'原东北军将领','原东北军将领，1931年九一八事变后投敌，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aac6751e001e497e9c951de7b3324b2c','bcd03f19-d8a0-447e-a638-681d48c37d41',1931,'原东北军将领','原东北军将领，1932年投敌，任伪黑龙江省长，协助日军镇压抗日武装，推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c00c9c2593ea43d0a909321e040bb86d','38bc729a-4bb0-47c6-9a01-e54c57b99810',1932,'原奉系法律人士','原奉系法律人士，投日后参与伪满政权建立，在哈尔滨及黑龙江地区推行伪法统，协助日本关东军镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-abbed4da351144009e61c8d97e52f5ae','5258c327-4c46-4c20-99f0-279a8d4fbdbd',1932,'原黑龙江省官僚','原黑龙江省官僚，投日后历任伪省财政厅长、黑河省长，为日军搜刮物资，配合“讨伐”抗联，迫害当地居民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3e02ceee397c42e3aa36e1d0e940bc7c','f843233b-eac3-452b-88de-71194e62ee95',1932,'原黑龙江省议员','原黑龙江省议员，投日后在黑龙江多地任职，参与建立保甲制度，协助日军清乡，对抗联活动区域进行经济封锁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19370b2c45714cd5a08a6be7e76f2f28','ae412c3e-663f-4f2a-8049-57fecb320799',1932,'原哈尔滨特别市市长','原哈尔滨特别市市长，投日后任伪黑龙江省长，推行奴化教育，强征劳工，支持日军“治安肃正”行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9368f4fabd544124a51fff38d67a8458','e7b6eba8-dab2-4d06-bcf4-2776a1dc4295',1934,'原吉林军官','原吉林军官，投日后任三江省长，该地区含大兴安岭东麓，多次组织伪军配合日军围剿抗联第三路军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5198434448b14122b507c4e2600d4674','e4a30dc0-49b1-49e4-b53b-3d4a06a23c5c',1932,'原呼伦贝尔地区蒙古族上层','原呼伦贝尔地区蒙古族上层，投日后任伪兴安北省省长，管理大兴安岭西麓，协助日军控制鄂伦春等少数民族，阻挠抗联活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4be839cabc494d5b845dde5f6f82a048','09ba49ef-bc8e-4049-8872-fe5c8a2fce25',1933,'原呼伦贝尔警察','原呼伦贝尔警察，投日后任伪警务厅长，在大兴安岭北部地区搜捕抗联小分队，破坏地下交通线。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2643c12c17345f6a2528245b968853b','fb994669-74cb-4fb6-b1fc-450cacdb148c',1934,'原黑龙江地方士绅','原黑龙江地方士绅，投日后任伪黑河省参事，参与制定“无人区”政策，强迫大兴安岭边缘居民迁移，断绝抗联补给。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2aebfe4ab22a40db992ad681ae6f9f41','a55f61d5-8dad-4496-9f74-cd29a21da690',1932,'原奉系将领','原奉系将领，投日后任伪满军政要职，其指挥的伪军曾调往黑龙江地区参与镇压抗联，包括大兴安岭周边。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5451f691567740b6ade0b8840f4c31b1','025f12c3-0de0-484d-aa36-5d183dbfd6a5',1932,'原吉林军官','原吉林军官，投日后率伪军多次越界进入黑龙江南部及大兴安岭余脉，配合日军“围剿”抗联。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b3a93a508ed410ca9760daf668484f1','fea8cbb1-5de4-4c0c-adc9-f55781567899',1933,'原黑龙江地方武装头目','原黑龙江地方武装头目，投日后任伪保安局长，在新林及周边林区设立检查站，截杀抗联侦察员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9439f386e8b44df8db37604ae10f81c','232e0651-d354-4b94-95d0-b07cf2e63b47',1935,'原林区把头','原林区把头，投日后任伪护林队长，为日军提供大兴安岭地形情报，引导日军袭击抗联密营。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa77b32d51d5465cbd60ef02a8834643','40cb0bc7-438c-4a75-af61-1024d732347d',1933,'原蒙古族军官','原蒙古族军官，投日后率伪兴安军在大兴安岭北部巡逻，多次与抗联第三支队交战，杀害抗联战士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3c8a1e23b9d44b680cb9b0a076c00c8','fd8984c2-b09f-4cb7-86bf-19e400a2f79e',1934,'原黑龙江教育界汉奸','原黑龙江教育界汉奸，投日后在协和会任职，在大兴安岭地区推行奴化宣传，诱降抗联意志薄弱者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ec460c7044c40db9579198f62eab66c','b4fef8ab-c1e0-4c79-885a-5c9c9888b68f',1932,'原黑龙江警察头目','原黑龙江警察头目，投日后任伪警务厅长，组织特务队深入大兴安岭，破坏抗联后方基地。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-73bd5529dbda416cad0f44abd3072cd9','220b8b5c-0926-4833-887f-fa5247038ae6',1931,'原洮南镇守使','原洮南镇守使，九一八后公开投敌，在黑龙江西部及大兴安岭周边协助日军进攻抗日义勇军，后任伪满高官。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee5991d66faa4e9c8e9c85b79a624928','339197b2-99bc-46bc-aa31-326e655d5622',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪黑龙江省长，在齐齐哈尔及大兴安岭地区推行日伪经济统制，掠夺木材矿产。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54c04ef0b7a64be7a7b07ec2866a80a6','d29d6c26-3d52-4ec3-bda7-1f2fd01aabdc',1933,'原黑龙江省政府委员','原黑龙江省政府委员，投日后历任伪黑龙江省长，在松岭及嫩江流域配合日军“讨伐”抗联，实施归屯并户。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2031e7cc28c41f38907348ac6b83711','ff3fa400-3b12-4199-98f6-29af34e87baf',1932,'原布特哈旗总管','原布特哈旗总管，投日后任伪兴安东省省长，在扎兰屯、松岭一带推行保甲制度，镇压鄂伦春等族抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a6da488446a4a00903687ce7b1a75a9','bd104200-36b2-48e7-bd39-944715536a8f',1933,'原达斡尔旗佐领','原达斡尔旗佐领，投日后任伪兴安东省省长，在大兴安岭地区组织伪警察队，参与搜捕抗联小分队。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f579a89826a41a7b7b87a7fcca42ad4','c4588836-7635-4912-ac97-16d0ad77a5b5',1932,'原索伦旗总管','原索伦旗总管，投日后任伪兴安北省省长，在海拉尔至松岭一带协助日军建立“无人区”，迫害抗联联络员。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04b7e47319be4979af85c53da77c02da','9815460d-a7b9-41c6-939f-fe5ac2547ace',1932,'1932年2月一度接受伪满任命','1932年2月一度接受伪满任命，任伪黑龙江省长，但旋即反正抗日，故不列为长期汉奸，此处仅作历史备注。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-990e8b0b16804998acf2b4b614512788','83aa3748-f365-469e-9b5c-b1e5405a7f30',1933,'原东北军军官','原东北军军官，投日后在黑龙江地区协助日军策划“讨伐”抗联，多次参与松岭、嫩江一带的扫荡行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df5becefbca54be9b3252001e75afd9d','1ec62417-9162-4a79-90a2-ba029d073e42',1932,'原呼伦贝尔蒙古贵族','原呼伦贝尔蒙古贵族，投日后组建伪兴安骑兵师，在大兴安岭西麓及松岭地区参与围剿抗联三支队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf5abceb2bd44a4da73ecd77c67a191c','e9a0d083-9b63-4622-8ee4-cdcf29a17855',1938,'原伪兴安军军官','原伪兴安军军官，在大兴安岭地区执行日伪任务，1944年率部起义投奔苏联，此前曾参与镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be52dca6813844ff9de8d0cc20800722','e9a0d083-9b63-4622-8ee4-cdcf29a17855',1938,'曾率伪兴安军参与镇压抗联','曾率伪兴安军参与镇压抗联，1944年率部反正，但此前有汉奸行为。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d56f108a36454db1ae7b36419cc25005','12c0c5ec-5264-448f-a3db-0aed771ca92d',1932,'原蒙古王公子弟','原蒙古王公子弟，投日后任伪兴安军高级顾问，在松岭、阿尔山一带协助日军训练伪军，对抗抗联。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a161b911ce6d49d29bbc692725097323','6e53a97e-d0b4-412a-ab1c-4702983054f1',1935,'原黑河地方士绅','原黑河地方士绅，投日后任伪省参事，在漠河及大兴安岭北部为日军提供抗联情报，参与“归屯并户”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04eaf40728aa4772b8a08ec156f657a1','04988047-c032-4c87-901f-ee06fb1f5fd2',1932,'曾任东省特别区（哈尔滨）长官','曾任东省特别区（哈尔滨）长官，后投敌成为伪满最高行政首脑，签署多项卖国条约，配合日军统治黑龙江地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9208b4882d2741749b6ed699c69c4929','a9680fc5-6903-46a3-b966-1c25adf7424d',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪省长，为日军筹措粮饷，协助镇压马占山等抗日义勇军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92eb50325a9f4288a31bab587adcd9c3','a9680fc5-6903-46a3-b966-1c25adf7424d',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后出任伪黑龙江省长，协助日军建立殖民统治，镇压黑河、嫩江地区反日运动','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7862305308534be1b3ae394240200ae8','ef195a3c-8178-400a-858a-74f3363a1431',1932,'在齐齐哈尔地区积极推行日伪殖民政策','在齐齐哈尔地区积极推行日伪殖民政策，参与“治安肃正”，迫害抗日军民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-477c118c9319476fad5ebb78eba5d7e4','5f78de3f-3820-4946-8fda-b9c95d780855',1934,'在黑河（今黑河市及大兴安岭部分地区）任伪省长','在黑河（今黑河市及大兴安岭部分地区）任伪省长，协助日军建立边境防御体系，强征劳工修筑军事工事。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ddfd7c014b24b21b4e4dcee8bba4e24','cab5f90a-fb4f-460e-88f5-f102ccb1beb1',1935,'长期在黑河地区任伪职','长期在黑河地区任伪职，配合日本关东军对苏联情报战，迫害抗联人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fcf2e6ecaf0e48c69619ceb4418bd17e','142c3929-5ece-4d99-863f-f4da458a9654',1934,'在三江地区推行“集团部落”','在三江地区推行“集团部落”，切断抗联与群众联系，导致大量平民死亡。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac6cb70f6f9545a4a57f874fe80e8e98','78667ca2-a07a-40a3-9dd6-52d0b4adf2ab',1932,'在黑龙江任职期间为日军搜刮物资','在黑龙江任职期间为日军搜刮物资，推行“粮谷出荷”政策，导致大兴安岭周边农民饥荒。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c61d871f2bef4632a3fafd240372cd4c','5bed6dde-7afa-479c-a582-4782eccbc5ff',1932,'在黑龙江司法系统内为日军服务','在黑龙江司法系统内为日军服务，判处大量抗日人士死刑，破坏抗联地下组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6d6838b85ccc40caa3a2cc98d6d18e43','5bed6dde-7afa-479c-a582-4782eccbc5ff',1932,'在黑龙江地区审判抗日志士','在黑龙江地区审判抗日志士，以“反满抗日”罪名判处大量爱国者死刑或徒刑。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3ee7ce651164e0cb4801bc27178f4dc','d2b4b7c5-ee39-48dd-9210-1a14b9680edf',1932,'在嫩江、大兴安岭东南部地区率部投敌','在嫩江、大兴安岭东南部地区率部投敌，协助日军进攻抗日义勇军，后转任热河伪职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39385e7cdf8c4852a3d5c934475efb7e','1d3beb0c-5e59-41b9-822e-9261b18eb4f4',1932,'一度接受伪职','一度接受伪职，但旋即反正抗日，故历史评价复杂，此处仅作记录。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5a89de0702954674a19088f3b3bf896f','7834d008-1c76-4945-bb89-5c9bea23c23c',1935,'在漠河、呼玛等边境县组织警察队','在漠河、呼玛等边境县组织警察队，协助日军封锁边境，杀害越境抗联战士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41a1eff76abb4d05ae13b89218a64873','01cf581f-f0e3-428e-a262-01000544c8dd',1938,'在大兴安岭原始森林中带领伪军追击抗联第三路军','在大兴安岭原始森林中带领伪军追击抗联第三路军，烧毁山林，破坏抗联密营。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-61188c4f6f6842eba03363104845df3d','60f9cffd-6ead-4481-9999-9bd947f279f0',1935,'在漠河县（今漠河市）推行日伪统治','在漠河县（今漠河市）推行日伪统治，强征当地鄂伦春族和汉族百姓为日军修路、伐木，虐待劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da570fba497048958dd25f4569616c74','66158b78-fa38-44a8-949f-f0249ea9e548',1937,'在呼玛、漠河一带配合日军“边境清剿”','在呼玛、漠河一带配合日军“边境清剿”，杀害抗联联络员，没收抗日家属财产。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee6e63e559bb43c68f800127fd80ca7c','2810fb2d-912b-4853-80fe-b7d29860e656',1939,'率森林警察为日军提供木材资源','率森林警察为日军提供木材资源，并参与搜捕抗联小分队，在漠河林区多次设伏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-51b2c0e5262b42f695173c1a9adaa050','d628d355-6b89-46da-b3a9-8e6c6995c1dc',1932,'原东北军团长','原东北军团长，投日后在呼伦贝尔及大兴安岭西部镇压蒙古族抗日武装，后反正。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39ec09503a9e4c41aa17680692115bbe','15662ba0-8941-416a-842f-e246c781f765',1936,'在黑河至漠河边境地带驻防','在黑河至漠河边境地带驻防，多次参与对苏联情报人员的搜捕，并杀害抗联交通员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f2bc19be5e614ba581a7d5560e4f2f16','d020fbf2-fb87-48e9-a190-83e4e9e0b742',1931,'原东北军将领','原东北军将领，九一八事变后率部投敌，任伪奉天警备司令、伪军政部大臣等职，参与镇压东北抗日武装，为伪满军事系统重要汉奸。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d98cae1a0b714d6eb9b61a98812c189c','dca62604-e2b0-4944-8e40-da0e28c121ef',1931,'原辽宁省政府主席','原辽宁省政府主席，九一八事变后被俘投敌，历任伪满洲国民政部总长、参议府议长等职，参与伪满殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e2f7d8de04544c4809c7af2302d6a9a','dca62604-e2b0-4944-8e40-da0e28c121ef',1931,'原辽宁省政府主席','原辽宁省政府主席，被俘后投敌，参与伪满政权建设，影响遍及东北包括黑龙江。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1f1d51c5c09d46c2b1ce4d3e138cc481','dca62604-e2b0-4944-8e40-da0e28c121ef',1931,'辽宁沈阳人','辽宁沈阳人，九一八事变后被日军逮捕后投敌，历任伪奉天省长、伪满洲国民政部总长、参议府议长，为伪满政权重要汉奸，其行政体系覆盖东北包括黑龙江。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-235bb8f338c14965a748e0f4dbc640e5','dca62604-e2b0-4944-8e40-da0e28c121ef',1931,'辽宁沈阳人','辽宁沈阳人，九一八事变后被日军扣押，后投降任伪奉天省长，继任伪满洲国民政部总长、参议府议长，为伪满政权重要附逆者，其管辖范围涵盖黑龙江等地民政事务。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8368423e6ba46e984746c3c99ebc3e2','299d9fc5-fee0-49f8-9bf7-2d2c81195ae2',1930,'在伪滨江省警务系统任职','在伪滨江省警务系统任职，参与搜捕、镇压抗日人员，推行保甲连坐与治安肃正政策。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d2cf79a992bb4e7883882aed317225b2','61910a66-0395-4b33-926a-38977fc7d4f9',1930,'在伪滨江省政权与协和会系统中活动','在伪滨江省政权与协和会系统中活动，参与殖民宣传、民众控制与战时动员。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d036329f4eba425484121821db6e3c35','0b0fc552-8940-4943-841e-9f58a8feda09',1930,'在大庆地区肇州一带任伪县长','在大庆地区肇州一带任伪县长，执行日本殖民政令，征粮征工，配合日伪军警镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bdc52a6e697346f086b72d19d9bd187c','5270488a-0631-4a45-ade3-bdedc67d801c',1931,'原东北军骑兵将领','原东北军骑兵将领，九一八事变后投敌，参与进攻黑龙江抗日部队，后任伪洮辽镇守使、伪热河省警备司令，在东北西部包括大庆周边地区配合日军作战。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-418ad304b7af401296072cfd0437aaf0','5270488a-0631-4a45-ade3-bdedc67d801c',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，任伪洮辽镇守使，率伪军配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪热河省警备司令，其活动直接涉及黑龙江地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d38d65f1d1fc4f2b870ffb1a3fd1026f','5270488a-0631-4a45-ade3-bdedc67d801c',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪热河省警备司令等职。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8732ebf1d0f140f58724a22e6c00fb30','9a22c833-0d16-4758-9a45-6ab19cb2e365',1931,'原东北军黑龙江部队将领','原东北军黑龙江部队将领，马占山抗日时动摇投敌，任伪黑龙江省警备司令，参与瓦解抗日武装，控制黑龙江地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5c22a0489884b809fe763399f83ddb7','bb4cbeca-26f7-4895-af04-2c87344e92c5',1930,'在伪黑龙江省政权中任职','在伪黑龙江省政权中任职，协助日本推行省政殖民化，参与治安肃正与物资统制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc1cc9127d4b4fcea979244ecf14453d','bb4cbeca-26f7-4895-af04-2c87344e92c5',1930,'原东北军军官','原东北军军官，九一八事变后投敌，曾任伪黑龙江省长，参与伪满地方政权建设，其统治区域包括齐齐哈尔及龙沙地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e413f6e2fe748fcb45dad2cf70b9fee','bcd39420-287c-4a3c-bebf-20bb0307f2a8',1930,'在郭尔罗斯后旗（今大庆肇源一带）任伪旗长','在郭尔罗斯后旗（今大庆肇源一带）任伪旗长，执行日本对蒙旗的殖民统治政策，配合征粮、征畜与劳工动员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7b23428b617e4919a6908f5da75c4aa9','21991bb7-67fd-49fe-858f-d961ed38dace',1930,'在杜尔伯特旗（今大庆杜尔伯特蒙古族自治县）任伪旗长','在杜尔伯特旗（今大庆杜尔伯特蒙古族自治县）任伪旗长，协助日伪推行旗政、保甲与物资掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbbbdb41789a41099485434f686643a1','bd192182-3681-4bc4-a260-7cf7d71b8c20',1930,'在杜尔伯特旗伪旗公署任职','在杜尔伯特旗伪旗公署任职，参与日本对当地蒙古族民众的控制与战时动员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-15da8277c2be469eb1b7013669b14ff7','bd84e977-2e10-401a-83aa-9bb3d497b51c',1930,'在肇东一带任伪县长','在肇东一带任伪县长，执行日伪政令，配合军警镇压抗日地下活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-12d0f562446342f980b5d3115c8688ad','e84e1bef-43f3-4f26-80f3-e11324545eb5',1930,'在安达地区任伪县长','在安达地区任伪县长，协助日本推行殖民行政、征粮征工与治安控制。','危害等级C（丙级，基层头目）','hanjian');
