INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac1e87fd9b3449c69afe928017226a57','6e7a54d4-cad5-437a-b885-1d8f5c3af823',1930,'在伪滨江省行政中枢任职','在伪滨江省行政中枢任职，协助日本控制地方财政、人事与治安事务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b45437caf6f84e2897a5fe2e6aec7ba8','40ba645f-4862-4e04-a174-2cca19965dde',1930,'长期在哈尔滨及滨江省伪政权任职','长期在哈尔滨及滨江省伪政权任职，参与日本对北满地区的殖民统治与经济掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-787f0bb0cba540589966406110536d8b','f303e6be-4298-4a11-a5ce-afd03ca53ce5',1930,'在伪滨江省经济部门任职','在伪滨江省经济部门任职，配合日本推行产业统制与资源掠夺。','危害等级B（乙级，市县厅局级）','hanjian');
