INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43f7a23ce3f840b883a29725892eda4b','25f4a506-ea09-46d8-9ec1-a8ccf3625eda',1930,'在肇州地区警察系统任职','在肇州地区警察系统任职，参与搜捕抗日人员、镇压民众反抗。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbf9f5d58ac444c3a3d18219edfdb2a8','1d0a891b-72c9-4ae2-8ae5-d1ef726787aa',1930,'在安达地区警察系统任职','在安达地区警察系统任职，配合日伪军警进行治安肃正与情报活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d3c0ca7f9b5498eb893c55a18606c73','5a881417-aa2b-42fe-9e60-1ace5f856ffd',1930,'在林甸地区警察系统任职','在林甸地区警察系统任职，参与镇压抗日活动与民众控制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb9c015232694515ab9c313d81ffd613','e8d8b8dd-228c-4caa-87f4-8d368d9940c8',1930,'在杜尔伯特旗警察系统任职','在杜尔伯特旗警察系统任职，协助日本控制当地蒙古族民众，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a8b078e87f9f4ee890a568de9f0bc764','d868b8fd-4827-40e5-b9d6-4708f848defc',1930,'在郭尔罗斯后旗警察系统任职','在郭尔罗斯后旗警察系统任职，参与日伪治安肃正与情报搜集。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ad113a4d119451ab10ff9991f087c01','80811145-3fab-49c3-a1e9-e4bf4a1b3b6f',1932,'原奉系法律人士','原奉系法律人士，九一八后积极参与伪满建国，曾任伪哈尔滨特别市市长（管辖今大庆部分地区），推行奴化教育，协助日本殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-50cc1efc131b4d2c8b00d5faf7f711fb','80811145-3fab-49c3-a1e9-e4bf4a1b3b6f',1932,'原奉系政客','原奉系政客，九一八后投日，曾任伪哈尔滨特别市市长，后任伪满立法院院长，积极推行奴化政策，协助日本殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bca2cf7289f947d4ad8cd31ab5156978','80811145-3fab-49c3-a1e9-e4bf4a1b3b6f',1932,'原奉系政客','原奉系政客，九一八后投日，曾任伪哈尔滨市长，协助日军建立殖民统治，镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a2760c62ec884a8ba43790ef29ac519f','80811145-3fab-49c3-a1e9-e4bf4a1b3b6f',1932,'参与伪满政权建立','参与伪满政权建立，曾任哈尔滨市长，管辖包括鹤岗在内的区域，协助日本掠夺资源。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc3c1fe1b5ff47878ca927ec06532a9a','80811145-3fab-49c3-a1e9-e4bf4a1b3b6f',1932,'原奉系政客','原奉系政客，投日后任伪哈尔滨特别市市长，在黑龙江地区推行日伪殖民政策，协助日军镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0cb6785f492e4693b11b47f617e8a4e1','8c239ba2-02db-461f-9f13-5c5bd6317bd7',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投日后任伪哈尔滨市长，在黑龙江地区（含大庆一带）强制推行“保甲制”和“粮谷出荷”，压迫民众。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77f8b9261afa445b9dd2ce34c3b0346b','78b6effb-1ee9-4407-8026-a52651ff498b',1932,'原黑龙江实业界人士','原黑龙江实业界人士，投日后任伪黑龙江省长（省会齐齐哈尔，管辖大庆地区），为日军搜刮粮食、木材，并协助镇压抗联活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d50e2f3981994a18bf7b81b57eec3303','78b6effb-1ee9-4407-8026-a52651ff498b',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，1932年投敌，任伪黑龙江省省长，后任伪满经济部大臣，为日军搜刮物资，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86b72b6f6fb64d69b0700fa617701af9','78b6effb-1ee9-4407-8026-a52651ff498b',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，1932年投敌，任伪黑龙江省长期间，强征粮食物资，配合日军经济掠夺，迫害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa081c4fe429440995c0ff5ffa0a1d12','78b6effb-1ee9-4407-8026-a52651ff498b',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪黑龙江省省长，在鹤岗矿区强化殖民统治，配合日军掠夺煤炭资源，镇压矿工反抗。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ce7f1c787b3496798b3bf4480fbf3a7','6692354e-8d72-4c15-9f4b-a3103b1d1078',1932,'原黑龙江省政府官员','原黑龙江省政府官员，投日后历任伪黑龙江省长，在齐齐哈尔、大庆等地区推行“归屯并户”，制造无人区，对抗联进行经济封锁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8bdcea3be8da49fd8982918446c013c5','6692354e-8d72-4c15-9f4b-a3103b1d1078',1932,'原黑龙江省财政厅长','原黑龙江省财政厅长，投日后任伪黑龙江省省长，后任伪满财政部大臣，协助日本控制黑龙江经济命脉。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-77d73ee137fc4348ba3c4885e79f3a66','6692354e-8d72-4c15-9f4b-a3103b1d1078',1932,'原黑龙江省财政厅长','原黑龙江省财政厅长，投日后继任伪满黑龙江省省长，后升任伪满财政部大臣，在黑龙江地区推行经济掠夺政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-44fe3e57a56a4a6ea4fe7100f6029e6e','7bff03f9-241e-46bc-a5a4-0fedb615004f',1932,'原哈尔滨警察头目','原哈尔滨警察头目，投日后任伪滨江省（含哈尔滨、大庆部分地区）警务厅长，指挥伪警察配合日军逮捕、杀害抗联战士及爱国群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c9b0e3b21d2469fb98e21b407467b2c','94cb5328-f0e8-4078-98fe-ef443c573d28',1932,'伪满时期大同县（今大庆大同区）汉奸县长','伪满时期大同县（今大庆大同区）汉奸县长，积极为日军征粮、抓劳工，镇压当地抗日活动，具体劣迹包括强征民夫修筑警备道路。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a16e87203ac445d6b48843294ab3d942','2f864117-4a87-4622-a63f-0837248dc428',1932,'原哈尔滨特别市市长','原哈尔滨特别市市长，1932年投敌，后任伪满民生部大臣，参与制定并实施对东北人民的奴役政策。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-267cbef8b5504fb6b68cfcefebc1181b','2f864117-4a87-4622-a63f-0837248dc428',1932,'在哈尔滨任伪职期间','在哈尔滨任伪职期间，配合日军镇压反满抗日活动，推行保甲制度。','危害等级A（甲级，特别市市长）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1190686b91734aeea3e4dcac3adde976','0026147f-f38c-4624-bd31-c7a35853f0bb',1934,'原东北地方官员','原东北地方官员，投日后任伪满滨江省省长，管辖哈尔滨及周边地区，积极推行日伪法令，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75f9d5fead9f44b2ba794bf3f344e0b1','5585d86d-ae88-4493-9857-c6c151508117',1932,'原哈尔滨警察头目','原哈尔滨警察头目，投日后任伪哈尔滨警察厅厅长，后升任滨江省警务厅长，大肆搜捕抗日志士，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ad1117c1fd1c46e3a084791c5146ac57','a0933415-c09d-4866-b421-2da717cad384',1932,'原黑龙江省警察头目','原黑龙江省警察头目，投日后任伪省警务厅长，组织伪警察配合日军“讨伐”抗联，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0b68fe08be26492ca7fe854388e1b98c','9ec8b83a-87d6-4c79-bdd4-6f5e35c9869f',1931,'原奉系将领','原奉系将领，曾任黑龙江省长，九一八后投日，后任伪满国务总理大臣，虽主要活动于新京，但长期控制黑龙江伪政权，是头号汉奸。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1c5cf0043f3343b2b4c01cec3f339a44','9ec8b83a-87d6-4c79-bdd4-6f5e35c9869f',1931,'虽主要活动于伪满中央','虽主要活动于伪满中央，但出身黑龙江，长期控制北满伪政权，对肇州地区殖民统治负有直接责任。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5fb1db0b8754befa08b1b31bb9c536c','9ec8b83a-87d6-4c79-bdd4-6f5e35c9869f',1931,'九一八后投日','九一八后投日，虽居高位，但早期在哈尔滨一带活动，支持日军占领黑龙江，其势力影响鹤岗、绥滨地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ec23d5032ca04e249c6ea502278dba89','5891f38b-03d7-497d-8642-59f695f729fc',1932,'原黑龙江省代主席','原黑龙江省代主席，1932年2月一度投降日军，任伪黑龙江省长，但4月反正抗日，故不列为固定汉奸，但历史上有投敌记录。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6590907ffbdd47b7b6888cb96e158d28','5b11a932-b70c-4212-83d9-9d74848dd168',1932,'原东北军军官','原东北军军官，投日后任伪满第三军管区司令，驻齐齐哈尔，多次率伪军进攻抗联，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bcb433a3dade409a8bce561f5c9936be','5b11a932-b70c-4212-83d9-9d74848dd168',1932,'原东北军军官','原东北军军官，投日后驻守齐齐哈尔，指挥伪军多次“讨伐”抗联部队，在富裕县等地烧杀抢掠','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33f68b36c9c043b2a6efa8a86a61603a','e956a247-6b06-4b89-a02a-40a4d9d42a22',1935,'原哈尔滨警察','原哈尔滨警察，投日后升任滨江省警务厅长，参与策划对东北抗联的“大讨伐”，抓捕大量地下党员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-331d9216a5cb46c88a16693db8722062','19857d82-261b-403d-b6a4-44fe31eabebb',1932,'原黑龙江省教育界人士','原黑龙江省教育界人士，投日后任伪省教育厅长，推行奴化教育，篡改历史，毒害青少年。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6aca87b1d9614cceaf45d77e9947946a','3c503824-ea11-4e61-8d18-01c184500c39',1932,'原黑龙江省官员','原黑龙江省官员，投日后任伪省民政厅长，协助日伪建立保甲制度，强化殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2301c68a374446d8b3e185d31f7188ad','3f4ded3d-81ac-4c22-926a-6a45a2fa4a30',1932,'原地方士绅','原地方士绅，日军占领后出任大庆地区（当时为安达县、肇州县等）维持会长，为日军征粮派夫，欺压百姓。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a719dff7e09940fb91677abfa5c448b3','cabb71dd-63ec-434b-b7cc-bbc8797d48f5',1932,'投日后任伪安达县县长','投日后任伪安达县县长，积极推行日伪苛政，强征劳工，协助日军镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fbffed8f82104ddb9208a7d363098ad0','81fe178f-dd22-4c86-8a31-b9bf10b490a9',1932,'投日后任伪肇州县县长','投日后任伪肇州县县长，组织伪县公署，配合日军“清乡”，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-21e6e3b9387a44dfb159bcbd4a2e2f00','72aa9ee8-f145-4fd6-a865-99e616951b32',1932,'原蒙古族上层','原蒙古族上层，投日后任伪旗长，协助日军控制蒙古族地区，征募伪军。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0b25e0dad024ee0abf7e2a83db1e66c','b646f262-a18b-4f90-97ce-894e5a492158',1931,'原东北军骑兵旅长','原东北军骑兵旅长，江桥抗战后随马占山一度抗日，后于1932年投敌，任伪黑龙江省警备司令，率伪军配合日军镇压黑龙江抗日武装，后任伪满军政部次长，其活动直接覆盖齐齐哈尔、大庆、杜尔伯特一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b162f800ca4a45d3b510d0b26220ef49','b646f262-a18b-4f90-97ce-894e5a492158',1931,'原东北军骑兵旅长','原东北军骑兵旅长，江桥抗战后投敌，任伪黑龙江省警备司令，配合日军镇压黑龙江抗日力量，后任伪满军政部次长。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-534df682d4334038b006eba355853774','9c01c70c-3149-4372-b39b-f64173c2df19',1931,'原东北军军官','原东北军军官，投敌后任伪黑龙江省警备司令部司令，统率伪军配合日军在黑龙江地区围剿抗日联军，其防区包括大庆、杜尔伯特周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a026ab3f24344e33ac490f13a87a4900','9c01c70c-3149-4372-b39b-f64173c2df19',1931,'原东北军军官','原东北军军官，投敌后历任伪黑龙江省警备司令部司令等职，在齐齐哈尔及周边地区指挥伪军配合日军围剿抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c7a4440ce29948cf965e6b4fac587bac','7f10e9ab-d72b-4123-9309-ae6658954e6a',1931,'原东北军军官','原东北军军官，投敌后历任伪黑龙江省长、伪满参议府参议，参与伪满在黑龙江的殖民统治，推行保甲连坐、粮谷出荷等政策，其辖区涵盖大庆、杜尔伯特地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cefc2ac0657e4fea94c82bbc03353491','7f10e9ab-d72b-4123-9309-ae6658954e6a',1931,'原东北军军官','原东北军军官，投敌后任伪黑龙江省长，参与伪满在黑龙江地区的行政统治，后任伪满参议府参议。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f5daecf3f1f46b9bf4e8761c42b9fa0','5875a850-9329-4e69-99eb-245ef530f515',1931,'原哈尔滨商人','原哈尔滨商人，投敌后任伪黑龙江省长，后任伪满经济部大臣，积极推行日本经济掠夺政策，在黑龙江地区强征粮食、劳工，其统治范围包括大庆、杜尔伯特一带。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
