INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0c09a0e1fe34f8bae67a2442b4ae873','e5f48016-51b4-45e4-bd03-a503eb9b25a1',1932,'指挥警察镇压哈尔滨及周边地区反日运动','指挥警察镇压哈尔滨及周边地区反日运动，逮捕并杀害大量抗联情报人员。','危害等级B（乙级，市县厅局级）','hanjian');
