INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b014af3a7cf34bc6a8d917cce1850be1','eebd71c2-4618-422b-9fe1-4aff66457af3',1934,'在林甸县设立多处警察分驻所','在林甸县设立多处警察分驻所，抓捕抗联交通员，参与“归屯并户”政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be9165e1054d4d48a3d667a14a8ed9d5','0f93e535-79d7-4f6f-8dd0-fe1e2f6b6e70',1932,'在肇州、大同（今大庆）一带强征民夫修筑警备道路','在肇州、大同（今大庆）一带强征民夫修筑警备道路，协助日军扫荡抗联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be09e2773e53479e8737533c3270fedc','ff47a655-2f41-4484-a232-764ad35fc713',1933,'在安达地区推行“粮谷出荷”','在安达地区推行“粮谷出荷”，搜刮农民粮食，导致饥荒，并配合日军抓捕抗联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74560606a86e4396b3ca8857681b8364','c35c614f-0e62-468e-b50c-13cd2c0416fc',1932,'在蒙古族聚居区推行日伪“蒙地政策”','在蒙古族聚居区推行日伪“蒙地政策”，强征牲畜，破坏抗日民族统一战线。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8490144f5e06426cbd0a9918777d5bcf','8ab5c656-2f94-4798-818f-eead00ca12ea',1935,'率保安队多次袭击抗联小分队','率保安队多次袭击抗联小分队，在林甸县境内杀害抗联伤员及支持抗联的农民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1eeb4cfe2fb745f18f4a37b4ad9f9510','bb7b260b-2b6e-4619-bbb8-2346612e2daf',1936,'在齐齐哈尔及周边林甸、泰康（今大庆）地区发展密探','在齐齐哈尔及周边林甸、泰康（今大庆）地区发展密探，破坏抗联地下组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-78ac1c1c32dd43a7976f27d6f415eb05','05626ae4-8892-4067-8149-2f245a0433d2',1934,'在黑龙江各地（含林甸、大庆）组织协和会宣传“日满亲善”','在黑龙江各地（含林甸、大庆）组织协和会宣传“日满亲善”，瓦解民众抗日意志。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e183759ec3947a69f591078343b4704','208f3673-2be9-4708-bce4-3a215ad0e239',1931,'原东北军军官','原东北军军官，九一八事变后投敌，曾任伪满洲国江防舰队司令、伪军管区司令等职，参与封锁松花江流域并配合日军讨伐抗日力量，活动涉及大庆周边地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c90b0389c6db44b1a28b3c02be99972e','208f3673-2be9-4708-bce4-3a215ad0e239',1931,'原东北军军官','原东北军军官，投敌后任伪江防舰队司令，率伪舰艇在松花江、黑龙江流域巡逻，配合日军封锁和镇压沿江抗日武装，活动范围包括萝北、鹤岗沿江地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7be8c90b71024069ab64d6976018cb74','40027e30-200b-4bb6-86f9-e8e64f4c7e6e',1931,'在伪满时期于安达县（今大庆市安达地区','在伪满时期于安达县（今大庆市安达地区，邻近红岗）担任伪警察大队长，协助日军维持治安、搜捕抗日人员，属地方伪警头目。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a0b05b1f49146cdad5470c2613655ae','9169c0aa-d809-4678-b097-715588d00189',1931,'伪满时期在肇州县（今大庆市肇州县','伪满时期在肇州县（今大庆市肇州县，邻近红岗）组织维持会，协助日军建立殖民统治秩序，推行保甲制度，为地方附逆者。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fee0417da66c45018c930bc14d49c5cb','87f07188-8d38-49cf-9ac4-a4b233da6d24',1931,'伪满时期在黑龙江省公署任职','伪满时期在黑龙江省公署任职，参与推行日本殖民政策，协助日军控制地方行政，其活动范围覆盖今大庆地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bd5b5c8478c432eb50e250ca5db2c58','57c735e7-2008-4ede-8d63-2c87bc1ab5da',1931,'辽宁金县人','辽宁金县人，九一八事变后投敌，历任伪黑龙江省长、伪经济部大臣等职，协助日本掠夺东北经济资源，其施政范围包括今大庆地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-51c415936c6547ba8281550f0667955f','57c735e7-2008-4ede-8d63-2c87bc1ab5da',1931,'辽宁金县人','辽宁金县人，九一八事变后投敌，历任伪黑龙江省长、伪满洲国经济部大臣，在黑龙江地区推行经济统制政策，掠夺资源支持日军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7bcdea6100844a74a0b9f2fc76860398','eea5da36-2085-41ae-81d5-16100bd27834',1931,'九一八事变后投敌','九一八事变后投敌，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c03a75edd47f410ca813980f1a711ae2','eea5da36-2085-41ae-81d5-16100bd27834',1931,'原东北军将领','原东北军将领，1932年投敌，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4772443b67c142ce8d713dd6dff377bb','fd5e62f7-2957-4d77-8d65-ecd8dfd37d98',1932,'原东北军将领','原东北军将领，叛变后任伪满军事要职，在黑龙江地区围剿抗联，制造多起惨案。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13992271efd440ca883e9020707ebf62','336cf929-d74f-43d6-960c-dcf999ee96ae',1932,'参与伪满建国','参与伪满建国，曾任哈尔滨市长，协助日本控制北满经济与治安。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe7ad435f1954e79b4ae0920417b8972','3032e385-b875-4f7d-8231-8e2c85960f45',1932,'投日后主管伪满财政','投日后主管伪满财政，在黑龙江推行经济掠夺政策，强征粮食与劳工。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3d021ba138574d8d90d21f30206dd850','3032e385-b875-4f7d-8231-8e2c85960f45',1932,'原哈尔滨商人','原哈尔滨商人，投日后负责伪满财政，在牡丹江地区设立“金融合作社”，掠夺当地资源。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e8c7a7a378a4614b55d476487698c2d','3032e385-b875-4f7d-8231-8e2c85960f45',1932,'原黑龙江省官员','原黑龙江省官员，投日后负责伪满财政搜刮，为日军侵华提供经济支持，在绥化、明水等地推行苛捐杂税。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-16c5e9cda3e744ae9d4b6c0e9531fa6f','3032e385-b875-4f7d-8231-8e2c85960f45',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投敌后主管伪省财政，为日军搜刮物资，支持殖民经济，在齐齐哈尔地区推行经济统制','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c206d2e7ee59493ba92808b549aff5bc','3032e385-b875-4f7d-8231-8e2c85960f45',1932,'为日军掠夺黑龙江粮食、木材等资源','为日军掠夺黑龙江粮食、木材等资源，在讷河地区推行“出荷粮”政策，导致民众饥荒。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bc175b0c46eb47ab8bab3c45a6a96af0','00be0a62-e9c0-4f97-babe-10ceb7c3ab42',1933,'曾任伪黑龙江省长','曾任伪黑龙江省长，配合日军“治安肃正”，镇压肇州等地抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ce4f47ac4da4de189a64ea328b38b01','2c501cb0-8846-41d1-8464-d320f96e2e41',1932,'指挥伪警察在肇州、大庆地区搜捕抗日志士','指挥伪警察在肇州、大庆地区搜捕抗日志士，参与“三肇惨案”围剿。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f46e3561a86485ebb997888243f7a82','17b7c00a-bd61-4c33-842c-e6a7d2b38d35',1935,'在肇州任伪县长期间','在肇州任伪县长期间，强征民夫修建警备道路，协助日军清乡并迫害抗联家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67ace82d2b7a46b489a5e2f2e1189fcb','4259cd5f-7eb7-4162-99cd-91c9ce899d5f',1932,'1932年一度投降日军任伪省长','1932年一度投降日军任伪省长，但旋即反正抗日，故在汉奸名录中存争议，仍列此供参考。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a5a6d3a3a5994e529573fbcd5e4b105a','01ef547c-ea8e-4dee-a10a-dd25f9cbad5a',1938,'在肇州、肇东交界地区抓捕抗联交通员','在肇州、肇东交界地区抓捕抗联交通员，破坏地下组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5034bebce267417b9cd51ddc5ec3fa52','023bc233-c893-4038-b745-1906cea04312',1939,'率伪军参与“三肇地区”大讨伐','率伪军参与“三肇地区”大讨伐，杀害抗联第三路军战士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4b3d1901714448e78a39e8e8a1283eae','818efcd9-e345-49c3-b03a-192ae0d88913',1932,'原黑龙江省财政厅长','原黑龙江省财政厅长，投敌后历任伪满黑龙江省省长，后升任伪满民生部大臣，在黑龙江期间强征劳工、掠夺资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-754ef9d55f9145ffaba3e594f4462d91','818efcd9-e345-49c3-b03a-192ae0d88913',1932,'原黑龙江省财政厅长','原黑龙江省财政厅长，投日后历任伪职，在黑龙江推行保甲制度，协助日军搜捕抗联地下组织。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f10e68f33a2d4a3b90916e9f6b6b3201','818efcd9-e345-49c3-b03a-192ae0d88913',1932,'原黑龙江省财政厅长','原黑龙江省财政厅长，投敌后历任伪满黑龙江省省长，在绥化、肇东地区推行“保甲制度”和“集团部落”，配合日军对抗联进行经济封锁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9c634b243f94966945e0836c11f312b','818efcd9-e345-49c3-b03a-192ae0d88913',1932,'原东北军将领','原东北军将领，叛变后任伪职，在鹤岗地区推行“保甲连坐”制度，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fefff0ac43604f3189fd44d54ab4d00f','ed498ae1-1ede-4509-a778-1913923885a9',1934,'原哈尔滨特别市市长','原哈尔滨特别市市长，投敌后任伪满滨江省省长（辖今哈尔滨、大庆、肇源一带），协助日军建立保甲制度，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4cb0f55e9709465f84b55d80b87523dc','ed498ae1-1ede-4509-a778-1913923885a9',1934,'原哈尔滨特区长官','原哈尔滨特区长官，投敌后任伪满滨江省省长，管辖区域包括肇东（时属滨江省），曾组织伪警察和自卫团在肇东一带搜捕抗日分子。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-387c58d65e7f4829adf82007a0fae3c6','dd2819f1-5eb5-4394-9862-588f5b09ec39',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投敌后任伪满滨江省省长，后任伪满外交部大臣，在任期间推行“治安肃正”，迫害抗日军民。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7899f3949a8a49ae8d6f3926ed8f9087','dd2819f1-5eb5-4394-9862-588f5b09ec39',1932,'原哈尔滨市市长','原哈尔滨市市长，投敌后任伪满滨江省省长，肇东在其辖区内，曾多次到肇东视察“治安工作”，督促地方伪政权强化对民众的控制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-402a922582d240a6a3e68a22923a2ba7','dd2819f1-5eb5-4394-9862-588f5b09ec39',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投日后任伪满滨江省省长（辖今哈尔滨、黑河部分地区），后任伪满外交部大臣。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3dd711388ea1417ab57a15cdad3fac8a','b266dabd-bf65-4973-ba5b-1f9cccf176d3',1940,'原东北地方官员','原东北地方官员，投敌后任伪满滨江省省长，管辖肇源等县，配合日军进行“大讨伐”，残害抗联战士及群众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c078a0163154dd39620586ecef5f758','c5f0b44b-6f17-461c-90b9-8466d0b400da',1934,'原哈尔滨警察头目','原哈尔滨警察头目，投敌后长期任伪满滨江省警务厅厅长，直接指挥警察特务在肇源、大庆等地搜捕抗日分子，制造多起惨案。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9046176fa944d92a2ab4b13fd049da9','e2178adc-63fc-43e6-aa92-fa0b54ece078',1932,'原肇州地方士绅','原肇州地方士绅，投敌后任伪满肇州县县长（今属大庆），强征民夫修建公路、碉堡，协助日军“讨伐”抗联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6b747a6174cd4c8ca90e6647fa41ba44','9415eb75-c4b8-4b51-8850-20ddb7ff8676',1933,'原肇源县商会会长','原肇源县商会会长，投敌后任伪满肇源县县长，推行“粮谷出荷”，搜刮民财，并告密导致抗联小分队被围。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29c89108b3d541c98adb07fa7d57c9a4','91e9b9c5-f8fb-4455-997b-323812a98109',1935,'原肇源县警察','原肇源县警察，投敌后任伪满肇源县警务科科长，亲自带队抓捕抗联交通员，刑讯逼供，杀害多名抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86c1785beffa4af6bfbdb85ebdec45be','8f318046-8c4c-46f5-a97c-2b04c4dde17c',1932,'原萨尔图地主武装头目','原萨尔图地主武装头目，投敌后组织维持会，为日军提供情报，参与“清乡”行动，迫害当地抗日家属。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-417d0eb52caa4312ad5516a13a2f0666','ed74b5da-3326-43f2-8d05-8cf28786cd12',1931,'原东北军军官','原东北军军官，九一八事变后投敌，任伪军中将，在黑龙江、吉林地区参与围剿抗日义勇军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e63849f9780249829c4d47a3c0b1e605','38b0ba9e-5ea3-410f-8ff7-b0fd9a2099a5',1932,'黑龙江人','黑龙江人，投敌后任伪黑龙江省公署厅长，参与伪政权行政事务，协助日军推行保甲制度与物资统制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8bfa9f072a2549b7976ab43f244c4138','38b0ba9e-5ea3-410f-8ff7-b0fd9a2099a5',1932,'黑龙江地方士绅','黑龙江地方士绅，投敌后任伪黑龙江省公署要职，协助日军推行殖民政策，参与地方伪政权建设，活动于齐齐哈尔地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9401716746cf42b2acd6d73a0740d0ec','07841143-ec80-438b-bced-879b06970068',1932,'投敌后任伪黑龙江省公署参事官','投敌后任伪黑龙江省公署参事官，参与伪政权决策，协助日军在黑龙江地区实施殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe2b939661a341fbba8e1f456add56a4','a2e53155-2eae-4d16-a9bd-94be3bc4f16f',1934,'投敌后任伪滨江省公署省长','投敌后任伪滨江省公署省长，滨江省辖今哈尔滨及大庆部分地区，参与推行伪满政策，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-627c3d2b33a740719746605a47714444','29ed01af-7a53-4ef3-8912-d3f99c72d732',1932,'投敌后任伪滨江省公署厅长','投敌后任伪滨江省公署厅长，参与伪政权行政，协助日军在滨江省（含今大庆地区）推行保甲连坐与物资掠夺。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a88355518e774ce3bce237da37d7547f','0c1cda62-fe02-4e8d-ad24-fecfef75e355',1932,'投敌后历任伪哈尔滨市长、伪滨江省省长','投敌后历任伪哈尔滨市长、伪滨江省省长，在哈尔滨及周边地区推行伪满政策，参与镇压抗日地下活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ed93297b95ca49fdb334e7bf87a4daaa','0b1cadbf-843c-422f-b36b-4d83cac704d9',1932,'投敌后任伪滨江省警务厅厅长','投敌后任伪滨江省警务厅厅长，指挥伪警察在滨江省各地搜捕抗日人员，推行治安肃正。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38a5413b53da4853b47eb55ce1001251','1949d126-c9f7-4fb6-aa00-170e35d086c1',1932,'肇州（今属大庆市）人','肇州（今属大庆市）人，投敌后任伪肇州县公署县长，在肇州及萨尔图一带推行伪满政令，协助日军征粮、抓劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2538e218964f4909b2da47d96c7a7858','4ff02803-2db6-4466-ac23-1888d1e1bc2f',1932,'投敌后任伪肇州县公署参事官','投敌后任伪肇州县公署参事官，参与伪县政，协助日军在肇州地区实施保甲制度与物资统制。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-964071625c5d49cfa7efdbda245e9b65','0a9f327e-beab-4c67-989f-12377f34825a',1932,'安达（今属大庆市）人','安达（今属大庆市）人，投敌后任伪安达县公署县长，在安达及萨尔图一带推行伪满政策，协助日军掠夺资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-216fbba9466f47a899b5197540df3997','75f03d89-55ff-4191-97ef-27af97833d15',1932,'林甸（今属大庆市）人','林甸（今属大庆市）人，投敌后任伪林甸县公署县长，在林甸地区推行伪满政令，协助日军征粮、抓劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2c57681a607a4391b1f88347814056c7','64e34a83-2599-489a-ae1a-b3c868ee3651',1932,'杜尔伯特旗（今属大庆市）投敌者','杜尔伯特旗（今属大庆市）投敌者，任伪旗长，协助日军在杜尔伯特地区推行殖民统治，掠夺畜牧资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e9b31d27fcf3481098a085007e729e0a','632edb77-3ba1-4566-b509-032920ed12f8',1932,'萨尔图（今大庆市萨尔图区）投敌者','萨尔图（今大庆市萨尔图区）投敌者，任伪保长，协助日军在萨尔图一带推行保甲制度，征粮、抓劳工、监视抗日人员。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a805f99b11a24c5daa13588ab01cbed9','b1e3fdd2-1154-4fb2-81b3-5729265222f4',1932,'萨尔图投敌者','萨尔图投敌者，任伪警察分驻所所长，在萨尔图及周边地区搜捕抗日人员，配合日军维持殖民治安。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9070578d3edf4c22830963784dff5f72','c762a9c3-d64f-4cbe-9e5e-9c3ed5b9914f',1931,'原东北军将领','原东北军将领，1931年后投敌，历任伪奉天警备司令、伪军政部大臣等职，率伪军配合日军在东北包括黑龙江地区围剿抗日武装。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-477f0029f21e43849d6df95d09eb4328','c762a9c3-d64f-4cbe-9e5e-9c3ed5b9914f',1931,'原东北军东边道镇守使','原东北军东边道镇守使，1931年九一八事变后投敌，组织伪军配合日军进攻抗日武装，后任伪满洲国军政部大臣、治安部大臣，统辖伪满军警镇压东北抗日联军，其伪军活动范围包括黑龙江、齐齐哈尔一带。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b61d669ef384feb877eea27a863cb57','b68c9a78-d216-473a-ad13-35f75fa32a3e',1931,'原东北军骑兵将领','原东北军骑兵将领，江桥抗战后投敌，任伪黑龙江省警备司令，率伪军配合日军在黑龙江地区围剿抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-96fb869138e04d0ca08433cbd6ecd539','419110dd-ed47-4a98-8560-8d66596c2c84',1931,'原东北军军官','原东北军军官，随程志远投敌，在伪黑龙江省警备司令部任职，参与对黑龙江地区抗日武装的围剿。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b47a74d0ceb446eaa0e952b4d94b51a','0a41c03f-628a-4e15-b07d-81fa6a62273c',1931,'原哈尔滨商人','原哈尔滨商人，九一八事变后投敌，历任伪黑龙江省长、伪滨江省长等职，参与伪满对黑龙江地区的殖民统治和经济掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-643b861589864468afd6e067646a054c','0a41c03f-628a-4e15-b07d-81fa6a62273c',1931,'辽宁金县人','辽宁金县人，1932年投敌，历任伪黑龙江省长、伪滨江省长、伪经济部大臣等职，在齐齐哈尔等地推行经济统制，为日军掠夺资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47c6e13c72a14e3da8dc304104f98c36','d2447623-7c17-463f-a033-c7a6d97f5cfc',1931,'原东北地方官员','原东北地方官员，九一八事变后投敌，曾任伪黑龙江省长，参与伪满对黑龙江地区的统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-19af59d012e14da5a2ff0dc36a26386e','58e4f510-7ba6-473c-8f3d-4ee1db257e77',1931,'原黑龙江地方士绅','原黑龙江地方士绅，九一八事变后投敌，在伪黑龙江省公署任职并参与伪满协和会活动，协助日军推行殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d224e32bf12d415b8147646dc266bff1','b27033e2-bf94-418c-951c-82cbaa532858',1931,'大庆地区地方士绅','大庆地区地方士绅，日军侵占后组织维持会，协助日军维持地方秩序、征发物资，为伪政权在让胡路及周边地区的基层代理人。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0480515e7d434167b332e95baa328623','f1594c77-2e3b-4bab-ae54-4e2c9431f9bb',1931,'伪满时期任安达县县长','伪满时期任安达县县长，安达为今大庆市辖区之一，其伪政权统治覆盖让胡路周边地区，协助日军征粮、征兵、镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05facb68b2e04242a82180deb8211f78','ee639b3e-4e0e-4a0b-9e18-a542fe5fc45e',1931,'伪满时期任肇州县县长','伪满时期任肇州县县长，肇州为今大庆市辖区，其伪政权活动覆盖大庆南部包括让胡路周边，协助日军推行保甲制、征发劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb61d61baf0648b2b716aae07e7a6fef','4a9d2efc-1d4a-42d3-b0d3-4c2b5a1f8856',1931,'伪满时期任林甸县县长','伪满时期任林甸县县长，林甸为今大庆市辖区，其伪政权活动覆盖大庆北部地区，协助日军征粮、维持治安。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4c7c85574f445179ab651ddf4a58f76','4108eb34-6836-4f9f-9c5e-6785cc62554d',1931,'伪满时期杜尔伯特旗（今大庆市杜尔伯特蒙古族自治县）旗长','伪满时期杜尔伯特旗（今大庆市杜尔伯特蒙古族自治县）旗长，协助日军在牧区推行殖民统治、征发牲畜物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f1da740420a41d78b4098e5d19dcdad','94ffd1c9-3ddd-4822-9da7-67c77677943f',1931,'原东北地方官员','原东北地方官员，九一八事变后投敌，历任伪哈尔滨警察厅长、伪滨江省长等职，其统治区域邻近大庆地区，参与镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b5281529224447bfb664b267603f4ee9','94ffd1c9-3ddd-4822-9da7-67c77677943f',1931,'投敌后历任伪哈尔滨警察厅长、伪滨江省长等职','投敌后历任伪哈尔滨警察厅长、伪滨江省长等职，镇压哈尔滨及周边地区抗日活动，其辖区与齐齐哈尔地区相邻。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d82cc3645327471bb6a3018b8d4c447e','a7ab0e18-274b-40ab-807a-01bb9489a21b',1931,'伪满协和会黑龙江省本部负责人之一','伪满协和会黑龙江省本部负责人之一，在黑龙江各地包括大庆地区推行协和会运动，协助日军进行思想控制和殖民宣传。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
