INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-954e67b56474496ca1c8ea61a7ff927e','c85cf0b4-bd91-4035-9345-5502e15246da',1933,'在宁安推行“集团部落”政策','在宁安推行“集团部落”政策，强迫农民并村，烧毁民房，制造无人区，切断抗联与群众联系。','危害等级C（丙级，基层头目）','hanjian');
