INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8157f74588d7473c83e424b73a3d65a3','b376233d-fb03-4067-8f84-0df1736cd6ce',1935,'控制牡丹江铁路运输','控制牡丹江铁路运输，为日军运送兵力和军火，同时协助封锁抗联物资流通。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-773bd392e4e74447a16c1dc6a0b7c6be','88e37224-f468-4869-84d6-98a2f9eee297',1937,'推行“勤劳奉仕”制度','推行“勤劳奉仕”制度，强征中国劳工为日军修建军事设施，导致大量劳工死亡。','危害等级B（乙级，市县厅局级）','hanjian');
