INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-13484e1881de410f86356f0d21ef3a45','ab85ba4e-fe65-4588-b030-3e1639cba622',1933,'原热河地方武装首领','原热河地方武装首领，投日后任伪满蒙古军总司令，曾率部参与对黑龙江东部及牡丹江地区的扫荡，配合日军镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fabc1013e3914943bedb7274e499bf4f','622666d0-0eec-42f4-8518-5e042b37ed70',1932,'原东宁地方士绅','原东宁地方士绅，伪满建立后出任东宁县县长，积极推行日伪殖民政策，协助日军在东宁边境修建军事要塞，强征劳工，迫害抗日群众。','危害等级C（丙级，基层头目）','hanjian');
