INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58a18620a1ef4f8b915a6acfacc6c4a0','52d05190-7bfa-4911-9395-4359ce995bd7',1933,'原东宁地方警察','原东宁地方警察，投日后任东宁警察署署长，多次参与搜捕抗联交通员和群众，为日军提供情报，协助镇压东宁地区抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d5d13c9be7847e19eeef8024bc494c3','bcf825f3-0d6b-4afe-b036-cddc3f2cd68c',1938,'原牡丹江地区商人','原牡丹江地区商人，投日后任伪满协和会牡丹江省事务长，积极宣传“日满亲善”，组织汉奸团体，为日军筹粮筹款，破坏抗日统一战线。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
