INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-afb39961da4345e080060752d5996481','126f5e58-d6e7-4b0f-bb15-c3d8892cc27e',1933,'原东北军下级军官','原东北军下级军官，投日后任东宁地区警备司令，负责东宁边境防务，协助日军修建东宁要塞，并率伪军参与对苏联边境的侦察和对抗联的围剿。','危害等级B（乙级，市县厅局级）','hanjian');
