INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-877e3886d9874e279a1847329db07a32','eb3ed5a7-780a-4fb5-abaa-f0f24f3b90da',1932,'原东北军将领','原东北军将领，后投敌，在牡丹江、林口地区多次指挥伪军对抗联第二、第五军进行“讨伐”，制造多起惨案。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2e371c4abdf94442b95bb61f66ec2432','eb3ed5a7-780a-4fb5-abaa-f0f24f3b90da',1932,'原吉林自卫军将领','原吉林自卫军将领，叛变后任伪军高官，在黑龙江、牡丹江地区多次率伪军“围剿”东北抗日联军，制造多起惨案。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-42aab5bd8951453c9e2d8234d925ab3c','eb3ed5a7-780a-4fb5-abaa-f0f24f3b90da',1932,'原吉林自卫军将领','原吉林自卫军将领，1932年率部投日，后任伪满第四军管区司令，管辖包括牡丹江地区，多次参与“讨伐”抗日联军，残害抗联将士。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c35af5d9c61246b4950aa2fabd084f3a','7ac5a631-a242-4216-a6bd-ebc44588955f',1937,'在牡丹江地区组织特务警察网','在牡丹江地区组织特务警察网，破坏抗联地下组织，逮捕并杀害多名抗联联络员和爱国群众。','危害等级B（乙级，市县厅局级）','hanjian');
