INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54d593f705f248a58f87847f14ae4c2a','adaa3b11-f08b-4aa4-a8b4-dc9d05a1be07',1931,'1939年叛变后','1939年叛变后，在牡丹江、林口一带充当日军向导，诱降抗联人员，参与围剿抗联第二路军，导致多支小分队被消灭。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c75fcc9ff6884c49bf88a180b176d979','95adc584-039a-4dd3-b5ec-fea138f6cb1e',1931,'1939年投敌后','1939年投敌后，在勃利、林口地区协助日军搜捕抗联，出卖抗联密营位置，致使抗联第八军余部几乎全灭。','危害等级B（乙级，市县厅局级）','hanjian');
