INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-520954e603d54f80abd07c320dadbea6','c90e14ca-bc79-404a-88cd-07daca8313fe',1932,'投日后任海林县伪县长','投日后任海林县伪县长，协助日军建立伪政权，强征劳工修筑铁路和军事设施，对抗联活动区域进行经济封锁。','危害等级C（丙级，基层头目）','hanjian');
