INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-99417d9546914bf98fbf415830bff461','7c0a55d8-553b-4460-a71e-3ca07753a361',1933,'率伪军部队驻扎牡丹江','率伪军部队驻扎牡丹江，多次参与对海林、宁安一带抗联的“大讨伐”，烧毁村屯，屠杀抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d6e223378b642f5a5fabb371aa84b2e','f2ff9c0d-33be-4a98-8583-34e06e6e3ce6',1939,'负责地方武装和情报工作','负责地方武装和情报工作，在海林地区建立特务网，诱捕抗联人员，破坏抗联与地方百姓的联系。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9af89472c28c4a1dbe08f3966d87e8d7','61a3d999-6629-4dc3-94c9-8331baebcb03',1937,'原地方官僚','原地方官僚，投日后任伪牡丹江省省长，推行日伪“治安肃正”，强征劳工，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-167a23a6fa41455a9a507ea45b8f5369','6b52aaf4-1694-451a-864c-d2fa536e38c8',1938,'负责牡丹江地区伪警察系统','负责牡丹江地区伪警察系统，协助日本宪兵队抓捕抗联地下工作者，实施“归屯并户”。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f321cd8f4f26462baec5b3a55a2c7a97','ca63d031-cdee-4297-83f4-26fd9ef0bed5',1933,'原东北军团长','原东北军团长，投日后任伪警备司令，多次率部“讨伐”镜泊湖、宁安一带的抗联游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b66d205aac194512905235998b35ae93','fd15605e-de77-44db-84b0-49f0c9d91f5d',1935,'在爱民地区推行保甲制度','在爱民地区推行保甲制度，强征粮食，向日军提供抗联活动情报，导致多名抗日群众被捕。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79b8e36fbb934e66b8a263ec3ed86f26','1878a518-ff55-4bdf-8da7-f5574c839eda',1937,'率伪警察配合日军“讨伐”','率伪警察配合日军“讨伐”，在爱民山区烧毁民房，抓捕抗联交通员，并参与“集团部落”建设。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93957c0d9c4c499cba6c61fb85b7ef23','41f232d8-29e7-40be-8bad-ccb46e939f12',1932,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，虽常驻新京，但曾多次到牡丹江地区视察“治安”，支持日军对爱民等地的清剿。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f7c915653ebb44149dd5445a9d2554fb','1571a01a-0c70-4f28-8776-141bc6fb0b1c',1932,'虽主要活动于新京','虽主要活动于新京，但曾参与制定针对牡丹江地区的“治安肃正”计划，支持爱民一带的“无人区”政策。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a0d5c35818714811a8e5de23343a10e6','9409c87c-66c0-48d6-9876-250835f4f8f1',1932,'原吉林自卫军将领','原吉林自卫军将领，1932年率部投敌，后任伪满军高官，在牡丹江、哈尔滨等地多次围剿东北抗日联军，制造多起惨案。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce08e741ab2f49928dd42f02d7b680ac','4d206342-8e11-488c-9e3b-f5dc9e46127a',1937,'原东北军旅长','原东北军旅长，投日后任伪牡丹江省省长，在牡丹江地区推行“集团部落”政策，制造无人区，对抗联进行经济封锁。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5545223ca64405bba378556da03ed36','d35d0a2b-b159-442e-8de2-0b6848006842',1937,'日本关东军特务出身','日本关东军特务出身，以“次长”身份控制牡丹江省政务，指挥伪警宪特围剿抗联，残害当地百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3ca4087363c470ea0d18bdef95f291e','9b2b93a2-0645-423b-9e3c-214aeb9ab65e',1938,'原地方士绅','原地方士绅，投日后任伪牡丹江市市长，协助日军建立市镇统治，强征劳工修建军事设施。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76e2135f0c3d497190b4ca40c047a8ba','65cbbf3a-2582-45d3-b8f3-e45e1e023f3e',1935,'原奉系将领','原奉系将领，九一八后投敌，任伪满最高行政长官，全面配合日军对黑龙江、牡丹江等地的殖民统治和军事镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2093b709fbcf4175b417587372d5bbfa','b84c00cf-4f6f-479a-834f-7ac329d07b52',1932,'原辽宁省政府主席','原辽宁省政府主席，投日后任伪满高官，参与制定针对东北抗联的“治安肃正”计划，间接影响牡丹江地区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8498483d198e4ae3a6b9abfc725c1bd1','8092c629-5df1-4d53-ab5c-cb445a0bbcac',1932,'原吉林副司令长官','原吉林副司令长官，投日后协助日军整合伪军，其部队曾参与对牡丹江镜泊湖一带抗联的围剿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-18a83df19d3c47b38f40c0ca572fb21e','dcb20551-4a37-4bc3-b6f0-b234e5e19585',1937,'伪满警察头目','伪满警察头目，在牡丹江地区组建特务网络，抓捕抗联交通员，刑讯逼供，杀害多名地下党员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71e81bc1e1de4d51b96e00c07d540c43','d70aa1c3-b629-41f7-bb2d-49ca5fa5c3dd',1932,'原东北军法务人员','原东北军法务人员，投日后任伪满法官，以“反满抗日”罪名判处大量爱国志士死刑，包括牡丹江地区被捕人员。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-553a848ca29c4dc8a1a0fe764d240b03','9f5e7da8-3431-472d-be52-339a7cc6edf4',1932,'原哈尔滨警察头目','原哈尔滨警察头目，投日后多次率特务赴牡丹江、宁安等地破坏抗联地下联络站。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-911e6b913bbd419ba97e80dd32d33424','2e04a3b1-c29a-4200-b052-8652362f5cdf',1938,'地方汉奸武装头目','地方汉奸武装头目，配合日军“讨伐”抗联，在牡丹江周边村庄烧杀抢掠，强迫村民“归屯并户”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-301fdb359003469a9bd32d0897203841','24a39b61-ac29-4912-9ff5-7e1c97801ff8',1936,'在宁安地区推行日伪“粮谷出荷”政策','在宁安地区推行日伪“粮谷出荷”政策，强征农民粮食，并协助日军搜捕抗联第五军留守人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3f6166495be9435f8c0d9884faf15e37','6097de11-b1b0-48be-ba60-b5c10dcb87cc',1937,'在穆棱地区组织“自卫团”','在穆棱地区组织“自卫团”，配合日军袭击抗联密营，破坏抗日根据地。','危害等级C（丙级，基层头目）','hanjian');
