INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3732861504f4d4984da095417506326','8d44aba5-6613-4c34-bf9e-af241aa83cdb',1940,'在林口地区推行“连坐保甲”','在林口地区推行“连坐保甲”，强迫百姓报告抗联行踪，导致多处抗联秘密仓库被毁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a6bb1b8a3c3496dae1be39145dd7c2f','3e5b473a-8bf0-400f-b04f-91b0cbcf8bee',1938,'为日本宪兵队充当翻译','为日本宪兵队充当翻译，参与审讯和酷刑，直接迫害被捕的抗联战士和爱国群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-50822994d7594b108d0a65690d1e8bac','caef3a01-bcc8-4077-8dcd-dc68b5c90239',1933,'在穆棱县任职期间','在穆棱县任职期间，积极推行日伪殖民政策，强征劳工，配合日军清乡，破坏抗日地下组织，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0407092d87bd40eabe89b2e9a2dd8aaa','4108a245-ebe8-4bf3-bd85-c9a5a7ab3cd3',1934,'在穆棱地区组织伪警察','在穆棱地区组织伪警察，多次参与搜捕抗联交通员，刑讯逼供，导致多名抗日志士牺牲，并协助日军建立“集团部落”。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39d358d0db464ec48a0dc84563e5a8a0','849ce544-e22c-45ea-8bf0-60efe8e598a8',1937,'在牡丹江地区主持伪警务','在牡丹江地区主持伪警务，指挥特务警察破坏抗联地下联络站，诱降抗联叛徒，参与制造多起屠杀事件。','危害等级B（乙级，市县厅局级）','hanjian');
