INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b89ecf3ba0cb4ad0949ea135e587d973','eeb5d0e5-bb75-4df2-937b-9dead16ab7ea',1935,'率保安队配合日军“讨伐”抗联第五军','率保安队配合日军“讨伐”抗联第五军，在穆棱山区多次袭击抗联密营，杀害抗联伤员，并参与强迫农民迁入“人圈”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e46d2ca944104aad9136ee61f5d29f94','1d0d08fd-b5bd-4047-89ec-25b95164da55',1936,'在牡丹江宪兵队担任翻译','在牡丹江宪兵队担任翻译，参与审讯和拷打被捕抗联人员，直接导致多名抗联干部被处决，并协助日军进行“特别移送”。','危害等级C（丙级，基层头目）','hanjian');
