INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-151eaf586a5b4ff887cdf63b32b99204','83babfe0-f5d2-4da5-82d0-228c558b8910',1931,'原东北军将领','原东北军将领，九一八后投敌，曾任伪满黑龙江省长等职，协助日军镇压抗日力量，在绥化、兰西一带推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f3b38fc19e38403cb7a9d12c38feeeec','27d81726-e941-4f68-8e54-f1a841d6145e',1932,'原地方士绅','原地方士绅，投靠日军后任伪省参事，参与组织地方维持会，为日军征粮派夫，在兰西县境内协助清乡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee0f383e711b4ef58a799c03348ae975','b9274ae2-28bd-4bd0-8fdc-8ab5457d7fcd',1934,'负责伪警务','负责伪警务，在兰西、绥化等地建立警察网络，抓捕抗日地下人员，推行保甲连坐制度。','危害等级B（乙级，市县厅局级）','hanjian');
