INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4a7e98184da249e0bb6c9c8895f4b236','0042e055-36e4-4045-8710-3a50cc04e9f9',1933,'原地方官僚','原地方官僚，投日后任绥化伪县长，推行奴化教育，强制民众参加“勤劳奉仕”，协助日军抓捕抗日分子。','危害等级C（丙级，基层头目）','hanjian');
