INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-91b515255c0346ab9ccec105a0411872','0fb9b8b5-03ec-408f-81c4-63825ef787cc',1932,'原东北政客','原东北政客，投日后历任伪黑龙江省长等职，参与制定经济掠夺政策，导致兰西、绥化农民粮食被搜刮殆尽。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
