INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-202cb8d88cb942e1bc2bb0d298b69a4b','e6ff68dc-2f0a-4833-9a50-d7d73d8db0d1',1931,'九一八事变后组织伪黑龙江省维持会','九一八事变后组织伪黑龙江省维持会，任会长，后任伪黑龙江省长，协助日军控制绥化、望奎等县，推行保甲连坐，镇压抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0f82d925fe8445029ec1b7d199c7342e','eca39f1f-86be-48bb-b232-3588fa8e9696',1932,'原为哈尔滨商人','原为哈尔滨商人，投敌后任伪黑龙江省长，积极为日军筹粮筹款，在绥化、望奎等地推行经济统制，后任伪满经济部大臣。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b5a096ba8e4492e98fc341ad5ddd1bc','33c81cf8-3f8b-4eb9-9952-10c76e1126e9',1932,'九一八事变后投敌','九一八事变后投敌，出任伪绥化县县长兼维持会会长，协助日军建立伪政权，征发劳工、粮食，镇压当地抗日救国会。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e2fac3619e844918b8537de7db45cfbb','8da19c59-20ba-4266-b5d4-0647dfd62e49',1933,'投敌后任伪望奎县县长','投敌后任伪望奎县县长，后兼警察署长，在望奎推行保甲制，搜捕抗日地下工作者，强征国兵和劳工，为日军提供情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-681a69fe8c1c49cf9ffd08993b668b99','65e48dbb-f05c-44a0-be06-e1489a1c0c02',1934,'长期在绥化地区任伪警察头目','长期在绥化地区任伪警察头目，指挥伪警察配合日军讨伐队扫荡抗日联军，在望奎、绥棱等地制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b9cbfc7d7aed4735895888eb082f1226','bd4cf625-1fdf-4fca-bba0-8b7e7c6861f8',1935,'望奎本地地主','望奎本地地主，投敌后任保甲长兼协和会会长，协助日军征粮、抓劳工，监视村民，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-002301cd526a4ae2aa801cbbd40a12b5','565e24a6-c68d-418c-970b-a33138686831',1936,'在绥化教育界推行奴化教育','在绥化教育界推行奴化教育，编写亲日教材，组织学生参拜神社，为日军培养顺民，是文化教育领域附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9aacd6e0de2a4daaabaeb012c23a3a0f','89c12c28-5e60-45a0-8f97-03c52168e262',1937,'望奎商人','望奎商人，投敌后任商务会长，协助日军实施经济统制，低价强购粮食、物资，供给日军，压榨当地民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b259e87f79b491b923194eaeefc631b','fa7f15e1-b997-4d7c-8165-d8804c871bfb',1938,'组建伪保安团','组建伪保安团，配合日军在绥化、望奎、庆安等地讨伐抗日联军，杀害抗日军民，后升任伪滨江省保安总队副。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7dc1f95953e5452c9b7a2a6a588097f4','bb06a8cd-95e9-4c0c-98d9-100a221873d8',1931,'清室宗亲','清室宗亲，九一八事变后率先投敌，以吉林省长身份宣布独立，后任伪满财政部大臣，其附逆行为对包括黑龙江在内的东北全境产生恶劣影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-162b48517d4b4ad58f96dd3bc3772df0','bd11e862-45ad-4b7e-bee1-1ca9f8b66262',1931,'原辽宁省主席','原辽宁省主席，被俘后投敌，历任伪奉天省长、民政部大臣，参与伪满殖民统治，其政策推行至黑龙江各地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d20ee3c808fa4b219e1353678ec9d24f','6725667e-fb9c-42aa-ab0e-3968facf1790',1932,'原中东铁路督办','原中东铁路督办，投敌后任伪滨江省长，管辖区域包括今哈尔滨及绥化部分地区，参与镇压抗日活动、推行保甲连坐。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06ba0b2eb70d46e6aa36852df5b11d12','d9aee6bb-cc0e-47bd-9269-fff4d5c150fd',1932,'原东北军军官','原东北军军官，投敌后任伪军旅长、第三军管区司令官，活动于北满地区，包括绥化、海伦一带，参与围剿东北抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2a689f04f09b44e7968541ff038dc8d9','35382793-e86c-40c4-8541-f2b317b1cd47',1932,'达斡尔族','达斡尔族，投敌后历任伪军团长、旅长、第十军管区司令官，驻防海拉尔、齐齐哈尔等地，其部队活动范围覆盖黑龙江北部，参与镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dec1c232a59545099ee7caab93c3f91c','df90420f-5ef2-4391-b6c8-921d76c485fc',1932,'投敌后历任伪哈尔滨警察厅长、市长、滨江省长','投敌后历任伪哈尔滨警察厅长、市长、滨江省长，管辖哈尔滨及周边绥化地区，推行殖民统治，镇压抗日地下活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b268102a245a48689000d38ecdcbe5aa','0d0963d5-2c0d-4a48-9939-2d31fb64d545',1932,'原东北海军军官','原东北海军军官，投敌后任伪江防舰队司令，活动于松花江流域，包括绥化、海伦附近水域，配合日军封锁抗日联军水上通道。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3fb89df010784c5995bc33dd88c745cc','0daefeed-a7b0-423f-aaad-a155b1992aa3',1932,'原东北军军官','原东北军军官，投敌后任伪靖安军司令，率部在黑龙江各地进行治安肃正，包括绥化、海伦地区，参与围剿抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bafa3d0955d94ce498bcfb0ecfdb2dd0','cb6f7367-6230-4d41-b62a-b6f6926664b8',1932,'投敌后任伪军团长、绥化地区警备司令','投敌后任伪军团长、绥化地区警备司令，直接负责绥化、海伦一带的治安肃正，配合日军围剿抗日联军和地下抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-176ab0f9305244b6b9245d69e73e4025','fcabb8d7-f304-4bcf-bdb4-906d1a2d9718',1932,'伪满时期任海伦县县长','伪满时期任海伦县县长，推行保甲制度、粮谷出荷、劳工征发等殖民政策，配合日军镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8b3ec79989414901ad0bb13712e426ce','f37d80b5-ead2-43fe-8757-d0dec346cfdb',1932,'伪满时期任绥化县县长','伪满时期任绥化县县长，执行日伪殖民统治政策，组织维持会、保甲自卫团，协助日军搜捕抗日人员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b77aad9e73934ff183fb60c32aec90d8','b4c87f28-0b86-48be-bb82-b41ff5613ccf',1932,'九一八事变后在海伦组织维持会','九一八事变后在海伦组织维持会，迎接日军进城，协助建立伪政权，为日军筹集物资、提供情报。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be610ee41e354f209a14f53cccf771aa','6a945680-17cd-4c59-88a4-9b9d03403523',1932,'在绥化组织维持会','在绥化组织维持会，投靠日军，协助维持地方秩序、征发民夫，为伪政权建立铺路。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e455c74e1f2a403fa01a01ba3de47bcf','a788424a-61f6-4614-a4cc-01db6a2870ba',1932,'任协和会绥化分会会长','任协和会绥化分会会长，进行亲日宣传、奴化教育，组织青少年团、妇女会等，配合日伪殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b3870d6cfe84596b809b8f5e46ab2a7','6dc9f127-f837-40ba-be04-f2b0bce829cf',1932,'任协和会海伦分会会长','任协和会海伦分会会长，推行奴化教育，协助日军征发劳工、粮谷，监视民众思想。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f988c2660da4bfca712c359036fd16c','770f50e0-150a-4467-8d08-42404f5f1cb8',1932,'任伪绥化县警察署长','任伪绥化县警察署长，指挥伪警察搜捕抗日人员，实施保甲连坐，镇压民众反抗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd402ce4252e4fa29fc8c6e82dc94857','eb32291e-1fb2-477d-91d2-6f0499b30e77',1932,'任伪海伦县警察署长','任伪海伦县警察署长，配合日军宪兵队进行治安肃正，抓捕抗日嫌疑分子，刑讯逼供。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-116bb16bc83f4bc8801ee102d09577d6','8077375e-5d51-4a26-bd1f-faef2e530b0c',1932,'任伪绥化县自卫团团长','任伪绥化县自卫团团长，率地主武装配合日军围剿抗日联军，袭击抗日游击区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-59c295b6d9c04aabb98a8b02868f0d01','73348a1a-670f-43be-b5b4-da01ed7a147b',1932,'任海伦县某保保长','任海伦县某保保长，执行保甲制度，监视居民，为日军提供情报，征发劳工和粮谷。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab1fdbdde9674c549b8bd3da05b04711','d5e48a42-5744-4f91-97e3-429b7150d804',1932,'任伪绥化县教育会长','任伪绥化县教育会长，推行日语教育、奴化课程，篡改历史，培养亲日思想。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be238d4fff1e4b0999a609faa2e401f9','f60008c6-1e5f-425c-b5db-f7f6a712c929',1932,'任伪海伦县商务会长','任伪海伦县商务会长，协助日军统制经济，强制征购粮谷，压榨商民，为日伪筹集物资。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46b2d15a5c0549fb8b7d2f4d7e4d7ac0','020baca4-8063-408b-b176-7f90ad4ebf6e',1932,'历任伪满洲国交通部次长、大臣','历任伪满洲国交通部次长、大臣，后任伪滨江省长，管辖区域包括今哈尔滨及绥化部分地区，推行日本殖民经济政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06de76963dcf4895b44a10bb1c347ffa','33cdc430-4e36-4c42-9336-218dbcf775a3',1932,'原东北军军官','原东北军军官，投敌后任伪军警备司令，在绥化、绥棱一带率部\'讨伐\'东北抗日联军，镇压当地抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c1dc39dc5ed149f4b196ca6ab7d99319','95d1fa91-1ece-4e4d-8a34-a7fadb012517',1930,'任伪绥棱县县长期间','任伪绥棱县县长期间，推行保甲制度，配合日伪征粮、征兵，镇压当地抗日群众，维持殖民统治秩序。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a94c0ea4ce3c43c79ec082291d15f421','d41232e5-8351-4023-8a71-a80ad2ed6a8f',1932,'九一八事变后组织绥化维持会','九一八事变后组织绥化维持会，迎接日军进城，后任伪绥化县长，协助日伪推行殖民政策，搜捕抗日人员。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-522bbf16fad148b388237421d5edc5a4','4e9fda7f-b378-4be5-b43a-890b59d6602f',1930,'任伪绥化县警务局长期间','任伪绥化县警务局长期间，指挥伪警察配合日军\'讨伐\'抗日联军，在绥棱、庆城一带搜捕抗日地下工作者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-975003f5a7c444c3a5ce35b571aee532','a74c7701-19bb-4247-a1c2-18b2268910e2',1932,'历任伪海伦县长、绥化地区协和会会长','历任伪海伦县长、绥化地区协和会会长，积极推行\'王道乐土\'宣传，协助日伪征调劳工、粮食，支持殖民统治。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31954bba9dc8412b80a77a0bb9ecaab9','d47aad90-38f9-4e77-b20e-95504fc71f50',1932,'历任伪哈尔滨市长、滨江省长','历任伪哈尔滨市长、滨江省长，管辖范围包括绥化地区，推行日本殖民经济统制政策，压榨当地民众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f5e4a468427d4db2a3e1ad49f94909fd','69d3c1a7-d446-41e0-af11-a9735b6578eb',1932,'长期在伪满教育系统任职','长期在伪满教育系统任职，推行奴化教育，在黑龙江地区包括绥化各校强制日语教学，篡改历史，毒害青年。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7426c4b8bb2d44768eafdf6aba0fbfb4','fbf22fa0-e7e4-47fd-9e78-9df3b8f405fe',1930,'任伪绥棱县协和会事务长','任伪绥棱县协和会事务长，配合日伪进行思想控制、物资统制，动员当地青年参加伪军，协助镇压抗日活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eaf6b1b80caa45e8aa6fea5fbcb004e6','254e9f0e-e4d9-4466-8ff4-502faad43516',1940,'原东北军文职官员','原东北军文职官员，投敌后任伪满黑龙江省省长，管辖绥化地区，积极推行“粮谷出荷”政策，导致绥化农民粮食被大量掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f566fdd1341447de97262c457b3c5a2a','9a6d7499-c5ff-4a05-9d41-ddd56e071d55',1932,'原绥化地方士绅','原绥化地方士绅，日军占领绥化后出任伪县长，协助日军建立伪政权，组织“自卫团”对抗联进行清剿，强征民夫修筑公路和碉堡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-607cb8df34114f7d8909511754f395a4','1e252528-02c5-49d7-94a9-f554c194886d',1933,'原肇东县商会会长','原肇东县商会会长，投敌后任伪县长，积极为日军筹集军粮，镇压当地抗日武装，曾参与抓捕多名抗联地下交通员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe7d6997270f4b47b5e15eb2dc64c961','41d39050-8778-4cfa-9696-a83bec3a84d2',1932,'原吉林省政府委员','原吉林省政府委员，九一八后投敌，曾率伪军参与对黑龙江地区的军事行动，其部队在绥化、肇东一带烧杀抢掠，对抗联进行残酷镇压。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a5205c4901a4aa29a53cf49499209f2','41d39050-8778-4cfa-9696-a83bec3a84d2',1932,'原吉林军将领','原吉林军将领，投日后参与伪满统治，间接涉及黑龙江地区殖民管理。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e47f0c5c42545e5baf0dad3c093127c','923b2f00-837e-42db-9579-534ccf3a7133',1933,'原东北军旅长','原东北军旅长，投敌后任伪满吉林军区司令，曾率伪军进入黑龙江绥化地区围剿抗联第三路军，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-26f8b060a68b4d069828dbba89e6b78b','ddd4281b-3265-4d9e-a744-5fa1c9cf706b',1934,'原哈尔滨警察厅长','原哈尔滨警察厅长，投敌后任伪满滨江省警务厅长，直接指挥肇东、呼兰等地伪警察对抗联进行搜捕，曾下令处决多名抗日嫌疑犯。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0a21011742824931b9172dee06429810','e5f8bb5a-9f9f-41dc-82e3-c6cf3268e6c2',1935,'原绥化土匪头目','原绥化土匪头目，被日军收编后任伪保安队长，带领伪军多次袭击抗联小分队，杀害抗日群众，在绥化、海伦一带民愤极大。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d97531e013142bb886950bf192091ae','bd3d3c70-908c-4551-b60f-01595270bf51',1936,'原肇东地方恶霸','原肇东地方恶霸，投靠日军后任伪警察署长，积极抓捕抗联情报人员，曾参与“三肇惨案”中对抗日群众的屠杀。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-23e095075a964cabaec77482338abd87','1a845417-0bac-41dc-b348-fd9625041d8a',1937,'原绥化富商','原绥化富商，投敌后任伪协和会会长，协助日军进行奴化宣传，组织“勤劳奉仕队”为日军服劳役，强征青年充当伪军。','危害等级C（丙级，基层头目）','hanjian');
