INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e47e2bb7296b4661b775b499a0842484','2ec660e3-b65d-4eb5-904b-628023577513',1931,'九一八事变后投靠日军','九一八事变后投靠日军，任伪满热河省省长，协助日军镇压抗日武装，推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9cf3d1fa787e40fda0a8c5f70aab3c8e','61b1904d-d67c-4cc7-b590-0fdd73ee2bd5',1932,'任伪青冈县县长期间','任伪青冈县县长期间，强征民夫修建警备道路，配合日军“讨伐”抗日游击队，搜刮民财。','危害等级C（丙级，基层头目）','hanjian');
