INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7ac48b75f1084c72a5d2f36683e483a7','4c3d2c0a-da3a-4923-858c-6ca790de2921',1937,'为日军宪兵队充当翻译','为日军宪兵队充当翻译，参与刑讯逼供抗日志士，直接导致多名地下党员牺牲。','危害等级C（丙级，基层头目）','hanjian');
