INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ac5ca88165f84dd989a4e4634d508a63','56e9e2ea-9b2b-4832-a717-f97b6edeb971',1933,'在鸡西地区推行日伪“治安肃正”','在鸡西地区推行日伪“治安肃正”，组织伪警察队围剿抗联小分队，强征农民出劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-40a90be7bd2d44ada7ed9e3b1bfe0157','cd7ccc0d-dae2-4529-aaee-c89c35a777aa',1931,'参与策划伪满建国','参与策划伪满建国，在吉林及黑龙江东部地区协助日军建立伪政权，镇压抗日力量。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a82c8733a0c649029e0d2a5b43990e82','b93d63ea-89da-43e5-abb3-efd5ab3cf937',1935,'在滨江省任职期间','在滨江省任职期间，配合日军修建铁路、公路以利“讨伐”，在鸡西地区强征民夫。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-073e405e5f9146c99088e2cf0db95125','6b63b43c-db15-4c02-a96d-e01879b476a3',1939,'在鸡西、城子河地区指挥伪警察和特务','在鸡西、城子河地区指挥伪警察和特务，破坏抗联地下组织，逮捕杀害多名地下党员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d9c593662f6c406b87290828df32f645','7e5ca577-2f0e-4a10-95ea-ae0ba16a0024',1940,'在城子河一带设立检查站','在城子河一带设立检查站，盘查抗日人员，参与“归屯并户”，制造无人区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c43cde526eb4987b83d2ea34cd4d55f','9cd25729-2367-4d83-aa52-9378b8fc32c2',1932,'在黑龙江推行“粮谷出荷”政策','在黑龙江推行“粮谷出荷”政策，强征粮食，导致民众饥荒，间接支援日军侵华。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9c96d700ae2444d99a7527a19e49b329','6433a659-3398-408a-ba86-ceb141fe87bf',1932,'任伪密山县县长期间','任伪密山县县长期间，积极推行日伪殖民政策，协助日军镇压抗日武装，强征劳工，搜刮民财，为日本侵略者提供物资和情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b1163ff190c14e0ca159097e0dd61694','8f1626e3-eede-455d-801c-cb25b3ac7572',1933,'指挥伪警察配合日军“讨伐”抗日联军','指挥伪警察配合日军“讨伐”抗日联军，抓捕抗日志士，实施“归屯并户”，制造无人区，残害百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e3e3e5c8705419bb73ea3cd1f4c7064','7a947eee-918b-4c0c-a62b-734a63d31470',1934,'率伪保安队多次袭击抗联密营','率伪保安队多次袭击抗联密营，杀害抗联伤员和群众，参与“三光”政策，烧毁村屯，抢夺粮食。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04b1714fbcfe497f8824b100e6274f64','19687611-8d2b-4e73-b63c-52b3236384a5',1935,'在鸡西地区强制推行“粮谷出荷”','在鸡西地区强制推行“粮谷出荷”，强征农民粮食，组织劳工为日军开采煤炭，镇压反满抗日活动，迫害矿工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b2fc0febc8b84acb8a14605b7a92f921','6d59d863-0b32-49de-9416-db644a3bc18d',1936,'管理鸡西煤矿期间','管理鸡西煤矿期间，残酷压榨中国矿工，实行“人肉开采”，导致大量矿工死亡，并配合日军将矿工充当细菌实验对象。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3528b99d0cdf434c818879afa2a3cb96','6908aa34-d758-4f87-b8e3-2fff7b43c89a',1937,'组织“协和会”宣传奴化思想','组织“协和会”宣传奴化思想，搜集抗日情报，告密抗联活动，协助日军逮捕地下党员和爱国群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5db9a2bf1c7e424e80043a3f3136bfdc','7a601b4a-ab15-4a74-9c38-e4f247f76ca1',1938,'率自卫团配合日军封锁山区','率自卫团配合日军封锁山区，破坏抗联交通线，参与屠杀抗联战士及无辜村民，抢夺财物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45d38b5befa5402d982feb0a77e2dd20','c51c980a-715f-49f9-8ffc-5a6c40e00b09',1939,'审理抗日案件时严刑逼供','审理抗日案件时严刑逼供，判处多名抗联人员死刑，并协助日军建立“矫正院”，关押迫害爱国人士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f9125cbde9b49b19d0727107559d91c','212ef6e3-4993-4eb3-a177-de64d7e316ee',1940,'指挥特务警察破坏抗联地下联络站','指挥特务警察破坏抗联地下联络站，逮捕多名交通员，实施“大检举”，导致数十名抗日群众被杀害。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f81c93fbf0324212a1521cb471f3a841','5bbf5b21-d557-498a-85a6-6c2f570559d8',1941,'强制推行“出荷粮”制度','强制推行“出荷粮”制度，搜刮农民粮食供应日军，致使当地发生严重饥荒，饿死百姓无数。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cae335be755448088ba4d6f7fa406746','0cab01cf-4872-4975-8cde-f8b37537e793',1931,'原东北军军官','原东北军军官，投敌后任伪满军职，活动于牡丹江、鸡西一带，参与围剿东北抗日联军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d53e518b71204285bb23052dc6a04198','c6c22078-b7cd-41ea-90a3-2c3551cf47ad',1931,'投敌后任伪满军东安省警备司令','投敌后任伪满军东安省警备司令，东安省辖今鸡西、密山、虎林等地，参与对东北抗日联军的围剿。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ced26bb68e4c4ca4abec8bddca65b80f','ef69f5d0-46c4-4cb0-a0ed-a29f94442439',1931,'日本籍伪满官员','日本籍伪满官员，任伪东安省次长，实际掌控东安省（含今鸡西地区）行政，推行殖民统治与治安肃正。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-06be7b1c5da44a0898d71e919990110c','ae40667d-7371-4d87-884d-cf957c5ec907',1931,'日本籍伪满警务官员','日本籍伪满警务官员，任伪东安省警务厅长，指挥伪警察配合日军围剿鸡西、密山一带抗日武装。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8ae0bf133cd24b82b137402150ad9307','b626e5ba-05aa-4cc4-8108-bb92061a0869',1931,'鸡西地区伪政权头目','鸡西地区伪政权头目，任伪鸡宁县维持会会长及县长，协助日军征粮、抓劳工，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d943d5c14e24d60885581f76f9cbb00','9f403de7-7e26-4647-b756-80ca3853025b',1931,'伪鸡宁县警务局长','伪鸡宁县警务局长，指挥伪警察在鸡西恒山、滴道一带搜捕抗日人员，推行保甲连坐。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-219e6a8eda7a40978b6ad62eb5bb0ac3','2e91cbf6-f974-4c61-baa6-68653cbb59eb',1931,'鸡西恒山地区伪保长','鸡西恒山地区伪保长，协助日军管理煤矿劳工，监视居民，举报抗日嫌疑人员。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5ec1842cc5145bb9920ddb4504af07a','03a5a109-9a18-473f-969e-7883129a4bf6',1931,'鸡西滴道煤矿把头','鸡西滴道煤矿把头，为日军强制征集劳工，虐待矿工，配合伪警察镇压矿工反抗。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6795c998cd014265becdc538db3e9232','da971060-2fb6-4a75-9aab-2b14c28d39fc',1931,'伪协和会鸡宁分会会长','伪协和会鸡宁分会会长，在鸡西地区推行奴化教育，宣传“日满亲善”，协助日军进行思想控制。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4845e4c369054997948894bdb14b4ee0','f76e7a1e-8d85-43d7-9d70-bffb2975c7e0',1931,'伪密山县县长','伪密山县县长，密山与鸡西相邻，其伪政权配合日军对鸡西、密山一带抗日联军进行经济封锁与围剿。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bdd7e827ede4c288605cc450e2b537d','0318510c-9bdd-4b4e-b0ff-8e94847437ca',1931,'伪虎林县县长','伪虎林县县长，虎林属东安省，与鸡西地区同属伪东安省管辖，协助日军镇压抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-58dbd88ab48d455491ac5e7384511862','9627682d-6bfc-4fcb-9d28-d786e874b975',1931,'伪东安省民生厅长','伪东安省民生厅长，负责东安省（含鸡西）物资统制与劳工征集，支持日军侵略战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-79db7bbaa5944aa8b9357db60f6ffa57','2410465b-222e-40cb-ba8b-b7ec49299307',1931,'伪牡丹江省省长','伪牡丹江省省长，牡丹江省与东安省相邻，其伪政权配合日军对鸡西地区抗日联军进行围剿。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-128237a398864c2c8cfc8bd4d71d7349','654ab0af-3a0f-4922-8c57-857c2036418d',1931,'辽宁盖平人','辽宁盖平人，原东北军将领，九一八事变后投敌，任伪洮辽镇守使，率伪军进攻黑龙江抗日部队，后任伪热河省长等职。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e047365aec74e62a40e9913f4652c0a','15b6daa5-adcb-4088-960d-5991f387f41e',1931,'原东北军骑兵旅长','原东北军骑兵旅长，1931年江桥抗战后投敌，历任伪黑龙江省长、伪满军政部大臣等职，直接参与对黑龙江地区的伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b91bde9d59f74782a8369f4d16d2904a','ebdcf8ec-b0c3-4185-b58f-d101f4594b3b',1932,'原东北军将领','原东北军将领，1932年投敌，任伪黑龙江省长，协助日军镇压黑龙江抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c5d13db97cb4018b1387f1786f39fdb','ed0cfe8d-f211-4af8-a91d-51679a7eb27f',1932,'原东北军官员','原东北军官员，1932年投敌，任伪黑龙江省长，协助日军维持黑龙江地区统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1ed1265795344937b1a6ef162f4d9516','4788caba-362b-47cd-a8e4-e3f738fdd9ea',1931,'辽宁人','辽宁人，九一八事变后投敌，历任伪牡丹江省长、伪东安省长等职，东安省辖今鸡西地区，直接参与对鸡西一带的伪化统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1c92c29828c49e6bf8367818998de98','ea8251c5-59c5-4848-b84e-7f094237eef5',1939,'日本官员','日本官员，任伪东安省次长，实际控制东安省（辖今鸡西地区）行政，推行殖民统治与资源掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5f545969a93a4d96b2a8f05789167936','1ea603cb-ccbc-4cd3-8d5f-f0295e62a7d2',1939,'日本官员','日本官员，任伪东安省参与官，协助控制鸡西一带的伪政权与煤矿资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9dbf9dc170fd4fc7b2fb7b20610ce89c','4cc79ef3-c0f5-41b4-8837-c345c0725482',1930,'鸡西地区煤矿把头','鸡西地区煤矿把头，投靠日军，组织伪矿警镇压矿工，协助日军掠夺鸡西煤炭资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1a21d22669264591a34e309e38802ac6','32a0447a-5e43-4203-9584-7dcf5a95ced5',1932,'鸡西地区地方士绅','鸡西地区地方士绅，1932年日军侵占鸡西后组织维持会，任会长，协助日军维持地方秩序、征发物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9fdd7c419204411397c288d047442c09','ea2dbd1a-b885-4b2b-8b24-7138c9ae85b0',1933,'鸡西地区保甲长','鸡西地区保甲长，协助日伪推行保甲连坐制度，监视抗日活动，征派劳工。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccea64c38e43487a86ae9b15f4b7fb74','68d7fecb-d55b-41fb-b4dd-a3488c5d3ce4',1930,'梨树镇伪警察头目','梨树镇伪警察头目，协助日军镇压抗日群众，抓捕抗日人员，推行殖民统治。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7f85063631cc42d3bbd5b720f0c5b0ea','7be78046-e275-44fe-bf12-00c8d1b06281',1932,'梨树镇地方人物','梨树镇地方人物，1932年参与组织维持会，协助日军侵占梨树地区，征发民夫物资。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-64ce61e30f724e1aa06356ca620aac6e','094158b3-7dd1-4a8b-a537-e871502c99d5',1935,'鸡西煤矿劳务把头','鸡西煤矿劳务把头，协助日军强征劳工，虐待矿工，参与掠夺鸡西煤炭资源。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d0850687f7a14455a1704ee1235409c6','20b88e03-2a97-4aa3-930c-7300b26450c5',1936,'鸡西地区协和会头目','鸡西地区协和会头目，协助日伪进行思想控制、宣传奴化教育，监视民众。','危害等级C（丙级，基层头目）','hanjian');
