INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ccdb992cfcb0452abd46fa8eb580b585','5fd0ad95-711d-4805-a410-36fbb3676a42',1933,'鸡西商界人物','鸡西商界人物，投靠日伪，任伪商会会长，协助日军征购物资、控制经济。','危害等级C（丙级，基层头目）','hanjian');
