INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8403d5db0ce5461e9f1e02c3498eb378','d469df9b-cb89-4eda-94bd-ed5a26c775a4',1934,'鸡西地区伪警察头目','鸡西地区伪警察头目，协助日军镇压抗日武装，抓捕抗日人员，推行保甲制度。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6005ce2ad6c84ea59e50dc3eb5f9dcb1','d6d6a9c3-1b9c-4332-9158-eb2810c56295',1939,'伪东安省警察头目','伪东安省警察头目，辖今鸡西地区，协助日军镇压抗日力量，实施殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7386b353ac4941f39ba3e7666ebbd657','9c11b45c-1e5f-4b9f-a604-949cec27f72b',1939,'伪东安省官员','伪东安省官员，参与对鸡西地区的经济掠夺、劳工征发与殖民管理。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cef3586ef13148e2b913b25b4ac8f60d','0cd11e63-f585-4073-881f-62175eb023c3',1938,'鸡西地区经济附逆者','鸡西地区经济附逆者，任伪兴农合作社理事长，协助日军统制粮食、掠夺农产品。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-647f68bbf7e548fc89293159c232c2cb','31afad2d-062e-4da3-8887-ace2a2f24175',1935,'日本殖民者','日本殖民者，任鸡西炭矿株式会社社长，直接掠夺鸡西煤炭资源，奴役中国劳工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-89c51be87aaa4e0f81be88cd81fca634','ac556a25-e9be-482a-9506-72127c081ffa',1933,'鸡西地区伪军头目','鸡西地区伪军头目，率伪保安大队协助日军围剿抗日武装，镇压民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5757637dc6b54bf99c2de928ef3bf21e','4cebb7a9-ebe7-4188-8854-4528e95d47b1',1933,'任伪满滴道煤矿矿长期间','任伪满滴道煤矿矿长期间，残酷压榨中国矿工，推行‘人肉开采’政策，导致大量矿工死于事故和疾病，并协助日军抓捕抗日分子。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fdcd6d5e6d2d46a88ccea86a5e9dcda8','3b59edc6-8c93-4d3e-98cc-46696ff2a0c2',1935,'效忠日本关东军','效忠日本关东军，在滴道地区大肆搜捕抗日联军地下工作者，多次带队‘讨伐’抗联小分队，杀害无辜百姓，并强征劳工送往煤矿。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb2df342178b43e1bc97d7292e4e65bf','0c4f4c70-b154-48c3-908c-77f07e176f74',1937,'协助日军维持‘治安’','协助日军维持‘治安’，参与镇压1938年滴道矿工暴动，事后按日军命令处决数十名矿工，并充当日军耳目，破坏抗联地下联络站。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-233c209653d442399e939605c3b4b54c','e7dc62de-a7d0-4ca9-9f33-a6f2f56e1430',1938,'在鸡西地区积极推行奴化教育','在鸡西地区积极推行奴化教育，组织‘协和会’宣传‘日满亲善’，为日军募集物资，并告发多名抗日群众，导致其被逮捕杀害。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3727ff4b3bcb47449009b049eff3668e','fdc83b48-4d31-4d8c-a316-fee1ebccf10f',1939,'负责管理矿工‘劳务’','负责管理矿工‘劳务’，制定严苛的惩罚制度，克扣矿工口粮，将病弱矿工直接抛弃于‘万人坑’，并配合日军进行‘思想矫正’。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e426ce232f9c43c09046afc8a6896ad4','adb317ed-b3c4-43ed-bae9-82f71b457ba9',1940,'协助日伪推行‘保甲连坐’制度','协助日伪推行‘保甲连坐’制度，强征农民土地供日军修建军事设施，多次向日军提供抗联活动情报，致使抗联小分队遭伏击。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2088cc91a6bb45d2949d7f88096af652','5d1f3aec-4ff4-4050-b251-1baa51b13975',1936,'充当日军宪兵队翻译','充当日军宪兵队翻译，参与审讯和刑讯抗日志士，多次歪曲供词制造冤案，并直接参与抓捕滴道地区的地下党员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05583bc68af54881b72d02b40f884c77','e14cf077-0b59-4d18-8e7f-5426a773d8c9',1932,'作为煤矿大把头','作为煤矿大把头，以暴力手段逼迫矿工超时劳动，私吞矿工工资，并经常向日军举报‘思想不良’矿工，导致多人被处决。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-233fea350acc4ff0b144d324210683c4','5460bb21-8ea8-4fa2-8b8e-f395dff457e7',1939,'组织地方自卫团协助日军扫荡','组织地方自卫团协助日军扫荡，在滴道周边村庄烧杀抢掠，曾一次抓捕12名疑似抗联联络员的农民，全部移交日军处死。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b48bd6462fe240539c109e7dc9514015','eb7a7f89-63d6-42a8-a91f-352970ad88dd',1934,'长期在鸡西、滴道一带指挥伪警察‘讨伐’抗日武装','长期在鸡西、滴道一带指挥伪警察‘讨伐’抗日武装，破坏抗联密营，并参与‘归屯并户’行动，制造无人区，致使大量平民冻饿而死。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d745c84695a841b29fca747e7c5ada5b','cd479b03-f3c8-424d-9a7a-6159a95b4bc0',1934,'任伪虎林县县长期间','任伪虎林县县长期间，积极推行日伪殖民政策，强征劳工修建军事工程，镇压抗日民众，为日军提供粮食物资支持。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c43656d1e8d946e688eb718f1788cb07','820fcf38-f950-436e-bae2-7c28050dff3d',1935,'协助日军搜捕抗日联军地下联络员','协助日军搜捕抗日联军地下联络员，多次带队围剿抗联小分队，残害无辜百姓，参与“归屯并户”行动，制造无人区。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cb58896af3748959956d8c496eb9a94','ec1d89b1-499e-4460-946b-22ad4cf6a923',1935,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，签署多项出卖东北主权协定，支持日军对虎林、密山等边境地区的军事统治和资源掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81347d02706741c2acd3ad511b3eab53','7350a521-1a0f-4ffb-bc1f-65194bec8cc7',1937,'率伪军配合日军“讨伐”抗联第七军、第十一军','率伪军配合日军“讨伐”抗联第七军、第十一军，在虎林、饶河一带多次发动围剿，杀害抗联战士及群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8dcef68558764763b6d122a6ec270c30','d7dd2c30-5064-4c57-9f3d-aa4e867ed488',1938,'组织“协和会”宣传奴化思想','组织“协和会”宣传奴化思想，强迫居民参加“日满亲善”活动，告密抗日分子，协助日军建立保甲制度。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9486a184ace34761afe525481b0d50d7','4750ae31-64dd-4bee-9c3d-9611ff637bd1',1939,'带领保安队为日军运输军火','带领保安队为日军运输军火，参与抓捕抗联后勤人员，在虎林山区设卡盘查，导致多名抗联交通员被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a9bb90f182074ba2a46d2095b7640882','b049fddf-f1ef-401e-996a-88beba7a0898',1940,'审判并判处多名抗日志士死刑或重刑','审判并判处多名抗日志士死刑或重刑，伪造“反满抗日”罪名，协助日军实施“思想矫正法”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b7e3f75a33874ecab94e611317aa1a7b','251319fa-7571-4f71-aa97-6569bcdc28ea',1936,'推行日语教育','推行日语教育，篡改历史教材，强迫学生参拜神社，灌输“日满一德一心”思想，压制爱国师生。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1cafecc11c194723b776462772bff93f','8ab2e7dc-43e7-4661-89be-079bdfb43c10',1941,'建立特务情报网','建立特务情报网，收买汉奸告密，破获多起抗联地下联络站，导致数十名地下党员被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-10df3f16877845b6957a3551bba27535','4c5e08af-5f2e-412a-a0b8-4f24b45c7e49',1942,'为日军强征中国劳工修筑虎头要塞','为日军强征中国劳工修筑虎头要塞，虐待劳工致大量死亡，克扣劳工口粮，隐瞒劳工死亡人数。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86b22f5fa3014fa6b6f6d45d362a49e6','f21308d3-d266-402b-999e-55e02367c948',1931,'九一八事变后投敌','九一八事变后投敌，任伪职，协助日军镇压抗日武装，在黑龙江及周边地区推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a6b13b02a1a249fe9d14b44e11760f03','3a9dff5d-3eac-477e-9da1-f0af0692bc10',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投敌后任伪省长，协助日军掠夺黑龙江资源，参与“治安肃正”行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bcbf4e08ba564adb9f2c90bd2b83ee02','2fe01607-e8b8-47e5-b830-06c76310f585',1937,'在牡丹江省（含今鸡西、鸡东）推行日伪统治','在牡丹江省（含今鸡西、鸡东）推行日伪统治，组织伪警察和保甲制度，镇压抗日联军。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e74b108e6234d7e82275acc4fc136a0','db6d022d-ab3f-4169-a9c7-58eb5531c364',1939,'在东安省（今鸡西、密山等地）强化殖民统治','在东安省（今鸡西、密山等地）强化殖民统治，配合日军“归屯并户”，迫害抗日群众。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d3423503ace488f93cf8640435c8aef','ce432c5a-7875-490a-b180-f078990326e1',1933,'在鸡东地区充当汉奸县长','在鸡东地区充当汉奸县长，强征劳工，为日军修建军事设施，镇压当地抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8dbe383c2fde49be8daa87455fc005ba','559e2ef0-d32d-4f46-9972-b858d6753e22',1935,'指挥伪警察抓捕抗日联军地下人员','指挥伪警察抓捕抗日联军地下人员，参与“大检举”行动，残害爱国志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0649e03eee6e467abf74e959530bb7e3','1c8c2427-fef0-4b64-9e30-11f84652c3e8',1935,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，全面配合日本统治，其政策覆盖黑龙江包括鸡西、鸡东地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8fab655d554a474aa17deda698d2cc4d','7273e825-6666-47a7-9cce-e564272ccf5a',1932,'原东北军军官','原东北军军官，投敌后任伪军将领，率部在牡丹江、鸡西地区围剿抗日联军，镇压当地抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a83be5ade52042959b3d58e606bb6b08','f090e98d-5caa-4a6b-96ac-a883534388cd',1932,'原抗日武装人员','原抗日武装人员，后叛变投敌，任伪军将领，在黑龙江东部三江地区配合日军围剿抗日联军。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf853810954d4d81bfc11beaf8e46dec','89c6cf6e-3234-4901-b0bc-5c284db8b49d',1939,'原东北抗日联军第八军军长','原东北抗日联军第八军军长，1939年叛变投敌，任伪职，在勃利、鸡西一带协助日军镇压抗日力量。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dfa59c3d5e7b42a4904968e50e6c6a49','8a61d506-e99d-4635-9884-a38e8bca6c89',1933,'投敌后任伪军将领','投敌后任伪军将领，在东安省（今鸡西、密山一带）配合日军围剿抗日联军，镇压当地民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-083ebc7b4b3a497fb2343d71eda874b4','2e6c04cc-4f2a-49cc-a34b-11a8f77eef89',1932,'鸡西地区投敌分子','鸡西地区投敌分子，组织维持会迎接日军占领，协助日军征粮、派夫，镇压当地抗日活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df669309b42a471cb9cd0d6e39e9faa1','0903f8f7-7cae-43b6-8458-935d2bd76900',1934,'伪鸡宁县（今鸡西）县长','伪鸡宁县（今鸡西）县长，执行日伪统治政策，推行保甲连坐，征劳工、征粮，配合日军围剿抗日武装。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-575652f94ce04da8a1bfaae001639813','2eb06202-62fa-4622-8948-8a4ce6674b0a',1936,'在鸡西煤矿为日军管理劳工','在鸡西煤矿为日军管理劳工，残酷压榨矿工，协助日军镇压矿工反抗，是经济领域附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e11dc192324d4f3b853e1fe77ac8ed79','75cb914e-ac35-4c3f-99fa-5e832c112ba1',1935,'鸡冠山地区保长','鸡冠山地区保长，执行日伪保甲制度，监视民众，举报抗日人员，协助日军维持地方统治。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f62ab5e31de3467683ef77cb4afb0c84','51e93950-600f-4c15-ae01-bd7bc0c5697b',1937,'伪鸡西县警察头目','伪鸡西县警察头目，率伪警察配合日军搜捕抗日人员，镇压当地抗日活动，残害民众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf2d441eb2224ae8802dd49495e0cd39','90dbfa33-c541-45b1-b01a-37fd4020d8a2',1939,'在东安省（含鸡西地区）推行奴化教育','在东安省（含鸡西地区）推行奴化教育，篡改历史，强制教授日语，为日伪统治培养顺民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-613b198f778b451d8d1295fcd2058160','7a2dc57e-ba43-4a46-9585-105eb3eaa722',1938,'在鸡西地区组织协和会','在鸡西地区组织协和会，进行反动宣传，协助日军征劳工、征粮，监视民众思想。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0c4d55327b0e478586ee8148069be95b','d3126b06-8b8b-44b8-bbd0-1eabe7b544f4',1933,'任伪鸡宁县（今鸡西地区）县长期间','任伪鸡宁县（今鸡西地区）县长期间，积极推行日伪殖民政策，协助日军镇压抗日武装，强征劳工，掠夺当地煤炭资源。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f39b7c07bce45039a6af5d730c8bf8f','bf49407b-154d-4582-a220-361c8c925650',1938,'在麻山地区担任伪警察署长','在麻山地区担任伪警察署长，多次参与围剿抗日游击队，抓捕并杀害抗日志士，为日军提供情报，欺压百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d21ac99ca944413c81189e231037746c','3aa97704-59c1-4515-aa86-906a745f009c',1940,'作为日伪基层保甲长','作为日伪基层保甲长，强征民夫修筑军事工事，搜刮百姓粮食，告发抗日群众，导致多人被捕牺牲。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e78238c2b1e74ecea2608cd38d0ad5e1','2e2c1415-0208-46bd-8099-c10c5129a1bb',1941,'在麻山地区组织维持会','在麻山地区组织维持会，为日军筹集粮饷，协助日军“清乡”，迫害抗日家属，破坏抗日组织。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-63ec5053fa23423889149736b566377a','21637236-8add-4f3c-8b58-a85147ba555f',1942,'担任日军宪兵队翻译','担任日军宪兵队翻译，参与审讯和酷刑迫害抗日志士，提供情报导致地下党组织被破坏。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-76a14b15dc734a55922771171dda57cc','cddd0aeb-a515-4127-bc5f-3d2069aaaff2',1932,'原哈尔滨特区行政长官','原哈尔滨特区行政长官，投日后任伪职，在黑龙江地区推行奴化教育和经济统制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-108b3ea6f670421eac21b1a43b59e315','7aa2e31f-e380-4dcc-887e-91296313a627',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，投敌后任伪省长，协助日军征粮、抓劳工，用于鹤岗煤矿开采。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f9909ff9662e4e1cbf9e6c473da2e527','c20b38ab-9c06-4428-bdb6-8831efd3a44c',1934,'原依兰镇守使','原依兰镇守使，投日后任伪三江省省长，管辖鹤岗矿区，协助日军强征矿工，迫害劳工。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-dc5cbc77e47c40c1bc4b9a7226c58445','776f03ba-5d71-445a-b3b6-8c68707630c2',1935,'在伪三江省任职期间','在伪三江省任职期间，直接参与对鹤岗地区抗联部队的围剿，并管理煤矿劳工。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-32989a8aeb3e435a87be208c034903a9','e4a44fec-c08c-4e79-abb9-5ad29ec64c0e',1937,'指挥伪警察在鹤岗地区搜捕抗日分子','指挥伪警察在鹤岗地区搜捕抗日分子，破坏地下组织，实施白色恐怖。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe478b9e4a434daabbfb4655baf692b0','c15e3345-4b1f-4452-b9a0-837eea9a5562',1933,'负责鹤岗煤矿的掠夺性开采','负责鹤岗煤矿的掠夺性开采，强迫中国劳工劳动，造成大量矿工死亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f1643beae06347f6b2e194a12b66427b','d4e8b9e5-4fa3-4ad9-83ce-f27d40781cdc',1938,'实际控制鹤岗煤矿生产','实际控制鹤岗煤矿生产，推行“以人换煤”政策，虐待矿工。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ed8d2a369eb43f388ab7009b2063767','43e015c5-8efb-4e20-9d55-317b26ef895c',1939,'在鹤岗县推行伪满法令','在鹤岗县推行伪满法令，组织“协和会”，协助日军征粮抓丁。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fe054d9346f4e2bb6f31cac432d795f','6c49160a-c5b9-4d39-9bea-46b16e368219',1932,'原吉林军将领','原吉林军将领，投日后任伪满第四军管区司令，驻防哈尔滨及黑龙江地区，多次率伪军“讨伐”抗日联军，后任伪滨江省省长。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62fdf5b98cb8498fb16a89b267d3259c','bbddc88d-ce0e-412b-b179-09bec16ff46d',1932,'原哈尔滨特别市市长','原哈尔滨特别市市长，投日后任伪滨江省省长，管辖鹤岗、东山等地区，积极推行“治安肃正”，捕杀抗日人员。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-569b4d43034c4b9d99dd6a1e316abe32','dd59d3dd-efd9-4d43-b254-be42d15f7aed',1932,'原黑龙江省警察头目','原黑龙江省警察头目，投日后任伪省警务厅长，在鹤岗、东山地区建立伪警察网络，多次参与“讨伐”抗日联军，逮捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9004b6819c3f4f76aa1f90974b4a5cdb','dd59d3dd-efd9-4d43-b254-be42d15f7aed',1932,'原黑龙江省警察机构官员','原黑龙江省警察机构官员，投日后任伪满省警务厅厅长，在齐齐哈尔、拜泉等地组织特务网，抓捕抗日地下工作者，破坏抗日组织。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86a20a37c4514aaeb55c863329e3e1cd','ad853f96-5b07-4fad-96d1-7595537554b2',1934,'原鹤岗煤矿中方管理人员','原鹤岗煤矿中方管理人员，投日后任伪满鹤岗煤矿公司监事，协助日军强化对鹤岗煤矿的掠夺，压迫矿工，破坏抗日地下活动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6060c9d59af84998967f0b64ec1a1ceb','718ced81-fdb0-4b26-81be-12640871b8d7',1935,'投日后任伪鹤岗县县长','投日后任伪鹤岗县县长，在鹤岗、东山地区推行保甲制度，组织伪自卫团，配合日军“清乡”，多次围剿抗日游击队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c686d5028a374c35a420d32a2f06e5a2','a305562a-21ca-4325-9d62-df14d771fc64',1931,'原东北军将领','原东北军将领，九一八后投敌，曾任伪黑龙江省省长，后升任伪满国务总理，虽主要活动于新京，但其早期在黑龙江（含鹤岗、东山地区）的伪政权建设中起核心作用。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-021a48ef58c14f50901f0dff5a63544c','6a73e895-ea4a-4280-b8fd-12ca003ed378',1932,'1932年2月一度投降日军','1932年2月一度投降日军，任伪黑龙江省省长，但同年4月反正，重新抗日。因短暂投敌，部分史料将其列入汉奸名录，但最终反正，故仅作备注。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6bd98f40d2f84fbc9719946aca5e6922','fc665549-c647-4522-9642-95317c62935f',1932,'原东北军将领','原东北军将领，1932年投敌，任伪黑龙江省长，协助日军镇压抗日武装，推行殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6ea75e1933f44783b6d5d4a468376244','e23d3aa6-e612-487d-b651-32e5f62504cd',1932,'原东北军旅长','原东北军旅长，叛变后率伪军多次围剿东北抗联，在鹤岗、兴山（今鹤岗）一带制造惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b39f3816cc4f413a9547a2d46dc28259','39f3bae7-3627-4567-8821-38a000b68bba',1932,'积极参与伪满政权建设','积极参与伪满政权建设，为日本殖民统治出谋划策，涉及黑龙江地区行政规划。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5460996c112d478f9931d487621f7f00','e4edc591-d34a-417c-91bb-97f848bb9cdb',1932,'原哈尔滨特别市市长','原哈尔滨特别市市长，投敌后任伪省长，镇压反满抗日活动，协助日本开拓团侵占土地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-74b96885f6cb4942af7f4874e4a529d5','7cc1d7e2-52a4-4b88-bbf0-40fd9a469342',1934,'在三江省推行“集团部落”政策','在三江省推行“集团部落”政策，制造无人区，围剿抗联，对鹤岗矿区实施军事管制。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-363c650fa7e04626905048d0be8c213a','26bed57c-f9d4-4685-99f0-d91b67101988',1932,'蒙古族投日分子','蒙古族投日分子，在兴安地区推行蒙满分离政策，组织伪兴安军协助日军镇压当地抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c9b07dc959854f2da8323cb770090359','dd2e819f-91a8-4512-bf91-523a7cbc24a7',1932,'蒙古王公出身','蒙古王公出身，组建伪兴安骑兵，在兴安岭、嫩江流域多次袭击抗联和抗日民众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-17674c55bbd94d869249448d1b8a9e7e','a6dab8a4-cc1d-4697-a827-3fc5448cf342',1932,'在兴安北省（今呼伦贝尔部分）为日军提供情报','在兴安北省（今呼伦贝尔部分）为日军提供情报，协助镇压当地少数民族抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3663419cedda4cb79792738eac55f45c','1e0b19e4-3707-43f3-993a-17fef58adb8c',1932,'初期投日任伪省长','初期投日任伪省长，后因不满日本控制，暗中支持抗日，1936年被日军以“通苏”罪名处决。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6be81705899149a49b7d18cce3dabb38','4a05ad95-f961-469c-901a-1f08d97af064',1932,'原东三省特别区长官','原东三省特别区长官，全面投日，作为伪满最高汉奸之一，对黑龙江、鹤岗、兴安地区殖民统治负有总责。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c03cfccc79da457eae9680acbdb6957c','863707e7-9940-4f6f-ae4b-1efd19706d40',1932,'原吉林军参谋长','原吉林军参谋长，策划吉林独立投日，参与伪满对黑龙江东部资源的掠夺。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d275718b17db406ea7b07a1dae2d1d6d','1f86023e-9a1a-4a68-8432-18ed7c379e06',1932,'一度投降日军任伪省长','一度投降日军任伪省长，但旋即反正抗日，故通常不列为最终汉奸，但历史记录中曾有此段。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0fc2064af3764757adb498e203f42cdb','2f1f523f-bbeb-42f8-96ec-a0ecb5164f3a',1933,'在黑龙江西部及兴安地区围剿抗联','在黑龙江西部及兴安地区围剿抗联，实施“三光”政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-be58045004d1412fb4a8623929484026','6671b51f-e7dd-4f61-9fe1-1102e5e9db19',1932,'组织伪警察特务','组织伪警察特务，在鹤岗矿区监视矿工，抓捕抗日地下人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22f96ace3c0e414fa154ce3df8f821c4','d3ba0a1d-a2b2-4b1a-a9c4-8231cb8b841a',1934,'在佳木斯、鹤岗地区建立特务网络','在佳木斯、鹤岗地区建立特务网络，破坏抗联地下联络站。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a84f272f0c3346849de067898f57f2f0','0d339d9b-dd56-4738-9c80-bf744182e8f0',1935,'协助日军在兴安地区推行“并村”政策','协助日军在兴安地区推行“并村”政策，强迫鄂伦春等族迁移。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3e0999ac9ec4858b0481e6899287a41','4ac9c2e2-201b-49ac-a79c-74c6132dc724',1934,'伪满时期长期在三江省任职','伪满时期长期在三江省任职，历任民生厅厅长、省长等职，三江省省会佳木斯，辖今鹤岗、兴山一带，其推行日伪殖民统治、征发劳工等政策直接涉及该地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-57369df939974c5db71fabf325f7904a','1850e92e-1348-4b4a-9b43-d7de0a283969',1930,'伪满时期任三江省警务厅厅长','伪满时期任三江省警务厅厅长，负责该省警务、治安，配合日军镇压抗日力量，其辖区包括鹤岗、兴山地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03cae405c9e8457cbc83cadfba0229a0','cb0f0ac1-a734-43cc-adf5-2750fa0fd62d',1930,'鹤岗煤矿地区汉奸把头','鹤岗煤矿地区汉奸把头，勾结日伪军警，残酷压榨矿工，迫害抗日人员，在兴山、鹤岗一带为日伪效力。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-67fb2f12a0774722b03bf47603ed7cf1','8224d010-57b5-4016-a210-90b5993cf1a1',1932,'原为抗日武装','原为抗日武装，后投降日军，任伪自卫团总团长、伪军团长，活动于松花江下游依兰、桦川、鹤岗一带，配合日军围剿抗日联军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce1d5fe873944ca185be78a980f6cd8a','931987d9-8e3d-4119-b9fd-6bde82448552',1939,'原为抗日联军将领','原为抗日联军将领，1939年投降日军，任伪自卫团总团长、伪军团长，活动于勃利、桦南、鹤岗一带，配合日军围剿抗联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-75b8a7de25d64b89934dec3415eccc04','86478787-aecb-4a6a-bc57-f2ba3e5d43ae',1930,'在鹤岗煤矿充当日伪劳务管理人员','在鹤岗煤矿充当日伪劳务管理人员，负责强征、管理矿工，迫害劳工，为日军掠夺煤炭资源服务。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e495db9f66a7420899e96602895580ff','1cb1f439-b1a0-4851-aa46-1553e309ddc9',1930,'兴山地区伪保甲长','兴山地区伪保甲长，协助日伪征发劳工、征收物资、监视居民，迫害抗日群众。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e0816fda162f4f1b98b66dc87fa41f32','7d533a39-9ecf-488c-964d-6a11b382ca8b',1932,'原东北军团长','原东北军团长，投日后任伪满第四军管区司令官，司令部设于佳木斯，管辖包括鹤岗、汤原等地区，多次率伪军“讨伐”抗日联军，在鹤岗南山一带制造多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d8bbad260abe4a17b2e53b5e5791dcd8','a4289d07-a0be-402e-b354-2812d88a253b',1938,'日本侵占鹤岗煤矿后','日本侵占鹤岗煤矿后，任伪警察署长，负责镇压矿工反抗，勾结日本宪兵队，在南山矿区抓捕并杀害抗日地下工作者及矿工，有“南山屠夫”之称。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a334f982dc71424e8e69e16b451d9464','6b859cca-615c-4c6b-b643-655e465eeb2d',1939,'原为地方土匪','原为地方土匪，投靠日军后任鹤岗保安队队长，协助日军在南山地区清乡，多次带队袭击抗联小分队，并参与“归屯并户”政策，烧毁民房，强征劳工。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7a3236562f049998a46cb8f64c4c1fb','6575b6c5-4aea-4afa-8125-057ded328be6',1940,'作为伪满基层行政头目','作为伪满基层行政头目，在鹤岗南山地区推行保甲制度，强制居民领取“良民证”，向日军提供抗联活动情报，并组织汉奸武装配合日军扫荡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-818d6ed5a9d649a4b9dfd928a1ed0c88','6bdb4555-12b6-48fc-896d-ef55a3cc1f82',1941,'为日本宪兵队担任翻译','为日本宪兵队担任翻译，参与审讯和刑讯抗日志士，在南山地区多次指认抗联联络员，导致多名地下党员被捕牺牲。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-459bf0706fbd40c8be607db5691d9270','1ea95d49-7f4b-4738-b906-f3d602611a14',1942,'负责为日军强征劳工','负责为日军强征劳工，在南山矿区实行“以人换煤”政策，克扣矿工口粮，虐待致死数百人，并告密矿工中的抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4c8719c241774dacab4248c9878c70c4','655394bd-1448-43a2-b840-377c6d705d72',1932,'1932年投靠日本','1932年投靠日本，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-98e9bd872f234ad2846b668fecfa498a','74a346de-d407-433e-8a2e-addf5c55511b',1933,'原东北军将领','原东北军将领，1933年叛变投日，在鹤岗、佳木斯一带围剿抗联部队，制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-878ea0ad8c8f40b78d8af828629d3878','e5128cc2-bed1-40d9-81f2-7d32f29abf12',1932,'参与伪满政权建立','参与伪满政权建立，曾协助日本在黑龙江地区推行奴化教育，镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-45020a83407845fda4377b6b65e7ffb2','72a10216-4f42-4adb-be82-5553a7897abf',1932,'在鹤岗地区协助日军掠夺煤炭资源','在鹤岗地区协助日军掠夺煤炭资源，强征劳工，迫害矿工。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4e44a8ce5aea4c04b87788f781cc2d12','47c0b10f-733e-4a4c-a859-a841aca8c81c',1932,'协助日伪推行“保甲制”','协助日伪推行“保甲制”，在鹤岗矿区建立特务网络，迫害抗日群众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-86d67cf4874c4d3798ecf13d1a168c23','4cf6c44a-de8e-4c8d-9362-9fcde71def23',1934,'在向阳地区组织协和会','在向阳地区组织协和会，宣传“日满亲善”，破坏抗日统一战线。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bd2eb1479c034e79b5b3fb888fb39f6a','33c64991-f5a1-486a-b9ed-fb4bdebf03ef',1933,'为日军开采鹤岗煤炭','为日军开采鹤岗煤炭，虐待矿工，提供资源支持侵华战争。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8f1ea533bba6484685593fb4bf080ea7','dbdc9bf3-0106-4f11-bb05-59236a0766cb',1935,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，其政策覆盖鹤岗、向阳地区，支持日军经济掠夺和军事镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-054e610563424e12ba58183749f12839','131df861-ab42-4b0e-88d9-8fa684f79c01',1932,'长期在伪三江省（辖今鹤岗、佳木斯、双鸭山等地）任职','长期在伪三江省（辖今鹤岗、佳木斯、双鸭山等地）任职，参与伪满地方警政与军事镇压，配合日军围剿东北抗日联军，是黑龙江东部地区重要附逆人物。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d59e203cd4b43f8a15c75e877d50abd','2cd5794e-47ff-42f5-95db-65f23b9de3d9',1932,'在鹤岗煤矿地区为日军掠夺煤炭资源','在鹤岗煤矿地区为日军掠夺煤炭资源，残酷压榨矿工，配合伪满经济统制政策，是鹤岗地区经济领域重要附逆者。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f14b83dde0714b75b3c55e2092fe74b6','c29307ff-6651-424d-a02e-b058bd2cb679',1932,'在鹤岗及周边地区组织维持会','在鹤岗及周边地区组织维持会，协助日军建立保甲制度，搜捕抗日人员，为伪满基层政权服务。','危害等级D（丁级，基层帮凶(维持会系统)）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c2347a7550304ab693c4da53de15a175','b7ea14b1-6fe1-4510-b60b-a54138c4b823',1936,'在伪三江省（含鹤岗地区）推行协和会殖民教化','在伪三江省（含鹤岗地区）推行协和会殖民教化，宣传“日满亲善”，协助日军进行思想控制与情报搜集。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9b5085c5ac3f493088ceff27ade7ab5a','8d9ce3d3-b131-413e-994a-968577a1477a',1932,'在黑龙江地区任伪满军职','在黑龙江地区任伪满军职，参与松花江、黑龙江流域的军事行动，配合日军封锁与围剿抗日联军，活动范围覆盖鹤岗周边水域。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7594d1bf94e348929ecff737b8a966fe','435a57f5-34a6-4c9a-b010-235948b25ffa',1931,'原东北军将领','原东北军将领，九一八后投敌，在黑龙江地区协助日军镇压抗日武装，后任伪满高官。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71ed7bcc32284f4d97a270c87e04d68d','13198c26-c905-4cf7-8a55-95e44e51c759',1932,'参与伪满政权建立','参与伪满政权建立，在哈尔滨等地推行殖民法律，协助镇压反满抗日活动。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-28b026590af840fb8c75d4b55f36bb53','bdd41d19-bbee-4398-b9ba-4b677cf55f35',1935,'在黑龙江推行经济统制','在黑龙江推行经济统制，掠夺资源，协助日军建立殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6c771d966ebe41618acd4708eeb0beeb','dfae40f9-67e1-4496-9602-4c58047c501c',1934,'在三江地区（含绥滨、鹤岗）残酷镇压抗联','在三江地区（含绥滨、鹤岗）残酷镇压抗联，推行归屯并户，制造无人区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8c3c12e3835849319c9c830133bb9656','08c0260b-82a2-4485-bec3-e654042624b6',1937,'在鹤岗、绥滨一带强化保甲制度','在鹤岗、绥滨一带强化保甲制度，抓捕抗日群众，配合日军“讨伐”行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fc44fd1100dc41b4828b9f4979d99495','c776adaf-bcbc-4e2a-abe2-cf3ef8261f2c',1941,'在绥滨、鹤岗地区强制劳工开采煤矿','在绥滨、鹤岗地区强制劳工开采煤矿，迫害矿工，镇压反满活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c5c4cc2b04a34c1f9951451820ceea85','c49878d5-d5cf-4259-ad25-d057dbcad3a3',1932,'管理鹤岗煤矿','管理鹤岗煤矿，奴役中国矿工，为日军提供战略煤炭，造成大量矿工死亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b501dd48ddd345158bcf96ff5936d5bc','a148b226-2227-4833-8d7a-7d5ff1eb0daa',1932,'1932年2月一度投降日军','1932年2月一度投降日军，任伪省长，但4月反正，故不列入正式汉奸名录，此处仅作历史备注。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-545fa8d424294c8885abd2a1ae0a5ba5','496aad4d-0dce-4c4a-ba61-007541335c40',1933,'在佳木斯、绥滨、鹤岗一带指挥伪军多次围剿抗联','在佳木斯、绥滨、鹤岗一带指挥伪军多次围剿抗联，杀害抗联战士及平民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0ac0428e896645b9abfb94cfc8faf6d3','446eb879-17d2-4807-b8aa-adb421bdeaf9',1935,'在绥滨、鹤岗地区建立警察网络','在绥滨、鹤岗地区建立警察网络，抓捕抗联地下组织，实施酷刑。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7e481c117c7f4599bb6da992d3ecddec','301ed914-93ed-4cda-b6fc-a38b9d508e0c',1933,'在鹤岗推行“治安肃正”','在鹤岗推行“治安肃正”，强征民夫修筑警备道路，协助日军清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7cf3a0ccf0ea4a3b897ed2846c9f40ad','dd141bcb-137a-45ce-88b1-906f1f99c3c8',1934,'在绥滨县组织“自卫团”','在绥滨县组织“自卫团”，配合日军扫荡，强征粮食，迫害抗联家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e68c47a722b4027b68f0711985aaae7','9ff6eb61-ee0a-4be6-b28a-8d67412d4165',1936,'在绥滨县多次带队袭击抗联小分队','在绥滨县多次带队袭击抗联小分队，逮捕并杀害抗日志士。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1f6d19a6a164b309d2acc827adb4e4f','647f2a7b-1f80-461d-8b3b-f6df7e98fe59',1938,'负责从华北等地骗招劳工至鹤岗煤矿','负责从华北等地骗招劳工至鹤岗煤矿，克扣口粮，致数千劳工死亡。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3f2bda4c52b4a5fa3b436380c2e5d5e','8d19c90b-6510-4dda-841d-45e0c5132616',1939,'在绥滨、萝北一带为日军充当向导','在绥滨、萝北一带为日军充当向导，参与“讨伐”抗联，烧毁村庄。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cde6b4bbc89843fc9c96b67f921ac7b1','f37a6fa2-4b7e-4102-850d-b60c74ccebb7',1937,'宣传“日满亲善”','宣传“日满亲善”，组织告密网，破坏抗日活动，协助日军抓捕反满分子。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1e68ab358527462b97e00dde9ff4459e','3fabf0b2-d79a-4a95-a9b3-6daba6d897e2',1934,'长期在伪三江省任职','长期在伪三江省任职，负责警务和治安，伪三江省辖境包括今鹤岗、萝北等地，其指挥伪警察配合日军围剿抗日联军，镇压当地民众抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d5b1b015b9743fb8ccf67ab10b61197','718c8b1f-26f4-43a4-a428-0f2857d330f1',1937,'曾任伪三江省省长','曾任伪三江省省长，管辖包括鹤岗、萝北在内的三江平原地区，推行日伪殖民统治政策，征发劳工、掠夺资源，配合日军对抗日联军进行经济封锁和军事围剿。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5e358e6dedfe496bbdca4d0cfd853451','7ccdd491-4c8e-4873-976b-7711809c3a33',1934,'伪萝北县公署县长','伪萝北县公署县长，直接负责萝北地区伪政权运作，推行保甲制度，征发劳工、粮食，配合日军和伪警察镇压当地抗日活动，是萝北地区主要附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-da23a59bff6c4b26a903fbd3de675271','a84cbcc7-fbb2-4134-8926-6086aef9d1e6',1935,'伪萝北县警务负责人','伪萝北县警务负责人，指挥伪警察在萝北及周边地区搜捕抗日人员，实施保甲连坐，迫害抗日群众，配合日军维持殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-29647cc2b3804ed9beec82babe471845','b8cb5e5c-afc9-428c-bf96-6b9556c8966a',1936,'在鹤岗煤矿负责劳工征发和管理','在鹤岗煤矿负责劳工征发和管理，配合日军强征中国劳工，实施残酷压榨，导致大量劳工死亡，是经济领域附逆者的典型。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2b19a9b9b7b34e319d7eab76a27108f0','1b9e6496-5af9-4397-a87d-1237c94f7c4b',1932,'九一八事变后组织鹤岗街维持会','九一八事变后组织鹤岗街维持会，迎接日军占领，协助日军筹粮、征夫，维持地方秩序，为伪政权建立铺路。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-000b1a825b004df0bf064f8df883126d','67de21ee-b902-4a9d-b122-65bff2521fa2',1936,'在伪三江省负责特务警察工作','在伪三江省负责特务警察工作，派遣密探渗透抗日联军，破坏中共地下组织，其活动范围覆盖鹤岗、萝北一带，是镇压抗日力量的重要附逆者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41286b5341ad4e4abc2ac428fc4b7733','57287e45-473c-4079-b890-9236240da54f',1934,'曾任伪满黑河省省长','曾任伪满黑河省省长，积极推行日伪殖民政策，镇压抗日力量，协助日军掠夺黑河地区资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0cea3489147d4e2897efd369c81869bf','7735ed65-6fe3-407c-b78f-0bce7db5e707',1935,'指挥伪警察和特务','指挥伪警察和特务，搜捕抗日联军及地下工作者，多次参与“讨伐”行动，残害百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-47e6ad5c096148e385c6de88674b0d9a','39185738-bc81-4244-b0a7-f2bd85a51673',1935,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，全面配合日本关东军统治，包括对黑河地区的殖民统治和资源掠夺。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ecc81140d96429b8fa5647ca8da011c','39185738-bc81-4244-b0a7-f2bd85a51673',1935,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，全面配合日军对黑河、孙吴等地的殖民统治和军事镇压。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc4db6e9e41945a280fe6963b0209a8b','ccff2efa-9ef2-47af-98cd-4ce1b5e0a08a',1936,'负责为日军征收苛捐杂税','负责为日军征收苛捐杂税，强征劳工，侵吞地方财政，支持日军军事建设。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d54755c0caf7452d90fb214515557c48','5a2fc990-ef55-4c16-a2e1-ec072115dad7',1937,'组织协和会宣传奴化思想','组织协和会宣传奴化思想，破坏抗日群众组织，协助日军进行“治安肃正”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ee4f2f2614754b3fa2564eeaba81a10f','b3d0c5ca-b10c-4df7-b81c-007925ee78e9',1938,'利用伪司法系统迫害抗日志士','利用伪司法系统迫害抗日志士，判处大量爱国人士死刑或长期监禁。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-71af35a99f6344628ab975a0b5f4cfb8','af1f8487-31e3-4836-b379-c3add94ba019',1939,'推行“粮谷出荷”政策','推行“粮谷出荷”政策，强征农民粮食，导致黑河地区饥荒，并强抓壮丁充当日军苦力。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1d7d9077152a4376b03c34430fad4aa6','5ee36999-4c92-4668-84b5-bfdd0b79c7dd',1940,'指挥伪军配合日军围剿东北抗联第三路军','指挥伪军配合日军围剿东北抗联第三路军，在逊克、孙吴等地多次发动“扫荡”。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c433a1cf34524689a1141d42708cc764','57fe556f-7738-4ffb-9952-1be09d129466',1941,'管理黑河市政务','管理黑河市政务，强制推行“保甲制度”，建立特务网络，镇压反满抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2619b1e897ab4a00b5282a76596d2b58','399468d0-73b4-4e1a-8f9f-68e0af3364c0',1933,'虽主要活动于热河','虽主要活动于热河，但曾率伪军赴黑河地区协助日军“讨伐”抗联，烧毁村屯。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e1eb9c5cd8954b03890ac98c21099d03','8e4c4851-f70b-46bb-8116-01fbfe573f8c',1932,'原哈尔滨律师','原哈尔滨律师，投日后任伪满哈尔滨特别市市长，后升任伪满立法院院长，在哈尔滨及黑河地区推行日伪统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95ae232fd409476293632c9df0b57689','f4b45abc-3b20-47d8-ac37-b80d72353430',1934,'原黑河地区官僚','原黑河地区官僚，投日后任伪满黑河省省长，管辖黑河、五大连池一带，配合日军镇压抗联和民众反抗。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f4bb1753d6d34f13bdeee2184ff10b57','02e3a2a0-89cc-4cec-8584-a606a672e287',1935,'原黑河警察头目','原黑河警察头目，投日后任伪满黑河省警务厅厅长，组织伪警察和特务，搜捕抗联地下工作者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95c1e4368db54eda90263bd5ba1fdfdd','76485f21-57fa-434f-a3bf-0517a64ffcf9',1937,'黑河地区地主豪绅','黑河地区地主豪绅，投日后任伪满黑河省协和会会长，协助日军进行奴化宣传和物资征集。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c3449be43e634d76a35383d53799faa6','7b180ffa-0911-4daa-9c1f-34d233754baa',1932,'原黑龙江省代主席','原黑龙江省代主席，1932年2月一度投日任伪满黑龙江省长，但同年4月反正抗日，故其投日行为仅属短暂，后成为抗日英雄。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bdcb406e33ac48e59b7e75734ded4f73','e3a3267f-5a01-4833-bcdc-cc16e9d6563c',1932,'曾任东北军将领','曾任东北军将领，后投敌叛国，出任伪满黑龙江省长，积极推行日伪殖民政策，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7fffae0f3734405b994869669d163bf3','e3a3267f-5a01-4833-bcdc-cc16e9d6563c',1932,'曾任东北军将领','曾任东北军将领，后投敌叛国，任伪黑龙江省省长，积极推行日伪殖民政策，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-82dbdfc7c3664078ae0c72817868454b','3faf1317-aa9d-483f-a720-450522195bae',1934,'在任期间协助日军建立黑河地区伪政权','在任期间协助日军建立黑河地区伪政权，强征劳工，掠夺资源，镇压抗联活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-46024d48a2c546d499d19e998e221e17','3faf1317-aa9d-483f-a720-450522195bae',1934,'原黑河地区官僚','原黑河地区官僚，投日后任伪黑河省省长，协助日军统治黑河、爱辉地区，强征劳工，掠夺资源。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-34839d9d4f4344fca252ee5ca54541de','8bee5efc-ccd4-432e-9008-898d9861f0d8',1932,'原奉系将领','原奉系将领，九一八后投敌，历任伪黑龙江省长、伪满国务总理，全面配合日本殖民统治。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
