INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d997f95f35854fed9063f0d778c8fde1','628cec71-dfb1-4ed4-8116-1de77cdac9a6',1933,'原爱辉地方士绅','原爱辉地方士绅，投日后任伪爱辉县县长，协助日军推行保甲制度，强征民夫修建军事设施。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-49a112f963d04ce8a56d54b427832cf2','61b868b0-3de3-40bc-b8c4-f06b32ace05f',1936,'积极组织协和会宣传亲日思想','积极组织协和会宣传亲日思想，在爱辉等地破坏抗日组织，搜集情报供日军使用。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0660d51198944f75a641472a6cf304cf','c7edd6f3-545e-4d00-995c-a28c93ab0a15',1937,'原黑河地方官僚','原黑河地方官僚，投日后任伪省参事，参与制定镇压抗联的“讨伐”计划，迫害当地百姓。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c11c2108842343b69daa0186707e3c80','66ff97bc-23f8-45aa-baf7-1571bc414479',1939,'虽为日本人','虽为日本人，但作为伪满官员在黑河省任职，直接指挥对爱辉地区抗联的军事行动。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a0b097e6ea1439190418e88ca54d799','0ef8ef65-b629-410c-a2a0-eaa667e95f83',1932,'原吉林自卫军将领','原吉林自卫军将领，叛变投日后任伪满第四军管区司令，驻防黑河、逊克一带，多次率伪军“讨伐”抗联部队。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ef680343698c4910b4cfa1216337c030','b3982ff9-4bdf-4ee1-8f03-0d18590c2006',1934,'曾任伪满黑河省省长','曾任伪满黑河省省长，推行日伪殖民政策，协助日军镇压逊克、孙吴等地抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-afc23043de0847a49e020363e8e0ded2','5fb487c9-15b1-4dbc-8b38-7d9af999aff7',1936,'原地方士绅','原地方士绅，投靠日伪后任协和会黑河省分会会长，鼓吹“日满亲善”，协助日军征集劳工修筑军事工事。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ab9987ecd9e74659b00ab8854d00329b','d5ee1f64-bbcc-49e1-b8eb-00e547235cc8',1933,'首任伪逊克县县长','首任伪逊克县县长，强征民夫修建警备道路，配合日军“归屯并户”，导致逊克沿江村屯大量民众流离失所。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ab97362cc9e4977b837d32a950b5180','8974194f-ac5e-47ff-9fc6-ac24478287be',1937,'直接指挥伪警察和特务队','直接指挥伪警察和特务队，多次袭击抗联小分队，抓捕并杀害抗日群众，在逊克宝山乡制造“血洗”事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1eddfc872a7c401291dc0a3e12a4fcc9','58b2f139-5be1-4550-8139-96d9b9edd34b',1938,'作为伪满黑河省次长','作为伪满黑河省次长，协助日本参事官控制地方行政，推行粮食统制，导致逊克等地农民饿殍遍野。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-85994c99586840fc85bd9c7fad636315','9f219ae2-fe95-4926-9709-1f8edf7940c1',1939,'率保安队配合日军“讨伐”抗联第三路军','率保安队配合日军“讨伐”抗联第三路军，在逊克县库尔滨河一带伏击抗联小部队，杀害多名伤员。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-22aa8c435ab1441999e781c31944b1a9','79611df0-ec37-4b47-9685-d747eb10d394',1932,'原黑龙江省议会议长','原黑龙江省议会议长，日军占领齐齐哈尔后出任伪省长，协助日军建立伪政权，镇压反日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c32e2952f814498986d923945e3d951','79611df0-ec37-4b47-9685-d747eb10d394',1932,'黑龙江齐齐哈尔人','黑龙江齐齐哈尔人，原黑龙江省议会议长，1932年日军占领齐齐哈尔后出任伪黑龙江省省长，协助日军建立伪政权，推行奴化政策，强征民夫物资。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cd5f195fd4dd45d4af6c2f4afb3efe7b','3b81c39a-8667-48c1-b369-03e313d996d6',1932,'原吉林军将领','原吉林军将领，投日后长期在黑龙江地区统率伪军，围剿抗联，制造多起屠杀事件。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-03e4feda14ea49cca8fb17092097810c','91f80122-4e70-4473-9d3c-a868c391f798',1932,'原马占山部旅长','原马占山部旅长，1932年叛变投日，在齐齐哈尔一带协助日军清剿抗日义勇军，后任伪军高级职务。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4078bb34cb4549a88b36823afe1a2fba','cebec3a9-49dd-4918-b588-d1fee4c3876f',1934,'长期任伪黑龙江省（省会齐齐哈尔）省长','长期任伪黑龙江省（省会齐齐哈尔）省长，推行日伪法令，强征劳工，配合日本经济掠夺。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7bcc7a223cc34d03a3d85d5d61bcbea4','c6e5e72d-f044-403c-bef1-8edb4be1d397',1932,'投日后出任齐齐哈尔伪市长','投日后出任齐齐哈尔伪市长，管理城市治安，协助日军建立宪兵统治，迫害爱国人士。','危害等级B（乙级，市县厅局级）','hanjian');
