INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b51ea30e72cf4ac69b95847ace9c21de','e503061c-ce16-4fa2-a734-648335b9bfdd',1933,'满清宗室后裔','满清宗室后裔，投日后统辖伪军警，多次参与对抗联的“讨伐”行动，烧毁村屯。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2fae9cc096014cfa80e3f5852d59f020','f95de530-acf5-4023-b0ea-f79675c177e5',1932,'蒙古族王公','蒙古族王公，投靠日本，在齐齐哈尔周边蒙古族地区推行伪满统治，协助日军镇压牧民抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-aa07cc5580724bc686edc1359fd1da6a','b109704d-d57d-476d-8df6-e1f40da43ab9',1932,'蒙古族贵族','蒙古族贵族，投日，参与组织伪蒙古军，在齐齐哈尔西部边境配合日军军事行动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
