INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-067f7722a5ac44cc9f91a50be8474492','065eee24-9229-4fac-ad9d-3ead24dbb2ce',1942,'伪满最后一任黑龙江省长','伪满最后一任黑龙江省长，继续为日军服务，直至日本投降。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-af702080881e4712bfa70c997d7bfaa8','d20bcafd-1927-4fc1-855b-070f19b165f7',1932,'1932年曾一度投降日军','1932年曾一度投降日军，任伪满黑龙江省长，但旋即反正抗日，故不列入正式汉奸名录。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a163ffc4400947cda1803d7e93d14ed7','0e1c6374-a83e-41a8-a29a-0d94d7f0c454',1932,'投日后任齐齐哈尔市长','投日后任齐齐哈尔市长，协助日军控制城市，镇压反满抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
