INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8e29d5f3563a499d9d576f49ff1168f4','d3728dcc-b841-4a02-a03e-0f119ce3f9fd',1938,'伪满齐齐哈尔市长','伪满齐齐哈尔市长，配合日军“粮谷出荷”，压榨百姓。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-de1a9e20faab4f3fae9fbdc587209a34','d2302c09-b3bc-44ea-a6fe-92ed94f1d818',1941,'伪满末期齐齐哈尔市长','伪满末期齐齐哈尔市长，维持殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-92ec4572542b406b9d8707b7b5cdf547','916e7cda-4ffc-42ed-8168-a84d26f9ca68',1932,'克东县在伪满时期设县长','克东县在伪满时期设县长，历任者均为日伪服务，具体人员包括：张书翰（1932-1935）、李春荣（1935-1938）、王佐才（1938-1941）、赵维藩（1941-1945）等，负责征收粮税、抓劳工、镇压抗联。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d42b0abd58674318889f06cd1e345b70','7a435b60-ad20-4257-a367-561c7b878abc',1932,'首任伪克东县长','首任伪克东县长，建立日伪基层政权，协助日军清乡。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-27b7bd70381347ca9f28dd82cbc8a096','c5d8af98-2ba1-4c63-8585-4d723f76a309',1935,'伪克东县长','伪克东县长，推行“保甲连坐”，迫害抗日家属。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bf9655e979e24e3b9c7a839e1c896d33','85448608-b4ed-4b8e-952c-f6975f4bedf5',1938,'伪克东县长','伪克东县长，强征粮食供应日军，镇压抗联活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ea293a0d0044cb9867e78656e071e67','e9c49f97-9c74-416e-a496-32d27df3c283',1941,'伪克东末任县长','伪克东末任县长，组织“勤劳奉仕”劳工队，为日军修工事。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c240616e08914a639f5e604b5e696b90','eb0ca498-79dc-467e-bcc5-0f260190222c',1932,'吉林怀德人','吉林怀德人，原东北军将领，江桥抗战后一度降日任伪黑龙江省省长，但不久即反正重新抗日，其短暂附逆期间与齐齐哈尔、克山地区有直接关联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8d26b9a0af624a01b1939a37d3ec8fe6','eb0ca498-79dc-467e-bcc5-0f260190222c',1932,'原东北军将领','原东北军将领，江桥抗战后一度降日，任伪黑龙江省省长，但不久即反正重新抗日，其降日经历在齐齐哈尔、黑龙江地区有明确记载。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b3dfdde62b9048048c126d8b6536e6bf','165b73e2-755e-4a57-9ef5-2b04a418bbdd',1932,'原东北军骑兵将领','原东北军骑兵将领，马占山降日期间任伪黑龙江省警备司令，后任伪黑龙江省长，积极配合日军镇压黑龙江抗日力量，活动范围覆盖齐齐哈尔、克山等地。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7f0d52803894c229fc0105f35962917','165b73e2-755e-4a57-9ef5-2b04a418bbdd',1932,'原东北军骑兵旅长','原东北军骑兵旅长，1932年投敌，任伪黑龙江省警备司令，后任伪黑龙江省长，在齐齐哈尔地区积极推行伪化统治，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1efd6aae321c4c84b7a90d9c7aa8ee99','30ba7a11-97e5-4bf5-8625-5c7c6c6f4243',1932,'原东北军军官','原东北军军官，投敌后任伪黑龙江省警备司令部司令，协助日军维持黑龙江地区治安，镇压抗日武装，活动范围包括齐齐哈尔及周边克山等县。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b8ff4dfb438143d1b26d8c3138c7d580','495b9b30-1161-4740-b60d-483831635fc0',1932,'辽宁金县人','辽宁金县人，投敌后历任伪黑龙江省公署参事官、伪滨江省长等职，参与伪满地方政权运作，其活动涉及黑龙江地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d704de28848a4c44b56126d6fc707433','50ebe401-b470-42a1-b99d-bec625a27dfa',1932,'投敌后历任伪黑龙江省公署厅长、伪三江省长等职','投敌后历任伪黑龙江省公署厅长、伪三江省长等职，协助日本在黑龙江地区推行殖民统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1768c3f9ad7b423997905eda9b9eae9d','f178dab4-7eec-498f-8ddb-67bb05cef77c',1932,'投敌后任伪齐齐哈尔警察厅厅长','投敌后任伪齐齐哈尔警察厅厅长，负责齐齐哈尔地区治安，镇压抗日分子，配合日军维持殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ce0f10f161734edfb337fc32d21cc2e3','0d355017-794c-4a48-baf8-94ac6a232572',1930,'投敌后任伪齐齐哈尔市市长','投敌后任伪齐齐哈尔市市长，协助日军管理齐齐哈尔市政，推行殖民政策。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb8275a3959e4cd994705acd0e5be631','0d355017-794c-4a48-baf8-94ac6a232572',1930,'投敌后任伪齐齐哈尔市市长','投敌后任伪齐齐哈尔市市长，参与伪满地方政权，推行殖民政策。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1914999a4a5f4d9990ac11e9c6c6b708','107d0f22-afb6-491c-b2f9-cb77583de3f1',1932,'齐齐哈尔商界人物','齐齐哈尔商界人物，投敌后任伪齐齐哈尔市商会会长，协助日军经济掠夺，为伪政权筹款筹物。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-823451bddbf242829d3e28f3ec6d2e67','6ec9cef8-a2a8-4056-9fdc-46f470b6cad9',1932,'投敌后任伪克山县县长','投敌后任伪克山县县长，在克山地区推行保甲制度，协助日军征粮征兵，镇压抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5ac221ab6a634ae4bef6df53ddc9f210','9a4fcb99-ab0f-45b6-8711-0112bcbcecf9',1932,'克山地方士绅','克山地方士绅，日军侵占克山后组织维持会并任会长，协助日军维持地方秩序，为伪政权建立做准备。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-deb4793180a04f5782ed5656e1ac43ee','c3dda819-05ff-4477-a894-1c7509540dc5',1932,'投敌后任伪克山县警察署署长','投敌后任伪克山县警察署署长，率伪警察配合日军讨伐抗日武装，镇压克山地区抗日群众。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b2aa2f714b446b09f47f8cea5811b10','d00996c8-800e-4cac-9445-e330802654d6',1932,'教育界附逆者','教育界附逆者，任伪齐齐哈尔师范学校校长，推行奴化教育，宣传“日满亲善”，毒害青年学生。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3a990e14e4447b58f2919028a48016a','daac9cd0-2f60-45c3-bfaf-2e313a4d6855',1932,'投敌后任伪齐齐哈尔协和会会长','投敌后任伪齐齐哈尔协和会会长，协助日军进行思想控制和社会动员，推行殖民文化政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-369eb86e287a4003a18c00931a070496','530a55f4-008b-4303-9596-6023ea648a6d',1932,'克山地方人物','克山地方人物，任伪克山县协和会会长，配合日军进行宣传和民众控制，协助推行殖民政策。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-07753840974547fe9a6822872f5e6447','35979e33-bbb3-4303-85a9-fb440dd29f13',1933,'克山地方保甲长','克山地方保甲长，协助日军和伪县公署征收粮款、监视民众，举报抗日分子，维持基层殖民统治。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-501b1e96c39045188109fb28dae13016','d3a12bcc-5109-4bd9-927b-5b65bf694010',1933,'投敌后任伪克山县自卫团团长','投敌后任伪克山县自卫团团长，率地方武装配合日军讨伐队进攻抗日游击队，镇压克山地区抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-473b87b2d96748a7876b694e4cec4af1','0eb61a95-a2e2-421d-90bc-baf3732df0fb',1932,'原东北军将领','原东北军将领，后投敌，任伪满军高级将领，驻防齐齐哈尔，负责镇压抗日武装，配合日军“讨伐”活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe857f07174145138c5b3acb6fa144ce','0eb61a95-a2e2-421d-90bc-baf3732df0fb',1932,'吉林双城人','吉林双城人，原东北军将领，九一八后投敌，任伪满第四军管区（驻齐齐哈尔）司令官，负责镇压齐齐哈尔及周边抗日武装，多次参与“讨伐”抗联部队，残害抗日军民。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7dbba863a38840a08989a2da76732b13','989da250-4a59-4141-b32e-d108ca6e1025',1931,'早年留学日本','早年留学日本，后参与伪满建国，曾在齐齐哈尔司法系统任职，为日本殖民统治提供法律支持。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e21b4f6bea0945a1a82b56be90cd61d3','11fc3e53-6736-4d00-9447-89c59dcf540c',1932,'原黑龙江省实业厅长','原黑龙江省实业厅长，后投敌，任伪黑龙江省长，在齐齐哈尔推行日伪政令，强征物资，镇压反满抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-680c7dea27e0412880689e9e651b0dec','4a2e55ea-9d19-4703-b733-0089450604ff',1934,'继韩云阶后任伪黑龙江省长','继韩云阶后任伪黑龙江省长，驻齐齐哈尔，积极执行日本经济掠夺政策，强迫农民“出荷”粮食。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-264fd60582824c7e92ffa38cfbc862dc','bd7d5e4a-0835-4559-b3e4-00735ff479c0',1937,'清肃亲王善耆之子','清肃亲王善耆之子，投靠日本，任伪黑龙江省长，在齐齐哈尔地区强化治安，协助关东军围剿抗联。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-37d332b7c243443dace6d290e91d04c2','9e24f8c5-163c-465f-bfbb-1a9313ebd844',1932,'原黑龙江省警察头目','原黑龙江省警察头目，投敌后任伪警务厅长，在齐齐哈尔及富拉尔基等地建立特务网络，抓捕抗日志士。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e706c9bdfc1540f8b2103d3fc8dcb4cb','1ffc1301-7571-41f9-beb7-01f67705a312',1933,'任伪齐齐哈尔市长期间','任伪齐齐哈尔市长期间，推行奴化教育，强征劳工，为日军修建军事设施，迫害当地居民。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-62a9576e8e93445fa5582fc62637a7fa','6c7bceed-e335-4cf3-baae-6075b04054db',1932,'在富拉尔基（今齐齐哈尔市富拉尔基区）组织伪维持会','在富拉尔基（今齐齐哈尔市富拉尔基区）组织伪维持会，协助日军征粮、抓丁，报告抗日分子活动。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ba6bc988027f44408924cc103f21ba2a','42a3d978-5be2-4389-9867-c6bbd011bc33',1936,'负责在齐齐哈尔及富拉尔基地区宣传“日满亲善”','负责在齐齐哈尔及富拉尔基地区宣传“日满亲善”，组织协和会，监控民众思想，强迫居民参加反共集会。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cf8cca0057484a3a8b685bf670a6d750','7a18a7ed-9faa-4b9b-883d-737776fdf95c',1934,'原黑龙江省实业厅长','原黑龙江省实业厅长，投日后任伪省长，在齐齐哈尔、富裕一带强征粮税，镇压反满抗日活动','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8aa774f9ae0c427c874e3e0e03bfaded','065aa7a9-3112-4b48-9913-55779d44aa95',1937,'原东北军文职官员','原东北军文职官员，投日后任伪省长，在齐齐哈尔地区推行“治安肃正”，协助日军清剿抗联','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d1d5b079e3fa48ca9054fa9d6ec22065','cf3e4e52-ee1c-44d3-a2bd-655e0635474d',1939,'原黑龙江省政府参议','原黑龙江省政府参议，投日后任伪省长，在富裕县等地实施“归屯并户”，切断抗联与民众联系','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4bdf7005ac604f4dbdf8e9050c4d3b94','f475ff27-0144-421f-84a3-2ec2dc017b5a',1942,'原黑龙江地方官僚','原黑龙江地方官僚，投日后任伪省长，在齐齐哈尔、富裕地区强抓劳工，供应日军军事工程','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4ffdfd5e1e9a4448934368e0b0e59b01','f7bf5d6f-1a4a-40e3-a26f-87266bc45d76',1932,'原哈尔滨特别市市长','原哈尔滨特别市市长，投日后首任伪黑龙江省长，在齐齐哈尔建立伪政权，镇压学生爱国运动','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b15755fe1e544acd934c4a00fe391081','d1ba0f52-a01d-4196-89c3-c93aeac7a132',1931,'原东北军将领','原东北军将领，1931年投敌，虽为伪满中央高官，但其势力范围涵盖黑龙江，对齐齐哈尔、富裕地区伪政权有直接控制','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-e4238e263ef84f6c91be96c67f5772e8','92f4ea59-b66d-403c-81b4-c88032913192',1932,'原抗日将领','原抗日将领，1932年2月一度投日任伪省长，但同年4月反正抗日，其短暂变节行为涉及齐齐哈尔地区','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb00984c5f5649a0bb3652055fc4b9d7','38d96338-bf15-4afc-949d-b3db84a1ebc2',1933,'原富裕县地方士绅','原富裕县地方士绅，投日后任伪县长，协助日军建立保甲制度，强征军粮，迫害抗日家属','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-323892de17c74effbdf79259607694f1','dc9ed2ff-8a37-48b8-8c31-1f54f3082eb2',1937,'原齐齐哈尔市警察署长','原齐齐哈尔市警察署长，投日后调任富裕县，推行“连坐法”，多次配合日军突袭抗联秘密联络点','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-53ddad40fc794cbb84468ae9c0a47673','3ce739e5-6ad0-4a16-860f-1f972c446ecb',1932,'原富裕县民团头目','原富裕县民团头目，投日后任伪警察署长，抓捕抗联交通员，严刑逼供，杀害多名抗日群众','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41ce588aeb78431ea91e43b3fbd1a324','4b5caeb9-ceae-41da-bef3-764e919b6f68',1932,'原齐齐哈尔商会会长','原齐齐哈尔商会会长，投日后任伪市长，为日军筹措军费，强征民夫修建军用机场','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f97c177e31a841068e8c75af2c7330df','820847ec-5d74-46f5-9a13-f7dd4771f083',1935,'原黑龙江省政府科长','原黑龙江省政府科长，投日后任伪市长，推行“粮谷出荷”，导致富裕地区农民饥荒','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-c77da51811564232b95111ea488cb1f9','5451ff7a-6564-42f6-af44-3f015cecf97d',1938,'原齐齐哈尔中学教员','原齐齐哈尔中学教员，投日后任伪市长，建立奴化教育体系，强迫学生参加“勤劳奉仕”','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2acb6e8ae89d4de693da142a3dec4722','4af7e5a0-673d-4103-9827-d109bc4808b1',1941,'原伪满民政部官员','原伪满民政部官员，调任齐齐哈尔后，配合日军“特别治安”行动，在富裕县设立集中营','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-855d8fe802134f7bb75c059fada3f302','0536d036-00bb-4e5b-8e46-c3d6aab21f8c',1934,'原富裕县地主','原富裕县地主，投日后任协和会会长，组织汉奸宣传队，煽动民众告发抗联活动','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9ebca11176d8436c96a5351cf962a68c','b25bc1cc-01d8-4348-8369-cfdf0b9e96a3',1932,'齐齐哈尔人','齐齐哈尔人，投日后任伪省警务厅厅长，组织伪警察和特务机构，大肆搜捕抗日地下工作者，破坏抗联地下联络站，制造多起血腥镇压事件。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80a6a7254f54461b873dbce2be5c2d5b','f9d25faf-8d11-48d0-8523-938921d2cf53',1932,'齐齐哈尔人','齐齐哈尔人，原为地方士绅，投日后主管伪省财政，为日军筹措军费，强征苛捐杂税，掠夺粮食资源，支援日本侵华战争。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-95aced6ce9c14c0f821cd7dd4dfcfba9','4ce2b15a-f0f6-4ea8-8a1e-d8c1d9911db7',1933,'齐齐哈尔本地人','齐齐哈尔本地人，投日后出任伪市长，推行日本殖民统治，实施保甲制度，强制居民领取“良民证”，协助日军清乡，镇压抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-adb885993ec74603a9f2cf69dc057c7b','72a11c08-69e3-43ee-b251-f657e7d94634',1932,'齐齐哈尔人','齐齐哈尔人，投日后任伪警察局长，指挥伪警配合日军宪兵队，多次突袭抗联秘密据点，逮捕并刑讯抗日志士，双手沾满鲜血。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8352ce80e6304725a717a1dfcebac84a','71053947-9c7d-494b-b21b-cf459929b070',1934,'齐齐哈尔人','齐齐哈尔人，任伪协和会齐齐哈尔本部总务部长，积极宣传“日满亲善”，组织奴化教育，煽动民众告密，破坏抗日群众组织。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9e6e2fdb241f4c1086f7763f93dc5411','c984b791-e604-47f0-bd7e-2f6350e68ffc',1932,'齐齐哈尔人','齐齐哈尔人，投日后任伪保安队长，率伪军多次围剿抗联小分队，在嫩江流域烧毁村庄，屠杀抗日群众，罪行累累。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6afd205b8111490c8bccad8926af5c3e','db270795-bdd7-44ce-af91-a07382932933',1933,'齐齐哈尔人','齐齐哈尔人，精通日语，为日本宪兵队充当翻译，参与审讯和酷刑迫害抗日志士，直接协助日军制造多起惨案。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3059d4ec9ad54dfda7bfb45e8d041c68','7a96986e-11d4-4bc7-9f0d-2a27db0b1b3b',1932,'曾任齐齐哈尔市伪市长','曾任齐齐哈尔市伪市长，积极推行日伪殖民政策，强征劳工，为日军提供物资，协助镇压当地抗日活动。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc3aad98e2734a608f5257ae837ba162','37aae442-b665-425a-82f5-fa2bdca6d953',1933,'在齐齐哈尔地区推行奴化教育','在齐齐哈尔地区推行奴化教育，强制学校教授日语，删除中国历史内容，迫害爱国教师，协助日伪进行思想控制。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7c7a77fdf3394586a7b7609f04252a0b','01edb929-3690-42a7-859b-1b8868bd59eb',1932,'任拜泉县伪县长期间','任拜泉县伪县长期间，组织伪县公署，配合日军清乡，强征农民粮食，抓捕抗日联军联络员，向日军提供抗日武装情报。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3ba47f0550bb488b8af2d8d6a6b4192c','131c6664-a01c-44fb-89a8-4dc3d8098988',1931,'原东北军将领','原东北军将领，九一八事变后投敌，曾任伪满黑龙江省省长（早期），后升任伪满国务总理，虽主要活动于新京，但其早期在黑龙江（含齐齐哈尔、拜泉）的伪政权建设中起关键作用，支持日军镇压抗日力量。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fb742ac5bee541b0bcd0a62f61cbbbe6','3a1c25d3-967f-4155-ba3e-f605f36852ec',1932,'1932年2月一度接受伪满任命','1932年2月一度接受伪满任命，任伪黑龙江省省长（齐齐哈尔），但同年4月反正抗日，故其汉奸身份短暂且存争议，但历史档案中列入伪职名录。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-095f726c99be44498c25794cb1956397','8254e310-d42d-46bb-893e-e59d2826a165',1932,'原东北军将领','原东北军将领，叛国投日，在齐齐哈尔地区围剿抗日武装，制造多起惨案，后任伪满治安部大臣','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1b919f0f5add47bfad309ce2722e2d0e','69918bcb-d3f8-430c-bb9d-c2f23bd1a79d',1932,'江桥抗战后一度诈降','江桥抗战后一度诈降，任伪黑龙江省长，后反正抗日，但投敌期间为日伪效力，属争议人物','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-14a82785a84e42e98947c09c50fda06c','5e6894b8-9ad5-4a67-a30d-24120215483a',1932,'原黑龙江省议员','原黑龙江省议员，积极投靠日军，参与组织伪政权，协助日军统治齐齐哈尔，镇压反满抗日活动','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-80a8c96ea1764a7b9884c0419521506a','85e6de33-6cef-4491-885c-92152d124ba6',1933,'在昂昂溪地区为日军效力','在昂昂溪地区为日军效力，镇压铁路工人抗日活动，协助日军抓捕地下抗日人员，罪行累累','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-ff739d7555a84521bf3d8dad43533228','2570502f-ab2e-4c9f-98cb-df0336a52f8f',1932,'原洮辽镇守使','原洮辽镇守使，九一八后投敌，在黑龙江北部及齐齐哈尔外围协助日军清剿抗日义勇军，后调任热河','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fa133746060c4abdb52a7ef3519c0f75','adbd935d-5c96-4450-b523-705d04c9bf11',1932,'原东北军旅长','原东北军旅长，一度抗日后投敌，在黑龙江东部及齐齐哈尔周边参与围剿抗联，后任伪满要职','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-39ecb87a6d8e4cd487ce6da8a3d2f344','c501c43f-dad8-4563-8798-3b37011b7eb8',1932,'原奉系将领','原奉系将领，投日后任伪满军事顾问，协助日军整编伪军，在齐齐哈尔地区训练伪军对抗抗联','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4f855656cf9465eb8a4caa147e7e87e','78ec3a91-4f05-41b3-9405-509b79e8d6b0',1931,'原东北军骑兵第二旅旅长','原东北军骑兵第二旅旅长，江桥抗战后随马占山一度抗日，后叛变投敌，任伪黑龙江省省长、伪满军中将，协助日军镇压黑龙江抗日力量，其统治区域覆盖齐齐哈尔。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-033b88be9ce14210b8ab7c7190adeb2a','95987fdc-37d7-4527-a64a-573750ef26fa',1931,'辽宁金县人','辽宁金县人，九一八事变后投敌，1932年任伪黑龙江省省长，后任伪满洲国经济部大臣、热河省省长等职，在黑龙江地区推行日本经济掠夺政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f65df48b403942d1873a1d0e67a6d217','e5979554-8147-468e-addd-9221cc2d2039',1931,'原黑龙江省官员','原黑龙江省官员，九一八事变后投敌，在伪黑龙江省公署任职，参与组织伪政权和协和会活动，协助日军控制齐齐哈尔及周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cc4a3ea14342422c9bd7d4030b765a9c','6bf4f6c9-0a65-4b14-9a1d-c40294d46a40',1931,'伪满时期在齐齐哈尔警察系统任职','伪满时期在齐齐哈尔警察系统任职，参与镇压齐齐哈尔地区抗日活动，搜捕抗日志士，推行保甲连坐制度。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8265d97913eb48e0a8f242eec42fc0b6','63889e3e-ed3c-42ee-9f0e-c6b2d1300b9c',1931,'齐齐哈尔地方士绅','齐齐哈尔地方士绅，日军占领齐齐哈尔后出面组织维持会，协助日军维持地方秩序、征发物资，为伪政权建立提供地方支持。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-33b714ca62f4467a8804fc2551c8e99b','f06ddfb6-d72a-4f86-bedf-bfc1ed23b140',1931,'在伪龙江省（辖齐齐哈尔地区）任职','在伪龙江省（辖齐齐哈尔地区）任职，参与推行伪满殖民政策，组织协和会进行奴化宣传，协助日军征发劳工和物资。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02edfcd6696b46b3beb854b7a7ef86b3','d0e2ac27-bf15-496d-8652-d25322f21fb1',1931,'伪满时期任龙江县县长','伪满时期任龙江县县长，管辖区域包括今齐齐哈尔市区及梅里斯一带，推行保甲制度，协助日军征粮征丁，镇压地方抗日活动。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-039afbf572b74a19bcff0b0a071f6e38','190fd1a6-07f8-4590-9760-5be8992555ce',1931,'伪满时期曾任龙江省省长','伪满时期曾任龙江省省长，管辖齐齐哈尔及周边地区，推行日本殖民统治政策，协助经济掠夺和劳工征发。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a3dbdf7158b14802833367b5ef17c2db','38305caf-bb2c-48b5-b10d-1420a87a40ea',1931,'伪满时期历任龙江省省长、勤劳奉公部大臣等职','伪满时期历任龙江省省长、勤劳奉公部大臣等职，在齐齐哈尔地区推行劳工征发政策，为日本侵略战争提供人力物力支持。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9f3fc11615a3495a8a521b2702f3935d','b38d9885-0c9c-4653-9ff6-22e5c1151a1b',1931,'在伪龙江省教育系统任职','在伪龙江省教育系统任职，推行奴化教育，篡改历史教材，向齐齐哈尔地区学生灌输亲日思想，协助日军进行文化侵略。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a03f5e5519f740258fde92d3b35bbc9f','20bc0e83-345c-4025-abda-029a60f9e385',1931,'在齐齐哈尔铁路系统任职','在齐齐哈尔铁路系统任职，配合日军保护铁路运输，镇压铁路沿线抗日活动，参与搜捕抗日地下工作者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a838d932081c470f97c65af2e14a8712','1f83c2f4-0d93-439e-bf0f-cd9a72ad6fc3',1931,'伪满时期任梅里斯地区保长','伪满时期任梅里斯地区保长，协助日军征粮征丁，推行保甲连坐，监视当地居民，镇压抗日活动。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a56865ee5fbc42b8b2ec04c190516f12','7b3c1646-cb11-4e61-b192-28f25ffabba3',1931,'在伪龙江省协和会任职','在伪龙江省协和会任职，组织亲日宣传和奴化教育活动，协助日军控制齐齐哈尔地区民众思想。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9a2ff143b6354c998a105a13ff259918','3fb17249-7154-40f8-b686-5e622bd0a9e2',1931,'伪满时期任齐齐哈尔市商会会长','伪满时期任齐齐哈尔市商会会长，协助日军征发物资、摊派款项，配合经济统制政策，为日军侵略提供经济支持。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df45ffcdcbb74542acff61cebcc332b1','66ff3b11-461f-4069-959c-2b8da5e3b638',1931,'在伪龙江省警务系统任职','在伪龙江省警务系统任职，指挥伪警察镇压齐齐哈尔地区抗日活动，搜捕抗日人员，推行法西斯统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3b7e06ed95e94dcc964a1a6785cc7006','9b6300b1-1856-40a4-bb70-8ce6af696874',1931,'原奉系军阀官员','原奉系军阀官员，后投靠日本，任伪满奉天省省长，推行殖民政策，协助日军掠夺资源，镇压抗日力量。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-7d0e913cc9a442128af747413ad28e70','e7019e7e-d452-459b-aecf-7329a47c545d',1933,'原黑龙江省财政厅长','原黑龙江省财政厅长，投敌后任伪满黑龙江省省长，期间积极为日军征粮派夫，破坏抗日组织。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-30081b4910754367a77ae792c433da3b','c51b3ffb-1063-402f-83f9-5835207ee844',1935,'原东北军将领','原东北军将领，投日后任伪满黑龙江省省长，协助日军清剿抗日武装，推行保甲制度。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-094b07a39e574ef1839f1dace82ef199','b2a70c2d-e81d-461d-9d7f-453892d113c6',1937,'原吉林军将领','原吉林军将领，投敌后任伪满黑龙江省省长，曾率伪军参与对抗日联军的围剿，在泰来、齐齐哈尔一带活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-797a8e1bed1d4d46930b0944e64e76f0','68677777-5914-40d7-b389-04cfcdf89982',1932,'原黑龙江省代主席','原黑龙江省代主席，1932年2月一度投降日军，任伪满黑龙江省省长，但同年4月反正，重新抗日，故其投敌行为短暂且后反正，通常不列为汉奸，但历史记录中曾有此段。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cdda9e048b2349b8b379953aece848df','525494da-f545-4ddd-ac4c-f8b6e6e42686',1932,'原黑龙江地方官员','原黑龙江地方官员，投敌后任伪满齐齐哈尔市市长，协助日军维持治安，推行殖民统治。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-bb50343951604eed80b06ffca7c47e33','13612f82-581d-4f26-8041-56b55280056a',1933,'原齐齐哈尔地方士绅','原齐齐哈尔地方士绅，投日后任伪满齐齐哈尔市市长，参与奴化宣传和物资搜刮。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9eb7d8be352f4ff0ab698c8533f33363','203d2659-1e4c-405d-a132-e577ddb69a44',1935,'原黑龙江省政府官员','原黑龙江省政府官员，投敌后任伪满齐齐哈尔市市长，配合日军清乡，迫害抗日家属。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-43c8832b13974cfb84685c8aa16adc14','a705ba11-8639-4dbb-98cc-1a1d4c845c73',1932,'原泰来县地方官员','原泰来县地方官员，投敌后任伪满泰来县县长，为日军提供情报，镇压当地抗日义勇军。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-1fdd0875f81749548537a3f3586d4577','ed5db895-5a7c-4c07-a52d-50989abd4d97',1934,'原泰来县士绅','原泰来县士绅，投日后任伪满泰来县县长，推行“归屯并户”，切断抗日联军与群众联系。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-3faf1ccbd5034e37ab9519051335f2e6','9d770a56-0d81-4feb-92d3-3ed133656390',1932,'原泰来县警察','原泰来县警察，投敌后任伪满泰来县警察署长，率伪警抓捕抗日人员，参与多起屠杀事件。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-41a600d904b84be0bd35e82e6c804e6c','572b097e-90c1-40c9-9d54-4f703d330c4f',1932,'原地方土匪头目','原地方土匪头目，投日后任伪满保安队队长，在齐齐哈尔、泰来一带协助日军围剿抗日游击队，烧杀抢掠。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-029bdff34a494438abf13c6be534607b','1ca43f72-c0b8-4a36-bd7d-4826353e689f',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪奉天警备司令、伪满洲国军政部大臣，统辖伪军参与镇压东北抗日武装，其军事活动范围包括黑龙江、齐齐哈尔地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-f15d7c9ac5c340459c81d6e36975424a','1ca43f72-c0b8-4a36-bd7d-4826353e689f',1931,'原东北军将领','原东北军将领，九一八事变后投敌，任伪奉天警备司令、伪军政部大臣，统辖伪军参与镇压东北抗日武装，其伪军活动范围包括黑龙江、齐齐哈尔地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-31e1d49004b449e7a61e4fd4d41db446','45a650d5-92a9-40b8-8129-307106e7bde2',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪热河省警备司令官，是黑龙江地区早期投敌的伪军头目之一。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-2d7ef4c6a15142fdb10fc4904bdc619b','45a650d5-92a9-40b8-8129-307106e7bde2',1931,'原东北军洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与江桥战役对抗马占山抗日军，后任伪热河省警备司令官，为黑龙江地区早期汉奸武装头目之一。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-93d977a7db5944fa86e4ae876ffc239a','898f2763-7843-4ce9-a881-aded9ff9344f',1931,'原东北军骑兵旅长','原东北军骑兵旅长，江桥抗战后投敌，任伪黑龙江省警备司令官，率伪军配合日军镇压黑龙江抗日武装，其活动直接覆盖齐齐哈尔及甘南周边地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81149c5bd9ce48d3a1ce04bda23eb1ed','898f2763-7843-4ce9-a881-aded9ff9344f',1931,'原东北军骑兵旅长','原东北军骑兵旅长，九一八事变后随马占山抗日，后于1932年投降日军，任伪黑龙江省警备司令官，率伪军配合日军镇压黑龙江抗日武装，直接活动于齐齐哈尔及龙沙地区。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-5d63d9df58a844e1af9517a420383251','82587177-8a9a-4e81-9cae-e65a2bedf867',1932,'原东北军军官','原东北军军官，随程志远投敌，任伪黑龙江省警备司令部要职，参与围剿黑龙江抗日联军，活动于齐齐哈尔一带。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-cb037fe9147a4b4f81e231abe54f3084','35b974c6-b1c0-4459-89cb-91cfdef21112',1931,'辽宁金县人','辽宁金县人，九一八事变后投敌，1932年任伪黑龙江省长，后任伪满洲国经济部大臣，在齐齐哈尔主持伪省政，推行日本殖民经济政策。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a370d31482a942eeb8532d8744eeb06d','35b974c6-b1c0-4459-89cb-91cfdef21112',1931,'辽宁金州人','辽宁金州人，九一八事变后投敌，任伪黑龙江省长，后任伪经济部大臣，参与伪满经济统制与掠夺，其活动涉及齐齐哈尔地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-df79890a731844ec91e87984737e900d','9399e1fd-fc88-4d37-8dfb-296a703938c5',1932,'辽宁辽阳人','辽宁辽阳人，九一八事变后投敌，曾任伪黑龙江省长，后任伪满洲国财政部大臣，参与伪满财政体系构建，其任职期间管辖齐齐哈尔地区。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-256cb90ec231482ca8ef43eff8138ae8','f79e83ae-ec15-44b5-9f2f-273fc712d7ec',1932,'原东北军军官','原东北军军官，投敌后任伪黑龙江省公署参事官，后升任伪满洲国民生部大臣，参与伪满地方政权建设，活动涉及齐齐哈尔。','危害等级D（丁级，无明确职位或一般帮凶）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-56eeb2f1c2864a48843d0b3ecd9221c8','f43c5772-5baf-4f3a-aa05-3eb7c1ccff8c',1931,'辽宁人','辽宁人，投敌后历任伪黑龙江省长、伪司法部大臣，在齐齐哈尔推行伪满法令，镇压抗日活动。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
