INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-04d5c18703794556904d779dd1bf0fcb','bc08348f-281b-498f-b0c2-0be0bb0436ab',1933,'指挥伪警察配合日军“清乡”','指挥伪警察配合日军“清乡”，在讷河、克山等地逮捕抗日地下人员，破坏抗联交通线。','危害等级B（乙级，市县厅局级）','hanjian');
