INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-05e17c2478d04a88ac03b79a3e161de2','2dd0df13-1d91-4fee-941b-8486fab91259',1931,'作为伪满最高汉奸之一','作为伪满最高汉奸之一，全面配合日军统治，其势力范围覆盖黑龙江包括齐齐哈尔、讷河地区。','危害等级S（特级，伪政权最高层/元首级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b129e7cfb457430b89d2862fe5b8d648','62a8097c-c42a-4dcf-af88-033b973e37e9',1932,'一度投降日军任伪职','一度投降日军任伪职，但不久反正抗日，其投敌行为在讷河地区有短暂影响。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-9d3a6257cee14ff3aa6350e5735b87a0','6e82a6cb-f8b1-4847-bae3-68cdb8467f1c',1932,'率伪骑兵在讷河、富裕一带追击抗联部队','率伪骑兵在讷河、富裕一带追击抗联部队，杀害抗联第三路军指战员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-eb3eeae1d35d409ba08c7d2b8ec1f9c3','eb55ce47-b13e-430d-a3c4-bd2845da90d4',1932,'在讷河县推行日伪法令','在讷河县推行日伪法令，组织伪自卫团，协助日军抓捕抗联地下工作者。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8602cf79e7f74ef294a98b4db1028c9a','57277d33-7628-4950-9a3a-605303aeb071',1933,'指挥伪警察在讷河农村“扫荡”','指挥伪警察在讷河农村“扫荡”，烧毁抗联密营，逮捕并刑讯抗日群众。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-4d0188930436431788bbeb4af8500cbb','b8d30d20-1c22-42af-a5c8-fe3d48931122',1935,'宣传“日满亲善”','宣传“日满亲善”，组织汉奸团体，刺探抗联情报，破坏抗日组织。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-593baae7760f4022aa511cc44e094b75','aa089533-2e13-4fcd-841e-ab8030066377',1934,'率保安队配合日军在讷河、克山交界处“讨伐”','率保安队配合日军在讷河、克山交界处“讨伐”，杀害抗联战士多人。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8dad064330364646af63b68a84ab6089','c7e166e0-cca8-44b0-bb84-9ed2d19ec3ac',1932,'在齐齐哈尔、讷河推行奴化教育','在齐齐哈尔、讷河推行奴化教育，强制学校教授日语，篡改历史教材。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-38d590ddb5a6484eb14dd03fadb47909','22d6e0dd-874d-4e34-89c7-a9b773c2296c',1932,'辽宁辽阳人','辽宁辽阳人，1932年投敌，曾任伪黑龙江省长，后任伪财政部次长等职，参与伪满财政经济统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-81f5c6e61a5b49e5a98ee77417aec640','08ac1e96-3be6-41a9-866f-83e5a3570ebd',1932,'在齐齐哈尔地区担任伪警察头目','在齐齐哈尔地区担任伪警察头目，负责维持治安、镇压抗日活动，配合日军搜捕抗日人员。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-54aee3f79b2a46edbd7c6bf130c79a5a','4e6acb1d-0f79-48a7-a4f2-297af078249c',1932,'在齐齐哈尔地区任职','在齐齐哈尔地区任职，参与伪政权地方行政管理，推行保甲制度，协助日军控制地方。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-a7a10119f1774012bf453edcf6b2cead','8203c62f-7625-43ea-9880-d7574f3483c9',1931,'九一八事变后','九一八事变后，在齐齐哈尔组织维持会，协助日军维持地方秩序，为伪政权建立做准备。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-6f839b5c437b47898446255a20f3f8ab','4aeab342-81c4-477c-bbcd-e463bfe10a94',1932,'在铁锋地区担任伪保甲长','在铁锋地区担任伪保甲长，负责征收赋税、摊派劳工，协助日军控制基层社会。','危害等级D（丁级，一般帮凶/基层人员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-8512091840bf421f8cf1546b7e6b2387','05eb169f-79bc-4db9-954c-bb0a8223c6f6',1932,'在黑龙江地区推行奴化教育','在黑龙江地区推行奴化教育，篡改历史教材，宣传“日满亲善”，毒害青少年。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-b4b8890762df4312be26eec8ac06e75b','0a22fa7b-4c8e-41b5-9d00-56fe7181875c',1932,'在黑龙江地区推行经济统制','在黑龙江地区推行经济统制，协助日军掠夺粮食、矿产等资源，压榨当地民众。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-0cc65a724e28496b8b469789b266f463','e2daf60e-2b73-4f1e-9ca4-c4b9b80366e7',1931,'原东北军军官','原东北军军官，九一八事变后投敌，任伪黑龙江省警备司令部司令，后任伪第四军管区司令官，驻齐齐哈尔，统辖伪军镇压黑龙江抗日力量。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fed916ce678548ab9d24bca31d4a117b','c3b8e2f5-86eb-4f4f-a808-fafe720dcf0b',1931,'辽宁人','辽宁人，九一八事变后投敌，长期在伪满地方政权任职，曾任哈尔滨市长、滨江省长，其活动范围接近黑龙江齐齐哈尔地区，参与伪满地方统治。','危害等级A（甲级，省部级/大军区级要员）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-fe5d6707687d43c9ac9e8b0f959637b0','b8c48f69-cde7-48c9-8d9f-4f6a7c80af90',1931,'伪满时期曾任齐齐哈尔市长','伪满时期曾任齐齐哈尔市长，参与伪满地方行政管理，直接活动于齐齐哈尔及龙沙地区，为当地伪政权附逆者。','危害等级B（乙级，市县厅局级）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d6da0991531e44349dbe3a101521fbb3','ad16d162-13eb-4b0e-925f-08ef83f5d18b',1931,'九一八事变后','九一八事变后，在齐齐哈尔组织维持会，协助日军维持地方秩序，为日军侵占齐齐哈尔提供地方支持，直接活动于齐齐哈尔及龙沙地区。','危害等级C（丙级，基层维持会/地方自治头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-110d50897b434d90b928da8b3669b7db','b032fb18-26b9-4529-a86c-55e245f0c7a1',1931,'伪满时期曾任龙江县县长','伪满时期曾任龙江县县长，龙江县治所位于齐齐哈尔，其行政活动直接覆盖齐齐哈尔及龙沙地区，参与伪满地方统治与物资征调。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-d1997f1261b74b68953aaf0b54540642','36c6c408-851c-4944-b4ce-83026f0b6858',1931,'伪满时期任齐齐哈尔市商会会长','伪满时期任齐齐哈尔市商会会长，协助日军进行经济统制与物资征集，为当地经济领域附逆者，活动于齐齐哈尔及龙沙地区。','危害等级C（丙级，基层头目）','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cr-02de613f4f754a92b5e02cbe5cbcc5cd','bcd5c9a3-739b-46a6-9a06-871d3ff45bb9',1931,'伪满时期任齐齐哈尔市教育会会长','伪满时期任齐齐哈尔市教育会会长，推行奴化教育，协助日军控制当地教育文化领域，活动于齐齐哈尔及龙沙地区。','危害等级C（丙级，基层头目）','hanjian');
